INSERT INTO exercises (id, name_en, name_de, category, movement_pattern, mechanic, force, laterality, level, variation_of, instructions, instructions_source_id, needs_review) VALUES
('1-arm-half-kneeling-lat-pulldown', '1-Arm Half-Kneeling Lat Pulldown', NULL, 'strength', 'vertical_pull', NULL, NULL, 'unilateral', NULL, NULL, '["Attach a D-Handle to a high pully. And use your lat muscles to pull the weight single handedly."]', 'wger', 0),
('3-4-sit-up', '3/4 Sit-Up', NULL, 'strength', NULL, 'compound', 'pull', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('3008-abdominal-crunch', '3008 Abdominal Crunch', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["This is especially for the gym80 device 3008 Abdominal Crunch."]', 'wger', 0),
('90-hamstring', '90/90 Hamstring', NULL, 'stretching', NULL, NULL, 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('ab-roller', 'Ab Roller', NULL, 'strength', NULL, 'compound', 'pull', NULL, 'intermediate', NULL, NULL, NULL, 0),
('ab-wheel', 'Ab wheel', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Starting Position: Kneel on the floor with the ab wheel in front of you.", "Grip the Wheel: Hold the handles firmly.", "Roll Out: Slowly roll the wheel forward, extending your body while keeping your core tight.", "Return: Pull the wheel back towards your knees, maintaining tension in your core."]', 'wger', 0),
('abdominal-crunch', 'Abdominal Crunch', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["The Abdominal Crunch is a classic core isolation exercise performed on the floor or a mat. Unlike a full sit-up, it involves a smaller range of motion where you only lift your shoulders and upper back off the ground, keeping your lower back pressed firmly against the floor."]', 'wger', 0),
('abdominal-draw-in', 'Abdominal Draw-In', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Lie on your back with knees bent. Gently pull your belly button toward your spine without moving your hips or holding your breath."]', 'wger', 0),
('abdominal-stabilization', 'Abdominal Stabilization', 'Bauch Stabilisation', 'strength', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0),
('adductor-groin', 'Adductor/Groin', NULL, 'stretching', NULL, NULL, 'static', NULL, 'intermediate', NULL, NULL, NULL, 0),
('air-bike', 'Air Bike', NULL, 'strength', NULL, 'compound', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('all-fours-quad-stretch', 'All Fours Quad Stretch', NULL, 'stretching', NULL, NULL, 'static', NULL, 'intermediate', NULL, NULL, NULL, 0),
('alternate-back-lunge', 'Alternate back lunges', NULL, 'strength', 'lunge', NULL, NULL, 'alternating', NULL, NULL, '["The posterior muscles of the buttocks, hamstrings, soleus and gastrocnemius are trained more"]', 'wger', 0),
('alternate-heel-touchers', 'Alternate Heel Touchers', NULL, 'strength', 'isolation_other', 'isolation', 'pull', 'alternating', 'beginner', NULL, NULL, NULL, 0),
('alternate-leg-diagonal-bound', 'Alternate Leg Diagonal Bound', NULL, 'plyometrics', NULL, 'compound', 'push', 'alternating', 'beginner', NULL, NULL, NULL, 0),
('alternating-lying-chin-tuck-neck-twist', 'Alternating Lying Chin Tuck Neck Twist', NULL, 'mobility', NULL, NULL, NULL, 'alternating', NULL, NULL, '["Lie on your back with your forehead and chin parallel to the floor.", "Tuck your chin in gently without lifting your head.", "Rotate your neck slowly all the way to one side.", "Return your head to center and rest briefly.", "Rotate your neck all the way to the opposite side.", "Return your head to center to complete one repetition.", "Alternate the starting side with each new set.", "Repeat the exercise for the desired amount of time or repetitions."]', 'longhaul-fitness', 0),
('ankle-circle', 'Ankle Circles', NULL, 'stretching', NULL, 'isolation', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('ankle-dorsiflexion-rocks', 'ankle dorsiflexion rocks', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Move your knee forward, keeping your heel on the ground. Hold the position for a couple of seconds and return to the starting position."]', 'wger', 0),
('ankle-knee', 'Ankle On The Knee', NULL, 'stretching', NULL, NULL, 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('anterior-tibialis-smr', 'Anterior Tibialis-SMR', NULL, 'stretching', NULL, NULL, 'static', NULL, 'intermediate', NULL, NULL, NULL, 0),
('arabesque', 'Arabesque', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Take all your weight onto one leg and you''re going to maintain that position, keeping your hips and pelvis level the whole time. With your back in a neutral position you want to tilt yourself forward kicking your leg back up and then slowly with your glutes bring yourself back up to neutral."]', 'wger', 0),
('archer-pull-up', 'Archer Pull Up', NULL, 'strength', 'vertical_pull', NULL, NULL, 'bilateral', NULL, NULL, '["An archer pull-up is an advanced bodyweight exercise that strengthens your back and biceps, serving as a progression towards a one-arm pull-up. It gets its name from the \"bow-drawing\" position your body takes at the top.Here''s how to do it:1. Grip: Grasp a pull-up bar with a wider-than-shoulder-width overhand grip.2. Starting Position: Hang with arms fully extended, engaging your core and keeping your shoulder blades pulled down.3. The Pull: Pull your body up towards one hand, similar to a regular pull-up. At the same time, extend the other arm out to the side, keeping it as straight as possible. Your chin should come towards the hand that is pulling.4. Hold & Lower: Briefly hold the top position where one arm is bent and pulling, and the other is extended. Slowly lower yourself back to the starting position with control.5. Alternate: Repeat the movement, pulling up towards the opposite hand.The key to this exercise is to keep the assisting arm as straight as possible to maximise the load on the working arm. This makes it a challenging but effective exercise for unilateral pulling strength."]', 'wger', 0),
('archer-push-up-rings', 'Archer Push Up – Rings', NULL, 'strength', 'horizontal_push', NULL, NULL, 'bilateral', NULL, NULL, '["Adjust the rings to be about shin height.", "Grip each ring with your palms facing towards each other and arms extended.", "Position yourself in a plank position with feet together, body in a straight line from head to heels.", "Engage your core and keep your glutes and legs tight. This is your starting position.", "Shift your body weight to one side. Bend your elbow to lower your chest on that side as if doing a push-up. While lowering, extend the other arm out to the side as if you''re holding a drawn bow and arrow.", "Lower yourself until your chest is in line with the lowered hand, keeping the extended arm slightly bent.", "Push back up to the starting position by pressing with the bent arm and performing a chest fly with the extended arm.", "Alternate sides and repeat for desired repetitions, ensuring equal reps for both arms."]', 'longhaul-fitness', 0),
('arco-femorale-una-gamba', 'Arco femorale una gamba', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0),
('arm-circle', 'Arm Circles', NULL, 'stretching', NULL, 'isolation', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('arm-raise-t-y-i', 'Arm Raises (T/Y/I)', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Stand upright with feet hip-width apart, core engaged, and arms relaxed at your sides. From this position, perform three different arm raises to target the shoulders and upper back:", "T Raise: Lift your arms straight out to the sides until they are parallel to the floor, forming a “T” shape.", "Y Raise: Lift your arms upward at about a 45° angle from your body to form a “Y” shape.", "I Raise: Raise your arms straight overhead, close together, forming an “I” shape.", "Maintain a neutral spine, avoid arching your lower back, and move slowly with control. Focus on squeezing your shoulder blades together and keeping your shoulders down away from your ears."]', 'wger', 0),
('arnold-press', 'Arnold Press', NULL, 'strength', 'vertical_push', NULL, NULL, NULL, NULL, NULL, '["Hold a dumbbell in each hand and sit or stand with your feet shoulder-width apart.", "Start with your arms bent so that your palms face your body and the dumbbells are at shoulder height.", "As you press the dumbbells overhead, rotate your palms to face forward.", "Continue to press the dumbbells overhead until your arms are fully extended.", "Lower the dumbbells back down to the starting position, rotating your palms back to face your body as you do so.", "Repeat."]', 'longhaul-fitness', 0),
('assisted-wrist-rotation', 'Assisted Wrist Rotation', NULL, 'mobility', NULL, NULL, NULL, NULL, NULL, NULL, '["Raise your arms straight in front of you and clasp your hands together with your thumbs up and fingers interlaced.", "Rotate your wrists together. Imagine tracing an infinity symbol (∞) with your knuckles. Aim for the largest rotation possible within tolerable limits.", "Complete 5-8 repetitions in one direction (clockwise).", "Switch direction (counter-clockwise) and repeat.", "Continue alternating the movement in each direction for the desired amount of time."]', 'longhaul-fitness', 0),
('atlas-stone-trainer', 'Atlas Stone Trainer', NULL, 'strongman', NULL, 'compound', 'pull', NULL, 'intermediate', NULL, NULL, NULL, 0),
('atlas-stones', 'Atlas Stones', NULL, 'strongman', NULL, 'compound', 'pull', NULL, 'advanced', NULL, NULL, NULL, 0),
('australian-pull-up', 'Australian pull-ups', NULL, 'strength', 'vertical_pull', NULL, NULL, 'bilateral', NULL, NULL, '["Lie down under a high bar or suspension bar, positioned at an appropriate height.", "Position yourself on your back under the bar, gripping the bar with a supinated grip (palms facing you).", "Adjust your position so that your body is aligned straight from head to toe. Arms should be fully extended, shoulders stabilized, and legs aligned with the rest of the body.", "Bend your elbows and pull your chest towards the bar, contracting your back muscles. Imagine you''re trying to bring your shoulder blades together.", "Hold the contraction at the top of the movement for a moment to maximize muscle activation.", "Slowly return to the starting position, extending your elbows."]', 'wger', 0),
('axle-deadlift', 'Axle Deadlift', NULL, 'strongman', 'hinge', 'compound', 'pull', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('backward-drag', 'Backward Drag', NULL, 'strongman', NULL, 'compound', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('bag-training', 'Bag training', NULL, 'cardio', NULL, NULL, NULL, NULL, NULL, NULL, '["Bag training improves muscle definition of: deltoids; rear deltoids; triceps; biceps, as well as being a great cardio exercise"]', 'wger', 0),
('balance-board', 'Balance Board', NULL, 'strength', NULL, 'compound', NULL, NULL, 'beginner', NULL, NULL, NULL, 0),
('ball-slam', 'Ball Slams', NULL, 'cardio', NULL, NULL, NULL, NULL, NULL, NULL, '["Stand with your feet about shoulder-width apart, your knees and hips slightly bent, holding the ball in both hands at chest height. Engage your core, and keep a good posture.", "Extend your knees and drive your hips forward while simultaneously lifting the ball. Aim for being as tall as possible, the ball overhead, arms up, hips slightly forward, and on your toes from the force of your drive.", "Use your core and arms to slam the medicine ball straight down between your feet with as much force as possible. Press your hips back and bend your knees to further power the slam. Exhale as you slam the ball down.", "Squat down to pick up the ball from the floor, then immediately move into the next slam by repeating the movement. Repeat for reps or time."]', 'wger', 0),
('band-assisted-pull-up', 'Assisted Pull-Up', NULL, 'strength', 'vertical_pull', 'compound', NULL, 'bilateral', 'beginner', NULL, '["The Assisted Pull-Up is a compound vertical pulling exercise performed on a machine with a counterweight platform or by using resistance bands. It mimics the mechanics of a standard pull-up but reduces the total weight you have to lift, making it an excellent tool for building functional strength and perfecting your technique."]', 'wger', 0),
('band-back-flyes', 'Back Flyes - With Bands', NULL, 'strength', 'isolation_other', 'compound', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('band-banded-clamshell', 'Banded Clamshell', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Position Side plank with the elbow and the forearm on the ground and the legs slightly bent. Stretch a doubled-up resistance band between your thighs, just above the knee.", "Execution Lift your upper knee while keeping your feet close together, like a “shell opening,” then slowly return to the starting position. Keep your core stable and your hips aligned."]', 'wger', 0),
('band-banded-scapular-retraction', 'Banded Scapular Retraction', 'Schulter-Rückzieher', 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Attach one end of resistance band to wall/upright/... at shoulder height. Insert arm into the loop, at the tricep. Step back until band is pulled straight. Pull back elbow and shoulder against the resistance of the band."]', 'wger', 0),
('band-banded-shoulder-drills', 'Banded Shoulder Drills', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Attach a resistance band to something solid behind you. Stand away from it, holding it in your hand so it is taut.", "See the attached youtube video: https://www.youtube.com/watch?v=zdwEWchSjrI ."]', 'wger', 0),
('band-bench-press', 'Bench Press - With Bands', NULL, 'strength', 'horizontal_push', 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('band-box-squat', 'Box Squat with Bands', NULL, 'strength', 'squat', 'compound', 'push', 'bilateral', 'advanced', NULL, NULL, NULL, 1),
('band-calf-raise', 'Calf Raises - With Bands', NULL, 'strength', 'isolation_other', 'isolation', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('band-cross-over', 'Cross Over - With Bands', NULL, 'strength', NULL, 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('band-deadlift', 'Deadlift with Bands', NULL, 'strength', 'hinge', 'compound', 'pull', 'bilateral', 'advanced', NULL, NULL, NULL, 1),
('band-drinking-bird-row', 'Drinking Bird Row – Band', NULL, 'strength', 'horizontal_pull', NULL, NULL, NULL, NULL, NULL, '["Tie a resistance band down in front of you at sternum height and hold it with both hands using an overhand grip.", "Stand with your feet shoulder-width apart and hinge at the hips forward while keeping your spine neutral and a slight bend in the knees.", "Reach your hands out overhead as you hinge forward, maintaining tension in the band. This is your starting position.", "Reverse the hinge and stand straight up while pulling the band towards your sternum, leading with your elbows.", "Squeeze your back muscles as your hands reach your sternum and you''re standing up straight.", "Slowly return to the starting position by hinging forward at the hips again.", "Repeat the movement for your desired number of repetitions."]', 'longhaul-fitness', 0),
('band-exercise-dorsiflexion', 'Exercise Band Dorsiflexion', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["This exercise uses an exercise band. It targets the Soleus and Tibialis anterior."]', 'wger', 0),
('band-exercise-plantarflexion', 'Exercise Band Plantarflexion', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Banded plantarflexion is a great way to bridge the gap between plantarflexion range of motion and the more strenuous calf raises in weight bearing. This can help strengthen the calf muscles, load the Achilles tendon, and improve plantarflexion range of motion."]', 'wger', 0),
('band-external-rotation', 'External Rotation with Band', NULL, 'strength', 'rotation', 'compound', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('band-external-shoulder-rotation', 'External Shoulder Rotation – Band', NULL, 'strength', 'rotation', NULL, NULL, NULL, NULL, NULL, '["Attach a resistance band to a stable object at waist height.", "Stand perpendicular to the anchor point with your right arm farthest away from it, and your feet shoulder-width apart.", "Reach across your body with your right hand and grab the band.", "Create resistance in the band by bringing your right elbow close to your right side where it hangs naturally.", "This starting position has you with your right forearm across the front of your body, at a 90-degree angle to your right upper-arm.", "Keep your core engaged and your shoulders relaxed.", "Slowly rotate your arms outward, away from your body, until your right hand is in line with your right shoulder.", "Pause for a moment, then slowly return to the starting position.", "Repeat for the desired number of repetitions and then switch sides."]', 'longhaul-fitness', 0),
('band-face-pull-yellow-green', 'Face pulls with yellow/green band', NULL, 'strength', 'horizontal_pull', NULL, NULL, 'bilateral', NULL, NULL, '["Face pulls with band – standing horizontal pull. Grab the band at face height, pull elbows high and wide towards your face while squeezing shoulder blades together. Trains upper back, rear shoulders and improves posture."]', 'wger', 0),
('band-good-morning', 'Band Good Morning', NULL, 'strength', 'hinge', 'compound', 'pull', NULL, 'beginner', NULL, NULL, NULL, 1),
('band-good-morning-pull-through', 'Band Good Morning (Pull Through)', NULL, 'strength', 'hinge', 'compound', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('band-hip-abduction', 'Hip Abduction – Band', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Start by placing an exercise band around both of your knees. Make sure the band is secure and does not slip during the exercise.", "Sit on a bench with your feet hip-width apart and your toes pointing forward.", "Exhale as you slowly press your knees outward, against the resistance of the exercise band.", "Continue pressing until you feel a comfortable stretch in your outer hip and thigh muscles.", "Pause for a brief moment at the outwardmost position, feeling the tension in the exercise band.", "Inhale as you release the pressure and bring your knees back together, returning to the starting position.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('band-hip-adductions', 'Band Hip Adductions', NULL, 'strength', 'isolation_other', 'isolation', 'pull', NULL, 'beginner', NULL, NULL, NULL, 1),
('band-hip-extension', 'Hip Extension with Bands', NULL, 'strength', NULL, 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('band-hip-flexion', 'Hip Flexion with Band', NULL, 'strength', NULL, 'compound', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('band-hip-hinge', 'Hip Hinge – Band', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Place a resistance band around your hips and anchor it behind you at mid-hamstring level.", "Stand with your feet hip-width apart and maintain a light bend in your knees. This is your starting position.", "Engage your core and hinge forward at the hips, keeping your back straight and chest lifted.", "Continue hinging until you feel a stretch in your hamstrings.", "Pause briefly at the bottom, ensuring you maintain a neutral spine.", "Stand straight back up to the starting position.", "Repeat the movement for your desired number of repetitions."]', 'longhaul-fitness', 0),
('band-hip-lift', 'Hip Lift with Band', NULL, 'strength', NULL, 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('band-hip-thrust', 'Hip Thrust – Band', NULL, 'strength', 'hinge', NULL, NULL, 'bilateral', NULL, NULL, '["Place a resistance band below your knees.", "Sit on the ground with your back against a bench, your feet flat on the ground, and position a barbell across your hips.", "Engage your core and glute muscles, and slowly lift your hips up off the ground until your body forms a straight line from your knees to your shoulders.", "Hold for a second or two at the top of the movement, then lower your hips back down to the ground.", "Repeat."]', 'longhaul-fitness', 0),
('band-horizontal-wood-chop', 'Horizontal Wood Chop – Band', NULL, 'strength', 'rotation', NULL, NULL, NULL, NULL, NULL, '["Attach a resistance band to a sturdy anchor point at waist height.", "Stand perpendicular to the anchor point with feet shoulder-width apart and knees slightly bent.", "Hold the resistance band with both hands and extend arms out in front of the body.", "Rotate the torso and pull the band across the body towards the opposite hip.", "Keep the arms straight and engage the core muscles throughout the movement.", "Slowly return to the starting position", "Repeat."]', 'longhaul-fitness', 0),
('band-internal-rotation', 'Internal Rotation with Band', NULL, 'strength', 'rotation', 'isolation', NULL, NULL, 'beginner', NULL, NULL, NULL, 0),
('band-internal-shoulder-rotation', 'Internal Shoulder Rotation – Band', NULL, 'strength', 'rotation', NULL, NULL, NULL, NULL, NULL, '["Attach a resistance band to a stable object at waist height.", "Stand perpendicular to the anchor point with your right arm closest to it, and your feet shoulder-width apart.", "Reach your right hand and grab the band.", "Create resistance in the band by side-stepping away from the anchor point.", "This starting position has your right forearm at a 90-degree angle to your right upper-arm. Your right forearm points to your right.", "Keep your core engaged and your shoulders relaxed.", "Slowly rotate your arms inward, toward your body, until your right hand is in line with your right shoulder.", "Pause for a moment, then slowly return to the starting position.", "Repeat for the desired number of repetitions and then switch sides."]', 'longhaul-fitness', 0),
('band-lateral-raise', 'Lateral Raise - With Bands', NULL, 'strength', 'isolation_other', 'isolation', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('band-lateral-walk', 'Lateral Walk – Band', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Place a resistance band around your ankles and stand with your feet hip-width apart.", "Take a step to the right with your right foot, keeping tension on the band.", "Bring your left foot to meet your right foot, maintaining tension on the band.", "Take another step to the right with your right foot, again keeping tension on the band.", "Repeat this lateral movement for a desired number of steps to the right.", "Then, reverse the movement and take the same number of steps to the left."]', 'longhaul-fitness', 1),
('band-leg-curl-elastic', 'Leg curl with elastic', NULL, 'strength', 'isolation_other', NULL, NULL, NULL, NULL, NULL, '["Standing position: Place the band under your feet in the middle of your foot and grasp it with a hammer grip."]', 'wger', 0),
('band-monster-walk', 'Monster Walk – Band', NULL, 'strength', NULL, 'compound', 'pull', NULL, 'beginner', NULL, '["Place a band around your ankles.", "Stand with your feet shoulder-width apart and your knees slightly bent.", "Engage your core and keep your hands at your sides or on your hips. This is your starting position.", "Take a diagonal step forward and to the side with one foot, keeping tension in the band and your body low.", "Follow with the other foot, stepping diagonally forward to meet the first foot, maintaining the band’s tension.", "Continue moving forward by alternating diagonal steps with each foot.", "Keep your steps controlled and the band tense, moving steadily forward across the room.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('band-one-arm-row-lunge', 'One-Arm Row Lunge – Band', NULL, 'strength', 'lunge', NULL, NULL, 'unilateral', NULL, NULL, '["Anchor a resistance band at the level of your belly button in front of you.", "Grip the band with your target arm and start in a lunge position with the front leg opposite the target arm.", "Simultaneously pull the band through a row motion while transitioning into a single leg stand on the front leg.", "Raise the knee of the same side leg as the target arm to hip height as you pull the band, squeezing your back muscles.", "Reverse the motion by lowering the knee and returning to the starting lunge position.", "Repeat the movement for your desired number of repetitions."]', 'longhaul-fitness', 0),
('band-one-handed-standing-chest-fly', 'One-Handed Standing Chest Fly – Band', NULL, 'strength', 'isolation_other', NULL, NULL, 'unilateral', NULL, NULL, '["Find a sturdy stationary object, such as a pole or a door anchor, and attach one end of the resistance band to it at chest height.", "Stand with your feet shoulder-width apart, facing away from the stationary object.", "Hold the free end of the resistance band in one hand, with your palm facing forward.", "Position yourself at a distance from the stationary object so that there is tension in the band when your arm is extended forward at chest height.", "Keep your elbow slightly bent and your arm extended out to the side at shoulder height.", "Engage your core muscles to stabilize your torso.", "With a slight bend in your elbow, bring your arm across your chest in a sweeping motion while keeping your chest open.", "Feel the stretch in your chest muscles as you bring your arm across your body.", "Return your arm to the starting position in a controlled manner.", "Complete the desired number of repetitions on one side before switching to the other."]', 'longhaul-fitness', 0),
('band-one-leg-prone-quad-stretch', 'One-Leg Prone Quad Stretch – Band', NULL, 'stretching', NULL, NULL, NULL, 'unilateral', NULL, NULL, '["Loop a strength band or pull-up assist band around one ankle.", "Lie down on your stomach.", "Hold the band with both hands, over your back, over the same shoulder as the looped ankle, all the way until it''s in front of your forehead as your lying down.", "Pull the band away from your forehead to flex your quad.", "Hold the stretch for the desired time and switch to the other side."]', 'longhaul-fitness', 0),
('band-pull-apart', 'Band pull-aparts', NULL, 'strength', 'isolation_other', 'isolation', 'pull', NULL, 'beginner', NULL, '["Stand with feet shoulder-width apart and hold a resistance band with both hands.", "Extend your arms straight out in front of you, keeping your palms facing down.", "Begin pulling the band apart by squeezing your shoulder blades together.", "Continue pulling until your hands are at shoulder height and the band is stretched tight.", "Hold for a moment, then slowly release the tension and return to the starting position.", "Repeat."]', 'longhaul-fitness', 0),
('band-pull-apart-external-rotation', 'Band pull-apart with external rotation', NULL, 'strength', 'rotation', NULL, NULL, NULL, NULL, NULL, '["Stand tall with your feet shoulder-width apart, chest out, and shoulders back.", "Hold the resistance band with both hands, palms facing up or facing each other, depending on the band type.", "Bend your elbows at a 90-degree angle and glue your upper arms to your sides.", "The band should have some tension in the starting position, with your hands closer together in front of your stomach.", "Rotate Outward: While keeping your elbows tucked into your sides, slowly move your hands away from each other, stretching the band.", "Squeeze: Squeeze your shoulder blades together and down as you rotate your hands outward.", "Range of Motion: Rotate your hands as far outward as you comfortably can without allowing your elbows to leave your sides.", "Hold: Hold the end position for 1–2 seconds to maximize muscle engagement.", "Return: Slowly and with control, bring your hands back to the starting position."]', 'wger', 0),
('band-rack-pull', 'Rack Pull with Bands', NULL, 'strength', NULL, 'compound', 'pull', 'bilateral', 'intermediate', NULL, NULL, NULL, 1),
('band-rebound-external-rotation', 'Rebound External Rotation – Band', NULL, 'strength', 'rotation', NULL, NULL, NULL, NULL, NULL, '["Anchor a resistance band in front of you at roughly head height.", "Keep your elbow bent at a 90-degree angle and abducted to shoulder height.", "Start with your forearm parallel to the floor.", "Grip the free end of the band and take a step backwards to add tension to the band.", "Pull the band by externally rotating your shoulder until your forearm is perpendicular to the floor (90 degrees external rotation). This is your starting position.", "Let the band pull your hand internally by 5-10 degrees.", "Externally rotate your shoulder once again to return to the starting position.", "Repeat the movement for your desired number of repetitions."]', 'longhaul-fitness', 0),
('band-reverse-bench-press', 'Reverse Band Bench Press', NULL, 'strength', 'horizontal_push', 'compound', 'push', 'bilateral', 'intermediate', NULL, NULL, NULL, 1),
('band-reverse-fly-standing', 'Reverse Fly Standing', NULL, 'strength', 'isolation_other', NULL, NULL, NULL, NULL, NULL, '["Stand with a good posture holding a cable in each hand opposite the machine", "Starting with the hands in front of your chest pull the arms out to your side into the shape of a T with the elbows nearly straight", "Slowly release the arms forward to the start", "Repeat with the arms moving into the shape of a Y", "Repeat with the arms in the shape of a W", "Repeat with the arms in the shape of an L by your side"]', 'wger', 0),
('band-reverse-power-squat', 'Reverse Band Power Squat', NULL, 'strength', 'squat', 'compound', 'push', 'bilateral', 'advanced', NULL, NULL, NULL, 1),
('band-rubber-glute-kickback', 'rubber band glute kickback', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["A rubber band glute kickback is an exercise performed on hands and knees, where you anchor a resistance band to your foot and kick your heel back and up, squeezing your glute at the top of the movement, while maintaining a stable core and flat back to target and strengthen the gluteal muscles."]', 'wger', 0),
('band-seated-half-good-morning', 'Seated Half Good Morning – Band', NULL, 'strength', 'hinge', NULL, NULL, NULL, NULL, NULL, '["Sit on an incline bench set at a 45-degree angle, facing the bench.", "Loop a light monster band around both of your feet and run it across your upper back.", "Maintain a neutral spine and hinge forward at the hips until your torso touches the pad of the bench.", "Hinge backward to return to the neutral position.", "Repeat the movement for your desired number of repetitions."]', 'longhaul-fitness', 0),
('band-seated-hamstring-curl', 'Seated Band Hamstring Curl', NULL, 'strength', 'isolation_other', 'isolation', 'pull', NULL, 'beginner', NULL, NULL, NULL, 1),
('band-seated-v-grip-row', 'Seated V-Grip Row', NULL, 'strength', 'horizontal_pull', NULL, NULL, NULL, NULL, NULL, '["The Seated V-Grip Row is a compound pulling exercise performed on a cable machine using a close-grip \"V\" handle. While seated with your feet braced, you pull the handle toward your midsection, focusing on back thickness and mid-back development."]', 'wger', 0),
('band-shoulder-press', 'Shoulder Press - With Bands', NULL, 'strength', 'vertical_push', 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('band-side-kick', 'Side Kicks – Band', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Stand with your feet hip-width apart and a resistance band around your ankles.", "Engage your core and lift one leg out to the side, keeping it straight and the foot flexed.", "Pause at the top of the movement, then slowly lower the leg back down to the starting position.", "Repeat for the desired number of reps, then switch sides."]', 'longhaul-fitness', 0),
('band-skull-crusher', 'Band Skull Crusher', NULL, 'strength', 'elbow_extension', 'isolation', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('band-speed-overhead-triceps', 'Speed Band Overhead Triceps', NULL, 'strength', 'isolation_other', 'isolation', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('band-squat', 'Squat with Bands', NULL, 'strength', 'squat', 'compound', 'push', 'bilateral', 'intermediate', NULL, NULL, NULL, 1),
('band-squat-2', 'Squats - With Bands', NULL, 'strength', 'squat', 'compound', 'push', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('band-upright-row', 'Upright Row - With Bands', NULL, 'strength', 'vertical_pull', 'compound', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('band-walking-lunge', 'Walking Lunges', NULL, 'strength', 'lunge', NULL, NULL, 'alternating', NULL, NULL, '["Starting Position: Stand with feet hip-width apart and hands either on your hips or holding dumbbells at your sides.", "The Stride: Take a wide step forward with your right leg.", "The Descent: Lower your hips until both knees are bent at approximately 90-degree angles.", "The Transition: Drive through your front heel to stand up, bringing your back foot forward to step directly into the next lunge."]', 'wger', 0),
('band-weighted-sit-up', 'Weighted Sit-Ups - With Bands', NULL, 'strength', 'isolation_other', 'isolation', 'pull', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('bar-hang', 'Bar Hang', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Find a sturdy horizontal bar that can support your body weight.", "Stand facing the bar and reach up to grab it with both hands, palms facing away from your body.", "Jump or step up to lift your feet off the ground and hang from the bar with your arms fully extended.", "Engage your shoulder blades and core muscles to maintain a stable position.", "Hold the position for a desired amount of time.", "To release, slowly lower your body down and step or jump off the bar."]', 'longhaul-fitness', 0),
('barbell-ab-rollout', 'Barbell Ab Rollout', NULL, 'strength', NULL, 'compound', 'pull', 'bilateral', 'intermediate', NULL, '["Place a barbell on the floor at your feet.", "Bending at the waist, grip the barbell with a shoulder with overhand grip.", "With a slow controlled motion, roll the bar out so that your back is straight.", "Roll back up raising your hips and butt as you return to the starting position."]', 'wger', 0),
('barbell-ab-rollout-knees', 'Barbell Ab Rollout - On Knees', NULL, 'strength', NULL, 'compound', 'pull', 'bilateral', 'advanced', NULL, NULL, NULL, 0),
('barbell-anti-gravity-press', 'Anti-Gravity Press', NULL, 'strength', NULL, 'compound', 'push', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('barbell-behind-neck-press', 'Behind the Neck Press – Barbell', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["Start by standing at a barbell rack with your feet shoulder-width apart and your knees slightly bent.", "Grasp the barbell with a wide grip, with your palms facing forward and your hands slightly wider than your shoulders.", "Lift the barbell up and bring it behind your head, resting it on your upper traps.", "Press the barbell up towards the ceiling, keeping your elbows pointed out to the sides.", "Lower the barbell back down to the starting position behind your head.", "Repeat."]', 'longhaul-fitness', 0),
('barbell-bench-press', 'Bench Press', 'Bankdrücken LH', 'strength', 'horizontal_push', 'compound', 'push', 'bilateral', 'beginner', NULL, '["Lie on a flat bench with your feet firmly planted on the ground.", "Grip the barbell with your hands slightly wider than shoulder-width apart, with your palms facing away from your body.", "Lift the bar off the rack and hold it directly above your chest with extended arms.", "Slowly lower the bar down to your chest, keeping your elbows close to your body.", "Pause briefly when the bar touches your chest.", "Push the bar back up to the starting position by extending your arms.", "Repeat."]', 'longhaul-fitness', 0),
('barbell-bench-press-chains', 'Bench Press with Chains', NULL, 'strength', 'horizontal_push', 'compound', 'push', 'bilateral', 'advanced', NULL, NULL, NULL, 0),
('barbell-bench-press-nb', 'Barbell Bench Press - NB', NULL, 'strength', 'horizontal_push', NULL, NULL, 'bilateral', NULL, NULL, '["The bench press is a compound exercise that builds strength and muscle in the chest and triceps. When many people think of listing, the bench press is often the first exercise that comes to mind"]', 'wger', 0),
('barbell-bench-press-powerlifting', 'Bench Press - Powerlifting', NULL, 'strength', 'horizontal_push', 'compound', 'push', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('barbell-bent-arm-pullover', 'Bent-Arm Barbell Pullover', NULL, 'strength', NULL, 'compound', 'pull', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('barbell-bent-over-one-arm-long-bar-row', 'Bent Over One-Arm Long Bar Row', NULL, 'strength', 'horizontal_pull', 'compound', 'pull', 'unilateral', 'beginner', NULL, NULL, NULL, 0),
('barbell-bent-over-two-arm-long-bar-row', 'Bent Over Two-Arm Long Bar Row', NULL, 'strength', 'horizontal_pull', 'compound', 'pull', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('barbell-biceps-curl', 'Biceps Curls With Barbell', 'Bizeps LH-Curls', 'strength', 'elbow_flexion', 'isolation', 'pull', 'bilateral', 'beginner', NULL, '["Stand with your feet shoulder-width apart and your knees slightly bent.", "Hold the barbell with an underhand grip, palms facing up, and your hands shoulder-width apart.", "Keep your elbows close to your sides and curl the barbell up towards your chest, exhaling as you lift.", "Pause at the top of the movement and squeeze your biceps.", "Lower the barbell back down to the starting position, inhaling as you lower.", "Repeat."]', 'longhaul-fitness', 0),
('barbell-board-press', 'Board Press', NULL, 'strength', NULL, 'compound', 'push', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('barbell-box-squat', 'Box Squat', NULL, 'strength', 'squat', 'compound', 'push', 'bilateral', 'intermediate', NULL, NULL, NULL, 1),
('barbell-box-squat-chains', 'Box Squat with Chains', NULL, 'strength', 'squat', 'compound', 'push', 'bilateral', 'advanced', NULL, NULL, NULL, 0),
('barbell-bradford-rocky-press', 'Bradford/Rocky Presses', NULL, 'strength', NULL, 'compound', 'push', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('barbell-calf-raise', 'Calf Raise – Barbell', NULL, 'strength', 'isolation_other', NULL, NULL, 'bilateral', NULL, NULL, '["Load a barbell. Also, find a raised platform or step to stand on.", "Place yourself with the step in front of you and the barbell behind you. Stand with your feet shoulder-width apart, toes pointing forward.", "Perform a Hack Squat to lift and hold the barbell behind your glutes.", "Step onto the platform or step with the balls of your feet, leaving your heels hanging off the edge. Your feet should be parallel to each other. This is your starting position.", "Slowly rise up on the balls of your feet, lifting your heels off the ground.", "Hold the raised position for a moment, feeling the contraction in your calf muscles.", "Lower your heels back down to the starting position in a controlled manner.", "Repeat the movement for the desired number of repetitions."]', 'longhaul-fitness', 0),
('barbell-car-drivers', 'Car Drivers', NULL, 'strength', 'isolation_other', 'isolation', 'push', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('barbell-clean', 'Clean', NULL, 'olympic', NULL, 'compound', 'pull', 'bilateral', 'intermediate', NULL, '["Regular olympic lift clean. Pull bar from ground, catch on shoulders performing a front squat."]', 'wger', 0),
('barbell-clean-and-jerk', 'Clean and Jerk', NULL, 'olympic', NULL, 'compound', 'push', 'bilateral', 'advanced', NULL, NULL, NULL, 1),
('barbell-clean-and-jerk-ol', 'Clean and Jerk OL', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["Olympic lift clean and jerk. Combination of clean and jerk in one motion."]', 'wger', 0),
('barbell-clean-and-press', 'Barbell Clean and press', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["This exercise involves lifting a barbell from the ground to the shoulders, then pressing it overhead. It is a compound movement that targets multiple muscle groups, including the legs, back, shoulders, and arms. It is often used in strength and conditioning programs to improve overall power and athleticism."]', 'wger', 1),
('barbell-clean-and-press-2', 'Clean and Press', NULL, 'strength', NULL, 'compound', 'push', 'bilateral', 'intermediate', NULL, '["The First Pull: Lift the bar from the floor to knee-height by driving with the legs, keeping the angle of your back constant.", "The \"Power\" Position: As the bar reaches mid-thigh, explosively shrug and extend your hips to create vertical momentum.", "The Quick Elbow Turnover: In the catch phase, rotate your elbows rapidly under the bar to create a \"shelf\" on your front deltoids.", "The Vertical Press: Press the bar in a straight line; your head should shift slightly forward once the bar clears your forehead to reach full lockout."]', 'wger', 0),
('barbell-clean-deadlift', 'Clean Deadlift', NULL, 'olympic', NULL, 'compound', 'pull', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('barbell-clean-from-blocks', 'Clean from Blocks', NULL, 'olympic', NULL, 'compound', 'pull', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('barbell-clean-pull', 'Clean Pull', NULL, 'olympic', NULL, 'compound', 'pull', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('barbell-clean-shrug', 'Clean Shrug', NULL, 'olympic', NULL, 'compound', 'pull', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('barbell-curl-lying-against-incline', 'Barbell Curls Lying Against An Incline', NULL, 'strength', 'elbow_flexion', 'isolation', 'pull', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('barbell-deadlift', 'Deadlifts', 'Kreuzheben', 'strength', 'hinge', 'compound', 'pull', 'bilateral', 'intermediate', NULL, '["Stand with your feet roughly hip-width apart, with the barbell positioned over the middle of your feet.", "Bend at your hips and knees to reach down and grasp the barbell with both hands, slightly wider than shoulder-width apart, palms facing towards your body.", "With a flat back, engage your core, flatten your shoulder blades and look ahead to keep your neck in a neutral position.", "Stand up with the weight by pushing through your heels, keeping the bar close to your body, and driving your hips forward.", "Straighten your legs and hips to come to a full standing position, with the barbell hanging in front of your thighs. Do not lean back at the top.", "Pause briefly at the top of the lift while maintaining a tight core, and take a breath if needed.", "Lower the barbell back to the ground by hinging at the hips and bending the knees, keeping the bar close to your body and your back straight.", "Place the barbell back on the ground and return to the starting position, ready to perform the next repetition."]', 'longhaul-fitness', 0),
('barbell-deadlift-chains', 'Deadlift with Chains', NULL, 'strength', 'hinge', 'compound', 'pull', 'bilateral', 'advanced', NULL, NULL, NULL, 0),
('barbell-deadlift-fat-bar', 'Deadlift – Fat Bar', NULL, 'strength', 'hinge', NULL, NULL, 'bilateral', NULL, NULL, '["Stand with your feet shoulder-width apart, holding a loaded fat bar in front of your quads.", "Bend your knees, hinge and lean forward at the hips, keeping your back straight and your chest up.", "Lower the fat bar towards the ground, keeping it close to your legs.", "Pause when the fat bar is just below your knees.", "Push through your heels and stand up, keeping your back straight and your chest up.", "Repeat."]', 'longhaul-fitness', 0),
('barbell-decline-close-grip-bench-to-skull-crusher', 'Decline Close-Grip Bench To Skull Crusher', NULL, 'strength', 'elbow_extension', 'compound', 'push', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('barbell-drag-curl', 'Drag Curl', NULL, 'strength', 'elbow_flexion', 'compound', 'pull', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('barbell-elevated-back-lunge', 'Elevated Back Lunge', NULL, 'strength', 'lunge', 'compound', 'push', NULL, 'intermediate', NULL, NULL, NULL, 0),
('barbell-external-rotation-stretch', 'External Rotation Stretch', NULL, 'stretching', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["Sit with your feet pressed against each other, and one knee raised all the way out to the side of your body.", "Place your elbow on your raised knee, bend it at 90 degrees, and point your hand directly forward, holding your barbell/dumbbell.", "Keep your shoulder depressed and retracted, raise your hand until your forearm is vertical, as if you were about to wave at someone like a robot.", "Lower your hand to the original position and repeat."]', 'wger', 0),
('barbell-feet-up-bench-press', 'Feet-Up Bench Press – Barbell', NULL, 'strength', 'horizontal_push', NULL, NULL, 'bilateral', NULL, NULL, '["Lie flat on a bench with your feet up in the air, knees bent at a 90-degree angle.", "Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.", "Engage your core and press your lower back into the bench.", "Unrack the barbell and hold it directly above your chest, arms fully extended.", "Inhale and slowly lower the barbell towards your chest, keeping your elbows tucked in.", "Pause for a brief moment when the barbell touches your chest.", "Exhale and push the barbell back up to the starting position, fully extending your arms.", "Repeat the movement for the desired number of repetitions."]', 'longhaul-fitness', 0),
('barbell-finger-curl', 'Finger Curls', NULL, 'strength', 'elbow_flexion', 'isolation', 'pull', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('barbell-floor-press', 'Floor Press', NULL, 'strength', 'horizontal_push', 'compound', 'push', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('barbell-floor-press-chains', 'Floor Press with Chains', NULL, 'strength', 'horizontal_push', 'compound', 'push', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('barbell-forearm-roll-up', 'Forearm Roll-Up – Barbell', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["Set up a power rack placing a barbell at about chest height.", "Select a kettlebell and an appropriately sized resistance band that can be looped around it.", "Loop one end of the resistance band around the kettlebell securely.", "Loop the other end of the resistance band around one end of the barbell securely, wrapping it twice to ensure the kettlebell is suspended and the band is taut.", "Stand facing the barbell with your feet shoulder-width apart, positioning yourself slightly back to allow full range of motion for the barbell to roll.", "Extend your arms forward and grasp the barbell with both hands using an overhand grip, placing your hands slightly wider than shoulder-width for stability. Place one hand on either side of the band connected to the barbell.", "Begin with your right hand, rolling the barbell away from you as much as possible to contract your forearm muscles.", "After rolling with your right hand, switch to your left hand and perform the same rolling motion, alternating between hands with each roll.", "Continue this alternating pattern, rolling the barbell and lifting the kettlebell until you cannot roll any further or the kettlebell reaches its peak height.", "Carefully reverse the rolling motion using alternate hands again to lower the kettlebell back to the starting position in a controlled manner."]', 'longhaul-fitness', 0),
('barbell-frankenstein-squat', 'Frankenstein Squat', NULL, 'olympic', 'squat', 'compound', 'push', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('barbell-front-rack-curtsy-lunge', 'Front Rack Curtsy Lunge – Barbell', NULL, 'strength', 'lunge', NULL, NULL, NULL, NULL, NULL, '["Position a barbell on a squat rack at shoulder height.", "Stand facing the barbell, step under it, and rest it across the front of your shoulders.", "Step back from the rack with the barbell in the front rack position.", "Stand with feet hip-width apart, head up, and chest high. This is your starting position.", "Take a step back and to the side with your right foot, crossing it behind your left leg.", "Lower your body into a lunge, keeping your front knee aligned over your front foot and your core engaged.", "Push through your front heel to rise, bringing your right foot back to the starting position.", "Repeat for the desired number of repetitions and switch to the other side."]', 'longhaul-fitness', 0),
('barbell-front-raise', 'Front Raise – Barbell', NULL, 'strength', 'isolation_other', NULL, NULL, 'bilateral', NULL, NULL, '["Stand with your feet shoulder-width apart and your knees slightly bent.", "Hold a barbell with an overhand grip, hands shoulder-width apart, and the bar resting on your thighs.", "Keeping your arms straight, lift the barbell up in front of you until it reaches shoulder height.", "Pause for a moment, then slowly lower the barbell back down to your thighs.", "Repeat."]', 'longhaul-fitness', 0),
('barbell-front-raise-and-pullover', 'Front Raise And Pullover', NULL, 'strength', 'isolation_other', 'compound', 'pull', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('barbell-front-squat-clean-grip', 'Front Squat (Clean Grip)', NULL, 'strength', NULL, 'compound', 'push', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('barbell-full-squat', 'Barbell Full Squat', NULL, 'strength', 'squat', 'compound', 'push', 'bilateral', 'intermediate', NULL, '["The barbell full squat is a compound exercise that targets multiple muscle groups in the lower body, including the quadriceps, hamstrings, and glutes.", "Proper form is crucial for maximizing results and preventing injuries during the barbell full squat. This includes maintaining a shoulder-width stance, creating whole body tension, controlling your descent, and maintaining proper depth and knee positioning.", "Assistance moves such as the front squat, goblet squat, split squat, and Bulgarian split squat can help improve your performance in the barbell full squat by targeting specific muscle groups and improving overall technique.", "To achieve new personal records in your back squat, gradually increase weight over time, vary rep ranges and sets to stimulate muscle growth, and prioritize rest and recovery between training sessions."]', 'wger', 0),
('barbell-glute-bridge', 'Barbell Glute Bridge', NULL, 'strength', 'hinge', 'compound', 'push', 'bilateral', 'intermediate', NULL, NULL, NULL, 1),
('barbell-good-morning', 'Good Morning', NULL, 'strength', 'hinge', 'compound', 'push', 'bilateral', 'intermediate', NULL, NULL, NULL, 1),
('barbell-good-morning-off-pins', 'Good Morning off Pins', NULL, 'strength', 'hinge', 'compound', 'push', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('barbell-guillotine-bench-press', 'Barbell Guillotine Bench Press', NULL, 'strength', 'horizontal_push', 'compound', 'push', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('barbell-hack-squat', 'Barbell Hack Squats', NULL, 'strength', 'squat', 'compound', 'push', 'bilateral', 'intermediate', NULL, '["Stand in front of the barbell with your feet shoulder-width apart. The barbell will be by the back of your calves.", "Bend down and grip the barbell with an overhand grip, with your palms facing behind you.", "Stand up straight, lifting the barbell off the ground and holding it behind your legs.", "Keeping your back straight, lower your body by bending your knees and hips, as if you were sitting down on a chair, until your thighs are parallel to the ground.", "Push through your heels to stand back up to the starting position.", "Repeat."]', 'longhaul-fitness', 1),
('barbell-hack-squat-landmine', 'Hack Squat – Landmine', NULL, 'strength', 'squat', NULL, NULL, 'bilateral', NULL, NULL, '["Place the end of a barbell into a landmine attachment or securely anchor it in a corner.", "Stand with your feet shoulder-width apart, toes slightly turned out.", "Hold the unattached end of the barbell with both hands, palms facing inwards. Lift the end up and over one shoulder while you turn away from the weight. Rest the barbell on your shoulder with the weight at your back.", "Keep your core engaged, chest lifted, and back straight.", "Lower your body by bending at the knees and hips, as if sitting back into a chair.", "Continue lowering until your thighs are parallel to the ground or slightly below.", "Push through your heels and extend your knees and hips to return to the starting position.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('barbell-hang-clean', 'Hang Clean', NULL, 'olympic', NULL, 'compound', 'pull', 'bilateral', 'intermediate', NULL, NULL, NULL, 1),
('barbell-hang-clean-below-knees', 'Hang Clean - Below the Knees', NULL, 'olympic', NULL, 'compound', 'pull', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('barbell-hang-snatch', 'Hang Snatch', NULL, 'olympic', NULL, 'compound', 'pull', 'bilateral', 'advanced', NULL, NULL, NULL, 1),
('barbell-hang-snatch-below-knees', 'Hang Snatch - Below Knees', NULL, 'olympic', NULL, 'compound', 'pull', 'bilateral', 'advanced', NULL, NULL, NULL, 0),
('barbell-hanging-bar-good-morning', 'Hanging Bar Good Morning', NULL, 'strength', 'hinge', 'compound', 'push', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('barbell-heaving-snatch-balance', 'Heaving Snatch Balance', NULL, 'olympic', NULL, 'compound', 'push', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('barbell-hip-hinge', 'Hip hinge', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["Hip Hinge Exercise DescriptionThe hip hinge is a fundamental movement pattern that involves bending at the hips while keeping the spine neutral. It is commonly used in exercises like deadlifts, kettlebell swings, and good mornings. To perform a hip hinge: Starting Position: Stand with your feet hip-width apart and a slight bend in your knees. Hinge at the Hips: Push your hips back while maintaining a straight back. Your torso should lean forward, and your chest should stay up. Lowering Phase: Continue to hinge until your torso is nearly parallel to the ground, or until you feel a stretch in your hamstrings. Return to Standing: Drive through your heels and thrust your hips forward to return to the starting position."]', 'wger', 0),
('barbell-hip-thrust', 'Hip Thrust', 'Beckenheben', 'strength', 'hinge', 'compound', 'push', 'bilateral', 'intermediate', NULL, '["Sit on the ground with your back against a bench, your feet flat on the ground, and position a barbell across your hips.", "Engage your core and glute muscles, and slowly lift your hips up off the ground until your body forms a straight line from your knees to your shoulders.", "Hold for a second or two at the top of the movement, then lower your hips back down to the ground.", "Repeat."]', 'longhaul-fitness', 0),
('barbell-incline-bench-pull', 'Incline Bench Pull', NULL, 'strength', 'isolation_other', 'isolation', 'pull', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('barbell-incline-shoulder-raise', 'Barbell Incline Shoulder Raise', NULL, 'strength', NULL, 'compound', 'push', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('barbell-jefferson-squat', 'Jefferson Squats', NULL, 'strength', 'squat', 'compound', 'push', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('barbell-jerk-balance', 'Jerk Balance', NULL, 'olympic', NULL, 'compound', 'push', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('barbell-jerk-dip-squat', 'Jerk Dip Squat', NULL, 'olympic', NULL, 'compound', 'push', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('barbell-jerk-ol', 'Jerk OL', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["Olympic lift jerk", "Hold bar in front on shoulders like push press", "Bend and extend knees pushing bar up while diving under the bar", "Catch bar overhead with straight arms using lunge", "Move feet parallel while holding bar in lockout"]', 'wger', 0),
('barbell-jm-press', 'JM Press', NULL, 'strength', 'elbow_extension', 'compound', 'push', 'bilateral', 'beginner', NULL, '["The JM press keeps your shoulders stationary, relying on the elbow flexion and extension to move the weight using your triceps strength. That means you get all the benefits of the best triceps-strengthening exercises without overtaxing that delicate shoulder joint. Classic win-win!"]', 'wger', 0),
('barbell-kickstand-romanian-deadlift', 'Kickstand RDL', NULL, 'strength', 'hinge', NULL, NULL, 'bilateral', NULL, NULL, '["use non-working leg''s toes to help with balance and perform an RDL."]', 'wger', 0),
('barbell-kneeling-cuban-rotation', 'Kneeling Cuban Rotation – Barbell', NULL, 'strength', 'rotation', NULL, NULL, 'bilateral', NULL, NULL, '["Start in a tall kneeling position with your knees hip-width apart and your torso upright.", "Hold a barbell with a wide, pronated grip (palms facing forward) in both hands over your head.", "Lower the barbell towards your head by bending your elbows until your upper arms are parallel to the ground and your forearms are perpendicular to the ground. This is your starting position.", "Slowly lower the barbell by rotating your shoulders forward, keeping your elbows as stationary as possible.", "Pause briefly when your forearms have rotated parallel to the ground.", "Rotate your shoulders backwards, slowly raising the barbell back to the starting position.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('barbell-landmine-180s', 'Landmine 180''s', NULL, 'strength', NULL, 'compound', 'pull', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('barbell-landmine-linear-jammer', 'Landmine Linear Jammer', NULL, 'strength', NULL, 'compound', 'push', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('barbell-landmine-press', 'Landmine press', 'Landmine-Press, Einarmig', 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, NULL, NULL, 0),
('barbell-landmine-squat-to-press', 'Landmine Squat to Press', NULL, 'strength', 'squat', NULL, NULL, 'bilateral', NULL, NULL, '["Bar Position: Anchor one end of a barbell in a landmine attachment or a secure corner. Stance: Stand facing the barbell with feet slightly wider than shoulder-width. Turn your toes out 10–35 degrees to allow for better pelvic movement and depth. Grip: Cup the free end of the barbell with both hands (fingers interlaced or overlapping) and hold it at mid-chest level, just below the collarbone.", "Descent: Brace your core and sit back into a squat, keeping your chest up and weight on your heels. Depth: Lower until your thighs are at least parallel to the floor. A good reference is when your elbows touch the tops of your thighs or just inside your knees. Posture: Ensure your back remains flat and your spine neutral throughout the movement.", "Drive: Powerfully drive through your heels to stand up. Use the momentum from your legs to \"thrust\" the weight upward. Extension: In one fluid motion, press the bar overhead until your arms are fully extended. At the top, your biceps should be near your ears. The \"Lean\": As you reach the top of the press, lean slightly forward into the bar to encourage proper upward rotation of the shoulder blades and avoid lower back arching.", "Slowly lower the barbell back to chest height in a controlled manner before immediately beginning the next repetition."]', 'wger', 0),
('barbell-larsen-press', 'Larsen Press', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["Put your legs up on a separate Bench and press with no leg drive"]', 'wger', 0),
('barbell-low-box-squat-wide-stance', 'Low Box Squat - Wide Stance', NULL, 'strength', 'squat', NULL, NULL, 'bilateral', NULL, NULL, '["Unrack the bar and set your stance wide, beyond your hips. Push your hips back and sit down to a box that takes you below parallel. Sit completely down, do not touch and go. Then explosively stand up. Stay tight in your upper back and torso throughout the movement."]', 'wger', 0),
('barbell-lunge', 'Lunge – Barbell', NULL, 'strength', 'lunge', 'compound', 'push', NULL, 'intermediate', NULL, '["Start by standing with your feet hip-width apart and your back straight.", "Hold a barbell across your upper back, resting it on your shoulders.", "Take a step forward with your right foot, keeping your core engaged and your chest lifted.", "Bend both knees to lower your body towards the ground, making sure your front knee does not go past your toes.", "Lower your body until your front thigh is parallel to the ground, and your back knee is hovering just above the floor.", "Push through your front heel to return to the starting position.", "Repeat the movement on the other side by stepping forward with your left foot.", "Continue alternating legs for the desired number of repetitions."]', 'longhaul-fitness', 1),
('barbell-lying-cambered-row', 'Lying Cambered Barbell Row', NULL, 'strength', 'horizontal_pull', 'isolation', 'pull', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('barbell-lying-close-grip-triceps-extension-behind-head', 'Lying Close-Grip Barbell Triceps Extension Behind The Head', NULL, 'strength', 'elbow_extension', 'isolation', 'push', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('barbell-lying-close-grip-triceps-press-to-chin', 'Lying Close-Grip Barbell Triceps Press To Chin', NULL, 'strength', 'isolation_other', 'isolation', 'push', 'bilateral', 'intermediate', NULL, NULL, NULL, 1),
('barbell-lying-high-bench-curl', 'Lying High Bench Barbell Curl', NULL, 'strength', 'elbow_flexion', 'isolation', 'pull', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('barbell-meadows-row', 'Meadows Row', NULL, 'strength', 'horizontal_pull', NULL, NULL, 'bilateral', NULL, NULL, '["The Meadows row is a unilateral row performed with a landmine setup, overhand grip, and staggered stance. Lean your torso forward and grip the barbell. Rest the other forearm on the forward leg. Start this movement by driving the elbow behind you while retracting the shoulder-blade. Keep the working shoulder down. Pull toward your back hip until the elbow is level with your torso."]', 'wger', 0),
('barbell-muscle-snatch', 'Muscle Snatch', NULL, 'olympic', NULL, 'compound', 'pull', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('barbell-neck-press', 'Neck Press', NULL, 'strength', NULL, 'compound', 'push', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('barbell-olympic-squat', 'Olympic Squat', NULL, 'olympic', 'squat', 'compound', 'push', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('barbell-one-arm-long-bar-row', 'One-Arm Long Bar Row', NULL, 'strength', 'horizontal_pull', 'compound', 'pull', 'unilateral', 'beginner', NULL, NULL, NULL, 0),
('barbell-one-arm-side-deadlift', 'One-Arm Side Deadlift', NULL, 'strength', 'hinge', 'compound', 'pull', 'unilateral', 'advanced', NULL, NULL, NULL, 0),
('barbell-one-handed-shoulder-press-landmine', 'One-Handed Shoulder Press – Landmine', NULL, 'strength', 'vertical_push', NULL, NULL, 'unilateral', NULL, NULL, '["Position a barbell securely in a landmine attachment or securely in a corner to prevent it from sliding.", "Load the desired weight onto the free end of the barbell.", "Stand facing the barbell with your feet shoulder-width apart for stability.", "Bend slightly to grab the barbell with one hand directly where the barbell is loaded.", "Raise the barbell to your shoulder level, switching your grip so that your hand is under the barbell and your palm faces your chin over a bent and tucked elbow. This is your starting position.", "Brace your core, and exhale as you press the barbell upward and slightly forward by extending your arm.", "Keep your body straight and avoid rotating your hips or shoulders during the press.", "Inhale as you slowly return the barbell to the starting position at your shoulder.", "Complete all reps on one side before switching hands to work the opposite side."]', 'longhaul-fitness', 0),
('barbell-overhead-squat', 'Overhead Squat', NULL, 'olympic', 'squat', 'compound', 'push', 'bilateral', 'advanced', NULL, NULL, NULL, 0),
('barbell-overhead-tricep-extension', 'Overhead Tricep Extension – Barbell', NULL, 'strength', 'elbow_extension', NULL, NULL, 'bilateral', NULL, NULL, '["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip.", "Bring the barbell behind your head, keeping your elbows close to your ears.", "Extend your arms upward, straightening your elbows and lifting the barbell above your head.", "Pause briefly at the top of the movement, then slowly lower the barbell back behind your head.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('barbell-palms-down-wrist-curl-over-bench', 'Palms-Down Wrist Curl Over A Bench', NULL, 'strength', 'isolation_other', 'isolation', 'pull', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('barbell-palms-up-wrist-curl-over-bench', 'Palms-Up Barbell Wrist Curl Over A Bench', NULL, 'strength', 'isolation_other', 'isolation', 'pull', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('barbell-pause-bench', 'Pause Bench', 'Pause Bench', 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["Lower the bar to your chest and pause (but do not rest) there for 2 seconds. Press back up. use the same weight you would on bench press, but perform only single reps. Total the number of reps you did in one set of bench press (if you did 3 sets of 8 do 8 sinlge pause bench reps."]', 'wger', 0),
('barbell-pendelay-row', 'Pendelay Rows', 'Pendelay Rows', 'strength', 'horizontal_pull', NULL, NULL, 'bilateral', NULL, NULL, '["Back excercise with a barbell with a starting position which is in a bent over position with the back paralell to the ground. The barbell is on the ground at chest level.For the movement grab the barbell at shoulder width grip and pull towards your chest without losing the bent over position and without moving anything but your arms"]', 'wger', 0),
('barbell-perpendicular-unilateral-landmine-row', 'Perpendicular Unilateral Landmine Row', NULL, 'strength', 'horizontal_pull', NULL, NULL, 'unilateral', NULL, NULL, '["Using a landmine attachment with the barbell running at 90 degrees to either side, hinge slightly at the hips and grip the barbell by the plate sleeve. Raise the barbell to chest height, with your upper arm parallel to the floor at the top of the movement."]', 'wger', 0),
('barbell-pin-bench-press', 'Pin Bench Press BB', NULL, 'strength', 'horizontal_push', NULL, NULL, 'bilateral', NULL, NULL, '["Set security pins to about the height of your sticking point", "Lower the bar, rest on the pins for 1s while holding tension", "Move bar up with maximum force"]', 'wger', 0),
('barbell-pin-ohp', 'Pin OHP', NULL, 'strength', 'vertical_push', NULL, NULL, 'bilateral', NULL, NULL, '["Set security pins to the height of your lower chin", "Rest bar on pins keeping tension", "Raise bar over head"]', 'wger', 0),
('barbell-pin-press', 'Pin Presses', NULL, 'strength', NULL, 'compound', 'push', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('barbell-pin-squat', 'Pin Squat', NULL, 'strength', 'squat', NULL, NULL, 'bilateral', NULL, NULL, '["Set security pins to about the height of your sticking point", "Lower the bar, rest on the pins for 2s keeping tension", "Stand up with maximum force"]', 'wger', 0),
('barbell-power-clean', 'Power Clean', 'Umsetzen', 'strength', NULL, 'compound', 'pull', 'bilateral', 'intermediate', NULL, '["Olympic weight lifting"]', 'wger', 0),
('barbell-power-clean-from-blocks', 'Power Clean from Blocks', NULL, 'olympic', NULL, 'compound', 'pull', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
