('barbell-power-snatch', 'Power Snatch', NULL, 'olympic', NULL, 'compound', 'pull', 'bilateral', 'advanced', NULL, NULL, NULL, 1),
('barbell-power-snatch-from-blocks', 'Power Snatch from Blocks', NULL, 'olympic', NULL, 'compound', 'pull', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('barbell-preacher-curl', 'Preacher Curl – Barbell', NULL, 'strength', 'elbow_flexion', 'isolation', 'pull', 'bilateral', 'beginner', NULL, '["Set up a preacher curl bench with the appropriate weight on the barbell.", "Adjust the seat height so that your armpits are resting comfortably on the top of the bench.", "Grab the barbell with an underhand grip, hands shoulder-width apart.", "Place your upper arms on the bench pad, keeping your elbows close to your body.", "Exhale and curl the barbell up towards your shoulders, keeping your upper arms stationary.", "Pause briefly at the top of the movement, squeezing your biceps.", "Inhale and slowly lower the barbell back down to the starting position.", "Repeat."]', 'longhaul-fitness', 0),
('barbell-press-sit-up', 'Press Sit-Up', NULL, 'strength', NULL, 'compound', 'push', 'bilateral', 'advanced', NULL, NULL, NULL, 0),
('barbell-pullover', 'Pullover – Barbell', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["Lie on a bench with your head and shoulders supported, and your feet flat on the floor.", "Hold a barbell with a pronated grip (palms facing forward) slightly wider than shoulder-width, and press it up to arm''s length over your chest. This is your starting position.", "Keep a slight bend in your elbows and lock your arms in this slightly bent position throughout the entire movement.", "Inhale and slowly lower the barbell in an arc behind your head while keeping your arms straight, moving primarily at the shoulder joints.", "Lower the barbell until your arms are parallel to the floor or until you feel a stretch in your chest or lats, whichever comes first.", "Exhale as you reverse the motion, bringing the barbell back over your chest in the same arc motion.", "Repeat for the desired number of reps."]', 'longhaul-fitness', 0),
('barbell-push-ohp', 'Push OHP', NULL, 'strength', 'vertical_push', NULL, NULL, 'bilateral', NULL, NULL, '["Rest bar in front on your shoulders", "Bend knees while keeping upper body straight", "Extend legs pushing the bar overhead with force"]', 'wger', 0),
('barbell-push-press', 'Push Press – Barbell', NULL, 'olympic', 'vertical_push', 'compound', 'push', 'bilateral', 'advanced', NULL, '["Start with the barbell resting on your front shoulders, with your feet shoulder-width apart.", "Bend your knees slightly and dip your hips down, then explosively extend your legs and push the barbell up overhead.", "As the barbell reaches the top of the movement, press it up and lock out your arms.", "Lower the barbell back down to your shoulders and repeat for the desired number of reps."]', 'longhaul-fitness', 1);
INSERT INTO exercises (id, name_en, name_de, category, movement_pattern, mechanic, force, laterality, level, variation_of, instructions, instructions_source_id, needs_review) VALUES
('barbell-rack-delivery', 'Rack Delivery', NULL, 'olympic', NULL, 'compound', 'pull', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('barbell-rack-pull', 'Rack Pulls', NULL, 'strength', NULL, 'compound', 'pull', 'bilateral', 'intermediate', NULL, NULL, NULL, 1),
('barbell-rear-delt-row', 'Rear Delt Row – Barbell', NULL, 'strength', 'horizontal_pull', 'compound', 'pull', 'bilateral', 'beginner', NULL, '["Stand with your feet shoulder-width apart and your knees slightly bent.", "Hold a barbell with an overhand grip, hands shoulder-width apart.", "Lean forward at the hips, keeping your back straight and your abs engaged.", "Bring the barbell up towards your upper chest, keeping your elbows wide and out to the sides.", "Squeeze your shoulder blades together at the top of the movement.", "Lower the barbell back down to the starting position.", "Repeat."]', 'longhaul-fitness', 0),
('barbell-remo-alto-polea-alta', 'Remo alto polea alta', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["High pulley row with support using a single grip"]', 'wger', 0),
('barbell-reverse-preacher-curl', 'Reverse Barbell Preacher Curls', NULL, 'strength', 'elbow_flexion', 'isolation', 'pull', 'bilateral', 'intermediate', NULL, NULL, NULL, 1),
('barbell-reverse-triceps-bench-press', 'Reverse Triceps Bench Press', NULL, 'strength', 'horizontal_push', 'compound', 'push', 'bilateral', 'intermediate', NULL, NULL, NULL, 1),
('barbell-rocking-standing-calf-raise', 'Rocking Standing Calf Raise', NULL, 'strength', 'isolation_other', 'isolation', 'push', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('barbell-rollout-from-bench', 'Barbell Rollout from Bench', NULL, 'strength', NULL, 'compound', 'pull', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('barbell-romanian-deadlift-from-deficit', 'Romanian Deadlift from Deficit', NULL, 'olympic', 'hinge', 'compound', 'pull', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('barbell-row', 'Row – Barbell', NULL, 'strength', 'horizontal_pull', NULL, NULL, 'bilateral', NULL, NULL, '["Stand in front of a barbell with your feet shoulder-width apart.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.", "Engage your core and pull the barbell towards your upper abs or lower chest, keeping your elbows close to your body.", "Pause and squeeze your shoulder blades together for a moment at the top of the movement.", "Slowly lower the barbell back to the starting position.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 1),
('barbell-seated-close-grip-concentration-curl', 'Seated Close-Grip Concentration Barbell Curl', NULL, 'strength', 'elbow_flexion', 'isolation', 'pull', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('barbell-seated-palm-up-wrist-curl', 'Seated Palm-Up Barbell Wrist Curl', NULL, 'strength', 'isolation_other', 'isolation', 'pull', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('barbell-seated-palms-down-wrist-curl', 'Seated Palms-Down Barbell Wrist Curl', NULL, 'strength', 'isolation_other', 'isolation', 'pull', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('barbell-seated-twist', 'Seated Barbell Twist', NULL, 'strength', 'rotation', 'isolation', 'pull', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('barbell-shoulder-press', 'Shoulder Press, Barbell', 'Schulterdrücken LH', 'strength', 'vertical_push', 'compound', 'push', 'bilateral', 'intermediate', NULL, '["Start by standing with your feet shoulder-width apart, looking at a racked, weighted barbell.", "Raise the barbell to shoulder height, palms facing forward, and elbows bent.", "Press the barbell upward until your arms are fully extended above your head.", "Pause for a moment at the top of the movement, then slowly lower the barbell back down to shoulder height.", "Repeat."]', 'longhaul-fitness', 0),
('barbell-shrug', 'Shrugs, Barbells', 'Shrugs LH', 'strength', 'isolation_other', 'isolation', 'pull', 'bilateral', 'beginner', NULL, '["Stand with your feet shoulder-width apart and hold a barbell in front of your thighs with an overhand grip.", "Keep your arms fully extended and your shoulders relaxed.", "Slowly raise your shoulders as high as possible, as if you are trying to touch your ears with them.", "Hold the contracted position for a brief pause, squeezing your shoulder muscles.", "Lower your shoulders back down to the starting position in a controlled manner.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('barbell-shrug-behind-back', 'Barbell Shrug Behind The Back', NULL, 'strength', 'isolation_other', 'isolation', 'pull', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('barbell-side-bend', 'Barbell Side Bend', NULL, 'strength', 'isolation_other', 'isolation', 'pull', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('barbell-side-split-squat', 'Barbell Side Split Squat', NULL, 'strength', 'lunge', 'compound', 'push', 'unilateral', 'beginner', NULL, NULL, NULL, 0),
('barbell-silverback-shrug', 'Barbell Silverback Shrug', NULL, 'strength', 'isolation_other', NULL, NULL, 'bilateral', NULL, NULL, '["Stand with your feet shoulder width apart holding the barbell with both hands in front just past shoulder width.", "Bend forward at the hips with a slight bend in your knees, keeping your back straight.", "Engage your shoulder blades, as if you are trying to touch them together.", "Release the shrug. Description taken from MuscleWiki"]', 'wger', 0),
('barbell-single-arm-linear-jammer', 'Single-Arm Linear Jammer', NULL, 'strength', NULL, 'compound', 'push', 'unilateral', 'intermediate', NULL, NULL, NULL, 0),
('barbell-single-arm-thruster-landmine', 'Single-Arm Thruster – Landmine', NULL, 'strength', NULL, NULL, NULL, 'unilateral', NULL, NULL, '["Start by placing a barbell into a landmine attachment or securely anchor it into a corner.", "Stand with feet shoulder-width apart, holding the unattached end of the barbell with one hand at shoulder height. This is your starting position.", "Perform a squat by pushing your hips back, keeping your chest up, and bending your knees until your thighs are parallel to the floor.", "Explode upward from the squat position, using leg drive to assist in pressing the barbell overhead.", "Extend your arm fully overhead while keeping the opposite arm by your side for balance.", "Slowly lower the barbell back to shoulder height, controlling the descent, returning to the starting position.", "Repeat for the desired number of repetitions, then switch to the other arm."]', 'longhaul-fitness', 0),
('barbell-single-leg-romanian-deadlift-landmine', 'Single-Leg Romanian Deadlift – Landmine', NULL, 'strength', 'hinge', NULL, NULL, 'unilateral', NULL, NULL, '["Stand with your right side facing the end of a barbell secured in a landmine attachment, holding the bar with your right hand using a pronated (overhand) grip. The end of the barbell should be at arms-length in front of your quad. This is your starting position.", "Shift your weight onto your left leg, keeping a slight bend in the knee of your standing leg.", "Hinge at your hips and lean forward, extending your right leg straight back for balance.", "Lower the barbell toward the floor while keeping your back straight and core engaged, ensuring your hips remain square.", "Continue lowering until you feel a stretch in the hamstring of the standing leg or your upper body is nearly parallel to the floor.", "Drive through the heel of the standing leg to return to the starting position, engaging your glutes as you stand.", "Keep your gaze forward and chest lifted throughout the movement to maintain a flat back.", "Repeat for the desired number of reps before switching to the opposite leg."]', 'longhaul-fitness', 0),
('barbell-skull-crusher', 'Skull Crusher – Barbell', NULL, 'strength', 'elbow_extension', NULL, NULL, 'bilateral', NULL, NULL, '["Lie down on a flat bench with a barbell in your hands. Your feet should be flat on the floor for stability.", "Grip the barbell with an overhand grip (palms facing towards your feet) slightly narrower than shoulder-width apart.", "Extend your arms fully so that the barbell is directly above your shoulders. This is your starting position.", "Keeping your upper arms stationary, inhale and slowly lower the barbell by bending your elbows until the barbell is just above your forehead.", "Pause when the barbell is closest to your forehead, ensuring your elbows are in position and only your forearms are moving.", "Exhale and raise the barbell back to the starting position by extending your elbows and contracting the triceps.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('barbell-sliding-lateral-lunge', 'Sliding Lateral Lunge', NULL, 'strength', 'lunge', NULL, NULL, NULL, NULL, NULL, '["Stand upright with your feet hip-width apart, holding a kettlebell close to your chest in goblet position. Place one foot on a slider, gliding disc, or towel. Keep your chest tall and core engaged. Slowly slide the foot outward to the side while bending the opposite knee, lowering your hips into a lateral lunge. Keep the working leg’s knee aligned with the toes and avoid letting it collapse inward. The non-working leg remains straight and slides smoothly along the floor. Push through the heel of the bent leg to return to the starting position while maintaining control of the kettlebell."]', 'wger', 0),
('barbell-snach', 'Snach', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["Stand with your feet at hip width and your shins against the bar. Grasp the bar at double shoulder width and, keeping your lower back flat, drive your heels into the floor to begin lifting the bar. When it''s above your knees, explosively extend your hips and shrug your shoulders. Let the momentum carry the weight overhead."]', 'wger', 0),
('barbell-snatch', 'Snatch', NULL, 'olympic', NULL, 'compound', 'pull', 'bilateral', 'intermediate', NULL, NULL, NULL, 1),
('barbell-snatch-balance', 'Snatch Balance', NULL, 'olympic', NULL, 'compound', 'push', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('barbell-snatch-deadlift', 'Snatch Deadlift', NULL, 'olympic', NULL, 'compound', 'pull', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('barbell-snatch-from-blocks', 'Snatch from Blocks', NULL, 'olympic', NULL, 'compound', 'pull', 'bilateral', 'advanced', NULL, NULL, NULL, 0),
('barbell-snatch-ol', 'Snatch OL', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["Olympic lift snatch", "Pull barbell from ground to overhead lockout using a wide grip and overhead squat.", "Move bar slowly until cleared knees then explosively extend hips, pull bar up and dive under the bar", "Catch bar overhead with straight arms", "Push head forward during lockout"]', 'wger', 0),
('barbell-snatch-pull', 'Snatch Pull', NULL, 'strength', NULL, 'compound', 'pull', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('barbell-snatch-shrug', 'Snatch Shrug', NULL, 'olympic', NULL, 'compound', 'pull', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('barbell-speed-box-squat', 'Speed Box Squat', NULL, 'strength', 'squat', 'compound', 'push', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('barbell-speed-squat', 'Speed Squats', NULL, 'strength', 'squat', 'compound', 'push', 'bilateral', 'advanced', NULL, NULL, NULL, 0),
('barbell-split-clean', 'Split Clean', NULL, 'olympic', NULL, 'compound', 'pull', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('barbell-split-jerk', 'Split Jerk', NULL, 'olympic', NULL, 'compound', 'push', 'bilateral', 'intermediate', NULL, NULL, NULL, 1),
('barbell-split-snatch', 'Split Snatch', NULL, 'olympic', NULL, 'compound', 'pull', 'bilateral', 'advanced', NULL, NULL, NULL, 0),
('barbell-split-squat', 'Split Squat – Barbell', NULL, 'strength', 'lunge', NULL, NULL, 'unilateral', NULL, NULL, '["Set up a barbell on a squat rack at shoulder height and load it with the desired weight.", "Position yourself under the barbell, placing it comfortably across your upper back. Hold the barbell with both hands just outside shoulder-width.", "Engage your core, step back and away from the rack, and position one foot forward and the other foot back, bending your knees.", "Adjust your position so your back toe is on the ground and your forward knee is slightly bent. This is your starting position.", "Lower your hips by bending both knees until your back knee is just above the ground. Keep your chest lifted and your front knee over your ankle.", "Push through your front heel and extend your legs to return to the starting position.", "Complete the desired number of repetitions and switch to the other side."]', 'longhaul-fitness', 0),
('barbell-squat', 'Squats', 'Kniebeuge', 'strength', 'squat', 'compound', 'push', 'bilateral', 'beginner', NULL, '["Begin by standing with your feet shoulder-width apart and your toes pointing forward. Hold a barbell behind your neck, resting it on your shoulders with your elbows pointing down and your palms facing forward.", "Engage your core and keep your chest lifted as you bend your knees and lower your hips back and down as if sitting in a chair. Make sure to keep your weight on your heels and your knees tracking in line with your toes.", "As you descend into the squat, inhale and maintain proper form. Lean forward so that your chest is over your thighs. Keep your back straight and your core engaged. Lower your body until your thighs parallel the ground, and your hips should align with your knees.", "Pause briefly at the bottom of the movement, then exhale and push through your heels to stand back up to the starting position. Keep your core engaged and your chest lifted until you''re fully standing.", "Repeat the movement for your desired number of repetitions.", "Place the barbell on the rack after you''ve finished your set."]', 'longhaul-fitness', 0),
('barbell-squat-chains', 'Squat with Chains', NULL, 'strength', 'squat', 'compound', 'push', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('barbell-squat-jerk', 'Squat Jerk', NULL, 'strength', NULL, 'compound', 'push', 'bilateral', 'advanced', NULL, NULL, NULL, 1),
('barbell-squat-landmine', 'Squat – Landmine', NULL, 'strength', 'squat', NULL, NULL, 'bilateral', NULL, NULL, '["Start by placing a barbell into a landmine attachment or securely anchor it into a corner.", "Stand facing the barbell with your feet shoulder-width apart and your toes pointing slightly outward.", "Grab the end of the barbell with both hands and lift it up to your chest.", "Lower your hips down and back, keeping your chest up and your back straight.", "Bend your knees and lower your body until your thighs are parallel to the ground.", "Push through your heels and stand back up to the starting position.", "Repeat."]', 'longhaul-fitness', 0),
('barbell-squat-to-bench', 'Barbell Squat To A Bench', NULL, 'strength', 'squat', 'compound', 'push', 'bilateral', 'advanced', NULL, NULL, NULL, 0),
('barbell-standing-bradford-press', 'Standing Bradford Press', NULL, 'strength', NULL, 'compound', 'push', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('barbell-standing-front-raise-over-head', 'Standing Front Barbell Raise Over Head', NULL, 'strength', 'isolation_other', 'isolation', 'push', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('barbell-standing-palms-up-behind-back-wrist-curl', 'Standing Palms-Up Barbell Behind The Back Wrist Curl', NULL, 'strength', 'isolation_other', 'isolation', 'pull', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('barbell-standing-press-behind-neck', 'Standing Barbell Press Behind Neck', NULL, 'strength', NULL, 'compound', 'push', 'bilateral', 'intermediate', NULL, NULL, NULL, 1),
('barbell-step-back-lunge', 'Barbell Step Back Lunge', NULL, 'strength', 'lunge', NULL, NULL, NULL, NULL, NULL, '["Step 1: Stand with your feet hip-width apart, holding a barbell on your upper back. Step 2: Keep your back straight, chest up, and core engaged. Step 3: Take a step back with one leg and lower your body by bending both knees. Ensure that your back knee nearly touches the ground. Step 4: Push off your back foot to return to the starting position. Step 5: Repeat the movement with the other leg. Continue alternating between legs for the desired repetitions."]', 'wger', 0),
('barbell-step-up', 'Barbell Step Ups', NULL, 'strength', 'lunge', 'compound', 'push', 'unilateral', 'intermediate', NULL, NULL, NULL, 1),
('barbell-straight-bar-bench-mid-row', 'Straight Bar Bench Mid Rows', NULL, 'strength', 'horizontal_pull', 'compound', 'pull', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('barbell-straight-raise-incline-bench', 'Straight Raises on Incline Bench', NULL, 'strength', 'isolation_other', 'isolation', 'push', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('barbell-supine-press', 'Supine press', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["Take a close grip and push perpendicular to the bench. Keep back flat."]', 'wger', 0),
('barbell-t-bar-row', 'T-Bar row', NULL, 'strength', 'horizontal_pull', NULL, NULL, 'bilateral', NULL, NULL, '["Load the desired weight onto the T-Bar machine.", "Lie down on the T-Bar machine with your feet securely planted.", "Grasp the handles of the T-Bar with an overhand grip.", "Pull the T-Bar towards your chest, keeping your elbows close to your body.", "Pause briefly at the top of the movement, squeezing your shoulder blades together.", "Slowly lower the T-Bar back to the starting position.", "Repeat."]', 'longhaul-fitness', 1),
('barbell-t-bar-row-handle', 'T-Bar Row with Handle', NULL, 'strength', 'horizontal_pull', 'compound', 'pull', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('barbell-thruster', 'Thruster', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["Start by doing a front squat", "At the top position, push the bar above your head (similar to a press)", "Lower the bar to the shoulders"]', 'wger', 0),
('barbell-triceps-extension', 'Barbell Triceps Extension', 'Trizepsdrücken KH Über Kopf', 'strength', 'elbow_extension', NULL, NULL, 'bilateral', NULL, NULL, '["Position barbell overhead with narrow overhand grip.", "Lower forearm behind upper arm with elbows remaining overhead. Extend forearm overhead. Lower and repeat."]', 'wger', 0),
('barbell-upright-row', 'Upright Row – Barbell', NULL, 'strength', 'vertical_pull', 'compound', 'pull', 'bilateral', 'beginner', NULL, '["Stand with your feet shoulder-width apart and your knees slightly bent.", "Grasp the barbell with an overhand grip, hands narrower than shoulder-width apart.", "Hold the barbell in front of your thighs with your arms extended.", "Exhale and lift the barbell straight up towards your chin, keeping it close to your body.", "Pause for a moment at the top of the movement, then inhale and slowly lower the barbell back down to the starting position.", "Repeat."]', 'longhaul-fitness', 0),
('barbell-walking-lunge', 'Barbell Lunges Walking', NULL, 'strength', 'lunge', 'compound', 'push', 'alternating', 'beginner', NULL, '["Start with your feet hip-width apart and the barbell on your shoulders.", "Take a large step forward with your right foot, lowering your body until your right thigh is parallel to the ground and your left knee is hovering just above the floor.", "Push through your right heel to stand back up, bringing your left foot forward to meet your right foot.", "Repeat the lunge on the other side by stepping forward with your left foot.", "Continue alternating lunges for the desired number of reps or distance."]', 'longhaul-fitness', 0),
('barbell-weighted-sissy-squat', 'Weighted Sissy Squat', NULL, 'strength', 'squat', 'compound', 'push', 'bilateral', 'advanced', NULL, NULL, NULL, 0),
('barbell-wide-stance-stiff-legs', 'Wide Stance Stiff Legs', NULL, 'olympic', NULL, 'compound', 'pull', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('barbell-wrist-curl', 'Barbell Wrist Curl', 'Handgelenkstreckung', 'strength', 'isolation_other', NULL, NULL, 'bilateral', NULL, NULL, '["Start by sitting on a bench with your forearms resting on your knees and your palms facing up.", "Hold a barbell with an underhand grip, with your hands shoulder-width apart.", "Slowly lift the barbell towards your forearms by curling your wrists.", "Pause for a moment at the top of the movement, then slowly lower the barbell back down to the starting position.", "Repeat."]', 'longhaul-fitness', 0),
('barbell-wrist-curl-behind-back', 'Wrist Curl Behind the Back – Barbell', NULL, 'strength', 'isolation_other', NULL, NULL, 'bilateral', NULL, NULL, '["Stand with your feet shoulder-width apart and your knees slightly bent.", "Hold a barbell with an overhand grip behind your back, with your palms facing away from your body.", "Keep your elbows close to your body and your upper arms stationary.", "Curl the barbell up towards your forearms, keeping your wrists straight.", "Pause at the top of the movement and squeeze your forearms.", "Slowly lower the barbell back down to the starting position.", "Repeat."]', 'longhaul-fitness', 0),
('barbell-wrist-extension', 'Wrist Extension – Barbell', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["Hold a barbell with an overhand grip, with your hands shoulder-width apart.", "Sit on a bench with your feet shoulder-width apart.", "Rest the barbell on the top of your thighs, with your palms facing down.", "Slowly lift the barbell by extending your wrists, keeping your elbows stationary. Focus on bringing your knuckles back towards the top of your forearms.", "Hold the barbell at the top of the movement for a moment.", "Lower the barbell back down to the starting position by flexing your wrists.", "Repeat."]', 'longhaul-fitness', 0),
('barbell-wrist-rotation-straight-bar', 'Wrist Rotations with Straight Bar', NULL, 'strength', 'rotation', 'isolation', 'pull', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('barbell-z-press', 'Z Press – Barbell', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["Position a loaded barbell in a rack a little above knee height.", "Sit down on the floor so that the barbell touches your upper chest.", "Extend your legs straight in front of you. Ensure your back is straight.", "Grip the barbell just outside shoulder width with palms facing forward.", "Unrack the barbell so it is positioned in front of your chin with tension on your front shoulders. This is your starting position.", "Brace your core. Push your heels into the ground.", "Press the barbell upwards until your arms are fully extended, making sure the bar moves in a straight vertical line.", "Pause briefly at the top of the movement.", "Lower the bar back to the starting position in a controlled manner.", "Repeat for the desired number of reps."]', 'longhaul-fitness', 0),
('barbell-zercher-squat', 'Zercher Squats', NULL, 'strength', 'squat', 'compound', 'push', 'bilateral', 'advanced', NULL, NULL, NULL, 0),
('battle-ropes', 'Battle Ropes', NULL, 'cardio', NULL, NULL, NULL, NULL, NULL, NULL, '["Hold the ends of the rope at arm''s length in front of your hips with your hands shoulder-width apart.", "Brace your core and begin alternately raising and lowering each arm explosively.", "Keep alternating arms for three to four sets of 1 to 2 minutes."]', 'wger', 0),
('battling-ropes', 'Battling Ropes', NULL, 'strength', NULL, 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('bayesian-curl', 'Bayesian Curl', NULL, 'strength', 'elbow_flexion', NULL, NULL, NULL, NULL, NULL, '["Cable curl with stretched shoulder (backwards)"]', 'wger', 0),
('bear-crawl-sled-drags', 'Bear Crawl Sled Drags', NULL, 'strongman', 'locomotion', 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('bear-walk-2', 'Bear Walk 2', 'Bear Walk', 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["-Rest your weight on your palms and the balls of your feet, not dissimilar to normal pushup position", "-Move by stepping with your R palm and L foot, then your L palm and R foot. Basically, walk like a lumbering bear.", "-Move as fast as you can. Measure your reps/sets in either distance (i.e. 40 yards) or time (i.e. 45 seconds)", "-Works your Pecs, Deltoids, Triceps, Traps, Lats, Abs and Lower Back, Hip Flexors, Quads, Glutes and Calves"]', 'wger', 0),
('behind-head-chest-stretch', 'Behind Head Chest Stretch', NULL, 'stretching', NULL, 'isolation', 'static', NULL, 'advanced', NULL, NULL, NULL, 0),
('belt-squat', 'Belt Squat', NULL, 'strength', 'squat', NULL, NULL, 'bilateral', NULL, NULL, '["Belt Squat: a squat variation done with a belt attached to a loading machine or platform so the weight is supported at the hips instead of on the spine. It mainly trains the quads and glutes, with much less lower-back fatigue than a barbell squat. Use a full range of motion, keep the torso upright, and drive through the mid-foot."]', 'wger', 0),
('bench-dip-floor-hd', 'Bench Dips On Floor HD', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["Triceps dips on floor are a compound exercise as they worked multiple muscle groups simultaneously. Although this bodyweight exercise mainly targets the triceps, it also hits your chest and front of your shoulder. Triceps dips on floor are one of the most effective exercises to increase arm strength and also build lean muscle in your upper arms. Triceps dips on floor are a closed kinetic chain exercise and express that you do the movements around a fixed point. It increases compression force on your joints thereby improving stability."]', 'wger', 0),
('bench-jump', 'Bench Jump', NULL, 'plyometrics', NULL, 'compound', 'push', NULL, 'intermediate', NULL, NULL, NULL, 0),
('bench-sprint', 'Bench Sprint', NULL, 'plyometrics', 'locomotion', 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('bent-knee-hip-raise', 'Bent-Knee Hip Raise', NULL, 'strength', NULL, 'compound', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('biceps-close-grip-pull-down', 'Biceps Close Grip Pull Down', NULL, 'strength', 'vertical_pull', NULL, NULL, NULL, NULL, NULL, '["On a lat pull down machine, hold the bar keeping your hands relatively close. Use an underhand grip (I.E.: the back of your hand must be facing the machine). Then pull down the bar in a straight line towards the ground. Make sure your biceps are the main drivers of the motion. You will probably feel your shoulders and lats working, but make sure your biceps are working more."]', 'wger', 0),
('biceps-trx', 'Biceps with TRX', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Grab the handles of the TRX straps, lean your body back, arms and legs extended, with your body positioned in a single straight line. (This is an arm exercise, not an abdominal one.)"]', 'wger', 0),
('bicycle-crunch', 'bicycle crunches', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["Bicycle crunches are a core exercise performed on the floor. Lie on your back with your hands behind your head and legs extended. Lift your shoulders off the ground, bring one knee toward your chest, and twist your torso so your opposite elbow meets the knee. Alternate sides in a pedaling motion, ensuring controlled movements and engaging your core throughout the exercise."]', 'wger', 0),
('bicycle-crunch-2', 'Bicycle Crunch', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["Lie flat on your back with your hands behind your head and your knees bent.", "Bring your right elbow towards your left knee while simultaneously straightening your right leg.", "Return to the starting position and repeat the movement on the opposite side, bringing your left elbow towards your right knee while straightening your left leg.", "Continue alternating sides in a pedaling motion, keeping your core engaged and your lower back pressed into the floor.", "Complete the desired number of repetitions."]', 'longhaul-fitness', 1),
('bicycling', 'Bicycling', NULL, 'cardio', 'locomotion', NULL, NULL, NULL, 'beginner', NULL, NULL, NULL, 0),
('bird-dog', 'Bird Dog', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["The Bird Dog is a core stability exercise that enhances balance, coordination, and spinal alignment. It’s a low-impact movement ideal for strengthening the posterior chain and improving overall functional control.", "Begin on all fours with hands under shoulders and knees under hips, keeping your spine neutral.", "Extend your right arm forward and left leg backward simultaneously, keeping hips square.", "Pause briefly at full extension while engaging your core and glutes.", "Return to the starting position and repeat on the opposite side"]', 'wger', 0),
('black-widow-knee-slide', 'Black Widow Knee Slides', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["In this bottom-up rotation exercise movement, you’ll cross your knee over and drive it into that opposite elbow. Start in high plank position (or tabletop position) with hands directly beneath your shoulders. Lift the left knee toward the right arm and slide it up the forearm to get more of that posterior pelvic tilt and engagement of the abdominal muscles. Then do the opposite side, bringing your right knee toward your left hand."]', 'wger', 0),
('blaze', 'Blaze', NULL, 'cardio', NULL, NULL, NULL, NULL, NULL, NULL, '["BLAZE is a full-body HIIT workout. Designed to supercharge your cardio fitness and strength. Delivered in its own purpose-built studio, BLAZE is a unique mix of martial arts, intense cardio and strength training."]', 'wger', 0),
('block-snatch', 'Block Snatch', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Set up the blocks so the barbell rests somewhere between mid-shin to mid-thigh height.", "Stand with your feet hip-width apart, in front of the bar.", "Bend at the hips and knees, and grip the bar with a wide overhand grip.", "Position your shoulders slightly over the bar, back straight, eyes focused ahead. This is your starting position.", "Explosively extend your hips and knees, simultaneously shrugging your shoulders upward.", "Pull your body under the bar rapidly, rotating your wrists around the bar as you drop into a squat position.", "Catch the bar overhead with arms fully extended, while in a deep squat.", "Stand up by straightening your legs, keeping the bar steady overhead.", "Lower the bar back to the blocks carefully.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('body-tricep-press', 'Body Tricep Press', NULL, 'strength', 'isolation_other', 'isolation', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('body-up', 'Body-Up', NULL, 'strength', 'isolation_other', 'isolation', 'push', NULL, 'intermediate', NULL, NULL, NULL, 0),
('bodyweight-biceps-curl', 'Bodyweight Biceps Curl', NULL, 'strength', 'elbow_flexion', NULL, NULL, NULL, NULL, NULL, '["Adjust the height of the rings or TRX to waist height and stand facing them.", "Hold the rings or TRX handles with an underhand grip and lean back, extending your arms straight in front of you.", "Keep your feet shoulder-width apart and your body in a straight line from head to heels.", "Engage your biceps and bend your elbows, pulling your body up towards the rings or TRX handles.", "As you pull your body up, keep your elbows close to your body and your wrists straight.", "When your hands reach your chest, pause for a moment and then slowly lower your body back down to the starting position.", "Repeat the exercise for the desired number of reps."]', 'longhaul-fitness', 0),
('bodyweight-lunge-hd', 'Bodyweight lunge HD', NULL, 'strength', 'lunge', NULL, NULL, NULL, NULL, NULL, '["Bodyweight lunges are an effective calisthenic exercise for strengthening the lower body, improving balance and stability, and developing functional strength. They are a popular choice for bodyweight workouts, home workouts, and can also be included as part of a larger strength training routine."]', 'wger', 0),
('bodyweight-mid-row', 'Bodyweight Mid Row', NULL, 'strength', 'horizontal_pull', 'compound', 'pull', NULL, 'intermediate', NULL, NULL, NULL, 0),
('bodyweight-squat-hd', 'Bodyweight Squat HD', NULL, 'strength', 'squat', NULL, NULL, 'bilateral', NULL, NULL, '["Squat is a type of bodyweight exercise. It is one of the most popular exercises for strength and muscle growth. Squat is particularly effective for focusing on the muscles of the leg and hips. Squat are an easy exercise for beginners to do. It can help strengthen leg muscles, tighten hip muscles and burn calories to lose weight. It tightens the butt and legs. Squats are very effective for firming and strengthening your legs by acting on the gluteus,hip flexors, quadriceps, hamstrings and inner thigh muscles. Also, bodyweight squats can help shape your glutes and butt."]', 'wger', 0),
('bodyweight-walking-lunge', 'Bodyweight Walking Lunge', NULL, 'strength', 'lunge', 'compound', 'push', 'alternating', 'beginner', NULL, NULL, NULL, 0),
('bosu-burpee', 'Burpee – BOSU', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Start in a standing position with the BOSU ball on the ground (inflated-side down) in front of you.", "Grip the edges of the BOSU ball and jump your feet back into a plank position.", "Perform a push-up while gripping the BOSU ball.", "Jump your feet back towards the BOSU ball into a low squat position.", "Complete the squat by standing up. As you rise, lift the BOSU ball overhead, extending your arms towards the ceiling.", "Repeat the exercise for desired number of reps."]', 'longhaul-fitness', 0),
('bosu-cable-ball-crunch-side-bend', 'Bosu Ball Cable Crunch With Side Bends', NULL, 'strength', 'isolation_other', 'isolation', 'pull', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('bosu-mountain-climber', 'Mountain Climbers – BOSU', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Place a BOSU ball on the floor with the dome side facing down.", "Assume a push-up position with your hands gripped on the sides of the BOSU ball.", "Engage your core and keep your body in a straight line from head to toe.", "Start by bringing one knee towards your chest, then quickly switch and bring the other knee towards your chest.", "Continue alternating your knees in a running motion, keeping your hips low and your abs tight.", "Perform the exercise for the desired number of repetitions or time."]', 'longhaul-fitness', 0),
('bosu-plank', 'Plank - BOSU', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["Place a BOSU ball on the ground with the flat side facing up.", "Assume a plank position with your forearms on the BOSU ball and your toes on the ground.", "Engage your core and keep your body in a straight line from head to heels.", "Hold the position for the desired amount of time.", "Release the position by lowering your knees to the ground."]', 'longhaul-fitness', 1),
('bosu-squat', 'Squat – BOSU', NULL, 'strength', 'squat', NULL, NULL, 'bilateral', NULL, NULL, '["Place the BOSU ball on the ground with the flat side down.", "Stand on the BOSU ball with your feet shoulder-width apart for stability.", "Find your balance and engage your core muscles.", "Perform a squat by bending your knees and lowering your hips as if sitting back into a chair, keeping your back straight.", "Lower down as far as comfortable. Aim for your thighs to be parallel with the Bosu ball, but you may go lower for increased difficulty.", "Press through your heels to lift yourself back up to the starting position.", "Repeat the squat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('bottoms-up', 'Bottoms Up', NULL, 'strength', NULL, 'compound', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('box-jump', 'box jumps', 'Boxsprünge', 'cardio', NULL, NULL, NULL, NULL, NULL, NULL, '["Jump from a standing position onto the box, stretch your body, then step down again (do not jump)"]', 'wger', 0),
('box-jump-multiple-response', 'Box Jump (Multiple Response)', NULL, 'plyometrics', NULL, 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('box-skip', 'Box Skip', NULL, 'plyometrics', 'locomotion', 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('box-squat', 'Box squat', NULL, 'strength', 'squat', NULL, NULL, 'bilateral', NULL, NULL, '["Set up the box: Position the box behind you, about 3 feet from a squat rack if you''re using a barbell. Choose a height that allows you to squat down and gently tap your glutes on the box with your back straight.", "Stand with proper form: Stand with your feet shoulder-width apart, toes pointed slightly outward. Engage your core and keep your back neutral. If using a barbell, rack it at shoulder height.", "Lower down: Sit back as if going to sit on a chair, bending your knees and lowering your hips towards the box. Keep your core tight and back straight throughout the movement.", "Controlled descent: Descend in a controlled manner until your glutes gently touch the box. Don''t plop down.", "Pause and press up: Briefly pause at the bottom with your back straight and core engaged. Then, press through your heels to drive yourself back up to the starting position.", "Improvements in coordination, balance and endurance, toning of the leg and buttock muscles and an overall increase in bone density eliminating the risk of osteoporosis."]', 'wger', 0),
('box-step-up', 'Box Step-Up', NULL, 'strength', 'lunge', NULL, NULL, 'unilateral', NULL, NULL, '["Stand upright with a platform in front of you, feet hip-width apart. The height of the platform marks the difficult of the exercise.", "Place your right foot on the platform, ensuring your entire foot is on the surface.", "Press through your right foot to lift your body up onto the platform, bringing your left foot to meet your right foot.", "Stand tall on the platform with both feet flat and your core engaged.", "Step back down with your left foot, returning to the floor.", "Follow by stepping down with your right foot, coming back to the starting position.", "Repeat the exercise for the desired number of repetitions before switching to lead with the left foot."]', 'longhaul-fitness', 0),
('braced-squat', 'Braced Squat', NULL, 'strength', 'squat', NULL, NULL, 'bilateral', NULL, NULL, '["Stand with feet slightly wider than shoulder-width apart, while standing as tall as you can.", "Grab a weight plate and hold it out in front of your body with arms straight out. Keep your core tight and stand with a natural arch in your back.", "Now, push hips back and bend knees down into a squat as far as you can. Hold for a few moments and bring yourself back up to the starting position."]', 'wger', 0),
('bretzel-stretch', 'Bretzel stretch', NULL, 'stretching', NULL, NULL, NULL, NULL, NULL, NULL, '["How to Perform the Bretzel Stretch Starting Position: Lie on your back on a flat surface, such as a mat. Bend your knees and place your feet flat on the ground. Leg Positioning: Lift your right leg and cross it over your left leg, placing your right foot on the outside of your left knee. Your left leg should remain flat on the ground. Arm Positioning: Extend your left arm out to the side at shoulder height, keeping it straight. Use your right hand to gently pull your right knee towards the floor on the left side of your body. Stretching: As you pull your knee down, try to keep your left shoulder flat on the ground. You should feel a stretch in your hip, lower back, and possibly your chest. Hold the Position: Maintain this position for 20-30 seconds, breathing deeply and relaxing into the stretch. Switch sides and repeat the process."]', 'wger', 0),
('bulgarian-split-squat', 'Bulgarian Split Squat', NULL, 'strength', 'lunge', NULL, NULL, 'unilateral', NULL, NULL, '["Stand with your back facing a bench or step.", "Place the top of one foot on the bench or step behind you.", "Bend your front knee and lower your body down towards the ground, keeping your back straight.", "Pause when your front thigh is parallel to the ground.", "Push through your front heel to return to the starting position.", "Repeat for the desired number of repetitions, then switch legs."]', 'longhaul-fitness', 0),
('burpee', 'Burpees', 'Burpees', 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Start in a standing position with your feet shoulder-width apart.", "Lower your body into a squat position, placing your hands on the floor in front of you.", "Kick your feet back, landing in a plank position with your arms fully extended.", "Lower your chest and thighs to the floor, keeping your elbows close to your body.", "Push up to return to the plank position.", "Jump your feet back towards your hands, landing in a squat position.", "Jump up explosively, reaching your arms overhead.", "Land softly and immediately lower back into the squat position to begin the next repetition."]', 'longhaul-fitness', 1),
('bus-drivers', 'BUS DRIVERS', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Sitting with a Weight Plate, used as wheel, in both hands; raised slightly below eye level"]', 'wger', 0),
('butchers-block-stretch', 'Butchers Block Stretch', NULL, 'stretching', NULL, NULL, NULL, NULL, NULL, NULL, '["Kneel down with the hands together", "Rest the elbows on a bench in front of you and lower the chest down", "Keep the elbows bent with good posture and hold"]', 'wger', 0),
('butt-lift-bridge', 'Butt Lift (Bridge)', NULL, 'strength', 'isolation_other', 'isolation', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('butt-up', 'Butt-Ups', NULL, 'strength', NULL, 'compound', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('butterfly', 'Butterfly', 'Butterfly', 'strength', 'isolation_other', NULL, NULL, NULL, NULL, NULL, '["Sit on the butterfly machine, the feet have a good contact with the floor, the upper arms are parallel to the floor. Press your arms together till the handles are practically together (but aren''t!). Go slowly back. The weights should stay all the time in the air."]', 'wger', 0),
('butterfly-sit-up', 'Butterfly Sit Up', NULL, 'strength', 'isolation_other', NULL, NULL, 'bilateral', NULL, NULL, '["In this midrange exercise your arm muscles provide you with a little bit of momentum to help to get you off the ground. You also open them up in overhead position which engages the upper back. Start lying with feet flat on the ground, knees at an angle, arms crossed in towards your chest. Using your ab muscles, bring your upper body off the ground as you open your arms into goal post position, then slowly lower yourself back down to return to starting position."]', 'wger', 0),
('butterfly-superman', 'Butterfly Superman', NULL, 'strength', 'isolation_other', NULL, NULL, NULL, NULL, NULL, '["Lie on stomach, intertwine fingers behind the head and start raising your head and raise elbows as far as they go."]', 'wger', 0),
('cable-alternating-high-row', 'Alternating High Cable Row', NULL, 'strength', 'horizontal_pull', NULL, NULL, 'alternating', NULL, NULL, '["Start by putting the attachment in a high position on the cable station and step back about 1m from the attachment. Grab the cable pulley handle in your left hand at about head height with your elbow slightly bent. Step back with your left foot.", "Pull your elbow joint in toward the torso twisting slightly and perform a single-arm row. Engage the lats as you twist.", "Return to the starting position with cable pulley and left foot and grab the cable pulley handle in the right hand. Repeat this motion on the opposite side with your right foot stepped back."]', 'wger', 0),
('cable-bent-over-low-pulley-side-lateral', 'Bent Over Low-Pulley Side Lateral', NULL, 'strength', 'isolation_other', 'isolation', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('cable-biceps-curl', 'Biceps Curl With Cable', 'Bizeps am Kabel', 'strength', 'elbow_flexion', NULL, NULL, NULL, NULL, NULL, '["Stand facing a cable machine with your feet shoulder-width apart.", "Attach a straight bar to the low pulley of the cable machine.", "Grasp the bar with an underhand grip, hands shoulder-width apart.", "Keep your elbows close to your sides and your upper arms stationary throughout the exercise.", "Exhale and curl the bar up towards your shoulders, contracting your biceps.", "Pause for a moment at the top of the movement, squeezing your biceps.", "Inhale and slowly lower the bar back to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('cable-chest-press', 'Chest Press – Cable', NULL, 'strength', 'horizontal_push', 'compound', 'push', NULL, 'beginner', NULL, '["Adjust the cable machine to chest height and attach the handles to the cables.", "Stand facing away from the machine and grasp the handles with an overhand grip.", "Step forward to create tension in the cables and position your feet shoulder-width apart.", "Engage your core and keep your chest up as you push the handles forward until your arms are fully extended.", "Hold the position for a moment and then slowly release the handles back to the starting position.", "Repeat."]', 'longhaul-fitness', 1),
('cable-concentration-curl', 'Cable Concentration Curl', NULL, 'strength', 'elbow_flexion', NULL, NULL, NULL, NULL, NULL, '["The concentration curl is a classic exercise for building the biceps one arm at a time. It can be performed bent over or kneeling, but is more often performed seated on a bench. It''s great for emphasizing the biceps peak and is often used to finish a biceps workout"]', 'wger', 0),
('cable-cross-body-y-raise', 'Cross-Body Cable Y-Raise', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Attach a D-Bar to the cable machine. Perform a motion akin to drawing a sword from across your body."]', 'wger', 0),
('cable-cross-over', 'Cable Cross-over', 'Kabelcross', 'strength', 'isolation_other', 'isolation', 'push', NULL, 'beginner', NULL, '["Begin with cables at about shoulder height, one in each hand. Take a step forward so that one foot is in front of the other, for stability, and so that there is tension on the cables. Bring hands together in front of you. Try to make your hands overlap (so that the cables cross) a few inches."]', 'wger', 0),
('cable-crunch', 'Crunches With Cable', 'Crunches am Seil', 'strength', 'isolation_other', 'isolation', 'pull', 'bilateral', 'beginner', NULL, '["Attach a rope handle to a high pulley cable machine.", "Adjust the weight to a comfortable level.", "Kneel on a mat facing the machine and grab the rope handle with both hands.", "Position yourself so that your hands hold the rope by each ear and the cable is behind your neck, above you.", "Engage your core and pull the rope towards your knees.", "Hold the contraction for a few seconds and slowly release back to the starting position.", "Repeat."]', 'longhaul-fitness', 0),
('cable-deadlift', 'Cable Deadlifts', NULL, 'strength', 'hinge', 'compound', 'pull', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('cable-elevated-row', 'Elevated Cable Rows', NULL, 'strength', 'horizontal_pull', 'compound', 'pull', NULL, 'intermediate', NULL, NULL, NULL, 0),
('cable-external-rotation', 'Cable External Rotation', NULL, 'strength', 'rotation', 'isolation', 'pull', NULL, 'beginner', NULL, '["Steps:", "Start off placing an extension band around a post or in a secure position where it will not release and is at elbow level.", "Position yourself to the side of the band and with your hand that is opposite of the band, reach out and grab the handle.", "Bring the band to your chest keeping your elbow bent in a 90 degree angle then slowly rotate your arm in a backhand motion so that the band externally rotates out", "Continue out as far as possible so that you feel a stretch in your shoulders, hold for a count and then return back to the starting position.", "Repeat for as many reps and sets as desired."]', 'wger', 0),
('cable-face-pull', 'Face Pull', NULL, 'strength', 'horizontal_pull', 'compound', 'pull', 'bilateral', 'intermediate', NULL, NULL, NULL, 1),
('cable-fly', 'Fly With Cable', NULL, 'strength', 'isolation_other', 'isolation', 'push', NULL, 'intermediate', NULL, '["cable machine, two steps forward, straight back"]', 'wger', 0),
('cable-fly-lower-chest', 'Cable Fly Lower Chest', NULL, 'strength', 'isolation_other', NULL, NULL, NULL, NULL, NULL, '["Execution", "Start position:", "Arms extended out to your sides in a “Y” shape.", "Feel a stretch in your chest (slight bend in elbows — don’t lock them).", "Movement:", "Bring your hands downward and together in front of your lower chest or upper abs, in a smooth arc motion.", "Squeeze your chest hard at the bottom for 1–2 seconds.", "Return:", "Slowly raise your arms back up along the same path until you feel a good stretch in your chest.", "Maintain control — don’t let the weights pull you back too quickly."]', 'wger', 0),
('cable-fly-middle-chest', 'Cable Fly Middle Chest', NULL, 'strength', 'isolation_other', NULL, NULL, NULL, NULL, NULL, '["Execution", "Start position: Arms extended out to your sides (a big “T” shape), feeling a stretch in your chest.", "Movement: Bring your hands together in front of your chest in a wide hugging motion.", "Focus on squeezing your chest at the center.", "Do not lock your elbows or turn it into a press.", "Return: Slowly open your arms back to the start, maintaining tension on the chest."]', 'wger', 0),
('cable-fly-upper-chest', 'Cable Fly Upper Chest', NULL, 'strength', 'isolation_other', NULL, NULL, NULL, NULL, NULL, '["Execution", "Start position:", "Arms down and slightly behind your body, elbows slightly bent.", "Feel a light stretch across your chest.", "Movement:", "Bring your hands upward and together in front of your upper chest — roughly at chin to collarbone level.", "Use a smooth, controlled motion (avoid jerking).", "Squeeze your chest at the top for 1–2 seconds.", "Return:", "Slowly let your arms move back down and out to the sides, keeping control and tension."]', 'wger', 0),
('cable-front-raise', 'Front Raise (Cable)', NULL, 'strength', 'isolation_other', 'isolation', 'push', NULL, 'beginner', NULL, '["Raise the handle in a slight arc with controlled movement.", "Don’t swing your torso to start the rep."]', 'wger', 0),
('cable-front-raise-small-bar', 'Cable Front Raise with a small bar', NULL, 'strength', 'isolation_other', NULL, NULL, NULL, NULL, NULL, '["The Cable Front Raise with a small bar isolates your anterior deltoids (front shoulders) by providing constant tension, requiring you to stand facing away from a low pulley, grab the bar with an overhand grip, and lift it in front of you to shoulder height with slightly bent arms, avoiding swinging and keeping your core tight for controlled movement up and down. Use a light-to-moderate weight, focusing on slow, controlled reps to feel the muscle work, not momentum.", "How to Perform the Cable Front Raise (Bar)", "Setup: Attach a small straight bar to a low cable pulley. Set the weight to a light or moderate setting.", "Starting Position: Stand with your back to the machine, holding the bar with an overhand grip (palms facing down) at hip level, arms extended but not locked. Feet shoulder-width apart, core braced, shoulders back and down.", "The Lift: Exhale and slowly raise the bar straight up in front of you, keeping a slight bend in your elbows, until your hands reach shoulder height (or slightly below).", "The Hold: Pause briefly at the top, squeezing your front delts.", "The Lower: Inhale as you slowly and controllably lower the bar back to the starting position, maintaining tension."]', 'wger', 0),
('cable-full-range-motion-lat-pulldown', 'Full Range-Of-Motion Lat Pulldown', NULL, 'strength', 'vertical_pull', 'compound', 'pull', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('cable-hammer-curl-rope-attachment', 'Cable Hammer Curls - Rope Attachment', NULL, 'strength', 'elbow_flexion', 'isolation', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('cable-hammercurls', 'Hammercurls on Cable', 'Hammercurls am Seil', 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Take a cable in your hands (palms parallel, point to each other), the body is straight. Bend the arms and bring the weight up with a fast movement. Without any pause bring it back down with a slow, controlled movement, but don''t stretch completely your arms.", "Don''t swing your body during the exercise, the biceps should do all the work here. The elbows are at your side and don''t move."]', 'wger', 0),
('cable-high-cross-tricep-extention-nb', 'High-Cable Cross Tricep Extention - NB', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["The high-cable cross tricep extension is an isolation exercise for targeting the triceps, particularly the long head. It utilizes cables and handles grasped with opposite hands, allowing for a unique pressing motion that can be effective for building tricep strength. Unlike exercises that use a straight bar or rope, this variation can be more comfortable on your wrists and elbows"]', 'wger', 0),
('cable-high-curl', 'High Cable Curls', NULL, 'strength', 'elbow_flexion', 'compound', 'pull', NULL, 'intermediate', NULL, NULL, NULL, 0),
('cable-high-lateral-raise', 'High-Cable Lateral Raise', NULL, 'strength', 'isolation_other', NULL, NULL, NULL, NULL, NULL, '["Stand next to a cable machine with the pulley set to waist height.", "Grab the opposite-side handle with the hand farthest from the pulley, keeping your palm facing in.", "Keep your core engaged, chest lifted, and shoulders relaxed. Maintain a slight bend in the elbow throughout the lift.", "Lift your arm out to the side until your elbow reaches shoulder height, keeping your wrist aligned with your elbow.", "Briefly pause at the top, then slowly lower the handle back to your side with control. Repeat for the desired reps."]', 'wger', 0),
('cable-high-to-low-wood-chop', 'High to Low Wood Chop – Cable', NULL, 'strength', 'rotation', NULL, NULL, NULL, NULL, NULL, '["Attach a cable to a high pulley and select the desired weight.", "Stand perpendicular to the cable with feet shoulder-width apart and knees slightly bent.", "Grasp the handle with both hands and extend arms overhead, keeping them straight.", "Engage core muscles and rotate torso diagonally downwards, pulling the cable down towards the opposite hip.", "Bend knees and pivot back foot as needed to maintain balance and stability.", "Pause briefly at the bottom of the movement, then reverse the motion and return to starting position.", "Repeat for desired number of repetitions, then switch sides and repeat."]', 'longhaul-fitness', 0),
('cable-hip-adduction', 'Cable Hip Adduction', NULL, 'strength', 'isolation_other', 'isolation', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('cable-horizontal-wood-chop', 'Horizontal Wood Chop – Cable', NULL, 'strength', 'rotation', NULL, NULL, NULL, NULL, NULL, '["Set up the cable machine by adjusting the cable to just under chest height and attach a handle.", "Stand perpendicular to the cable machine with your feet shoulder-width apart, keeping your toes and head angled away from the machine.", "Grip the handle with both hands, extending your arms fully. Begin with your upper body twisted so that your arms and the handle are positioned on the side closest to the machine, while your head and toes continue to face away.", "Step away from the machine to create enough tension in the cable, ensuring it is taut before you start the exercise.", "Rotate your torso while keeping your arms straight, moving the handle in a horizontal motion across your body until your hands are aligned forward, matching the direction of your toes and head.", "Keep your core engaged throughout the movement to maintain stability and prevent any rotation in your hips or bending of the arms.", "Complete the twisting motion until your arms are fully extended in front of you, parallel to the direction your toes and head are facing.", "Slowly and with control, reverse the motion, returning to the twisted starting position while maintaining the alignment of your head and toes facing forward."]', 'longhaul-fitness', 0),
('cable-incline-pushdown', 'Cable Incline Pushdown', NULL, 'strength', 'elbow_extension', 'isolation', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('cable-internal-rotation', 'Cable Internal Rotation', NULL, 'strength', 'rotation', 'compound', 'pull', NULL, 'beginner', NULL, NULL, NULL, 1),
('cable-iron-cross', 'Cable Iron Cross', NULL, 'strength', 'isolation_other', 'isolation', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('cable-judo-flip', 'Cable Judo Flip', NULL, 'strength', NULL, 'compound', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('cable-kneeling-crunch-alternating-oblique-twist', 'Kneeling Cable Crunch With Alternating Oblique Twists', NULL, 'strength', 'rotation', 'isolation', 'pull', 'alternating', 'beginner', NULL, NULL, NULL, 0),
('cable-kneeling-high-pulley-row', 'Kneeling High Pulley Row', NULL, 'strength', 'horizontal_pull', 'compound', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('cable-kneeling-single-arm-high-pulley-row', 'Kneeling Single-Arm High Pulley Row', NULL, 'strength', 'horizontal_pull', 'compound', 'pull', 'unilateral', 'beginner', NULL, NULL, NULL, 0),
('cable-lateral-row-one-armed', 'Lateral Rows on Cable, One Armed', 'Seitheben am Kabel, Einarmig', 'strength', 'horizontal_pull', NULL, NULL, NULL, NULL, NULL, '["Set cable at waist height, start with arm across your belly and move han over and out too other side, one arm at the time."]', 'wger', 0),
('cable-low-chest-fly', 'Low Chest Fly – Cable', NULL, 'strength', 'isolation_other', NULL, NULL, NULL, NULL, NULL, '["Attach single handle grips to the low pulleys on both sides of a cable machine.", "Set the weight on the stack to an appropriate level.", "Grab the handles with your palms facing forwards, and slightly bend your elbows.", "Stand in the middle of the cable machine and take one step forward so you''re in a staggered stance.", "Lean slightly forward at your hips, keeping your back straight and core engaged.", "Start with your arms down towards the ground as low as the gripped cables allow. This is the starting position.", "Pull the handles together in a wide, upward arc until your hands meet in front of your chest.", "Squeeze your chest muscles and hold the contraction briefly.", "Slowly return your arms back to the starting position maintaining the slight bend in the elbows.", "Repeat the exercise for the desired number of repetitions."]', 'longhaul-fitness', 0),
('cable-low-cross-over-nb', 'Low-Cable Cross-Over - NB', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["The low-cable cross-over is an isolation movement that uses a cable stack to target the upper portion of the pectoral muscles. It is common in upper-body and chest-focused muscle-building workouts, often in combination with presses or flyes from other angles to target all portions of the chest."]', 'wger', 0),
('cable-low-crossover', 'Low Cable Crossover', NULL, 'strength', 'isolation_other', 'isolation', 'push', NULL, 'beginner', NULL, NULL, NULL, 1),
('cable-low-pulley-ffly', 'Low Pulley Cable fFly', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Adjust the cable machine: Set the pulley to the lowest setting possible. Choose your handles: You can use neutral grip handles (palms facing each other) or straight handles depending on your preference. Neutral grip might be easier on your wrists. Stand with proper form: Stand with your feet shoulder-width apart, knees slightly bent, and core engaged. Maintain a slight arch in your lower back throughout the exercise. Grip the handles: Grab the handles with your chosen grip and step back a small step or two until there''s slight tension on the cables. Initiate the movement: Keep your elbows slightly bent throughout the exercise. Imagine you''re giving someone a big hug. Squeeze your chest muscles as you bring your hands together in front of your chest. Control the movement: Focus on squeezing your chest muscles rather than using your arms to pull the handles. Peak contraction: Briefly hold the squeeze at the top of the movement with your hands together at chest level. Return slowly: Slowly release the tension and return the handles back down to the starting position with your arms slightly extended but not locked out."]', 'wger', 0),
('cable-low-pulley-fly', 'Low Pulley Cable Fly', NULL, 'strength', 'isolation_other', NULL, NULL, NULL, NULL, NULL, '["Adjust the cable machine: Set the pulley to the lowest setting possible. Choose your handles: You can use neutral grip handles (palms facing each other) or straight handles depending on your preference. Neutral grip might be easier on your wrists. Stand with proper form: Stand with your feet shoulder-width apart, knees slightly bent, and core engaged. Maintain a slight arch in your lower back throughout the exercise. Grip the handles: Grab the handles with your chosen grip and step back a small step or two until there''s slight tension on the cables. Initiate the movement: Keep your elbows slightly bent throughout the exercise. Imagine you''re giving someone a big hug. Squeeze your chest muscles as you bring your hands together in front of your chest. Control the movement: Focus on squeezing your chest muscles rather than using your arms to pull the handles. Peak contraction: Briefly hold the squeeze at the top of the movement with your hands together at chest level. Return slowly: Slowly release the tension and return the handles back down to the starting position with your arms slightly extended but not locked out."]', 'wger', 0),
('cable-low-pulley-row-to-neck', 'Low Pulley Row To Neck', NULL, 'strength', 'horizontal_pull', 'compound', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('cable-low-triceps-extension', 'Low Cable Triceps Extension', NULL, 'strength', 'elbow_extension', 'isolation', 'push', NULL, 'beginner', NULL, NULL, NULL, 1),
('cable-lying-close-grip-bar-curl-high-pulley', 'Lying Close-Grip Bar Curl On High Pulley', NULL, 'strength', 'elbow_flexion', 'isolation', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('cable-omni-cross-over', 'Omni Cable Cross-over', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["Adjust the weights based on the motion. When pulling from top to bottom, increase the weight by 20% to 40% more than the bottom-to-top motion. This accounts for the fact that when operating from top down, the upper chest muscles are naturally weaker than the lower chest muscles. So, adjust your weight stack to compensate.", "Position one cable at a high setting and the other at the lowest level setting. Get into a staggered stance in between the cable towers.", "For the cable set low, pull it upward and across your body. This effectively targets the upper chest.", "For the cable set high, draw it downward and across your body. This will primarily engage the lower chest.", "Once you’re done, swap the positions of the cables. Change the previously high cable to the lowest position and vice versa. Repeat the exercise sequence, ensuring you’re targeting both chest regions effectively."]', 'wger', 1),
('cable-one-arm-high-pulley-side-bend', 'One-Arm High-Pulley Cable Side Bends', NULL, 'strength', 'isolation_other', 'isolation', 'pull', 'unilateral', 'beginner', NULL, NULL, NULL, 0),
('cable-one-arm-overhead-tricep-extension', 'One Arm Overhead Cable Tricep Extension', NULL, 'strength', 'elbow_extension', NULL, NULL, 'unilateral', NULL, NULL, '["Set the pulley at the bottom of the cable machine and grab onto it without using any attachments. Extend the cable directly overhead.", "While keeping your back straight and upper arm stationary, lower the cable behind your head until you feel a good stretch in your triceps, and then extend it back upward until your elbow is locked out."]', 'wger', 1),
('cable-one-handed-bayesian-curl', 'One-Handed Bayesian Curl – Cable', NULL, 'strength', 'elbow_flexion', NULL, NULL, 'unilateral', NULL, NULL, '["Stand facing away from a cable machine with the pulley set to the lowest height.", "Select an appropriate weight on the machine for your fitness level.", "Grip the handle attached to the cable with one hand, your palm facing forward.", "Keep your feet shoulder-width apart, back straight, and shoulders back.", "Curl the handle towards your chest, focusing on contracting the biceps while keeping your elbow stationary and close to your body.", "Pause at the top of the curl to squeeze the bicep muscle intensely.", "Slowly lower the handle back to the starting position, controlling the movement throughout the descent.", "Repeat the movement for the desired number of repetitions before switching arms."]', 'longhaul-fitness', 0),
('cable-one-handed-high-row', 'One-Handed High-Cable Row', NULL, 'strength', 'horizontal_pull', NULL, NULL, 'unilateral', NULL, NULL, '["Adjust the cable machine pulley to a position above your head and attach a single handle.", "Stand facing the cable machine with your feet shoulder-width apart.", "Grab the handle with one hand, palm facing down.", "Step back slightly from the cable machine to create tension on the cable. Stretch your arm out in front of you. This is your starting position.", "Pull the handle towards your side, keeping your elbow close to your body. Rotate your palm to face your torso as you pull.", "Squeeze your back muscles when your hand is near your torso.", "Slowly extend your arm to return the handle to the starting position while controlling the weight.", "Repeat for the desired number of repetitions before switching arms."]', 'longhaul-fitness', 0),
('cable-one-legged-kickback', 'One-Legged Cable Kickback', NULL, 'strength', 'isolation_other', 'isolation', 'push', 'unilateral', 'intermediate', NULL, NULL, NULL, 0),
('cable-overhead-curl', 'Overhead Cable Curl', NULL, 'strength', 'elbow_flexion', 'isolation', 'pull', NULL, 'intermediate', NULL, NULL, NULL, 1),
('cable-overhead-tricep-extension', 'Overhead Cable Tricep Extension', NULL, 'strength', 'elbow_extension', NULL, NULL, NULL, NULL, NULL, '["Attach a rope to a cable machine at a low setting.", "Face the machine and grab the rope with an overhand grip.", "Step back to create tension in the cable and keep your feet shoulder-width apart.", "Keep your elbows close to your head and your upper arms stationary.", "Extend your forearms down until your arms are fully extended.", "Pause for a moment and then slowly return to the starting position.", "Repeat for desired number of repetitions."]', 'longhaul-fitness', 0),
('cable-pallof-press', 'Pallof Press', NULL, 'strength', 'anti_rotation', 'isolation', 'pull', NULL, 'beginner', NULL, NULL, NULL, 1),
('cable-pallof-press-rotation', 'Pallof Press With Rotation', NULL, 'strength', 'anti_rotation', 'compound', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('cable-preacher-curl', 'Cable Preacher Curl', NULL, 'strength', 'elbow_flexion', 'isolation', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('cable-press-around', 'Cable Press Around', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Set the cable pulley at chest height and attach a D-handle bar. Grab the handle with a neutral grip and hold it next to your chest with your elbow fully flexed and tight to your side. Turn away from the pulley so your torso is at 45 degrees.", "Hold the other side of the functional trainer with your corresponding hand. Assume a staggered stance for better balance.", "While keeping your chest proud, extend your elbow at 45 degrees across your midline while keeping your arm parallel to the floor. Stop shy of lockout and contract your chest at the top of the range of motion (ROM)."]', 'wger', 0),
('cable-pull-through', 'Cable pull through', NULL, 'strength', NULL, 'compound', 'pull', NULL, 'beginner', NULL, '["Attach a rope to a cable machine at floor-level position and stand facing away from the machine with your feet shoulder-width apart.", "Grab the rope with both hands and position it between your legs, just above your knees.", "Hinge forward at the hips and push your glutes back, keeping your back straight and chest up.", "Lower your torso until it is parallel to the floor, feeling a stretch in your hamstrings.", "Engage your glutes and hamstrings to drive your hips forward, standing up straight.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('cable-rear-delt-fly', 'Cable Rear Delt Fly', NULL, 'strength', 'isolation_other', 'isolation', 'pull', NULL, 'beginner', NULL, '["The reverse cable fly, also known as the cable rear delt fly, is a deltoid muscle strengthening and definition exercise. It’s one of the best isolation exercises for your back and posterior deltoid.This workout targets your posterior (back) deltoids while using a range of upper body muscles.", "Adjust the weight and the pulleys to the right height. You should be able to see the pulleys because they should be above your head.", "With your right hand, grab the left pulley, and with your left hand, grab the right pulley, crossing them in front of you. This is where you’ll begin your journey.", "Start the movement by moving your arms back and forth while keeping your arms straight.", "Pause at the finish of the move for a brief moment before returning the handles to their starting positions."]', 'wger', 0),
('cable-rear-delt-row', 'Rear Delt Row – Cable', NULL, 'strength', 'horizontal_pull', NULL, NULL, NULL, NULL, NULL, '["Attach a straight bar to a cable machine, preferably with a bench and foot rests.", "Sit facing the cable machine with your feet shoulder-width apart and your knees slightly bent.", "Grasp the bar with an overhand grip, with your hands slightly more than shoulder-width apart.", "Lean forward slightly, keeping your back straight and your core engaged.", "Pull the bar towards your upper chest, keeping your elbows wide and out to the sides.", "Squeeze your shoulder blades together at the top of the movement.", "Slowly release the bar back to the starting position.", "Repeat."]', 'longhaul-fitness', 0),
('cable-rope-crunch', 'Rope Crunch', NULL, 'strength', 'isolation_other', 'isolation', 'pull', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('cable-rope-overhead-triceps-extension', 'Cable Rope Overhead Triceps Extension', NULL, 'strength', 'elbow_extension', 'isolation', 'push', NULL, 'beginner', NULL, NULL, NULL, 1),
('cable-rope-rear-delt-row', 'Cable Rope Rear-Delt Rows', NULL, 'strength', 'horizontal_pull', 'compound', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('cable-rope-straight-arm-pulldown', 'Rope Straight-Arm Pulldown', NULL, 'strength', 'vertical_pull', 'isolation', 'pull', NULL, 'beginner', NULL, NULL, NULL, 1),
('cable-russian-twist', 'Cable Russian Twists', NULL, 'strength', 'rotation', 'compound', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('cable-seated-mid-trap-shrug', 'SEATED CABLE MID TRAP SHRUG', NULL, 'strength', 'isolation_other', NULL, NULL, 'bilateral', NULL, NULL, '["seated straight back, slight hold at top"]', 'wger', 0),
('cable-seated-one-arm-pulley-row', 'Seated One-arm Cable Pulley Rows', NULL, 'strength', 'horizontal_pull', 'compound', 'pull', 'unilateral', 'intermediate', NULL, NULL, NULL, 1),
('cable-seated-one-handed-row', 'Seated One-Handed Row – Cable', NULL, 'strength', 'horizontal_pull', NULL, NULL, 'unilateral', NULL, NULL, '["Sit facing a cable machine with your feet flat on the ground or footrests.", "Grasp the handle with one hand, palm facing inward.", "Use your feet to push your body back, creating tension on the cable, keeping your arm fully extended.", "Engage your core while leaning slightly forward.", "Pull the handle towards your torso, keeping your elbow close to your body.", "Squeeze your shoulder blades together while leaning slightly back.", "Pause for a moment at the top of the movement, feeling the contraction in your back muscles.", "Slowly extend your arm back to the starting position, maintaining control throughout the movement.", "Repeat for the desired number of repetitions, then switch to the other hand."]', 'longhaul-fitness', 0),
('cable-seated-row', 'Seated Cable Rows', NULL, 'strength', 'horizontal_pull', 'compound', 'pull', NULL, 'beginner', NULL, '["“Stay leaned forward - tuck elbows in on the negative”"]', 'wger', 0),
('cable-seated-two-arm-palms-up-low-pulley-wrist-curl', 'Seated Two-Arm Palms-Up Low-Pulley Wrist Curl', NULL, 'strength', 'isolation_other', 'isolation', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('cable-shotgun-row', 'Shotgun Row', NULL, 'strength', 'horizontal_pull', 'compound', 'pull', NULL, 'beginner', NULL, NULL, NULL, 1),
('cable-shoulder-external-rotation', 'Shoulder External Rotation (Cable)', NULL, 'strength', 'rotation', NULL, NULL, NULL, NULL, NULL, '["Stand side-on to a cable machine, with the machine arm set at the middle height. Attach a single handle.", "Grab the handle with the hand that''s furthest from the machine, ensuring that your elbow is bent at a 90-degree angle.", "Step away from the machine so that the weight is lifted slightly from its stack and there is tension on the cable.", "Position your elbow so that it is close to your side and holding weight across your abdomen.", "Slowly rotate your arm outward, pulling the handle away from the machine while keeping your elbow fixed at your side.", "Rotate the arm until the hand as far as possible without releasing tension on your back rotator cuff and without compromising form.", "Pause for a moment at the maximum rotation point.", "Slowly return the handle to the starting position in a controlled manner without allowing the weight to pull your arm back too fast.", "Repeat the exercise for the desired number of reps before switching sides to ensure both back rotator cuffs are worked evenly."]', 'longhaul-fitness', 0),
('cable-shoulder-internal-rotation', 'Shoulder Internal Rotation (Cable)', NULL, 'strength', 'rotation', NULL, NULL, NULL, NULL, NULL, '["Stand side-on to a cable machine, with the machine arm set at the middle height. Attach a single handle.", "Grab the handle with the hand that''s closest to the machine, ensuring that your elbow is bent at a 90-degree angle.", "Step away from the machine so that the weight is lifted slightly from its stack and there is tension on the cable.", "Position your elbow so that it is close to your side and your forearm points towards the machine as far as naturally possible.", "Slowly rotate your arm inward, pulling the handle away from the machine while keeping your elbow fixed at your side.", "Rotate the arm until the hand crosses your abdomen without releasing tension on your front rotator cuff and without compromising form.", "Pause for a moment at the maximum rotation point.", "Slowly return the handle to the starting position in a controlled manner without allowing the weight to pull your arm back too fast.", "Repeat the exercise for the desired number of reps before switching sides to ensure both front rotator cuffs are worked evenly."]', 'longhaul-fitness', 0),
('cable-shoulder-press', 'Cable Shoulder Press', NULL, 'strength', 'vertical_push', 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('cable-shrug-in', 'Cable Shrug-In', NULL, 'strength', 'isolation_other', 'isolation', 'pull', 'bilateral', 'beginner', NULL, '["Attach two D-Handles to two low cables and shrug in using your upper traps."]', 'wger', 0),
('cable-side-lateral-raise', 'Side Lateral Raise (Cable)', NULL, 'strength', 'isolation_other', NULL, NULL, NULL, NULL, NULL, '["Lift with your elbows leading, not your hands.", "Don’t shrug your shoulders; keep traps quiet."]', 'wger', 1),
('cable-side-lateral-raise-back', 'Side lateral raise - Back (Cable)', NULL, 'strength', 'isolation_other', NULL, NULL, NULL, NULL, NULL, '["on a cable rack do a side lateral raise with the cable behind you. focus on tension in the front of the shoulder."]', 'wger', 0),
('cable-side-straight-arm-pulldown', 'Side Straight-Arm Pulldown (Cable)', NULL, 'strength', 'vertical_pull', NULL, NULL, NULL, NULL, NULL, '["Keep your torso still, pulling the handle down along your side using the outer lat.", "Don’t twist your body or rotate your torso to cheat the rep."]', 'wger', 0),
('cable-single-arm-half-kneeling-high-row', 'Single Arm Half Kneeling High Row – Cable', NULL, 'strength', 'horizontal_pull', NULL, NULL, 'unilateral', NULL, NULL, '["Position a cable machine at the top setting and attach a single handle.", "Assume a half-kneeling position with your right knee on the ground and left foot forward.", "Grasp the handle with your right hand while keeping the arm extended.", "Engage your core and keep your torso upright.", "Pull the handle down and backwards by engaging your lat, keeping the elbow close to your body.", "Pull until your hand reaches chest level, then pause briefly.", "Slowly extend your arm back to the start position, controlling the movement.", "Complete the desired number of repetitions and switch to the other side."]', 'longhaul-fitness', 0),
('cable-skull-crusher-rope', 'Skull Crusher – Cable with Rope', NULL, 'strength', 'elbow_extension', NULL, NULL, NULL, NULL, NULL, '["Begin by setting a flat bench in front of a cable machine with a low pulley.", "Lie down on the bench with your head closest to the cable machine.", "Grab the rope with an overhand grip, arms fully extended above your forehead. This is your starting position.", "Ensure your elbows are shoulder-width apart and remain in a fixed position throughout the exercise.", "Engage your core as you slowly lower the rope towards your forehead by bending your elbows.", "Pause briefly once the rope is close to your forehead.", "Press back to the starting position by extending your elbows and contracting your triceps.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('cable-standing-leg-curl', 'Standing Cable Leg Curl', NULL, 'strength', 'isolation_other', NULL, NULL, NULL, NULL, NULL, '["Stand facing a cable machine with your feet hip-width apart.", "Attach an ankle cuff to your right ankle.", "Hold onto the machine for support and balance.", "Bend your right knee and bring your heel towards your glutes, keeping your upper leg stationary.", "Squeeze your hamstring at the top of the movement.", "Slowly lower your leg back to the starting position.", "Repeat for the desired number of repetitions.", "Switch sides and perform the exercise with your left leg."]', 'longhaul-fitness', 1),
('cable-standing-lift', 'Standing Cable Lift', NULL, 'strength', NULL, 'compound', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('cable-standing-low-pulley-deltoid-raise', 'Standing Low-Pulley Deltoid Raise', NULL, 'strength', 'isolation_other', 'isolation', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('cable-standing-low-pulley-one-arm-triceps-extension', 'Standing Low-Pulley One-Arm Triceps Extension', NULL, 'strength', 'elbow_extension', 'isolation', 'push', 'unilateral', 'intermediate', NULL, NULL, NULL, 0),
('cable-standing-wood-chop', 'Standing Cable Wood Chop', NULL, 'strength', 'rotation', 'compound', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('cable-straight-arm-pulldown', 'Straight-Arm Pulldown (Cable)', NULL, 'strength', 'vertical_pull', 'isolation', 'pull', NULL, 'beginner', NULL, '["Keep arms straight but not locked, pulling with your lats, not your shoulders.", "Don’t let your shoulders shrug up during the movement."]', 'wger', 0);
INSERT INTO exercises (id, name_en, name_de, category, movement_pattern, mechanic, force, laterality, level, variation_of, instructions, instructions_source_id, needs_review) VALUES
('cable-straight-bar-curl', 'Straight Bar Cable Curls', NULL, 'strength', 'elbow_flexion', NULL, NULL, NULL, NULL, NULL, '["Standing upright in front of Cable Tower using a straight bar"]', 'wger', 0),
('cable-straight-bar-front-raise', 'Straight Bar Cable Front Raise', NULL, 'strength', 'isolation_other', NULL, NULL, 'bilateral', NULL, NULL, '["Back to cable tower, cable between legs, SZ Bar"]', 'wger', 1),
('cable-tri-extension-external-rotation', 'Cable Tri Extension - External Rotation', NULL, 'strength', 'rotation', NULL, NULL, NULL, NULL, NULL, '["single arm exercise with cable held at opposite shoulder with elbow bent. Turn away from the cable, and the straighten the elbow across the body."]', 'wger', 0),
('cable-tri-extension-internal-rotation', 'Cable Tri Extension - Internal Rotation', NULL, 'strength', 'rotation', NULL, NULL, NULL, NULL, NULL, '["single arm exercise with cable held at opposite shoulder with elbow bent. Turn towards the cable, and the straighten the elbow across the body."]', 'wger', 0),
('cable-tricep-kickback', 'Cable Tricep Kickback', NULL, 'strength', 'elbow_extension', NULL, NULL, NULL, NULL, NULL, '["Grab onto the handle, and pull your elbow up and back slightly above your torso. Keep your upper arm to be parallel to the ground for the duration of the set"]', 'wger', 0),
('cable-tricep-pushdown', 'Tricep Pushdown on Cable', NULL, 'strength', 'elbow_extension', 'isolation', 'push', NULL, 'beginner', NULL, '["Stand facing a cable machine with your feet shoulder-width apart and your knees slightly bent.", "Attach a rope handle to the high pulley of the cable machine.", "Grasp the rope with an overhand grip, palms facing each other.", "Keep your elbows close to your sides and your upper arms stationary throughout the exercise.", "Pull the rope towards the ground until your forearms are about parallel to the ground. This is your starting position.", "Exhale and push the rope down until your arms are fully extended, while keeping your upper arms stationary.", "Hold the contracted position for a brief pause, squeezing your triceps.", "Inhale and slowly allow the rope to return to the starting position, while maintaining tension in your triceps.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('cable-triceps-extension', 'Triceps Extensions on Cable', 'Trizeps Seildrücken', 'strength', 'elbow_extension', NULL, NULL, NULL, NULL, NULL, '["Grab the cable, stand with your feet shoulder wide, keep your back straight and lean forward a little. Push the bar down, making sure the elbows don''t move during the exercise. Rotate your hands outwards at the very end and go back to the initial position without pause."]', 'wger', 0),
('cable-triceps-extension-bar', 'Triceps Extensions on Cable With Bar', 'Trizeps Seildrücken Mit Stange', 'strength', 'elbow_extension', NULL, NULL, NULL, NULL, NULL, '["Grab the bar, stand with your feet shoulder wide, keep your back straight and lean forward a little. Push the bar down, making sure the elbows don''t move during the exercise. Without pause go back to the initial position."]', 'wger', 0),
('cable-triceps-press', 'Cable Triceps Press', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["A single arm exercise that starts with the hand close to the chest with with the elbows bent, and the elbow flared out. Press forward and down against the cable straightening the elbow."]', 'wger', 0),
('cable-triceps-pushdown-rope-attachment', 'Triceps Pushdown - Rope Attachment', NULL, 'strength', 'elbow_extension', 'isolation', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('cable-triceps-pushdown-v-bar-attachment', 'Triceps Pushdown - V-Bar Attachment', NULL, 'strength', 'elbow_extension', 'isolation', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('cable-trunk-rotation', 'Trunk Rotation With Cable', NULL, 'strength', 'rotation', NULL, NULL, NULL, NULL, NULL, '["Seated trunk rotation with cable"]', 'wger', 0),
('cable-twist', 'Twist – Cable', NULL, 'strength', 'rotation', NULL, NULL, NULL, NULL, NULL, '["Stand with your left foot in front of your right, knees slightly bent, facing away from the cable machine.", "Rotate and reach to your right, behind you, and grab the cable handle with both hands. Your left arm should be straight across your body and behind you.", "Rotate your torso left until you''re facing forward, pulling the cable across your body.", "Pause briefly at the end of the movement, then slowly rotate back to the starting position.", "Repeat for the desired number of reps and then switch sides."]', 'longhaul-fitness', 0),
('cable-underhand-pulldowns', 'Underhand Cable Pulldowns', NULL, 'strength', 'vertical_pull', 'compound', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('cable-unilateral-cross-body-pull-down', 'unilateral cross body cable pull down', NULL, 'strength', 'vertical_pull', NULL, NULL, 'unilateral', NULL, NULL, '["on a cable rack place cable high, and with a straight arm pull that cable across you from high to low. focus on tension in back shoulder."]', 'wger', 0),
('cable-unilateral-row', 'Unilateral Cable row', NULL, 'strength', 'horizontal_pull', NULL, NULL, 'unilateral', NULL, NULL, '["Put a vertical seated bench in front of the cable row machine.position it so that you can focus on one side, and then do slow pulls focusing on the lateral muscles and ensuring tention in those muscles when in a stretched position."]', 'wger', 0),
('cable-upright-downward-internal-rotation', 'Upright Downward Internal Rotation – Cable', NULL, 'strength', 'rotation', NULL, NULL, NULL, NULL, NULL, '["Adjust the pulley on a cable machine to eye-level and attach a handle to it.", "Stand facing away from the machine, feet shoulder-width apart.", "Grab the handle with one hand, raising your arm so your upper arm is parallel to the ground and your forearm is pointing straight up, creating a 90-degree angle at your elbow.", "Brace your core and begin to rotate your hand forward at your shoulder, keeping your upper arm stable and parallel to the ground throughout the movement.", "Continue the rotation until your forearm is parallel to the ground, completing the internal rotation.", "Complete the desired number of repetitions before switching arms to perform the exercise on the opposite side."]', 'longhaul-fitness', 0),
('cable-upright-row', 'Upright Cable Row', NULL, 'strength', 'horizontal_pull', 'compound', 'pull', NULL, 'intermediate', NULL, NULL, NULL, 0),
('cable-upright-upward-external-rotation', 'Upright Upward External Rotation – Cable', NULL, 'strength', 'rotation', NULL, NULL, NULL, NULL, NULL, '["Adjust the pulley on a cable machine to sternum-level and attach a handle to it.", "Stand facing the machine, feet shoulder-width apart.", "Grab the handle with one hand, palm facing down, keeping your upper arm parallel to the ground and your forearm pointing towards the pulley, also parallel to the ground. This is your starting position.", "Begin to rotate your arm at the shoulder, moving your hand upward and backwards, keeping the upper arm stable and parallel to the ground throughout the movement.", "Continue the rotation until your forearm is pointing straight up, perpendicular to the ground, maintaining a 90-degree angle at your elbow.", "Lower the handle back down to the starting position in a controlled manner.", "Complete the desired number of repetitions before switching arms to perform the exercise on the opposite side."]', 'longhaul-fitness', 0),
('cable-v-bar-pulldown', 'V-Bar Pulldown', NULL, 'strength', 'vertical_pull', 'compound', 'pull', NULL, 'intermediate', NULL, NULL, NULL, 0),
('cable-wide-grip-lat-pulldown', 'Wide-Grip Lat Pulldown', NULL, 'strength', 'vertical_pull', 'compound', 'pull', 'bilateral', 'beginner', NULL, NULL, NULL, 1),
('cable-wide-grip-pulldown-behind-neck', 'Wide-Grip Pulldown Behind The Neck', NULL, 'strength', 'vertical_pull', 'compound', 'pull', NULL, 'intermediate', NULL, NULL, NULL, 0),
('cable-wide-grip-seated-row', 'Wide Grip Seated Row – Cable', NULL, 'strength', 'horizontal_pull', NULL, NULL, NULL, NULL, NULL, '["Adjust the cable machine to a low setting and attach a wide grip handle to the cable.", "Sit on the seat with your feet flat on the floor and your knees slightly bent.", "Grab the handle with an overhand grip, hands wider than shoulder-width apart.", "Keep your back straight and lean slightly forward from the hips.", "Pull the handle towards your lower chest, squeezing your shoulder blades together.", "Pause for a moment, then slowly extend your arms back to the starting position.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('cable-woodchoppers', 'Cable Woodchoppers', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Set cable pulley slightly lower than chest height. Keep body facing forward with hips stable. Grab the pulley handle, fully extend your arms and bring your arms forward and across your body. Hold for 1 second at the end of the movement and slowly return to starting position."]', 'wger', 0),
('cable-wrist-curl', 'Wrist curl, cable', NULL, 'strength', 'isolation_other', 'isolation', 'pull', NULL, 'beginner', NULL, '["Extend your arm down, then slightly lift your forearm", "Extend your wrist in a supinated form (palm up)", "Adjust cable height so that the cable handle is in your supinated hand", "Perform the movement by curling your palms and wrists upwards", "(optional/variable) Pause at the top", "Slowly return to the starting position"]', 'wger', 0),
('calf-raise-left-leg', 'Calf raises, left leg', NULL, 'strength', 'isolation_other', NULL, NULL, NULL, NULL, NULL, '["Stand on the floor or on the edge of a step to increase the range of movement.", "Raise one foot.", "Lift your heel until you''re standing on your toes.", "(variable) Stay in this position for three seconds", "Slowly lower your foot until you almost touch the ground with your heel - don''t slam your foot!"]', 'wger', 0),
('calf-raise-one-legged', 'Calf raises, one legged', 'Wadenheben, Einbenig', 'strength', 'isolation_other', NULL, NULL, 'unilateral', NULL, NULL, NULL, NULL, 0),
('calf-stretch-elbows-against-wall', 'Calf Stretch Elbows Against Wall', NULL, 'stretching', NULL, 'isolation', 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('calf-stretch-hands-against-wall', 'Calf Stretch Hands Against Wall', NULL, 'stretching', NULL, 'isolation', 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('car-deadlift', 'Car Deadlift', NULL, 'strongman', 'hinge', 'compound', 'pull', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('carioca-quick-step', 'Carioca Quick Step', NULL, 'plyometrics', NULL, NULL, NULL, NULL, 'beginner', NULL, NULL, NULL, 0),
('cat-plank', 'Cat Plank', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["On your fours and raise the knees of the floor ever so slightly. Curl your back out and push back from your shoulders as to resemble a cat making itself look large."]', 'wger', 0),
('cat-stretch', 'Cat Stretch', NULL, 'stretching', NULL, NULL, 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('chain-handle-extension', 'Chain Handle Extension', NULL, 'strength', 'isolation_other', 'isolation', 'push', NULL, 'intermediate', NULL, NULL, NULL, 0),
('chain-press', 'Chain Press', NULL, 'strength', NULL, 'compound', 'push', NULL, 'intermediate', NULL, NULL, NULL, 0),
('chair-leg-extended-stretch', 'Chair Leg Extended Stretch', NULL, 'stretching', NULL, 'isolation', 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('chair-lower-back-stretch', 'Chair Lower Back Stretch', NULL, 'stretching', NULL, 'isolation', 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('chair-upper-body-stretch', 'Chair Upper Body Stretch', NULL, 'stretching', NULL, NULL, 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('chest-and-front-shoulder-stretch', 'Chest And Front Of Shoulder Stretch', NULL, 'stretching', NULL, 'isolation', 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('chest-press', 'Chest Press', 'Brustpresse', 'strength', 'horizontal_push', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0),
('childs-pose', 'Child''s Pose', NULL, 'stretching', NULL, NULL, 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('chin-to-chest-stretch', 'Chin To Chest Stretch', NULL, 'stretching', NULL, NULL, 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('chin-up', 'Chin Up', 'Chin-ups', 'strength', 'vertical_pull', 'compound', 'pull', 'bilateral', 'beginner', NULL, '["The chin-up (also known as a chin or chinup) is a strength training exercise. People frequently do this exercise with the intention of strengthening muscles such as the latissimus dorsi and biceps, which extend the shoulder and flex the elbow, respectively. In this maneuver, the palms are faced towards the body. It is a form of pull-up in which the range of motion is established in relation to a person''s chin."]', 'wger', 0),
('chin-up-2', 'Chin-Up', NULL, 'strength', 'vertical_pull', NULL, NULL, 'bilateral', NULL, NULL, '["Stand underneath a chin-up bar with your feet shoulder-width apart.", "Reach up and grasp the bar with an underhand grip, with your palms facing towards you and your hands shoulder-width apart.", "Hang from the bar with your arms fully extended and your shoulders relaxed.", "Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.", "Continue pulling until your chin is above the bar.", "Pause briefly at the top of the movement, then slowly lower yourself back down to the starting position.", "Repeat."]', 'longhaul-fitness', 1),
('circus-bell', 'Circus Bell', NULL, 'strongman', NULL, 'compound', 'push', NULL, 'advanced', NULL, NULL, NULL, 0),
('clamshell', 'Clamshell', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Position Side plank with the elbow and the forearm on the ground and the legs slightly bent.", "Execution Lift your upper knee while keeping your feet close together, like a “shell opening,” then slowly return to the starting position. Keep your core stable and your hips aligned."]', 'wger', 0),
('clap-push-up', 'Clap Push-UP', NULL, 'strength', 'horizontal_push', NULL, NULL, 'bilateral', NULL, NULL, '["The clap push-up is an explosive upper body movement that builds power and fast-twitch muscle strength. It adds a plyometric challenge to the traditional push-up by requiring the hands to leave the ground mid-rep.", "Start in a strong push-up position with your hands slightly wider than shoulder-width and core engaged", "Lower your body explosively and push off the ground with enough force to lift your hands.", "Quickly clap your hands together at chest level before returning them to the floor.", "Land with soft elbows to absorb the impact and immediately move into the next rep"]', 'wger', 0),
('claps-over-head', 'Claps over the head', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Stand with your feet shoulder width apart. Raise your arms and clap over your head"]', 'wger', 0),
('clean', 'Clean', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Start with feet hip-width apart and hands gripping the barbell just outside the legs.", "Lower into a squat position, keeping the back straight and the chest up.", "Explosively extend the hips, knees, and ankles, driving the barbell upwards.", "As the barbell reaches chest level, quickly drop underneath it in a squat position, rotating the elbows forward.", "Catch the barbell on the front of the shoulders, with the elbows pointing forward and the chest up.", "Stand up by extending the hips and knees, keeping the barbell close to the body.", "Lower the barbell back to the starting position by reversing the movement."]', 'longhaul-fitness', 1),
('clean-and-jerk', 'Clean and Jerk', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Start with the barbell on the ground, feet shoulder-width apart and toes pointing forward.", "Bend down and grip the bar with hands slightly wider than shoulder-width apart.", "Stand up, keeping your back straight and the bar close to your body.", "Once the bar reaches your hips, explosively extend your hips, knees, and ankles to propel the bar upward.", "As the bar reaches your chest, drop your body underneath it and catch it on your shoulders in a front squat position.", "Stand up from the front squat position and prepare for the jerk.", "Dip your body slightly and then explosively drive the bar overhead by extending your arms and legs.", "Lock out your arms and hold the bar overhead for a moment before lowering it back down to the starting position.", "Repeat."]', 'longhaul-fitness', 0),
('climbmill', 'ClimbMill', NULL, 'cardio', NULL, NULL, NULL, NULL, NULL, NULL, '["The ClimbMill, also known as a stair climber, is a cardio-focused machine that simulates climbing stairs. It provides an effective way to improve endurance while strengthening the lower body. To use the machine, step onto the moving stairs, maintain an upright posture, and use the handrails for balance if needed. Adjust the speed and intensity to match your fitness level. This exercise helps improve cardiovascular health, burns calories, and enhances lower body muscle endurance."]', 'wger', 0),
('clock-push-up', 'Clock Push-Up', NULL, 'strength', 'horizontal_push', 'compound', 'push', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('close-grip-bench-press', 'Close-Grip Bench Press', NULL, 'strength', 'horizontal_push', NULL, NULL, NULL, NULL, NULL, '["Set up the bench press station with the appropriate weight on the barbell.", "Lie down on the bench with your feet flat on the ground and your back pressed against the bench.", "Grasp the barbell with your hands shoulder-width apart or just slightly narrower.", "Unrack the barbell and hold it directly above your chest, arms fully extended.", "Lower the barbell towards your chest by bending your elbows, keeping them close to your body.", "Pause briefly with the barbell barely above your chest.", "Push the barbell back up to the starting position by extending your arms, keeping your elbows close to your body.", "Repeat the movement for the desired number of repetitions."]', 'longhaul-fitness', 1),
('cobra-stretch', 'Cobra Stretch', NULL, 'stretching', NULL, NULL, NULL, NULL, NULL, NULL, '["The Cobra Stretch is a back extension exercise that helps improve spinal flexibility and relieve lower back tension. To perform, lie face down on the floor with your hands placed under your shoulders. Press your palms into the floor and lift your chest while keeping your hips on the ground. Keep your elbows slightly bent and your shoulders relaxed. Hold the stretch for a few seconds, then slowly lower yourself back down. This exercise is beneficial for improving posture and reducing lower back stiffness."]', 'wger', 0),
('cocoons', 'Cocoons', NULL, 'strength', NULL, 'compound', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('commando-pull-up', 'commando pull-ups', NULL, 'strength', 'vertical_pull', NULL, NULL, 'bilateral', NULL, NULL, '["variation of the pull-up exercise, it is performed with a grip of one hand supine and one hand prone, do not twist the torso to get back to the front, the head passes once to one side, once to the other."]', 'wger', 0),
('conans-wheel', 'Conan''s Wheel', NULL, 'strongman', NULL, 'compound', NULL, NULL, 'intermediate', NULL, NULL, NULL, 0),
('concentration-curl', 'Concentration Curl', NULL, 'strength', 'elbow_flexion', NULL, NULL, NULL, NULL, NULL, '["Start by sitting on a bench with your feet flat on the floor and your knees slightly bent.", "Hold a dumbbell in one hand and place your elbow on the inside of your thigh, just above the knee.", "Extend your arm fully, allowing the dumbbell to hang down towards the floor.", "Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder while contracting your biceps.", "Pause for a moment at the top of the movement, squeezing your biceps.", "Inhale and slowly lower the dumbbell back to the starting position, fully extending your arm.", "Repeat for the desired number of repetitions and then switch arms."]', 'longhaul-fitness', 1),
('copenhagen-adduction-exercise', 'Copenhagen Adduction Exercise', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Lie on your side with the elbow placed directly under the shoulder, similar to a side plank position. Place the upper leg on a bench with the inside of the foot or ankle resting on it. Lift your hips and hold your body in a straight line while keeping the lower leg off the floor. The exercise strongly activates the adductors of the upper leg while also challenging the core and hip stabilizers."]', 'wger', 0),
('copenhagen-plank-leg-lift', 'Copenhagen Plank with Leg Lift', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["Begin by positioning yourself on your side, propped up on your forearm and elbow directly beneath your shoulder.", "Extend your legs straight out with your top foot resting on a bench or elevated surface.", "Align your body in a straight line from head to heels, engaging your core and glutes.", "Lift your lower leg up and down without rotating your hips or losing alignment.", "Maintain a strong core throughout the movement to keep your hips elevated and stable.", "Repeat for desired number of reps, then switch to the other side."]', 'longhaul-fitness', 0),
('core-rotation', 'Core Rotation', NULL, 'strength', 'rotation', NULL, NULL, NULL, NULL, NULL, '["Sit back, raise feet above the ground with knees bent and start rotating left and right with hands touching the ground every move."]', 'wger', 0),
('cossack-squat', 'Cossack squat', NULL, 'strength', 'squat', NULL, NULL, 'bilateral', NULL, NULL, '["The Cossack Squat is a multi-joint exercise that works mainly on the legs and buttocks, but also involves stabilizing muscles. It is an excellent exercise for improving strength, mobility and stability in a functional way."]', 'wger', 0),
('cross-body-crunch', 'Cross-Body Crunch', NULL, 'strength', NULL, 'compound', 'pull', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('crossbody-hamstring-stretch', 'Crossbody Hamstring Stretch', NULL, 'stretching', NULL, NULL, NULL, NULL, NULL, NULL, '["While standing, cross one leg behind the other (keep this leg straight). Reach downward and try to touch the toes of that leg. Slightly bend the other leg so that you can bend down."]', 'wger', 0),
('crossbody-leg-swing', 'Crossbody Leg Swings', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Hold onto a wall or something near you for support. Swing one leg across the front of your body, then back and out to the side. Repeat while slowly increasing your range of motion."]', 'wger', 0),
('crossover-reverse-lunge', 'Crossover Reverse Lunge', NULL, 'stretching', NULL, NULL, 'pull', NULL, 'intermediate', NULL, NULL, NULL, 0),
('crucifix', 'Crucifix', NULL, 'strongman', NULL, 'isolation', 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('crunch', 'Crunches', 'Crunches', 'strength', 'isolation_other', 'isolation', 'pull', 'bilateral', 'beginner', NULL, '["Lay down on your back a soft surface, the feet are on the floor. Ask a partner or use some other help (barbell, etc.) to keep them fixed, your hands are behind your head. From this position move your upper body up till your head or elbows touch your knees. Do this movement by rolling up your back."]', 'wger', 0),
('crunch-2', 'Crunch', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["Start by lying flat on your back with your knees bent and feet flat on the ground.", "Place your hands behind your head, with your elbows pointing outwards.", "Engage your core muscles by pulling your belly button towards your spine.", "Lift your head, neck, and shoulders off the ground, while keeping your lower back pressed into the floor.", "Hold the contraction for a moment, then slowly lower yourself back down to the starting position.", "Repeat."]', 'longhaul-fitness', 1),
('crunch-hands-overhead', 'Crunch - Hands Overhead', NULL, 'strength', 'isolation_other', 'isolation', 'pull', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('crunch-hd', 'Crunches HD', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["Crunch movement is one of the most basic exercises designed to strengthen the core muscles of the body. Exercise helps to strengthen core muscles, improve posture, and increase muscle mobility and flexibility. Improves six pack muscles: When crunch exercise is done, the rectus abdominus and oblique muscles are tightened, so the upper abdominal muscles and six pack muscles develop. Increases the strength of the abdominal muscles: The primary role of your abdominal muscles is to stabilize your mid-section. It supports you while lifting heavy objects, allowing you to twist and rotate your body. These are all day long actions that you do not notice, so it is important that your abdominal muscles can sustain long hours of work. Crunch exercise helps build this important endurance in the abdominal muscles. Muscular endurance is the ability of these fibers to resist resistance for a long time."]', 'wger', 0),
('crunch-legs-up', 'Crunches With Legs Up', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["On your back, legs extended straight up, reach toward your toes with your hands and lift your shoulder blades off the ground and back."]', 'wger', 0),
('cycling', 'Cycling', 'Fahrrad fahren', 'cardio', 'locomotion', NULL, NULL, NULL, NULL, NULL, '["Cycling, also called bicycling or biking, is the use of bicycles for transport, recreation, exercise or sport. People engaged in cycling are referred to as cyclists, bicyclists, or bikers. Apart from two-wheeled bicycles, cycling also includes the riding of unicycles, tricycles, quadracycles, recumbent and similar human-powered vehicles."]', 'wger', 0),
('dancers-stretch', 'Dancer''s Stretch', NULL, 'stretching', NULL, NULL, 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('dead-bug', 'Dead Bug', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Start by lying on your back with your arms extended towards the ceiling.", "Bend your knees and lift your legs up so that your knees are directly above your hips and your shins are parallel to the floor.", "Engage your core muscles by lowering your right arm and left leg towards the floor, keeping them hovering just above the ground. Both your right arm and left leg straighten as they approach the floor.", "Return your arm and leg to the starting position and repeat on the opposite side.", "Continue alternating sides for the desired number of repetitions or time."]', 'longhaul-fitness', 0),
('dead-bug-2', 'Dead Bug', NULL, 'strength', NULL, 'compound', 'pull', NULL, 'beginner', NULL, NULL, NULL, 1),
('decline-bench-leg-raise', 'Decline Bench Leg Raise', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Setup: Lie on a decline bench with your head at the top and grip the handles.", "The Start: Extend legs fully, keeping them slightly elevated to engage your core.", "The Lift: Raise your legs toward the ceiling using your abs, not momentum.", "The Squeeze: Pause and contract your lower abdominals at the top.", "The Return: Lower your legs slowly to the starting position with control."]', 'wger', 0),
('deficit-deadlift', 'Deficit Deadlift', NULL, 'strength', 'hinge', NULL, NULL, 'bilateral', NULL, NULL, '["Stand with your feet roughly hip-width apart on a step or plate that raises your body 2-4 inches (5-10 cm) off the ground.", "Position a loaded barbell over the middle of your feet.", "Bend at your hips and knees to reach down and grasp the barbell with both hands, slightly wider than shoulder-width apart, palms facing towards your body.", "With a flat back, engage your core, flatten your shoulder blades and look ahead to keep your neck in a neutral position.", "Stand up with the weight by pushing through your heels, keeping the bar close to your body, and driving your hips forward.", "Straighten your legs and hips to come to a full standing position, with the barbell hanging in front of your thighs. Do not lean back at the top.", "Pause briefly at the top of the lift while maintaining a tight core, and take a breath if needed.", "Lower the barbell back to the ground by hinging at the hips and bending the knees, keeping the bar close to your body and your back straight.", "Place the barbell back on the ground and return to the starting position, ready to perform the next repetition."]', 'longhaul-fitness', 0),
('delt-stretch', 'Delt Stretch', NULL, 'stretching', NULL, NULL, NULL, NULL, NULL, NULL, '["Stretch your deltoids for a certain period of time."]', 'wger', 0),
('depth-jump-leap', 'Depth Jump Leap', NULL, 'plyometrics', NULL, 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('diamond-push-up', 'Diamond push ups', 'Liegestüzten Diamond', 'strength', 'horizontal_push', NULL, NULL, 'bilateral', NULL, NULL, NULL, NULL, 0),
('dip', 'Dips', 'Dips', 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["A dip is an upper-body strength exercise. Narrow, shoulder-width dips primarily train the triceps, with major synergists being the anterior deltoid, the pectoralis muscles (sternal, clavicular, and minor), and the rhomboid muscles of the back (in that order).[1] Wide arm training places additional emphasis on the pectoral muscles, similar in respect to the way a wide grip bench press would focus more on the pectorals and less on the triceps."]', 'wger', 0),
('dip-bench', 'Dip – Bench', NULL, 'strength', NULL, 'compound', 'push', 'bilateral', 'beginner', NULL, '["Find a stable bench or chair and sit on the edge with your hands next to your hips, fingers pointing forward.", "Slide your feet forward and lower your hips off the bench. Straighten or bend your knees to make the exercise more or less difficult.", "Lower your body by bending your elbows until your upper arms are parallel to the ground.", "Push yourself back up to the starting position by straightening your arms.", "Repeat."]', 'longhaul-fitness', 0),
('dip-between-two-benches', 'Dips Between Two Benches', 'Dips Zwischen 2 Bänke', 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["Put two benches so far appart, that you can hold onto one with your hands and are just able to reach the other with your feet. The legs stay during the exercise completely stretched. With your elbows facing back, bend them as much as you can. Push yourself up, but don''t stretch out the arms."]', 'wger', 0),
('dip-chest-version', 'Dips - Chest Version', NULL, 'strength', NULL, 'compound', 'push', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('dip-triceps-version', 'Dips - Triceps Version', NULL, 'strength', NULL, 'compound', 'push', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('donkey-calf-raise', 'Donkey Calf Raises', NULL, 'strength', 'isolation_other', 'isolation', 'push', NULL, 'intermediate', NULL, NULL, NULL, 0),
('doorway-pectoral-stretch', 'Doorway Pectoral Stretch', NULL, 'stretching', NULL, NULL, NULL, NULL, NULL, NULL, '["Place the forearm vertically on a door frame or stationary object at head height", "Step forward past the arm, keeping it still against the object to stretch the chest"]', 'wger', 0),
('double-leg-abdominal-press', 'Double-Leg Abdominal Press', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Lie on your back with knees and hips bent at 90 degrees (tabletop).", "Place your hands on your thighs just above your knees. Push your hands against your knees as hard as possible while using your abs to pull your knees toward your hands.", "Hold for 10 seconds of maximum effort. Your abs should be shaking."]', 'wger', 0),
('double-leg-butt-kick', 'Double Leg Butt Kick', NULL, 'plyometrics', NULL, 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('double-leg-calf-raise', 'Double Leg Calf Raise', NULL, 'strength', 'isolation_other', NULL, NULL, NULL, NULL, NULL, '["The double leg heel raise is important to strengthen and create control and stability around the ankle and knee, and provide balance and control for the hip and pelvis."]', 'wger', 0),
('dragon-flag', 'Dragon-flag', 'Dragon Flag', 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Keep your body completely rigid throughout the movement, avoiding sagging in your lower back. Use a firm grip to stabilize your upper body. Start with simpler versions (such as with bent knees) to build strength and control."]', 'wger', 0),
('dragon-squat', 'Dragon squat', NULL, 'strength', 'squat', NULL, NULL, 'bilateral', NULL, NULL, '["Start standing with your feet hip-width apart. Cross your right foot behind you to the left corner and back of the room while bending both knees. Return and repeat, alternating sides. Keep your hips and shoulders forward as you cross your feet and bend your knees."]', 'wger', 0),
('drop-push', 'Drop Push', NULL, 'plyometrics', NULL, 'compound', 'push', NULL, 'intermediate', NULL, NULL, NULL, 0),
('dumbbell-alternating-deltoid-raise', 'Alternating Deltoid Raise', NULL, 'strength', 'isolation_other', 'isolation', 'push', 'alternating', 'beginner', NULL, NULL, NULL, 0),
('dumbbell-alternating-tall-kneeling-arnold-press-hand-weights', 'Alternating Tall Kneeling Arnold Press – Hand Weights', NULL, 'strength', 'vertical_push', NULL, NULL, 'alternating', NULL, NULL, '["Choose a pair of appropriate weights: dumbbells, kettlebells, etc.", "Kneel on the ground with both knees, keeping your back straight and core engaged.", "Hold the dumbbells in front of you at shoulder height, elbows bent, and palms facing your face. This is your starting position.", "Rotate one arm outward, so your palm faces forward, and press the dumbbell overhead.", "Bring the dumbbell back to the starting position while simultaneously rotating the other arm and pressing the dumbbell overhead.", "Continue alternating arms, pressing one dumbbell overhead at a time.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('dumbbell-alternative-gorilla-row', 'Alternative DB Gorilla rows', NULL, 'strength', 'horizontal_pull', NULL, NULL, NULL, NULL, NULL, '["Slightly bent down and knees to mimic a gorilla position and pull/row up the DBs to the chest. DB stay straight (thumbs pointing up)"]', 'wger', 0),
('dumbbell-arnold-press', 'Arnold Dumbbell Press', NULL, 'strength', 'vertical_push', 'compound', 'push', NULL, 'intermediate', NULL, NULL, NULL, 1),
('dumbbell-around-worlds', 'Around The Worlds', NULL, 'strength', NULL, 'compound', 'push', NULL, 'intermediate', NULL, NULL, NULL, 0),
('dumbbell-bear-crawl-pull-through', 'Bear crawl pull through', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Place a dumbbell at around hip level and assume a bear crawl position. Push the knees off the floor and hold.", "With the opposite hand reach for the dumbbell and pull it to the other side. Place your hand back on the floor and repeat with your other hand."]', 'wger', 0),
('dumbbell-bench-press', 'Benchpress Dumbbells', 'Bankdrücken KH', 'strength', 'horizontal_push', 'compound', 'push', NULL, 'beginner', NULL, '["Lie flat on a bench with your feet firmly planted on the ground.", "Hold a dumbbell in each hand, palms facing forward, and extend your arms straight up over your chest.", "Lower the dumbbells slowly towards your chest, keeping your elbows wide.", "Pause for a moment when the dumbbells are just above your chest.", "Push the dumbbells back up to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('dumbbell-bent-arm-pullover', 'Bent-Arm Dumbbell Pullover', NULL, 'strength', NULL, 'compound', 'push', NULL, 'intermediate', NULL, NULL, NULL, 0),
('dumbbell-bent-high-pull', 'Bent High Pulls', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Bend over slightly while holding two dumbbells. Pull the dumbbells up to your chest, keeping your elbows as high as you can."]', 'wger', 0),
('dumbbell-bent-over-face-pull', 'Dumbbell Bent Over Face Pull', NULL, 'strength', 'horizontal_pull', NULL, NULL, 'bilateral', NULL, NULL, '["This exercise involves using dumbbells to perform a bent over face pull, which targets the upper back and shoulders. The movement involves pulling the weights towards the face while keeping the elbows high and squeezing the shoulder blades together."]', 'wger', 0),
('dumbbell-bent-over-rear-delt-raise-head-bench', 'Bent Over Dumbbell Rear Delt Raise With Head On Bench', NULL, 'strength', 'isolation_other', 'isolation', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('dumbbell-bent-over-two-row', 'Bent Over Two-Dumbbell Row', NULL, 'strength', 'horizontal_pull', 'compound', 'pull', NULL, 'beginner', NULL, NULL, NULL, 1),
('dumbbell-bent-over-two-row-palms-in', 'Bent Over Two-Dumbbell Row With Palms In', NULL, 'strength', 'horizontal_pull', 'compound', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('dumbbell-bicep-curl-to-press', 'Dumbbell bicep curl to press', NULL, 'strength', 'elbow_flexion', NULL, NULL, NULL, NULL, NULL, '["Bend your elbows and lift the dumbbells to your shoulders. Push the dumbbells over your head while rotating your arms to make your palms face forward. Reverse it to lower down. Repeat the exercise."]', 'wger', 0),
('dumbbell-biceps-curl', 'Biceps Curls With Dumbbell', 'Bizeps KH-Curls', 'strength', 'elbow_flexion', 'isolation', 'pull', NULL, 'beginner', NULL, '["Stand up straight with your feet shoulder-width apart and your arms at your sides, holding a dumbbell in each hand.", "Keeping your elbows close to your sides, slowly lift the dumbbells up towards your shoulders, rotating your palms to face your shoulders as you lift.", "Pause for a moment at the top of the movement, squeezing your biceps.", "Slowly lower the dumbbells back down to the starting position, rotating your palms back to face your thighs as you lower.", "Repeat."]', 'longhaul-fitness', 0),
('dumbbell-bizeps-curl-trifecta', 'Bizeps Curls Trifecta', NULL, 'strength', 'elbow_flexion', NULL, NULL, NULL, NULL, NULL, '["This exercise is a mixture of three different curls: the Supinated Cross Body Curl, the Pronated Cross Body Curl and the No Money Curl. You alternate between three curl variations that each accomplish different goals, and you’ll keep the set going beyond the usual 8-12 rep range which gives us that intensity.", "For the Supinated Cross Body Curl, supinate the forearm with palms facing toward the ceiling and forearms coming across the body. Lift the inner-facing weight of the dumbbell towards your shoulder.", "For the Pronated Cross Body Curl, pronate the forearm with palms facing toward the floor (pronated grip or overhand grip) and forearms coming across the body. Lift the inner-facing weight of the dumbbell towards your shoulder.", "For the No Money Curl, you’ll curl the dumbbell as you outwardly rotate the shoulder. Lift the inner-facing weight of the dumbbell towards your outer side of the shoulder."]', 'wger', 0),
('dumbbell-bradford-press', 'Dumbbell Bradford press', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["From a front hold of the DBs in a OHP, press above the head, bring back towards the rear of the shoulders, down, and press back forward."]', 'wger', 0),
('dumbbell-bulgarian-squat', 'Bulgarian Squat with Dumbbells', NULL, 'strength', 'lunge', NULL, NULL, 'unilateral', NULL, NULL, '["The Bulgarian split squat consists of performing a squat on one leg with the rear foot resting on a raised platform. Elevating your back leg on a bench creates instability and increases the range of motion of the exercise."]', 'wger', 0),
('dumbbell-calf-raise', 'Calf Raise On A Dumbbell', NULL, 'strength', 'isolation_other', 'isolation', 'push', NULL, 'intermediate', NULL, NULL, NULL, 0),
('dumbbell-cheat-curl', 'Dumbbell Cheat Curl', NULL, 'strength', 'elbow_flexion', NULL, NULL, NULL, NULL, NULL, '["Starting position is standing with feet shoulder width apart.", "Hands should take an underhand or supinated grip on the dumbbells holding them with hands shoulder width apart.", "Keeping elbows tucked into your sides throughout the entire movement, use momentum to curl the dumbbells, squeezing your biceps at the top of the movement.", "Slowly lower to return to the starting position. Keep the core tight throughout the exercise.", "Cheating through the concentric curling portion of this challenging exercise gives us a great opportunity to increase time under tension and create eccentric overload with heavier weight when we lower."]', 'wger', 0),
('dumbbell-chest-press', 'Dumbbell Chest Press', NULL, 'strength', 'horizontal_push', NULL, NULL, NULL, NULL, NULL, '["The dumbbell chest press is a pressing exercise similar to the barbell bench press, except that it is performed with dumbbells."]', 'wger', 1),
('dumbbell-chest-supported-rear-delt-raise', 'Chest-Supported Rear Delt Raise', NULL, 'strength', 'isolation_other', NULL, NULL, NULL, NULL, NULL, '["\"The Y\"Position: Set an incline bench to 30-45 degrees. Lie face-down with your chest supported, keeping your head neutral or looking slightly down to avoid neck strain.Grip: Hold light dumbbells with a neutral or thumbs-up grip (thumb pointing to the ceiling).Movement: With straight or slightly bent elbows, raise the dumbbells up and out in a \"Y\" shape. Focus on moving the shoulders and shoulder blades rather than just lifting the arms.Top Position: Squeeze the shoulder blades together and reach high, ensuring the arms are angled to form a \"Y\".Control: Lower the dumbbells slowly to the starting position."]', 'wger', 0),
('dumbbell-clean', 'Dumbbell Clean', NULL, 'strength', NULL, 'compound', 'pull', NULL, 'intermediate', NULL, NULL, NULL, 1),
('dumbbell-close-grip-press', 'Close-Grip Dumbbell Press', NULL, 'strength', NULL, 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('dumbbell-close-grip-push-up-off', 'Close-Grip Push-Up off of a Dumbbell', NULL, 'strength', 'horizontal_push', 'compound', 'push', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('dumbbell-concentration-curl', 'Dumbbell Concentration Curl', 'Konzentrations-Curls', 'strength', 'elbow_flexion', 'isolation', 'pull', NULL, 'beginner', NULL, '["Sit on bench. Grasp dumbbell between feet. Place back of upper arm to inner thigh. Lean into leg to raise elbow slightly."]', 'wger', 0),
('dumbbell-cross-bench-pullover', 'Cross-Bench Dumbbell Pullovers', 'Pull-Over KH', 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Grasp a moderately weighted dumbbell so your palms are flat against the underside of the top plates and your thumbs are around the bar. Lie on your back across a flat bench so only your upper back and shoulders are in contact with the bench. Your feet should be set about shoulder-width apart and your head should hang slightly downward. With the dumbbell supported at arm''s length directly about your chest, bend your arms about 15 degrees and keep them bent throughout the movement. Slowly lower the dumbbell backward and downward in a semicircle arc to as low a position as is comfortably possible. Raise it slowly back along the same arc to the starting point, and repeat for the required number of repetitions."]', 'wger', 0),
('dumbbell-cross-body-hammer-curl', 'DB Cross Body Hammer Curls', NULL, 'strength', 'elbow_flexion', 'isolation', 'pull', NULL, 'beginner', NULL, '["Dumbbell cross body biceps curls, works on the braccialis"]', 'wger', 0),
('dumbbell-crunch', 'Dumbbell Crunches', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["Dumbbell crunches are a weighted variation of traditional crunches designed to target the abdominal muscles more intensely. Lie flat on your back with your knees bent and feet flat on the floor. Hold a dumbbell with both hands close to your chest or above your head. Lift your shoulders and upper back off the ground in a crunching motion, engaging your core. Slowly lower yourself back to the starting position. Ensure controlled movements throughout the exercise to prevent strain."]', 'wger', 0),
('dumbbell-crush-grip-curl', 'Crush Grip Curl – Dumbbell', NULL, 'strength', 'elbow_flexion', NULL, NULL, NULL, NULL, NULL, '["Select a single dumbbell and grip it with both hands, one on each end, pressing your palms against the sides of the dumbbell.", "Position yourself straight-armed on a preacher curl bench, ensuring that your elbows and upper arms are comfortably resting against the bench pad. This is your starting position.", "Keep pressing your hands together firmly to maintain a ''crush grip'' on the dumbbell throughout the exercise.", "While maintaining the grip, exhale and curl the dumbbell upwards towards your shoulders, focusing on contracting the biceps.", "Hold the contraction briefly at the top of the movement, then inhale and slowly lower the dumbbell back to the starting position.", "Repeat the curl for the desired number of repetitions, ensuring the crush grip is maintained throughout each curl."]', 'longhaul-fitness', 0),
('dumbbell-cuban-press', 'Cuban Press', NULL, 'strength', NULL, 'compound', 'push', NULL, 'intermediate', NULL, NULL, NULL, 0),
('dumbbell-curl-de-biceps-con-agarre-prono', 'Curl de biceps con agarre prono', NULL, 'strength', 'elbow_flexion', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0),
('dumbbell-curl-shoulder-elevated', 'Curl - With Shoulder Elevated', NULL, 'strength', 'elbow_flexion', NULL, NULL, NULL, NULL, NULL, '["Place elbow so that it is about level with the shoulder. Curl the wieght to your shoulder. Focus on the stretch in the eccentric part of the curl"]', 'wger', 0),
('dumbbell-deadlift', 'Dumbbell Deadlift', NULL, 'strength', 'hinge', NULL, NULL, 'bilateral', NULL, NULL, '["Stand with your feet shoulder-width apart, with a dumbbell in each hand.", "Hold the dumbbells about halfway between the front and side of your quads, with your palms facing your body.", "Bend your knees, hinge and lean forward at the hips, keeping your back straight and your chest up.", "Lower the dumbbells towards the ground, keeping them close to your body.", "Pause when your dumbbells are just below your knees.", "Push through your heels and stand up, keeping your back straight and your chest up.", "Repeat."]', 'longhaul-fitness', 0),
('dumbbell-devils-press', 'Devil’s Press', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["The Devil’s Press is a hybrid movement combining a dumbbell burpee and a double dumbbell snatch. It’s a full-body, high-intensity exercise that develops strength, power, and metabolic conditioning.", "Start with a dumbbell in each hand and perform a burpee, letting your chest touch the ground while holding the dumbbells.", "Explosively jump your feet forward and swing the dumbbells between your legs.", "Drive the dumbbells overhead in one continuous motion, locking out your arms.", "Lower the dumbbells with control to return to the starting position and repeat"]', 'wger', 0),
('dumbbell-drag-curl', 'Dumbbell drag curls', NULL, 'strength', 'elbow_flexion', NULL, NULL, NULL, NULL, NULL, '["Hold a dumbbell in each hand with your palms facing forward. Pull your elbows back and lift the dumbbells to your chest height. Slowly lower the dumbbell and repeat the exercise."]', 'wger', 0),
('dumbbell-drop-curl', 'Drop Curl', NULL, 'strength', 'elbow_flexion', NULL, NULL, NULL, NULL, NULL, '["Drop curls in a modified position at a slow pace effectively engage the brachialis for arm width. Starting position is with both arms in a slight angle towards each other at chest height with a dumbbell in each hand. Lower one dumbbell close to full extended arm position slowly and in a controlled manner during the first half of the curl, then curl it back up to starting position, while the other dumbbell stays at its starting position. Now lower the other dumbbell down. This keeps tension on the brachialis. As we pass the 90deg mark on our way down, the biceps will take over the work."]', 'wger', 0),
('dumbbell-elbows-tucked-bench-press', 'Elbows Tucked DB Bench Press', NULL, 'strength', 'horizontal_push', NULL, NULL, NULL, NULL, NULL, '["Elbows Tucked DB Bench Press, chest press movement focusing on the triceps. DB stays parallel with body"]', 'wger', 0),
('dumbbell-external-rotation', 'External Rotation', NULL, 'strength', 'rotation', 'isolation', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('dumbbell-flexor-incline-curl', 'Flexor Incline Dumbbell Curls', NULL, 'strength', 'elbow_flexion', 'isolation', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('dumbbell-floor-bench-press', 'Floor dumbbell bench press', NULL, 'strength', 'horizontal_push', NULL, NULL, NULL, NULL, NULL, '["This exercise involves lying on your back with a dumbbell in each hand, and pressing them up towards the ceiling, targeting the chest muscles. The dumbbells are then lowered back down to the starting position on the floor."]', 'wger', 0),
('dumbbell-floor-press', 'Dumbbell Floor Press', NULL, 'strength', 'horizontal_push', 'compound', 'push', NULL, 'intermediate', NULL, '["Lie flat on your back on the floor with your knees bent and feet flat on the ground.", "Hold a dumbbell in each hand with your palms facing towards your feet.", "Extend your arms straight up towards the ceiling, with your elbows slightly bent.", "Slowly lower the dumbbells down towards your chest, keeping your elbows close to your body.", "Pause when your upper arms touch the ground.", "Repeat."]', 'longhaul-fitness', 0),
('dumbbell-fly', 'Fly With Dumbbells', 'Fliegende KH Flachbank', 'strength', 'isolation_other', 'isolation', 'push', NULL, 'beginner', NULL, '["Start by lying flat on a bench with your feet firmly on the ground and your head, shoulders, and buttocks touching the bench.", "Hold a dumbbell in each hand with your palms facing each other and your arms extended above your chest.", "Slowly lower the dumbbells out to the sides of your body, keeping your elbows slightly bent and your palms facing up.", "Lower the dumbbells until your arms are parallel to the ground or until you feel a stretch in your chest muscles.", "Pause for a moment, then slowly bring the dumbbells back up to the starting position, keeping your elbows slightly bent and your palms facing each other.", "Repeat."]', 'longhaul-fitness', 0),
('dumbbell-forearm-twist', 'Forearm Twist – Dumbbell', NULL, 'strength', 'rotation', NULL, NULL, NULL, NULL, NULL, '["Stand up straight with your feet shoulder-width apart.", "Hold a dumbbell in each hand and let your arms hang down in front of your quads, palms facing forward, with a slight bend in the elbows.", "Curl the dumbbells upwards by bending your elbows, stopping when your forearms are parallel to the ground. This is the starting position.", "While keeping your upper arms stationary, rotate your wrists to flip the dumbbells towards each other until your palms face down.", "Pause for a moment, then rotate your wrists in the opposite direction, turning the dumbbells back to the starting position.", "Repeat the desired number of repetitions."]', 'longhaul-fitness', 0),
('dumbbell-frog-press', 'Dumbbell Frog Press', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Similar to hip thrust, but with feet put up together, lifting the butt off the ground in a frog like position."]', 'wger', 0),
('dumbbell-front-rack-knee-over-toe-split-squat', 'Front Rack Knee Over Toe Split Squat – Dumbbell', NULL, 'strength', 'lunge', NULL, NULL, 'unilateral', NULL, NULL, '["Select an appropriate pair of dumbbells and hold one in each hand.", "Clean the dumbbells to the front rack position, resting one end of each dumbbell on your shoulders with your elbows pointed forward and your palms facing each other.", "Position your feet in a split stance with one leg forward and the other leg behind you.", "Align your front knee with your second to fourth toes, ensuring your knee travels over your toes throughout the movement.", "Engage your core to maintain an upright torso and stabilize your position. This is your starting position.", "Lower your body by bending both knees, ensuring the front knee tracks over the toes and the back knee approaches the ground.", "Descend until the back knee is just above the ground and the front thigh is parallel to the floor.", "Press through the heel of your front foot to return to the starting position.", "Repeat the movement for the desired number of repetitions and then switch legs."]', 'longhaul-fitness', 0),
('dumbbell-front-raise', 'Front Raise – Dumbbell', NULL, 'strength', 'isolation_other', 'isolation', 'push', NULL, 'beginner', NULL, '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand with your palms facing your thighs.", "Keeping your arms straight, lift the dumbbells in front of you until they reach shoulder height.", "Hold the position for a second, then slowly lower the dumbbells back down to your thighs.", "Repeat."]', 'longhaul-fitness', 0),
('dumbbell-front-two-raise', 'Front Two-Dumbbell Raise', NULL, 'strength', 'isolation_other', 'isolation', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('dumbbell-glute-bridge-single-arm-press', 'Glute Bridge Single-Arm Press', NULL, 'strength', 'hinge', NULL, NULL, 'unilateral', NULL, NULL, '["With one dumbbell in hand, perform a glute bridge. Now hold the dumbbell above your chest, this is the rep starting position. Lower the dumbbell so that your elbow touches the floor or is roughly 45 degrees below your shoulder if using a bench. Push the dumbbell back into the starting position."]', 'wger', 0),
('dumbbell-goblet-squat', 'Dumbbell Goblet Squat', NULL, 'strength', 'squat', NULL, NULL, 'bilateral', NULL, NULL, '["Grasp dumbbell with both hands at the sides of the upper plates. Hold dumbbell in front of chest, close to torso. Place feet about shoulderwide apart, keep knees slightly bent.", "Squat down until thighs are parallel to floor. Keep back straight, bend and move hips backward to keep knees above feet. Return, keep knees slightly flexed. Repeat.", "Keep bodyweight on heels and look ahead or slightly above to keep back straight."]', 'wger', 0),
('dumbbell-hammer-grip-incline-bench-press', 'Hammer Grip Incline DB Bench Press', NULL, 'strength', 'horizontal_push', 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('dumbbell-helms-row', 'Helms Row', NULL, 'strength', 'horizontal_pull', NULL, NULL, NULL, NULL, NULL, '["Setup: Place your chest on the end of a bench, using a towel or anything soft to keep your chest protected. You want your chest to be in contact with the bench around the nipple line. Your back should be almost parallel to the floor Execution: When you’re starting the exercise, focus on pulling your elbows back until you feel maximum tightness in the lats. If you want to get some trap activation with the exercise, relax your shoulder blades when the weights are hanging down and then retract them as you start the rep."]', 'wger', 0),
('dumbbell-hip-thrust', 'Dumbbell Hip Thrust', NULL, 'strength', 'hinge', NULL, NULL, 'bilateral', NULL, NULL, '["Dumbbell hip thrust Begin seated on the ground with a bench placed horizontally behind you and your knees bent. Lay a dumbbell across your hips, holding either end with both hands. You may wish to place a pad or towel on your hips to increase comfort. With knees bent and feet firmly planted on the floor, lean back onto the bench so that it is gently pressing into your upper back. This is your starting position. Inhale. Exhale. Holding onto the dumbbell, press your heels into the mat and raise your hips off the floor until your body forms one straight line from chin to knee, resting your shoulders on the bench and ensuring that your head is an extension of your spine. Inhale. Lower your hips to return to the starting position but without resting your glutes on the mat. Repeat for the specified number of repetitions."]', 'wger', 0),
('dumbbell-horizontal-external-shoulder-rotation', 'Horizontal External Shoulder Rotation – Dumbbell', NULL, 'strength', 'rotation', NULL, NULL, NULL, NULL, NULL, '["Stand perpendicular to a bar set at a height just below shoulder level when standing.", "Grip a dumbbell with your working hand, maintaining the 90-degree angle at the elbow.", "Place the upper arm of your working side on the bar so that it is parallel to the ground and your elbow is bent at a 90-degree angle. Your forearm with dumbbell should be hanging vertically towards the floor.", "Brace your core and keep your shoulder blades down and back to prevent them from rolling forward during the exercise.", "Rotate your arm at the shoulder, lifting the dumbbell upwards while keeping your upper arm and elbow firmly in place on the bar.", "Continue the rotation until your forearm is horizontal to the floor or as far as your shoulder flexibility allows without discomfort or compromising form.", "Pause at the top of the movement, focusing on contracting the muscles around the shoulder.", "Slowly reverse the motion, lowering the dumbbell back to the starting position with control to complete one repetition.", "Perform the desired number of reps, then switch sides and repeat the exercise with the other arm."]', 'longhaul-fitness', 0),
('dumbbell-horizontal-internal-shoulder-rotation', 'Horizontal Internal Shoulder Rotation – Dumbbell', NULL, 'strength', 'rotation', NULL, NULL, NULL, NULL, NULL, '["Lie on your back on a flat surface with a dumbbell nearby.", "Raise one arm at the shoulder joint to your side so that your upper arm is perpendicular to your body. Bend your elbow at a 90-degree angle bringing your forearm perpendicular to the upper arm so that your hand is above your head on your supporting surface. This position is commonly known as as a single-arm \"cactus pose\".", "Hold a dumbbell in your hand with your palm facing up towards the ceiling.", "Slowly rotate your arm up towards the ceiling until it''s perpendicular to the ground, keeping your elbow bent and your upper arm stationary.", "Pause for a moment at the top of the movement, then slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch sides and repeat the exercise with your other arm."]', 'longhaul-fitness', 0),
('dumbbell-incline-bench-palms-facing-in', 'Incline Dumbbell Bench With Palms Facing In', NULL, 'strength', NULL, 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('dumbbell-incline-chest-supported-row', 'Incline Chest-Supported Dumbbell Row', NULL, 'strength', 'horizontal_pull', NULL, NULL, NULL, NULL, NULL, '["Set up an adjustable bench at a 45-degree angle. Lay on your stomach with your head hanging just above the edge of the bench. Grab a dumbbell in each hand and set up with a good posture – core and lats engaged and shoulders neutral. Row the dumbbells toward the top of the stomach and squeeze the back at the top of the rep. Finally, lower the dumbbells back to the starting position and repeat until all reps are completed."]', 'wger', 0),
('dumbbell-incline-flyes-twist', 'Incline Dumbbell Flyes - With A Twist', NULL, 'strength', 'rotation', 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('dumbbell-incline-hex-press', 'Incline Hex Press – Dumbbell', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Select two dumbbells of suitable weight and an incline bench set to a 30-degree angle.", "Sit on the bench with a dumbbell in each hand, resting them on your thighs.", "Kick the weights to shoulder height as you lean back, positioning the dumbbells at chest level with your palms facing each other.", "Press the dumbbells up over your chest by extending your arms while actively pushing the dumbbells against one another the entire time.", "Pause briefly at the top of the movement, squeezing your chest muscles.", "Lower the weights slowly back to the starting position, maintaining control and keeping the dumbbells close together."]', 'longhaul-fitness', 1),
('dumbbell-incline-inner-biceps-curl', 'Incline Inner Biceps Curl', NULL, 'strength', 'elbow_flexion', 'isolation', NULL, NULL, 'beginner', NULL, NULL, NULL, 0),
('dumbbell-incline-shoulder-raise', 'Dumbbell Incline Shoulder Raise', NULL, 'strength', 'isolation_other', 'isolation', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('dumbbell-incline-static-hold', 'Incline Static Hold', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Execution", "Hold Position:", "Lower the dumbbells a few inches above your chest — about the midpoint of a normal incline press.", "This is where your upper chest is under maximum tension.", "Static Hold:", "Hold the position for 20–45 seconds while keeping the chest tight.", "Breathe slowly but stay tense — do not relax your chest or shoulders.", "End the set:", "After the hold, carefully bring the dumbbells down and rest."]', 'wger', 0),
('dumbbell-incline-y-raise', 'Incline DB Y-Raise', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Set an incline bench to a 45-degree angle and sit facing the bench, chest against the pad, with a dumbbell in each hand, palms facing each other.", "Position your feet firmly on the ground for stability and let your arms hang down naturally with a slight bend in your elbows.", "Engage your core and keep your back straight throughout the movement.", "Raise your arms forward and out to form a Y shape, keeping the movement controlled and your elbows slightly bent.", "Lift until your arms are roughly parallel to the floor and in line with your ears.", "Pause briefly at the top of the movement to engage your shoulder muscles fully, then slowly lower your arms back down to the starting position.", "Ensure the movement is slow and controlled during both the ascent and descent to maximize engagement of the deltoids and supporting muscles.", "Repeat for the desired number of repetitions, maintaining proper form throughout."]', 'wger', 0),
('dumbbell-iron-cross', 'Iron Cross', NULL, 'strength', NULL, 'compound', 'push', NULL, 'intermediate', NULL, NULL, NULL, 0),
('dumbbell-jalon-caballero-unialteral', 'Jalon caballero unialteral', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Pull performed in knight''s stance"]', 'wger', 0),
('dumbbell-kong-curl', 'Kong Curl', NULL, 'strength', 'elbow_flexion', NULL, NULL, NULL, NULL, NULL, '["This exercise is somewhat similar to a cable curl and a cable crossover. But instead of a chest/biceps exercise, this exercise targets the brachialis muscle, responsible for that broad arm when viewed from a front view. During the exercise, maintain a pronated forearm position with starting position of approx. 45 degree pronated. Start with slightly bend elbows and alternately curl until your hands (your thumb first) meet your upper middle chest (similar to how Kong hits his chest, thus the name of this exercise)."]', 'wger', 0),
('dumbbell-kreis-press', 'Kreis Press DB', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Sit on a bench with 45° incline", "Hold dumbbells overhead", "Move dumbbells down as if doing overhead press", "Rotate dumbbells palms facing up and extend your arms in front of your body", "Move hands together until dumbbells meet, keep arms extended", "Reverse the motion until dumbbells are overhead again", "This is one repetition"]', 'wger', 0),
('dumbbell-lat-pull', 'Lat Pull DB', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Bend upper body forward", "Move dumbbells near your body with slightly bent arms towards your back"]', 'wger', 0),
('dumbbell-lateral-lunge', 'Lateral Lunge – Dumbbell', NULL, 'strength', 'lunge', NULL, NULL, NULL, NULL, NULL, '["Stand with your feet hip-width apart, holding a dumbbell in each hand at your sides. This is the starting position.", "Take a big step out to the right, ensuring your toes on both feet are pointing forward.", "Shift your weight over your right leg, hinging at the hip and pushing your buttocks back while bending the right knee. Keep the left leg straight.", "Keep your back straight and chest up as you lunge, lowering until your right thigh is parallel to the floor. The dumbbells will lower with your arms on either side of your right calf.", "Push off your right foot to return to the starting position.", "Repeat for the desired number of repetitions before switching to the left side."]', 'longhaul-fitness', 0),
('dumbbell-lateral-raise', 'Lateral Raises', 'Seitheben KH', 'strength', 'isolation_other', 'isolation', 'push', NULL, 'beginner', NULL, '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand with your palms facing inward.", "Keep your arms straight and lift them out to the sides until they are parallel to the floor.", "Pause for a moment, then slowly lower the dumbbells back down to your sides.", "Repeat."]', 'longhaul-fitness', 0),
('dumbbell-lateral-to-front-raise', 'Lateral-to-Front Raises', NULL, 'strength', 'isolation_other', NULL, NULL, NULL, NULL, NULL, '["-(1) Perform a lateral raise, pausing at the top of the lift (2).", "-Instead of lowering the weight, bring it to the front of your body so that you appear to be at the top position of a front raise. You will do this by using a Pec Fly motion, maintaining straight arms. (3)", "-Now lower the weight to your quadriceps, or, in other words, lower the dumbbells as though you are completing a Front Raise repetition. (4)", "-Reverse the motion: Perform a front raise (5), at the apex of the lift use a Reverse Fly motion to position the weights at the top of a Lateral Raise (6), and finally, lower the weights until your palms are essentially touching the sides of your thighs (7). THIS IS ONE REP.", "(1) l front view(2) -l- FV (3) l- side view (4) l SV/FV (5) l- SV (6) -l- FV (7) l FV/SV"]', 'wger', 0),
('dumbbell-lu-raise', 'Lu Raise – Dumbbell', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Stand with your feet shoulder-width apart, holding a pair of dumbbells at your sides with your palms facing your body.", "Lift the dumbbells laterally with a slight bend in the elbows, rotating your thumbs upwards as the weights ascend.", "Continue lifting the weights above your head until your arms are fully extended and your thumbs are pointing towards each other.", "Pause briefly at the top of the movement.", "Lower the dumbbells back to the starting position in a controlled manner, reversing the thumb rotation."]', 'longhaul-fitness', 0),
('dumbbell-lunge', 'Lunge – Dumbbell', NULL, 'strength', 'lunge', 'compound', 'push', NULL, 'beginner', NULL, '["Stand with your feet hip-width apart and hold a dumbbell in each hand, palms facing your body.", "Take a big step forward with your right foot, keeping your torso upright.", "Bend both knees to lower your body towards the floor, making sure your right knee is directly above your ankle.", "Push through your right heel to return to the starting position.", "Repeat on the other side, stepping forward with your left foot.", "Continue alternating legs for the desired number of repetitions."]', 'longhaul-fitness', 1),
('dumbbell-lunge-walking', 'Dumbbell Lunges Walking', 'Ausfallschritte im Gehen', 'strength', 'lunge', NULL, NULL, 'alternating', NULL, NULL, '["Take two dumbbells in your hands, stand straight, feet about shoulder wide. Take one long step so that the front knee is approximately forming a right angle. The back leg is streched, the knee is low but doesn''t touch the ground. \"Complete\" the step by standing up and repeat the movement with the other leg."]', 'wger', 0),
('dumbbell-lying-internal-shoulder-rotation', 'Lying Internal Shoulder Rotation – Dumbbell', NULL, 'strength', 'rotation', NULL, NULL, NULL, NULL, NULL, '["Lie on your side on a flat bench with your legs stacked, and your body straight as possible from head to toes.", "Bend your lower arm (the one closest to the bench) at a 90-degree angle at your elbow, and grasp a dumbbell with a your palm facing the ceiling.", "Rotate your shoulder while keeping your elbow at a 90-degree angle, moving your forearm towards the ceiling and inwards towards your body.", "Rotate your arm upward as far as comfortably possible without lifting your elbow off the bench or your body moving off its position.", "Pause at the top of the movement for a brief moment.", "Slowly return the dumbbell to the starting position by rotating the forearm back to the bench while keeping the elbow angle constant.", "Complete all the desired repetitions on one arm before switching to the other arm and repeating the steps."]', 'longhaul-fitness', 0),
('dumbbell-lying-one-arm-rear-lateral-raise', 'Dumbbell Lying One-Arm Rear Lateral Raise', NULL, 'strength', 'isolation_other', 'isolation', 'pull', 'unilateral', 'intermediate', NULL, NULL, NULL, 1),
('dumbbell-lying-pronation', 'Dumbbell Lying Pronation', NULL, 'strength', 'isolation_other', 'isolation', 'pull', NULL, 'intermediate', NULL, NULL, NULL, 0),
('dumbbell-lying-rear-lateral-raise', 'Dumbbell Lying Rear Lateral Raise', NULL, 'strength', 'isolation_other', 'isolation', 'pull', NULL, 'intermediate', NULL, NULL, NULL, 0),
('dumbbell-lying-row-ss-seated-shrug', 'LYING DUMBBELL ROW SS SEATED SHRUG', NULL, 'strength', 'horizontal_pull', NULL, NULL, 'bilateral', NULL, NULL, '["laying on the stomach on a bench with slight angle"]', 'wger', 0),
('dumbbell-lying-supination', 'Dumbbell Lying Supination', NULL, 'strength', 'isolation_other', 'isolation', 'pull', NULL, 'intermediate', NULL, NULL, NULL, 0),
('dumbbell-lying-supine-curl', 'Lying Supine Dumbbell Curl', NULL, 'strength', 'elbow_flexion', 'isolation', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('dumbbell-machine-scott', 'Dumbbells on Scott Machine', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0),
('dumbbell-middle-back-shrug', 'Middle Back Shrug', NULL, 'strength', 'isolation_other', 'isolation', 'pull', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('dumbbell-no-leg-drive-chest-press', 'No Leg Drive Dumbbell Chest Press', NULL, 'strength', 'horizontal_push', NULL, NULL, NULL, NULL, NULL, '["Set up for a normal Dumbbell chest press but lift your leg ups straight or put them on another bench to remove the leg drive."]', 'wger', 0),
('dumbbell-one-arm-heavy-row', 'One-Arm Heavy Row', NULL, 'strength', 'horizontal_pull', NULL, NULL, 'unilateral', NULL, NULL, '["Execution", "Rowing phase (concentric):", "Pull the dumbbell toward your lower chest or waist, leading with your elbow.", "Keep your torso stable — avoid twisting or rotating your shoulders.", "Pause at the top and squeeze your lats."]', 'wger', 0),
('dumbbell-one-arm-side-laterals', 'One-Arm Side Laterals', NULL, 'strength', 'isolation_other', 'isolation', 'push', 'unilateral', 'beginner', NULL, NULL, NULL, 0),
('dumbbell-one-handed-hammer-isometric-hold', 'One-Handed Hammer Isometric Hold – Dumbbell', NULL, 'strength', NULL, NULL, NULL, 'unilateral', NULL, NULL, '["Select a dumbbell of appropriate weight and position yourself at a preacher curl bench.", "Stand with one foot forward and the other back in a staggered stance.", "Lean slightly forward from the hips and place the back of your upper arm (of the arm that will be curling) on the sloped part of the preacher bench, ensuring your shoulders are open to the side.", "Curl your arm up to achieve a 90-degree angle at the elbow. Your forearm should be roughly perpendicular to the floor.", "Hold the dumbbell at this angle, maintain the position firmly and ensure the muscle is under constant tension without movement for the desired time period.", "Once the hold is complete, slowly lower the dumbbell back to the starting position in a controlled manner.", "Repeat the process using the other arm."]', 'longhaul-fitness', 0),
('dumbbell-one-handed-leaning-lateral-raise', 'One-Handed Leaning Lateral Raise – Dumbbell', NULL, 'strength', 'isolation_other', NULL, NULL, 'unilateral', NULL, NULL, '["Stand with your feet shoulder-width apart and a dumbbell in your left hand.", "Slightly lean your right shoulder against a wall or stable structure. Aim for a 60-degree angle between you and the ground.", "Keep your back straight and core engaged. This is your starting position.", "Slowly lift the dumbbell to the side, keeping your arm slightly bent. Raise it until your left arm is perpendicular with your body.", "Pause at the top of the movement, then slowly lower the dumbbell back to the starting position.", "Repeat the desired number of repetitions before switching to the other side."]', 'longhaul-fitness', 0),
('dumbbell-one-handed-overhead-contralateral-step-up', 'One-Handed Overhead Contralateral Step-Up – Dumbbell', NULL, 'strength', 'lunge', NULL, NULL, 'unilateral', NULL, NULL, '["Stand in front of a step or bench with feet hip-width apart and a dumbbell in one hand.", "Press the dumbbell overhead with the arm fully extended, keeping the core engaged.", "Place the opposite foot on the step, ensuring the entire foot is on the platform.", "Push through the heel of the foot on the step to lift your body up, while keeping the dumbbell arm extended overhead.", "Bring the trailing leg up to join the lead on the step, achieving a balanced position.", "Carefully step back down with the trailing leg first, followed by the lead leg.", "Maintain control and balance throughout the movement, keeping the dumbbell overhead.", "Repeat for desired reps, then switch arms and legs."]', 'longhaul-fitness', 0),
('dumbbell-one-handed-overhead-tricep-extension', 'One-Handed Overhead Tricep Extension – Dumbbell', NULL, 'strength', 'elbow_extension', NULL, NULL, 'unilateral', NULL, NULL, '["Stand with your feet shoulder-width apart and hold a dumbbell in one hand.", "Extend your arm straight up, holding the dumbbell above your head.", "Bend your elbow and lower the dumbbell behind your head, keeping your upper arm stationary.", "Pause for a moment, then extend your arm back up to the starting position.", "Repeat for the desired number of reps, then switch to the other arm."]', 'longhaul-fitness', 0),
('dumbbell-one-handed-suitcase-walking-lunge', 'One-Handed Suitcase Walking Lunge – Dumbbell', NULL, 'strength', 'lunge', NULL, NULL, 'alternating', NULL, NULL, '["Stand upright with feet shoulder-width apart while holding a dumbbell in one hand by your side, similar to carrying a suitcase.", "Keep your chest up, shoulders back, and core engaged.", "Step forward with one leg into a lunge position, ensuring your front knee is directly above your ankle and your back knee is hovering just above the ground.", "Push through the heel of your front foot to bring your back leg forward into the starting position, keeping the dumbbell steady by your side.", "Continue the lunge by stepping forward with the opposite leg, maintaining balance and proper form.", "Repeat the walking lunge series for the desired number of repetitions or distance while keeping the dumbbell in the same hand.", "Switch the dumbbell to the other hand and repeat for balance after completing the set with one side."]', 'longhaul-fitness', 0),
('dumbbell-one-handed-wrist-curl', 'One-Handed Wrist Curl – Dumbbell', NULL, 'strength', 'isolation_other', NULL, NULL, 'unilateral', NULL, NULL, '["Sit on a bench, resting your forearm on your knee, gripping a dumbbell in one hand with your palm facing up.", "Bending at the wrist, extend your knuckles towards the floor.", "Curl your wrist upward, bringing the dumbbell towards your forearm.", "Pause for a moment at the top of the movement, squeezing your forearm muscles.", "Slowly lower the dumbbell back to the starting position, fully extending your wrist.", "Repeat for the desired number of repetitions.", "Switch hands and repeat the exercise with the other hand."]', 'longhaul-fitness', 0),
('dumbbell-one-handed-wrist-extension', 'One-Handed Wrist Extension – Dumbbell', NULL, 'strength', NULL, NULL, NULL, 'unilateral', NULL, NULL, '["Hold a dumbbell with an overhand grip.", "Sit on a bench with your feet shoulder-width apart.", "Rest your forearm on the top of your thigh, with your palm facing down.", "Slowly lift the dumbbell by extending your wrist, keeping your elbows stationary. Focus on bringing your knuckles back towards the top of your forearm.", "Hold the dumbbell at the top of the movement for a moment.", "Lower the dumbbell back down to the starting position by flexing your wrist towards the floor.", "Repeat for the desired number of reps and then switch sides."]', 'longhaul-fitness', 0),
('dumbbell-one-leg-front-foot-elevated-split-squat', 'One-Leg Front Foot Elevated Split Squat – Dumbbell', NULL, 'strength', 'lunge', NULL, NULL, 'unilateral', NULL, NULL, '["Place a 12-16 inch plyobox in front of you and hold dumbbells of the desired weight.", "Step onto the plyobox with your front foot, creating a split stance.", "Engage your core and keep your chest lifted.", "Lunge forward by bending the front foot''s knee, allowing your back knee to lower towards the ground.", "Lean forward slightly to allow your front knee to move past your toes, ensuring full knee flexion.", "Push through your front heel to return to the standing position.", "Repeat the movement for your desired number of repetitions then switch legs."]', 'longhaul-fitness', 0),
('dumbbell-palms-down-wrist-curl-over-bench', 'Palms-Down Dumbbell Wrist Curl Over A Bench', NULL, 'strength', 'isolation_other', 'isolation', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('dumbbell-palms-up-wrist-curl-over-bench', 'Palms-Up Dumbbell Wrist Curl Over A Bench', NULL, 'strength', 'isolation_other', 'isolation', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('dumbbell-patada-de-burro-con-mancuerna', 'Patada de burro con mancuerna', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0),
('dumbbell-patadas-traseras', 'Patadas traseras', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["The dumbbell kickback is a popular strength training exercise that targets the triceps muscles in the back of your upper arms. It helps strengthen and tone the triceps, contributing to overall arm strength and aesthetics.", "Among the exercises that work the arm muscles, kickback and its variations are very effective. You can easily apply these exercises with dumbbells, cables or resistance bands."]', 'wger', 0),
('dumbbell-plie-squat', 'Plie Dumbbell Squat', NULL, 'strength', 'squat', 'compound', 'push', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('dumbbell-power-partials', 'Power Partials', NULL, 'strength', 'isolation_other', 'isolation', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('dumbbell-preacher-curl', 'Preacher Curl – Dumbbell', NULL, 'strength', 'elbow_flexion', NULL, NULL, NULL, NULL, NULL, '["Sit on a preacher bench, placing your upper arms on the padding, holding a dumbbell in each hand with an underhand grip.", "Adjust the seat height so your armpits touch the top of the padding and your arm fully extends. This is your starting position.", "Curl the dumbbells upwards towards your shoulders, contracting your biceps while keeping your upper arms stationary.", "Pause briefly at the top of the movement, squeezing your biceps.", "Lower the dumbbells slowly back to the starting position in a controlled manner, fully extending your arms.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('dumbbell-preacher-curl-externally-rotated', 'Preacher Curl - Externally Rotated', NULL, 'strength', 'elbow_flexion', NULL, NULL, NULL, NULL, NULL, '["Single arm curl that can be done using a dumbbell and a preacher bench, or a preacher curl machine. Turn body away from the weight"]', 'wger', 0),
('dumbbell-preacher-curl-internally-rotated', 'Preacher Curl - Internally Rotated', NULL, 'strength', 'elbow_flexion', NULL, NULL, NULL, NULL, NULL, '["Single arm curl that can be done using a dumbbell and a preacher bench, or a preacher curl machine. Turn body towards the weight"]', 'wger', 0),
('dumbbell-prone-incline-curl', 'Dumbbell Prone Incline Curl', NULL, 'strength', 'elbow_flexion', 'isolation', 'pull', NULL, 'intermediate', NULL, NULL, NULL, 0),
('dumbbell-prone-incline-front-raise', 'Prone Incline Front Raise – Dumbbell', NULL, 'strength', 'isolation_other', NULL, NULL, NULL, NULL, NULL, '["Set an incline bench to a 45-degree angle and lie face down with your chest against the bench.", "Hold a dumbbell in each hand, palms facing your knees, arms extended towards the ground.", "Keep the balls of your feet on the ground and your neck in a neutral position. Brace your core and maintain a straight back throughout the exercise.", "With your arms straight except for a slight elbow bend, slowly raise the dumbbells until they are above your head, parallel with your upper body.", "Pause briefly at the top of the movement.", "Slowly lower the dumbbells back to the starting position.", "Repeat the movement for the desired number of repetitions."]', 'longhaul-fitness', 0),
('dumbbell-pullover', 'Pullover', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Lie on a bench with your head and shoulders supported, and your feet flat on the floor.", "Hold a dumbbell with both hands, palms pressing against the underside of one of the sides of the dumbbell. Push the dumbbell towards the sky above your chest. This is your starting position.", "Keep a slight bend in your elbows and lock your arms in this slightly bent position throughout the entire movement.", "Inhale and slowly lower the dumbbell in an arc behind your head while keeping your arms straight, moving primarily at the shoulder joints.", "Lower the dumbbell until your arms are parallel to the floor or until you feel a stretch in your chest or lats, whichever comes first.", "Exhale as you reverse the motion, bringing the dumbbell back over your chest in the same arc motion.", "Repeat for the desired number of reps."]', 'longhaul-fitness', 0);
INSERT INTO exercises (id, name_en, name_de, category, movement_pattern, mechanic, force, laterality, level, variation_of, instructions, instructions_source_id, needs_review) VALUES
('dumbbell-push-press', 'Push Press – Dumbbell', NULL, 'strength', 'vertical_push', NULL, NULL, NULL, NULL, NULL, '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand at shoulder level with your palms facing your head.", "Bend your knees slightly and dip your body down.", "Quickly straighten your legs and use the momentum to push the dumbbells overhead.", "Lock out your arms at the top of the movement.", "Lower the dumbbells back down to shoulder level and repeat for desired number of reps."]', 'longhaul-fitness', 1),
('dumbbell-raise', 'Dumbbell Raise', NULL, 'strength', NULL, 'compound', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('dumbbell-rear-delt-raise', 'Rear Delt Raises', NULL, 'strength', 'isolation_other', NULL, NULL, NULL, NULL, NULL, '["Seated on a bench with the dumbbells on the floor bend over at 45 Degrees and then slowly raise each dumbbell to shoulder height and hold for a couple seconds before lowering to the starting position."]', 'wger', 0),
('dumbbell-rear-delt-row', 'Dumbbell rear delt row', NULL, 'strength', 'horizontal_pull', NULL, NULL, NULL, NULL, NULL, '["Stand up straight holding a dumbbell in each hand with an overhand grip, palms facing your thighs.", "Hinge forward at the hips with a slight bend in the knees, keeping your back straight and nearly parallel to the floor.", "Let the dumbbells hang directly in front of you with your arms fully extended. This is the starting position.", "Keep your eyes looking slightly ahead to maintain neck alignment with your spine.", "Exhale as you pull the dumbbells towards your upper chest, keeping your elbows flared out. Imagine you are squeezing your shoulder blades together.", "Hold the contraction for a second when the dumbbells reach the peak position when your upper arm is just beyond horizontal.", "Inhale as you slowly lower the dumbbells back to the starting position in a controlled manner.", "Repeat the movement for the desired number of repetitions."]', 'longhaul-fitness', 0),
('dumbbell-rear-lunge', 'Dumbbell Rear Lunge', NULL, 'strength', 'lunge', 'compound', 'push', NULL, 'intermediate', NULL, '["This exercise involves holding a dumbbell in each hand and stepping back into a lunge position, then returning to standing. It primarily targets the glutes, hamstrings, and quadriceps."]', 'wger', 0),
('dumbbell-renegade-row', 'Renegade Row', NULL, 'strength', 'horizontal_pull', NULL, NULL, NULL, NULL, NULL, '["Get into pushup position gripping some dumbbells. Perform one pushup, then drive your left elbo up, bringing the dumbell up to your body. Return the dumbell to starting position.", "Perform another pushup and then row with the other arm to complete one rep."]', 'wger', 0),
('dumbbell-reverse-fly', 'Reverse Fly – Dumbbell', NULL, 'strength', 'isolation_other', 'isolation', 'pull', NULL, 'beginner', NULL, '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand with your palms facing each other.", "Bend forward at your hips, keeping your back straight and your core engaged.", "Extend your arms straight down towards the floor, with your elbows slightly bent.", "Keeping your arms straight, lift the dumbbells out to the sides until they reach shoulder height.", "Pause for a moment, then slowly lower the dumbbells back down to the starting position.", "Repeat."]', 'longhaul-fitness', 0),
('dumbbell-reverse-flyes-external-rotation', 'Reverse Flyes With External Rotation', NULL, 'strength', 'rotation', 'isolation', 'pull', NULL, 'intermediate', NULL, NULL, NULL, 0),
('dumbbell-row', 'Row – Dumbbell', NULL, 'strength', 'horizontal_pull', NULL, NULL, NULL, NULL, NULL, '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand with a neutral grip (palms facing each other).", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Bring the dumbbells up towards your chest, keeping your elbows close to your body.", "Pause at the top of the movement and squeeze your shoulder blades together.", "Lower the dumbbells back down to the starting position.", "Repeat."]', 'longhaul-fitness', 1),
('dumbbell-scaption', 'Dumbbell Scaption', NULL, 'strength', 'isolation_other', 'isolation', 'push', NULL, 'beginner', NULL, '["Starting position:", "Stand upright with your feet shoulder-width apart.", "Hold a dumbbell in each hand with a neutral grip (palms facing each other).", "Keep a slight bend in your elbows, shoulders relaxed and shoulder blades pulled back.", "Execution:", "Slowly raise the dumbbells forward and slightly to the side, at about a 30–45° angle from your body (between a front raise and a lateral raise).", "Lift until your arms are about shoulder height (do not go overhead).", "Pause for a second at the top and feel the activation in your shoulders and scapular stabilizers.", "Lower the dumbbells back down under control to the starting position.", "Breathing:", "Inhale as you lower the dumbbells.", "Exhale as you lift them.", "Common mistakes:", "Using dumbbells that are too heavy (causing jerky movements).", "Lifting above shoulder height (puts unnecessary stress on the shoulder joint).", "Arching the lower back instead of keeping the movement controlled at the shoulders.", "Purpose of the exercise:", "Activates the lower trapezius, serratus anterior, and scapular stabilizers.", "Helps correct posture and improve shoulder balance."]', 'wger', 0),
('dumbbell-schoulder-raise', 'Schoulder Raise (Dumbbell)', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0),
('dumbbell-seated-bent-over-two-arm-triceps-extension', 'Seated Bent-Over Two-Arm Dumbbell Triceps Extension', NULL, 'strength', 'elbow_extension', 'isolation', 'push', NULL, 'intermediate', NULL, NULL, NULL, 0),
('dumbbell-seated-box-jump', 'Dumbbell Seated Box Jump', NULL, 'plyometrics', NULL, 'compound', 'push', NULL, 'intermediate', NULL, NULL, NULL, 0),
('dumbbell-seated-inner-biceps-curl', 'Seated Dumbbell Inner Biceps Curl', NULL, 'strength', 'elbow_flexion', 'isolation', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('dumbbell-seated-one-arm-palms-down-wrist-curl', 'Seated One-Arm Dumbbell Palms-Down Wrist Curl', NULL, 'strength', 'isolation_other', 'isolation', 'pull', 'unilateral', 'intermediate', NULL, NULL, NULL, 0),
('dumbbell-seated-one-arm-palms-up-wrist-curl', 'Seated One-Arm Dumbbell Palms-Up Wrist Curl', NULL, 'strength', 'isolation_other', 'isolation', 'pull', 'unilateral', 'beginner', NULL, NULL, NULL, 0),
('dumbbell-seated-palms-down-wrist-curl', 'Seated Dumbbell Palms-Down Wrist Curl', NULL, 'strength', 'isolation_other', 'isolation', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('dumbbell-seated-palms-up-wrist-curl', 'Seated Dumbbell Palms-Up Wrist Curl', NULL, 'strength', 'isolation_other', 'isolation', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('dumbbell-seated-press', 'Seated Dumbbell Press', NULL, 'strength', NULL, 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('dumbbell-seated-rear-delt-rise', 'Seated rear delt rise', NULL, 'strength', 'isolation_other', NULL, NULL, NULL, NULL, NULL, '["Seated, bent 45 deg forward. Arms fully stretched out, raise arms up to shoulder height and back down"]', 'wger', 0),
('dumbbell-seated-side-lateral', 'Seated Dumbbell Side Lateral', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["seated slightly leaned forward at beginning of exercise"]', 'wger', 0),
('dumbbell-seated-triceps-press', 'Seated Triceps Press', NULL, 'strength', 'isolation_other', 'isolation', 'push', NULL, 'beginner', NULL, '["Sit down on a back (better with back support). Take a dumbbell firmly with both hands and hold it with extended arms over your head. With your palms facing upward and holding the weight of the dumbbell, slowly lower the weight behind your head."]', 'wger', 0),
('dumbbell-seated-w-curl', 'Seated W Curl', NULL, 'strength', 'elbow_flexion', NULL, NULL, NULL, NULL, NULL, '["Sit on bench with 60° incline", "Hold dumbbells beside body near the ground, palms facing outwards, arms fully extended", "Move dumbbells up using only biceps and without momentum"]', 'wger', 0),
('dumbbell-see-saw-press-alternating-side', 'See-Saw Press (Alternating Side Press)', NULL, 'strength', NULL, 'compound', 'push', 'alternating', 'intermediate', NULL, NULL, NULL, 0),
('dumbbell-shoulder-external-rotation', 'Shoulder External Rotation with Dumbbell', NULL, 'strength', 'rotation', NULL, NULL, NULL, NULL, NULL, '["Lie on your side holding a dumbbell in your upper hand", "Tuck your elbow into your side and rest the hand in front of you", "Rotate the shoulder so the hand raises up", "Lower the hand down"]', 'wger', 0),
('dumbbell-shoulder-pendular-exercise', 'Shoulder Dumbbell Pendular Exercise', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Lean forward to rest your hand on a chair or other object, holding a dumbbell in the other hand", "Gently swing the dumbbell in a circular motion"]', 'wger', 0),
('dumbbell-shoulder-press', 'Shoulder Press, Dumbbells', 'Schulterdrücken KH', 'strength', 'vertical_push', 'compound', 'push', NULL, 'intermediate', NULL, '["Start by standing with your feet shoulder-width apart, holding a dumbbell in each hand by your thighs.", "Raise the dumbbells to shoulder height, palms facing forward, and elbows bent.", "Press the dumbbells upward until your arms are fully extended above your head.", "Pause for a moment at the top of the movement, then slowly lower the dumbbells back down to shoulder height.", "Repeat."]', 'longhaul-fitness', 0),
('dumbbell-shoulder-raise-side-and-front', 'Shoulder Raise Side and Front DB', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Stand while holding dumbbells beside body", "Keep arms almost fully extended", "Without momentum raise dumbbells to the side of your body until shoulder height, palms facing down", "Lower dumbbells beside body, palms facing inwards", "Immediately raise dumbbells in front of your body until shoulder height, palms facing down", "Down again", "This is one repetition"]', 'wger', 0),
('dumbbell-shoulder-rotation', 'Dumbbell Shoulder Rotations', NULL, 'strength', 'rotation', NULL, NULL, NULL, NULL, NULL, '["Dumbbell shoulder rotations are designed to strengthen the rotator cuff muscles and improve shoulder stability and mobility.", "External Rotation: Hold a dumbbell in one hand, keeping your elbow bent at 90 degrees and close to your body. Rotate your forearm outward, away from your body, keeping your elbow stationary. Slowly return to the starting position.", "Internal Rotation: Hold a dumbbell in one hand, keeping your elbow bent at 90 degrees and close to your body. Rotate your forearm inward, toward your body, and slowly return to the starting position. Perform the exercise with controlled movements to avoid strain."]', 'wger', 0),
('dumbbell-shrug', 'Shrugs, Dumbbells', 'Shrugs KH', 'strength', 'isolation_other', 'isolation', 'pull', 'bilateral', 'beginner', NULL, '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.", "Keep your arms straight and allow the dumbbells to hang at your sides.", "Engage your core and lift your shoulders towards your ears, squeezing your shoulder blades together.", "Hold the contraction for a second, then slowly lower your shoulders back down to the starting position.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('dumbbell-side-bend', 'Dumbbell Side Bend', NULL, 'strength', 'isolation_other', 'isolation', 'pull', NULL, 'beginner', NULL, '["This exercise involves holding a dumbbell in one hand and bending sideways to work the oblique muscles on the side of the body. It can be done standing or seated and is often used as a core strengthening exercise."]', 'wger', 1),
('dumbbell-side-laterals-to-front-raise', 'Side Laterals to Front Raise', NULL, 'strength', 'isolation_other', 'isolation', 'push', NULL, 'beginner', NULL, NULL, NULL, 1),
('dumbbell-side-squat', 'Dumbbell Side Squat', NULL, 'strength', 'squat', NULL, NULL, 'bilateral', NULL, NULL, '["This exercise involves holding a dumbbell in one hand and performing a squat while stepping to the side. It targets the legs, glutes, and core muscles."]', 'wger', 0),
('dumbbell-side-trunk-flexion', 'Side Dumbbell Trunk Flexion', 'Seitliches Oberkörperbeugen Mit KH', 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["AKA dumbbell side bends. Stand in line with the hips with slightly bent knees, maintain the natural curvature of the spine, hand stretched by the body, grip the barbell with one hand. Make slow and controlled torso side flexions till you reach the angle of approximately 45°."]', 'wger', 0),
('dumbbell-single-arm-bulgarian-split-squat', 'Single-Arm Bulgarian Split Squat – Dumbbell', NULL, 'strength', 'lunge', NULL, NULL, 'unilateral', NULL, NULL, '["Stand a few feet in front of a bench with your back towards it.", "Hold a dumbbell in one hand on the same side as the working leg.", "Extend your opposite leg back and place the top of your foot on the bench.", "Keep your chest upright and core engaged throughout the movement.", "Slowly lower your hips by bending the knee of the working leg.", "Continue lowering until your front thigh is parallel to the ground.", "Push through the heel of your front foot to return to the starting position.", "Repeat for the desired number of repetitions before switching sides."]', 'longhaul-fitness', 0),
('dumbbell-single-leg-hip-thrust', 'Dumbbell Single-leg Hip Thrust', NULL, 'strength', 'hinge', NULL, NULL, 'unilateral', NULL, NULL, '["The single-leg hip thrust is performed by placing your upper back on a weight bench, raising one leg, and extending the hip of the other leg to achieve an isolated contraction of the glute. By working each side separately, you can fully isolate your glutes unilaterally, providing maximal training stimulus."]', 'wger', 1),
('dumbbell-single-raise', 'Single Dumbbell Raise', NULL, 'strength', 'isolation_other', 'isolation', NULL, NULL, 'beginner', NULL, NULL, NULL, 0),
('dumbbell-skullcrusher', 'Skullcrusher Dumbbells', 'Frenchpress KH', 'strength', 'elbow_extension', NULL, NULL, NULL, NULL, NULL, '["Lie on a bench with your knees bent and feet flat on the ground. Hold a dumbbell in each hand directly above your shoulders with your arms fully extended.", "With your palms facing each other, engage your core and keep your wrists straight.", "Slowly bend your elbows to lower the dumbbells towards the sides of your forehead. Keep your upper arms stationary and elbows pointing straight up throughout the movement.", "Lower the weights until your forearms and biceps are at least at a 90-degree angle.", "Pause briefly at the bottom of the movement.", "Press the dumbbells back up to the starting position by extending your elbows while exhaling. Focus on using your triceps to move the weight.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('dumbbell-spell-caster', 'Spell Caster', NULL, 'strength', NULL, 'compound', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('dumbbell-split-squat', 'Dumbbell Split Squat', 'Dumbbell Split Squat', 'strength', 'lunge', 'compound', 'push', 'unilateral', 'beginner', NULL, '["Controlled execution", "No momentum", "Execute slowly"]', 'wger', 0),
('dumbbell-squat', 'Squat – Dumbbell', NULL, 'strength', 'squat', 'compound', 'push', 'bilateral', 'beginner', NULL, '["Stand with your feet shoulder-width apart, with your toes pointing slightly outward.", "Hold a dumbbell in each hand by your sides, with your palms facing inward.", "Engage your core and keep your chest lifted throughout the movement.", "Lower your body by bending at the hips and knees as if sitting on a chair.", "Keep your weight in your heels, and make sure your knees are tracking over your toes.", "Lower your body until your thighs are parallel to the ground or until you reach your desired depth.", "Push through your heels to stand back up to the starting position.", "Repeat."]', 'longhaul-fitness', 0),
('dumbbell-squat-to-bench', 'Dumbbell Squat To A Bench', NULL, 'strength', 'squat', 'compound', 'push', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('dumbbell-standing-alternating-press', 'Standing Alternating Dumbbell Press', NULL, 'strength', NULL, 'compound', 'push', 'alternating', 'beginner', NULL, NULL, NULL, 0),
('dumbbell-standing-bent-over-two-arm-triceps-extension', 'Standing Bent-Over Two-Arm Dumbbell Triceps Extension', NULL, 'strength', 'elbow_extension', 'isolation', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('dumbbell-standing-inner-biceps-curl', 'Standing Inner-Biceps Curl', NULL, 'strength', 'elbow_flexion', 'isolation', 'pull', NULL, 'intermediate', NULL, NULL, NULL, 0),
('dumbbell-standing-one-arm-curl-over-incline-bench', 'Standing One-Arm Dumbbell Curl Over Incline Bench', NULL, 'strength', 'elbow_flexion', 'isolation', 'pull', 'unilateral', 'beginner', NULL, NULL, NULL, 0),
('dumbbell-standing-palm-in-one-arm-press', 'Standing Palm-In One-Arm Dumbbell Press', NULL, 'strength', NULL, 'compound', 'push', 'unilateral', 'beginner', NULL, NULL, NULL, 0),
('dumbbell-standing-palms-in-press', 'Standing Palms-In Dumbbell Press', NULL, 'strength', NULL, 'compound', 'push', NULL, 'intermediate', NULL, NULL, NULL, 0),
('dumbbell-standing-press', 'Standing Dumbbell Press', NULL, 'strength', NULL, 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('dumbbell-standing-straight-arm-front-delt-raise-above-head', 'Standing Dumbbell Straight-Arm Front Delt Raise Above Head', NULL, 'strength', 'isolation_other', 'isolation', 'push', NULL, 'intermediate', NULL, NULL, NULL, 0),
('dumbbell-step-up', 'Dumbbell Step Ups', NULL, 'strength', 'lunge', 'compound', 'push', 'unilateral', 'intermediate', NULL, NULL, NULL, 1),
('dumbbell-straight-arm-pullover', 'Straight-Arm Dumbbell Pullover', NULL, 'strength', NULL, 'compound', 'pull', NULL, 'intermediate', NULL, NULL, NULL, 0),
('dumbbell-supine-hip-abduction', 'Supine Hip Abduction', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Starting Position: Lie on your back (supine) on a mat, with your legs extended and relaxed. Arms can be placed alongside your body or out to the sides for stability.", "The Movement: Slightly lift one leg off the floor (keeping it straight or with a slight bend). Move it laterally outward, away from the other leg, as if stepping over a small obstacle.", "Range of Motion: Move the leg as far as comfortable without lifting your pelvis or rotating your torso, feeling a stretch in the inner thigh and hip.", "Return: Slowly bring the leg back to the starting position with controlled movement.", "Goal: Improves lateral hip mobility (abduction) and strengthens the pelvic stabilizer muscles."]', 'wger', 0),
('dumbbell-tate-press', 'Dumbell Tate Press', NULL, 'strength', 'elbow_extension', 'isolation', 'push', NULL, 'intermediate', NULL, '["Set Up: Lie flat with a dumbbell in each hand. Extend your arms straight up over your chest as if you were at the top of a dumbbell bench press", "Starting Position: Position the dumbbells so they are touching or very close together with a pronated grip (palms facing your feet and thumbs facing each other)", "Lowering: Without moving your upper arms or shoulders, bend your elbows and flare them outward to the sides. Lower the inner ends of the dumbbells toward the center of your chest", "Touch and Pause: Gently touch the dumbbells to your chest. Do not rest the weight on your body; maintain constant tension in your triceps", "Press: Forcefully extend your elbows to return the dumbbells to the starting position. Focus on \"pushing your pinkies toward the sky\" to maximize triceps engagement", "https://www.youtube.com/watch?v=IgSjoXbpy1M&t=2"]', 'wger', 0),
('dumbbell-thruster', 'Dumbbell Thruster', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Start with the dumbbells resting on your shoulders and squat down. Push into standing and raise the dumbbells into an overhead position. Bring the dumbbells back to your shoulders and repeat."]', 'wger', 0),
('dumbbell-thumbs-up-lateral-raise', 'Thumbs-Up Lateral Raise – Dumbbell', NULL, 'strength', 'isolation_other', NULL, NULL, NULL, NULL, NULL, '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with a thumbs up grip (mid pronation).", "Position your arms to your side and about 30 degrees in front of your body.", "Engage your core and keep your elbows slightly bent. This is your starting position.", "Raise the dumbbells to approximately shoulder height, focusing on using your shoulder muscles.", "Pause briefly at the top of the movement.", "Slowly lower the dumbbells back to the starting position with control.", "Repeat the movement for your desired number of repetitions."]', 'longhaul-fitness', 0),
('dumbbell-tricep-extension-pronated-grip', 'Dumbbell Tricep Extension -Pronated Grip', NULL, 'strength', 'elbow_extension', 'isolation', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('dumbbell-tricep-kickback', 'Tricep Dumbbell Kickback', 'Kick-Backs', 'strength', 'elbow_extension', 'isolation', 'push', NULL, 'beginner', NULL, '["Start with a dumbbell in each hand and your palms facing your torso. Keep your back straight with a slight bend in the knees and bend forward at the waist. Your torso should be almost parallel to the floor. Make sure to keep your head up. Your upper arms should be close to your torso and parallel to the floor. Your forearms should be pointed towards the floor as you hold the weights. There should be a 90-degree angle formed between your forearm and upper arm. This is your starting position.", "Now, while keeping your upper arms stationary, exhale and use your triceps to lift the weights until the arm is fully extended. Focus on moving the forearm.", "After a brief pause at the top contraction, inhale and slowly lower the dumbbells back down to the starting position.", "Repeat the movement for the prescribed amount of repetitions.", "Variations: This exercise can be executed also one arm at a time much like the one arm rows are performed.", "Also, if you like the one arm variety, you can use a low pulley handle instead of a dumbbell for better peak contraction. In this case, the palms should be facing up (supinated grip) as opposed to the torso (neutral grip)."]', 'wger', 0),
('dumbbell-triceps-extension', 'Dumbbell Triceps Extension', NULL, 'strength', 'elbow_extension', NULL, NULL, NULL, NULL, NULL, '["Position one dumbbell over head with both hands under inner plate (heart shaped grip).", "With elbows over head, lower forearm behind upper arm by flexing elbows. Flex wrists at bottom to avoid hitting dumbbell on back of neck. Raise dumbbell over head by extending elbows while hyperextending wrists. Return and repeat."]', 'wger', 0),
('dumbbell-triceps-overhead', 'Triceps Overhead (Dumbbell)', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0),
('dumbbell-turkish-get-up', 'Turkish Get-Up', 'Turkish Get-Up', 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Starting on back, move to the standing position with dumbbell in one hand. Switch hands between reps."]', 'wger', 0),
('dumbbell-two-arm-preacher-curl', 'Two-Arm Dumbbell Preacher Curl', NULL, 'strength', 'elbow_flexion', 'isolation', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('dumbbell-ucv', 'DB UCV', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Dumbbell upper chest variance. Curl like movement up above at head level, activating chest and front delts"]', 'wger', 0),
('dumbbell-underhand-dead-row', 'Dumbbell Underhand Dead Row', NULL, 'strength', 'horizontal_pull', NULL, NULL, NULL, NULL, NULL, '["The Dumbbell Underhand Dead Row will involve the back, which means you can try a bit heavier weight. The catch is that you need to be able to control the weight for all the reps.", "Start by holding a pair of dumbbells with your feet shoulder-wide apart and your knees slightly bent.", "Hinge at your hips to lower your torse forward until it''s almost parallel to the floor, keeping your back flat and maintaining a slight bend in your knees.", "Exhale as you row the dumbbells to your sides up to chest height, leading with your elbows until your upper arms are just past parallel to the floor and the dumbbells are at ribcage level.", "Slowly lower to the starting position and repeat. Keep your back flat all the time."]', 'wger', 0),
('dumbbell-upper-chest-variation', 'DB Upper Chest Variation', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Dumbbell in hand in a curl fashion, lean body into the arm to help the dumbbell up above the chest, next to the head, to activate chest and delt combo"]', 'wger', 0),
('dumbbell-upright-row', 'Dumbbell upright-row', NULL, 'strength', 'vertical_pull', NULL, NULL, NULL, NULL, NULL, '["Hold a dumbbell in each hand in front of your body. Keep your palms towards your body. Lift you hands straight up until your hands are under your chin, then lower them. Repeat the exercise."]', 'wger', 0),
('dumbbell-upright-row-w', 'Upright Row w/ Dumbbells', NULL, 'strength', 'vertical_pull', NULL, NULL, NULL, NULL, NULL, '["Feet apart at shoulder width. Nice and Slow!"]', 'wger', 0),
('dumbbell-vertical-swing', 'Vertical Swing', NULL, 'plyometrics', 'hinge', 'compound', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('dumbbell-wide-bicep-curl', 'Dumbbell wide bicep curls', NULL, 'strength', 'elbow_flexion', NULL, NULL, NULL, NULL, NULL, '["Hold a dumbbell in each hand with your hands slightly wider than shoulder-width apart and palms facing forward. Bend your elbows and lift the dumbbells to your shoulders. Slowly return and repeat."]', 'wger', 0),
('dumbbell-ytwl-exercise', 'YTWL Exercise', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Purpose: Improves shoulder stability, posture, and scapular (shoulder blade) control. Often used in physical therapy and warm-ups.", "Starting Position: Stand with feet shoulder-width apart. Hinge forward at the hips (like a deadlift) keeping your back flat, or lie face down on an incline bench. Keep your thumbs pointing up throughout.", "Y (Arms up): Extend both arms straight forward and upward at a 135-degree angle from your body, forming a \"Y\". Squeeze your shoulder blades together at the top.", "T (Arms out): Open your arms straight out to the sides, perpendicular to your body, forming a \"T\". Focus on pinching your shoulder blades.", "W (Arms bent): Pull your elbows back, bending them to 90 degrees, and squeeze your shoulder blades to form a \"W\". Keep your wrists firm.", "L (Arms rotated): Start with elbows bent at 90 degrees and close to your body. Rotate your forearms outward (external rotation) like a goalpost, forming an \"L\" or a gate.", "Key Focus: Movements should be slow and controlled. Always lead with the thumbs and think about moving the shoulder blades, not just the arms."]', 'wger', 0),
('dumbbell-z-press', 'Z Press – Dumbbell', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Sit down on the ground, legs extended in front of you and spaced apart for stability.", "Hold a dumbbell in each hand at shoulder height, palms facing forward.", "Plant your heels firmly on the ground and brace your core.", "Press the dumbbells vertically overhead, fully extending your arms without locking your elbows.", "Pause briefly at the top of the movement.", "Lower the dumbbells back to the starting position at shoulder height in a controlled manner.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('dumbbell-zottman-curl', 'Zottman curl', NULL, 'strength', 'elbow_flexion', 'isolation', 'pull', NULL, 'intermediate', NULL, '["With your palms facing forward, curl the weights up to your shoulders. Turn your hands so that that your palms downwards and slowly return the weights back down. Finally face your palms back forward."]', 'wger', 0),
('dumbbell-zottman-preacher-curl', 'Zottman Preacher Curl', NULL, 'strength', 'elbow_flexion', 'isolation', 'pull', NULL, 'intermediate', NULL, NULL, NULL, 0),
('dynamic-back-stretch', 'Dynamic Back Stretch', NULL, 'stretching', NULL, NULL, 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('dynamic-chest-stretch', 'Dynamic Chest Stretch', NULL, 'stretching', NULL, NULL, 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('dynamic-planche', 'Dynamic Planche', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Start in a plank position, with your hands directly under your shoulders and your feet hip-width apart.", "Engage your core to keep your body in a straight line from head to toe.", "From this position, bend your knees slightly and jump with both feet inward, bringing them as close to your core as possible", "As soon as your feet touch the ground, push off forcefully to jump again and return to the starting plank position.", "Continue repeating this jumping motion, maintaining control and core stability throughout the exercise.", "Make sure to keep your breathing steady while jumping, breathing deeply and controlling your breathing.", "Keep your gaze fixed on the ground to maintain proper spinal alignment.", "Repeat the jumps for the desired length of time or the number of repetitions recommended for your workout program.", "To finish the exercise, rest by releasing the plank position, then stretch if necessary to loosen your muscles."]', 'wger', 0),
('eccentric-chest-press', 'Eccentric Chest Press', NULL, 'strength', 'horizontal_push', NULL, NULL, NULL, NULL, NULL, '["Adjust a chest press machine''s seat height so that the handles are at chest level.", "Select the appropriate weight on the weight stack.", "Sit on the machine with your back flat against the backrest and your feet flat on the floor.", "Grasp the handles with an overhand grip and push them away from your chest with two hands until your arms are fully extended.", "Release the handle with your right hand; your right hand bears no weight.", "Slowly lower the handles back towards your chest with your left hand, keeping your elbow at a 90-degree angle. Note that this will only work on machines where the two handles are linked to each other and to the weight.", "Grasp the handles with both hands. Push to fully extend your arms.", "Release the handle with your left hand; your left hand bears no weight.", "Slowly lower the handles back towards your chest with your right hand. This marks one repetition.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('eccentric-heel-drop', 'Eccentric Heel Drop', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Stand on a raised platform or step with the balls of your feet on the edge and your heels hanging off.", "Raise your heels up as high as possible with both feet.", "Shift your weight onto one leg and slowly lower your heel down below the platform, only using the single leg.", "Use both feet to push yourself back up to the raised position.", "Switch your weight to the other foot and lower yourself down single-legged.", "Continue alternating sides for the desired number of repetitions."]', 'longhaul-fitness', 0),
('eccentric-leg-extension', 'Eccentric Leg Extension', NULL, 'strength', 'isolation_other', NULL, NULL, NULL, NULL, NULL, '["Start by sitting on a leg extension machine with your back against the backrest and your feet flat on the footpad.", "Adjust the machine so that the knee joint is aligned with the axis of rotation.", "Place your hands on the side handles for stability.", "Slowly extend your legs by straightening your knees, pushing against the resistance of the weight stack.", "Once your legs are fully extended, pause briefly at the top of the movement.", "Withdraw one leg so that the other leg supports all the weight. Slowly lower the weight back down with one leg by bending a knee, resisting the weight as it pulls your legs back towards the starting position.", "Continue lowering the weight until your knees are at a 90-degree angle or slightly beyond.", "Repeat the movement for the desired number of repetitions then switch sides."]', 'longhaul-fitness', 0),
('elbow-circle', 'Elbow Circles', NULL, 'stretching', NULL, 'isolation', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('elbow-to-knee', 'Elbow to Knee', NULL, 'strength', NULL, 'compound', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('elbows-back', 'Elbows Back', NULL, 'stretching', NULL, 'isolation', 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('elephant-walk', 'Elephant Walks', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Hinge at your hips until you feel a stretch behind your knees. Bend one leg while the other is straight then fluidly bend the other knee while straightening the first knee."]', 'wger', 0),
('elevacion-lateral-polea', 'Elevación lateral polea', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Lateral elevation unilateral using a polea"]', 'wger', 0),
('elevated-prayer-stretch', 'Elevated prayer stretch', NULL, 'stretching', NULL, NULL, NULL, NULL, NULL, NULL, '["Starting position: Kneel in front of a bench, far enough so that your torso can fit between your knees and the bench. With your back straight, place your elbows on the bench, with palms together, hands pointing up. Steps:", "On exhale, stretch your chest down toward the floor without moving your lower back. At the same time, bring your hands toward your shoulders, keeping palms together and elbows on the bench.", "Hold for a few seconds.", "On inhale, relax your back to return to the starting position.", "Repeat."]', 'wger', 0),
('elliptical', 'Elliptical', NULL, 'cardio', 'locomotion', NULL, NULL, NULL, NULL, NULL, '["It improves muscle toning, strengthens the leg muscles (quads, glutes, calves), helps vascularisation and increases resistance. The elliptical is also very useful if you aim to lose weight. Teste"]', 'wger', 0),
('estiramiento-de-brazos-y-cuello', 'Estiramiento de brazos y cuello', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0),
('estiramiento-de-piernas-y-cadera', 'Estiramiento de piernas y cadera', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0),
('exercise-ball-ball-leg-curl', 'Ball Leg Curl', NULL, 'strength', 'isolation_other', 'isolation', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('exercise-ball-chest-stretch', 'Chest Stretch on Stability Ball', NULL, 'stretching', NULL, 'isolation', 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('exercise-ball-crunch', 'Exercise Ball Crunch', NULL, 'strength', 'isolation_other', 'isolation', 'pull', 'bilateral', 'beginner', NULL, NULL, NULL, 1),
('exercise-ball-crunch-legs', 'Crunch - Legs On Exercise Ball', NULL, 'strength', 'isolation_other', 'isolation', 'pull', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('exercise-ball-downward-facing-balance', 'Downward Facing Balance', NULL, 'strength', 'isolation_other', 'isolation', 'static', NULL, 'intermediate', NULL, NULL, NULL, 0),
('exercise-ball-dumbbell-pullover', 'Stability Ball Pullover – Dumbbell', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Select an appropriate weight dumbbell and a stability ball.", "Sit on the stability ball and place the dumbbell on your lap.", "Roll down the ball until your upper back and shoulders are supported by it, keeping your hips lifted, your body in a straight line, and your feet flat on the ground.", "Hold the dumbbell over your chest with both hands, gripping one end of the dumbbell while the other end points towards your chest. This is your starting position.", "Slowly lower the dumbbell in an arc behind your head, keeping your arms mostly straight, but slightly bent, throughout.", "Stretch your arms back as far as comfortably possible while maintaining control of the weight.", "Bring the dumbbell back up over your chest along the same arc.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('exercise-ball-feet-elevated-oblique-crunch', 'Feet-Elevated Oblique Crunch – Stability Ball', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["Begin by lying on your back on the ground with your feet and calves resting on a stability ball placed by your glutes. This is the starting position.", "Place your arms crossed over your chest or hands behind your ears, ensuring not to pull on your head or neck.", "Engage your core muscles and rotate your right shoulder towards your left knee. Lift your shoulder as high as you can while keeping your lower back connected to the ground. Focus on contracting your right oblique muscles.", "Hold the position briefly at the top of the movement while squeezing your obliques.", "Lower your torso back down to the starting position in a controlled manner.", "Continue alternating crunches on each side for the desired number of repetitions."]', 'longhaul-fitness', 0),
('exercise-ball-hug-ball', 'Hug A Ball', NULL, 'stretching', NULL, 'isolation', 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('exercise-ball-physioball-hip-bridge', 'Physioball Hip Bridge', NULL, 'strength', NULL, 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('exercise-ball-pull-in', 'Exercise Ball Pull-In', NULL, 'strength', NULL, 'compound', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
