('exercise-ball-pyramid', 'Pyramid', NULL, 'stretching', NULL, NULL, 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('exercise-ball-torso-rotation', 'Torso Rotation', NULL, 'stretching', NULL, NULL, 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('exercise-ball-wall-balls', 'Wall balls', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Get a medicine ball, shoulder width stance, squat, thrust the ball as high as possible against the wall and catch"]', 'wger', 0),
('exercise-ball-weighted-ball-hyperextension', 'Weighted Ball Hyperextension', NULL, 'strength', 'hinge', 'compound', 'pull', NULL, 'intermediate', NULL, NULL, NULL, 0),
('exercise-ball-weighted-ball-side-bend', 'Weighted Ball Side Bend', NULL, 'strength', 'isolation_other', 'isolation', 'pull', NULL, 'intermediate', NULL, NULL, NULL, 0),
