('kettlebell-one-arm-split-snatch', 'One-Arm Kettlebell Split Snatch', NULL, 'strength', NULL, 'compound', 'pull', 'unilateral', 'advanced', NULL, NULL, NULL, 0),
('kettlebell-one-handed-curl', 'one-handed kettlebell curls', NULL, 'strength', 'elbow_flexion', NULL, NULL, 'unilateral', NULL, NULL, '["Standing with the kettlebell in one hand and bent at the elbow, start from a fully extended position until your hand reaches shoulder height. To perform the movement correctly, try not to push with your back or body."]', 'wger', 0),
('kettlebell-one-leg-kneeling-bottoms-up-hold', 'One-Leg Kneeling Bottoms-Up Hold – Kettlebell', NULL, 'strength', NULL, NULL, NULL, 'unilateral', NULL, NULL, '["Hold a kettlebell in your left hand.", "Kneel with your left knee and right foot on the ground.", "Raise the kettlebell by the handle so that you''re balancing it upside-down.", "Keep your elbow stacked directly below your wrist.", "Flex your shoulder to 90 degrees and bend your elbow to 90 degrees.", "Hold the kettlebell with your arm in this position for the desired amount of time.", "Repeat the exercise on the other side from the same amount of time to complete a set."]', 'longhaul-fitness', 0),
('kettlebell-one-legged-deadlift', 'Kettlebell One Legged Deadlift', NULL, 'strength', 'hinge', NULL, NULL, 'unilateral', NULL, NULL, '["This exercise involves holding a kettlebell in one hand and standing on one leg while bending forward to touch the kettlebell to the ground. It targets the hamstrings, glutes, and lower back while also improving balance and stability."]', 'wger', 0),
('kettlebell-one-legged-deadlift-2', 'Kettlebell One-Legged Deadlift', NULL, 'strength', 'hinge', 'compound', 'pull', 'unilateral', 'intermediate', NULL, NULL, NULL, 0),
