('knee-circle', 'Knee Circles', NULL, 'stretching', NULL, 'compound', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('knee-hip-raise-parallel-bars', 'Knee/Hip Raise On Parallel Bars', NULL, 'strength', 'isolation_other', 'isolation', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('knee-push-up', 'knee push-ups', NULL, 'strength', 'horizontal_push', NULL, NULL, 'bilateral', NULL, NULL, '["Start by kneeling on the floor, keeping your knees together. Place your hands on the floor in front of you, slightly wider than shoulder-width apart.", "Make sure your body forms a straight line from head to knees. Hands should be positioned below shoulders.", "Lower your torso towards the ground, bending your elbows while keeping your trunk stable. Keep your knees in contact with the floor.", "Push through your hands to return to the starting position. Be sure to maintain contraction of chest, shoulder and arm muscles at the top of the movement.", "Perform the desired number of repetitions, controlling the movement and maintaining good form."]', 'wger', 0),
('knee-raise', 'Knee Raises', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["The 90° leg raise on the bar is a very intense exercise that involves all the abdominal muscles."]', 'wger', 0),
('knee-to-chest-stretch', 'Knee to Chest Stretch', NULL, 'stretching', NULL, NULL, NULL, NULL, NULL, NULL, '["The knee to chest stretch is a simple yet effective exercise for relieving lower back tension and improving hip mobility. To perform, lie flat on your back with your legs extended. Bring one knee toward your chest, wrapping your hands around your shin or behind your thigh. Gently pull the knee closer to your chest while keeping the other leg straight on the floor. Hold the stretch for 15–30 seconds, then switch sides. For a deeper stretch, both knees can be pulled toward the chest simultaneously."]', 'wger', 0),
('knee-tuck-jump', 'Knee Tuck Jump', NULL, 'plyometrics', NULL, 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('kneeling-ab-wheel-roll-out', 'Kneeling Ab Wheel Roll-Out', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Kneel on the floor with an ab wheel in front of you.", "Place your hands on the ab wheel handles, shoulder-width apart.", "Engage your core and slowly roll the ab wheel forward, keeping your arms straight and your back flat.", "Continue rolling out until your body is fully extended and your arms are overhead.", "Pause for a moment, then slowly roll the ab wheel back towards your knees.", "Repeat."]', 'longhaul-fitness', 0),
('kneeling-arm-drill', 'Kneeling Arm Drill', NULL, 'plyometrics', NULL, NULL, 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('kneeling-forearm-stretch', 'Kneeling Forearm Stretch', NULL, 'stretching', NULL, 'isolation', 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('kneeling-hip-flexor', 'Kneeling Hip Flexor', NULL, 'stretching', NULL, 'isolation', 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('kneeling-reclining-hero-pose-pillow', 'Kneeling Reclining Hero Pose – Pillow', NULL, 'mobility', NULL, NULL, NULL, NULL, NULL, NULL, '["Kneel on a padded and stable surface.", "Place a thick cushion or pillow directly behind you.", "Sit on the floor with your bum between your feet.", "Recline back with your upper body until your upper back is fully supported by the pillow.", "Keep your arms straight overhead.", "Hold the stretch for the desired time."]', 'longhaul-fitness', 0),
('kroc-row', 'Kroc Row', NULL, 'strength', 'horizontal_pull', NULL, NULL, NULL, NULL, NULL, '["Dumbbell rows with looser technique but heavier weight."]', 'wger', 0),
('l-sit', 'L-sit', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Sit on the ground with your legs together and your arms by your sides. Push your body off the ground using your hands, maintaining the same sitting position so that your legs are straight and your feet do not touch the floor.", "Hold for as long as required."]', 'wger', 0),
('l-sit-foot-supported', 'L-Sit (Foot Supported)', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["As with an L-sit, but allow your feet to touch the floor to support the some of the weight of your legs."]', 'wger', 0),
('landmine-rotation', 'Landmine Rotation', NULL, 'strength', 'rotation', NULL, NULL, NULL, NULL, NULL, '["Place one end of a barbell securely into a landmine attachment or a corner to stabilize it.", "Stand with your feet shoulder-width apart, facing the end of the barbell, and grab the end of the bar with both hands.", "Press the barbell up and hold it in front of your head with your arms extended, while keeping your elbows slightly bent.", "Begin to rotate your torso to one side; as you do, allow your hands holding the barbell to drop towards the hip on the same side as the rotation. During the rotation, keep your arms in the same position, extended with elbows bent, as much as possible.", "Simultaneously, allow the foot you are rotating away from to rise up to the ball of the foot at the bottom of the rotation, facilitating a full rotation of the hips.", "Reverse the direction and rotate your torso to the opposite side, repeating the arm movement and foot pivot to complete one full repetition.", "Continue alternating the rotational movements for the desired number of repetitions, maintaining the appropriate arm and foot mechanics throughout."]', 'longhaul-fitness', 0),
('lat-pull-down', 'Lat Pull Down', NULL, 'strength', 'vertical_pull', NULL, NULL, 'bilateral', NULL, NULL, '["The lat pull down is an exercise used to build the muscles of the back. While the exercise will primarily target the lats, you will also notice a fair amount of bicep and middle back activation."]', 'wger', 0),
('lat-pull-down-leaning-back', 'Lat Pull Down (Leaning Back)', NULL, 'strength', 'vertical_pull', NULL, NULL, 'bilateral', NULL, NULL, '["Lean Back, Pull into chest"]', 'wger', 0),
('lat-pull-down-straight-back', 'Lat Pull Down (Straight Back)', NULL, 'strength', 'vertical_pull', NULL, NULL, 'bilateral', NULL, NULL, '["Pull bar down to strenum and keep straight back."]', 'wger', 0),
('lat-pulldown-cross-body-single-arm', 'Lat Pulldown - Cross Body Single Arm', NULL, 'strength', 'vertical_pull', NULL, NULL, 'unilateral', NULL, NULL, '["Sit at lat pulldown machine with body at a diagonal angle so that only one leg is under the pad. Pull the cable down with the opposite arm. this will force the cable to across your body while pulling down. Emphasises the stretch of the lat."]', 'wger', 0),
('lateral-bound', 'Lateral Bound', NULL, 'plyometrics', NULL, 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('lateral-box-jump', 'Lateral Box Jump', NULL, 'plyometrics', NULL, 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('lateral-cone-hop', 'Lateral Cone Hops', NULL, 'plyometrics', NULL, 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('lateral-push-off', 'Lateral Push Off', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Push off the ground and land on one leg and regain balance before jumping to the other leg"]', 'wger', 0),
('lateral-walk', 'Lateral Walk', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Lateral walks, also known as side steps or squat walks, are a type of exercise where you move sideways in a squatting position. They can be performed with or without resistance bands. These exercises strengthen the hip abductors, glutes, and other stabilizing muscles."]', 'wger', 0),
('leg-curl', 'Leg Curl', NULL, 'strength', 'isolation_other', NULL, NULL, NULL, NULL, NULL, '["The leg curl, also known as the hamstring curl, is an isolation exercise that targets the hamstring muscles. The exercise involves flexing the lower leg against resistance towards the buttocks. Other exercises that can be used to strengthen the hamstrings are the glute-ham raise and the deadlift."]', 'wger', 0),
('leg-curl-laying', 'Leg Curls (laying)', 'Beinbeuger Liegend', 'strength', 'isolation_other', NULL, NULL, NULL, NULL, NULL, '["Lie face down on a leg curl machine with your legs fully extended and your ankles against the padded lever.", "Grasp the handles on the machine for stability.", "Engage your core and squeeze your glutes.", "Bend your knees to curl the lever towards your glutes, keeping your upper legs stationary.", "Pause for a moment at the top of the movement, feeling the contraction in your hamstrings.", "Slowly lower the lever back to the starting position, fully extending your legs.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('leg-curl-sitting', 'Leg Curls (sitting)', NULL, 'strength', 'isolation_other', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0),
('leg-extension', 'Leg Extension', 'Beinstrecker', 'strength', 'isolation_other', NULL, NULL, NULL, NULL, NULL, '["The leg extension is a resistance weight training exercise that targets the quadriceps muscle in the legs. The exercise is done using a machine called the Leg Extension Machine. There are various manufacturers of these machines and each one is slightly different. Most gym and weight rooms will have the machine in their facility. The leg extension is an isolated exercise targeting one specific muscle group, the quadriceps. It should not be considered as a total leg workout, such as the squat or deadlift. The exercise consists of bending the leg at the knee and extending the legs, then lowering them back to the original position."]', 'wger', 0),
('leg-lift', 'Leg Lift', NULL, 'strength', 'isolation_other', 'isolation', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('leg-press', 'Leg Press', 'Beinpresse', 'strength', 'squat', NULL, NULL, 'bilateral', NULL, NULL, '["The leg press is a weight training exercise in which the individual pushes a weight or resistance away from them using their legs."]', 'wger', 0),
('leg-press-narrow', 'Leg Presses (narrow)', 'Beinpresse Eng', 'strength', 'squat', NULL, NULL, 'bilateral', NULL, NULL, '["The exercise is very similar to the wide leg press:", "Sit on the machine and put your feet on the platform so far apart that you could just put another foot in between them. The feet are parallel and point up.", "Lower the weight so much, that the knees form a right angle. Push immediately the platform up again, without any pause. When in the lower position, the knees point a bit outwards and the movement should be always fluid."]', 'wger', 0),
('leg-press-toe', 'Leg Press Toe Press', NULL, 'strength', 'squat', NULL, NULL, 'bilateral', NULL, NULL, '["Move the leg press using your calves by placing your feet at the bottom of the platform."]', 'wger', 0),
('leg-press-wide', 'Leg Presses (wide)', NULL, 'strength', 'squat', NULL, NULL, 'bilateral', NULL, NULL, '["Sit on the machine and put your feet on the platform, a bit more than shoulder wide. The feet are turned outwards by a few degrees.", "Lower the weight so much, that the knees form a right angle. Push immediately the platform up again, without any pause. When in the lower position, the knees point a bit outwards and the movement should be always fluid."]', 'wger', 0),
('leg-raise', 'Leg Raise', 'Beine heben', 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["The leg raise is a strength training exercise which targets the iliopsoas (the anterior hip flexors). Because the abdominal muscles are used isometrically to stabilize the body during the motion, leg raises are also often used to strengthen the rectus abdominis muscle and the internal and external oblique muscles."]', 'wger', 0),
('leg-raise-lying', 'Leg Raises, Lying', 'Beinheben Liegend', 'strength', 'isolation_other', 'isolation', 'pull', NULL, 'beginner', NULL, '["Lay down on a bench and hold onto the recliner with your hands to keep you stable. Hold your legs straight and lift them till they make an angle of about 45°. Make a short pause of 1 sec. and go slowly down to the initial position. To increase the intensity you can make a longer pause of 7 sec. every 5th time."]', 'wger', 0),
('leg-raise-pull-up-bar', 'Leg raises pull up bar', NULL, 'strength', 'vertical_pull', NULL, NULL, 'bilateral', NULL, NULL, '["with a firm grip with both hands on the bar, raise your outstretched legs, until you reach a 90° angle with your torso."]', 'wger', 0),
('leg-swing-frontback', 'Leg Swings (Front–Back)', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Stand tall next to a wall or stable support. Swing one leg forward and backward in a controlled motion, keeping the torso upright and the core engaged. Alternate legs after completing the repetitions."]', 'wger', 0),
('leg-up-hamstring-stretch', 'Leg-Up Hamstring Stretch', NULL, 'stretching', NULL, 'isolation', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('leg-wheel', 'Leg Wheel', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Lay on the back and lift legs in perpendicular fashion, keeping the knees together.", "Start making small circles in one direction with both of your knees with very small range of motion, focusing on abs and keeping your back in contact with the floor."]', 'wger', 0),
('legend-incline-bench-press', 'Legend Incline Bench Press', NULL, 'strength', 'horizontal_push', NULL, NULL, NULL, NULL, NULL, '["incline bench press on LeverEdge machine."]', 'wger', 0),
('levitation-crunch', 'Levitation Crunch', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["For this top down movement, we’re trying to move the upper torso without moving the lower torso. Start lying on the ground with feet flat on the floor and crossed arms above your head with hands behind head. Lift upper body up and clear your shoulder blades off the ground and then hold and pause at the top for a one or two count. Try to make the upper abs work and hold that contraction for 10 good quality reps."]', 'wger', 0),
('linear-3-part-start-technique', 'Linear 3-Part Start Technique', NULL, 'plyometrics', NULL, 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('linear-acceleration-wall-drill', 'Linear Acceleration Wall Drill', NULL, 'plyometrics', NULL, 'compound', NULL, NULL, 'beginner', NULL, NULL, NULL, 0),
('linear-depth-jump', 'Linear Depth Jump', NULL, 'plyometrics', NULL, 'compound', 'push', NULL, 'intermediate', NULL, NULL, NULL, 0),
('log-lift', 'Log Lift', NULL, 'strongman', NULL, 'compound', 'push', NULL, 'intermediate', NULL, NULL, NULL, 0),
('london-bridge', 'London Bridges', NULL, 'strength', NULL, 'compound', 'pull', NULL, 'intermediate', NULL, NULL, NULL, 0),
('long-pulley-low-row', 'Long-Pulley (low Row)', 'Long-Pulley', 'strength', 'horizontal_pull', NULL, NULL, NULL, NULL, NULL, '["Sit down, put your feet on the supporting points and grab the bar with a wide grip. Pull the weight with a rapid movement towards your belly button, not upper. Keep your arms and elbows during the movement close to your body. Your shoulders are pulled together. Let the weight slowly down till your arms are completely stretched."]', 'wger', 0),
('long-pulley-narrow', 'Long-Pulley, Narrow', 'Long-Pulley (eng)', 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["The exercise is the same as the regular long pulley, but with a narrow grip:", "Sit down, put your feet on the supporting points and grab the bar with a wide grip. Pull the weight with a rapid movement towards your belly button, not upper. Keep your arms and elbows during the movement close to your body. Your shoulders are pulled together. Let the weight slowly down till your arms are completely stretched."]', 'wger', 0),
('looking-at-ceiling', 'Looking At Ceiling', NULL, 'stretching', NULL, 'isolation', 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('lower-back-curl', 'Lower Back Curl', NULL, 'stretching', NULL, NULL, 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('lunge-bodyweight', 'Lunges', 'Ausfallschritte', 'strength', 'lunge', NULL, NULL, NULL, NULL, NULL, '["Stand with your feet shoulder-width apart and your hands on your hips.", "Step forward with one leg, bending your knee until your thigh is parallel to the ground.", "Keep your back straight and your core engaged.", "Push through your front heel to return to the starting position.", "Repeat with the other leg."]', 'longhaul-fitness', 0),
('lying-bent-leg-groin', 'Lying Bent Leg Groin', NULL, 'stretching', NULL, NULL, 'static', NULL, 'advanced', NULL, NULL, NULL, 0),
('lying-crossover', 'Lying Crossover', NULL, 'stretching', NULL, NULL, 'static', NULL, 'advanced', NULL, NULL, NULL, 0);
INSERT INTO exercises (id, name_en, name_de, category, movement_pattern, mechanic, force, laterality, level, variation_of, instructions, instructions_source_id, needs_review) VALUES
('lying-glute', 'Lying Glute', NULL, 'stretching', NULL, NULL, 'static', NULL, 'advanced', NULL, NULL, NULL, 0),
('lying-hamstring', 'Lying Hamstring', NULL, 'stretching', NULL, NULL, 'static', NULL, 'advanced', NULL, NULL, NULL, 0),
('lying-hamstring-bridge', 'Lying Hamstring Bridge', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Lie down on your back with your knees bent at about 110 degrees.", "Keep your heels planted on the floor and raise your toes up.", "Engage your core to maintain a neutral spine.", "Lift your pelvis off the ground, squeezing your hamstrings and glutes.", "Hold the lifted position for a moment, ensuring your spine remains neutral.", "Slowly lower your pelvis back down to the starting position.", "Repeat the movement for your desired number of repetitions."]', 'longhaul-fitness', 0),
('lying-overhead-shoulder-rotation-dowel', 'Lying Overhead Shoulder Rotation – Dowel', NULL, 'mobility', NULL, NULL, NULL, NULL, NULL, NULL, '["Lie on your back holding a dowel with both hands above your chest, hands shoulder-width apart, with straight arms.", "Lower the dowel over over your head by flexing your shoulders, keeping arms straight.", "Hold the end range stretch for the desired amount of time."]', 'longhaul-fitness', 0),
('lying-prone-quadriceps', 'Lying Prone Quadriceps', NULL, 'stretching', NULL, NULL, NULL, NULL, 'advanced', NULL, NULL, NULL, 0),
('lying-triceps-extension', 'Lying Triceps Extensions', NULL, 'strength', 'elbow_extension', NULL, NULL, 'bilateral', NULL, NULL, '["Starting position for this practical triceps exercise is lying on a standard bench holding a barbell or two dumbbells in both hands with an overhand grip, hands at shoulder width apart.", "Begin with arms over your upper chest and elbows bent back at about a 45-degree angle.", "First bend at the elbows and then allow the upper arm to drop back, bringing the barbell/dumbbells behind your head and down toward the floor. In terms of upper arm position, the barbell/dumbbells should never be fully above your head, but instead behind it, to ensure that you’re targeting the triceps.", "Keep the shoulder blades tucked under, the elbows tight in toward your head and your core active during this entire movement."]', 'wger', 0),
('lying-windshield-wiper', 'Lying Windshield Wiper', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Lie flat on your back with your arms extended out to the sides, palms down, and your legs extended straight up towards the ceiling.", "Keep your feet together and engage your core muscles by drawing your navel towards your spine.", "Lower your legs to one side, keeping them straight and close to the floor without touching it.", "Pause briefly and then lift your legs back up to the starting position.", "Repeat the movement, this time lowering your legs to the opposite side.", "Continue alternating sides for the desired number of reps or time."]', 'longhaul-fitness', 0),
('lying-windshield-wiper-bent-knees', 'Lying Windshield Wiper with Bent Knees', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Start by lying flat on your back with your arms extended out to the sides and your palms facing down.", "Bend your knees and lift your feet off the ground, keeping your shins parallel to the floor.", "Slowly lower your legs to one side, keeping your knees bent and your feet together.", "Pause for a moment, then use your core muscles to lift your legs back to the starting position.", "Repeat the movement to the other side, alternating sides for the desired number of repetitions."]', 'longhaul-fitness', 0),
('machine-ab-crunch', 'Ab Crunch Machine', NULL, 'strength', 'isolation_other', 'isolation', 'pull', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('machine-bench-press', 'Bench Press – Machine', NULL, 'strength', 'horizontal_push', 'compound', 'push', NULL, 'beginner', NULL, '["Adjust the bench and seat height so that your chest aligns with the bench press machine''s handles and your feet are flat on the floor.", "Select the appropriate weight on the weight stack.", "Sit on the machine with your back flat against the back pad.", "Grasp the handles with a firm grip, keeping your wrists straight. This is the starting position.", "Press the handles away from your chest, keeping your elbows at about a 45-degree angle from your body, extending your arms fully without locking your elbows.", "Pause briefly at the top of the press.", "Slowly lower the handles back to the starting position, maintaining control throughout the movement.", "Repeat the press for the desired number of repetitions."]', 'longhaul-fitness', 0),
('machine-biceps-curl', 'Biceps Curl Machine', NULL, 'strength', 'elbow_flexion', 'isolation', 'pull', NULL, 'beginner', NULL, '["Adjust the seat height and position yourself comfortably on the machine.", "Grasp the handles with an underhand grip, palms facing up.", "Keep your back straight and your elbows close to your sides.", "Exhale and slowly curl the handles towards your shoulders, contracting your biceps.", "Pause for a moment at the top of the movement, squeezing your biceps.", "Inhale and slowly lower the handles back to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('machine-bicycling-stationary', 'Bicycling, Stationary', NULL, 'cardio', 'locomotion', NULL, NULL, NULL, 'beginner', NULL, NULL, NULL, 0),
('machine-butterfly', 'Butterfly', NULL, 'strength', 'isolation_other', 'isolation', 'pull', NULL, 'beginner', NULL, NULL, NULL, 1),
('machine-calf-press', 'Calf Press', NULL, 'strength', 'isolation_other', 'isolation', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('machine-calf-press-leg', 'Calf Press Using Leg Press Machine', 'Wadendrücken an Beinpresse', 'strength', 'squat', 'isolation', 'push', 'bilateral', 'beginner', NULL, '["Put the balls of your feet on an extended leg press pad. Use your calves to press the weight by flexing your feet/toes into a pointed position, and releasing back into a relaxed position.", "This exercise builds mass and strength in the Gastrocnemius and Soleus muscles as well, if not better, than any calf exercise."]', 'wger', 0),
('machine-calf-raise', 'Calf Raise – Machine', NULL, 'strength', 'isolation_other', NULL, NULL, NULL, NULL, NULL, '["Stand on calf raise machine with the balls of your feet on the edge and your heels hanging off.", "Slowly raise your heels as high as possible, keeping your knees straight.", "Hold the position, then lower your heels back down below the level of the raised surface.", "Repeat."]', 'longhaul-fitness', 0),
('machine-calf-raise-hack-squat', 'Calf Raise using Hack Squat Machine', NULL, 'strength', 'isolation_other', NULL, NULL, 'bilateral', NULL, NULL, '["Ideally using a trapeze addon, Lift the weight up using your calves by getting on your toes."]', 'wger', 0),
('machine-calf-raise-hackenschmitt', 'Calf Raises on Hackenschmitt Machine', 'Wadenheben an Hackenschmidt', 'strength', 'isolation_other', NULL, NULL, NULL, NULL, NULL, '["Place yourself on the machine with your back firmly against the backrest, the feet are on the platform for calf raises. Check that the feet are half free and that you can completely stretch the calf muscles down.", "With straight knees pull up your weight as much as you can. Go with a fluid movement down till the calves are completely stretched. Repeat."]', 'wger', 0),
('machine-calf-raise-leg-press', 'Calf Raise – Leg Press Machine', NULL, 'strength', 'isolation_other', NULL, NULL, 'bilateral', NULL, NULL, '["Sit on the leg press machine and position your feet about hip-width apart on the lower part of the platform.", "Ensure that only the balls of your feet and your toes are making contact with the platform, with your heels hanging off.", "Straighten your legs to release the safety bars of the machine, keeping your knees slightly bent to avoid locking them.", "Press through the balls of your feet to push the platform away, raising your heels as high as possible and contracting your calf muscles.", "Pause at the top of the movement for a moment to maximize the contraction in the calves.", "Slowly lower your heels back below the level of the platform to return to the starting position and stretch your calf muscles.", "Repeat for the desired number of reps."]', 'longhaul-fitness', 0),
('machine-calf-shoulder-shrug', 'Calf-Machine Shoulder Shrug', NULL, 'strength', 'isolation_other', 'isolation', 'pull', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('machine-chair-squat', 'Chair Squat', NULL, 'strength', 'squat', 'compound', 'push', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('machine-chest-fly', 'Machine chest fly', NULL, 'strength', 'isolation_other', NULL, NULL, NULL, NULL, NULL, '["Adjust the seat height and position on the machine to ensure proper alignment with the handles.", "Extend your arms out to the sides, keeping a slight bend in your elbows. Grasp the handles and sit with your back flat against the pad.", "Inhale and slowly bring your arms together in front of your chest, keeping them slightly bent.", "Exhale and slowly return your arms to the starting position, maintaining a slight bend in your elbows.", "Repeat."]', 'longhaul-fitness', 0),
('machine-chest-press-exercise', 'Machine Chest Press Exercise', NULL, 'strength', 'horizontal_push', NULL, NULL, NULL, NULL, NULL, '["Adjust the seat height so that the handles are at chest level.", "Select the appropriate weight on the weight stack.", "Sit on the machine with your back flat against the backrest and your feet flat on the floor.", "Grasp the handles with an overhand grip and push them away from your chest until your arms are fully extended.", "Slowly lower the handles back towards your chest, keeping your elbows at a 90-degree angle.", "Repeat."]', 'longhaul-fitness', 1),
('machine-crunch', 'Crunches on Machine', 'Crunches an Maschine', 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["Adjust the seat height and foot pad position on the crunch machine to ensure proper alignment.", "Sit on the machine with your back against the backrest and your feet secured under the foot pads.", "Place your hands lightly on the sides of your head, avoiding pulling on your neck.", "Engage your core muscles by drawing your belly button in towards your spine.", "Exhale and slowly curl your upper body forward, contracting your abdominal muscles.", "Pause for a moment at the top of the movement, feeling the contraction in your abs.", "Inhale and slowly lower your upper body back to the starting position, maintaining control throughout the movement.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('machine-dip', 'Dip Machine', NULL, 'strength', NULL, 'compound', 'push', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('machine-eccentric-bicep-curl', 'Eccentric Bicep Curl – Machine', NULL, 'strength', 'elbow_flexion', NULL, NULL, NULL, NULL, NULL, '["Select the appropriate weight on the machine and adjust the seat and arm pad to align with your elbow joint.", "Grip the handles with your palms facing upward in a supinated position.", "Sit or stand (depending on machine design) with your upper arm pressed against the arm pad, back straight, and feet flat on the floor for stability.", "Use both arms to lift the weight with a controlled motion, flexing the elbows without swinging the arms or leaning back.", "Release the handle with one hand. Your other arm completely controls the weight.", "Gradually release the weight back to the starting position, emphasizing the downward movement—this is the eccentric phase—taking 3 to 4 seconds to lower the load.", "Make sure to fully extend the arms at the bottom, but avoid locking the elbows.", "Grip the handles with both hands and use both arms to lift the weight again.", "Release the handle with the other hand.", "Gradually release the weight back to the starting position again, focusing on the eccentric phase of a single bicep. This completes one full repetition.", "Repeat the movement for the desired number of reps, maintaining good form and controlled speed."]', 'longhaul-fitness', 0),
('machine-elliptical-trainer', 'Elliptical Trainer', NULL, 'cardio', 'locomotion', NULL, NULL, NULL, 'intermediate', NULL, NULL, NULL, 0),
('machine-flat-press', 'Flat Machine Press', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Execution", "Start position:", "Elbows bent at roughly 90°, hands just outside your chest.", "Keep wrists straight and aligned with your forearms.", "Pressing phase (concentric):", "Push the handles forward until your arms are almost fully extended — don’t lock out.", "Focus on squeezing your chest at the end of the movement.", "Returning phase (eccentric):", "Slowly bring the handles back toward your chest, feeling the stretch in your pecs.", "Maintain tension — don’t let the weight stack touch down between reps."]', 'wger', 0),
('machine-glute-ham-raise', 'Glute Ham Raise', NULL, 'strength', NULL, 'compound', 'pull', NULL, 'intermediate', NULL, NULL, NULL, 0),
('machine-glute-kickback', 'Glute Kickback (Machine)', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Adjust the machine to fit your body height", "Position yourself in the machine with your hands on the handles and one ankle on the padding.", "Keeping your core engaged, exhale and extend your leg back as far as possible while squeezing your glutes.", "Inhale and slowly return your leg to the starting position.", "Repeat."]', 'longhaul-fitness', 0),
('machine-hack-squat', 'Hack Squat – Machine', NULL, 'strength', 'squat', 'compound', 'push', 'bilateral', 'beginner', NULL, '["Adjust the seat height and foot platform of the machine to your desired position.", "Sit on the machine with your back against the pad and grasp the handles with an overhand grip.", "Engage your core throughout the exercise.", "Bend your knees and lower your body down, keeping your back straight and your heels on the foot platform.", "Continue descending until your thighs are parallel to the foot platform or as low as your flexibility allows.", "Push through your heels and extend your legs to return to the starting position.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 1),
('machine-hip-abduction', 'Machine Hip Abduction', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Adjust the machine to fit your height and leg length.", "Sit on the machine with your back against the backrest and your feet on the footrests.", "Press your legs outward against the resistance of the machine.", "With your knees at their farthest point, hold the weight for a moment before slowly releasing the resistance and returning to the starting position.", "Repeat."]', 'longhaul-fitness', 0),
('machine-hip-adduction', 'Hip Adduction – Machine', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Adjust the seat height of the hip adduction machine so that your knees are at a 90-degree angle when seated.", "Sit on the machine with your back against the backrest and your feet flat on the footrests.", "Place your thighs against the thigh pads, just above your knees.", "Grasp the handles on the sides of the machine for stability.", "Engage your core and squeeze your inner thighs together as you exhale.", "Hold the contraction for a second and then slowly release as you inhale.", "Repeat the movement for the desired number of repetitions."]', 'longhaul-fitness', 0),
('machine-hip-thrust', 'Hip Thrust – Machine', NULL, 'strength', 'hinge', NULL, NULL, 'bilateral', NULL, NULL, '["Adjust the machine to the appropriate height and resistance level.", "Sit on the machine with your back against the backrest and your feet flat on the foot platform.", "Engage your core and glutes, then press through your heels to extend your hips forward.", "Continue to drive your hips forward until your body is in a straight line from your knees to your shoulders.", "Hold the position for a brief moment, focusing on squeezing your glutes.", "Slowly lower your hips back down to the starting position, maintaining control throughout the movement.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('machine-jogging-treadmill', 'Jogging, Treadmill', NULL, 'cardio', 'locomotion', NULL, NULL, NULL, 'beginner', NULL, NULL, NULL, 0),
('machine-lateral-wise', 'Machine lateral wise', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["The machine lateral raise is an isolation exercise that targets the medial (side) deltoid muscle to build wider, more defined shoulders. The machine''s fixed path of motion provides greater stability than dumbbells, making it ideal for beginners or those who want to focus solely on muscle activation."]', 'wger', 0),
('machine-leg-extension', 'Leg Extensions', NULL, 'strength', 'isolation_other', 'isolation', 'push', NULL, 'beginner', NULL, NULL, NULL, 1),
('machine-leg-press', 'Leg Press – Machine', NULL, 'strength', 'squat', 'compound', 'push', 'bilateral', 'beginner', NULL, '["Adjust the seat of the leg press machine so that your knees are at a ~90-degree angle when your feet are on the footplate.", "Sit on the machine and place your feet shoulder-width apart on the footplate.", "Push the footplate away from your body by extending your legs.", "Lower the footplate back towards your body by bending your legs and keeping your feet flat on the plate.", "Repeat."]', 'longhaul-fitness', 1),
('machine-leg-press-hackenschmidt', 'Leg Press on Hackenschmidt Machine', 'Kniebeuge an Hackenschmidtmaschine', 'strength', 'squat', NULL, NULL, 'bilateral', NULL, NULL, NULL, NULL, 0),
('machine-leverage-chest-press', 'Leverage Machine Chest Press', NULL, 'strength', 'horizontal_push', 'compound', 'push', NULL, 'beginner', NULL, '["Be sure to adjust seat height so that the handles are towards the bottom of your pectorals."]', 'wger', 0),
('machine-leverage-deadlift', 'Leverage Deadlift', NULL, 'strength', 'hinge', 'compound', 'pull', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('machine-leverage-high-row', 'Leverage High Row', NULL, 'strength', 'horizontal_pull', 'compound', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('machine-leverage-iso-row', 'Leverage Machine Iso Row', NULL, 'strength', 'horizontal_pull', 'compound', 'pull', NULL, 'beginner', NULL, '["Adjust seat height so that the handles are at the bottom of your pectorals or just below."]', 'wger', 0),
('machine-leverage-shoulder-press', 'Leverage Shoulder Press', NULL, 'strength', 'vertical_push', 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('machine-leverage-shrug', 'Leverage Shrug', NULL, 'strength', 'isolation_other', 'isolation', 'pull', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('machine-lunge-sprint', 'Lunge Sprint', NULL, 'strength', 'lunge', 'compound', 'push', NULL, 'intermediate', NULL, NULL, NULL, 0),
('machine-lying-leg-curl', 'Lying Leg Curls', NULL, 'strength', 'isolation_other', 'isolation', 'pull', NULL, 'beginner', NULL, NULL, NULL, 1),
('machine-lying-squat', 'Lying Machine Squat', NULL, 'strength', 'squat', 'compound', 'push', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('machine-lying-t-bar-row', 'Lying T-Bar Row', NULL, 'strength', 'horizontal_pull', 'compound', 'pull', NULL, 'intermediate', NULL, NULL, NULL, 0),
('machine-overhead-tricep-extension', 'Overhead Tricep Extension – Machine', NULL, 'strength', 'elbow_extension', NULL, NULL, NULL, NULL, NULL, '["Adjust the seat height so your arms comfortably reach the handles with your elbows at a 90-degree angle.", "Sit down on the machine bench and grasp the handles with your palms facing each other.", "Keep your elbows close to your head and your back flat against the pad throughout the exercise.", "Exhale and extend your arms, pushing the handles overhead until your arms are fully extended but not locked.", "Pause momentarily at the top of the movement, focusing on contracting your triceps.", "Inhale as you slowly lower the handles back to the starting position, maintaining control and tension on the triceps.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('machine-preacher-curl', 'Machine Preacher Curls', NULL, 'strength', 'elbow_flexion', 'isolation', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('machine-pull-up', 'Pull Ups on Machine', 'Klimmzüge an Maschine', 'strength', 'vertical_pull', NULL, NULL, 'bilateral', NULL, NULL, NULL, NULL, 0),
('machine-pullover', 'Pullover Machine', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Pullover machine, sitting, elbows on pads"]', 'wger', 0),
('machine-recumbent-bike', 'Recumbent Bike', NULL, 'cardio', 'locomotion', NULL, NULL, NULL, 'beginner', NULL, NULL, NULL, 1),
('machine-reverse-fly', 'Reverse Fly – Machine', NULL, 'strength', 'isolation_other', 'isolation', 'pull', NULL, 'beginner', NULL, '["Adjust the seat height and chest pad of the machine to your comfort level.", "Sit on the machine with your chest against the pad and grasp the handles with an overhand grip.", "Keep your back straight and engage your core muscles.", "Exhale and slowly pull the handles back and away from your body, squeezing your shoulder blades together.", "Pause for a moment at the fully contracted position.", "Inhale and slowly return the handles to the starting position, maintaining control throughout the movement.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('machine-reverse-hyperextension', 'Reverse Hyperextension', NULL, 'strength', 'hinge', NULL, 'pull', NULL, 'intermediate', NULL, NULL, NULL, 0),
('machine-rotary-torso', 'Rotary Torso Machine', 'Bauch-Twist Gerät', 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Slow and Steady", "Not too much weight"]', 'wger', 0),
('machine-rowing-stationary', 'Rowing, Stationary', NULL, 'cardio', NULL, NULL, NULL, NULL, 'intermediate', NULL, NULL, NULL, 0),
('machine-running-treadmill', 'Running, Treadmill', NULL, 'cardio', 'locomotion', NULL, NULL, NULL, 'beginner', NULL, NULL, NULL, 0),
('machine-seated-row', 'Seated Row (Machine)', NULL, 'strength', 'horizontal_pull', NULL, NULL, NULL, NULL, NULL, '["Adjust the seat height so that the handles are at chest level.", "Sit on the machine with your feet flat on the footrests and your knees slightly bent.", "Grasp the handles with an overhand grip and keep your back straight.", "Pull the handles towards your chest while keeping your elbows close to your body.", "Pause for a moment and then slowly release the handles back to the starting position.", "Repeat."]', 'longhaul-fitness', 0),
('machine-shoulder-military-press', 'Machine Shoulder (Military) Press', NULL, 'strength', 'vertical_push', 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('machine-shoulder-press', 'Shoulder Press, on Machine', 'Schultermaschine', 'strength', 'vertical_push', NULL, NULL, NULL, NULL, NULL, '["Adjust the seat height so that the handles are at shoulder level.", "Sit on the machine with your back against the pad and your feet flat on the floor.", "Grasp the handles with an overhand grip and push them upward until your arms are fully extended.", "Slowly lower the handles back down to shoulder level, keeping your elbows slightly bent.", "Repeat for desired number of repetitions."]', 'longhaul-fitness', 0),
('machine-side-bend', 'Side Bends on Machine', 'Seitliches Oberkörperbeugen am Gerät', 'strength', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1),
('machine-side-lateral-raise', 'Machine Side Lateral Raises', NULL, 'strength', 'isolation_other', NULL, NULL, NULL, NULL, NULL, '["Adjust the seat height so that the handles are at shoulder level.", "Sit on the machine with your back against the pad and your feet flat on the floor.", "Grasp the handles with an overhand grip and keep your elbows slightly bent.", "Exhale and raise your arms out to the sides until they are parallel to the floor.", "Pause for a moment and then inhale as you slowly lower the handles back to the starting position.", "Repeat."]', 'longhaul-fitness', 0),
('machine-ski', 'Ski Machine', NULL, 'cardio', NULL, NULL, NULL, NULL, NULL, NULL, '["Start standing on the platform with your feet hip-width apart.", "Reach overhead to grip the handles with your palms facing in.", "Soften your knees, then simultaneously drive your butt back as if you''re closing a door behind you while pulling your arms straight down past your hips until your hands pass by the side of your knees.", "Next, bring your arms back overhead while thrusting your hips forward until you''re standing with your arms fully extended.", "Repeat for reps, time or distance."]', 'wger', 0),
('machine-squat-belt', 'Squat – Belt', NULL, 'strength', 'squat', NULL, NULL, 'bilateral', NULL, NULL, '["Add your desired weight to the machine.", "Attach a belt or harness around your waist.", "Attach a cable or chain to the belt or harness.", "Stand on a platform or box with feet shoulder-width apart.", "Hold onto a stable object for balance.", "Squat by bending the knees and hips while keeping the back straight.", "Pause at the bottom of the squat and then push up through the legs to return to the starting position.", "Repeat."]', 'longhaul-fitness', 1),
('machine-stairmaster', 'Stairmaster', NULL, 'cardio', 'locomotion', NULL, NULL, NULL, 'intermediate', NULL, NULL, NULL, 0),
('machine-step-mill', 'Step Mill', NULL, 'cardio', NULL, NULL, NULL, NULL, 'intermediate', NULL, NULL, NULL, 0),
('machine-thigh-abductor', 'Thigh Abductor', NULL, 'strength', 'isolation_other', 'isolation', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('machine-thigh-adductor', 'Thigh Adductor', NULL, 'strength', 'isolation_other', 'isolation', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('machine-torso-rotation', 'Torso Rotation Machine', NULL, 'strength', 'rotation', NULL, NULL, NULL, NULL, NULL, '["Adjust the seat and chest pad of the machine.", "Kneel on the knee pad with your chest against the chest pad.", "Grasp the handles with both hands and keep your elbows bent.", "Rotate your torso to the left as far as you comfortably can, while keeping your hips and legs stationary.", "Pause briefly at the end of the range of motion, then rotate your torso back to the starting position.", "Repeat the rotation to the right side, and continue alternating sides for the desired number of repetitions or time."]', 'longhaul-fitness', 0),
('machine-triceps', 'Triceps on Machine', 'Trizepsmaschine', 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Sit down and hold the bar firmly with your hands. Now press the weight upwards (don''t fully extend your arms) and lower it slowly again. As with other triceps exercises, it''s important not to move your upper arms."]', 'wger', 0),
('machine-triceps-extension', 'Machine Triceps Extension', NULL, 'strength', 'elbow_extension', 'isolation', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('machine-walking-treadmill', 'Walking, Treadmill', NULL, 'cardio', 'locomotion', NULL, NULL, NULL, 'beginner', NULL, NULL, NULL, 0),
('march-or-jog-in-place', 'March or jog in place', NULL, 'cardio', 'locomotion', NULL, NULL, NULL, NULL, NULL, '["Low-impact cardiovascular exercise that simulates running without moving, ideal for warming up, improving endurance, or training in small spaces."]', 'wger', 0),
('meadows-row', 'Meadows Row', NULL, 'strength', 'horizontal_pull', NULL, NULL, NULL, NULL, NULL, '["Place one end of a barbell in a corner to secure it, or use a landmine attachment if available.", "Stand next to the barbell so it is to your side, with your feet shoulder-width apart.", "Bend your knees slightly and hinge at the hips to lean forward, keeping your back straight.", "Grasp the barbell with one hand using an overhand grip, just above the weight plates.", "Place your other hand on your thigh or knee for support.", "Brace your core and row the barbell towards your armpit, keeping your elbow tucked in.", "Squeeze your back muscles at the top of the movement.", "Slowly lower the barbell back to the starting position.", "Repeat for the desired number of repetitions before switching sides."]', 'longhaul-fitness', 1),
('medicine-ball-backward-throw', 'Backward Medicine Ball Throw', NULL, 'plyometrics', NULL, 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('medicine-ball-booklet-crunch', 'Medicine ball booklet crunch', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["Using a medicine ball as an overload will make the exercise heavier."]', 'wger', 0),
('medicine-ball-catch-and-overhead-throw', 'Catch and Overhead Throw', NULL, 'plyometrics', NULL, 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('medicine-ball-chest-pass', 'Medicine Ball Chest Pass', NULL, 'plyometrics', NULL, 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('medicine-ball-chest-push-from-3-point-stance', 'Chest Push from 3 point stance', NULL, 'plyometrics', NULL, 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('medicine-ball-chest-push-multiple-response', 'Chest Push (multiple response)', NULL, 'plyometrics', NULL, 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('medicine-ball-chest-push-run-release', 'Chest Push with Run Release', NULL, 'plyometrics', 'locomotion', 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('medicine-ball-chest-push-single-response', 'Chest Push (single response)', NULL, 'plyometrics', NULL, 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('medicine-ball-full-twist', 'Medicine Ball Full Twist', NULL, 'plyometrics', NULL, 'compound', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('medicine-ball-overhead-slam', 'Overhead Slam', NULL, 'plyometrics', NULL, 'compound', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('medicine-ball-push-up', 'Push-Up – Medicine Ball', NULL, 'strength', 'horizontal_push', NULL, NULL, 'bilateral', NULL, NULL, '["Place a medicine ball on the ground and assume a plank position with your hands placed on the ball directly beneath your chest. Keep your feet together or slightly apart for better stability.", "Engage your core and maintain a straight line from your head to your heels, avoiding any sagging or arching in your lower back.", "Lower your body towards the ball by bending your elbows, keeping them close to your body. Go as low as you can without compromising your form.", "Push through your hands and chest to extend your arms and raise your body back up to the starting position.", "Repeat the movement for the desired number of reps, making sure to maintain proper form throughout the set."]', 'longhaul-fitness', 1),
('medicine-ball-return-push-from-stance', 'Return Push from Stance', NULL, 'plyometrics', NULL, 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('medicine-ball-rolling-push-up', 'Rolling Push-Up – Medicine Ball', NULL, 'strength', 'horizontal_push', NULL, NULL, 'bilateral', NULL, NULL, '["Begin by placing a medicine ball on the floor in front of you.", "Assume a push-up position by getting into a plank, with your hands shoulder-width apart and feet extended back.", "Position one hand on the center of the medicine ball, while the other remains on the floor, keeping your body straight and core engaged.", "Perform a push-up, lowering your chest to the floor while maintaining balance and stability on the ball.", "Push back up to the starting position, keeping your body in a straight line.", "Carefully roll the medicine ball across to the other hand while remaining in the plank position.", "Place your opposite hand on the medicine ball and stabilize your body.", "Repeat the push-up with the medicine ball under the other hand.", "Continue alternating hands after each push-up for the desired number of repetitions or sets."]', 'longhaul-fitness', 0),
('medicine-ball-rotational-slam', 'Rotational Slam – Medicine Ball', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Stand with your feet shoulder-width apart and knees slightly bent, holding the medicine ball with both hands near one hip.", "Begin the exercise by lifting the medicine ball in a circular motion on the same side, raising it up and over your head.", "Continue the circular motion bringing the ball down with force on the opposite side.", "As you bring the ball down, rotate your hips towards the opposite side, pivoting on the toes of one foot, while the other leg bends into a small squat.", "Release the medicine ball towards the ground as you near the opposite hip from where you started, channeling maximum force through the slam.", "Retrieve the medicine ball, return to the starting position on the opposite hip, and perform the exercise on the other side.", "Repeat the exercise for the desired number of repetitions."]', 'longhaul-fitness', 0),
('medicine-ball-rotational-throw', 'Rotational Throw – Medicine Ball', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Start by standing about arms-length away from the wall with your feet shoulder-width apart.", "Hold a medicine ball with both hands at chest height.", "Rotating your core and upper body towards the wall, explosively throw the ball against the wall.", "Catch the ball as it rebounds off the wall and rotate your body away from the wall.", "Repeat for the desired number of reps and then switch sides."]', 'longhaul-fitness', 0),
('medicine-ball-scoop-throw', 'Medicine Ball Scoop Throw', NULL, 'plyometrics', NULL, 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('medicine-ball-slam', 'Slam – Medicine Ball', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Stand with your feet shoulder-width apart, holding a medicine ball in front of you with both hands.", "Begin by raising the medicine ball above your head. As you lift the ball, come onto the balls of your feet, elevating your heels to maximize reach.", "From this fully extended position, drive your heels down to the ground as you explosively throw the ball onto the ground in front of you with as much force as possible, engaging your abs, shoulders, and arms.", "Squat down to pick up the ball after it bounces, keeping your back straight and chest up.", "Return to a standing position and lift the ball above your head again, coming onto your toes to prepare for the next slam.", "Repeat the sequence for the desired number of repetitions."]', 'longhaul-fitness', 0),
('medicine-ball-standing-two-arm-overhead-throw', 'Standing Two-Arm Overhead Throw', NULL, 'plyometrics', NULL, 'compound', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('medicine-ball-supine-chest-throw', 'Supine Chest Throw', NULL, 'plyometrics', NULL, 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('medicine-ball-supine-one-arm-overhead-throw', 'Supine One-Arm Overhead Throw', NULL, 'plyometrics', NULL, 'compound', 'pull', 'unilateral', 'beginner', NULL, NULL, NULL, 0),
('medicine-ball-supine-two-arm-overhead-throw', 'Supine Two-Arm Overhead Throw', NULL, 'plyometrics', NULL, 'compound', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('medicine-ball-twist', 'Medicine ball twist', NULL, 'strength', 'rotation', NULL, NULL, NULL, NULL, NULL, '["In a seated position, the torso is rotated from side to side without forcing, approaching the knees and making the ball touch the ground from time to time"]', 'wger', 1),
('medicine-ball-weighted-crunch', 'Weighted Crunches', NULL, 'strength', 'isolation_other', 'isolation', 'pull', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('middle-back-stretch', 'Middle Back Stretch', NULL, 'stretching', NULL, 'isolation', 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('mixed-grip-chin', 'Mixed Grip Chin', NULL, 'strength', NULL, 'compound', 'pull', NULL, 'advanced', NULL, NULL, NULL, 0),
('modified-pulldown', 'Modified pulldown', NULL, 'strength', 'vertical_pull', NULL, NULL, NULL, NULL, NULL, '["With an inclined bench in front of the pulldown machine, use a close-grip to do latfocused pulldowns."]', 'wger', 0),
('monkey-row', 'Monkey Row', NULL, 'strength', 'horizontal_pull', NULL, NULL, NULL, NULL, NULL, '["Start in a standing position with your feet shoulder-width apart and your knees slightly bent.", "Hold a dumbbell in each hand with your palms facing each other and your arms extended by your sides.", "Bend your elbows and pull the dumbbells up towards your armpits, keeping your elbows close to your body.", "Pause at the top of the movement and squeeze your shoulder blades together.", "Lower the dumbbells back down to the starting position.", "Repeat."]', 'longhaul-fitness', 0),
('mountain-climber', 'Mountain Climbers', NULL, 'plyometrics', NULL, 'compound', 'pull', NULL, 'beginner', NULL, '["Start in a high plank position with your hands shoulder-width apart and your wrists directly under your shoulders.", "Engage your core and bring your right knee towards your chest, keeping your foot off the ground.", "Quickly switch legs, bringing your left knee towards your chest while extending your right leg back.", "Continue alternating legs at a quick pace, as if you are running in place while in a plank position.", "Keep your hips low and your shoulders over your wrists throughout the exercise.", "Repeat."]', 'longhaul-fitness', 1),
('moving-claw-series', 'Moving Claw Series', NULL, 'plyometrics', NULL, 'compound', NULL, NULL, 'beginner', NULL, NULL, NULL, 0),
('muscle-up', 'Muscle up', NULL, 'strength', 'vertical_pull', NULL, NULL, 'bilateral', NULL, NULL, '["The body is then explosively pulled up by the arms in a radial pull-up, with greater speed than a regular pull-up. When the bar approaches the upper chest, the wrists are swiftly flexed to bring the forearms above the bar. The body is leaned forward, and the elbows are straightened by activating the triceps. The routine is considered complete when the bar is at the level of the waist and the arms are fully straight.", "To dismount, the arms are bent at the elbow, and the body is lowered to the floor, and the exercise can be repeated.", "As a relatively advanced exercise, muscle-ups are typically first learned with an assistive kip. The legs swing (kip) up and provide momentum to assist in the explosive upward force needed to ascend above the bar. More advanced athletes can perform a strict variation of the muscle-up which is done slowly, without any kip. This variation begins with a still dead hang and uses isometric muscle contraction to ascend above the bar in a slow, controlled fashion."]', 'wger', 0),
('muscle-up-2', 'Muscle Up', NULL, 'strength', 'vertical_pull', 'compound', 'pull', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('natural-glute-ham-raise', 'Natural Glute Ham Raise', NULL, 'strength', NULL, 'compound', 'pull', NULL, 'intermediate', NULL, NULL, NULL, 0),
('neck-smr', 'Neck-SMR', NULL, 'stretching', NULL, NULL, 'static', NULL, 'intermediate', NULL, NULL, NULL, 0),
('neck-twist-lacrosse-ball', 'Neck Twist – Lacrosse Ball', NULL, 'mobility', NULL, NULL, NULL, NULL, NULL, NULL, '["Place a massage or lacrosse ball against the front and outer side of your neck.", "Use your hand to gently compress the ball into the muscles.", "Slowly rotate your head to the opposite side to increase the stretch on the neck.", "Use small movements to massage the muscle group while maintaining gentle pressure.", "Hold the massage and stretch for the desired time and switch to the other side."]', 'longhaul-fitness', 0),
('negative-crunch', 'Negative Crunches', 'Crunches an Negativbank', 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["Sit yourself on the decline bench and fix your legs. Cross your arms over the chest and bring with a rolling movement your upper body up, go now without a pause and with a slow movement down again. Don''t let your head move during the exercise."]', 'wger', 0),
('neutral-grip-pull-up-or-trx-row', 'Neutral-grip pull-ups or TRX rows', NULL, 'strength', 'vertical_pull', NULL, NULL, 'bilateral', NULL, NULL, '["Pull-Up: Vertical Pull — Focuses more on the Lats (back width).", "TRX Row: Horizontal Pull — Focuses more on the Rhomboids/Traps (mid-back thickness and posture)."]', 'wger', 0),
('nordic-curl', 'Nordic Curl', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["The Nordic hamstring curl is one of the best lower-body exercises to build posterior leg strength, improve knee health, and prevent injury."]', 'wger', 0),
('nordic-hamstring-curl', 'Nordic Hamstring Curl', NULL, 'strength', 'isolation_other', NULL, NULL, NULL, NULL, NULL, '["Kneel on a padded surface, with your body upright and legs bent at a 90-degree angle at the knees.", "Secure your lower legs or ankles under a sturdy object, or have a partner hold them down.", "Cross your arms over your chest or place your hands on your thighs.", "Engage your core and glutes to keep your body straight from your knees to your head.", "Slowly lower your upper body towards the ground by extending your knees, keeping your torso straight.", "Descend as far as you can control, ideally until your body is nearly parallel to the floor.", "Use your hamstrings to pull your body back up to the starting position."]', 'longhaul-fitness', 1),
('oblique-crunch', 'Oblique Crunch', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["Lie on your back with your legs together, knees bent and feet flat on the ground. Drop both legs to the ground on your right side.", "Place your left hand behind your head and your right arm on the ground on your right side.", "Engage your core muscles and lift your shoulders off the ground, extending your left elbow towards your left quadricep. Flex your waist several inches to feel the contraction in your left oblique.", "Lower your shoulders back down to the ground and repeat for the desired number of repetitions.", "Continue alternating sides for the desired number of repetitions.", "Switch sides and repeat the exercise for the same number of repetitions."]', 'longhaul-fitness', 0),
('oblique-crunch-2', 'Oblique Crunches', NULL, 'strength', 'isolation_other', 'isolation', 'pull', 'bilateral', 'beginner', NULL, NULL, NULL, 1),
('oblique-crunch-floor', 'Oblique Crunches - On The Floor', NULL, 'strength', 'isolation_other', 'isolation', 'pull', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('oblique-sit-up', 'Oblique Sit-Up', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["Lie on your back with your knees bent and feet flat on the ground.", "Place your hands behind your head, with your elbows pointing out to the sides.", "Engage your core muscles by pulling your belly button in towards your spine.", "Slowly lift your upper body off the ground, twisting to one side, touching one elbow to the opposite knee.", "Exhale as you reach the top of the movement and hold for a second.", "Lower your upper body back down to the starting position, inhaling as you do so.", "Repeat the movement on the other side, twisting to the opposite side.", "Continue alternating sides for the desired number of repetitions."]', 'longhaul-fitness', 0),
('one-arm-against-wall', 'One Arm Against Wall', NULL, 'stretching', NULL, 'isolation', 'static', 'unilateral', 'beginner', NULL, NULL, NULL, 0),
('one-arm-bicep-wall-stretch', 'One-Arm Bicep Wall Stretch', NULL, 'stretching', NULL, NULL, NULL, 'unilateral', NULL, NULL, '["Raise one arm to shoulder height next to your body.", "Rotate your wrist so your palm faces down.", "Place your palm firmly against a doorframe, squat rack, or wall.", "Twist your body away from your anchored arm to stretch your biceps.", "Hold the stretch for the desired time and switch to the other side."]', 'longhaul-fitness', 0),
('one-arm-chin-up', 'One Arm Chin-Up', NULL, 'strength', 'vertical_pull', 'compound', 'pull', 'unilateral', 'advanced', NULL, NULL, NULL, 0),
('one-arm-front-bend-wall-push', 'One-Arm Front Bend Wall Push', NULL, 'mobility', NULL, NULL, NULL, 'unilateral', NULL, NULL, '["Stand facing a wall and place one hand flat against it at shoulder height.", "Step back slightly and bend forward at the hips, keeping your arm straight and pressed into the wall.", "Lift your arm upward along the wall to increase the stretch in the front of your shoulder.", "Keep your back flat and your core engaged to avoid arching.", "Hold the stretch for the desired time and switch to the other side."]', 'longhaul-fitness', 0),
('one-arm-front-shoulder-active-massage-lacrosse-ball', 'One-Arm Front Shoulder Active Massage – Lacrosse Ball', NULL, 'mobility', NULL, NULL, NULL, 'unilateral', NULL, NULL, '["Stand with a massage ball in one hand and your other arm, the target arm, in a natural position hanging by your side.", "Reach across your body to place a massage ball along a tender spot on the front of your target shoulder.", "Pin the massage ball in place and compress it within tolerable limits.", "Bend your target arm at the elbow so that there''s a right angle between your upper and lower arm. This is your starting position.", "Slowly extend your elbow behind you, keeping it close to your torso, to stretch your shoulder.", "Lift your elbow away from your body about 45°.", "Extend your arm in front of you, straightening the elbow, until you''re comfortably reaching forward.", "Return to the starting position, lowering your elbow close to your body, to complete the circlular motion and one repetition.", "Continue repetitions for the desired amount of time."]', 'longhaul-fitness', 0),
('one-arm-kneeling-spine-twist', 'One-Arm Kneeling Spine Twist', NULL, 'mobility', NULL, NULL, NULL, 'unilateral', NULL, NULL, '["Sit on your heels to isolate the movement from your low back.", "Place one palm flat on the floor and the other just behind your head or neck. This is your starting position.", "Rotate your upper body as far as you can or until your elbow points straight up to the ceiling.", "Hold the rotation for the desired amount of time.", "Slowly return to the start position.", "Repeat the exercise on the other side for the same time."]', 'longhaul-fitness', 0),
('one-arm-lunging-lower-back-wall-twist', 'One-Arm Lunging Lower Back Wall Twist', NULL, 'mobility', NULL, NULL, NULL, 'unilateral', NULL, NULL, '["Start in a split squat position with your front leg against the wall, foot flat on the ground. Place your back leg''s knee and toes on the ground.", "Raise the arm on the same side as your front leg parallel to the ground in front of you. Keep the back of your hand and forearm in contact with the wall.", "Rotate your torso slowly away from the front leg side, reaching your other arm back, parallel to the ground, to touch the back of that hand to the wall behind you.", "Keep your hips facing forward and chest open as you rotate.", "Hold the stretch for the desired time and switch to the other side."]', 'longhaul-fitness', 0),
('one-arm-lying-spine-twist-yoga-block', 'One-Arm Lying Spine Twist – Yoga Block', NULL, 'mobility', NULL, NULL, NULL, 'unilateral', NULL, NULL, '["Lie on your side with your top leg supported by a yoga block or foam roller.", "Extend both arms straight in front of you, palms together.", "Lift your top arm up towards the ceiling while keeping your legs stable. Your gaze should follow the top arm while it travels.", "Rotate your upper body, moving your top arm behind your back, face twisted towards the top arm, without lifting your leg off the support.", "Hold the pose for the desired amount of time before repeating the exercise on the other side."]', 'longhaul-fitness', 0),
('one-arm-posterior-shoulder-pull-dowel', 'One-Arm Posterior Shoulder Pull – Dowel', NULL, 'mobility', NULL, NULL, NULL, 'unilateral', NULL, NULL, '["Stand tall with a dowel held behind your back using both hands.", "Place one hand on the dowel at the small of your low back and the other hand behind your head on the dowel.", "Use your top arm to gently pull the target hand up between your shoulder blades.", "Hold the stretch for the desired amount of time and switch sides."]', 'longhaul-fitness', 0),
('one-arm-prone-rotator-cuff-external-rotation', 'One-Arm Prone Rotator Cuff External Rotation', NULL, 'mobility', NULL, NULL, NULL, 'unilateral', NULL, NULL, '["Lie on your belly on a padded surface, such as a yoga mat.", "Extend one arm out to the side, in line with your shoulder. Bend your elbow to a 90-degree angle to form a ''cactus'' or ''goalpost'' shape, with your forearm and palm resting on the floor.", "Keep your elbow pinned to the floor, ensuring it stays in contact with the floor throughout the movement.", "Rotate your hand towards the ceiling as high as possible, keeping the elbow pinned.", "Hold the position for the desired time.", "Repeat exercise on the other side."]', 'longhaul-fitness', 0),
('one-arm-seated-lower-back-rotation-stretch', 'One-Arm Seated Lower Back Rotation Stretch', NULL, 'stretching', NULL, NULL, NULL, 'unilateral', NULL, NULL, '["Sit on a stable surface with your legs extended in front of you.", "Place your opposite forearm between both thighs.", "Lean forward slightly and rotate your torso away from the side you want to stretch.", "Reach your back arm towards the ceiling.", "Use the arm between your thighs to provide additional leverage to assist in your rotation.", "Hold the stretch for the desired time and switch to the other side."]', 'longhaul-fitness', 0),
('one-arm-tabletop-spine-twist', 'One-Arm Tabletop Spine Twist', NULL, 'mobility', NULL, NULL, NULL, 'unilateral', NULL, NULL, '["Kneel down and sit back onto your heels.", "Place both elbows on the ground in front of you.", "Raise one arm and place your hand behind your head.", "Rotate your upper body towards the side with the raised arm, looking up.", "Hold the stretch for the desired time.", "Slowly return to the starting position.", "Repeat the stretch for the same time on the other side."]', 'longhaul-fitness', 0),
('one-armed-push-up', 'One armed push-ups', NULL, 'strength', 'horizontal_push', NULL, NULL, 'bilateral', NULL, NULL, '["Perform push-ups with one hand, alternating the sides"]', 'wger', 0),
('one-half-locust', 'One Half Locust', NULL, 'stretching', NULL, NULL, 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('one-handed-cross-body-curl', 'One-Handed Cross-Body Curl', NULL, 'strength', 'elbow_flexion', NULL, NULL, 'unilateral', NULL, NULL, '["Stand up, leaning slightly forward from a straight position, feet shoulder-width apart, and your knees slightly bent.", "Hold a dumbbell in each hand, with your palms facing your body and arms fully extended at your sides. This is your starting position.", "Keeping your elbows close to your body, slowly curl one dumbbell up toward your opposite shoulder, across your body.", "Continue curling until the weight comes close to the activating bicep''s shoulder. Squeeze your bicep before slowly lowering the weight to the starting position.", "Repeat the curl on the opposite side.", "Continue alternating curls on each side for the desired number of repetitions."]', 'longhaul-fitness', 0),
('one-handed-hang', 'One Handed Hang', NULL, 'stretching', NULL, NULL, 'static', 'unilateral', 'beginner', NULL, NULL, NULL, 0),
('one-knee-to-chest', 'One Knee To Chest', NULL, 'stretching', NULL, 'compound', 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('one-leg-bent-knee-calf-stretch-yoga-block', 'One-Leg Bent Knee Calf Stretch – Yoga Block', NULL, 'stretching', NULL, NULL, NULL, 'unilateral', NULL, NULL, '["Stand with one foot slightly ahead of the other as if you''d just taken one step forward.", "Place your forward foot on a yoga block, in the loop of a kettlebell, or anything stable you can step on with the ball of your foot at ankle height. Ensure your heel remains on the ground.", "Lean forward with both legs to create a stretch in the calf of the front leg.", "Bend the knee of the front leg to target the soleus muscle in your calf.", "Hold the stretch for the desired time and switch to the other side."]', 'longhaul-fitness', 0),
('one-leg-elevated-pigeon-stretch', 'One-Leg Elevated Pigeon Stretch', NULL, 'stretching', NULL, NULL, NULL, 'unilateral', NULL, NULL, '["Place your front leg on an elevated surface, such as a bench, with the shin flat on the surface and the knee rotated outward from your hip.", "Extend your back leg straight behind you on the ground.", "Drop your front hip down toward the ground.", "Support your upper body with your hands on the ground to maintain balance.", "Keep your spine neutral and avoid leaning forward or back.", "Take deep breaths, holding the stretch for the desired time, and switch sides."]', 'longhaul-fitness', 0),
('one-leg-foot-plank-yoga-block', 'One-Leg Foot Plank – Yoga Block', NULL, 'mobility', NULL, NULL, NULL, 'unilateral', NULL, NULL, '["Place two yoga blocks on the floor and stand so one foot is supported on the blocks at the heel and toes.", "Shift your weight onto the supported foot.", "Allow the ball of your big toe to drop below the level of the yoga block.", "Activate the muscles in your foot to lift the ball of your big toe back to a neutral position.", "Hold the lifted position for 5 to 7 seconds.", "Rest for the same amount of time.", "Continue repetitions for the desired amount of time."]', 'longhaul-fitness', 0),
('one-leg-incline-pigeon-stretch-bench', 'One-Leg Incline Pigeon Stretch – Bench', NULL, 'stretching', NULL, NULL, NULL, 'unilateral', NULL, NULL, '["Set up an exercise bench at a 30 to 45 degree incline.", "Place the outside calf of the leg you want to stretch on the inclined bench with the knee elevated above the foot. This calf should cross the center line of your body.", "Have the other leg supporting your bodyweight behind you.", "Drop the hip towards the ground and use your hands to support your body.", "Keep the spine neutral to isolate the stretch to the hips.", "Optionally, hinge forwards at the hips while maintaining a neutral spine to deepen the stretch.", "Hold the stretch for the desired time and switch to the other side."]', 'longhaul-fitness', 0),
('one-leg-incline-reverse-pigeon-bench', 'One-Leg Incline Reverse Pigeon – Bench', NULL, 'mobility', NULL, NULL, NULL, 'unilateral', NULL, NULL, '["Set up an exercise bench at a 30 to 45 degree incline.", "Place the shin of the leg you want to stretch on the inclined bench with the knee elevated above the foot.", "Position the other leg behind you to support your bodyweight.", "Drop the hip of the leg on the bench towards the ground and use your hands to support your body.", "Keep your spine neutral to focus the stretch on your hips.", "Hinge forward at the hips while maintaining a neutral spine to deepen the stretch.", "Hold the stretch for the desired time and switch to the other side."]', 'longhaul-fitness', 0),
('one-leg-kneeling-couch-quad-stretch', 'One-Leg Kneeling Couch Quad Stretch', NULL, 'stretching', NULL, NULL, NULL, 'unilateral', NULL, NULL, '["Stand in front of a couch, chair, or step stool.", "Bend your right knee to place the top of your right foot on the surface behind you.", "Bend your left knee to kneel to lower your body into a single-leg kneeling position.", "Lower your body until you feel a comfortable stretch or your right knee rests on the floor.", "Sit back towards your heel to increase the stretch in your quad.", "Hold the stretch for the desired time and switch to the other side to complete a set."]', 'longhaul-fitness', 0),
('one-leg-lying-ankle-nerve-floss', 'One-Leg Lying Ankle Nerve Floss', NULL, 'mobility', NULL, NULL, NULL, 'unilateral', NULL, NULL, '["Lie on your back on a padded surface with one thigh lifted to 90 degrees and supported by both both hands interlaced on the hamstring.", "Keep the raised knee as straight as possible without causing nerve tension.", "Keep the other leg straight and flat on the floor.", "Simultaneously lift your head off the ground and at your chest while pointing your toes away from you (plantarflex).", "Then, lower your head and look towards the ceiling while pulling your raised foot toward you (dorsiflex).", "Repeat the movement for the desired number of repetitions then switch sides."]', 'longhaul-fitness', 0),
('one-leg-lying-heel-slide', 'One-Leg Lying Heel Slide', NULL, 'strength', NULL, NULL, NULL, 'unilateral', NULL, NULL, '["Lie down on your back on a padded surface with the target leg straight.", "Wear a pair of socks or place a slider disc under the heel of the target leg. The goal is to be able to slide your heel on the floor.", "Engage your core and keep your non-working leg bent with the foot flat on the floor. This is your starting position.", "Slide your heel across the floor towards your buttocks, bending your knee as you go. Focus on contracting your hamstring on the sliding leg.", "Slowly slide your heel back down to return to the straight leg position.", "Repeat the movement for your desired number of repetitions then switch sides."]', 'longhaul-fitness', 0),
('one-leg-lying-outer-thigh-hip-twist', 'One-Leg Lying Outer Thigh Hip Twist', NULL, 'mobility', NULL, NULL, NULL, 'unilateral', NULL, NULL, '["Lie on your back with knees bent and feet flat on the floor.", "Cross one ankle over the opposite thigh just above the knee.", "Keep your upper back and shoulders pressed into the floor.", "Slowly rotate your hips away from the crossed leg, letting the bottom thigh fall toward the floor.", "Use the weight of the crossed leg to deepen the stretch in your outer hip.", "Hold the stretch for the desired time and switch to the other side."]', 'longhaul-fitness', 0),
('one-leg-lying-pretzel-stretch', 'One-Leg Lying Pretzel Stretch', NULL, 'stretching', NULL, NULL, NULL, 'unilateral', NULL, NULL, '["Lie on your back with your feet flat on the floor, knees bent.", "Place one ankle on the opposite knee by rotating the leg.", "Reach around the leg with the foot on the floor to grab that leg''s shin.", "Keep your back on the floor and pull your knee towards your chest.", "Hold the stretch for the desired time and switch to the other side."]', 'longhaul-fitness', 0),
('one-leg-prone-hip-extension', 'One-Leg Prone Hip Extension', NULL, 'strength', NULL, NULL, NULL, 'unilateral', NULL, NULL, '["Lie down on your stomach with your arms extended out in front of you for support.", "Engage your core to stabilize your lower back and minimize anterior pelvic tilt.", "Lift one heel up towards the ceiling while keeping the knee straight and the foot flexed.", "Hold the lifted position for 5-10 seconds, focusing on the contraction in the glutes and hamstrings.", "Slowly lower your leg back down to the ground.", "Repeat the movement on the same side for your desired number of repetitions, then switch to the other leg."]', 'longhaul-fitness', 0),
('one-leg-seated-ankle-crosses', 'One-Leg Seated Ankle Crosses', NULL, 'mobility', NULL, NULL, NULL, 'unilateral', NULL, NULL, '["Sit on a chair or a stable surface with your legs on the ground.", "Pull the target leg''s knee towards your chest. Leave the other foot on the ground for stability.", "You''re going to draw a bowtie shape, ''⋈'', with your with the toes of your target leg.", "Rotate your foot inwards and then outwards, exploring the full range of motion at the ankle.", "After completing the bowtie shape in one direction, reverse the direction you''re drawing with your foot.", "Repeat the shape, forward and backward, for the desired amount of time and switch to target the other leg."]', 'longhaul-fitness', 0),
('one-leg-seated-calf-release-lacrosse-ball', 'One-Leg Seated Calf Release – Lacrosse Ball', NULL, 'mobility', NULL, NULL, NULL, 'unilateral', NULL, NULL, '["Sit on a chair with both feet on the floor.", "Lift your target leg and cross it over the other leg so that the target leg''s ankle is resting on your other knee.", "Place a massage ball on the inner part of your shin bone.", "Apply pressure with the ball within tolerable limits.", "Start with the ball at the midpoint of your shin and move down towards the foot 1 inch at a time.", "Slowly and repeatedly rotate the ankle to point your foot towards the floor, then the ceiling, then back again to get an active release of the muscle.", "Complete 3-5 slow repetitions per tender spot.", "Continue the massage for the desired amount of time."]', 'longhaul-fitness', 0),
('one-leg-seated-pretzel-stretch', 'One-Leg Seated Pretzel Stretch', NULL, 'stretching', NULL, NULL, NULL, 'unilateral', NULL, NULL, '["Sit on a chair with your feet flat on the floor.", "Place one ankle on the opposite knee by rotating the leg.", "Push the folded knee towards the floor while leaning forward by hinging at the hips.", "Keep the spine neutral to uncouple motion between the hip and back.", "Hold the stretch for the desired time and switch to the other side."]', 'longhaul-fitness', 0),
('one-leg-seated-rock-paper-scissor-toes', 'One-Leg Seated Rock-Paper-Scissor Toes', NULL, 'mobility', NULL, NULL, NULL, 'unilateral', NULL, NULL, '["Sit on a chair or on the floor. Raise one foot off the floor, holding the leg up by the raised knee.", "Curl all toes to create the ''rock'' position.", "Return to neutral with toes relaxed.", "Spread all toes apart into the ''paper'' position.", "Extend the big toe while keeping other toes curled for the ''scissors'' position part one.", "Curl the big toe and extend the other four toes for the ''scissors'' position part two.", "Continue alternating between the ''rock'', ''paper'', and both ''scissors'' positions for the desired number of repetitions before switching to the other side."]', 'longhaul-fitness', 0),
('one-leg-wide-lunge', 'One-Leg Wide Lunge', NULL, 'mobility', NULL, NULL, NULL, 'unilateral', NULL, NULL, '["Start in a plank or push-up position with both hands on the floor.", "Step one foot forward, placing it just outside your hand on the same side.", "Keep the back leg extended straight behind you with toes tucked under.", "Lower your hips towards the floor to stretch the front leg''s hamstrings and glutes. Your back knee may touch the floor.", "Push your hips forward to stretch the hip flexors of the back leg.", "Hold the stretch for the desired time and switch to the other side."]', 'longhaul-fitness', 0),
('one-legged-balance', 'One-Legged Balance', NULL, 'strength', NULL, NULL, NULL, 'unilateral', NULL, NULL, '["Stand tall with your feet hip-width apart.", "Shift your weight onto one leg and lift the other leg off the ground.", "Engage your core muscles to maintain balance.", "Keep your standing leg slightly bent and your knee aligned with your toes.", "Find a focal point to help you maintain balance and focus.", "Hold the position for a desired amount of time.", "Switch legs and repeat the exercise."]', 'longhaul-fitness', 0),
('one-legged-hip-thrust', 'One-Legged Hip Thrust', NULL, 'strength', 'hinge', NULL, NULL, 'unilateral', NULL, NULL, '["Begin by lying on your back with your knees bent and feet flat on the ground.", "Extend one leg straight out, keeping it in line with your hip.", "Place your hands on the ground by your sides for support.", "Engage your glutes and lift your hips up towards the ceiling, keeping your extended leg straight.", "Pause at the top of the movement, then slowly lower your hips back down to the ground.", "Repeat for the desired number of reps, then switch legs."]', 'longhaul-fitness', 1),
('otis-up', 'Otis-Up', NULL, 'strength', NULL, 'compound', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('overhead-lat', 'Overhead Lat', NULL, 'stretching', NULL, NULL, 'static', NULL, 'advanced', NULL, NULL, NULL, 0),
('overhead-shrug-neck-rotation', 'Overhead Shrug Neck Rotation', NULL, 'mobility', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["Raise both arms with your elbows straight overhead.", "Shrug your shoulders upwards.", "Slowly rotate your head and neck completely to one side without dropping the shoulders.", "Rotate your head and neck completely to the opposite side.", "Return to neutral cervical spine rotation.", "Continue these rotations for the desired amount of time."]', 'longhaul-fitness', 0),
('overhead-stretch', 'Overhead Stretch', NULL, 'stretching', NULL, 'compound', 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('overhead-tricep-extension-bodyweight', 'Overhead Tricep Extension – Bodyweight', NULL, 'strength', 'elbow_extension', NULL, NULL, NULL, NULL, NULL, '["Set a stationary bar (ex. Smith Machine) at hip height", "Stand with your feet shoulder-width, lean forward, and grab the bar with your arms in front of you.", "Bend your elbows and lower your head forward and below the bar. Keep your elbows close to your ears.", "Squeeze your triceps to extend your arms to the starting position.", "Repeat."]', 'longhaul-fitness', 0),
('overhead-triceps', 'Overhead Triceps', NULL, 'stretching', NULL, NULL, 'static', NULL, 'advanced', NULL, NULL, NULL, 0),
('pallof-press', 'PALLOF PRESS', NULL, 'strength', 'anti_rotation', NULL, NULL, NULL, NULL, NULL, '["Stand side-on to a cable machine or secure a resistance band at chest height.", "Select an appropriate weight if using a cable machine.", "Grasp the handle (or end of the band) with both hands and take a step away to create tension.", "Position your feet shoulder-width apart for stability.", "Hold the handle or band close to your chest, keeping your hands centered in front of you.", "Engage your core muscles to stabilize your torso.", "Slowly press the handle or band straight out in front of your chest, keeping your arms straight.", "Ensure your hips and shoulders stay squared and facing forward throughout the movement.", "Hold the fully-pressed position for 1-2 seconds.", "Slowly return the handle or band back to your chest with control.", "Repeat for the desired number of repetitions.", "Switch sides and perform the exercise to work the core muscles evenly."]', 'longhaul-fitness', 0),
('parallel-bar-dip', 'Parallel Bar Dip', NULL, 'strength', NULL, 'compound', 'push', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('parallel-bar-hold', 'Parallel Bar Hold', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Stand between a set of parallel bars.", "Place your hands, knuckles outwards, on the bars.", "Push down on your hands to lift yourself off the floor.", "Hold yourself in this position with your arms straight for the required time."]', 'wger', 0),
('pec-deck', 'Pec Deck', NULL, 'strength', 'isolation_other', NULL, NULL, NULL, NULL, NULL, '["Sit on the Pec Deck machine with your back flat against the backrest and your feet firmly on the floor.", "Adjust the seat height so that the handles are at chest level.", "Grasp the handles with an overhand grip, keeping your elbows slightly bent.", "Exhale and push the handles together in front of your chest, squeezing your chest muscles.", "Hold the contraction for a second, then slowly release the handles back to the starting position.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('pelvic-tilt-into-bridge', 'Pelvic Tilt Into Bridge', NULL, 'stretching', NULL, 'compound', 'static', NULL, 'intermediate', NULL, NULL, NULL, 0),
('pendlay-row', 'Pendlay Row', NULL, 'strength', 'horizontal_pull', NULL, NULL, NULL, NULL, NULL, '["Load a barbell with weights on the floor.", "Stand with your feet shoulder-width apart and your knees slightly bent.", "Bend forward at the hips, keeping your back straight and parallel to the ground.", "Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.", "Keeping your upper body still and your elbows close to your body, pull the barbell up towards your chest, squeezing your shoulder blades together.", "Lower the barbell all the way back down to the floor. Completely release the tension of the weight for a brief moment while maintaining control and keeping your back straight.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('pendulum-squat', 'Pendulum Squat', 'Pendelkniebeube', 'strength', 'squat', NULL, NULL, 'bilateral', NULL, NULL, '["Place your feet in the middle of the plate at about shoulder width. Tense your torso. Keep your neck relaxed."]', 'wger', 0),
('perfect-hang', 'Perfect Hang', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Grasp a pull-up bar with both hands at shoulder-width apart using an overhand grip.", "Hang from the bar with your feet off the ground and your arms fully extended.", "Engage your shoulder blades by pulling them back and down to stabilize your shoulders and upper back.", "Lean back slightly to bring your chest parallel to the ground and your torso at a 45° angle to the ground.", "Curl your legs backwards. Imagine your body as the curve on the letter \"D\" if you were to see yourself from the side.", "Breathe deeply and hold the hang for as long as you can manage comfortably, ensuring your shoulder blades remain engaged."]', 'longhaul-fitness', 0),
('peroneals-stretch', 'Peroneals Stretch', NULL, 'stretching', NULL, NULL, 'static', NULL, 'intermediate', NULL, NULL, NULL, 0),
('pike-push-up', 'Pike Push Ups', 'Hecht-Liegestütze', 'strength', 'vertical_push', NULL, NULL, 'bilateral', NULL, NULL, '["Push Up performed from a pike position (optional to have feet elevated)."]', 'wger', 0),
('pistol-squat', 'Pistol Squat', 'Einbeinige Kniebeuge', 'strength', 'squat', NULL, NULL, 'unilateral', NULL, NULL, '["Stand with feet hip-width apart, toes pointed forward, and chest tall.", "Extend your leg straight out; extend both arms in front of you, at shoulder level. Brace your core and look straight ahead.", "Slowly squat down.", "(optional) pause at the bottom.", "Keep your (free) leg and arms extended for the whole duration."]', 'wger', 0),
('planche-de-cote-dynamique', 'Planche de cote dynamique', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0),
('plank', 'Plank', 'Plank', 'strength', 'isolation_other', 'isolation', 'static', 'bilateral', 'beginner', NULL, '["Get into a position on the floor supporting your weight on your forearms and toes. Arms are bent and directly below the shoulder.", "Keep your body straight at all times and hold this position as long as possible. To increase difficulty an arm or leg can be raised while performing this exercise."]', 'wger', 0),
('plank-2', 'Plank', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, NULL, NULL, 1),
('plank-alternating-leg-lift', 'Plank with Alternating Leg Lift', NULL, 'strength', NULL, NULL, NULL, 'alternating', NULL, NULL, '["In a plank position, lift one leg alternately."]', 'wger', 0),
('plank-jacks', 'Plank Jacks', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["Jumping jacks from the plank position."]', 'wger', 0),
('plank-pull-through', 'Plank Pull Through', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["Start in a high plank position with your hands positioned directly under your shoulders, feet slightly wider than hip-width apart, and a dumbbell or kettlebell placed on the floor on one side of your body at sternum-level.", "Reach under your torso with your opposite hand to grab the dumbbell.", "Pull the weight across the floor to the other side of your body while keeping your hips as stable as possible.", "Place the weight on the floor and return your hand to the starting plank position.", "Repeat the movement by reaching with the other hand to pull the dumbbell back to the starting side.", "Continue alternating sides for the desired number of reps or time duration."]', 'longhaul-fitness', 0),
('plank-shoulder-taps', 'Plank Shoulder Taps', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["In the correct plank position, place your feet slightly wider than shoulder-width apart. alternately lift and touch the opposite shoulder with one hand."]', 'wger', 0),
('plank-to-elbow-extension', 'Plank-to-Elbow Extension', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["The Plank-to-Elbow Extension is a dynamic exercise that combines the plank with an elbow extension movement"]', 'wger', 0),
('plate-alternating-side-lunge-pull', 'Alternating Side Lunge Pull – Plate', NULL, 'strength', 'lunge', NULL, NULL, 'alternating', NULL, NULL, '["Stand with a plate between your feet. This is your starting position.", "Take a step to the side with one leg, bending that knee to lower your body into a side lunge.", "Keep the other leg straight and your torso upright.", "As you push through the heel of your bent leg to return to the standing position, use your non-planted leg to pull the weight plate inwards.", "Continue pulling the plate inwards until you are fully standing with the plate close to your feet in the starting position.", "Repeat the movement on the other side to complete a single repetition.", "Continue for your desired number of repetitions, alternating legs with each lunge."]', 'longhaul-fitness', 0),
('plate-front-hold', 'Front Hold – Plate', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Stand with your feet shoulder-width apart and hold a weight plate with both hands in front of your chest.", "Engage your core and keep your back straight.", "Extend your arms fully, keeping your arms parallel to the ground.", "Hold this position for the desired amount of time."]', 'longhaul-fitness', 0),
('plate-front-raise', 'Front Plate Raise', NULL, 'strength', 'isolation_other', 'isolation', 'push', NULL, 'intermediate', NULL, '["Stand with your feet shoulder-width apart and hold a weight plate with both hands in front of your thighs.", "Keep your arms straight and slowly raise the weight plate up to shoulder level, making sure to keep your core engaged and your back straight.", "Pause for a moment at the top of the movement, then slowly lower the weight plate back down to the starting position.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('plate-lying-face-down-neck-resistance', 'Lying Face Down Plate Neck Resistance', NULL, 'strength', 'isolation_other', 'isolation', 'pull', NULL, 'intermediate', NULL, NULL, NULL, 0),
('plate-lying-face-up-neck-resistance', 'Lying Face Up Plate Neck Resistance', NULL, 'strength', 'isolation_other', 'isolation', 'pull', NULL, 'intermediate', NULL, NULL, NULL, 0),
('plate-one-handed-wrist-curl', 'One-Handed Plate Wrist Curl', NULL, 'strength', 'isolation_other', NULL, NULL, 'unilateral', NULL, NULL, '["Start by sitting on a bench or chair with your feet flat on the ground.", "Hold a weight plate with an underhand grip, placing your hand on the inside rim of the plate.", "Rest your forearm on your thigh, with your wrist hanging off the edge and pointing to the ceiling.", "Lower the weight plate towards the ground by flexing your wrist, keeping your forearm stationary.", "Pause for a moment at the bottom of the movement, feeling the stretch in your wrist.", "Slowly curl the weight plate back up towards your body.", "Repeat for the desired number of reps and then switch sides."]', 'longhaul-fitness', 0),
('plate-pinch', 'Plate Pinch', NULL, 'strength', 'isolation_other', 'isolation', 'static', NULL, 'intermediate', NULL, NULL, NULL, 0),
('plate-pinch-hold', 'Plate Pinch Hold', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["The plate pinch hold is a grip strength exercise designed to target the forearms and improve grip endurance. Select one or two weight plates (smooth-edged plates work best) and pinch them together between your thumb and fingers. Hold the plates with your arm straight down by your side or extended slightly in front of you. Maintain the hold for as long as you can, keeping your shoulders relaxed and your grip firm. This exercise can be done for time or repetitions."]', 'wger', 0),
('plate-reverse-curl', 'Reverse Plate Curls', NULL, 'strength', 'elbow_flexion', 'isolation', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('plate-squat-movers', 'Squat with Plate Movers', NULL, 'strength', 'squat', 'compound', 'push', 'bilateral', 'intermediate', NULL, NULL, NULL, 1),
('plate-standing-olympic-hand-squeeze', 'Standing Olympic Plate Hand Squeeze', NULL, 'strength', 'isolation_other', 'isolation', 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('plate-twist', 'Plate twist', NULL, 'strength', 'rotation', 'compound', 'pull', NULL, 'intermediate', NULL, '["Step 1: Sit on an exercise mat with your legs extended in front of you. Step 2: Grasp a plate in both hands as if holding a steering wheel, arms slightly bent, and hold it in front of your abdominals. Step 3: With knees slightly bent, cross your ankles and slowly lift them a few inches off the floor. Step 4: Keep your back straight but lean backward slightly to help maintain balance. Step 5: Exhaling, rotate your torso (twist) to the right side and touch the end of the plate to the floor. Step 6: Inhale and return to the forward facing start position. Step 7: Exhaling, rotate your torso (twist) to the left side and touch the end of the plate to the floor. Step 8: Inhale and return to the forward facing start position. Step 9: Repeat for a full set."]', 'wger', 0),
('platform-hamstring-slide', 'Platform Hamstring Slides', NULL, 'strength', 'isolation_other', 'isolation', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('plyo-push-up', 'Plyo Push-up', NULL, 'plyometrics', 'horizontal_push', 'compound', 'push', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('posterior-tibialis-stretch', 'Posterior Tibialis Stretch', NULL, 'stretching', NULL, NULL, 'static', NULL, 'intermediate', NULL, NULL, NULL, 0),
('power-clean', 'Power Clean', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Place a barbell on the ground and stand with your feet hip-width apart, toes under the bar.", "Bend at the hips and knees to grip the bar with an overhand grip slightly wider than shoulder width.", "Bend your knees until your shins touch the bar, keeping your back flat and chest up. This is your starting position.", "Lift the bar by extending your hips and knees, keeping the bar close to your body and your elbows straight.", "As the bar passes your knees, aggressively extend your hips, shrug your shoulders, and then pull yourself under the bar.", "Catch the bar in a partial squat position, with elbows forward and the bar resting on your shoulders.", "Stand up straight to complete the movement.", "Lower the bar to the ground carefully and set up for the next repetition.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 1),
('power-clean-and-press', 'Power Clean and Press', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Start with feet shoulder-width apart and the barbell on the floor in front of you.", "Bend down and grip the barbell with hands slightly wider than shoulder-width apart.", "Stand up, keeping your back straight, the barbell close to your shins, and lifting with your legs.", "As the barbell reaches your chest, quickly drop into a high squat position. The crease of your hips should be above the top of your thighs. Catch the barbell at shoulder height.", "Stand up from the squat position, lifting the barbell overhead with arms fully extended.", "Lower the barbell back down to shoulder height.", "Reverse the movement and lower the barbell back down to the floor and release your grip.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('power-jerk', 'Power Jerk', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Start with the barbell resting on your front shoulders, with your feet shoulder-width apart.", "Bend your knees slightly and dip your hips down.", "Quickly extend your legs and hips, driving the barbell upwards.", "As the barbell reaches its highest point, quickly drop underneath it, in a small squat.", "As you catch the barbell overhead, straighten your legs and stand up.", "Lower the barbell back down to your front shoulders to complete the rep.", "Repeat."]', 'longhaul-fitness', 0),
('power-snatch', 'Power Snatch', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Start with feet hip-width apart, toes slightly turned out, with a loaded barbell on the ground in front of you.", "Hold the barbell with a wide grip, hands outside the legs.", "Bend at the knees and hips, keeping the back straight and chest up.", "Explosively extend the hips, knees, and ankles, pulling the barbell upwards.", "As the barbell reaches hip level, quickly drop under it by pulling yourself down into a squat position.", "Catch the barbell overhead with arms fully extended, in a deep squat position.", "Stand up by extending the hips and knees, keeping the barbell overhead.", "Lower the barbell back to the starting position by reversing the movement."]', 'longhaul-fitness', 0),
('power-stairs', 'Power Stairs', NULL, 'strongman', NULL, 'compound', 'pull', NULL, 'intermediate', NULL, NULL, NULL, 0),
('prisoner-squat-bodyweight', 'Prisoner Squat', 'Prisoner Squat', 'strength', 'squat', NULL, NULL, 'bilateral', NULL, NULL, '["Stand with your feet shoulder-width apart and toes pointing forward or slightly away from your body up to 15°.", "Place your hands behind your head with your elbows pointing out to the sides. This is your starting position.", "Bend your knees and lower your hips back and down as if sitting in a chair, keeping your weight on your heels.", "Lower your body until your thighs are parallel to the ground.", "Push through your heels to stand back up to the starting position.", "Repeat the movement for your desired number of repetitions."]', 'longhaul-fitness', 0),
('pronated-grip-lat-pulldown', 'Pronated Grip Lat Pulldown', NULL, 'strength', 'vertical_pull', NULL, NULL, 'bilateral', NULL, NULL, '["Adjust the seat height and position yourself on the lat pulldown machine.", "Grab the bar with an overhand grip, palms facing away from you, slightly wider than shoulder-width apart.", "Sit down and position your thighs under the thigh pads, keeping your feet flat on the floor.", "Keep your back straight and lean back slightly, engaging your core muscles.", "Exhale and pull the bar down towards your upper chest, leading with your elbows.", "Squeeze your shoulder blades together at the bottom of the movement.", "Inhale and slowly release the bar back to the starting position, extending your arms fully.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 0);
INSERT INTO exercises (id, name_en, name_de, category, movement_pattern, mechanic, force, laterality, level, variation_of, instructions, instructions_source_id, needs_review) VALUES
('prone-assisted-neck-bridge', 'Prone Assisted Neck Bridge', NULL, 'mobility', NULL, NULL, NULL, NULL, NULL, NULL, '["Place a yoga or exercise mat on the floor for head padding.", "Position the top of your head on the floor with your arms bent at the elbows, hands on the ground by both sides of your head, supporting your upper body.", "Support your lower body by balancing on the balls of your toes.", "Hinge at the hips to maintain a neutral spine throughout the movement.", "Hold the bridge position for up to 8 seconds or as long as comfortable.", "Lower your heels back down to the floor and extend your arms at the elbows to finish one repetition.", "Repeat the exercise for the desired number of repetitions."]', 'longhaul-fitness', 0),
('prone-manual-hamstring', 'Prone Manual Hamstring', NULL, 'strength', 'isolation_other', 'isolation', 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('prone-scapular-retraction-arms-at-side', 'Prone Scapular Retraction - Arms at Side', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Lying on stomach with head on towel.", "Stretch arms straight out to your sides.", "Slowly lift your arms, pulling your shoulderblades together, hold for 3 seconds."]', 'wger', 0),
('prowler-sprint', 'Prowler Sprint', NULL, 'cardio', 'locomotion', 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('pseudo-planche-push-up', 'Pseudo Planche Push-up', NULL, 'strength', 'horizontal_push', NULL, NULL, 'bilateral', NULL, NULL, '["You should have the shoulder line in front of your wrists an perform a push-up, maintaining the shoulder in the same position"]', 'wger', 0),
('pull-over-polea-alta', 'PULL OVER POLEA ALTA', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0),
('pull-up', 'Pull-ups', 'Klimmzüge', 'strength', 'vertical_pull', 'compound', 'pull', 'bilateral', 'beginner', NULL, '["Grab the pull up bar with a wide grip, the body is hanging freely. Keep your chest out and pull yourself up till your chin reaches the bar or it touches your neck, if you want to pull behind you. Go with a slow and controlled movement down, always keeping the chest out."]', 'wger', 0),
('pull-up-2', 'Pull-Up', NULL, 'strength', 'vertical_pull', NULL, NULL, 'bilateral', NULL, NULL, '["Begin by finding a sturdy horizontal bar high enough off the ground that you can hang from it with your feet off the floor.", "Stand underneath the bar and jump up, grabbing onto the bar with an overhand grip (palms facing away from you) and your hands slightly wider than shoulder-width apart. Your arms should be fully extended.", "Engage your core and retract your shoulder blades as you pull your body up towards the bar. Keep your elbows pointed downwards and your head in a neutral position.", "Continue pulling your body up until your chin is above the bar. Keep your core tight and your shoulders engaged throughout the movement.", "Pause briefly at the top of the movement, then slowly lower yourself back down to the starting position with control. Make sure to maintain a controlled descent and avoid letting your body swing or drop.", "Repeat the movement for your desired number of repetitions."]', 'longhaul-fitness', 1),
('pull-up-isometric-hold', 'Pull-up Isometric Hold', NULL, 'strength', 'vertical_pull', NULL, NULL, 'bilateral', NULL, NULL, '["Hold the pull-up movement in any position"]', 'wger', 0),
('pullback', 'Pullback', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Set weight and grip for the cables in the cage. Take a few steps away, bend over, pull and extend the back at the same time."]', 'wger', 0),
('punches', 'punches', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["stand stable and throw normal straight punches"]', 'wger', 0),
('push-press', 'Push Press', NULL, 'strength', 'vertical_push', NULL, NULL, NULL, NULL, NULL, '["Clean your dumbbells onto your shoulders, palms facing in. Take a breath and brace your core. (picture 1)Dip at the knees and use your legs to help (picture 2) press your dumbbells overhead. Lower under control with a slow tempo to your shoulders and repeat."]', 'wger', 0),
('push-up', 'Push-Up', NULL, 'strength', 'horizontal_push', 'compound', 'push', 'bilateral', 'beginner', NULL, '["The push-up is a fundamental bodyweight exercise that targets the chest, arms, and shoulders while engaging the core for stability. It requires no equipment and is excellent for building upper body strength.", "Instructions:", "Start in a plank position with hands placed slightly wider than shoulder-width, feet together, and body in a straight line from head to heels.", "Engage your core and lower your body by bending your elbows, keeping them close to your body or flared slightly outward.", "Lower until your chest nearly touches the ground while maintaining a neutral spine.", "Push through your palms to return to the starting position, fully extending your arms."]', 'wger', 0),
('push-up-2', 'Push-Up', NULL, 'strength', 'horizontal_push', NULL, NULL, 'bilateral', NULL, NULL, '["Start in a plank position, with your hands shoulder-width apart and your fingers pointing forward.", "Keep your core engaged, your back straight, and your hips in line with your shoulders.", "Lower your body towards the ground by bending your elbows, keeping your upper arms close to your sides.", "Keep your elbows at a 45-degree angle to your body, and continue lowering until your chest touches the ground.", "Push back up to the starting position by straightening your arms, keeping your core engaged and your body in a straight line throughout the movement.", "Repeat"]', 'longhaul-fitness', 1),
('push-up-against-wall', 'Push-Up Against Wall', NULL, 'strength', 'horizontal_push', NULL, NULL, 'bilateral', NULL, NULL, '["Stand facing a wall with your feet shoulder-width apart.", "Place your hands on the wall at shoulder height, slightly wider than shoulder-width apart.", "Step back a few feet, keeping your body straight and your core engaged.", "Bend your elbows and lower your chest towards the wall, keeping your body in a straight line.", "Push through your palms and straighten your arms to return to the starting position.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('push-up-close-and-wide-hand-positions', 'Pushups (Close and Wide Hand Positions)', NULL, 'strength', 'horizontal_push', 'compound', 'push', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('push-up-close-triceps-position', 'Push-Ups - Close Triceps Position', NULL, 'strength', 'horizontal_push', 'compound', 'push', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('push-up-feet-elevated', 'Push-Ups With Feet Elevated', NULL, 'strength', 'horizontal_push', 'compound', 'push', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('push-up-feet-in-rings', 'Push-Up – Feet in Rings', NULL, 'strength', 'horizontal_push', NULL, NULL, 'bilateral', NULL, NULL, '["Start in a plank position with your feet in the rings and your hands shoulder-width apart on the ground.", "Lower your body towards the ground by bending your elbows and keeping your body straight.", "Push yourself back up to the starting position by straightening your arms.", "Repeat."]', 'longhaul-fitness', 0),
('push-up-hands-in-rings', 'Push-Up – Hands in Rings', NULL, 'strength', 'horizontal_push', NULL, NULL, 'bilateral', NULL, NULL, '["Start in a plank position with your hands placed inside suspended rings.", "Engage your core and glutes to keep your body in a straight line.", "Lower your body towards the ground by bending your elbows.", "Keep your elbows close to your body and your shoulders down and back.", "Push yourself back up to the starting position by straightening your arms.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('push-up-parallettes', 'Push-Ups | Parallettes', NULL, 'strength', 'horizontal_push', NULL, NULL, 'bilateral', NULL, NULL, '["Parallettes push-ups are a variation of the traditional push-up that are performed with the hands on parallel bars, known as parallettes. To perform a parallettes push-up, assume a push-up position with your hands on the parallettes and your feet on the ground. Lower your body towards the ground while keeping your elbows close to your sides, and then push back up to the starting position. Parallettes push-ups place more emphasis on the chest and shoulders compared to traditional push-ups, as they allow for a greater range of motion in the shoulder joint. This increased range of motion can also help to improve shoulder stability and mobility. Additionally, parallettes push-ups engage the core muscles more than traditional push-ups, as the instability of the parallettes requires greater activation of the core muscles to maintain proper form. The added challenge of balancing on the parallettes also requires greater upper body strength and control, making parallettes push-ups a more advanced variation of the traditional push-up. They can be a great way to challenge yourself and add variety to your upper body workout routine. As always, be sure to use proper form and start with a level that is appropriate for your strength and fitness level."]', 'wger', 0),
('push-up-to-side-plank', 'Push Up to Side Plank', NULL, 'strength', 'horizontal_push', 'compound', 'push', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('push-up-wide', 'Push-Up Wide', NULL, 'strength', 'horizontal_push', 'compound', NULL, 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('quad-stretch', 'Quad Stretch', NULL, 'stretching', NULL, NULL, 'static', NULL, 'intermediate', NULL, NULL, NULL, 0),
('quadriped-arm-and-leg-raise', 'Quadriped Arm and Leg Raise', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["In this exercise, the back muscles and the muscles of the back of the leg and back of the arm are activated by lifting the crossed arm and leg at the same time in the crawling position. It also improves balance and proprioception. The movement is done symmetrically.", "Get into a crawling posture.2. Draw your abdomen in, then raise your right leg and left arm.3. You should keep your abdomen in for 8 seconds.4. After 8 seconds, slowly lower your arm and leg.5. Then release your muscle."]', 'wger', 0),
('quadruped-hip-extension', 'Quadruped Hip Extension', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Begin on your hands and knees in the quadruped position with hands under shoulders and knees under hips.", "Engage your core and maintain a neutral spine throughout the exercise. This is your starting position.", "Maintaining a bent knee, squeeze your glute and extend one foot towards the ceiling. Imagine placing your foot flat on the ceiling.", "Squeeze your glutes at the top of the movement.", "Lower the leg back to the starting position without touching the ground.", "Perform the desired repetitions on one side before switching to the other leg."]', 'longhaul-fitness', 0),
('quick-leap', 'Quick Leap', NULL, 'plyometrics', NULL, 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('rack-deadlift', 'Rack Deadlift', NULL, 'strength', 'hinge', NULL, NULL, 'bilateral', NULL, NULL, '["Deadlift to be done using a Smith machine or a free rack. Bar or barbell hould be just right under the knee cap level. Lift using the glutes and through the heels, then come back to starting postion with a control movement of 2 seconds.", "This exercise targets mainly the lower back and glutes."]', 'wger', 0),
('rack-pull', 'Rack Pull', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Set up a barbell in a power rack at shin height or just below your knees.", "Stand with your feet shoulder-width apart and your shins touching the bar.", "Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.", "Engage your core and lift the bar by extending your hips and knees.", "Keep your back straight and your shoulders pulled back throughout the movement.", "Lower the bar back down to the starting position by bending your hips and knees.", "Repeat."]', 'longhaul-fitness', 0),
('reach-up', 'Reach ups', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0),
('rear-leg-raise', 'Rear Leg Raises', NULL, 'stretching', NULL, NULL, 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('recumbent-bike', 'Recumbent Bike', NULL, 'cardio', 'locomotion', NULL, NULL, NULL, NULL, NULL, '["For this exercise Recumbent Bike is needed. You just sit on it, set level and time and start the workout"]', 'wger', 0),
('remada-unilateral-no-cabo', 'Remada unilateral no cabo', NULL, 'strength', NULL, NULL, NULL, 'unilateral', NULL, NULL, NULL, NULL, 0),
('respiracion-profunda-de-pie-o-sentado', 'Respiración profunda (de pie o sentado)', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0),
('reverse-curl', 'Reverse Curl', 'Reverse Curls', 'strength', 'elbow_flexion', NULL, NULL, 'bilateral', NULL, NULL, '["The reverse-grip barbell curl is a variation on the biceps curl where the palms face downward. The switch from an underhand to an overhand grip brings the forearm and brachialis muscles more into the exercise."]', 'wger', 0),
('reverse-hyperextension', 'Reverse Hyperextension', NULL, 'strength', 'hinge', NULL, NULL, NULL, NULL, NULL, '["Lie face-down on a bench with your legs hanging off the edge.", "Bend your hips so your thighs are vertical, bending your knees at the same time so your shins stay horizontal.", "Straighten out your legs so they are not bent and your toes are pointing backwards horizontally.", "Return to the original position, and repeat."]', 'wger', 0),
('reverse-snow-angel', 'Reverse Snow Angel', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Lay flat on your stomach with your arms extended in front of you on the ground as your legs are lying flat. Lift both your arms and move them to your side slowly. Then, move them back."]', 'wger', 0),
('reverse-wood-chops', 'Reverse Wood Chops', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Attach a looping resistance band to a rack below knee height", "Grip the other end of the band like holding a baseball bat with both hands", "Stretch the band facing it", "Start with your hands at the side of your hips, knees bent", "Rotate your hips while moving your hands towards over the top of your opposite shoulder", "Imagine the motion as striking a baseball with a bat"]', 'wger', 0),
('rickshaw-carry', 'Rickshaw Carry', NULL, 'strongman', 'carry', 'compound', NULL, NULL, 'intermediate', NULL, NULL, NULL, 0),
('rickshaw-deadlift', 'Rickshaw Deadlift', NULL, 'strongman', 'hinge', 'compound', 'pull', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('ring-dip', 'Ring Dips', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["Dips peformed on gymnastic rings."]', 'wger', 0),
('ring-dip-2', 'Ring Dips', NULL, 'strength', NULL, 'compound', 'push', 'bilateral', 'intermediate', NULL, NULL, NULL, 1),
('rocket-jump', 'Rocket Jump', NULL, 'plyometrics', NULL, 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('rocky-pull-up-pulldowns', 'Rocky Pull-Ups/Pulldowns', NULL, 'strength', 'vertical_pull', 'compound', 'pull', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('roll-up', 'Roll-Up', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Lie on your back with your arms extended overhead and your legs straight.", "Engage your core and slowly lift your head, neck, and shoulders off the ground.", "Continue to roll up, reaching your arms towards your toes and keeping your legs straight.", "Pause at the top of the movement, then slowly roll back down to the starting position.", "Repeat."]', 'longhaul-fitness', 0),
('romanian-deadlift-single-leg', 'Romanian deadlift, single leg', NULL, 'strength', 'hinge', NULL, NULL, 'unilateral', NULL, NULL, '["Also known as: RDL. Steps:"]', 'wger', 0),
('rope-climb', 'Rope Climb', NULL, 'strength', NULL, 'compound', 'pull', NULL, 'intermediate', NULL, NULL, NULL, 0),
('rope-jumping', 'Rope Jumping', NULL, 'cardio', NULL, NULL, NULL, NULL, 'intermediate', NULL, NULL, NULL, 0),
('rope-pullover-row', 'Rope Pullover/row', NULL, 'strength', 'horizontal_pull', NULL, NULL, NULL, NULL, NULL, '["Set up bench in front of cable row machine. Lean over bench to do a row/pullover with rope that targets lats. See picture."]', 'wger', 0),
('rope-wave', 'Rope Wave', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Stand with your feet shoulder-width apart, knees slightly bent, in front of a heavy rope.", "Grip the ends of the rope with both hands. Your palms should be facing inward.", "Tighten your core to stabilize your spine.", "Begin to raise and lower both arms rapidly in unison. The motion should create waves in the rope.", "Keep the waves going consistently for the desired number of repetitions."]', 'longhaul-fitness', 0),
('round-world-shoulder-stretch', 'Round The World Shoulder Stretch', NULL, 'stretching', NULL, NULL, 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('row', 'Row', NULL, 'strength', 'horizontal_pull', NULL, NULL, 'bilateral', NULL, NULL, '["In strength training, rowing (or a row, usually preceded by a qualifying adjective — for instance a seated row) is an exercise where the purpose is to strengthen the muscles that draw the rower''s arms toward the body (latissimus dorsi) as well as those that retract the scapulae (trapezius and rhomboids) and those that support the spine (erector spinae). When done on a rowing machine, rowing also exercises muscles that extend and support the legs (quadriceps and thigh muscles). In all cases, the abdominal and lower back muscles must be used in order to support the body and prevent back injury."]', 'wger', 0),
('rowing-lying-bench', 'Rowing, Lying on Bench', NULL, 'strength', 'horizontal_pull', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0),
('rowing-machine', 'Rowing Machine', 'Rudergerät', 'cardio', NULL, NULL, NULL, NULL, NULL, NULL, '["Sit on a rowing machine with your back straight."]', 'wger', 0),
('rowing-seated-narrow-grip', 'Rowing seated, narrow grip', 'Rudern Sitzend, Eng', 'strength', 'horizontal_pull', NULL, NULL, NULL, NULL, NULL, '["Adjust the cable machine to the appropriate weight and attach a V-bar handle to the cable.", "Sit on the machine with your feet flat on the footrests and your knees slightly bent.", "Grasp the V-bar handle with an overhand grip, with your hands close together.", "Keep your back straight and your shoulders down and back.", "Pull the V-bar handle towards your abdomen, keeping your elbows close to your body.", "Squeeze your shoulder blades together at the end of the movement.", "Slowly release the handle back to the starting position.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('rowing-t-bar', 'Rowing, T-bar', 'T-Bar Rudern (breit)', 'strength', 'horizontal_pull', NULL, NULL, NULL, NULL, NULL, '["The execution of this exercise is very similar to the regular bent over rowing, only that the bar is fixed here.", "Grab the barbell with a wide grip (slightly more than shoulder wide) and lean forward. Your upper body is not quite parallel to the floor, but forms a slight angle. The chest''s out during the whole exercise. Pull now the barbell with a fast movement towards your belly button, not further up. Go slowly down to the initial position. Don''t swing with your body and keep your arms next to your body."]', 'wger', 0),
('runners-5', 'Runner''s 5', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Stand with your feet hip-width apart. We''re going to complete five, one-legged exercises on one side, then the other.", "First, One-legged Squats: Stand on one leg with the other leg extended slightly behind you. Slowly lower your body by bending the knee of the standing leg, keeping your back straight and chest up. Lower yourself as far as comfortable while maintaining balance, then return to the starting position. Repeat for the desired number of repetitions.", "Second, One-legged Romanian Deadlifts: Stand on one leg with a slight bend in your knee. Keeping your back straight, hinge at your hips to lower your upper body forward while extending the opposite leg straight behind you. Go as low as your flexibility allows, feeling a stretch in your hamstring. Return to the upright position. Repeat for the desired number of repetitions.", "Third, One-legged Lunges: Stand on one leg and take a step forward with the other leg. Lower your body by bending both knees until your front thigh is parallel to the ground (or as low as you can comfortably go). Keep your upper body upright, and push through your front heel to return to the starting position. Repeat for the desired number of repetitions.", "Fourth, One-legged Sidekicks: Stand on one leg with the other leg slightly lifted to the side. Perform a side kick by extending your lifted leg straight out to the side, then bring it back to the starting position. Maintain balance throughout. Repeat for the desired number of repetitions.", "Fifth, One-legged Front-Back Kicks: Stand on one leg with the other leg lifted slightly in front of you. Perform a front kick by extending your lifted leg forward, then immediately perform a back kick by extending it backward. Keep control and balance throughout the movement. Repeat for the desired number of repetitions.", "Repeat the five exercises on the other side."]', 'longhaul-fitness', 0),
('runners-stretch', 'Runner''s Stretch', NULL, 'stretching', NULL, NULL, 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('russian-twist', 'Russian Twist', NULL, 'strength', 'rotation', NULL, NULL, NULL, NULL, NULL, '["Hold a dumbbell, barbell weight or something else that is heavy with both hands, but make sure it is not too heavy and you are able to keep in form.", "Lean back to a 45-degree angle from the floor. For an extra challenge, lift your feet off the floor.", "Rotate your arms to one side to the same level as your chest, touch the floor for a little extra challenge, and then do the same to the other side. When you''re back in your original position after doing both sides it will count as 1 rep."]', 'wger', 0),
('russian-twist-2', 'Russian Twist', NULL, 'strength', 'rotation', 'compound', 'pull', NULL, 'intermediate', NULL, NULL, NULL, 0),
('sandbag-load', 'Sandbag Load', NULL, 'strongman', NULL, 'compound', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('scapula-pull', 'Scapula Pulls', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Hang straight on a pull-up bar", "Pull shoulder blades together, moving the body slightly up"]', 'wger', 0),
('scapular-pull-up', 'Scapular Pull-Up', NULL, 'strength', 'vertical_pull', 'isolation', 'pull', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('scissor-kick', 'Scissor Kick', NULL, 'stretching', NULL, 'isolation', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('scissors', 'Scissors', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Scissors is an abdominal exercise that strengthens the transverse abdominals, helping flatten your belly and strengthen your entire core. Scissors is not only a core strength move, but it is also a great stretch for your hamstrings and your lower back. Everyone is looking for new ways to work the core, to flatten the belly and to improve flexibility. If you learn how to do Scissors you will get everything rolled together in one move."]', 'wger', 0),
('scissors-jump', 'Scissors Jump', NULL, 'plyometrics', NULL, 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('seated-bench-press', 'Seated Bench Press', NULL, 'strength', 'horizontal_push', NULL, NULL, NULL, NULL, NULL, '["Set up the chest press machine so that the grips are aligned with your lower chest when you sit down. Make sure you''re sitting with your back flat against the seat. Grab a handle in each hand, stick your chest out, and keep your head against the headrest. Breathe deeply and slowly push the handles forward until your arms are almost fully extended. Pause just before the lockout, then slowly return the handles to the starting position. Pause just before the handles come to a complete stop and perform another repetition."]', 'wger', 0),
('seated-biceps', 'Seated Biceps', NULL, 'stretching', NULL, 'isolation', 'static', NULL, 'advanced', NULL, NULL, NULL, 0),
('seated-calf-massage-lacrosse-ball', 'Seated Calf Massage – Lacrosse Ball', NULL, 'mobility', NULL, NULL, NULL, NULL, NULL, NULL, '["Sit on the floor and place a massage ball under your calf muscle.", "Apply gentle pressure by pressing your leg down onto the ball.", "Slowly flex your foot upward (dorsiflex) to stretch the calf while keeping pressure on the ball.", "Then point your foot downward (plantarflex) to massage the calf.", "Repeat the flexing and pointing movement slowly to massage the muscle.", "Hold the massage for the desired time and switch to the other calf if needed."]', 'longhaul-fitness', 0),
('seated-calf-raise', 'Seated Calf Raise', NULL, 'strength', 'isolation_other', NULL, NULL, NULL, NULL, NULL, '["Adjust the seat height and position yourself on the calf raise machine with your feet flat on the foot platform.", "Place your thighs under the leg pad and ensure that your knees are slightly bent.", "Grasp the handles or sides of the machine for stability.", "Slowly raise your heels by extending your ankles as far as possible while keeping your toes on the foot platform.", "Hold the contracted position for a brief moment, feeling the stretch in your calves.", "Lower your heels back down to the starting position, allowing your calves to stretch.", "Repeat the movement for the desired number of repetitions."]', 'longhaul-fitness', 1),
('seated-calf-stretch', 'Seated Calf Stretch', NULL, 'stretching', NULL, NULL, 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('seated-corkscrew', 'Seated Corkscrew', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["To do this abs and obliques exercise, start with your hands back behind your body and bring your knees in and across, really trying to contract the obliques. Then extend your legs back out to starting position and repeat toward the opposite side of the abs. Beginners might find that they can’t even get through the first 45 seconds of this challenging reverse crunches variation. That’s ok because it gives you a place to start and something to improve upon."]', 'wger', 0),
('seated-crossed-leg-forward-stretch', 'Seated Crossed Leg Forward Stretch', NULL, 'stretching', NULL, NULL, NULL, NULL, NULL, NULL, '["Sit on the floor with your legs crossed.", "Place your hands on the floor beside your hips.", "Begin to lean forward, leading with your hands.", "Crawl your hands forward to deepen the stretch.", "Hold the stretch for the desired time while focusing on relaxed breaths."]', 'longhaul-fitness', 0),
('seated-figure-four', 'seated figure four', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Seat on a bench. Feet flat on the ground. Place your left ankle over your right knee. Your right knee stays flat. Keep your back straight. Gently push your left knee down."]', 'wger', 0),
('seated-floor-hamstring-stretch', 'Seated Floor Hamstring Stretch', NULL, 'stretching', NULL, NULL, 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('seated-front-deltoid', 'Seated Front Deltoid', NULL, 'stretching', NULL, NULL, 'static', NULL, 'advanced', NULL, NULL, NULL, 0),
('seated-glute', 'Seated Glute', NULL, 'stretching', NULL, NULL, 'static', NULL, 'advanced', NULL, NULL, NULL, 0),
('seated-hamstring', 'Seated Hamstring', NULL, 'stretching', NULL, NULL, 'static', NULL, 'advanced', NULL, NULL, NULL, 0),
('seated-hamstring-and-calf-stretch', 'Seated Hamstring and Calf Stretch', NULL, 'stretching', NULL, NULL, 'static', NULL, 'intermediate', NULL, NULL, NULL, 0),
('seated-head-harness-neck-resistance', 'Seated Head Harness Neck Resistance', NULL, 'strength', 'isolation_other', 'isolation', 'pull', NULL, 'intermediate', NULL, NULL, NULL, 0),
('seated-hip-abduction', 'Seated Hip Abduction', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Starting Position:", "Adjust the seat height so that your knees are aligned with the pivot point of the machine.", "Sit with your back flat against the backrest, maintaining good posture.", "Place the outside of your thighs against the machine''s padded levers.", "Position your feet flat on the footrests or platform of the machine.", "Grasp the handles or sides of the seat for stability.", "Ensure your spine is neutral and your core is slightly engaged.", "Movement:", "Exhale as you slowly push your legs outward against the resistance pads.", "Focus on initiating the movement from your hips, not your knees.", "Continue opening your legs until you feel a strong contraction in your outer hips and thighs.", "Hold the fully abducted position briefly (1-2 seconds) to maximize muscle engagement.", "Inhale as you slowly control the return of your legs to the starting position, resisting the weight throughout the movement.", "Avoid allowing the weight stack to touch down between repetitions to maintain constant tension on the muscles.", "Repeat for the desired number of repetitions, maintaining control throughout the set."]', 'wger', 0),
('seated-hip-adduction', 'Seated Hip Adduction', 'Adduktoren-Maschine', 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Starting Position: Sit on the machine with your knees inward and against the pads. Pull the pin to release the pads. Grab the handles on the sides.b"]', 'wger', 0),
('seated-knee-to-heel-taps', 'Seated Knee To Heel Taps', NULL, 'mobility', NULL, NULL, NULL, NULL, NULL, NULL, '["Sit on the ground leaning backwards with your arms straight and your hands behind you.", "Place your feet just wider than shoulder distance in front of you with your knees bent at 90° angles. This is your starting position.", "Rotate one hip outwards until the knee of that leg reaches the ground.", "Rotate the other hip inwards so that the knee of that leg touches the heel of the leg on the ground.", "Return to the starting position and alternate sides.", "Continue alternating the movement on each side for the desired amount of time."]', 'longhaul-fitness', 0),
('seated-knee-tuck', 'Seated Knee Tuck', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Sit on floor or mat. Place arms slightly behind you. Raise legs. Now extend your legs and pull them back."]', 'wger', 0),
('seated-leg-tuck', 'Seated Leg Tucks', NULL, 'strength', 'isolation_other', 'isolation', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('seated-oblique-twist', 'Seated Oblique Twist', NULL, 'strength', 'rotation', NULL, NULL, NULL, NULL, NULL, '["Sit on a workout mat or bench with your knees bent and feet flat on the floor.", "Engage your core muscles by drawing your navel towards your spine.", "Hold a dumbbell or medicine ball with both hands close to your chest.", "Keeping your back straight, lean slightly back to engage your abdominal muscles.", "Exhale and rotate your torso to the right, bringing the weight towards your right hip.", "Inhale as you return to the starting position.", "Exhale and rotate your torso to the left, bringing the weight towards your left hip.", "Inhale as you return to the starting position.", "Repeat the twisting motion for the desired number of repetitions on each side."]', 'longhaul-fitness', 0),
('seated-pancake-good-morning', 'Seated Pancake Good Morning', NULL, 'strength', 'hinge', NULL, NULL, NULL, NULL, NULL, '["Sit with your legs completely straight (knees locked), spread wide in a straddle position.", "Place your hands on the back of your neck.", "Hinge your torso and head towards the floor."]', 'wger', 0),
('seated-shoulder-extension-stretch', 'Seated Shoulder Extension Stretch', NULL, 'stretching', NULL, NULL, NULL, NULL, NULL, NULL, '["Sit with your hands behind you, shoulder width apart.", "Lock your elbows.", "Scoot your feet and hips out forwards, lowering your shoulders down towards ground.", "Go as far as possible to obtain a good stretch.", "See the video: https://www.youtube.com/watch?v=ihUAbG0e8zw"]', 'wger', 0),
('seated-snatch-grip-behind-neck-press', 'Seated Snatch Grip Behind the Neck Press', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Start by sitting on a bench with a backrest, next to a racked, weighted barbell.", "Grip the barbell with a wide snatch grip.", "Position the barbell behind your neck, resting it on your upper traps.", "Engage your core and keep your back straight.", "Press the barbell overhead by extending your arms and pushing the weight up.", "Lock out your elbows at the top of the movement.", "Lower the barbell back down to the starting position behind your neck.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('seated-triceps-press', 'Seated Triceps Press', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Machine Setup", "Adjust the seat height so that the machine''s handles align with your elbow joint", "Ensure your back is firmly supported against the backrest", "Feet should be flat on the floor", "Maintain a neutral spine position", "Movement Mechanics", "Starting Position", "Grip the handles with a neutral grip", "Keep upper arms close to your body", "Elbows bent at approximately 90 degrees", "Press Movement", "Extend arms forward by pushing the handles away", "Focus on using triceps to drive the movement", "Avoid using shoulder or chest muscles", "Fully extend arms without locking elbows", "Return Phase", "Slowly return to the starting position", "Maintain controlled, smooth motion", "Keep tension on the triceps throughout"]', 'wger', 1),
('segmental-lower-back-flexion', 'Segmental Lower Back Flexion', NULL, 'mobility', NULL, NULL, NULL, NULL, NULL, NULL, '["Sit or stand with a neutral spine.", "Flex your neck by bringing your chin towards your chest.", "Slump your shoulders forward and flex your upper back.", "Bend forward incrementally at each segment of the thoracic spine.", "Continue the movement for the desired amount of time."]', 'longhaul-fitness', 0),
('shallow-lunge-bodyweight', 'Shallow Lunge – Bodyweight', NULL, 'strength', 'lunge', NULL, NULL, NULL, NULL, NULL, '["Stand with your feet shoulder-width apart and your hands on your hips.", "Step forward with one leg, bending your knee until your thigh is parallel to the ground.", "Keep your back straight and your core engaged.", "Push through your front heel to return to the starting position.", "Repeat with the other leg."]', 'longhaul-fitness', 0),
('shinbox-ir-stretch', 'Shinbox IR Stretch', NULL, 'stretching', NULL, NULL, NULL, NULL, NULL, NULL, '["Starting Position: Sit on the floor with both hips and knees bent at 90-degree angles.", "Leg Placement: Place one leg in front of you (external rotation) and the other leg out to the side/behind you (internal rotation). The shins and knees should remain flat on the ground.", "The Movement: Keeping your hips square, hinge your torso forward or tilt it laterally (side-to-side) toward the front leg to deepen the stretch.", "Target Areas: Stretches the glutes and piriformis (front leg) and the hip flexors and quads (back leg). Engages the core and obliques during lateral flexion.", "Goal: Improves hip mobility, specifically internal and external rotation, and relieves lower back tension."]', 'wger', 0),
('shotgun-row', 'Shotgun Row', NULL, 'strength', 'horizontal_pull', NULL, NULL, NULL, NULL, NULL, '["Attach a single handle to a low cable.", "After selecting the correct weight, stand a couple feet back with a wide-split stance. Your arm should be extended and your shoulder forward. This will be your starting position.", "Perform the movement by retracting the shoulder and flexing the elbow. As you pull, supinate the wrist, turning the palm upward as you go.", "After a brief pause, return to the starting position."]', 'wger', 0),
('shoulder-circle', 'Shoulder Circles', NULL, 'stretching', NULL, NULL, 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('shoulder-raise', 'Shoulder Raise', NULL, 'stretching', NULL, NULL, 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('shoulder-shrug', 'Shoulder Shrug', 'Schulterzucken', 'strength', 'isolation_other', NULL, NULL, 'bilateral', NULL, NULL, '["The shoulder shrug (usually called simply the shrug) is an exercise in weight training used to develop the upper trapezius muscle. The lifter stands erect, hands about shoulder width apart, and raises the shoulders as high as possible, and then lowers them, while not bending the elbows, or moving the body at all. The lifter may not have as large a range of motion as in a normal shrug done for active flexibility. It is usually considered good form if the slope of the shoulders is horizontal in the elevated position."]', 'wger', 0),
('shoulder-stretch', 'Shoulder Stretch', NULL, 'stretching', NULL, NULL, 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('shoulder-teepee-dowel', 'Shoulder Teepee – Dowel', NULL, 'mobility', NULL, NULL, NULL, NULL, NULL, NULL, '["Grab a dowel or broomstick with hands wider than shoulder-width apart, holding it parallel to the ground in front of your waist.", "Raise one end of the dowel above your head and then behind your back, keeping the other hand at hip level.", "Lower the dowel so that it''s parallel to the ground behind your back.", "Raise the other hand to pull the dowel up and over your body bringing it parallel to the ground in front of you again.", "Alternate directions, performing the same steps going the other direction.", "Continue alternating the movement on each side for the desired amount of time."]', 'longhaul-fitness', 0),
('side-bridge', 'Side Bridge', NULL, 'strength', NULL, NULL, 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('side-crunch', 'Side Crunch', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["Hold weight in one hand. Bend side ways to the knee. Pull upo to upright position using your obliquus."]', 'wger', 0),
('side-hop-sprint', 'Side Hop-Sprint', NULL, 'plyometrics', 'locomotion', 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('side-jackknife', 'Side Jackknife', NULL, 'strength', NULL, 'compound', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('side-laying-interior-rotation', 'Side-laying interior rotation', NULL, 'strength', 'rotation', NULL, NULL, 'bilateral', NULL, NULL, '["Laying on your side and using the arm closest to the bench, maintain a 90 degree bend at the elbow and allow the weight to fall towards the ground past the bench as low as comfortable. Bring the weight up using only rotation of the shoulder to the opposing shoulder."]', 'wger', 0),
('side-leg-raise', 'Side Leg Raises', NULL, 'stretching', NULL, NULL, 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('side-lying-clamshell', 'Side-Lying Clamshell', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Lie on your side with your knees bent and your feet together.", "Keep your feet touching and lift your top knee as high as you can without moving your pelvis.", "Pause for a moment at the top of the movement, then slowly lower your knee back down.", "Repeat the movement for the desired number of repetitions, then switch to the other side."]', 'longhaul-fitness', 0),
('side-lying-floor-stretch', 'Side-Lying Floor Stretch', NULL, 'stretching', NULL, NULL, 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('side-lying-groin-stretch', 'Side Lying Groin Stretch', NULL, 'stretching', NULL, 'isolation', 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('side-neck-stretch', 'Side Neck Stretch', NULL, 'stretching', NULL, 'isolation', 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('side-plank', 'Side Plank', 'Side Plank', 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["Works your obliques and helps stabilize your spine. Lie on your side and support your body between your forearm and knee to your feet."]', 'wger', 0),
('side-plank-2', 'Side Plank', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["Start by lying on your side with your legs extended and stacked on top of each other.", "Place your forearm on the ground directly below your shoulder, with your elbow bent at a 90-degree angle.", "Engage your core muscles and lift your hips off the ground, creating a straight line from your head to your feet.", "Keep your body in a straight line and avoid sagging or letting your hips drop.", "Hold the position for the desired amount of time.", "Repeat on the other side."]', 'longhaul-fitness', 1),
('side-slide-squat', 'Side Slides + Squats', NULL, 'strength', 'squat', NULL, NULL, 'bilateral', NULL, NULL, '["With feet a little wider than shoulder-width apart and staying low to mimic a defensive position, you should step with their lead leg and push off with their plant leg. After three slides, rotate your body for 180 degree on the guiding (/outer) leg and do a squat. Continue."]', 'wger', 0),
('side-standing-long-jump', 'Side Standing Long Jump', NULL, 'plyometrics', NULL, 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('side-to-box-shuffle', 'Side to Side Box Shuffle', NULL, 'plyometrics', NULL, 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('side-to-chins', 'Side To Side Chins', NULL, 'strength', NULL, 'compound', 'pull', NULL, 'intermediate', NULL, NULL, NULL, 0),
('side-to-push-up', 'Side to Side Push Ups', NULL, 'strength', 'horizontal_push', NULL, NULL, 'bilateral', NULL, NULL, '["-start in push up position", "-lean the body weight to the right side, and complete a push up with the chest over the right hand", "-come back to the centered position", "-on rep 2, lean to the left side"]', 'wger', 0),
('side-wrist-pull', 'Side Wrist Pull', NULL, 'stretching', NULL, 'isolation', 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('single-arm-hang-bar', 'Single-Arm Hang – Bar', NULL, 'strength', NULL, NULL, NULL, 'unilateral', NULL, NULL, '["Find a sturdy bar that can support your weight.", "Jump up and grab the bar with one hand.", "Hold the position for as long as you can.", "Slowly lower yourself down and release your grip on the bar."]', 'longhaul-fitness', 0),
('single-arm-row', 'Single arm row', NULL, 'strength', 'horizontal_pull', NULL, NULL, 'unilateral', NULL, NULL, '["Sitting on the ground, use a high cable in a single grip, to do lat pulldowns with a focus on a long stretch in the lats."]', 'wger', 0),
('single-cone-sprint-drill', 'Single-Cone Sprint Drill', NULL, 'plyometrics', 'locomotion', NULL, 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('single-leg-butt-kick', 'Single Leg Butt Kick', NULL, 'plyometrics', NULL, 'compound', 'push', 'unilateral', 'beginner', NULL, NULL, NULL, 0),
('single-leg-extension', 'Single Leg Extension', 'Beinstrecker Einbeinig', 'strength', NULL, NULL, NULL, 'unilateral', NULL, NULL, NULL, NULL, 0),
('single-leg-glute-bridge', 'Single Leg Glute Bridge', NULL, 'strength', 'hinge', 'isolation', 'push', 'unilateral', 'beginner', NULL, '["A glute bridge, where you use just one leg at a time."]', 'wger', 0),
('single-leg-hamstring-stretch', 'Single Leg Hamstring Stretch', NULL, 'stretching', NULL, NULL, NULL, 'unilateral', NULL, NULL, '["Sit on the ground with one leg straight out in front of you and the other leg bent in toward you. Reach forward with both hands, trying to touch the toes of your straight leg."]', 'wger', 0),
('single-leg-high-box-squat', 'Single-Leg High Box Squat', NULL, 'strength', 'squat', 'compound', 'push', 'unilateral', 'beginner', NULL, NULL, NULL, 0),
('single-leg-hop-progression', 'Single-Leg Hop Progression', NULL, 'plyometrics', NULL, 'compound', 'push', 'unilateral', 'beginner', NULL, NULL, NULL, 0),
('single-leg-lateral-hop', 'Single-Leg Lateral Hop', NULL, 'plyometrics', NULL, 'compound', 'push', 'unilateral', 'beginner', NULL, NULL, NULL, 0),
('single-leg-push-off', 'Single Leg Push-off', NULL, 'plyometrics', NULL, 'compound', 'push', 'unilateral', 'beginner', NULL, NULL, NULL, 0),
('single-leg-romanian-deadlift', 'Single Leg RDL', NULL, 'strength', 'hinge', NULL, NULL, 'unilateral', NULL, NULL, '["Stand upright and hold weights in both hands if using loads.", "Brace your core and lift one leg off the ground.", "Keep your back straight, hinge at the hips while lowering your torso forward, ensuring you don’t rotate your hips.", "Lower until you feel a stretch in your standing leg''s hamstring, then return to standing position. Repeat on both sides."]', 'wger', 0),
('single-leg-romanian-deadlift-jump', 'Single-Leg Romanian Deadlift Jump', NULL, 'strength', 'hinge', NULL, NULL, 'unilateral', NULL, NULL, '["Stand on your right leg, keeping a slight bend in the right knee. Bend your right arm in front of your chest and keep your left arm straight down by your side. This is your starting position.", "Lean forward at your hips, extending your left leg behind you for balance. Keep your back straight, bend your left arm bent in front of your chest, and straighten your right arm behind you in rough alignment with your left leg.", "Lower your torso and lift your left leg until your body forms a ''T'' shape, or go as low as your flexibility allows.", "Push through the heel of your right foot and prepare to explode upwards. Thrust your left arm down towards the ground while bringing your right arm up towards your chest to gain momentum for the jump.", "Jump upwards, driving force through your right leg and using the motion of your arms to enhance the lift.", "Land softly on your right leg, absorbing the impact with a slight bend in your knee, and reset your arms to their starting positions.", "Repeat for the desired number of repetitions on one leg before switching to the other."]', 'longhaul-fitness', 0),
('single-leg-side-glute-press', 'Single-leg side glute press', NULL, 'strength', NULL, NULL, NULL, 'unilateral', NULL, NULL, '["The Single-Leg Side Glute Press is a leg press machine variation where you angle your body sideways on the pad, placing one foot high and slightly angled to press the weight, powerfully targeting the outer glute (gluteus medius/minimus) and hamstrings for balanced leg development and stability, requiring focus on pushing through the heel and maintaining control without locking out.", "How to Perform:", "Setup: Sit in the leg press machine, rotate your body to one hip, placing one foot high on the platform at about a 45-degree angle with toes pointed slightly out/forward.", "Positioning: Keep your hip, knee, and ankle aligned, and ensure your lower back stays on the pad.", "Descent: Slowly lower the weight, allowing your knee to bend deeply (near 90 degrees), feeling a stretch in your glute and hamstring.", "Press: Drive through your heel (not your toes) to press the weight back up, squeezing your glutes and hamstrings, stopping just before your leg fully extends.", "Control: Avoid bouncing and don''t let your lower back lift off the pad; maintain tension throughout the movement."]', 'wger', 0),
('single-leg-stride-jump', 'Single-Leg Stride Jump', NULL, 'plyometrics', NULL, 'compound', 'push', 'unilateral', 'beginner', NULL, NULL, NULL, 0),
('single-leg-tuck-up', 'Single-Leg Tuck-Up', NULL, 'strength', NULL, NULL, NULL, 'unilateral', NULL, NULL, '["Start by lying flat on the floor with your arms extended overhead and your legs straight. This is your starting position.", "Simultaneously lift one knee towards your chest while crunching upwards, bringing your arms forward to reach past the raised knee towards the foot.", "Hold the crunch position briefly, ensuring your core is engaged and your hands are reaching towards the lifting foot.", "Slowly lower your arms, upper body, and leg back to the starting position.", "Repeat the movement with the opposite leg and alternate sides for the desired number of repetitions."]', 'longhaul-fitness', 0),
('sit-and-reach', 'Sit & Reach', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Sit on the ground with your legs extended straight in front of you. Reach both hands forward, trying to reach past your toes or as far as you can go. Return to the starting position and repeat."]', 'wger', 0),
('sit-squat', 'Sit Squats', NULL, 'stretching', NULL, NULL, 'push', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('sit-up', 'Sit-ups', 'Sit Ups', 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["Start by lying on your back with your legs close together, knees bent, and feet flat on the ground.", "Place your hands lightly on the back of your head without interlocking your fingers. Elbows should be out to the sides.", "Engage your core muscles, exhale, and lift your upper body off the ground towards your knees. Lift until you''re essentially sitting upright.", "Inhale as you reverse the movement and lower back down to the ground.", "Repeat."]', 'longhaul-fitness', 0),
('sit-up-2', 'Sit-Up', NULL, 'strength', 'isolation_other', 'isolation', 'pull', 'bilateral', 'beginner', NULL, NULL, NULL, 1),
('sit-up-elbow-thrust', 'Sit Up Elbow Thrust', 'Sit-Ups (Ellenbogen zum Knie)', 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["This is a top down rotation movement, and it’s a bit more explosive, too. Lying with knees bent and feet on the floor, sit up and then drive your left elbow across your entire body toward the right, then come back to center and then finally lower yourself down. Then hit the other side."]', 'wger', 0),
('sitting-calf-raise', 'Sitting Calf Raises', 'Wadenheben Sitzend', 'strength', 'isolation_other', NULL, NULL, NULL, NULL, NULL, '["Sit on a bench for calf raises and check that the feet are half free and that you can completely stretch the calf muscles down. Pull your calves up, going as far (up) as you can. Make at the highest point a short pause of 1 or 2 seconds and go down."]', 'wger', 0),
('sitting-calf-stretch-dorsiflexion', 'Sitting Calf Stretch (Dorsiflexion)', NULL, 'stretching', NULL, NULL, NULL, NULL, NULL, NULL, '["This is a light stretch for the calf that is great for rehab."]', 'wger', 0),
('skating', 'Skating', NULL, 'cardio', NULL, NULL, NULL, NULL, 'intermediate', NULL, NULL, NULL, 0),
('skipping-standard', 'Skipping - Standard', 'Seilspringen', 'cardio', 'locomotion', NULL, NULL, NULL, NULL, NULL, '["Do a single, double footed jump for each swing of the rope.", "Work on a smooth, rhythmical movement, bouncing lightly on the balls of your feet."]', 'wger', 0),
('sled-drag-harness', 'Sled Drag - Harness', NULL, 'strongman', NULL, 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('sled-overhead-backward-walk', 'Sled Overhead Backward Walk', NULL, 'strength', NULL, 'compound', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('sled-overhead-triceps-extension', 'Sled Overhead Triceps Extension', NULL, 'strength', 'elbow_extension', 'isolation', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('sled-pull', 'Sled Pull', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Adjust the weight on the sled according to your fitness level and training goals.", "If using a pulling harness, strap it on securely, making sure it''s comfortably snug. If using straps with handles, grip the handles firmly with both hands.", "Stand facing the sled with your feet hip-width apart. Make sure you have a smooth, level, unobstructed path behind you.", "Lower into a quarter-squat position, keeping your back straight, and brace your core.", "Begin walking backwards slowly, taking small steps while keeping the tension on the harness or handles.", "Push through the balls of your feet with each step, focusing on engaging your quadriceps, calves, and glutes.", "Keep your chest up and shoulders back throughout the movement to maintain proper posture.", "Continue pulling the sled for a number of steps or seconds.", "Carefully disengage from the harness or place down the handles."]', 'longhaul-fitness', 0),
('sled-push', 'Sled Push', NULL, 'cardio', NULL, NULL, NULL, NULL, NULL, NULL, '["Position yourself behind the sled with your feet shoulder-width apart.", "Place your hands on the handles of the sled, gripping them firmly.", "Engage your core and drive through your legs to push the sled forward.", "Maintain a straight back and keep your head up as you push the sled.", "Continue pushing the sled for the desired steps, distance, or time.", "Once finished, release the handles and step away from the sled."]', 'longhaul-fitness', 0),
('sled-push-2', 'Sled Push', NULL, 'strongman', NULL, 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 1),
('sled-reverse-flye', 'Sled Reverse Flye', NULL, 'strength', 'isolation_other', 'isolation', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('sled-row', 'Sled Row', NULL, 'strength', 'horizontal_pull', 'compound', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('sledgehammer-swing', 'Sledgehammer Swings', NULL, 'plyometrics', NULL, 'compound', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('sleeper-stretch', 'Sleeper Stretch', NULL, 'stretching', NULL, NULL, NULL, NULL, NULL, NULL, '["Lie on your side so that you are resting a little weight on your shoulder blade to keep it still", "Extend your arm to 90 degrees in front of you, resting on the floor/mat", "Lift your hand with your elbow so that your fingers point to the ceiling and your palm points towards your feet", "Keeping your elbow still, gently lower your palm toward the floor"]', 'wger', 0),
('smith-machine-behind-back-shrug', 'Smith Machine Behind the Back Shrug', NULL, 'strength', 'isolation_other', 'isolation', 'pull', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('smith-machine-bench-press', 'Bench Press – Smith Machine', NULL, 'strength', 'horizontal_push', 'compound', 'push', 'bilateral', 'beginner', NULL, '["Set up a bench under a Smith machine so that the bar is over your chest while lying on the bench.", "Lie down on the bench with your feet flat on the floor and your back pressed against the bench.", "Extend your arms and grip the bar with your hands slightly wider than shoulder-width apart, palms facing forward.", "Unrack the bar by straightening your arms and lifting it off the rack.", "Lower the bar slowly towards your chest, keeping your elbows wide.", "Pause for a moment when the bar touches your chest.", "Push the bar back up to the starting position by extending your arms fully.", "Repeat the movement for the desired number of repetitions.", "Once finished, carefully rack the bar back onto the Smith machine."]', 'longhaul-fitness', 0),
('smith-machine-bent-over-row', 'Smith Machine Bent Over Row', NULL, 'strength', 'horizontal_pull', 'compound', 'pull', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('smith-machine-calf-raise', 'Smith Machine Calf Raise', NULL, 'strength', 'isolation_other', 'isolation', 'push', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('smith-machine-hang-power-clean', 'Smith Machine Hang Power Clean', NULL, 'strength', NULL, 'compound', 'pull', 'bilateral', 'intermediate', NULL, NULL, NULL, 1),
('smith-machine-high-incline-press', 'High-Incline Smith Machine Press', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["Set the bench to a 45-60° incline. Touch the upper chest with the bar."]', 'wger', 0),
('smith-machine-hip-raise', 'Smith Machine Hip Raise', NULL, 'strength', 'isolation_other', 'isolation', 'pull', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('smith-machine-incline-shoulder-raise', 'Smith Incline Shoulder Raise', NULL, 'strength', 'isolation_other', 'isolation', 'push', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('smith-machine-leg-press', 'Smith Machine Leg Press', NULL, 'strength', 'squat', 'compound', 'push', 'bilateral', 'intermediate', NULL, NULL, NULL, 1),
('smith-machine-pistol-squat', 'Smith Machine Pistol Squat', NULL, 'strength', 'squat', 'compound', 'push', 'unilateral', 'intermediate', NULL, NULL, NULL, 1),
('smith-machine-press', 'Smith Press', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["Sitting almost 90 degree angle, smith machine"]', 'wger', 0),
('smith-machine-shoulder-press', 'Shoulder Press, on Multi Press', 'Frontdrücken MP', 'strength', 'vertical_push', 'compound', 'push', 'bilateral', 'beginner', NULL, '["The exercise is basically the same as with a free barbell:", "Sit on a bench, the back rest should be almost vertical. Take a bar with a shoulder wide grip and bring it down to chest height. Press the weight up, but don''t stretch the arms completely. Go slowly down and repeat."]', 'wger', 0),
('smith-machine-shrug', 'Shrugs on Multipress', 'Shrugs an der MP', 'strength', 'isolation_other', NULL, NULL, 'bilateral', NULL, NULL, NULL, NULL, 0),
('smith-machine-slight-incline-press', 'SMITH MACHINE SLIGHT INCLINE PRESS', NULL, 'strength', 'horizontal_push', NULL, NULL, 'bilateral', NULL, NULL, '["laying under smith machine, with slight incline"]', 'wger', 0),
('smith-machine-split-squat', 'Smith Machine Split Squat', NULL, 'strength', 'lunge', NULL, NULL, 'unilateral', NULL, NULL, '["The \"Smith Machine Split Squat\" is a strength exercise performed on the Smith machine, ideal for targeting the legs and glutes. It involves placing one foot forward and the other back, lowering the body until the front thigh is parallel to the ground while the bar slides vertically along the machine. This exercise helps improve stability, correct muscle imbalances, and reduces stress on the back, providing a safe environment for strength training."]', 'wger', 0),
('smith-machine-squat', 'Squats on Multipress', 'Kniebeuge an Multipresse - Eng', 'strength', 'squat', 'compound', 'push', 'bilateral', 'beginner', NULL, '["Adjust the bar height to your desired position.", "Load the bar with an appropriate weight.", "Stand facing the bar with your feet shoulder-width apart.", "Step forward and position the bar on your shoulders, resting on the back of your neck.", "Grasp the bar with both hands, keeping your elbows pointed down and your chest up.", "Lower your body by bending at the knees and hips, keeping your back straight and your head up.", "Lower until your thighs are parallel to the ground, then push back up to the starting position.", "Repeat."]', 'longhaul-fitness', 0),
('smith-machine-stiff-legged-deadlift', 'Smith Machine Stiff-Legged Deadlift', NULL, 'strength', 'hinge', 'compound', 'pull', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('smith-machine-upright-row', 'Upright Row, on Multi Press', 'Rudern Aufrecht MP', 'strength', 'vertical_pull', 'compound', 'pull', 'bilateral', 'beginner', NULL, '["The movements are basically the same as with an SZ-bar, but you use the bar on the multi press:", "Stand straight, your feet are shoulder-width apart. Hold the bar with an overhand grip on your thighs, the arms are stretched. Lift the bar close to the body till your chin. The elbows point out so that at the highest point they form a V. Make here a short pause before going slowly down and repeating the movement."]', 'wger', 0),
('snap-down', 'Snap Down', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Begin in a standing position with your arms up over your head and your toes pushing into the ground raising your heels up becoming as tall as you can. From this position, perform a small hop with both feet slightly coming off of the ground. As you land, bend your knees and begin to hinge forward at your hips absorbing the landing. Return to the starting position and repeat. You should feel the muscles in your lower body working. Start with your arms and knees fully straightened out. Keep a stable balance as you land and briefly hold that end position, don’t go too fast and become off balanced. Keep your chest up. For a detailed video on landing mechanics, click here: https://youtu.be/RThUCYRDyZw"]', 'wger', 0),
('snatch', 'Snatch', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Start with feet shoulder-width apart and toes pointing slightly outward.", "Place hands on the barbell with a wide grip, palms facing down.", "Lower your hips and bend your knees, keeping your back straight.", "Drive through your legs and hips, pulling the barbell up to your chest.", "As the barbell reaches chest height, quickly extend your arms and legs, pulling the barbell up and overhead.", "Lock out your arms and stand up straight, holding the barbell overhead.", "Lower the barbell back down to the starting position by reversing the movement.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('snatch-grip-deadlift', 'Snatch Grip Deadlift', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["Begin by standing with your feet shoulder-width apart and the barbell on the ground in front of you.", "Take a wide grip on the barbell, with your hands outside of your shoulders.", "Lower your hips and bend your knees, keeping your back straight and your chest up.", "Engage your core and lift the barbell off the ground, keeping it close to your body.", "As you lift the barbell, extend your hips and knees to stand up straight.", "Once you are standing, pause briefly and then lower the barbell back down to the ground, keeping it close to your body.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('sphinx', 'Sphinx', 'Sphinx', 'stretching', NULL, NULL, NULL, NULL, NULL, NULL, '["Lie on your stomach flat, legs extended and the backs of your feet on the ground. Bring your forearms under your shoulders, elbows directly underneath. Then press your hands into the floor to lift your chest. Draw your shoulder blades together, open your collarbones, and direct your gaze forward, while keeping the lower back relaxed."]', 'wger', 0),
('spider-crawl', 'Spider Crawl', NULL, 'strength', NULL, 'compound', 'pull', NULL, 'beginner', NULL, NULL, NULL, 1),
('spider-curl', 'Spider Curl', NULL, 'strength', 'elbow_flexion', NULL, NULL, NULL, NULL, NULL, '["To get the most out of DB Spider Curls, you need an adjustable weight bench set at a 45-degree incline. This inclined position allows your arms to hang freely, putting them in an extended start position with elbows slightly in front of your torso, which is the key to maintaining low-level isometric tension throughout the movement pattern.", "Lie face-down on an adjustable weight bench with your chest fully supported, holding a pair of dumbbells.", "Keep a neutral head position and don’t crane your neck.", "Let your arms hang straight down with your palms facing forward (for a standard Spider Curl) or palms facing inward for a Hammer Curl exercise variation.", "Keep a stable foot position on the floor to maintain balance and control.", "Start the curl motion by flexing your biceps muscles and lifting the pair of dumbbells or curl bar toward your shoulders.", "Keep your elbow flexion controlled. Your arms should stay locked in position with no unnecessary movement.", "Squeeze hard at the top for 1-2 seconds. This is where maximum tension hits the biceps muscle fibers.", "Lower the weight under control for 3-4 seconds to keep muscles under tension for the entire range of motion."]', 'wger', 0),
('spinal-stretch', 'Spinal Stretch', NULL, 'stretching', NULL, 'isolation', 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('splinter-sit-up', 'Splinter Sit-ups', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["Lie on your back with your legs straight and arms at your sides, keeping your elbows bent at 90 degrees. As you sit up, twist your upper body to the left and bring your left knee toward your right elbow while you swing your left arm back. Lower your body to the starting position, and repeat to your right. That''s 1 rep."]', 'wger', 0),
('split-jerk', 'Split Jerk', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Start with the barbell resting on your shoulders, hands slightly wider than shoulder-width apart.", "Bend your knees and lower your body into a partial squat, keeping your back straight and core engaged.", "Drive through your legs and explosively push the barbell overhead, extending your arms fully.", "As the barbell reaches its peak, quickly split your legs, with one foot moving forward and the other moving backward into a high lunge position.", "Stabilize your body and hold the split position for a moment.", "Stand back up by bringing your front and back feet back to the position where they started.", "Lower the barbell back to your shoulders and repeat the movement for the desired number of repetitions."]', 'longhaul-fitness', 0),
('split-jump', 'Split Jump', NULL, 'plyometrics', NULL, 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('split-squat', 'Split Squats', NULL, 'stretching', NULL, NULL, 'push', 'unilateral', 'intermediate', NULL, NULL, NULL, 1),
('squat-bodyweight', 'Squat – Bodyweight', NULL, 'strength', 'squat', 'compound', 'push', 'bilateral', 'beginner', NULL, '["Stand with your feet shoulder-width apart and point your toes slightly outward.", "Keep your chest up, shoulders back, and core engaged.", "Lower your body by bending your knees and pushing your hips back as if you were sitting in a chair.", "Keep your weight on your heels and your knees behind your toes.", "Lower yourself until your thighs are parallel to the ground or as low as you can comfortably go while maintaining good form.", "Pause briefly at the bottom of the squat.", "Push through your heels to stand back up, driving your hips forward as you do.", "Stand up straight and repeat."]', 'longhaul-fitness', 0),
('squat-box', 'Squat – Box', NULL, 'strength', 'squat', NULL, NULL, 'bilateral', NULL, NULL, '["Stand with your feet shoulder-width apart, toes slightly turned out.", "Place a box or bench behind you at a height that allows you to squat to parallel or slightly below parallel.", "Engage your core and keep your chest lifted throughout the exercise.", "Lower your body by pushing your hips back and bending your knees, as if sitting back onto the box.", "Keep your weight on your heels and your knees in line with your toes.", "Pause briefly on the box, then push through your heels to stand back up, fully extending your hips and knees.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 1),
('squat-jerk', 'Squat Jerk', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["Start with your feet shoulder-width apart and toes slightly turned out.", "Get into position by cleaning the barbell or lifting it from a rack at shoulder height with an overhand grip.", "Drop your body into a deep squat position, keeping your chest up and back straight, while pushing the barbell above your head, extending your arms fully.", "As you reach the bottom of the squat, explosively drive through your legs and hips to stand up.", "Lock out your elbows and stabilize the weight overhead.", "Lower the weight back down to shoulder height and repeat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('squat-jump', 'Squat Jumps', 'Tiefe Hocksprünge', 'strength', 'squat', NULL, NULL, 'bilateral', NULL, NULL, '["Jump wide, then close"]', 'wger', 0),
('squat-thrust', 'Squat Thrust', 'Kniebeugen', 'strength', 'squat', NULL, NULL, 'bilateral', NULL, NULL, '["The burpee, or squat thrust, is a full body exercise used in strength training and as an aerobic exercise. The basic movement is performed in four steps and known as a four-count burpee: Begin in a standing position. Move into a squat position with your hands on the ground. (count 1) Kick your feet back into a plank position, while keeping your arms extended. (count 2) Immediately return your feet into squat position. (count 3) Stand up from the squat position (count 4)"]', 'wger', 0),
('stair-master', 'Stair Master', NULL, 'cardio', NULL, NULL, NULL, NULL, NULL, NULL, '["cardio and lower-body strength machine designed to simulate climbing stairs. It provides a low-impact, high-intensity workout that targets the legs, glutes, and core while improving cardiovascular endurance."]', 'wger', 0),
('standing-biceps-stretch', 'Standing Biceps Stretch', NULL, 'stretching', NULL, 'isolation', 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('standing-biceps-stretch-left', 'Standing biceps stretch left', NULL, 'stretching', NULL, NULL, NULL, NULL, NULL, NULL, '["Stand with your left arm close to a wall. Extend your left arm and put your left hand on the wall, then gently turn your body to the right."]', 'wger', 0),
('standing-biceps-stretch-right', 'Standing biceps stretch right', NULL, 'stretching', NULL, NULL, NULL, NULL, NULL, NULL, '["Stand with your right arm close to a wall. Extend your right arm and put your left hand on the wall, then gently turn your body to the right."]', 'wger', 0),
('standing-calf-raise', 'Standing Calf Raises', 'Wadenheben Stehend', 'strength', 'isolation_other', NULL, NULL, NULL, NULL, NULL, '["Get onto the calf raises machine, you should able to completely push your calves down. Stand straight, don''t make a hollow back and don''t bend your legs. Pull yourself up as high as you can. Make a small pause of 1 - 2 seconds and go slowly down."]', 'wger', 0),
('standing-calf-stretch', 'Standing Calf Stretch', NULL, 'stretching', NULL, NULL, NULL, NULL, NULL, NULL, '["This stretch targets the gastrocnemius (the chief muscle of the calf of the leg, which flexes the knee and foot). It is easy to perform anywhere. All you need is a wall or a chair."]', 'wger', 0),
('standing-clamshell', 'Standing Clamshell', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Stand with your feet shoulder-width apart and place your hands together, in front of your face, for balance.", "Lower your body by bending your knees until you''re in a half-squat position.", "Bring your knees close together, until they''re almost touching. This is your starting position.", "Rotate your knees outwards, away from your body, engaging your outer hips and glutes.", "Hold the position for a moment, then slowly bring your knees back to the starting position.", "Continue the movement for your desired number of repetitions."]', 'longhaul-fitness', 0),
('standing-elevated-quad-stretch', 'Standing Elevated Quad Stretch', NULL, 'stretching', NULL, NULL, 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('standing-gastrocnemius-calf-stretch', 'Standing Gastrocnemius Calf Stretch', NULL, 'stretching', NULL, NULL, 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('standing-hamstring-and-calf-stretch', 'Standing Hamstring and Calf Stretch', NULL, 'stretching', NULL, NULL, 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('standing-hip-circle', 'Standing Hip Circles', NULL, 'stretching', NULL, 'isolation', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('standing-hip-flexors', 'Standing Hip Flexors', NULL, 'stretching', NULL, 'isolation', 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('standing-lateral-stretch', 'Standing Lateral Stretch', NULL, 'stretching', NULL, NULL, 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('standing-long-jump', 'Standing Long Jump', NULL, 'plyometrics', NULL, 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 0);
INSERT INTO exercises (id, name_en, name_de, category, movement_pattern, mechanic, force, laterality, level, variation_of, instructions, instructions_source_id, needs_review) VALUES
('standing-pancake', 'Standing Pancake', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Stand and open your legs as wide as possible into a straddle position. Then bend at the hips, pushing them back while keeping your back straight."]', 'wger', 0),
('standing-pancake-good-morning', 'Standing Pancake Good Morning', NULL, 'strength', 'hinge', NULL, NULL, NULL, NULL, NULL, '["Stand with your feet wider than shoulder-width apart and toes pointed slightly outward. Place your hands on the back of your head. Hinge at your hips and lower your upper body towards the ground, keeping your back straight and chest open."]', 'wger', 0),
('standing-pelvic-tilt', 'Standing Pelvic Tilt', NULL, 'stretching', NULL, 'isolation', 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('standing-snatch-grip-behind-neck-press', 'Standing Snatch Grip Behind the Neck Press', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Stand with your feet shoulder-width apart and grip the barbell with a wide snatch grip.", "Position the barbell behind your neck, resting it on your upper traps.", "Engage your core and keep your back straight.", "Press the barbell overhead by extending your arms and pushing the weight up.", "Lock out your elbows at the top of the movement.", "Lower the barbell back down to the starting position behind your neck.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('standing-soleus-and-achilles-stretch', 'Standing Soleus And Achilles Stretch', NULL, 'stretching', NULL, 'isolation', 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('standing-soleus-stretch', 'Standing Soleus Stretch', NULL, 'stretching', NULL, NULL, NULL, NULL, NULL, NULL, '["This stretch targets the Soleus part of your calf. It may be performed with a wall or chair."]', 'wger', 0),
('standing-toe-touches', 'Standing Toe Touches', NULL, 'stretching', NULL, NULL, 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('standing-towel-triceps-extension', 'Standing Towel Triceps Extension', NULL, 'strength', 'elbow_extension', 'isolation', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('star-jump', 'Star Jump', NULL, 'plyometrics', NULL, 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('step-up', 'Step-Up', NULL, 'strength', 'lunge', NULL, NULL, 'unilateral', NULL, NULL, '["Stand upright with a bench or bench-height platform in front of you, feet hip-width apart.", "Place your right foot on the bench, ensuring your entire foot is on the surface.", "Press through your right foot to lift your body up onto the bench, bringing your left foot to meet your right foot.", "Stand tall on the bench with both feet flat and your core engaged.", "Step back down with your left foot, returning to the floor.", "Follow by stepping down with your right foot, coming back to the starting position.", "Repeat the exercise for the desired number of repetitions before switching to lead with the left foot."]', 'longhaul-fitness', 0),
('step-up-knee-raise', 'Step-up with Knee Raise', NULL, 'strength', 'lunge', 'compound', 'push', 'unilateral', 'beginner', NULL, NULL, NULL, 0),
('stomach-vacuum', 'Stomach Vacuum', NULL, 'stretching', NULL, 'isolation', 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('straddle', 'The Straddle', NULL, 'stretching', NULL, NULL, 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('straddle-l-sit', 'Straddle L-Sit', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["With your legs in a sitting saddle position, push your body upwards off the ground. Your legs should be horizontal and point straight outwards. Your arms should be between your legs.", "Hold isometrically as long as required."]', 'wger', 0),
('straight-arm-lat-pulldown', 'Straight Arm Lat Pulldown', NULL, 'strength', 'vertical_pull', NULL, NULL, 'bilateral', NULL, NULL, '["Adjust the cable machine to a high position and attach a straight bar to the cable.", "Stand facing the machine with your feet shoulder-width apart and your knees slightly bent.", "Grasp the bar with both hands using an overhand grip, with your hands slightly wider than shoulder-width apart.", "Engage your core and keep your arms straight as you pull the bar down towards your thighs, using your lats to initiate the movement.", "Pause for a moment at the bottom of the movement, then slowly release the bar back up to the starting position.", "Repeat."]', 'longhaul-fitness', 1),
('straight-arm-pull-down-bar-attachment', 'Straight-arm Pull Down (bar Attachment)', 'Lat-Ziehen Mit Gesteckten Armen Mit (Stange)', 'strength', 'vertical_pull', NULL, NULL, NULL, NULL, NULL, '["Use the straight bar attachment on a high pulley. Grasp the two ends of the bar with your palms facing downward and your arms straight out in front of you. Pull your hands down towards your hips, while keeping your arms straight, then raise them back up to the starting position."]', 'wger', 0),
('straight-arm-pull-down-rope-attachment', 'Straight-arm Pull Down (rope Attachment)', 'Lat-Zug am Seil', 'strength', 'vertical_pull', NULL, NULL, NULL, NULL, NULL, '["Use the rope attachment on a high pulley. Grasp the two ends of the rope with your arms straight out in front of you. Pull your hands down towards your hips, while keeping your arms straight, then raise them back up to the starting position."]', 'wger', 0),
('stride-jump-crossover', 'Stride Jump Crossover', NULL, 'plyometrics', NULL, 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('sumo-deadlift', 'Sumo Deadlift', 'Sumo Kreuzheben', 'strength', 'hinge', NULL, NULL, 'bilateral', NULL, NULL, '["Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the shoulders, which in effect lengthens your arms.", "Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees.", "As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.", "Return the weight to the ground by bending at the hips and controlling the weight on the way down."]', 'wger', 0),
('superman', 'Superman', 'Superman', 'stretching', NULL, 'compound', 'static', NULL, 'beginner', NULL, '["Lay flat on your stomach with your arms extended in front of you on the ground as your legs are lying flat. Lift both your arms and legs at the same time, as if you were flying, and contract the lower back. Make sure that you are breathing and, depending on your fitness level, hold the movement for at least two to five seconds per repetition."]', 'wger', 0),
('supinated-grip-lat-pulldown', 'Supinated Grip Lat Pulldown', NULL, 'strength', 'vertical_pull', NULL, NULL, 'bilateral', NULL, NULL, '["Adjust the weight on the lat pulldown machine to a comfortable level.", "Stand facing the machine and grasp the bar with an underhand grip, with your hands shoulder-width apart.", "Sit down on the bench and adjust the knee pad so that it fits snugly against your thighs.", "Lean back slightly and keep your chest up and your shoulders down.", "Exhale and pull the bar down towards your chest, keeping your elbows close to your body.", "Pause for a moment and squeeze your shoulder blades together.", "Inhale and slowly release the bar back to the starting position, keeping your arms straight but not locked.", "Repeat."]', 'longhaul-fitness', 0),
('suspended-crossess', 'Suspended crossess', NULL, 'cardio', NULL, NULL, NULL, NULL, NULL, NULL, '["Suspension exercise with trx for chest training"]', 'wger', 0),
('suspended-fallout', 'Suspended Fallout', NULL, 'strength', 'isolation_other', 'isolation', 'pull', NULL, 'intermediate', NULL, NULL, NULL, 0),
('suspended-push-up', 'Suspended Push-Up', NULL, 'strength', 'horizontal_push', 'compound', 'push', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('suspended-reverse-crunch', 'Suspended Reverse Crunch', NULL, 'strength', 'isolation_other', 'isolation', 'pull', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('suspended-row', 'Suspended Row', NULL, 'strength', 'horizontal_pull', 'compound', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('suspended-split-squat', 'Suspended Split Squat', NULL, 'strength', 'lunge', 'compound', 'push', 'unilateral', 'intermediate', NULL, NULL, NULL, 0),
('svend-press', 'Svend Press', NULL, 'strength', NULL, 'compound', 'push', NULL, 'beginner', NULL, NULL, NULL, 0),
('talons-fesses', 'Talons fesses', NULL, 'cardio', NULL, NULL, NULL, NULL, NULL, NULL, '["Touch your heels to your buttocks, while remaining static or moving"]', 'wger', 0),
('tire-flip', 'Tire Flip', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Stand facing the tire with your feet wider than shoulder-width apart, toes pointing slightly outwards to ensure a stable wide-leg squat stance.", "Bend at the hips and knees to squat down and grab the bottom of the tire with your fingers underneath and palms facing towards you.", "Keep your chest up, back straight, and engage your core to prepare to lift.", "Drive through your heels and legs, lifting the tire off the ground using your entire body, especially your glutes, hamstrings, and quads.", "Once the tire is lifted, quickly reposition your hands from underneath to a pushing position as the tire reaches knee to waist level.", "Extend your hips forward powerfully, and use the momentum to flip the tire over by pushing it away from you.", "Follow through with your arms to ensure the tire completes the flip and lands flat.", "Reposition your feet as necessary and reset your stance to repeat the process for the desired number of reps."]', 'longhaul-fitness', 0),
('tire-flip-2', 'Tire Flip', NULL, 'strongman', NULL, 'compound', 'pull', NULL, 'intermediate', NULL, NULL, NULL, 1),
('toe-taps', 'Toe Taps', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Toe taps are a core-focused exercise performed lying on your back. Lie flat with your arms by your sides and your legs raised to a tabletop position (knees bent at 90 degrees). Slowly lower one foot to gently tap the floor, keeping your core engaged and your lower back pressed into the ground. Return to the starting position and alternate legs. This exercise strengthens the core while minimizing strain on the lower back."]', 'wger', 0),
('toe-touch', 'Toe Touch', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Stand with your feet closer together. Hinge at your hips and lower your upper body towards your toes. Reach your hands towards your feet, try to touch your toes, the ground, or as far down your legs as you can comfortably go."]', 'wger', 0),
('toe-touchers', 'Toe Touchers', NULL, 'stretching', NULL, 'isolation', 'pull', NULL, 'beginner', NULL, NULL, NULL, 1),
('torso-rotation-stretch', 'Torso rotation stretch', NULL, 'stretching', NULL, NULL, NULL, NULL, NULL, NULL, '["The torso rotation stretch helps improve spinal mobility and relieves tension in the lower back and obliques. It can be performed standing or seated.", "Standing Variation: Stand upright with your feet shoulder-width apart. Place your hands on your hips or extend your arms in front of you. Slowly rotate your torso to one side, keeping your hips stable. Hold for a few seconds, then rotate to the opposite side.", "Seated Variation: Sit on a chair with your feet flat on the floor. Place one hand on the outside of your opposite thigh and gently twist your torso toward that side. Hold the stretch before switching sides."]', 'wger', 0),
('torso-twist', 'TORSO TWIST', NULL, 'strength', 'rotation', NULL, NULL, NULL, NULL, NULL, '["Standing Torso Twist WorkoutTarget your core and improve flexibility with this dynamic standing exercise! The Standing Torso Twist Workout involves twisting your torso while keeping your feet and hips stable, engaging your obliques, and stretching your entire upper body. This movement helps to:Strengthen core musclesIncrease flexibility in the spine and torsoImprove posture and balanceEnhance overall athletic performancePerform 3 sets of 10-15 reps, twisting to each side, to feel the benefits of this effective and efficient workout!"]', 'wger', 0),
('towel-pull-up', 'Towel Pull-Up', NULL, 'strength', 'vertical_pull', NULL, NULL, 'bilateral', NULL, NULL, '["Find a sturdy horizontal bar that can support your body weight.", "Fold a single large towel or two hand towels in half and drape them over the bar.", "Grab the ends of the towel with both hands, palms facing each other.", "Hang from the bar with your arms fully extended and your feet off the ground.", "Pull yourself up towards the bar by bending your elbows and squeezing your shoulder blades together.", "Pause at the top of the movement, with your chin above the bar.", "Lower yourself back down to the starting position with control.", "Repeat for desired number of repetitions."]', 'longhaul-fitness', 0),
('towel-superman', 'Towel Superman', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["In this exercise, you lie flat on your stomach, hold a towel with your arms extended in front of you, and pull it apart to create tension. Then, you move it forward and back under your stomach. This exercise targets the back and shoulder muscles as well as core stability."]', 'wger', 0),
('trail-running-walking', 'Trail Running/Walking', NULL, 'cardio', 'locomotion', NULL, NULL, NULL, 'beginner', NULL, NULL, NULL, 0),
('trap-3-raise', 'Trap-3 Raise', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Hinge forwards and bend your knees slightly. Depress and retract the shoulder you will use. Rest the other hand on your knee.", "Raise your hand about 15 degrees overhead, maintaining the position of your shoulder."]', 'wger', 0),
('trap-bar-deadlift-high-handles', 'Deadlift – Trap Bar High Handles', NULL, 'strength', 'hinge', 'compound', 'pull', 'bilateral', 'beginner', NULL, '["Stand in the center of a loaded trap bar with your feet about hip-width apart.", "Bend at your hips and knees to lower your body, maintaining a flat back, to grasp the high handles of the trap bar.", "Look forward, keeping your chest up, and straighten your back to prepare for the lift.", "Drive through your heels to stand up straight, extending your hips and knees simultaneously while keeping the core engaged.", "At the top of the movement, stand fully upright with your shoulders back.", "Pause briefly at the top of the lift before initiating the return.", "Lower the bar by bending at the hips first, then the knees, maintaining a flat back and controlled movement until the weights are back on the ground.", "Reset your posture and prepare for the next repetition."]', 'longhaul-fitness', 0),
('trap-bar-shrug', 'Shrug –  Trap Bar', NULL, 'strength', 'isolation_other', NULL, NULL, 'bilateral', NULL, NULL, '["Stand inside a trap bar with your feet shoulder-width apart.", "Grasp the handles of the trap bar with an overhand grip.", "Keep your back straight and your core engaged.", "Exhale and lift your shoulders up towards your ears, squeezing your trapezius muscles.", "Hold the shrug position for a second.", "Inhale and slowly lower your shoulders back down to the starting position.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('trap-bar-squat', 'Trap Bar Squat', NULL, 'strength', 'squat', NULL, NULL, 'bilateral', NULL, NULL, '["A combination of squat and deadlift principles with the use of a hex/trap bar, easing stress on the lower back by better centering the weight."]', 'wger', 0),
('trap-press', 'Trap press', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["Laying flat with arm pointing straight upwards, elbow fully extended, use only your shoulder to raise the weight as high as comfortable and back to rest."]', 'wger', 0),
('trazioni-impugnatura-inversa', 'Trazioni impugnatura inversa', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0),
('tricep-rope-pushdowns', 'Tricep Rope Pushdowns', NULL, 'strength', 'elbow_extension', NULL, NULL, NULL, NULL, NULL, '["Setup: Stand facing the cable, feet shoulder-width apart, with a slight forward lean.", "Grip: Hold the rope with palms facing each other and elbows tucked tight to your ribs.", "Execution: Push the rope down until arms are fully straight, pulling the ends apart at the bottom.", "Control: Keep upper arms still and return to the start with a slow, controlled motion."]', 'wger', 0),
('tricep-side-stretch', 'Tricep Side Stretch', NULL, 'stretching', NULL, NULL, 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('triceps-dip-assisted', 'Triceps Dips (Assisted)', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["Assisted triceps dips is a gym work out exercise that targets triceps and also involves chest."]', 'wger', 0),
('triceps-pushdown', 'Triceps Pushdown', NULL, 'strength', 'elbow_extension', NULL, NULL, NULL, NULL, NULL, '["Triceps pushdown on cable using lat bar."]', 'wger', 1),
('triceps-stretch', 'Triceps Stretch', NULL, 'stretching', NULL, 'isolation', 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('triceps-stretch-left', 'Triceps stretch left', NULL, 'stretching', NULL, NULL, NULL, NULL, NULL, NULL, '["Put your right hand on your back, use your left hand to grab your right elbow and gently pull it. Hold this position for a few seconds."]', 'wger', 0),
('triceps-stretch-right', 'Triceps stretch right', NULL, 'stretching', NULL, NULL, NULL, NULL, NULL, NULL, '["Put your right hand on your back, use your left hand to grab your right elbow and gently pull it. Hold this position for a few seconds."]', 'wger', 0),
('trx-dip', 'TRX dips', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, NULL, '["Start with the hands on the suspension trainer and feet on the ground. Your hands should be under your shoulders with the feet slightly in front. Lower yourself by bringing the hips between the handles and flexing the elbows. Extend the elbows to come back to the starting position and repeat."]', 'wger', 0),
('trx-gorilla-biceps-curl', 'TRX gorilla biceps curl', NULL, 'strength', 'elbow_flexion', NULL, NULL, NULL, NULL, NULL, '["We''ll stand facing the TRX straps and grab them with our fists facing each other, facing forward, with our arms fully extended at about shoulder-width apart. We''ll keep our body straight, backward, as in the previous exercises, since we''ll be lifting our body toward the TRX straps by activating our biceps. Our body will be straight, with our feet flat on the floor. This time, we''ll place our arms open to the sides and at chest height. The movement we''ll perform is a contraction toward our chest. To achieve this, we''ll bend our elbows so that, by activating our biceps, we can pull our body toward the straps."]', 'wger', 0),
('trx-hammer-curl', 'TRX hammer curl', NULL, 'strength', 'elbow_flexion', NULL, NULL, NULL, NULL, NULL, '["Place the grips as if they were a continuation of the straps. We will position our arms stretched forward and our body leaning back, completely straight. The biceps muscles will activate as you bend your elbows to bring your body towards the straps. The contraction movement will end with a slight outward movement of the hands, due to the grip we are using."]', 'wger', 0),
('trx-obliques', 'TRX Obliques', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Place your feet in the stirrups and assume a high plank with your hands directly beneath your shoulders.", "Pull your knees to your right elbow, then push them back out and to the centre."]', 'wger', 0),
('trx-roll-out', 'TRX roll out', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0),
('trx-row', 'TRX Rows', NULL, 'strength', 'horizontal_pull', NULL, NULL, NULL, NULL, NULL, '["This exercise serves as a lead-up to Pull Ups."]', 'wger', 0),
('trx-single-arm-bicep-curl', 'Trx Single Arm Bicep Curl', NULL, 'strength', 'elbow_flexion', NULL, NULL, 'unilateral', NULL, NULL, '["Step 1: Stand comfortably and grasp the handles of the suspension system. Step 2: Lean back resting your weight on one arm, keepng the spine neutral. Step 3: Slowly curl to pull your body weight to the up position. Supinate the arm and squeeze as you approach the end position. Step 4: Lower yourself back down and repeat."]', 'wger', 0),
('trx-tricep-extension', 'TRX Tricep Extension', NULL, 'strength', 'elbow_extension', NULL, NULL, NULL, NULL, NULL, '["Attach the TRX or other suspension system overhead, having the handles hanging at chest level or slightly lower. Experiment to see what height allows you to set up in the best way. Stand in front of the handles and grab them with your palms facing down. Engage your abs, squeeze your glutes, take a breath and lean forward, lifting your heels off the floor. Keep your elbows straight. Take another breath and lower yourself slowly by bending your elbows. Go down until your elbows are at a 90-degree angle (to the point where your wrists are above your elbows). Hold the position for a moment. Extend your arms by engaging your triceps and bring yourself to the starting position as you exhale."]', 'wger', 0),
('tuck-crunch', 'Tuck Crunch', NULL, 'strength', 'isolation_other', 'isolation', 'pull', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('tuck-l-sit', 'Tuck L-sit', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["The tuck L-sit is a bodyweight hold where you support yourself on parallel bars, parallettes, or the floor with straight arms while pulling your knees toward your chest. Your hips stay lifted, your spine stays tall, and your feet hover off the ground. The goal is to keep your core tight, shoulders depressed, and arms locked out while maintaining the tucked position. It’s a core-intensive, shoulder-stabilizing static hold often used as a progression toward the full L-sit."]', 'wger', 0),
('tuck-planche', 'Tuck planche', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Basic calisthenics progression for the full planche"]', 'wger', 0),
('typewriter-pull-up', 'Typewriter Pull-ups', NULL, 'strength', 'vertical_pull', NULL, NULL, 'bilateral', NULL, NULL, '["Hang from a pull-up bar with an overhand grip, slightly wider than shoulder-width. Pull yourself up until your chin is above the bar. At the top position, instead of going straight down, shift your body to one side by extending one arm while keeping the other arm bent. Move smoothly from one side to the other, like a typewriter motion, before lowering yourself back down. This exercise increases time under tension and strengthens the lats, biceps, and shoulders while building unilateral pulling strength."]', 'wger', 0),
('unilateral-hip-thrust', 'Unilateral Hip Thrust', NULL, 'strength', 'hinge', NULL, NULL, 'unilateral', NULL, NULL, '["Extend one leg while laying down and start raising your body with one leg touching the ground through the heel."]', 'wger', 0),
('unilateral-lunge', 'Unilateral Lunges', NULL, 'strength', 'lunge', NULL, NULL, 'unilateral', NULL, NULL, '["No stops during movement, hands on the hips."]', 'wger', 0),
('upper-back', 'Upper Back', 'Upper Back', 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Upper Back is suitable for building up the core muscles with a special focus on the deltoid and rhomboid muscles and the upper back muscles"]', 'wger', 0),
('upper-back-leg-grab', 'Upper Back-Leg Grab', NULL, 'stretching', NULL, NULL, 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('upper-back-stretch', 'Upper Back Stretch', NULL, 'stretching', NULL, NULL, 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('upper-external-oblique', 'Upper External Oblique', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Exercise for upper external oblique muscles"]', 'wger', 0),
('upward-stretch', 'Upward Stretch', NULL, 'stretching', NULL, NULL, 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('v-bar-pullup', 'V-Bar Pullup', NULL, 'strength', 'vertical_pull', 'compound', 'pull', 'bilateral', 'beginner', NULL, NULL, NULL, 0),
('v-up', 'V-Up', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Start by lying on your back with your arms extended above your head and your legs straight out in front of you.", "Engage your core muscles and lift your legs up to a 45-degree angle while simultaneously lifting your upper body off the ground.", "Reach your arms forward and try to touch your toes with your fingertips.", "Hold the position long enough to flex your abdominal muscles, then slowly lower your body back down to the starting position.", "Repeat."]', 'longhaul-fitness', 0),
('vpushup', 'Vpushup', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Lift your body off the ground by pushing your arms upwards"]', 'wger', 0),
('w-raise', 'W-Raise', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["This challenging exercise is a variation of reverse crunches that is made up of three parts in which we’re basically drawing an upside down ‘W’ with our legs. Start position is lying face up flat on the floor with legs extended at the low point of the outer leg of the ‘W’. Keeping a strong core and legs straight, go up, rise your hips and then slowly lower your legs down halfway. Then, lifting your legs back up to the top, rise your hips again, maintaining that straight line, use your core strength to finally come back all the way down to the other outer leg of the W. Then you reverse the ‘W’ to return to the start."]', 'wger', 0),
('walking', 'Walking', NULL, 'cardio', 'locomotion', NULL, NULL, NULL, NULL, NULL, '["Walking outdoor or indoor, try keeping a pace of at list 100 steps per minute."]', 'wger', 0),
('walking-bridge', 'walking bridge', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["from a standing position with knees slightly bent and hands resting on the floor. From here, proceed forward with your hands keeping your buttocks contracted and without losing control of your lower back."]', 'wger', 0),
('wall-angels', 'Wall Angels', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["The Wall Angels exercise primarily targets the upper back and shoulder muscles, helping improve posture, shoulder mobility, and scapular control."]', 'wger', 0),
('wall-drills', 'Wall Drills', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Exercises for strengthening knee and leg musculature.", "Lateral Wall Drills March - https://youtu.be/9RiTlJ6Mmek", "Lateral Wall Drills OPEN - https://youtu.be/ADRlN8-Wfdg", "Lateral Wall Drills CROSS - https://youtu.be/hGH2sj0Tzu4"]', 'wger', 0),
('wall-pushup', 'Wall Pushup', NULL, 'strength', 'horizontal_push', NULL, NULL, 'bilateral', NULL, NULL, '["Pushup against a wall"]', 'wger', 0),
('wall-sit', 'Wall-sit', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["The Wall Sit (or wall chair) is an isometric exercise that mainly involves the leg muscles, improving muscular endurance and stability. Here are the main and secondary muscles activated during the exercise."]', 'wger', 0),
('wall-slide', 'Wall Slides', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Stand with heels, shoulders, back of head, and hips touching the wall. Start with biceps straight out and elbows at a 90 degree angle. Straighten the arms while remaining againstthe wall without arching the back off of the wall, mimicking a shoulder press movement."]', 'wger', 0),
('wall-squat', 'Wall Squat', 'Wall Squat', 'strength', 'squat', NULL, NULL, 'bilateral', NULL, NULL, '["Find a nice flat piece of wall and stand with your back leaning against the wall. Slowly slide down the wall while moving your feet away from it, until your thighs are parallel to the ground and both your knees and your hips are bent at a 90° angle. Cross your arms in front of your chest and hold this position for 30 seconds.", "Variant: put a big inflated rubber ball (like a small basketball) between your knees and squeeze the ball while holding the squat position"]', 'wger', 0),
('weighted-bench-dip', 'Weighted Bench Dip', NULL, 'strength', NULL, 'compound', 'push', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('weighted-pull-up', 'Weighted Pull Ups', NULL, 'strength', 'vertical_pull', 'compound', 'pull', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('weighted-squat', 'Weighted Squat', NULL, 'strength', 'squat', 'compound', 'push', 'bilateral', 'intermediate', NULL, NULL, NULL, 0),
('wide-grip-pulldown', 'Wide-grip Pulldown', 'Latzug Breit', 'strength', 'vertical_pull', NULL, NULL, NULL, NULL, NULL, '["Lat pulldowns with a wide grip on the bar."]', 'wger', 0),
('wide-grip-rear-pull-up', 'Wide-Grip Rear Pull-Up', NULL, 'strength', 'vertical_pull', 'compound', 'pull', 'bilateral', 'intermediate', NULL, NULL, NULL, 1),
('wide-pull-up', 'Wide Pull Up', NULL, 'strength', 'vertical_pull', NULL, NULL, 'bilateral', NULL, NULL, '["The grip width for a wide grip pull-up is typically wider than shoulder-width apart, which means your hands will be positioned farther apart than they would be for a standard pull-up. This wider grip targets the latissimus dorsi muscles more effectively, making it an excellent exercise for building upper body strength, particularly in the back muscles."]', 'wger', 0),
('wind-sprint', 'Wind Sprints', NULL, 'strength', NULL, 'compound', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('windmill', 'Windmills', NULL, 'stretching', NULL, NULL, 'pull', NULL, 'intermediate', NULL, NULL, NULL, 1),
('windshield-wiper', 'Windshield Wipers', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["Hang from a pull-up bar, raise your legs to the ceiling. Move lower body from left to right with straight legs like a windshield wiper"]', 'wger', 0),
('worlds-greatest-stretch', 'World''s Greatest Stretch', NULL, 'stretching', NULL, NULL, 'static', NULL, 'intermediate', NULL, NULL, NULL, 0),
('wrist-circle', 'Wrist Circles', NULL, 'stretching', NULL, 'isolation', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('wrist-extensor-rotation-stretch', 'Wrist Extensor Rotation Stretch', NULL, 'stretching', NULL, NULL, NULL, NULL, NULL, NULL, '["Bend your hands at the wrists towards you. Place the back of your hands against a stable object like a bench or the floor with your body in a comfortable position that allows you to push down on your wrists.", "Lean your body forwards to push the wrist into extension, staying within tolerable limits.", "Rotate the elbows in and hold the stretch for up to 10 seconds.", "Rotate the elbows out and hold the stretch for up to 10 seconds.", "Continue alternating the movement on each side for the desired amount of time."]', 'longhaul-fitness', 0),
('wrist-roller', 'Wrist Roller', NULL, 'strength', 'isolation_other', 'isolation', 'pull', NULL, 'beginner', NULL, NULL, NULL, 0),
('yoga-exercise-cow-cat', 'Yoga exercise: Cow-cat', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, NULL, '["First get into the four-footed stance. The hands are underneath the shoulders. The fingers are fanned out wide and ensure a stable stance. It is best to rest your front body weight on your thumbs and index fingers. Now place your legs hip-width apart on the yoga mat. Your thighs should be vertically below your hips. Make sure that your weight is evenly distributed between your hands and knees. Your head is an extension of your spine and you are looking down at your mat. Your back is in a neutral position. Breathe in deeply and start with the cat. With the next exhalation, round your back vertebra by vertebra. Try to pull yourself as far as possible towards the ceiling. Pull your head towards your chest and tilt your pelvis. Now inhale deeply and move into the opposite position, cow pose. Bend your back down, pull your shoulders back slightly and lift your head as far as is comfortable for you. Your gaze is directed upwards. Breathe out consciously and switch back to the cat. With the next exhalation, switch back to cow. Repeat the exercise a few times and make sure that you are in the flow."]', 'wger', 0),
('yoke-walk', 'Yoke Walk', NULL, 'strongman', 'carry', 'compound', NULL, NULL, 'intermediate', NULL, NULL, NULL, 0),
('your-back-quad-stretch', 'On-Your-Back Quad Stretch', NULL, 'stretching', NULL, 'isolation', 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('your-side-quad-stretch', 'On Your Side Quad Stretch', NULL, 'stretching', NULL, 'isolation', 'static', NULL, 'beginner', NULL, NULL, NULL, 0),
('zottman-curl', 'Zottman Curl', NULL, 'strength', 'elbow_flexion', NULL, NULL, NULL, NULL, NULL, '["Stand up straight with a dumbbell in each hand at arm''s length. Keep your elbows close to your torso and palms facing upward.", "Without moving your upper arms, curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position briefly.", "While holding the dumbbells at shoulder height, rotate your wrists until your palms are facing downward.", "Keep your upper arms still, exhale, and start to lower the dumbbells back to the starting position with your palms facing downward in a reverse curl motion.", "Once you have reached the starting position, rotate your wrists back to the initial palms-up grip.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 1),
('alternating-rope-wave', 'Alternating Rope Wave', NULL, 'strength', NULL, NULL, NULL, 'alternating', NULL, 'rope-wave', '["Stand with your feet shoulder-width apart, knees slightly bent, in front of a heavy rope.", "Grip the ends of the rope with both hands. Your palms should be facing inward.", "Tighten your core to stabilize your spine.", "Begin to alternately raise and lower each arm rapidly. The motion should create alternating waves in each of the two ropes.", "Keep the waves going consistently for the desired number of repetitions."]', 'longhaul-fitness', 0),
('band-reverse-box-squat', 'Reverse Band Box Squat', NULL, 'strength', 'squat', 'compound', 'push', 'bilateral', 'intermediate', 'band-box-squat', NULL, NULL, 1),
('band-reverse-deadlift', 'Reverse Band Deadlift', NULL, 'strength', 'hinge', 'compound', 'pull', 'bilateral', 'advanced', 'band-deadlift', NULL, NULL, 1),
('band-reverse-sumo-deadlift', 'Reverse Band Sumo Deadlift', NULL, 'strength', 'hinge', 'compound', 'pull', 'bilateral', 'advanced', 'band-deadlift', NULL, NULL, 1),
('band-sumo-deadlift', 'Sumo Deadlift with Bands', NULL, 'strength', 'hinge', 'compound', 'pull', 'bilateral', 'intermediate', 'band-deadlift', NULL, NULL, 1),
('barbell-bench-press-narrow-grip', 'Bench Press Narrow Grip', 'Bankdrücken Eng', 'strength', 'horizontal_push', 'compound', 'push', 'bilateral', 'beginner', 'barbell-bench-press', '["Lay down on a bench, the bar is directly over your eyes, the knees form a slight angle and the feet are firmly on the ground. Hold the bar with a narrow grip (around 20cm.). Lead the weight slowly down till the arms are parallel to the floor (elbow: right angle), press then the bar up. When bringing the bar down, don''t let it down on your nipples as with the regular bench pressing, but somewhat lower."]', 'wger', 0),
('barbell-bent-over-rowing', 'Bent Over Rowing', 'Rudern Vorgebeugt LH', 'strength', 'horizontal_pull', 'compound', 'pull', 'bilateral', 'beginner', 'barbell-row', '["Holding a barbell with a pronated grip (palms facing down), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.", "Now, while keeping the torso stationary, breathe out and lift the barbell to you. Keep the elbows close to the body and only use the forearms to hold the weight. At the top contracted position, squeeze the back muscles and hold for a brief pause.", "Then inhale and slowly lower the barbell back to the starting position.", "Repeat for the recommended amount of repetitions."]', 'wger', 0),
('barbell-bent-over-rowing-reverse', 'Bent Over Rowing Reverse', 'Rudern Vorgebeugt LH Reverse', 'strength', 'horizontal_pull', NULL, NULL, 'bilateral', NULL, 'barbell-row', '["The same as regular rowing, but holding a reversed grip (your palms pointing forwards):", "Grab the barbell with a wide grIp (slightly more than shoulder wide) and lean forward. Your upper body is not quite parallel to the floor, but forms a slight angle. The chest''s out during the whole exercise.", "Pull now the barbell with a fast movement towards your belly button, not further up. Go slowly down to the initial position. Don''t swing with your body and keep your arms next to your body."]', 'wger', 0),
('barbell-close-grip-feet-up-bench-press', 'Close-Grip Feet-Up Bench Press – Barbell', NULL, 'strength', 'horizontal_push', NULL, NULL, 'bilateral', NULL, 'barbell-feet-up-bench-press', '["Lie flat on a bench with your feet up and your back pressed against the bench.", "Grasp the barbell with your hands shoulder-width apart or just slightly narrower.", "Unrack the barbell and hold it above your chest with your arms extended.", "Lower the barbell to your chest, keeping your elbows close to your body.", "Pause briefly at the bottom of the movement, then press the barbell back up to the starting position.", "Repeat."]', 'longhaul-fitness', 0),
('barbell-close-grip-standing-curl', 'Close-Grip Standing Barbell Curl', NULL, 'strength', 'elbow_flexion', 'isolation', 'pull', 'bilateral', 'beginner', 'barbell-biceps-curl', NULL, NULL, 0),
('barbell-decline-bench-press', 'Decline Bench Press Barbell', 'Negativ Bankdrücken', 'strength', 'horizontal_push', 'compound', 'push', 'bilateral', 'beginner', 'barbell-bench-press', '["Set up the decline bench at a decline angle of your choice.", "Lie down on the bench with your feet secured under the foot pads.", "Grip the barbell with an overhand grip slightly wider than shoulder-width apart.", "Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.", "Inhale and slowly lower the barbell towards your lower chest.", "Pause for a moment when the barbell is just above your chest.", "Exhale and push the barbell back up to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('barbell-deficit-deadlift', 'Deficit Deadlift', 'Defizit Kreuzheben', 'strength', 'hinge', 'compound', 'pull', 'bilateral', 'intermediate', 'barbell-deadlift', '["Preparation", "Stand on weight plate, bumper plate, or shallow elevated platform with loaded bar above feet. Squat down and grasp bar with shoulder width or slightly wider overhand or mixed grip.", "Execution", "Lift bar by extending hips and knees to full extension. Pull shoulders back at top of lift if rounded. Return weights to floor by bending hips back while allowing knees to bend forward, keeping back straight and knees pointed same direction as feet. Repeat.", "Comments", "Throughout lift, keep hips low, shoulders high, arms and back straight. Knees should point same direction as feet throughout movement. Keep bar close to body to improve mechanical leverage. Grip strength and strength endurance often limit ability to perform multiple reps at heavy resistances. Gym chalk, wrist straps, grip work, and mixed grip can be used to enhance grip. Mixed grip indicates one hand holding with overhand grip and other hand holding with underhand grip. Lever barbell jack can be used to lift barbell from floor for easier loading and unloading of weight plates.", "Barbell Deficit Deadlift emphasizes building strength through lowest portion of Deadlift. Target muscle is exercised isometrically. Heavy barbell deadlifts significantly engages Latissmus Dorsi. See Barbell Deficit Deadlift under Gluteus Maximus. Also see Deadlift Analysis."]', 'wger', 1),
('barbell-front-squat', 'Front Squats', 'Front Kniebeuge', 'strength', 'squat', 'compound', 'push', 'bilateral', 'advanced', 'barbell-squat', '["This variation of the squat trains the hamstrings and gluteus maximus. It also works the back extensors and abductors."]', 'wger', 0),
('barbell-front-squat-to-bench', 'Front Barbell Squat To A Bench', NULL, 'strength', 'squat', 'compound', 'push', 'bilateral', 'advanced', 'barbell-squat-to-bench', NULL, NULL, 0),
('barbell-incline-bench-press', 'Incline Bench Press - Barbell', 'Schrägbankdrücken LH', 'strength', 'horizontal_push', 'compound', 'push', 'bilateral', 'beginner', 'barbell-bench-press', '["Set up the incline bench at a 45-degree angle.", "Lie down on the bench with your feet flat on the ground.", "Grip the barbell with your hands slightly wider than shoulder-width apart.", "Unrack the barbell and lower it towards your chest, keeping your elbows tucked in.", "Pause briefly at the bottom of the movement, then press the barbell back up to the starting position.", "Repeat for desired number of reps.", "Rack the barbell once you have completed your set."]', 'longhaul-fitness', 0),
('barbell-incline-close-grip-bench-press', 'Incline Close Grip Barbell Bench Press', NULL, 'strength', 'horizontal_push', NULL, NULL, 'bilateral', NULL, 'barbell-bench-press', '["Narrower grip than regular bench press, just outside shoulder width."]', 'wger', 0),
('barbell-incline-triceps-extension', 'Incline Barbell Triceps Extension', NULL, 'strength', 'elbow_extension', 'isolation', 'push', 'bilateral', 'intermediate', 'barbell-triceps-extension', NULL, NULL, 0),
('barbell-kneeling-jump-squat', 'Kneeling Jump Squat', NULL, 'olympic', 'squat', 'compound', 'push', 'bilateral', 'advanced', 'barbell-squat', NULL, NULL, 0),
('barbell-kneeling-squat', 'Kneeling Squat', NULL, 'strength', 'squat', 'compound', 'push', 'bilateral', 'intermediate', 'barbell-squat', NULL, NULL, 0),
('barbell-lunge-standing', 'Barbell Lunges Standing', NULL, 'strength', 'lunge', NULL, NULL, NULL, NULL, 'barbell-lunge', '["Put barbell on the back of your shoulders. Stand upright, then take the first step forward. Step should bring you forward so that your supporting legs knee can touch the floor. Then stand back up and repeat with the other leg.", "Remember to keep good posture."]', 'wger', 0),
('barbell-narrow-stance-squat', 'Narrow Stance Squats', NULL, 'strength', 'squat', 'compound', 'push', 'bilateral', 'intermediate', 'barbell-squat', NULL, NULL, 0),
('barbell-one-arm-floor-press', 'One Arm Floor Press', NULL, 'strength', 'horizontal_push', 'compound', 'push', 'unilateral', 'intermediate', 'barbell-floor-press', NULL, NULL, 0),
('barbell-one-leg-squat', 'One Leg Barbell Squat', NULL, 'strength', 'squat', 'compound', 'push', 'unilateral', 'advanced', 'barbell-squat', NULL, NULL, 0),
('barbell-pause-deadlift', 'Pause Deadlift – Barbell', NULL, 'strength', 'hinge', NULL, NULL, 'bilateral', NULL, 'barbell-deadlift', '["Stand with your feet hip-width apart and your toes pointing forward.", "Bend at the hips and knees to lower your body down, keeping your back straight and your chest lifted.", "Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.", "Engage your core and lift the barbell off the ground, driving through your heels and keeping your back straight.", "Almost immediately during your lift, pause for a brief moment when the barbell is in front of your lower shins, maintaining tension in your muscles.", "Continue the lift until you''re standing straight.", "Lower the barbell back down to the ground, maintaining control and keeping your back straight.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('barbell-pause-squat', 'Pause Squat – Barbell', NULL, 'strength', 'squat', NULL, NULL, 'bilateral', NULL, 'barbell-squat', '["Start with your feet shoulder-width apart, your toes pointing slightly outward, and the barbell on your shoulders.", "Lower your body into a squat position, keeping your back straight and your knees tracking with your toes.", "Pause at the bottom of the squat for 2-3 seconds.", "Slowly rise back up to the starting position.", "Repeat."]', 'longhaul-fitness', 0),
('barbell-push-press-behind-neck', 'Push Press - Behind the Neck', NULL, 'olympic', 'vertical_push', 'compound', 'push', 'bilateral', 'intermediate', 'barbell-push-press', NULL, NULL, 1),
('barbell-reverse-curl', 'Reverse Curl – Barbell', NULL, 'strength', 'elbow_flexion', 'isolation', 'pull', 'bilateral', 'beginner', 'barbell-biceps-curl', '["Stand up straight with a shoulder-width grip on the barbell, palms facing down (pronated grip). Keep your elbows close to your torso.", "While keeping the upper arms stationary, contract your forearms by raising the bar towards your shoulders, hinging at your elbows. Your forearms should be the only part moving. Keep your wrists straight, focusing on a straight line from your elbow to your knuckles.", "Continue to raise the weight until bar is at shoulder level. Hold the forearm-contracting position for a brief pause.", "Inhale and slowly begin to lower the barbell back to the starting position.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('barbell-reverse-grip-bench-press', 'Reverse Grip Bench Press', NULL, 'strength', 'horizontal_push', NULL, NULL, 'bilateral', NULL, 'barbell-bench-press', '["Upper chest focuses exercise that also works triceps"]', 'wger', 0),
('barbell-reverse-grip-bent-over-row', 'Reverse Grip Bent-Over Rows', NULL, 'strength', 'horizontal_pull', 'compound', 'pull', 'bilateral', 'intermediate', 'barbell-row', NULL, NULL, 0),
('barbell-reverse-grip-curl', 'Reverse Grip Barbell Curls', NULL, 'strength', 'elbow_flexion', NULL, NULL, 'bilateral', NULL, 'barbell-biceps-curl', '["Hold the barbell with an overhand grip (palms facing down) approximately shoulder-width apart. Ensure your back is straight, shoulders slightly pulled back, and arms fully extended. Curl the barbell upwards towards your chest in a controlled motion, keeping your elbows close to your body. The motion should be smooth without any swinging or momentum use. Once the barbell is at chest level, pause briefly to maximize contraction in the biceps and forearms. Slowly lower the barbell back to the starting position with a controlled movement, fully extending your arms."]', 'wger', 0),
('barbell-romanian-deadlift', 'Romanian Deadlift', 'Rumänisches Kreuzheben', 'strength', 'hinge', 'compound', 'pull', 'bilateral', 'intermediate', 'barbell-deadlift', '["Preferably, start with a loaded barbell at hip height on a squat rack. Alternatively, you can lift the barbell from the floor to the starting position.", "Stand with your feet hip-width apart, and grip the barbell with hands just outside your thighs using an overhand grip.", "Begin the movement with a slight bend in your knees, and keep your back straight and chest up throughout the exercise.", "Push your hips back, hinging at the hips to lower the barbell, while keeping it close to your body as the bar descends.", "Lower the weight to just below your knees or to mid-shin level — the exact point depends on your hamstring flexibility, without rounding your back.", "Pause briefly at the bottom of the movement, maintaining a braced core and tension in your hamstrings and glutes.", "Reverse the motion by driving your hips forward to return to a fully upright position, squeezing your glutes at the top of the movement.", "Repeat for the desired number of repetitions, ensuring that the tension is maintained in the target muscles without resting the bar on the floor between reps."]', 'longhaul-fitness', 0),
('barbell-row-overhand', 'Barbell Row (Overhand)', NULL, 'strength', 'horizontal_pull', NULL, NULL, 'bilateral', NULL, 'barbell-row', '["Execution", "Starting position:", "Hold the barbell with arms fully extended toward the floor.", "Maintain tension in your lats and back muscles."]', 'wger', 0),
('barbell-row-underhand', 'Barbell Row (Underhand)', NULL, 'strength', 'horizontal_pull', NULL, NULL, 'bilateral', NULL, 'barbell-row', '["Execution", "Starting position:", "Hold the barbell with arms fully extended toward the floor.", "Maintain tension in your lats and back muscles."]', 'wger', 0),
('barbell-seated-calf-raise', 'Barbell Seated Calf Raise', NULL, 'strength', 'isolation_other', 'isolation', 'push', 'bilateral', 'beginner', 'barbell-calf-raise', NULL, NULL, 1),
('barbell-seated-good-morning', 'Seated Good Morning – Barbell', NULL, 'strength', 'hinge', 'compound', 'pull', 'bilateral', 'intermediate', 'barbell-good-morning', '["Select an appropriate weight barbell and set up a bench for sitting.", "Sit on the bench with feet firmly planted on the ground, slightly wider than shoulder-width apart.", "Position the barbell on your upper back, using a grip slightly wider than shoulder-width.", "Ensure your back is straight, chest up, and core engaged. This is your starting position.", "Bend at the hips, lowering your torso forward while keeping your back flat and core tight.", "Lower your torso until it is nearly parallel with the ground, maintaining control.", "Engage your glutes and core as you raise your torso back to the starting position.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('barbell-seated-shoulder-press', 'Seated Shoulder Press – Barbell', NULL, 'strength', 'vertical_push', 'compound', 'push', 'bilateral', 'intermediate', 'barbell-shoulder-press', '["Start by sitting on a back-supporting bench with your feet firmly planted on the ground.", "Hold the barbell with an overhand grip, slightly wider than shoulder-width apart.", "Bring the barbell to shoulder level, resting it on your upper chest and front shoulders.", "Engage your core and keep your back straight throughout the exercise.", "Press the barbell overhead by extending your arms fully, but without locking your elbows.", "Pause briefly at the top of the movement, then slowly lower the barbell back to the starting position.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('barbell-standing-calf-raise', 'Standing Barbell Calf Raise', NULL, 'strength', 'isolation_other', 'isolation', 'push', 'bilateral', 'beginner', 'barbell-calf-raise', NULL, NULL, 1),
('barbell-standing-military-press', 'Standing Military Press', NULL, 'strength', 'vertical_push', 'compound', 'push', 'bilateral', 'beginner', 'barbell-shoulder-press', NULL, NULL, 0),
('barbell-standing-overhead-triceps-extension', 'Standing Overhead Barbell Triceps Extension', NULL, 'strength', 'elbow_extension', 'isolation', 'push', 'bilateral', 'beginner', 'barbell-overhead-tricep-extension', NULL, NULL, 1),
('barbell-stiff-leg-good-morning', 'Stiff Leg Barbell Good Morning', NULL, 'strength', 'hinge', 'compound', 'push', 'bilateral', 'beginner', 'barbell-good-morning', NULL, NULL, 0),
('barbell-stiff-legged-deadlift', 'Stiff-legged Deadlifts', NULL, 'strength', 'hinge', 'compound', 'pull', 'bilateral', 'intermediate', 'barbell-deadlift', '["Stand with your feet hip-width apart, holding a barbell in front of your thighs with straight arms using an overhand grip.", "Position the bar so it is touching or nearly touching your legs.", "Keep your legs straight or maintain a slight bend in the knees (do not lock them).", "Brace your core, keep your upper back straight while slightly arching your lower back.", "Inhale, then push your hips back and lower the bar towards the ground, hinging at the hips, not the waist.", "Keep the bar close to your body to avoid putting undue stress on your lower back.", "Lower the barbell as far down as your hamstring flexibility allows. You should feel a stretch in your hamstrings. Do not round your spine.", "Exhale as you lift the bar back to the starting position by extending your hips and pushing them forward. Avoid using your back to pull; the motion should come from your hamstrings and glutes.", "Squeeze your glutes at the top of the movement for a second before performing the next repetition.", "Perform the desired number of repetitions while maintaining proper form, keeping the movement controlled and avoiding any jerky motions."]', 'longhaul-fitness', 0),
('barbell-sumo-deadlift', 'Sumo Deadlift – Barbell', NULL, 'strength', 'hinge', 'compound', 'pull', 'bilateral', 'intermediate', 'barbell-deadlift', '["Stand with feet wider than shoulder-width apart and toes pointed outwards.", "Place hands on the barbell with a grip wider than shoulder-width apart and palms facing down.", "Engage core and lift the barbell off the ground, keeping back straight and knees bent.", "As you lift, push hips forward and straighten legs.", "Lower the barbell back down to the ground, keeping back straight and knees bent."]', 'longhaul-fitness', 1),
('barbell-sumo-deadlift-chains', 'Sumo Deadlift with Chains', NULL, 'strength', 'hinge', 'compound', 'pull', 'bilateral', 'intermediate', 'barbell-deadlift-chains', NULL, NULL, 0),
('barbell-sumo-squat', 'Sumo Squat – Barbell', NULL, 'strength', 'squat', NULL, NULL, 'bilateral', NULL, 'barbell-squat', '["Hold a barbell behind your neck, resting it on your shoulders with your elbows pointing down and your palms facing forward.", "Stand with your feet wider than shoulder-width apart and toes pointed out at about a 45-degree angle.", "Keep your chest up, back straight, and weight primarily on your heels. This is your starting position.", "Bend your knees, keeping them in line with your toes, while lowerering your hips down until your thighs are at least parallel to the floor.", "Push through your heels to extend your legs and return to the starting position."]', 'longhaul-fitness', 0),
('barbell-weighted-jump-squat', 'Weighted Jump Squat', NULL, 'strength', 'squat', 'compound', 'push', 'bilateral', 'intermediate', 'barbell-squat', NULL, NULL, 0),
('barbell-wide-grip-bench-press', 'Wide-Grip Barbell Bench Press', NULL, 'strength', 'horizontal_push', 'compound', 'push', 'bilateral', 'intermediate', 'barbell-bench-press', NULL, NULL, 0),
('barbell-wide-grip-decline-bench-press', 'Wide-Grip Decline Barbell Bench Press', NULL, 'strength', 'horizontal_push', 'compound', 'push', 'bilateral', 'intermediate', 'barbell-bench-press', NULL, NULL, 0),
('barbell-wide-grip-decline-pullover', 'Wide-Grip Decline Barbell Pullover', NULL, 'strength', NULL, 'compound', 'pull', 'bilateral', 'intermediate', 'barbell-pullover', NULL, NULL, 0),
('barbell-wide-grip-standing-curl', 'Wide-Grip Standing Barbell Curl', NULL, 'strength', 'elbow_flexion', 'isolation', 'pull', 'bilateral', 'beginner', 'barbell-biceps-curl', NULL, NULL, 0),
('barbell-wide-stance-squat', 'Wide Stance Barbell Squat', NULL, 'strength', 'squat', 'compound', 'push', 'bilateral', 'intermediate', 'barbell-squat', NULL, NULL, 0),
('butterfly-narrow-grip', 'Butterfly Narrow Grip', 'Butterfly Eng', 'strength', 'isolation_other', NULL, NULL, NULL, NULL, 'butterfly', '["The movement is the same as with a regular butterfly, only that the grip is narrow:", "Sit on the butterfly machine, the feet have a good contact with the floor, the upper arms are parallel to the floor. Press your arms together till the handles are practically together (but aren''t!). Go slowly back. The weights should stay all the time in the air."]', 'wger', 0),
('butterfly-reverse', 'Butterfly Reverse', 'Butterfly Reverse', 'strength', 'isolation_other', NULL, NULL, NULL, NULL, 'butterfly', NULL, NULL, 0),
('cable-alternating-shoulder-press', 'Alternating Cable Shoulder Press', NULL, 'strength', 'vertical_push', 'compound', 'push', 'alternating', 'beginner', 'cable-shoulder-press', NULL, NULL, 0),
('cable-behind-back-lateral-raise', 'Behind the Back Cable Lateral Raise', NULL, 'strength', 'isolation_other', NULL, NULL, NULL, NULL, 'cable-side-lateral-raise-back', '["Lateral raises have long been a staple for building capped delts, and lifters use everything from dumbbells and bands to machines and single-arm variations to make them grow."]', 'wger', 0),
('cable-bent-over-flye', 'Bent over Cable Flye', NULL, 'strength', 'isolation_other', NULL, NULL, NULL, NULL, 'cable-fly', '["Holding your upper body at an approximate 105° angle."]', 'wger', 0),
('cable-chest-press-decline', 'Cable Chest Press - Decline', NULL, 'strength', 'horizontal_push', NULL, NULL, NULL, NULL, 'cable-chest-press', '["Single arm chest press done with the cable machine. Use the other arm to brace bodyweight to focus on strength of the press, rather than balancing of the body. Start with the hand as close to the chest as possible, and then press against the cable at a slight decline and aiming towards the center of your chest."]', 'wger', 0),
('cable-chest-press-incline', 'Cable Chest Press - Incline', NULL, 'strength', 'horizontal_push', 'compound', 'push', NULL, 'beginner', 'cable-chest-press', '["Single arm chest press done with the cable machine. Use the other arm to brace bodyweight to focus on strength of the press, rather than balancing of the body. Start with the hand as close to the chest as possible, and then press against the cable at a slight incline and aiming towards the center of your chest."]', 'wger', 0),
('cable-close-grip-front-lat-pulldown', 'Close-Grip Front Lat Pulldown', NULL, 'strength', 'vertical_pull', 'compound', 'pull', 'bilateral', 'beginner', 'cable-wide-grip-lat-pulldown', NULL, NULL, 0),
('cable-hammer-curl-rope', 'Hammer Curl – Cable With Rope', NULL, 'strength', 'elbow_flexion', NULL, NULL, NULL, NULL, 'cable-biceps-curl', '["Attach a rope to the low pulley of a cable machine.", "Stand facing the cable machine with your feet shoulder-width apart and a slight bend in your knees.", "Grab each end of the rope with a neutral grip (palms facing each other) and stand up straight. This is your starting position.", "Keeping your upper arms stationary, exhale as you curl the weights up towards your shoulders by flexing your biceps. Keep your elbows close to your body.", "Pause briefly at the top of the movement, squeezing your biceps.", "Inhale as you slowly lower the rope back to the starting position.", "Repeat for the desired number of reps."]', 'longhaul-fitness', 0),
('cable-incline-flye', 'Incline Cable Flye', NULL, 'strength', 'isolation_other', 'isolation', 'push', NULL, 'intermediate', 'cable-fly', NULL, NULL, 0),
('cable-incline-triceps-extension', 'Cable Incline Triceps Extension', NULL, 'strength', 'elbow_extension', 'isolation', 'push', NULL, 'beginner', 'cable-tricep-pushdown', NULL, NULL, 0),
('cable-kneeling-triceps-extension', 'Kneeling Cable Triceps Extension', NULL, 'strength', 'elbow_extension', 'isolation', 'push', NULL, 'intermediate', 'cable-tricep-pushdown', NULL, NULL, 0),
('cable-lateral-raise-single-arm', 'Cable Lateral Raises (Single Arm)', NULL, 'strength', 'isolation_other', NULL, NULL, 'unilateral', NULL, 'cable-side-lateral-raise', '["Stand upright with your feet shoulder-width apart and your knees slightly bent.", "Hold the cable handle in one hand with an overhand grip.", "Keep your arm straight and your palm facing down.", "Engage your core and maintain a neutral spine.", "Exhale and slowly lift your arm out to the side until it reaches shoulder level.", "Pause for a moment and squeeze your shoulder muscles.", "Inhale and slowly lower your arm back down to the starting position.", "Repeat for the desired number of repetitions.", "Switch sides and perform the exercise with the other arm."]', 'longhaul-fitness', 0),
('cable-lying-curl', 'Lying Cable Curl', NULL, 'strength', 'elbow_flexion', 'isolation', 'pull', NULL, 'intermediate', 'cable-biceps-curl', NULL, NULL, 0),
('cable-lying-triceps-extension', 'Cable Lying Triceps Extension', NULL, 'strength', 'elbow_extension', 'isolation', 'push', NULL, 'beginner', 'cable-tricep-pushdown', NULL, NULL, 0),
('cable-one-arm-lat-pulldown', 'One Arm Lat Pulldown', NULL, 'strength', 'vertical_pull', 'compound', 'pull', 'unilateral', 'beginner', 'cable-wide-grip-lat-pulldown', NULL, NULL, 1),
('cable-one-arm-tricep-extension', 'One Arm Triceps Extensions on Cable', 'Trizeps Seildrücken Einarmig', 'strength', 'elbow_extension', 'isolation', 'push', 'unilateral', 'beginner', 'cable-tricep-pushdown', NULL, NULL, 0),
('cable-one-handed-standing-chest-fly', 'One-Handed Standing Chest Fly – Cable', NULL, 'strength', 'isolation_other', NULL, NULL, 'unilateral', NULL, 'cable-fly', '["Adjust the cable machine pulley to shoulder height and attach a single handle.", "Stand with your side facing the cable machine and grab the handle with your nearest hand.", "Step away from the machine to create tension on the cable, feet shoulder-width apart and knees slightly bent for stability.", "Straighten your arm with a slight bend in the elbow, positioning it parallel to the floor.", "Brace your core and keep your hips and shoulders squared forward. This is your starting position.", "Pull the handle just across your sternum, allowing your chest muscles to fully contract while keeping your arm slightly bent.", "Slowly return the handle to the starting position while controlling the resistance.", "Complete the desired number of repetitions and then switch sides."]', 'longhaul-fitness', 0),
('cable-one-handed-tricep-pushdown', 'One-Handed Tricep Pushdown – Cable', NULL, 'strength', 'elbow_extension', NULL, NULL, 'unilateral', NULL, 'cable-tricep-pushdown', '["Stand facing a cable machine with your feet shoulder-width apart.", "Grasp the cable attachment with one hand, palm facing down.", "Position your elbow at a 90-degree angle and keep it close to your side.", "Engage your core and maintain a neutral spine.", "Exhale and extend your arm down, fully straightening your elbow.", "Pause for a moment, squeezing your tricep muscle.", "Inhale and slowly return your arm to the starting position, maintaining control.", "Repeat for the desired number of repetitions and then switch arms."]', 'longhaul-fitness', 0),
('cable-overhand-curl', 'Overhand Cable Curl', NULL, 'strength', 'elbow_flexion', NULL, NULL, NULL, NULL, 'cable-biceps-curl', '["Hands at shoulder height, curl arms in toward head, then back out."]', 'wger', 0),
('cable-reverse-crunch', 'Cable Reverse Crunch', NULL, 'strength', 'isolation_other', 'isolation', 'pull', 'bilateral', 'beginner', 'cable-crunch', NULL, NULL, 0),
('cable-reverse-curl', 'Reverse Cable Curl', NULL, 'strength', 'elbow_flexion', 'isolation', 'pull', NULL, 'beginner', 'cable-biceps-curl', NULL, NULL, 0),
('cable-reverse-grip-triceps-pushdown', 'Reverse Grip Triceps Pushdown', NULL, 'strength', 'elbow_extension', 'isolation', 'push', NULL, 'beginner', 'cable-tricep-pushdown', NULL, NULL, 0),
('cable-seated-chest-fly', 'Seated Cable chest fly', 'Butterfly am Kabelzug', 'strength', 'isolation_other', NULL, NULL, NULL, NULL, 'cable-fly', '["Place a bench between two cable pulleys and adjust the pulleys so they are at chest/shoulder height when you are seated.", "Grab the handles with a neutral grip and lean against the upright backrest.", "Bring your arms together in front of your chest in a controlled motion, focusing on squeezing your chest muscles. Keep your elbows slightly bent throughout the movement.", "Pause briefly at the top position.", "Slowly lower your arms back to the starting position while maintaining control of the movement.", "Repeat for reps."]', 'wger', 0),
('cable-seated-crunch', 'Cable Seated Crunch', NULL, 'strength', 'isolation_other', 'isolation', 'pull', 'bilateral', 'beginner', 'cable-crunch', NULL, NULL, 0),
('cable-seated-lateral-raise', 'Cable Seated Lateral Raise', NULL, 'strength', 'isolation_other', 'isolation', 'pull', NULL, 'beginner', 'cable-side-lateral-raise', NULL, NULL, 0),
('cable-seated-shoulder-press', 'Seated Cable Shoulder Press', NULL, 'strength', 'vertical_push', 'compound', 'push', NULL, 'beginner', 'cable-shoulder-press', NULL, NULL, 0),
('cable-side-lateral-raise-front', 'Side lateral raise - Front (Cable)', NULL, 'strength', 'isolation_other', NULL, NULL, NULL, NULL, 'cable-side-lateral-raise', '["in a cablerack do a side lateral raise with cable in front of you, with focus in tension on the back of your shoulder."]', 'wger', 0),
('cable-single-arm-crossover', 'Single-Arm Cable Crossover', NULL, 'strength', 'isolation_other', 'isolation', 'push', 'unilateral', 'beginner', 'cable-cross-over', NULL, NULL, 0),
('cable-standing-biceps-curl', 'Standing Biceps Cable Curl', NULL, 'strength', 'elbow_flexion', 'isolation', 'pull', NULL, 'beginner', 'cable-biceps-curl', NULL, NULL, 1),
('cable-standing-chest-fly', 'Standing Chest Fly – Cable', NULL, 'strength', 'isolation_other', NULL, NULL, NULL, NULL, 'cable-fly', '["Stand in front of a cable machine, facing away from the machine, with your feet shoulder-width apart and knees slightly bent.", "Grasp the handles of the cables with your palms facing forward and your arms extended out to the sides at shoulder height.", "Engage your core and maintain a slight bend in your elbows throughout the exercise. Try not to change the degree of elbow bend during the repetitions.", "Exhale and slowly bring your arms forward, until your hands touch, while maintaining the same level of shoulder height.", "Inhale and slowly return your arms back to the starting position, keeping them extended and at shoulder height.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 1),
('cable-standing-chest-press', 'Standing Cable Chest Press', NULL, 'strength', 'horizontal_push', 'compound', 'push', NULL, 'beginner', 'cable-chest-press', NULL, NULL, 0),
('cable-standing-one-arm-curl', 'Standing One-Arm Cable Curl', NULL, 'strength', 'elbow_flexion', 'isolation', 'pull', 'unilateral', 'intermediate', 'cable-biceps-curl', NULL, NULL, 1),
('cable-standing-rope-crunch', 'Standing Rope Crunch', NULL, 'strength', 'isolation_other', 'isolation', 'pull', 'bilateral', 'beginner', 'cable-rope-crunch', NULL, NULL, 0),
('close-grip-lat-pull-down', 'Close-grip Lat Pull Down', 'Latzug Eng', 'strength', 'vertical_pull', NULL, NULL, 'bilateral', NULL, 'lat-pull-down', '["Grip the pull-down bar with your hands closer than shoulder width apart, with your palms facing away from you. Lean back slightly. Pull the bar down towards your chest, keeping your elbows close to your sides as you come down. Pull your shoulders back at the end of the motion."]', 'wger', 0),
('close-grip-press-up', 'Close-grip Press-ups', NULL, 'strength', 'horizontal_push', NULL, NULL, 'bilateral', NULL, 'push-up', '["Drop into a strong plank position, bringing your hands close together until they''re almost touching. (picture 1)Bend your elbows to slowly bring your chest to the floor (picture 2). Keep your elbows close to your body as you push back up explosively. Repeat. Ensure you take your time lowering on each rep, keeping your form sharp."]', 'wger', 0),
('close-grip-push-up', 'Close-Grip Push-Up', NULL, 'strength', 'horizontal_push', NULL, NULL, 'bilateral', NULL, 'push-up-2', '["Start in a plank position with your hands under your shoulders, or just slightly narrower, and your fingers pointing forward.", "Lower your body towards the ground, keeping your elbows close to your sides.", "Push back up to the starting position, keeping your core engaged and your body in a straight line.", "Repeat."]', 'longhaul-fitness', 1),
('decline-crunch', 'Decline Crunch', NULL, 'strength', 'isolation_other', 'isolation', 'pull', 'bilateral', 'intermediate', 'crunch', NULL, NULL, 0),
('decline-oblique-crunch', 'Decline Oblique Crunch', NULL, 'strength', NULL, 'compound', 'pull', 'bilateral', 'beginner', 'oblique-crunch-2', NULL, NULL, 0),
('decline-push-up', 'Decline Pushups', 'Negativ Pushups', 'strength', 'horizontal_push', NULL, NULL, 'bilateral', NULL, 'push-up', '["With your feet raised approximately 30cm on a platform, align your shoulders, elbows and hands, then perform regular pushups. This emphasises the clavicular fibers of the pectoralis major."]', 'wger', 0),
('decline-push-up-2', 'Decline Push-Up', NULL, 'strength', 'horizontal_push', 'compound', 'push', 'bilateral', 'beginner', 'push-up-2', NULL, NULL, 1),
('decline-reverse-crunch', 'Decline Reverse Crunch', NULL, 'strength', NULL, 'compound', 'pull', 'bilateral', 'beginner', 'crunch', NULL, NULL, 0),
('decline-sit-up', 'Decline Sit-Up', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, 'sit-up', '["Position yourself on a decline bench with your feet securely locked in place.", "Place your hands behind your head or across your chest.", "Engage your core and slowly lift your upper body towards your knees.", "Pause briefly at the top of the movement, then slowly lower your upper body back down to the starting position.", "Repeat."]', 'longhaul-fitness', 0),
('deficit-push-up', 'Deficit Push ups', NULL, 'strength', 'horizontal_push', NULL, NULL, 'bilateral', NULL, 'push-up', '["Pushup on blocks or grips, so you can dip lower than the hands in the decent."]', 'wger', 0),
('dumbbell-alternate-incline-curl', 'Alternate Incline Dumbbell Curl', NULL, 'strength', 'elbow_flexion', 'isolation', 'pull', 'alternating', 'beginner', 'dumbbell-biceps-curl', NULL, NULL, 0),
('dumbbell-alternating-arnold-press', 'Alternating Arnold Press – Dumbbell', NULL, 'strength', 'vertical_push', NULL, NULL, 'alternating', NULL, 'dumbbell-arnold-press', '["Begin standing with your feet shoulder-width apart, holding a dumbbell in each hand in front of each shoulder, palms facing your body. This is your starting position.", "Rotate your wrists as you press one dumbbell overhead, turning the palm away from your body during the movement.", "Simultaneously maintain the starting position with the other arm, keeping the dumbbell at shoulder height and palm facing your body.", "Fully extend the pressing arm until it is straight overhead.", "Lower the dumbbell back to the starting position, rotating the wrist back to the starting position.", "Immediately rotate the alternate hand’s wrist, pressing the other dumbbell overhead with the same motion.", "Continue alternating the press between each arm for the desired number of repetitions."]', 'longhaul-fitness', 0),
('dumbbell-alternating-biceps-curl', 'Alternating bicep curls', 'Abwechselnde Bizepscurls', 'strength', 'elbow_flexion', 'isolation', 'pull', 'alternating', 'beginner', 'dumbbell-biceps-curl', '["Starting position:", "Start standing up with dumbbells in each hand, your back straight and feet hip-width apart. Your arms should be relaxed, pointing down. Your knees should be slightly bent, your abs contracted, and your shoulders down.", "Steps:", "Bend one arm at the elbow, bringing the dumbbell up to your shoulder. Your upper arm should remain motionless during this movement.", "Bring the dumbbell back down until your arm is in its original relaxed position.", "Repeat, switching arms."]', 'wger', 0),
('dumbbell-alternating-hammer-curl', 'Alternating dumbbell hammer curl', 'Hammercurl mit Kurzhanteln, abwechselnd', 'strength', 'elbow_flexion', 'isolation', 'pull', 'alternating', 'beginner', 'dumbbell-biceps-curl', '["Stand with your knees slightly bent and your back straight. Hold a dumbbell in each hand, using a neutral grip at your sides."]', 'wger', 0),
('dumbbell-bench-press-neutral-grip', 'Dumbbell Bench Press with Neutral Grip', NULL, 'strength', 'horizontal_push', 'compound', 'push', NULL, 'beginner', 'dumbbell-bench-press', NULL, NULL, 0);
INSERT INTO exercises (id, name_en, name_de, category, movement_pattern, mechanic, force, laterality, level, variation_of, instructions, instructions_source_id, needs_review) VALUES
('dumbbell-bent-over-row', 'Bent Over Dumbbell Rows', 'Rudern Einarmig KH', 'strength', 'horizontal_pull', NULL, NULL, NULL, NULL, 'dumbbell-row', '["With dumbbells in hand, bend at the hip until hands hang just below the knees (similar to straight-legged-deadlift starting position). Keep upper body angle constant while contracting your lats to pull you ellbows back pinching the shoulder blades at the top. Try not to stand up with every rep, check hands go below knees on every rep."]', 'wger', 0),
('dumbbell-close-grip-bench-press', 'Dumbbell close grip bench press', NULL, 'strength', 'horizontal_push', NULL, NULL, NULL, NULL, 'dumbbell-bench-press', '["Lie down with your back on a flat bench. Hold a dumbbell in each hand. Raise your arms towards the ceiling with your palms facing each other and dumbbells pressed together. Slowly lower the dumbbells to your chest, then slowly push them back. Repeat the exercise."]', 'wger', 0),
('dumbbell-close-grip-incline-bench-press', 'Close-Grip Incline Bench Press – Dumbbell', NULL, 'strength', 'horizontal_push', NULL, NULL, NULL, NULL, 'dumbbell-bench-press', '["Set the incline bench to a 30-45 degree angle.", "Grab a pair of dumbbells with a neutral grip and sit on the bench.", "Lie back on the bench, positioning the dumbbells at shoulder width with palms facing each other.", "Engage your core and firmly plant your feet on the ground.", "Press the dumbbells above your chest until your arms are fully extended, making sure they are close to each other without touching.", "Slowly lower the dumbbells back to the starting position just above your chest.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('dumbbell-decline-bench-press', 'Decline Bench Press Dumbbell', 'Negativ Bankdrücken KH', 'strength', 'horizontal_push', 'compound', 'push', NULL, 'beginner', 'dumbbell-bench-press', '["Set up a decline bench at a 45-degree angle.", "Grab a pair of dumbbells and lie down on the bench with your feet secured at the end.", "Hold the dumbbells at chest level with your palms facing forward.", "Lower the dumbbells slowly towards your chest, keeping your elbows at a 45-degree angle.", "Pause for a moment, then push the dumbbells back up to the starting position.", "Repeat."]', 'longhaul-fitness', 0),
('dumbbell-decline-triceps-extension', 'Decline Dumbbell Triceps Extension', NULL, 'strength', 'elbow_extension', 'isolation', 'push', NULL, 'beginner', 'dumbbell-triceps-extension', NULL, NULL, 0),
('dumbbell-fly-decline-bench', 'Fly With Dumbbells, Decline Bench', 'Negativ Fliegende Mit KH', 'strength', 'isolation_other', 'compound', 'push', NULL, 'beginner', 'dumbbell-fly', '["The exercise is the same as with a regular bench:", "Take two dumbbells and lay on a bench, make sure the feet are firmly on the ground and your back is not arched, but has good contact with the bench. The arms are stretched in front of you, about shoulder wide. Bend now the arms a bit and let them down with a half-circle movement to the side. Without changing the angle of the elbow bring them in a fluid movement back up."]', 'wger', 0),
('dumbbell-front-incline-raise', 'Front Incline Dumbbell Raise', NULL, 'strength', 'isolation_other', 'isolation', 'push', NULL, 'beginner', 'dumbbell-raise', NULL, NULL, 0),
('dumbbell-front-squat', 'Dumbbell Front Squat', NULL, 'strength', 'squat', NULL, NULL, 'bilateral', NULL, 'dumbbell-squat', '["This exercise involves holding a dumbbell in each hand at shoulder height and performing a squat. It targets the lower body muscles, including the quads, hamstrings, and glutes, while also engaging the core and upper body."]', 'wger', 0),
('dumbbell-hammer-curl', 'Hammer Curls', 'Hammercurls', 'strength', 'elbow_flexion', 'isolation', 'pull', NULL, 'beginner', 'dumbbell-biceps-curl', '["Stand up straight with your feet shoulder-width apart and hold a dumbbell in each hand with your palms facing your body.", "Keep your elbows close to your torso and exhale as you lift both dumbbells towards the shoulder of their holding hand, until your bicep is fully contracted and the dumbbell is at shoulder level.", "Pause for a second at the top of the movement and squeeze your biceps.", "Lower the dumbbells back down to the starting position in a controlled manner.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('dumbbell-incline-bench-press', 'Incline Bench Press - Dumbbell', 'Schrägbankdrücken KH', 'strength', 'horizontal_push', 'compound', 'push', NULL, 'beginner', 'dumbbell-bench-press', '["Set up an incline bench at a 45-degree angle.", "Choose two dumbbells of equal weight and sit on the bench with them resting on your thighs.", "Lie back on the bench and bring the dumbbells up to your chest, palms facing forward.", "Push the dumbbells up and away from your chest, extending your arms fully but not locking your elbows.", "Slowly lower the dumbbells back down to your chest, keeping your elbows at a 45-degree angle to your body.", "Repeat."]', 'longhaul-fitness', 0),
('dumbbell-incline-bench-reverse-fly', 'Incline Bench Reverse Fly', NULL, 'strength', 'isolation_other', NULL, NULL, NULL, NULL, 'dumbbell-reverse-fly', '["The incline dumbbell reverse fly is an upper-body exercise targeting the posterior or rear deltoids, as well as the postural muscles of the upper back. Because it targets such small muscles, this exercise is usually performed with light weight for high reps, such as 10-15 reps per set or more."]', 'wger', 0),
('dumbbell-incline-chest-press', 'Incline Chest Press DB', NULL, 'strength', 'horizontal_push', NULL, NULL, NULL, NULL, 'dumbbell-chest-press', '["Bench 45° incline", "Hold dumbbells parallel on your chest", "Press up until arms extended"]', 'wger', 0),
('dumbbell-incline-curl', 'Dumbbell Incline Curl', 'Bizeps KH-Curls Schrägbank', 'strength', 'elbow_flexion', 'isolation', 'pull', NULL, 'beginner', 'dumbbell-biceps-curl', '["Adjust the bench to a 45-degree angle.", "Grab a pair of dumbbells and sit on the bench with your back straight.", "Let your arms hang down by your sides with your palms facing forward.", "Slowly curl the dumbbells up towards your shoulders while keeping your elbows close to your body.", "Pause for a moment at the top of the movement, then slowly lower the dumbbells back down to the starting position.", "Repeat."]', 'longhaul-fitness', 0),
('dumbbell-incline-fly', 'Incline Dumbbell Fly', 'Fliegende KH Schrägbank', 'strength', 'isolation_other', 'compound', 'push', NULL, 'beginner', 'dumbbell-fly', '["Use inclined bench. Hold dumbbells straight out to your sides, elbows slightly bent. Bring arms together above you, keeping angle of elbows fixed."]', 'wger', 0),
('dumbbell-incline-hammer-curl', 'Incline Hammer Curls', NULL, 'strength', 'elbow_flexion', 'isolation', 'pull', NULL, 'beginner', 'dumbbell-biceps-curl', NULL, NULL, 0),
('dumbbell-incline-ohp', 'Incline OHP DB', NULL, 'strength', 'vertical_push', NULL, NULL, NULL, NULL, 'dumbbell-shoulder-press', '["Sit on a bench with 45° incline", "Ellbows 45° out", "Move dumbbells down until upper arms are parallel to shoulders", "Move dumbbells up, meeting overhead"]', 'wger', 0),
('dumbbell-incline-row', 'Incline Dumbbell Row', 'Rudern KH Auf Schrägbank', 'strength', 'horizontal_pull', 'compound', 'pull', NULL, 'beginner', 'dumbbell-row', '["Using a neutral grip, lean into an incline bench.", "Take a dumbbell in each hand with a neutral grip, beginning with the arms straight. This will be your starting position.", "Retract the shoulder blades and flex the elbows to row the dumbbells to your side.", "Pause at the top of the motion, and then return to the starting position."]', 'wger', 0),
('dumbbell-lunge-standing', 'Dumbbell Lunges Standing', 'Ausfallschritte Stehend', 'strength', 'lunge', NULL, NULL, NULL, NULL, 'dumbbell-lunge', '["."]', 'wger', 0),
('dumbbell-lying-curl', 'Lying Dumbbell Curls', NULL, 'strength', 'elbow_flexion', NULL, NULL, NULL, NULL, 'dumbbell-biceps-curl', '["Take a dumbbell in each hand and lie backwards on a bench, similar to a classic chest press. Let your arms hang down at your sides, with the dumbbells possibly touching the floor. Now start to lift the dumbbells upwards until your forearms are perpendicular to the ceiling. Slowly lower the dumbbells until they almost touch the floor again. Keep your ellbows in place to minimize cheating."]', 'wger', 0),
('dumbbell-lying-external-shoulder-rotation', 'Lying External Shoulder Rotation – Dumbbell', NULL, 'strength', 'rotation', NULL, NULL, NULL, NULL, 'dumbbell-shoulder-external-rotation', '["Lie on your side on a flat bench with your legs stacked, and your body straight as possible from head to toes.", "Bend your upper arm (the one farthest from the bench) at a 90-degree angle at your elbow with your forearm parallel to the floor, and grasp a dumbbell with a your palm facing the floor.", "Rotate your shoulder while keeping your elbow at a 90-degree angle, moving your forearm towards the ceiling and above your body.", "Rotate your arm upward as far as comfortably possible without lifting your elbow off your torso or your body moving off its position.", "Pause at the top of the movement for a brief moment.", "Slowly return the dumbbell to the starting position by rotating the forearm back to the horizontal starting position while keeping the elbow angle constant.", "Complete all the desired repetitions on one arm before switching to the other arm and repeating the steps."]', 'longhaul-fitness', 0),
('dumbbell-lying-one-arm-lateral-raise', 'Lying One-Arm Lateral Raise', NULL, 'strength', 'isolation_other', 'isolation', 'pull', 'unilateral', 'intermediate', 'dumbbell-lateral-raise', NULL, NULL, 1),
('dumbbell-lying-rear-delt-raise', 'Lying Rear Delt Raise', NULL, 'strength', 'isolation_other', 'isolation', 'pull', NULL, 'intermediate', 'dumbbell-rear-delt-raise', NULL, NULL, 0),
('dumbbell-lying-tricep-extension', 'Lying Dumbbell Tricep Extension', NULL, 'strength', 'elbow_extension', 'isolation', 'push', NULL, 'intermediate', 'dumbbell-triceps-extension', NULL, NULL, 0),
('dumbbell-lying-triceps-kickback', 'Lying Triceps Kickback', NULL, 'strength', 'elbow_extension', NULL, NULL, NULL, NULL, 'dumbbell-tricep-kickback', '["Set the bench to an 60deg angle. Stand still and rest your upper body on the inclined bench, ensuring a nearly straight line of your entire body. Squeeze your shoulder blades together, so that your elbows are located behind your torso with your upper arms nearly parallel to the floor. Lift the dumbbells until your arms form a straight line. Slowly lower the dumbbells back to the initial position. Initial position corresponds to an rectangular position of upper and lower arms."]', 'wger', 0),
('dumbbell-one-arm-bench-press', 'One Arm Dumbbell Bench Press', NULL, 'strength', 'horizontal_push', 'compound', 'push', 'unilateral', 'beginner', 'dumbbell-bench-press', NULL, NULL, 0),
('dumbbell-one-arm-flat-bench-flye', 'One-Arm Flat Bench Dumbbell Flye', NULL, 'strength', 'isolation_other', 'isolation', 'push', 'unilateral', 'beginner', 'dumbbell-fly', NULL, NULL, 0),
('dumbbell-one-arm-incline-lateral-raise', 'One-Arm Incline Lateral Raise', NULL, 'strength', 'isolation_other', 'isolation', 'push', 'unilateral', 'beginner', 'dumbbell-lateral-raise', NULL, NULL, 0),
('dumbbell-one-arm-pronated-triceps-extension', 'One Arm Pronated Dumbbell Triceps Extension', NULL, 'strength', 'elbow_extension', 'isolation', 'push', 'unilateral', 'beginner', 'dumbbell-triceps-extension', NULL, NULL, 1),
('dumbbell-one-arm-shoulder-press', 'Dumbbell One-Arm Shoulder Press', NULL, 'strength', 'vertical_push', 'compound', 'push', 'unilateral', 'intermediate', 'dumbbell-shoulder-press', NULL, NULL, 0),
('dumbbell-one-arm-supinated-triceps-extension', 'One Arm Supinated Dumbbell Triceps Extension', NULL, 'strength', 'elbow_extension', 'isolation', 'push', 'unilateral', 'beginner', 'dumbbell-triceps-extension', NULL, NULL, 0),
('dumbbell-one-arm-triceps-extension', 'Dumbbell One-Arm Triceps Extension', NULL, 'strength', 'elbow_extension', 'isolation', 'push', 'unilateral', 'intermediate', 'dumbbell-triceps-extension', NULL, NULL, 1),
('dumbbell-one-arm-upright-row', 'Dumbbell One-Arm Upright Row', NULL, 'strength', 'vertical_pull', 'compound', 'pull', 'unilateral', 'intermediate', 'dumbbell-upright-row', NULL, NULL, 0),
('dumbbell-one-handed-chest-press', 'One-Handed Chest Press – Dumbbell', NULL, 'strength', 'horizontal_push', NULL, NULL, 'unilateral', NULL, 'dumbbell-chest-press', '["Start by lying flat on a bench with your feet firmly planted on the ground.", "Hold a dumbbell in one hand, with your palm facing towards your feet.", "Extend your arm straight up towards the ceiling, keeping your elbow slightly bent.", "Inhale and slowly lower the dumbbell towards your chest, keeping your elbow at a 90-degree angle.", "Exhale and push the dumbbell back up to the starting position, fully extending your arm.", "Repeat for the desired number of repetitions, then switch to the other hand."]', 'longhaul-fitness', 0),
('dumbbell-one-handed-hammer-curl', 'One-Handed Hammer Curl – Dumbbell', NULL, 'strength', 'elbow_flexion', NULL, NULL, 'unilateral', NULL, 'dumbbell-biceps-curl', '["Select a dumbbell of appropriate weight and position yourself at a preacher curl bench.", "Stand with one foot forward and the other back in a staggered stance.", "Lean slightly forward from the hips and place the back of your upper arm (of the arm that will be curling) on the sloped part of the preacher bench, ensuring your shoulders are open to the side.", "Grasp the dumbbell with a neutral grip (palm facing the wall) and fully extend your arm downwards. This is your starting position.", "Brace your core and curl the dumbbell upwards toward your shoulder, keeping the wrist stable and in a neutral position throughout the movement.", "Pause briefly at the top of the curl to contract the bicep, then slowly lower the dumbbell back to the starting position, controlling the weight as it descends.", "Complete the desired number of repetitions before switching arms."]', 'longhaul-fitness', 0),
('dumbbell-one-handed-row', 'One-Handed Row – Dumbbell', NULL, 'strength', 'horizontal_pull', 'compound', 'pull', 'unilateral', 'beginner', 'dumbbell-row', '["Stand with your feet shoulder-width apart and your knees slightly bent.", "Hold a dumbbell in one hand with your palm facing your body.", "Bend forward at the waist, keeping your back straight and your abs engaged.", "Let the dumbbell hang straight down towards the floor.", "Exhale and pull the dumbbell up towards your chest, keeping your elbow close to your body.", "Squeeze your shoulder blades together at the top of the movement.", "Inhale and slowly lower the dumbbell back down towards the floor.", "Repeat for the desired number of reps, then switch sides and repeat."]', 'longhaul-fitness', 1),
('dumbbell-preacher-hammer-curl', 'Preacher Hammer Dumbbell Curl', NULL, 'strength', 'elbow_flexion', 'isolation', 'pull', NULL, 'beginner', 'dumbbell-preacher-curl', NULL, NULL, 0),
('dumbbell-romanian-deadlift', 'Dumbbell Romanian Deadlift', NULL, 'strength', 'hinge', NULL, NULL, 'bilateral', NULL, 'dumbbell-deadlift', '["Stand with your feet hip-width apart, holding a dumbbell in each hand with palms facing your body.", "Begin with a slight bend in your knees, keep your back straight, chest up, and shoulders back throughout the exercise.", "Push your hips back and hinge at the hips to lower the dumbbells along the front of your legs, maintaining a neutral spine.", "Lower the dumbbells to just below your knees or to mid-shin level, depending on your flexibility, while keeping the weights close to your legs.", "Pause briefly at the bottom of the movement, ensuring your core is braced and your hamstrings and glutes are engaged.", "Thrust your hips forward to lift your torso back to the starting position, simultaneously contracting your glutes at the top of the movement.", "Repeat the movement for the desired number of repetitions without letting the dumbbells touch the floor between reps to keep tension on the muscles."]', 'longhaul-fitness', 0),
('dumbbell-seated-bent-over-one-arm-triceps-extension', 'Seated Bent-Over One-Arm Dumbbell Triceps Extension', NULL, 'strength', 'elbow_extension', 'isolation', 'push', 'unilateral', 'beginner', 'dumbbell-triceps-extension', NULL, NULL, 0),
('dumbbell-seated-bent-over-rear-delt-raise', 'Seated Bent-Over Rear Delt Raise', NULL, 'strength', 'isolation_other', 'isolation', 'pull', NULL, 'intermediate', 'dumbbell-rear-delt-raise', NULL, NULL, 1),
('dumbbell-seated-calf-raise', 'Seated Dumbbell Calf Raise', NULL, 'strength', 'isolation_other', NULL, NULL, NULL, NULL, 'dumbbell-calf-raise', '["The seated dumbbell calf raise is a targeted exercise for strengthening the lower leg muscles. It follows the same movement pattern as the machine version: you place the weight on your knees, and by extending and flexing your ankles, you move the weight."]', 'wger', 0),
('dumbbell-seated-curl', 'Seated Dumbbell Curls', NULL, 'strength', 'elbow_flexion', 'isolation', 'pull', NULL, 'beginner', 'dumbbell-biceps-curl', '["Seated Dumbbell Curls are an effective bicep workout that isolates the muscles by stabilizing the upper body, reducing momentum that can detract from the exercise’s effectiveness. This exercise is performed sitting down with a dumbbell in each hand, focusing on controlled movement to maximize engagement of the bicep muscles."]', 'wger', 0),
('dumbbell-seated-incline-front-raise', 'Seated Incline Front Raise – Dumbbell', NULL, 'strength', 'isolation_other', NULL, NULL, NULL, NULL, 'dumbbell-front-raise', '["Sit on an incline bench set at a 45-degree angle, holding a dumbbell in each hand with palms facing each other.", "Keep your feet flat on the floor, back against the bench, and chest up.", "Start with the dumbbells hanging straight down towards the ground, arms extended.", "Raise the dumbbells in front of you, keeping your arms straight, palms facing down, until they are above shoulder height but not so high to take tension off the front shoulder muscle.", "Pause briefly at the top of the movement.", "Slowly lower the dumbbells back to the starting position.", "Repeat the movement for the desired number of repetitions."]', 'longhaul-fitness', 0),
('dumbbell-seated-one-leg-calf-raise', 'Dumbbell Seated One-Leg Calf Raise', NULL, 'strength', 'isolation_other', 'isolation', 'push', 'unilateral', 'beginner', 'dumbbell-calf-raise', NULL, NULL, 0),
('dumbbell-seated-shoulder-press', 'Seated Shoulder Press – Dumbbell', NULL, 'strength', 'vertical_push', NULL, NULL, NULL, NULL, 'dumbbell-shoulder-press', '["Start by sitting on a bench with a backrest, holding a dumbbell in each hand at shoulder level.", "Ensure that your feet are firmly planted on the ground and your back is straight.", "Press the dumbbells up above your head, extending your arms fully.", "Pause briefly at the top of the movement, then slowly lower the dumbbells back down to shoulder level.", "Repeat."]', 'longhaul-fitness', 0),
('dumbbell-seated-side-lateral-raise', 'Seated Side Lateral Raise', NULL, 'strength', 'isolation_other', 'isolation', 'push', NULL, 'beginner', 'dumbbell-lateral-raise', NULL, NULL, 0),
('dumbbell-single-arm-front-rack-walking-lunge', 'Single-Arm Front Rack Walking Lunge – Dumbbell', NULL, 'strength', 'lunge', NULL, NULL, 'alternating', NULL, 'dumbbell-lunge-walking', '["Stand with feet hip-width apart holding a dumbbell in one hand at shoulder height, with your elbow close to your body, palm facing inward.", "Engage your core to maintain balance and ensure your shoulders are level.", "Step forward with the opposite leg to the dumbbell and lower your body into a lunge until both knees are at around 90-degree angles.", "Ensure your front knee does not extend past your toes and your back knee hovers just above the ground.", "Push off the front foot to bring your rear leg forward, coming back to the standing position.", "Continue the movement by alternating legs as you walk forward, maintaining balance and control throughout.", "Perform an even number of repetitions with the dumbbell in one hand before switching the dumbbell to the other hand and doing the same number of repetitions again."]', 'longhaul-fitness', 0),
('dumbbell-single-arm-preacher-curl', 'Single-arm Preacher Curl', NULL, 'strength', 'elbow_flexion', 'isolation', 'pull', 'unilateral', 'beginner', 'dumbbell-preacher-curl', '["Sit on the preacher curl bench and perform a bicep curl with a dumbbell in one hand. Your other hand can be at rest, or beneath your curling arm''s elbow."]', 'wger', 0),
('dumbbell-single-leg-deadlift', 'Single-Leg Deadlift with Dumbbell', NULL, 'strength', 'hinge', NULL, NULL, 'unilateral', NULL, 'dumbbell-deadlift', '["Starting Position: Stand upright with a slight bend in your knees, holding a dumbbell in one or both hands. Shift your weight onto your supporting leg (e.g., your right leg) and lift your non-supporting foot slightly off the floor.", "The Hinge: Keeping your back flat and core engaged, hinge at your hips, pushing your glutes backward. As your torso lowers, extend your non-supporting leg straight back behind you for balance, keeping your hips square to the floor. The dumbbell(s) should lower toward the ground along the line of your supporting leg.", "Range of Motion: Continue lowering your torso until it is nearly parallel to the floor, or you feel an intense stretch in your supporting hamstring, ensuring your back remains neutral throughout the movement.", "Return to Start: Pause at the bottom, then contract your glutes and hamstrings to slowly raise your torso back to the starting position. Your non-supporting leg should return in line with the supporting one.", "Switch Sides: After completing your desired number of repetitions on one side, switch your weight and repeat the movement on the other leg."]', 'wger', 0),
('dumbbell-single-leg-romanian-deadlift', 'Single-Leg Romanian Deadlift – Dumbbell', NULL, 'strength', 'hinge', NULL, NULL, 'unilateral', NULL, 'dumbbell-deadlift', '["Begin by standing on one leg, with a slight bend in the knee. Keep your other leg off the ground and behind you.", "Hold a dumbbell or kettlebell in the opposite hand of the leg you are standing on.", "Brace your core, keep your chest up, and slowly hinge forward at the hips, keeping your back straight and your shoulders down. As you hinge, lift your non-standing leg behind you, keeping it in line with your torso.", "Continue lowering the weight until you feel a stretch in your hamstring. Your standing knee should be slightly bent but not locked.", "Pause briefly at the bottom of the movement, then slowly reverse the motion by driving your hips forward and standing up tall while bringing your lifted leg back down to the ground.", "Repeat for the desired number of repetitions on one leg before switching to the other."]', 'longhaul-fitness', 0),
('dumbbell-standing-bent-over-one-arm-triceps-extension', 'Standing Bent-Over One-Arm Dumbbell Triceps Extension', NULL, 'strength', 'elbow_extension', 'isolation', 'push', 'unilateral', 'beginner', 'dumbbell-triceps-extension', NULL, NULL, 0),
('dumbbell-standing-bicep-curl', 'Standing Bicep Curl', NULL, 'strength', 'elbow_flexion', NULL, NULL, NULL, NULL, 'dumbbell-biceps-curl', '["Stand holding dumbbells at shoulder width apart. Face forearm upward and keep upper arm still while raising each dumbbell up to your shoulder."]', 'wger', 0),
('dumbbell-standing-calf-raise', 'Standing Dumbbell Calf Raise', NULL, 'strength', 'isolation_other', 'isolation', 'push', NULL, 'intermediate', 'dumbbell-calf-raise', NULL, NULL, 1),
('dumbbell-standing-concentration-curl', 'Standing Concentration Curl', NULL, 'strength', 'elbow_flexion', 'isolation', 'pull', NULL, 'beginner', 'dumbbell-concentration-curl', NULL, NULL, 0),
('dumbbell-standing-external-shoulder-rotation', 'Standing External Shoulder Rotation – Dumbbell', NULL, 'strength', 'rotation', NULL, NULL, NULL, NULL, 'dumbbell-shoulder-external-rotation', '["Stand with feet shoulder-width apart, holding a dumbbell in one hand.", "Bend the arm at the shoulder to raise your upper arm, making it parallel to the floor and perpendicular to your body.", "Bend your forearm at the elbow to a 90-degree angle so that your forearm is parallel to the floor, creating an ''L'' shape with your arm. This is the starting position.", "Keeping your upper arm stationary, rotate your shoulder, lifting the dumbbell towards the ceiling as far as possible without discomfort.", "Pause briefly at the top of the rotation, then slowly return the dumbbell to the starting position.", "Complete the desired number of repetitions, then switch arms and repeat the exercise."]', 'longhaul-fitness', 1),
('dumbbell-standing-one-arm-triceps-extension', 'Standing One-Arm Dumbbell Triceps Extension', NULL, 'strength', 'elbow_extension', 'isolation', 'push', 'unilateral', 'beginner', 'dumbbell-triceps-extension', NULL, NULL, 0),
('dumbbell-standing-reverse-curl', 'Standing Dumbbell Reverse Curl', NULL, 'strength', 'elbow_flexion', 'isolation', 'pull', NULL, 'intermediate', 'dumbbell-biceps-curl', NULL, NULL, 0),
('dumbbell-standing-triceps-extension', 'Standing Dumbbell Triceps Extension', NULL, 'strength', 'elbow_extension', 'isolation', 'push', NULL, 'beginner', 'dumbbell-triceps-extension', NULL, NULL, 1),
('dumbbell-standing-upright-row', 'Standing Dumbbell Upright Row', NULL, 'strength', 'vertical_pull', 'compound', 'pull', NULL, 'beginner', 'dumbbell-upright-row', NULL, NULL, 1),
('dumbbell-stiff-legged-deadlift', 'Stiff-Legged Dumbbell Deadlift', NULL, 'strength', 'hinge', 'compound', 'pull', 'bilateral', 'beginner', 'dumbbell-deadlift', NULL, NULL, 0),
('dumbbell-sumo-squat', 'Sumo Squat – Dumbbell', NULL, 'strength', 'squat', NULL, NULL, 'bilateral', NULL, 'dumbbell-squat', '["Hold a dumbbell in front of your chest with both hands.", "Stand with your feet wider than shoulder-width apart and toes pointed out at about a 45-degree angle.", "Keep your chest up, back straight, and weight primarily on your heels. This is your starting position.", "Bend your knees, keeping them in line with your toes, while lowerering your hips down until your thighs are at least parallel to the floor.", "Push through your heels to extend your legs and return to the starting position."]', 'longhaul-fitness', 0),
('dumbbell-underhand-bench-press', 'DB Underhand bench press', NULL, 'strength', 'horizontal_push', NULL, NULL, NULL, NULL, 'dumbbell-bench-press', '["Underhand grip DB, perform a normal bench press movement, keeping the elbows close to the chest"]', 'wger', 0),
('dumbbell-weighted-crunch', 'Weighted Crunch', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, 'dumbbell-crunch', '["The Weighted Crunch is a variation of the classic crunch exercise that involves adding resistance (a weight) to increase the intensity of the abdominal work.", "Lay down", "(Optional) Bend your knees to add difficulty", "(Optional) Bend your knees and let your feet rest on a bench or a box or something (90 degree angle on knees)", "Lift your head and torso while bending your back forward (if you don''t it''s a sit-up and also involves some back muscles). The higher you go, the more you should feel your abs contracting.", "Go back to starting position an repeat"]', 'wger', 0),
('ez-bar-close-grip-curl', 'Close-Grip EZ Bar Curl', NULL, 'strength', 'elbow_flexion', 'isolation', 'pull', 'bilateral', 'beginner', 'ez-bar-biceps-curl', NULL, NULL, 0),
('ez-bar-reverse-preacher-curl-close-grip', 'Reverse Preacher Curl (Close Grip)', NULL, 'strength', 'elbow_flexion', NULL, NULL, 'bilateral', NULL, 'ez-bar-preacher-curl', '["Sitting reverse on a Biceps Bench with a close grip"]', 'wger', 0),
('front-plank', 'Front Plank', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, 'plank', '["The plank is a bodyweight exercise. As a multi-functional movement, the plank not only targets your abdominal muscles but also the spine and hip. Plank strengthens and tightens your entire body, improves your posture and balance, reduces body fat, and can help boost your metabolism. Exercises such as the “plank pose” help strengthen the stamina of stabilizing abdominal muscles. It can also help relieve back pain associated with a weakening of the function of the stabilizing muscles of the body. Planks are a versatile exercise that targets many of the most important muscle groups in the body, so they can be applied by anyone to improve endurance and overall body strength."]', 'wger', 0),
('incline-crunch', 'Incline Crunches', 'Crunches an Schrägbank', 'strength', NULL, NULL, NULL, 'bilateral', NULL, 'crunch', '["Lay down on your back on a inclined bench, feet are on one end of the bench. Ask a partner or use some other help (barbell, etc.) to keep them fixed, your hands are behind your head. From this position move your upper body up till your head or elbows touch your knees. Do this movement by rolling up your back."]', 'wger', 0),
('incline-push-up', 'Incline Push up', NULL, 'strength', 'horizontal_push', NULL, NULL, 'bilateral', NULL, 'push-up-2', '["Start in a plank position with your hands on an elevated surface, such as a bench or step.", "Place your hands slightly wider than shoulder-width apart and keep your fingers pointing forward.", "Engage your core and glutes to maintain a straight line from your head to your heels.", "Lower your chest towards the bench, keeping your elbows close to your body.", "Pause when your chest is just above the bench.", "Push back up to the starting position, fully extending your arms.", "Repeat."]', 'longhaul-fitness', 0),
('incline-push-up-close-grip', 'Incline Push-Up Close-Grip', NULL, 'strength', 'horizontal_push', 'compound', 'push', 'bilateral', 'beginner', 'push-up', NULL, NULL, 0),
('incline-push-up-reverse-grip', 'Incline Push-Up Reverse Grip', NULL, 'strength', 'horizontal_push', 'compound', 'push', 'bilateral', 'beginner', 'push-up', NULL, NULL, 0),
('incline-push-up-wide', 'Incline Push-Up Wide', NULL, 'strength', 'horizontal_push', 'compound', 'push', 'bilateral', 'beginner', 'push-up-wide', NULL, NULL, 0),
('jump-squat-bodyweight', 'Jump Squat – Bodyweight', NULL, 'strength', 'squat', NULL, NULL, 'bilateral', NULL, 'squat-bodyweight', '["Stand with feet shoulder-width apart, toes slightly pointing outward, knees slightly bent.", "Engage your core and keep your chest up. This is your starting position.", "Lower your body into a squat, bending at the hips and knees until your thighs are parallel to the ground.", "Ensure your knees do not extend past your toes.", "Keep weight distributed evenly across your feet.", "Once at the bottom of the squat, explosively push through your feet to jump upward.", "Swing your arms downward to gain momentum.", "Land softly, with knees slightly bent, returning to the starting position.", "Repeat the jump squat for desired repetitions."]', 'longhaul-fitness', 1),
('kettlebell-alternating-hang-clean', 'Alternating Hang Clean', NULL, 'strength', NULL, 'compound', 'pull', 'alternating', 'intermediate', 'kettlebell-hang-clean', NULL, NULL, 0),
('kettlebell-one-arm-open-palm-clean', 'One-Arm Open Palm Kettlebell Clean', NULL, 'strength', NULL, 'compound', 'pull', 'unilateral', 'intermediate', 'kettlebell-open-palm-clean', NULL, NULL, 0),
('kettlebell-one-arm-swing', 'One-Arm Kettlebell Swings', NULL, 'strength', 'hinge', 'compound', 'pull', 'unilateral', 'intermediate', 'kettlebell-swing', NULL, NULL, 0),
('kneeling-incline-push-up', 'Kneeling Incline Push-Up', NULL, 'strength', 'horizontal_push', NULL, NULL, 'bilateral', NULL, 'push-up-2', '["Start by kneeling on the ground with your hands placed slightly wider than shoulder-width apart on an elevated surface, such as a bench or step.", "Engage your core and lower your chest towards the elevated surface, bending your elbows and keeping them close to your body. Keep your body in a straight line from head to knee.", "Pause briefly when your chest is just above the surface, then push through your hands to extend your arms and return to the starting position.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('kneeling-pallof-press', 'Kneeling Pallof Press', NULL, 'strength', 'anti_rotation', NULL, NULL, NULL, NULL, 'pallof-press', '["Kneel side-on to a cable machine or secure a resistance band at chest height.", "Grasp the handle (or end of the band) with both hands and take a kneeling step away to create tension.", "Position your knees shoulder-width apart for stability.", "Hold the handle or band close to your chest, keeping your hands centered in front of you.", "Engage your core muscles to stabilize your torso. This is your starting position.", "Slowly press the handle or band straight out in front of your chest, keeping your arms straight.", "Ensure your hips and shoulders stay squared and facing forward throughout the movement.", "Hold the fully-pressed position for 1-2 seconds.", "Slowly return the handle or band back to the starting position with control.", "Repeat for the desired number of repetitions.", "Switch sides and perform the exercise to work the core muscles evenly."]', 'longhaul-fitness', 0),
('kneeling-push-up', 'Kneeling Push-Up', NULL, 'strength', 'horizontal_push', NULL, NULL, 'bilateral', NULL, 'push-up-2', '["Start on your hands and knees, with your hands shoulder-width apart and your knees hip-width apart.", "Extend your legs behind you, so that your body forms a straight line from your head to your heels.", "Engage your core and glutes to keep your body in a straight line.", "Lower your body towards the ground by bending your elbows, keeping them close to your body.", "Pause when your chest is just above the ground.", "Push yourself back up to the starting position by straightening your arms.", "Repeat."]', 'longhaul-fitness', 0),
('kneeling-side-plank', 'Kneeling Side Plank', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, 'side-plank-2', '["From a kneeling position on the ground, lean to the right until your right hand or elbow make contact with the ground directly under your right shoulder.", "Your body should form a straight line from your left shoulder (pointing towards the ceiling) to your left knee that stacked on top of the right knee.", "Hold this position, engaging your core, for the desired time.", "Raise back up to a kneeling position and repeat on the other side."]', 'longhaul-fitness', 0),
('kneeling-superman', 'Kneeling Superman', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, 'superman', '["Push one foot back until leg fully extended, concentrating on the having the foot high and pushed back as if pulled.", "Extend arm forward with focus having the shoulder high up.", "Unilateral and static hold."]', 'wger', 0),
('lat-pulldown-wide-grip', 'Lat Pulldown (Wide Grip)', NULL, 'strength', 'vertical_pull', NULL, NULL, 'bilateral', NULL, 'lat-pull-down', '["Execution", "Starting position:", "Arms extended overhead, feeling a stretch in your lats.", "Keep your shoulders depressed (don’t shrug upward).", "Pulling phase (concentric):", "Pull the bar down to your upper chest or collarbone area by driving your elbows down and back.", "Keep your chest lifted and squeeze your shoulder blades together at the bottom."]', 'wger', 0),
('leg-curl-standing', 'Leg Curls (standing)', 'Beinbeuger Stehend', 'strength', 'isolation_other', NULL, NULL, NULL, NULL, 'leg-curl', NULL, NULL, 0),
('leg-raise-standing', 'Leg Raises, Standing', 'Beinheben Aufrecht', 'strength', NULL, NULL, NULL, NULL, NULL, 'leg-raise', '["Put your forearms on the pads on the leg raise machine, the body is hanging freely. Lift now your legs with a fast movement as high as you can, make a short pause of 1sec at the top, and bring them down again. Make sure that during the exercise your body does not swing, only the legs should move."]', 'wger', 0),
('lying-leg-raise', 'Lying Leg Raise', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, 'leg-raise', '["Lie flat on your back on a mat or bench.", "Place your hands by your sides or under your glutes for support.", "Keep your legs straight and together, with your toes pointed towards the ceiling.", "Engage your core muscles by drawing your belly button towards your spine.", "Slowly lift your legs off the ground, keeping them straight, until they are perpendicular to the floor.", "Pause for a moment at the top, squeezing your lower abs.", "Lower your legs back down to the starting position in a controlled manner.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 1),
('machine-decline-bench-press', 'Decline Bench Press – Machine', NULL, 'strength', 'horizontal_push', NULL, NULL, NULL, NULL, 'machine-bench-press', '["Adjust the bench and seat height so that your chest aligns with the decline bench press machine''s handles and your feet are flat on the floor.", "Select the appropriate weight on the weight stack.", "Sit on the machine with your back flat against the back pad.", "Grasp the handles with a firm grip, keeping your wrists straight. This is the starting position.", "Press the handles away from your chest, keeping your elbows at about a 45-degree angle from your body, extending your arms fully without locking your elbows.", "Pause briefly at the top of the press.", "Slowly lower the handles back to the starting position, maintaining control throughout the movement.", "Repeat the press for the desired number of repetitions."]', 'longhaul-fitness', 0),
('machine-incline-bench-press', 'Incline Bench Press – Machine', NULL, 'strength', 'horizontal_push', NULL, NULL, NULL, NULL, 'machine-bench-press', '["Adjust the bench and seat height so that your chest aligns with the incline bench press machine''s handles and your feet are flat on the floor.", "Select the appropriate weight on the weight stack.", "Sit on the machine with your back flat against the back pad.", "Grasp the handles with a firm grip, keeping your wrists straight. This is the starting position.", "Press the handles away from your chest, keeping your elbows at about a 45-degree angle from your body, extending your arms fully without locking your elbows.", "Pause briefly at the top of the press.", "Slowly lower the handles back to the starting position, maintaining control throughout the movement.", "Repeat the press for the desired number of repetitions."]', 'longhaul-fitness', 0),
('machine-leverage-decline-chest-press', 'Leverage Decline Chest Press', NULL, 'strength', 'horizontal_push', 'compound', 'push', NULL, 'beginner', 'machine-leverage-chest-press', NULL, NULL, 0),
('machine-leverage-incline-chest-press', 'Leverage Incline Chest Press', NULL, 'strength', 'horizontal_push', 'compound', 'push', NULL, 'beginner', 'machine-leverage-chest-press', NULL, NULL, 0),
('machine-narrow-stance-hack-squat', 'Narrow Stance Hack Squats', NULL, 'strength', 'squat', 'compound', 'push', 'bilateral', 'intermediate', 'machine-hack-squat', NULL, NULL, 0),
('machine-narrow-stance-leg-press', 'Narrow Stance Leg Press', NULL, 'strength', 'squat', 'compound', 'push', 'bilateral', 'intermediate', 'machine-leg-press', NULL, NULL, 0),
('machine-seated-calf-raise', 'Calf Raise with machine (seated)', NULL, 'strength', 'isolation_other', 'isolation', 'push', NULL, 'beginner', 'machine-calf-raise', '["slow and controlled movement", "do not bounce on lower position", "Kontrollierte Ausführung", "Kein Schwung holen", "Langsame Ausführung"]', 'wger', 1),
('machine-seated-leg-curl', 'Seated Leg Curl', NULL, 'strength', 'isolation_other', 'isolation', 'pull', NULL, 'beginner', 'machine-lying-leg-curl', NULL, NULL, 1),
('machine-single-leg-extension', 'Single-Leg Leg Extension', NULL, 'strength', 'isolation_other', 'isolation', 'push', 'unilateral', 'beginner', 'machine-leg-extension', NULL, NULL, 0),
('machine-standing-calf-raise', 'Standing Calf Raises', NULL, 'strength', 'isolation_other', 'isolation', 'push', NULL, 'beginner', 'machine-calf-raise', NULL, NULL, 1),
('machine-standing-glute-kickback', 'Standing Glute Kickback – Machine', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, 'machine-glute-kickback', '["Adjust the machine to the appropriate height for your body.", "Stand facing the machine with your feet shoulder-width apart and your hands holding onto the handles.", "Engage your glutes and lift one leg straight back behind you, keeping it in line with your body.", "Pause at the top of the movement and squeeze your glutes.", "Lower your leg back down to the starting position and repeat on the other side.", "Complete the desired number of repetitions on each leg."]', 'longhaul-fitness', 1),
('machine-standing-leg-curl', 'Standing Leg Curl', NULL, 'strength', 'isolation_other', 'isolation', 'pull', NULL, 'beginner', 'machine-lying-leg-curl', NULL, NULL, 1),
('medicine-ball-one-arm-slam', 'One-Arm Medicine Ball Slam', NULL, 'strength', NULL, 'compound', 'pull', 'unilateral', 'beginner', 'medicine-ball-slam', NULL, NULL, 0),
('medicine-ball-seated-rotational-slam', 'Seated Rotational Slam – Medicine Ball', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, 'medicine-ball-rotational-slam', '["Sit with your feet extended in front of you, knees bent, and your feet or heels on the ground for stability. Hold the medicine ball with both hands near one hip. This is your starting position.", "Begin the exercise by lifting the medicine ball in a circular motion on the same side, raising it up and over your head.", "Continue the circular motion bringing the ball down with force on the opposite side.", "Release the medicine ball towards the ground as you near the opposite hip from where you started, channeling maximum force through the slam.", "Retrieve the medicine ball, return to the starting position on the opposite hip, and perform the exercise on the other side.", "Repeat the exercise for the desired number of repetitions."]', 'longhaul-fitness', 0),
('neutral-grip-lat-pulldown', 'Neutral Grip Lat Pulldown', NULL, 'strength', 'vertical_pull', NULL, NULL, 'bilateral', NULL, 'lat-pull-down', '["Lat pull downs with a neutral grip on the bar."]', 'wger', 0),
('one-handed-lat-pulldown', 'One-Handed Lat Pulldown', NULL, 'strength', 'vertical_pull', NULL, NULL, 'unilateral', NULL, 'lat-pull-down', '["Adjust the seat height and position yourself in the lat pulldown machine.", "Grasp the lat pulldown bar with one hand, using an overhand grip.", "Engage your core and keep your back straight throughout the exercise.", "Start with your arm fully extended, allowing the weight to be lifted off the stack.", "Exhale and pull the bar down towards your side, focusing on squeezing your lat muscles.", "Pause for a moment at the bottom of the movement, feeling the contraction in your lat.", "Inhale and slowly return the bar to the starting position, fully extending your arm.", "Repeat for the desired number of repetitions and then switch to the other hand."]', 'longhaul-fitness', 0),
('one-handed-plank', 'One-Handed Plank', NULL, 'strength', NULL, NULL, NULL, 'unilateral', NULL, 'plank-2', '["Begin in a standard push-up position with your hands on the ground and elbows aligned below your shoulders, and your body forming a straight line from your head to your heels.", "Spread your legs slightly wider than hip-width apart to provide additional stability.", "Shift your weight onto your left hand as you slowly lift your right hand off the ground, wrapping it behind your back or under your sternum.", "Engage your core, glutes, and thigh muscles to prevent your hips from dropping or rotating.", "Hold the one-handed plank for the desired duration, breathing steadily throughout the exercise.", "Lower your right hand back to the starting plank position with control.", "Repeat the exercise by shifting your weight onto your right hand and wrapping your left hand behind your back or under your sternum."]', 'longhaul-fitness', 0),
('one-legged-glute-bridge', 'One-Legged Glute Bridge', NULL, 'strength', 'hinge', NULL, NULL, 'unilateral', NULL, 'glute-bridge', '["Start by lying on your back with your knees bent and feet flat on the ground.", "Lift your right leg off the ground and extend it straight up towards the ceiling.", "Press your left foot into the ground and lift your hips up towards the ceiling.", "Pause at the top of the movement and squeeze your glutes.", "Lower your hips back down to the ground and repeat for the desired number of reps.", "Switch legs and repeat the exercise on the other side."]', 'longhaul-fitness', 1),
('pause-hack-squat', 'Pause Hack Squats', NULL, 'strength', 'squat', NULL, NULL, 'bilateral', NULL, 'hack-squat', '["Hack Squats but with a 1-2s pause at the bottom of the movement. This makes sure that there is no more elastic energy stored in the muscles."]', 'wger', 0),
('plate-one-handed-pinch', 'One-Handed Plate Pinch', NULL, 'strength', NULL, NULL, NULL, 'unilateral', NULL, 'plate-pinch', '["Choose two weight plates of the same size and weight.", "Stand facing the plates and place them on the ground.", "Bend down and grip the top of each plate with your fingers and thumbs.", "Lift the plates off the ground and hold them beside your body with your arms hanging, elbows straight, but not locked.", "Squeeze your fingers and thumbs together to maintain a strong grip on the plates.", "Hold the plates for a set amount of time. Consider each second one \"repetition\".", "Lower the plates back to the ground and release your grip."]', 'longhaul-fitness', 0),
('pull-up-neutral-grip', 'Pull-Ups (Neutral Grip)', NULL, 'strength', 'vertical_pull', NULL, NULL, 'bilateral', NULL, 'pull-up-2', '["Execution", "Pulling phase (concentric):", "Drive your elbows down and back, pulling your chest toward your hands.", "Keep your shoulders depressed and retracted (avoid shrugging).", "Focus on squeezing your lats and upper back at the top.", "Top position:", "Chin should clear or reach the level of your hands.", "Pause briefly and contract your lats hard."]', 'wger', 0),
('pull-up-wide-grip', 'Pull-Ups (Wide Grip)', NULL, 'strength', 'vertical_pull', NULL, NULL, 'bilateral', NULL, 'pull-up', '["Execution", "Pulling phase (concentric):", "Drive your elbows down and slightly back, pulling your chest toward the bar.", "Focus on leading with your chest, not your chin.", "Keep your shoulders depressed (avoid shrugging).", "Top position:", "Chin should clear the bar (or at least reach bar level).", "Pause for a brief squeeze in your lats."]', 'wger', 0),
('push-up-incline', 'Push-Ups | Incline', NULL, 'strength', 'horizontal_push', 'compound', 'push', 'bilateral', 'beginner', 'push-up', '["Inclined push-ups primarily target the chest muscles (pectoralis major and minor), but also work the triceps, shoulders, and core to a lesser extent. Because the upper body is elevated, the incline push-up places less emphasis on the triceps compared to regular push-ups, which may be beneficial for individuals looking to specifically target their chest muscles."]', 'wger', 1),
('reverse-crunch', 'Reverse crunch', NULL, 'strength', 'isolation_other', 'isolation', 'pull', 'bilateral', 'beginner', 'crunch', '["Lay down", "Place your hands near your butt (often slightly in front or under or both)", "Raise your legs, but about 70% of the way you should be able to also raise your pelvis", "(optional/variable) Hold 1/2 seconds at the top", "Go back to starting position"]', 'wger', 0),
('reverse-nordic-curl', 'Reverse Nordic Curl', NULL, 'strength', NULL, NULL, NULL, NULL, NULL, 'nordic-curl', '["Natural Leg Extension is alternative to Leg Extension machine with no equipment."]', 'wger', 0),
('seated-flat-bench-leg-pull-in', 'Seated Flat Bench Leg Pull-In', NULL, 'strength', NULL, 'compound', 'pull', NULL, 'beginner', 'flat-bench-leg-pull-in', NULL, NULL, 0),
('seated-leg-curl', 'Seated Leg Curl', NULL, 'strength', 'isolation_other', NULL, NULL, NULL, NULL, 'leg-curl', '["Adjust the machine to fit your body size and leg length.", "Sit on the machine with your back against the backrest and your legs straight out in front of you.", "Place your ankles over the padded bar and grasp the handles on the sides of the seat for support.", "Bend your knees and curl your legs towards your buttocks, keeping your back straight and your feet flexed.", "Pause briefly at the bottom of the movement, then slowly straighten your legs back to the starting position.", "Repeat."]', 'longhaul-fitness', 0),
('seated-overhead-stretch', 'Seated Overhead Stretch', NULL, 'stretching', NULL, 'isolation', 'static', NULL, 'beginner', 'overhead-stretch', NULL, NULL, 0),
('single-arm-push-up', 'Single-Arm Push-Up', NULL, 'strength', 'horizontal_push', 'compound', 'push', 'unilateral', 'intermediate', 'push-up', NULL, NULL, 0),
('single-leg-v-up', 'Single-Leg V-Up', NULL, 'strength', NULL, NULL, NULL, 'unilateral', NULL, 'v-up', '["Lie flat on your back on a mat with your arms extended overhead and your legs fully extended.", "Lift one leg towards a 60-degree angle with the floor while simultaneously raising your upper body, reaching your hands towards the raised foot.", "Keep both legs straight, with the non-moving leg remaining on the floor.", "Contract your abdominals as you lift your body, aiming to touch your toes with your hands.", "Hold the V position momentarily, maintaining balance and stability.", "Slowly lower your upper body and leg back to the starting position.", "Repeat the movement with the other leg, alternating legs with each repetition."]', 'longhaul-fitness', 0),
('smith-machine-close-grip-bench-press', 'Smith Machine Close-grip Bench Press', NULL, 'strength', 'horizontal_push', 'compound', 'push', 'bilateral', 'beginner', 'smith-machine-bench-press', '["Perform a standard bench press on the smith machine, but have your hands on the bar about shoulder width apart, and keep your elbows close to your body."]', 'wger', 0),
('smith-machine-decline-press', 'Decline Smith Press', NULL, 'strength', NULL, 'compound', 'push', 'bilateral', 'beginner', 'smith-machine-bench-press', NULL, NULL, 0),
('smith-machine-incline-press', 'Incline Smith Press', NULL, 'strength', NULL, 'compound', 'push', 'bilateral', 'beginner', 'smith-machine-bench-press', '["Adjust the height of the Smith machine bar to a comfortable level for the incline bench press.", "Select the desired weight and load it onto the bar.", "Lie down on the incline bench and position yourself under the bar.", "Grip the bar with a slightly wider than shoulder-width grip and lift it off the rack.", "Lower the bar down to your chest while keeping your elbows tucked in.", "Push the bar back up to the starting position, keeping your core engaged and your back flat on the bench.", "Repeat.", "When finished, carefully rack the bar back onto the Smith machine."]', 'longhaul-fitness', 0),
('smith-machine-one-arm-upright-row', 'Smith Machine One-Arm Upright Row', NULL, 'strength', 'vertical_pull', 'compound', 'pull', 'unilateral', 'beginner', 'smith-machine-upright-row', NULL, NULL, 0),
('smith-machine-reverse-calf-raise', 'Smith Machine Reverse Calf Raises', NULL, 'strength', 'isolation_other', 'isolation', 'push', 'bilateral', 'beginner', 'smith-machine-calf-raise', NULL, NULL, 0),
('smith-machine-seated-shoulder-press', 'Seated Shoulder Press – Smith Machine', NULL, 'strength', 'vertical_push', NULL, NULL, 'bilateral', NULL, 'smith-machine-shoulder-press', '["Sit on a back-supporting seat under a Smith Machine with your back straight and feet flat on the floor.", "Adjust the height of the barbell on the Smith Machine so that it is at shoulder level.", "Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.", "Engage your core and press the barbell upward until your arms are fully extended, but not locked.", "Pause for a moment at the top of the movement, then slowly lower the barbell back down to shoulder level.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('smith-machine-single-leg-split-squat', 'Smith Single-Leg Split Squat', NULL, 'strength', 'lunge', 'compound', 'push', 'unilateral', 'beginner', 'smith-machine-split-squat', NULL, NULL, 0),
('standing-bicycle-crunch', 'Standing Bicycle Crunch', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, 'bicycle-crunch-2', '["Stand upright with your feet hip-width apart.", "Place your hands behind your head, elbows out to the sides.", "Engage your core muscles to stabilize your torso.", "Lift your right knee towards your chest while simultaneously crunching your left elbow towards your right knee.", "Return to the starting position.", "Now, lift your left knee towards your chest while crunching your right elbow towards your left knee.", "Continue alternating between sides for the desired number of repetitions."]', 'longhaul-fitness', 0),
('standing-side-crunch', 'Standing Side Crunches', NULL, 'strength', NULL, NULL, NULL, 'bilateral', NULL, 'side-crunch', '["Standing side crunches are a dynamic exercise that targets the obliques while improving balance and stability. Stand upright with your feet shoulder-width apart and hands behind your head or holding a dumbbell in one hand. Lean your torso to one side, contracting your obliques, while bringing your elbow toward your hip (or crunching toward the weight if using a dumbbell). Return to the starting position and alternate sides or perform all repetitions on one side before switching."]', 'wger', 0),
('sumo-squat', 'Sumo Squats', 'Sumo Kniebeuge', 'strength', 'squat', NULL, NULL, 'bilateral', NULL, 'squat-bodyweight', '["Stand with your feet wider than your shoulders, with your toes pointed out at a 45 degree angle and barbell on your shoulder.", "While keeping your back straight, descend slowly by bending at the knees and hips as if you are sitting down (squatting).", "Lower yourself until your quadriceps and hamstrings are parallel to the floor.", "Return to the starting position by pressing upwards and extending your legs while maintaining an equal distribution of weight on your forefoot and heel."]', 'wger', 0),
('underhand-grip-inverted-row', 'Underhand Grip Inverted Row', NULL, 'strength', 'horizontal_pull', NULL, NULL, NULL, NULL, 'inverted-row-2', '["Set up a barbell or suspension trainer at waist height.", "Stand facing the barbell or suspension trainer and grab it with an underhand grip, hands shoulder-width apart.", "Walk your feet forward until your body is at a slight angle, with your arms extended and your body in a straight line.", "Engage your core and squeeze your shoulder blades together as you pull your chest towards the barbell or suspension trainer.", "Pause for a moment at the top of the movement, then slowly lower yourself back down to the starting position.", "Repeat for the desired number of repetitions."]', 'longhaul-fitness', 0),
('underhand-lat-pull-down', 'Underhand Lat Pull Down', NULL, 'strength', 'vertical_pull', NULL, NULL, 'bilateral', NULL, 'lat-pull-down', '["Grip the pull-down bar with your palms facing you and your hands closer than shoulder-width apart. Lean back slightly and keep your back straight. Pull the bar down towards your chest, pulling your shoulders back slightly at the end of the motion."]', 'wger', 0),
('weighted-push-up', 'Weighted push-ups', NULL, 'strength', 'horizontal_push', NULL, NULL, 'bilateral', NULL, 'push-up', '["Setup: Begin in a standard plank position with a weight plate balanced securely on your upper back.", "Alignment: Maintain a straight line from your head to your heels, engaging your core to prevent your back from sagging.", "Execution: Lower your body until your chest nearly touches the floor, keeping your elbows at a forty-five degrees.", "Ascent: Press through your palms to return to the starting position, fully extending your arms."]', 'wger', 0);
