INSERT INTO source_records (source_id, source_record_id, exercise_id, source_url, license, author, match_method, match_score, raw_json) VALUES
('free-exercise-db', '3_4_Sit-Up', '3-4-sit-up', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/3_4_Sit-Up.json', 'Unlicense', NULL, 'new', NULL, '{"name":"3/4 Sit-Up","force":"pull","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Lie down on the floor and secure your feet. Your legs should be bent at the knees.","Place your hands behind or to the side of your head. You will begin with your back on the ground. This will be your starting position.","Flex your hips and spine to raise your torso toward your knees.","At the top of the contraction your torso should be perpendicular to the ground. Reverse the motion, going only ¾ of the way down.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["3_4_Sit-Up/0.jpg","3_4_Sit-Up/1.jpg"],"id":"3_4_Sit-Up"}'),
('free-exercise-db', '90_90_Hamstring', '90-hamstring', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/90_90_Hamstring.json', 'Unlicense', NULL, 'new', NULL, '{"name":"90/90 Hamstring","force":"push","level":"beginner","mechanic":null,"equipment":"body only","primaryMuscles":["hamstrings"],"secondaryMuscles":["calves"],"instructions":["Lie on your back, with one leg extended straight out.","With the other leg, bend the hip and knee to 90 degrees. You may brace your leg with your hands if necessary. This will be your starting position.","Extend your leg straight into the air, pausing briefly at the top. Return the leg to the starting position.","Repeat for 10-20 repetitions, and then switch to the other leg."],"category":"stretching","images":["90_90_Hamstring/0.jpg","90_90_Hamstring/1.jpg"],"id":"90_90_Hamstring"}'),
('free-exercise-db', 'Ab_Crunch_Machine', 'machine-ab-crunch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Ab_Crunch_Machine.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Ab Crunch Machine","force":"pull","level":"intermediate","mechanic":"isolation","equipment":"machine","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Select a light resistance and sit down on the ab machine placing your feet under the pads provided and grabbing the top handles. Your arms should be bent at a 90 degree angle as you rest the triceps on the pads provided. This will be your starting position.","At the same time, begin to lift the legs up as you crunch your upper torso. Breathe out as you perform this movement. Tip: Be sure to use a slow and controlled motion. Concentrate on using your abs to move the weight while relaxing your legs and feet.","After a second pause, slowly return to the starting position as you breathe in.","Repeat the movement for the prescribed amount of repetitions."],"category":"strength","images":["Ab_Crunch_Machine/0.jpg","Ab_Crunch_Machine/1.jpg"],"id":"Ab_Crunch_Machine"}'),
('free-exercise-db', 'Ab_Roller', 'ab-roller', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Ab_Roller.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Ab Roller","force":"pull","level":"intermediate","mechanic":"compound","equipment":"other","primaryMuscles":["abdominals"],"secondaryMuscles":["shoulders"],"instructions":["Hold the Ab Roller with both hands and kneel on the floor.","Now place the ab roller on the floor in front of you so that you are on all your hands and knees (as in a kneeling push up position). This will be your starting position.","Slowly roll the ab roller straight forward, stretching your body into a straight position. Tip: Go down as far as you can without touching the floor with your body. Breathe in during this portion of the movement.","After a pause at the stretched position, start pulling yourself back to the starting position as you breathe out. Tip: Go slowly and keep your abs tight at all times."],"category":"strength","images":["Ab_Roller/0.jpg","Ab_Roller/1.jpg"],"id":"Ab_Roller"}'),
('free-exercise-db', 'Adductor', 'foam-roller-adductor', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Adductor.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Adductor","force":"static","level":"intermediate","mechanic":"isolation","equipment":"foam roll","primaryMuscles":["adductors"],"secondaryMuscles":[],"instructions":["Lie face down with one leg on a foam roll.","Rotate the leg so that the foam roll contacts against your inner thigh. Shift as much weight onto the foam roll as can be tolerated.","While trying to relax the muscles if the inner thigh, roll over the foam between your hip and knee, holding points of tension for 10-30 seconds. Repeat with the other leg."],"category":"stretching","images":["Adductor/0.jpg","Adductor/1.jpg"],"id":"Adductor"}'),
('free-exercise-db', 'Adductor_Groin', 'adductor-groin', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Adductor_Groin.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Adductor/Groin","force":"static","level":"intermediate","mechanic":null,"equipment":null,"primaryMuscles":["adductors"],"secondaryMuscles":[],"instructions":["Lie on your back with your feet raised towards the ceiling.","Have your partner hold your feet or ankles. Abduct your legs as far as you can. This will be your starting position.","Attempt to squeeze your legs together for 10 or more seconds, while your partner prevents you from doing so.","Now, relax the muscles in your legs as your partner pushes your feet apart, stretching as far as is comfortable for you. Be sure to let your partner know when the stretch is adequate to prevent overstretching or injury."],"category":"stretching","images":["Adductor_Groin/0.jpg","Adductor_Groin/1.jpg"],"id":"Adductor_Groin"}'),
('free-exercise-db', 'Advanced_Kettlebell_Windmill', 'kettlebell-advanced-windmill', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Advanced_Kettlebell_Windmill.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Advanced Kettlebell Windmill","force":"push","level":"intermediate","mechanic":"isolation","equipment":"kettlebells","primaryMuscles":["abdominals"],"secondaryMuscles":["glutes","hamstrings","shoulders"],"instructions":["Clean and press a kettlebell overhead with one arm.","Keeping the kettlebell locked out at all times, push your butt out in the direction of the locked out kettlebell. Keep the non-working arm behind your back and turn your feet out at a forty-five degree angle from the arm with the kettlebell.","Lower yourself as far as possible.","Pause for a second and reverse the motion back to the starting position."],"category":"strength","images":["Advanced_Kettlebell_Windmill/0.jpg","Advanced_Kettlebell_Windmill/1.jpg"],"id":"Advanced_Kettlebell_Windmill"}'),
('free-exercise-db', 'Air_Bike', 'air-bike', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Air_Bike.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Air Bike","force":"pull","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Lie flat on the floor with your lower back pressed to the ground. For this exercise, you will need to put your hands beside your head. Be careful however to not strain with the neck as you perform it. Now lift your shoulders into the crunch position.","Bring knees up to where they are perpendicular to the floor, with your lower legs parallel to the floor. This will be your starting position.","Now simultaneously, slowly go through a cycle pedal motion kicking forward with the right leg and bringing in the knee of the left leg. Bring your right elbow close to your left knee by crunching to the side, as you breathe out.","Go back to the initial position as you breathe in.","Crunch to the opposite side as you cycle your legs and bring closer your left elbow to your right knee and exhale.","Continue alternating in this manner until all of the recommended repetitions for each side have been completed."],"category":"strength","images":["Air_Bike/0.jpg","Air_Bike/1.jpg"],"id":"Air_Bike"}'),
('free-exercise-db', 'All_Fours_Quad_Stretch', 'all-fours-quad-stretch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/All_Fours_Quad_Stretch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"All Fours Quad Stretch","force":"static","level":"intermediate","mechanic":null,"equipment":"body only","primaryMuscles":["quadriceps"],"secondaryMuscles":["quadriceps"],"instructions":["Start off on your hands and knees, then lift your leg off the floor and hold the foot with your hand.","Use your hand to hold the foot or ankle, keeping the knee fully flexed, stretching the quadriceps and hip flexors.","Focus on extending your hips, thrusting them towards the floor. Hold for 10-20 seconds and then switch sides."],"category":"stretching","images":["All_Fours_Quad_Stretch/0.jpg","All_Fours_Quad_Stretch/1.jpg"],"id":"All_Fours_Quad_Stretch"}'),
('free-exercise-db', 'Alternate_Hammer_Curl', 'dumbbell-alternating-hammer-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Alternate_Hammer_Curl.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Alternate Hammer Curl","force":"pull","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["biceps"],"secondaryMuscles":["forearms"],"instructions":["Stand up with your torso upright and a dumbbell in each hand being held at arms length. The elbows should be close to the torso.","The palms of the hands should be facing your torso. This will be your starting position.","While holding the upper arm stationary, curl the right weight forward while contracting the biceps as you breathe out. Continue the movement until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps. Tip: Only the forearms should move.","Slowly begin to bring the dumbbells back to starting position as your breathe in.","Repeat the movement with the left hand. This equals one repetition.","Continue alternating in this manner for the recommended amount of repetitions."],"category":"strength","images":["Alternate_Hammer_Curl/0.jpg","Alternate_Hammer_Curl/1.jpg"],"id":"Alternate_Hammer_Curl"}'),
('free-exercise-db', 'Alternate_Heel_Touchers', 'alternate-heel-touchers', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Alternate_Heel_Touchers.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Alternate Heel Touchers","force":"pull","level":"beginner","mechanic":"isolation","equipment":"body only","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Lie on the floor with the knees bent and the feet on the floor around 18-24 inches apart. Your arms should be extended by your side. This will be your starting position.","Crunch over your torso forward and up about 3-4 inches to the right side and touch your right heel as you hold the contraction for a second. Exhale while performing this movement.","Now go back slowly to the starting position as you inhale.","Now crunch over your torso forward and up around 3-4 inches to the left side and touch your left heel as you hold the contraction for a second. Exhale while performing this movement and then go back to the starting position as you inhale. Now that both heels have been touched, that is considered 1 repetition.","Continue alternating sides in this manner until all prescribed repetitions are done."],"category":"strength","images":["Alternate_Heel_Touchers/0.jpg","Alternate_Heel_Touchers/1.jpg"],"id":"Alternate_Heel_Touchers"}'),
('free-exercise-db', 'Alternate_Incline_Dumbbell_Curl', 'dumbbell-alternate-incline-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Alternate_Incline_Dumbbell_Curl.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Alternate Incline Dumbbell Curl","force":"pull","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["biceps"],"secondaryMuscles":["forearms"],"instructions":["Sit down on an incline bench with a dumbbell in each hand being held at arms length. Tip: Keep the elbows close to the torso.This will be your starting position.","While holding the upper arm stationary, curl the right weight forward while contracting the biceps as you breathe out. As you do so, rotate the hand so that the palm is facing up. Continue the movement until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps. Tip: Only the forearms should move.","Slowly begin to bring the dumbbell back to starting position as your breathe in.","Repeat the movement with the left hand. This equals one repetition.","Continue alternating in this manner for the recommended amount of repetitions."],"category":"strength","images":["Alternate_Incline_Dumbbell_Curl/0.jpg","Alternate_Incline_Dumbbell_Curl/1.jpg"],"id":"Alternate_Incline_Dumbbell_Curl"}'),
('free-exercise-db', 'Alternate_Leg_Diagonal_Bound', 'alternate-leg-diagonal-bound', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Alternate_Leg_Diagonal_Bound.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Alternate Leg Diagonal Bound","force":"push","level":"beginner","mechanic":"compound","equipment":null,"primaryMuscles":["quadriceps"],"secondaryMuscles":["abductors","adductors","calves","glutes","hamstrings"],"instructions":["Assume a comfortable stance with one foot slightly in front of the other.","Begin by pushing off with the front leg, driving the opposite knee forward and as high as possible before landing. Attempt to cover as much distance to each side with each bound.","It may help to use a line on the ground to guage distance from side to side.","Repeat the sequence with the other leg."],"category":"plyometrics","images":["Alternate_Leg_Diagonal_Bound/0.jpg","Alternate_Leg_Diagonal_Bound/1.jpg"],"id":"Alternate_Leg_Diagonal_Bound"}'),
('free-exercise-db', 'Alternating_Cable_Shoulder_Press', 'cable-alternating-shoulder-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Alternating_Cable_Shoulder_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Alternating Cable Shoulder Press","force":"push","level":"beginner","mechanic":"compound","equipment":"cable","primaryMuscles":["shoulders"],"secondaryMuscles":["triceps"],"instructions":["Move the cables to the bottom of the tower and select an appropriate weight.","Grasp the cables and hold them at shoulder height, palms facing forward. This will be your starting position.","Keeping your head and chest up, extend through the elbow to press one side directly over head.","After pausing at the top, return to the starting position and repeat on the opposite side."],"category":"strength","images":["Alternating_Cable_Shoulder_Press/0.jpg","Alternating_Cable_Shoulder_Press/1.jpg"],"id":"Alternating_Cable_Shoulder_Press"}'),
('free-exercise-db', 'Alternating_Deltoid_Raise', 'dumbbell-alternating-deltoid-raise', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Alternating_Deltoid_Raise.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Alternating Deltoid Raise","force":"push","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":[],"instructions":["In a standing position, hold a pair of dumbbells at your side.","Keeping your elbows slightly bent, raise the weights directly in front of you to shoulder height, avoiding any swinging or cheating.","Return the weights to your side.","On the next repetition, raise the weights laterally, raising them out to your side to about shoulder height.","Return the weights to the starting position and continue alternating to the front and side."],"category":"strength","images":["Alternating_Deltoid_Raise/0.jpg","Alternating_Deltoid_Raise/1.jpg"],"id":"Alternating_Deltoid_Raise"}'),
('free-exercise-db', 'Alternating_Floor_Press', 'kettlebell-alternating-floor-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Alternating_Floor_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Alternating Floor Press","force":"push","level":"beginner","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["chest"],"secondaryMuscles":["abdominals","shoulders","triceps"],"instructions":["Lie on the floor with two kettlebells next to your shoulders.","Position one in place on your chest and then the other, gripping the kettlebells on the handle with the palms facing forward.","Extend both arms, so that the kettlebells are being held above your chest. Lower one kettlebell, bringing it to your chest and turn the wrist in the direction of the locked out kettlebell.","Raise the kettlebell and repeat on the opposite side."],"category":"strength","images":["Alternating_Floor_Press/0.jpg","Alternating_Floor_Press/1.jpg"],"id":"Alternating_Floor_Press"}'),
('free-exercise-db', 'Alternating_Hang_Clean', 'kettlebell-alternating-hang-clean', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Alternating_Hang_Clean.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Alternating Hang Clean","force":"pull","level":"intermediate","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["hamstrings"],"secondaryMuscles":["biceps","calves","forearms","glutes","lower back","traps"],"instructions":["Place two kettlebells between your feet. To get in the starting position, push your butt back and look straight ahead.","Clean one kettlebell to your shoulder and hold on to the other kettlebell in a hanging position. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulders. Rotate your wrist as you do so.","Lower the cleaned kettlebell to a hanging position and clean the alternate kettlebell. Repeat."],"category":"strength","images":["Alternating_Hang_Clean/0.jpg","Alternating_Hang_Clean/1.jpg"],"id":"Alternating_Hang_Clean"}'),
('free-exercise-db', 'Alternating_Kettlebell_Press', 'kettlebell-alternating-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Alternating_Kettlebell_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Alternating Kettlebell Press","force":"push","level":"intermediate","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["shoulders"],"secondaryMuscles":["triceps"],"instructions":["Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so.","Press one directly overhead by extending through the elbow, turning it so the palm faces forward while holding the other kettlebell stationary .","Lower the pressed kettlebell to the starting position and immediately press with your other arm."],"category":"strength","images":["Alternating_Kettlebell_Press/0.jpg","Alternating_Kettlebell_Press/1.jpg"],"id":"Alternating_Kettlebell_Press"}'),
('free-exercise-db', 'Alternating_Kettlebell_Row', 'kettlebell-alternating-row', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Alternating_Kettlebell_Row.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Alternating Kettlebell Row","force":"pull","level":"intermediate","mechanic":"isolation","equipment":"kettlebells","primaryMuscles":["middle back"],"secondaryMuscles":["biceps","lats"],"instructions":["Place two kettlebells in front of your feet. Bend your knees slightly and push your butt out as much as possible. As you bend over to get into the starting position grab both kettlebells by the handles.","Pull one kettlebell off of the floor while holding on to the other kettlebell. Retract the shoulder blade of the working side, as you flex the elbow, drawing the kettlebell towards your stomach or rib cage.","Lower the kettlebell in the working arm and repeat with your other arm."],"category":"strength","images":["Alternating_Kettlebell_Row/0.jpg","Alternating_Kettlebell_Row/1.jpg"],"id":"Alternating_Kettlebell_Row"}'),
('free-exercise-db', 'Alternating_Renegade_Row', 'kettlebell-alternating-renegade-row', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Alternating_Renegade_Row.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Alternating Renegade Row","force":"pull","level":"expert","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["middle back"],"secondaryMuscles":["abdominals","biceps","chest","lats","triceps"],"instructions":["Place two kettlebells on the floor about shoulder width apart. Position yourself on your toes and your hands as though you were doing a pushup, with the body straight and extended. Use the handles of the kettlebells to support your upper body. You may need to position your feet wide for support.","Push one kettlebell into the floor and row the other kettlebell, retracting the shoulder blade of the working side as you flex the elbow, pulling it to your side.","Then lower the kettlebell to the floor and begin the kettlebell in the opposite hand. Repeat for several reps."],"category":"strength","images":["Alternating_Renegade_Row/0.jpg","Alternating_Renegade_Row/1.jpg"],"id":"Alternating_Renegade_Row"}'),
('free-exercise-db', 'Ankle_Circles', 'ankle-circle', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Ankle_Circles.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Ankle Circles","force":"pull","level":"beginner","mechanic":"isolation","equipment":null,"primaryMuscles":["calves"],"secondaryMuscles":[],"instructions":["Use a sturdy object like a squat rack to hold yourself.","Lift the right leg in the air (just around 2 inches from the floor) and perform a circular motion with the big toe. Pretend that you are drawing a big circle with it. Tip: One circle equals 1 repetition. Breathe normally as you perform the movement.","When you are done with the right foot, then repeat with the left leg."],"category":"stretching","images":["Ankle_Circles/0.jpg","Ankle_Circles/1.jpg"],"id":"Ankle_Circles"}'),
('free-exercise-db', 'Ankle_On_The_Knee', 'ankle-knee', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Ankle_On_The_Knee.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Ankle On The Knee","force":"static","level":"beginner","mechanic":null,"equipment":null,"primaryMuscles":["glutes"],"secondaryMuscles":[],"instructions":["From a lying position, bend your knees and keep your feet on the floor.","Place your ankle of one foot on your opposite knee.","Grasp the thigh or knee of the bottom leg and pull both of your legs into the chest. Relax your neck and shoulders. Hold for 10-20 seconds and then switch sides."],"category":"stretching","images":["Ankle_On_The_Knee/0.jpg","Ankle_On_The_Knee/1.jpg"],"id":"Ankle_On_The_Knee"}'),
('free-exercise-db', 'Anterior_Tibialis-SMR', 'anterior-tibialis-smr', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Anterior_Tibialis-SMR.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Anterior Tibialis-SMR","force":"static","level":"intermediate","mechanic":null,"equipment":"other","primaryMuscles":["calves"],"secondaryMuscles":[],"instructions":["Begin seated on the ground with your legs bent and your feet on the floor.","Using a Muscle Roller or a rolling pin, apply pressure to the muscles on the outside of your shins. Work from just below the knee to above the ankle, pausing at points of tension for 10-30 seconds. Repeat on the other leg."],"category":"stretching","images":["Anterior_Tibialis-SMR/0.jpg","Anterior_Tibialis-SMR/1.jpg"],"id":"Anterior_Tibialis-SMR"}'),
('free-exercise-db', 'Anti-Gravity_Press', 'barbell-anti-gravity-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Anti-Gravity_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Anti-Gravity Press","force":"push","level":"beginner","mechanic":"compound","equipment":"barbell","primaryMuscles":["shoulders"],"secondaryMuscles":["middle back","traps","triceps"],"instructions":["Place a bar on the ground behind the head of an incline bench.","Lay on the bench face down. With a pronated grip, pick the barbell up from the floor. Flex the elbows, performing a reverse curl to bring the bar near your chest. This will be your starting position.","To begin, press the barbell out in front of your head by extending your elbows. Keep your arms parallel to the ground throughout the movement.","Return to the starting position and repeat to complete the set."],"category":"strength","images":["Anti-Gravity_Press/0.jpg","Anti-Gravity_Press/1.jpg"],"id":"Anti-Gravity_Press"}'),
('free-exercise-db', 'Arm_Circles', 'arm-circle', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Arm_Circles.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Arm Circles","force":"push","level":"beginner","mechanic":"isolation","equipment":null,"primaryMuscles":["shoulders"],"secondaryMuscles":["traps"],"instructions":["Stand up and extend your arms straight out by the sides. The arms should be parallel to the floor and perpendicular (90-degree angle) to your torso. This will be your starting position.","Slowly start to make circles of about 1 foot in diameter with each outstretched arm. Breathe normally as you perform the movement.","Continue the circular motion of the outstretched arms for about ten seconds. Then reverse the movement, going the opposite direction."],"category":"stretching","images":["Arm_Circles/0.jpg","Arm_Circles/1.jpg"],"id":"Arm_Circles"}'),
('free-exercise-db', 'Arnold_Dumbbell_Press', 'dumbbell-arnold-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Arnold_Dumbbell_Press.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Arnold Dumbbell Press","force":"push","level":"intermediate","mechanic":"compound","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":["triceps"],"instructions":["Sit on an exercise bench with back support and hold two dumbbells in front of you at about upper chest level with your palms facing your body and your elbows bent. Tip: Your arms should be next to your torso. The starting position should look like the contracted portion of a dumbbell curl.","Now to perform the movement, raise the dumbbells as you rotate the palms of your hands until they are facing forward.","Continue lifting the dumbbells until your arms are extended above you in straight arm position. Breathe out as you perform this portion of the movement.","After a second pause at the top, begin to lower the dumbbells to the original position by rotating the palms of your hands towards you. Tip: The left arm will be rotated in a counter clockwise manner while the right one will be rotated clockwise. Breathe in as you perform this portion of the movement.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Arnold_Dumbbell_Press/0.jpg","Arnold_Dumbbell_Press/1.jpg"],"id":"Arnold_Dumbbell_Press"}'),
('free-exercise-db', 'Around_The_Worlds', 'dumbbell-around-worlds', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Around_The_Worlds.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Around The Worlds","force":"push","level":"intermediate","mechanic":"compound","equipment":"dumbbell","primaryMuscles":["chest"],"secondaryMuscles":["shoulders"],"instructions":["Lay down on a flat bench holding a dumbbell in each hand with the palms of the hands facing towards the ceiling. Tip: Your arms should be parallel to the floor and next to your thighs. To avoid injury, make sure that you keep your elbows slightly bent. This will be your starting position.","Now move the dumbbells by creating a semi-circle as you displace them from the initial position to over the head. All of the movement should happen with the arms parallel to the floor at all times. Breathe in as you perform this portion of the movement.","Reverse the movement to return the weight to the starting position as you exhale."],"category":"strength","images":["Around_The_Worlds/0.jpg","Around_The_Worlds/1.jpg"],"id":"Around_The_Worlds"}'),
('free-exercise-db', 'Atlas_Stone_Trainer', 'atlas-stone-trainer', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Atlas_Stone_Trainer.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Atlas Stone Trainer","force":"pull","level":"intermediate","mechanic":"compound","equipment":"other","primaryMuscles":["lower back"],"secondaryMuscles":["biceps","forearms","glutes","hamstrings","quadriceps"],"instructions":["This trainer is effective for developing Atlas Stone strength for those who don''t have access to stones, and are typically made from bar ends or heavy pipe.","Begin by loading the desired weight onto the bar. Straddle the weight, wrapping your arms around the implement, bending at the hips.","Begin by pulling the weight up past the knees, extending through the hips. As the weight clears the knees, it can be lapped by resting it on your thighs and sitting back, hugging it tightly to your chest.","Finish the movement by extending through your hips and knees to raise the weight as high as possible. The weight can be returned to the lap or to the ground for successive repetitions."],"category":"strongman","images":["Atlas_Stone_Trainer/0.jpg","Atlas_Stone_Trainer/1.jpg"],"id":"Atlas_Stone_Trainer"}'),
('free-exercise-db', 'Atlas_Stones', 'atlas-stones', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Atlas_Stones.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Atlas Stones","force":"pull","level":"expert","mechanic":"compound","equipment":"other","primaryMuscles":["lower back"],"secondaryMuscles":["abdominals","adductors","biceps","calves","forearms","glutes","hamstrings","middle back","quadriceps","traps"],"instructions":["Begin with the atlas stone between your feet. Bend at the hips to wrap your arms vertically around the Atlas Stone, attempting to get your fingers underneath the stone. Many stones will have a small flat portion on the bottom, which will make the stone easier to hold.","Pulling the stone into your torso, drive through the back half of your feet to pull the stone from the ground.","As the stone passes the knees, lap it by sitting backward, pulling the stone on top of your thighs.","Sit low, getting the stone high onto your chest as you change your grip to reach over the stone. Stand, driving through with your hips. Close distance to the loading platform, and lean back, extending the hips to get the stone as high as possible."],"category":"strongman","images":["Atlas_Stones/0.jpg","Atlas_Stones/1.jpg"],"id":"Atlas_Stones"}'),
('free-exercise-db', 'Axle_Deadlift', 'axle-deadlift', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Axle_Deadlift.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Axle Deadlift","force":"pull","level":"intermediate","mechanic":"compound","equipment":"other","primaryMuscles":["lower back"],"secondaryMuscles":["forearms","glutes","hamstrings","middle back","quadriceps","traps"],"instructions":["Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an over/under grip.","With your feet and your grip set, take a big breath and then lower your hips and flex the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward.","After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.","Lower the bar by bending at the hips and guiding it to the floor."],"category":"strongman","images":["Axle_Deadlift/0.jpg","Axle_Deadlift/1.jpg"],"id":"Axle_Deadlift"}'),
('free-exercise-db', 'Back_Flyes_-_With_Bands', 'band-back-flyes', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Back_Flyes_-_With_Bands.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Back Flyes - With Bands","force":"pull","level":"beginner","mechanic":"compound","equipment":"bands","primaryMuscles":["shoulders"],"secondaryMuscles":["middle back","triceps"],"instructions":["Run a band around a stationary post like that of a squat rack.","Grab the band by the handles and stand back so that the tension in the band rises.","Extend and lift the arms straight in front of you. Tip: Your arms should be straight and parallel to the floor while perpendicular to your torso. Your feet should be firmly planted on the floor spread at shoulder width. This will be your starting position.","As you exhale, move your arms to the sides and back. Keep your arms extended and parallel to the floor. Continue the movement until the arms are extended to your sides.","After a pause, go back to the original position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Back_Flyes_-_With_Bands/0.jpg","Back_Flyes_-_With_Bands/1.jpg"],"id":"Back_Flyes_-_With_Bands"}'),
('free-exercise-db', 'Backward_Drag', 'backward-drag', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Backward_Drag.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Backward Drag","force":"pull","level":"beginner","mechanic":"compound","equipment":"other","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","forearms","glutes","hamstrings","lower back"],"instructions":["Load a sled with the desired weight, attaching a rope or straps to the sled that you can hold onto.","Begin the exercise by moving backwards for a given distance. Leaning back, extend through the legs for short steps to move as quickly as possible."],"category":"strongman","images":["Backward_Drag/0.jpg","Backward_Drag/1.jpg"],"id":"Backward_Drag"}'),
('free-exercise-db', 'Backward_Medicine_Ball_Throw', 'medicine-ball-backward-throw', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Backward_Medicine_Ball_Throw.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Backward Medicine Ball Throw","force":"push","level":"beginner","mechanic":"compound","equipment":"medicine ball","primaryMuscles":["shoulders"],"secondaryMuscles":[],"instructions":["This exercise is best done with a partner. If you lack a partner, the ball can be thrown and retrieved or thrown against a wall.","Begin standing a few meters in front of your partner, both facing the same direction. Begin holding the ball between your legs.","Squat down and then forcefully reverse direction, coming to full extension and you toss the ball over your head to your partner.","Your partner can then roll the ball back to you. Repeat for the desired number of repetitions."],"category":"plyometrics","images":["Backward_Medicine_Ball_Throw/0.jpg","Backward_Medicine_Ball_Throw/1.jpg"],"id":"Backward_Medicine_Ball_Throw"}'),
('free-exercise-db', 'Balance_Board', 'balance-board', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Balance_Board.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Balance Board","force":null,"level":"beginner","mechanic":"compound","equipment":"other","primaryMuscles":["calves"],"secondaryMuscles":["hamstrings","quadriceps"],"instructions":["Place a balance board in front of you.","Stand up on it and try to balance yourself.","Hold the balance for as long as desired."],"category":"strength","images":["Balance_Board/0.jpg","Balance_Board/1.jpg"],"id":"Balance_Board"}'),
('free-exercise-db', 'Ball_Leg_Curl', 'exercise-ball-ball-leg-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Ball_Leg_Curl.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Ball Leg Curl","force":"pull","level":"beginner","mechanic":"isolation","equipment":"exercise ball","primaryMuscles":["hamstrings"],"secondaryMuscles":["calves","glutes"],"instructions":["Begin on the floor laying on your back with your feet on top of the ball.","Position the ball so that when your legs are extended your ankles are on top of the ball. This will be your starting position.","Raise your hips off of the ground, keeping your weight on the shoulder blades and your feet.","Flex the knees, pulling the ball as close to you as you can, contracting the hamstrings.","After a brief pause, return to the starting position."],"category":"strength","images":["Ball_Leg_Curl/0.jpg","Ball_Leg_Curl/1.jpg"],"id":"Ball_Leg_Curl"}'),
('free-exercise-db', 'Band_Assisted_Pull-Up', 'band-assisted-pull-up', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Band_Assisted_Pull-Up.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Band Assisted Pull-Up","force":null,"level":"beginner","mechanic":"compound","equipment":"other","primaryMuscles":["lats"],"secondaryMuscles":["abdominals","forearms","middle back"],"instructions":["Choke the band around the center of the pullup bar. You can use different bands to provide varying levels of assistance.","Pull the end of the band down, and place one bent knee into the loop, ensuring it won''t slip out. Take a medium to wide grip on the bar. This will be your starting position.","Pull yourself upward by contracting the lats as you flex the elbow. The elbow should be driven to your side. Pull to the front, attempting to get your chin over the bar. Avoid swinging or jerking movements.","After a brief pause, return to the starting position."],"category":"strength","images":["Band_Assisted_Pull-Up/0.jpg","Band_Assisted_Pull-Up/1.jpg"],"id":"Band_Assisted_Pull-Up"}'),
('free-exercise-db', 'Band_Good_Morning', 'band-good-morning', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Band_Good_Morning.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Band Good Morning","force":"pull","level":"beginner","mechanic":"compound","equipment":"bands","primaryMuscles":["hamstrings"],"secondaryMuscles":["glutes","lower back"],"instructions":["Using a 41 inch band, stand on one end, spreading your feet a small amount. Bend at the hips to loop the end of the band behind your neck. This will be your starting position.","Keeping your legs straight, extend through the hips to come to a near vertical position.","Ensure that you do not round your back as you go down back to the starting position."],"category":"powerlifting","images":["Band_Good_Morning/0.jpg","Band_Good_Morning/1.jpg"],"id":"Band_Good_Morning"}'),
('free-exercise-db', 'Band_Good_Morning_Pull_Through', 'band-good-morning-pull-through', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Band_Good_Morning_Pull_Through.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Band Good Morning (Pull Through)","force":"pull","level":"beginner","mechanic":"compound","equipment":"bands","primaryMuscles":["hamstrings"],"secondaryMuscles":["glutes","lower back"],"instructions":["Loop the band around a post. Standing a little ways away, loop the opposite end around the neck. Your hands can help hold the band in position.","Begin by bending at the hips, getting your butt back as far as possible. Keep your back flat and bend forward to about 90 degrees. Your knees should be only slightly bent.","Return to the starting position be driving through with the hips to come back to a standing position."],"category":"powerlifting","images":["Band_Good_Morning_Pull_Through/0.jpg","Band_Good_Morning_Pull_Through/1.jpg"],"id":"Band_Good_Morning_Pull_Through"}'),
('free-exercise-db', 'Band_Hip_Adductions', 'band-hip-adductions', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Band_Hip_Adductions.json', 'Unlicense', NULL, 'new', 88.9, '{"name":"Band Hip Adductions","force":"pull","level":"beginner","mechanic":"isolation","equipment":"bands","primaryMuscles":["adductors"],"secondaryMuscles":[],"instructions":["Anchor a band around a solid post or other object.","Stand with your left side to the post, and put your right foot through the band, getting it around the ankle.","Stand up straight and hold onto the post if needed. This will be your starting position.","Keeping the knee straight, raise your right legs out to the side as far as you can.","Return to the starting position and repeat for the desired rep count.","Switch sides."],"category":"strength","images":["Band_Hip_Adductions/0.jpg","Band_Hip_Adductions/1.jpg"],"id":"Band_Hip_Adductions"}'),
('free-exercise-db', 'Band_Pull_Apart', 'band-pull-apart', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Band_Pull_Apart.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Band Pull Apart","force":"pull","level":"beginner","mechanic":"isolation","equipment":"bands","primaryMuscles":["shoulders"],"secondaryMuscles":["middle back","traps"],"instructions":["Begin with your arms extended straight out in front of you, holding the band with both hands.","Initiate the movement by performing a reverse fly motion, moving your hands out laterally to your sides.","Keep your elbows extended as you perform the movement, bringing the band to your chest. Ensure that you keep your shoulders back during the exercise.","Pause as you complete the movement, returning to the starting position under control."],"category":"strength","images":["Band_Pull_Apart/0.jpg","Band_Pull_Apart/1.jpg"],"id":"Band_Pull_Apart"}'),
('free-exercise-db', 'Band_Skull_Crusher', 'band-skull-crusher', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Band_Skull_Crusher.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Band Skull Crusher","force":"push","level":"beginner","mechanic":"isolation","equipment":"bands","primaryMuscles":["triceps"],"secondaryMuscles":[],"instructions":["Secure a band to the base of a rack or the bench. Lay on the bench so that the band is lined up with your head.","Take hold of the band, raising your elbows so that the upper arm is perpendicular to the floor. With the elbow flexed, the band should be above your head. This will be your starting position.","Extend through the elbow to straighten your arm, keeping your upper arm in place. Pause at the top of the motion, and return to the starting position."],"category":"strength","images":["Band_Skull_Crusher/0.jpg","Band_Skull_Crusher/1.jpg"],"id":"Band_Skull_Crusher"}'),
('free-exercise-db', 'Barbell_Ab_Rollout', 'barbell-ab-rollout', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Barbell_Ab_Rollout.json', 'Unlicense', NULL, 'exact', 100.0, '{"name":"Barbell Ab Rollout","force":"pull","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["abdominals"],"secondaryMuscles":["lower back","shoulders"],"instructions":["For this exercise you will need to get into a pushup position, but instead of having your hands of the floor, you will be grabbing on to an Olympic barbell (loaded with 5-10 lbs on each side) instead. This will be your starting position.","While keeping a slight arch on your back, lift your hips and roll the barbell towards your feet as you exhale. Tip: As you perform the movement, your glutes should be coming up, you should be keeping the abs tight and should maintain your back posture at all times. Also your arms should be staying perpendicular to the floor throughout the movement. If you don''t, you will work out your shoulders and back more than the abs.","After a second contraction at the top, start to roll the barbell back forward to the starting position slowly as you inhale.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Barbell_Ab_Rollout/0.jpg","Barbell_Ab_Rollout/1.jpg"],"id":"Barbell_Ab_Rollout"}'),
('free-exercise-db', 'Barbell_Ab_Rollout_-_On_Knees', 'barbell-ab-rollout-knees', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Barbell_Ab_Rollout_-_On_Knees.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Barbell Ab Rollout - On Knees","force":"pull","level":"expert","mechanic":"compound","equipment":"barbell","primaryMuscles":["abdominals"],"secondaryMuscles":["lower back","shoulders"],"instructions":["Hold an Olympic barbell loaded with 5-10lbs on each side and kneel on the floor.","Now place the barbell on the floor in front of you so that you are on all your hands and knees (as in a kneeling push up position). This will be your starting position.","Slowly roll the barbell straight forward, stretching your body into a straight position. Tip: Go down as far as you can without touching the floor with your body. Breathe in during this portion of the movement.","After a second pause at the stretched position, start pulling yourself back to the starting position as you breathe out. Tip: Go slowly and keep your abs tight at all times."],"category":"strength","images":["Barbell_Ab_Rollout_-_On_Knees/0.jpg","Barbell_Ab_Rollout_-_On_Knees/1.jpg"],"id":"Barbell_Ab_Rollout_-_On_Knees"}'),
('free-exercise-db', 'Barbell_Bench_Press_-_Medium_Grip', 'barbell-bench-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Barbell_Bench_Press_-_Medium_Grip.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Barbell Bench Press - Medium Grip","force":"push","level":"beginner","mechanic":"compound","equipment":"barbell","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["Lie back on a flat bench. Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.","From the starting position, breathe in and begin coming down slowly until the bar touches your middle chest.","After a brief pause, push the bar back to the starting position as you breathe out. Focus on pushing the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position at the top of the motion, hold for a second and then start coming down slowly again. Tip: Ideally, lowering the weight should take about twice as long as raising it.","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the bar back in the rack."],"category":"strength","images":["Barbell_Bench_Press_-_Medium_Grip/0.jpg","Barbell_Bench_Press_-_Medium_Grip/1.jpg"],"id":"Barbell_Bench_Press_-_Medium_Grip"}'),
('free-exercise-db', 'Barbell_Curl', 'barbell-biceps-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Barbell_Curl.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Barbell Curl","force":"pull","level":"beginner","mechanic":"isolation","equipment":"barbell","primaryMuscles":["biceps"],"secondaryMuscles":["forearms"],"instructions":["Stand up with your torso upright while holding a barbell at a shoulder-width grip. The palm of your hands should be facing forward and the elbows should be close to the torso. This will be your starting position.","While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move.","Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.","Slowly begin to bring the bar back to starting position as your breathe in.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Barbell_Curl/0.jpg","Barbell_Curl/1.jpg"],"id":"Barbell_Curl"}'),
('free-exercise-db', 'Barbell_Curls_Lying_Against_An_Incline', 'barbell-curl-lying-against-incline', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Barbell_Curls_Lying_Against_An_Incline.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Barbell Curls Lying Against An Incline","force":"pull","level":"beginner","mechanic":"isolation","equipment":"barbell","primaryMuscles":["biceps"],"secondaryMuscles":[],"instructions":["Lie against an incline bench, with your arms holding a barbell and hanging down in a horizontal line. This will be your starting position.","While keeping the upper arms stationary, curl the weight up as high as you can while squeezing the biceps. Breathe out as you perform this portion of the movement. Tip: Only the forearms should move. Do not swing the arms.","After a second contraction, slowly go back to the starting position as you inhale. Tip: Make sure that you go all of the way down.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Barbell_Curls_Lying_Against_An_Incline/0.jpg","Barbell_Curls_Lying_Against_An_Incline/1.jpg"],"id":"Barbell_Curls_Lying_Against_An_Incline"}'),
('free-exercise-db', 'Barbell_Deadlift', 'barbell-deadlift', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Barbell_Deadlift.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Barbell Deadlift","force":"pull","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["lower back"],"secondaryMuscles":["calves","forearms","glutes","hamstrings","lats","middle back","quadriceps","traps"],"instructions":["Stand in front of a loaded barbell.","While keeping the back as straight as possible, bend your knees, bend forward and grasp the bar using a medium (shoulder width) overhand grip. This will be the starting position of the exercise. Tip: If it is difficult to hold on to the bar with this grip, alternate your grip or use wrist straps.","While holding the bar, start the lift by pushing with your legs while simultaneously getting your torso to the upright position as you breathe out. In the upright position, stick your chest out and contract the back by bringing the shoulder blades back. Think of how the soldiers in the military look when they are in standing in attention.","Go back to the starting position by bending at the knees while simultaneously leaning the torso forward at the waist while keeping the back straight. When the weights on the bar touch the floor you are back at the starting position and ready to perform another repetition.","Perform the amount of repetitions prescribed in the program."],"category":"strength","images":["Barbell_Deadlift/0.jpg","Barbell_Deadlift/1.jpg"],"id":"Barbell_Deadlift"}'),
('free-exercise-db', 'Barbell_Full_Squat', 'barbell-full-squat', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Barbell_Full_Squat.json', 'Unlicense', NULL, 'exact', 100.0, '{"name":"Barbell Full Squat","force":"push","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings","lower back"],"instructions":["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just above shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.","Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.","Step away from the rack and position your legs using a shoulder-width medium stance with the toes slightly pointed out. Keep your head up at all times and maintain a straight back. This will be your starting position.","Begin to slowly lower the bar by bending the knees and sitting back with your hips as you maintain a straight posture with the head up. Continue down until your hamstrings are on your calves. Inhale as you perform this portion of the movement.","Begin to raise the bar as you exhale by pushing the floor with the heel or middle of your foot as you straighten the legs and extend the hips to go back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Barbell_Full_Squat/0.jpg","Barbell_Full_Squat/1.jpg"],"id":"Barbell_Full_Squat"}'),
('free-exercise-db', 'Barbell_Glute_Bridge', 'barbell-glute-bridge', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Barbell_Glute_Bridge.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Barbell Glute Bridge","force":"push","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["glutes"],"secondaryMuscles":["calves","hamstrings"],"instructions":["Begin seated on the ground with a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise. Roll the bar so that it is directly above your hips, and lay down flat on the floor.","Begin the movement by driving through with your heels, extending your hips vertically through the bar. Your weight should be supported by your upper back and the heels of your feet.","Extend as far as possible, then reverse the motion to return to the starting position."],"category":"powerlifting","images":["Barbell_Glute_Bridge/0.jpg","Barbell_Glute_Bridge/1.jpg"],"id":"Barbell_Glute_Bridge"}'),
('free-exercise-db', 'Barbell_Guillotine_Bench_Press', 'barbell-guillotine-bench-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Barbell_Guillotine_Bench_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Barbell Guillotine Bench Press","force":"push","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over your neck with your arms locked. This will be your starting position.","As you breathe in, bring the bar down slowly until it is about 1 inch from your neck.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the bar back in the rack."],"category":"strength","images":["Barbell_Guillotine_Bench_Press/0.jpg","Barbell_Guillotine_Bench_Press/1.jpg"],"id":"Barbell_Guillotine_Bench_Press"}'),
('free-exercise-db', 'Barbell_Hack_Squat', 'barbell-hack-squat', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Barbell_Hack_Squat.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Barbell Hack Squat","force":"push","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","forearms","hamstrings"],"instructions":["Stand up straight while holding a barbell behind you at arms length and your feet at shoulder width. Tip: A shoulder width grip is best with the palms of your hands facing back. You can use wrist wraps for this exercise for a better grip. This will be your starting position.","While keeping your head and eyes up and back straight, squat until your upper thighs are parallel to the floor. Breathe in as you slowly go down.","Pressing mainly with the heel of the foot and squeezing the thighs, go back up as you breathe out.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Barbell_Hack_Squat/0.jpg","Barbell_Hack_Squat/1.jpg"],"id":"Barbell_Hack_Squat"}'),
('free-exercise-db', 'Barbell_Hip_Thrust', 'barbell-hip-thrust', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Barbell_Hip_Thrust.json', 'Unlicense', NULL, 'exact', 100.0, '{"name":"Barbell Hip Thrust","force":"push","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["glutes"],"secondaryMuscles":["calves","hamstrings"],"instructions":["Begin seated on the ground with a bench directly behind you. Have a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise.","Roll the bar so that it is directly above your hips, and lean back against the bench so that your shoulder blades are near the top of it.","Begin the movement by driving through your feet, extending your hips vertically through the bar. Your weight should be supported by your shoulder blades and your feet. Extend as far as possible, then reverse the motion to return to the starting position."],"category":"powerlifting","images":["Barbell_Hip_Thrust/0.jpg","Barbell_Hip_Thrust/1.jpg"],"id":"Barbell_Hip_Thrust"}'),
('free-exercise-db', 'Barbell_Incline_Bench_Press_-_Medium_Grip', 'barbell-incline-bench-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Barbell_Incline_Bench_Press_-_Medium_Grip.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Barbell Incline Bench Press - Medium Grip","force":"push","level":"beginner","mechanic":"compound","equipment":"barbell","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["Lie back on an incline bench. Using a medium-width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.","As you breathe in, come down slowly until you feel the bar on you upper chest.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly again. Tip: it should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the bar back in the rack."],"category":"strength","images":["Barbell_Incline_Bench_Press_-_Medium_Grip/0.jpg","Barbell_Incline_Bench_Press_-_Medium_Grip/1.jpg"],"id":"Barbell_Incline_Bench_Press_-_Medium_Grip"}'),
('free-exercise-db', 'Barbell_Incline_Shoulder_Raise', 'barbell-incline-shoulder-raise', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Barbell_Incline_Shoulder_Raise.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Barbell Incline Shoulder Raise","force":"push","level":"beginner","mechanic":"compound","equipment":"barbell","primaryMuscles":["shoulders"],"secondaryMuscles":["chest"],"instructions":["Lie back on an Incline Bench. Using a medium width grip (a grip that is slightly wider than shoulder width), lift the bar from the rack and hold it straight over you with your arms straight. This will be your starting position.","While keeping the arms straight, lift the bar by protracting your shoulder blades, raising the shoulders from the bench as you breathe out.","Bring back the bar to the starting position as you breathe in.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Barbell_Incline_Shoulder_Raise/0.jpg","Barbell_Incline_Shoulder_Raise/1.jpg"],"id":"Barbell_Incline_Shoulder_Raise"}'),
('free-exercise-db', 'Barbell_Lunge', 'barbell-lunge', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Barbell_Lunge.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Barbell Lunge","force":"push","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings"],"instructions":["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.","Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.","Step away from the rack and step forward with your right leg and squat down through your hips, while keeping the torso upright and maintaining balance. Inhale as you go down. Note: Do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. li>","Using mainly the heel of your foot, push up and go back to the starting position as you exhale.","Repeat the movement for the recommended amount of repetitions and then perform with the left leg."],"category":"strength","images":["Barbell_Lunge/0.jpg","Barbell_Lunge/1.jpg"],"id":"Barbell_Lunge"}'),
('free-exercise-db', 'Barbell_Rear_Delt_Row', 'barbell-rear-delt-row', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Barbell_Rear_Delt_Row.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Barbell Rear Delt Row","force":"pull","level":"beginner","mechanic":"compound","equipment":"barbell","primaryMuscles":["shoulders"],"secondaryMuscles":["biceps","lats","middle back"],"instructions":["Stand up straight while holding a barbell using a wide (higher than shoulder width) and overhand (palms facing your body) grip.","Bend knees slightly and bend over as you keep the natural arch of your back. Let the arms hang in front of you as they hold the bar. Once your torso is parallel to the floor, flare the elbows out and away from your body. Tip: Your torso and your arms should resemble the letter \"T\". Now you are ready to begin the exercise.","While keeping the upper arms perpendicular to the torso, pull the barbell up towards your upper chest as you squeeze the rear delts and you breathe out. Tip: When performed correctly, this exercise should resemble a bench press in reverse. Also, refrain from using your biceps to do the work. Focus on targeting the rear delts; the arms should only act as hooks.","Slowly go back to the initial position as you breathe in.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Barbell_Rear_Delt_Row/0.jpg","Barbell_Rear_Delt_Row/1.jpg"],"id":"Barbell_Rear_Delt_Row"}'),
('free-exercise-db', 'Barbell_Rollout_from_Bench', 'barbell-rollout-from-bench', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Barbell_Rollout_from_Bench.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Barbell Rollout from Bench","force":"pull","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["abdominals"],"secondaryMuscles":["glutes","hamstrings","lats","shoulders"],"instructions":["Place a loaded barbell on the ground, near the end of a bench. Kneel with both legs on the bench, and take a medium to narrow grip on the barbell. This will be your starting position.","To begin, extend through the hips to slowly roll the bar forward. As you roll out, flex the shoulder to roll the bar above your head. Ensure that your arms remain extended throughout the movement.","When the bar has been moved as far forward as possible, return to the starting position."],"category":"strength","images":["Barbell_Rollout_from_Bench/0.jpg","Barbell_Rollout_from_Bench/1.jpg"],"id":"Barbell_Rollout_from_Bench"}'),
('free-exercise-db', 'Barbell_Seated_Calf_Raise', 'barbell-seated-calf-raise', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Barbell_Seated_Calf_Raise.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Barbell Seated Calf Raise","force":"push","level":"beginner","mechanic":"isolation","equipment":"barbell","primaryMuscles":["calves"],"secondaryMuscles":[],"instructions":["Place a block about 12 inches in front of a flat bench.","Sit on the bench and place the ball of your feet on the block.","Have someone place a barbell over your upper thighs about 3 inches above your knees and hold it there. This will be your starting position.","Raise up on your toes as high as possible as you squeeze the calves and as you breathe out.","After a second contraction, slowly go back to the starting position. Tip: To get maximum benefit stretch your calves as far as you can.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Barbell_Seated_Calf_Raise/0.jpg","Barbell_Seated_Calf_Raise/1.jpg"],"id":"Barbell_Seated_Calf_Raise"}'),
('free-exercise-db', 'Barbell_Shoulder_Press', 'barbell-shoulder-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Barbell_Shoulder_Press.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Barbell Shoulder Press","force":"push","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["shoulders"],"secondaryMuscles":["chest","triceps"],"instructions":["Sit on a bench with back support in a squat rack. Position a barbell at a height that is just above your head. Grab the barbell with a pronated grip (palms facing forward).","Once you pick up the barbell with the correct grip width, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.","Lower the bar down to the shoulders slowly as you inhale.","Lift the bar back up to the starting position as you exhale.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Barbell_Shoulder_Press/0.jpg","Barbell_Shoulder_Press/1.jpg"],"id":"Barbell_Shoulder_Press"}'),
('free-exercise-db', 'Barbell_Shrug', 'barbell-shrug', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Barbell_Shrug.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Barbell Shrug","force":"pull","level":"beginner","mechanic":"isolation","equipment":"barbell","primaryMuscles":["traps"],"secondaryMuscles":[],"instructions":["Stand up straight with your feet at shoulder width as you hold a barbell with both hands in front of you using a pronated grip (palms facing the thighs). Tip: Your hands should be a little wider than shoulder width apart. You can use wrist wraps for this exercise for a better grip. This will be your starting position.","Raise your shoulders up as far as you can go as you breathe out and hold the contraction for a second. Tip: Refrain from trying to lift the barbell by using your biceps.","Slowly return to the starting position as you breathe in.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Barbell_Shrug/0.jpg","Barbell_Shrug/1.jpg"],"id":"Barbell_Shrug"}'),
('free-exercise-db', 'Barbell_Shrug_Behind_The_Back', 'barbell-shrug-behind-back', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Barbell_Shrug_Behind_The_Back.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Barbell Shrug Behind The Back","force":"pull","level":"beginner","mechanic":"isolation","equipment":"barbell","primaryMuscles":["traps"],"secondaryMuscles":["forearms","middle back"],"instructions":["Stand up straight with your feet at shoulder width as you hold a barbell with both hands behind your back using a pronated grip (palms facing back). Tip: Your hands should be a little wider than shoulder width apart. You can use wrist wraps for this exercise for better grip. This will be your starting position.","Raise your shoulders up as far as you can go as you breathe out and hold the contraction for a second. Tip: Refrain from trying to lift the barbell by using your biceps. The arms should remain stretched out at all times.","Slowly return to the starting position as you breathe in.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Barbell_Shrug_Behind_The_Back/0.jpg","Barbell_Shrug_Behind_The_Back/1.jpg"],"id":"Barbell_Shrug_Behind_The_Back"}'),
('free-exercise-db', 'Barbell_Side_Bend', 'barbell-side-bend', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Barbell_Side_Bend.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Barbell Side Bend","force":"pull","level":"beginner","mechanic":"isolation","equipment":"barbell","primaryMuscles":["abdominals"],"secondaryMuscles":["lower back"],"instructions":["Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck). Your feet should be shoulder width apart. This will be your starting position.","While keeping your back straight and your head up, bend only at the waist to the right as far as possible. Breathe in as you bend to the side. Then hold for a second and come back up to the starting position as you exhale. Tip: Keep the rest of the body stationary.","Now repeat the movement but bending to the left instead. Hold for a second and come back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Barbell_Side_Bend/0.jpg","Barbell_Side_Bend/1.jpg"],"id":"Barbell_Side_Bend"}'),
('free-exercise-db', 'Barbell_Side_Split_Squat', 'barbell-side-split-squat', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Barbell_Side_Split_Squat.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Barbell Side Split Squat","force":"push","level":"beginner","mechanic":"compound","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","hamstrings","lower back"],"instructions":["Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck). Your feet should be placed wide apart with the foot of the lead leg angled out to the side. This will be your starting position.","Lower your body towards the side of your angled foot by bending the knee and hip of your lead leg and while keeping the opposite leg only slightly bent. Breathe in as you lower your body.","Return to the starting position by extending the hip and knee of the lead leg. Breathe out as you perform this movement.","After performing the recommended amount of reps, repeat the movement with the opposite leg."],"category":"strength","images":["Barbell_Side_Split_Squat/0.jpg","Barbell_Side_Split_Squat/1.jpg"],"id":"Barbell_Side_Split_Squat"}'),
('free-exercise-db', 'Barbell_Squat', 'barbell-squat', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Barbell_Squat.json', 'Unlicense', NULL, 'exact', 100.0, '{"name":"Barbell Squat","force":"push","level":"beginner","mechanic":"compound","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings","lower back"],"instructions":["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack to just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.","Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.","Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section).","Begin to slowly lower the bar by bending the knees and hips as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees. Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Barbell_Squat/0.jpg","Barbell_Squat/1.jpg"],"id":"Barbell_Squat"}'),
('free-exercise-db', 'Barbell_Squat_To_A_Bench', 'barbell-squat-to-bench', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Barbell_Squat_To_A_Bench.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Barbell Squat To A Bench","force":"push","level":"expert","mechanic":"compound","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings","lower back"],"instructions":["This exercise is best performed inside a squat rack for safety purposes. To begin, first place a flat bench or a box behind you. The flat bench is used to teach you to set your hips back and to hit depth.","","Then, set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.","Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.","Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section).","Begin to slowly lower the bar by bending the knees and sitting your hips back as you maintain a straight posture with the head up. Continue down until you slightly touch the bench behind you. Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs and extend the hips to go back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Barbell_Squat_To_A_Bench/0.jpg","Barbell_Squat_To_A_Bench/1.jpg"],"id":"Barbell_Squat_To_A_Bench"}'),
('free-exercise-db', 'Barbell_Step_Ups', 'barbell-step-up', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Barbell_Step_Ups.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Barbell Step Ups","force":"push","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings","quadriceps"],"instructions":["Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck) and stand upright behind an elevated platform (such as the one used for spotting behind a flat bench). This is your starting position.","Place the right foot on the elevated platform. Step on the platform by extending the hip and the knee of your right leg. Use the heel mainly to lift the rest of your body up and place the foot of the left leg on the platform as well. Breathe out as you execute the force required to come up.","Step down with the left leg by flexing the hip and knee of the right leg as you inhale. Return to the original standing position by placing the right foot of to next to the left foot on the initial position.","Repeat with the right leg for the recommended amount of repetitions and then perform with the left leg."],"category":"strength","images":["Barbell_Step_Ups/0.jpg","Barbell_Step_Ups/1.jpg"],"id":"Barbell_Step_Ups"}'),
('free-exercise-db', 'Barbell_Walking_Lunge', 'barbell-walking-lunge', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Barbell_Walking_Lunge.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Barbell Walking Lunge","force":"push","level":"beginner","mechanic":"compound","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings"],"instructions":["Begin standing with your feet shoulder width apart and a barbell across your upper back.","Step forward with one leg, flexing the knees to drop your hips. Descend until your rear knee nearly touches the ground. Your posture should remain upright, and your front knee should stay above the front foot.","Drive through the heel of your lead foot and extend both knees to raise yourself back up.","Step forward with your rear foot, repeating the lunge on the opposite leg."],"category":"strength","images":["Barbell_Walking_Lunge/0.jpg","Barbell_Walking_Lunge/1.jpg"],"id":"Barbell_Walking_Lunge"}'),
('free-exercise-db', 'Battling_Ropes', 'battling-ropes', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Battling_Ropes.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Battling Ropes","force":"push","level":"beginner","mechanic":"compound","equipment":"other","primaryMuscles":["shoulders"],"secondaryMuscles":["chest","forearms"],"instructions":["For this exercise you will need a heavy rope anchored at its center 15-20 feet away. Standing in front of the rope, take an end in each hand with your arms extended at your side. This will be your starting position.","Initiate the movement by rapidly raising one arm to shoulder level as quickly as you can.","As you let that arm drop to the starting position, raise the opposite side.","Continue alternating your left and right arms, whipping the ropes up and down as fast as you can."],"category":"strength","images":["Battling_Ropes/0.jpg","Battling_Ropes/1.jpg"],"id":"Battling_Ropes"}'),
('free-exercise-db', 'Bear_Crawl_Sled_Drags', 'bear-crawl-sled-drags', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Bear_Crawl_Sled_Drags.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Bear Crawl Sled Drags","force":"push","level":"beginner","mechanic":"compound","equipment":"other","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings"],"instructions":["Wearing either a harness or a loose weight belt, attach the chain to the back so that you will be facing away from the sled. Bend down so that your hands are on the ground. Your back should be flat and knees bent. This is your starting position.","Begin by driving with legs, alternating left and right. Use your hands to maintain balance and to help pull. Try to keep your back flat as you move over a given distance."],"category":"strongman","images":["Bear_Crawl_Sled_Drags/0.jpg","Bear_Crawl_Sled_Drags/1.jpg"],"id":"Bear_Crawl_Sled_Drags"}'),
('free-exercise-db', 'Behind_Head_Chest_Stretch', 'behind-head-chest-stretch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Behind_Head_Chest_Stretch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Behind Head Chest Stretch","force":"static","level":"expert","mechanic":"isolation","equipment":"other","primaryMuscles":["chest"],"secondaryMuscles":["shoulders"],"instructions":["Sit upright on the floor with your partner behind you.","Place your hands behind your hand, and push your elbows back as far as you can. Your partner should hold your elbows. This will be your starting position.","Gently attempt to pull your elbows forward with your hands still behind your head for 10 or more seconds. Your partner should prevent your elbows from moving.","Now, relax your muscles and have your partner gently pull the elbows back as far as it comfortable for you. Be sure to let your partner know when the stretch is adequate to prevent overstretching or injury."],"category":"stretching","images":["Behind_Head_Chest_Stretch/0.jpg","Behind_Head_Chest_Stretch/1.jpg"],"id":"Behind_Head_Chest_Stretch"}'),
('free-exercise-db', 'Bench_Dips', 'dip-bench', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Bench_Dips.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Bench Dips","force":"push","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["triceps"],"secondaryMuscles":["chest","shoulders"],"instructions":["For this exercise you will need to place a bench behind your back. With the bench perpendicular to your body, and while looking away from it, hold on to the bench on its edge with the hands fully extended, separated at shoulder width. The legs will be extended forward, bent at the waist and perpendicular to your torso. This will be your starting position.","Slowly lower your body as you inhale by bending at the elbows until you lower yourself far enough to where there is an angle slightly smaller than 90 degrees between the upper arm and the forearm. Tip: Keep the elbows as close as possible throughout the movement. Forearms should always be pointing down.","Using your triceps to bring your torso up again, lift yourself back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Bench_Dips/0.jpg","Bench_Dips/1.jpg"],"id":"Bench_Dips"}'),
('free-exercise-db', 'Bench_Jump', 'bench-jump', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Bench_Jump.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Bench Jump","force":"push","level":"intermediate","mechanic":"compound","equipment":"body only","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings"],"instructions":["Begin with a box or bench 1-2 feet in front of you. Stand with your feet shoulder width apart. This will be your starting position.","Perform a short squat in preparation for the jump; swing your arms behind you.","Rebound out of this position, extending through the hips, knees, and ankles to jump as high as possible. Swing your arms forward and up.","Jump over the bench, landing with the knees bent, absorbing the impact through the legs.","Turn around and face the opposite direction, then jump back over the bench."],"category":"plyometrics","images":["Bench_Jump/0.jpg","Bench_Jump/1.jpg"],"id":"Bench_Jump"}'),
('free-exercise-db', 'Bench_Press_-_Powerlifting', 'barbell-bench-press-powerlifting', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Bench_Press_-_Powerlifting.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Bench Press - Powerlifting","force":"push","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["triceps"],"secondaryMuscles":["chest","forearms","lats","shoulders"],"instructions":["Begin by lying on the bench, getting your head beyond the bar if possible. Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement.","However wide your grip, it should cover the ring on the bar. Pull the bar out of the rack without protracting your shoulders. Focus on squeezing the bar and trying to pull it apart.","Lower the bar to your lower chest or upper stomach. The bar, wrist, and elbow should stay in line at all times.","Pause when the barbell touches your torso, and then drive the bar up with as much force as possible. The elbows should be tucked in until lockout."],"category":"powerlifting","images":["Bench_Press_-_Powerlifting/0.jpg","Bench_Press_-_Powerlifting/1.jpg"],"id":"Bench_Press_-_Powerlifting"}'),
('free-exercise-db', 'Bench_Press_-_With_Bands', 'band-bench-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Bench_Press_-_With_Bands.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Bench Press - With Bands","force":"push","level":"beginner","mechanic":"compound","equipment":"bands","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["Using a flat bench secure a band under the leg of the bench that is nearest to your head.","Once the band is secure, grab it by both handles and lie down on the bench.","Extend your arms so that you are holding the band handles in front of you at shoulder width.","Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.","Bring down the handles slowly until your elbow forms a 90 degree angle. Keep full control at all times.","As you breathe out, bring the handles up using your pectoral muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions of your training program."],"category":"strength","images":["Bench_Press_-_With_Bands/0.jpg","Bench_Press_-_With_Bands/1.jpg"],"id":"Bench_Press_-_With_Bands"}'),
('free-exercise-db', 'Bench_Press_with_Chains', 'barbell-bench-press-chains', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Bench_Press_with_Chains.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Bench Press with Chains","force":"push","level":"expert","mechanic":"compound","equipment":"barbell","primaryMuscles":["triceps"],"secondaryMuscles":["chest","lats","shoulders"],"instructions":["Adjust the leader chain, shortening it to the desired length.Place the chains on the sleeves of the bar.","Lying on the bench, get your head beyond the bar if possible. Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement. However wide your grip, it should cover the ring on the bar.","Pull the bar out of the rack without protracting your shoulders. Focus on squeezing the bar and trying to pull it apart. Lower the bar to your lower chest or upper stomach. The bar, wrist, and elbow should stay in line at all times.","Pause when the barbell touches your torso, and then drive the bar up with as much force as possible. The elbows should be tucked in until lockout."],"category":"powerlifting","images":["Bench_Press_with_Chains/0.jpg","Bench_Press_with_Chains/1.jpg"],"id":"Bench_Press_with_Chains"}'),
('free-exercise-db', 'Bench_Sprint', 'bench-sprint', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Bench_Sprint.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Bench Sprint","force":"push","level":"beginner","mechanic":"compound","equipment":"other","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings"],"instructions":["Stand on the ground with one foot resting on a bench or box with your heel close to the edge.","Push off with your foot on top of the bench, extending through the hip and knee.","Land with the opposite foot on top of the box, returning your other foot back to the start position.","Continue alternating from one foot to another to complete the set."],"category":"plyometrics","images":["Bench_Sprint/0.jpg","Bench_Sprint/1.jpg"],"id":"Bench_Sprint"}'),
('free-exercise-db', 'Bent-Arm_Barbell_Pullover', 'barbell-bent-arm-pullover', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Bent-Arm_Barbell_Pullover.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Bent-Arm Barbell Pullover","force":"pull","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["lats"],"secondaryMuscles":["chest","lats","shoulders","triceps"],"instructions":["Lie on a flat bench with a barbell using a shoulder grip width.","Hold the bar straight over your chest with a bend in your arms. This will be your starting position.","While keeping your arms in the bent arm position, lower the weight slowly in an arc behind your head while breathing in until you feel a stretch on the chest.","At that point, bring the barbell back to the starting position using the arc through which the weight was lowered and exhale as you perform this movement.","Hold the weight on the initial position for a second and repeat the motion for the prescribed number of repetitions."],"category":"strength","images":["Bent-Arm_Barbell_Pullover/0.jpg","Bent-Arm_Barbell_Pullover/1.jpg"],"id":"Bent-Arm_Barbell_Pullover"}'),
('free-exercise-db', 'Bent-Arm_Dumbbell_Pullover', 'dumbbell-bent-arm-pullover', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Bent-Arm_Dumbbell_Pullover.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Bent-Arm Dumbbell Pullover","force":"push","level":"intermediate","mechanic":"compound","equipment":"dumbbell","primaryMuscles":["chest"],"secondaryMuscles":["lats","shoulders","triceps"],"instructions":["Place a dumbbell standing up on a flat bench.","Ensuring that the dumbbell stays securely placed at the top of the bench, lie perpendicular to the bench (torso across it as in forming a cross) with only your shoulders lying on the surface. Hips should be below the bench and legs bent with feet firmly on the floor. The head will be off the bench as well.","Grasp the dumbbell with both hands and hold it straight over your chest with a bend in your arms. Both palms should be pressing against the underside one of the sides of the dumbbell. This will be your starting position. Caution: Always ensure that the dumbbell used for this exercise is secure. Using a dumbbell with loose plates can result in the dumbbell falling apart and falling on your face.","While keeping your arms locked in the bent arm position, lower the weight slowly in an arc behind your head while breathing in until you feel a stretch on the chest.","At that point, bring the dumbbell back to the starting position using the arc through which the weight was lowered and exhale as you perform this movement.","Hold the weight on the initial position for a second and repeat the motion for the prescribed number of repetitions."],"category":"strength","images":["Bent-Arm_Dumbbell_Pullover/0.jpg","Bent-Arm_Dumbbell_Pullover/1.jpg"],"id":"Bent-Arm_Dumbbell_Pullover"}'),
('free-exercise-db', 'Bent-Knee_Hip_Raise', 'bent-knee-hip-raise', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Bent-Knee_Hip_Raise.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Bent-Knee Hip Raise","force":"pull","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Lay flat on the floor with your arms next to your sides.","Now bend your knees at around a 75 degree angle and lift your feet off the floor by around 2 inches.","Using your lower abs, bring your knees in towards you as you maintain the 75 degree angle bend in your legs. Continue this movement until you raise your hips off of the floor by rolling your pelvis backward. Breathe out as you perform this portion of the movement. Tip: At the end of the movement your knees will be over your chest.","Squeeze your abs at the top of the movement for a second and then return to the starting position slowly as you breathe in. Tip: Maintain a controlled motion at all times.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Bent-Knee_Hip_Raise/0.jpg","Bent-Knee_Hip_Raise/1.jpg"],"id":"Bent-Knee_Hip_Raise"}'),
('free-exercise-db', 'Bent_Over_Barbell_Row', 'barbell-bent-over-rowing', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Bent_Over_Barbell_Row.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Bent Over Barbell Row","force":"pull","level":"beginner","mechanic":"compound","equipment":"barbell","primaryMuscles":["middle back"],"secondaryMuscles":["biceps","lats","shoulders"],"instructions":["Holding a barbell with a pronated grip (palms facing down), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.","Now, while keeping the torso stationary, breathe out and lift the barbell to you. Keep the elbows close to the body and only use the forearms to hold the weight. At the top contracted position, squeeze the back muscles and hold for a brief pause.","Then inhale and slowly lower the barbell back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Bent_Over_Barbell_Row/0.jpg","Bent_Over_Barbell_Row/1.jpg"],"id":"Bent_Over_Barbell_Row"}'),
('free-exercise-db', 'Bent_Over_Dumbbell_Rear_Delt_Raise_With_Head_On_Bench', 'dumbbell-bent-over-rear-delt-raise-head-bench', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Bent_Over_Dumbbell_Rear_Delt_Raise_With_Head_On_Bench.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Bent Over Dumbbell Rear Delt Raise With Head On Bench","force":"pull","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":[],"instructions":["Stand up straight while holding a dumbbell in each hand and with an incline bench in front of you.","While keeping your back straight and maintaining the natural arch of your back, lean forward until your forehead touches the bench in front of you. Let the arms hang in front of you perpendicular to the ground. The palms of your hands should be facing each other and your torso should be parallel to the floor. This will be your starting position.","Keeping your torso forward and stationary, and the arms straight with a slight bend at the elbows, lift the dumbbells straight to the side until both arms are parallel to the floor. Exhale as you lift the weights. Caution: avoid swinging the torso or bringing the arms back as opposed to the side.","After a one second contraction at the top, slowly lower the dumbbells back to the starting position.","Repeat the recommended amount of repetitions."],"category":"strength","images":["Bent_Over_Dumbbell_Rear_Delt_Raise_With_Head_On_Bench/0.jpg","Bent_Over_Dumbbell_Rear_Delt_Raise_With_Head_On_Bench/1.jpg"],"id":"Bent_Over_Dumbbell_Rear_Delt_Raise_With_Head_On_Bench"}'),
('free-exercise-db', 'Bent_Over_Low-Pulley_Side_Lateral', 'cable-bent-over-low-pulley-side-lateral', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Bent_Over_Low-Pulley_Side_Lateral.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Bent Over Low-Pulley Side Lateral","force":"pull","level":"beginner","mechanic":"isolation","equipment":"cable","primaryMuscles":["shoulders"],"secondaryMuscles":["lower back","middle back","traps"],"instructions":["Select a weight and hold the handle of the low pulley with your right hand.","Bend at the waist until your torso is nearly parallel to the floor. Your legs should be slightly bent with your left hand placed on your lower left thigh. Your right arm should be hanging from your shoulder in front of you and with a slight bend at the elbow. This will be your starting position.","Raise your right arm, elbow slightly bent, to the side until the arm is parallel to the floor and in line with your right ear. Breathe out as you perform this step.","Slowly lower the weight back to the starting position as you breathe in.","Repeat for the recommended amount of repetitions and repeat the movement with the other arm."],"category":"strength","images":["Bent_Over_Low-Pulley_Side_Lateral/0.jpg","Bent_Over_Low-Pulley_Side_Lateral/1.jpg"],"id":"Bent_Over_Low-Pulley_Side_Lateral"}'),
('free-exercise-db', 'Bent_Over_One-Arm_Long_Bar_Row', 'barbell-bent-over-one-arm-long-bar-row', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Bent_Over_One-Arm_Long_Bar_Row.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Bent Over One-Arm Long Bar Row","force":"pull","level":"beginner","mechanic":"compound","equipment":"barbell","primaryMuscles":["middle back"],"secondaryMuscles":["biceps","lats","lower back","traps"],"instructions":["Put weight on one of the ends of an Olympic barbell. Make sure that you either place the other end of the barbell in the corner of two walls; or put a heavy object on the ground so the barbell cannot slide backward.","Bend forward until your torso is as close to parallel with the floor as you can and keep your knees slightly bent.","Now grab the bar with one arm just behind the plates on the side where the weight was placed and put your other hand on your knee. This will be your starting position.","Pull the bar straight up with your elbow in (to maximize back stimulation) until the plates touch your lower chest. Squeeze the back muscles as you lift the weight up and hold for a second at the top of the movement. Breathe out as you lift the weight. Tip: Do not allow for any swinging of the torso. Only the arm should move.","Slowly lower the bar to the starting position getting a nice stretch on the lats. Tip: Do not let the plates touch the floor. To ensure the best range of motion, I recommend using small plates (25-lb ones) as opposed to larger plates (like 35-45lb ones).","Repeat for the recommended amount of repetitions and switch arms."],"category":"strength","images":["Bent_Over_One-Arm_Long_Bar_Row/0.jpg","Bent_Over_One-Arm_Long_Bar_Row/1.jpg"],"id":"Bent_Over_One-Arm_Long_Bar_Row"}'),
('free-exercise-db', 'Bent_Over_Two-Arm_Long_Bar_Row', 'barbell-bent-over-two-arm-long-bar-row', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Bent_Over_Two-Arm_Long_Bar_Row.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Bent Over Two-Arm Long Bar Row","force":"pull","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["middle back"],"secondaryMuscles":["biceps","lats"],"instructions":["Put weight on one of the ends of an Olympic barbell. Make sure that you either place the other end of the barbell in the corner of two walls; or put a heavy object on the ground so the barbell cannot slide backward.","Bend forward until your torso is as close to parallel with the floor as you can and keep your knees slightly bent.","Now grab the bar with both arms just behind the plates on the side where the weight was placed and put your other hand on your knee. This will be your starting position.","Pull the bar straight up with your elbows in (to maximize back stimulation) until the plates touch your lower chest. Squeeze the back muscles as you lift the weight up and hold for a second at the top of the movement. Breathe out as you lift the weight. Tip: Use a stirrup or double handle cable attachment by hooking it under the end of the bar.","Slowly lower the bar to the starting position getting a nice stretch on the lats. Tip: Do not let the plates touch the floor. To ensure the best range of motion, I recommend using small plates (25-lb ones) as opposed to larger plates (like 35-45lb ones).","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Bent_Over_Two-Arm_Long_Bar_Row/0.jpg","Bent_Over_Two-Arm_Long_Bar_Row/1.jpg"],"id":"Bent_Over_Two-Arm_Long_Bar_Row"}'),
('free-exercise-db', 'Bent_Over_Two-Dumbbell_Row', 'dumbbell-bent-over-two-row', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Bent_Over_Two-Dumbbell_Row.json', 'Unlicense', NULL, 'new', 85.7, '{"name":"Bent Over Two-Dumbbell Row","force":"pull","level":"beginner","mechanic":"compound","equipment":"dumbbell","primaryMuscles":["middle back"],"secondaryMuscles":["biceps","lats","shoulders"],"instructions":["With a dumbbell in each hand (palms facing your torso), bend your knees slightly and bring your torso forward by bending at the waist; as you bend make sure to keep your back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The weights should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.","While keeping the torso stationary, lift the dumbbells to your side (as you breathe out), keeping the elbows close to the body (do not exert any force with the forearm other than holding the weights). On the top contracted position, squeeze the back muscles and hold for a second.","Slowly lower the weight again to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Bent_Over_Two-Dumbbell_Row/0.jpg","Bent_Over_Two-Dumbbell_Row/1.jpg"],"id":"Bent_Over_Two-Dumbbell_Row"}'),
('free-exercise-db', 'Bent_Over_Two-Dumbbell_Row_With_Palms_In', 'dumbbell-bent-over-two-row-palms-in', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Bent_Over_Two-Dumbbell_Row_With_Palms_In.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Bent Over Two-Dumbbell Row With Palms In","force":"pull","level":"beginner","mechanic":"compound","equipment":"dumbbell","primaryMuscles":["middle back"],"secondaryMuscles":["biceps","lats"],"instructions":["With a dumbbell in each hand (palms facing each other), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The weights should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.","While keeping the torso stationary, lift the dumbbells to your side as you breathe out, squeezing your shoulder blades together. On the top contracted position, squeeze the back muscles and hold for a second.","Slowly lower the weight again to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Bent_Over_Two-Dumbbell_Row_With_Palms_In/0.jpg","Bent_Over_Two-Dumbbell_Row_With_Palms_In/1.jpg"],"id":"Bent_Over_Two-Dumbbell_Row_With_Palms_In"}'),
('free-exercise-db', 'Bent_Press', 'kettlebell-bent-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Bent_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Bent Press","force":"pull","level":"expert","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["abdominals"],"secondaryMuscles":["glutes","hamstrings","lower back","quadriceps","shoulders","triceps"],"instructions":["Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so. This will be your starting position.","Begin my leaning to the side opposite the kettlebell, continuing until you are able to touch the ground with your free hand, keeping your eyes on the kettlebell. As you do so, press the weight vertically be extending through the elbow, keeping your arm perpendicular to the ground.","Return to an upright position, with the kettlebell above your head. Return the kettlebell to the shoulder and repeat for the desired number of repetitions."],"category":"strength","images":["Bent_Press/0.jpg","Bent_Press/1.jpg"],"id":"Bent_Press"}'),
('free-exercise-db', 'Bicycling', 'bicycling', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Bicycling.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Bicycling","force":null,"level":"beginner","mechanic":null,"equipment":"other","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings"],"instructions":["To begin, seat yourself on the bike and adjust the seat to your height."],"category":"cardio","images":["Bicycling/0.jpg","Bicycling/1.jpg"],"id":"Bicycling"}'),
('free-exercise-db', 'Bicycling_Stationary', 'machine-bicycling-stationary', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Bicycling_Stationary.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Bicycling, Stationary","force":null,"level":"beginner","mechanic":null,"equipment":"machine","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings"],"instructions":["To begin, seat yourself on the bike and adjust the seat to your height.","Select the desired option from the menu. You may have to start pedaling to turn it on. You can use the manual setting, or you can select a program to use. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. The level of resistance can be changed throughout the workout. The handles can be used to monitor your heart rate to help you stay at an appropriate intensity."],"category":"cardio","images":["Bicycling_Stationary/0.jpg","Bicycling_Stationary/1.jpg"],"id":"Bicycling_Stationary"}'),
('free-exercise-db', 'Board_Press', 'barbell-board-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Board_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Board Press","force":"push","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["triceps"],"secondaryMuscles":["chest","forearms","lats","shoulders"],"instructions":["Begin by lying on the bench, getting your head beyond the bar if possible. One to five boards, made out of 2x6''s, can be screwed together and held in place by a training partner, bands, or just tucked under your shirt.","Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement.","You can take a standard bench grip, or shoulder width to focus on the triceps. Pull the bar out of the rack without protracting your shoulders. The bar, wrist, and elbow should stay in line at all times. Focus on squeezing the bar and trying to pull it apart.","Lower the bar to the boards, and then drive the bar up with as much force as possible. The elbows should be tucked in until lockout."],"category":"powerlifting","images":["Board_Press/0.jpg","Board_Press/1.jpg"],"id":"Board_Press"}'),
('free-exercise-db', 'Body-Up', 'body-up', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Body-Up.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Body-Up","force":"push","level":"intermediate","mechanic":"isolation","equipment":"body only","primaryMuscles":["triceps"],"secondaryMuscles":["abdominals","forearms"],"instructions":["Assume a plank position on the ground. You should be supporting your bodyweight on your toes and forearms, keeping your torso straight. Your forearms should be shoulder-width apart. This will be your starting position.","Pressing your palms firmly into the ground, extend through the elbows to raise your body from the ground. Keep your torso rigid as you perform the movement.","Slowly lower your forearms back to the ground by allowing the elbows to flex.","Repeat."],"category":"strength","images":["Body-Up/0.jpg","Body-Up/1.jpg"],"id":"Body-Up"}'),
('free-exercise-db', 'Body_Tricep_Press', 'body-tricep-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Body_Tricep_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Body Tricep Press","force":"push","level":"beginner","mechanic":"isolation","equipment":"body only","primaryMuscles":["triceps"],"secondaryMuscles":[],"instructions":["Position a bar in a rack at chest height.","Standing, take a shoulder width grip on the bar and step a yard or two back, feet together and arms extended so that you are leaning on the bar. This will be your starting position.","Begin by flexing the elbow, lowering yourself towards the bar.","Pause, and then reverse the motion by extending the elbows.","Progress from bodyweight by adding chains over your shoulders."],"category":"strength","images":["Body_Tricep_Press/0.jpg","Body_Tricep_Press/1.jpg"],"id":"Body_Tricep_Press"}'),
('free-exercise-db', 'Bodyweight_Flyes', 'ez-bar-bodyweight-flyes', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Bodyweight_Flyes.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Bodyweight Flyes","force":"push","level":"intermediate","mechanic":"isolation","equipment":"e-z curl bar","primaryMuscles":["chest"],"secondaryMuscles":["abdominals","shoulders","triceps"],"instructions":["Position two equally loaded EZ bars on the ground next to each other. Ensure they are able to roll.","Assume a push-up position over the bars, supporting your weight on your toes and hands with your arms extended and body straight.","Place your hands on the bars. This will be your starting position.","Using a slow and controlled motion, move your hands away from the midline of your body, rolling the bars apart. Inhale during this portion of the motion.","After moving the bars as far apart as you can, return to the starting position by pulling them back together. Exhale as you perform this movement."],"category":"strength","images":["Bodyweight_Flyes/0.jpg","Bodyweight_Flyes/1.jpg"],"id":"Bodyweight_Flyes"}'),
('free-exercise-db', 'Bodyweight_Mid_Row', 'bodyweight-mid-row', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Bodyweight_Mid_Row.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Bodyweight Mid Row","force":"pull","level":"intermediate","mechanic":"compound","equipment":"other","primaryMuscles":["middle back"],"secondaryMuscles":["biceps","lats"],"instructions":["Begin by taking a medium to wide grip on a pull-up apparatus with your palms facing away from you. From a hanging position, tuck your knees to your chest, leaning back and getting your legs over your side of the pull-up apparatus. This will be your starting position.","Beginning with your arms straight, flex the elbows and retract the shoulder blades to raise your body up until your legs contact the pull-up apparatus.","After a brief pause, return to the starting position."],"category":"strength","images":["Bodyweight_Mid_Row/0.jpg","Bodyweight_Mid_Row/1.jpg"],"id":"Bodyweight_Mid_Row"}'),
('free-exercise-db', 'Bodyweight_Squat', 'squat-bodyweight', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Bodyweight_Squat.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Bodyweight Squat","force":"push","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["quadriceps"],"secondaryMuscles":["glutes","hamstrings"],"instructions":["Stand with your feet shoulder width apart. You can place your hands behind your head. This will be your starting position.","Begin the movement by flexing your knees and hips, sitting back with your hips.","Continue down to full depth if you are able,and quickly reverse the motion until you return to the starting position. As you squat, keep your head and chest up and push your knees out."],"category":"strength","images":["Bodyweight_Squat/0.jpg","Bodyweight_Squat/1.jpg"],"id":"Bodyweight_Squat"}'),
('free-exercise-db', 'Bodyweight_Walking_Lunge', 'bodyweight-walking-lunge', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Bodyweight_Walking_Lunge.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Bodyweight Walking Lunge","force":"push","level":"beginner","mechanic":"compound","equipment":null,"primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings"],"instructions":["Begin standing with your feet shoulder width apart and your hands on your hips.","Step forward with one leg, flexing the knees to drop your hips. Descend until your rear knee nearly touches the ground. Your posture should remain upright, and your front knee should stay above the front foot.","Drive through the heel of your lead foot and extend both knees to raise yourself back up.","Step forward with your rear foot, repeating the lunge on the opposite leg."],"category":"strength","images":["Bodyweight_Walking_Lunge/0.jpg","Bodyweight_Walking_Lunge/1.jpg"],"id":"Bodyweight_Walking_Lunge"}'),
('free-exercise-db', 'Bosu_Ball_Cable_Crunch_With_Side_Bends', 'bosu-cable-ball-crunch-side-bend', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Bosu_Ball_Cable_Crunch_With_Side_Bends.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Bosu Ball Cable Crunch With Side Bends","force":"pull","level":"beginner","mechanic":"isolation","equipment":"cable","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Connect a standard handle to each arm of a cable machine, and position them in the most downward position.","Grab a Bosu Ball and position it in front and center of the cable machine.","Lie down on the Bosu Ball with the small of your back arched around the ball. Your rear end should be close to the floor without touching it.","With both hands, reach back and grab the handle of each cable.","With your feet positioned in a wide stance, extend your arms straight out in front of you and in between your knees. Your hands should be at knee level.","Keep your arms straight and in-line with the upward angle of the cable. Elevate your torso in a crunching motion without dropping or bending your arms.","Maintain the rigid position with your arms. Slowly descend back to the starting position with your back arched around the Bosu Ball and your abdominals elongated.","Repeat the same series of movements to failure.","Once you reach failure, keep your abs tight and raise your torso into plank position so your back is elevated off the Bosu Ball.","Lower your arms down to your side; keep them straight. Start doing alternating side bends; reach for your heels! This finishing movement will focus on your obliques."],"category":"strength","images":["Bosu_Ball_Cable_Crunch_With_Side_Bends/0.jpg","Bosu_Ball_Cable_Crunch_With_Side_Bends/1.jpg"],"id":"Bosu_Ball_Cable_Crunch_With_Side_Bends"}'),
('free-exercise-db', 'Bottoms-Up_Clean_From_The_Hang_Position', 'kettlebell-bottoms-up-clean-from-hang-position', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Bottoms-Up_Clean_From_The_Hang_Position.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Bottoms-Up Clean From The Hang Position","force":"pull","level":"intermediate","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["forearms"],"secondaryMuscles":["biceps","shoulders"],"instructions":["Initiate the exercise by standing upright with a kettlebell in one hand.","Swing the kettlebell back forcefully and then reverse the motion forcefully. Crush the kettlebell handle as hard as possible and raise the kettlebell to your shoulder."],"category":"strength","images":["Bottoms-Up_Clean_From_The_Hang_Position/0.jpg","Bottoms-Up_Clean_From_The_Hang_Position/1.jpg"],"id":"Bottoms-Up_Clean_From_The_Hang_Position"}'),
('free-exercise-db', 'Bottoms_Up', 'bottoms-up', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Bottoms_Up.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Bottoms Up","force":"pull","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Begin by lying on your back on the ground. Your legs should be straight and your arms at your side. This will be your starting position.","To perform the movement, tuck the knees toward your chest by flexing the hips and knees. Following this, extend your legs directly above you so that they are perpendicular to the ground. Rotate and elevate your pelvis to raise your glutes from the floor.","After a brief pause, return to the starting position."],"category":"strength","images":["Bottoms_Up/0.jpg","Bottoms_Up/1.jpg"],"id":"Bottoms_Up"}'),
('free-exercise-db', 'Box_Jump_Multiple_Response', 'box-jump-multiple-response', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Box_Jump_Multiple_Response.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Box Jump (Multiple Response)","force":"push","level":"beginner","mechanic":"compound","equipment":"other","primaryMuscles":["hamstrings"],"secondaryMuscles":["abductors","adductors","calves","glutes","quadriceps"],"instructions":["Assume a relaxed stance facing the box or platform approximately an arm''s length away. Arms should be down at the sides and legs slightly bent.","Using the arms to aid in the initial burst, jump upward and forward, landing with feet simultaneously on top of the box or platform.","Immediately drop or jump back down to the original starting place; then repeat the sequence."],"category":"plyometrics","images":["Box_Jump_Multiple_Response/0.jpg","Box_Jump_Multiple_Response/1.jpg"],"id":"Box_Jump_Multiple_Response"}'),
('free-exercise-db', 'Box_Skip', 'box-skip', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Box_Skip.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Box Skip","force":"push","level":"beginner","mechanic":"compound","equipment":"other","primaryMuscles":["hamstrings"],"secondaryMuscles":["abductors","adductors","calves","glutes","quadriceps"],"instructions":["You will need several boxes lined up about 8 feet apart.","Begin facing the first box with one leg slightly behind the other.","Drive off the back leg, attempting to gain as much height with the hips as possible.","Immediately upon landing on the box, drive the other leg forward and upward to gain height and distance, leaping from the box. Land between the first two boxes with the same leg that landed on the first box.","Then, step to the next box and repeat."],"category":"plyometrics","images":["Box_Skip/0.jpg","Box_Skip/1.jpg"],"id":"Box_Skip"}'),
('free-exercise-db', 'Box_Squat', 'barbell-box-squat', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Box_Squat.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Box Squat","force":"push","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["adductors","calves","glutes","hamstrings","lower back"],"instructions":["The box squat allows you to squat to desired depth and develop explosive strength in the squat movement. Begin in a power rack with a box at the appropriate height behind you. Typically, you would aim for a box height that brings you to a parallel squat, but you can train higher or lower if desired.","Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wider for more emphasis on the back, glutes, adductors, and hamstrings, or closer together for more quad development. Keep your head facing forward.","With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. Ideally, your shins should be perpendicular to the ground. Pause when you reach the box, and relax the hip flexors. Never bounce off of a box.","Keeping the weight on your heels and pushing your feet and knees out, drive upward off of the box as you lead the movement with your head. Continue upward, maintaining tightness head to toe."],"category":"powerlifting","images":["Box_Squat/0.jpg","Box_Squat/1.jpg"],"id":"Box_Squat"}'),
('free-exercise-db', 'Box_Squat_with_Bands', 'band-box-squat', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Box_Squat_with_Bands.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Box Squat with Bands","force":"push","level":"expert","mechanic":"compound","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["abductors","adductors","calves","glutes","hamstrings","lower back"],"instructions":["Begin in a power rack with a box at the appropriate height behind you. Set up the bands on the sleeves, secured to either band pegs, the rack, or dumbbells so that there is appropriate tension. If dumbbells are used, secure them so that they don''t move. Also, ensure that the dumbbells you are using are heavy enough for the bands that you are using. Additional plates can be used to hold the dumbbells down. If more tension is needed, you can either widen the base on the floor or choke the bands. Typically, you would aim for a box height that brings you to a parallel squat, but you can train higher or lower if desired.","Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wider for more emphasis on the back, glutes, adductors, and hamstrings, or closer together for more quad development. Keep your head facing forward.","With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. Ideally, your shins should be perpendicular to the ground. Pause when you reach the box, and relax the hip flexors. Never bounce off of a box.","Keeping the weight on your heels and pushing your feet and knees out, drive upward off of the box as you lead the movement with your head. Continue upward, maintaining tightness head to toe. Use care to return the barbell to the rack."],"category":"powerlifting","images":["Box_Squat_with_Bands/0.jpg","Box_Squat_with_Bands/1.jpg"],"id":"Box_Squat_with_Bands"}'),
('free-exercise-db', 'Box_Squat_with_Chains', 'barbell-box-squat-chains', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Box_Squat_with_Chains.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Box Squat with Chains","force":"push","level":"expert","mechanic":"compound","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["abductors","adductors","calves","glutes","hamstrings","lower back"],"instructions":["Begin in a power rack with a box at the appropriate height behind you. Typically, you would aim for a box height that brings you to a parallel squat, but you can train higher or lower if desired.","To set up the chains, begin by looping the leader chain over the sleeves of the bar. The heavy chain should be attached using a snap hook. Adjust the length of the lead chain so that a few links are still on the floor at the top of the movement.","Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wider for more emphasis on the back, glutes, adductors, and hamstrings, or closer together for more quad development. Keep your head facing forward.","With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. Ideally, your shins should be perpendicular to the ground. Pause when you reach the box, and relax the hip flexors. Never bounce off of a box.","Keeping the weight on your heels and pushing your feet and knees out, drive upward off of the box as you lead the movement with your head. Continue upward, maintaining tightness head to toe."],"category":"strength","images":["Box_Squat_with_Chains/0.jpg","Box_Squat_with_Chains/1.jpg"],"id":"Box_Squat_with_Chains"}'),
('free-exercise-db', 'Brachialis-SMR', 'foam-roller-brachialis-smr', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Brachialis-SMR.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Brachialis-SMR","force":"static","level":"intermediate","mechanic":null,"equipment":"foam roll","primaryMuscles":["biceps"],"secondaryMuscles":[],"instructions":["Lie on your side, with your upper arm against the foam roller. The upper arm should be more or less aligned with your body, with the outside of the bicep pressed against the foam roller.","Raise your hips off of the floor, supporting your weight on your arm and on your feet. Hold for 10-30 seconds, and then switch sides."],"category":"stretching","images":["Brachialis-SMR/0.jpg","Brachialis-SMR/1.jpg"],"id":"Brachialis-SMR"}'),
('free-exercise-db', 'Bradford_Rocky_Presses', 'barbell-bradford-rocky-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Bradford_Rocky_Presses.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Bradford/Rocky Presses","force":"push","level":"beginner","mechanic":"compound","equipment":"barbell","primaryMuscles":["shoulders"],"secondaryMuscles":["triceps"],"instructions":["Sit on a Military Press Bench with a bar at shoulder level with a pronated grip (palms facing forward). Tip: Your grip should be wider than shoulder width and it should create a 90-degree angle between the forearm and the upper arm as the barbell goes down. This is your starting position.","Once you pick up the barbell with the correct grip, lift the bar up over your head by locking your arms.","Now lower the bar down to the back of the head slowly as you inhale.","Lift the bar back up to the starting position as you exhale.","Lower the bar down to the starting position slowly as you inhale. This is one repetition.","Alternate in this manner until you complete the recommended amount of repetitions."],"category":"strength","images":["Bradford_Rocky_Presses/0.jpg","Bradford_Rocky_Presses/1.jpg"],"id":"Bradford_Rocky_Presses"}'),
('free-exercise-db', 'Butt-Ups', 'butt-up', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Butt-Ups.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Butt-Ups","force":"pull","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Begin a pushup position but with your elbows on the ground and resting on your forearms. Your arms should be bent at a 90 degree angle.","Arch your back slightly out rather than keeping your back completely straight.","Raise your glutes toward the ceiling, squeezing your abs tightly to close the distance between your ribcage and hips. The end result will be that you''ll end up in a high bridge position. Exhale as you perform this portion of the movement.","Lower back down slowly to your starting position as you breathe in. Tip: Don''t let your back sag downwards.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Butt-Ups/0.jpg","Butt-Ups/1.jpg"],"id":"Butt-Ups"}'),
('free-exercise-db', 'Butt_Lift_Bridge', 'butt-lift-bridge', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Butt_Lift_Bridge.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Butt Lift (Bridge)","force":"push","level":"beginner","mechanic":"isolation","equipment":"body only","primaryMuscles":["glutes"],"secondaryMuscles":["hamstrings"],"instructions":["Lie flat on the floor on your back with the hands by your side and your knees bent. Your feet should be placed around shoulder width. This will be your starting position.","Pushing mainly with your heels, lift your hips off the floor while keeping your back straight. Breathe out as you perform this part of the motion and hold at the top for a second.","Slowly go back to the starting position as you breathe in."],"category":"strength","images":["Butt_Lift_Bridge/0.jpg","Butt_Lift_Bridge/1.jpg"],"id":"Butt_Lift_Bridge"}'),
('free-exercise-db', 'Butterfly', 'machine-butterfly', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Butterfly.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Butterfly","force":"pull","level":"beginner","mechanic":"isolation","equipment":"machine","primaryMuscles":["chest"],"secondaryMuscles":[],"instructions":["Sit on the machine with your back flat on the pad.","Take hold of the handles. Tip: Your upper arms should be positioned parallel to the floor; adjust the machine accordingly. This will be your starting position.","Push the handles together slowly as you squeeze your chest in the middle. Breathe out during this part of the motion and hold the contraction for a second.","Return back to the starting position slowly as you inhale until your chest muscles are fully stretched.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Butterfly/0.jpg","Butterfly/1.jpg"],"id":"Butterfly"}'),
('free-exercise-db', 'Cable_Chest_Press', 'cable-chest-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Cable_Chest_Press.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Cable Chest Press","force":"push","level":"beginner","mechanic":"compound","equipment":"cable","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 45 degrees to the body, with your head and chest up. The elbows should be bent to about 90 degrees. This will be your starting position.","Begin by extending through the elbow, pressing the handles together straight in front of you. Keep your shoulder blades retracted as you execute the movement.","After pausing at full extension, return to th starting position, keeping tension on the cables.","You can also execute this movement with your back off the pad, at an incline or decline, or alternate hands."],"category":"strength","images":["Cable_Chest_Press/0.jpg","Cable_Chest_Press/1.jpg"],"id":"Cable_Chest_Press"}'),
('free-exercise-db', 'Cable_Crossover', 'cable-cross-over', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Cable_Crossover.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Cable Crossover","force":"push","level":"beginner","mechanic":"isolation","equipment":"cable","primaryMuscles":["chest"],"secondaryMuscles":["shoulders"],"instructions":["To get yourself into the starting position, place the pulleys on a high position (above your head), select the resistance to be used and hold the pulleys in each hand.","Step forward in front of an imaginary straight line between both pulleys while pulling your arms together in front of you. Your torso should have a small forward bend from the waist. This will be your starting position.","With a slight bend on your elbows in order to prevent stress at the biceps tendon, extend your arms to the side (straight out at both sides) in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms and torso should remain stationary; the movement should only occur at the shoulder joint.","Return your arms back to the starting position as you breathe out. Make sure to use the same arc of motion used to lower the weights.","Hold for a second at the starting position and repeat the movement for the prescribed amount of repetitions."],"category":"strength","images":["Cable_Crossover/0.jpg","Cable_Crossover/1.jpg"],"id":"Cable_Crossover"}'),
('free-exercise-db', 'Cable_Crunch', 'cable-crunch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Cable_Crunch.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Cable Crunch","force":"pull","level":"beginner","mechanic":"isolation","equipment":"cable","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Kneel below a high pulley that contains a rope attachment.","Grasp cable rope attachment and lower the rope until your hands are placed next to your face.","Flex your hips slightly and allow the weight to hyperextend the lower back. This will be your starting position.","With the hips stationary, flex the waist as you contract the abs so that the elbows travel towards the middle of the thighs. Exhale as you perform this portion of the movement and hold the contraction for a second.","Slowly return to the starting position as you inhale. Tip: Make sure that you keep constant tension on the abs throughout the movement. Also, do not choose a weight so heavy that the lower back handles the brunt of the work.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Cable_Crunch/0.jpg","Cable_Crunch/1.jpg"],"id":"Cable_Crunch"}'),
('free-exercise-db', 'Cable_Deadlifts', 'cable-deadlift', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Cable_Deadlifts.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Cable Deadlifts","force":"pull","level":"beginner","mechanic":"compound","equipment":"cable","primaryMuscles":["quadriceps"],"secondaryMuscles":["forearms","glutes","hamstrings","lower back"],"instructions":["Move the cables to the bottom of the towers and select an appropriate weight. Stand directly in between the uprights.","To begin, squat down be flexing your hips and knees until you can reach the handles.","After grasping them, begin your ascent. Driving through your heels extend your hips and knees keeping your hands hanging at your side. Keep your head and chest up throughout the movement.","After reaching a full standing position, Return to the starting position and repeat."],"category":"strength","images":["Cable_Deadlifts/0.jpg","Cable_Deadlifts/1.jpg"],"id":"Cable_Deadlifts"}'),
('free-exercise-db', 'Cable_Hammer_Curls_-_Rope_Attachment', 'cable-hammer-curl-rope-attachment', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Cable_Hammer_Curls_-_Rope_Attachment.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Cable Hammer Curls - Rope Attachment","force":"pull","level":"beginner","mechanic":"isolation","equipment":"cable","primaryMuscles":["biceps"],"secondaryMuscles":[],"instructions":["Attach a rope attachment to a low pulley and stand facing the machine about 12 inches away from it.","Grasp the rope with a neutral (palms-in) grip and stand straight up keeping the natural arch of the back and your torso stationary.","Put your elbows in by your side and keep them there stationary during the entire movement. Tip: Only the forearms should move; not your upper arms. This will be your starting position.","Using your biceps, pull your arms up as you exhale until your biceps touch your forearms. Tip: Remember to keep the elbows in and your upper arms stationary.","After a 1 second contraction where you squeeze your biceps, slowly start to bring the weight back to the original position.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Cable_Hammer_Curls_-_Rope_Attachment/0.jpg","Cable_Hammer_Curls_-_Rope_Attachment/1.jpg"],"id":"Cable_Hammer_Curls_-_Rope_Attachment"}'),
('free-exercise-db', 'Cable_Hip_Adduction', 'cable-hip-adduction', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Cable_Hip_Adduction.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Cable Hip Adduction","force":"pull","level":"beginner","mechanic":"isolation","equipment":"cable","primaryMuscles":["quadriceps"],"secondaryMuscles":[],"instructions":["Stand in front of a low pulley facing forward with one leg next to the pulley and the other one away.","Attach the ankle cuff to the cable and also to the ankle of the leg that is next to the pulley.","Now step out and away from the stack with a wide stance and grasp the bar of the pulley system.","Stand on the foot that does not have the ankle cuff (the far foot) and allow the leg with the cuff to be pulled towards the low pulley. This will be your starting position.","Now perform the movement by moving the leg with the ankle cuff in front of the far leg by using the inner thighs to abduct the hip. Breathe out during this portion of the movement.","Slowly return to the starting position as you breathe in.","Repeat for the recommended amount of repetitions and then repeat the same movement with the opposite leg."],"category":"strength","images":["Cable_Hip_Adduction/0.jpg","Cable_Hip_Adduction/1.jpg"],"id":"Cable_Hip_Adduction"}'),
('free-exercise-db', 'Cable_Incline_Pushdown', 'cable-incline-pushdown', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Cable_Incline_Pushdown.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Cable Incline Pushdown","force":"pull","level":"beginner","mechanic":"isolation","equipment":"cable","primaryMuscles":["lats"],"secondaryMuscles":[],"instructions":["Lie on incline an bench facing away from a high pulley machine that has a straight bar attachment on it.","Grasp the straight bar attachment overhead with a pronated (overhand; palms down) shoulder width grip and extend your arms in front of you. The bar should be around 2 inches away from your upper thighs. This will be your starting position.","Keeping the upper arms stationary, lift your arms back in a semi circle until the bar is straight over your head. Breathe in during this portion of the movement.","Slowly go back to the starting position using your lats and hold the contraction once you reach the starting position. Breathe out during the execution of this movement.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Cable_Incline_Pushdown/0.jpg","Cable_Incline_Pushdown/1.jpg"],"id":"Cable_Incline_Pushdown"}'),
('free-exercise-db', 'Cable_Incline_Triceps_Extension', 'cable-incline-triceps-extension', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Cable_Incline_Triceps_Extension.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Cable Incline Triceps Extension","force":"push","level":"beginner","mechanic":"isolation","equipment":"cable","primaryMuscles":["triceps"],"secondaryMuscles":[],"instructions":["Lie on incline an bench facing away from a high pulley machine that has a straight bar attachment on it.","Grasp the straight bar attachment overhead with a pronated (overhand; palms down) narrow grip (less than shoulder width) and keep your elbows tucked in to your sides. Your upper arms should create around a 25 degree angle when measured from the floor.","Keeping the upper arms stationary, extend the arms as you flex the triceps. Breathe out during this portion of the movement and hold the contraction for a second.","Slowly go back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Cable_Incline_Triceps_Extension/0.jpg","Cable_Incline_Triceps_Extension/1.jpg"],"id":"Cable_Incline_Triceps_Extension"}'),
('free-exercise-db', 'Cable_Internal_Rotation', 'cable-internal-rotation', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Cable_Internal_Rotation.json', 'Unlicense', NULL, 'new', 88.2, '{"name":"Cable Internal Rotation","force":"pull","level":"beginner","mechanic":"compound","equipment":"cable","primaryMuscles":["shoulders"],"secondaryMuscles":[],"instructions":["Sit next to a low pulley sideways (with legs stretched in front of you or crossed) and grasp the single hand cable attachment with the arm nearest to the cable. Tip: If you can adjust the pulley''s height, you can use a flat bench to sit on instead.","Position the elbow against your side with the elbow bent at 90° and the arm pointing towards the pulley. This will be your starting position.","Pull the single hand cable attachment toward your body by internally rotating your shoulder until your forearm is across your abs. You will be creating an imaginary semi-circle. Tip: The forearm should be perpendicular to your torso at all times.","Slowly go back to the initial position.","Repeat for the recommended amount of repetitions and then repeat the movement with the next arm."],"category":"strength","images":["Cable_Internal_Rotation/0.jpg","Cable_Internal_Rotation/1.jpg"],"id":"Cable_Internal_Rotation"}'),
('free-exercise-db', 'Cable_Iron_Cross', 'cable-iron-cross', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Cable_Iron_Cross.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Cable Iron Cross","force":"push","level":"beginner","mechanic":"isolation","equipment":"cable","primaryMuscles":["chest"],"secondaryMuscles":[],"instructions":["Begin by moving the pulleys to the high position, select the resistance to be used, and take a handle in each hand.","Stand directly between both pulleys with your arms extended out to your sides. Your head and chest should be up while your arms form a \"T\". This will be your starting position.","Keeping the elbows extended, pull your arms straight to your sides.","Return your arms back to the starting position after a pause at the peak contraction.","Continue the movement for the prescribed number of repetitions."],"category":"strength","images":["Cable_Iron_Cross/0.jpg","Cable_Iron_Cross/1.jpg"],"id":"Cable_Iron_Cross"}'),
('free-exercise-db', 'Cable_Judo_Flip', 'cable-judo-flip', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Cable_Judo_Flip.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Cable Judo Flip","force":"pull","level":"beginner","mechanic":"compound","equipment":"cable","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Connect a rope attachment to a tower, and move the cable to the lowest pulley position. Stand with your side to the cable with a wide stance, and grab the rope with both hands.","Twist your body away from the pulley as you bring the rope over your shoulder like you''re performing a judo flip.","Shift your weight between your feet as you twist and crunch forward, pulling the cable downward.","Return to the starting position and repeat until failure.","Then, reposition and repeat the same series of movements on the opposite side."],"category":"strength","images":["Cable_Judo_Flip/0.jpg","Cable_Judo_Flip/1.jpg"],"id":"Cable_Judo_Flip"}'),
('free-exercise-db', 'Cable_Lying_Triceps_Extension', 'cable-lying-triceps-extension', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Cable_Lying_Triceps_Extension.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Cable Lying Triceps Extension","force":"push","level":"beginner","mechanic":"isolation","equipment":"cable","primaryMuscles":["triceps"],"secondaryMuscles":[],"instructions":["Lie on a flat bench and grasp the straight bar attachment of a low pulley with a narrow overhand grip. Tip: The easiest way to do this is to have someone hand you the bar as you lay down.","With your arms extended, position the bar over your torso. Your arms and your torso should create a 90-degree angle. This will be your starting position.","Lower the bar by bending at the elbow while keeping the upper arms stationary and elbows in. Go down until the bar lightly touches your forehead. Breathe in as you perform this portion of the movement.","Flex the triceps as you lift the bar back to its starting position. Exhale as you perform this portion of the movement.","Hold for a second at the contracted position and repeat for the recommended amount of repetitions."],"category":"strength","images":["Cable_Lying_Triceps_Extension/0.jpg","Cable_Lying_Triceps_Extension/1.jpg"],"id":"Cable_Lying_Triceps_Extension"}'),
('free-exercise-db', 'Cable_One_Arm_Tricep_Extension', 'cable-one-arm-tricep-extension', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Cable_One_Arm_Tricep_Extension.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Cable One Arm Tricep Extension","force":"push","level":"beginner","mechanic":"isolation","equipment":"cable","primaryMuscles":["triceps"],"secondaryMuscles":[],"instructions":["With your right hand, grasp a single handle attached to the high-cable pulley using a supinated (underhand; palms facing up) grip. You should be standing directly in front of the weight stack.","Now pull the handle down so that your upper arm and elbow are locked in to the side of your body. Your upper arm and forearm should form an acute angle (less than 90-degrees). You can keep the other arm by the waist and you can have one leg in front of you and the other one back for better balance. This will be your starting position.","As you contract the triceps, move the single handle attachment down to your side until your arm is straight. Breathe out as you perform this movement. Tip: Only the forearms should move. Your upper arms should remain stationary at all times.","Squeeze the triceps and hold for a second in this contracted position.","Slowly return the handle to the starting position.","Repeat for the recommended amount of repetitions and then perform the same movement with the other arm."],"category":"strength","images":["Cable_One_Arm_Tricep_Extension/0.jpg","Cable_One_Arm_Tricep_Extension/1.jpg"],"id":"Cable_One_Arm_Tricep_Extension"}'),
('free-exercise-db', 'Cable_Preacher_Curl', 'cable-preacher-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Cable_Preacher_Curl.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Cable Preacher Curl","force":"pull","level":"beginner","mechanic":"isolation","equipment":"cable","primaryMuscles":["biceps"],"secondaryMuscles":["forearms"],"instructions":["Place a preacher bench about 2 feet in front of a pulley machine.","Attach a straight bar to the low pulley.","Sit at the preacher bench with your elbow and upper arms firmly on top of the bench pad and have someone hand you the bar from the low pulley.","Grab the bar and fully extend your arms on top of the preacher bench pad. This will be your starting position.","Now start pilling the weight up towards your shoulders and squeeze the biceps hard at the top of the movement. Exhale as you perform this motion. Also, hold for a second at the top.","Now slowly lower the weight to the starting position.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Cable_Preacher_Curl/0.jpg","Cable_Preacher_Curl/1.jpg"],"id":"Cable_Preacher_Curl"}'),
('free-exercise-db', 'Cable_Rear_Delt_Fly', 'cable-rear-delt-fly', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Cable_Rear_Delt_Fly.json', 'Unlicense', NULL, 'exact', 100.0, '{"name":"Cable Rear Delt Fly","force":"pull","level":"beginner","mechanic":"isolation","equipment":"cable","primaryMuscles":["shoulders"],"secondaryMuscles":[],"instructions":["Adjust the pulleys to the appropriate height and adjust the weight. The pulleys should be above your head.","Grab the left pulley with your right hand and the right pulley with your left hand, crossing them in front of you. This will be your starting position.","Initiate the movement by moving your arms back and outward, keeping your arms straight as you execute the movement.","Pause at the end of the motion before returning the handles to the start position."],"category":"strength","images":["Cable_Rear_Delt_Fly/0.jpg","Cable_Rear_Delt_Fly/1.jpg"],"id":"Cable_Rear_Delt_Fly"}'),
('free-exercise-db', 'Cable_Reverse_Crunch', 'cable-reverse-crunch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Cable_Reverse_Crunch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Cable Reverse Crunch","force":"pull","level":"beginner","mechanic":"isolation","equipment":"cable","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Connect an ankle strap attachment to a low pulley cable and position a mat on the floor in front of it.","Sit down with your feet toward the pulley and attach the cable to your ankles.","Lie down, elevate your legs and bend your knees at a 90-degree angle. Your legs and the cable should be aligned. If not, adjust the pulley up or down until they are.","With your hands behind your head, bring your knees inward to your torso and elevate your hips off the floor.","Pause for a moment and in a slow and controlled manner drop your hips and bring your legs back to the starting 90-degree angle. You should still have tension on your abs in the resting position.","Repeat the same movement to failure."],"category":"strength","images":["Cable_Reverse_Crunch/0.jpg","Cable_Reverse_Crunch/1.jpg"],"id":"Cable_Reverse_Crunch"}'),
('free-exercise-db', 'Cable_Rope_Overhead_Triceps_Extension', 'cable-rope-overhead-triceps-extension', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Cable_Rope_Overhead_Triceps_Extension.json', 'Unlicense', NULL, 'new', 91.2, '{"name":"Cable Rope Overhead Triceps Extension","force":"push","level":"beginner","mechanic":"isolation","equipment":"cable","primaryMuscles":["triceps"],"secondaryMuscles":[],"instructions":["Attach a rope to the bottom pulley of the pulley machine.","Grasping the rope with both hands, extend your arms with your hands directly above your head using a neutral grip (palms facing each other). Your elbows should be in close to your head and the arms should be perpendicular to the floor with the knuckles aimed at the ceiling. This will be your starting position.","Slowly lower the rope behind your head as you hold the upper arms stationary. Inhale as you perform this movement and pause when your triceps are fully stretched.","Return to the starting position by flexing your triceps as you breathe out.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Cable_Rope_Overhead_Triceps_Extension/0.jpg","Cable_Rope_Overhead_Triceps_Extension/1.jpg"],"id":"Cable_Rope_Overhead_Triceps_Extension"}'),
('free-exercise-db', 'Cable_Rope_Rear-Delt_Rows', 'cable-rope-rear-delt-row', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Cable_Rope_Rear-Delt_Rows.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Cable Rope Rear-Delt Rows","force":"pull","level":"beginner","mechanic":"compound","equipment":"cable","primaryMuscles":["shoulders"],"secondaryMuscles":["biceps","middle back"],"instructions":["Sit in the same position on a low pulley row station as you would if you were doing seated cable rows for the back.","Attach a rope to the pulley and grasp it with an overhand grip. Your arms should be extended and parallel to the floor with the elbows flared out.","Keep your lower back upright and slide your hips back so that your knees are slightly bent. This will be your starting position.","Pull the cable attachment towards your upper chest, just below the neck, as you keep your elbows up and out to the sides. Continue this motion as you exhale until the elbows travel slightly behind the back. Tip: Keep your upper arms horizontal, perpendicular to the torso and parallel to the floor throughout the motion.","Go back to the initial position where the arms are extended and the shoulders are stretched forward. Inhale as you perform this portion of the movement.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Cable_Rope_Rear-Delt_Rows/0.jpg","Cable_Rope_Rear-Delt_Rows/1.jpg"],"id":"Cable_Rope_Rear-Delt_Rows"}'),
('free-exercise-db', 'Cable_Russian_Twists', 'cable-russian-twist', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Cable_Russian_Twists.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Cable Russian Twists","force":"pull","level":"beginner","mechanic":"compound","equipment":"cable","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Connect a standard handle attachment, and position the cable to a middle pulley position.","Lie on a stability ball perpendicular to the cable and grab the handle with one hand. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable.","Grab the handle with both hands and fully extend your arms above your chest. You hands should be directly in-line with the pulley. If not, adjust the pulley up or down until they are.","Keep your hips elevated and abs engaged. Rotate your torso away from the pulley for a full-quarter rotation. Your body should be flat from head to knees.","Pause for a moment and in a slow and controlled manner reset to the starting position. You should still have side tension on the cable in the resting position.","Repeat the same movement to failure.","Then, reposition and repeat the same series of movements on the opposite side."],"category":"strength","images":["Cable_Russian_Twists/0.jpg","Cable_Russian_Twists/1.jpg"],"id":"Cable_Russian_Twists"}'),
('free-exercise-db', 'Cable_Seated_Crunch', 'cable-seated-crunch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Cable_Seated_Crunch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Cable Seated Crunch","force":"pull","level":"beginner","mechanic":"isolation","equipment":"cable","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Seat on a flat bench with your back facing a high pulley.","Grasp the cable rope attachment with both hands (with the palms of the hands facing each other) and place your hands securely over both shoulders. Tip: Allow the weight to hyperextend the lower back slightly. This will be your starting position.","With the hips stationary, flex the waist so the elbows travel toward the hips. Breathe out as you perform this step.","As you inhale, go back to the initial position slowly.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Cable_Seated_Crunch/0.jpg","Cable_Seated_Crunch/1.jpg"],"id":"Cable_Seated_Crunch"}'),
('free-exercise-db', 'Cable_Seated_Lateral_Raise', 'cable-seated-lateral-raise', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Cable_Seated_Lateral_Raise.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Cable Seated Lateral Raise","force":"pull","level":"beginner","mechanic":"isolation","equipment":"cable","primaryMuscles":["shoulders"],"secondaryMuscles":["middle back","traps"],"instructions":["Stand in the middle of two low pulleys that are opposite to each other and place a flat bench right behind you (in perpendicular fashion to you; the narrow edge of the bench should be the one behind you). Select the weight to be used on each pulley.","Now sit at the edge of the flat bench behind you with your feet placed in front of your knees.","Bend forward while keeping your back flat and rest your torso on the thighs.","Have someone give you the single handles attached to the pulleys. Grasp the left pulley with the right hand and the right pulley with the left after you select your weight. The pulleys should run under your knees and your arms will be extended with palms facing each other and a slight bend at the elbows. This will be the starting position.","While keeping the arms stationary, raise the upper arms to the sides until they are parallel to the floor and at shoulder height. Exhale during the execution of this movement and hold the contraction for a second.","Slowly lower your arms to the starting position as you inhale.","Repeat for the recommended amount of repetitions. Tip: Maintain upper arms perpendicular to torso and a fixed elbow position (10 degree to 30 degree angle) throughout exercise."],"category":"strength","images":["Cable_Seated_Lateral_Raise/0.jpg","Cable_Seated_Lateral_Raise/1.jpg"],"id":"Cable_Seated_Lateral_Raise"}'),
('free-exercise-db', 'Cable_Shoulder_Press', 'cable-shoulder-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Cable_Shoulder_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Cable Shoulder Press","force":"push","level":"beginner","mechanic":"compound","equipment":"cable","primaryMuscles":["shoulders"],"secondaryMuscles":["triceps"],"instructions":["Move the cables to the bottom of the towers and select an appropriate weight.","Stand directly in between the uprights. Grasp the cables and hold them at shoulder height, palms facing forward. This will be your starting position.","Keeping your head and chest up, extend through the elbow to press the handles directly over head.","After pausing at the top, return to the starting position and repeat."],"category":"strength","images":["Cable_Shoulder_Press/0.jpg","Cable_Shoulder_Press/1.jpg"],"id":"Cable_Shoulder_Press"}'),
('free-exercise-db', 'Cable_Shrugs', 'cable-shrug-in', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Cable_Shrugs.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Cable Shrugs","force":"pull","level":"beginner","mechanic":"isolation","equipment":"cable","primaryMuscles":["traps"],"secondaryMuscles":[],"instructions":["Grasp a cable bar attachment that is attached to a low pulley with a shoulder width or slightly wider overhand (palms facing down) grip.","Stand erect close to the pulley with your arms extended in front of you holding the bar. This will be your starting position.","Lift the bar by elevating the shoulders as high as possible as you exhale. Hold the contraction at the top for a second. Tip: The arms should remain extended at all times. Refrain from using the biceps to help lift the bar. Only the shoulders should be moving up and down.","Lower the bar back to the original position.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Cable_Shrugs/0.jpg","Cable_Shrugs/1.jpg"],"id":"Cable_Shrugs"}'),
('free-exercise-db', 'Cable_Wrist_Curl', 'cable-wrist-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Cable_Wrist_Curl.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Cable Wrist Curl","force":"pull","level":"beginner","mechanic":"isolation","equipment":"cable","primaryMuscles":["forearms"],"secondaryMuscles":[],"instructions":["Start out by placing a flat bench in front of a low pulley cable that has a straight bar attachment.","Use your arms to grab the cable bar with a narrow to shoulder width supinated grip (palms up) and bring them up so that your forearms are resting against the top of your thighs. Your wrists should be hanging just beyond your knees.","Start out by curling your wrist upwards and exhaling. Keep the contraction for a second.","Slowly lower your wrists back down to the starting position while inhaling.","Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Cable_Wrist_Curl/0.jpg","Cable_Wrist_Curl/1.jpg"],"id":"Cable_Wrist_Curl"}'),
('free-exercise-db', 'Calf-Machine_Shoulder_Shrug', 'machine-calf-shoulder-shrug', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Calf-Machine_Shoulder_Shrug.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Calf-Machine Shoulder Shrug","force":"pull","level":"beginner","mechanic":"isolation","equipment":"machine","primaryMuscles":["traps"],"secondaryMuscles":[],"instructions":["Position yourself on the calf machine so that the shoulder pads are above your shoulders. Your torso should be straight with the arms extended normally by your side. This will be your starting position.","Raise your shoulders up towards your ears as you exhale and hold the contraction for a full second.","Slowly return to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Calf-Machine_Shoulder_Shrug/0.jpg","Calf-Machine_Shoulder_Shrug/1.jpg"],"id":"Calf-Machine_Shoulder_Shrug"}'),
('free-exercise-db', 'Calf_Press', 'machine-calf-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Calf_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Calf Press","force":"push","level":"beginner","mechanic":"isolation","equipment":"machine","primaryMuscles":["calves"],"secondaryMuscles":[],"instructions":["Adjust the seat so that your legs are only slightly bent in the start position. The balls of your feet should be firmly on the platform.","Select an appropriate weight, and grasp the handles. This will be your starting position.","Straighten the legs by extending the knees, just barely lifting the weight from the stack. Your ankle should be fully flexed, toes pointing up. Execute the movement by pressing downward through the balls of your feet as far as possible.","After a brief pause, reverse the motion and repeat."],"category":"strength","images":["Calf_Press/0.jpg","Calf_Press/1.jpg"],"id":"Calf_Press"}'),
('free-exercise-db', 'Calf_Press_On_The_Leg_Press_Machine', 'machine-calf-press-leg', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Calf_Press_On_The_Leg_Press_Machine.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Calf Press On The Leg Press Machine","force":"push","level":"beginner","mechanic":"isolation","equipment":"machine","primaryMuscles":["calves"],"secondaryMuscles":[],"instructions":["Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance.","Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you without locking your knees. (Note: In some leg press units you can leave the safety bars on for increased safety. If your leg press unit allows for this, then this is the preferred method of performing the exercise.) Your torso and the legs should make perfect 90-degree angle. Now carefully place your toes and balls of your feet on the lower portion of the platform with the heels extending off. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter. This will be your starting position.","Press on the platform by raising your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.","Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Calf_Press_On_The_Leg_Press_Machine/0.jpg","Calf_Press_On_The_Leg_Press_Machine/1.jpg"],"id":"Calf_Press_On_The_Leg_Press_Machine"}'),
('free-exercise-db', 'Calf_Raise_On_A_Dumbbell', 'dumbbell-calf-raise', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Calf_Raise_On_A_Dumbbell.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Calf Raise On A Dumbbell","force":"push","level":"intermediate","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["calves"],"secondaryMuscles":[],"instructions":["Hang on to a sturdy object for balance and stand on a dumbbell handle, preferably one with round plates so that it rolls as in this manner you have to work harder to stabilize yourself; thus increasing the effectiveness of the exercise.","Now roll your foot slightly forward so that you can get a nice stretch of the calf. This will be your starting position.","Lift the calf as you roll your foot over the top of the handle so that you get a full extension. Exhale during the execution of this movement. Contract the calf hard at the top and hold for a second. Tip: As you come up, roll the dumbbell slightly backward.","Now inhale as you roll the dumbbell slightly forward as you come down to get a better stretch.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Calf_Raise_On_A_Dumbbell/0.jpg","Calf_Raise_On_A_Dumbbell/1.jpg"],"id":"Calf_Raise_On_A_Dumbbell"}'),
('free-exercise-db', 'Calf_Raises_-_With_Bands', 'band-calf-raise', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Calf_Raises_-_With_Bands.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Calf Raises - With Bands","force":"push","level":"beginner","mechanic":"isolation","equipment":"bands","primaryMuscles":["calves"],"secondaryMuscles":[],"instructions":["Grab an exercise band and stand on it with your toes making sure that the length of the band between the foot and the arms is the same for both sides.","While holding the handles of the band, raise the arms to the side of your head as if you were getting ready to perform a shoulder press. The palms should be facing forward with the elbows bent and to the sides. This movement will create tension on the band. This will be your starting position.","Keeping the hands by your shoulder, stand up on your toes as you exhale and contract the calves hard at the top of the movement.","After a one second contraction, slowly go back down to the starting position.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Calf_Raises_-_With_Bands/0.jpg","Calf_Raises_-_With_Bands/1.jpg"],"id":"Calf_Raises_-_With_Bands"}'),
('free-exercise-db', 'Calf_Stretch_Elbows_Against_Wall', 'calf-stretch-elbows-against-wall', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Calf_Stretch_Elbows_Against_Wall.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Calf Stretch Elbows Against Wall","force":"static","level":"beginner","mechanic":"isolation","equipment":null,"primaryMuscles":["calves"],"secondaryMuscles":[],"instructions":["Stand facing a wall from a couple feet away.","Lean against the wall, placing your weight on your forearms.","Attempt to keep your heels on the ground. Hold for 10-20 seconds. You may move further or closer the wall, making it more or less difficult, respectively."],"category":"stretching","images":["Calf_Stretch_Elbows_Against_Wall/0.jpg","Calf_Stretch_Elbows_Against_Wall/1.jpg"],"id":"Calf_Stretch_Elbows_Against_Wall"}'),
('free-exercise-db', 'Calf_Stretch_Hands_Against_Wall', 'calf-stretch-hands-against-wall', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Calf_Stretch_Hands_Against_Wall.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Calf Stretch Hands Against Wall","force":"static","level":"beginner","mechanic":"isolation","equipment":null,"primaryMuscles":["calves"],"secondaryMuscles":[],"instructions":["Stand facing a wall from several feet away. Stagger your stance, placing one foot forward.","Lean forward and rest your hands on the wall, keeping your heel, hip and head in a straight line.","Attempt to keep your heel on the ground. Hold for 10-20 seconds and then switch sides."],"category":"stretching","images":["Calf_Stretch_Hands_Against_Wall/0.jpg","Calf_Stretch_Hands_Against_Wall/1.jpg"],"id":"Calf_Stretch_Hands_Against_Wall"}'),
('free-exercise-db', 'Calves-SMR', 'foam-roller-calves-smr', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Calves-SMR.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Calves-SMR","force":"static","level":"intermediate","mechanic":null,"equipment":"foam roll","primaryMuscles":["calves"],"secondaryMuscles":[],"instructions":["Begin seated on the floor. Place a foam roller underneath your lower leg. Your other leg can either be crossed over the opposite or be placed on the floor, supporting some of your weight. This will be your starting position.","Place your hands to your side or just behind you, and press down to raise your hips off of the floor, placing much of your weight against your calf muscle. Roll from below the knee to above the ankle, pausing at points of tension for 10-30 seconds. Repeat for the other leg."],"category":"stretching","images":["Calves-SMR/0.jpg","Calves-SMR/1.jpg"],"id":"Calves-SMR"}'),
('free-exercise-db', 'Car_Deadlift', 'car-deadlift', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Car_Deadlift.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Car Deadlift","force":"pull","level":"intermediate","mechanic":"compound","equipment":"other","primaryMuscles":["quadriceps"],"secondaryMuscles":["forearms","glutes","hamstrings","lower back","traps"],"instructions":["This event apparatus typically has neutral grip handles, however some have a straight bar that you can approach like a normal deadlift. The apparatus can be loaded with a vehicle or other heavy objects such as tractor tires or kegs.","Center yourself between the handles if you are a strong squatter, or back a couple inches if you are a strong deadlifter. You feet should be about hip width apart. Bend at the hip to grip the handles. With your feet and your grip set, take a big breath and then lower your hips and flex the knees.","Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. As the weight comes up, pull your shoulder blades together as you drive your hips forward.","Lower the weight by bending at the hips and guiding it to the floor."],"category":"strongman","images":["Car_Deadlift/0.jpg","Car_Deadlift/1.jpg"],"id":"Car_Deadlift"}'),
('free-exercise-db', 'Car_Drivers', 'barbell-car-drivers', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Car_Drivers.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Car Drivers","force":"push","level":"beginner","mechanic":"isolation","equipment":"barbell","primaryMuscles":["shoulders"],"secondaryMuscles":["forearms"],"instructions":["While standing upright, hold a barbell plate in both hands at the 3 and 9 o''clock positions. Your palms should be facing each other and your arms should be extended straight out in front of you. This will be your starting position.","Initiate the movement by rotating the plate as far to one side as possible. Use the same type of movement you would use to turn a steering wheel to one side.","Reverse the motion, turning it all the way to the opposite side.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Car_Drivers/0.jpg","Car_Drivers/1.jpg"],"id":"Car_Drivers"}'),
('free-exercise-db', 'Carioca_Quick_Step', 'carioca-quick-step', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Carioca_Quick_Step.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Carioca Quick Step","force":null,"level":"beginner","mechanic":null,"equipment":null,"primaryMuscles":["adductors"],"secondaryMuscles":["abdominals","abductors","calves","glutes","hamstrings","quadriceps"],"instructions":["Begin with your feet a few inches apart and your left arm up in a relaxed, athletic position.","With your right foot, quick step behind and pull the knee up.","Fire your arms back up when you pull the right knee, being sure that your knee goes straight up and down. Avoid turning your feet as you move and continue to look forward as you move to the side."],"category":"plyometrics","images":["Carioca_Quick_Step/0.jpg","Carioca_Quick_Step/1.jpg"],"id":"Carioca_Quick_Step"}'),
('free-exercise-db', 'Cat_Stretch', 'cat-stretch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Cat_Stretch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Cat Stretch","force":"static","level":"beginner","mechanic":null,"equipment":null,"primaryMuscles":["lower back"],"secondaryMuscles":["middle back","traps"],"instructions":["Position yourself on the floor on your hands and knees.","Pull your belly in and round your spine, lower back, shoulders, and neck, letting your head drop.","Hold for 15 seconds."],"category":"stretching","images":["Cat_Stretch/0.jpg","Cat_Stretch/1.jpg"],"id":"Cat_Stretch"}'),
('free-exercise-db', 'Catch_and_Overhead_Throw', 'medicine-ball-catch-and-overhead-throw', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Catch_and_Overhead_Throw.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Catch and Overhead Throw","force":"push","level":"beginner","mechanic":"compound","equipment":"medicine ball","primaryMuscles":["lats"],"secondaryMuscles":["abdominals","chest","shoulders"],"instructions":["Begin standing while facing a wall or a partner.","Using both hands, position the ball behind your head, stretching as much as possible, and forcefully throw the ball forward.","Ensure that you follow your throw through, being prepared to receive your rebound from your throw. If you are throwing against the wall, make sure that you stand close enough to the wall to receive the rebound, and aim a little higher than you would with a partner."],"category":"plyometrics","images":["Catch_and_Overhead_Throw/0.jpg","Catch_and_Overhead_Throw/1.jpg"],"id":"Catch_and_Overhead_Throw"}'),
('free-exercise-db', 'Chain_Handle_Extension', 'chain-handle-extension', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Chain_Handle_Extension.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Chain Handle Extension","force":"push","level":"intermediate","mechanic":"isolation","equipment":"other","primaryMuscles":["triceps"],"secondaryMuscles":[],"instructions":["You will need two cable handle attachments and a flat bench, as well as chains, for this exercise. Clip the middle of the chains to the handles, and position yourself on the flat bench. Your elbows should be pointing straight up.","Begin by extending through the elbow, keeping your upper arm still, with your wrists pronated.","Pause at the lockout, and reverse the motion to return to the starting position."],"category":"powerlifting","images":["Chain_Handle_Extension/0.jpg","Chain_Handle_Extension/1.jpg"],"id":"Chain_Handle_Extension"}'),
('free-exercise-db', 'Chain_Press', 'chain-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Chain_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Chain Press","force":"push","level":"intermediate","mechanic":"compound","equipment":"other","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["Begin by connecting the chains to the cable handle attachments. Position yourself on the flat bench in the same position as for a dumbbell press. Your wrists should be pronated and arms perpendicular to the floor. This will be your starting position.","Lower the chains by flexing the elbows, unloading some of the chain onto the floor.","Continue until your elbow forms a 90 degree angle, and then reverse the motion by extending through the elbow to lockout."],"category":"powerlifting","images":["Chain_Press/0.jpg","Chain_Press/1.jpg"],"id":"Chain_Press"}'),
('free-exercise-db', 'Chair_Leg_Extended_Stretch', 'chair-leg-extended-stretch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Chair_Leg_Extended_Stretch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Chair Leg Extended Stretch","force":"static","level":"beginner","mechanic":"isolation","equipment":"other","primaryMuscles":["hamstrings"],"secondaryMuscles":["adductors"],"instructions":["Sit upright in a chair and grip the seat on the sides.","Raise one leg, extending the knee, flexing the ankle as you do so.","Slowly move that leg outward as far as you can, and then back to the center and down.","Repeat for your other leg."],"category":"stretching","images":["Chair_Leg_Extended_Stretch/0.jpg","Chair_Leg_Extended_Stretch/1.jpg"],"id":"Chair_Leg_Extended_Stretch"}'),
('free-exercise-db', 'Chair_Lower_Back_Stretch', 'chair-lower-back-stretch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Chair_Lower_Back_Stretch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Chair Lower Back Stretch","force":"static","level":"beginner","mechanic":"isolation","equipment":null,"primaryMuscles":["lats"],"secondaryMuscles":["lower back"],"instructions":["Sit upright on a chair.","Bend to one side with your arm over your head. You can hold onto the chair with your free hand.","Hold for 10 seconds, and repeat for your other side."],"category":"stretching","images":["Chair_Lower_Back_Stretch/0.jpg","Chair_Lower_Back_Stretch/1.jpg"],"id":"Chair_Lower_Back_Stretch"}'),
('free-exercise-db', 'Chair_Squat', 'machine-chair-squat', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Chair_Squat.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Chair Squat","force":"push","level":"beginner","mechanic":"compound","equipment":"machine","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings"],"instructions":["To begin, first set the bar to a position that best matches your height. Once the bar is loaded, step under it and position it across the back of your shoulders.","Take the bar with your hands facing forward, unlock it and lift it off the rack by extending your legs.","Move your feet forward about 18 inches in front of the bar. Position your legs using a shoulder width stance with the toes slightly pointed out. Look forward at all times and maintain a neutral or slightly arched spine. This will be your starting position.","Slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper and lower leg breaks 90 degrees.","Begin to raise the bar as you exhale by pushing the floor with the heels of your feet, extending the knees and returning to the starting position.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Chair_Squat/0.jpg","Chair_Squat/1.jpg"],"id":"Chair_Squat"}'),
('free-exercise-db', 'Chair_Upper_Body_Stretch', 'chair-upper-body-stretch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Chair_Upper_Body_Stretch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Chair Upper Body Stretch","force":"static","level":"beginner","mechanic":null,"equipment":"other","primaryMuscles":["shoulders"],"secondaryMuscles":["biceps","chest"],"instructions":["Sit on the edge of a chair, gripping the back of it.","Straighten your arms, keeping your back straight, and pull your upper body forward so you feel a stretch. Hold for 20-30 seconds."],"category":"stretching","images":["Chair_Upper_Body_Stretch/0.jpg","Chair_Upper_Body_Stretch/1.jpg"],"id":"Chair_Upper_Body_Stretch"}'),
('free-exercise-db', 'Chest_And_Front_Of_Shoulder_Stretch', 'chest-and-front-shoulder-stretch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Chest_And_Front_Of_Shoulder_Stretch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Chest And Front Of Shoulder Stretch","force":"static","level":"beginner","mechanic":"isolation","equipment":"other","primaryMuscles":["chest"],"secondaryMuscles":["shoulders"],"instructions":["Start off by standing with your legs together, holding a bodybar or a broomstick.","Take a slightly wider than shoulder width grip on the pole and hold it in front of you with your palms facing down.","Carefully lift the pole up and behind your head."],"category":"stretching","images":["Chest_And_Front_Of_Shoulder_Stretch/0.jpg","Chest_And_Front_Of_Shoulder_Stretch/1.jpg"],"id":"Chest_And_Front_Of_Shoulder_Stretch"}'),
('free-exercise-db', 'Chest_Push_from_3_point_stance', 'medicine-ball-chest-push-from-3-point-stance', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Chest_Push_from_3_point_stance.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Chest Push from 3 point stance","force":"push","level":"beginner","mechanic":"compound","equipment":"medicine ball","primaryMuscles":["chest"],"secondaryMuscles":["abdominals","shoulders","triceps"],"instructions":["Begin in a three point stance, squatted down with your back flat and one hand on the ground. Place the medicine ball directly in front of you.","To begin, take your first step as you pull the ball to your chest, positioning both hands to prepare for the throw.","As you execute the second step, explosively release the ball forward as hard as possible."],"category":"plyometrics","images":["Chest_Push_from_3_point_stance/0.jpg","Chest_Push_from_3_point_stance/1.jpg"],"id":"Chest_Push_from_3_point_stance"}'),
('free-exercise-db', 'Chest_Push_multiple_response', 'medicine-ball-chest-push-multiple-response', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Chest_Push_multiple_response.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Chest Push (multiple response)","force":"push","level":"beginner","mechanic":"compound","equipment":"medicine ball","primaryMuscles":["chest"],"secondaryMuscles":["abdominals","shoulders","triceps"],"instructions":["Begin in a kneeling position facing a wall or utilize a partner. Hold the ball with both hands tight into the chest.","Execute the pass by exploding forward and outward with the hips while pushing the ball as hard as possible.","Follow through by falling forward, catching yourself with your hands.","Immediately return to an upright position. Repeat for the desired number of repetitions."],"category":"plyometrics","images":["Chest_Push_multiple_response/0.jpg","Chest_Push_multiple_response/1.jpg"],"id":"Chest_Push_multiple_response"}'),
('free-exercise-db', 'Chest_Push_single_response', 'medicine-ball-chest-push-single-response', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Chest_Push_single_response.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Chest Push (single response)","force":"push","level":"beginner","mechanic":"compound","equipment":"medicine ball","primaryMuscles":["chest"],"secondaryMuscles":["abdominals","shoulders","triceps"],"instructions":["Begin in a kneeling position holding the medicine ball with both hands tightly into the chest.","Execute the pass by exploding forward and outward with the hips while pushing the ball as far as possible.","Follow through by falling forward, catching yourself with your hands."],"category":"plyometrics","images":["Chest_Push_single_response/0.jpg","Chest_Push_single_response/1.jpg"],"id":"Chest_Push_single_response"}'),
('free-exercise-db', 'Chest_Push_with_Run_Release', 'medicine-ball-chest-push-run-release', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Chest_Push_with_Run_Release.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Chest Push with Run Release","force":"push","level":"beginner","mechanic":"compound","equipment":"medicine ball","primaryMuscles":["chest"],"secondaryMuscles":["abdominals","shoulders","triceps"],"instructions":["Begin in an athletic stance with the knees bent, hips back, and back flat. Hold the medicine ball near your legs. This will be your starting position.","While taking your first step draw the medicine ball into your chest.","As you take the second step, explosively push the ball forward, immediately sprinting for 10 yards after the release. If you are really fast, you can catch your own pass!"],"category":"plyometrics","images":["Chest_Push_with_Run_Release/0.jpg","Chest_Push_with_Run_Release/1.jpg"],"id":"Chest_Push_with_Run_Release"}'),
('free-exercise-db', 'Chest_Stretch_on_Stability_Ball', 'exercise-ball-chest-stretch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Chest_Stretch_on_Stability_Ball.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Chest Stretch on Stability Ball","force":"static","level":"beginner","mechanic":"isolation","equipment":"exercise ball","primaryMuscles":["chest"],"secondaryMuscles":[],"instructions":["Get on your hands and knees next to an exercise ball.","Place your elbows on top of the ball, keeping your arm out to your side. This will be your starting position.","Lower your torso towards the floor, keeping your elbow on top of the ball. Hold the stretch for 20-30 seconds, and repeat with the other arm."],"category":"stretching","images":["Chest_Stretch_on_Stability_Ball/0.jpg","Chest_Stretch_on_Stability_Ball/1.jpg"],"id":"Chest_Stretch_on_Stability_Ball"}'),
('free-exercise-db', 'Childs_Pose', 'childs-pose', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Childs_Pose.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Child''s Pose","force":"static","level":"beginner","mechanic":null,"equipment":null,"primaryMuscles":["lower back"],"secondaryMuscles":["glutes","middle back"],"instructions":["Get on your hands and knees, walk your hands in front of you.","Lower your buttocks down to sit on your heels. Let your arms drag along the floor as you sit back to stretch your entire spine.","Once you settle onto your heels, bring your hands next to your feet and relax. \"breathe\" into your back. Rest your forehead on the floor. Avoid this position if you have knee problems."],"category":"stretching","images":["Childs_Pose/0.jpg","Childs_Pose/1.jpg"],"id":"Childs_Pose"}'),
('free-exercise-db', 'Chin-Up', 'chin-up', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Chin-Up.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Chin-Up","force":"pull","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["lats"],"secondaryMuscles":["biceps","forearms","middle back"],"instructions":["Grab the pull-up bar with the palms facing your torso and a grip closer than the shoulder width.","As you have both arms extended in front of you holding the bar at the chosen grip width, keep your torso as straight as possible while creating a curvature on your lower back and sticking your chest out. This is your starting position. Tip: Keeping the torso as straight as possible maximizes biceps stimulation while minimizing back involvement.","As you breathe out, pull your torso up until your head is around the level of the pull-up bar. Concentrate on using the biceps muscles in order to perform the movement. Keep the elbows close to your body. Tip: The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.","After a second of squeezing the biceps in the contracted position, slowly lower your torso back to the starting position; when your arms are fully extended. Breathe in as you perform this portion of the movement.","Repeat this motion for the prescribed amount of repetitions."],"category":"strength","images":["Chin-Up/0.jpg","Chin-Up/1.jpg"],"id":"Chin-Up"}'),
('free-exercise-db', 'Chin_To_Chest_Stretch', 'chin-to-chest-stretch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Chin_To_Chest_Stretch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Chin To Chest Stretch","force":"static","level":"beginner","mechanic":null,"equipment":null,"primaryMuscles":["neck"],"secondaryMuscles":["traps"],"instructions":["Get into a seated position on the floor.","Place both hands at the rear of your head, fingers interlocked, thumbs pointing down and elbows pointing straight ahead. Slowly pull your head down to your chest. Hold for 20-30 seconds."],"category":"stretching","images":["Chin_To_Chest_Stretch/0.jpg","Chin_To_Chest_Stretch/1.jpg"],"id":"Chin_To_Chest_Stretch"}'),
('free-exercise-db', 'Circus_Bell', 'circus-bell', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Circus_Bell.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Circus Bell","force":"push","level":"expert","mechanic":"compound","equipment":"other","primaryMuscles":["shoulders"],"secondaryMuscles":["forearms","glutes","hamstrings","lower back","traps","triceps"],"instructions":["The circus bell is an oversized dumbbell with a thick handle. Begin with the dumbbell between your feet, and grip the handle with both hands.","Clean the dumbbell by extending through your hips and knees to deliver the implement to the desired shoulder, letting go with the extra hand.","Ensure that you get one of the dumbbell heads behind the shoulder to keep from being thrown off balance. To raise it overhead, dip by flexing the knees, and the drive upwards as you extend the dumbbell overhead, leaning slightly away from it as you do so.","Carefully guide the bell back to the floor, keeping it under control as much as possible. It is best to perform this event on a thick rubber mat to prevent damage to the floor."],"category":"strongman","images":["Circus_Bell/0.jpg","Circus_Bell/1.jpg"],"id":"Circus_Bell"}'),
('free-exercise-db', 'Clean', 'barbell-clean', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Clean.json', 'Unlicense', NULL, 'exact', 100.0, '{"name":"Clean","force":"pull","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["hamstrings"],"secondaryMuscles":["calves","forearms","glutes","lower back","quadriceps","shoulders","traps"],"instructions":["With a barbell on the floor close to the shins, take an overhand (or hook) grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.","","Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees.","Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended.","As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, aggressively pull yourself down, rotating your elbows under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery.","Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position."],"category":"olympic weightlifting","images":["Clean/0.jpg","Clean/1.jpg"],"id":"Clean"}'),
('free-exercise-db', 'Clean_Deadlift', 'barbell-clean-deadlift', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Clean_Deadlift.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Clean Deadlift","force":"pull","level":"beginner","mechanic":"compound","equipment":"barbell","primaryMuscles":["hamstrings"],"secondaryMuscles":["forearms","glutes","lower back","middle back","quadriceps","traps"],"instructions":["Begin standing with a barbell close to your shins. Your feet should be directly under your hips with your feet turned out slightly. Grip the bar with a double overhand grip or hook grip, about shoulder width apart. Squat down to the bar. Your spine should be in full extension, with a back angle that places your shoulders in front of the bar and your back as vertical as possible.","Begin by driving through the floor through the front of your heels. As the bar travels upward, maintain a constant back angle. Flare your knees out to the side to help keep them out of the bar''s path.","After the bar crosses the knees, complete the lift by driving the hips into the bar until your hips and knees are extended."],"category":"olympic weightlifting","images":["Clean_Deadlift/0.jpg","Clean_Deadlift/1.jpg"],"id":"Clean_Deadlift"}'),
('free-exercise-db', 'Clean_Pull', 'barbell-clean-pull', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Clean_Pull.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Clean Pull","force":"pull","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["forearms","glutes","hamstrings","lower back","traps"],"instructions":["With a barbell on the floor close to the shins, take an overhand or hook grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.","Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight and elbows out. Move the weight with control as you continue to above the knees.","Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended. Full extension should be violent and abrupt, and ensure that you do not prolong the extension for longer than necessary."],"category":"olympic weightlifting","images":["Clean_Pull/0.jpg","Clean_Pull/1.jpg"],"id":"Clean_Pull"}'),
('free-exercise-db', 'Clean_Shrug', 'barbell-clean-shrug', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Clean_Shrug.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Clean Shrug","force":"pull","level":"beginner","mechanic":"compound","equipment":"barbell","primaryMuscles":["traps"],"secondaryMuscles":["forearms","shoulders"],"instructions":["Begin with a shoulder width, double overhand or hook grip, with the bar hanging at the mid thigh position. Your back should be straight and inclined slightly forward.","Shrug your shoulders towards your ears. While this exercise can usually by loaded with heavier weight than a clean, avoid overloading to the point that the execution slows down."],"category":"olympic weightlifting","images":["Clean_Shrug/0.jpg","Clean_Shrug/1.jpg"],"id":"Clean_Shrug"}'),
('free-exercise-db', 'Clean_and_Jerk', 'barbell-clean-and-jerk', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Clean_and_Jerk.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Clean and Jerk","force":"push","level":"expert","mechanic":"compound","equipment":"barbell","primaryMuscles":["shoulders"],"secondaryMuscles":["abdominals","glutes","hamstrings","lower back","quadriceps","traps","triceps"],"instructions":["With a barbell on the floor close to the shins, take an overhand or hook grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.","Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees.","Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended.","As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, aggressively pull yourself down, rotating your elbows under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery.","Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position.","The second phase is the jerk, which raises the weight overhead. Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible.","Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders.","At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as possible. In the brief moment the feet are not actively driving against the platform, the athletes effort to push the bar up will drive them down. The feet should be split, with one foot forward, and one foot back. Receive the bar with the arms locked out overhead. Return to a standing position."],"category":"olympic weightlifting","images":["Clean_and_Jerk/0.jpg","Clean_and_Jerk/1.jpg"],"id":"Clean_and_Jerk"}'),
('free-exercise-db', 'Clean_and_Press', 'barbell-clean-and-press-2', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Clean_and_Press.json', 'Unlicense', NULL, 'exact', 100.0, '{"name":"Clean and Press","force":"push","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["shoulders"],"secondaryMuscles":["abdominals","calves","glutes","hamstrings","lower back","middle back","quadriceps","shoulders","traps","triceps"],"instructions":["Assume a shoulder-width stance, with knees inside the arms. Now while keeping the back flat, bend at the knees and hips so that you can grab the bar with the arms fully extended and a pronated grip that is slightly wider than shoulder width. Point the elbows out to sides. The bar should be close to the shins. Position the shoulders over or slightly ahead of the bar. Establish a flat back posture. This will be your starting position.","Begin to pull the bar by extending the knees. Move your hips forward and raise the shoulders at the same rate while keeping the angle of the back constant; continue to lift the bar straight up while keeping it close to your body.","As the bar passes the knee, extend at the ankles, knees, and hips forcefully, similar to a jumping motion. As you do so, continue to guide the bar with your hands, shrugging your shoulders and using the momentum from your movement to pull the bar as high as possible. The bar should travel close to your body, and you should keep your elbows out.","At maximum elevation, your feet should clear the floor and you should start to pull yourself under the bar. The mechanics of this could change slightly, depending on the weight used. You should descend into a squatting position as you pull yourself under the bar.","As the bar hits terminal height, rotate your elbows around and under the bar. Rack the bar across the front of the shoulders while keeping the torso erect and flexing the hips and knees to absorb the weight of the bar.","Stand to full height, holding the bar in the clean position.","Without moving your feet, press the bar overhead as you exhale. Lower the bar under control ."],"category":"strength","images":["Clean_and_Press/0.jpg","Clean_and_Press/1.jpg"],"id":"Clean_and_Press"}'),
('free-exercise-db', 'Clean_from_Blocks', 'barbell-clean-from-blocks', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Clean_from_Blocks.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Clean from Blocks","force":"pull","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings","shoulders","traps"],"instructions":["With a barbell on boxes or stands of the desired height, take an overhand or hook grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.","Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight with the elbows pointed out.","As full extension is achieved, transition into the receiving position by aggressively shrugging and flexing the arms with the elbows up and out. Aggressively pull yourself down, rotating your elbows under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery.","Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position. Return the weight to the boxes for the next rep."],"category":"olympic weightlifting","images":["Clean_from_Blocks/0.jpg","Clean_from_Blocks/1.jpg"],"id":"Clean_from_Blocks"}'),
('free-exercise-db', 'Clock_Push-Up', 'clock-push-up', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Clock_Push-Up.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Clock Push-Up","force":"push","level":"intermediate","mechanic":"compound","equipment":"body only","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["Move into a prone position on the floor, supporting your weight on your hands and toes.","Your arms should be fully extended with the hands around shoulder width. Keep your body straight throughout the movement. This will be your starting position.","Descend by flexing at the elbow, lowering your chest toward the ground.","At the bottom, reverse the motion by pushing yourself up through elbow extension as quickly as possible until you are air borne. Aim to \"jump\" 12-18 inches to one side.","As you accelerate up, move your outside foot away from your direction of travel. Leaving the ground, shift your body about 30 degrees for the next repetition.","Return to the starting position and repeat the exercise, working all the way around until you are back where you started."],"category":"strength","images":["Clock_Push-Up/0.jpg","Clock_Push-Up/1.jpg"],"id":"Clock_Push-Up"}'),
('free-exercise-db', 'Close-Grip_Barbell_Bench_Press', 'barbell-bench-press-narrow-grip', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Close-Grip_Barbell_Bench_Press.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Close-Grip Barbell Bench Press","force":"push","level":"beginner","mechanic":"compound","equipment":"barbell","primaryMuscles":["triceps"],"secondaryMuscles":["chest","shoulders"],"instructions":["Lie back on a flat bench. Using a close grip (around shoulder width), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.","As you breathe in, come down slowly until you feel the bar on your middle chest. Tip: Make sure that - as opposed to a regular bench press - you keep the elbows close to the torso at all times in order to maximize triceps involvement.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your triceps muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the bar back in the rack."],"category":"strength","images":["Close-Grip_Barbell_Bench_Press/0.jpg","Close-Grip_Barbell_Bench_Press/1.jpg"],"id":"Close-Grip_Barbell_Bench_Press"}'),
('free-exercise-db', 'Close-Grip_Dumbbell_Press', 'dumbbell-close-grip-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Close-Grip_Dumbbell_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Close-Grip Dumbbell Press","force":"push","level":"beginner","mechanic":"compound","equipment":"dumbbell","primaryMuscles":["triceps"],"secondaryMuscles":["chest","shoulders"],"instructions":["Place a dumbbell standing up on a flat bench.","Ensuring that the dumbbell stays securely placed at the top of the bench, lie perpendicular to the bench with only your shoulders lying on the surface. Hips should be below the bench and your legs bent with your feet firmly on the floor.","Grasp the dumbbell with both hands and hold it straight over your chest at arm''s length. Both palms should be pressing against the underside of the sides of the dumbbell. This will be your starting position.","Initiate the movement by lowering the dumbbell to your chest.","Return to the starting position by extending the elbows."],"category":"strength","images":["Close-Grip_Dumbbell_Press/0.jpg","Close-Grip_Dumbbell_Press/1.jpg"],"id":"Close-Grip_Dumbbell_Press"}'),
('free-exercise-db', 'Close-Grip_EZ-Bar_Curl_with_Band', 'ez-bar-band-close-grip-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Close-Grip_EZ-Bar_Curl_with_Band.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Close-Grip EZ-Bar Curl with Band","force":"pull","level":"beginner","mechanic":"isolation","equipment":"e-z curl bar","primaryMuscles":["biceps"],"secondaryMuscles":["forearms"],"instructions":["Attach a band to each end of the bar. Take the bar, placing a foot on the middle of the band. Stand upright with a narrow, supinated grip on the EZ bar. The elbows should be close to the torso. This will be your starting position.","While keeping the upper arms in place, flex the elbows to execute the curl. Exhale as the weight is lifted.","Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.","Slowly begin to bring the bar back to starting position as your breathe in.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Close-Grip_EZ-Bar_Curl_with_Band/0.jpg","Close-Grip_EZ-Bar_Curl_with_Band/1.jpg"],"id":"Close-Grip_EZ-Bar_Curl_with_Band"}'),
('free-exercise-db', 'Close-Grip_EZ-Bar_Press', 'ez-bar-close-grip-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Close-Grip_EZ-Bar_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Close-Grip EZ-Bar Press","force":"push","level":"beginner","mechanic":"compound","equipment":"e-z curl bar","primaryMuscles":["triceps"],"secondaryMuscles":["chest","shoulders"],"instructions":["Lie on a flat bench with an EZ bar loaded to an appropriate weight.","Using a narrow grip lift the bar and hold it straight over your torso with your elbows in. The arms should be perpendicular to the floor. This will be your starting position.","Now lower the bar down to your lower chest as you breathe in. Keep the elbows in as you perform this movement.","Using the triceps to push the bar back up, press it back to the starting position by extending the elbows as you exhale.","Repeat."],"category":"strength","images":["Close-Grip_EZ-Bar_Press/0.jpg","Close-Grip_EZ-Bar_Press/1.jpg"],"id":"Close-Grip_EZ-Bar_Press"}'),
('free-exercise-db', 'Close-Grip_EZ_Bar_Curl', 'ez-bar-close-grip-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Close-Grip_EZ_Bar_Curl.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Close-Grip EZ Bar Curl","force":"pull","level":"beginner","mechanic":"isolation","equipment":"barbell","primaryMuscles":["biceps"],"secondaryMuscles":["forearms"],"instructions":["Stand up with your torso upright while holding an E-Z Curl Bar at the closer inner handle. The palm of your hands should be facing forward and they should be slightly tilted inwards due to the shape of the bar. The elbows should be close to the torso. This will be your starting position.","While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move.","Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.","Slowly begin to bring the bar back to starting position as your breathe in.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Close-Grip_EZ_Bar_Curl/0.jpg","Close-Grip_EZ_Bar_Curl/1.jpg"],"id":"Close-Grip_EZ_Bar_Curl"}'),
('free-exercise-db', 'Close-Grip_Front_Lat_Pulldown', 'cable-close-grip-front-lat-pulldown', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Close-Grip_Front_Lat_Pulldown.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Close-Grip Front Lat Pulldown","force":"pull","level":"beginner","mechanic":"compound","equipment":"cable","primaryMuscles":["lats"],"secondaryMuscles":["biceps","middle back","shoulders"],"instructions":["Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.","Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.","As you have both arms extended in front of you - while holding the bar at the chosen grip width - bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.","As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary (only the arms should move). The forearms should do no other work except for holding the bar; therefore do not try to pull the bar down using the forearms.","After a second in the contracted position, while squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.","6. Repeat this motion for the prescribed amount of repetitions."],"category":"strength","images":["Close-Grip_Front_Lat_Pulldown/0.jpg","Close-Grip_Front_Lat_Pulldown/1.jpg"],"id":"Close-Grip_Front_Lat_Pulldown"}'),
('free-exercise-db', 'Close-Grip_Push-Up_off_of_a_Dumbbell', 'dumbbell-close-grip-push-up-off', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Close-Grip_Push-Up_off_of_a_Dumbbell.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Close-Grip Push-Up off of a Dumbbell","force":"push","level":"intermediate","mechanic":"compound","equipment":"body only","primaryMuscles":["triceps"],"secondaryMuscles":["abdominals","chest","shoulders"],"instructions":["Lie on the floor and place your hands on an upright dumbbell. Supporting your weight on your toes and hands, keep your torso rigid and your elbows in with your arms straight. This will be your starting position.","Lower your body, allowing the elbows to flex while you inhale. Keep your body straight, not allowing your hips to rise or sag.","Press yourself back up to the starting position by extending the elbows. Breathe out as you perform this step.","After a pause at the contracted position, repeat the movement for the prescribed amount of repetitions."],"category":"strength","images":["Close-Grip_Push-Up_off_of_a_Dumbbell/0.jpg","Close-Grip_Push-Up_off_of_a_Dumbbell/1.jpg"],"id":"Close-Grip_Push-Up_off_of_a_Dumbbell"}'),
('free-exercise-db', 'Close-Grip_Standing_Barbell_Curl', 'barbell-close-grip-standing-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Close-Grip_Standing_Barbell_Curl.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Close-Grip Standing Barbell Curl","force":"pull","level":"beginner","mechanic":"isolation","equipment":"barbell","primaryMuscles":["biceps"],"secondaryMuscles":["forearms"],"instructions":["Hold a barbell with both hands, palms up and a few inches apart.","Stand with your torso straight and your head up. Your feet should be about shoulder width and your elbows close to your torso. This will be your starting position. Tip: You will keep your upper arms and elbows stationary throughout the movement.","Curl the bar up in a semicircular motion until the forearms touch your biceps. Exhale as you perform this portion of the movement and contract your biceps hard for a second at the top. Tip: Avoid bending the back or using swinging motions as you lift the weight. Only the forearms should move.","Slowly go back down to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Close-Grip_Standing_Barbell_Curl/0.jpg","Close-Grip_Standing_Barbell_Curl/1.jpg"],"id":"Close-Grip_Standing_Barbell_Curl"}'),
('free-exercise-db', 'Cocoons', 'cocoons', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Cocoons.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Cocoons","force":"pull","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Begin by lying on your back on the ground. Your legs should be straight and your arms extended behind your head. This will be your starting position.","To perform the movement, tuck the knees toward your chest, rotating your pelvis to lift your glutes from the floor. As you do so, flex the spine, bringing your arms back over your head to perform a simultaneous crunch motion.","After a brief pause, return to the starting position."],"category":"strength","images":["Cocoons/0.jpg","Cocoons/1.jpg"],"id":"Cocoons"}'),
('free-exercise-db', 'Conans_Wheel', 'conans-wheel', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Conans_Wheel.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Conan''s Wheel","force":null,"level":"intermediate","mechanic":"compound","equipment":"other","primaryMuscles":["quadriceps"],"secondaryMuscles":["abdominals","biceps","calves","forearms","lower back","shoulders","traps"],"instructions":["With the weight loaded, take a zurcher hold on the end of the implement. Place the bar in the crook of the elbow and hold onto your wrist. Try to keep the weight off of the forearms.","Begin by lifting the weight from the ground. Keep a tight, upright posture as you being to walk, taking short, fast steps. Look up and away as you turn in a circle. Do not hold your breath during the event. Continue walking until you complete one or more complete turns."],"category":"strongman","images":["Conans_Wheel/0.jpg","Conans_Wheel/1.jpg"],"id":"Conans_Wheel"}'),
('free-exercise-db', 'Concentration_Curls', 'dumbbell-concentration-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Concentration_Curls.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Concentration Curls","force":"pull","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["biceps"],"secondaryMuscles":["forearms"],"instructions":["Sit down on a flat bench with one dumbbell in front of you between your legs. Your legs should be spread with your knees bent and feet on the floor.","Use your right arm to pick the dumbbell up. Place the back of your right upper arm on the top of your inner right thigh. Rotate the palm of your hand until it is facing forward away from your thigh. Tip: Your arm should be extended and the dumbbell should be above the floor. This will be your starting position.","While holding the upper arm stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Tip: At the top of the movement make sure that the little finger of your arm is higher than your thumb. This guarantees a good contraction. Hold the contracted position for a second as you squeeze the biceps.","Slowly begin to bring the dumbbells back to starting position as your breathe in. Caution: Avoid swinging motions at any time.","Repeat for the recommended amount of repetitions. Then repeat the movement with the left arm."],"category":"strength","images":["Concentration_Curls/0.jpg","Concentration_Curls/1.jpg"],"id":"Concentration_Curls"}'),
('free-exercise-db', 'Cross-Body_Crunch', 'cross-body-crunch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Cross-Body_Crunch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Cross-Body Crunch","force":"pull","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Lie flat on your back and bend your knees about 60 degrees.","Keep your feet flat on the floor and place your hands loosely behind your head. This will be your starting position.","Now curl up and bring your right elbow and shoulder across your body while bring your left knee in toward your left shoulder at the same time. Reach with your elbow and try to touch your knee. Exhale as you perform this movement. Tip: Try to bring your shoulder up towards your knee rather than just your elbow and remember that the key is to contract the abs as you perform the movement; not just to move the elbow.","Now go back down to the starting position as you inhale and repeat with the left elbow and the right knee.","Continue alternating in this manner until all prescribed repetitions are done."],"category":"strength","images":["Cross-Body_Crunch/0.jpg","Cross-Body_Crunch/1.jpg"],"id":"Cross-Body_Crunch"}'),
('free-exercise-db', 'Cross_Body_Hammer_Curl', 'dumbbell-cross-body-hammer-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Cross_Body_Hammer_Curl.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Cross Body Hammer Curl","force":"pull","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["biceps"],"secondaryMuscles":["forearms"],"instructions":["Stand up straight with a dumbbell in each hand. Your hands should be down at your side with your palms facing in.","While keeping your palms facing in and without twisting your arm, curl the dumbbell of the right arm up towards your left shoulder as you exhale. Touch the top of the dumbbell to your shoulder and hold the contraction for a second.","Slowly lower the dumbbell along the same path as you inhale and then repeat the same movement for the left arm.","Continue alternating in this fashion until the recommended amount of repetitions is performed for each arm."],"category":"strength","images":["Cross_Body_Hammer_Curl/0.jpg","Cross_Body_Hammer_Curl/1.jpg"],"id":"Cross_Body_Hammer_Curl"}'),
('free-exercise-db', 'Cross_Over_-_With_Bands', 'band-cross-over', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Cross_Over_-_With_Bands.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Cross Over - With Bands","force":"push","level":"beginner","mechanic":"compound","equipment":"bands","primaryMuscles":["chest"],"secondaryMuscles":["biceps","shoulders"],"instructions":["Secure an exercise band around a stationary post.","While facing away from the post, grab the handles on both ends of the band and step forward enough to create tension on the band.","Raise your arms to the sides, parallel to the floor, perpendicular to your torso (your torso and the arms should resemble the letter \"T\") and with the palms facing forward. Have them extended with a slight bend at the elbows. This will be your starting position.","While keeping your arms straight, bring them across your chest in a semicircular motion to the front as you exhale and flex your pecs. Hold the contraction for a second.","Slowly return to the starting position as you inhale.","Perform for the recommended amount of repetitions."],"category":"strength","images":["Cross_Over_-_With_Bands/0.jpg","Cross_Over_-_With_Bands/1.jpg"],"id":"Cross_Over_-_With_Bands"}'),
('free-exercise-db', 'Crossover_Reverse_Lunge', 'crossover-reverse-lunge', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Crossover_Reverse_Lunge.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Crossover Reverse Lunge","force":"pull","level":"intermediate","mechanic":null,"equipment":null,"primaryMuscles":["lower back"],"secondaryMuscles":["abdominals","abductors","glutes","hamstrings","quadriceps"],"instructions":["Stand with your feet shoulder width apart. This will be your starting position.","Perform a rear lunge by stepping back with one foot and flexing the hips and front knee. As you do so, rotate your torso across the front leg.","After a brief pause, return to the starting position and repeat on the other side, continuing in an alternating fashion."],"category":"stretching","images":["Crossover_Reverse_Lunge/0.jpg","Crossover_Reverse_Lunge/1.jpg"],"id":"Crossover_Reverse_Lunge"}'),
('free-exercise-db', 'Crucifix', 'crucifix', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Crucifix.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Crucifix","force":"static","level":"beginner","mechanic":"isolation","equipment":"other","primaryMuscles":["shoulders"],"secondaryMuscles":["forearms"],"instructions":["In the crucifix, you statically hold weights out to the side for time. While the event can be practiced using dumbbells, it is best to practice with one of the various implements used, such as axes and hammers, as it feels different.","Begin standing, and raise your arms out to the side holding the implements. Your arms should be parallel to the ground. In competition, judges or sensors are used to let you know when you break parallel. Hold for as long as you can. Typically, the weights should be heavy enough that you fail in 30-60 seconds."],"category":"strongman","images":["Crucifix/0.jpg","Crucifix/1.jpg"],"id":"Crucifix"}'),
('free-exercise-db', 'Crunch_-_Hands_Overhead', 'crunch-hands-overhead', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Crunch_-_Hands_Overhead.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Crunch - Hands Overhead","force":"pull","level":"beginner","mechanic":"isolation","equipment":"body only","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Lie on the floor with your back flat and knees bent with around a 60-degree angle between the hamstrings and the calves.","Keep your feet flat on the floor and stretch your arms overhead with your palms crossed. This will be your starting position.","Curl your upper body forward and bring your shoulder blades just off the floor. At all times, keep your arms aligned with your head, neck and shoulder. Don''t move them forward from that position. Exhale as you perform this portion of the movement and hold the contraction for a second.","Slowly lower down to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Crunch_-_Hands_Overhead/0.jpg","Crunch_-_Hands_Overhead/1.jpg"],"id":"Crunch_-_Hands_Overhead"}'),
('free-exercise-db', 'Crunch_-_Legs_On_Exercise_Ball', 'exercise-ball-crunch-legs', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Crunch_-_Legs_On_Exercise_Ball.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Crunch - Legs On Exercise Ball","force":"pull","level":"beginner","mechanic":"isolation","equipment":"body only","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Lie flat on your back with your feet resting on an exercise ball and your knees bent at a 90 degree angle.","Place your feet three to four inches apart and point your toes inward so they touch.","Place your hands lightly on either side of your head keeping your elbows in. Tip: Don''t lock your fingers behind your head.","Push the small of your back down in the floor in order to better isolate your abdominal muscles. This will be your starting position.","Begin to roll your shoulders off the floor and continue to push down as hard as you can with your lower back. Your shoulders should come up off the floor only about four inches, and your lower back should remain on the floor. Breathe out as you execute this portion of the movement. Squeeze your abdominals hard at the top of the contraction and hold for a second. Tip: Focus on a slow, controlled movement. Refrain from using momentum at any time.","Slowly go back down to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Crunch_-_Legs_On_Exercise_Ball/0.jpg","Crunch_-_Legs_On_Exercise_Ball/1.jpg"],"id":"Crunch_-_Legs_On_Exercise_Ball"}'),
('free-exercise-db', 'Crunches', 'crunch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Crunches.json', 'Unlicense', NULL, 'exact', 100.0, '{"name":"Crunches","force":"pull","level":"beginner","mechanic":"isolation","equipment":"body only","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Lie flat on your back with your feet flat on the ground, or resting on a bench with your knees bent at a 90 degree angle. If you are resting your feet on a bench, place them three to four inches apart and point your toes inward so they touch.","Now place your hands lightly on either side of your head keeping your elbows in. Tip: Don''t lock your fingers behind your head.","While pushing the small of your back down in the floor to better isolate your abdominal muscles, begin to roll your shoulders off the floor.","Continue to push down as hard as you can with your lower back as you contract your abdominals and exhale. Your shoulders should come up off the floor only about four inches, and your lower back should remain on the floor. At the top of the movement, contract your abdominals hard and keep the contraction for a second. Tip: Focus on slow, controlled movement - don''t cheat yourself by using momentum.","After the one second contraction, begin to come down slowly again to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Crunches/0.jpg","Crunches/1.jpg"],"id":"Crunches"}'),
('free-exercise-db', 'Cuban_Press', 'dumbbell-cuban-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Cuban_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Cuban Press","force":"push","level":"intermediate","mechanic":"compound","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":["traps"],"instructions":["Take a dumbbell in each hand with a pronated grip in a standing position. Raise your upper arms so that they are parallel to the floor, allowing your lower arms to hang in the \"scarecrow\" position. This will be your starting position.","To initiate the movement, externally rotate the shoulders to move the upper arm 180 degrees. Keep the upper arms in place, rotating the upper arms until the wrists are directly above the elbows, the forearms perpendicular to the floor.","Now press the dumbbells by extending at the elbows, straightening your arms overhead.","Return to the starting position as you breathe in by reversing the steps.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Cuban_Press/0.jpg","Cuban_Press/1.jpg"],"id":"Cuban_Press"}'),
('free-exercise-db', 'Dancers_Stretch', 'dancers-stretch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Dancers_Stretch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Dancer''s Stretch","force":"static","level":"beginner","mechanic":null,"equipment":null,"primaryMuscles":["lower back"],"secondaryMuscles":["abductors","glutes"],"instructions":["Sit up on the floor.","Cross your right leg over your left, keeping the knee bent. Your left leg is straight and down on the floor.","Place your left arm on your right leg and your right hand on the floor.","Rotate your upper body to the right, and hold for 10-20 seconds. Switch sides."],"category":"stretching","images":["Dancers_Stretch/0.jpg","Dancers_Stretch/1.jpg"],"id":"Dancers_Stretch"}'),
('free-exercise-db', 'Dead_Bug', 'dead-bug-2', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Dead_Bug.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Dead Bug","force":"pull","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Begin lying on your back with your hands extended above you toward the ceiling.","Bring your feet, knees, and hips up to 90 degrees.","Exhale hard to bring your ribcage down and flatten your back onto the floor, rotating your pelvis up and squeezing your glutes. Hold this position throughout the movement. This will be your starting position.","Initiate the exercise by extending one leg, straightening the knee and hip to bring the leg just above the ground.","Maintain the position of your lumbar and pelvis as you perform the movement, as your back is going to want to arch.","Stay tight and return the working leg to the starting position.","Repeat on the opposite side, alternating until the set is complete."],"category":"strength","images":["Dead_Bug/0.jpg","Dead_Bug/1.jpg"],"id":"Dead_Bug"}'),
('free-exercise-db', 'Deadlift_with_Bands', 'band-deadlift', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Deadlift_with_Bands.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Deadlift with Bands","force":"pull","level":"expert","mechanic":"compound","equipment":"barbell","primaryMuscles":["lower back"],"secondaryMuscles":["forearms","glutes","hamstrings","middle back","quadriceps","traps"],"instructions":["To deadlift with short bands, simply loop them over the bar before you start, and step into them to set up. For long bands, they will need to be anchored to a secure base, such as heavy dumbbells or a rack.","With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.","Lower the bar by bending at the hips and guiding it to the floor."],"category":"powerlifting","images":["Deadlift_with_Bands/0.jpg","Deadlift_with_Bands/1.jpg"],"id":"Deadlift_with_Bands"}'),
('free-exercise-db', 'Deadlift_with_Chains', 'barbell-deadlift-chains', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Deadlift_with_Chains.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Deadlift with Chains","force":"pull","level":"expert","mechanic":"compound","equipment":"barbell","primaryMuscles":["lower back"],"secondaryMuscles":["forearms","glutes","hamstrings","middle back","quadriceps","traps"],"instructions":["You can attach the chains to the sleeves of the bar, or just drape the middle over the bar so there is a greater weight increase as you lift.","Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an overhand grip or an over/under grip on heavier sets. With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar.","Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.","Lower the bar by bending at the hips and guiding it to the floor."],"category":"powerlifting","images":["Deadlift_with_Chains/0.jpg","Deadlift_with_Chains/1.jpg"],"id":"Deadlift_with_Chains"}'),
('free-exercise-db', 'Decline_Barbell_Bench_Press', 'barbell-decline-bench-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Decline_Barbell_Bench_Press.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Decline Barbell Bench Press","force":"push","level":"beginner","mechanic":"compound","equipment":"barbell","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["Secure your legs at the end of the decline bench and slowly lay down on the bench.","Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. The arms should be perpendicular to the floor. This will be your starting position. Tip: In order to protect your rotator cuff, it is best if you have a spotter help you lift the barbell off the rack.","As you breathe in, come down slowly until you feel the bar on your lower chest.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up).","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the bar back in the rack."],"category":"strength","images":["Decline_Barbell_Bench_Press/0.jpg","Decline_Barbell_Bench_Press/1.jpg"],"id":"Decline_Barbell_Bench_Press"}'),
('free-exercise-db', 'Decline_Close-Grip_Bench_To_Skull_Crusher', 'barbell-decline-close-grip-bench-to-skull-crusher', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Decline_Close-Grip_Bench_To_Skull_Crusher.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Decline Close-Grip Bench To Skull Crusher","force":"push","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["triceps"],"secondaryMuscles":["chest","shoulders"],"instructions":["Secure your legs at the end of the decline bench and slowly lay down on the bench.","Using a close grip (a grip that is slightly less than shoulder width), lift the bar from the rack and hold it straight over you with your arms locked and elbows in. The arms should be perpendicular to the floor. This will be your starting position. Tip: In order to protect your rotator cuff, it is best if you have a spotter help you lift the barbell off the rack.","Now lower the bar down to your lower chest as you breathe in. Keep the elbows in as you perform this movement.","Using the triceps to push the bar back up, press it back to the starting position as you exhale.","As you breathe in and you keep the upper arms stationary, bring the bar down slowly by moving your forearms in a semicircular motion towards you until you feel the bar slightly touch your forehead. Breathe in as you perform this portion of the movement.","Lift the bar back to the starting position by contracting the triceps and exhaling.","Repeat steps 3-6 until the recommended amount of repetitions is performed."],"category":"strength","images":["Decline_Close-Grip_Bench_To_Skull_Crusher/0.jpg","Decline_Close-Grip_Bench_To_Skull_Crusher/1.jpg"],"id":"Decline_Close-Grip_Bench_To_Skull_Crusher"}'),
('free-exercise-db', 'Decline_Crunch', 'decline-crunch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Decline_Crunch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Decline Crunch","force":"pull","level":"intermediate","mechanic":"isolation","equipment":"body only","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Secure your legs at the end of the decline bench and lie down.","Now place your hands lightly on either side of your head keeping your elbows in. Tip: Don''t lock your fingers behind your head.","While pushing the small of your back down in the bench to better isolate your abdominal muscles, begin to roll your shoulders off it.","Continue to push down as hard as you can with your lower back as you contract your abdominals and exhale. Your shoulders should come up off the bench only about four inches, and your lower back should remain on the bench. At the top of the movement, contract your abdominals hard and keep the contraction for a second. Tip: Focus on slow, controlled movement - don''t cheat yourself by using momentum.","After the one second contraction, begin to come down slowly again to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Decline_Crunch/0.jpg","Decline_Crunch/1.jpg"],"id":"Decline_Crunch"}'),
('free-exercise-db', 'Decline_Dumbbell_Bench_Press', 'dumbbell-decline-bench-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Decline_Dumbbell_Bench_Press.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Decline Dumbbell Bench Press","force":"push","level":"beginner","mechanic":"compound","equipment":"dumbbell","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.","Once you are laying down, move the dumbbells in front of you at shoulder width.","Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.","Bring down the weights slowly to your side as you breathe out. Keep full control of the dumbbells at all times. Tip: Throughout the motion, the forearms should always be perpendicular to the floor.","As you breathe out, push the dumbbells up using your pectoral muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up..","Repeat the movement for the prescribed amount of repetitions of your training program."],"category":"strength","images":["Decline_Dumbbell_Bench_Press/0.jpg","Decline_Dumbbell_Bench_Press/1.jpg"],"id":"Decline_Dumbbell_Bench_Press"}'),
('free-exercise-db', 'Decline_Dumbbell_Flyes', 'dumbbell-fly-decline-bench', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Decline_Dumbbell_Flyes.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Decline Dumbbell Flyes","force":"push","level":"beginner","mechanic":"compound","equipment":"dumbbell","primaryMuscles":["chest"],"secondaryMuscles":[],"instructions":["Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.","Once you are laying down, move the dumbbells in front of you at shoulder width. The palms of the hands should be facing each other and the arms should be perpendicular to the floor and fully extended. This will be your starting position.","With a slight bend on your elbows in order to prevent stress at the biceps tendon, lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms should remain stationary; the movement should only occur at the shoulder joint.","Return your arms back to the starting position as you squeeze your chest muscles and breathe out. Tip: Make sure to use the same arc of motion used to lower the weights.","Hold for a second at the contracted position and repeat the movement for the prescribed amount of repetitions."],"category":"strength","images":["Decline_Dumbbell_Flyes/0.jpg","Decline_Dumbbell_Flyes/1.jpg"],"id":"Decline_Dumbbell_Flyes"}'),
('free-exercise-db', 'Decline_Dumbbell_Triceps_Extension', 'dumbbell-decline-triceps-extension', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Decline_Dumbbell_Triceps_Extension.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Decline Dumbbell Triceps Extension","force":"push","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["triceps"],"secondaryMuscles":[],"instructions":["Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.","Once you are laying down, move the dumbbells in front of you at shoulder width. The palms of the hands should be facing each other and the arms should be perpendicular to the floor and fully extended. This will be your starting position.","As you breathe in and you keep the upper arms stationary (and elbows in), bring the dumbbells down slowly by moving your forearms in a semicircular motion towards you until your thumbs are next to your ears. Breathe in as you perform this portion of the movement.","Lift the dumbbells back to the starting position by contracting the triceps and exhaling.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Decline_Dumbbell_Triceps_Extension/0.jpg","Decline_Dumbbell_Triceps_Extension/1.jpg"],"id":"Decline_Dumbbell_Triceps_Extension"}');
INSERT INTO source_records (source_id, source_record_id, exercise_id, source_url, license, author, match_method, match_score, raw_json) VALUES
('free-exercise-db', 'Decline_EZ_Bar_Triceps_Extension', 'ez-bar-decline-triceps-extension', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Decline_EZ_Bar_Triceps_Extension.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Decline EZ Bar Triceps Extension","force":"push","level":"beginner","mechanic":"isolation","equipment":"barbell","primaryMuscles":["triceps"],"secondaryMuscles":[],"instructions":["Secure your legs at the end of the decline bench and slowly lay down on the bench.","Using a close grip (a grip that is slightly less than shoulder width), lift the EZ bar from the rack and hold it straight over you with your arms locked and elbows in. The arms should be perpendicular to the floor. This will be your starting position. Tip: In order to protect your rotator cuff, it is best if you have a spotter help you lift the barbell off the rack.","As you breathe in and you keep the upper arms stationary, bring the bar down slowly by moving your forearms in a semicircular motion towards you until you feel the bar slightly touch your forehead. Breathe in as you perform this portion of the movement.","Lift the bar back to the starting position by contracting the triceps and exhaling.","Repeat until the recommended amount of repetitions is performed."],"category":"strength","images":["Decline_EZ_Bar_Triceps_Extension/0.jpg","Decline_EZ_Bar_Triceps_Extension/1.jpg"],"id":"Decline_EZ_Bar_Triceps_Extension"}'),
('free-exercise-db', 'Decline_Oblique_Crunch', 'decline-oblique-crunch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Decline_Oblique_Crunch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Decline Oblique Crunch","force":"pull","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Secure your legs at the end of the decline bench and slowly lay down on the bench.","Raise your upper body off the bench until your torso is about 35-45 degrees if measured from the floor.","Put one hand beside your head and the other on your thigh. This will be your starting position.","Raise your upper body slowly from the starting position while turning your torso to the left. Continue crunching up as you exhale until your right elbow touches your left knee. Hold this contracted position for a second. Tip: Focus on keeping your abs tight and keeping the movement slow and controlled.","Lower your body back down slowly to the starting position as you inhale.","After completing one set on the right for the recommended amount of repetitions, switch to your left side. Tip: Focus on really twisting your torso and feeling the contraction when you are in the up position."],"category":"strength","images":["Decline_Oblique_Crunch/0.jpg","Decline_Oblique_Crunch/1.jpg"],"id":"Decline_Oblique_Crunch"}'),
('free-exercise-db', 'Decline_Push-Up', 'decline-push-up-2', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Decline_Push-Up.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Decline Push-Up","force":"push","level":"beginner","mechanic":"compound","equipment":null,"primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length. Move your feet up to a box or bench. This will be your starting position.","Next, lower yourself downward until your chest almost touches the floor as you inhale.","Now breathe out and press your upper body back up to the starting position while squeezing your chest.","After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed."],"category":"strength","images":["Decline_Push-Up/0.jpg","Decline_Push-Up/1.jpg"],"id":"Decline_Push-Up"}'),
('free-exercise-db', 'Decline_Reverse_Crunch', 'decline-reverse-crunch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Decline_Reverse_Crunch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Decline Reverse Crunch","force":"pull","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Lie on your back on a decline bench and hold on to the top of the bench with both hands. Don''t let your body slip down from this position.","Hold your legs parallel to the floor using your abs to hold them there while keeping your knees and feet together. Tip: Your legs should be fully extended with a slight bend on the knee. This will be your starting position.","While exhaling, move your legs towards the torso as you roll your pelvis backwards and you raise your hips off the bench. At the end of this movement your knees will be touching your chest.","Hold the contraction for a second and move your legs back to the starting position while inhaling.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Decline_Reverse_Crunch/0.jpg","Decline_Reverse_Crunch/1.jpg"],"id":"Decline_Reverse_Crunch"}'),
('free-exercise-db', 'Decline_Smith_Press', 'smith-machine-decline-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Decline_Smith_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Decline Smith Press","force":"push","level":"beginner","mechanic":"compound","equipment":"machine","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["Place a decline bench underneath the Smith machine. Now place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Using a pronated grip that is wider than shoulder width, unlock the bar from the rack and hold it straight over you with your arms extended. This will be your starting position.","As you inhale, lower the bar under control by allowing the elbows to flex, lightly contacting the torso.","After a brief pause, bring the bar back to the starting position by extending the elbows, exhaling as you do so.","Repeat the movement for the prescribed amount of repetitions.","When the set is complete, lock the bar back in the rack."],"category":"strength","images":["Decline_Smith_Press/0.jpg","Decline_Smith_Press/1.jpg"],"id":"Decline_Smith_Press"}'),
('free-exercise-db', 'Deficit_Deadlift', 'barbell-deficit-deadlift', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Deficit_Deadlift.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Deficit Deadlift","force":"pull","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["lower back"],"secondaryMuscles":["forearms","glutes","hamstrings","middle back","quadriceps","traps"],"instructions":["Begin by having a platform or weight plates that you can stand on, usually 1-3 inches in height. Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an overhand grip or an over/under grip on heavier sets.","With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.","Lower the bar by bending at the hips and guiding it to the floor."],"category":"powerlifting","images":["Deficit_Deadlift/0.jpg","Deficit_Deadlift/1.jpg"],"id":"Deficit_Deadlift"}'),
('free-exercise-db', 'Depth_Jump_Leap', 'depth-jump-leap', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Depth_Jump_Leap.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Depth Jump Leap","force":"push","level":"beginner","mechanic":"compound","equipment":"other","primaryMuscles":["quadriceps"],"secondaryMuscles":["abductors","adductors","calves","glutes","hamstrings"],"instructions":["For this drill you will need two boxes or benches, one 12 to 16 inches high and the other 22 to 26 inches high.","Stand on one of the two boxes with arms at the sides; feet should be together and slightly off the edge as in the depth jump. Place the other box approximately two or three feet in front of and facing the performer.","Begin by dropping off the initial box, landing and simultaneously taking off with both feet.","Rebound by driving upward and outward as intensely as possible, using the arms and full extension of the body to jump onto the higher box. Again, allow the legs to absorb the impact."],"category":"plyometrics","images":["Depth_Jump_Leap/0.jpg","Depth_Jump_Leap/1.jpg"],"id":"Depth_Jump_Leap"}'),
('free-exercise-db', 'Dip_Machine', 'machine-dip', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Dip_Machine.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Dip Machine","force":"push","level":"beginner","mechanic":"compound","equipment":"machine","primaryMuscles":["triceps"],"secondaryMuscles":["chest","shoulders"],"instructions":["Sit securely in a dip machine, select the weight and firmly grasp the handles.","Now keep your elbows in at your sides in order to place emphasis on the triceps. The elbows should be bent at a 90 degree angle.","As you contract the triceps, extend your arms downwards as you exhale. Tip: At the bottom of the movement, focus on keeping a little bend in your arms to keep tension on the triceps muscle.","Now slowly let your arms come back up to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Dip_Machine/0.jpg","Dip_Machine/1.jpg"],"id":"Dip_Machine"}'),
('free-exercise-db', 'Dips_-_Chest_Version', 'dip-chest-version', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Dips_-_Chest_Version.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Dips - Chest Version","force":"push","level":"intermediate","mechanic":"compound","equipment":"other","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["For this exercise you will need access to parallel bars. To get yourself into the starting position, hold your body at arms length (arms locked) above the bars.","While breathing in, lower yourself slowly with your torso leaning forward around 30 degrees or so and your elbows flared out slightly until you feel a slight stretch in the chest.","Once you feel the stretch, use your chest to bring your body back to the starting position as you breathe out. Tip: Remember to squeeze the chest at the top of the movement for a second.","Repeat the movement for the prescribed amount of repetitions."],"category":"strength","images":["Dips_-_Chest_Version/0.jpg","Dips_-_Chest_Version/1.jpg"],"id":"Dips_-_Chest_Version"}'),
('free-exercise-db', 'Dips_-_Triceps_Version', 'dip-triceps-version', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Dips_-_Triceps_Version.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Dips - Triceps Version","force":"push","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["triceps"],"secondaryMuscles":["chest","shoulders"],"instructions":["To get into the starting position, hold your body at arm''s length with your arms nearly locked above the bars.","Now, inhale and slowly lower yourself downward. Your torso should remain upright and your elbows should stay close to your body. This helps to better focus on tricep involvement. Lower yourself until there is a 90 degree angle formed between the upper arm and forearm.","Then, exhale and push your torso back up using your triceps to bring your body back to the starting position.","Repeat the movement for the prescribed amount of repetitions."],"category":"strength","images":["Dips_-_Triceps_Version/0.jpg","Dips_-_Triceps_Version/1.jpg"],"id":"Dips_-_Triceps_Version"}'),
('free-exercise-db', 'Donkey_Calf_Raises', 'donkey-calf-raise', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Donkey_Calf_Raises.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Donkey Calf Raises","force":"push","level":"intermediate","mechanic":"isolation","equipment":"other","primaryMuscles":["calves"],"secondaryMuscles":[],"instructions":["For this exercise you will need access to a donkey calf raise machine. Start by positioning your lower back and hips under the padded lever provided. The tailbone area should be the one making contact with the pad.","Place both of your arms on the side handles and place the balls of your feet on the calf block with the heels extending off. Align the toes forward, inward or outward, depending on the area you wish to target, and straighten the knees without locking them. This will be your starting position.","Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.","Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Donkey_Calf_Raises/0.jpg","Donkey_Calf_Raises/1.jpg"],"id":"Donkey_Calf_Raises"}'),
('free-exercise-db', 'Double_Kettlebell_Alternating_Hang_Clean', 'kettlebell-double-alternating-hang-clean', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Double_Kettlebell_Alternating_Hang_Clean.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Double Kettlebell Alternating Hang Clean","force":"pull","level":"intermediate","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["hamstrings"],"secondaryMuscles":["biceps","calves","forearms","glutes","lower back","quadriceps","traps"],"instructions":["Place two kettlebells between your feet. To get in the starting position, push your butt back and look straight ahead.","Clean one kettlebell to your shoulder and hold on to the other kettlebell.","With a fluid motion, lower the top kettlebell while driving the bottom kettlebell up."],"category":"strength","images":["Double_Kettlebell_Alternating_Hang_Clean/0.jpg","Double_Kettlebell_Alternating_Hang_Clean/1.jpg"],"id":"Double_Kettlebell_Alternating_Hang_Clean"}'),
('free-exercise-db', 'Double_Kettlebell_Jerk', 'kettlebell-double-jerk', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Double_Kettlebell_Jerk.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Double Kettlebell Jerk","force":"push","level":"intermediate","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["shoulders"],"secondaryMuscles":["calves","quadriceps","triceps"],"instructions":["Hold a kettlebell by the handle in each hand.","Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so, so that the palms face forward. This will be your starting position.","Dip your body by bending the knees, keeping your torso upright.","Immediately reverse direction, driving through the heels, in essence jumping to create momentum.","As you do so, press the kettlebells overhead to lockout by extending the arms, using your body''s momentum to move the weights.","Return your feet to the ground in a split fashion, with one foot forward and one foot back.","Keeping the weights overhead, return to a standing position, bringing your feet together. Lower the weights to perform the next repetition."],"category":"strength","images":["Double_Kettlebell_Jerk/0.jpg","Double_Kettlebell_Jerk/1.jpg"],"id":"Double_Kettlebell_Jerk"}'),
('free-exercise-db', 'Double_Kettlebell_Push_Press', 'kettlebell-double-push-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Double_Kettlebell_Push_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Double Kettlebell Push Press","force":"push","level":"intermediate","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["shoulders"],"secondaryMuscles":["calves","quadriceps","triceps"],"instructions":["Clean two kettlebells to your shoulders.","Squat down a few inches and reverse the motion rapidly. Use the momentum from the legs to drive the kettlebells overhead.","Once the kettlebells are locked out, lower the kettlebells to your shoulders and repeat."],"category":"strength","images":["Double_Kettlebell_Push_Press/0.jpg","Double_Kettlebell_Push_Press/1.jpg"],"id":"Double_Kettlebell_Push_Press"}'),
('free-exercise-db', 'Double_Kettlebell_Snatch', 'kettlebell-double-snatch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Double_Kettlebell_Snatch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Double Kettlebell Snatch","force":"pull","level":"expert","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["shoulders"],"secondaryMuscles":["glutes","hamstrings","quadriceps"],"instructions":["Place two kettlebells behind your feet. Bend your knees and sit back to pick up the kettlebells.","Swing the kettlebells between your legs forcefully and reverse the direction.","Drive through with your hips and lock the ketttlebells overhead in one uninterrupted motion."],"category":"strength","images":["Double_Kettlebell_Snatch/0.jpg","Double_Kettlebell_Snatch/1.jpg"],"id":"Double_Kettlebell_Snatch"}'),
('free-exercise-db', 'Double_Kettlebell_Windmill', 'kettlebell-double-windmill', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Double_Kettlebell_Windmill.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Double Kettlebell Windmill","force":"pull","level":"intermediate","mechanic":null,"equipment":"kettlebells","primaryMuscles":["abdominals"],"secondaryMuscles":["glutes","hamstrings","shoulders","triceps"],"instructions":["Place a kettlebell in front of your front foot and clean and press a kettlebell overhead with your opposite arm. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulders. Rotate your wrist as you do so, so that the palm faces forward.","Keeping the kettlebell locked out at all times, push your butt out in the direction of the locked out kettlebell. Turn your feet out at a forty-five degree angle from the arm with the locked out kettlebell.","Bending at the hip to one side, sticking your butt out, slowly lean until you can retrieve the kettlebell from the floor. Keep your eyes on the kettlebell that you hold over your head at all times.","Pause for a second after retrieving the kettlebell from the ground and reverse the motion back to the starting position."],"category":"strength","images":["Double_Kettlebell_Windmill/0.jpg","Double_Kettlebell_Windmill/1.jpg"],"id":"Double_Kettlebell_Windmill"}'),
('free-exercise-db', 'Double_Leg_Butt_Kick', 'double-leg-butt-kick', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Double_Leg_Butt_Kick.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Double Leg Butt Kick","force":"push","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["quadriceps"],"secondaryMuscles":["abductors","adductors","calves","glutes","hamstrings"],"instructions":["Begin standing with your knees slightly bent.","Quickly squat a short distance, flexing the hips and knees, and immediately extend to jump for maximum vertical height.","As you go up, tuck your heels by flexing the knees, attempting to touch the buttocks.","Finish the motion by landing with the knees only partially bent, using your legs to absorb the impact."],"category":"plyometrics","images":["Double_Leg_Butt_Kick/0.jpg","Double_Leg_Butt_Kick/1.jpg"],"id":"Double_Leg_Butt_Kick"}'),
('free-exercise-db', 'Downward_Facing_Balance', 'exercise-ball-downward-facing-balance', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Downward_Facing_Balance.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Downward Facing Balance","force":"static","level":"intermediate","mechanic":"isolation","equipment":"exercise ball","primaryMuscles":["glutes"],"secondaryMuscles":["abdominals","hamstrings"],"instructions":["Lie facedown on top of an exercise ball.","While resting on your stomach on the ball, walk your hands forward along the floor and lift your legs, extending your elbows and knees."],"category":"strength","images":["Downward_Facing_Balance/0.jpg","Downward_Facing_Balance/1.jpg"],"id":"Downward_Facing_Balance"}'),
('free-exercise-db', 'Drag_Curl', 'barbell-drag-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Drag_Curl.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Drag Curl","force":"pull","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["biceps"],"secondaryMuscles":["forearms"],"instructions":["Grab a barbell with a supinated grip (palms facing forward) and get your elbows close to your torso and back. This will be your starting position.","As you exhale, curl the bar up while keeping the elbows to the back as you \"Drag\" the bar up by keeping it in contact with your torso. Tip: As you can see, you will not be keeping the elbows pinned to your sides, but instead you will be bringing them back. Also, do not lift your shoulders.","Slowly go back to the starting position as you keep the bar in contact with the torso at all times.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Drag_Curl/0.jpg","Drag_Curl/1.jpg"],"id":"Drag_Curl"}'),
('free-exercise-db', 'Drop_Push', 'drop-push', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Drop_Push.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Drop Push","force":"push","level":"intermediate","mechanic":"compound","equipment":"other","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["Position low boxes or other platforms 2-3 feet apart.","Move to a pushup position between them, supporting yourself by placing your hands on the boxes.","With good posture, drop from the platforms by pressing up and moving your hands to shoulder width, cushioning your landing by absorbing the impact through the arm."],"category":"plyometrics","images":["Drop_Push/0.jpg","Drop_Push/1.jpg"],"id":"Drop_Push"}'),
('free-exercise-db', 'Dumbbell_Alternate_Bicep_Curl', 'dumbbell-alternating-biceps-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Dumbbell_Alternate_Bicep_Curl.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Dumbbell Alternate Bicep Curl","force":"pull","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["biceps"],"secondaryMuscles":["forearms"],"instructions":["Stand (torso upright) with a dumbbell in each hand held at arms length. The elbows should be close to the torso and the palms of your hand should be facing your thighs.","While holding the upper arm stationary, curl the right weight as you rotate the palm of the hands until they are facing forward. At this point continue contracting the biceps as you breathe out until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps. Tip: Only the forearms should move.","Slowly begin to bring the dumbbell back to the starting position as your breathe in. Tip: Remember to twist the palms back to the starting position (facing your thighs) as you come down.","Repeat the movement with the left hand. This equals one repetition.","Continue alternating in this manner for the recommended amount of repetitions."],"category":"strength","images":["Dumbbell_Alternate_Bicep_Curl/0.jpg","Dumbbell_Alternate_Bicep_Curl/1.jpg"],"id":"Dumbbell_Alternate_Bicep_Curl"}'),
('free-exercise-db', 'Dumbbell_Bench_Press', 'dumbbell-bench-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Dumbbell_Bench_Press.json', 'Unlicense', NULL, 'exact', 100.0, '{"name":"Dumbbell Bench Press","force":"push","level":"beginner","mechanic":"compound","equipment":"dumbbell","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["Lie down on a flat bench with a dumbbell in each hand resting on top of your thighs. The palms of your hands will be facing each other.","Then, using your thighs to help raise the dumbbells up, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.","Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. The dumbbells should be just to the sides of your chest, with your upper arm and forearm creating a 90 degree angle. Be sure to maintain full control of the dumbbells at all times. This will be your starting position.","Then, as you breathe out, use your chest to push the dumbbells up. Lock your arms at the top of the lift and squeeze your chest, hold for a second and then begin coming down slowly. Tip: Ideally, lowering the weight should take about twice as long as raising it.","Repeat the movement for the prescribed amount of repetitions of your training program."],"category":"strength","images":["Dumbbell_Bench_Press/0.jpg","Dumbbell_Bench_Press/1.jpg"],"id":"Dumbbell_Bench_Press"}'),
('free-exercise-db', 'Dumbbell_Bench_Press_with_Neutral_Grip', 'dumbbell-bench-press-neutral-grip', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Dumbbell_Bench_Press_with_Neutral_Grip.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Dumbbell Bench Press with Neutral Grip","force":"push","level":"beginner","mechanic":"compound","equipment":"dumbbell","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["Take a dumbbell in each hand and lay back onto a flat bench. Your feet should be flat on the floor and your shoulder blades retracted.","Maintaining a neutral grip, palms facing each other, begin with your arms extended directly above you, perpendicular to the floor. This will be your starting position.","Begin the movement by flexing the elbow, lowering the upper arms to the side. Descend until the dumbbells are to your torso.","Pause, then extend the elbow and return to the starting position."],"category":"strength","images":["Dumbbell_Bench_Press_with_Neutral_Grip/0.jpg","Dumbbell_Bench_Press_with_Neutral_Grip/1.jpg"],"id":"Dumbbell_Bench_Press_with_Neutral_Grip"}'),
('free-exercise-db', 'Dumbbell_Bicep_Curl', 'dumbbell-biceps-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Dumbbell_Bicep_Curl.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Dumbbell Bicep Curl","force":"pull","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["biceps"],"secondaryMuscles":["forearms"],"instructions":["Stand up straight with a dumbbell in each hand at arm''s length. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position.","Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps.","Then, inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Dumbbell_Bicep_Curl/0.jpg","Dumbbell_Bicep_Curl/1.jpg"],"id":"Dumbbell_Bicep_Curl"}'),
('free-exercise-db', 'Dumbbell_Clean', 'dumbbell-clean', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Dumbbell_Clean.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Dumbbell Clean","force":"pull","level":"intermediate","mechanic":"compound","equipment":"dumbbell","primaryMuscles":["hamstrings"],"secondaryMuscles":["calves","forearms","glutes","lower back","quadriceps","shoulders","traps"],"instructions":["Begin standing with a dumbbell in each hand with your feet shoulder width apart.","Lower the weights to the floor by flexing at the hips and knees, pushing your hips back until the dumbbells reach the floor. This will be your starting position.","To initiate the movement, violently jump upward by extending the hips, knees, and ankles to acclerate the weights upward. Maintaining a neutral grip on the dumbbells, keep the arms straight until full extension is reached.","After full extension, rebend the hips and knees to receive the weight in a squat position. Allow the arms to bend, guiding the dumbbells to your shoulders.","Upon receiving the weight in the squat position, extend the hips and knees to finish in a standing position with the weights on your shoulders."],"category":"strength","images":["Dumbbell_Clean/0.jpg","Dumbbell_Clean/1.jpg"],"id":"Dumbbell_Clean"}'),
('free-exercise-db', 'Dumbbell_Floor_Press', 'dumbbell-floor-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Dumbbell_Floor_Press.json', 'Unlicense', NULL, 'exact', 100.0, '{"name":"Dumbbell Floor Press","force":"push","level":"intermediate","mechanic":"compound","equipment":"dumbbell","primaryMuscles":["triceps"],"secondaryMuscles":["chest","shoulders"],"instructions":["Lay on the floor holding dumbbells in your hands. Your knees can be bent. Begin with the weights fully extended above you.","Lower the weights until your upper arm comes in contact with the floor. You can tuck your elbows to emphasize triceps size and strength, or to focus on your chest angle your arms to the side.","Pause at the bottom, and then bring the weight together at the top by extending through the elbows."],"category":"powerlifting","images":["Dumbbell_Floor_Press/0.jpg","Dumbbell_Floor_Press/1.jpg"],"id":"Dumbbell_Floor_Press"}'),
('free-exercise-db', 'Dumbbell_Flyes', 'dumbbell-fly', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Dumbbell_Flyes.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Dumbbell Flyes","force":"push","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["chest"],"secondaryMuscles":[],"instructions":["Lie down on a flat bench with a dumbbell on each hand resting on top of your thighs. The palms of your hand will be facing each other.","Then using your thighs to help raise the dumbbells, lift the dumbbells one at a time so you can hold them in front of you at shoulder width with the palms of your hands facing each other. Raise the dumbbells up like you''re pressing them, but stop and hold just before you lock out. This will be your starting position.","With a slight bend on your elbows in order to prevent stress at the biceps tendon, lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms should remain stationary; the movement should only occur at the shoulder joint.","Return your arms back to the starting position as you squeeze your chest muscles and breathe out. Tip: Make sure to use the same arc of motion used to lower the weights.","Hold for a second at the contracted position and repeat the movement for the prescribed amount of repetitions."],"category":"strength","images":["Dumbbell_Flyes/0.jpg","Dumbbell_Flyes/1.jpg"],"id":"Dumbbell_Flyes"}'),
('free-exercise-db', 'Dumbbell_Incline_Row', 'dumbbell-incline-row', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Dumbbell_Incline_Row.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Dumbbell Incline Row","force":"pull","level":"beginner","mechanic":"compound","equipment":"dumbbell","primaryMuscles":["middle back"],"secondaryMuscles":["biceps","forearms","lats","shoulders"],"instructions":["Using a neutral grip, lean into an incline bench.","Take a dumbbell in each hand with a neutral grip, beginning with the arms straight. This will be your starting position.","Retract the shoulder blades and flex the elbows to row the dumbbells to your side.","Pause at the top of the motion, and then return to the starting position."],"category":"strength","images":["Dumbbell_Incline_Row/0.jpg","Dumbbell_Incline_Row/1.jpg"],"id":"Dumbbell_Incline_Row"}'),
('free-exercise-db', 'Dumbbell_Incline_Shoulder_Raise', 'dumbbell-incline-shoulder-raise', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Dumbbell_Incline_Shoulder_Raise.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Dumbbell Incline Shoulder Raise","force":"push","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":["triceps"],"instructions":["Sit on an Incline Bench while holding a dumbbell on each hand on top of your thighs.","Lift your legs up to kick the weights to your shoulders and lean back. Position the dumbbells above your shoulders with your arms extended. The arms should be perpendicular to the floor with your palms facing forward and knuckles pointing towards the ceiling. This will be your starting position.","While keeping the arms straight and locked, lift the dumbbells by raising the shoulders from the bench as you breathe out.","Bring back the dumbbells to the starting position as you breathe in.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Dumbbell_Incline_Shoulder_Raise/0.jpg","Dumbbell_Incline_Shoulder_Raise/1.jpg"],"id":"Dumbbell_Incline_Shoulder_Raise"}'),
('free-exercise-db', 'Dumbbell_Lunges', 'dumbbell-lunge', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Dumbbell_Lunges.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Dumbbell Lunges","force":"push","level":"beginner","mechanic":"compound","equipment":"dumbbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings"],"instructions":["Stand with your torso upright holding two dumbbells in your hands by your sides. This will be your starting position.","Step forward with your right leg around 2 feet or so from the foot being left stationary behind and lower your upper body down, while keeping the torso upright and maintaining balance. Inhale as you go down. Note: As in the other exercises, do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. Make sure that you keep your front shin perpendicular to the ground.","Using mainly the heel of your foot, push up and go back to the starting position as you exhale.","Repeat the movement for the recommended amount of repetitions and then perform with the left leg."],"category":"strength","images":["Dumbbell_Lunges/0.jpg","Dumbbell_Lunges/1.jpg"],"id":"Dumbbell_Lunges"}'),
('free-exercise-db', 'Dumbbell_Lying_One-Arm_Rear_Lateral_Raise', 'dumbbell-lying-one-arm-rear-lateral-raise', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Dumbbell_Lying_One-Arm_Rear_Lateral_Raise.json', 'Unlicense', NULL, 'new', 85.7, '{"name":"Dumbbell Lying One-Arm Rear Lateral Raise","force":"pull","level":"intermediate","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":["middle back"],"instructions":["While holding a dumbbell in one hand, lay with your chest down on a slightly inclined (around 15 degrees when measured from the floor) adjustable bench. The other hand can be used to hold to the leg of the bench for stability.","Position the palm of the hand that is holding the dumbbell in a neutral manner (palms facing your torso) as you keep the arm extended with the elbow slightly bent. This will be your starting position.","Now raise the arm with the dumbbell to the side until your elbow is at shoulder height and your arm is roughly parallel to the floor as you exhale. Tip: Maintain your arm perpendicular to the torso while keeping your arm extended throughout the movement. Also, keep the contraction at the top for a second.","Slowly lower the dumbbell to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Dumbbell_Lying_One-Arm_Rear_Lateral_Raise/0.jpg","Dumbbell_Lying_One-Arm_Rear_Lateral_Raise/1.jpg"],"id":"Dumbbell_Lying_One-Arm_Rear_Lateral_Raise"}'),
('free-exercise-db', 'Dumbbell_Lying_Pronation', 'dumbbell-lying-pronation', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Dumbbell_Lying_Pronation.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Dumbbell Lying Pronation","force":"pull","level":"intermediate","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["forearms"],"secondaryMuscles":[],"instructions":["Lie on a flat bench face down with one arm holding a dumbbell and the other hand on top of the bench folded so that you can rest your head on it.","Bend the elbows of the arm holding the dumbbell so that it creates a 90-degree angle between the upper arm and the forearm.","Now raise the upper arm so that the forearm is perpendicular to the floor and the upper arm is perpendicular to your torso. Tip: The upper arm should be parallel to the floor and also creating a 90-degree angle with your torso. This will be your starting position.","As you breathe out, externally rotate your forearm so that the dumbbell is lifted forward as you maintain the 90 degree angle bend between the upper arms and the forearm. You will continue this external rotation until the forearm is parallel to the floor. At this point you will hold the contraction for a second.","As you breathe in, slowly go back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Dumbbell_Lying_Pronation/0.jpg","Dumbbell_Lying_Pronation/1.jpg"],"id":"Dumbbell_Lying_Pronation"}'),
('free-exercise-db', 'Dumbbell_Lying_Rear_Lateral_Raise', 'dumbbell-lying-rear-lateral-raise', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Dumbbell_Lying_Rear_Lateral_Raise.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Dumbbell Lying Rear Lateral Raise","force":"pull","level":"intermediate","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":[],"instructions":["While holding a dumbbell in each hand, lay with your chest down on a slightly inclined (around 15 degrees when measured from the floor) adjustable bench.","Position the palms of the hands in a neutral manner (palms facing your torso) as you keep the arms extended with the elbows slightly bent. This will be your starting position.","Now raise the arms to the side until your elbows are at shoulder height and your arms are roughly parallel to the floor as you exhale. Tip: Maintain your arms perpendicular to the torso while keeping them extended throughout the movement. Also, keep the contraction at the top for a second.","Slowly lower the dumbbells to the starting position as you inhale.","Repeat for the recommended amount of repetitions and then switch to the other arm."],"category":"strength","images":["Dumbbell_Lying_Rear_Lateral_Raise/0.jpg","Dumbbell_Lying_Rear_Lateral_Raise/1.jpg"],"id":"Dumbbell_Lying_Rear_Lateral_Raise"}'),
('free-exercise-db', 'Dumbbell_Lying_Supination', 'dumbbell-lying-supination', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Dumbbell_Lying_Supination.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Dumbbell Lying Supination","force":"pull","level":"intermediate","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["forearms"],"secondaryMuscles":[],"instructions":["Lie sideways on a flat bench with one arm holding a dumbbell and the other hand on top of the bench folded so that you can rest your head on it.","Bend the elbows of the arm holding the dumbbell so that it creates a 90-degree angle between the upper arm and the forearm.","Now raise the upper arm so that the forearm is parallel to the floor and perpendicular to your torso (Tip: So the forearm will be directly in front of you). The upper arm will be stationary by your torso and should be parallel to the floor (aligned with your torso at all times). This will be your starting position.","As you breathe out, externally rotate your forearm so that the dumbbell is lifted up in a semicircle motion as you maintain the 90 degree angle bend between the upper arms and the forearm. You will continue this external rotation until the forearm is perpendicular to the floor and the torso pointing towards the ceiling. At this point you will hold the contraction for a second.","As you breathe in, slowly go back to the starting position.","Repeat for the recommended amount of repetitions and then switch to the other arm."],"category":"strength","images":["Dumbbell_Lying_Supination/0.jpg","Dumbbell_Lying_Supination/1.jpg"],"id":"Dumbbell_Lying_Supination"}'),
('free-exercise-db', 'Dumbbell_One-Arm_Shoulder_Press', 'dumbbell-one-arm-shoulder-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Dumbbell_One-Arm_Shoulder_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Dumbbell One-Arm Shoulder Press","force":"push","level":"intermediate","mechanic":"compound","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":["triceps"],"instructions":["Grab a dumbbell and either sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs or stand up straight.","Clean the dumbbell up to bring it to shoulder height. The other hand can be kept fully extended to the side, by the waist or grabbing a fixed surface.","Rotate the wrist so that the palm of your hand is facing forward. This is your starting position.","As you exhale, push the dumbbell up until your arm is fully extended.","After a second pause, slowly come down back to the starting position as you inhale.","Repeat for the recommended amount of repetitions and then switch arms."],"category":"strength","images":["Dumbbell_One-Arm_Shoulder_Press/0.jpg","Dumbbell_One-Arm_Shoulder_Press/1.jpg"],"id":"Dumbbell_One-Arm_Shoulder_Press"}'),
('free-exercise-db', 'Dumbbell_One-Arm_Triceps_Extension', 'dumbbell-one-arm-triceps-extension', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Dumbbell_One-Arm_Triceps_Extension.json', 'Unlicense', NULL, 'new', 88.5, '{"name":"Dumbbell One-Arm Triceps Extension","force":"push","level":"intermediate","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["triceps"],"secondaryMuscles":[],"instructions":["Grab a dumbbell and either sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs or stand up straight.","Clean the dumbbell up to bring it to shoulder height and then extend the arm over your head so that the whole arm is perpendicular to the floor and next to your head. The dumbbell should be on top of you. The other hand can be kept fully extended to the side, by the waist, supporting the upper arm that has the dumbbell or grabbing a fixed surface.","Rotate the wrist so that the palm of your hand is facing forward and the pinkie is facing the ceiling. This will be your starting position.","Slowly lower the dumbbell behind your head as you hold the upper arm stationary. Inhale as you perform this movement and pause when your triceps are fully stretched.","Return to the starting position by flexing your triceps as you breathe out. Tip: It is imperative that only the forearm moves. The upper arm should remain at all times stationary next to your head.","Repeat for the recommended amount of repetitions and switch arms."],"category":"strength","images":["Dumbbell_One-Arm_Triceps_Extension/0.jpg","Dumbbell_One-Arm_Triceps_Extension/1.jpg"],"id":"Dumbbell_One-Arm_Triceps_Extension"}'),
('free-exercise-db', 'Dumbbell_One-Arm_Upright_Row', 'dumbbell-one-arm-upright-row', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Dumbbell_One-Arm_Upright_Row.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Dumbbell One-Arm Upright Row","force":"pull","level":"intermediate","mechanic":"compound","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":["biceps","traps"],"instructions":["Grab a dumbbell and stand up straight with your arm extended in front of you with a slight bend at the elbows and your back straight. This will be your starting position. Tip: The dumbbell should be resting on top of your thigh with the palm of your hands facing your thighs.","Keep the other hand can be kept fully extended to the side, by the waist or grabbing a fixed surface. This will be your starting position.","Use your side shoulders to lift the dumbbell as you exhale. The dumbbell should be close to the body as you move it up. Continue to lift it until the dumbbell is nearly in line with your chin. Tip: Your elbows should drive the motion. As you lift the dumbbell, your elbow should always be higher than your forearm. Also, keep your torso stationary and pause for a second at the top of the movement.","Lower the dumbbell back down slowly to the starting position. Inhale as you perform this portion of the movement.","Repeat for the recommended amount of repetitions and switch arms."],"category":"strength","images":["Dumbbell_One-Arm_Upright_Row/0.jpg","Dumbbell_One-Arm_Upright_Row/1.jpg"],"id":"Dumbbell_One-Arm_Upright_Row"}'),
('free-exercise-db', 'Dumbbell_Prone_Incline_Curl', 'dumbbell-prone-incline-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Dumbbell_Prone_Incline_Curl.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Dumbbell Prone Incline Curl","force":"pull","level":"intermediate","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["biceps"],"secondaryMuscles":[],"instructions":["Grab a dumbbell on each hand and lie face down on an incline bench with your shoulders near top of the incline. Your knees can rest on the seat or your legs can be straddled to the sides (my preferred way).","Let your arms extend and hang naturally in front of you so that they are perpendicular to the floor.","Now keep your elbows in by your side and face the palms forward. This will be your starting position.","Raise the dumbbells by contracting the biceps until your arms are fully flexed. Exhale as you perform this portion of the movement and ensure that only the forearms move. The upper arms should remain stationary at all times.","Lower the dumbbells until your arms are fully extended.","Repeat for the recommended amount of times."],"category":"strength","images":["Dumbbell_Prone_Incline_Curl/0.jpg","Dumbbell_Prone_Incline_Curl/1.jpg"],"id":"Dumbbell_Prone_Incline_Curl"}'),
('free-exercise-db', 'Dumbbell_Raise', 'dumbbell-raise', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Dumbbell_Raise.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Dumbbell Raise","force":"pull","level":"beginner","mechanic":"compound","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":["biceps"],"instructions":["Grab a dumbbell in each arm and stand up straight with your arms extended by your sides with a slight bend at the elbows and your back straight. This will be your starting position. Tip: The dumbbell should be next to your thighs with the palm of your hands facing back.","Use your side shoulders to lift the dumbbells as you exhale. The dumbbells should be to the side of the body as you move them up. Continue to lift it until the dumbbells are nearly in line with your chin. Tip: Your elbows should drive the motion. As you lift the dumbbell, your elbow should always be higher than your forearm. Also, keep your torso stationary and pause for a second at the top of the movement.","Lower the dumbbells back down slowly to the starting position. Inhale as you perform this portion of the movement.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Dumbbell_Raise/0.jpg","Dumbbell_Raise/1.jpg"],"id":"Dumbbell_Raise"}'),
('free-exercise-db', 'Dumbbell_Rear_Lunge', 'dumbbell-rear-lunge', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Dumbbell_Rear_Lunge.json', 'Unlicense', NULL, 'exact', 100.0, '{"name":"Dumbbell Rear Lunge","force":"push","level":"intermediate","mechanic":"compound","equipment":"dumbbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings"],"instructions":["Stand with your torso upright holding two dumbbells in your hands by your sides. This will be your starting position.","Step backward with your right leg around two feet or so from the left foot and lower your upper body down, while keeping the torso upright and maintaining balance. Inhale as you go down. Tip: As in the other exercises, do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. Make sure that you keep your front shin perpendicular to the ground. Keep the torso upright during the lunge; flexible hip flexors are important. A long lunge emphasizes the Gluteus Maximus; a short lunge emphasizes Quadriceps.","Push up and go back to the starting position as you exhale. Tip: Use the ball of your feet to push in order to accentuate the quadriceps. To focus on the glutes, press with your heels.","Now repeat with the opposite leg."],"category":"strength","images":["Dumbbell_Rear_Lunge/0.jpg","Dumbbell_Rear_Lunge/1.jpg"],"id":"Dumbbell_Rear_Lunge"}'),
('free-exercise-db', 'Dumbbell_Scaption', 'dumbbell-scaption', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Dumbbell_Scaption.json', 'Unlicense', NULL, 'exact', 100.0, '{"name":"Dumbbell Scaption","force":"push","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":["traps"],"instructions":["This corrective exercise strengthens the muscles that stabilize your shoulder blade. Hold a light weight in each hand, hanging at your sides. Your thumbs should pointing up.","Begin the movement raising your arms out in front of you, about 30 degrees off center. Your arms should be fully extended as you perform the movement.","Continue until your arms are parallel to the ground, and then return to the starting position."],"category":"strength","images":["Dumbbell_Scaption/0.jpg","Dumbbell_Scaption/1.jpg"],"id":"Dumbbell_Scaption"}'),
('free-exercise-db', 'Dumbbell_Seated_Box_Jump', 'dumbbell-seated-box-jump', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Dumbbell_Seated_Box_Jump.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Dumbbell Seated Box Jump","force":"push","level":"intermediate","mechanic":"compound","equipment":"dumbbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings"],"instructions":["Position a box a couple feet to the side of a bench. Hold a dumbbell to your chest with both hands and seat yourself on the bench facing the box. This will be your starting position.","Plant your feet firmly on the ground as you lean forward, extending through the hips and knees to jump up and forward.","Land on the box with both feet, absorbing the impact by allowing the hips and knees to bend.","Step down and return to the starting position."],"category":"plyometrics","images":["Dumbbell_Seated_Box_Jump/0.jpg","Dumbbell_Seated_Box_Jump/1.jpg"],"id":"Dumbbell_Seated_Box_Jump"}'),
('free-exercise-db', 'Dumbbell_Seated_One-Leg_Calf_Raise', 'dumbbell-seated-one-leg-calf-raise', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Dumbbell_Seated_One-Leg_Calf_Raise.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Dumbbell Seated One-Leg Calf Raise","force":"push","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["calves"],"secondaryMuscles":[],"instructions":["Place a block on the floor about 12 inches from a flat bench.","Sit on a flat bench and place a dumbbell on your upper left thigh about 3 inches above your knee.","Now place the ball of your left foot on the block. This will be your starting position.","Raise your toes up as high as possible as you exhale and you contract your calf muscle. Hold the contraction for a second.","Slowly return to the starting position, stretching as far down as possible.","Repeat for your prescribed number of repetitions and then repeat with the right leg."],"category":"strength","images":["Dumbbell_Seated_One-Leg_Calf_Raise/0.jpg","Dumbbell_Seated_One-Leg_Calf_Raise/1.jpg"],"id":"Dumbbell_Seated_One-Leg_Calf_Raise"}'),
('free-exercise-db', 'Dumbbell_Shoulder_Press', 'dumbbell-shoulder-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Dumbbell_Shoulder_Press.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Dumbbell Shoulder Press","force":"push","level":"intermediate","mechanic":"compound","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":["triceps"],"instructions":["While holding a dumbbell in each hand, sit on a military press bench or utility bench that has back support. Place the dumbbells upright on top of your thighs.","Now raise the dumbbells to shoulder height one at a time using your thighs to help propel them up into position.","Make sure to rotate your wrists so that the palms of your hands are facing forward. This is your starting position.","Now, exhale and push the dumbbells upward until they touch at the top.","Then, after a brief pause at the top contracted position, slowly lower the weights back down to the starting position while inhaling.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Dumbbell_Shoulder_Press/0.jpg","Dumbbell_Shoulder_Press/1.jpg"],"id":"Dumbbell_Shoulder_Press"}'),
('free-exercise-db', 'Dumbbell_Shrug', 'dumbbell-shrug', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Dumbbell_Shrug.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Dumbbell Shrug","force":"pull","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["traps"],"secondaryMuscles":[],"instructions":["Stand erect with a dumbbell on each hand (palms facing your torso), arms extended on the sides.","Lift the dumbbells by elevating the shoulders as high as possible while you exhale. Hold the contraction at the top for a second. Tip: The arms should remain extended at all times. Refrain from using the biceps to help lift the dumbbells. Only the shoulders should be moving up and down.","Lower the dumbbells back to the original position.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Dumbbell_Shrug/0.jpg","Dumbbell_Shrug/1.jpg"],"id":"Dumbbell_Shrug"}'),
('free-exercise-db', 'Dumbbell_Side_Bend', 'dumbbell-side-bend', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Dumbbell_Side_Bend.json', 'Unlicense', NULL, 'exact', 100.0, '{"name":"Dumbbell Side Bend","force":"pull","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Stand up straight while holding a dumbbell on the left hand (palms facing the torso) as you have the right hand holding your waist. Your feet should be placed at shoulder width. This will be your starting position.","While keeping your back straight and your head up, bend only at the waist to the right as far as possible. Breathe in as you bend to the side. Then hold for a second and come back up to the starting position as you exhale. Tip: Keep the rest of the body stationary.","Now repeat the movement but bending to the left instead. Hold for a second and come back to the starting position.","Repeat for the recommended amount of repetitions and then change hands."],"category":"strength","images":["Dumbbell_Side_Bend/0.jpg","Dumbbell_Side_Bend/1.jpg"],"id":"Dumbbell_Side_Bend"}'),
('free-exercise-db', 'Dumbbell_Squat', 'dumbbell-squat', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Dumbbell_Squat.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Dumbbell Squat","force":"push","level":"beginner","mechanic":"compound","equipment":"dumbbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings","lower back"],"instructions":["Stand up straight while holding a dumbbell on each hand (palms facing the side of your legs).","Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section.","Begin to slowly lower your torso by bending the knees as you maintain a straight posture with the head up. Continue down until your thighs are parallel to the floor. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise your torso as you exhale by pushing the floor with the heel of your foot mainly as you straighten the legs again and go back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Dumbbell_Squat/0.jpg","Dumbbell_Squat/1.jpg"],"id":"Dumbbell_Squat"}'),
('free-exercise-db', 'Dumbbell_Squat_To_A_Bench', 'dumbbell-squat-to-bench', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Dumbbell_Squat_To_A_Bench.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Dumbbell Squat To A Bench","force":"push","level":"intermediate","mechanic":"compound","equipment":"dumbbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings","lower back"],"instructions":["Stand up straight with a flat bench behind you while holding a dumbbell on each hand (palms facing the side of your legs).","Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section.","Begin to slowly lower your torso by bending the knees as you maintain a straight posture with the head up. Continue down until you slightly touch the bench behind you. Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise the bar as you exhale by pushing the floor with the heel of your foot mainly as you straighten the legs again and go back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Dumbbell_Squat_To_A_Bench/0.jpg","Dumbbell_Squat_To_A_Bench/1.jpg"],"id":"Dumbbell_Squat_To_A_Bench"}'),
('free-exercise-db', 'Dumbbell_Step_Ups', 'dumbbell-step-up', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Dumbbell_Step_Ups.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Dumbbell Step Ups","force":"push","level":"intermediate","mechanic":"compound","equipment":"dumbbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings"],"instructions":["Stand up straight while holding a dumbbell on each hand (palms facing the side of your legs).","Place the right foot on the elevated platform. Step on the platform by extending the hip and the knee of your right leg. Use the heel mainly to lift the rest of your body up and place the foot of the left leg on the platform as well. Breathe out as you execute the force required to come up.","Step down with the left leg by flexing the hip and knee of the right leg as you inhale. Return to the original standing position by placing the right foot of to next to the left foot on the initial position.","Repeat with the right leg for the recommended amount of repetitions and then perform with the left leg."],"category":"strength","images":["Dumbbell_Step_Ups/0.jpg","Dumbbell_Step_Ups/1.jpg"],"id":"Dumbbell_Step_Ups"}'),
('free-exercise-db', 'Dumbbell_Tricep_Extension_-Pronated_Grip', 'dumbbell-tricep-extension-pronated-grip', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Dumbbell_Tricep_Extension_-Pronated_Grip.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Dumbbell Tricep Extension -Pronated Grip","force":"push","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["triceps"],"secondaryMuscles":[],"instructions":["Lie down on a flat bench holding two dumbbells directly above your shoulders. Your arms should be fully extended and form a 90 degree angle from your torso and the floor.","The palms of your hands should be facing forward, and your elbows should be tucked in. This will be your starting position.","Now, inhale and slowly lower the dumbbells until they are near your ears. Be sure to keep your upper arms stationary and your elbows tucked in.","Then, exhale and use your triceps to return the weight to the starting position."],"category":"strength","images":["Dumbbell_Tricep_Extension_-Pronated_Grip/0.jpg","Dumbbell_Tricep_Extension_-Pronated_Grip/1.jpg"],"id":"Dumbbell_Tricep_Extension_-Pronated_Grip"}'),
('free-exercise-db', 'Dynamic_Back_Stretch', 'dynamic-back-stretch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Dynamic_Back_Stretch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Dynamic Back Stretch","force":"pull","level":"beginner","mechanic":null,"equipment":null,"primaryMuscles":["lats"],"secondaryMuscles":[],"instructions":["Stand with your feet shoulder width apart. This will be your starting position.","Keeping your arms straight, swing them straight up in front of you 5-10 times, increasing the range of motion each time until your arms are above your head."],"category":"stretching","images":["Dynamic_Back_Stretch/0.jpg","Dynamic_Back_Stretch/1.jpg"],"id":"Dynamic_Back_Stretch"}'),
('free-exercise-db', 'Dynamic_Chest_Stretch', 'dynamic-chest-stretch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Dynamic_Chest_Stretch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Dynamic Chest Stretch","force":"pull","level":"beginner","mechanic":null,"equipment":null,"primaryMuscles":["chest"],"secondaryMuscles":["middle back"],"instructions":["Stand with your hands together, arms extended directly in front of you. This will be your starting position.","Keeping your arms straight, quickly move your arms back as far as possible and back in again, similar to an exaggerated clapping motion. Repeat 5-10 times, increasing speed as you do so."],"category":"stretching","images":["Dynamic_Chest_Stretch/0.jpg","Dynamic_Chest_Stretch/1.jpg"],"id":"Dynamic_Chest_Stretch"}'),
('free-exercise-db', 'EZ-Bar_Curl', 'ez-bar-biceps-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/EZ-Bar_Curl.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"EZ-Bar Curl","force":"pull","level":"beginner","mechanic":"isolation","equipment":"e-z curl bar","primaryMuscles":["biceps"],"secondaryMuscles":[],"instructions":["Stand up straight while holding an EZ curl bar at the wide outer handle. The palms of your hands should be facing forward and slightly tilted inward due to the shape of the bar. Keep your elbows close to your torso. This will be your starting position.","Now, while keeping your upper arms stationary, exhale and curl the weights forward while contracting the biceps. Focus on only moving your forearms.","Continue to raise the weight until your biceps are fully contracted and the bar is at shoulder level. Hold the top contracted position for a moment and squeeze the biceps.","Then inhale and slowly lower the bar back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["EZ-Bar_Curl/0.jpg","EZ-Bar_Curl/1.jpg"],"id":"EZ-Bar_Curl"}'),
('free-exercise-db', 'EZ-Bar_Skullcrusher', 'ez-bar-skullcrusher', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/EZ-Bar_Skullcrusher.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"EZ-Bar Skullcrusher","force":"push","level":"beginner","mechanic":"isolation","equipment":"e-z curl bar","primaryMuscles":["triceps"],"secondaryMuscles":["forearms"],"instructions":["Using a close grip, lift the EZ bar and hold it with your elbows in as you lie on the bench. Your arms should be perpendicular to the floor. This will be your starting position.","Keeping the upper arms stationary, lower the bar by allowing the elbows to flex. Inhale as you perform this portion of the movement. Pause once the bar is directly above the forehead.","Lift the bar back to the starting position by extending the elbow and exhaling.","Repeat."],"category":"strength","images":["EZ-Bar_Skullcrusher/0.jpg","EZ-Bar_Skullcrusher/1.jpg"],"id":"EZ-Bar_Skullcrusher"}'),
('free-exercise-db', 'Elbow_Circles', 'elbow-circle', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Elbow_Circles.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Elbow Circles","force":"pull","level":"beginner","mechanic":"isolation","equipment":null,"primaryMuscles":["shoulders"],"secondaryMuscles":["traps"],"instructions":["Sit or stand with your feet slightly apart.","Place your hands on your shoulders with your elbows at shoulder level and pointing out.","Slowly make a circle with your elbows. Breathe out as you start the circle and breathe in as you complete the circle."],"category":"stretching","images":["Elbow_Circles/0.jpg","Elbow_Circles/1.jpg"],"id":"Elbow_Circles"}'),
('free-exercise-db', 'Elbow_to_Knee', 'elbow-to-knee', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Elbow_to_Knee.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Elbow to Knee","force":"pull","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Lie on the floor, crossing your right leg across your bent left knee. Clasp your hands behind your head, beginning with your shoulder blades on the ground. This will be your starting position.","Perform the motion by flexing the spine and rotating your torso to bring the left elbow to the right knee.","Return to the starting position and repeat the movement for the desired number of repetitions before switching sides."],"category":"strength","images":["Elbow_to_Knee/0.jpg","Elbow_to_Knee/1.jpg"],"id":"Elbow_to_Knee"}'),
('free-exercise-db', 'Elbows_Back', 'elbows-back', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Elbows_Back.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Elbows Back","force":"static","level":"beginner","mechanic":"isolation","equipment":null,"primaryMuscles":["chest"],"secondaryMuscles":["shoulders"],"instructions":["Stand up straight.","Place both hands on your lower back, fingers pointing downward and elbows out.","Then gently pull your elbows back aiming to touch them together."],"category":"stretching","images":["Elbows_Back/0.jpg","Elbows_Back/1.jpg"],"id":"Elbows_Back"}'),
('free-exercise-db', 'Elevated_Back_Lunge', 'barbell-elevated-back-lunge', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Elevated_Back_Lunge.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Elevated Back Lunge","force":"push","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["glutes","hamstrings"],"instructions":["Position a bar onto a rack at shoulder height loaded to an appropriate weight. Place a short, raised platform behind you.","Rack the bar onto your upper back, keeping your back arched and tight. Step onto your raised platform with both feet. This will be your starting position.","Begin by stepping backwards with one leg. Descend by flexing your hips and knees until your knee touches the floor.","Pause, and extend through the hips and knees to rise up, returning all the way to the starting position before alternating."],"category":"strength","images":["Elevated_Back_Lunge/0.jpg","Elevated_Back_Lunge/1.jpg"],"id":"Elevated_Back_Lunge"}'),
('free-exercise-db', 'Elevated_Cable_Rows', 'cable-elevated-row', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Elevated_Cable_Rows.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Elevated Cable Rows","force":"pull","level":"intermediate","mechanic":"compound","equipment":"cable","primaryMuscles":["lats"],"secondaryMuscles":["middle back","traps"],"instructions":["Get a platform of some sort (it can be an aerobics or calf raise platform) that is around 4-6 inches in height.","Place it on the seat of the cable row machine.","Sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.","Lean over as you keep the natural alignment of your back and grab the V-bar handles.","With your arms extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lats as you hold the bar in front of you. This is the starting position of the exercise.","Keeping the torso stationary, pull the handles back towards your torso while keeping the arms close to it until you touch the abdominals. Breathe out as you perform that movement. At that point you should be squeezing your back muscles hard. Hold that contraction for a second and slowly go back to the original position while breathing in.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Elevated_Cable_Rows/0.jpg","Elevated_Cable_Rows/1.jpg"],"id":"Elevated_Cable_Rows"}'),
('free-exercise-db', 'Elliptical_Trainer', 'machine-elliptical-trainer', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Elliptical_Trainer.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Elliptical Trainer","force":null,"level":"intermediate","mechanic":null,"equipment":"machine","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings"],"instructions":["To begin, step onto the elliptical and select the desired option from the menu. Most ellipticals have a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout.","The handles can be used to monitor your heart rate to help you stay at an appropriate intensity."],"category":"cardio","images":["Elliptical_Trainer/0.jpg","Elliptical_Trainer/1.jpg"],"id":"Elliptical_Trainer"}'),
('free-exercise-db', 'Exercise_Ball_Crunch', 'exercise-ball-crunch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Exercise_Ball_Crunch.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Exercise Ball Crunch","force":"pull","level":"beginner","mechanic":"isolation","equipment":"exercise ball","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Lie on an exercise ball with your lower back curvature pressed against the spherical surface of the ball. Your feet should be bent at the knee and pressed firmly against the floor. The upper torso should be hanging off the top of the ball. The arms should either be kept alongside the body or crossed on top of your chest as these positions avoid neck strains (as opposed to the hands behind the back of the head position).","Lower your torso into a stretch position keeping the neck stationary at all times. This will be your starting position.","With the hips stationary, flex the waist by contracting the abdominals and curl the shoulders and trunk upward until you feel a nice contraction on your abdominals. The arms should simply slide up the side of your legs if you have them at the side or just stay on top of your chest if you have them crossed. The lower back should always stay in contact with the ball. Exhale as you perform this movement and hold the contraction for a second.","As you inhale, go back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Exercise_Ball_Crunch/0.jpg","Exercise_Ball_Crunch/1.jpg"],"id":"Exercise_Ball_Crunch"}'),
('free-exercise-db', 'Exercise_Ball_Pull-In', 'exercise-ball-pull-in', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Exercise_Ball_Pull-In.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Exercise Ball Pull-In","force":"pull","level":"beginner","mechanic":"compound","equipment":"exercise ball","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Place an exercise ball nearby and lay on the floor in front of it with your hands on the floor shoulder width apart in a push-up position.","Now place your lower shins on top of an exercise ball. Tip: At this point your legs should be fully extended with the shins on top of the ball and the upper body should be in a push-up type of position being supported by your two extended arms in front of you. This will be your starting position.","While keeping your back completely straight and the upper body stationary, pull your knees in towards your chest as you exhale, allowing the ball to roll forward under your ankles. Squeeze your abs and hold that position for a second.","Now slowly straighten your legs, rolling the ball back to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Exercise_Ball_Pull-In/0.jpg","Exercise_Ball_Pull-In/1.jpg"],"id":"Exercise_Ball_Pull-In"}'),
('free-exercise-db', 'Extended_Range_One-Arm_Kettlebell_Floor_Press', 'kettlebell-extended-range-one-arm-floor-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Extended_Range_One-Arm_Kettlebell_Floor_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Extended Range One-Arm Kettlebell Floor Press","force":"push","level":"beginner","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["Lie on the floor and position a kettlebell for one arm to press. The kettlebell should be held by the handle. The leg on the same side that you are pressing should be bent, with the knee crossing over the midline of the body.","Press the kettlebell by extending the elbow and adducting the arm, pressing it above your body. Return to the starting position."],"category":"strength","images":["Extended_Range_One-Arm_Kettlebell_Floor_Press/0.jpg","Extended_Range_One-Arm_Kettlebell_Floor_Press/1.jpg"],"id":"Extended_Range_One-Arm_Kettlebell_Floor_Press"}'),
('free-exercise-db', 'External_Rotation', 'dumbbell-external-rotation', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/External_Rotation.json', 'Unlicense', NULL, 'new', NULL, '{"name":"External Rotation","force":"pull","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":[],"instructions":["Lie sideways on a flat bench with one arm holding a dumbbell and the other hand on top of the bench folded so that you can rest your head on it.","Bend the elbows of the arm holding the dumbbell so that it creates a 90-degree angle between the upper arm and the forearm. Tip: Keep the arm parallel to your torso.","Now bend the elbow while keeping the upper arm stationary. In this manner, the forearm will be parallel to the floor and perpendicular to your torso (Tip: So the forearm will be directly in front of you). The upper arm will be stationary by your torso and should be parallel to the floor (aligned with your torso at all times). This will be your starting position.","As you breathe out, externally rotate your forearm so that the dumbbell is lifted up in a semicircle motion as you maintain the 90 degree angle bend between the upper arms and the forearm. You will continue this external rotation until the forearm is perpendicular to the floor and the torso pointing towards the ceiling. At this point you will hold the contraction for a second.","As you breathe in, slowly go back to the starting position.","Repeat for the recommended amount of repetitions and then switch to the other arm."],"category":"strength","images":["External_Rotation/0.jpg","External_Rotation/1.jpg"],"id":"External_Rotation"}'),
('free-exercise-db', 'External_Rotation_with_Band', 'band-external-rotation', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/External_Rotation_with_Band.json', 'Unlicense', NULL, 'new', NULL, '{"name":"External Rotation with Band","force":"pull","level":"beginner","mechanic":"compound","equipment":"bands","primaryMuscles":["shoulders"],"secondaryMuscles":[],"instructions":["Choke the band around a post. The band should be at the same height as your elbow. Stand with your left side to the band a couple of feet away.","Grasp the end of the band with your right hand, and keep your elbow pressed firmly to your side. We recommend you hold a pad or foam roll in place with your elbow to keep it firmly in position.","With your upper arm in position, your elbow should be flexed to 90 degrees with your hand reaching across the front of your torso. This will be your starting position.","Execute the movement by rotating your arm in a backhand motion, keeping your elbow in place.","Continue as far as you are able, pause, and then return to the starting position."],"category":"strength","images":["External_Rotation_with_Band/0.jpg","External_Rotation_with_Band/1.jpg"],"id":"External_Rotation_with_Band"}'),
('free-exercise-db', 'External_Rotation_with_Cable', 'cable-external-rotation', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/External_Rotation_with_Cable.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"External Rotation with Cable","force":"pull","level":"beginner","mechanic":"isolation","equipment":"cable","primaryMuscles":["shoulders"],"secondaryMuscles":[],"instructions":["Adjust the cable to the same height as your elbow. Stand with your left side to the band a couple of feet away.","Grasp the handle with your right hand, and keep your elbow pressed firmly to your side. We recommend you hold a pad or foam roll in place with your elbow to keep it firmly in position.","With your upper arm in position, your elbow should be flexed to 90 degrees with your hand reaching across the front of your torso. This will be your starting position.","Execute the movement by rotating your arm in a backhand motion, keeping your elbow in place."],"category":"strength","images":["External_Rotation_with_Cable/0.jpg","External_Rotation_with_Cable/1.jpg"],"id":"External_Rotation_with_Cable"}'),
('free-exercise-db', 'Face_Pull', 'cable-face-pull', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Face_Pull.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Face Pull","force":"pull","level":"intermediate","mechanic":"compound","equipment":"cable","primaryMuscles":["shoulders"],"secondaryMuscles":["middle back"],"instructions":["Facing a high pulley with a rope or dual handles attached, pull the weight directly towards your face, separating your hands as you do so. Keep your upper arms parallel to the ground."],"category":"strength","images":["Face_Pull/0.jpg","Face_Pull/1.jpg"],"id":"Face_Pull"}'),
('free-exercise-db', 'Farmers_Walk', 'farmers-walk-2', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Farmers_Walk.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Farmer''s Walk","force":null,"level":"intermediate","mechanic":"compound","equipment":"other","primaryMuscles":["forearms"],"secondaryMuscles":["abdominals","glutes","hamstrings","lower back","quadriceps","traps"],"instructions":["There are various implements that can be used for the farmers walk. These can also be performed with heavy dumbbells or short bars if these implements aren''t available. Begin by standing between the implements.","After gripping the handles, lift them up by driving through your heels, keeping your back straight and your head up.","Walk taking short, quick steps, and don''t forget to breathe. Move for a given distance, typically 50-100 feet, as fast as possible."],"category":"strongman","images":["Farmers_Walk/0.jpg","Farmers_Walk/1.jpg"],"id":"Farmers_Walk"}'),
('free-exercise-db', 'Fast_Skipping', 'fast-skipping', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Fast_Skipping.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Fast Skipping","force":"push","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["quadriceps"],"secondaryMuscles":["abductors","adductors","calves","glutes","hamstrings"],"instructions":["Start in a relaxed position with one leg slightly forward. This will be your starting position.","Skip by executing a step-hop pattern of right-right-step to left-left-step, and so on, alternating back and forth.","Perform fast skips by maintaining close contact with the ground and reduce air time, moving as quickly as possible."],"category":"plyometrics","images":["Fast_Skipping/0.jpg","Fast_Skipping/1.jpg"],"id":"Fast_Skipping"}'),
('free-exercise-db', 'Finger_Curls', 'barbell-finger-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Finger_Curls.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Finger Curls","force":"pull","level":"beginner","mechanic":"isolation","equipment":"barbell","primaryMuscles":["forearms"],"secondaryMuscles":[],"instructions":["Hold a barbell with both hands and your palms facing up; hands spaced about shoulder width.","Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart. This will be your starting position.","Lower the bar as far as possible by extending the fingers. Allowing the bar to roll down the hands, catch the bar with the final joint in the fingers.","Now curl bar up as high as possible by closing your hands while exhaling. Hold the contraction at the top."],"category":"strength","images":["Finger_Curls/0.jpg","Finger_Curls/1.jpg"],"id":"Finger_Curls"}'),
('free-exercise-db', 'Flat_Bench_Cable_Flyes', 'cable-fly', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Flat_Bench_Cable_Flyes.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Flat Bench Cable Flyes","force":"push","level":"intermediate","mechanic":"isolation","equipment":"cable","primaryMuscles":["chest"],"secondaryMuscles":[],"instructions":["Position a flat bench between two low pulleys so that when you are laying on it, your chest will be lined up with the cable pulleys.","Lay flat on the bench and keep your feet on the ground.","Have someone hand you the handles on each hand. You will grab each single handle attachment with a palms up grip.","Extend your arms by your side with a slight bend on your elbows. Tip: You will keep this bend constant through the whole movement. Your arms should be parallel to the floor. This is your starting position.","Now start lifting the arms in a semi-circle motion directly in front of you by pulling the cables together until both hands meet at the top of the movement. Squeeze your chest as you perform this motion and breathe out during this movement. Also, hold the contraction for a second at the top. Tip: When performed correctly, at the top position of this movement, your arms should be perpendicular to your torso and the floor touching above your chest.","Slowly come back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Flat_Bench_Cable_Flyes/0.jpg","Flat_Bench_Cable_Flyes/1.jpg"],"id":"Flat_Bench_Cable_Flyes"}'),
('free-exercise-db', 'Flat_Bench_Leg_Pull-In', 'flat-bench-leg-pull-in', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Flat_Bench_Leg_Pull-In.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Flat Bench Leg Pull-In","force":"pull","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Lie on an exercise mat or a flat bench with your legs off the end.","Place your hands either under your glutes with your palms down or by the sides holding on to the bench (or with palms down by the side on an exercise mat). Also extend your legs straight out. This will be your starting position.","Bend your knees and pull your upper thighs into your midsection as you breathe out. Continue this movement until your knees are near your chest. Hold the contracted position for a second.","As you breathe in, slowly return to the starting position.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Flat_Bench_Leg_Pull-In/0.jpg","Flat_Bench_Leg_Pull-In/1.jpg"],"id":"Flat_Bench_Leg_Pull-In"}'),
('free-exercise-db', 'Flat_Bench_Lying_Leg_Raise', 'leg-raise-lying', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Flat_Bench_Lying_Leg_Raise.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Flat Bench Lying Leg Raise","force":"pull","level":"beginner","mechanic":"isolation","equipment":"body only","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Lie with your back flat on a bench and your legs extended in front of you off the end.","Place your hands either under your glutes with your palms down or by the sides holding on to the bench. This will be your starting position.","As you keep your legs extended, straight as possible with your knees slightly bent but locked raise your legs until they make a 90-degree angle with the floor. Exhale as you perform this portion of the movement and hold the contraction at the top for a second.","Now, as you inhale, slowly lower your legs back down to the starting position."],"category":"strength","images":["Flat_Bench_Lying_Leg_Raise/0.jpg","Flat_Bench_Lying_Leg_Raise/1.jpg"],"id":"Flat_Bench_Lying_Leg_Raise"}'),
('free-exercise-db', 'Flexor_Incline_Dumbbell_Curls', 'dumbbell-flexor-incline-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Flexor_Incline_Dumbbell_Curls.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Flexor Incline Dumbbell Curls","force":"pull","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["biceps"],"secondaryMuscles":[],"instructions":["Hold the dumbbell towards the side farther from you so that you have more weight on the side closest to you. (This can be done for a good effect on all bicep dumbbell exercises). Now do a normal incline dumbbell curl, but keep your wrists as far back as possible so as to neutralize any stress that is placed on them.","Sit on an incline bench that is angled at 45-degrees while holding a dumbbell on each hand.","Let your arms hang down on your sides, with the elbows in, and turn the palms of your hands forward with the thumbs pointing away from the body. Tip: You will keep this hand position throughout the movement as there should not be any twisting of the hands as they come up. This will be your starting position.","Curl up the two dumbbells at the same time until your biceps are fully contracted and exhale. Tip: Do not swing the arms or use momentum. Keep a controlled motion at all times. Hold the contracted position for a second at the top.","As you inhale, slowly go back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Flexor_Incline_Dumbbell_Curls/0.jpg","Flexor_Incline_Dumbbell_Curls/1.jpg"],"id":"Flexor_Incline_Dumbbell_Curls"}'),
('free-exercise-db', 'Floor_Glute-Ham_Raise', 'floor-glute-ham-raise', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Floor_Glute-Ham_Raise.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Floor Glute-Ham Raise","force":"pull","level":"intermediate","mechanic":"isolation","equipment":null,"primaryMuscles":["hamstrings"],"secondaryMuscles":["calves","glutes"],"instructions":["You can use a partner for this exercise or brace your feet under something stable.","Begin on your knees with your upper legs and torso upright. If using a partner, they will firmly hold your feet to keep you in position. This will be your starting position.","Lower yourself by extending at the knee, taking care to NOT flex the hips as you go forward.","Place your hands in front of you as you reach the floor. This movement is very difficult and you may be unable to do it unaided. Use your arms to lightly push off the floor to aid your return to the starting position."],"category":"strength","images":["Floor_Glute-Ham_Raise/0.jpg","Floor_Glute-Ham_Raise/1.jpg"],"id":"Floor_Glute-Ham_Raise"}'),
('free-exercise-db', 'Floor_Press', 'barbell-floor-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Floor_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Floor Press","force":"push","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["triceps"],"secondaryMuscles":["chest","shoulders"],"instructions":["Adjust the j-hooks so they are at the appropriate height to rack the bar. Begin lying on the floor with your head near the end of a power rack. Keeping your shoulder blades pulled together; pull the bar off of the hooks.","Lower the bar towards the bottom of your chest or upper stomach, squeezing the bar and attempting to pull it apart as you do so. Ensure that you tuck your elbows throughout the movement. Lower the bar until your upper arm contacts the ground and pause, preventing any slamming or bouncing of the weight.","Press the bar back up as fast as you can, keeping the bar, your wrists, and elbows in line as you do so."],"category":"powerlifting","images":["Floor_Press/0.jpg","Floor_Press/1.jpg"],"id":"Floor_Press"}'),
('free-exercise-db', 'Floor_Press_with_Chains', 'barbell-floor-press-chains', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Floor_Press_with_Chains.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Floor Press with Chains","force":"push","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["triceps"],"secondaryMuscles":["chest","shoulders"],"instructions":["Adjust the j-hooks so they are at the appropriate height to rack the bar. For this exercise, drape the chains directly over the end of the bar, trying to keep the ends away from the plates.","Begin lying on the floor with your head near the end of a power rack. Keeping your shoulder blades pulled together, pull the bar off of the hooks.","Lower the bar towards the bottom of your chest or upper stomach, squeezing the bar and attempting to pull it apart as you do so. Ensure that you tuck your elbows throughout the movement. Lower the bar until your upper arm contacts the ground and pause, preventing any slamming or bouncing of the weight.","Press the bar back up as fast as you can, keeping the bar, your wrists, and elbows in line as you do so."],"category":"powerlifting","images":["Floor_Press_with_Chains/0.jpg","Floor_Press_with_Chains/1.jpg"],"id":"Floor_Press_with_Chains"}'),
('free-exercise-db', 'Flutter_Kicks', 'flutter-kick-2', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Flutter_Kicks.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Flutter Kicks","force":"pull","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["glutes"],"secondaryMuscles":["hamstrings"],"instructions":["On a flat bench lie facedown with the hips on the edge of the bench, the legs straight with toes high off the floor and with the arms on top of the bench holding on to the front edge.","Squeeze your glutes and hamstrings and straighten the legs until they are level with the hips. This will be your starting position.","Start the movement by lifting the left leg higher than the right leg.","Then lower the left leg as you lift the right leg.","Continue alternating in this manner (as though you are doing a flutter kick in water) until you have done the recommended amount of repetitions for each leg. Make sure that you keep a controlled movement at all times. Tip: You will breathe normally as you perform this movement."],"category":"strength","images":["Flutter_Kicks/0.jpg","Flutter_Kicks/1.jpg"],"id":"Flutter_Kicks"}'),
('free-exercise-db', 'Foot-SMR', 'foot-smr', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Foot-SMR.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Foot-SMR","force":"static","level":"intermediate","mechanic":null,"equipment":"other","primaryMuscles":["calves"],"secondaryMuscles":[],"instructions":["This exercise stretches the fascia of the muscles in the feet. Start off seated with your shoes removed. Using a foot roller or a similar object, such as a small section of pvc pipe, place your foot against the roller across the arch of your foot. This will be your starting position.","Press down firmly, rolling across the arch of your foot. Hold for 10-30 seconds, and then switch feet."],"category":"stretching","images":["Foot-SMR/0.jpg","Foot-SMR/1.jpg"],"id":"Foot-SMR"}'),
('free-exercise-db', 'Forward_Drag_with_Press', 'forward-drag-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Forward_Drag_with_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Forward Drag with Press","force":"push","level":"intermediate","mechanic":"compound","equipment":"other","primaryMuscles":["chest"],"secondaryMuscles":["calves","glutes","hamstrings","quadriceps","shoulders","triceps"],"instructions":["Attach a dual handled chain or rope attachment to the sled. You should be facing away from the sled, holding a handle in each hand.","Begin the movement by moving forward for one step. Leaning forward, extend through the legs and hips to move, pausing with each step to extend through the elbows, pressing your hands forward. Step forward until you return to the start position prepared to press."],"category":"strongman","images":["Forward_Drag_with_Press/0.jpg","Forward_Drag_with_Press/1.jpg"],"id":"Forward_Drag_with_Press"}'),
('free-exercise-db', 'Frankenstein_Squat', 'barbell-frankenstein-squat', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Frankenstein_Squat.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Frankenstein Squat","force":"push","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["abdominals","calves","glutes","hamstrings"],"instructions":["This drill teaches you the proper positioning of both the bar and your body during the clean and front squat.","Place the barbell on the front of the shoulders, releasing your grip and extending your arms out in front of you. The shoulders should be pushed forward to create a shelf, and the bar should be in contact with the throat. Ensure that you only move your shoulder blades forward; don''t round the thoracic spine.","Squat by flexing the knees and hips, sitting in between your legs. Keep the torso upright, the arms up, and the shoulders forward, and the bar should stay in place. Go to the bottom of the squat, until your hamstrings contact your calves.","Return to the upright position by driving through the front of the heel and extending the knees and hips."],"category":"olympic weightlifting","images":["Frankenstein_Squat/0.jpg","Frankenstein_Squat/1.jpg"],"id":"Frankenstein_Squat"}'),
('free-exercise-db', 'Freehand_Jump_Squat', 'freehand-jump-squat', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Freehand_Jump_Squat.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Freehand Jump Squat","force":"push","level":"intermediate","mechanic":"compound","equipment":"body only","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings"],"instructions":["Cross your arms over your chest.","With your head up and your back straight, position your feet at shoulder width.","Keeping your back straight and chest up, squat down as you inhale until your upper thighs are parallel, or lower, to the floor.","Now pressing mainly with the ball of your feet, jump straight up in the air as high as possible, using the thighs like springs. Exhale during this portion of the movement.","When you touch the floor again, immediately squat down and jump again.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Freehand_Jump_Squat/0.jpg","Freehand_Jump_Squat/1.jpg"],"id":"Freehand_Jump_Squat"}'),
('free-exercise-db', 'Frog_Hops', 'frog-hop', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Frog_Hops.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Frog Hops","force":"push","level":"intermediate","mechanic":"compound","equipment":null,"primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings"],"instructions":["Stand with your hands behind your head, and squat down keeping your torso upright and your head up. This will be your starting position.","Jump forward several feet, avoiding jumping unnecessarily high. As your feet contact the ground, absorb the impact through your legs, and jump again. Repeat this action 5-10 times."],"category":"stretching","images":["Frog_Hops/0.jpg","Frog_Hops/1.jpg"],"id":"Frog_Hops"}'),
('free-exercise-db', 'Frog_Sit-Ups', 'frog-sit-up', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Frog_Sit-Ups.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Frog Sit-Ups","force":"pull","level":"intermediate","mechanic":"isolation","equipment":"body only","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Lie with your back flat on the floor (or exercise mat) and your legs extended in front of you.","Now bend at the knees and place your outer thighs by the floor (or mat) as you make the soles of your feet touch each other.","Now try pushing both soles and bringing them up as near you as possible while you keep the outer thighs on the floor (or at least almost touching it). Tip: In this position your legs should create a diamond shape.","Now, cross your arms in front of you by touching the opposite shoulders. This will be your starting position.","As you exhale flatten your lower back to the floor while curling the torso upwards. Tip: This will be like performing the first 1/4 movement of a sit up. Hold at the top position for a second.","As you inhale, slowly lower back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Frog_Sit-Ups/0.jpg","Frog_Sit-Ups/1.jpg"],"id":"Frog_Sit-Ups"}'),
('free-exercise-db', 'Front_Barbell_Squat', 'barbell-front-squat', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Front_Barbell_Squat.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Front Barbell Squat","force":"push","level":"expert","mechanic":"compound","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings"],"instructions":["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, bring your arms up under the bar while keeping the elbows high and the upper arm slightly above parallel to the floor. Rest the bar on top of the deltoids and cross your arms while grasping the bar for total control.","Lift the bar off the rack by first pushing with your legs and at the same time straightening your torso.","Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).","Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise the bar as you exhale by pushing the floor mainly with the middle of your foot as you straighten the legs again and go back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Front_Barbell_Squat/0.jpg","Front_Barbell_Squat/1.jpg"],"id":"Front_Barbell_Squat"}'),
('free-exercise-db', 'Front_Barbell_Squat_To_A_Bench', 'barbell-front-squat-to-bench', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Front_Barbell_Squat_To_A_Bench.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Front Barbell Squat To A Bench","force":"push","level":"expert","mechanic":"compound","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings"],"instructions":["This exercise is best performed inside a squat rack for safety purposes. To begin, first set a flat bench behind you and set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, bring your arms up under the bar while keeping the elbows high and the upper arm slightly above parallel to the floor. Rest the bar on top of the deltoids and cross your arms while grasping the bar for total control.","Lift the bar off the rack by first pushing with your legs and at the same time straightening your torso.","Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).","Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until you touch the bench with your glutes. Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise the bar as you exhale by pushing the floor mainly with the heel of your foot as you straighten the legs again and go back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Front_Barbell_Squat_To_A_Bench/0.jpg","Front_Barbell_Squat_To_A_Bench/1.jpg"],"id":"Front_Barbell_Squat_To_A_Bench"}'),
('free-exercise-db', 'Front_Box_Jump', 'front-box-jump', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Front_Box_Jump.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Front Box Jump","force":"push","level":"beginner","mechanic":"compound","equipment":"other","primaryMuscles":["hamstrings"],"secondaryMuscles":["abductors","adductors","calves","glutes","quadriceps"],"instructions":["Begin with a box of an appropriate height 1-2 feet in front of you. Stand with your feet should width apart. This will be your starting position.","Perform a short squat in preparation for jumping, swinging your arms behind you.","Rebound out of this position, extending through the hips, knees, and ankles to jump as high as possible. Swing your arms forward and up.","Land on the box with the knees bent, absorbing the impact through the legs. You can jump from the box back to the ground, or preferably step down one leg at a time."],"category":"plyometrics","images":["Front_Box_Jump/0.jpg","Front_Box_Jump/1.jpg"],"id":"Front_Box_Jump"}'),
('free-exercise-db', 'Front_Cable_Raise', 'cable-front-raise', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Front_Cable_Raise.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Front Cable Raise","force":"push","level":"beginner","mechanic":"isolation","equipment":"cable","primaryMuscles":["shoulders"],"secondaryMuscles":[],"instructions":["Select the weight on a low pulley machine and grasp the single hand cable attachment that is attached to the low pulley with your left hand.","Face away from the pulley and put your arm straight down with the hand cable attachment in front of your thighs at arms'' length with the palms of the hand facing your thighs. This will be your starting position.","While maintaining the torso stationary (no swinging), lift the left arm to the front with a slight bend on the elbow and the palms of the hand always faces down. Continue to go up until you arm is slightly above parallel to the floor. Exhale as you execute this portion of the movement and pause for a second at the top.","Now as you inhale lower the arm back down slowly to the starting position.","Once all of the recommended amount of repetitions have been performed for this arm, switch arms and perform the exercise with the right one."],"category":"strength","images":["Front_Cable_Raise/0.jpg","Front_Cable_Raise/1.jpg"],"id":"Front_Cable_Raise"}'),
('free-exercise-db', 'Front_Cone_Hops_or_hurdle_hops', 'front-cone-hop-or-hurdle', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Front_Cone_Hops_or_hurdle_hops.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Front Cone Hops (or hurdle hops)","force":"push","level":"beginner","mechanic":"compound","equipment":"other","primaryMuscles":["quadriceps"],"secondaryMuscles":["abductors","adductors","calves","glutes","hamstrings"],"instructions":["Set up a row of cones or other small barriers, placing them a few feet apart.","Stand in front of the first cone with your feet shoulder width apart. This will be your starting position.","Begin by jumping with both feet over the first cone, swinging both arms as you jump.","Absorb the impact of landing by bending the knees, rebounding out of the first leap by jumping over the next cone.","Continue until you have jumped over all of the cones."],"category":"plyometrics","images":["Front_Cone_Hops_or_hurdle_hops/0.jpg","Front_Cone_Hops_or_hurdle_hops/1.jpg"],"id":"Front_Cone_Hops_or_hurdle_hops"}'),
('free-exercise-db', 'Front_Dumbbell_Raise', 'dumbbell-front-raise', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Front_Dumbbell_Raise.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Front Dumbbell Raise","force":"push","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":[],"instructions":["Pick a couple of dumbbells and stand with a straight torso and the dumbbells on front of your thighs at arms length with the palms of the hand facing your thighs. This will be your starting position.","While maintaining the torso stationary (no swinging), lift the left dumbbell to the front with a slight bend on the elbow and the palms of the hands always facing down. Continue to go up until you arm is slightly above parallel to the floor. Exhale as you execute this portion of the movement and pause for a second at the top. Inhale after the second pause.","Now lower the dumbbell back down slowly to the starting position as you simultaneously lift the right dumbbell.","Continue alternating in this fashion until all of the recommended amount of repetitions have been performed for each arm."],"category":"strength","images":["Front_Dumbbell_Raise/0.jpg","Front_Dumbbell_Raise/1.jpg"],"id":"Front_Dumbbell_Raise"}'),
('free-exercise-db', 'Front_Incline_Dumbbell_Raise', 'dumbbell-front-incline-raise', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Front_Incline_Dumbbell_Raise.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Front Incline Dumbbell Raise","force":"push","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":[],"instructions":["Sit down on an incline bench with the incline set anywhere between 30 to 60 degrees while holding a dumbbell on each hand. Tip: You can change the angle to hit the muscle a little differently each time.","Extend your arms straight in front of you and have your palms facing down with the dumbbells raised about 1 inch above your thighs. This will be your starting position.","Slowly raise the dumbbells straight up until they are slightly above your shoulders, while keeping your elbows locked. Squeeze at the top for a second and make sure you breathe out during this portion of the movement. Tip: Keep your head resting down against the bench and your legs on the floor at all times.","Lower the arms back to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Front_Incline_Dumbbell_Raise/0.jpg","Front_Incline_Dumbbell_Raise/1.jpg"],"id":"Front_Incline_Dumbbell_Raise"}'),
('free-exercise-db', 'Front_Leg_Raises', 'front-leg-raise', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Front_Leg_Raises.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Front Leg Raises","force":"pull","level":"beginner","mechanic":null,"equipment":"body only","primaryMuscles":["hamstrings"],"secondaryMuscles":[],"instructions":["Stand next to a chair or other support, holding on with one hand.","Swing your leg forward, keeping the leg straight. Continue with a downward swing, bringing the leg as far back as your flexibility allows. Repeat 5-10 times, and then switch legs."],"category":"stretching","images":["Front_Leg_Raises/0.jpg","Front_Leg_Raises/1.jpg"],"id":"Front_Leg_Raises"}'),
('free-exercise-db', 'Front_Plate_Raise', 'plate-front-raise', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Front_Plate_Raise.json', 'Unlicense', NULL, 'exact', 100.0, '{"name":"Front Plate Raise","force":"push","level":"intermediate","mechanic":"isolation","equipment":"other","primaryMuscles":["shoulders"],"secondaryMuscles":[],"instructions":["While standing straight, hold a barbell plate in both hands at the 3 and 9 o''clock positions. Your palms should be facing each other and your arms should be extended and locked with a slight bend at the elbows and the plate should be down near your waist in front of you as far as you can go. Tip: The arms will remain in this position throughout the exercise. This will be your starting position.","Slowly raise the plate as you exhale until it is a little above shoulder level. Hold the contraction for a second. Tip: make sure that you do not swing the weight or bend at the elbows. Your torso should remain stationary throughout the movement as well.","As you inhale, slowly lower the plate back down to the starting position.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Front_Plate_Raise/0.jpg","Front_Plate_Raise/1.jpg"],"id":"Front_Plate_Raise"}'),
('free-exercise-db', 'Front_Raise_And_Pullover', 'barbell-front-raise-and-pullover', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Front_Raise_And_Pullover.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Front Raise And Pullover","force":"pull","level":"beginner","mechanic":"compound","equipment":"barbell","primaryMuscles":["chest"],"secondaryMuscles":["lats","shoulders","triceps"],"instructions":["Lie on a flat bench while holding a barbell using a palms down grip that is about 15 inches apart.","Place the bar on your upper thighs, extend your arms and lock them while keeping a slight bend on the elbows. This will be your starting position.","Now raise the weight using a semicircular motion and keeping your arms straight as you inhale. Continue the same movement until the bar is on the other side above your head . (Tip: the bar will travel approximately 180-degrees). At this point your arms should be parallel to the floor with the palms of your hands facing the ceiling.","Now return the barbell to the starting position by reversing the motion as you exhale.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Front_Raise_And_Pullover/0.jpg","Front_Raise_And_Pullover/1.jpg"],"id":"Front_Raise_And_Pullover"}'),
('free-exercise-db', 'Front_Squat_Clean_Grip', 'barbell-front-squat-clean-grip', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Front_Squat_Clean_Grip.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Front Squat (Clean Grip)","force":"push","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["abdominals","glutes","hamstrings"],"instructions":["To begin, first set the bar in a rack slightly below shoulder level. Rest the bar on top of the deltoids, pushing into the clavicles, and lightly touching the throat. Your hands should be in a clean grip, touching the bar only with your fingers to help keep it in position.","Lift the bar off the rack by first pushing with your legs and at the same time straightening your torso. Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head and elbows up at all times. This will be your starting position.","Bend at the knees, sitting down between your legs. Continue down until your hamstrings are on your calves. Keep your knees aligned with your feet by consciously using your abductors to push your knees out as you squat.","Begin to raise the bar as you exhale by pushing the floor mainly with the heel or middle of your foot as you straighten the legs again and return to the starting position."],"category":"strength","images":["Front_Squat_Clean_Grip/0.jpg","Front_Squat_Clean_Grip/1.jpg"],"id":"Front_Squat_Clean_Grip"}'),
('free-exercise-db', 'Front_Squats_With_Two_Kettlebells', 'kettlebell-front-squat-two', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Front_Squats_With_Two_Kettlebells.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Front Squats With Two Kettlebells","force":"push","level":"intermediate","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes"],"instructions":["Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so.","Looking straight ahead at all times, squat as low as you can and pause at the bottom. As you squat down, push your knees out. You should squat between your legs, keeping an upright torso, with your head and chest up.","Rise back up by driving through your heels and repeat."],"category":"strength","images":["Front_Squats_With_Two_Kettlebells/0.jpg","Front_Squats_With_Two_Kettlebells/1.jpg"],"id":"Front_Squats_With_Two_Kettlebells"}'),
('free-exercise-db', 'Front_Two-Dumbbell_Raise', 'dumbbell-front-two-raise', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Front_Two-Dumbbell_Raise.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Front Two-Dumbbell Raise","force":"push","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":[],"instructions":["Pick a couple of dumbbells and stand with a straight torso and the dumbbells on front of your thighs at arms length with the palms of the hand facing your thighs. This will be your starting position.","While maintaining the torso stationary (no swinging), lift the dumbbells to the front with a slight bend on the elbow and the palms of the hands always facing down. Continue to go up until you arms are slightly above parallel to the floor. Exhale as you execute this portion of the movement and pause for a second at the top.","As you inhale, lower the dumbbells back down slowly to the starting position.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Front_Two-Dumbbell_Raise/0.jpg","Front_Two-Dumbbell_Raise/1.jpg"],"id":"Front_Two-Dumbbell_Raise"}'),
('free-exercise-db', 'Full_Range-Of-Motion_Lat_Pulldown', 'cable-full-range-motion-lat-pulldown', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Full_Range-Of-Motion_Lat_Pulldown.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Full Range-Of-Motion Lat Pulldown","force":"pull","level":"intermediate","mechanic":"compound","equipment":"cable","primaryMuscles":["lats"],"secondaryMuscles":["biceps","middle back","shoulders"],"instructions":["Either standing or seated on a high bench, grasp two stirrup cables that are attached to the high pulleys. Grab with the opposing hand so your arms are crisscrossed about you and your palms are facing forward.","Keeping your chest up and maintaining a slight arch in your lower back, pull the handles down as if you were doing a regular pulldown. The range of motion will be more of an arc. During the movement, rotate your hands so that in the bottom position your palms face each other rather than forward. Return slowly to the starting position and repeat."],"category":"strength","images":["Full_Range-Of-Motion_Lat_Pulldown/0.jpg","Full_Range-Of-Motion_Lat_Pulldown/1.jpg"],"id":"Full_Range-Of-Motion_Lat_Pulldown"}'),
('free-exercise-db', 'Gironda_Sternum_Chins', 'gironda-sternum-chins', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Gironda_Sternum_Chins.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Gironda Sternum Chins","force":"pull","level":"intermediate","mechanic":"compound","equipment":"other","primaryMuscles":["lats"],"secondaryMuscles":["biceps","middle back"],"instructions":["Grasp the pull-up bar with a shoulder width underhand grip.","Now hang with your arms fully extended and stick your chest out and lean back. Tip: You will be leaning back throughout the entire movement. This will be your starting position.","Start pulling yourself towards the bar with your spine arched throughout the movement and your head leaning back as far away from the bar as possible. Exhale as you perform this portion of the movement. Tip: At the upper end of the movement, your hips and legs will be at about a 45-degree angle to the floor.","Keep pulling until your collarbone passes the bar and your lower chest or sternum area touches it. Hold that contraction for a second. Tip: By the time you''ve completed this portion of the movement; your head will be parallel to the floor.","Slowly start going back to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Gironda_Sternum_Chins/0.jpg","Gironda_Sternum_Chins/1.jpg"],"id":"Gironda_Sternum_Chins"}'),
('free-exercise-db', 'Glute_Ham_Raise', 'machine-glute-ham-raise', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Glute_Ham_Raise.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Glute Ham Raise","force":"pull","level":"intermediate","mechanic":"compound","equipment":"machine","primaryMuscles":["hamstrings"],"secondaryMuscles":["calves","glutes"],"instructions":["Begin by adjusting the equipment to fit your body. Place your feet against the footplate in between the rollers as you lie facedown. Your knees should be just behind the pad.","Start from the bottom of the movement. Keep your back arched as you begin the movement by flexing the knees. Drive your toes into the foot plate as you do so. Keep your upper body straight, and continue until your body is upright.","Return to the starting position, keeping your descent under control."],"category":"powerlifting","images":["Glute_Ham_Raise/0.jpg","Glute_Ham_Raise/1.jpg"],"id":"Glute_Ham_Raise"}'),
('free-exercise-db', 'Glute_Kickback', 'glute-kickback', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Glute_Kickback.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Glute Kickback","force":"push","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["glutes"],"secondaryMuscles":["hamstrings"],"instructions":["Kneel on the floor or an exercise mat and bend at the waist with your arms extended in front of you (perpendicular to the torso) in order to get into a kneeling push-up position but with the arms spaced at shoulder width. Your head should be looking forward and the bend of the knees should create a 90-degree angle between the hamstrings and the calves. This will be your starting position.","As you exhale, lift up your right leg until the hamstrings are in line with the back while maintaining the 90-degree angle bend. Contract the glutes throughout this movement and hold the contraction at the top for a second. Tip: At the end of the movement the upper leg should be parallel to the floor while the calf should be perpendicular to it.","Go back to the initial position as you inhale and now repeat with the left leg.","Continue to alternate legs until all of the recommended repetitions have been performed."],"category":"strength","images":["Glute_Kickback/0.jpg","Glute_Kickback/1.jpg"],"id":"Glute_Kickback"}'),
('free-exercise-db', 'Goblet_Squat', 'kettlebell-goblet-squat', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Goblet_Squat.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Goblet Squat","force":"push","level":"beginner","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings","shoulders"],"instructions":["Stand holding a light kettlebell by the horns close to your chest. This will be your starting position.","Squat down between your legs until your hamstrings are on your calves. Keep your chest and head up and your back straight.","At the bottom position, pause and use your elbows to push your knees out. Return to the starting position, and repeat for 10-20 repetitions."],"category":"strength","images":["Goblet_Squat/0.jpg","Goblet_Squat/1.jpg"],"id":"Goblet_Squat"}'),
('free-exercise-db', 'Good_Morning', 'barbell-good-morning', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Good_Morning.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Good Morning","force":"push","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["hamstrings"],"secondaryMuscles":["abdominals","glutes","lower back"],"instructions":["Begin with a bar on a rack at shoulder height. Rack the bar across the rear of your shoulders as you would a power squat, not on top of your shoulders. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Step back from the rack.","Begin by bending at the hips, moving them back as you bend over to near parallel. Keep your back arched and your cervical spine in proper alignment.","Reverse the motion by extending through the hips with your glutes and hamstrings. Continue until you have returned to the starting position."],"category":"powerlifting","images":["Good_Morning/0.jpg","Good_Morning/1.jpg"],"id":"Good_Morning"}'),
('free-exercise-db', 'Good_Morning_off_Pins', 'barbell-good-morning-off-pins', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Good_Morning_off_Pins.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Good Morning off Pins","force":"push","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["hamstrings"],"secondaryMuscles":["abdominals","glutes","lower back"],"instructions":["Begin with a bar on a rack at about the same height as your stomach. Bend over underneath the bar and rack the bar across the rear of your shoulders as you would a power squat, not on top of your shoulders. At the proper height, you should be near parallel to the floor when bent over. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Keep your back arched and your cervical spine in proper alignment.","Begin the motion by extending through the hips with your glutes and hamstrings, and you are standing with the weight. Slowly lower the weight back to the pins returning to the starting position."],"category":"powerlifting","images":["Good_Morning_off_Pins/0.jpg","Good_Morning_off_Pins/1.jpg"],"id":"Good_Morning_off_Pins"}'),
('free-exercise-db', 'Gorilla_Chin_Crunch', 'gorilla-chin-crunch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Gorilla_Chin_Crunch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Gorilla Chin/Crunch","force":"pull","level":"intermediate","mechanic":"compound","equipment":"body only","primaryMuscles":["abdominals"],"secondaryMuscles":["biceps","lats"],"instructions":["Hang from a chin-up bar using an underhand grip (palms facing you) that is slightly wider than shoulder width.","Now bend your knees at a 90 degree angle so that the calves are parallel to the floor while the thighs remain perpendicular to it. This will be your starting position.","As you exhale, pull yourself up while crunching your knees up at the same time until your knees are at chest level. You will stop going up as soon as your nose is at the same level as the bar. Tip: When you get to this point you should also be finishing the crunch at the same time.","Slowly start to inhale as you return to the starting position.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Gorilla_Chin_Crunch/0.jpg","Gorilla_Chin_Crunch/1.jpg"],"id":"Gorilla_Chin_Crunch"}'),
('free-exercise-db', 'Groin_and_Back_Stretch', 'groin-and-back-stretch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Groin_and_Back_Stretch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Groin and Back Stretch","force":"static","level":"intermediate","mechanic":"compound","equipment":null,"primaryMuscles":["adductors"],"secondaryMuscles":[],"instructions":["Sit on the floor with your knees bent and feet together.","Interlock your fingers behind your head. This will be your starting position.","Curl downwards, bringing your elbows to the inside of your thighs. After a brief pause, return to the starting position with your head up and your back straight. Repeat for 10-20 repetitions."],"category":"stretching","images":["Groin_and_Back_Stretch/0.jpg","Groin_and_Back_Stretch/1.jpg"],"id":"Groin_and_Back_Stretch"}'),
('free-exercise-db', 'Groiners', 'groiners', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Groiners.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Groiners","force":"pull","level":"intermediate","mechanic":"compound","equipment":"body only","primaryMuscles":["adductors"],"secondaryMuscles":[],"instructions":["Begin in a pushup position on the floor. This will be your starting position.","Using both legs, jump forward landing with your feet next to your hands. Keep your head up as you do so.","Return to the starting position and immediately repeat the movement, continuing for 10-20 repetitions."],"category":"stretching","images":["Groiners/0.jpg","Groiners/1.jpg"],"id":"Groiners"}'),
('free-exercise-db', 'Hack_Squat', 'machine-hack-squat', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Hack_Squat.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Hack Squat","force":"push","level":"beginner","mechanic":"compound","equipment":"machine","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings"],"instructions":["Place the back of your torso against the back pad of the machine and hook your shoulders under the shoulder pads provided.","Position your legs in the platform using a shoulder width medium stance with the toes slightly pointed out. Tip: Keep your head up at all times and also maintain the back on the pad at all times.","Place your arms on the side handles of the machine and disengage the safety bars (which on most designs is done by moving the side handles from a facing front position to a diagonal position).","Now straighten your legs without locking the knees. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).","Begin to slowly lower the unit by bending the knees as you maintain a straight posture with the head up (back on the pad at all times). Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise the unit as you exhale by pushing the floor with mainly with the heel of your foot as you straighten the legs again and go back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Hack_Squat/0.jpg","Hack_Squat/1.jpg"],"id":"Hack_Squat"}'),
('free-exercise-db', 'Hammer_Curls', 'dumbbell-hammer-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Hammer_Curls.json', 'Unlicense', NULL, 'exact', 100.0, '{"name":"Hammer Curls","force":"pull","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["biceps"],"secondaryMuscles":[],"instructions":["Stand up with your torso upright and a dumbbell on each hand being held at arms length. The elbows should be close to the torso.","The palms of the hands should be facing your torso. This will be your starting position.","Now, while holding your upper arm stationary, exhale and curl the weight forward while contracting the biceps. Continue to raise the weight until the biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a brief moment as you squeeze the biceps. Tip: Focus on keeping the elbow stationary and only moving your forearm.","After the brief pause, inhale and slowly begin the lower the dumbbells back down to the starting position.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Hammer_Curls/0.jpg","Hammer_Curls/1.jpg"],"id":"Hammer_Curls"}'),
('free-exercise-db', 'Hammer_Grip_Incline_DB_Bench_Press', 'dumbbell-hammer-grip-incline-bench-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Hammer_Grip_Incline_DB_Bench_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Hammer Grip Incline DB Bench Press","force":"push","level":"beginner","mechanic":"compound","equipment":"dumbbell","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["Lie back on an incline bench with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.","By using your thighs to help you get the dumbbells up, clean the dumbbells one arm at a time so that you can hold them at shoulder width.","Once at shoulder width, keep the palms of your hands with a neutral grip (palms facing each other). Keep your elbows flared out with the upper arms in line with the shoulders (perpendicular to the torso) and the elbows bent creating a 90-degree angle between the upper arm and the forearm. This will be your starting position.","Now bring down the weights slowly to your side as you breathe in. Keep full control of the dumbbells at all times.","As you breathe out, push the dumbbells up using your pectoral muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the dumbbells back in your thighs and then on the floor. This is the safest manner to dispose of the dumbbells."],"category":"strength","images":["Hammer_Grip_Incline_DB_Bench_Press/0.jpg","Hammer_Grip_Incline_DB_Bench_Press/1.jpg"],"id":"Hammer_Grip_Incline_DB_Bench_Press"}'),
('free-exercise-db', 'Hamstring-SMR', 'foam-roller-hamstring-smr', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Hamstring-SMR.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Hamstring-SMR","force":"static","level":"beginner","mechanic":"isolation","equipment":"foam roll","primaryMuscles":["hamstrings"],"secondaryMuscles":[],"instructions":["In a seated position, extend your legs over a foam roll so that it is position on the back of the upper legs. Place your hands to the side or behind you to help support your weight. This will be your starting position.","Using your hands, lift your hips off of the floor and shift your weight on the foam roll to one leg. Relax the hamstrings of the leg you are stretching.","Roll over the foam from below the hip to above the back of the knee, pausing at points of tension for 10-30 seconds. Repeat for the other leg."],"category":"stretching","images":["Hamstring-SMR/0.jpg","Hamstring-SMR/1.jpg"],"id":"Hamstring-SMR"}'),
('free-exercise-db', 'Hamstring_Stretch', 'hamstring-stretch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Hamstring_Stretch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Hamstring Stretch","force":"static","level":"beginner","mechanic":"isolation","equipment":null,"primaryMuscles":["hamstrings"],"secondaryMuscles":[],"instructions":["Lie on your back with one leg extended above you, with the hip at ninety degrees. Keep the other leg flat on the floor.","Loop a belt, band, or rope over the ball of your foot. This will be your starting position.","Pull on the belt to create tension in the calves and hamstrings. Hold this stretch for 10-30 seconds, and repeat with the other leg."],"category":"stretching","images":["Hamstring_Stretch/0.jpg","Hamstring_Stretch/1.jpg"],"id":"Hamstring_Stretch"}'),
('free-exercise-db', 'Handstand_Push-Ups', 'handstand-pushup', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Handstand_Push-Ups.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Handstand Push-Ups","force":"push","level":"expert","mechanic":"compound","equipment":"body only","primaryMuscles":["shoulders"],"secondaryMuscles":["triceps"],"instructions":["With your back to the wall bend at the waist and place both hands on the floor at shoulder width.","Kick yourself up against the wall with your arms straight. Your body should be upside down with the arms and legs fully extended. Keep your whole body as straight as possible. Tip: If doing this for the first time, have a spotter help you. Also, make sure that you keep facing the wall with your head, rather than looking down.","Slowly lower yourself to the ground as you inhale until your head almost touches the floor. Tip: It is of utmost importance that you come down slow in order to avoid head injury.","Push yourself back up slowly as you exhale until your elbows are nearly locked.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Handstand_Push-Ups/0.jpg","Handstand_Push-Ups/1.jpg"],"id":"Handstand_Push-Ups"}'),
('free-exercise-db', 'Hang_Clean', 'barbell-hang-clean', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Hang_Clean.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Hang Clean","force":"pull","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","forearms","glutes","hamstrings","lower back","shoulders","traps"],"instructions":["Begin with a shoulder width, double overhand or hook grip, with the bar hanging at the mid thigh position. Your back should be straight and inclined slightly forward.","Begin by aggressively extending through the hips, knees and ankles, driving the weight upward. As you do so, shrug your shoulders towards your ears.","Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position."],"category":"olympic weightlifting","images":["Hang_Clean/0.jpg","Hang_Clean/1.jpg"],"id":"Hang_Clean"}'),
('free-exercise-db', 'Hang_Clean_-_Below_the_Knees', 'barbell-hang-clean-below-knees', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Hang_Clean_-_Below_the_Knees.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Hang Clean - Below the Knees","force":"pull","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","forearms","glutes","hamstrings","lower back","shoulders","traps"],"instructions":["Begin with a shoulder width, double overhand or hook grip, with the bar hanging just below the knees. Your back should be straight and inclined slightly forward.","Begin by aggressively extending through the hips, knees and ankles, driving the weight upward. As you do so, shrug your shoulders towards your ears. As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out.","At peak extension, aggressively pull yourself down, rotating your elbows under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery.","Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position."],"category":"olympic weightlifting","images":["Hang_Clean_-_Below_the_Knees/0.jpg","Hang_Clean_-_Below_the_Knees/1.jpg"],"id":"Hang_Clean_-_Below_the_Knees"}'),
('free-exercise-db', 'Hang_Snatch', 'barbell-hang-snatch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Hang_Snatch.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Hang Snatch","force":"pull","level":"expert","mechanic":"compound","equipment":"barbell","primaryMuscles":["hamstrings"],"secondaryMuscles":["abdominals","calves","forearms","glutes","lower back","quadriceps","shoulders","traps"],"instructions":["Begin with a wide grip on the bar, with an overhand or hook grip. The feet should be directly below the hips with the feet turned out. Your knees should be slightly bent, and the torso inclined forward. The spine should be fully extended and the head facing forward. The bar should be at the hips. This will be your starting position.","Aggressively extend through the legs and hips. At peak extension, shrug the shoulders and allow the elbows to flex to the side.","As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. Receive the bar with your body as low as possible and the arms fully extended overhead.","Return to a standing position with the weight overhead. Follow by returning the weight to the ground under control."],"category":"olympic weightlifting","images":["Hang_Snatch/0.jpg","Hang_Snatch/1.jpg"],"id":"Hang_Snatch"}'),
('free-exercise-db', 'Hang_Snatch_-_Below_Knees', 'barbell-hang-snatch-below-knees', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Hang_Snatch_-_Below_Knees.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Hang Snatch - Below Knees","force":"pull","level":"expert","mechanic":"compound","equipment":"barbell","primaryMuscles":["hamstrings"],"secondaryMuscles":["abdominals","calves","forearms","glutes","lower back","quadriceps","shoulders","traps"],"instructions":["Begin with a wide grip on the bar, with an overhand or hook grip. The feet should be directly below the hips with the feet turned out. Your knees should be slightly bent, and the torso inclined forward. The spine should be fully extended and the head facing forward. The bar should be just below the knees. This will be your starting position.","Aggressively extend through the legs and hips. At peak extension, shrug the shoulders and allow the elbows to flex to the side.","As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. Receive the bar with your body as low as possible and the arms fully extended overhead.","Return to a standing position with the weight overhead, and then return the weight to the floor under control."],"category":"olympic weightlifting","images":["Hang_Snatch_-_Below_Knees/0.jpg","Hang_Snatch_-_Below_Knees/1.jpg"],"id":"Hang_Snatch_-_Below_Knees"}'),
('free-exercise-db', 'Hanging_Bar_Good_Morning', 'barbell-hanging-bar-good-morning', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Hanging_Bar_Good_Morning.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Hanging Bar Good Morning","force":"push","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["hamstrings"],"secondaryMuscles":["abdominals","glutes","lower back"],"instructions":["Begin with a bar on a rack at about the same height as your stomach. Suspend the bar using chains or suspension straps.","Bend over underneath the bar and rack the bar across the rear of your shoulders as you would a power squat, not on top of your traps. At the proper height, you should be near parallel to the floor when bent over. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Keep your back arched and your cervical spine in proper alignment.","Begin the motion by extending through the hips with your glutes and hamstrings, and you are standing with the weight.","Slowly lower the weight back to the starting position, where it is supported by the chains."],"category":"powerlifting","images":["Hanging_Bar_Good_Morning/0.jpg","Hanging_Bar_Good_Morning/1.jpg"],"id":"Hanging_Bar_Good_Morning"}'),
('free-exercise-db', 'Hanging_Leg_Raise', 'hanging-leg-raise', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Hanging_Leg_Raise.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Hanging Leg Raise","force":"pull","level":"expert","mechanic":"isolation","equipment":"body only","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Hang from a chin-up bar with both arms extended at arms length in top of you using either a wide grip or a medium grip. The legs should be straight down with the pelvis rolled slightly backwards. This will be your starting position.","Raise your legs until the torso makes a 90-degree angle with the legs. Exhale as you perform this movement and hold the contraction for a second or so.","Go back slowly to the starting position as you breathe in.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Hanging_Leg_Raise/0.jpg","Hanging_Leg_Raise/1.jpg"],"id":"Hanging_Leg_Raise"}'),
('free-exercise-db', 'Hanging_Pike', 'hanging-pike', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Hanging_Pike.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Hanging Pike","force":"pull","level":"expert","mechanic":"compound","equipment":"body only","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Hang from a chin-up bar with your legs and feet together using an overhand grip (palms facing away from you) that is slightly wider than shoulder width. Tip: You may use wrist wraps in order to facilitate holding on to the bar.","Now bend your knees at a 90 degree angle and bring the upper legs forward so that the calves are perpendicular to the floor while the thighs remain parallel to it. This will be your starting position.","Pull your legs up as you exhale until you almost touch your shins with the bar above you. Tip: Try to straighten your legs as much as possible while at the top.","Lower your legs as slowly as possible until you reach the starting position. Tip: Avoid swinging and using momentum at all times.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Hanging_Pike/0.jpg","Hanging_Pike/1.jpg"],"id":"Hanging_Pike"}'),
('free-exercise-db', 'Heaving_Snatch_Balance', 'barbell-heaving-snatch-balance', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Heaving_Snatch_Balance.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Heaving Snatch Balance","force":"push","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["abdominals","forearms","glutes","hamstrings","shoulders","triceps"],"instructions":["This drill helps you learn the snatch. Begin by holding a light weight across the back of the shoulders. Your feet should be slightly wider than hip width apart with the feet turned out, the same position that you would perform a squat with.","Begin by dipping with the knees slightly, and popping back up to briefly unload the bar. Drive yourself underneath the bar, elevating it overhead as you descend into a full squat.","Return to a standing position."],"category":"olympic weightlifting","images":["Heaving_Snatch_Balance/0.jpg","Heaving_Snatch_Balance/1.jpg"],"id":"Heaving_Snatch_Balance"}'),
('free-exercise-db', 'Heavy_Bag_Thrust', 'heavy-bag-thrust', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Heavy_Bag_Thrust.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Heavy Bag Thrust","force":"push","level":"beginner","mechanic":"compound","equipment":"other","primaryMuscles":["chest"],"secondaryMuscles":["abdominals","shoulders","triceps"],"instructions":["Utilize a heavy bag for this exercise. Assume an upright stance next to the bag, with your feet staggered, fairly wide apart. Place your hand on the bag at about chest height. This will be your starting position.","Begin by twisting at the waist, pushing the bag forward as hard as possible. Perform this move quickly, pushing the bag away from your body.","Receive the bag as it swings back by reversing these steps."],"category":"plyometrics","images":["Heavy_Bag_Thrust/0.jpg","Heavy_Bag_Thrust/1.jpg"],"id":"Heavy_Bag_Thrust"}'),
('free-exercise-db', 'High_Cable_Curls', 'cable-high-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/High_Cable_Curls.json', 'Unlicense', NULL, 'new', NULL, '{"name":"High Cable Curls","force":"pull","level":"intermediate","mechanic":"compound","equipment":"cable","primaryMuscles":["biceps"],"secondaryMuscles":[],"instructions":["Stand between a couple of high pulleys and grab a handle in each arm. Position your upper arms in a way that they are parallel to the floor with the palms of your hands facing you. This will be your starting position.","Curl the handles towards you until they are next to your ears. Make sure that as you do so you flex your biceps and exhale. The upper arms should remain stationary and only the forearms should move. Hold for a second in the contracted position as you squeeze the biceps.","Slowly bring back the arms to the starting position.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["High_Cable_Curls/0.jpg","High_Cable_Curls/1.jpg"],"id":"High_Cable_Curls"}'),
('free-exercise-db', 'Hip_Circles_prone', 'hip-circle-prone', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Hip_Circles_prone.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Hip Circles (prone)","force":"pull","level":"beginner","mechanic":"isolation","equipment":"body only","primaryMuscles":["abductors"],"secondaryMuscles":["adductors"],"instructions":["Position yourself on your hands and knees on the ground. Maintaining good posture, raise one bent knee off of the ground. This will be your starting position.","Keeping the knee in a bent position, rotate the femur in an arc, attempting to make a big circle with your knee.","Perform this slowly for a number of repetitions, and repeat on the other side."],"category":"stretching","images":["Hip_Circles_prone/0.jpg","Hip_Circles_prone/1.jpg"],"id":"Hip_Circles_prone"}'),
('free-exercise-db', 'Hip_Extension_with_Bands', 'band-hip-extension', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Hip_Extension_with_Bands.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Hip Extension with Bands","force":"push","level":"beginner","mechanic":"compound","equipment":"bands","primaryMuscles":["glutes"],"secondaryMuscles":["hamstrings"],"instructions":["Secure one end of the band to the lower portion of a post and attach the other to one ankle.","Facing the attachment point of the band, hold on to the column to stabilize yourself.","Keeping your head and your chest up, move the resisted leg back as far as you can while keeping the knee straight.","Return the leg to the starting position."],"category":"strength","images":["Hip_Extension_with_Bands/0.jpg","Hip_Extension_with_Bands/1.jpg"],"id":"Hip_Extension_with_Bands"}'),
('free-exercise-db', 'Hip_Flexion_with_Band', 'band-hip-flexion', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Hip_Flexion_with_Band.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Hip Flexion with Band","force":"pull","level":"beginner","mechanic":"compound","equipment":"bands","primaryMuscles":["quadriceps"],"secondaryMuscles":[],"instructions":["Secure one end of the band to the lower portion of a post and attach the other to one ankle.","Face away from the attachment point of the band.","Keeping your head and your chest up, raise your knee up to 90 degrees and pause.","Return the leg to the starting position."],"category":"strength","images":["Hip_Flexion_with_Band/0.jpg","Hip_Flexion_with_Band/1.jpg"],"id":"Hip_Flexion_with_Band"}'),
('free-exercise-db', 'Hip_Lift_with_Band', 'band-hip-lift', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Hip_Lift_with_Band.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Hip Lift with Band","force":"push","level":"beginner","mechanic":"compound","equipment":"bands","primaryMuscles":["glutes"],"secondaryMuscles":["calves","hamstrings"],"instructions":["After choosing a suitable band, lay down in the middle of the rack, after securing the band on either side of you. If your rack doesn''t have pegs, the band can be secured using heavy dumbbells or similar objects, just ensure they won''t move.","Adjust your position so that the band is directly over your hips. Bend your knees and place your feet flat on the floor. Your hands can be on the floor or holding the band in position.","Keeping your shoulders on the ground, drive through your heels to raise your hips, pushing into the band as high as you can.","Pause at the top of the motion, and return to the starting position."],"category":"powerlifting","images":["Hip_Lift_with_Band/0.jpg","Hip_Lift_with_Band/1.jpg"],"id":"Hip_Lift_with_Band"}'),
('free-exercise-db', 'Hug_A_Ball', 'exercise-ball-hug-ball', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Hug_A_Ball.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Hug A Ball","force":"static","level":"beginner","mechanic":"isolation","equipment":"exercise ball","primaryMuscles":["lower back"],"secondaryMuscles":["calves","glutes"],"instructions":["Seat yourself on the floor.","Straddle an exercise ball between both legs and lower your hips down toward the floor.","Hug your arms around the ball to support your body. Adjust your legs so that your feet are flat on the floor and your knees line up over your ankles. Keep a good grip on the ball so it doesn''t roll away from you and send you back onto your buttocks."],"category":"stretching","images":["Hug_A_Ball/0.jpg","Hug_A_Ball/1.jpg"],"id":"Hug_A_Ball"}'),
('free-exercise-db', 'Hug_Knees_To_Chest', 'hug-knees-to-chest', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Hug_Knees_To_Chest.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Hug Knees To Chest","force":"static","level":"beginner","mechanic":null,"equipment":null,"primaryMuscles":["lower back"],"secondaryMuscles":["glutes"],"instructions":["Lie down on your back and pull both knees up to your chest.","Hold your arms under the knees, not over (that would put to much pressure on your knee joints).","Slowly pull the knees toward your shoulders. This also stretches your buttocks muscles."],"category":"stretching","images":["Hug_Knees_To_Chest/0.jpg","Hug_Knees_To_Chest/1.jpg"],"id":"Hug_Knees_To_Chest"}'),
('free-exercise-db', 'Hurdle_Hops', 'hurdle-hop', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Hurdle_Hops.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Hurdle Hops","force":"push","level":"beginner","mechanic":"compound","equipment":"other","primaryMuscles":["hamstrings"],"secondaryMuscles":["abductors","adductors","calves","glutes","hamstrings"],"instructions":["Set up a row of hurdles or other small barriers, placing them a few feet apart.","Stand in front of the first hurdle with your feet shoulder width apart. This will be your starting position.","Begin by jumping with both feet over the first hurdle, swinging both arms as you jump.","Absorb the impact of landing by bending the knees, rebounding out of the first leap by jumping over the next hurdle. Continue until you have jumped over all of the hurdles."],"category":"plyometrics","images":["Hurdle_Hops/0.jpg","Hurdle_Hops/1.jpg"],"id":"Hurdle_Hops"}'),
('free-exercise-db', 'Hyperextensions_Back_Extensions', 'hyperextensions-back-extension', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Hyperextensions_Back_Extensions.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Hyperextensions (Back Extensions)","force":"pull","level":"beginner","mechanic":"isolation","equipment":"other","primaryMuscles":["lower back"],"secondaryMuscles":["glutes","hamstrings"],"instructions":["Lie face down on a hyperextension bench, tucking your ankles securely under the footpads.","Adjust the upper pad if possible so your upper thighs lie flat across the wide pad, leaving enough room for you to bend at the waist without any restriction.","With your body straight, cross your arms in front of you (my preference) or behind your head. This will be your starting position. Tip: You can also hold a weight plate for extra resistance in front of you under your crossed arms.","Start bending forward slowly at the waist as far as you can while keeping your back flat. Inhale as you perform this movement. Keep moving forward until you feel a nice stretch on the hamstrings and you can no longer keep going without a rounding of the back. Tip: Never round the back as you perform this exercise. Also, some people can go farther than others. The key thing is that you go as far as your body allows you to without rounding the back.","Slowly raise your torso back to the initial position as you inhale. Tip: Avoid the temptation to arch your back past a straight line. Also, do not swing the torso at any time in order to protect the back from injury.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Hyperextensions_Back_Extensions/0.jpg","Hyperextensions_Back_Extensions/1.jpg"],"id":"Hyperextensions_Back_Extensions"}'),
('free-exercise-db', 'Hyperextensions_With_No_Hyperextension_Bench', 'hyperextensions-no-hyperextension-bench', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Hyperextensions_With_No_Hyperextension_Bench.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Hyperextensions With No Hyperextension Bench","force":"pull","level":"intermediate","mechanic":"compound","equipment":"body only","primaryMuscles":["lower back"],"secondaryMuscles":["glutes","hamstrings"],"instructions":["With someone holding down your legs, slide yourself down to the edge a flat bench until your hips hang off the end of the bench. Tip: Your entire upper body should be hanging down towards the floor. Also, you will be in the same position as if you were on a hyperextension bench but the range of motion will be shorter due to the height of the flat bench vs. that of the hyperextension bench.","With your body straight, cross your arms in front of you (my preference) or behind your head. This will be your starting position. Tip: You can also hold a weight plate for extra resistance in front of you under your crossed arms.","Start bending forward slowly at the waist as far as you can while keeping your back flat. Inhale as you perform this movement. Keep moving forward until you almost touch the floor or you feel a nice stretch on the hamstrings (whichever comes first). Tip: Never round the back as you perform this exercise.","Slowly raise your torso back to the initial position as you exhale. Tip: Avoid the temptation to arch your back past a straight line. Also, do not swing the torso at any time in order to protect the back from injury.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Hyperextensions_With_No_Hyperextension_Bench/0.jpg","Hyperextensions_With_No_Hyperextension_Bench/1.jpg"],"id":"Hyperextensions_With_No_Hyperextension_Bench"}'),
('free-exercise-db', 'IT_Band_and_Glute_Stretch', 'it-band-and-glute-stretch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/IT_Band_and_Glute_Stretch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"IT Band and Glute Stretch","force":"static","level":"intermediate","mechanic":null,"equipment":"other","primaryMuscles":["abductors"],"secondaryMuscles":[],"instructions":["Loop a belt, rope, or band around one of your feet, and swing that leg across your body to the opposite side, keeping the leg extended as you lay on the ground. This will be your starting position.","Keeping your foot off of the floor, pull on the belt, using the tension to pull the toes up. Hold for 10-20 seconds, and repeat on the other side."],"category":"stretching","images":["IT_Band_and_Glute_Stretch/0.jpg","IT_Band_and_Glute_Stretch/1.jpg"],"id":"IT_Band_and_Glute_Stretch"}'),
('free-exercise-db', 'Iliotibial_Tract-SMR', 'foam-roller-iliotibial-tract-smr', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Iliotibial_Tract-SMR.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Iliotibial Tract-SMR","force":"static","level":"intermediate","mechanic":"isolation","equipment":"foam roll","primaryMuscles":["abductors"],"secondaryMuscles":[],"instructions":["Lay on your side, with the bottom leg placed onto a foam roller between the hip and the knee. The other leg can be crossed in front of you.","Place as much of your weight as is tolerable onto your bottom leg; there is no need to keep your bottom leg in contact with the ground. Be sure to relax the muscles of the leg you are stretching.","Roll your leg over the foam from you hip to your knee, pausing for 10-30 seconds at points of tension. Repeat with the opposite leg."],"category":"stretching","images":["Iliotibial_Tract-SMR/0.jpg","Iliotibial_Tract-SMR/1.jpg"],"id":"Iliotibial_Tract-SMR"}'),
('free-exercise-db', 'Inchworm', 'inchworm', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Inchworm.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Inchworm","force":null,"level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["hamstrings"],"secondaryMuscles":[],"instructions":["Stand with your feet close together. Keeping your legs straight, stretch down and put your hands on the floor directly in front of you. This will be your starting position.","Begin by walking your hands forward slowly, alternating your left and your right. As you do so, bend only at the hip, keeping your legs straight.","Keep going until your body is parallel to the ground in a pushup position.","Now, keep your hands in place and slowly take short steps with your feet, moving only a few inches at a time.","Continue walking until your feet are by hour hands, keeping your legs straight as you do so."],"category":"stretching","images":["Inchworm/0.jpg","Inchworm/1.jpg"],"id":"Inchworm"}'),
('free-exercise-db', 'Incline_Barbell_Triceps_Extension', 'barbell-incline-triceps-extension', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Incline_Barbell_Triceps_Extension.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Incline Barbell Triceps Extension","force":"push","level":"intermediate","mechanic":"isolation","equipment":"barbell","primaryMuscles":["triceps"],"secondaryMuscles":["forearms"],"instructions":["Hold a barbell with an overhand grip (palms down) that is a little closer together than shoulder width.","Lie back on an incline bench set at any angle between 45-75-degrees.","Bring the bar overhead with your arms extended and elbows in. The arms should be in line with the torso above the head. This will be your starting position.","Now lower the bar in a semicircular motion behind your head until your forearms touch your biceps. Inhale as you perform this movement. Tip: Keep your upper arms stationary and close to your head at all times. Only the forearms should move.","Return to the starting position as you breathe out and you contract the triceps. Hold the contraction for a second.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Incline_Barbell_Triceps_Extension/0.jpg","Incline_Barbell_Triceps_Extension/1.jpg"],"id":"Incline_Barbell_Triceps_Extension"}'),
('free-exercise-db', 'Incline_Bench_Pull', 'barbell-incline-bench-pull', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Incline_Bench_Pull.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Incline Bench Pull","force":"pull","level":"beginner","mechanic":"isolation","equipment":"barbell","primaryMuscles":["middle back"],"secondaryMuscles":["lats","shoulders"],"instructions":["Grab a dumbbell in each hand and lie face down on an incline bench that is set to an incline that is approximately 30 degrees.","Let the arms hang to your sides fully extended as they point to the floor.","Turn the wrists until your hands have a pronated (palms down) grip.","Now flare the elbows out. This will be your starting position.","As you breathe out, start to pull the dumbbells up as if you are doing a reverse bench press. You will do this by bending at the elbows and bringing the upper arms up as you let the forearms hang. Continue this motion until the upper arms are at the same level as your back. Tip: The elbows will come out to the side and your upper arms and torso should make the letter \"T\" at the top of the movement. Hold the contraction at the top for a second.","Slowly go back down to the starting position as you breathe in.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Incline_Bench_Pull/0.jpg","Incline_Bench_Pull/1.jpg"],"id":"Incline_Bench_Pull"}'),
('free-exercise-db', 'Incline_Cable_Chest_Press', 'cable-chest-press-incline', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Incline_Cable_Chest_Press.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Incline Cable Chest Press","force":"push","level":"beginner","mechanic":"compound","equipment":"cable","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 45 degrees to the body, with your head and chest up. The elbows should be bent to about 90 degrees. This will be your starting position.","Begin by extending through the elbow, pressing the handles together straight in front of you. Keep your shoulder blades retracted as you execute the movement.","After pausing at full extension, return to the starting position, keeping tension on the cables."],"category":"strength","images":["Incline_Cable_Chest_Press/0.jpg","Incline_Cable_Chest_Press/1.jpg"],"id":"Incline_Cable_Chest_Press"}'),
('free-exercise-db', 'Incline_Cable_Flye', 'cable-incline-flye', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Incline_Cable_Flye.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Incline Cable Flye","force":"push","level":"intermediate","mechanic":"isolation","equipment":"cable","primaryMuscles":["chest"],"secondaryMuscles":["shoulders"],"instructions":["To get yourself into the starting position, set the pulleys at the floor level (lowest level possible on the machine that is below your torso).","Place an incline bench (set at 45 degrees) in between the pulleys, select a weight on each one and grab a pulley on each hand.","With a handle on each hand, lie on the incline bench and bring your hands together at arms length in front of your face. This will be your starting position.","With a slight bend of your elbows (in order to prevent stress at the biceps tendon), lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms should remain stationary. The movement should only occur at the shoulder joint.","Return your arms back to the starting position as you squeeze your chest muscles and exhale. Hold the contracted position for a second. Tip: Make sure to use the same arc of motion used to lower the weights.","Repeat the movement for the prescribed amount of repetitions."],"category":"strength","images":["Incline_Cable_Flye/0.jpg","Incline_Cable_Flye/1.jpg"],"id":"Incline_Cable_Flye"}'),
('free-exercise-db', 'Incline_Dumbbell_Bench_With_Palms_Facing_In', 'dumbbell-incline-bench-palms-facing-in', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Incline_Dumbbell_Bench_With_Palms_Facing_In.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Incline Dumbbell Bench With Palms Facing In","force":"push","level":"beginner","mechanic":"compound","equipment":"dumbbell","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["Lie back on an incline bench with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.","By using your thighs to help you get the dumbbells up, clean the dumbbells one arm at a time so that you can hold them at shoulder width.","Once at shoulder width, keep the palms of your hands with a neutral grip (palms facing each other). Keep your elbows flared out with the upper arms in line with the shoulders (perpendicular to the torso) and the elbows bent creating a 90-degree angle between the upper arm and the forearm. This will be your starting position.","Now bring down the weights slowly to your side as you breathe in. Keep full control of the dumbbells at all times.","As you breathe out, push the dumbbells up using your pectoral muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the dumbbells back in your thighs and then on the floor. This is the safest manner to dispose of the dumbbells."],"category":"strength","images":["Incline_Dumbbell_Bench_With_Palms_Facing_In/0.jpg","Incline_Dumbbell_Bench_With_Palms_Facing_In/1.jpg"],"id":"Incline_Dumbbell_Bench_With_Palms_Facing_In"}'),
('free-exercise-db', 'Incline_Dumbbell_Curl', 'dumbbell-incline-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Incline_Dumbbell_Curl.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Incline Dumbbell Curl","force":"pull","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["biceps"],"secondaryMuscles":[],"instructions":["Sit back on an incline bench with a dumbbell in each hand held at arms length. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position.","While holding the upper arm stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second.","Slowly begin to bring the dumbbells back to starting position as your breathe in.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Incline_Dumbbell_Curl/0.jpg","Incline_Dumbbell_Curl/1.jpg"],"id":"Incline_Dumbbell_Curl"}'),
('free-exercise-db', 'Incline_Dumbbell_Flyes', 'dumbbell-incline-fly', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Incline_Dumbbell_Flyes.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Incline Dumbbell Flyes","force":"push","level":"beginner","mechanic":"compound","equipment":"dumbbell","primaryMuscles":["chest"],"secondaryMuscles":["shoulders"],"instructions":["Hold a dumbbell on each hand and lie on an incline bench that is set to an incline angle of no more than 30 degrees.","Extend your arms above you with a slight bend at the elbows.","Now rotate the wrists so that the palms of your hands are facing you. Tip: The pinky fingers should be next to each other. This will be your starting position.","As you breathe in, start to slowly lower the arms to the side while keeping the arms extended and while rotating the wrists until the palms of the hand are facing each other. Tip: At the end of the movement the arms will be by your side with the palms facing the ceiling.","As you exhale start to bring the dumbbells back up to the starting position by reversing the motion and rotating the hands so that the pinky fingers are next to each other again. Tip: Keep in mind that the movement will only happen at the shoulder joint and at the wrist. There is no motion that happens at the elbow joint.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Incline_Dumbbell_Flyes/0.jpg","Incline_Dumbbell_Flyes/1.jpg"],"id":"Incline_Dumbbell_Flyes"}'),
('free-exercise-db', 'Incline_Dumbbell_Flyes_-_With_A_Twist', 'dumbbell-incline-flyes-twist', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Incline_Dumbbell_Flyes_-_With_A_Twist.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Incline Dumbbell Flyes - With A Twist","force":"push","level":"beginner","mechanic":"compound","equipment":"dumbbell","primaryMuscles":["chest"],"secondaryMuscles":["shoulders"],"instructions":["Hold a dumbbell in each hand and lie on an incline bench that is set to an incline angle of no more than 30 degrees.","Extend your arms above you with a slight bend at the elbows.","Now rotate the wrists so that the palms of your hands are facing you. Tip: The pinky fingers should be next to each other. This will be your starting position.","As you breathe in, start to slowly lower the arms to the side while keeping the arms extended and while rotating the wrists until the palms of the hand are facing each other. Tip: At the end of the movement the arms will be by your side with the palms facing the ceiling.","As you exhale start to bring the dumbbells back up to the starting position by reversing the motion and rotating the hands so that the pinky fingers are next to each other again. Tip: Keep in mind that the movement will only happen at the shoulder joint and at the wrist. There is no motion that happens at the elbow joint.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Incline_Dumbbell_Flyes_-_With_A_Twist/0.jpg","Incline_Dumbbell_Flyes_-_With_A_Twist/1.jpg"],"id":"Incline_Dumbbell_Flyes_-_With_A_Twist"}'),
('free-exercise-db', 'Incline_Dumbbell_Press', 'dumbbell-incline-bench-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Incline_Dumbbell_Press.json', 'Unlicense', NULL, 'exact', 100.0, '{"name":"Incline Dumbbell Press","force":"push","level":"beginner","mechanic":"compound","equipment":"dumbbell","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["Lie back on an incline bench with a dumbbell in each hand atop your thighs. The palms of your hands will be facing each other.","Then, using your thighs to help push the dumbbells up, lift the dumbbells one at a time so that you can hold them at shoulder width.","Once you have the dumbbells raised to shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.","Be sure to keep full control of the dumbbells at all times. Then breathe out and push the dumbbells up with your chest.","Lock your arms at the top, hold for a second, and then start slowly lowering the weight. Tip Ideally, lowering the weights should take about twice as long as raising them.","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the dumbbells back on your thighs and then on the floor. This is the safest manner to release the dumbbells."],"category":"strength","images":["Incline_Dumbbell_Press/0.jpg","Incline_Dumbbell_Press/1.jpg"],"id":"Incline_Dumbbell_Press"}'),
('free-exercise-db', 'Incline_Hammer_Curls', 'dumbbell-incline-hammer-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Incline_Hammer_Curls.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Incline Hammer Curls","force":"pull","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["biceps"],"secondaryMuscles":[],"instructions":["Seat yourself on an incline bench with a dumbbell in each hand. You should pressed firmly against he back with your feet together. Allow the dumbbells to hang straight down at your side, holding them with a neutral grip. This will be your starting position.","Initiate the movement by flexing at the elbow, attempting to keep the upper arm stationary.","Continue to the top of the movement and pause, then slowly return to the start position."],"category":"strength","images":["Incline_Hammer_Curls/0.jpg","Incline_Hammer_Curls/1.jpg"],"id":"Incline_Hammer_Curls"}'),
('free-exercise-db', 'Incline_Inner_Biceps_Curl', 'dumbbell-incline-inner-biceps-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Incline_Inner_Biceps_Curl.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Incline Inner Biceps Curl","force":null,"level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["biceps"],"secondaryMuscles":[],"instructions":["Hold a dumbbell in each hand and lie back on an incline bench.","The dumbbells should be at arm''s length hanging at your sides and your palms should be facing out. This will be your starting position.","Now as you exhale curl the weight outward and up while keeping your forearms in line with your side deltoids. Continue the curl until the dumbbells are at shoulder height and to the sides of your deltoids. Tip: The end of the movement should look similar to a double biceps pose.","After a second contraction at the top of the movement, start to inhale and slowly lower the weights back to the starting position using the same path used to bring them up.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Incline_Inner_Biceps_Curl/0.jpg","Incline_Inner_Biceps_Curl/1.jpg"],"id":"Incline_Inner_Biceps_Curl"}'),
('free-exercise-db', 'Incline_Push-Up', 'push-up-incline', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Incline_Push-Up.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Incline Push-Up","force":"push","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["Stand facing bench or sturdy elevated platform. Place hands on edge of bench or platform, slightly wider than shoulder width.","Position forefoot back from bench or platform with arms and body straight. Arms should be perpendicular to body. Keeping body straight, lower chest to edge of box or platform by bending arms.","Push body up until arms are extended. Repeat."],"category":"strength","images":["Incline_Push-Up/0.jpg","Incline_Push-Up/1.jpg"],"id":"Incline_Push-Up"}'),
('free-exercise-db', 'Incline_Push-Up_Close-Grip', 'incline-push-up-close-grip', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Incline_Push-Up_Close-Grip.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Incline Push-Up Close-Grip","force":"push","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["triceps"],"secondaryMuscles":["chest","shoulders"],"instructions":["Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.","Place your hands next to one another on the bar.","Position your feet back from the bar with arms and body straight. This will be your starting position.","Keeping your body straight, lower your chest to the bar by bending the arms.","Return to the starting position by extending the elbows, pressing yourself back up."],"category":"strength","images":["Incline_Push-Up_Close-Grip/0.jpg","Incline_Push-Up_Close-Grip/1.jpg"],"id":"Incline_Push-Up_Close-Grip"}'),
('free-exercise-db', 'Incline_Push-Up_Depth_Jump', 'incline-push-up-depth-jump', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Incline_Push-Up_Depth_Jump.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Incline Push-Up Depth Jump","force":"push","level":"beginner","mechanic":"compound","equipment":"other","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["For this drill you will need a box about 12 inches high, and two thick mats or aerobics steps.","Place the steps just outside of your shoulders, and place your feet on top of the box so that you are in an incline pushup position, your hands just inside the steps. This will be your starting position.","Begin by bending at the elbows to lower your body, quickly reversing position to push your body off of the ground. As you leave the ground, move your hands onto the steps, bending your elbows to absorb the impact.","Repeat the motion to return to the starting position."],"category":"plyometrics","images":["Incline_Push-Up_Depth_Jump/0.jpg","Incline_Push-Up_Depth_Jump/1.jpg"],"id":"Incline_Push-Up_Depth_Jump"}'),
('free-exercise-db', 'Incline_Push-Up_Medium', 'incline-push-up-medium', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Incline_Push-Up_Medium.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Incline Push-Up Medium","force":"push","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["chest"],"secondaryMuscles":["abdominals","shoulders","triceps"],"instructions":["Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.","Place your hands on the bar, with your hands about shoulder width apart.","Position your feet back from the bar with arms and body straight. This will be your starting position.","Keeping your body straight, lower your chest to the bar by bending the arms.","Return to the starting position by extending the elbows, pressing yourself back up."],"category":"strength","images":["Incline_Push-Up_Medium/0.jpg","Incline_Push-Up_Medium/1.jpg"],"id":"Incline_Push-Up_Medium"}'),
('free-exercise-db', 'Incline_Push-Up_Reverse_Grip', 'incline-push-up-reverse-grip', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Incline_Push-Up_Reverse_Grip.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Incline Push-Up Reverse Grip","force":"push","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["chest"],"secondaryMuscles":["abdominals","shoulders","triceps"],"instructions":["Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.","Place your hands on the bar palms up, with your hands about shoulder width apart.","Position your feet back from the bar with arms and body straight. This will be your starting position.","Keeping your body straight, lower your chest to the bar by bending the arms.","Return to the starting position by extending the elbows, pressing yourself back up."],"category":"strength","images":["Incline_Push-Up_Reverse_Grip/0.jpg","Incline_Push-Up_Reverse_Grip/1.jpg"],"id":"Incline_Push-Up_Reverse_Grip"}'),
('free-exercise-db', 'Incline_Push-Up_Wide', 'incline-push-up-wide', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Incline_Push-Up_Wide.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Incline Push-Up Wide","force":"push","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["chest"],"secondaryMuscles":["abdominals","shoulders","triceps"],"instructions":["Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.","Place your hands on the bar, with your hands wider than shoulder width.","Position your feet back from the bar with arms and body straight. Your arms should be perpendicular to the body. This will be your starting position.","Keeping your body straight, lower your chest to the bar by bending the arms.","Return to the starting position by extending the elbows, pressing yourself back up."],"category":"strength","images":["Incline_Push-Up_Wide/0.jpg","Incline_Push-Up_Wide/1.jpg"],"id":"Incline_Push-Up_Wide"}'),
('free-exercise-db', 'Intermediate_Groin_Stretch', 'intermediate-groin-stretch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Intermediate_Groin_Stretch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Intermediate Groin Stretch","force":"static","level":"intermediate","mechanic":"isolation","equipment":"other","primaryMuscles":["hamstrings"],"secondaryMuscles":[],"instructions":["Lie on your back with your legs extended. Loop a belt, rope, or band around one of your feet, and swing that leg as far to the side as you can. This will be your starting position.","Pull gently on the belt to create tension in your groin and hamstring muscles. Hold for 10-20 seconds, and repeat on the other side."],"category":"stretching","images":["Intermediate_Groin_Stretch/0.jpg","Intermediate_Groin_Stretch/1.jpg"],"id":"Intermediate_Groin_Stretch"}'),
('free-exercise-db', 'Intermediate_Hip_Flexor_and_Quad_Stretch', 'intermediate-hip-flexor-and-quad-stretch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Intermediate_Hip_Flexor_and_Quad_Stretch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Intermediate Hip Flexor and Quad Stretch","force":"static","level":"intermediate","mechanic":"compound","equipment":"other","primaryMuscles":["quadriceps"],"secondaryMuscles":[],"instructions":["Lie face down on the floor, with a rope, belt, or band looped around one foot.","Flex the knee and extend the hip of the leg to be stretched, using both hands to pull on the belt. Your knee and your hip should come off of the floor, creating tension in the hip flexors and quadriceps. Hold the stretch for 10-20 seconds, and repeat on the other leg."],"category":"stretching","images":["Intermediate_Hip_Flexor_and_Quad_Stretch/0.jpg","Intermediate_Hip_Flexor_and_Quad_Stretch/1.jpg"],"id":"Intermediate_Hip_Flexor_and_Quad_Stretch"}'),
('free-exercise-db', 'Internal_Rotation_with_Band', 'band-internal-rotation', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Internal_Rotation_with_Band.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Internal Rotation with Band","force":null,"level":"beginner","mechanic":"isolation","equipment":"bands","primaryMuscles":["shoulders"],"secondaryMuscles":[],"instructions":["Choke the band around a post. The band should be at the same height as your elbow. Stand with your right side to the band a couple of feet away.","Grasp the end of the band with your right hand, and keep your elbow pressed firmly to your side. We recommend you hold a pad or foam roll in place with your elbow to keep it firmly in position.","With your upper arm in position, your elbow should be flexed to 90 degrees with your hand reaching away from your torso. This will be your starting position.","Execute the movement by rotating your arm in a forehand motion, keeping your elbow in place.","Continue as far as you are able, pause, and then return to the starting position."],"category":"strength","images":["Internal_Rotation_with_Band/0.jpg","Internal_Rotation_with_Band/1.jpg"],"id":"Internal_Rotation_with_Band"}'),
('free-exercise-db', 'Inverted_Row', 'inverted-row-2', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Inverted_Row.json', 'Unlicense', NULL, 'exact', 100.0, '{"name":"Inverted Row","force":"pull","level":"beginner","mechanic":"compound","equipment":null,"primaryMuscles":["middle back"],"secondaryMuscles":["lats"],"instructions":["Position a bar in a rack to about waist height. You can also use a smith machine.","Take a wider than shoulder width grip on the bar and position yourself hanging underneath the bar. Your body should be straight with your heels on the ground with your arms fully extended. This will be your starting position.","Begin by flexing the elbow, pulling your chest towards the bar. Retract your shoulder blades as you perform the movement.","Pause at the top of the motion, and return yourself to the start position.","Repeat for the desired number of repetitions."],"category":"strength","images":["Inverted_Row/0.jpg","Inverted_Row/1.jpg"],"id":"Inverted_Row"}'),
('free-exercise-db', 'Inverted_Row_with_Straps', 'inverted-row-straps', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Inverted_Row_with_Straps.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Inverted Row with Straps","force":"pull","level":"beginner","mechanic":"compound","equipment":"other","primaryMuscles":["middle back"],"secondaryMuscles":["biceps","lats"],"instructions":["Hang a rope or suspension straps from a rack or other stable object. Grasp the ends and position yourself in a supine position hanging from the ropes. Your body should be straight with your heels on the ground with your arms fully extended. This will be your starting position.","Begin by flexing the elbow, pulling your chest to your hands. Retract your shoulder blades as you perform the movement.","Pause at the top of the motion, and return yourself to the start position.","Repeat for the desired number of repetitions."],"category":"strength","images":["Inverted_Row_with_Straps/0.jpg","Inverted_Row_with_Straps/1.jpg"],"id":"Inverted_Row_with_Straps"}'),
('free-exercise-db', 'Iron_Cross', 'dumbbell-iron-cross', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Iron_Cross.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Iron Cross","force":"push","level":"intermediate","mechanic":"compound","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":["chest","glutes","hamstrings","lower back","quadriceps","traps"],"instructions":[],"category":"strength","images":["Iron_Cross/0.jpg","Iron_Cross/1.jpg"],"id":"Iron_Cross"}'),
('free-exercise-db', 'Iron_Crosses_stretch', 'iron-crosses-stretch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Iron_Crosses_stretch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Iron Crosses (stretch)","force":"pull","level":"intermediate","mechanic":"compound","equipment":null,"primaryMuscles":["quadriceps"],"secondaryMuscles":[],"instructions":["Lie face down on the floor, with your arms extended out to your side, palms pressed to the floor. This will be your starting position.","To begin, flex one knee and bring that leg across the back of your body, attempting to touch it to the ground near the opposite hand.","Promptly return the leg to the starting postion, and quickly repeat with the other leg. Continue alternating for 10-20 repetitions."],"category":"stretching","images":["Iron_Crosses_stretch/0.jpg","Iron_Crosses_stretch/1.jpg"],"id":"Iron_Crosses_stretch"}'),
('free-exercise-db', 'Isometric_Chest_Squeezes', 'isometric-chest-squeezes', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Isometric_Chest_Squeezes.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Isometric Chest Squeezes","force":"static","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["While either seating or standing, bend your arms at a 90-degree angle and place the palms of your hands together in front of your chest. Tip: Your hands should be open with the palms together and fingers facing forward (perpendicular to your torso).","Push both hands against each other as you contract your chest. Start with slow tension and increase slowly. Keep breathing normally as you execute this contraction.","Hold for the recommended number of seconds.","Now release the tension slowly.","Rest for the recommended amount of time and repeat."],"category":"plyometrics","images":["Isometric_Chest_Squeezes/0.jpg","Isometric_Chest_Squeezes/1.jpg"],"id":"Isometric_Chest_Squeezes"}'),
('free-exercise-db', 'Isometric_Neck_Exercise_-_Front_And_Back', 'isometric-neck-exercise-front-and-back', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Isometric_Neck_Exercise_-_Front_And_Back.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Isometric Neck Exercise - Front And Back","force":"static","level":"beginner","mechanic":"isolation","equipment":"body only","primaryMuscles":["neck"],"secondaryMuscles":[],"instructions":["With your head and neck in a neutral position (normal position with head erect facing forward), place both of your hands on the front side of your head.","Now gently push forward as you contract the neck muscles but resisting any movement of your head. Start with slow tension and increase slowly. Keep breathing normally as you execute this contraction.","Hold for the recommended number of seconds.","Now release the tension slowly.","Rest for the recommended amount of time and repeat with your hands placed on the back side of your head."],"category":"strength","images":["Isometric_Neck_Exercise_-_Front_And_Back/0.jpg","Isometric_Neck_Exercise_-_Front_And_Back/1.jpg"],"id":"Isometric_Neck_Exercise_-_Front_And_Back"}'),
('free-exercise-db', 'Isometric_Neck_Exercise_-_Sides', 'isometric-neck-exercise-sides', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Isometric_Neck_Exercise_-_Sides.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Isometric Neck Exercise - Sides","force":"static","level":"beginner","mechanic":"isolation","equipment":"body only","primaryMuscles":["neck"],"secondaryMuscles":[],"instructions":["With your head and neck in a neutral position (normal position with head erect facing forward), place your left hand on the left side of your head.","Now gently push towards the left as you contract the left neck muscles but resisting any movement of your head. Start with slow tension and increase slowly. Keep breathing normally as you execute this contraction.","Hold for the recommended number of seconds.","Now release the tension slowly.","Rest for the recommended amount of time and repeat with your right hand placed on the right side of your head."],"category":"strength","images":["Isometric_Neck_Exercise_-_Sides/0.jpg","Isometric_Neck_Exercise_-_Sides/1.jpg"],"id":"Isometric_Neck_Exercise_-_Sides"}'),
('free-exercise-db', 'Isometric_Wipers', 'isometric-wiper', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Isometric_Wipers.json', 'Unlicense', NULL, 'exact', 100.0, '{"name":"Isometric Wipers","force":"push","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["chest"],"secondaryMuscles":["abdominals","shoulders","triceps"],"instructions":["Assume a push-up position, supporting your weight on your hands and toes while keeping your body straight. Your hands should be just outside of shoulder width. This will be your starting position.","Begin by shifting your body weight as far to one side as possible, allowing the elbow on that side to flex as you lower your body.","Reverse the motion by extending the flexed arm, pushing yourself up and then dropping to the other side.","Repeat for the desired number of repetitions."],"category":"strength","images":["Isometric_Wipers/0.jpg","Isometric_Wipers/1.jpg"],"id":"Isometric_Wipers"}'),
('free-exercise-db', 'JM_Press', 'barbell-jm-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/JM_Press.json', 'Unlicense', NULL, 'exact', 100.0, '{"name":"JM Press","force":"push","level":"beginner","mechanic":"compound","equipment":"barbell","primaryMuscles":["triceps"],"secondaryMuscles":["chest","shoulders"],"instructions":["Start the exercise the same way you would a close grip bench press. You will lie on a flat bench while holding a barbell at arms length (fully extended) with the elbows in. However, instead of having the arms perpendicular to the torso, make sure the bar is set in a direct line above the upper chest. This will be your starting position.","Now beginning from a fully extended position lower the bar down as if performing a lying triceps extension. Inhale as you perform this movement. When you reach the half way point, let the bar roll back about one inch by moving the upper arms towards your legs until they are perpendicular to the torso. Tip: Keep the bend at the elbows constant as you bring the upper arms forward.","As you exhale, press the bar back up by using the triceps to perform a close grip bench press.","Now go back to the starting position and start over.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["JM_Press/0.jpg","JM_Press/1.jpg"],"id":"JM_Press"}'),
('free-exercise-db', 'Jackknife_Sit-Up', 'jackknife-sit-up', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Jackknife_Sit-Up.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Jackknife Sit-Up","force":"pull","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Lie flat on the floor (or exercise mat) on your back with your arms extended straight back behind your head and your legs extended also. This will be your starting position.","As you exhale, bend at the waist while simultaneously raising your legs and arms to meet in a jackknife position. Tip: The legs should be extended and lifted at approximately a 35-45 degree angle from the floor and the arms should be extended and parallel to your legs. The upper torso should be off the floor.","While inhaling, lower your arms and legs back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Jackknife_Sit-Up/0.jpg","Jackknife_Sit-Up/1.jpg"],"id":"Jackknife_Sit-Up"}'),
('free-exercise-db', 'Janda_Sit-Up', 'janda-sit-up', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Janda_Sit-Up.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Janda Sit-Up","force":"pull","level":"beginner","mechanic":"isolation","equipment":"body only","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Position your body on the floor in the basic sit-up position; knees to a ninety degree angle with feet flat on the floor and arms either crossed over your chest or to the sides. This will be your starting position.","As you strongly tighten your glutes and hamstrings, fill your lungs with air and in a slow (three to six second count) ascent, slowly exhale. Tip: It is important to tighten the glutes and hamstrings as this will cause the hip flexors to be inactivated in a process called reciprocal inhibition, which basically means that opposite muscles to the contracted ones will relax.","As you inhale, slowly go back in a controlled manner to the starting position.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Janda_Sit-Up/0.jpg","Janda_Sit-Up/1.jpg"],"id":"Janda_Sit-Up"}'),
('free-exercise-db', 'Jefferson_Squats', 'barbell-jefferson-squat', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Jefferson_Squats.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Jefferson Squats","force":"push","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings","lower back","traps"],"instructions":["Place a barbell on the floor.","Stand in the middle of the bar length wise.","Bend down by bending at the knees and keeping your back straight and grasp the front of the bar with your right hand. Your palm should be in (neutral grip) facing the left side.","Grasp the rear of the bar with your left hand. The palm of your hand should be in neutral grip alignment (palms facing the right side). Tip: Ensure that your grip is even on the bar. Your torso should be positioned right in the middle of the bar and the distance between your torso and your right hand (which should be at the front) should be the same as the distance between your torso and your left hand (which should be to your back).","Now stand straight up with the weight. Tip: Your feet should be shoulder width apart and your toes slightly pointed out.","Squat down by bending at the knees and keeping your back straight until your upper thighs are parallel with the floor. Tip: Keep your back as vertical as possible with the floor and your head up. Also remember to not let your knees go past your toes. Inhale during this portion of the movement.","Now drive yourself back up to the starting position by pushing with the feet . Tip: Keep the bar hanging at arm''s length and your elbows locked with a slight bend. The arms only serve as hooks. Avoid doing any lifting with them. Do the lifting with your thighs; not your arms."],"category":"strength","images":["Jefferson_Squats/0.jpg","Jefferson_Squats/1.jpg"],"id":"Jefferson_Squats"}'),
('free-exercise-db', 'Jerk_Balance', 'barbell-jerk-balance', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Jerk_Balance.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Jerk Balance","force":"push","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["shoulders"],"secondaryMuscles":["glutes","hamstrings","quadriceps","triceps"],"instructions":["This drill helps you learn to drive yourself low enough during the jerk and corrects those who move backward during the movement. Begin with the bar racked in the jerk position, with the shoulders forward, torso upright, and the feet split slightly apart.","Initiate the movement as you would a normal jerk, dipping at the knees while keeping your torso vertical, and driving back up forcefully, using momentum and not your arms to elevate the weight.","Keep the rear foot in place, using it to drive your body forward into a full split as you jerk the weight. Recover by standing up with the weight overhead."],"category":"olympic weightlifting","images":["Jerk_Balance/0.jpg","Jerk_Balance/1.jpg"],"id":"Jerk_Balance"}'),
('free-exercise-db', 'Jerk_Dip_Squat', 'barbell-jerk-dip-squat', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Jerk_Dip_Squat.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Jerk Dip Squat","force":"push","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["abdominals","calves"],"instructions":["This movement strengthens the dip portion of the jerk. Begin with the bar racked in the jerk position, with the shoulders forward to create a shelf and the bar lightly contacting the throat. The feet should be directly under the hips, with the feet turned out as is comfortable.","Keeping the torso vertical, dip by flexing the knees, allowing them to travel forward and without moving the hips to the rear. The dip should not be excessive. Return the weight to the starting position by driving forcefully though the feet."],"category":"olympic weightlifting","images":["Jerk_Dip_Squat/0.jpg","Jerk_Dip_Squat/1.jpg"],"id":"Jerk_Dip_Squat"}'),
('free-exercise-db', 'Jogging_Treadmill', 'machine-jogging-treadmill', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Jogging_Treadmill.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Jogging, Treadmill","force":null,"level":"beginner","mechanic":null,"equipment":"machine","primaryMuscles":["quadriceps"],"secondaryMuscles":["glutes","hamstrings"],"instructions":["To begin, step onto the treadmill and select the desired option from the menu. Most treadmills have a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout.","Treadmills offer convenience, cardiovascular benefits, and usually have less impact than jogging outside. A 150 lb person will burn almost 250 calories jogging for 30 minutes, compared to more than 450 calories running. Maintain proper posture as you jog, and only hold onto the handles when necessary, such as when dismounting or checking your heart rate."],"category":"cardio","images":["Jogging_Treadmill/0.jpg","Jogging_Treadmill/1.jpg"],"id":"Jogging_Treadmill"}'),
('free-exercise-db', 'Keg_Load', 'keg-load', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Keg_Load.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Keg Load","force":"pull","level":"intermediate","mechanic":"compound","equipment":"other","primaryMuscles":["lower back"],"secondaryMuscles":["abdominals","biceps","calves","forearms","glutes","hamstrings","middle back","quadriceps","shoulders","traps"],"instructions":["To load kegs, place the desired number a distance from the loading platform, typically 30-50 feet.","Begin by grabbing the close handle of the first keg, tilting it onto its side to grab the opposite edge of the bottom of the keg. Lift the keg up to your chest.","The higher you can place the keg, the faster you should be able to move to the platform. Shouldering is usually not allowed. Be sure to keep a firm hold on the keg. Move as quickly as possible to the platform, and load it, extending through your hips, knees, and ankles to get it as high as possible.","Return to the starting position to retrieve the next keg, and repeat until the event is completed."],"category":"strongman","images":["Keg_Load/0.jpg","Keg_Load/1.jpg"],"id":"Keg_Load"}'),
('free-exercise-db', 'Kettlebell_Arnold_Press', 'kettlebell-arnold-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Kettlebell_Arnold_Press.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Kettlebell Arnold Press","force":"push","level":"intermediate","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["shoulders"],"secondaryMuscles":["triceps"],"instructions":["Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulder by extending through the legs and hips as you raise the kettlebell towards your shoulder. The palm should be facing inward.","Looking straight ahead, press the kettlebell out and overhead, rotating your wrist so that your palm faces forward at the top of the motion.","Return the kettlebell to the starting position, with the palm facing in."],"category":"strength","images":["Kettlebell_Arnold_Press/0.jpg","Kettlebell_Arnold_Press/1.jpg"],"id":"Kettlebell_Arnold_Press"}'),
('free-exercise-db', 'Kettlebell_Dead_Clean', 'kettlebell-dead-clean', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Kettlebell_Dead_Clean.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Kettlebell Dead Clean","force":"pull","level":"intermediate","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["hamstrings"],"secondaryMuscles":["calves","glutes","lower back","quadriceps","traps"],"instructions":["Place kettlebell between your feet. To get in the starting position, push your butt back and look straight ahead.","Clean the kettlebell to your shoulder. Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so.","Lower the kettlebell, keeping the hamstrings loaded by keeping your back straight and your butt out."],"category":"strength","images":["Kettlebell_Dead_Clean/0.jpg","Kettlebell_Dead_Clean/1.jpg"],"id":"Kettlebell_Dead_Clean"}'),
('free-exercise-db', 'Kettlebell_Figure_8', 'kettlebell-figure-8', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Kettlebell_Figure_8.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Kettlebell Figure 8","force":"pull","level":"intermediate","mechanic":null,"equipment":"kettlebells","primaryMuscles":["abdominals"],"secondaryMuscles":["hamstrings","shoulders"],"instructions":["Place one kettlebell between your legs and take a wider than shoulder width stance. Bend over by pushing your butt out and keeping your back flat.","Pick up a kettlebell and pass it to your other hand between your legs. The receiving hand should reach from behind the legs. Go back and forth for several repetitions."],"category":"strength","images":["Kettlebell_Figure_8/0.jpg","Kettlebell_Figure_8/1.jpg"],"id":"Kettlebell_Figure_8"}'),
('free-exercise-db', 'Kettlebell_Halo', 'kettlebell-halo', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Kettlebell_Halo.json', 'Unlicense', NULL, 'new', NULL, '{"id":"Kettlebell_Halo","name":"Kettlebell Halo","force":null,"level":"beginner","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["shoulders"],"secondaryMuscles":["traps","middle back","abdominals","triceps"],"instructions":["Stand tall with your feet hip-width apart. Hold a kettlebell upside down by the horns, with the bell above your hands and close to your chest. Brace your abdominals and squeeze your glutes so your ribcage stays down. This is your starting position.","Keeping your elbows close to your head, move the kettlebell up past one ear and around behind your head.","Continue the circle past the opposite ear and back down to the starting position in front of your chest, letting the bell pass close to your body throughout.","Complete the prescribed number of circles in one direction, then repeat the same number in the opposite direction.","Move slowly and keep your head, hips and lower back still. If your lower back arches or the bell drifts far from your head, use a lighter weight."],"category":"strength","images":[]}'),
('free-exercise-db', 'Kettlebell_Halo_With_Overhead_Extension', 'kettlebell-halo-overhead-extension', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Kettlebell_Halo_With_Overhead_Extension.json', 'Unlicense', NULL, 'new', NULL, '{"id":"Kettlebell_Halo_With_Overhead_Extension","name":"Kettlebell Halo with Overhead Extension","force":"push","level":"intermediate","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["shoulders","triceps"],"secondaryMuscles":["traps","middle back","abdominals"],"instructions":["Stand tall with your feet hip-width apart. Hold a kettlebell upside down by the horns, with the bell above your hands and close to your chest. Brace your abdominals and squeeze your glutes so your ribcage stays down. This is your starting position.","Keeping your elbows close to your head, move the kettlebell up past one ear and around until it sits behind your head. Pause here.","From this position, extend your elbows to press the kettlebell up and overhead until your arms are straight, keeping your upper arms alongside your head.","Bend your elbows to lower the kettlebell back to the pause position behind your head, under control.","Continue the circle past the opposite ear and back down to the starting position in front of your chest to complete one repetition.","Alternate the direction of the circle on each repetition. Keep your head, hips and lower back still throughout; if your lower back arches or you cannot reach the overhead position without leaning back, use a lighter weight or perform the halo and the extension as separate exercises."],"category":"strength","images":[]}'),
('free-exercise-db', 'Kettlebell_Hang_Clean', 'kettlebell-hang-clean', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Kettlebell_Hang_Clean.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Kettlebell Hang Clean","force":"pull","level":"intermediate","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["hamstrings"],"secondaryMuscles":["calves","glutes","lower back","shoulders","traps"],"instructions":["Place kettlebell between your feet. To get in the starting position, push your butt back and look straight ahead.","Clean kettlebell to your shoulder. Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so.","Lower kettlebell to a hanging position between your legs while keeping the hamstrings loaded. Keep your head up at all times."],"category":"strength","images":["Kettlebell_Hang_Clean/0.jpg","Kettlebell_Hang_Clean/1.jpg"],"id":"Kettlebell_Hang_Clean"}'),
('free-exercise-db', 'Kettlebell_One-Legged_Deadlift', 'kettlebell-one-legged-deadlift-2', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Kettlebell_One-Legged_Deadlift.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Kettlebell One-Legged Deadlift","force":"pull","level":"intermediate","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["hamstrings"],"secondaryMuscles":["glutes","lower back"],"instructions":["Hold a kettlebell by the handle in one hand. Stand on one leg, on the same side that you hold the kettlebell.","Keeping that knee slightly bent, perform a stiff legged deadlift by bending at the hip, extending your free leg behind you for balance.","Continue lowering the kettlebell until you are parallel to the ground, and then return to the upright position."],"category":"strength","images":["Kettlebell_One-Legged_Deadlift/0.jpg","Kettlebell_One-Legged_Deadlift/1.jpg"],"id":"Kettlebell_One-Legged_Deadlift"}'),
('free-exercise-db', 'Kettlebell_Overhead_Triceps_Extension', 'kettlebell-overhead-triceps-extension', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Kettlebell_Overhead_Triceps_Extension.json', 'Unlicense', NULL, 'new', NULL, '{"id":"Kettlebell_Overhead_Triceps_Extension","name":"Kettlebell Overhead Triceps Extension","force":"push","level":"beginner","mechanic":"isolation","equipment":"kettlebells","primaryMuscles":["triceps"],"secondaryMuscles":["shoulders","abdominals"],"instructions":["Stand with your feet hip-width apart, holding a kettlebell by the horns with both hands. Press it overhead until your arms are extended, with the bell hanging behind your hands.","Brace your abdominals and keep your upper arms vertical and close to your head. This is your starting position.","Bend at the elbows to lower the kettlebell behind your head, going as far as your shoulder mobility allows without your elbows flaring outward.","Extend your elbows to press the kettlebell back to the starting position, keeping your upper arms still throughout.","Keep your ribcage down and avoid arching your lower back as you extend."],"category":"strength","images":[]}'),
('free-exercise-db', 'Kettlebell_Pass_Between_The_Legs', 'kettlebell-pass-between-legs', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Kettlebell_Pass_Between_The_Legs.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Kettlebell Pass Between The Legs","force":"pull","level":"intermediate","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["abdominals"],"secondaryMuscles":["glutes","hamstrings","shoulders"],"instructions":["Place one kettlebell between your legs and take a comfortable stance. Bend over by pushing your butt out and keeping your back flat.","Pick up a kettlebell and pass it to your other hand between your legs, in the fashion of a \"W\". Go back and forth for several repetitions."],"category":"strength","images":["Kettlebell_Pass_Between_The_Legs/0.jpg","Kettlebell_Pass_Between_The_Legs/1.jpg"],"id":"Kettlebell_Pass_Between_The_Legs"}'),
('free-exercise-db', 'Kettlebell_Pirate_Ships', 'kettlebell-pirate-ships', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Kettlebell_Pirate_Ships.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Kettlebell Pirate Ships","force":"push","level":"beginner","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["shoulders"],"secondaryMuscles":["abdominals"],"instructions":["With a wide stance, hold a kettlebell with both hands. Allow it to hang at waist level with your arms extended. This will be your starting position.","Initiate the movement by turning to one side, swinging the kettlebell to head height. Briefly pause at the top of the motion.","Allow the bell to drop as you rotate to the opposite side, again raising the kettlebell to head height.","Repeat for the desired amount of repetitions."],"category":"strength","images":["Kettlebell_Pirate_Ships/0.jpg","Kettlebell_Pirate_Ships/1.jpg"],"id":"Kettlebell_Pirate_Ships"}'),
('free-exercise-db', 'Kettlebell_Pistol_Squat', 'kettlebell-pistol-squat', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Kettlebell_Pistol_Squat.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Kettlebell Pistol Squat","force":"push","level":"expert","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings","shoulders"],"instructions":["Pick up a kettlebell with two hands and hold it by the horns. Hold one leg off of the floor and squat down on the other.","Squat down by flexing the knee and sitting back with the hips, holding the kettlebell up in front of you.","Hold the bottom position for a second and then reverse the motion, driving through the heel and keeping your head and chest up.","Lower yourself again and repeat."],"category":"strength","images":["Kettlebell_Pistol_Squat/0.jpg","Kettlebell_Pistol_Squat/1.jpg"],"id":"Kettlebell_Pistol_Squat"}'),
('free-exercise-db', 'Kettlebell_Seated_Press', 'kettlebell-seated-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Kettlebell_Seated_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Kettlebell Seated Press","force":"push","level":"intermediate","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["shoulders"],"secondaryMuscles":["triceps"],"instructions":["Sit on the floor and spread your legs out comfortably.","Clean one kettlebell to your shoulder.","Press the kettlebell up and out until it is locked out overhead. Return to the starting position."],"category":"strength","images":["Kettlebell_Seated_Press/0.jpg","Kettlebell_Seated_Press/1.jpg"],"id":"Kettlebell_Seated_Press"}'),
('free-exercise-db', 'Kettlebell_Seesaw_Press', 'kettlebell-seesaw-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Kettlebell_Seesaw_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Kettlebell Seesaw Press","force":"push","level":"intermediate","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["shoulders"],"secondaryMuscles":["triceps"],"instructions":["Clean two kettlebells two your shoulders.","Press one kettlebell.","Lower the kettlebell and immediately press the other kettlebell. Make sure to do the same amount of reps on both sides."],"category":"strength","images":["Kettlebell_Seesaw_Press/0.jpg","Kettlebell_Seesaw_Press/1.jpg"],"id":"Kettlebell_Seesaw_Press"}'),
('free-exercise-db', 'Kettlebell_Sumo_High_Pull', 'kettlebell-sumo-high-pull', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Kettlebell_Sumo_High_Pull.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Kettlebell Sumo High Pull","force":"pull","level":"intermediate","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["traps"],"secondaryMuscles":["adductors","glutes","hamstrings","quadriceps","shoulders"],"instructions":["Place a kettlebell on the ground between your feet. Position your feet in a wide stance, and grasp the kettlebell with two hands. Set your hips back as far as possible, with your knees bent. Keep your chest and head up. This will be your starting position.","Begin by extending the hips and knees, simultaneously pulling the kettlebell to your shoulders, raising your elbows as you do so. Reverse the motion to return to the starting position."],"category":"strength","images":["Kettlebell_Sumo_High_Pull/0.jpg","Kettlebell_Sumo_High_Pull/1.jpg"],"id":"Kettlebell_Sumo_High_Pull"}'),
('free-exercise-db', 'Kettlebell_Thruster', 'kettlebell-thruster', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Kettlebell_Thruster.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Kettlebell Thruster","force":"push","level":"intermediate","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["shoulders"],"secondaryMuscles":["quadriceps","triceps"],"instructions":["Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so. This will be your starting position.","Begin to squat by flexing your hips and knees, lowering your hips between your legs. Maintain an upright, straight back as you descend as low as you can.","At the bottom, reverse direction and squat by extending your knees and hips, driving through your heels. As you do so, press both kettlebells overhead by extending your arms straight up, using the momentum from the squat to help drive the weights upward.","As you begin the next repetition, return the weights to the shoulders."],"category":"strength","images":["Kettlebell_Thruster/0.jpg","Kettlebell_Thruster/1.jpg"],"id":"Kettlebell_Thruster"}'),
('free-exercise-db', 'Kettlebell_Turkish_Get-Up_Lunge_style', 'kettlebell-turkish-get-up-lunge-style', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Kettlebell_Turkish_Get-Up_Lunge_style.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Kettlebell Turkish Get-Up (Lunge style)","force":"push","level":"intermediate","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["shoulders"],"secondaryMuscles":["abdominals","hamstrings","quadriceps","triceps"],"instructions":["Lie on your back on the floor and press a kettlebell to the top position by extending the elbow. Bend the knee on the same side as the kettlebell.","Keeping the kettlebell locked out at all times, pivot to the opposite side and use your non- working arm to assist you in driving forward to the lunge position. Using your free hand, push yourself to a seated position, then progressing to one knee.","While looking up at the kettlebell, slowly stand up. Reverse the motion back to the starting position and repeat."],"category":"strength","images":["Kettlebell_Turkish_Get-Up_Lunge_style/0.jpg","Kettlebell_Turkish_Get-Up_Lunge_style/1.jpg"],"id":"Kettlebell_Turkish_Get-Up_Lunge_style"}'),
('free-exercise-db', 'Kettlebell_Turkish_Get-Up_Squat_style', 'kettlebell-turkish-get-up-squat-style', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Kettlebell_Turkish_Get-Up_Squat_style.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Kettlebell Turkish Get-Up (Squat style)","force":"push","level":"intermediate","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["shoulders"],"secondaryMuscles":["abdominals","calves","hamstrings","quadriceps","triceps"],"instructions":["Lie on your back on the floor and press a kettlebell to the top position by extending the elbow. Bend the knee on the same side as the kettlebell.","Keeping the kettlebell locked out at all times, pivot to the opposite side and use your non- working arm to assist you in driving forward to the lunge position.","Using your free hand, push yourself to a seated position, then progressing to your feet. While looking up at the kettlebell, slowly stand up. Reverse the motion back to the starting position and repeat."],"category":"strength","images":["Kettlebell_Turkish_Get-Up_Squat_style/0.jpg","Kettlebell_Turkish_Get-Up_Squat_style/1.jpg"],"id":"Kettlebell_Turkish_Get-Up_Squat_style"}'),
('free-exercise-db', 'Kettlebell_Windmill', 'kettlebell-windmill', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Kettlebell_Windmill.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Kettlebell Windmill","force":"pull","level":"intermediate","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["abdominals"],"secondaryMuscles":["glutes","hamstrings","shoulders","triceps"],"instructions":["Place a kettlebell in front of your lead foot and clean and press it overhead with your opposite arm. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulders. Rotate your wrist as you do so, so that the palm faces forward. Press it overhead by extending the elbow.","Keeping the kettlebell locked out at all times, push your butt out in the direction of the locked out kettlebell. Turn your feet out at a forty-five degree angle from the arm with the locked out kettlebell. Bending at the hip to one side, sticking your butt out, slowly lean until you can touch the floor with your free hand. Keep your eyes on the kettlebell that you hold over your head at all times.","Pause for a second after reaching the ground and reverse the motion back to the starting position."],"category":"strength","images":["Kettlebell_Windmill/0.jpg","Kettlebell_Windmill/1.jpg"],"id":"Kettlebell_Windmill"}'),
('free-exercise-db', 'Kipping_Muscle_Up', 'kipping-muscle-up', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Kipping_Muscle_Up.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Kipping Muscle Up","force":"pull","level":"intermediate","mechanic":"compound","equipment":"other","primaryMuscles":["lats"],"secondaryMuscles":["abdominals","biceps","forearms","middle back","shoulders","traps","triceps"],"instructions":["Grip the rings using a false grip, with the base of your palms on top of the rings.","Begin with a movement swinging your legs backward slightly.","Counter that movement by swinging your legs forward and up, jerking your chin and chest back, pulling yourself up with both arms as you do so. As you reach the top position of the pull-up, pull the rings to your armpits as you roll your shoulders forward, allowing your elbows to move straight back behind you. This puts you into the proper position to continue into the dip portion of the movement.","Maintaining control and stability, extend through the elbow to complete the motion.","Use care when lowering yourself to the ground."],"category":"strength","images":["Kipping_Muscle_Up/0.jpg","Kipping_Muscle_Up/1.jpg"],"id":"Kipping_Muscle_Up"}'),
('free-exercise-db', 'Knee_Across_The_Body', 'knee-across-body', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Knee_Across_The_Body.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Knee Across The Body","force":"static","level":"beginner","mechanic":null,"equipment":null,"primaryMuscles":["glutes"],"secondaryMuscles":["abductors","lower back"],"instructions":["Lie down on the floor with your right leg straight. Bend your left leg and lower it across your body, holding the knee down toward the floor with your right hand. (The knee doesn''t need to touch the floor if you''re tight.)","Place your left arm comfortably beside you and turn your head to the left. Imagine you have a weight tied to your tailbone. let your tailbone fall back toward the floor as your chest reaches in the opposite direction to stretch your lower back. Switch sides."],"category":"stretching","images":["Knee_Across_The_Body/0.jpg","Knee_Across_The_Body/1.jpg"],"id":"Knee_Across_The_Body"}'),
('free-exercise-db', 'Knee_Circles', 'knee-circle', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Knee_Circles.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Knee Circles","force":"pull","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["calves"],"secondaryMuscles":["hamstrings","quadriceps"],"instructions":["Stand with your legs together and hands by your waist.","Now move your knees in a circular motion as you breathe normally.","Repeat for the recommended amount of repetitions."],"category":"stretching","images":["Knee_Circles/0.jpg","Knee_Circles/1.jpg"],"id":"Knee_Circles"}'),
('free-exercise-db', 'Knee_Hip_Raise_On_Parallel_Bars', 'knee-hip-raise-parallel-bars', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Knee_Hip_Raise_On_Parallel_Bars.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Knee/Hip Raise On Parallel Bars","force":"pull","level":"beginner","mechanic":"isolation","equipment":"other","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Position your body on the vertical leg raise bench so that your forearms are resting on the pads next to the torso and holding on to the handles. Your arms will be bent at a 90 degree angle.","The torso should be straight with the lower back pressed against the pad of the machine and the legs extended pointing towards the floor. This will be your starting position.","Now as you breathe out, lift your legs up as you keep them extended. Continue this movement until your legs are roughly parallel to the floor and then hold the contraction for a second. Tip: Do not use any momentum or swinging as you perform this exercise.","Slowly go back to the starting position as you breathe in.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Knee_Hip_Raise_On_Parallel_Bars/0.jpg","Knee_Hip_Raise_On_Parallel_Bars/1.jpg"],"id":"Knee_Hip_Raise_On_Parallel_Bars"}'),
('free-exercise-db', 'Knee_Tuck_Jump', 'knee-tuck-jump', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Knee_Tuck_Jump.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Knee Tuck Jump","force":"push","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["hamstrings"],"secondaryMuscles":["abductors","adductors","calves","glutes","quadriceps"],"instructions":["Begin in a comfortable standing position with your knees slightly bent. Hold your hands in front of you, palms down with your fingertips together at chest height. This will be your starting position.","Rapidly dip down into a quarter squat and immediately explode upward. Drive the knees towards the chest, attempting to touch them to the palms of the hands.","Jump as high as you can, raising your knees up, and then ensure a good land be re-extending your legs, absorbing impact through be allowing the knees to rebend."],"category":"plyometrics","images":["Knee_Tuck_Jump/0.jpg","Knee_Tuck_Jump/1.jpg"],"id":"Knee_Tuck_Jump"}'),
('free-exercise-db', 'Kneeling_Arm_Drill', 'kneeling-arm-drill', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Kneeling_Arm_Drill.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Kneeling Arm Drill","force":"pull","level":"beginner","mechanic":null,"equipment":null,"primaryMuscles":["shoulders"],"secondaryMuscles":["abdominals"],"instructions":["This drill helps increase arm efficiency during the run. Begin kneeling, left foot in front, right knee down. Apply pressure through the front heel to keep your glutes and hamstrings activated.","Begin by blocking the arms in long, pendulum like swings. Close the arm angle, blocking with the arms as you would when jogging, progressing to a run and finally a sprint.","As soon as your hands pass the hip, accelerate them forward during the sprinting motion to move them as quickly as possible.","Switch knees and repeat."],"category":"plyometrics","images":["Kneeling_Arm_Drill/0.jpg","Kneeling_Arm_Drill/1.jpg"],"id":"Kneeling_Arm_Drill"}'),
('free-exercise-db', 'Kneeling_Cable_Crunch_With_Alternating_Oblique_Twists', 'cable-kneeling-crunch-alternating-oblique-twist', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Kneeling_Cable_Crunch_With_Alternating_Oblique_Twists.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Kneeling Cable Crunch With Alternating Oblique Twists","force":"pull","level":"beginner","mechanic":"isolation","equipment":"cable","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Connect a rope attachment to a high pulley cable and position a mat on the floor in front of it.","Grab the rope with both hands and kneel approximately two feet back from the tower.","Position the rope behind your head with your hands by your ears.","Keep your hands in the same place, contract your abs and pull downward on the rope in a crunching movement until your elbows reach your knees.","Pause briefly at the bottom and rise up in a slow and controlled manner until you reach the starting position.","Repeat the same downward movement until you''re halfway down, at which time you''ll begin rotating one of your elbows to the opposite knee.","Again, pause briefly at the bottom and rise up in a slow and controlled manner until you reach the starting position.","Repeat the same movement as before, but alternate the other elbow to the opposite knee.","Continue this series of movements to failure."],"category":"strength","images":["Kneeling_Cable_Crunch_With_Alternating_Oblique_Twists/0.jpg","Kneeling_Cable_Crunch_With_Alternating_Oblique_Twists/1.jpg"],"id":"Kneeling_Cable_Crunch_With_Alternating_Oblique_Twists"}'),
('free-exercise-db', 'Kneeling_Cable_Triceps_Extension', 'cable-kneeling-triceps-extension', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Kneeling_Cable_Triceps_Extension.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Kneeling Cable Triceps Extension","force":"push","level":"intermediate","mechanic":"isolation","equipment":"cable","primaryMuscles":["triceps"],"secondaryMuscles":[],"instructions":["Place a bench sideways in front of a high pulley machine.","Hold a straight bar attachment above your head with your hands about 6 inches apart with your palms facing down.","Face away from the machine and kneel.","Place your head and the back of your upper arms on the bench. Your elbows should be bent with the forearms pointing towards the high pulley. This will be your starting position.","While keeping your upper arms close to your head at all times with the elbows in, press the bar out in a semicircular motion until the elbows are locked and your arms are parallel to the floor. Contract the triceps hard and keep this position for a second. Exhale as you perform this movement.","Slowly return to the starting position as you breathe in.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Kneeling_Cable_Triceps_Extension/0.jpg","Kneeling_Cable_Triceps_Extension/1.jpg"],"id":"Kneeling_Cable_Triceps_Extension"}'),
('free-exercise-db', 'Kneeling_Forearm_Stretch', 'kneeling-forearm-stretch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Kneeling_Forearm_Stretch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Kneeling Forearm Stretch","force":"static","level":"beginner","mechanic":"isolation","equipment":null,"primaryMuscles":["forearms"],"secondaryMuscles":[],"instructions":["Start by kneeling on a mat with your palms flat and your fingers pointing back toward your knees.","Slowly lean back keeping your palms flat on the floor until you feel a stretch in your wrists and forearms. Hold for 20-30 seconds."],"category":"stretching","images":["Kneeling_Forearm_Stretch/0.jpg","Kneeling_Forearm_Stretch/1.jpg"],"id":"Kneeling_Forearm_Stretch"}'),
('free-exercise-db', 'Kneeling_High_Pulley_Row', 'cable-kneeling-high-pulley-row', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Kneeling_High_Pulley_Row.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Kneeling High Pulley Row","force":"pull","level":"beginner","mechanic":"compound","equipment":"cable","primaryMuscles":["lats"],"secondaryMuscles":["biceps","middle back"],"instructions":["Select the appropriate weight using a pulley that is above your head. Attach a rope to the cable and kneel a couple of feet away, holding the rope out in front of you with both arms extended. This will be your starting position.","Initiate the movement by flexing the elbows and fully retracting your shoulders, pulling the rope toward your upper chest with your elbows out.","After pausing briefly, slowly return to the starting position."],"category":"strength","images":["Kneeling_High_Pulley_Row/0.jpg","Kneeling_High_Pulley_Row/1.jpg"],"id":"Kneeling_High_Pulley_Row"}'),
('free-exercise-db', 'Kneeling_Hip_Flexor', 'kneeling-hip-flexor', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Kneeling_Hip_Flexor.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Kneeling Hip Flexor","force":"static","level":"beginner","mechanic":"isolation","equipment":null,"primaryMuscles":["quadriceps"],"secondaryMuscles":["quadriceps"],"instructions":["Kneel on a mat and bring your right knee up so the bottom of your foot is on the floor and extend your left leg out behind you so the top of your foot is on the floor.","Shift your weight forward until you feel a stretch in your hip. Hold for 15 seconds, then repeat for your other side."],"category":"stretching","images":["Kneeling_Hip_Flexor/0.jpg","Kneeling_Hip_Flexor/1.jpg"],"id":"Kneeling_Hip_Flexor"}');
INSERT INTO source_records (source_id, source_record_id, exercise_id, source_url, license, author, match_method, match_score, raw_json) VALUES
('free-exercise-db', 'Kneeling_Jump_Squat', 'barbell-kneeling-jump-squat', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Kneeling_Jump_Squat.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Kneeling Jump Squat","force":"push","level":"expert","mechanic":"compound","equipment":"barbell","primaryMuscles":["glutes"],"secondaryMuscles":["calves","hamstrings","quadriceps"],"instructions":["Begin kneeling on the floor with a barbell racked across the back of your shoulders, or you can use your body weight for this exercise. This can be done inside of a power rack to make unracking easier.","Sit back with your hips until your glutes touch your feet, keeping your head and chest up.","Explode up with your hips, generating enough power to land with your feet flat on the floor.","Continue with the squat by driving through your heels and extending the knees to come to a standing position."],"category":"olympic weightlifting","images":["Kneeling_Jump_Squat/0.jpg","Kneeling_Jump_Squat/1.jpg"],"id":"Kneeling_Jump_Squat"}'),
('free-exercise-db', 'Kneeling_Single-Arm_High_Pulley_Row', 'cable-kneeling-single-arm-high-pulley-row', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Kneeling_Single-Arm_High_Pulley_Row.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Kneeling Single-Arm High Pulley Row","force":"pull","level":"beginner","mechanic":"compound","equipment":"cable","primaryMuscles":["lats"],"secondaryMuscles":["biceps","middle back"],"instructions":["Attach a single handle to a high pulley and make your weight selection.","Kneel in front of the cable tower, taking the cable with one hand with your arm extended. This will be your starting position.","Starting with your palm facing forward, pull the weight down to your torso by flexing the elbow and retract the shoulder blade. As you do so, rotate the wrist so that at the completion of the movement, your palm is now facing you.","After a brief pause, return to the starting position."],"category":"strength","images":["Kneeling_Single-Arm_High_Pulley_Row/0.jpg","Kneeling_Single-Arm_High_Pulley_Row/1.jpg"],"id":"Kneeling_Single-Arm_High_Pulley_Row"}'),
('free-exercise-db', 'Kneeling_Squat', 'barbell-kneeling-squat', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Kneeling_Squat.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Kneeling Squat","force":"push","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["glutes"],"secondaryMuscles":["abdominals","hamstrings","lower back"],"instructions":["Set the bar to the proper height in a power rack. Kneel behind the bar; it may be beneficial to put a mat down to pad your knees. Slide under the bar, racking it across the back of your shoulders. Your shoulder blades should be retracted and the bar tight across your back. Unrack the weight.","With your head looking forward, sit back with your butt until you touch your calves.","Reverse the motion, returning the torso to an upright position."],"category":"powerlifting","images":["Kneeling_Squat/0.jpg","Kneeling_Squat/1.jpg"],"id":"Kneeling_Squat"}'),
('free-exercise-db', 'Landmine_180s', 'barbell-landmine-180s', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Landmine_180s.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Landmine 180''s","force":"pull","level":"beginner","mechanic":"compound","equipment":"barbell","primaryMuscles":["abdominals"],"secondaryMuscles":["glutes","lower back","shoulders"],"instructions":["Position a bar into a landmine or securely anchor it in a corner. Load the bar to an appropriate weight.","Raise the bar from the floor, taking it to shoulder height with both hands with your arms extended in front of you. Adopt a wide stance. This will be your starting position.","Perform the movement by rotating the trunk and hips as you swing the weight all the way down to one side. Keep your arms extended throughout the exercise.","Reverse the motion to swing the weight all the way to the opposite side.","Continue alternating the movement until the set is complete."],"category":"strength","images":["Landmine_180s/0.jpg","Landmine_180s/1.jpg"],"id":"Landmine_180s"}'),
('free-exercise-db', 'Landmine_Linear_Jammer', 'barbell-landmine-linear-jammer', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Landmine_Linear_Jammer.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Landmine Linear Jammer","force":"push","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["shoulders"],"secondaryMuscles":["abdominals","calves","chest","hamstrings","quadriceps","triceps"],"instructions":["Position a bar into landmine or, lacking one, securely anchor it in a corner. Load the bar to an appropriate weight and position the handle attachment on the bar.","Raise the bar from the floor, taking the handles to your shoulders. This will be your starting position.","In an athletic stance, squat by flexing your hips and setting your hips back, keeping your arms flexed.","Reverse the motion by powerfully extending through the hips, knees, and ankles, while also extending the elbows to straighten the arms. This movement should be done explosively, coming out of the squat to full extension as powerfully as possible.","Return to the starting position."],"category":"strength","images":["Landmine_Linear_Jammer/0.jpg","Landmine_Linear_Jammer/1.jpg"],"id":"Landmine_Linear_Jammer"}'),
('free-exercise-db', 'Lateral_Bound', 'lateral-bound', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Lateral_Bound.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Lateral Bound","force":"push","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["adductors"],"secondaryMuscles":["abductors","calves","glutes","hamstrings","quadriceps"],"instructions":["Assume a half squat position facing 90 degrees from your direction of travel. This will be your starting position.","Allow your lead leg to do a countermovement inward as you shift your weight to the outside leg.","Immediately push off and extend, attempting to bound to the side as far as possible.","Upon landing, immediately push off in the opposite direction, returning to your original start position.","Continue back and forth for several repetitions."],"category":"plyometrics","images":["Lateral_Bound/0.jpg","Lateral_Bound/1.jpg"],"id":"Lateral_Bound"}'),
('free-exercise-db', 'Lateral_Box_Jump', 'lateral-box-jump', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Lateral_Box_Jump.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Lateral Box Jump","force":"push","level":"beginner","mechanic":"compound","equipment":"other","primaryMuscles":["adductors"],"secondaryMuscles":["abductors","calves","glutes","hamstrings","quadriceps"],"instructions":["Assume a comfortable standing position, with a short box positioned next to you. This will be your starting position.","Quickly dip into a quarter squat to initiate the stretch reflex, and immediately reverse direction to jump up and to the side.","Bring your knees high enough to ensure your feet have good clearance over the box.","Land on the center of the box, using your legs to absorb the impact.","Carefully jump down to the other side of the box, and continue going back and forth for several repetitions."],"category":"plyometrics","images":["Lateral_Box_Jump/0.jpg","Lateral_Box_Jump/1.jpg"],"id":"Lateral_Box_Jump"}'),
('free-exercise-db', 'Lateral_Cone_Hops', 'lateral-cone-hop', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Lateral_Cone_Hops.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Lateral Cone Hops","force":"push","level":"beginner","mechanic":"compound","equipment":"other","primaryMuscles":["adductors"],"secondaryMuscles":["abductors","calves","glutes","hamstrings","quadriceps"],"instructions":["Position a number of cones in a row several feet apart.","Stand next to the end of the cones, facing 90 degrees to the direction of travel. This will be your starting position.","Begin the jump by dipping with the knees to initiate a stretch reflex, and immediately reverse direction to push off the ground, jumping up and sideways over the cone.","Use your legs to absorb impact upon landing, and rebound into the next jump, continuing down the row of cones."],"category":"plyometrics","images":["Lateral_Cone_Hops/0.jpg","Lateral_Cone_Hops/1.jpg"],"id":"Lateral_Cone_Hops"}'),
('free-exercise-db', 'Lateral_Raise_-_With_Bands', 'band-lateral-raise', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Lateral_Raise_-_With_Bands.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Lateral Raise - With Bands","force":"push","level":"beginner","mechanic":"isolation","equipment":"bands","primaryMuscles":["shoulders"],"secondaryMuscles":[],"instructions":["To begin, stand on an exercise band so that tension begins at arm''s length. Grasp the handles using a pronated (palms facing your thighs) grip that is slightly less than shoulder width. The handles should be resting on the sides of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position.","Use your side shoulders to lift the handles to the sides as you exhale. Continue to lift the handles until they are slightly above parallel. Tip: As you lift the handles, slightly tilt the hand as if you were pouring water and keep your arms extended. Also, keep your torso stationary and pause for a second at the top of the movement.","Lower the handles back down slowly to the starting position. Inhale as you perform this portion of the movement.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Lateral_Raise_-_With_Bands/0.jpg","Lateral_Raise_-_With_Bands/1.jpg"],"id":"Lateral_Raise_-_With_Bands"}'),
('free-exercise-db', 'Latissimus_Dorsi-SMR', 'foam-roller-latissimus-dorsi-smr', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Latissimus_Dorsi-SMR.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Latissimus Dorsi-SMR","force":"static","level":"beginner","mechanic":"isolation","equipment":"foam roll","primaryMuscles":["lats"],"secondaryMuscles":[],"instructions":["While lying on the floor, place a foam roll under your back and to one side, just behind your arm pit. This will be your starting position.","Keep the arm of the side being stretched behind and to the side of you as you shift your weight onto your lats, keeping your upper body off of the ground. Hold for 10-30 seconds, and switch sides."],"category":"stretching","images":["Latissimus_Dorsi-SMR/0.jpg","Latissimus_Dorsi-SMR/1.jpg"],"id":"Latissimus_Dorsi-SMR"}'),
('free-exercise-db', 'Leg-Over_Floor_Press', 'kettlebell-leg-over-floor-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Leg-Over_Floor_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Leg-Over Floor Press","force":"push","level":"intermediate","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["Lie on the floor with one kettlebell in place on your chest, holding it by the handle. Extend leg on working side over leg on non-working side.Your free arm can be extended out to your side for support.","Press the kettlebll into a locked out position.","Lower the weight until the elbow touches the ground, keeping the kettlebell above the elbow. Repeat for the desired number of repetitions."],"category":"strength","images":["Leg-Over_Floor_Press/0.jpg","Leg-Over_Floor_Press/1.jpg"],"id":"Leg-Over_Floor_Press"}'),
('free-exercise-db', 'Leg-Up_Hamstring_Stretch', 'leg-up-hamstring-stretch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Leg-Up_Hamstring_Stretch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Leg-Up Hamstring Stretch","force":"push","level":"beginner","mechanic":"isolation","equipment":null,"primaryMuscles":["hamstrings"],"secondaryMuscles":[],"instructions":["Lie flat on your back, bend one knee, and put that foot flat on the floor to stabilize your spine.","Extend the other leg in the air. If you''re tight, you wont be able to straighten it. That''s okay. Extend the knee so that the sole of the lifted foot faces the ceiling (or as close as you can get it).","Slowly straighten the legs as much as possible and then pull the leg toward your nose. Switch sides."],"category":"stretching","images":["Leg-Up_Hamstring_Stretch/0.jpg","Leg-Up_Hamstring_Stretch/1.jpg"],"id":"Leg-Up_Hamstring_Stretch"}'),
('free-exercise-db', 'Leg_Extensions', 'machine-leg-extension', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Leg_Extensions.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Leg Extensions","force":"push","level":"beginner","mechanic":"isolation","equipment":"machine","primaryMuscles":["quadriceps"],"secondaryMuscles":[],"instructions":["For this exercise you will need to use a leg extension machine. First choose your weight and sit on the machine with your legs under the pad (feet pointed forward) and the hands holding the side bars. This will be your starting position. Tip: You will need to adjust the pad so that it falls on top of your lower leg (just above your feet). Also, make sure that your legs form a 90-degree angle between the lower and upper leg. If the angle is less than 90-degrees then that means the knee is over the toes which in turn creates undue stress at the knee joint. If the machine is designed that way, either look for another machine or just make sure that when you start executing the exercise you stop going down once you hit the 90-degree angle.","Using your quadriceps, extend your legs to the maximum as you exhale. Ensure that the rest of the body remains stationary on the seat. Pause a second on the contracted position.","Slowly lower the weight back to the original position as you inhale, ensuring that you do not go past the 90-degree angle limit.","Repeat for the recommended amount of times."],"category":"strength","images":["Leg_Extensions/0.jpg","Leg_Extensions/1.jpg"],"id":"Leg_Extensions"}'),
('free-exercise-db', 'Leg_Lift', 'leg-lift', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Leg_Lift.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Leg Lift","force":"push","level":"beginner","mechanic":"isolation","equipment":"body only","primaryMuscles":["glutes"],"secondaryMuscles":["hamstrings"],"instructions":["While standing up straight with both feet next to each other at around shoulder width, grab a sturdy surface such as the sides of a squat rack or the top of a chair to brace yourself and keep balance.","With or without an ankle weight, lift one leg behind you as if performing a leg curl but standing up while keeping the other leg straight. Breathe out as you perform this movement.","Slowly bring the raised leg back to the floor as you breathe in.","Repeat for the recommended amount of repetitions.","Repeat the movement with the opposite leg."],"category":"strength","images":["Leg_Lift/0.jpg","Leg_Lift/1.jpg"],"id":"Leg_Lift"}'),
('free-exercise-db', 'Leg_Press', 'machine-leg-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Leg_Press.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Leg Press","force":"push","level":"beginner","mechanic":"compound","equipment":"machine","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings"],"instructions":["Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).","Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you. Tip: Make sure that you do not lock your knees. Your torso and the legs should make a perfect 90-degree angle. This will be your starting position.","As you inhale, slowly lower the platform until your upper and lower legs make a 90-degree angle.","Pushing mainly with the heels of your feet and using the quadriceps go back to the starting position as you exhale.","Repeat for the recommended amount of repetitions and ensure to lock the safety pins properly once you are done. You do not want that platform falling on you fully loaded."],"category":"strength","images":["Leg_Press/0.jpg","Leg_Press/1.jpg"],"id":"Leg_Press"}'),
('free-exercise-db', 'Leg_Pull-In', 'flat-bench-leg-pull-in', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Leg_Pull-In.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Leg Pull-In","force":"pull","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Lie on an exercise mat with your legs extended and your hands either palms facing down next to you or under your glutes. Tip: My preference is with the hands next to me. This will be your starting position.","Bend your knees and pull your upper thighs into your midsection as you breathe out. Continue the motion until your knees are around chest level. Contract your abs as you execute this movement and hold for a second at the top. Tip: As you perform the motion, the lower legs (calves) should always remain parallel to the floor.","Return to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Leg_Pull-In/0.jpg","Leg_Pull-In/1.jpg"],"id":"Leg_Pull-In"}'),
('free-exercise-db', 'Leverage_Chest_Press', 'machine-leverage-chest-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Leverage_Chest_Press.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Leverage Chest Press","force":"push","level":"beginner","mechanic":"compound","equipment":"machine","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the bottom or middle of the pectorals at the beginning of the motion.","Your chest and head should be up and your shoulder blades retracted. This will be your starting position.","Press the handles forward by extending through the elbow.","After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete."],"category":"strength","images":["Leverage_Chest_Press/0.jpg","Leverage_Chest_Press/1.jpg"],"id":"Leverage_Chest_Press"}'),
('free-exercise-db', 'Leverage_Deadlift', 'machine-leverage-deadlift', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Leverage_Deadlift.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Leverage Deadlift","force":"pull","level":"beginner","mechanic":"compound","equipment":"machine","primaryMuscles":["quadriceps"],"secondaryMuscles":["glutes","hamstrings"],"instructions":["Load the pins to an appropriate weight. Position yourself directly between the handles. Grasp the bottom handles with a comfortable grip, and then lower your hips as you take a breath. Look forward with your head and keep your chest up. This will be your starting position.","Return the weight to the starting position."],"category":"strength","images":["Leverage_Deadlift/0.jpg","Leverage_Deadlift/1.jpg"],"id":"Leverage_Deadlift"}'),
('free-exercise-db', 'Leverage_Decline_Chest_Press', 'machine-leverage-decline-chest-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Leverage_Decline_Chest_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Leverage Decline Chest Press","force":"push","level":"beginner","mechanic":"compound","equipment":"machine","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the bottom of the pectorals at the beginning of the motion. Your chest and head should be up and your shoulder blades retracted. This will be your starting position.","Press the handles forward by extending through the elbow.","After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete."],"category":"strength","images":["Leverage_Decline_Chest_Press/0.jpg","Leverage_Decline_Chest_Press/1.jpg"],"id":"Leverage_Decline_Chest_Press"}'),
('free-exercise-db', 'Leverage_High_Row', 'machine-leverage-high-row', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Leverage_High_Row.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Leverage High Row","force":"pull","level":"beginner","mechanic":"compound","equipment":"machine","primaryMuscles":["middle back"],"secondaryMuscles":["lats"],"instructions":["Load an appropriate weight onto the pins and adjust the seat height so that you can just reach the handles above you. Adjust the knee pad to help keep you down. Grasp the handles with a pronated grip. This will be your starting position.","Pull the handles towards your torso, retracting your shoulder blades as you flex the elbow.","Pause at the bottom of the motion, and then slowly return the handles to the starting position.","For multiple repetitions, avoid completely returning the weight to the stops to keep tension on the muscles being worked."],"category":"strength","images":["Leverage_High_Row/0.jpg","Leverage_High_Row/1.jpg"],"id":"Leverage_High_Row"}'),
('free-exercise-db', 'Leverage_Incline_Chest_Press', 'machine-leverage-incline-chest-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Leverage_Incline_Chest_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Leverage Incline Chest Press","force":"push","level":"beginner","mechanic":"compound","equipment":"machine","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the top of the pectorals at the beginning of the motion. Your chest and head should be up and your shoulder blades retracted. This will be your starting position.","Press the handles forward by extending through the elbow.","After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete."],"category":"strength","images":["Leverage_Incline_Chest_Press/0.jpg","Leverage_Incline_Chest_Press/1.jpg"],"id":"Leverage_Incline_Chest_Press"}'),
('free-exercise-db', 'Leverage_Iso_Row', 'machine-leverage-iso-row', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Leverage_Iso_Row.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Leverage Iso Row","force":"pull","level":"beginner","mechanic":"compound","equipment":"machine","primaryMuscles":["lats"],"secondaryMuscles":["biceps","middle back"],"instructions":["Load an appropriate weight onto the pins and adjust the seat height so that the handles are at chest level. Grasp the handles with either a neutral or pronated grip. This will be your starting position.","Pull the handles towards your torso, retracting your shoulder blades as you flex the elbow.","Pause at the bottom of the motion, and then slowly return the handles to the starting position. For multiple repetitions, avoid completely returning the weight to the stops to keep tension on the muscles being worked."],"category":"strength","images":["Leverage_Iso_Row/0.jpg","Leverage_Iso_Row/1.jpg"],"id":"Leverage_Iso_Row"}'),
('free-exercise-db', 'Leverage_Shoulder_Press', 'machine-leverage-shoulder-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Leverage_Shoulder_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Leverage Shoulder Press","force":"push","level":"beginner","mechanic":"compound","equipment":"machine","primaryMuscles":["shoulders"],"secondaryMuscles":["triceps"],"instructions":["Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the top of the shoulders at the beginning of the motion. Your chest and head should be up and handles held with a pronated grip. This will be your starting position.","Press the handles upward by extending through the elbow.","After a brief pause at the top, return the weight to just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete."],"category":"strength","images":["Leverage_Shoulder_Press/0.jpg","Leverage_Shoulder_Press/1.jpg"],"id":"Leverage_Shoulder_Press"}'),
('free-exercise-db', 'Leverage_Shrug', 'machine-leverage-shrug', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Leverage_Shrug.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Leverage Shrug","force":"pull","level":"beginner","mechanic":"isolation","equipment":"machine","primaryMuscles":["traps"],"secondaryMuscles":["forearms"],"instructions":["Load the pins to an appropriate weight. Position yourself directly between the handles.","Grasp the top handles with a comfortable grip, and then lower your hips as you take a breath. Look forward with your head and keep your chest up.","Drive through the floor with your heels, extending your hips and knees as you rise to a standing position. Keep your arms straight throughout the movement, finishing with your shoulders back. This will be your starting position.","Raise the weight by shrugging the shoulders towards your ears, moving straight up and down.","Pause at the top of the motion, and then return the weight to the starting position."],"category":"strength","images":["Leverage_Shrug/0.jpg","Leverage_Shrug/1.jpg"],"id":"Leverage_Shrug"}'),
('free-exercise-db', 'Linear_3-Part_Start_Technique', 'linear-3-part-start-technique', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Linear_3-Part_Start_Technique.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Linear 3-Part Start Technique","force":"push","level":"beginner","mechanic":"compound","equipment":null,"primaryMuscles":["hamstrings"],"secondaryMuscles":["calves","quadriceps"],"instructions":["This drill helps you accelerate as quickly as possible into a sprint from a dead stop. It helps to use a line to start from. Begin with two feet on the line. Place your left foot with the toe next to your right ankle. Place your right foot 4-6 inches behind the left.","Place your right hand onto the line, and thing bring your nose close to your left knee.","Squat down as you lean foward, your head being lower than your hips and your weight loaded onto the left leg. This will be your starting position.","Take your left hand up so that it is parallel to the ground, pointing behind you, and explode out when ready."],"category":"plyometrics","images":["Linear_3-Part_Start_Technique/0.jpg","Linear_3-Part_Start_Technique/1.jpg"],"id":"Linear_3-Part_Start_Technique"}'),
('free-exercise-db', 'Linear_Acceleration_Wall_Drill', 'linear-acceleration-wall-drill', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Linear_Acceleration_Wall_Drill.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Linear Acceleration Wall Drill","force":null,"level":"beginner","mechanic":"compound","equipment":null,"primaryMuscles":["hamstrings"],"secondaryMuscles":["calves","glutes","quadriceps"],"instructions":["Lean at around 45 degrees against a wall. Your feet should be together, glutes contracted.","Begin by lifting your right knee quickly, pausing, and then driving it straight down into the ground.","Switch legs, raising the opposite knee, and then attacking the ground straight down.","Repeat once more with your right leg, and as soon as the right foot strikes the ground hammer them out rapidly, alternating left and right as fast as you can."],"category":"plyometrics","images":["Linear_Acceleration_Wall_Drill/0.jpg","Linear_Acceleration_Wall_Drill/1.jpg"],"id":"Linear_Acceleration_Wall_Drill"}'),
('free-exercise-db', 'Linear_Depth_Jump', 'linear-depth-jump', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Linear_Depth_Jump.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Linear Depth Jump","force":"push","level":"intermediate","mechanic":"compound","equipment":"other","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings"],"instructions":["You will need two boxes or benches spaced a few feet away from each other. Begin by standing on one box facing towards the other platform.","To initiate the movement, gently drop down to the ground between your platforms, allowing the knees and hips to flex.","Reverse the motion by exploding, extending through the hips, knees, and ankles to jump onto the other platform.","Land softly, asborbing the impact through the legs."],"category":"plyometrics","images":["Linear_Depth_Jump/0.jpg","Linear_Depth_Jump/1.jpg"],"id":"Linear_Depth_Jump"}'),
('free-exercise-db', 'Log_Lift', 'log-lift', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Log_Lift.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Log Lift","force":"push","level":"intermediate","mechanic":"compound","equipment":"other","primaryMuscles":["shoulders"],"secondaryMuscles":["abdominals","chest","glutes","hamstrings","lower back","middle back","quadriceps","traps","triceps"],"instructions":["Begin standing with the log in front of you. Grasp the handles, and begin to clean the log. As you are bent over to start the clean, attempt to get the log as high as possible, pulling it into your chest. Extend through the hips and knees to bring it up to complete the clean.","Push your head back and look up, creating a shelf on your chest to rest the log. Begin the press by dipping, flexing slightly through the knees and reversing the motion. This push press will generate momentum to start the log moving vertically. Continue by extending through the elbows to press the log above your head. There are no strict rules on form, so use whatever techniques you are most efficient with. As the log is pressed, ensure that you push your head through on each repetition, looking forward.","Repeat as many times as possible. Attempt to control the descent of the log as it is returned to the ground."],"category":"strongman","images":["Log_Lift/0.jpg","Log_Lift/1.jpg"],"id":"Log_Lift"}'),
('free-exercise-db', 'London_Bridges', 'london-bridge', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/London_Bridges.json', 'Unlicense', NULL, 'new', NULL, '{"name":"London Bridges","force":"pull","level":"intermediate","mechanic":"compound","equipment":"other","primaryMuscles":["lats"],"secondaryMuscles":["biceps","forearms","middle back"],"instructions":["Attach a climbing rope to a high beam or cross member. Below it, ensure that the smith machine bar is locked in place with the safeties and cannot move. Alternatively, a secure box could also be utilized.","Stand on the bar, using the rope to balance yourself. This will be your starting position.","Keeping your body straight, lean back and lower your body by slowly going hand over hand with the rope. Continue until you are perpendicular to the ground.","Keeping your body straight, reverse the motion, going hand over hand back to the starting position."],"category":"strength","images":["London_Bridges/0.jpg","London_Bridges/1.jpg"],"id":"London_Bridges"}'),
('free-exercise-db', 'Looking_At_Ceiling', 'looking-at-ceiling', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Looking_At_Ceiling.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Looking At Ceiling","force":"static","level":"beginner","mechanic":"isolation","equipment":null,"primaryMuscles":["quadriceps"],"secondaryMuscles":[],"instructions":["Kneel on the floor, holding your heels with both hands.","Lift your buttocks up and forward while bringing your head back to look up at the ceiling, to give an arch in your back."],"category":"stretching","images":["Looking_At_Ceiling/0.jpg","Looking_At_Ceiling/1.jpg"],"id":"Looking_At_Ceiling"}'),
('free-exercise-db', 'Low_Cable_Crossover', 'cable-low-crossover', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Low_Cable_Crossover.json', 'Unlicense', NULL, 'new', 89.7, '{"name":"Low Cable Crossover","force":"push","level":"beginner","mechanic":"isolation","equipment":"cable","primaryMuscles":["chest"],"secondaryMuscles":["shoulders"],"instructions":["To move into the starting position, place the pulleys at the low position, select the resistance to be used and grasp a handle in each hand.","Step forward, gaining tension in the pulleys. Your palms should be facing forward, hands below the waist, and your arms straight. This will be your starting position.","With a slight bend in your arms, draw your hands upward and toward the midline of your body. Your hands should come together in front of your chest, palms facing up.","Return your arms back to the starting position after a brief pause."],"category":"strength","images":["Low_Cable_Crossover/0.jpg","Low_Cable_Crossover/1.jpg"],"id":"Low_Cable_Crossover"}'),
('free-exercise-db', 'Low_Cable_Triceps_Extension', 'cable-low-triceps-extension', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Low_Cable_Triceps_Extension.json', 'Unlicense', NULL, 'new', 89.5, '{"name":"Low Cable Triceps Extension","force":"push","level":"beginner","mechanic":"isolation","equipment":"cable","primaryMuscles":["triceps"],"secondaryMuscles":[],"instructions":["Select the desired weight and lay down face up on the bench of a seated row machine that has a rope attached to it. Your head should be pointing towards the attachment.","Grab the outside of the rope ends with your palms facing each other (neutral grip).","Position your elbows so that they are bent at a 90 degree angle and your upper arms are perpendicular (90 degree angle) to your torso. Tip: Keep the elbows in and make sure that the upper arms point to the ceiling while your forearms point towards the pulley above your head. This will be your starting position.","As you breathe out, extend your lower arms until they are straight and vertical. The upper arms and elbows remain stationary throughout the movement. Only the forearms should move. Contract the triceps hard for a second.","As you breathe in slowly return to the starting position.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Low_Cable_Triceps_Extension/0.jpg","Low_Cable_Triceps_Extension/1.jpg"],"id":"Low_Cable_Triceps_Extension"}'),
('free-exercise-db', 'Low_Pulley_Row_To_Neck', 'cable-low-pulley-row-to-neck', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Low_Pulley_Row_To_Neck.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Low Pulley Row To Neck","force":"pull","level":"beginner","mechanic":"compound","equipment":"cable","primaryMuscles":["shoulders"],"secondaryMuscles":["biceps","middle back","traps"],"instructions":["Sit on a low pulley row machine with a rope attachment.","Grab the ends of the rope using a palms-down grip and sit with your back straight and your knees slightly bent. Tip: Keep your back almost completely vertical and your arms fully extended in front of you. This will be your starting position.","While keeping your torso stationary, lift your elbows and start bending them as you pull the rope towards your neck while exhaling. Throughout the movement your upper arms should remain parallel to the floor. Tip: Continue this motion until your hands are almost next to your ears (the forearms will not be parallel to the floor at the end of the movement as they will be angled a bit upwards) and your elbows are out away from your sides.","After holding for a second or so at the contracted position, come back slowly to the starting position as you inhale. Tip: Again, during no part of the movement should the torso move.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Low_Pulley_Row_To_Neck/0.jpg","Low_Pulley_Row_To_Neck/1.jpg"],"id":"Low_Pulley_Row_To_Neck"}'),
('free-exercise-db', 'Lower_Back-SMR', 'foam-roller-lower-back-smr', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Lower_Back-SMR.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Lower Back-SMR","force":"static","level":"beginner","mechanic":null,"equipment":"foam roll","primaryMuscles":["lower back"],"secondaryMuscles":[],"instructions":["In a seated position, place a foam roll under your lower back. Cross your arms in front of you and protract your shoulders. This will be your starting position.","Raise your hips off of the floor and lean back, keeping your weight on your lower back. Now shift your weight slightly to one side, keeping your weight off of the spine and on the muscles to the side of it. Roll over your lower back, holding points of tension for 10-30 seconds. Repeat on the other side."],"category":"stretching","images":["Lower_Back-SMR/0.jpg","Lower_Back-SMR/1.jpg"],"id":"Lower_Back-SMR"}'),
('free-exercise-db', 'Lower_Back_Curl', 'lower-back-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Lower_Back_Curl.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Lower Back Curl","force":"static","level":"beginner","mechanic":null,"equipment":"body only","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Lie on your stomach with your arms out to your sides. This will be your starting position.","Using your lower back muscles, extend your spine lifting your chest off of the ground. Do not use your arms to push yourself up. Keep your head up during the movement. Repeat for 10-20 repetitions."],"category":"stretching","images":["Lower_Back_Curl/0.jpg","Lower_Back_Curl/1.jpg"],"id":"Lower_Back_Curl"}'),
('free-exercise-db', 'Lunge_Pass_Through', 'kettlebell-lunge-pass-through', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Lunge_Pass_Through.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Lunge Pass Through","force":"push","level":"intermediate","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["hamstrings"],"secondaryMuscles":["calves","glutes","quadriceps"],"instructions":["Stand with your torso upright holding a kettlebell in your right hand. This will be your starting position.","Step forward with your left foot and lower your upper body down by flexing the hip and the knee, keeping the torso upright. Lower your back knee until it nearly touches the ground.","As you lunge, pass the kettlebell under your front leg to your opposite hand.","Pressing through the heel of your foot, return to the starting position.","Repeat the movement for the recommended amount of repetitions, alternating legs."],"category":"strength","images":["Lunge_Pass_Through/0.jpg","Lunge_Pass_Through/1.jpg"],"id":"Lunge_Pass_Through"}'),
('free-exercise-db', 'Lunge_Sprint', 'machine-lunge-sprint', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Lunge_Sprint.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Lunge Sprint","force":"push","level":"intermediate","mechanic":"compound","equipment":"machine","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings"],"instructions":["Adjust a bar in a Smith machine to an appropriate height. Position yourself under the bar, racking it across the back of your shoulders. Unrack the bar, and then split your feet, moving one foot forward and one foot back. This will be your starting position.","Lower your back knee nearly to the ground, flexing the knees and lowering your hips as you do so.","At the bottom of the descent, immediately reverse direction. Explosively drive through the heel of your front foot with light pressure from your back foot. Jump up and reverse the position of your legs.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Lunge_Sprint/0.jpg","Lunge_Sprint/1.jpg"],"id":"Lunge_Sprint"}'),
('free-exercise-db', 'Lying_Bent_Leg_Groin', 'lying-bent-leg-groin', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Lying_Bent_Leg_Groin.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Lying Bent Leg Groin","force":"static","level":"expert","mechanic":null,"equipment":"other","primaryMuscles":["adductors"],"secondaryMuscles":[],"instructions":["Lie on your back with your knees bent and the soles of the feet pressed together. Have your partner hold your knees. This will be your starting position.","Attempt to squeeze your knees together, while your partner prevents any movement from occurring.","After 10-20 seconds, relax your muscles as your partner gently pushes your knees towards the floor. Be sure to inform your helper when the stretch is adequate to prevent injury or overstretching."],"category":"stretching","images":["Lying_Bent_Leg_Groin/0.jpg","Lying_Bent_Leg_Groin/1.jpg"],"id":"Lying_Bent_Leg_Groin"}'),
('free-exercise-db', 'Lying_Cable_Curl', 'cable-lying-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Lying_Cable_Curl.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Lying Cable Curl","force":"pull","level":"intermediate","mechanic":"isolation","equipment":"cable","primaryMuscles":["biceps"],"secondaryMuscles":[],"instructions":["Grab a straight bar or E-Z bar attachment that is attached to the low pulley with both hands, using an underhand (palms facing up) shoulder-width grip.","Lie flat on your back on top of an exercise mat in front of the weight stack with your feet flat against the frame of the pulley machine and your legs straight.","With your arms extended and your elbows close to your body slightly bend your arms. This will be your starting position.","While keeping your upper arms stationary and the elbows close to your body, curl the bar up slowly toward your chest as you breathe out and you squeeze the biceps.","After a second squeeze at the top of the movement, slowly return to the starting position.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Lying_Cable_Curl/0.jpg","Lying_Cable_Curl/1.jpg"],"id":"Lying_Cable_Curl"}'),
('free-exercise-db', 'Lying_Cambered_Barbell_Row', 'barbell-lying-cambered-row', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Lying_Cambered_Barbell_Row.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Lying Cambered Barbell Row","force":"pull","level":"beginner","mechanic":"isolation","equipment":"barbell","primaryMuscles":["middle back"],"secondaryMuscles":["biceps","lats","traps"],"instructions":["Place a cambered bar underneath an exercise bench.","Lie face down on the exercise bench and grab the bar using a palms down (pronated grip) that is wider than shoulder width. This will be your starting position.","As you exhale row the bar up as you keep the elbows close to your body to either your chest, in order to target the upper mid back, or to your stomach if targeting the lats is your goal.","After a second hold at the top, lower back down to the starting position slowly as you inhale."],"category":"strength","images":["Lying_Cambered_Barbell_Row/0.jpg","Lying_Cambered_Barbell_Row/1.jpg"],"id":"Lying_Cambered_Barbell_Row"}'),
('free-exercise-db', 'Lying_Close-Grip_Bar_Curl_On_High_Pulley', 'cable-lying-close-grip-bar-curl-high-pulley', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Lying_Close-Grip_Bar_Curl_On_High_Pulley.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Lying Close-Grip Bar Curl On High Pulley","force":"pull","level":"beginner","mechanic":"isolation","equipment":"cable","primaryMuscles":["biceps"],"secondaryMuscles":[],"instructions":["Place a flat bench in front of a high pulley or lat pulldown machine.","Hold the straight bar attachment using an underhand grip (palms up) that is about shoulder width.","Lie on your back with your head over the end of the bench.","Now extend your arms straight above your shoulders. Your torso and your arms should make a 90-degree angle and the elbows should be in. This will be your starting position.","As you breathe out, curl the bar down in a semicircular motion until it touches your chin. Squeeze the biceps for a second at the top contracted position. Tip: As you execute this motion only the forearms should move. At no time should the upper arms be moving at all. They are to remain perpendicular throughout the movement.","Return to starting position slowly.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Lying_Close-Grip_Bar_Curl_On_High_Pulley/0.jpg","Lying_Close-Grip_Bar_Curl_On_High_Pulley/1.jpg"],"id":"Lying_Close-Grip_Bar_Curl_On_High_Pulley"}'),
('free-exercise-db', 'Lying_Close-Grip_Barbell_Triceps_Extension_Behind_The_Head', 'barbell-lying-close-grip-triceps-extension-behind-head', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Lying_Close-Grip_Barbell_Triceps_Extension_Behind_The_Head.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Lying Close-Grip Barbell Triceps Extension Behind The Head","force":"push","level":"intermediate","mechanic":"isolation","equipment":"barbell","primaryMuscles":["triceps"],"secondaryMuscles":[],"instructions":["While holding a barbell or EZ Curl bar with a pronated grip (palms facing forward), lie on your back on a flat bench with your head close to the end of the bench. Tip: If you are holding a barbell grab it using a shoulder-width grip and if you are using an E-Z Bar grab it on the inner handles.","Extend your arms in front of you and slowly bring the bar back in a semi circular motion (while keeping the arms extended) to a position over your head. At the end of this step your arms should be overhead and parallel to the floor. This will be your starting position. Tip: Keep your elbows in at all times.","As you inhale, lower the bar by bending at the elbows and while keeping the upper arm stationary. Keep lowering the bar until your forearms are perpendicular to the floor.","As you exhale bring the bar back up to the starting position by pushing the bar up in a semi-circular motion until the lower arms are also parallel to the floor. Contract the triceps hard at the top of the movement for a second. Tip: Again, only the forearms should move. The upper arms should remain stationary at all times.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Lying_Close-Grip_Barbell_Triceps_Extension_Behind_The_Head/0.jpg","Lying_Close-Grip_Barbell_Triceps_Extension_Behind_The_Head/1.jpg"],"id":"Lying_Close-Grip_Barbell_Triceps_Extension_Behind_The_Head"}'),
('free-exercise-db', 'Lying_Close-Grip_Barbell_Triceps_Press_To_Chin', 'barbell-lying-close-grip-triceps-press-to-chin', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Lying_Close-Grip_Barbell_Triceps_Press_To_Chin.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Lying Close-Grip Barbell Triceps Press To Chin","force":"push","level":"intermediate","mechanic":"isolation","equipment":"e-z curl bar","primaryMuscles":["triceps"],"secondaryMuscles":[],"instructions":["While holding a barbell or EZ Curl bar with a pronated grip (palms facing forward), lie on your back on a flat bench with your head off the end of the bench. Tip: If you are holding a barbell grab it using a shoulder-width grip and if you are using an E-Z Bar grab it on the inner handles.","Extend your arms in front of you as you hold the barbell over your chest. The arms should be perpendicular to your torso (90-degree angle). This will be your starting position.","As you inhale, lower the bar in a semi-circular motion by bending at the elbows and while keeping the upper arm stationary and elbows in. Keep lowering the bar until it lightly touches your chin.","As you exhale bring the bar back up to the starting position by pushing the bar up in a semi-circular motion. Contract the triceps hard at the top of the movement for a second. Tip: Again, only the forearms should move. The upper arms should remain stationary at all times.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Lying_Close-Grip_Barbell_Triceps_Press_To_Chin/0.jpg","Lying_Close-Grip_Barbell_Triceps_Press_To_Chin/1.jpg"],"id":"Lying_Close-Grip_Barbell_Triceps_Press_To_Chin"}'),
('free-exercise-db', 'Lying_Crossover', 'lying-crossover', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Lying_Crossover.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Lying Crossover","force":"static","level":"expert","mechanic":null,"equipment":"body only","primaryMuscles":["abductors"],"secondaryMuscles":[],"instructions":["Lie on your back with your legs extended.","Cross one leg over your body with the knee bent, attempting to touch the knee to the ground. Your partner should kneel beside you, holding your shoulder down with one hand and controlling the crossed leg with the other. this will be your starting position.","Attempt to raise the bent knee off of the ground as your partner prevents any actual movement.","After 10-20 seconds, relax the leg as your partner gently presses the knee towards the floor. Repeat with the other side."],"category":"stretching","images":["Lying_Crossover/0.jpg","Lying_Crossover/1.jpg"],"id":"Lying_Crossover"}'),
('free-exercise-db', 'Lying_Dumbbell_Tricep_Extension', 'dumbbell-lying-tricep-extension', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Lying_Dumbbell_Tricep_Extension.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Lying Dumbbell Tricep Extension","force":"push","level":"intermediate","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["triceps"],"secondaryMuscles":["chest","shoulders"],"instructions":["Lie on a flat bench while holding two dumbbells directly in front of you. Your arms should be fully extended at a 90-degree angle from your torso and the floor. The palms should be facing in and the elbows should be tucked in. This is the starting position.","As you breathe in and you keep the upper arms stationary with the elbows in, slowly lower the weight until the dumbbells are near your ears.","At that point, while keeping the elbows in and the upper arms stationary, use the triceps to bring the weight back up to the starting position as you breathe out.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Lying_Dumbbell_Tricep_Extension/0.jpg","Lying_Dumbbell_Tricep_Extension/1.jpg"],"id":"Lying_Dumbbell_Tricep_Extension"}'),
('free-exercise-db', 'Lying_Face_Down_Plate_Neck_Resistance', 'plate-lying-face-down-neck-resistance', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Lying_Face_Down_Plate_Neck_Resistance.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Lying Face Down Plate Neck Resistance","force":"pull","level":"intermediate","mechanic":"isolation","equipment":"other","primaryMuscles":["neck"],"secondaryMuscles":[],"instructions":["Lie face down with your whole body straight on a flat bench while holding a weight plate behind your head. Tip: You will need to position yourself so that your shoulders are slightly above the end of a flat bench in order for the upper chest, neck and face to be off the bench. This will be your starting position.","While keeping the plate secure on the back of your head slowly lower your head (as in saying \"yes\") as you breathe in.","Raise your head back up to the starting position in a semi-circular motion as you breathe out. Hold the contraction for a second.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Lying_Face_Down_Plate_Neck_Resistance/0.jpg","Lying_Face_Down_Plate_Neck_Resistance/1.jpg"],"id":"Lying_Face_Down_Plate_Neck_Resistance"}'),
('free-exercise-db', 'Lying_Face_Up_Plate_Neck_Resistance', 'plate-lying-face-up-neck-resistance', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Lying_Face_Up_Plate_Neck_Resistance.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Lying Face Up Plate Neck Resistance","force":"pull","level":"intermediate","mechanic":"isolation","equipment":"other","primaryMuscles":["neck"],"secondaryMuscles":[],"instructions":["Lie face up with your whole body straight on a flat bench while holding a weight plate on top of your forehead. Tip: You will need to position yourself so that your shoulders are slightly above the end of a flat bench in order for the traps, neck and head to be off the bench. This will be your starting position.","While keeping the plate secure on your forehead slowly lower your head back in a semi-circular motion as you breathe in.","Raise your head back up to the starting position in a semi-circular motion as you breathe out. Hold the contraction for a second.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Lying_Face_Up_Plate_Neck_Resistance/0.jpg","Lying_Face_Up_Plate_Neck_Resistance/1.jpg"],"id":"Lying_Face_Up_Plate_Neck_Resistance"}'),
('free-exercise-db', 'Lying_Glute', 'lying-glute', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Lying_Glute.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Lying Glute","force":"static","level":"expert","mechanic":null,"equipment":"body only","primaryMuscles":["glutes"],"secondaryMuscles":["abductors"],"instructions":["Lie on your back with your partner kneeling beside you.","Flex the hip of one leg, raising it off of the floor. Rotate the leg so the foot is over the opposite hip, the lower leg perpendicular to your body. Your partner should hold the knee and ankle in place. This will be your starting position.","Attempt to push your leg towards your partner, who should be preventing any actual movement of the leg.","After 10-20 seconds, completely relax as your partner gently pushes the ankle and knee towards your chest. Be sure to inform your helper when the stretch is adequate to prevent injury or overstretching."],"category":"stretching","images":["Lying_Glute/0.jpg","Lying_Glute/1.jpg"],"id":"Lying_Glute"}'),
('free-exercise-db', 'Lying_Hamstring', 'lying-hamstring', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Lying_Hamstring.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Lying Hamstring","force":"static","level":"expert","mechanic":null,"equipment":"other","primaryMuscles":["hamstrings"],"secondaryMuscles":["calves"],"instructions":["Lie on your back with your legs extended. Your partner should be kneeling beside you. Raise one leg up towards the ceiling and have your partner hold the ankle. Your partner can use their shoulder to brace your leg if necessary. This will be your starting position.","With your partner holding your leg in place, attempt to flex the knee, contracting the hamstrings for 10-20 seconds.","Then relax your leg, allowing your partner to gently push the leg towards your head. Be sure to inform your helper when the stretch is adequate to prevent injury or overstretching. Switch sides once complete."],"category":"stretching","images":["Lying_Hamstring/0.jpg","Lying_Hamstring/1.jpg"],"id":"Lying_Hamstring"}'),
('free-exercise-db', 'Lying_High_Bench_Barbell_Curl', 'barbell-lying-high-bench-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Lying_High_Bench_Barbell_Curl.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Lying High Bench Barbell Curl","force":"pull","level":"intermediate","mechanic":"isolation","equipment":"barbell","primaryMuscles":["biceps"],"secondaryMuscles":[],"instructions":["Lie face forward on a tall flat bench while holding a barbell with a supinated grip (palms facing up). Tip: If you are holding a barbell grab it using a shoulder-width grip and if you are using an E-Z Bar grab it on the inner handles. Your upper body should be positioned in a way that the upper chest is over the end of the bench and the barbell is hanging in front of you with the arms extended and perpendicular to the floor. This will be your starting position.","While keeping the elbows in and the upper arms stationary, curl the weight up in a semi-circular motion as you contract the biceps and exhale. Hold at the top of the movement for a second.","As you inhale, slowly go back to the starting position. Tip: Maintain full control of the weight at all times and avoid any swinging. Remember, only the forearms should move throughout the movement.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Lying_High_Bench_Barbell_Curl/0.jpg","Lying_High_Bench_Barbell_Curl/1.jpg"],"id":"Lying_High_Bench_Barbell_Curl"}'),
('free-exercise-db', 'Lying_Leg_Curls', 'machine-lying-leg-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Lying_Leg_Curls.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Lying Leg Curls","force":"pull","level":"beginner","mechanic":"isolation","equipment":"machine","primaryMuscles":["hamstrings"],"secondaryMuscles":[],"instructions":["Adjust the machine lever to fit your height and lie face down on the leg curl machine with the pad of the lever on the back of your legs (just a few inches under the calves). Tip: Preferably use a leg curl machine that is angled as opposed to flat since an angled position is more favorable for hamstrings recruitment.","Keeping the torso flat on the bench, ensure your legs are fully stretched and grab the side handles of the machine. Position your toes straight (or you can also use any of the other two stances described on the foot positioning section). This will be your starting position.","As you exhale, curl your legs up as far as possible without lifting the upper legs from the pad. Once you hit the fully contracted position, hold it for a second.","As you inhale, bring the legs back to the initial position. Repeat for the recommended amount of repetitions."],"category":"strength","images":["Lying_Leg_Curls/0.jpg","Lying_Leg_Curls/1.jpg"],"id":"Lying_Leg_Curls"}'),
('free-exercise-db', 'Lying_Machine_Squat', 'machine-lying-squat', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Lying_Machine_Squat.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Lying Machine Squat","force":"push","level":"intermediate","mechanic":"compound","equipment":"machine","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings"],"instructions":["Adjust the leg machine to a height that will allow you to get inside it with your knees bent and the thighs slightly below parallel.","Once you select the weight, position yourself inside the machine face up with the knees bent and thighs slightly below parallel to the platform. Make sure that the knees do not go past the toes. The angle created between the hamstrings and the calves should be one that is slightly less than 90 degrees (since your starting position requires you to start slightly below parallel). Your back and your head should be resting on the machine while your shoulders are pressed under the shoulder pads.","Place your hands by the handles and position your feet slightly pointing out at a shoulder width position. This will be your starting position.","While pressing with the balls of the feet as you breathe out, make your whole body erect as you squeeze the quads. Hold the contracted position for a second. Tip: Since you are starting below parallel, you can opt to use your hands to help you up by pressing on your thighs only on the first repetition.","Slowly squat down as you inhale but instead of going all the way down to the starting position, just stop once your thighs are parallel to the platform. The angle between your hamstrings and calves should be a 90-degree angle.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Lying_Machine_Squat/0.jpg","Lying_Machine_Squat/1.jpg"],"id":"Lying_Machine_Squat"}'),
('free-exercise-db', 'Lying_One-Arm_Lateral_Raise', 'dumbbell-lying-one-arm-lateral-raise', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Lying_One-Arm_Lateral_Raise.json', 'Unlicense', NULL, 'new', 93.1, '{"name":"Lying One-Arm Lateral Raise","force":"pull","level":"intermediate","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":[],"instructions":["While holding a dumbbell in one hand, lay with your chest down on a flat bench. The other hand can be used to hold to the leg of the bench for stability.","Position the palm of the hand that is holding the dumbbell in a neutral manner (palms facing your torso) as you keep the arm extended with the elbow slightly bent. This will be your starting position.","Now raise the arm with the dumbbell to the side until your elbow is at shoulder height and your arm is roughly parallel to the floor as you exhale. Tip: Maintain your arm perpendicular to the torso while keeping your arm extended throughout the movement. Also, keep the contraction at the top for a second.","Slowly lower the dumbbell to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Lying_One-Arm_Lateral_Raise/0.jpg","Lying_One-Arm_Lateral_Raise/1.jpg"],"id":"Lying_One-Arm_Lateral_Raise"}'),
('free-exercise-db', 'Lying_Prone_Quadriceps', 'lying-prone-quadriceps', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Lying_Prone_Quadriceps.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Lying Prone Quadriceps","force":null,"level":"expert","mechanic":null,"equipment":"body only","primaryMuscles":["quadriceps"],"secondaryMuscles":[],"instructions":["Lay face down on the floor with your partner kneeling beside you. Flex one knee and raise that leg off the ground, attempting to touch your glutes with your foot. Your partner should hold the knee and ankle. This will be your starting position.","Attempt to extend your knee while your partner prevents any actual movement.","After 10-20 seconds, relax your muscles as your partner gently pushes the foot towards your glutes, further stretching the quadriceps and hip flexors.","After 10-20 seconds, switch sides."],"category":"stretching","images":["Lying_Prone_Quadriceps/0.jpg","Lying_Prone_Quadriceps/1.jpg"],"id":"Lying_Prone_Quadriceps"}'),
('free-exercise-db', 'Lying_Rear_Delt_Raise', 'dumbbell-lying-rear-delt-raise', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Lying_Rear_Delt_Raise.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Lying Rear Delt Raise","force":"pull","level":"intermediate","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":[],"instructions":["While holding a dumbbell in each hand, lay with your chest down on a flat bench.","Position the palms of the hands in a neutral manner (palms facing your torso) as you keep the arms extended with the elbows slightly bent. This will be your starting position.","Now raise the arms to the side until your elbows are at shoulder height and your arms are roughly parallel to the floor as you exhale. Tip: Maintain your arms perpendicular to the torso while keeping them extended throughout the movement. Also, keep the contraction at the top for a second.","Slowly lower the dumbbells to the starting position as you inhale.","Repeat for the recommended amount of repetitions and then switch to the other arm."],"category":"strength","images":["Lying_Rear_Delt_Raise/0.jpg","Lying_Rear_Delt_Raise/1.jpg"],"id":"Lying_Rear_Delt_Raise"}'),
('free-exercise-db', 'Lying_Supine_Dumbbell_Curl', 'dumbbell-lying-supine-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Lying_Supine_Dumbbell_Curl.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Lying Supine Dumbbell Curl","force":"pull","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["biceps"],"secondaryMuscles":[],"instructions":["Lie down on a flat bench face up while holding a dumbbell in each arm on top of your thighs.","Bring the dumbbells to the sides with the arms extended and the palms of the hands facing your thighs (neutral grip).","While keeping the arms close to your torso and elbows in, slowly lower your arms (as you keep them extended with a slight bend at the elbows) as far down towards the floor as you can go. Once you cannot go down any further, lock your upper arms in that position and that will be your starting position.","As you breathe out, slowly begin to curl the weights up as you simultaneously rotate your wrists so that the palms of the hands face up. Continue curling the weight until your biceps are fully contracted and squeeze hard at the top position for a second. Tip: Only the forearms should move. Upper arms should remain stationary and elbows should stay in throughout the movement.","Return back to the starting position very slowly."],"category":"strength","images":["Lying_Supine_Dumbbell_Curl/0.jpg","Lying_Supine_Dumbbell_Curl/1.jpg"],"id":"Lying_Supine_Dumbbell_Curl"}'),
('free-exercise-db', 'Lying_T-Bar_Row', 'machine-lying-t-bar-row', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Lying_T-Bar_Row.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Lying T-Bar Row","force":"pull","level":"intermediate","mechanic":"compound","equipment":"machine","primaryMuscles":["middle back"],"secondaryMuscles":["biceps","lats"],"instructions":["Load up the T-bar Row Machine with the desired weight and adjust the leg height so that your upper chest is at the top of the pad. Tip: In some machines all you can do is stand on the appropriate step that allows you to be at a height that has the upper chest at the top of the pad.","Lay face down on the pad and grab the handles. You can either use a palms down, palms up, or palms in position depending on what part of your back you want to emphasize.","Lift the bar off the rack and extend your arms in front of you. This will be your starting position.","As you exhale slowly pull the weight up and squeeze your back at the top of the movement. Tip: Keep the upper arms as close to the torso as possible throughout the movement in order to better engage the back muscles. Also, do not lift your body off of the pad at any time and refrain from using the biceps to lift the weight.","After a second contraction at the top of the movement, as you inhale, slowly go back down to the starting position.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Lying_T-Bar_Row/0.jpg","Lying_T-Bar_Row/1.jpg"],"id":"Lying_T-Bar_Row"}'),
('free-exercise-db', 'Lying_Triceps_Press', 'ez-bar-lying-triceps-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Lying_Triceps_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Lying Triceps Press","force":"push","level":"intermediate","mechanic":"isolation","equipment":"e-z curl bar","primaryMuscles":["triceps"],"secondaryMuscles":[],"instructions":["Lie on a flat bench with either an e-z bar (my preference) or a straight bar placed on the floor behind your head and your feet on the floor.","Grab the bar behind you, using a medium overhand (pronated) grip, and raise the bar in front of you at arms length. Tip: The arms should be perpendicular to the torso and the floor. The elbows should be tucked in. This is the starting position.","As you breathe in, slowly lower the weight until the bar lightly touches your forehead while keeping the upper arms and elbows stationary.","At that point, use the triceps to bring the weight back up to the starting position as you breathe out.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Lying_Triceps_Press/0.jpg","Lying_Triceps_Press/1.jpg"],"id":"Lying_Triceps_Press"}'),
('free-exercise-db', 'Machine_Bench_Press', 'machine-bench-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Machine_Bench_Press.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Machine Bench Press","force":"push","level":"beginner","mechanic":"compound","equipment":"machine","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["Sit down on the Chest Press Machine and select the weight.","Step on the lever provided by the machine since it will help you to bring the handles forward so that you can grab the handles and fully extend the arms.","Grab the handles with a palms-down grip and lift your elbows so that your upper arms are parallel to the floor to the sides of your torso. Tip: Your forearms will be pointing forward since you are grabbing the handles. Once you bring the handles forward and extend the arms you will be at the starting position.","Now bring the handles back towards you as you breathe in.","Push the handles away from you as you flex your pecs and you breathe out. Hold the contraction for a second before going back to the starting position.","Repeat for the recommended amount of reps.","When finished step on the lever again and slowly get the handles back to their original place."],"category":"strength","images":["Machine_Bench_Press/0.jpg","Machine_Bench_Press/1.jpg"],"id":"Machine_Bench_Press"}'),
('free-exercise-db', 'Machine_Bicep_Curl', 'machine-biceps-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Machine_Bicep_Curl.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Machine Bicep Curl","force":"pull","level":"beginner","mechanic":"isolation","equipment":"machine","primaryMuscles":["biceps"],"secondaryMuscles":[],"instructions":["Adjust the seat to the appropriate height and make your weight selection. Place your upper arms against the pads and grasp the handles. This will be your starting position.","Perform the movement by flexing the elbow, pulling your lower arm towards your upper arm.","Pause at the top of the movement, and then slowly return the weight to the starting position.","Avoid returning the weight all the way to the stops until the set is complete to keep tension on the muscles being worked."],"category":"strength","images":["Machine_Bicep_Curl/0.jpg","Machine_Bicep_Curl/1.jpg"],"id":"Machine_Bicep_Curl"}'),
('free-exercise-db', 'Machine_Preacher_Curls', 'machine-preacher-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Machine_Preacher_Curls.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Machine Preacher Curls","force":"pull","level":"beginner","mechanic":"isolation","equipment":"machine","primaryMuscles":["biceps"],"secondaryMuscles":[],"instructions":["Sit down on the Preacher Curl Machine and select the weight.","Place the back of your upper arms (your triceps) on the preacher pad provided and grab the handles using an underhand grip (palms facing up). Tip: Make sure that when you place the arms on the pad you keep the elbows in. This will be your starting position.","Now lift the handles as you exhale and you contract the biceps. At the top of the position make sure that you hold the contraction for a second. Tip: Only the forearms should move. The upper arms should remain stationary and on the pad at all times.","Lower the handles slowly back to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Machine_Preacher_Curls/0.jpg","Machine_Preacher_Curls/1.jpg"],"id":"Machine_Preacher_Curls"}'),
('free-exercise-db', 'Machine_Shoulder_Military_Press', 'machine-shoulder-military-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Machine_Shoulder_Military_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Machine Shoulder (Military) Press","force":"push","level":"beginner","mechanic":"compound","equipment":"machine","primaryMuscles":["shoulders"],"secondaryMuscles":["triceps"],"instructions":["Sit down on the Shoulder Press Machine and select the weight.","Grab the handles to your sides as you keep the elbows bent and in line with your torso. This will be your starting position.","Now lift the handles as you exhale and you extend the arms fully. At the top of the position make sure that you hold the contraction for a second.","Lower the handles slowly back to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Machine_Shoulder_Military_Press/0.jpg","Machine_Shoulder_Military_Press/1.jpg"],"id":"Machine_Shoulder_Military_Press"}'),
('free-exercise-db', 'Machine_Triceps_Extension', 'machine-triceps-extension', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Machine_Triceps_Extension.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Machine Triceps Extension","force":"push","level":"beginner","mechanic":"isolation","equipment":"machine","primaryMuscles":["triceps"],"secondaryMuscles":[],"instructions":["Adjust the seat to the appropriate height and make your weight selection. Place your upper arms against the pads and grasp the handles. This will be your starting position.","Perform the movement by extending the elbow, pulling your lower arm away from your upper arm.","Pause at the completion of the movement, and then slowly return the weight to the starting position.","Avoid returning the weight all the way to the stops until the set is complete to keep tension on the muscles being worked."],"category":"strength","images":["Machine_Triceps_Extension/0.jpg","Machine_Triceps_Extension/1.jpg"],"id":"Machine_Triceps_Extension"}'),
('free-exercise-db', 'Medicine_Ball_Chest_Pass', 'medicine-ball-chest-pass', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Medicine_Ball_Chest_Pass.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Medicine Ball Chest Pass","force":"push","level":"beginner","mechanic":"compound","equipment":"medicine ball","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["You will need a partner for this exercise. Lacking one, this movement can be performed against a wall.","Begin facing your partner holding the medicine ball at your torso with both hands.","Pull the ball to your chest, and reverse the motion by extending through the elbows. For sports applications, you can take a step as you throw.","Your partner should catch the ball, and throw it back to you.","Receive the throw with both hands at chest height."],"category":"plyometrics","images":["Medicine_Ball_Chest_Pass/0.jpg","Medicine_Ball_Chest_Pass/1.jpg"],"id":"Medicine_Ball_Chest_Pass"}'),
('free-exercise-db', 'Medicine_Ball_Full_Twist', 'medicine-ball-full-twist', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Medicine_Ball_Full_Twist.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Medicine Ball Full Twist","force":"pull","level":"beginner","mechanic":"compound","equipment":"medicine ball","primaryMuscles":["abdominals"],"secondaryMuscles":["shoulders"],"instructions":["For this exercise you will need a medicine ball and a partner. Stand back to back with your partner, spaced 2-3 feet apart. This will be your starting position.","Hold the ball in front of the trunk. Open the hips and turn the shoulders at the same time as your partner.","For full rotation, you and your partner should twist in the same direction, i.e. counter-clockwise.","Pass the ball to your partner, and both of you can now twist in the opposite direction to repeat the procedure."],"category":"plyometrics","images":["Medicine_Ball_Full_Twist/0.jpg","Medicine_Ball_Full_Twist/1.jpg"],"id":"Medicine_Ball_Full_Twist"}'),
('free-exercise-db', 'Medicine_Ball_Scoop_Throw', 'medicine-ball-scoop-throw', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Medicine_Ball_Scoop_Throw.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Medicine Ball Scoop Throw","force":"push","level":"beginner","mechanic":"compound","equipment":"medicine ball","primaryMuscles":["shoulders"],"secondaryMuscles":["abdominals","hamstrings","quadriceps"],"instructions":["Assume a semisquat stance with a medicine ball in your hands. Your arms should hang so the ball is near your feet.","Begin by thrusting the hips forward as you extend through the legs, jumping up.","As you do, swing your arms up and over your head, keeping them extended, releasing the ball at the peak of your movement. The goal is to throw the ball the greatest distance behind you."],"category":"plyometrics","images":["Medicine_Ball_Scoop_Throw/0.jpg","Medicine_Ball_Scoop_Throw/1.jpg"],"id":"Medicine_Ball_Scoop_Throw"}'),
('free-exercise-db', 'Middle_Back_Shrug', 'dumbbell-middle-back-shrug', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Middle_Back_Shrug.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Middle Back Shrug","force":"pull","level":"intermediate","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["middle back"],"secondaryMuscles":[],"instructions":["Lie facedown on an incline bench while holding a dumbbell in each hand. Your arms should be fully extended hanging down and pointing towards the floor. The palms of your hands should be facing each other. This will be your starting position.","As you exhale, squeeze your shoulder blades together and hold the contraction for a full second. Tip: This movement is just like the reverse action of a hug, or trying to perform rear laterals as if you had no arms.","As you inhale go back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Middle_Back_Shrug/0.jpg","Middle_Back_Shrug/1.jpg"],"id":"Middle_Back_Shrug"}'),
('free-exercise-db', 'Middle_Back_Stretch', 'middle-back-stretch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Middle_Back_Stretch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Middle Back Stretch","force":"static","level":"beginner","mechanic":"isolation","equipment":null,"primaryMuscles":["middle back"],"secondaryMuscles":["abdominals","lats","lower back"],"instructions":["Stand so your feet are shoulder width apart and your hands are on your hips.","Twist at your waist until you feel a stretch. Hold for 10 to 15 seconds, then twist to the other side."],"category":"stretching","images":["Middle_Back_Stretch/0.jpg","Middle_Back_Stretch/1.jpg"],"id":"Middle_Back_Stretch"}'),
('free-exercise-db', 'Mixed_Grip_Chin', 'mixed-grip-chin', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Mixed_Grip_Chin.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Mixed Grip Chin","force":"pull","level":"expert","mechanic":"compound","equipment":"other","primaryMuscles":["middle back"],"secondaryMuscles":["biceps","lats"],"instructions":["Using a spacing that is just about 1 inch wider than shoulder width, grab a pull-up bar with the palms of one hand facing forward and the palms of the other hand facing towards you. This will be your starting position.","Now start to pull yourself up as you exhale. Tip: With the arm that has the palms facing up concentrate on using the back muscles in order to perform the movement. The elbow of that arm should remain close to the torso. With the other arm that has the palms facing forward, the elbows will be away but in line with the torso. You will concentrate on using the lats to pull your body up.","After a second contraction at the top, start to slowly come down as you inhale.","Repeat for the recommended amount of repetitions.","On the following set, switch grips; so if you had the right hand with the palms facing you and the left one with the palms facing forward, on the next set you will have the palms facing forward for the right hand and facing you for the left."],"category":"strength","images":["Mixed_Grip_Chin/0.jpg","Mixed_Grip_Chin/1.jpg"],"id":"Mixed_Grip_Chin"}'),
('free-exercise-db', 'Monster_Walk', 'band-monster-walk', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Monster_Walk.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Monster Walk","force":"pull","level":"beginner","mechanic":"compound","equipment":"bands","primaryMuscles":["abductors"],"secondaryMuscles":[],"instructions":["Place a band around both ankles and another around both knees. There should be enough tension that they are tight when your feet are shoulder width apart.","To begin, take short steps forward alternating your left and right foot.","After several steps, do just the opposite and walk backward to where you started."],"category":"strength","images":["Monster_Walk/0.jpg","Monster_Walk/1.jpg"],"id":"Monster_Walk"}'),
('free-exercise-db', 'Mountain_Climbers', 'mountain-climber', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Mountain_Climbers.json', 'Unlicense', NULL, 'exact', 100.0, '{"name":"Mountain Climbers","force":"pull","level":"beginner","mechanic":"compound","equipment":null,"primaryMuscles":["quadriceps"],"secondaryMuscles":["chest","hamstrings","shoulders"],"instructions":["Begin in a pushup position, with your weight supported by your hands and toes. Flexing the knee and hip, bring one leg until the knee is approximately under the hip. This will be your starting position.","Explosively reverse the positions of your legs, extending the bent leg until the leg is straight and supported by the toe, and bringing the other foot up with the hip and knee flexed. Repeat in an alternating fashion for 20-30 seconds."],"category":"plyometrics","images":["Mountain_Climbers/0.jpg","Mountain_Climbers/1.jpg"],"id":"Mountain_Climbers"}'),
('free-exercise-db', 'Moving_Claw_Series', 'moving-claw-series', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Moving_Claw_Series.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Moving Claw Series","force":null,"level":"beginner","mechanic":"compound","equipment":null,"primaryMuscles":["hamstrings"],"secondaryMuscles":["calves","quadriceps"],"instructions":["This move helps prepare your running form to help you excel at sprinting. As you run, be sure to flex the knee, aiming to kick your glutes as the hip extends.","Reload the quad as the leg moves back forward, attacking the ground on the next step.","Ensure that as you run, you block with the arms, punching through in a rapid 1-2 motion."],"category":"plyometrics","images":["Moving_Claw_Series/0.jpg","Moving_Claw_Series/1.jpg"],"id":"Moving_Claw_Series"}'),
('free-exercise-db', 'Muscle_Snatch', 'barbell-muscle-snatch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Muscle_Snatch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Muscle Snatch","force":"pull","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["hamstrings"],"secondaryMuscles":["glutes","lower back","quadriceps","shoulders","triceps"],"instructions":["Begin with a loaded barbell held at the mid thigh position with a wide grip. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar. This will be the starting position.","Begin the pull by driving through the front of the heels, raising the bar. Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body.","Continue raising the bar to the overhead position, without rebending the knees."],"category":"olympic weightlifting","images":["Muscle_Snatch/0.jpg","Muscle_Snatch/1.jpg"],"id":"Muscle_Snatch"}'),
('free-exercise-db', 'Muscle_Up', 'muscle-up-2', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Muscle_Up.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Muscle Up","force":"pull","level":"intermediate","mechanic":"compound","equipment":"other","primaryMuscles":["lats"],"secondaryMuscles":["abdominals","biceps","forearms","middle back","shoulders","traps","triceps"],"instructions":["Grip the rings using a false grip, with the base of your palms on top of the rings. Initiate a pull up by pulling the elbows down to your side, flexing the elbows.","As you reach the top position of the pull-up, pull the rings to your armpits as you roll your shoulders forward, allowing your elbows to move straight back behind you. This puts you into the proper position to continue into the dip portion of the movement.","Maintaining control and stability, extend through the elbow to complete the motion.","Use care when lowering yourself to the ground."],"category":"strength","images":["Muscle_Up/0.jpg","Muscle_Up/1.jpg"],"id":"Muscle_Up"}'),
('free-exercise-db', 'Narrow_Stance_Hack_Squats', 'machine-narrow-stance-hack-squat', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Narrow_Stance_Hack_Squats.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Narrow Stance Hack Squats","force":"push","level":"intermediate","mechanic":"compound","equipment":"machine","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings"],"instructions":["Place the back of your torso against the back pad of the machine and hook your shoulders under the shoulder pads provided.","Position your legs in the platform using a less than shoulder width narrow stance with the toes slightly pointed out. Your feet should be around 3 inches or less apart. Tip: Keep your head up at all times and also maintain the back on the pad at all times.","Place your arms on the side handles of the machine and disengage the safety bars (which on most designs is done by moving the side handles from a facing front position to a diagonal position).","Now straighten your legs without locking the knees. This will be your starting position.","Begin to slowly lower the unit by bending the knees as you maintain a straight posture with the head up (back on the pad at all times). Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement.","Begin to raise the unit as you exhale by pushing the floor with mainly with the heels of your feet as you straighten the legs again and go back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Narrow_Stance_Hack_Squats/0.jpg","Narrow_Stance_Hack_Squats/1.jpg"],"id":"Narrow_Stance_Hack_Squats"}'),
('free-exercise-db', 'Narrow_Stance_Leg_Press', 'machine-narrow-stance-leg-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Narrow_Stance_Leg_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Narrow Stance Leg Press","force":"push","level":"intermediate","mechanic":"compound","equipment":"machine","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings"],"instructions":["Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a less-than-shoulder-width narrow stance with the toes slightly pointed out. Your feet should be around 3 inches or less apart. Tip: Keep your head up at all times and also maintain the back on the pad at all times.","Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you. Tip: Make sure that you do not lock your knees. Your torso and the legs should make a perfect 90-degree angle. This will be your starting position.","As you inhale, slowly lower the platform until your upper and lower legs make a 90-degree angle.","Pushing mainly with the heels of your feet and using the quadriceps go back to the starting position as you exhale.","Repeat for the recommended amount of repetitions and ensure to lock the safety pins properly once you are done. You do not want that platform falling on you fully loaded."],"category":"strength","images":["Narrow_Stance_Leg_Press/0.jpg","Narrow_Stance_Leg_Press/1.jpg"],"id":"Narrow_Stance_Leg_Press"}'),
('free-exercise-db', 'Narrow_Stance_Squats', 'barbell-narrow-stance-squat', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Narrow_Stance_Squats.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Narrow Stance Squats","force":"push","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings","lower back"],"instructions":["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.","Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.","Step away from the rack and position your legs using a less-than-shoulder-width narrow stance with the toes slightly pointed out. Feet should be around 3-6 inches apart. Keep your head up at all times (looking down will get you off balance) and maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section).","Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise the bar as you exhale by pushing the floor with the heel of your foot mainly as you straighten the legs again and go back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Narrow_Stance_Squats/0.jpg","Narrow_Stance_Squats/1.jpg"],"id":"Narrow_Stance_Squats"}'),
('free-exercise-db', 'Natural_Glute_Ham_Raise', 'natural-glute-ham-raise', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Natural_Glute_Ham_Raise.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Natural Glute Ham Raise","force":"pull","level":"intermediate","mechanic":"compound","equipment":"body only","primaryMuscles":["hamstrings"],"secondaryMuscles":["calves","glutes","lower back"],"instructions":["Using the leg pad of a lat pulldown machine or a preacher bench, position yourself so that your ankles are under the pads, knees on the seat, and you are facing away from the machine. You should be upright and maintaining good posture.","This will be your starting position. Lower yourself under control until your knees are almost completely straight.","Remaining in control, raise yourself back up to the starting position.","If you are unable to complete a rep, use a band, a partner, or push off of a box to aid in completing a repetition."],"category":"strength","images":["Natural_Glute_Ham_Raise/0.jpg","Natural_Glute_Ham_Raise/1.jpg"],"id":"Natural_Glute_Ham_Raise"}'),
('free-exercise-db', 'Neck-SMR', 'neck-smr', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Neck-SMR.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Neck-SMR","force":"static","level":"intermediate","mechanic":null,"equipment":"other","primaryMuscles":["neck"],"secondaryMuscles":[],"instructions":["Using a muscle roller or a rolling pin, place the roller behind your head and against your neck. Make sure that you do not place the roller directly against the spine, but turned slightly so that the roller is pressed against the muscles to either side of the spine. This will be your starting position.","Starting at the top of your neck, slowly roll down the muscles of your neck, pausing at points of tension for 10-30 seconds."],"category":"stretching","images":["Neck-SMR/0.jpg","Neck-SMR/1.jpg"],"id":"Neck-SMR"}'),
('free-exercise-db', 'Neck_Press', 'barbell-neck-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Neck_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Neck Press","force":"push","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["Lie back on a flat bench. Using a medium-width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over your neck with your arms locked. This will be your starting position.","As you breathe in, come down slowly until you feel the bar on your neck.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up).","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the bar back in the rack."],"category":"strength","images":["Neck_Press/0.jpg","Neck_Press/1.jpg"],"id":"Neck_Press"}'),
('free-exercise-db', 'Oblique_Crunches', 'oblique-crunch-2', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Oblique_Crunches.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Oblique Crunches","force":"pull","level":"beginner","mechanic":"isolation","equipment":"body only","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Lie flat on the floor with your lower back pressed to the ground. For this exercise, you will need to put one hand beside your head and the other to the side against the floor.","Make sure your feet are elevated and resting on a flat surface.","Now lift the shoulder in which your hand is touching your head.","Simply elevate your shoulder and body upward until you touch your knee. For example, if you have your right hand besides your head, then you want to elevate your body upwards until your right elbow touches your left knee. The same variation can be applied doing the inverse and using your left elbow to touch your right knee.","After your knee touches your elbow, lower your body until you have reached the starting position.","Remember to breathe in during the eccentric (lowering) part of the exercise and to breathe out during the concentric (upward) part of the exercise.","Continue alternating in this manner until all of the recommended repetitions for each side have been completed."],"category":"strength","images":["Oblique_Crunches/0.jpg","Oblique_Crunches/1.jpg"],"id":"Oblique_Crunches"}'),
('free-exercise-db', 'Oblique_Crunches_-_On_The_Floor', 'oblique-crunch-floor', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Oblique_Crunches_-_On_The_Floor.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Oblique Crunches - On The Floor","force":"pull","level":"beginner","mechanic":"isolation","equipment":"body only","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Start out by lying on your right side with your legs lying on top of each other. Make sure your knees are bent a little bit.","Place your left hand behind your head.","Once you are in this set position, begin by moving your left elbow up as you would perform a normal crunch except this time the main emphasis is on your obliques.","Crunch as high as you can, hold the contraction for a second and then slowly drop back down into the starting position.","Remember to breathe in during the eccentric (lowering) part of the exercise and to breathe out during the concentric (elevation) part of the exercise."],"category":"strength","images":["Oblique_Crunches_-_On_The_Floor/0.jpg","Oblique_Crunches_-_On_The_Floor/1.jpg"],"id":"Oblique_Crunches_-_On_The_Floor"}'),
('free-exercise-db', 'Olympic_Squat', 'barbell-olympic-squat', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Olympic_Squat.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Olympic Squat","force":"push","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings"],"instructions":["Begin with a barbell supported on top of the traps. The chest should be up, and the head facing forward. Adopt a hip width stance with the feet turned out as needed.","Descend by flexing the knees, refraining from moving the hips back as much as possible. This requires that the knees travel forward; ensure that they stay aligned with the feet. The goal is to keep the torso as upright as possible. Continue all the way down, keeping the weight on the front of the heel.","At the moment the upper legs contact the lower, reverse the motion, driving the weight upward."],"category":"olympic weightlifting","images":["Olympic_Squat/0.jpg","Olympic_Squat/1.jpg"],"id":"Olympic_Squat"}'),
('free-exercise-db', 'On-Your-Back_Quad_Stretch', 'your-back-quad-stretch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/On-Your-Back_Quad_Stretch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"On-Your-Back Quad Stretch","force":"static","level":"beginner","mechanic":"isolation","equipment":"other","primaryMuscles":["quadriceps"],"secondaryMuscles":[],"instructions":["Lie on a flat bench or step, and hang one leg and arm over the side.","Bend the knee and hold the top of the foot. As you do this, be careful not to arch your lower back.","Pull the belly button to the spine to stay in neutral. Press your foot down and into your hand. To add the hip stretch, lift the hip of the leg you''re holding up toward the ceiling.","Switch sides."],"category":"stretching","images":["On-Your-Back_Quad_Stretch/0.jpg","On-Your-Back_Quad_Stretch/1.jpg"],"id":"On-Your-Back_Quad_Stretch"}'),
('free-exercise-db', 'On_Your_Side_Quad_Stretch', 'your-side-quad-stretch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/On_Your_Side_Quad_Stretch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"On Your Side Quad Stretch","force":"static","level":"beginner","mechanic":"isolation","equipment":null,"primaryMuscles":["quadriceps"],"secondaryMuscles":[],"instructions":["Start off by lying on your right side, with your right knee bent at a 90-degree angle resting on the floor in front of you (this stabilizes the torso).","Bend your left knee behind you and hold your left foot with your left hand. To stretch your hip flexor, press your left hip forward as you push your left foot back into your hand. Switch sides."],"category":"stretching","images":["On_Your_Side_Quad_Stretch/0.jpg","On_Your_Side_Quad_Stretch/1.jpg"],"id":"On_Your_Side_Quad_Stretch"}'),
('free-exercise-db', 'One-Arm_Dumbbell_Row', 'dumbbell-one-handed-row', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/One-Arm_Dumbbell_Row.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"One-Arm Dumbbell Row","force":"pull","level":"beginner","mechanic":"compound","equipment":"dumbbell","primaryMuscles":["middle back"],"secondaryMuscles":["biceps","lats","shoulders"],"instructions":["Choose a flat bench and place a dumbbell on each side of it.","Place the right leg on top of the end of the bench, bend your torso forward from the waist until your upper body is parallel to the floor, and place your right hand on the other end of the bench for support.","Use the left hand to pick up the dumbbell on the floor and hold the weight while keeping your lower back straight. The palm of the hand should be facing your torso. This will be your starting position.","Pull the resistance straight up to the side of your chest, keeping your upper arm close to your side and keeping the torso stationary. Breathe out as you perform this step. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. Also, make sure that the force is performed with the back muscles and not the arms. Finally, the upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the dumbbell; therefore do not try to pull the dumbbell up using the forearms.","Lower the resistance straight down to the starting position. Breathe in as you perform this step.","Repeat the movement for the specified amount of repetitions.","Switch sides and repeat again with the other arm."],"category":"strength","images":["One-Arm_Dumbbell_Row/0.jpg","One-Arm_Dumbbell_Row/1.jpg"],"id":"One-Arm_Dumbbell_Row"}'),
('free-exercise-db', 'One-Arm_Flat_Bench_Dumbbell_Flye', 'dumbbell-one-arm-flat-bench-flye', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/One-Arm_Flat_Bench_Dumbbell_Flye.json', 'Unlicense', NULL, 'new', NULL, '{"name":"One-Arm Flat Bench Dumbbell Flye","force":"push","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["chest"],"secondaryMuscles":[],"instructions":["Lie down on a flat bench with a dumbbell in one hand resting on top of your thigh. The palm of your hand with the dumbbell in it should be at a neutral grip.","By using your thighs to help you get the dumbbell up, clean the dumbbell so that you can hold it in front of you with your lifting arm being fully extended. Remember to maintain a neutral grip with this exercise. Your non lifting hand should be to the side holding the flat bench for better support. This will be your starting position.","Your arm with the weight should have a slight bend on your elbow in order to prevent stress at the biceps tendon. Begin by lowering your arm with the weight in it out in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, your lifting arm should remain stationary; the movement should only occur at the shoulder joint.","Return your lifting arm back to the starting position as you squeeze your chest muscles and breathe out. Tip: Make sure to use the same arc of motion used to lower the weights.","Hold for a second at the contracted position and repeat the movement for the prescribed amount of repetitions.","Switch arms and repeat the exercise."],"category":"strength","images":["One-Arm_Flat_Bench_Dumbbell_Flye/0.jpg","One-Arm_Flat_Bench_Dumbbell_Flye/1.jpg"],"id":"One-Arm_Flat_Bench_Dumbbell_Flye"}'),
('free-exercise-db', 'One-Arm_High-Pulley_Cable_Side_Bends', 'cable-one-arm-high-pulley-side-bend', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/One-Arm_High-Pulley_Cable_Side_Bends.json', 'Unlicense', NULL, 'new', NULL, '{"name":"One-Arm High-Pulley Cable Side Bends","force":"pull","level":"beginner","mechanic":"isolation","equipment":"cable","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Connect a standard handle to a tower. Move cable to highest pulley position.","Stand with side to cable. With one hand, reach up and grab handle with underhand grip.","Pull down cable until elbow touches your side and the handle is by your shoulder.","Position feet hip-width apart. Place free hand on hip to help gauge pivot point.","Keep arm in static position. Contract oblique to bring the weight down in a side crunch.","Once you reach maximum contraction, slowly release the weight to the starting position. The weight stack should never be unloaded in a resting position. The aim is constant tension during the set.","Repeat to failure.","Then, reposition and repeat the same series of movements on the opposite side."],"category":"strength","images":["One-Arm_High-Pulley_Cable_Side_Bends/0.jpg","One-Arm_High-Pulley_Cable_Side_Bends/1.jpg"],"id":"One-Arm_High-Pulley_Cable_Side_Bends"}'),
('free-exercise-db', 'One-Arm_Incline_Lateral_Raise', 'dumbbell-one-arm-incline-lateral-raise', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/One-Arm_Incline_Lateral_Raise.json', 'Unlicense', NULL, 'new', NULL, '{"name":"One-Arm Incline Lateral Raise","force":"push","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":[],"instructions":["Lie down sideways on an incline bench press with a dumbbell in the hand. Make sure the shoulder is pressing against the incline bench and the arm is lying across your body with the palm around your navel.","Hold a dumbbell in your uppermost arm while keeping it extended in front of you parallel to the floor. This is your starting position.","While keeping the dumbbell parallel to the floor at all times, perform a lateral raise. Your arm should travel straight up until it is pointing at the ceiling. Tip: Exhale as you perform this movement. Hold the dumbbell in the position and feel the contraction in the shoulders for a second.","While inhaling lower the weight across your body back into the starting position.","Repeat the movement for the prescribed amount of repetitions.","Switch arms and repeat the movement."],"category":"strength","images":["One-Arm_Incline_Lateral_Raise/0.jpg","One-Arm_Incline_Lateral_Raise/1.jpg"],"id":"One-Arm_Incline_Lateral_Raise"}'),
('free-exercise-db', 'One-Arm_Kettlebell_Clean', 'kettlebell-one-arm-clean', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/One-Arm_Kettlebell_Clean.json', 'Unlicense', NULL, 'new', NULL, '{"name":"One-Arm Kettlebell Clean","force":"pull","level":"intermediate","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["hamstrings"],"secondaryMuscles":["glutes","lower back","shoulders","traps"],"instructions":["Place a kettlebell between your feet. As you bend down to grab the kettlebell, push your butt back and keep your eyes looking forward.","Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so.","Return the weight to the starting position."],"category":"strength","images":["One-Arm_Kettlebell_Clean/0.jpg","One-Arm_Kettlebell_Clean/1.jpg"],"id":"One-Arm_Kettlebell_Clean"}'),
('free-exercise-db', 'One-Arm_Kettlebell_Clean_and_Jerk', 'kettlebell-one-arm-clean-and-jerk', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/One-Arm_Kettlebell_Clean_and_Jerk.json', 'Unlicense', NULL, 'new', NULL, '{"name":"One-Arm Kettlebell Clean and Jerk","force":"push","level":"intermediate","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["shoulders"],"secondaryMuscles":[],"instructions":["Hold a kettlebell by the handle.","Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward.","Dip your body by bending the knees, keeping your torso upright.","Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, using your body''s momentum to move the weight.","Receive the weight overhead by returning to a squat position underneath the weight.","Keeping the weight overhead, return to a standing position. Lower the weight to the floor to perform the next repetition."],"category":"strength","images":["One-Arm_Kettlebell_Clean_and_Jerk/0.jpg","One-Arm_Kettlebell_Clean_and_Jerk/1.jpg"],"id":"One-Arm_Kettlebell_Clean_and_Jerk"}'),
('free-exercise-db', 'One-Arm_Kettlebell_Floor_Press', 'kettlebell-one-arm-floor-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/One-Arm_Kettlebell_Floor_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"One-Arm Kettlebell Floor Press","force":"push","level":"intermediate","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["chest"],"secondaryMuscles":["triceps"],"instructions":["Lie on the floor holding a kettlebell with one hand, with your upper arm supported by the floor. The palm should be facing in.","Press the kettlebell straight up toward the ceiling, rotating your wrist.","Lower the kettlebell back to the starting position and repeat."],"category":"strength","images":["One-Arm_Kettlebell_Floor_Press/0.jpg","One-Arm_Kettlebell_Floor_Press/1.jpg"],"id":"One-Arm_Kettlebell_Floor_Press"}'),
('free-exercise-db', 'One-Arm_Kettlebell_Jerk', 'kettlebell-one-arm-jerk', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/One-Arm_Kettlebell_Jerk.json', 'Unlicense', NULL, 'new', NULL, '{"name":"One-Arm Kettlebell Jerk","force":"push","level":"intermediate","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["shoulders"],"secondaryMuscles":["calves","quadriceps","triceps"],"instructions":["Hold a kettlebell by the handle. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position.","Dip your body by bending the knees, keeping your torso upright.","Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, using your body''s momentum to move the weight. Receive the weight overhead by returning to a squat position underneath the weight. Keeping the weight overhead, return to a standing position.","Lower the weight to perform the next repetition."],"category":"strength","images":["One-Arm_Kettlebell_Jerk/0.jpg","One-Arm_Kettlebell_Jerk/1.jpg"],"id":"One-Arm_Kettlebell_Jerk"}'),
('free-exercise-db', 'One-Arm_Kettlebell_Military_Press_To_The_Side', 'kettlebell-one-arm-military-press-to-side', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/One-Arm_Kettlebell_Military_Press_To_The_Side.json', 'Unlicense', NULL, 'new', NULL, '{"name":"One-Arm Kettlebell Military Press To The Side","force":"push","level":"intermediate","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["shoulders"],"secondaryMuscles":["triceps"],"instructions":["Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces inward. This will be your starting position.","Look at the kettlebell and press it up and out until it is locked out overhead.","Lower the kettlebell back to your shoulder under control and repeat. Make sure to contract your lat, butt, and stomach forcefully for added stability and strength."],"category":"strength","images":["One-Arm_Kettlebell_Military_Press_To_The_Side/0.jpg","One-Arm_Kettlebell_Military_Press_To_The_Side/1.jpg"],"id":"One-Arm_Kettlebell_Military_Press_To_The_Side"}'),
('free-exercise-db', 'One-Arm_Kettlebell_Para_Press', 'kettlebell-one-arm-para-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/One-Arm_Kettlebell_Para_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"One-Arm Kettlebell Para Press","force":"push","level":"intermediate","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["shoulders"],"secondaryMuscles":["triceps"],"instructions":["Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position.","Hold the kettlebell with the elbow out to the side, and press it up and out until it is locked out overhead.","Lower the kettlebell back to your shoulder under control and repeat. Make sure to contract your lat, butt, and stomach forcefully for added stability and strength."],"category":"strength","images":["One-Arm_Kettlebell_Para_Press/0.jpg","One-Arm_Kettlebell_Para_Press/1.jpg"],"id":"One-Arm_Kettlebell_Para_Press"}'),
('free-exercise-db', 'One-Arm_Kettlebell_Push_Press', 'kettlebell-one-arm-push-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/One-Arm_Kettlebell_Push_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"One-Arm Kettlebell Push Press","force":"push","level":"intermediate","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["shoulders"],"secondaryMuscles":["calves","quadriceps","triceps"],"instructions":["Hold a kettlebell by the handle. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position.","Dip your body by bending the knees, keeping your torso upright.","Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, using your body''s momentum to move the weight. Lower the weight to perform the next repetition."],"category":"strength","images":["One-Arm_Kettlebell_Push_Press/0.jpg","One-Arm_Kettlebell_Push_Press/1.jpg"],"id":"One-Arm_Kettlebell_Push_Press"}'),
('free-exercise-db', 'One-Arm_Kettlebell_Row', 'kettlebell-one-arm-row', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/One-Arm_Kettlebell_Row.json', 'Unlicense', NULL, 'new', NULL, '{"name":"One-Arm Kettlebell Row","force":"pull","level":"intermediate","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["middle back"],"secondaryMuscles":["biceps","lats"],"instructions":["Place a kettlebell in front of your feet. Bend your knees slightly and then push your butt out as much as possible as you bend over to get in the starting position. Grab the kettlebell and pull it to your stomach, retracting your shoulder blade and flexing the elbow. Keep your back straight. Lower and repeat."],"category":"strength","images":["One-Arm_Kettlebell_Row/0.jpg","One-Arm_Kettlebell_Row/1.jpg"],"id":"One-Arm_Kettlebell_Row"}'),
('free-exercise-db', 'One-Arm_Kettlebell_Snatch', 'kettlebell-one-arm-snatch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/One-Arm_Kettlebell_Snatch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"One-Arm Kettlebell Snatch","force":"pull","level":"expert","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["shoulders"],"secondaryMuscles":["calves","glutes","hamstrings","lower back","traps","triceps"],"instructions":["Place a kettlebell between your feet. Bend your knees and push your butt back to get in the proper starting position.","Look straight ahead and swing the kettlebell back between your legs.","Immediately reverse the direction and drive through with your hips and knees, accelerating the kettlebell upward. As the kettlebell rises to your shoulder rotate your hand and punch straight up, using momentum to receive the weight locked out overhead."],"category":"strength","images":["One-Arm_Kettlebell_Snatch/0.jpg","One-Arm_Kettlebell_Snatch/1.jpg"],"id":"One-Arm_Kettlebell_Snatch"}'),
('free-exercise-db', 'One-Arm_Kettlebell_Split_Jerk', 'kettlebell-one-arm-split-jerk', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/One-Arm_Kettlebell_Split_Jerk.json', 'Unlicense', NULL, 'new', NULL, '{"name":"One-Arm Kettlebell Split Jerk","force":"push","level":"intermediate","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["shoulders"],"secondaryMuscles":["glutes","hamstrings","quadriceps","triceps"],"instructions":["Hold a kettlebell by the handle. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position.","Dip your body by bending the knees, keeping your torso upright.","Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, using your body''s momentum to move the weight.","Receive the weight overhead by returning to a squat position underneath the weight, positioning one leg in front of you and one leg behind you.","Keeping the weight overhead, return to a standing position and bring your feet together. Lower the weight to perform the next repetition."],"category":"strength","images":["One-Arm_Kettlebell_Split_Jerk/0.jpg","One-Arm_Kettlebell_Split_Jerk/1.jpg"],"id":"One-Arm_Kettlebell_Split_Jerk"}'),
('free-exercise-db', 'One-Arm_Kettlebell_Split_Snatch', 'kettlebell-one-arm-split-snatch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/One-Arm_Kettlebell_Split_Snatch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"One-Arm Kettlebell Split Snatch","force":"pull","level":"expert","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["shoulders"],"secondaryMuscles":["hamstrings","quadriceps"],"instructions":["Hold a kettlebell in one hand by the handle.","Squat towards the floor, and then reverse the motion, extending the hips, knees, and finally the ankles, to raise the kettlebell overhead.","After fully extending the body, descend into a lunge position to receive the weights overhead, one leg forward and one leg back. Ensure you drive through with your hips and lock the ketttlebells overhead in one uninterrupted motion.","Return to a standing position, holding the weight overhead, and bring the feet together. Lower the weight to return to the starting position."],"category":"strength","images":["One-Arm_Kettlebell_Split_Snatch/0.jpg","One-Arm_Kettlebell_Split_Snatch/1.jpg"],"id":"One-Arm_Kettlebell_Split_Snatch"}'),
('free-exercise-db', 'One-Arm_Kettlebell_Swings', 'kettlebell-one-arm-swing', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/One-Arm_Kettlebell_Swings.json', 'Unlicense', NULL, 'new', NULL, '{"name":"One-Arm Kettlebell Swings","force":"pull","level":"intermediate","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["hamstrings"],"secondaryMuscles":["calves","glutes","lower back","shoulders"],"instructions":[],"category":"strength","images":["One-Arm_Kettlebell_Swings/0.jpg","One-Arm_Kettlebell_Swings/1.jpg"],"id":"One-Arm_Kettlebell_Swings"}'),
('free-exercise-db', 'One-Arm_Long_Bar_Row', 'barbell-one-arm-long-bar-row', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/One-Arm_Long_Bar_Row.json', 'Unlicense', NULL, 'new', NULL, '{"name":"One-Arm Long Bar Row","force":"pull","level":"beginner","mechanic":"compound","equipment":"barbell","primaryMuscles":["middle back"],"secondaryMuscles":["biceps","lats"],"instructions":["Position a bar into a landmine or in a corner to keep it from moving. Load an appropriate weight onto your end.","Stand next to the bar, and take a grip with one hand close to the collar. Using your hips and legs, rise to a standing position.","Assume a bent-knee stance with your hips back and your chest up. Your arm should be extended. This will be your starting position.","Pull the weight to your side by retracting the shoulder and flexing the elbow. Do not jerk the weight or cheat during the movement.","After a brief pause, return to the starting position."],"category":"strength","images":["One-Arm_Long_Bar_Row/0.jpg","One-Arm_Long_Bar_Row/1.jpg"],"id":"One-Arm_Long_Bar_Row"}'),
('free-exercise-db', 'One-Arm_Medicine_Ball_Slam', 'medicine-ball-one-arm-slam', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/One-Arm_Medicine_Ball_Slam.json', 'Unlicense', NULL, 'new', NULL, '{"name":"One-Arm Medicine Ball Slam","force":"pull","level":"beginner","mechanic":"compound","equipment":"medicine ball","primaryMuscles":["abdominals"],"secondaryMuscles":["lats","shoulders"],"instructions":["Start in a standing position with a staggered, athletic stance. Hold a medicine ball in one hand, on the same side as your back leg. This will be your starting position.","Begin by winding the arm, raising the medicine ball above your head. As you do so, extend through the hips, knees, and ankles to load up for the slam.","At peak extension, flex the shoulders, spine, and hips to throw the ball hard into the ground directly in front of you.","Catch the ball on the bounce and continue for the desired number of repetitions."],"category":"strength","images":["One-Arm_Medicine_Ball_Slam/0.jpg","One-Arm_Medicine_Ball_Slam/1.jpg"],"id":"One-Arm_Medicine_Ball_Slam"}'),
('free-exercise-db', 'One-Arm_Open_Palm_Kettlebell_Clean', 'kettlebell-one-arm-open-palm-clean', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/One-Arm_Open_Palm_Kettlebell_Clean.json', 'Unlicense', NULL, 'new', NULL, '{"name":"One-Arm Open Palm Kettlebell Clean","force":"pull","level":"intermediate","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["hamstrings"],"secondaryMuscles":["forearms","glutes","lower back","quadriceps","shoulders"],"instructions":["Place one kettlebell between your feet.","Grab the handle with one hand and raise the kettlebell rapidly, let it flip so that the ball of the kettlebell lands in the palm of your hand.","Throw the kettlebell out in front of you and catch the handle with one hand.","Take the kettlebell to the floor and repeat. Make sure to work both arms."],"category":"strength","images":["One-Arm_Open_Palm_Kettlebell_Clean/0.jpg","One-Arm_Open_Palm_Kettlebell_Clean/1.jpg"],"id":"One-Arm_Open_Palm_Kettlebell_Clean"}'),
('free-exercise-db', 'One-Arm_Overhead_Kettlebell_Squats', 'kettlebell-one-arm-overhead-squat', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/One-Arm_Overhead_Kettlebell_Squats.json', 'Unlicense', NULL, 'new', NULL, '{"name":"One-Arm Overhead Kettlebell Squats","force":"push","level":"expert","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings","shoulders"],"instructions":["Clean and press a kettlebell with one arm. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so. Press the weight overhead by extending through the elbow.This will be your starting position.","Looking straight ahead and keeping a kettlebell locked out above you, flex the knees and hips and lower your torso between your legs, keeping your head and chest up.","Pause at the bottom position for a second before rising back to the top, driving through the heels of your feet."],"category":"strength","images":["One-Arm_Overhead_Kettlebell_Squats/0.jpg","One-Arm_Overhead_Kettlebell_Squats/1.jpg"],"id":"One-Arm_Overhead_Kettlebell_Squats"}'),
('free-exercise-db', 'One-Arm_Side_Deadlift', 'barbell-one-arm-side-deadlift', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/One-Arm_Side_Deadlift.json', 'Unlicense', NULL, 'new', NULL, '{"name":"One-Arm Side Deadlift","force":"pull","level":"expert","mechanic":"compound","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["abdominals","calves","glutes","hamstrings","lower back","traps"],"instructions":["Stand to the side of a barbell next to its center. Bend your knees and lower your body until you are able to reach the barbell.","Grasp the bar as if you were grabbing a briefcase (palms facing you since the bar is sideways). You may need a wrist wrap if you are using a significant amount of weight. This is your starting position.","Use your legs to help lift the barbell up while exhaling. Your arms should extend fully as bring the barbell up until you are in a standing position.","Slowly bring the barbell back down while inhaling. Tip: Make sure to bend your knees while lowering the weight to avoid any injury from occurring.","Repeat for the recommended amount of repetitions.","Switch arms and repeat the movement."],"category":"strength","images":["One-Arm_Side_Deadlift/0.jpg","One-Arm_Side_Deadlift/1.jpg"],"id":"One-Arm_Side_Deadlift"}'),
('free-exercise-db', 'One-Arm_Side_Laterals', 'dumbbell-one-arm-side-laterals', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/One-Arm_Side_Laterals.json', 'Unlicense', NULL, 'new', NULL, '{"name":"One-Arm Side Laterals","force":"push","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":[],"instructions":["Pick a dumbbell and place it in one of your hands. Your non lifting hand should be used to grab something steady such as an incline bench press. Lean towards your lifting arm and away from the hand that is gripping the incline bench as this will allow you to keep your balance.","Stand with a straight torso and have the dumbbell by your side at arm''s length with the palm of the hand facing you. This will be your starting position.","While maintaining the torso stationary (no swinging), lift the dumbbell to your side with a slight bend on the elbow and your hand slightly tilted forward as if pouring water in a glass. Continue to go up until you arm is parallel to the floor. Exhale as you execute this movement and pause for a second at the top.","Lower the dumbbell back down slowly to the starting position as you inhale.","Repeat for the recommended amount of repetitions.","Switch arms and repeat the exercise."],"category":"strength","images":["One-Arm_Side_Laterals/0.jpg","One-Arm_Side_Laterals/1.jpg"],"id":"One-Arm_Side_Laterals"}'),
('free-exercise-db', 'One-Legged_Cable_Kickback', 'cable-one-legged-kickback', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/One-Legged_Cable_Kickback.json', 'Unlicense', NULL, 'new', NULL, '{"name":"One-Legged Cable Kickback","force":"push","level":"intermediate","mechanic":"isolation","equipment":"cable","primaryMuscles":["glutes"],"secondaryMuscles":["hamstrings"],"instructions":["Hook a leather ankle cuff to a low cable pulley and then attach the cuff to your ankle.","Face the weight stack from a distance of about two feet, grasping the steel frame for support.","While keeping your knees and hips bent slightly and your abs tight, contract your glutes to slowly \"kick\" the working leg back in a semicircular arc as high as it will comfortably go as you breathe out. Tip: At full extension, squeeze your glutes for a second in order to achieve a peak contraction.","Now slowly bring your working leg forward, resisting the pull of the cable until you reach the starting position.","Repeat for the recommended amount of repetitions.","Switch legs and repeat the movement for the other side."],"category":"strength","images":["One-Legged_Cable_Kickback/0.jpg","One-Legged_Cable_Kickback/1.jpg"],"id":"One-Legged_Cable_Kickback"}'),
('free-exercise-db', 'One_Arm_Against_Wall', 'one-arm-against-wall', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/One_Arm_Against_Wall.json', 'Unlicense', NULL, 'new', NULL, '{"name":"One Arm Against Wall","force":"static","level":"beginner","mechanic":"isolation","equipment":null,"primaryMuscles":["lats"],"secondaryMuscles":[],"instructions":["From a standing position, place a bent arm against a wall or doorway.","Slowly lean toward your arm until you feel a stretch in your lats."],"category":"stretching","images":["One_Arm_Against_Wall/0.jpg","One_Arm_Against_Wall/1.jpg"],"id":"One_Arm_Against_Wall"}'),
('free-exercise-db', 'One_Arm_Chin-Up', 'one-arm-chin-up', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/One_Arm_Chin-Up.json', 'Unlicense', NULL, 'new', NULL, '{"name":"One Arm Chin-Up","force":"pull","level":"expert","mechanic":"compound","equipment":"other","primaryMuscles":["middle back"],"secondaryMuscles":["biceps","forearms","lats"],"instructions":["For this exercise, start out by placing a towel around a chin up bar.","Grab the chin-up bar with your palm facing you. One hand will be grabbing the chin-up bar and the other will be grabbing the towel.","Bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.v","Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.","After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.","Repeat this motion for the prescribed amount of repetitions.","Switch arms and repeat the movement."],"category":"strength","images":["One_Arm_Chin-Up/0.jpg","One_Arm_Chin-Up/1.jpg"],"id":"One_Arm_Chin-Up"}'),
('free-exercise-db', 'One_Arm_Dumbbell_Bench_Press', 'dumbbell-one-arm-bench-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/One_Arm_Dumbbell_Bench_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"One Arm Dumbbell Bench Press","force":"push","level":"beginner","mechanic":"compound","equipment":"dumbbell","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["Lie down on a flat bench with a dumbbell in one hand on top of your thigh.","By using your thigh to help you get the dumbbell up, clean the dumbbell up so that you can hold it in front of you at shoulder width. Use the hand you are not lifting with to help position the dumbbell over you properly.","Once at shoulder width, rotate your wrist forward so that the palm of your hand is facing away from you. This will be your starting position.","Bring down the weights slowly to your side as you breathe in. Keep full control of the dumbbell at all times. Tip: Use the hand that you are not lifting with to help keep the dumbbell balance as you may struggle a bit at first. Only use your non-lifting hand if it is needed. Otherwise, keep it resting to the side.","As you breathe out, push the dumbbells up using your pectoral muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions of your training program.","Switch arms and repeat the movement."],"category":"strength","images":["One_Arm_Dumbbell_Bench_Press/0.jpg","One_Arm_Dumbbell_Bench_Press/1.jpg"],"id":"One_Arm_Dumbbell_Bench_Press"}'),
('free-exercise-db', 'One_Arm_Dumbbell_Preacher_Curl', 'dumbbell-single-arm-preacher-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/One_Arm_Dumbbell_Preacher_Curl.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"One Arm Dumbbell Preacher Curl","force":"pull","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["biceps"],"secondaryMuscles":[],"instructions":["Grab a dumbbell with the right arm and place the upper arm on top of the preacher bench or the incline bench. The dumbbell should be held at shoulder length. This will be your starting position.","As you breathe in, slowly lower the dumbbell until your upper arm is extended and the biceps is fully stretched.","As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the dumbbell is at shoulder height. Again, remember that to ensure full contraction you need to bring that small finger higher than the thumb.","Squeeze the biceps hard for a second at the contracted position and repeat for the recommended amount of repetitions.","Switch arms and repeat the movement."],"category":"strength","images":["One_Arm_Dumbbell_Preacher_Curl/0.jpg","One_Arm_Dumbbell_Preacher_Curl/1.jpg"],"id":"One_Arm_Dumbbell_Preacher_Curl"}'),
('free-exercise-db', 'One_Arm_Floor_Press', 'barbell-one-arm-floor-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/One_Arm_Floor_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"One Arm Floor Press","force":"push","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["triceps"],"secondaryMuscles":["chest","shoulders"],"instructions":["Lie down on a flat surface with your back pressing against the floor or an exercise mat. Make sure your knees are bent.","Have a partner hand you the bar on one hand. When starting, your arm should be just about fully extended, similar to the starting position of a barbell bench press. However, this time your grip will be neutral (palms facing your torso).","Make sure the hand you are not using to lift the weight is placed by your side.","Begin the exercise by lowering the barbell until your elbow touches the ground. Make sure to breathe in as this is the eccentric (lowering part of the exercise).","Then start lifting the barbell back up to the original starting position. Remember to breathe out during the concentric (lifting part of the exercise).","Repeat until you have performed your recommended repetitions.","Switch arms and repeat the movement."],"category":"strength","images":["One_Arm_Floor_Press/0.jpg","One_Arm_Floor_Press/1.jpg"],"id":"One_Arm_Floor_Press"}'),
('free-exercise-db', 'One_Arm_Lat_Pulldown', 'cable-one-arm-lat-pulldown', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/One_Arm_Lat_Pulldown.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"One Arm Lat Pulldown","force":"pull","level":"beginner","mechanic":"compound","equipment":"cable","primaryMuscles":["lats"],"secondaryMuscles":["biceps","middle back"],"instructions":["Select an appropriate weight and adjust the knee pad to help keep you down. Grasp the handle with a pronated grip. This will be your starting position.","Pull the handle down, squeezing your elbow to your side as you flex the elbow.","Pause at the bottom of the motion, and then slowly return the handle to the starting position.","For multiple repetitions, avoid completely returning the weight to keep tension on the muscles being worked."],"category":"strength","images":["One_Arm_Lat_Pulldown/0.jpg","One_Arm_Lat_Pulldown/1.jpg"],"id":"One_Arm_Lat_Pulldown"}'),
('free-exercise-db', 'One_Arm_Pronated_Dumbbell_Triceps_Extension', 'dumbbell-one-arm-pronated-triceps-extension', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/One_Arm_Pronated_Dumbbell_Triceps_Extension.json', 'Unlicense', NULL, 'new', 86.1, '{"name":"One Arm Pronated Dumbbell Triceps Extension","force":"push","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["triceps"],"secondaryMuscles":[],"instructions":["Lie flat on a bench while holding a dumbbell at arms length. Your arm should be perpendicular to your body. The palm of your hand should be facing towards your feet as a pronated grip is required to perform this exercise.","Place your non lifting hand on your bicep for support.","Slowly begin to lower the dumbbell down as you breathe in.","Then, begin lifting the dumbbell upward as you contract the triceps. Remember to breathe out during the concentric (lifting part of the exercise).","Repeat until you have performed your set repetitions.","Switch arms and repeat the movement."],"category":"strength","images":["One_Arm_Pronated_Dumbbell_Triceps_Extension/0.jpg","One_Arm_Pronated_Dumbbell_Triceps_Extension/1.jpg"],"id":"One_Arm_Pronated_Dumbbell_Triceps_Extension"}'),
('free-exercise-db', 'One_Arm_Supinated_Dumbbell_Triceps_Extension', 'dumbbell-one-arm-supinated-triceps-extension', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/One_Arm_Supinated_Dumbbell_Triceps_Extension.json', 'Unlicense', NULL, 'new', NULL, '{"name":"One Arm Supinated Dumbbell Triceps Extension","force":"push","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["triceps"],"secondaryMuscles":[],"instructions":["Lie flat on a bench while holding a dumbbell at arms length. Your arm should be perpendicular to your body. The palm of your hand should be facing towards your face as a supinated grip is required to perform this exercise.","Place your non lifting hand on your bicep for support.","Slowly begin to lower the dumbbell down as you breathe in.","Then, begin lifting the dumbbell upward as you contract the triceps. Remember to breathe out during the concentric (lifting part of the exercise).","Repeat until you have performed your set repetitions.","Switch arms and repeat the movement.","Switch arms again and repeat the movement."],"category":"strength","images":["One_Arm_Supinated_Dumbbell_Triceps_Extension/0.jpg","One_Arm_Supinated_Dumbbell_Triceps_Extension/1.jpg"],"id":"One_Arm_Supinated_Dumbbell_Triceps_Extension"}'),
('free-exercise-db', 'One_Half_Locust', 'one-half-locust', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/One_Half_Locust.json', 'Unlicense', NULL, 'new', NULL, '{"name":"One Half Locust","force":"static","level":"beginner","mechanic":null,"equipment":null,"primaryMuscles":["quadriceps"],"secondaryMuscles":["abdominals","biceps","chest"],"instructions":["Lie facedown on the floor.","Put your left hand under your left hipbone to pad your hip and pubic bone.","Bend your right knee so you can hold the foot in your right hand.","Lift the foot in the air and simultaneously lift your shoulders off the floor. This also stretches the right hip flexor and the chest and shoulders. Switch sides. If it doesn''t bother your back, you can try it with both arms and legs at the same time."],"category":"stretching","images":["One_Half_Locust/0.jpg","One_Half_Locust/1.jpg"],"id":"One_Half_Locust"}'),
('free-exercise-db', 'One_Handed_Hang', 'one-handed-hang', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/One_Handed_Hang.json', 'Unlicense', NULL, 'new', NULL, '{"name":"One Handed Hang","force":"static","level":"beginner","mechanic":null,"equipment":"other","primaryMuscles":["lats"],"secondaryMuscles":["biceps"],"instructions":["Grab onto a chinup bar with one hand, using a pronated grip. Keep your feet on the floor or a step. Allow the majority of your weight to hang from that hand, while keeping your feet on the ground. Hold for 10-20 seconds and switch sides."],"category":"stretching","images":["One_Handed_Hang/0.jpg","One_Handed_Hang/1.jpg"],"id":"One_Handed_Hang"}'),
('free-exercise-db', 'One_Knee_To_Chest', 'one-knee-to-chest', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/One_Knee_To_Chest.json', 'Unlicense', NULL, 'new', NULL, '{"name":"One Knee To Chest","force":"static","level":"beginner","mechanic":"compound","equipment":null,"primaryMuscles":["glutes"],"secondaryMuscles":["hamstrings","lower back"],"instructions":["Start off by lying on the floor.","Extend one leg straight and pull the other knee to your chest. Hold under the knee joint to protect the kneecap.","Gently tug that knee toward your nose.","Switch sides. This stretches the buttocks and lower back of the bent leg and the hip flexor of the straight leg."],"category":"stretching","images":["One_Knee_To_Chest/0.jpg","One_Knee_To_Chest/1.jpg"],"id":"One_Knee_To_Chest"}'),
('free-exercise-db', 'One_Leg_Barbell_Squat', 'barbell-one-leg-squat', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/One_Leg_Barbell_Squat.json', 'Unlicense', NULL, 'new', NULL, '{"name":"One Leg Barbell Squat","force":"push","level":"expert","mechanic":"compound","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings"],"instructions":["Start by standing about 2 to 3 feet in front of a flat bench with your back facing the bench. Have a barbell in front of you on the floor. Tip: Your feet should be shoulder width apart from each other.","Bend the knees and use a pronated grip with your hands being wider than shoulder width apart from each other to lift the barbell up until you can rest it on your chest.","Then lift the barbell over your head and rest it on the base of your neck. Move one foot back so that your toe is resting on the flat bench. Your other foot should be stationary in front of you. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. Tip: Make sure your back is straight and chest is out while performing this exercise.","As you inhale, slowly lower your leg until your thigh is parallel to the floor. At this point, your knee should be over your toes. Your chest should be directly above the middle of your thigh.","Leading with the chest and hips and contracting the quadriceps, elevate your leg back to the starting position as you exhale.","Repeat for the recommended amount of repetitions.","Switch legs and repeat the movement."],"category":"strength","images":["One_Leg_Barbell_Squat/0.jpg","One_Leg_Barbell_Squat/1.jpg"],"id":"One_Leg_Barbell_Squat"}'),
('free-exercise-db', 'Open_Palm_Kettlebell_Clean', 'kettlebell-open-palm-clean', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Open_Palm_Kettlebell_Clean.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Open Palm Kettlebell Clean","force":"pull","level":"expert","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["hamstrings"],"secondaryMuscles":["glutes","lower back","quadriceps","shoulders"],"instructions":["Place one kettlebell between your feet. Clean the kettlebell by extending through the legs and hips as you raise the kettlebell towards your shoulders.","Release the kettlebell as it comes up, and let it flip so that the ball of the kettlebell lands in the palms of your hands.","Release the kettlebell out in front of you and catch the handle with both hands. Lower the kettlebell to the starting position and repeat."],"category":"strength","images":["Open_Palm_Kettlebell_Clean/0.jpg","Open_Palm_Kettlebell_Clean/1.jpg"],"id":"Open_Palm_Kettlebell_Clean"}'),
('free-exercise-db', 'Otis-Up', 'otis-up', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Otis-Up.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Otis-Up","force":"pull","level":"beginner","mechanic":"compound","equipment":"other","primaryMuscles":["abdominals"],"secondaryMuscles":["chest","shoulders","triceps"],"instructions":["Secure your feet and lay back on the floor. Your knees should be bent. Hold a weight with both hands to your chest. This will be your starting position.","Initiate the movement by flexing the hips and spine to raise your torso up from the ground.","As you move up, press the weight up so that it is above your head at the top of the movement.","Return the weight to your chest as you reverse the sit-up motion, ensuring not to go all the way down to the floor."],"category":"strength","images":["Otis-Up/0.jpg","Otis-Up/1.jpg"],"id":"Otis-Up"}'),
('free-exercise-db', 'Overhead_Cable_Curl', 'cable-overhead-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Overhead_Cable_Curl.json', 'Unlicense', NULL, 'new', 92.3, '{"name":"Overhead Cable Curl","force":"pull","level":"intermediate","mechanic":"isolation","equipment":"cable","primaryMuscles":["biceps"],"secondaryMuscles":[],"instructions":["To begin, set a weight that is comfortable on each side of the pulley machine. Note: Make sure that the amount of weight selected is the same on each side.","Now adjust the height of the pulleys on each side and make sure that they are positioned at a height higher than that of your shoulders.","Stand in the middle of both sides and use an underhand grip (palms facing towards the ceiling) to grab each handle. Your arms should be fully extended and parallel to the floor with your feet positioned shoulder width apart from each other. Your body should be evenly aligned the handles. This is the starting position.","While exhaling, slowly squeeze the biceps on each side until your forearms and biceps touch.","While inhaling, move your forearms back to the starting position. Note: Your entire body is stationary during this exercise except for the forearms.","Repeat for the recommended amount of repetitions prescribed in your program."],"category":"strength","images":["Overhead_Cable_Curl/0.jpg","Overhead_Cable_Curl/1.jpg"],"id":"Overhead_Cable_Curl"}'),
('free-exercise-db', 'Overhead_Lat', 'overhead-lat', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Overhead_Lat.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Overhead Lat","force":"static","level":"expert","mechanic":null,"equipment":"other","primaryMuscles":["lats"],"secondaryMuscles":["triceps"],"instructions":["Sit upright on the floor with your partner behind you. Raise one arm straight up, and flex the elbow, attempting to touch your hand to your back. Your parner should hold your tricep and wrist. This will be your starting position.","Attempt to pull your upper arm to your side as your partner prevents you from doing actually doing so.","After 10-20 seconds, relax the arm and allow your partner to further stretch the lat by applying gentle pressure to the tricep. Hold for 10-20 seconds, and then switch sides."],"category":"stretching","images":["Overhead_Lat/0.jpg","Overhead_Lat/1.jpg"],"id":"Overhead_Lat"}'),
('free-exercise-db', 'Overhead_Slam', 'medicine-ball-overhead-slam', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Overhead_Slam.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Overhead Slam","force":"pull","level":"beginner","mechanic":"compound","equipment":"medicine ball","primaryMuscles":["lats"],"secondaryMuscles":[],"instructions":["Hold a medine ball with both hands and stand with your feet at shoulder width. This will be your starting position.","Initiate the countermovement by raising the ball above your head and fully extending your body.","Reverse the motion, slamming the ball into the ground directly in front of you as hard as you can.","Receive the ball with both hands on the bounce and repeat the movement."],"category":"plyometrics","images":["Overhead_Slam/0.jpg","Overhead_Slam/1.jpg"],"id":"Overhead_Slam"}'),
('free-exercise-db', 'Overhead_Squat', 'barbell-overhead-squat', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Overhead_Squat.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Overhead Squat","force":"push","level":"expert","mechanic":"compound","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["abdominals","calves","glutes","hamstrings","lower back","shoulders","triceps"],"instructions":["Start out by having a barbell in front of you on the floor. Your feet should be wider than shoulder width apart from each other.","Bend the knees and use a pronated grip (palms facing you) to grab the barbell. Your hands should be at a wider than shoulder width apart from each other before lifting. Once you are positioned, lift the barbell up until you can rest it on your chest.","Move the barbell over and slightly behind your head and make sure your arms are fully extended. Keep your head up at all times and also maintain a straight back. Retract your shoulder blades. This is your starting position.","Slowly lower the weight by bending your knees until your thighs are parallel to the ground while inhaling. Tip: Keep your back straight while performing this exercise to avoid any injuries and your arms should remain extended and over your head at all times.","Now use your feet and legs to help bring the weight back up to the starting position while exhaling.","Repeat for the recommended amount of repetitions."],"category":"olympic weightlifting","images":["Overhead_Squat/0.jpg","Overhead_Squat/1.jpg"],"id":"Overhead_Squat"}'),
('free-exercise-db', 'Overhead_Stretch', 'overhead-stretch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Overhead_Stretch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Overhead Stretch","force":"static","level":"beginner","mechanic":"compound","equipment":null,"primaryMuscles":["abdominals"],"secondaryMuscles":["chest","forearms","lats","triceps"],"instructions":["Standing straight up, lace your fingers together and open your palms to the ceiling. Keep your shoulders down as you extend your arms up.","To create a full torso stretch, pull your tailbone down and stabilize your torso as you do this. Stretch the muscles on both the front and the back of the torso."],"category":"stretching","images":["Overhead_Stretch/0.jpg","Overhead_Stretch/1.jpg"],"id":"Overhead_Stretch"}'),
('free-exercise-db', 'Overhead_Triceps', 'overhead-triceps', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Overhead_Triceps.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Overhead Triceps","force":"static","level":"expert","mechanic":null,"equipment":"body only","primaryMuscles":["triceps"],"secondaryMuscles":["lats"],"instructions":["Sit upright on the floor with your partner behind you. Raise one arm straight up, and flex the elbow, attempting to touch your hand to your back. Your parner should hold your elbow and wrist. This will be your starting position.","Attempt to extend the arm straight into the air as your partner prevents you from doing actually doing so.","After 10-20 seconds, relax the arm and allow your partner to further stretch the tricep by applying gentle pressure to the wrist. Hold for 10-20 seconds, and then switch sides."],"category":"stretching","images":["Overhead_Triceps/0.jpg","Overhead_Triceps/1.jpg"],"id":"Overhead_Triceps"}'),
('free-exercise-db', 'Pallof_Press', 'cable-pallof-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Pallof_Press.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Pallof Press","force":"pull","level":"beginner","mechanic":"isolation","equipment":"cable","primaryMuscles":["abdominals"],"secondaryMuscles":["chest","shoulders","triceps"],"instructions":["Connect a standard handle to a tower, and—if possible—position the cable to shoulder height. If not, a low pulley will suffice.","With your side to the cable, grab the handle with both hands and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable.","With your feet positioned hip-width apart and knees slightly bent, hold the cable to the middle of your chest. This will be your starting position.","Press the cable away from your chest, fully extending both arms. You core should be tight and engaged.","Hold the repetition for several seconds before returning to the starting position.","At the conclusion of the set, repeat facing the other direction."],"category":"strength","images":["Pallof_Press/0.jpg","Pallof_Press/1.jpg"],"id":"Pallof_Press"}'),
('free-exercise-db', 'Pallof_Press_With_Rotation', 'cable-pallof-press-rotation', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Pallof_Press_With_Rotation.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Pallof Press With Rotation","force":"pull","level":"beginner","mechanic":"compound","equipment":"cable","primaryMuscles":["abdominals"],"secondaryMuscles":["chest","shoulders","triceps"],"instructions":["Connect a standard handle to a tower, and position the cable to shoulder height.","With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable. Align outstretched arm with cable.","With your feet positioned hip-width apart, pull the cable into your chest and grab the handle with your other hand. Both hands should be on the handle at this time.","Facing forward, press the cable away from your chest. You core should be tight and engaged.","Keeping your hips straight, twist your torso away from the pulley until you get a full quarter rotation.","Maintain your rigid stance and straight arms. Return to the neutral position in a slow and controlled manner. Your arms should be extended in front of you.","With the side tension still engaging your core, bring your hands to your chest and immediately press outward to a fully extended position. This constitutes one rep.","Repeat to failure.","Then, reposition and repeat the same series of movements on the opposite side."],"category":"strength","images":["Pallof_Press_With_Rotation/0.jpg","Pallof_Press_With_Rotation/1.jpg"],"id":"Pallof_Press_With_Rotation"}'),
('free-exercise-db', 'Palms-Down_Dumbbell_Wrist_Curl_Over_A_Bench', 'dumbbell-palms-down-wrist-curl-over-bench', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Palms-Down_Dumbbell_Wrist_Curl_Over_A_Bench.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Palms-Down Dumbbell Wrist Curl Over A Bench","force":"pull","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["forearms"],"secondaryMuscles":[],"instructions":["Start out by placing two dumbbells on one side of a flat bench.","Kneel down on both of your knees so that your body is facing the flat bench.","Use your arms to grab both of the dumbbells with a pronated grip (palms facing down) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge.","Start out by curling your wrist upwards and exhaling.","Slowly lower your wrists back down to the starting position while inhaling.","Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Palms-Down_Dumbbell_Wrist_Curl_Over_A_Bench/0.jpg","Palms-Down_Dumbbell_Wrist_Curl_Over_A_Bench/1.jpg"],"id":"Palms-Down_Dumbbell_Wrist_Curl_Over_A_Bench"}'),
('free-exercise-db', 'Palms-Down_Wrist_Curl_Over_A_Bench', 'barbell-palms-down-wrist-curl-over-bench', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Palms-Down_Wrist_Curl_Over_A_Bench.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Palms-Down Wrist Curl Over A Bench","force":"pull","level":"beginner","mechanic":"isolation","equipment":"barbell","primaryMuscles":["forearms"],"secondaryMuscles":[],"instructions":["Start out by placing a barbell on one side of a flat bench.","Kneel down on both of your knees so that your body is facing the flat bench.","Use your arms to grab the barbell with a pronated grip (palms down) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge.","Start out by curling your wrist upwards and exhaling.","Slowly lower your wrists back down to the starting position while inhaling.","Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Palms-Down_Wrist_Curl_Over_A_Bench/0.jpg","Palms-Down_Wrist_Curl_Over_A_Bench/1.jpg"],"id":"Palms-Down_Wrist_Curl_Over_A_Bench"}'),
('free-exercise-db', 'Palms-Up_Barbell_Wrist_Curl_Over_A_Bench', 'barbell-palms-up-wrist-curl-over-bench', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Palms-Up_Barbell_Wrist_Curl_Over_A_Bench.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Palms-Up Barbell Wrist Curl Over A Bench","force":"pull","level":"beginner","mechanic":"isolation","equipment":"barbell","primaryMuscles":["forearms"],"secondaryMuscles":[],"instructions":["Start out by placing a barbell on one side of a flat bench.","Kneel down on both of your knees so that your body is facing the flat bench.","Use your arms to grab the barbell with a supinated grip (palms up) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge.","Start out by curling your wrist upwards and exhaling.","Slowly lower your wrists back down to the starting position while inhaling.","Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Palms-Up_Barbell_Wrist_Curl_Over_A_Bench/0.jpg","Palms-Up_Barbell_Wrist_Curl_Over_A_Bench/1.jpg"],"id":"Palms-Up_Barbell_Wrist_Curl_Over_A_Bench"}'),
('free-exercise-db', 'Palms-Up_Dumbbell_Wrist_Curl_Over_A_Bench', 'dumbbell-palms-up-wrist-curl-over-bench', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Palms-Up_Dumbbell_Wrist_Curl_Over_A_Bench.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Palms-Up Dumbbell Wrist Curl Over A Bench","force":"pull","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["forearms"],"secondaryMuscles":[],"instructions":["Start out by placing two dumbbells on one side of a flat bench.","Kneel down on both of your knees so that your body is facing the flat bench.","Use your arms to grab both of the dumbbells with a supinated grip (palms up) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge.","Start out by curling your wrist upwards and exhaling.","Slowly lower your wrists back down to the starting position while inhaling. Make sure to inhale during this part of the exercise.","Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Palms-Up_Dumbbell_Wrist_Curl_Over_A_Bench/0.jpg","Palms-Up_Dumbbell_Wrist_Curl_Over_A_Bench/1.jpg"],"id":"Palms-Up_Dumbbell_Wrist_Curl_Over_A_Bench"}'),
('free-exercise-db', 'Parallel_Bar_Dip', 'parallel-bar-dip', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Parallel_Bar_Dip.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Parallel Bar Dip","force":"push","level":"beginner","mechanic":"compound","equipment":"other","primaryMuscles":["triceps"],"secondaryMuscles":["chest","shoulders"],"instructions":["Stand between a set of parallel bars. Place a hand on each bar, and then take a small jump to help you get into the starting position with your arms locked out.","Begin by flexing the elbow, lowering your body until your arms break 90 degrees. Avoid swinging, and maintain good posture throughout the descent.","Reverse the motion by extending the elbow, pushing yourself back up into the starting position.","Repeat for the desired number of repetitions."],"category":"strength","images":["Parallel_Bar_Dip/0.jpg","Parallel_Bar_Dip/1.jpg"],"id":"Parallel_Bar_Dip"}'),
('free-exercise-db', 'Pelvic_Tilt_Into_Bridge', 'pelvic-tilt-into-bridge', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Pelvic_Tilt_Into_Bridge.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Pelvic Tilt Into Bridge","force":"static","level":"intermediate","mechanic":"compound","equipment":null,"primaryMuscles":["lower back"],"secondaryMuscles":[],"instructions":["Lie down with your feet on the floor, heels directly under your knees.","Lift only your tailbone to the ceiling to stretch your lower back. (Don''t lift the entire spine yet.) Pull in your stomach.","To go into a bridge, lift the entire spine except the neck."],"category":"stretching","images":["Pelvic_Tilt_Into_Bridge/0.jpg","Pelvic_Tilt_Into_Bridge/1.jpg"],"id":"Pelvic_Tilt_Into_Bridge"}'),
('free-exercise-db', 'Peroneals-SMR', 'foam-roller-peroneals-smr', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Peroneals-SMR.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Peroneals-SMR","force":"static","level":"intermediate","mechanic":null,"equipment":"foam roll","primaryMuscles":["calves"],"secondaryMuscles":[],"instructions":["Lay on your side, supporting your weight on your forearm and on a foam roller placed on the outside of your lower leg. Your upper leg can either be on top of your lower leg, or you can cross it in front of you. This will be your starting position.","Raise your hips off of the ground and begin to roll from below the knee to above the ankle on the side of your leg, pausing at points of tension for 10-30 seconds. Repeat on the other leg."],"category":"stretching","images":["Peroneals-SMR/0.jpg","Peroneals-SMR/1.jpg"],"id":"Peroneals-SMR"}'),
('free-exercise-db', 'Peroneals_Stretch', 'peroneals-stretch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Peroneals_Stretch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Peroneals Stretch","force":"static","level":"intermediate","mechanic":null,"equipment":"other","primaryMuscles":["calves"],"secondaryMuscles":[],"instructions":["In a seated position, loop a belt, rope, or band around one foot. This will be your starting position.","With the leg extended and the heel off of the ground, pull on the belt so that the foot is inverted, with the inside of the foot being pulled towards you. Hold for 10-20 seconds, and then switch sides."],"category":"stretching","images":["Peroneals_Stretch/0.jpg","Peroneals_Stretch/1.jpg"],"id":"Peroneals_Stretch"}'),
('free-exercise-db', 'Physioball_Hip_Bridge', 'exercise-ball-physioball-hip-bridge', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Physioball_Hip_Bridge.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Physioball Hip Bridge","force":"push","level":"beginner","mechanic":"compound","equipment":"exercise ball","primaryMuscles":["glutes"],"secondaryMuscles":["hamstrings"],"instructions":["Lay on a ball so that your upper back is on the ball with your hips unsupported. Both feet should be flat on the floor, hip width apart or wider. This will be your starting position.","Begin by extending the hips using your glutes and hamstrings, raising your hips upward as you bridge.","Pause at the top of the motion and return to the starting position."],"category":"strength","images":["Physioball_Hip_Bridge/0.jpg","Physioball_Hip_Bridge/1.jpg"],"id":"Physioball_Hip_Bridge"}'),
('free-exercise-db', 'Pin_Presses', 'barbell-pin-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Pin_Presses.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Pin Presses","force":"push","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["triceps"],"secondaryMuscles":["chest","forearms","lats","middle back","shoulders"],"instructions":["Pin presses remove the eccentric phase of the bench press, developing starting strength. They also allow you to train a desired range of motion.","The bench should be set up in a power rack. Set the pins to the desired point in your range of motion, whether it just be lockout or an inch off of your chest. The bar should be moved to the pins and prepared for lifting.","Begin by lying on the bench, with the bar directly above the contact point during your regular bench. Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement.","You can take a standard bench grip, or shoulder width to focus on the triceps. The bar, wrist, and elbow should stay in line at all times. Focus on squeezing the bar and trying to pull it apart.","Drive the bar up with as much force as possible. The elbows should be tucked in until lockout.","Return the bar to the pins, pausing before beginning the next repetition."],"category":"powerlifting","images":["Pin_Presses/0.jpg","Pin_Presses/1.jpg"],"id":"Pin_Presses"}'),
('free-exercise-db', 'Piriformis-SMR', 'foam-roller-piriformis-smr', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Piriformis-SMR.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Piriformis-SMR","force":"static","level":"intermediate","mechanic":"isolation","equipment":"foam roll","primaryMuscles":["glutes"],"secondaryMuscles":[],"instructions":["Sit with your buttocks on top of a foam roll. Bend your knees, and then cross one leg so that the ankle is over the knee. This will be your starting position.","Shift your weight to the side of the crossed leg, rolling over the buttocks until you feel tension in your upper glute. You may assist the stretch by using one hand to pull the bent knee towards your chest. Hold this position for 10-30 seconds, and then switch sides."],"category":"stretching","images":["Piriformis-SMR/0.jpg","Piriformis-SMR/1.jpg"],"id":"Piriformis-SMR"}'),
('free-exercise-db', 'Plank', 'plank', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Plank.json', 'Unlicense', NULL, 'exact', 100.0, '{"name":"Plank","force":"static","level":"beginner","mechanic":"isolation","equipment":"body only","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Get into a prone position on the floor, supporting your weight on your toes and your forearms. Your arms are bent and directly below the shoulder.","Keep your body straight at all times, and hold this position as long as possible. To increase difficulty, an arm or leg can be raised."],"category":"strength","images":["Plank/0.jpg","Plank/1.jpg"],"id":"Plank"}'),
('free-exercise-db', 'Plate_Pinch', 'plate-pinch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Plate_Pinch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Plate Pinch","force":"static","level":"intermediate","mechanic":"isolation","equipment":"other","primaryMuscles":["forearms"],"secondaryMuscles":[],"instructions":["Grab two wide-rimmed plates and put them together with the smooth sides facing outward","Use your fingers to grip the outside part of the plate and your thumb for the other side thus holding both plates together. This is the starting position.","Squeeze the plate with your fingers and thumb. Hold this position for as long as you can.","Repeat for the recommended amount of sets prescribed in your program.","Switch arms and repeat the movements."],"category":"strength","images":["Plate_Pinch/0.jpg","Plate_Pinch/1.jpg"],"id":"Plate_Pinch"}'),
('free-exercise-db', 'Plate_Twist', 'plate-twist', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Plate_Twist.json', 'Unlicense', NULL, 'exact', 100.0, '{"name":"Plate Twist","force":"pull","level":"intermediate","mechanic":"compound","equipment":"other","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Lie down on the floor or an exercise mat with your legs fully extended and your upper body upright. Grab the plate by its sides with both hands out in front of your abdominals with your arms slightly bent.","Slowly cross your legs near your ankles and lift them up off the ground. Your knees should also be bent slightly. Note: Move your upper body back slightly to help keep you balanced turning this exercise. This is the starting position.","Move the plate to the left side and touch the floor with it. Breathe out as you perform that movement.","Come back to the starting position as you breathe in and then repeat the movement but this time to the right side of the body. Tip: Use a slow controlled movement at all times. Jerking motions can injure the back.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Plate_Twist/0.jpg","Plate_Twist/1.jpg"],"id":"Plate_Twist"}'),
('free-exercise-db', 'Platform_Hamstring_Slides', 'platform-hamstring-slide', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Platform_Hamstring_Slides.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Platform Hamstring Slides","force":"pull","level":"beginner","mechanic":"isolation","equipment":"other","primaryMuscles":["hamstrings"],"secondaryMuscles":["glutes"],"instructions":["For this movement a wooden floor or similar is needed. Lay on your back with your legs extended. Place a gym towel or a light weight underneath your heel. This will be your starting position.","Begin the movement by flexing the knee, keeping your other leg straight.","Continue bringing the heel closer to you, sliding it on the floor.","At full knee flexion, reverse the movement to return to the starting position."],"category":"strength","images":["Platform_Hamstring_Slides/0.jpg","Platform_Hamstring_Slides/1.jpg"],"id":"Platform_Hamstring_Slides"}'),
('free-exercise-db', 'Plie_Dumbbell_Squat', 'dumbbell-plie-squat', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Plie_Dumbbell_Squat.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Plie Dumbbell Squat","force":"push","level":"beginner","mechanic":"compound","equipment":"dumbbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["abdominals","calves","glutes","hamstrings"],"instructions":["Hold a dumbbell at the base with both hands and stand straight up. Move your legs so that they are wider than shoulder width apart from each other with your knees slightly bent.","Your toes should be facing out. Note: Your arms should be stationary while performing the exercise. This is the starting position.","Slowly bend the knees and lower your legs until your thighs are parallel to the floor. Make sure to inhale as this is the eccentric part of the exercise.","Press mainly with the heel of the foot to bring the body back to the starting position while exhaling.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Plie_Dumbbell_Squat/0.jpg","Plie_Dumbbell_Squat/1.jpg"],"id":"Plie_Dumbbell_Squat"}'),
('free-exercise-db', 'Plyo_Kettlebell_Pushups', 'kettlebell-plyo-push-up', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Plyo_Kettlebell_Pushups.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Plyo Kettlebell Pushups","force":"push","level":"expert","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["Place a kettlebell on the floor. Place yourself in a pushup position, on your toes with one hand on the ground and one hand holding the kettlebell, with your elbows extended. This will be your starting position.","Begin by lowering yourself as low as you can, keeping your back straight.","Quickly and forcefully reverse direction, pushing yourself up to the other side of the kettlebell, switching hands as you do so. Continue the movement by descending and repeating the movement back and forth."],"category":"strength","images":["Plyo_Kettlebell_Pushups/0.jpg","Plyo_Kettlebell_Pushups/1.jpg"],"id":"Plyo_Kettlebell_Pushups"}'),
('free-exercise-db', 'Plyo_Push-up', 'plyo-push-up', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Plyo_Push-up.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Plyo Push-up","force":"push","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["Move into a prone position on the floor, supporting your weight on your hands and toes.","Your arms should be fully extended with the hands around shoulder width. Keep your body straight throughout the movement. This will be your starting position.","Descend by flexing at the elbow, lowering your chest towards the ground.","At the bottom, reverse the motion by pushing yourself up through elbow extension as quickly as possible. Attempt to push your upper body up until your hands leave the ground.","Return to the starting position and repeat the exercise.","For added difficulty, add claps into the movement while you are air borne."],"category":"plyometrics","images":["Plyo_Push-up/0.jpg","Plyo_Push-up/1.jpg"],"id":"Plyo_Push-up"}'),
('free-exercise-db', 'Posterior_Tibialis_Stretch', 'posterior-tibialis-stretch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Posterior_Tibialis_Stretch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Posterior Tibialis Stretch","force":"static","level":"intermediate","mechanic":null,"equipment":"other","primaryMuscles":["calves"],"secondaryMuscles":[],"instructions":["In a seated position, loop a belt, rope, or band around one foot. This will be your starting position.","With the leg extended and the heel off of the ground, pull on the belt so that the foot is everted, with the outside of the foot being pulled towards you. Hold for 10-20 seconds, and then switch sides."],"category":"stretching","images":["Posterior_Tibialis_Stretch/0.jpg","Posterior_Tibialis_Stretch/1.jpg"],"id":"Posterior_Tibialis_Stretch"}'),
('free-exercise-db', 'Power_Clean', 'barbell-power-clean', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Power_Clean.json', 'Unlicense', NULL, 'exact', 100.0, '{"name":"Power Clean","force":"pull","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["hamstrings"],"secondaryMuscles":["calves","forearms","glutes","lower back","middle back","quadriceps","shoulders","traps","triceps"],"instructions":["Stand with your feet slightly wider than shoulder width apart and toes pointing out slightly.","Squat down and grasp bar with a closed, pronated grip. Your hands should be slightly wider than shoulder width apart outside knees with elbows fully extended.","Place the bar about 1 inch in front of your shins and over the balls of your feet.","Your back should be flat or slightly arched, your chest held up and out and your shoulder blades should be retracted.","Keep your head in a neutral position (in line with vertebral column and not tilted or rotated) with your eyes focused straight ahead. Inhale during this phase.","Lift the bar from the floor by forcefully extending the hips and the knees as you exhale. Tip: The upper torso should maintain the same angle. Do not bend at the waist yet and do not let the hips rise before the shoulders (this would have the effect of pushing the glutes in the air and stretching the hamstrings.","Keep elbows fully extended with the head in a neutral position and the shoulders over the bar.","As the bar raises keep it as close to the shins as possible.","As the bar passes the knees, thrust your hips forward and slightly bend the knees to avoid locking them. Tip: At this point your thighs should be against the bar.","Keep the back flat or slightly arched, elbows fully extended and your head neutral. Tip: You will hold your breath until the next phase.","Inhale and then forcefully and quickly extend your hips and knees and stand on your toes.","Keep the bar as close to your body as possible. Tip: Your back should be flat with the elbows pointed out to the sides and your head in a neutral position. Also, keep your shoulders over the bar and arms straight as long as possible.","When your lower body joints are fully extended, shrug the shoulders upward rapidly without letting the elbows flex yet. Exhale during this portion of the movement.","As the shoulders reach their highest elevation flex your elbows to begin pulling your body under the bar.","Continue to pull the arms as high and as long as possible. Tip: Due to the explosive nature of this phase, your torso will be erect or with an arched back, your head will be tilted back slightly and your feet may lose contact with the floor.","After the lower body has fully extended and the bar reaches near maximal height, pull your body under the bar and rotate the arms around and under the bar.","Simultaneously, flex the hips and knees into a quarter squat position.","Once the arms are under the bar, inhale and then lift your elbows to position the upper arms parallel to the floor. Rack the bar across the front of your collar bones and front shoulder muscles.","Catch the bar with an erect and tight torso, a neutral head position and flat feet. Exhale during this movement.","Stand up by extending the hips and knees to a fully erect position.","Lower the bar by gradually reducing the muscular tension of the arms to allow a controlled descent of the bar to the thighs. Inhale during this movement.","Simultaneously flex the hips and knees to cushion the impact of the bar on the thighs.","Squat down with the elbows fully extended until the bar touches the floor.","Start over at Phase 1 and repeat for the recommended amount of repetitions."],"category":"strength","images":["Power_Clean/0.jpg","Power_Clean/1.jpg"],"id":"Power_Clean"}'),
('free-exercise-db', 'Power_Clean_from_Blocks', 'barbell-power-clean-from-blocks', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Power_Clean_from_Blocks.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Power Clean from Blocks","force":"pull","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["hamstrings"],"secondaryMuscles":["quadriceps"],"instructions":["With a barbell on boxes of the desired height, take a grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.","Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. As the bar approaches the mid-thigh position, begin extending through the hips.","In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight. At the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended.","As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, pull yourself under the bar far enough that it can be racked onto the shoulders, rotating your elbows under the bar as you do so. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed.","Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position, and complete the repetition by returning the weight to the boxes."],"category":"olympic weightlifting","images":["Power_Clean_from_Blocks/0.jpg","Power_Clean_from_Blocks/1.jpg"],"id":"Power_Clean_from_Blocks"}'),
('free-exercise-db', 'Power_Jerk', 'barbell-power-jerk', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Power_Jerk.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Power Jerk","force":"push","level":"expert","mechanic":"compound","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["abdominals","calves","glutes","hamstrings","shoulders","triceps"],"instructions":["Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible.","Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders.","At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as possible. In the brief moment the feet are not actively driving against the platform, the athletes effort to push the bar up will drive them down. The feet should be moved to a slightly wider stance, with the knees partially bent.","Receive the bar with the arms locked out overhead.","Return to a standing position."],"category":"olympic weightlifting","images":["Power_Jerk/0.jpg","Power_Jerk/1.jpg"],"id":"Power_Jerk"}'),
('free-exercise-db', 'Power_Partials', 'dumbbell-power-partials', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Power_Partials.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Power Partials","force":"push","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":[],"instructions":["Stand up with your torso upright and a dumbbell on each hand being held at arms length. The elbows should be close to the torso.","The palms of the hands should be facing your torso. Your feet should be about shoulder width apart. This will be your starting position.","Keeping your arms straight and the torso stationary, lift the weights out to your sides until they are about shoulder level height while exhaling.","Feel the contraction for a second and begin to lower the weights back down to the starting position while inhaling. Tip: Keep the palms facing down with the little finger slightly higher while lifting and lowering the weights as it will concentrate the stress on your shoulders mainly.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Power_Partials/0.jpg","Power_Partials/1.jpg"],"id":"Power_Partials"}'),
('free-exercise-db', 'Power_Snatch', 'barbell-power-snatch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Power_Snatch.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Power Snatch","force":"pull","level":"expert","mechanic":"compound","equipment":"barbell","primaryMuscles":["hamstrings"],"secondaryMuscles":["calves","glutes","lower back","quadriceps","shoulders","traps","triceps"],"instructions":["Begin with a loaded barbell on the floor. The bar should be close to or touching the shins, and a wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar. This will be the starting position.","Begin the first pull by driving through the front of the heels, raising the bar from the ground. The back angle should stay the same until the bar passes the knees.","Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body. At peak extension, shrug the shoulders and allow the elbows to flex to the side.","As you move your feet into the receiving position, a slightly wider position, pull yourself below the bar as you elevate the bar overhead. The bar should be received in a partial squat. Continue raising the bar to the overhead position, receiving the bar locked out overhead.","Return to a standing position with the weight over head."],"category":"olympic weightlifting","images":["Power_Snatch/0.jpg","Power_Snatch/1.jpg"],"id":"Power_Snatch"}'),
('free-exercise-db', 'Power_Snatch_from_Blocks', 'barbell-power-snatch-from-blocks', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Power_Snatch_from_Blocks.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Power Snatch from Blocks","force":"pull","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","forearms","glutes","hamstrings","lower back","shoulders","traps","triceps"],"instructions":["Begin with a loaded barbell on boxes or stands of the desired height. A wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar, with the elbows pointed out. This will be the starting position.","Begin the first pull by driving through the front of the heels, raising the bar from the boxes.","Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body. At peak extension, shrug the shoulders and allow the elbows to flex to the side.","As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. The feet should move to just outside the hips, turned out as necessary. Receive the bar above a full squat and with the arms fully extended overhead.","Keeping the bar aligned over the front of the heels, your head and chest up, drive through heels of the feet to move to a standing position. Carefully return the weight to the boxes."],"category":"olympic weightlifting","images":["Power_Snatch_from_Blocks/0.jpg","Power_Snatch_from_Blocks/1.jpg"],"id":"Power_Snatch_from_Blocks"}'),
('free-exercise-db', 'Power_Stairs', 'power-stairs', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Power_Stairs.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Power Stairs","force":"pull","level":"intermediate","mechanic":"compound","equipment":"other","primaryMuscles":["hamstrings"],"secondaryMuscles":["adductors","calves","glutes","lower back","quadriceps","shoulders","traps"],"instructions":["In the power stairs, implements are moved up a staircase. For training purposes, these can be performed with a tire or box.","Begin by taking the implement with both hands. Set your feet wide, with your head and chest up. Drive through the ground with your heels, extending your knees and hips to raise the weight from the ground.","As you lean back, attempt to swing the weight onto the stairs, which are usually around 16-18\" high. You can use your legs to help push the weight onto the stair.","Repeat for 3-5 repetitions, and continue with a heavier weight, moving as fast as possible."],"category":"strongman","images":["Power_Stairs/0.jpg","Power_Stairs/1.jpg"],"id":"Power_Stairs"}'),
('free-exercise-db', 'Preacher_Curl', 'barbell-preacher-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Preacher_Curl.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Preacher Curl","force":"pull","level":"beginner","mechanic":"isolation","equipment":"barbell","primaryMuscles":["biceps"],"secondaryMuscles":[],"instructions":["To perform this movement you will need a preacher bench and an E-Z bar. Grab the E-Z curl bar at the close inner handle (either have someone hand you the bar which is preferable or grab the bar from the front bar rest provided by most preacher benches). The palm of your hands should be facing forward and they should be slightly tilted inwards due to the shape of the bar.","With the upper arms positioned against the preacher bench pad and the chest against it, hold the E-Z Curl Bar at shoulder length. This will be your starting position.","As you breathe in, slowly lower the bar until your upper arm is extended and the biceps is fully stretched.","As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the bar is at shoulder height. Squeeze the biceps hard and hold this position for a second.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Preacher_Curl/0.jpg","Preacher_Curl/1.jpg"],"id":"Preacher_Curl"}'),
('free-exercise-db', 'Preacher_Hammer_Dumbbell_Curl', 'dumbbell-preacher-hammer-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Preacher_Hammer_Dumbbell_Curl.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Preacher Hammer Dumbbell Curl","force":"pull","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["biceps"],"secondaryMuscles":["forearms"],"instructions":["Place the upper part of both arms on top of the preacher bench as you hold a dumbbell in each hand with the palms facing each other (neutral grip).","As you breathe in, slowly lower the dumbbells until your upper arm is extended and the biceps is fully stretched.","As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the dumbbells are at shoulder height.","Squeeze the biceps hard for a second at the contracted position and repeat for the recommended amount of repetitions."],"category":"strength","images":["Preacher_Hammer_Dumbbell_Curl/0.jpg","Preacher_Hammer_Dumbbell_Curl/1.jpg"],"id":"Preacher_Hammer_Dumbbell_Curl"}'),
('free-exercise-db', 'Press_Sit-Up', 'barbell-press-sit-up', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Press_Sit-Up.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Press Sit-Up","force":"push","level":"expert","mechanic":"compound","equipment":"barbell","primaryMuscles":["abdominals"],"secondaryMuscles":["chest","shoulders","triceps"],"instructions":["To begin, lie down on a bench with a barbell resting on your chest. Position your legs so they are secure on the extension of the abdominal bench. This is the starting position.","While inhaling, tighten your abdominals and glutes. Simultaneously curl your torso as you do when performing a sit-up and press the barbell to an overhead position while exhaling. Tip: Use your arms to push the barbell out as you perform this exercise while still focusing on the abdominal muscles.","Lower your upper body back down to the starting position while bringing the barbell back down to your torso. Remember to breathe in while lowering the body.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Press_Sit-Up/0.jpg","Press_Sit-Up/1.jpg"],"id":"Press_Sit-Up"}'),
('free-exercise-db', 'Prone_Manual_Hamstring', 'prone-manual-hamstring', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Prone_Manual_Hamstring.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Prone Manual Hamstring","force":"static","level":"beginner","mechanic":"isolation","equipment":null,"primaryMuscles":["hamstrings"],"secondaryMuscles":[],"instructions":["You will need a partner for this exercise. Lay face down with your legs straight. Your assistant will place their hand on your heel.","To begin, flex the knee to curl your leg up. Your partner should provide resistance, starting light and increasing the pressure as the movement is completed. Communicate with your partner to monitor appropriate resistance levels.","Pause at the top, returning the leg to the starting position as your partner provides resistance going the other direction."],"category":"strength","images":["Prone_Manual_Hamstring/0.jpg","Prone_Manual_Hamstring/1.jpg"],"id":"Prone_Manual_Hamstring"}'),
('free-exercise-db', 'Prowler_Sprint', 'prowler-sprint', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Prowler_Sprint.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Prowler Sprint","force":"push","level":"beginner","mechanic":"compound","equipment":"other","primaryMuscles":["hamstrings"],"secondaryMuscles":["calves","chest","glutes","quadriceps","shoulders"],"instructions":["Place your sled on an appropriate surface, loaded to a suitable weight. The sled should provide enough resistance to require effort, but not so heavy that you are significantly slowed down.","You may use the upright or the low handles for this exercise. Place your hands on the handles with your arms extended, leaning into the implement.","With good posture, drive through the ground with alternating, short steps. Move as fast as you can for a short distance."],"category":"cardio","images":["Prowler_Sprint/0.jpg","Prowler_Sprint/1.jpg"],"id":"Prowler_Sprint"}'),
('free-exercise-db', 'Pull_Through', 'cable-pull-through', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Pull_Through.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Pull Through","force":"pull","level":"beginner","mechanic":"compound","equipment":"cable","primaryMuscles":["glutes"],"secondaryMuscles":["hamstrings","lower back"],"instructions":["Begin standing a few feet in front of a low pulley with a rope or handle attached. Face away from the machine, straddling the cable, with your feet set wide apart.","Begin the movement by reaching through your legs as far as possible, bending at the hips. Keep your knees slightly bent. Keeping your arms straight, extend through the hip to stand straight up. Avoid pulling upward through the shoulders; all of the motion should originate through the hips."],"category":"strength","images":["Pull_Through/0.jpg","Pull_Through/1.jpg"],"id":"Pull_Through"}'),
('free-exercise-db', 'Pullups', 'pull-up', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Pullups.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Pullups","force":"pull","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["lats"],"secondaryMuscles":["biceps","middle back"],"instructions":["Grab the pull-up bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.","As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.","Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.","After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.","Repeat this motion for the prescribed amount of repetitions."],"category":"strength","images":["Pullups/0.jpg","Pullups/1.jpg"],"id":"Pullups"}'),
('free-exercise-db', 'Push-Up_Wide', 'push-up-wide', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Push-Up_Wide.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Push-Up Wide","force":null,"level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["chest"],"secondaryMuscles":["abdominals","shoulders","triceps"],"instructions":["With your hands wide apart, support your body on your toes and hands in a plank position. Your elbows should be extended and your body straight. Do not allow your hips to sag. This will be your starting position.","To begin, allow the elbows to flex, lowering your chest to the floor as you inhale.","Using your pectoral muscles, press your upper body back up to the starting position by extending the elbows. Exhale as you perform this step.","After pausing at the contracted position, repeat the movement for the prescribed amount of repetitions."],"category":"strength","images":["Push-Up_Wide/0.jpg","Push-Up_Wide/1.jpg"],"id":"Push-Up_Wide"}'),
('free-exercise-db', 'Push-Ups_-_Close_Triceps_Position', 'push-up-close-triceps-position', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Push-Ups_-_Close_Triceps_Position.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Push-Ups - Close Triceps Position","force":"push","level":"intermediate","mechanic":"compound","equipment":"body only","primaryMuscles":["triceps"],"secondaryMuscles":["chest","shoulders"],"instructions":["Lie on the floor face down and place your hands closer than shoulder width for a close hand position. Make sure that you are holding your torso up at arms'' length.","Lower yourself until your chest almost touches the floor as you inhale.","Using your triceps and some of your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step.","After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions."],"category":"strength","images":["Push-Ups_-_Close_Triceps_Position/0.jpg","Push-Ups_-_Close_Triceps_Position/1.jpg"],"id":"Push-Ups_-_Close_Triceps_Position"}'),
('free-exercise-db', 'Push-Ups_With_Feet_Elevated', 'push-up-feet-elevated', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Push-Ups_With_Feet_Elevated.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Push-Ups With Feet Elevated","force":"push","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["Lie on the floor face down and place your hands about 36 inches apart from each other holding your torso up at arms length.","Place your toes on top of a flat bench. This will allow your body to be elevated. Note: The higher the elevation of the flat bench, the higher the resistance of the exercise is.","Lower yourself until your chest almost touches the floor as you inhale.","Using your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step.","After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions."],"category":"strength","images":["Push-Ups_With_Feet_Elevated/0.jpg","Push-Ups_With_Feet_Elevated/1.jpg"],"id":"Push-Ups_With_Feet_Elevated"}'),
('free-exercise-db', 'Push-Ups_With_Feet_On_An_Exercise_Ball', 'exercise-ball-push-up-feet', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Push-Ups_With_Feet_On_An_Exercise_Ball.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Push-Ups With Feet On An Exercise Ball","force":"push","level":"intermediate","mechanic":"compound","equipment":"exercise ball","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["Lie on the floor face down and place your hands about 36 inches apart from each other holding your torso up at arms length.","Place your toes on top of an exercise ball. This will allow your body to be elevated.","Lower yourself until your chest almost touches the floor as you inhale.","Using your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step.","After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions."],"category":"strength","images":["Push-Ups_With_Feet_On_An_Exercise_Ball/0.jpg","Push-Ups_With_Feet_On_An_Exercise_Ball/1.jpg"],"id":"Push-Ups_With_Feet_On_An_Exercise_Ball"}'),
('free-exercise-db', 'Push_Press', 'barbell-push-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Push_Press.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Push Press","force":"push","level":"expert","mechanic":"compound","equipment":"barbell","primaryMuscles":["shoulders"],"secondaryMuscles":["quadriceps","triceps"],"instructions":[],"category":"olympic weightlifting","images":["Push_Press/0.jpg","Push_Press/1.jpg"],"id":"Push_Press"}'),
('free-exercise-db', 'Push_Press_-_Behind_the_Neck', 'barbell-push-press-behind-neck', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Push_Press_-_Behind_the_Neck.json', 'Unlicense', NULL, 'new', 87.2, '{"name":"Push Press - Behind the Neck","force":"push","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["shoulders"],"secondaryMuscles":["calves","quadriceps","triceps"],"instructions":["Standing with the weight racked on the back of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible. Drive through the heels create as much speed and force as possible, moving the bar in a vertical path.","Using the momentum generated, finish pressing the weight overhead be extending through the arms.","Return to the starting position, using your legs to absorb the impact."],"category":"olympic weightlifting","images":["Push_Press_-_Behind_the_Neck/0.jpg","Push_Press_-_Behind_the_Neck/1.jpg"],"id":"Push_Press_-_Behind_the_Neck"}'),
('free-exercise-db', 'Push_Up_to_Side_Plank', 'push-up-to-side-plank', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Push_Up_to_Side_Plank.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Push Up to Side Plank","force":"push","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["chest"],"secondaryMuscles":["abdominals","shoulders","triceps"],"instructions":["Get into pushup position on the toes with your hands just outside of shoulder width.","Perform a pushup by allowing the elbows to flex. As you descend, keep your body straight.","Do one pushup and as you come up, shift your weight on the left side of the body, twist to the side while bringing the right arm up towards the ceiling in a side plank.","Lower the arm back to the floor for another pushup and then twist to the other side.","Repeat the series, alternating each side, for 10 or more reps."],"category":"strength","images":["Push_Up_to_Side_Plank/0.jpg","Push_Up_to_Side_Plank/1.jpg"],"id":"Push_Up_to_Side_Plank"}'),
('free-exercise-db', 'Pushups', 'push-up', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Pushups.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Pushups","force":"push","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length.","Next, lower yourself downward until your chest almost touches the floor as you inhale.","Now breathe out and press your upper body back up to the starting position while squeezing your chest.","After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed."],"category":"strength","images":["Pushups/0.jpg","Pushups/1.jpg"],"id":"Pushups"}'),
('free-exercise-db', 'Pushups_Close_and_Wide_Hand_Positions', 'push-up-close-and-wide-hand-positions', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Pushups_Close_and_Wide_Hand_Positions.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Pushups (Close and Wide Hand Positions)","force":"push","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["Lie on the floor face down and body straight with your toes on the floor and the hands wider than shoulder width for a wide hand position and closer than shoulder width for a close hand position. Make sure you are holding your torso up at arms length.","Lower yourself until your chest almost touches the floor as you inhale.","Using your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step.","After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions."],"category":"strength","images":["Pushups_Close_and_Wide_Hand_Positions/0.jpg","Pushups_Close_and_Wide_Hand_Positions/1.jpg"],"id":"Pushups_Close_and_Wide_Hand_Positions"}'),
('free-exercise-db', 'Pyramid', 'exercise-ball-pyramid', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Pyramid.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Pyramid","force":"static","level":"beginner","mechanic":null,"equipment":"exercise ball","primaryMuscles":["lower back"],"secondaryMuscles":["shoulders"],"instructions":["Start off by rolling your torso forward onto the ball so your hips rest on top of the ball and become the highest point of your body.","Rest your hands and feet on the floor. Your arms and legs can be slightly bent or straight, depending on the size of the ball, your flexibility, and the length of your limbs. This also helps develop stabilizing strength in your torso and shoulders."],"category":"stretching","images":["Pyramid/0.jpg","Pyramid/1.jpg"],"id":"Pyramid"}'),
('free-exercise-db', 'Quad_Stretch', 'quad-stretch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Quad_Stretch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Quad Stretch","force":"static","level":"intermediate","mechanic":null,"equipment":"other","primaryMuscles":["quadriceps"],"secondaryMuscles":[],"instructions":["Lay on your side. Loop a belt, rope, or band around your top foot. Flex the knee and extend your hip, attempting to touch your glutes with your foot, and holding the belt with your hands. This will be your starting position.","With the belt being held over the shoulder or overhead, gently pull to increase the stretch in the quadriceps. Hold for 10-20 seconds, and then switch sides."],"category":"stretching","images":["Quad_Stretch/0.jpg","Quad_Stretch/1.jpg"],"id":"Quad_Stretch"}'),
('free-exercise-db', 'Quadriceps-SMR', 'foam-roller-quadriceps-smr', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Quadriceps-SMR.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Quadriceps-SMR","force":"static","level":"intermediate","mechanic":"isolation","equipment":"foam roll","primaryMuscles":["quadriceps"],"secondaryMuscles":[],"instructions":["Lay facedown on the floor with your weight supported by your hands or forearms. Place a foam roll underneath one leg on the quadriceps, and keep the foot off of the ground. Make sure to relax the leg as much as possible. This will be your starting position.","Shifting as much weight onto the leg to be stretched as is tolerable, roll over the foam from above the knee to below the hip, holding points of tension for 10-30 seconds. Switch sides."],"category":"stretching","images":["Quadriceps-SMR/0.jpg","Quadriceps-SMR/1.jpg"],"id":"Quadriceps-SMR"}'),
('free-exercise-db', 'Quick_Leap', 'quick-leap', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Quick_Leap.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Quick Leap","force":"push","level":"beginner","mechanic":"compound","equipment":"other","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","hamstrings"],"instructions":["You will need a box for this exerise.","Begin facing the box standing 1-2 feet from its edge.","By utilizing your hips, hop onto the box, landing on both legs. Ensure that you land with your legs bent and your feet flat.","Immediately upon landing, fully extend through the entire body and swing your arms overhead to explode off of the box. Use your legs to absorb the impact of landing."],"category":"plyometrics","images":["Quick_Leap/0.jpg","Quick_Leap/1.jpg"],"id":"Quick_Leap"}'),
('free-exercise-db', 'Rack_Delivery', 'barbell-rack-delivery', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Rack_Delivery.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Rack Delivery","force":"pull","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["shoulders"],"secondaryMuscles":["forearms","traps"],"instructions":["This drill teaches the delivery of the barbell to the rack position on the shoulders. Begin holding a bar in the scarecrow position, with the upper arms parallel to the floor, and the forearms hanging down. Use a hook grip, with your fingers wrapped over your thumbs.","Begin by rotating the elbows around the bar, delivering the bar to the shoulders. As your elbows come forward, relax your grip. The shoulders should be protracted, providing a shelf for the bar, which should lightly contact the throat.","It is important that the bar stay close to the body at all times, as with a heavier load any distance will result in an unwanted collision. As the movement becomes smoother, speed and load can be increased before progressing further."],"category":"olympic weightlifting","images":["Rack_Delivery/0.jpg","Rack_Delivery/1.jpg"],"id":"Rack_Delivery"}'),
('free-exercise-db', 'Rack_Pull_with_Bands', 'band-rack-pull', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Rack_Pull_with_Bands.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Rack Pull with Bands","force":"pull","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["lower back"],"secondaryMuscles":["forearms","glutes","hamstrings","quadriceps","traps"],"instructions":["Set up in a power rack with the bar on the pins. The pins should be set to the desired point; just below the knees, just above, or in the mid thigh position. Attach bands to the base of the rack, or secure them with dumbbells. Attach the other end to the bar. You may need to choke the bands to provide tension.","Position yourself against the bar in proper deadlifting position. Your feet should be under your hips, your grip shoulder width, back arched, and hips back to engage the hamstrings. Since the weight is typically heavy, you may use a mixed grip, a hook grip, or use straps to aid in holding the weight.","With your head looking forward, extend through the hips and knees, pulling the weight up and back until lockout. Be sure to pull your shoulders back as you complete the movement. Return the weight to the pins and repeat."],"category":"powerlifting","images":["Rack_Pull_with_Bands/0.jpg","Rack_Pull_with_Bands/1.jpg"],"id":"Rack_Pull_with_Bands"}'),
('free-exercise-db', 'Rack_Pulls', 'barbell-rack-pull', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Rack_Pulls.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Rack Pulls","force":"pull","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["lower back"],"secondaryMuscles":["forearms","glutes","hamstrings","traps"],"instructions":["Set up in a power rack with the bar on the pins. The pins should be set to the desired point; just below the knees, just above, or in the mid thigh position. Position yourself against the bar in proper deadlifting position. Your feet should be under your hips, your grip shoulder width, back arched, and hips back to engage the hamstrings. Since the weight is typically heavy, you may use a mixed grip, a hook grip, or use straps to aid in holding the weight.","With your head looking forward, extend through the hips and knees, pulling the weight up and back until lockout. Be sure to pull your shoulders back as you complete the movement.","Return the weight to the pins and repeat."],"category":"powerlifting","images":["Rack_Pulls/0.jpg","Rack_Pulls/1.jpg"],"id":"Rack_Pulls"}'),
('free-exercise-db', 'Rear_Leg_Raises', 'rear-leg-raise', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Rear_Leg_Raises.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Rear Leg Raises","force":"push","level":"beginner","mechanic":null,"equipment":"body only","primaryMuscles":["quadriceps"],"secondaryMuscles":[],"instructions":["Place yourself on your hands knees on an exercise mat. Your head should be looking forward and the bend of the knees should create a 90-degree angle between the hamstrings and the calves. This will be your starting position.","Extend one leg up and behind you. The knee and hip should both extend. Repeat for 5-10 repetitions, and then switch sides."],"category":"stretching","images":["Rear_Leg_Raises/0.jpg","Rear_Leg_Raises/1.jpg"],"id":"Rear_Leg_Raises"}'),
('free-exercise-db', 'Recumbent_Bike', 'machine-recumbent-bike', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Recumbent_Bike.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Recumbent Bike","force":null,"level":"beginner","mechanic":null,"equipment":"machine","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings"],"instructions":["To begin, seat yourself on the bike and adjust the seat to your height.","Select the desired option from the menu. You may have to start pedaling to turn it on. You can use the manual setting, or you can select a program to use. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. The level of resistance can be changed throughout the workout. The handles can be used to monitor your heart rate to help you stay at an appropriate intensity.","Recumbent bikes offer convenience, cardiovascular benefits, and have less impact than other activities. A 150 lb person will burn about 230 calories cycling at a moderate rate for 30 minutes, compared to 450 calories or more running."],"category":"cardio","images":["Recumbent_Bike/0.jpg","Recumbent_Bike/1.jpg"],"id":"Recumbent_Bike"}'),
('free-exercise-db', 'Return_Push_from_Stance', 'medicine-ball-return-push-from-stance', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Return_Push_from_Stance.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Return Push from Stance","force":"push","level":"beginner","mechanic":"compound","equipment":"medicine ball","primaryMuscles":["shoulders"],"secondaryMuscles":["chest","triceps"],"instructions":["You will need a partner for this drill.","Begin in an athletic 2 or 3 point stance.","At the signal, move into a position to receive the pass from your partner.","Catch the medicine ball with both hands and immediately throw it back to your partner.","You can modify this drill by running different routes."],"category":"plyometrics","images":["Return_Push_from_Stance/0.jpg","Return_Push_from_Stance/1.jpg"],"id":"Return_Push_from_Stance"}'),
('free-exercise-db', 'Reverse_Band_Bench_Press', 'band-reverse-bench-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Reverse_Band_Bench_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Reverse Band Bench Press","force":"push","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["triceps"],"secondaryMuscles":["chest","forearms","lats","middle back","shoulders"],"instructions":["Position a bench inside a power rack, with the bar set to the correct height. Begin by anchoring bands either to band pegs or to the top of the rack. Ensure that you will be position properly under the bands. Attach the other end to the barbell.","Lie on the bench, tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement. However wide your grip, it should cover the ring on the bar.","Pull the bar out of the rack without protracting your shoulders. Focus on squeezing the bar and trying to pull it apart. Lower the bar to your lower chest or upper stomach. The bar, wrist, and elbow should stay in line at all times.","Pause when the barbell touches your torso, and then drive the bar up with as much force as possible. The elbows should be tucked in until lockout."],"category":"powerlifting","images":["Reverse_Band_Bench_Press/0.jpg","Reverse_Band_Bench_Press/1.jpg"],"id":"Reverse_Band_Bench_Press"}'),
('free-exercise-db', 'Reverse_Band_Box_Squat', 'band-reverse-box-squat', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Reverse_Band_Box_Squat.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Reverse Band Box Squat","force":"push","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["abductors","adductors","calves","forearms","glutes","hamstrings","lower back"],"instructions":["Begin in a power rack with a box at the appropriate height behind you. Set up the bands either on band pegs or attached to the top of the rack, ensuring they will be directly above the bar during the squat. Attach the other end to the bar.","Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wider for more emphasis on the back, glutes, adductors, and hamstrings, or closer together for more quad development. Keep your head facing forward.","With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. Ideally, your shins should be perpendicular to the ground. Pause when you reach the box, and relax the hip flexors. Never bounce off of a box.","Keeping the weight on your heels and pushing your feet and knees out, drive upward off of the box as you lead the movement with your head. Continue upward, maintaining tightness head to toe. Use care to return the barbell to the rack."],"category":"powerlifting","images":["Reverse_Band_Box_Squat/0.jpg","Reverse_Band_Box_Squat/1.jpg"],"id":"Reverse_Band_Box_Squat"}'),
('free-exercise-db', 'Reverse_Band_Deadlift', 'band-reverse-deadlift', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Reverse_Band_Deadlift.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Reverse Band Deadlift","force":"pull","level":"expert","mechanic":"compound","equipment":"barbell","primaryMuscles":["lower back"],"secondaryMuscles":["abductors","adductors","calves","glutes","hamstrings","quadriceps"],"instructions":["Set the bar up in a power rack. Attach bands to the top of the rack, using either bands pegs or the frame itself. Attach the other end of the bands to the bar.","Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an overhand grip or an over/under grip on heavier sets.","With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward.","After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.","Lower the bar by bending at the hips and guiding it to the floor."],"category":"powerlifting","images":["Reverse_Band_Deadlift/0.jpg","Reverse_Band_Deadlift/1.jpg"],"id":"Reverse_Band_Deadlift"}'),
('free-exercise-db', 'Reverse_Band_Power_Squat', 'band-reverse-power-squat', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Reverse_Band_Power_Squat.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Reverse Band Power Squat","force":"push","level":"expert","mechanic":"compound","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["adductors","calves","glutes","hamstrings","lower back"],"instructions":["Begin in a power rack with the pins and bar set at the appropriate height. After loading the bar, attach bands to the top of the rack, using either pegs or the frame itself. Attach the other end of the bands to the bar.","Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wide for more emphasis on the back, glutes, adductors, and hamstrings.","Keep your head facing forward. With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips as much as possible. Ideally, your shins should be perpendicular to the ground. Lower bar position necessitates a greater torso lean to keep the bar over the heels. Continue until you break parallel, which is defined as the crease of the hip being in line with the top of the knee.","Keeping the weight on your heels and pushing your feet and knees out, drive upward as you lead the movement with your head. Continue upward, maintaining tightness head to toe, until you have returned to the starting position."],"category":"powerlifting","images":["Reverse_Band_Power_Squat/0.jpg","Reverse_Band_Power_Squat/1.jpg"],"id":"Reverse_Band_Power_Squat"}'),
('free-exercise-db', 'Reverse_Band_Sumo_Deadlift', 'band-reverse-sumo-deadlift', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Reverse_Band_Sumo_Deadlift.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Reverse Band Sumo Deadlift","force":"pull","level":"expert","mechanic":"compound","equipment":"barbell","primaryMuscles":["hamstrings"],"secondaryMuscles":["abductors","adductors","calves","forearms","glutes","lower back","quadriceps","traps"],"instructions":["Begin with a bar loaded on the floor inside of a power rack. Attach bands to the top of the rack, using either pegs or the frame itself. Attach the other end to the barbell.","Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the shoulders, which in effect lengthens your arms.","Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees.","As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.","Return the weight to the ground by bending at the hips and controlling the weight on the way down."],"category":"powerlifting","images":["Reverse_Band_Sumo_Deadlift/0.jpg","Reverse_Band_Sumo_Deadlift/1.jpg"],"id":"Reverse_Band_Sumo_Deadlift"}'),
('free-exercise-db', 'Reverse_Barbell_Curl', 'barbell-reverse-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Reverse_Barbell_Curl.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Reverse Barbell Curl","force":"pull","level":"beginner","mechanic":"isolation","equipment":"barbell","primaryMuscles":["biceps"],"secondaryMuscles":["forearms"],"instructions":["Stand up with your torso upright while holding a barbell at shoulder width with the elbows close to the torso. The palm of your hands should be facing down (pronated grip). This will be your starting position.","While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second as you squeeze the muscle.","Slowly begin to bring the bar back to starting position as your breathe in.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Reverse_Barbell_Curl/0.jpg","Reverse_Barbell_Curl/1.jpg"],"id":"Reverse_Barbell_Curl"}'),
('free-exercise-db', 'Reverse_Barbell_Preacher_Curls', 'barbell-reverse-preacher-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Reverse_Barbell_Preacher_Curls.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Reverse Barbell Preacher Curls","force":"pull","level":"intermediate","mechanic":"isolation","equipment":"e-z curl bar","primaryMuscles":["biceps"],"secondaryMuscles":["forearms"],"instructions":["Grab an EZ-bar using a shoulder width and palms down (pronated) grip.","Now place the upper part of both arms on top of the preacher bench and have your arms extended. This will be your starting position.","As you exhale, use the biceps to curl the weight up until your biceps are fully contracted and the barbell is at shoulder height. Squeeze the biceps hard for a second at the contracted position.","As you breathe in, slowly lower the barbell until your upper arms are extended and the biceps is fully stretched.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Reverse_Barbell_Preacher_Curls/0.jpg","Reverse_Barbell_Preacher_Curls/1.jpg"],"id":"Reverse_Barbell_Preacher_Curls"}'),
('free-exercise-db', 'Reverse_Cable_Curl', 'cable-reverse-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Reverse_Cable_Curl.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Reverse Cable Curl","force":"pull","level":"beginner","mechanic":"isolation","equipment":"cable","primaryMuscles":["biceps"],"secondaryMuscles":["forearms"],"instructions":["Stand up with your torso upright while holding a bar attachment that is attached to a low pulley using a pronated (palms down) and shoulder width grip. Make sure also that you keep the elbows close to the torso. This will be your starting position.","While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second as you squeeze the muscle.","Slowly begin to bring the bar back to starting position as your breathe in.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Reverse_Cable_Curl/0.jpg","Reverse_Cable_Curl/1.jpg"],"id":"Reverse_Cable_Curl"}'),
('free-exercise-db', 'Reverse_Crunch', 'reverse-crunch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Reverse_Crunch.json', 'Unlicense', NULL, 'exact', 100.0, '{"name":"Reverse Crunch","force":"pull","level":"beginner","mechanic":"isolation","equipment":"body only","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Lie down on the floor with your legs fully extended and arms to the side of your torso with the palms on the floor. Your arms should be stationary for the entire exercise.","Move your legs up so that your thighs are perpendicular to the floor and feet are together and parallel to the floor. This is the starting position.","While inhaling, move your legs towards the torso as you roll your pelvis backwards and you raise your hips off the floor. At the end of this movement your knees will be touching your chest.","Hold the contraction for a second and move your legs back to the starting position while exhaling.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Reverse_Crunch/0.jpg","Reverse_Crunch/1.jpg"],"id":"Reverse_Crunch"}'),
('free-exercise-db', 'Reverse_Flyes', 'dumbbell-reverse-fly', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Reverse_Flyes.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Reverse Flyes","force":"pull","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":[],"instructions":["To begin, lie down on an incline bench with the chest and stomach pressing against the incline. Have the dumbbells in each hand with the palms facing each other (neutral grip).","Extend the arms in front of you so that they are perpendicular to the angle of the bench. The legs should be stationary while applying pressure with the ball of your toes. This is the starting position.","Maintaining the slight bend of the elbows, move the weights out and away from each other (to the side) in an arc motion while exhaling. Tip: Try to squeeze your shoulder blades together to get the best results from this exercise.","The arms should be elevated until they are parallel to the floor.","Feel the contraction and slowly lower the weights back down to the starting position while inhaling.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Reverse_Flyes/0.jpg","Reverse_Flyes/1.jpg"],"id":"Reverse_Flyes"}'),
('free-exercise-db', 'Reverse_Flyes_With_External_Rotation', 'dumbbell-reverse-flyes-external-rotation', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Reverse_Flyes_With_External_Rotation.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Reverse Flyes With External Rotation","force":"pull","level":"intermediate","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":[],"instructions":["To begin, lie down on an incline bench set at a 30-degree angle with the chest and stomach pressing against the incline.","Have the dumbbells in each hand with the palms facing down to the floor. Your arms should be in front of you so that they are perpendicular to the angle of the bench. Tip: Your elbows should have a slight bend. The legs should be stationary while applying pressure with the ball of your toes (your heels should not be touching the floor). This is the starting position.","Maintaining the slight bend of the elbows, move the weights out and away from each other in an arc motion while exhaling.","As you lift the weight, your wrist should externally rotate by 90-degrees so that you go from a palms down (pronated) grip to a palms facing each other (neutral) grip. Tip: Try to squeeze your shoulder blades together to get the best results from this exercise.","The arms should be elevated until they are level with the head.","Feel the contraction and slowly lower the weights back down to the starting position while inhaling.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Reverse_Flyes_With_External_Rotation/0.jpg","Reverse_Flyes_With_External_Rotation/1.jpg"],"id":"Reverse_Flyes_With_External_Rotation"}'),
('free-exercise-db', 'Reverse_Grip_Bent-Over_Rows', 'barbell-reverse-grip-bent-over-row', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Reverse_Grip_Bent-Over_Rows.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Reverse Grip Bent-Over Rows","force":"pull","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["middle back"],"secondaryMuscles":["biceps","lats","shoulders"],"instructions":["Stand erect while holding a barbell with a supinated grip (palms facing up).","Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.","While keeping the torso stationary, lift the barbell as you breathe out, keeping the elbows close to the body and not doing any force with the forearm other than holding the weights. On the top contracted position, squeeze the back muscles and hold for a second.","Slowly lower the weight again to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Reverse_Grip_Bent-Over_Rows/0.jpg","Reverse_Grip_Bent-Over_Rows/1.jpg"],"id":"Reverse_Grip_Bent-Over_Rows"}'),
('free-exercise-db', 'Reverse_Grip_Triceps_Pushdown', 'cable-reverse-grip-triceps-pushdown', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Reverse_Grip_Triceps_Pushdown.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Reverse Grip Triceps Pushdown","force":"push","level":"beginner","mechanic":"isolation","equipment":"cable","primaryMuscles":["triceps"],"secondaryMuscles":[],"instructions":["Start by setting a bar attachment (straight or e-z) on a high pulley machine.","Facing the bar attachment, grab it with the palms facing up (supinated grip) at shoulder width. Lower the bar by using your lats until your arms are fully extended by your sides. Tip: Elbows should be in by your sides and your feet should be shoulder width apart from each other. This is the starting position.","Slowly elevate the bar attachment up as you inhale so it is aligned with your chest. Only the forearms should move and the elbows/upper arms should be stationary by your side at all times.","Then begin to lower the cable bar back down to the original staring position while exhaling and contracting the triceps hard.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Reverse_Grip_Triceps_Pushdown/0.jpg","Reverse_Grip_Triceps_Pushdown/1.jpg"],"id":"Reverse_Grip_Triceps_Pushdown"}'),
('free-exercise-db', 'Reverse_Hyperextension', 'machine-reverse-hyperextension', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Reverse_Hyperextension.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Reverse Hyperextension","force":"pull","level":"intermediate","mechanic":null,"equipment":"machine","primaryMuscles":["hamstrings"],"secondaryMuscles":["calves","glutes"],"instructions":["Place your feet between the pads after loading an appropriate weight. Lay on the top pad, allowing your hips to hang off the back, while grasping the handles to hold your position.","To begin the movement, flex the hips, pulling the legs forward.","Reverse the motion by extending the hips, kicking the leg back. It is very important not to over-extend the hip on this movement, stopping short of your full range of motion.","Return by again flexing the hip, pulling the carriage forward as far as you can.","Repeat for the desired number of repetitions."],"category":"strength","images":["Reverse_Hyperextension/0.jpg","Reverse_Hyperextension/1.jpg"],"id":"Reverse_Hyperextension"}'),
('free-exercise-db', 'Reverse_Machine_Flyes', 'machine-reverse-fly', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Reverse_Machine_Flyes.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Reverse Machine Flyes","force":"pull","level":"beginner","mechanic":"isolation","equipment":"machine","primaryMuscles":["shoulders"],"secondaryMuscles":[],"instructions":["Adjust the handles so that they are fully to the rear. Make an appropriate weight selection and adjust the seat height so the handles are at shoulder level. Grasp the handles with your hands facing inwards. This will be your starting position.","In a semicircular motion, pull your hands out to your side and back, contracting your rear delts.","Keep your arms slightly bent throughout the movement, with all of the motion occurring at the shoulder joint.","Pause at the rear of the movement, and slowly return the weight to the starting position."],"category":"strength","images":["Reverse_Machine_Flyes/0.jpg","Reverse_Machine_Flyes/1.jpg"],"id":"Reverse_Machine_Flyes"}'),
('free-exercise-db', 'Reverse_Plate_Curls', 'plate-reverse-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Reverse_Plate_Curls.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Reverse Plate Curls","force":"pull","level":"beginner","mechanic":"isolation","equipment":"other","primaryMuscles":["biceps"],"secondaryMuscles":["forearms"],"instructions":["Start by standing straight with a weighted plate held by both hands and arms fully extended. Use a pronated grip (palms facing down) and make sure your fingers grab the rough side of the plate while your thumb grabs the smooth side. Note: For the best results, grab the weighted plate at an 11:00 and 1:00 o''clock position.","Your feet should be shoulder width apart from each other and the weighted plate should be near the groin area. This is the starting position.","Slowly lift the plate up while keeping the elbows in and the upper arms stationary until your biceps and forearms touch while exhaling. The plate should be evenly aligned with your torso at this point.","Feel the contraction for a second and begin to lower the weight back down to the starting position while inhaling","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Reverse_Plate_Curls/0.jpg","Reverse_Plate_Curls/1.jpg"],"id":"Reverse_Plate_Curls"}'),
('free-exercise-db', 'Reverse_Triceps_Bench_Press', 'barbell-reverse-triceps-bench-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Reverse_Triceps_Bench_Press.json', 'Unlicense', NULL, 'new', 87.5, '{"name":"Reverse Triceps Bench Press","force":"push","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["triceps"],"secondaryMuscles":["chest","shoulders"],"instructions":["Lie back on a flat bench. Using a close, supinated grip (around shoulder width), lift the bar from the rack and hold it straight over you with your arms locked extended in front of you and perpendicular to the floor. This will be your starting position.","As you breathe in, come down slowly until you feel the bar on your middle chest. Tip: Make sure that as opposed to a regular bench press, you keep the elbows close to the torso at all times in order to maximize triceps involvement.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your triceps muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the bar back in the rack."],"category":"strength","images":["Reverse_Triceps_Bench_Press/0.jpg","Reverse_Triceps_Bench_Press/1.jpg"],"id":"Reverse_Triceps_Bench_Press"}'),
('free-exercise-db', 'Rhomboids-SMR', 'foam-roller-rhomboids-smr', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Rhomboids-SMR.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Rhomboids-SMR","force":"static","level":"intermediate","mechanic":null,"equipment":"foam roll","primaryMuscles":["middle back"],"secondaryMuscles":["traps"],"instructions":["Lay down with your back on the floor. Place a foam roll underneath your upper back, and cross your arms in front of you, protracting your shoulders. This will be your starting position.","Raise your hips off of the ground, placing your weight onto the foam roll. Shift your weight to one side at a time, rolling over your middle and upper back. Pause at points of tension for 10-30 seconds."],"category":"stretching","images":["Rhomboids-SMR/0.jpg","Rhomboids-SMR/1.jpg"],"id":"Rhomboids-SMR"}');
INSERT INTO source_records (source_id, source_record_id, exercise_id, source_url, license, author, match_method, match_score, raw_json) VALUES
('free-exercise-db', 'Rickshaw_Carry', 'rickshaw-carry', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Rickshaw_Carry.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Rickshaw Carry","force":null,"level":"intermediate","mechanic":"compound","equipment":"other","primaryMuscles":["forearms"],"secondaryMuscles":["abdominals","calves","glutes","hamstrings","lower back","quadriceps","traps"],"instructions":["Position the frame at the starting point, and load with the appropriate weight. Standing in the center of the frame, begin by gripping the handles and driving through your heels to lift the frame. Ensure your chest and head are up and your back is straight.","Immediately begin walking briskly with quick, controlled steps. Keep your chest up and head forward, and make sure you continue breathing. Bring the frame to the ground after you have reached the end point."],"category":"strongman","images":["Rickshaw_Carry/0.jpg","Rickshaw_Carry/1.jpg"],"id":"Rickshaw_Carry"}'),
('free-exercise-db', 'Rickshaw_Deadlift', 'rickshaw-deadlift', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Rickshaw_Deadlift.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Rickshaw Deadlift","force":"pull","level":"intermediate","mechanic":"compound","equipment":"other","primaryMuscles":["quadriceps"],"secondaryMuscles":["forearms","glutes","hamstrings","lower back","traps"],"instructions":["Load the frame with the desired weight. Center yourself between the handles. You feet should be about hip width apart. Bend at the hips to grip the handles, allowing your shoulder blades to protract.","With your feet and your grip set, take a big breath and then lower your hips and flex the knees. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. As the weight comes up, pull your shoulder blades together as you drive your hips forward.","Lower the weight by bending at the hips and guiding it to the ground."],"category":"strongman","images":["Rickshaw_Deadlift/0.jpg","Rickshaw_Deadlift/1.jpg"],"id":"Rickshaw_Deadlift"}'),
('free-exercise-db', 'Ring_Dips', 'ring-dip-2', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Ring_Dips.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Ring Dips","force":"push","level":"intermediate","mechanic":"compound","equipment":"other","primaryMuscles":["triceps"],"secondaryMuscles":["chest","shoulders"],"instructions":["Grip a ring in each hand, and then take a small jump to help you get into the starting position with your arms locked out.","Begin by flexing the elbow, lowering your body until your arms break 90 degrees. Avoid swinging, and maintain good posture throughout the descent.","Reverse the motion by extending the elbow, pushing yourself back up into the starting position.","Repeat for the desired number of repetitions."],"category":"strength","images":["Ring_Dips/0.jpg","Ring_Dips/1.jpg"],"id":"Ring_Dips"}'),
('free-exercise-db', 'Rocket_Jump', 'rocket-jump', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Rocket_Jump.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Rocket Jump","force":"push","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","hamstrings"],"instructions":["Begin in a relaxed stance with your feet shoulder width apart and hold your arms close to the body.","To initiate the move, squat down halfway and explode back up as high as possible.","Fully extend your entire body, reaching overhead as far as possible. As you land, absorb your impact through the legs."],"category":"plyometrics","images":["Rocket_Jump/0.jpg","Rocket_Jump/1.jpg"],"id":"Rocket_Jump"}'),
('free-exercise-db', 'Rocking_Standing_Calf_Raise', 'barbell-rocking-standing-calf-raise', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Rocking_Standing_Calf_Raise.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Rocking Standing Calf Raise","force":"push","level":"beginner","mechanic":"isolation","equipment":"barbell","primaryMuscles":["calves"],"secondaryMuscles":[],"instructions":["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place it on the back of your shoulders (slightly below the neck).","Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.","Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance. Also maintain a straight back and keep the knees with a slight bend; never locked. This will be your starting position.","Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending (other than the slight initial bend we created during positioning) at any time. Hold the contracted position by a second before you start to go back down.","Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.","Now lift your toes by contracting the tibia muscles in the front of the calves as you breathe out.","Hold for a second and bring them back down as you breathe in.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Rocking_Standing_Calf_Raise/0.jpg","Rocking_Standing_Calf_Raise/1.jpg"],"id":"Rocking_Standing_Calf_Raise"}'),
('free-exercise-db', 'Rocky_Pull-Ups_Pulldowns', 'rocky-pull-up-pulldowns', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Rocky_Pull-Ups_Pulldowns.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Rocky Pull-Ups/Pulldowns","force":"pull","level":"intermediate","mechanic":"compound","equipment":"other","primaryMuscles":["lats"],"secondaryMuscles":["biceps","middle back","shoulders"],"instructions":["Grab the pull-up bar with the palms facing forward using a wide grip.","As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.","Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.","After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.","Now repeat the same movements as described above except this time your torso will remain straight as you go up and the bar will touch the back of the neck instead of the upper chest. Tip: Use the head to lean forward slightly as it will help you properly execute this portion of the exercise.","Once you have lowered yourself back down to the starting position, repeat the exercise for the prescribed amount of repetitions in your program."],"category":"strength","images":["Rocky_Pull-Ups_Pulldowns/0.jpg","Rocky_Pull-Ups_Pulldowns/1.jpg"],"id":"Rocky_Pull-Ups_Pulldowns"}'),
('free-exercise-db', 'Romanian_Deadlift', 'barbell-romanian-deadlift', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Romanian_Deadlift.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Romanian Deadlift","force":"pull","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["hamstrings"],"secondaryMuscles":["calves","glutes","lower back"],"instructions":["Put a barbell in front of you on the ground and grab it using a pronated (palms facing down) grip that a little wider than shoulder width. Tip: Depending on the weight used, you may need wrist wraps to perform the exercise and also a raised platform in order to allow for better range of motion.","Bend the knees slightly and keep the shins vertical, hips back and back straight. This will be your starting position.","Keeping your back and arms completely straight at all times, use your hips to lift the bar as you exhale. Tip: The movement should not be fast but steady and under control.","Once you are standing completely straight up, lower the bar by pushing the hips back, only slightly bending the knees, unlike when squatting. Tip: Take a deep breath at the start of the movement and keep your chest up. Hold your breath as you lower and exhale as you complete the movement.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Romanian_Deadlift/0.jpg","Romanian_Deadlift/1.jpg"],"id":"Romanian_Deadlift"}'),
('free-exercise-db', 'Romanian_Deadlift_from_Deficit', 'barbell-romanian-deadlift-from-deficit', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Romanian_Deadlift_from_Deficit.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Romanian Deadlift from Deficit","force":"pull","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["hamstrings"],"secondaryMuscles":["forearms","glutes","lower back","traps"],"instructions":["Begin standing while holding a bar at arm''s length in front of you. You can stand on a raised platform to increase the range of motion.","Begin by flexing the knees slightly, and then flex at the hip, moving your butt back as far as possible, lowering the torso as far as flexibility allows. The back should remain in absolute extension at all times, and the bar should remain in contact with the legs. If done properly, there should be heavy tension felt in the hamstrings.","Reverse the motion to return to the starting position."],"category":"olympic weightlifting","images":["Romanian_Deadlift_from_Deficit/0.jpg","Romanian_Deadlift_from_Deficit/1.jpg"],"id":"Romanian_Deadlift_from_Deficit"}'),
('free-exercise-db', 'Rope_Climb', 'rope-climb', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Rope_Climb.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Rope Climb","force":"pull","level":"intermediate","mechanic":"compound","equipment":"other","primaryMuscles":["lats"],"secondaryMuscles":["biceps","forearms","middle back","shoulders"],"instructions":["Grab the rope with both hands above your head. Pull down on the rope as you take a small jump.","Wrap the rope around one leg, using your feet to pinch the rope. Reach up as high as possible with your arms, gripping the rope tightly.","Release the rope from your feet as you pull yourself up with your arms, bringing your knees towards your chest.","Resecure your feet on the rope, and then stand up to take another high hold on the rope. Continue until you reach the top of the rope.","To lower yourself, loosen the grip of your feet on the rope as you slide down using a hand over hand motion."],"category":"strength","images":["Rope_Climb/0.jpg","Rope_Climb/1.jpg"],"id":"Rope_Climb"}'),
('free-exercise-db', 'Rope_Crunch', 'cable-rope-crunch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Rope_Crunch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Rope Crunch","force":"pull","level":"beginner","mechanic":"isolation","equipment":"cable","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Kneel 1-2 feet in front of a cable system with a rope attached.","After selecting an appropriate weight, grasp the rope with both hands reaching overhead. Your torso should be upright in the starting position.","To begin, flex at the spine, attempting to bring your rib cage to your legs as you pull the cable down.","Pause at the bottom of the motion, and then slowly return to the starting position.","These can be done with twists or to the side to hit the obliques."],"category":"strength","images":["Rope_Crunch/0.jpg","Rope_Crunch/1.jpg"],"id":"Rope_Crunch"}'),
('free-exercise-db', 'Rope_Jumping', 'rope-jumping', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Rope_Jumping.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Rope Jumping","force":null,"level":"intermediate","mechanic":null,"equipment":"other","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","hamstrings"],"instructions":["Hold an end of the rope in each hand. Position the rope behind you on the ground. Raise your arms up and turn the rope over your head bringing it down in front of you. When it reaches the ground, jump over it. Find a good turning pace that can be maintained. Different speeds and techniques can be used to introduce variation.","Rope jumping is exciting, challenges your coordination, and requires a lot of energy. A 150 lb person will burn about 350 calories jumping rope for 30 minutes, compared to over 450 calories running."],"category":"cardio","images":["Rope_Jumping/0.jpg","Rope_Jumping/1.jpg"],"id":"Rope_Jumping"}'),
('free-exercise-db', 'Rope_Straight-Arm_Pulldown', 'cable-rope-straight-arm-pulldown', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Rope_Straight-Arm_Pulldown.json', 'Unlicense', NULL, 'new', 89.4, '{"name":"Rope Straight-Arm Pulldown","force":"pull","level":"beginner","mechanic":"isolation","equipment":"cable","primaryMuscles":["lats"],"secondaryMuscles":[],"instructions":["Attach a rope to a high pulley and make your weight selection. Stand a couple feet back from the pulley with your feet staggered and take the rope with both hands. Lean forward from the hip, keeping your back straight, with your arms extended up in front of you. This will be your starting position.","Keeping your arms straight, extend the shoulder to pull the rope down to your thighs.","Pause at the bottom of the motion, squeezing your lats.","Return to the starting position without allowing the weight to fully rest on the stack."],"category":"strength","images":["Rope_Straight-Arm_Pulldown/0.jpg","Rope_Straight-Arm_Pulldown/1.jpg"],"id":"Rope_Straight-Arm_Pulldown"}'),
('free-exercise-db', 'Round_The_World_Shoulder_Stretch', 'round-world-shoulder-stretch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Round_The_World_Shoulder_Stretch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Round The World Shoulder Stretch","force":"static","level":"beginner","mechanic":null,"equipment":"other","primaryMuscles":["shoulders"],"secondaryMuscles":["biceps","chest"],"instructions":["Stand up straight with your legs together, holding a bodybar or broomstick.","Hold the pole behind your hips with a wider than shoulder width grip. Your palms should be down and your thumbs facing out.","Slowly lift your arms up behind your head. Don''t force it if it gets hard to lift further."],"category":"stretching","images":["Round_The_World_Shoulder_Stretch/0.jpg","Round_The_World_Shoulder_Stretch/1.jpg"],"id":"Round_The_World_Shoulder_Stretch"}'),
('free-exercise-db', 'Rowing_Stationary', 'machine-rowing-stationary', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Rowing_Stationary.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Rowing, Stationary","force":null,"level":"intermediate","mechanic":null,"equipment":"machine","primaryMuscles":["quadriceps"],"secondaryMuscles":["biceps","calves","glutes","hamstrings","lower back","middle back"],"instructions":["To begin, seat yourself on the rower. Make sure that your heels are resting comfortably against the base of the foot pedals and that the straps are secured. Select the program that you wish to use, if applicable. Sit up straight and bend forward at the hips.","There are three phases of movement when using a rower. The first phase is when you come forward on the rower. Your knees are bent and against your chest. Your upper body is leaning slightly forward while still maintaining good posture. Next, push against the foot pedals and extend your legs while bringing your hands to your upper abdominal area, squeezing your shoulders back as you do so. To avoid straining your back, use primarily your leg and hip muscles.","The recovery phase simply involves straightening your arms, bending the knees, and bringing your body forward again as you transition back into the first phase."],"category":"cardio","images":["Rowing_Stationary/0.jpg","Rowing_Stationary/1.jpg"],"id":"Rowing_Stationary"}'),
('free-exercise-db', 'Runners_Stretch', 'runners-stretch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Runners_Stretch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Runner''s Stretch","force":"static","level":"beginner","mechanic":null,"equipment":null,"primaryMuscles":["hamstrings"],"secondaryMuscles":["calves"],"instructions":["It''s easiest to get into this stretch if you start standing up, put one leg behind you, and slowly lower your torso down to the floor.","Keep the front heel on the floor (if it lifts up, scoot your other leg further back).","Place your hands on either side of your front leg. To get more out of this stretch, push your butt up toward the ceiling, and then gradually lower it back toward the floor. You''ll Stretch the hip flexor of the back leg and the hamstring and buttocks of the front."],"category":"stretching","images":["Runners_Stretch/0.jpg","Runners_Stretch/1.jpg"],"id":"Runners_Stretch"}'),
('free-exercise-db', 'Running_Treadmill', 'machine-running-treadmill', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Running_Treadmill.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Running, Treadmill","force":null,"level":"beginner","mechanic":null,"equipment":"machine","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings"],"instructions":["To begin, step onto the treadmill and select the desired option from the menu. Most treadmills have a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout.","Treadmills offer convenience, cardiovascular benefits, and usually have less impact than running outside. A 150 lb person will burn over 450 calories running 8 miles per hour for 30 minutes. Maintain proper posture as you run, and only hold onto the handles when necessary, such as when dismounting or checking your heart rate."],"category":"cardio","images":["Running_Treadmill/0.jpg","Running_Treadmill/1.jpg"],"id":"Running_Treadmill"}'),
('free-exercise-db', 'Russian_Twist', 'russian-twist-2', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Russian_Twist.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Russian Twist","force":"pull","level":"intermediate","mechanic":"compound","equipment":"body only","primaryMuscles":["abdominals"],"secondaryMuscles":["lower back"],"instructions":["Lie down on the floor placing your feet either under something that will not move or by having a partner hold them. Your legs should be bent at the knees.","Elevate your upper body so that it creates an imaginary V-shape with your thighs. Your arms should be fully extended in front of you perpendicular to your torso and with the hands clasped. This is the starting position.","Twist your torso to the right side until your arms are parallel with the floor while breathing out.","Hold the contraction for a second and move back to the starting position while breathing out. Now move to the opposite side performing the same techniques you applied to the right side.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Russian_Twist/0.jpg","Russian_Twist/1.jpg"],"id":"Russian_Twist"}'),
('free-exercise-db', 'Sandbag_Load', 'sandbag-load', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Sandbag_Load.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Sandbag Load","force":"pull","level":"beginner","mechanic":"compound","equipment":"other","primaryMuscles":["quadriceps"],"secondaryMuscles":["abdominals","biceps","calves","forearms","glutes","hamstrings","lower back","middle back","shoulders","traps"],"instructions":["To load sandbags or other objects, begin with the implements placed a distance from the loading platform, typically 50 feet.","Begin by lifting the sandbag. Sandbags are extremely awkward, and the manner of lifting them can vary depending on the particular sandbag used. Reach as far around it as possible, extending through the hips and knees to pull it up high. Shouldering is usually not allowed.","Move as quickly as possible to the platform, and load it, extending through your hips, knees, and ankles to get it as high as possible. Place it onto the platform, ensuring it doesn''t fall off.","Return to the starting position to retrieve the next sandbag, and repeat until the event is completed."],"category":"strongman","images":["Sandbag_Load/0.jpg","Sandbag_Load/1.jpg"],"id":"Sandbag_Load"}'),
('free-exercise-db', 'Scapular_Pull-Up', 'scapular-pull-up', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Scapular_Pull-Up.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Scapular Pull-Up","force":"pull","level":"beginner","mechanic":"isolation","equipment":null,"primaryMuscles":["traps"],"secondaryMuscles":["lats","middle back"],"instructions":["Take a pronated grip on a pull-up bar.","From a hanging position, raise yourself a few inches without using your arms. Do this by depressing your shoulder girdle in a reverse shrugging motion.","Pause at the completion of the movement, and then slowly return to the starting position before performing more repetitions."],"category":"strength","images":["Scapular_Pull-Up/0.jpg","Scapular_Pull-Up/1.jpg"],"id":"Scapular_Pull-Up"}'),
('free-exercise-db', 'Scissor_Kick', 'scissor-kick', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Scissor_Kick.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Scissor Kick","force":"pull","level":"beginner","mechanic":"isolation","equipment":"body only","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["To begin, lie down with your back pressed against the floor or on an exercise mat (optional). Your arms should be fully extended to the sides with your palms facing down. Note: The arms should be stationary the entire time.","With a slight bend at the knees, lift your legs up so that your heels are about 6 inches off the ground. This is the starting position.","Now lift your left leg up to about a 45 degree angle while your right leg is lowered until the heel is about 2-3 inches from the ground.","Switch movements by raising your right leg up and lowering your left leg. Remember to breathe while performing this exercise.","Repeat for the recommended amount of repetitions."],"category":"stretching","images":["Scissor_Kick/0.jpg","Scissor_Kick/1.jpg"],"id":"Scissor_Kick"}'),
('free-exercise-db', 'Scissors_Jump', 'scissors-jump', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Scissors_Jump.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Scissors Jump","force":"push","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["quadriceps"],"secondaryMuscles":["glutes","hamstrings"],"instructions":["Assume a lunge stance position with one foot forward with the knee bent, and the rear knee nearly touching the ground.","Ensure that the front knee is over the midline of the foot. Extending through both legs, jump as high as possible, swinging your arms to gain lift.","As you jump as high as you can, switch the position of your legs, moving your front leg to the back and the rear leg to the front.","As you land, absorb the impact through the legs by adopting the lunge position, and repeat."],"category":"plyometrics","images":["Scissors_Jump/0.jpg","Scissors_Jump/1.jpg"],"id":"Scissors_Jump"}'),
('free-exercise-db', 'Seated_Band_Hamstring_Curl', 'band-seated-hamstring-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Seated_Band_Hamstring_Curl.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Seated Band Hamstring Curl","force":"pull","level":"beginner","mechanic":"isolation","equipment":"other","primaryMuscles":["hamstrings"],"secondaryMuscles":[],"instructions":["Secure a band close to the ground and place a bench a couple feet away from it.","Seat yourself on the bench and secure the band behind your ankles, beginning with your legs straight. This will be your starting position.","Flex the knees, bringing your feet towards the bench. You may need to lean back slightly to keep your feet from striking the floor.","Pause at the completion of the movement, and then slowly return to the starting position."],"category":"strength","images":["Seated_Band_Hamstring_Curl/0.jpg","Seated_Band_Hamstring_Curl/1.jpg"],"id":"Seated_Band_Hamstring_Curl"}'),
('free-exercise-db', 'Seated_Barbell_Military_Press', 'barbell-seated-shoulder-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Seated_Barbell_Military_Press.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Seated Barbell Military Press","force":"push","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["shoulders"],"secondaryMuscles":["triceps"],"instructions":["Sit on a Military Press Bench with a bar behind your head and either have a spotter give you the bar (better on the rotator cuff this way) or pick it up yourself carefully with a pronated grip (palms facing forward). Tip: Your grip should be wider than shoulder width and it should create a 90-degree angle between the forearm and the upper arm as the barbell goes down.","Once you pick up the barbell with the correct grip length, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.","Lower the bar down to the collarbone slowly as you inhale.","Lift the bar back up to the starting position as you exhale.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Seated_Barbell_Military_Press/0.jpg","Seated_Barbell_Military_Press/1.jpg"],"id":"Seated_Barbell_Military_Press"}'),
('free-exercise-db', 'Seated_Barbell_Twist', 'barbell-seated-twist', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Seated_Barbell_Twist.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Seated Barbell Twist","force":"pull","level":"beginner","mechanic":"isolation","equipment":"barbell","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Start out by sitting at the end of a flat bench with a barbell placed on top of your thighs. Your feet should be shoulder width apart from each other.","Grip the bar with your palms facing down and make sure your hands are wider than shoulder width apart from each other. Begin to lift the barbell up over your head until your arms are fully extended.","Now lower the barbell behind your head until it is resting along the base of your neck. This is the starting position.","While keeping your feet and head stationary, move your waist from side to side so that your oblique muscles feel the contraction. Only move from side to side as far as your waist will allow you to go. Stretching or moving too far can cause an injury to occur. Tip: Use a slow and controlled motion.","Remember to breathe out while twisting your body to the side and in when moving back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Seated_Barbell_Twist/0.jpg","Seated_Barbell_Twist/1.jpg"],"id":"Seated_Barbell_Twist"}'),
('free-exercise-db', 'Seated_Bent-Over_One-Arm_Dumbbell_Triceps_Extension', 'dumbbell-seated-bent-over-one-arm-triceps-extension', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Seated_Bent-Over_One-Arm_Dumbbell_Triceps_Extension.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Seated Bent-Over One-Arm Dumbbell Triceps Extension","force":"push","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["triceps"],"secondaryMuscles":[],"instructions":["Sit down at the end of a flat bench with a dumbbell in one arm using a neutral grip (palms of the hand facing you).","Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Make sure that you keep the head up.","The upper arm with the dumbbell should be close to the torso and aligned with it (lifted up until it is parallel to the floor while the forearms are pointing towards the floor as the hands hold the weights). Tip: There should be a 90-degree angle between the forearms and the upper arm. This is your starting position.","Keeping the upper arm stationary, use the triceps to lift the weight as you exhale until the forearm is parallel to the floor and the whole arm is extended. Like many other arm exercises, only the forearm moves.","After a second contraction at the top, slowly lower the dumbbell back to the starting position as you inhale.","Repeat the movement for the prescribed amount of repetitions.","Switch arms and repeat the exercise."],"category":"strength","images":["Seated_Bent-Over_One-Arm_Dumbbell_Triceps_Extension/0.jpg","Seated_Bent-Over_One-Arm_Dumbbell_Triceps_Extension/1.jpg"],"id":"Seated_Bent-Over_One-Arm_Dumbbell_Triceps_Extension"}'),
('free-exercise-db', 'Seated_Bent-Over_Rear_Delt_Raise', 'dumbbell-seated-bent-over-rear-delt-raise', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Seated_Bent-Over_Rear_Delt_Raise.json', 'Unlicense', NULL, 'new', 85.7, '{"name":"Seated Bent-Over Rear Delt Raise","force":"pull","level":"intermediate","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":[],"instructions":["Place a couple of dumbbells looking forward in front of a flat bench.","Sit on the end of the bench with your legs together and the dumbbells behind your calves.","Bend at the waist while keeping the back straight in order to pick up the dumbbells. The palms of your hands should be facing each other as you pick them. This will be your starting position.","Keeping your torso forward and stationary, and the arms slightly bent at the elbows, lift the dumbbells straight to the side until both arms are parallel to the floor. Exhale as you lift the weights. (Note: avoid swinging the torso or bringing the arms back as opposed to the side.)","After a one second contraction at the top, slowly lower the dumbbells back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Seated_Bent-Over_Rear_Delt_Raise/0.jpg","Seated_Bent-Over_Rear_Delt_Raise/1.jpg"],"id":"Seated_Bent-Over_Rear_Delt_Raise"}'),
('free-exercise-db', 'Seated_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension', 'dumbbell-seated-bent-over-two-arm-triceps-extension', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Seated_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Seated Bent-Over Two-Arm Dumbbell Triceps Extension","force":"push","level":"intermediate","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["triceps"],"secondaryMuscles":[],"instructions":["Sit down at the end of a flat bench with a dumbbell in both arms using a neutral grip (palms of the hand facing you).","Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Make sure that you keep the head up.","The upper arms with the dumbbells should be close to the torso and aligned with it (lifted up until they are parallel to the floor while the forearms are pointing towards the floor as the hands hold the weights). Tip: There should be a 90-degree angle between the forearms and the upper arm. This is your starting position.","Keeping the upper arms stationary, use the triceps to lift the weight as you exhale until the forearms are parallel to the floor and the whole arm is extended. Like many other arm exercises, only the forearm moves.","After a second contraction at the top, slowly lower the dumbbells back to the starting position as you inhale.","Repeat the movement for the prescribed amount of repetitions."],"category":"strength","images":["Seated_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension/0.jpg","Seated_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension/1.jpg"],"id":"Seated_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension"}'),
('free-exercise-db', 'Seated_Biceps', 'seated-biceps', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Seated_Biceps.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Seated Biceps","force":"static","level":"expert","mechanic":"isolation","equipment":"body only","primaryMuscles":["biceps"],"secondaryMuscles":["chest","shoulders"],"instructions":["Sit on the floor with your knees bent and your partner standing behind you. Extend your arms straight behind you with your palms facing each other. Your partner will hold your wrists for you. This will be the starting position.","Attempt to flex your elbows, while your partner prevents any actual movement.","After 10-20 seconds, relax your arms while your partner gently pulls your wrists up to stretch your biceps. Be sure to let your partner know when the stretch is appropriate to prevent injury or overstretching."],"category":"stretching","images":["Seated_Biceps/0.jpg","Seated_Biceps/1.jpg"],"id":"Seated_Biceps"}'),
('free-exercise-db', 'Seated_Cable_Rows', 'cable-seated-row', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Seated_Cable_Rows.json', 'Unlicense', NULL, 'exact', 100.0, '{"name":"Seated Cable Rows","force":"pull","level":"beginner","mechanic":"compound","equipment":"cable","primaryMuscles":["middle back"],"secondaryMuscles":["biceps","lats","shoulders"],"instructions":["For this exercise you will need access to a low pulley row machine with a V-bar. Note: The V-bar will enable you to have a neutral grip where the palms of your hands face each other. To get into the starting position, first sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.","Lean over as you keep the natural alignment of your back and grab the V-bar handles.","With your arms extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lats as you hold the bar in front of you. This is the starting position of the exercise.","Keeping the torso stationary, pull the handles back towards your torso while keeping the arms close to it until you touch the abdominals. Breathe out as you perform that movement. At that point you should be squeezing your back muscles hard. Hold that contraction for a second and slowly go back to the original position while breathing in.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Seated_Cable_Rows/0.jpg","Seated_Cable_Rows/1.jpg"],"id":"Seated_Cable_Rows"}'),
('free-exercise-db', 'Seated_Cable_Shoulder_Press', 'cable-seated-shoulder-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Seated_Cable_Shoulder_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Seated Cable Shoulder Press","force":"push","level":"beginner","mechanic":"compound","equipment":"cable","primaryMuscles":["shoulders"],"secondaryMuscles":["triceps"],"instructions":["Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 90 degrees to the body, with your head and chest up. The elbows should also be bent to about 90 degrees. This will be your starting position.","Begin by extending through the elbow, pressing the handles together above your head.","After pausing at the top, return the handles to the starting position. Ensure that you maintain tension on the cables.","You can also execute this movement with your back off the pad and alternate hands."],"category":"strength","images":["Seated_Cable_Shoulder_Press/0.jpg","Seated_Cable_Shoulder_Press/1.jpg"],"id":"Seated_Cable_Shoulder_Press"}'),
('free-exercise-db', 'Seated_Calf_Raise', 'machine-seated-calf-raise', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Seated_Calf_Raise.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Seated Calf Raise","force":"push","level":"beginner","mechanic":"isolation","equipment":"machine","primaryMuscles":["calves"],"secondaryMuscles":[],"instructions":["Sit on the machine and place your toes on the lower portion of the platform provided with the heels extending off. Choose the toe positioning of your choice (forward, in, or out) as per the beginning of this chapter.","Place your lower thighs under the lever pad, which will need to be adjusted according to the height of your thighs. Now place your hands on top of the lever pad in order to prevent it from slipping forward.","Lift the lever slightly by pushing your heels up and release the safety bar. This will be your starting position.","Slowly lower your heels by bending at the ankles until the calves are fully stretched. Inhale as you perform this movement.","Raise the heels by extending the ankles as high as possible as you contract the calves and breathe out. Hold the top contraction for a second.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Seated_Calf_Raise/0.jpg","Seated_Calf_Raise/1.jpg"],"id":"Seated_Calf_Raise"}'),
('free-exercise-db', 'Seated_Calf_Stretch', 'seated-calf-stretch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Seated_Calf_Stretch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Seated Calf Stretch","force":"static","level":"beginner","mechanic":null,"equipment":null,"primaryMuscles":["calves"],"secondaryMuscles":["hamstrings","lower back"],"instructions":["Sit up straight on an exercise mat.","Bend one knee and put that foot on the floor to stabilize the torso.","Straighten your other leg and flex your ankle.","Using a band, towel, or your hand if you can reach, pull the toes toward you. Hold for 10 to 20 seconds, then switch sides."],"category":"stretching","images":["Seated_Calf_Stretch/0.jpg","Seated_Calf_Stretch/1.jpg"],"id":"Seated_Calf_Stretch"}'),
('free-exercise-db', 'Seated_Close-Grip_Concentration_Barbell_Curl', 'barbell-seated-close-grip-concentration-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Seated_Close-Grip_Concentration_Barbell_Curl.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Seated Close-Grip Concentration Barbell Curl","force":"pull","level":"intermediate","mechanic":"isolation","equipment":"barbell","primaryMuscles":["biceps"],"secondaryMuscles":[],"instructions":["Sit down on a flat bench with a barbell or E-Z Bar in front of you in between your legs. Your legs should be spread with the knees bent and the feet on the floor.","Use your arms to pick the barbell up and place the back of your upper arms on top of your inner thighs (around three and a half inches away from the front of the knee). A supinated grip closer than shoulder width is needed to perform this exercise. Tip: Your arm should be extended at arms length and the barbell should be above the floor. This will be your starting position.","While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps.","Slowly begin to bring the barbell back to starting position as your breathe in. Tip: Avoid swinging motions at any time.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Seated_Close-Grip_Concentration_Barbell_Curl/0.jpg","Seated_Close-Grip_Concentration_Barbell_Curl/1.jpg"],"id":"Seated_Close-Grip_Concentration_Barbell_Curl"}'),
('free-exercise-db', 'Seated_Dumbbell_Curl', 'dumbbell-seated-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Seated_Dumbbell_Curl.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Seated Dumbbell Curl","force":"pull","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["biceps"],"secondaryMuscles":[],"instructions":["Sit on a flat bench with a dumbbell on each hand being held at arms length. The elbows should be close to the torso.","Rotate the palms of the hands so that they are facing your torso. This will be your starting position.","While holding the upper arm stationary, curl the weights and start twisting the wrists once the dumbbells pass your thighs so that the palms of your hands face forward at the end of the movement. Make sure that you contract the biceps as you breathe out and make sure that only the forearms move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps.","Slowly begin to bring the dumbbells back to the starting position as your breathe in and as you rotate the wrists back to a neutral grip.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Seated_Dumbbell_Curl/0.jpg","Seated_Dumbbell_Curl/1.jpg"],"id":"Seated_Dumbbell_Curl"}'),
('free-exercise-db', 'Seated_Dumbbell_Inner_Biceps_Curl', 'dumbbell-seated-inner-biceps-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Seated_Dumbbell_Inner_Biceps_Curl.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Seated Dumbbell Inner Biceps Curl","force":"pull","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["biceps"],"secondaryMuscles":[],"instructions":["Sit on the end of a flat bench with a dumbbell in each hand being held at arms length. The elbows should be close to the torso.","Rotate the palms of the hands so that they are facing inward in a neutral position. This will be your starting position.","While holding the upper arms stationary, curl the dumbbells out and up, turning the palms out as you lift and keeping your forearms in line with your outer deltoids. Tips:","Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps.","Slowly begin to bring the dumbbells back to the starting position as your breathe in. Remember to rotate your arms as you lower the dumbbells so that you can switch back to a neutral grip.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Seated_Dumbbell_Inner_Biceps_Curl/0.jpg","Seated_Dumbbell_Inner_Biceps_Curl/1.jpg"],"id":"Seated_Dumbbell_Inner_Biceps_Curl"}'),
('free-exercise-db', 'Seated_Dumbbell_Palms-Down_Wrist_Curl', 'dumbbell-seated-palms-down-wrist-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Seated_Dumbbell_Palms-Down_Wrist_Curl.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Seated Dumbbell Palms-Down Wrist Curl","force":"pull","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["forearms"],"secondaryMuscles":[],"instructions":["Start out by placing two dumbbells on the floor in front of a flat bench.","Sit down on the edge of the flat bench with your legs at about shoulder width apart. Make sure to keep your feet on the floor.","Use your arms to grab both of the dumbbells and bring them up so that your forearms are resting against your thighs with the palms of the hands facing down. Your wrists should be hanging over the edge of your thighs.","Start out by curling your wrist upwards and exhaling.","Slowly lower your wrists back down to the starting position while inhaling. Make sure to inhale during this part of the exercise. Tip: Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.","Repeat for the recommended amount of repetitions.","When finished, simply lower the dumbbells to the floor."],"category":"strength","images":["Seated_Dumbbell_Palms-Down_Wrist_Curl/0.jpg","Seated_Dumbbell_Palms-Down_Wrist_Curl/1.jpg"],"id":"Seated_Dumbbell_Palms-Down_Wrist_Curl"}'),
('free-exercise-db', 'Seated_Dumbbell_Palms-Up_Wrist_Curl', 'dumbbell-seated-palms-up-wrist-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Seated_Dumbbell_Palms-Up_Wrist_Curl.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Seated Dumbbell Palms-Up Wrist Curl","force":"pull","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["forearms"],"secondaryMuscles":[],"instructions":["Start out by placing two dumbbells on the floor in front of a flat bench.","Sit down on the edge of the flat bench with your legs at about shoulder width apart. Make sure to keep your feet on the floor.","Use your arms to grab both of the dumbbells and bring them up so that your forearms are resting against your thighs with the palms of the hands facing up. Your wrists should be hanging over the edge of your thighs.","Start out by curling your wrist upwards and exhaling.","Slowly lower your wrists back down to the starting position while inhaling. Make sure to inhale during this part of the exercise. Tip: Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.","Repeat for the recommended amount of repetitions.","When finished, simply lower the dumbbells to the floor."],"category":"strength","images":["Seated_Dumbbell_Palms-Up_Wrist_Curl/0.jpg","Seated_Dumbbell_Palms-Up_Wrist_Curl/1.jpg"],"id":"Seated_Dumbbell_Palms-Up_Wrist_Curl"}'),
('free-exercise-db', 'Seated_Dumbbell_Press', 'dumbbell-seated-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Seated_Dumbbell_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Seated Dumbbell Press","force":"push","level":"beginner","mechanic":"compound","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":["triceps"],"instructions":["Grab a couple of dumbbells and sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs.","Clean the dumbbells up one at a time by using your thighs to bring the dumbbells up to shoulder height at each side.","Rotate the wrists so that the palms of your hands are facing forward. This is your starting position.","As you exhale, push the dumbbells up until they touch at the top.","After a second pause, slowly come down back to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Seated_Dumbbell_Press/0.jpg","Seated_Dumbbell_Press/1.jpg"],"id":"Seated_Dumbbell_Press"}'),
('free-exercise-db', 'Seated_Flat_Bench_Leg_Pull-In', 'seated-flat-bench-leg-pull-in', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Seated_Flat_Bench_Leg_Pull-In.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Seated Flat Bench Leg Pull-In","force":"pull","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Sit on a bench with the legs stretched out in front of you slightly below parallel and your arms holding on to the sides of the bench. Your torso should be leaning backwards around a 45-degree angle from the bench. This will be your starting position.","Bring the knees in toward you as you move your torso closer to them at the same time. Breathe out as you perform this movement.","After a second pause, go back to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Seated_Flat_Bench_Leg_Pull-In/0.jpg","Seated_Flat_Bench_Leg_Pull-In/1.jpg"],"id":"Seated_Flat_Bench_Leg_Pull-In"}'),
('free-exercise-db', 'Seated_Floor_Hamstring_Stretch', 'seated-floor-hamstring-stretch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Seated_Floor_Hamstring_Stretch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Seated Floor Hamstring Stretch","force":"static","level":"beginner","mechanic":null,"equipment":null,"primaryMuscles":["hamstrings"],"secondaryMuscles":["calves"],"instructions":["Sit on a mat with your right leg extended in front of you and your left leg bent with your foot against your right inner thigh.","Lean forward from your hips and reach for your ankle until you feel a stretch in your hamstring. Hold for 15 seconds, then repeat for your other side."],"category":"stretching","images":["Seated_Floor_Hamstring_Stretch/0.jpg","Seated_Floor_Hamstring_Stretch/1.jpg"],"id":"Seated_Floor_Hamstring_Stretch"}'),
('free-exercise-db', 'Seated_Front_Deltoid', 'seated-front-deltoid', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Seated_Front_Deltoid.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Seated Front Deltoid","force":"static","level":"expert","mechanic":null,"equipment":"body only","primaryMuscles":["shoulders"],"secondaryMuscles":["chest"],"instructions":["Sit upright on the floor with your legs bent, your partner standing behind you. Stick your arms straight out to your sides, with your palms facing the ground. Attempt to move them as far behind you as possible, as your assistant holds your wrists. This will be your starting position.","Keeping your elbows straight, attempt to move your arms to the front, with your partner gently restraining you to prevent any actual movement for 10-20 seconds.","Now, relax your muscles and allow your partner to gently increase the stretch on the shoulders and chest. Hold for 10 to 20 seconds."],"category":"stretching","images":["Seated_Front_Deltoid/0.jpg","Seated_Front_Deltoid/1.jpg"],"id":"Seated_Front_Deltoid"}'),
('free-exercise-db', 'Seated_Glute', 'seated-glute', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Seated_Glute.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Seated Glute","force":"static","level":"expert","mechanic":null,"equipment":"body only","primaryMuscles":["glutes"],"secondaryMuscles":["adductors"],"instructions":["In a seated position with your knees bent, cross one ankle over the opposite knee. Your partner will stand behind you. Now, lean forward as your partner braces your shoulders with their hands. This will be your starting position.","Attempt to push your torso back for 10-20 seconds, as your partner prevents any actual movement of your torso.","Now relax your muscles as your partner increases the stretch by gently pushing your torso forward for 10-20 seconds."],"category":"stretching","images":["Seated_Glute/0.jpg","Seated_Glute/1.jpg"],"id":"Seated_Glute"}'),
('free-exercise-db', 'Seated_Good_Mornings', 'barbell-seated-good-morning', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Seated_Good_Mornings.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Seated Good Mornings","force":"pull","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["lower back"],"secondaryMuscles":["glutes"],"instructions":["Set up a box in a power rack. The pins should be set at an appropriate height. Begin by stepping under the bar and placing it across the back of the shoulders, not on top of your traps. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders.","Remove the bar from the rack, creating a tight arch in your lower back. Keep your head facing forward. With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. This will be your starting position.","Keeping the bar tight, bend forward at the hips as much as possible. If you set the pins to what would be parallel, you not only have a safety if you fail, but know when to stop.","Pause just above the pins and reverse the motion until your torso it upright."],"category":"powerlifting","images":["Seated_Good_Mornings/0.jpg","Seated_Good_Mornings/1.jpg"],"id":"Seated_Good_Mornings"}'),
('free-exercise-db', 'Seated_Hamstring', 'seated-hamstring', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Seated_Hamstring.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Seated Hamstring","force":"static","level":"expert","mechanic":null,"equipment":null,"primaryMuscles":["hamstrings"],"secondaryMuscles":["calves"],"instructions":["In a seated position with your legs extended, have your partner stand behind you. Now, lean forward as your partner braces your shoulders with their hands. This will be your starting position.","Attempt to push your torso back for 10-20 seconds, as your partner prevents any actual movement of your torso.","Now relax your muscles as your partner increases the stretch by gently pushing your torso forward for 10-20 seconds."],"category":"stretching","images":["Seated_Hamstring/0.jpg","Seated_Hamstring/1.jpg"],"id":"Seated_Hamstring"}'),
('free-exercise-db', 'Seated_Hamstring_and_Calf_Stretch', 'seated-hamstring-and-calf-stretch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Seated_Hamstring_and_Calf_Stretch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Seated Hamstring and Calf Stretch","force":"static","level":"intermediate","mechanic":null,"equipment":"other","primaryMuscles":["hamstrings"],"secondaryMuscles":["calves"],"instructions":["Loop a belt, rope, or band around one foot. Sit down with both legs extended . This will be your starting position.","Leaning forward slightly, pull on the belt to draw the toes of your foot back. Hold this position for 10-20 seconds and then repeat with the other leg."],"category":"stretching","images":["Seated_Hamstring_and_Calf_Stretch/0.jpg","Seated_Hamstring_and_Calf_Stretch/1.jpg"],"id":"Seated_Hamstring_and_Calf_Stretch"}'),
('free-exercise-db', 'Seated_Head_Harness_Neck_Resistance', 'seated-head-harness-neck-resistance', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Seated_Head_Harness_Neck_Resistance.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Seated Head Harness Neck Resistance","force":"pull","level":"intermediate","mechanic":"isolation","equipment":"other","primaryMuscles":["neck"],"secondaryMuscles":[],"instructions":["Place a neck strap on the floor at the end of a flat bench. Once you have selected the weights, sit at the end of the flat bench with your feet wider than shoulder width apart from each other. Your toes should be pointed out.","Slowly move your torso forward until it is almost parallel with the floor. Using both hands, securely position the neck strap around your head. Tip: Make sure the weights are still lying on the floor to prevent any strain on the neck. Now grab the weight with both hands while elevating your torso back until it is almost perpendicular to the floor. Note: Your head and torso needs to be slightly tilted forward to perform this exercise.","Now place both hands on top of your knees. This is the starting position.","Slowly lower your neck down until your chin touches the upper part of your chest while breathing in.","While exhaling, bring your neck back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Seated_Head_Harness_Neck_Resistance/0.jpg","Seated_Head_Harness_Neck_Resistance/1.jpg"],"id":"Seated_Head_Harness_Neck_Resistance"}'),
('free-exercise-db', 'Seated_Leg_Curl', 'machine-seated-leg-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Seated_Leg_Curl.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Seated Leg Curl","force":"pull","level":"beginner","mechanic":"isolation","equipment":"machine","primaryMuscles":["hamstrings"],"secondaryMuscles":[],"instructions":["Adjust the machine lever to fit your height and sit on the machine with your back against the back support pad.","Place the back of lower leg on top of padded lever (just a few inches under the calves) and secure the lap pad against your thighs, just above the knees. Then grasp the side handles on the machine as you point your toes straight (or you can also use any of the other two stances) and ensure that the legs are fully straight right in front of you. This will be your starting position.","As you exhale, pull the machine lever as far as possible to the back of your thighs by flexing at the knees. Keep your torso stationary at all times. Hold the contracted position for a second.","Slowly return to the starting position as you breathe in.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Seated_Leg_Curl/0.jpg","Seated_Leg_Curl/1.jpg"],"id":"Seated_Leg_Curl"}'),
('free-exercise-db', 'Seated_Leg_Tucks', 'seated-leg-tuck', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Seated_Leg_Tucks.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Seated Leg Tucks","force":"pull","level":"beginner","mechanic":"isolation","equipment":"body only","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Sit on a bench with the legs stretched out in front of you slightly below parallel and your arms holding on to the sides of the bench. Your torso should be leaning backwards around a 45-degree angle from the bench. This will be your starting position.","Bring the knees in toward you as you move your torso closer to them at the same time. Breathe out as you perform this movement.","After a second pause, go back to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Seated_Leg_Tucks/0.jpg","Seated_Leg_Tucks/1.jpg"],"id":"Seated_Leg_Tucks"}'),
('free-exercise-db', 'Seated_One-Arm_Dumbbell_Palms-Down_Wrist_Curl', 'dumbbell-seated-one-arm-palms-down-wrist-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Seated_One-Arm_Dumbbell_Palms-Down_Wrist_Curl.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Seated One-Arm Dumbbell Palms-Down Wrist Curl","force":"pull","level":"intermediate","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["forearms"],"secondaryMuscles":[],"instructions":["Sit on a flat bench with a dumbbell in your right hand.","Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart.","Lean forward and place your right forearm on top of your upper right thigh with your palm down. Tip: Make sure that the back of the wrist lies on top of your knees. This will be your starting position.","Lower the dumbbell as far as possible as you keep a tight grip on the dumbbell. Inhale as you perform this movement.","Now curl the dumbbell as high as possible as you contract the forearms and as you exhale. Keep the contraction for a second before you lower again. Tip: The only movement should happen at the wrist.","Perform for the recommended amount of repetitions, switch arms and repeat the movement."],"category":"strength","images":["Seated_One-Arm_Dumbbell_Palms-Down_Wrist_Curl/0.jpg","Seated_One-Arm_Dumbbell_Palms-Down_Wrist_Curl/1.jpg"],"id":"Seated_One-Arm_Dumbbell_Palms-Down_Wrist_Curl"}'),
('free-exercise-db', 'Seated_One-Arm_Dumbbell_Palms-Up_Wrist_Curl', 'dumbbell-seated-one-arm-palms-up-wrist-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Seated_One-Arm_Dumbbell_Palms-Up_Wrist_Curl.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Seated One-Arm Dumbbell Palms-Up Wrist Curl","force":"pull","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["forearms"],"secondaryMuscles":[],"instructions":["Sit on a flat bench with a dumbbell in your right hand.","Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart.","Lean forward and place your right forearm on top of your upper right thigh with your palm up. Tip: Make sure that the front of the wrist lies on top of your knees. This will be your starting position.","Lower the dumbbell as far as possible as you keep a tight grip on the dumbbell. Inhale as you perform this movement.","Now curl the dumbbell as high as possible as you contract the forearms and as you exhale. Keep the contraction for a second before you lower again. Tip: The only movement should happen at the wrist.","Perform for the recommended amount of repetitions, switch arms and repeat the movement."],"category":"strength","images":["Seated_One-Arm_Dumbbell_Palms-Up_Wrist_Curl/0.jpg","Seated_One-Arm_Dumbbell_Palms-Up_Wrist_Curl/1.jpg"],"id":"Seated_One-Arm_Dumbbell_Palms-Up_Wrist_Curl"}'),
('free-exercise-db', 'Seated_One-arm_Cable_Pulley_Rows', 'cable-seated-one-arm-pulley-row', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Seated_One-arm_Cable_Pulley_Rows.json', 'Unlicense', NULL, 'new', 85.1, '{"name":"Seated One-arm Cable Pulley Rows","force":"pull","level":"intermediate","mechanic":"compound","equipment":"cable","primaryMuscles":["middle back"],"secondaryMuscles":["biceps","lats","traps"],"instructions":["To get into the starting position, first sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.","Lean over as you keep the natural alignment of your back and grab the single handle attachment with your left arm using a palms-down grip.","With your arm extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lat as you hold the bar in front of you. The right arm can be kept by the waist. This is the starting position of the exercise.","Keeping the torso stationary, pull the handles back towards your torso while keeping the arms close to it as you rotate the wrist, so that by the time your hand is by your abdominals it is in a neutral position (palms facing the torso). Breathe out as you perform that movement. At that point you should be squeezing your back muscles hard.","Hold that contraction for a second and slowly go back to the original position while breathing in. Tip: Remember to rotate the wrist as you go back to the starting position so that the palms are facing down again.","Repeat for the recommended amount of repetitions and then perform the same movement with the right hand."],"category":"strength","images":["Seated_One-arm_Cable_Pulley_Rows/0.jpg","Seated_One-arm_Cable_Pulley_Rows/1.jpg"],"id":"Seated_One-arm_Cable_Pulley_Rows"}'),
('free-exercise-db', 'Seated_Overhead_Stretch', 'seated-overhead-stretch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Seated_Overhead_Stretch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Seated Overhead Stretch","force":"static","level":"beginner","mechanic":"isolation","equipment":null,"primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Sit up straight on an exercise mat.","Touch the soles of your feet together with your feet six to eight inches in front of your hips.","Place one hand on the floor beside you and your other hand behind your head.","Lift your elbow to the ceiling as you incline your torso to the other side. Hold for 10 to 20 seconds, then switch sides."],"category":"stretching","images":["Seated_Overhead_Stretch/0.jpg","Seated_Overhead_Stretch/1.jpg"],"id":"Seated_Overhead_Stretch"}'),
('free-exercise-db', 'Seated_Palm-Up_Barbell_Wrist_Curl', 'barbell-seated-palm-up-wrist-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Seated_Palm-Up_Barbell_Wrist_Curl.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Seated Palm-Up Barbell Wrist Curl","force":"pull","level":"beginner","mechanic":"isolation","equipment":"barbell","primaryMuscles":["forearms"],"secondaryMuscles":[],"instructions":["Hold a barbell with both hands and your palms facing up; hands spaced about shoulder width.","Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart.","Lean forward and place your forearms on top of your upper thighs with your palms up. Tip: Make sure that the front of the wrists lay on top of your knees. This will be your starting position.","Lower the bar as far as possible while inhaling and keeping a tight grip.","Now curl bar up as high as possible while flexing the forearms and exhaling. Hold the contraction at the top for a second and Tip: Only the wrist should move."],"category":"strength","images":["Seated_Palm-Up_Barbell_Wrist_Curl/0.jpg","Seated_Palm-Up_Barbell_Wrist_Curl/1.jpg"],"id":"Seated_Palm-Up_Barbell_Wrist_Curl"}'),
('free-exercise-db', 'Seated_Palms-Down_Barbell_Wrist_Curl', 'barbell-seated-palms-down-wrist-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Seated_Palms-Down_Barbell_Wrist_Curl.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Seated Palms-Down Barbell Wrist Curl","force":"pull","level":"beginner","mechanic":"isolation","equipment":"barbell","primaryMuscles":["forearms"],"secondaryMuscles":[],"instructions":["Hold a barbell with both hands and your palms facing down; hands spaced about shoulder width.","Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart.","Lean forward and place your forearms on top of your upper thighs with your palms down. Tip: Make sure that the back of the wrists lay on top of your knees. This will be your starting position.","Lower the bar as far as possible while inhaling and keeping a tight grip.","Now curl bar up as high as possible while flexing the forearms and exhaling. Hold the contraction at the top for a second and Tip: Only the wrist should move."],"category":"strength","images":["Seated_Palms-Down_Barbell_Wrist_Curl/0.jpg","Seated_Palms-Down_Barbell_Wrist_Curl/1.jpg"],"id":"Seated_Palms-Down_Barbell_Wrist_Curl"}'),
('free-exercise-db', 'Seated_Side_Lateral_Raise', 'dumbbell-seated-side-lateral-raise', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Seated_Side_Lateral_Raise.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Seated Side Lateral Raise","force":"push","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":[],"instructions":["Pick a couple of dumbbells and sit at the end of a flat bench with your feet firmly on the floor. Hold the dumbbells with your palms facing in and your arms straight down at your sides at arms'' length. This will be your starting position.","While maintaining the torso stationary (no swinging), lift the dumbbells to your side with a slight bend on the elbow and the hands slightly tilted forward as if pouring water in a glass. Continue to go up until you arms are parallel to the floor. Exhale as you execute this movement and pause for a second at the top.","Lower the dumbbells back down slowly to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Seated_Side_Lateral_Raise/0.jpg","Seated_Side_Lateral_Raise/1.jpg"],"id":"Seated_Side_Lateral_Raise"}'),
('free-exercise-db', 'Seated_Triceps_Press', 'dumbbell-seated-triceps-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Seated_Triceps_Press.json', 'Unlicense', NULL, 'exact', 100.0, '{"name":"Seated Triceps Press","force":"push","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["triceps"],"secondaryMuscles":[],"instructions":["Sit down on a bench with back support and grasp a dumbbell with both hands and hold it overhead at arm''s length. Tip: a better way is to have somebody hand it to you especially if it is very heavy. The resistance should be resting in the palms of your hands with your thumbs around it. The palm of the hand should be facing inward. This will be your starting position.","Keeping your upper arms close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semi-circular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.","Go back to the starting position by using the triceps to raise the dumbbell. Breathe out as you perform this step.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Seated_Triceps_Press/0.jpg","Seated_Triceps_Press/1.jpg"],"id":"Seated_Triceps_Press"}'),
('free-exercise-db', 'Seated_Two-Arm_Palms-Up_Low-Pulley_Wrist_Curl', 'cable-seated-two-arm-palms-up-low-pulley-wrist-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Seated_Two-Arm_Palms-Up_Low-Pulley_Wrist_Curl.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Seated Two-Arm Palms-Up Low-Pulley Wrist Curl","force":"pull","level":"beginner","mechanic":"isolation","equipment":"cable","primaryMuscles":["forearms"],"secondaryMuscles":[],"instructions":["Put a bench in front of a low pulley machine that has a barbell or EZ Curl attachment on it.","Move the bench far enough away so that when you bring the handle to the top of your thighs tension is created on the cable due to the weight stack being moved up.","Now hold the handle with both hands, palms up, using a shoulder-width grip.","Step back and sit on the bench with your feet about shoulder width apart, firmly on the floor.","Lean forward and place the forearms on your thighs with the back of your wrists over your knees. This will be your starting position.","Lower the bar as far as possible, while inhaling and keeping a tight grip.","Now curl the bar up as high as possible while contracting the forearms. Tip: Only the wrist should move; not the forearms.","After a second contraction at the top go back to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Seated_Two-Arm_Palms-Up_Low-Pulley_Wrist_Curl/0.jpg","Seated_Two-Arm_Palms-Up_Low-Pulley_Wrist_Curl/1.jpg"],"id":"Seated_Two-Arm_Palms-Up_Low-Pulley_Wrist_Curl"}'),
('free-exercise-db', 'See-Saw_Press_Alternating_Side_Press', 'dumbbell-see-saw-press-alternating-side', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/See-Saw_Press_Alternating_Side_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"See-Saw Press (Alternating Side Press)","force":"push","level":"intermediate","mechanic":"compound","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":["abdominals","triceps"],"instructions":["Grab a dumbbell with each hand and stand up erect.","Clean (lift) the dumbbells to the chest/shoulder level and then rotate your wrists so that your palms are facing towards you as if you were getting ready to perform an Arnold Press. This will be your starting position.","Now start extending your left arm overhead as you rotate the wrist so that the palm of your hand faces forward as you go up. Your elbows should come out also as you lift the weight. Simultaneously, you will also be bending from your hip to your opposite side. Tip: If you perform the exercise correctly, is should look as if you are trying to reach for something overhead on the right hand side of your body, but with your left arm. Breathe out as you perform this movement.","Once you reach the top position breathe in. Then, with the weight fully extended overhead and you bent over to your right hand side, begin the movement to the left side.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["See-Saw_Press_Alternating_Side_Press/0.jpg","See-Saw_Press_Alternating_Side_Press/1.jpg"],"id":"See-Saw_Press_Alternating_Side_Press"}'),
('free-exercise-db', 'Shotgun_Row', 'cable-shotgun-row', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Shotgun_Row.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Shotgun Row","force":"pull","level":"beginner","mechanic":"compound","equipment":"cable","primaryMuscles":["lats"],"secondaryMuscles":["biceps","middle back"],"instructions":["Attach a single handle to a low cable.","After selecting the correct weight, stand a couple feet back with a wide-split stance. Your arm should be extended and your shoulder forward. This will be your starting position.","Perform the movement by retracting the shoulder and flexing the elbow. As you pull, supinate the wrist, turning the palm upward as you go.","After a brief pause, return to the starting position."],"category":"strength","images":["Shotgun_Row/0.jpg","Shotgun_Row/1.jpg"],"id":"Shotgun_Row"}'),
('free-exercise-db', 'Shoulder_Circles', 'shoulder-circle', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Shoulder_Circles.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Shoulder Circles","force":"pull","level":"beginner","mechanic":null,"equipment":null,"primaryMuscles":["shoulders"],"secondaryMuscles":["traps"],"instructions":["With shoulders relaxed and arms resting loosely at your sides (or in your lap if you''re seated), gently roll your shoulders forward, up, back, and down.","Reverse direction. You can do this exercise alternating shoulders or both at the same time."],"category":"stretching","images":["Shoulder_Circles/0.jpg","Shoulder_Circles/1.jpg"],"id":"Shoulder_Circles"}'),
('free-exercise-db', 'Shoulder_Press_-_With_Bands', 'band-shoulder-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Shoulder_Press_-_With_Bands.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Shoulder Press - With Bands","force":"push","level":"beginner","mechanic":"compound","equipment":"bands","primaryMuscles":["shoulders"],"secondaryMuscles":["triceps"],"instructions":["To begin, stand on an exercise band so that tension begins at arm''s length. Grasp the handles and lift them so that the hands are at shoulder height at each side.","Rotate the wrists so that the palms of your hands are facing forward. Your elbows should be bent, with the upper arms and forearms in line to the torso. This is your starting position.","As you exhale, lift the handles up until your arms are fully extended overhead."],"category":"strength","images":["Shoulder_Press_-_With_Bands/0.jpg","Shoulder_Press_-_With_Bands/1.jpg"],"id":"Shoulder_Press_-_With_Bands"}'),
('free-exercise-db', 'Shoulder_Raise', 'shoulder-raise', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Shoulder_Raise.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Shoulder Raise","force":"pull","level":"beginner","mechanic":null,"equipment":null,"primaryMuscles":["shoulders"],"secondaryMuscles":["lats"],"instructions":["Relax your arms to your sides and raise your shoulders up toward your ears, then back down."],"category":"stretching","images":["Shoulder_Raise/0.jpg","Shoulder_Raise/1.jpg"],"id":"Shoulder_Raise"}'),
('free-exercise-db', 'Shoulder_Stretch', 'shoulder-stretch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Shoulder_Stretch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Shoulder Stretch","force":"pull","level":"beginner","mechanic":null,"equipment":null,"primaryMuscles":["shoulders"],"secondaryMuscles":[],"instructions":["Reach your left arm across your body and hold it straight."],"category":"stretching","images":["Shoulder_Stretch/0.jpg","Shoulder_Stretch/1.jpg"],"id":"Shoulder_Stretch"}'),
('free-exercise-db', 'Side-Lying_Floor_Stretch', 'side-lying-floor-stretch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Side-Lying_Floor_Stretch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Side-Lying Floor Stretch","force":"static","level":"beginner","mechanic":null,"equipment":null,"primaryMuscles":["lats"],"secondaryMuscles":[],"instructions":["First lie on your left side, bending your left knee in front of you to stabilize your torso (use your abdominal muscles as well to hold you upright).","Straighten your right leg and rest the right foot on the floor behind your left. Straighten your right arm over your head and gently pull on your right wrist to stretch the entire right side of the body. Switch sides."],"category":"stretching","images":["Side-Lying_Floor_Stretch/0.jpg","Side-Lying_Floor_Stretch/1.jpg"],"id":"Side-Lying_Floor_Stretch"}'),
('free-exercise-db', 'Side_Bridge', 'side-bridge', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Side_Bridge.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Side Bridge","force":"static","level":"beginner","mechanic":null,"equipment":"body only","primaryMuscles":["abdominals"],"secondaryMuscles":["shoulders"],"instructions":[],"category":"strength","images":["Side_Bridge/0.jpg","Side_Bridge/1.jpg"],"id":"Side_Bridge"}'),
('free-exercise-db', 'Side_Hop-Sprint', 'side-hop-sprint', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Side_Hop-Sprint.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Side Hop-Sprint","force":"push","level":"beginner","mechanic":"compound","equipment":"other","primaryMuscles":["quadriceps"],"secondaryMuscles":["abductors","adductors","calves","hamstrings"],"instructions":["Stand to the side of a cone or hurdle.","Begin this drill by hopping sideways over the obstacle, rebounding out of your landing to hop back to where you started.","Hop for a prescribed number or repetitions as quickly as possible, and finish this drill by sprinting a short distance upon landing the last hop."],"category":"plyometrics","images":["Side_Hop-Sprint/0.jpg","Side_Hop-Sprint/1.jpg"],"id":"Side_Hop-Sprint"}'),
('free-exercise-db', 'Side_Jackknife', 'side-jackknife', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Side_Jackknife.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Side Jackknife","force":"pull","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":[],"category":"strength","images":["Side_Jackknife/0.jpg","Side_Jackknife/1.jpg"],"id":"Side_Jackknife"}'),
('free-exercise-db', 'Side_Lateral_Raise', 'dumbbell-lateral-raise', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Side_Lateral_Raise.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Side Lateral Raise","force":"push","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":[],"instructions":["Pick a couple of dumbbells and stand with a straight torso and the dumbbells by your side at arms length with the palms of the hand facing you. This will be your starting position.","While maintaining the torso in a stationary position (no swinging), lift the dumbbells to your side with a slight bend on the elbow and the hands slightly tilted forward as if pouring water in a glass. Continue to go up until you arms are parallel to the floor. Exhale as you execute this movement and pause for a second at the top.","Lower the dumbbells back down slowly to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Side_Lateral_Raise/0.jpg","Side_Lateral_Raise/1.jpg"],"id":"Side_Lateral_Raise"}'),
('free-exercise-db', 'Side_Laterals_to_Front_Raise', 'dumbbell-side-laterals-to-front-raise', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Side_Laterals_to_Front_Raise.json', 'Unlicense', NULL, 'new', 85.7, '{"name":"Side Laterals to Front Raise","force":"push","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":["traps"],"instructions":["In a standing position, hold a pair of dumbbells at your side. This will be your starting position.","Keeping your elbows slightly bent, raise the weights directly in front of you to shoulder height, avoiding any swinging or cheating.","At the top of the exercise move the weights out in front of you, keeping your arms extended.","Lower the weights with a controlled motion.","On the next repetition, raise the weights in front of you to shoulder height before moving the weights laterally to your sides.","Lower the weights to the starting position."],"category":"strength","images":["Side_Laterals_to_Front_Raise/0.jpg","Side_Laterals_to_Front_Raise/1.jpg"],"id":"Side_Laterals_to_Front_Raise"}'),
('free-exercise-db', 'Side_Leg_Raises', 'side-leg-raise', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Side_Leg_Raises.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Side Leg Raises","force":"pull","level":"beginner","mechanic":null,"equipment":"body only","primaryMuscles":["adductors"],"secondaryMuscles":[],"instructions":["Stand next to a chair, which you may hold onto as a support. Stand on one leg. This will be your starting position.","Keeping your leg straight, raise it as far out to the side as possible, and swing it back down, allowing it to cross the opposite leg.","Repeat this swinging motion 5-10 times, increasing the range of motion as you do so."],"category":"stretching","images":["Side_Leg_Raises/0.jpg","Side_Leg_Raises/1.jpg"],"id":"Side_Leg_Raises"}'),
('free-exercise-db', 'Side_Lying_Groin_Stretch', 'side-lying-groin-stretch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Side_Lying_Groin_Stretch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Side Lying Groin Stretch","force":"static","level":"beginner","mechanic":"isolation","equipment":null,"primaryMuscles":["adductors"],"secondaryMuscles":["hamstrings"],"instructions":["Start off by lying on your right side and bend your right knee in front of you to stabilize the torso.","Rest your head on your right hand or shoulder. Lift your left leg upward and hold it by the back of the knee (easier) or the foot (harder).","Pull your left knee in toward your left shoulder and simultaneously press your foot or knee down to the floor. To intensify this stretch, straighten your left leg. Switch sides."],"category":"stretching","images":["Side_Lying_Groin_Stretch/0.jpg","Side_Lying_Groin_Stretch/1.jpg"],"id":"Side_Lying_Groin_Stretch"}'),
('free-exercise-db', 'Side_Neck_Stretch', 'side-neck-stretch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Side_Neck_Stretch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Side Neck Stretch","force":"static","level":"beginner","mechanic":"isolation","equipment":null,"primaryMuscles":["neck"],"secondaryMuscles":[],"instructions":["Start with your shoulders relaxed, gently tilt your head towards your shoulder.","Assist stretch with a gentle pull on the side of the head."],"category":"stretching","images":["Side_Neck_Stretch/0.jpg","Side_Neck_Stretch/1.jpg"],"id":"Side_Neck_Stretch"}'),
('free-exercise-db', 'Side_Standing_Long_Jump', 'side-standing-long-jump', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Side_Standing_Long_Jump.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Side Standing Long Jump","force":"push","level":"beginner","mechanic":"compound","equipment":null,"primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings"],"instructions":["Begin standing with your feet hip width apart in an athletic stance. Your head and chest should be up, knees and hips slightly bent. This will be your starting position.","Leaning to your right, extend through your hips, knees, and ankles to jump into the air. Block with the arms to lead the movement, jumping as far to your right as you can.","Land facing the same direction with your feet hip width apart, absorbing the impact through your lower body."],"category":"plyometrics","images":["Side_Standing_Long_Jump/0.jpg","Side_Standing_Long_Jump/1.jpg"],"id":"Side_Standing_Long_Jump"}'),
('free-exercise-db', 'Side_To_Side_Chins', 'side-to-chins', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Side_To_Side_Chins.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Side To Side Chins","force":"pull","level":"intermediate","mechanic":"compound","equipment":"other","primaryMuscles":["lats"],"secondaryMuscles":["biceps","forearms","middle back","shoulders"],"instructions":["Grab the pull-up bar with the palms facing forward using a wide grip.","As you have both arms extended in front of you holding the bar at a wide grip, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.","Pull your torso up while leaning to the left hand side until the bar almost touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space (no swinging) and only the arms should move. The forearms should do no other work other than hold the bar.","After a second of contraction, inhale as you go back to the starting position.","Now, pull your torso up while leaning to the right hand side until the bar almost touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.","After a second of contraction, inhale as you go back to the starting position.","Repeat steps 3-6 until you have performed the prescribed amount of repetitions for each side."],"category":"strength","images":["Side_To_Side_Chins/0.jpg","Side_To_Side_Chins/1.jpg"],"id":"Side_To_Side_Chins"}'),
('free-exercise-db', 'Side_Wrist_Pull', 'side-wrist-pull', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Side_Wrist_Pull.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Side Wrist Pull","force":"static","level":"beginner","mechanic":"isolation","equipment":null,"primaryMuscles":["shoulders"],"secondaryMuscles":["forearms","lats"],"instructions":["This stretch works best standing. Cross your left arm over the midline of your body and hold the left wrist in your right hand down at the level of your hips. Start the stretch with a bent left arm.","Slowly straighten, pull, and lift it up to shoulder height, as pictured. Feel this stretch originate in your back, not your shoulders, and don''t pull too hard on the shoulders joint. Switch sides."],"category":"stretching","images":["Side_Wrist_Pull/0.jpg","Side_Wrist_Pull/1.jpg"],"id":"Side_Wrist_Pull"}'),
('free-exercise-db', 'Side_to_Side_Box_Shuffle', 'side-to-box-shuffle', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Side_to_Side_Box_Shuffle.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Side to Side Box Shuffle","force":"push","level":"beginner","mechanic":"compound","equipment":"other","primaryMuscles":["quadriceps"],"secondaryMuscles":["abductors","adductors","calves","hamstrings"],"instructions":["Stand to one side of the box with your left foot resting on the middle of it.","To begin, jump up and over to the other side of the box, landing with your right foot on top of the box and your left foot on the floor. Swing your arms to aid your movement.","Continue shuffling back and forth across the box."],"category":"plyometrics","images":["Side_to_Side_Box_Shuffle/0.jpg","Side_to_Side_Box_Shuffle/1.jpg"],"id":"Side_to_Side_Box_Shuffle"}'),
('free-exercise-db', 'Single-Arm_Cable_Crossover', 'cable-single-arm-crossover', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Single-Arm_Cable_Crossover.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Single-Arm Cable Crossover","force":"push","level":"beginner","mechanic":"isolation","equipment":"cable","primaryMuscles":["chest"],"secondaryMuscles":[],"instructions":["Begin by moving the pulleys to the high position, select the resistance to be used, and take a handle in each hand.","Step forward in front of both pulleys with your arms extended in front of you, bringing your hands together. Your head and chest should be up as you lean forward, while your feet should be staggered. This will be your starting position.","Keeping your left arm in place, allow your right arm to extend out to the side, maintaining a slight bend at the elbow. The right arm should be perpendicular to the body at approximately shoulder level.","Return your arm back to the starting position by pulling your hand back to the midline of the body.","Hold for a second at the starting position and repeat the movement on the opposite side. Continue alternating back and forth for the prescribed number of repetitions."],"category":"strength","images":["Single-Arm_Cable_Crossover/0.jpg","Single-Arm_Cable_Crossover/1.jpg"],"id":"Single-Arm_Cable_Crossover"}'),
('free-exercise-db', 'Single-Arm_Linear_Jammer', 'barbell-single-arm-linear-jammer', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Single-Arm_Linear_Jammer.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Single-Arm Linear Jammer","force":"push","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["shoulders"],"secondaryMuscles":["chest","triceps"],"instructions":["Position a bar into a landmine or securely anchor it in a corner. Load the bar to an appropriate weight.","Raise the bar from the floor, taking it to your shoulders with one or both hands. Adopt a wide stance. This will be your starting position.","Perform the movement by extending the elbow, pressing the weight up. Move explosively, extending the hips and knees fully to produce maximal force.","Return to the starting position."],"category":"strength","images":["Single-Arm_Linear_Jammer/0.jpg","Single-Arm_Linear_Jammer/1.jpg"],"id":"Single-Arm_Linear_Jammer"}'),
('free-exercise-db', 'Single-Arm_Push-Up', 'single-arm-push-up', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Single-Arm_Push-Up.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Single-Arm Push-Up","force":"push","level":"intermediate","mechanic":"compound","equipment":"body only","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["Begin laying prone on the ground. Move yourself into a position supporting your weight on your toes and one arm. Your working arm should be placed directly under the shoulder, fully extended. Your legs should be extended, and for this movement you may need a wider base, placing your feet further apart than in a normal push-up.","Maintain good posture, and place your free hand behind your back. This will be your starting position.","Lower yourself by allowing the elbow to flex until you touch the ground.","Descend slowly, and reverse direction be extending the arm to return to the starting position."],"category":"strength","images":["Single-Arm_Push-Up/0.jpg","Single-Arm_Push-Up/1.jpg"],"id":"Single-Arm_Push-Up"}'),
('free-exercise-db', 'Single-Cone_Sprint_Drill', 'single-cone-sprint-drill', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Single-Cone_Sprint_Drill.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Single-Cone Sprint Drill","force":"push","level":"beginner","mechanic":null,"equipment":"other","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings"],"instructions":["This drill teaches quick foot action. You need a single cone. Begin standing next to the cone with one arm back and one arm forward.","Chop the feet as quickly as possible, blocking with the arms. Circle the cone, keep your knees up, with violent foot action.","Rest after three trips around the cone."],"category":"plyometrics","images":["Single-Cone_Sprint_Drill/0.jpg","Single-Cone_Sprint_Drill/1.jpg"],"id":"Single-Cone_Sprint_Drill"}'),
('free-exercise-db', 'Single-Leg_High_Box_Squat', 'single-leg-high-box-squat', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Single-Leg_High_Box_Squat.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Single-Leg High Box Squat","force":"push","level":"beginner","mechanic":"compound","equipment":"other","primaryMuscles":["quadriceps"],"secondaryMuscles":["glutes","hamstrings"],"instructions":["Position a box in a rack. Secure a band or rope in place above the box.","Standing in front of it, step onto the box to a full standing position, letting your other leg remain unsupported. Hold onto the band for balance",". Continue stepping up and down on the same leg before switching to the opposite side."],"category":"strength","images":["Single-Leg_High_Box_Squat/0.jpg","Single-Leg_High_Box_Squat/1.jpg"],"id":"Single-Leg_High_Box_Squat"}'),
('free-exercise-db', 'Single-Leg_Hop_Progression', 'single-leg-hop-progression', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Single-Leg_Hop_Progression.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Single-Leg Hop Progression","force":"push","level":"beginner","mechanic":"compound","equipment":"other","primaryMuscles":["quadriceps"],"secondaryMuscles":["abductors","adductors","calves","hamstrings"],"instructions":["Arrange a line of cones in front of you. Assume a relaxed standing position, balanced on one leg. Raise the knee of your opposite leg. This will be your starting position.","Hop forward, jumping and landing with the same leg over the cone.","Use a countermovement jump to hop from cone to cone.","At the end, turn around and go back on the other leg."],"category":"plyometrics","images":["Single-Leg_Hop_Progression/0.jpg","Single-Leg_Hop_Progression/1.jpg"],"id":"Single-Leg_Hop_Progression"}'),
('free-exercise-db', 'Single-Leg_Lateral_Hop', 'single-leg-lateral-hop', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Single-Leg_Lateral_Hop.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Single-Leg Lateral Hop","force":"push","level":"beginner","mechanic":"compound","equipment":"other","primaryMuscles":["quadriceps"],"secondaryMuscles":["abductors","adductors","calves","hamstrings"],"instructions":["Stand to the side of a cone or hurdle. To get into the start position, stand on one leg with your knee slightly bent.","To begin, execute a counterjump to hop sideways over the cone.","Land on your jumping leg, and immediately rebound out of it by jumping back to the start position.","Continue hopping back and forth."],"category":"plyometrics","images":["Single-Leg_Lateral_Hop/0.jpg","Single-Leg_Lateral_Hop/1.jpg"],"id":"Single-Leg_Lateral_Hop"}'),
('free-exercise-db', 'Single-Leg_Leg_Extension', 'machine-single-leg-extension', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Single-Leg_Leg_Extension.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Single-Leg Leg Extension","force":"push","level":"beginner","mechanic":"isolation","equipment":"machine","primaryMuscles":["quadriceps"],"secondaryMuscles":[],"instructions":["Seat yourself in the machine and adjust it so that you are positioned properly. The pad should be against the lower part of the shin but not in contact with the ankle. Adjust the seat so that the pivot point is in line with your knee. Select a weight appropriate for your abilities.","Maintaining good posture, fully extend one leg, pausing at the top of the motion.","Return to the starting position without letting the weight stop, keeping tension on the muscle.","Repeat for the desired number of repetitions."],"category":"strength","images":["Single-Leg_Leg_Extension/0.jpg","Single-Leg_Leg_Extension/1.jpg"],"id":"Single-Leg_Leg_Extension"}'),
('free-exercise-db', 'Single-Leg_Stride_Jump', 'single-leg-stride-jump', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Single-Leg_Stride_Jump.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Single-Leg Stride Jump","force":"push","level":"beginner","mechanic":"compound","equipment":"other","primaryMuscles":["quadriceps"],"secondaryMuscles":["abductors","adductors","calves","hamstrings"],"instructions":["Stand to the side of a box with your inside foot on top of it, close to the edge.","Begin by swinging the arms upward as you push through the top leg, jumping upward as high as possible. Attempt to drive the opposite knee upward.","Land in the same position that you started, using your inside leg to decelerate the impact."],"category":"plyometrics","images":["Single-Leg_Stride_Jump/0.jpg","Single-Leg_Stride_Jump/1.jpg"],"id":"Single-Leg_Stride_Jump"}'),
('free-exercise-db', 'Single_Dumbbell_Raise', 'dumbbell-single-raise', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Single_Dumbbell_Raise.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Single Dumbbell Raise","force":null,"level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":["forearms","traps"],"instructions":["With a wide stance, hold a dumbell with both hands, grasping the head of the dumbbell instead of the handle. Your arms should be extended and hanging at the waist. This will be your starting position.","Raise the weight until it is above shoulder level, keeping your arms extended. Your torso and hips should remain stationary throughout the movement.","Return to the starting position and repeat for the recommended amount of repetitions."],"category":"strength","images":["Single_Dumbbell_Raise/0.jpg","Single_Dumbbell_Raise/1.jpg"],"id":"Single_Dumbbell_Raise"}'),
('free-exercise-db', 'Single_Leg_Butt_Kick', 'single-leg-butt-kick', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Single_Leg_Butt_Kick.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Single Leg Butt Kick","force":"push","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","hamstrings"],"instructions":["Begin by standing on one leg, with the bent knee raised. This will be your start position.","Using a countermovement jump, take off upward by extending the hip, knee, and ankle of the grounded leg.","Immediately flex the knee and attempt to touch your butt with the heel of your jumping leg.","Return the leg to a partially bent position underneath the hips and land. Your opposite leg should stay in relatively the same position throughout the drill."],"category":"plyometrics","images":["Single_Leg_Butt_Kick/0.jpg","Single_Leg_Butt_Kick/1.jpg"],"id":"Single_Leg_Butt_Kick"}'),
('free-exercise-db', 'Single_Leg_Glute_Bridge', 'single-leg-glute-bridge', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Single_Leg_Glute_Bridge.json', 'Unlicense', NULL, 'exact', 100.0, '{"name":"Single Leg Glute Bridge","force":"push","level":"beginner","mechanic":"isolation","equipment":"body only","primaryMuscles":["glutes"],"secondaryMuscles":["hamstrings"],"instructions":["Lay on the floor with your feet flat and knees bent.","Raise one leg off of the ground, pulling the knee to your chest. This will be your starting position.","Execute the movement by driving through the heel, extending your hip upward and raising your glutes off of the ground.","Extend as far as possible, pause and then return to the starting position."],"category":"strength","images":["Single_Leg_Glute_Bridge/0.jpg","Single_Leg_Glute_Bridge/1.jpg"],"id":"Single_Leg_Glute_Bridge"}'),
('free-exercise-db', 'Single_Leg_Push-off', 'single-leg-push-off', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Single_Leg_Push-off.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Single Leg Push-off","force":"push","level":"beginner","mechanic":"compound","equipment":"other","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","hamstrings"],"instructions":["Stand on the ground with one foot resting on the box, heel close to the edge.","Push off with your foot on top of the box, trying to gain as much height as possible by extending through the hip and knee.","Land with the same foot on top of the box, returning your other foot back to the start position."],"category":"plyometrics","images":["Single_Leg_Push-off/0.jpg","Single_Leg_Push-off/1.jpg"],"id":"Single_Leg_Push-off"}'),
('free-exercise-db', 'Sit-Up', 'sit-up-2', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Sit-Up.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Sit-Up","force":"pull","level":"beginner","mechanic":"isolation","equipment":"body only","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Lie down on the floor placing your feet either under something that will not move or by having a partner hold them. Your legs should be bent at the knees.","Place your hands behind your head and lock them together by clasping your fingers. This is the starting position.","Elevate your upper body so that it creates an imaginary V-shape with your thighs. Breathe out when performing this part of the exercise.","Once you feel the contraction for a second, lower your upper body back down to the starting position while inhaling.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Sit-Up/0.jpg","Sit-Up/1.jpg"],"id":"Sit-Up"}'),
('free-exercise-db', 'Sit_Squats', 'sit-squat', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Sit_Squats.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Sit Squats","force":"push","level":"beginner","mechanic":null,"equipment":null,"primaryMuscles":["quadriceps"],"secondaryMuscles":["abductors","glutes","hamstrings"],"instructions":["Stand with your feet shoulder width apart. This will be your starting position.","Begin the movement by flexing your knees and hips, sitting back with your hips.","Continue until you have squatted a portion of the way down, but are above parallel, and quickly reverse the motion until you return to the starting position. Repeat for 5-10 repetitions."],"category":"stretching","images":["Sit_Squats/0.jpg","Sit_Squats/1.jpg"],"id":"Sit_Squats"}'),
('free-exercise-db', 'Skating', 'skating', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Skating.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Skating","force":null,"level":"intermediate","mechanic":null,"equipment":"other","primaryMuscles":["quadriceps"],"secondaryMuscles":["abductors","adductors","calves","glutes","hamstrings"],"instructions":["Roller skating is a fun activity which can be effective in improving cardiorespiratory fitness and muscular endurance. It requires relatively good balance and coordination. It is necessary to learn the basics of skating including turning and stopping and to wear protective gear to avoid possible injury.","You can skate at a comfortable pace for 30 minutes straight. If you want a cardio challenge, do interval skating — speed skate two minutes of every five minutes, using the remaining three minutes to recover. A 150 lb person will typically burn about 175 calories in 30 minutes skating at a comfortable pace, similar to brisk walking."],"category":"cardio","images":["Skating/0.jpg","Skating/1.jpg"],"id":"Skating"}'),
('free-exercise-db', 'Sled_Drag_-_Harness', 'sled-drag-harness', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Sled_Drag_-_Harness.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Sled Drag - Harness","force":"push","level":"beginner","mechanic":"compound","equipment":"other","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings"],"instructions":["To begin, load the sled with the desired weight and attach the pulling strap. You can pull with handles, use a harness, or attach the pulling strap to a weight belt.","Whether pulling forwards or backwards, lean in the direction of travel and progress by extending through the hips and knees."],"category":"strongman","images":["Sled_Drag_-_Harness/0.jpg","Sled_Drag_-_Harness/1.jpg"],"id":"Sled_Drag_-_Harness"}'),
('free-exercise-db', 'Sled_Overhead_Backward_Walk', 'sled-overhead-backward-walk', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Sled_Overhead_Backward_Walk.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Sled Overhead Backward Walk","force":"pull","level":"beginner","mechanic":"compound","equipment":"other","primaryMuscles":["shoulders"],"secondaryMuscles":["calves","middle back","quadriceps"],"instructions":["Attach dual handles to a sled connected by a rope or chain. Load the sled to a light weight.","Face the sled, backing up until there is some tension in the line. Hold your hands directly above your head with your elbows extended. This will be your starting position.","Walk backwards, keeping your arms raised above your head. Avoid jerky movements."],"category":"strength","images":["Sled_Overhead_Backward_Walk/0.jpg","Sled_Overhead_Backward_Walk/1.jpg"],"id":"Sled_Overhead_Backward_Walk"}'),
('free-exercise-db', 'Sled_Overhead_Triceps_Extension', 'sled-overhead-triceps-extension', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Sled_Overhead_Triceps_Extension.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Sled Overhead Triceps Extension","force":"push","level":"beginner","mechanic":"isolation","equipment":"other","primaryMuscles":["triceps"],"secondaryMuscles":[],"instructions":["Attach dual handles to a sled using a chain or rope. Load the sled to an appropriate load.","Facing away from the sled, step away until there is tension in the line. Raise your hands above your head, keeping them together, palms facing each other. Your elbows should be pointed upward with the elbows flexed. This will be your starting position.","Extend through the elbow to straighten the arm. Ensure that your upper arm stays in position to isolate the triceps.","Upon full extension, step forward to take the slack out of the line. You may keep your feet staggered for more stability."],"category":"strength","images":["Sled_Overhead_Triceps_Extension/0.jpg","Sled_Overhead_Triceps_Extension/1.jpg"],"id":"Sled_Overhead_Triceps_Extension"}'),
('free-exercise-db', 'Sled_Push', 'sled-push-2', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Sled_Push.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Sled Push","force":"push","level":"beginner","mechanic":"compound","equipment":"other","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","chest","glutes","hamstrings","triceps"],"instructions":["Load your pushing sled with the desired weight.","Take an athletic posture, leaning into the sled with your arms fully extended, grasping the handles. Push the sled as fast as possible, focusing on extending your hips and knees to strengthen your posterior chain."],"category":"strongman","images":["Sled_Push/0.jpg","Sled_Push/1.jpg"],"id":"Sled_Push"}'),
('free-exercise-db', 'Sled_Reverse_Flye', 'sled-reverse-flye', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Sled_Reverse_Flye.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Sled Reverse Flye","force":"pull","level":"beginner","mechanic":"isolation","equipment":"other","primaryMuscles":["shoulders"],"secondaryMuscles":[],"instructions":["Attach dual handles to a sled connected by a rope or chain. Load the sled to a light weight.","Face the sled, backing up until there is some tension in the line. Take both handles at arms length at about waist level. Bend the knees slightly and keep your chest and head up. This will be your starting position.","Without flexing the elbow, pull the handles upward and apart, performing a reverse fly with some external rotation. Your palms should be facing forward as you do this.","Return to the starting position, taking a couple steps back to take the slack out of the line."],"category":"strength","images":["Sled_Reverse_Flye/0.jpg","Sled_Reverse_Flye/1.jpg"],"id":"Sled_Reverse_Flye"}'),
('free-exercise-db', 'Sled_Row', 'sled-row', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Sled_Row.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Sled Row","force":"pull","level":"beginner","mechanic":"compound","equipment":"other","primaryMuscles":["middle back"],"secondaryMuscles":["biceps","lats"],"instructions":["Attach dual handles to a sled connected by a rope or chain. Load the sled to an appropriate weight. Face the sled, backing up until there is some tension in the line.","With a handle in each hand, bend the knees slightly, keep your head and chest up, and begin with your arms extended.","To initiate the movement, flex the elbow as you retract your shoulder blades, pulling the sled towards you.","Take a step or two back to get tension in the line and repeat."],"category":"strength","images":["Sled_Row/0.jpg","Sled_Row/1.jpg"],"id":"Sled_Row"}'),
('free-exercise-db', 'Sledgehammer_Swings', 'sledgehammer-swing', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Sledgehammer_Swings.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Sledgehammer Swings","force":"pull","level":"beginner","mechanic":"compound","equipment":"other","primaryMuscles":["abdominals"],"secondaryMuscles":["calves","forearms","lats","middle back","shoulders"],"instructions":["You will need a tire and a sledgehammer for this exercise. Stand in front of the tire about two feet away from it with a staggered stance. Grip the sledgehammer.","If you are right handed, your left hand should be at the bottom of the handle, and your right hand should be choking up closer to the head.","As you bring the sledge up, your right hand slides toward the head; as you swing down, your right hand will slide down to join your left hand. Slam it down as hard as you can against the tire. Control the bounce of the hammer off of the tire.","Repeat on the other side."],"category":"plyometrics","images":["Sledgehammer_Swings/0.jpg","Sledgehammer_Swings/1.jpg"],"id":"Sledgehammer_Swings"}'),
('free-exercise-db', 'Smith_Incline_Shoulder_Raise', 'smith-machine-incline-shoulder-raise', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Smith_Incline_Shoulder_Raise.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Smith Incline Shoulder Raise","force":"push","level":"beginner","mechanic":"isolation","equipment":"barbell","primaryMuscles":["shoulders"],"secondaryMuscles":["chest"],"instructions":["Place an incline bench underneath the smith machine. Place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the incline bench and make sure your shoulders are aligned right under the barbell.","Using a shoulder width pronated (palms forward) grip, lift the bar from the rack and hold it straight over you with a slight bend at the elbows. This will be your starting position.","As you breathe out, lift the bar up until your arms are fully extended. Note: The contraction should be felt around the shoulders.","After a second pause, bring the bar back down to the starting position as you breathe in.","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the bar back in the rack."],"category":"strength","images":["Smith_Incline_Shoulder_Raise/0.jpg","Smith_Incline_Shoulder_Raise/1.jpg"],"id":"Smith_Incline_Shoulder_Raise"}'),
('free-exercise-db', 'Smith_Machine_Behind_the_Back_Shrug', 'smith-machine-behind-back-shrug', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Smith_Machine_Behind_the_Back_Shrug.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Smith Machine Behind the Back Shrug","force":"pull","level":"beginner","mechanic":"isolation","equipment":"machine","primaryMuscles":["traps"],"secondaryMuscles":["shoulders"],"instructions":["With the bar at thigh level, load an appropriate weight.","Stand with the bar behind you, taking a shoulder-width, pronated grip on the bar and unhook the weight. You should be standing up straight with your head and chest up and your arms extended. This will be your starting position.","Initiate the movement by shrugging your shoulders straight up. Do not flex the arms or wrist during the movement.","After a brief pause return the weight to the starting position.","Repeat for the desired number of repetitions before engaging the hooks to rack the weight."],"category":"strength","images":["Smith_Machine_Behind_the_Back_Shrug/0.jpg","Smith_Machine_Behind_the_Back_Shrug/1.jpg"],"id":"Smith_Machine_Behind_the_Back_Shrug"}'),
('free-exercise-db', 'Smith_Machine_Bench_Press', 'smith-machine-bench-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Smith_Machine_Bench_Press.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Smith Machine Bench Press","force":"push","level":"beginner","mechanic":"compound","equipment":"machine","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["Place a flat bench underneath the smith machine. Now place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the flat bench. Using a pronated grip that is wider than shoulder width, unlock the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.","As you breathe in, come down slowly until you feel the bar on your middle chest.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions.","When you are done, lock the bar back in the rack."],"category":"strength","images":["Smith_Machine_Bench_Press/0.jpg","Smith_Machine_Bench_Press/1.jpg"],"id":"Smith_Machine_Bench_Press"}'),
('free-exercise-db', 'Smith_Machine_Bent_Over_Row', 'smith-machine-bent-over-row', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Smith_Machine_Bent_Over_Row.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Smith Machine Bent Over Row","force":"pull","level":"beginner","mechanic":"compound","equipment":"machine","primaryMuscles":["middle back"],"secondaryMuscles":["biceps","lats","shoulders"],"instructions":["Set the barbell attached to the smith machine to a height that is about 2 inches below your knees.","Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up.","Now grasp the barbell using an overhand (pronated) grip and unlock it from the smith machine rack. Then let it hang directly in front of you as your arms hang extended perpendicular to the floor and your torso. This is your starting position.","While keeping the torso stationary, lift the barbell as you breathe out, keeping the elbows close to the body and not doing any force with the forearm other than holding the weights. On the top contracted position, squeeze the back muscles and hold for a second.","Slowly lower the weight again to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Smith_Machine_Bent_Over_Row/0.jpg","Smith_Machine_Bent_Over_Row/1.jpg"],"id":"Smith_Machine_Bent_Over_Row"}'),
('free-exercise-db', 'Smith_Machine_Calf_Raise', 'smith-machine-calf-raise', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Smith_Machine_Calf_Raise.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Smith Machine Calf Raise","force":"push","level":"beginner","mechanic":"isolation","equipment":"machine","primaryMuscles":["calves"],"secondaryMuscles":[],"instructions":["Place a block or weight plate below the bar on the Smith machine. Set the bar to a position that best matches your height. Once the correct height is chosen and the bar is loaded, step onto the plates with the balls of your feet and place the bar on the back of your shoulders.","Take the bar with both hands facing forward. Rotate the bar to unrack it. This will be your starting position.","Raise your heels as high as possible by pushing off of the balls of your feet, flexing your calf at the top of the contraction. Your knees should remain extended. Hold the contracted position for a second before you start to go back down.","Return slowly to the starting position as you breathe in while lowering your heels.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Smith_Machine_Calf_Raise/0.jpg","Smith_Machine_Calf_Raise/1.jpg"],"id":"Smith_Machine_Calf_Raise"}'),
('free-exercise-db', 'Smith_Machine_Close-Grip_Bench_Press', 'smith-machine-close-grip-bench-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Smith_Machine_Close-Grip_Bench_Press.json', 'Unlicense', NULL, 'exact', 100.0, '{"name":"Smith Machine Close-Grip Bench Press","force":"push","level":"beginner","mechanic":"compound","equipment":"machine","primaryMuscles":["triceps"],"secondaryMuscles":["chest","shoulders"],"instructions":["Place a flat bench underneath the smith machine. Place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the flat bench. Using a close and pronated grip (palms facing forward) that is around shoulder width, unlock the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.","As you breathe in, come down slowly until you feel the bar on your middle chest. Tip: Make sure that as opposed to a regular bench press, you keep the elbows close to the torso at all times in order to maximize triceps involvement.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your triceps muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions.","When you are done, lock the bar back in the rack."],"category":"strength","images":["Smith_Machine_Close-Grip_Bench_Press/0.jpg","Smith_Machine_Close-Grip_Bench_Press/1.jpg"],"id":"Smith_Machine_Close-Grip_Bench_Press"}'),
('free-exercise-db', 'Smith_Machine_Decline_Press', 'smith-machine-decline-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Smith_Machine_Decline_Press.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Smith Machine Decline Press","force":null,"level":"beginner","mechanic":"compound","equipment":"machine","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["Position a decline bench in the rack so that the bar will be above your chest. Load an appropriate weight and take your place on the bench.","Rotate the bar to unhook it from the rack and fully extend your arms. Your back should be slightly arched and your shoulder blades retracted. This will be your starting position.","Begin the movement by flexing your arms, lowering the bar to your chest.","Pause briefly, and then extend your arms to push the weight back to the starting position.","After completing the desired number of repetitions, rotate the bar to rack the weight."],"category":"strength","images":["Smith_Machine_Decline_Press/0.jpg","Smith_Machine_Decline_Press/1.jpg"],"id":"Smith_Machine_Decline_Press"}'),
('free-exercise-db', 'Smith_Machine_Hang_Power_Clean', 'smith-machine-hang-power-clean', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Smith_Machine_Hang_Power_Clean.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Smith Machine Hang Power Clean","force":"pull","level":"intermediate","mechanic":"compound","equipment":"machine","primaryMuscles":["hamstrings"],"secondaryMuscles":["glutes","lower back","quadriceps","shoulders","traps"],"instructions":["Position the bar at knee height and load it to an appropriate weight.","Take a pronated grip on the bar outside of shoulder width and unhook the bar from the machine. Your arms should be fully extended with your head and chest up. Your elbows should be pointed out with your shoulders back and down. Your hips should be back, loading the tension into the hamstrings. This will be your starting position.","Initate the movement by forcefully extending the hips and knees, accelerating into the bar. Ensure that you keep your arms straight during this part of the motion.","Upon full extension, rebend the hips and knees to lower your receiving position.","Allow the arms to flex at this point, rotating the elbows around the bar to receive it on your shoulders.","Extend through the hips and knees to come to a standing position with the bar racked on your shoulders to complete the movement."],"category":"strength","images":["Smith_Machine_Hang_Power_Clean/0.jpg","Smith_Machine_Hang_Power_Clean/1.jpg"],"id":"Smith_Machine_Hang_Power_Clean"}'),
('free-exercise-db', 'Smith_Machine_Hip_Raise', 'smith-machine-hip-raise', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Smith_Machine_Hip_Raise.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Smith Machine Hip Raise","force":"pull","level":"beginner","mechanic":"isolation","equipment":"machine","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Position a bench in the rack and load the bar to an appropriate weight. Lie down on the bench, placing the bottom of your feet against the bar. Unlock the bar and extend your legs. You may need to use your hands to assist you. For added stability grasp the sides of the Smith Machine. This will be your starting position.","Initiate the movement by rotating your pelvis, flexing your spine to raise your hips off of the bench. Maintain a slight bend in the knees throughout the motion.","After a brief pause, return the hips to the bench.","Repeat for the desired number of repetitions."],"category":"strength","images":["Smith_Machine_Hip_Raise/0.jpg","Smith_Machine_Hip_Raise/1.jpg"],"id":"Smith_Machine_Hip_Raise"}'),
('free-exercise-db', 'Smith_Machine_Incline_Bench_Press', 'smith-machine-incline-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Smith_Machine_Incline_Bench_Press.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Smith Machine Incline Bench Press","force":"push","level":"beginner","mechanic":"compound","equipment":"machine","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["Place an incline bench underneath the smith machine. Place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the incline bench and make sure your upper chest is aligned with the barbell. Using a pronated grip (palms facing forward) that is wider than shoulder width, unlock the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.","As you breathe in, come down slowly until you feel the bar on your upper chest.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the bar back in the rack."],"category":"strength","images":["Smith_Machine_Incline_Bench_Press/0.jpg","Smith_Machine_Incline_Bench_Press/1.jpg"],"id":"Smith_Machine_Incline_Bench_Press"}'),
('free-exercise-db', 'Smith_Machine_Leg_Press', 'smith-machine-leg-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Smith_Machine_Leg_Press.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Smith Machine Leg Press","force":"push","level":"intermediate","mechanic":"compound","equipment":"machine","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings"],"instructions":["Position a Smith machine bar a couple feet off of the ground. Ensure that it is resting on the safeties. After loading the bar to an appropriate weight, lie underneath the bar. Place the middle of your feet on the bar, tucking your knees to your chest. This will be your starting position.","Begin the movement by driving through your feet to move the bar upward, extending the hips and knees. Do not lock out your knees.","At the top of the motion, pause briefly before returning to the starting position."],"category":"strength","images":["Smith_Machine_Leg_Press/0.jpg","Smith_Machine_Leg_Press/1.jpg"],"id":"Smith_Machine_Leg_Press"}'),
('free-exercise-db', 'Smith_Machine_One-Arm_Upright_Row', 'smith-machine-one-arm-upright-row', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Smith_Machine_One-Arm_Upright_Row.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Smith Machine One-Arm Upright Row","force":"pull","level":"beginner","mechanic":"compound","equipment":"machine","primaryMuscles":["shoulders"],"secondaryMuscles":["biceps","traps"],"instructions":["With the bar at thigh level, load an appropriate weight.","Take a wide grip on the bar and unhook the weight, removing your off hand from the bar. Your arm should be extended as you stand up straight with your head and chest up. This will be your starting position.","Begin the movement by flexing the elbow, raising the upper arm with the elbow pointed out. Continue until your upper arm is parallel to the floor.","After a brief pause, return the weight to the starting position.","Repeat for the desired number of repetitions before engaging the hooks to rack the weight."],"category":"strength","images":["Smith_Machine_One-Arm_Upright_Row/0.jpg","Smith_Machine_One-Arm_Upright_Row/1.jpg"],"id":"Smith_Machine_One-Arm_Upright_Row"}'),
('free-exercise-db', 'Smith_Machine_Overhead_Shoulder_Press', 'smith-machine-shoulder-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Smith_Machine_Overhead_Shoulder_Press.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Smith Machine Overhead Shoulder Press","force":"push","level":"beginner","mechanic":"compound","equipment":"machine","primaryMuscles":["shoulders"],"secondaryMuscles":["triceps"],"instructions":["To begin, place a flat bench (or preferably one with back support) underneath a smith machine. Position the barbell at a height so that when seated on the flat bench, the arms must be almost fully extended to reach the barbell.","Once you have the correct height, sit slightly in behind the barbell so that there is an imaginary straight line from the tip of your nose to the barbell. Your feet should be stationary. Grab the barbell with the palms facing forward, unlock it and lift it up so that your arms are fully extended. This is the starting position.","Slowly begin to lower the barbell until it is level with your chin while inhaling.","Then lift the barbell back to the starting position using your shoulders while exhaling.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Smith_Machine_Overhead_Shoulder_Press/0.jpg","Smith_Machine_Overhead_Shoulder_Press/1.jpg"],"id":"Smith_Machine_Overhead_Shoulder_Press"}'),
('free-exercise-db', 'Smith_Machine_Pistol_Squat', 'smith-machine-pistol-squat', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Smith_Machine_Pistol_Squat.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Smith Machine Pistol Squat","force":"push","level":"intermediate","mechanic":"compound","equipment":"machine","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings"],"instructions":["To begin, first set the bar to a position that best matches your height. Step under it and position the bar across the back of your shoulders.","Take the bar with your hands facing forward, unlock it and lift it off the rack by extending your legs. 3","Move one foot forward about 12 inches in front of the bar. Extend the other leg out in front of you, holding it off the ground. Look forward at all times and maintain a neutral or slightly arched spine. This will be your starting position.","Maintaining good posture, lower yourself by flexing the knee and hip, going down as far as flexibility allows.","Pause briefly at the bottom and then return to the starting position by driving through the heel of your foot, extending the knee and hip."],"category":"strength","images":["Smith_Machine_Pistol_Squat/0.jpg","Smith_Machine_Pistol_Squat/1.jpg"],"id":"Smith_Machine_Pistol_Squat"}'),
('free-exercise-db', 'Smith_Machine_Reverse_Calf_Raises', 'smith-machine-reverse-calf-raise', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Smith_Machine_Reverse_Calf_Raises.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Smith Machine Reverse Calf Raises","force":"push","level":"beginner","mechanic":"isolation","equipment":"machine","primaryMuscles":["calves"],"secondaryMuscles":[],"instructions":["Adjust the barbell on the smith machine to fit your height and align a raised platform right under the bar.","Stand on the platform with the heels of your feet secured on top of it with the balls of your feet extending off it. Position your toes facing forward with a shoulder width stance.","Now, place your shoulders under the barbell while maintaining the foot positioning described and push the barbell up by extending your hips and knees until your torso is standing erect. The knees should be kept with a slight bend; never locked. This will be your starting position. Tip: The barbell on your back is only for balance purposes.","Raise the balls of your feet as you breathe out by extending your toes as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position for a second before you start to go back down.","Slowly go back down to the starting position as you breathe in by lowering the balls of your feet and toes.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Smith_Machine_Reverse_Calf_Raises/0.jpg","Smith_Machine_Reverse_Calf_Raises/1.jpg"],"id":"Smith_Machine_Reverse_Calf_Raises"}'),
('free-exercise-db', 'Smith_Machine_Squat', 'smith-machine-squat', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Smith_Machine_Squat.json', 'Unlicense', NULL, 'exact', 100.0, '{"name":"Smith Machine Squat","force":"push","level":"beginner","mechanic":"compound","equipment":"machine","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings","lower back"],"instructions":["To begin, first set the bar on the height that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.","Hold on to the bar using both arms at each side (palms facing forward), unlock it and lift it off the rack by first pushing with your legs and at the same time straightening your torso.","Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance which targets overall development; however you can choose any of the three stances discussed in the foot stances section).","Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Smith_Machine_Squat/0.jpg","Smith_Machine_Squat/1.jpg"],"id":"Smith_Machine_Squat"}'),
('free-exercise-db', 'Smith_Machine_Stiff-Legged_Deadlift', 'smith-machine-stiff-legged-deadlift', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Smith_Machine_Stiff-Legged_Deadlift.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Smith Machine Stiff-Legged Deadlift","force":"pull","level":"beginner","mechanic":"compound","equipment":"machine","primaryMuscles":["hamstrings"],"secondaryMuscles":["glutes","lower back"],"instructions":["To begin, set the bar on the smith machine to a height that is around the middle of your thighs. Once the correct height is chosen and the bar is loaded, grasp the bar using a pronated (palms forward) grip that is shoulder width apart. You may need some wrist wraps if using a significant amount of weight.","Lift the bar up by fully extending your arms while keeping your back straight. Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position.","Keeping the knees stationary, lower the barbell to over the top of your feet by bending at the waist while keeping your back straight. Keep moving forward as if you were going to pick something from the floor until you feel a stretch on the hamstrings. Exhale as you perform this movement","Start bringing your torso up straight again as soon as you feel the hamstrings stretch by extending your hips and waist until you are back at the starting position. Inhale as you perform this movement.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Smith_Machine_Stiff-Legged_Deadlift/0.jpg","Smith_Machine_Stiff-Legged_Deadlift/1.jpg"],"id":"Smith_Machine_Stiff-Legged_Deadlift"}'),
('free-exercise-db', 'Smith_Machine_Upright_Row', 'smith-machine-upright-row', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Smith_Machine_Upright_Row.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Smith Machine Upright Row","force":"pull","level":"beginner","mechanic":"compound","equipment":"machine","primaryMuscles":["traps"],"secondaryMuscles":["biceps","middle back","shoulders"],"instructions":["To begin, set the bar on the smith machine to a height that is around the middle of your thighs. Once the correct height is chosen and the bar is loaded, grasp the bar using a pronated (palms forward) grip that is shoulder width apart. You may need some wrist wraps if using a significant amount of weight.","Lift the barbell up and fully extend your arms with your back straight. There should be a slight bend at the elbows. This is the starting position.","Use your side shoulders to lift the bar as you exhale. The bar should be close to the body as you move it up. Continue to lift it until it nearly touches your chin. Tip: Your elbows should drive the motion. As you lift the bar, your elbows should always be higher than your forearms. Also, keep your torso stationary and pause for a second at the top of the movement.","Lower the bar back down slowly to the starting position. Inhale as you perform this portion of the movement.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Smith_Machine_Upright_Row/0.jpg","Smith_Machine_Upright_Row/1.jpg"],"id":"Smith_Machine_Upright_Row"}'),
('free-exercise-db', 'Smith_Single-Leg_Split_Squat', 'smith-machine-single-leg-split-squat', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Smith_Single-Leg_Split_Squat.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Smith Single-Leg Split Squat","force":"push","level":"beginner","mechanic":"compound","equipment":"machine","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings"],"instructions":["To begin, place a flat bench 2-3 feet behind the smith machine. Then, set the bar on the height that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.","Hold on to the bar using both arms at each side (palms facing forward), unlock it and lift it off the rack by first pushing with your legs and at the same time straightening your torso.","Position your legs by placing one foot slightly forward under the bar and extending your other leg back and place the top of your foot on the bench. This will be your starting position","Begin to slowly lower the bar by bending the knee as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calf becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knee should make an imaginary straight line with the toes that is perpendicular to the front. If your knee is past that imaginary line (if it is past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise the bar as you exhale by pushing the floor with the heel of your foot mainly as you straighten your leg again and go back to the starting position.","Repeat for the recommended amount of repetitions.","Switch legs and repeat the movement."],"category":"strength","images":["Smith_Single-Leg_Split_Squat/0.jpg","Smith_Single-Leg_Split_Squat/1.jpg"],"id":"Smith_Single-Leg_Split_Squat"}'),
('free-exercise-db', 'Snatch', 'barbell-snatch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Snatch.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Snatch","force":"pull","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["biceps","glutes","hamstrings","lower back","shoulders","traps","triceps"],"instructions":["Place your feet at a shoulder width stance with the barbell resting right above the connection between the toes and the rest of the foot.","With a palms facing down grip, bend at the knees and keeping the back flat grab the bar using a wider than shoulder width grip. Bring the hips down and make sure that your body drops as if you were going to sit on a chair. This will be your starting position.","Start pushing the floor as if it were a moving platform with your feet and simultaneously start lifting the barbell keeping it close to your legs.","As the bar reaches the middle of your thighs, push the floor with your legs and lift your body to a complete extension in an explosive motion.","Lift your shoulders back in a shrugging movement as you bring the bar up while lifting your elbows out to the side and keeping them above the bar for as long as possible.","Now in a very quick but powerful motion, you have to get your body under the barbell when it has reached a high enough point where it can be controlled and drop while locking your arms and holding the barbell overhead as you assume a squat position.","Finalize the movement by rising up out of the squat position to finish the lift. At the end of the lift both feet should be on line and the arms fully extended holding the barbell overhead."],"category":"olympic weightlifting","images":["Snatch/0.jpg","Snatch/1.jpg"],"id":"Snatch"}'),
('free-exercise-db', 'Snatch_Balance', 'barbell-snatch-balance', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Snatch_Balance.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Snatch Balance","force":"push","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings","shoulders","triceps"],"instructions":["Begin with the feet in the pulling position, the bar racked across the back of the shoulders, and the hands placed in a wide snatch grip.","Pop the bar with an abrupt dip and drive of the knees, and aggressively drive under the bar, transitioning the feet into the receiving position.","Receive the bar locked out overhead near the bottom of the squat. The torso should remain vertical, lowering the hips between the legs.","Continue to descend to full depth, and return to a standing position. Carefully lower the weight."],"category":"olympic weightlifting","images":["Snatch_Balance/0.jpg","Snatch_Balance/1.jpg"],"id":"Snatch_Balance"}'),
('free-exercise-db', 'Snatch_Deadlift', 'barbell-snatch-deadlift', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Snatch_Deadlift.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Snatch Deadlift","force":"pull","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["hamstrings"],"secondaryMuscles":["forearms","glutes","hamstrings","lower back","quadriceps","traps"],"instructions":["The snatch deadlift strengthens the first pull of the snatch. Begin with a wide snatch grip with the barbell placed on the platform. The feet should be directly under the hips, with the feet turned out. Squat down to the bar, keeping the back in absolute extension with the head facing forward.","Initiate the movement by driving through the heels, raising the hips. The back angle should remain the same until the bar passes the knees.","At that point, drive your hips through the bar as you lay back. Return the bar to the platform by reversing the motion."],"category":"olympic weightlifting","images":["Snatch_Deadlift/0.jpg","Snatch_Deadlift/1.jpg"],"id":"Snatch_Deadlift"}'),
('free-exercise-db', 'Snatch_Pull', 'barbell-snatch-pull', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Snatch_Pull.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Snatch Pull","force":"pull","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["hamstrings"],"secondaryMuscles":["calves","glutes","lower back","quadriceps","traps"],"instructions":["With a barbell on the floor close to the shins, take a wide snatch grip. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.","Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees.","Next comes the second pull, the main source of acceleration for the pull. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward.","There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back. Full extension should be violent and abrupt, and ensure that you do not prolong the extension for longer than necessary."],"category":"strength","images":["Snatch_Pull/0.jpg","Snatch_Pull/1.jpg"],"id":"Snatch_Pull"}'),
('free-exercise-db', 'Snatch_Shrug', 'barbell-snatch-shrug', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Snatch_Shrug.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Snatch Shrug","force":"pull","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["traps"],"secondaryMuscles":["forearms","shoulders"],"instructions":["Begin with a wide grip, with the bar hanging at the mid thigh position. You can use a hook or overhand grip. Your back should be straight and inclined slightly forward.","Shrug your shoulders towards your ears. While this exercise can usually by loaded with heavier weight than a snatch, avoid overloading to the point that the execution slows down."],"category":"olympic weightlifting","images":["Snatch_Shrug/0.jpg","Snatch_Shrug/1.jpg"],"id":"Snatch_Shrug"}'),
('free-exercise-db', 'Snatch_from_Blocks', 'barbell-snatch-from-blocks', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Snatch_from_Blocks.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Snatch from Blocks","force":"pull","level":"expert","mechanic":"compound","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","forearms","glutes","hamstrings","lower back","shoulders","traps","triceps"],"instructions":["Begin with a loaded barbell on boxes or stands of the desired height. A wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar, with the elbows pointed out. This will be the starting position.","Begin the first pull by driving through the front of the heels, raising the bar from the boxes.","Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body. At peak extension, shrug the shoulders and allow the elbows to flex to the side.","As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. The feet should move to just outside the hips, turned out as necessary. Receive the bar with your body as low as possible and the arms fully extended overhead.","Keeping the bar aligned over the front of the heels, your head and chest up, drive through heels of the feet to move to a standing position. Carefully return the weight to the boxes."],"category":"olympic weightlifting","images":["Snatch_from_Blocks/0.jpg","Snatch_from_Blocks/1.jpg"],"id":"Snatch_from_Blocks"}'),
('free-exercise-db', 'Speed_Band_Overhead_Triceps', 'band-speed-overhead-triceps', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Speed_Band_Overhead_Triceps.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Speed Band Overhead Triceps","force":"push","level":"beginner","mechanic":"isolation","equipment":"bands","primaryMuscles":["triceps"],"secondaryMuscles":[],"instructions":["For this exercise anchor a band to the ground. We used an incline bench and anchored the band to the base, standing over the bench. Alternatively, this could be performed standing on the band.","To begin, pull the band behind your head, holding it with a pronated grip and your elbows up. This will be your starting position.","To perform the movement, extend through the elbow to to straighten your arms, ensuring that you keep your upper arm in place.","Pause, and then return to the starting position."],"category":"strength","images":["Speed_Band_Overhead_Triceps/0.jpg","Speed_Band_Overhead_Triceps/1.jpg"],"id":"Speed_Band_Overhead_Triceps"}'),
('free-exercise-db', 'Speed_Box_Squat', 'barbell-speed-box-squat', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Speed_Box_Squat.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Speed Box Squat","force":"push","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings"],"instructions":["Attach bands to the bar that are securely anchored near the ground. You may need to choke the bands to get adequate tension.","Use a box of an appropriate height for this exercise. Load the bar to a weight that still requires effort, but isn''t so heavy that speed is compromised. Typically, that will be between 50-70% of your one rep max.","Position the bar on your upper back, shoulder blades retracted, back arched and everything tight head to toe. This will be the starting position.","Unrack the bar and position yourself in front of the box. Sit back with your hips until you are seated on the box, ensuring that you descend under control and don''t crash onto the surface.","Pause briefly, and explode off of the box, extending through the hips and knees."],"category":"powerlifting","images":["Speed_Box_Squat/0.jpg","Speed_Box_Squat/1.jpg"],"id":"Speed_Box_Squat"}'),
('free-exercise-db', 'Speed_Squats', 'barbell-speed-squat', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Speed_Squats.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Speed Squats","force":"push","level":"expert","mechanic":"compound","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings","lower back"],"instructions":["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.","Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.","Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance which targets overall development; however you can choose any of the three stances discussed in the foot stances section).","Begin to lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise the bar as fast as possible without involving momentum as you exhale by pushing the floor with the heel of your foot mainly as you straighten the legs again and go back to the starting position. Note: You should perform these exercises as fast as possible but without breaking perfect form and without involving momentum.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Speed_Squats/0.jpg","Speed_Squats/1.jpg"],"id":"Speed_Squats"}'),
('free-exercise-db', 'Spell_Caster', 'dumbbell-spell-caster', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Spell_Caster.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Spell Caster","force":"pull","level":"beginner","mechanic":"compound","equipment":"dumbbell","primaryMuscles":["abdominals"],"secondaryMuscles":["glutes","shoulders"],"instructions":["Hold a dumbbell in each hand with a pronated grip. Your feet should be wide with your hips and knees extended. This will be your starting position.","Begin the movement by pulling both of the dumbbells to one side next to your hip, rotating your torso.","Keeping your arms straight and the dumbbells parallel to the ground, rotate your torso to swing the weights to your opposite side.","Continue alternating, rotating from one side to the other until the set is complete."],"category":"strength","images":["Spell_Caster/0.jpg","Spell_Caster/1.jpg"],"id":"Spell_Caster"}'),
('free-exercise-db', 'Spider_Crawl', 'spider-crawl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Spider_Crawl.json', 'Unlicense', NULL, 'new', 87.0, '{"name":"Spider Crawl","force":"pull","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["abdominals"],"secondaryMuscles":["chest","shoulders","triceps"],"instructions":["Begin in a prone position on the floor. Support your weight on your hands and toes, with your feet together and your body straight. Your arms should be bent to 90 degrees. This will be your starting position.","Initiate the movement by raising one foot off of the ground. Externally rotate the leg and bring the knee toward your elbow, as far forward as possible.","Return this leg to the starting position and repeat on the opposite side."],"category":"strength","images":["Spider_Crawl/0.jpg","Spider_Crawl/1.jpg"],"id":"Spider_Crawl"}'),
('free-exercise-db', 'Spider_Curl', 'ez-bar-spider-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Spider_Curl.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Spider Curl","force":"pull","level":"beginner","mechanic":"isolation","equipment":"e-z curl bar","primaryMuscles":["biceps"],"secondaryMuscles":[],"instructions":["Start out by setting the bar on the part of the preacher bench that you would normally sit on. Make sure to align the barbell properly so that it is balanced and will not fall off.","Move to the front side of the preacher bench (the part where the arms usually lay) and position yourself to lay at a 45 degree slant with your torso and stomach pressed against the front side of the preacher bench.","Make sure that your feet (especially the toes) are well positioned on the floor and place your upper arms on top of the pad located on the inside part of the preacher bench.","Use your arms to grab the barbell with a supinated grip (palms facing up) at about shoulder width apart or slightly closer from each other.","Slowly begin to lift the barbell upwards and exhale. Hold the contracted position for a second as you squeeze the biceps.","Slowly begin to bring the barbell back to the starting position as your breathe in. .","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Spider_Curl/0.jpg","Spider_Curl/1.jpg"],"id":"Spider_Curl"}'),
('free-exercise-db', 'Spinal_Stretch', 'spinal-stretch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Spinal_Stretch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Spinal Stretch","force":"static","level":"beginner","mechanic":"isolation","equipment":null,"primaryMuscles":["middle back"],"secondaryMuscles":["lats","lower back","neck","traps"],"instructions":["Sit in a chair so your back is straight and your feet planted on the floor.","Interlace your fingers behind your head, elbows out and your chin down.","Twist your upper body to one side about 3 times as far as you can. Then lean forward and twist your torso to reach your elbow to the floor on the inside of your knee.","Return to upright position and then repeat for your other side."],"category":"stretching","images":["Spinal_Stretch/0.jpg","Spinal_Stretch/1.jpg"],"id":"Spinal_Stretch"}'),
('free-exercise-db', 'Split_Clean', 'barbell-split-clean', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Split_Clean.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Split Clean","force":"pull","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","forearms","glutes","hamstrings","lower back","shoulders","traps"],"instructions":["With a barbell on the floor close to the shins, take an overhand grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.","Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees.","Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended.","As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, aggressively pull yourself down, rotating your elbows under the bar as you do so.","Receive the bar with the feet split, aggressively moving one foot forward and one foot back. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom position, which will help in the recovery.","Immediately recover by driving through the heels, keeping the torso upright and elbows up. Bring the feet together as you stand up."],"category":"olympic weightlifting","images":["Split_Clean/0.jpg","Split_Clean/1.jpg"],"id":"Split_Clean"}'),
('free-exercise-db', 'Split_Jerk', 'barbell-split-jerk', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Split_Jerk.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Split Jerk","force":"push","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["glutes","hamstrings","shoulders","triceps"],"instructions":["Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward.","Go down only slightly, and reverse direction as powerfully as possible. Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders. At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as possible.","In the brief moment the feet are not actively driving against the platform, the athlete''s effort to push the bar up will drive them down. The feet should be moved to a split stance, one foot forward, one foot back, with the knees partially bent. Receive the bar with the arms locked out overhead.","Return to a standing position, bringing the feet together."],"category":"olympic weightlifting","images":["Split_Jerk/0.jpg","Split_Jerk/1.jpg"],"id":"Split_Jerk"}'),
('free-exercise-db', 'Split_Jump', 'split-jump', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Split_Jump.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Split Jump","force":"push","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings"],"instructions":["Assume a lunge stance position with one foot forward with the knee bent, and the rear knee nearly touching the ground.","Ensure that the front knee is over the midline of the foot.","Extending through both legs, jump as high as possible, swinging your arms to gain lift.","As you jump, bring your feet together, and move them back to their initial positions as you land.","Absorb the impact by reverting back to the starting position."],"category":"plyometrics","images":["Split_Jump/0.jpg","Split_Jump/1.jpg"],"id":"Split_Jump"}'),
('free-exercise-db', 'Split_Snatch', 'barbell-split-snatch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Split_Snatch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Split Snatch","force":"pull","level":"expert","mechanic":"compound","equipment":"barbell","primaryMuscles":["hamstrings"],"secondaryMuscles":["calves","forearms","glutes","hamstrings","lower back","quadriceps","shoulders","traps","triceps"],"instructions":["Begin with a loaded barbell on the floor. The bar should be close to or touching the shins, and a wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar. This will be the starting position.","Begin the first pull by driving through the front of the heels, raising the bar from the ground. The back angle should stay the same until the bar passes the knees.","Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body. At peak extension, shrug the shoulders and allow the elbows to flex to the side.","As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. The feet should move forcefully to a split position, one foot forward one foot back. Receive the bar with your body as low as possible and the arms fully extended overhead.","Keeping the bar aligned over the front of the heels, your head and chest up, drive through heels of the feet to move to a standing position, bringing your feet together.","Carefully return the weight to floor."],"category":"olympic weightlifting","images":["Split_Snatch/0.jpg","Split_Snatch/1.jpg"],"id":"Split_Snatch"}'),
('free-exercise-db', 'Split_Squat_with_Dumbbells', 'dumbbell-split-squat', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Split_Squat_with_Dumbbells.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Split Squat with Dumbbells","force":"push","level":"beginner","mechanic":"compound","equipment":"dumbbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["glutes","hamstrings"],"instructions":["Position yourself into a staggered stance with the rear foot elevated and front foot forward.","Hold a dumbbell in each hand, letting them hang at the sides. This will be your starting position.","Begin by descending, flexing your knee and hip to lower your body down. Maintain good posture througout the movement. Keep the front knee in line with the foot as you perform the exercise.","At the bottom of the movement, drive through the heel to extend the knee and hip to return to the starting position."],"category":"strength","images":["Split_Squat_with_Dumbbells/0.jpg","Split_Squat_with_Dumbbells/1.jpg"],"id":"Split_Squat_with_Dumbbells"}'),
('free-exercise-db', 'Split_Squats', 'split-squat', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Split_Squats.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Split Squats","force":"push","level":"intermediate","mechanic":null,"equipment":null,"primaryMuscles":["hamstrings"],"secondaryMuscles":["calves","glutes","quadriceps"],"instructions":["Being in a standing position. Jump into a split leg position, with one leg forward and one leg back, flexing the knees and lowering your hips slightly as you do so.","As you descend, immediately reverse direction, standing back up and jumping, reversing the position of your legs. Repeat 5-10 times on each leg."],"category":"stretching","images":["Split_Squats/0.jpg","Split_Squats/1.jpg"],"id":"Split_Squats"}'),
('free-exercise-db', 'Squat_Jerk', 'barbell-squat-jerk', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Squat_Jerk.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Squat Jerk","force":"push","level":"expert","mechanic":"compound","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings","shoulders","triceps"],"instructions":["Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible. Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders.","At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as possible. In the brief moment the feet are not actively driving against the platform, the athlete''s effort to push the bar up will drive them down. The feet should move forcefully to just outside the hips, turned out as necessary. Receive the bar with your body in a full squat and the arms fully extended overhead.","Keeping the bar aligned over the front of the heels, your head and chest up, drive throught heels of the feet to move to a standing position. Carefully return the weight to floor."],"category":"strength","images":["Squat_Jerk/0.jpg","Squat_Jerk/1.jpg"],"id":"Squat_Jerk"}'),
('free-exercise-db', 'Squat_with_Bands', 'band-squat', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Squat_with_Bands.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Squat with Bands","force":"push","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["adductors","calves","glutes","hamstrings","lower back"],"instructions":["Set up the bands on the sleeves, secured to either band pegs, the rack, or dumbbells so that there is appropriate tension.","Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wide for more emphasis on the back, glutes, adductors, and hamstrings. Keep your head facing forward.","With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips as much as possible. Ideally, your shins should be perpendicular to the ground. Lower bar position necessitates a greater torso lean to keep the bar over the heels. Continue until you break parallel, which is defined as the crease of the hip being in line with the top of the knee.","Keeping the weight on your heels and pushing your feet and knees out, drive upward as you lead the movement with your head. Continue upward, maintaining tightness head to toe, until you have returned to the starting position."],"category":"powerlifting","images":["Squat_with_Bands/0.jpg","Squat_with_Bands/1.jpg"],"id":"Squat_with_Bands"}'),
('free-exercise-db', 'Squat_with_Chains', 'barbell-squat-chains', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Squat_with_Chains.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Squat with Chains","force":"push","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["adductors","calves","glutes","hamstrings","lower back"],"instructions":["To set up the chains, begin by looping the leader chain over the sleeves of the bar. The heavy chain should be attached using a snap hook. Adjust the length of the lead chain so that a few links are still on the floor at the top of the movement.","Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wide for more emphasis on the back, glutes, adductors, and hamstrings. Keep your head facing forward.","With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips as much as possible. Ideally, your shins should be perpendicular to the ground. Lower bar position necessitates a greater torso lean to keep the bar over the heels. Continue until you break parallel, which is defined as the crease of the hip being in line with the top of the knee.","Keeping the weight on your heels and pushing your feet and knees out, drive upward as you lead the movement with your head. Continue upward, maintaining tightness head to toe, until you have returned to the starting position."],"category":"powerlifting","images":["Squat_with_Chains/0.jpg","Squat_with_Chains/1.jpg"],"id":"Squat_with_Chains"}'),
('free-exercise-db', 'Squat_with_Plate_Movers', 'plate-squat-movers', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Squat_with_Plate_Movers.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Squat with Plate Movers","force":"push","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["abductors","adductors","calves","glutes","hamstrings"],"instructions":["To begin, first set the bar on a rack to just below shoulder level. Position a weight plate on the ground a couple feet back from the rack. Once the bar is loaded, step under it and place the back of your shoulders across it.","Hold on to the bar with both hands and lift it off the rack by first pushing with your legs and at the same time straighten your torso.","Step away from the rack and adopt a wide stance with the toes slightly pointed out, with one foot on the weight plate. Keep your head up at all times. This will be your starting position.","Begin to slowly lower the bar by bending the knees and hips. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees.","Raise the bar as you exhale by pushing the floor with the heels of your feet as you extend the hips and knees.","At the top of the movement, side step, bringing your feet together on the opposite side of the plate.","Using your inside foot, push the weight plate, sliding it across the floor to where you were just standing.","Place your inside foot on the weight plate, adopting a wide stance for the next repetition."],"category":"strength","images":["Squat_with_Plate_Movers/0.jpg","Squat_with_Plate_Movers/1.jpg"],"id":"Squat_with_Plate_Movers"}'),
('free-exercise-db', 'Squats_-_With_Bands', 'band-squat-2', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Squats_-_With_Bands.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Squats - With Bands","force":"push","level":"beginner","mechanic":"compound","equipment":"bands","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings","lower back"],"instructions":["To start out, make sure that the exercise band is at an even split between both the left and right side of the body. To do this, use your hands to grab both sides of the band and place both feet in the middle of the band. Your feet should be shoulder width apart from each other.","When holding the bands, they should be the same height on each side. You should be using a pronated grip (palms facing forward) and have the handles of the bands next to your face for this exercise. This is the starting position.","Slowly start to bend the knees and lower the legs so that your thighs are parallel to the floor while exhaling.","Use the heel of your feet to push your body up to the starting position as you exhale.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Squats_-_With_Bands/0.jpg","Squats_-_With_Bands/1.jpg"],"id":"Squats_-_With_Bands"}'),
('free-exercise-db', 'Stairmaster', 'machine-stairmaster', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Stairmaster.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Stairmaster","force":null,"level":"intermediate","mechanic":null,"equipment":"machine","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings"],"instructions":["To begin, step onto the stairmaster and select the desired option from the menu. You can choose a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise.","Pump your legs up and down in an established rhythm, driving the pedals down but not all the way to the floor. It is recommended that you maintain your grip on the handles so that you don''t fall. The handles can be used to monitor your heart rate to help you stay at an appropriate intensity.","Stairmasters offer convenience, cardiovascular benefits, and usually have less impact than running outside. They are typically much harder than other cardio equipment. A 150 lb person will typically burn over 300 calories in 30 minutes, compared to about 175 calories walking."],"category":"cardio","images":["Stairmaster/0.jpg","Stairmaster/1.jpg"],"id":"Stairmaster"}'),
('free-exercise-db', 'Standing_Alternating_Dumbbell_Press', 'dumbbell-standing-alternating-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Standing_Alternating_Dumbbell_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Standing Alternating Dumbbell Press","force":"push","level":"beginner","mechanic":"compound","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":["triceps"],"instructions":["Stand with a dumbbell in each hand. Raise the dumbbells to your shoulders with your palms facing forward and your elbows pointed out. This will be your starting position.","Extend one arm to press the dumbbell straight up, keeping your off hand in place. Do not lean or jerk the weight during the movement.","After a brief pause, return the weight to the starting position.","Repeat for the opposite side, continuing to alternate between arms."],"category":"strength","images":["Standing_Alternating_Dumbbell_Press/0.jpg","Standing_Alternating_Dumbbell_Press/1.jpg"],"id":"Standing_Alternating_Dumbbell_Press"}'),
('free-exercise-db', 'Standing_Barbell_Calf_Raise', 'barbell-standing-calf-raise', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Standing_Barbell_Calf_Raise.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Standing Barbell Calf Raise","force":"push","level":"beginner","mechanic":"isolation","equipment":"barbell","primaryMuscles":["calves"],"secondaryMuscles":[],"instructions":["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the bar on the back of your shoulders (slightly below the neck).","Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.","Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. The knees should be kept with a slight bend; never locked. This will be your starting position. Tip: For better range of motion you may also place the ball of your feet on a wooden block but be careful as this option requires more balance and a sturdy block.","Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.","Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Standing_Barbell_Calf_Raise/0.jpg","Standing_Barbell_Calf_Raise/1.jpg"],"id":"Standing_Barbell_Calf_Raise"}'),
('free-exercise-db', 'Standing_Barbell_Press_Behind_Neck', 'barbell-standing-press-behind-neck', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Standing_Barbell_Press_Behind_Neck.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Standing Barbell Press Behind Neck","force":"push","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["shoulders"],"secondaryMuscles":["triceps"],"instructions":["This exercise is best performed inside a squat rack for easier pick up of the bar. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.","Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.","Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Your back should be kept straight while performing this exercise. This will be your starting position.","Elevate the barbell overhead by fully extending your arms while breathing out.","Hold the contraction for a second and lower the barbell back down to the starting position by inhaling.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Standing_Barbell_Press_Behind_Neck/0.jpg","Standing_Barbell_Press_Behind_Neck/1.jpg"],"id":"Standing_Barbell_Press_Behind_Neck"}'),
('free-exercise-db', 'Standing_Bent-Over_One-Arm_Dumbbell_Triceps_Extension', 'dumbbell-standing-bent-over-one-arm-triceps-extension', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Standing_Bent-Over_One-Arm_Dumbbell_Triceps_Extension.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Standing Bent-Over One-Arm Dumbbell Triceps Extension","force":"push","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["triceps"],"secondaryMuscles":["shoulders"],"instructions":["With a dumbbell in one hand and the palm facing your torso, bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Make sure that you keep the head up.","The upper arm should be close to the torso and parallel to the floor while the forearm is pointing towards the floor as the hand holds the weight. Tip: There should be a 90-degree angle between the forearm and the upper arm. This is your starting position.","Keeping the upper arms stationary, use the triceps to lift the weights as you exhale until the forearms are parallel to the floor and the whole arm is extended. Like many other arm exercises, only the forearm moves.","After a second contraction at the top, slowly lower the dumbbell back to the starting position as you inhale.","Repeat the movement for the prescribed amount of repetitions.","Switch arms and repeat the exercise."],"category":"strength","images":["Standing_Bent-Over_One-Arm_Dumbbell_Triceps_Extension/0.jpg","Standing_Bent-Over_One-Arm_Dumbbell_Triceps_Extension/1.jpg"],"id":"Standing_Bent-Over_One-Arm_Dumbbell_Triceps_Extension"}'),
('free-exercise-db', 'Standing_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension', 'dumbbell-standing-bent-over-two-arm-triceps-extension', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Standing_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Standing Bent-Over Two-Arm Dumbbell Triceps Extension","force":"push","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["triceps"],"secondaryMuscles":[],"instructions":["With a dumbbell in each hand and the palms facing your torso, bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Make sure that you keep the head up. The upper arms should be close to the torso and parallel to the floor while the forearms are pointing towards the floor as the hands hold the weights. Tip: There should be a 90-degree angle between the forearms and the upper arm. This is your starting position.","Keeping the upper arms stationary, use the triceps to lift the weights as you exhale until the forearms are parallel to the floor and the whole arms are extended. Like many other arm exercises, only the forearm moves.","After a second contraction at the top, slowly lower the dumbbells back to their starting position as you inhale.","Repeat the movement for the prescribed amount of repetitions."],"category":"strength","images":["Standing_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension/0.jpg","Standing_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension/1.jpg"],"id":"Standing_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension"}'),
('free-exercise-db', 'Standing_Biceps_Cable_Curl', 'cable-standing-biceps-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Standing_Biceps_Cable_Curl.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Standing Biceps Cable Curl","force":"pull","level":"beginner","mechanic":"isolation","equipment":"cable","primaryMuscles":["biceps"],"secondaryMuscles":[],"instructions":["Stand up with your torso upright while holding a cable curl bar that is attached to a low pulley. Grab the cable bar at shoulder width and keep the elbows close to the torso. The palm of your hands should be facing up (supinated grip). This will be your starting position.","While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second as you squeeze the muscle.","Slowly begin to bring the curl bar back to starting position as your breathe in.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Standing_Biceps_Cable_Curl/0.jpg","Standing_Biceps_Cable_Curl/1.jpg"],"id":"Standing_Biceps_Cable_Curl"}'),
('free-exercise-db', 'Standing_Biceps_Stretch', 'standing-biceps-stretch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Standing_Biceps_Stretch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Standing Biceps Stretch","force":"static","level":"beginner","mechanic":"isolation","equipment":"other","primaryMuscles":["biceps"],"secondaryMuscles":["chest","shoulders"],"instructions":["Clasp your hands behind your back with your palms together, straighten arms and then rotate them so your palms face downward.","Raise your arms up and hold until you feel a stretch in your biceps."],"category":"stretching","images":["Standing_Biceps_Stretch/0.jpg","Standing_Biceps_Stretch/1.jpg"],"id":"Standing_Biceps_Stretch"}'),
('free-exercise-db', 'Standing_Bradford_Press', 'barbell-standing-bradford-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Standing_Bradford_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Standing Bradford Press","force":"push","level":"beginner","mechanic":"compound","equipment":"barbell","primaryMuscles":["shoulders"],"secondaryMuscles":["triceps"],"instructions":["Place a loaded bar at shoulder level in a rack. With a pronated grip at shoulder width, begin with the bar racked across the front of your shoulders. This is your starting position.","Initiate the lift by extending the elbows to press the bar overhead. Avoid locking out the elbow as you move the weight behind your head.","Lower the bar down to the back of the head until your elbow forms a right angle.","Lift the bar back over your head by extending the elbows","Lower the bar down to the starting position.","Alternate in this manner until you complete the recommended amount of repetitions."],"category":"strength","images":["Standing_Bradford_Press/0.jpg","Standing_Bradford_Press/1.jpg"],"id":"Standing_Bradford_Press"}'),
('free-exercise-db', 'Standing_Cable_Chest_Press', 'cable-standing-chest-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Standing_Cable_Chest_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Standing Cable Chest Press","force":"push","level":"beginner","mechanic":"compound","equipment":"cable","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["Position dual pulleys to chest height and select an appropriate weight. Stand a foot or two in front of the cables, holding one in each hand. You can stagger your stance for better stability.","Position the upper arm at a 90 degree angle with the shoulder blades together. This will be your starting position.","Keeping the rest of the body stationary, extend through the elbows to press the handles forward, drawing them together in front of you.","Pause at the top of the motion, and return to the starting position."],"category":"strength","images":["Standing_Cable_Chest_Press/0.jpg","Standing_Cable_Chest_Press/1.jpg"],"id":"Standing_Cable_Chest_Press"}'),
('free-exercise-db', 'Standing_Cable_Lift', 'cable-standing-lift', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Standing_Cable_Lift.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Standing Cable Lift","force":"pull","level":"beginner","mechanic":"compound","equipment":"cable","primaryMuscles":["abdominals"],"secondaryMuscles":["shoulders"],"instructions":["Connect a standard handle on a tower, and move the cable to the lowest pulley position.","With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable. Your outstretched arm should be aligned with the cable.","With your feet positioned shoulder width apart, squat down and grab the handle with both hands. Your arms should still be fully extended.","In one motion, pull the handle up and across your body until your arms are in a fully-extended position above your head.","Keep your back straight and your arms close to your body as you pivot your back foot and straighten your legs to get a full range of motion.","Retract your arms and then your body. Return to the neutral position in a slow and controlled manner.","Repeat to failure.","Then, reposition and repeat the same series of movements on the opposite side."],"category":"strength","images":["Standing_Cable_Lift/0.jpg","Standing_Cable_Lift/1.jpg"],"id":"Standing_Cable_Lift"}'),
('free-exercise-db', 'Standing_Cable_Wood_Chop', 'cable-standing-wood-chop', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Standing_Cable_Wood_Chop.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Standing Cable Wood Chop","force":"pull","level":"beginner","mechanic":"compound","equipment":"cable","primaryMuscles":["abdominals"],"secondaryMuscles":["shoulders"],"instructions":["Connect a standard handle to a tower, and move the cable to the highest pulley position.","With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable. Your outstretched arm should be aligned with the cable.","With your feet positioned shoulder width apart, reach upward with your other hand and grab the handle with both hands. Your arms should still be fully extended.","In one motion, pull the handle down and across your body to your front knee while rotating your torso.","Keep your back and arms straight and core tight while you pivot your back foot and bend your knees to get a full range of motion.","Maintain your stance and straight arms. Return to the neutral position in a slow and controlled manner.","Repeat to failure.","Then, reposition and repeat the same series of movements on the opposite side."],"category":"strength","images":["Standing_Cable_Wood_Chop/0.jpg","Standing_Cable_Wood_Chop/1.jpg"],"id":"Standing_Cable_Wood_Chop"}'),
('free-exercise-db', 'Standing_Calf_Raises', 'machine-standing-calf-raise', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Standing_Calf_Raises.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Standing Calf Raises","force":"push","level":"beginner","mechanic":"isolation","equipment":"machine","primaryMuscles":["calves"],"secondaryMuscles":[],"instructions":["Adjust the padded lever of the calf raise machine to fit your height.","Place your shoulders under the pads provided and position your toes facing forward (or using any of the two other positions described at the beginning of the chapter). The balls of your feet should be secured on top of the calf block with the heels extending off it. Push the lever up by extending your hips and knees until your torso is standing erect. The knees should be kept with a slight bend; never locked. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter. This will be your starting position.","Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.","Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Standing_Calf_Raises/0.jpg","Standing_Calf_Raises/1.jpg"],"id":"Standing_Calf_Raises"}'),
('free-exercise-db', 'Standing_Concentration_Curl', 'dumbbell-standing-concentration-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Standing_Concentration_Curl.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Standing Concentration Curl","force":"pull","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["biceps"],"secondaryMuscles":["forearms"],"instructions":["Taking a dumbbell in your working hand, lean forward. Allow your working arm to hang perpendicular to the ground with the elbow pointing out. This will be your starting position.","Flex the elbow to curl the weight, keeping the upper arm stationary. At the top of the repetition, flex the biceps and pause.","Lower the dumbbell back to the starting position.","Repeat the movement for the prescribed amount of repetitions."],"category":"strength","images":["Standing_Concentration_Curl/0.jpg","Standing_Concentration_Curl/1.jpg"],"id":"Standing_Concentration_Curl"}'),
('free-exercise-db', 'Standing_Dumbbell_Calf_Raise', 'dumbbell-standing-calf-raise', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Standing_Dumbbell_Calf_Raise.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Standing Dumbbell Calf Raise","force":"push","level":"intermediate","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["calves"],"secondaryMuscles":[],"instructions":["Stand with your torso upright holding two dumbbells in your hands by your sides. Place the ball of the foot on a sturdy and stable wooden board (that is around 2-3 inches tall) while your heels extend off and touch the floor. This will be your starting position.","With the toes pointing either straight (to hit all parts equally), inwards (for emphasis on the outer head) or outwards (for emphasis on the inner head), raise the heels off the floor as you exhale by contracting the calves. Hold the top contraction for a second.","As you inhale, go back to the starting position by slowly lowering the heels.","Repeat for the recommended amount of times."],"category":"strength","images":["Standing_Dumbbell_Calf_Raise/0.jpg","Standing_Dumbbell_Calf_Raise/1.jpg"],"id":"Standing_Dumbbell_Calf_Raise"}'),
('free-exercise-db', 'Standing_Dumbbell_Press', 'dumbbell-standing-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Standing_Dumbbell_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Standing Dumbbell Press","force":"push","level":"beginner","mechanic":"compound","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":["triceps"],"instructions":["Standing with your feet shoulder width apart, take a dumbbell in each hand. Raise the dumbbells to head height, the elbows out and about 90 degrees. This will be your starting position.","Maintaining strict technique with no leg drive or leaning back, extend through the elbow to raise the weights together directly above your head.","Pause, and slowly return the weight to the starting position."],"category":"strength","images":["Standing_Dumbbell_Press/0.jpg","Standing_Dumbbell_Press/1.jpg"],"id":"Standing_Dumbbell_Press"}'),
('free-exercise-db', 'Standing_Dumbbell_Reverse_Curl', 'dumbbell-standing-reverse-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Standing_Dumbbell_Reverse_Curl.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Standing Dumbbell Reverse Curl","force":"pull","level":"intermediate","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["biceps"],"secondaryMuscles":["forearms"],"instructions":["To begin, stand straight with a dumbbell in each hand using a pronated grip (palms facing down). Your arms should be fully extended while your feet are shoulder width apart from each other. This is the starting position.","While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the muscle.","Slowly begin to bring the dumbbells back to starting position as your breathe in.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Standing_Dumbbell_Reverse_Curl/0.jpg","Standing_Dumbbell_Reverse_Curl/1.jpg"],"id":"Standing_Dumbbell_Reverse_Curl"}'),
('free-exercise-db', 'Standing_Dumbbell_Straight-Arm_Front_Delt_Raise_Above_Head', 'dumbbell-standing-straight-arm-front-delt-raise-above-head', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Standing_Dumbbell_Straight-Arm_Front_Delt_Raise_Above_Head.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Standing Dumbbell Straight-Arm Front Delt Raise Above Head","force":"push","level":"intermediate","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":[],"instructions":["Hold the dumbbells in front of your thighs, palms facing your thighs.","Keep your arms straight with a slight bend at the elbows but keep them locked. This will be your starting position.","Raise the dumbbells in a semicircular motion to arm''s length overhead as you exhale.","Slowly return to the starting position using the same path as you inhale.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Standing_Dumbbell_Straight-Arm_Front_Delt_Raise_Above_Head/0.jpg","Standing_Dumbbell_Straight-Arm_Front_Delt_Raise_Above_Head/1.jpg"],"id":"Standing_Dumbbell_Straight-Arm_Front_Delt_Raise_Above_Head"}'),
('free-exercise-db', 'Standing_Dumbbell_Triceps_Extension', 'dumbbell-standing-triceps-extension', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Standing_Dumbbell_Triceps_Extension.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Standing Dumbbell Triceps Extension","force":"push","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["triceps"],"secondaryMuscles":[],"instructions":["To begin, stand up with a dumbbell held by both hands. Your feet should be about shoulder width apart from each other. Slowly use both hands to grab the dumbbell and lift it over your head until both arms are fully extended.","The resistance should be resting in the palms of your hands with your thumbs around it. The palm of the hands should be facing up towards the ceiling. This will be your starting position.","Keeping your upper arms close to your head with elbows in and perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.","Go back to the starting position by using the triceps to raise the dumbbell. Breathe out as you perform this step.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Standing_Dumbbell_Triceps_Extension/0.jpg","Standing_Dumbbell_Triceps_Extension/1.jpg"],"id":"Standing_Dumbbell_Triceps_Extension"}'),
('free-exercise-db', 'Standing_Dumbbell_Upright_Row', 'dumbbell-standing-upright-row', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Standing_Dumbbell_Upright_Row.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Standing Dumbbell Upright Row","force":"pull","level":"beginner","mechanic":"compound","equipment":"dumbbell","primaryMuscles":["traps"],"secondaryMuscles":["biceps","shoulders"],"instructions":["Grasp a dumbbell in each hand with a pronated (palms forward) grip that is slightly less than shoulder width. The dumbbells should be resting on top of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position.","Use your side shoulders to lift the dumbbells as you exhale. The dumbbells should be close to the body as you move it up and the elbows should drive the motion. Continue to lift them until they nearly touch your chin. Tip: Your elbows should drive the motion. As you lift the dumbbells, your elbows should always be higher than your forearms. Also, keep your torso stationary and pause for a second at the top of the movement.","Lower the dumbbells back down slowly to the starting position. Inhale as you perform this portion of the movement.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Standing_Dumbbell_Upright_Row/0.jpg","Standing_Dumbbell_Upright_Row/1.jpg"],"id":"Standing_Dumbbell_Upright_Row"}'),
('free-exercise-db', 'Standing_Elevated_Quad_Stretch', 'standing-elevated-quad-stretch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Standing_Elevated_Quad_Stretch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Standing Elevated Quad Stretch","force":"static","level":"beginner","mechanic":null,"equipment":"other","primaryMuscles":["quadriceps"],"secondaryMuscles":[],"instructions":["Start by standing with your back about two to three feet away from a bench or step.","Lift one leg behind you and rest your foot on the step,either on your instep or the ball of your foot, whichever you find most comfortable.","Keep your supporting knee slightly bent and avoid letting that knee extend out beyond your toes. Switch sides."],"category":"stretching","images":["Standing_Elevated_Quad_Stretch/0.jpg","Standing_Elevated_Quad_Stretch/1.jpg"],"id":"Standing_Elevated_Quad_Stretch"}'),
('free-exercise-db', 'Standing_Front_Barbell_Raise_Over_Head', 'barbell-standing-front-raise-over-head', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Standing_Front_Barbell_Raise_Over_Head.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Standing Front Barbell Raise Over Head","force":"push","level":"intermediate","mechanic":"isolation","equipment":"barbell","primaryMuscles":["shoulders"],"secondaryMuscles":[],"instructions":["To begin, stand straight with a barbell in your hands. You should grip the bar with palms facing down and a closer than shoulder width grip apart from each other.","Your feet should be shoulder width apart from each other. Your elbows should be slightly bent. This is the starting position.","Lift the barbell up until it is directly over your head while exhaling. Make sure to keep your elbows slightly bent when performing each repetition.","Once you feel the contraction, begin to lower the barbell back down to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Standing_Front_Barbell_Raise_Over_Head/0.jpg","Standing_Front_Barbell_Raise_Over_Head/1.jpg"],"id":"Standing_Front_Barbell_Raise_Over_Head"}'),
('free-exercise-db', 'Standing_Gastrocnemius_Calf_Stretch', 'standing-gastrocnemius-calf-stretch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Standing_Gastrocnemius_Calf_Stretch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Standing Gastrocnemius Calf Stretch","force":"static","level":"beginner","mechanic":null,"equipment":null,"primaryMuscles":["calves"],"secondaryMuscles":["hamstrings"],"instructions":["Place your right heel on a step with your knee extended and lean forward to grab your right toe with your right hand. Your left knee should be slightly bent and your back should be straight.","Support your weight on your left leg and place your left hand on your left thigh.","Pull your right toes toward your knee until you feel a stretch in your calf."],"category":"stretching","images":["Standing_Gastrocnemius_Calf_Stretch/0.jpg","Standing_Gastrocnemius_Calf_Stretch/1.jpg"],"id":"Standing_Gastrocnemius_Calf_Stretch"}'),
('free-exercise-db', 'Standing_Hamstring_and_Calf_Stretch', 'standing-hamstring-and-calf-stretch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Standing_Hamstring_and_Calf_Stretch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Standing Hamstring and Calf Stretch","force":"static","level":"beginner","mechanic":null,"equipment":"other","primaryMuscles":["hamstrings"],"secondaryMuscles":[],"instructions":["Being by looping a belt, band, or rope around one foot. While standing, place that foot forward.","Bend your back leg, while keeping the front one straight. Now raise the toes of your front foot off of the ground and lean forward.","Using the belt, pull on the top of the foot to increase the stretch in the calf. Hold for 10-20 seconds and repeat with the other foot."],"category":"stretching","images":["Standing_Hamstring_and_Calf_Stretch/0.jpg","Standing_Hamstring_and_Calf_Stretch/1.jpg"],"id":"Standing_Hamstring_and_Calf_Stretch"}'),
('free-exercise-db', 'Standing_Hip_Circles', 'standing-hip-circle', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Standing_Hip_Circles.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Standing Hip Circles","force":"pull","level":"beginner","mechanic":"isolation","equipment":"body only","primaryMuscles":["abductors"],"secondaryMuscles":["adductors"],"instructions":["Begin standing on one leg, holding to a vertical support.","Raise the unsupported knee to 90 degrees. This will be your starting position.","Open the hip as far as possible, attempting to make a big circle with your knee.","Perform this movement slowly for a number of repetitions, and repeat on the other side."],"category":"stretching","images":["Standing_Hip_Circles/0.jpg","Standing_Hip_Circles/1.jpg"],"id":"Standing_Hip_Circles"}'),
('free-exercise-db', 'Standing_Hip_Flexors', 'standing-hip-flexors', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Standing_Hip_Flexors.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Standing Hip Flexors","force":"static","level":"beginner","mechanic":"isolation","equipment":null,"primaryMuscles":["quadriceps"],"secondaryMuscles":[],"instructions":["Stand up straight with the spine vertical, the left foot slightly in front of the right.","Bend both knees and lift the back heel off the floor as you press the right hip forward. You can''t get a thorough, deep stretch in this position, however, because it''s hard to relax the hip flexor and stand on it at the same time. Switch sides."],"category":"stretching","images":["Standing_Hip_Flexors/0.jpg","Standing_Hip_Flexors/1.jpg"],"id":"Standing_Hip_Flexors"}'),
('free-exercise-db', 'Standing_Inner-Biceps_Curl', 'dumbbell-standing-inner-biceps-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Standing_Inner-Biceps_Curl.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Standing Inner-Biceps Curl","force":"pull","level":"intermediate","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["biceps"],"secondaryMuscles":[],"instructions":["Stand up with a dumbbell in each hand being held at arms length. The elbows should be close to the torso. Your legs should be at about shoulder''s width apart from each other.","Rotate the palms of the hands so that they are facing inward in a neutral position. This will be your starting position.","While holding the upper arms stationary, curl the weights out while contracting the biceps as you breathe out. Your wrist should turn so that when the weights are fully elevated you have supinated grip (palms facing up).","Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Tip: Keep the forearms aligned with your outer deltoids.","Hold the contracted position for a second as you squeeze the biceps.","Slowly begin to bring the dumbbells back to the starting position as your breathe in. Remember to rotate the wrists as you lower the weight in order to switch back to a neutral grip.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Standing_Inner-Biceps_Curl/0.jpg","Standing_Inner-Biceps_Curl/1.jpg"],"id":"Standing_Inner-Biceps_Curl"}'),
('free-exercise-db', 'Standing_Lateral_Stretch', 'standing-lateral-stretch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Standing_Lateral_Stretch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Standing Lateral Stretch","force":"static","level":"beginner","mechanic":null,"equipment":null,"primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Take a slightly wider than hip distance stance with your knees slightly bent.","Place your right hand on your right hip to support the spine.","Raise your left arm in a vertical line and place your left hand behind your head. Keep it there as you incline your torso to the right.","Keep your weight evenly distributed between both legs (don''t lean into your left hip). Switch sides."],"category":"stretching","images":["Standing_Lateral_Stretch/0.jpg","Standing_Lateral_Stretch/1.jpg"],"id":"Standing_Lateral_Stretch"}'),
('free-exercise-db', 'Standing_Leg_Curl', 'machine-standing-leg-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Standing_Leg_Curl.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Standing Leg Curl","force":"pull","level":"beginner","mechanic":"isolation","equipment":"machine","primaryMuscles":["hamstrings"],"secondaryMuscles":[],"instructions":["Adjust the machine lever to fit your height and lie with your torso bent at the waist facing forward around 30-45 degrees (since an angled position is more favorable for hamstrings recruitment) with the pad of the lever on the back of your right leg (just a few inches under the calves) and the front of the right leg on top of the machine pad.","Keeping the torso bent forward, ensure your leg is fully stretched and grab the side handles of the machine. Position your toes straight. This will be your starting position.","As you exhale, curl your right leg up as far as possible without lifting the upper leg from the pad. Once you hit the fully contracted position, hold it for a second.","As you inhale, bring the legs back to the initial position. Repeat for the recommended amount of repetitions.","Perform the same exercise now for the left leg."],"category":"strength","images":["Standing_Leg_Curl/0.jpg","Standing_Leg_Curl/1.jpg"],"id":"Standing_Leg_Curl"}'),
('free-exercise-db', 'Standing_Long_Jump', 'standing-long-jump', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Standing_Long_Jump.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Standing Long Jump","force":"push","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings"],"instructions":["This drill is best done in sand or other soft landing surface. Ensure that you are able to measure distance. Stand in a partial squat stance with feet shoulder width apart.","Utilizing a big arm swing and a countermovement of the legs, jump forward as far as you can.","Attempt to land with your feet out in front you, reaching as far as possible with your legs.","Measure the distance from your landing point to the starting point and track results."],"category":"plyometrics","images":["Standing_Long_Jump/0.jpg","Standing_Long_Jump/1.jpg"],"id":"Standing_Long_Jump"}'),
('free-exercise-db', 'Standing_Low-Pulley_Deltoid_Raise', 'cable-standing-low-pulley-deltoid-raise', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Standing_Low-Pulley_Deltoid_Raise.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Standing Low-Pulley Deltoid Raise","force":"push","level":"beginner","mechanic":"isolation","equipment":"cable","primaryMuscles":["shoulders"],"secondaryMuscles":["forearms"],"instructions":["Start by standing to the right side of a low pulley row. Use your left hand to come across the body and grab a single handle attached to the low pulley with a pronated grip (palms facing down). Rest your arm in front of you. Your right hand should grab the machine for better support and balance.","Make sure that your back is erect and your feet are shoulder width apart from each other. This is the starting position.","Begin to use the left hand and come across your body out until it is elevated to shoulder height while exhaling.","Feel the contraction at the top for a second and begin to slowly lower the handle back down to the original starting position while inhaling.","Repeat for the recommended amount of repetitions.","Switch arms and repeat the exercise."],"category":"strength","images":["Standing_Low-Pulley_Deltoid_Raise/0.jpg","Standing_Low-Pulley_Deltoid_Raise/1.jpg"],"id":"Standing_Low-Pulley_Deltoid_Raise"}'),
('free-exercise-db', 'Standing_Low-Pulley_One-Arm_Triceps_Extension', 'cable-standing-low-pulley-one-arm-triceps-extension', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Standing_Low-Pulley_One-Arm_Triceps_Extension.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Standing Low-Pulley One-Arm Triceps Extension","force":"push","level":"intermediate","mechanic":"isolation","equipment":"cable","primaryMuscles":["triceps"],"secondaryMuscles":["chest","shoulders"],"instructions":["Grab a single handle with your left arm next to the low pulley machine. Turn away from the machine keeping the handle to the side of your body with your arm fully extended. Now use both hands to elevate the single handle directly above the head with the palm facing forward. Keep your upper arm completely vertical (perpendicular to the floor) and put your right hand on your left elbow to help keep it steady. This is the starting position.","Keeping your upper arms close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.","Go back to the starting position by using the triceps to raise the single handle. Breathe out as you perform this step.","Repeat for the recommended amount of repetitions.","Switch arms and repeat the exercise."],"category":"strength","images":["Standing_Low-Pulley_One-Arm_Triceps_Extension/0.jpg","Standing_Low-Pulley_One-Arm_Triceps_Extension/1.jpg"],"id":"Standing_Low-Pulley_One-Arm_Triceps_Extension"}'),
('free-exercise-db', 'Standing_Military_Press', 'barbell-standing-military-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Standing_Military_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Standing Military Press","force":"push","level":"beginner","mechanic":"compound","equipment":"barbell","primaryMuscles":["shoulders"],"secondaryMuscles":["triceps"],"instructions":["Start by placing a barbell that is about chest high on a squat rack. Once you have selected the weights, grab the barbell using a pronated (palms facing forward) grip. Make sure to grip the bar wider than shoulder width apart from each other.","Slightly bend the knees and place the barbell on your collar bone. Lift the barbell up keeping it lying on your chest. Take a step back and position your feet shoulder width apart from each other.","Once you pick up the barbell with the correct grip length, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.","Lower the bar down to the collarbone slowly as you inhale.","Lift the bar back up to the starting position as you exhale.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Standing_Military_Press/0.jpg","Standing_Military_Press/1.jpg"],"id":"Standing_Military_Press"}'),
('free-exercise-db', 'Standing_Olympic_Plate_Hand_Squeeze', 'plate-standing-olympic-hand-squeeze', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Standing_Olympic_Plate_Hand_Squeeze.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Standing Olympic Plate Hand Squeeze","force":"static","level":"beginner","mechanic":"isolation","equipment":"other","primaryMuscles":["forearms"],"secondaryMuscles":["biceps"],"instructions":["To begin, stand straight while holding a weight plate by the ridge at arm''s length in each hand using a neutral grip (palms facing in). You feet should be shoulder width apart from each other. This will be your starting position.","Lower the plates until the fingers are nearly extended but can still hold weights. Inhale as you lower the plates.","Now raise the plates back to the starting position as you exhale by closing your hands.","Repeat for the recommended amount of repetitions prescribed in your program."],"category":"strength","images":["Standing_Olympic_Plate_Hand_Squeeze/0.jpg","Standing_Olympic_Plate_Hand_Squeeze/1.jpg"],"id":"Standing_Olympic_Plate_Hand_Squeeze"}'),
('free-exercise-db', 'Standing_One-Arm_Cable_Curl', 'cable-standing-one-arm-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Standing_One-Arm_Cable_Curl.json', 'Unlicense', NULL, 'new', 88.9, '{"name":"Standing One-Arm Cable Curl","force":"pull","level":"intermediate","mechanic":"isolation","equipment":"cable","primaryMuscles":["biceps"],"secondaryMuscles":[],"instructions":["Start out by grabbing single handle next to the low pulley machine. Make sure you are far enough from the machine so that your arm is supporting the weight.","Make sure that your upper arm is stationary, perpendicular to the floor with elbows in and palms facing forward. Your non lifting arm should be grabbing your waist. This will allow you to keep your balance.","Slowly begin to curl the single handle upwards while keeping the upper arm stationary until your forearm touches your bicep while exhaling. Tip: Only the forearm should move.","Hold the contraction position as you squeeze the bicep and then lower the single handle back down to the starting position as you inhale.","Repeat for the recommended amount of repetitions.","Switch arms while performing this exercise."],"category":"strength","images":["Standing_One-Arm_Cable_Curl/0.jpg","Standing_One-Arm_Cable_Curl/1.jpg"],"id":"Standing_One-Arm_Cable_Curl"}'),
('free-exercise-db', 'Standing_One-Arm_Dumbbell_Curl_Over_Incline_Bench', 'dumbbell-standing-one-arm-curl-over-incline-bench', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Standing_One-Arm_Dumbbell_Curl_Over_Incline_Bench.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Standing One-Arm Dumbbell Curl Over Incline Bench","force":"pull","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["biceps"],"secondaryMuscles":[],"instructions":["Stand on the back side of an incline bench as if you were going to be a spotter for someone. Have a dumbbell in one hand and rest it across the incline bench with a supinated (palms up) grip.","Position your non lifting hand at the corner or side of the incline bench. The chest should be pressed against the top part of the incline and your feet should be pressed against the floor at a wide stance. This is the starting position.","While holding the upper arm stationary, curl the dumbbell upward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a second.","Slowly begin to bring the dumbbells back to starting position as your breathe in.","Repeat for the recommended amount of repetitions.","Switch arms while performing this exercise."],"category":"strength","images":["Standing_One-Arm_Dumbbell_Curl_Over_Incline_Bench/0.jpg","Standing_One-Arm_Dumbbell_Curl_Over_Incline_Bench/1.jpg"],"id":"Standing_One-Arm_Dumbbell_Curl_Over_Incline_Bench"}'),
('free-exercise-db', 'Standing_One-Arm_Dumbbell_Triceps_Extension', 'dumbbell-standing-one-arm-triceps-extension', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Standing_One-Arm_Dumbbell_Triceps_Extension.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Standing One-Arm Dumbbell Triceps Extension","force":"push","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["triceps"],"secondaryMuscles":["chest","shoulders"],"instructions":["To begin, stand up with a dumbbell held in one hand. Your feet should be about shoulder width apart from each other. Now fully extend the arm with the dumbbell over your head. Tip: The small finger of your hand should be facing the ceiling and the palm of your hand should be facing forward. The dumbbell should be above your head.","This will be your starting position.","Keeping your upper arm close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearm touch your bicep. Tip: The upper arm should remain stationary and only the forearm should move. Breathe in as you perform this step.","Go back to the starting position by using the triceps to raise the dumbbell. Breathe out as you perform this step.","Repeat for the recommended amount of repetitions.","Switch arms and repeat the exercise."],"category":"strength","images":["Standing_One-Arm_Dumbbell_Triceps_Extension/0.jpg","Standing_One-Arm_Dumbbell_Triceps_Extension/1.jpg"],"id":"Standing_One-Arm_Dumbbell_Triceps_Extension"}'),
('free-exercise-db', 'Standing_Overhead_Barbell_Triceps_Extension', 'barbell-standing-overhead-triceps-extension', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Standing_Overhead_Barbell_Triceps_Extension.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Standing Overhead Barbell Triceps Extension","force":"push","level":"beginner","mechanic":"isolation","equipment":"barbell","primaryMuscles":["triceps"],"secondaryMuscles":["shoulders"],"instructions":["To begin, stand up holding a barbell or e-z bar using a pronated grip (palms facing forward) with your hands closer than shoulder width apart from each other. Your feet should be about shoulder width apart.","Now elevate the barbell above your head until your arms are fully extended. Keep your elbows in. This will be your starting position.","Keeping your upper arms close to your head and elbows in, perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.","Go back to the starting position by using the triceps to raise the barbell. Breathe out as you perform this step.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Standing_Overhead_Barbell_Triceps_Extension/0.jpg","Standing_Overhead_Barbell_Triceps_Extension/1.jpg"],"id":"Standing_Overhead_Barbell_Triceps_Extension"}'),
('free-exercise-db', 'Standing_Palm-In_One-Arm_Dumbbell_Press', 'dumbbell-standing-palm-in-one-arm-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Standing_Palm-In_One-Arm_Dumbbell_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Standing Palm-In One-Arm Dumbbell Press","force":"push","level":"beginner","mechanic":"compound","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":["triceps"],"instructions":["Start by having a dumbbell in one hand with your arm fully extended to the side using a neutral grip. Use your other arm to hold on to an incline bench to keep your balance.","Your feet should be shoulder width apart from each other. Now slowly lift the dumbbell up until you create a 90 degree angle with your arm. Note: Your forearm should be perpendicular to the floor. Continue to maintain a neutral grip throughout the entire exercise.","Slowly lift the dumbbell up until your arm is fully extended. This the starting position.","While inhaling lower the weight down until your arm is at a 90 degree angle again.","Feel the contraction for a second and then lift the weight back up towards the starting position while exhaling. Remember to hold on to the incline bench and keep your feet positioned to keep balance during the exercise.","Repeat for the recommended amount of repetitions.","Switch arms and repeat the exercise."],"category":"strength","images":["Standing_Palm-In_One-Arm_Dumbbell_Press/0.jpg","Standing_Palm-In_One-Arm_Dumbbell_Press/1.jpg"],"id":"Standing_Palm-In_One-Arm_Dumbbell_Press"}'),
('free-exercise-db', 'Standing_Palms-In_Dumbbell_Press', 'dumbbell-standing-palms-in-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Standing_Palms-In_Dumbbell_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Standing Palms-In Dumbbell Press","force":"push","level":"intermediate","mechanic":"compound","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":["triceps"],"instructions":["Start by having a dumbbell in each hand with your arm fully extended to the side using a neutral grip. Your feet should be shoulder width apart from each other. Now slowly lift the dumbbells up until you create a 90 degree angle with your arms. Note: Your forearms should be perpendicular to the floor. This the starting position.","Continue to maintain a neutral grip throughout the entire exercise. Slowly lift the dumbbells up until your arms are fully extended.","While inhaling lower the weights down until your arm is at a 90 degree angle again.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Standing_Palms-In_Dumbbell_Press/0.jpg","Standing_Palms-In_Dumbbell_Press/1.jpg"],"id":"Standing_Palms-In_Dumbbell_Press"}'),
('free-exercise-db', 'Standing_Palms-Up_Barbell_Behind_The_Back_Wrist_Curl', 'barbell-standing-palms-up-behind-back-wrist-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Standing_Palms-Up_Barbell_Behind_The_Back_Wrist_Curl.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Standing Palms-Up Barbell Behind The Back Wrist Curl","force":"pull","level":"beginner","mechanic":"isolation","equipment":"barbell","primaryMuscles":["forearms"],"secondaryMuscles":[],"instructions":["Start by standing straight and holding a barbell behind your glutes at arm''s length while using a pronated grip (palms will be facing back away from the glutes) and having your hands shoulder width apart from each other.","You should be looking straight forward while your feet are shoulder width apart from each other. This is the starting position.","While exhaling, slowly elevate the barbell up by curling your wrist in a semi-circular motion towards the ceiling. Note: Your wrist should be the only body part moving for this exercise.","Hold the contraction for a second and lower the barbell back down to the starting position while inhaling.","Repeat for the recommended amount of repetitions.","When finished, lower the barbell down to the squat rack or the floor by bending the knees. Tip: It is easiest to either pick it up from a squat rack or have a partner hand it to you."],"category":"strength","images":["Standing_Palms-Up_Barbell_Behind_The_Back_Wrist_Curl/0.jpg","Standing_Palms-Up_Barbell_Behind_The_Back_Wrist_Curl/1.jpg"],"id":"Standing_Palms-Up_Barbell_Behind_The_Back_Wrist_Curl"}'),
('free-exercise-db', 'Standing_Pelvic_Tilt', 'standing-pelvic-tilt', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Standing_Pelvic_Tilt.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Standing Pelvic Tilt","force":"static","level":"beginner","mechanic":"isolation","equipment":null,"primaryMuscles":["lower back"],"secondaryMuscles":["glutes"],"instructions":["Start off with your feet hip-distance apart.","Bend your knees slightly to keep them soft and springy.","You may want to move your pelvis forward and backward and back few times before holding the tailbone forward in this stretch."],"category":"stretching","images":["Standing_Pelvic_Tilt/0.jpg","Standing_Pelvic_Tilt/1.jpg"],"id":"Standing_Pelvic_Tilt"}'),
('free-exercise-db', 'Standing_Rope_Crunch', 'cable-standing-rope-crunch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Standing_Rope_Crunch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Standing Rope Crunch","force":"pull","level":"beginner","mechanic":"isolation","equipment":"cable","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Attach a rope to a high pulley and select an appropriate weight.","Stand with your back to the cable tower. Take the rope with both hands over your shoulders, holding it to your upper chest. This will be your starting position.","Perform the movement by flexing the spine, crunching the weight down as far as you can.","Hold the peak contraction for a moment before returning to the starting position."],"category":"strength","images":["Standing_Rope_Crunch/0.jpg","Standing_Rope_Crunch/1.jpg"],"id":"Standing_Rope_Crunch"}'),
('free-exercise-db', 'Standing_Soleus_And_Achilles_Stretch', 'standing-soleus-and-achilles-stretch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Standing_Soleus_And_Achilles_Stretch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Standing Soleus And Achilles Stretch","force":"static","level":"beginner","mechanic":"isolation","equipment":null,"primaryMuscles":["calves"],"secondaryMuscles":[],"instructions":["Stand with your feet hip-distance apart, one foot slightly in front of the other.","Bend both knees, keeping your back heel on the floor. Switch sides."],"category":"stretching","images":["Standing_Soleus_And_Achilles_Stretch/0.jpg","Standing_Soleus_And_Achilles_Stretch/1.jpg"],"id":"Standing_Soleus_And_Achilles_Stretch"}'),
('free-exercise-db', 'Standing_Toe_Touches', 'standing-toe-touches', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Standing_Toe_Touches.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Standing Toe Touches","force":"static","level":"beginner","mechanic":null,"equipment":null,"primaryMuscles":["hamstrings"],"secondaryMuscles":["calves"],"instructions":["Stand with some space in front and behind you.","Bend at the waist, keeping your legs straight, until you can relax and let your upper body hang down in front of you. Let your arms and hands hang down naturally. Hold for 10 to 20 seconds."],"category":"stretching","images":["Standing_Toe_Touches/0.jpg","Standing_Toe_Touches/1.jpg"],"id":"Standing_Toe_Touches"}'),
('free-exercise-db', 'Standing_Towel_Triceps_Extension', 'standing-towel-triceps-extension', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Standing_Towel_Triceps_Extension.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Standing Towel Triceps Extension","force":"push","level":"beginner","mechanic":"isolation","equipment":"body only","primaryMuscles":["triceps"],"secondaryMuscles":[],"instructions":["To begin, stand up with both arms fully extended above the head holding one end of a towel with both hands. Your elbows should be in and the arms perpendicular to the floor with the palms facing each other while your feet should be shoulder width apart from each other. This is the starting position.","Now communicate with your partner so that he/she can grip the other side of the towel to apply resistance. Keeping your upper arms close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.","Go back to the starting position by using the triceps to raise the towel. Breathe out as you perform this step.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Standing_Towel_Triceps_Extension/0.jpg","Standing_Towel_Triceps_Extension/1.jpg"],"id":"Standing_Towel_Triceps_Extension"}'),
('free-exercise-db', 'Standing_Two-Arm_Overhead_Throw', 'medicine-ball-standing-two-arm-overhead-throw', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Standing_Two-Arm_Overhead_Throw.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Standing Two-Arm Overhead Throw","force":"pull","level":"beginner","mechanic":"compound","equipment":"medicine ball","primaryMuscles":["shoulders"],"secondaryMuscles":["chest","lats"],"instructions":["Stand with your feet shoulder width apart holding a medicine ball in both hands. To begin, reach the medicine ball deep behind your head as you bend the knees slightly and lean back.","Violently throw the ball forward, flexing at the hip and using your whole body to complete the movement.","The medicine ball can be thrown to a partner or to a wall, receiving it as it bounces back."],"category":"plyometrics","images":["Standing_Two-Arm_Overhead_Throw/0.jpg","Standing_Two-Arm_Overhead_Throw/1.jpg"],"id":"Standing_Two-Arm_Overhead_Throw"}'),
('free-exercise-db', 'Star_Jump', 'star-jump', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Star_Jump.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Star Jump","force":"push","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings","shoulders"],"instructions":["Begin in a relaxed stance with your feet shoulder width apart and hold your arms close to the body.","To initiate the move, squat down halfway and explode back up as high as possible. Fully extend your entire body, spreading your legs and arms away from the body.","As you land, bring your limbs back in and absorb your impact through the legs."],"category":"plyometrics","images":["Star_Jump/0.jpg","Star_Jump/1.jpg"],"id":"Star_Jump"}'),
('free-exercise-db', 'Step-up_with_Knee_Raise', 'step-up-knee-raise', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Step-up_with_Knee_Raise.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Step-up with Knee Raise","force":"push","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["glutes"],"secondaryMuscles":["hamstrings","quadriceps"],"instructions":["Stand facing a box or bench of an appropriate height with your feet together. This will be your starting position.","Begin the movement by stepping up, putting your left foot on the top of the bench. Extend through the hip and knee of your front leg to stand up on the box. As you stand on the box with your left leg, flex your right knee and hip, bringing your knee as high as you can.","Reverse this motion to step down off the box, and then repeat the sequence on the opposite leg."],"category":"strength","images":["Step-up_with_Knee_Raise/0.jpg","Step-up_with_Knee_Raise/1.jpg"],"id":"Step-up_with_Knee_Raise"}'),
('free-exercise-db', 'Step_Mill', 'machine-step-mill', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Step_Mill.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Step Mill","force":null,"level":"intermediate","mechanic":null,"equipment":"machine","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings"],"instructions":["To begin, step onto the stepmill and select the desired option from the menu. You can choose a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Use caution so that you don''t trip as you climb the stairs. It is recommended that you maintain your grip on the handles so that you don''t fall.","Stepmills offer convenience, cardiovascular benefits, and usually have less impact than running outside while offering a similar rate of calories burned. They are typically much harder than other cardio equipment. A 150 lb person will typically burn over 300 calories in 30 minutes, compared to about 175 calories walking."],"category":"cardio","images":["Step_Mill/0.jpg","Step_Mill/1.jpg"],"id":"Step_Mill"}'),
('free-exercise-db', 'Stiff-Legged_Barbell_Deadlift', 'barbell-stiff-legged-deadlift', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Stiff-Legged_Barbell_Deadlift.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Stiff-Legged Barbell Deadlift","force":"pull","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["hamstrings"],"secondaryMuscles":["glutes","lower back"],"instructions":["Grasp a bar using an overhand grip (palms facing down). You may need some wrist wraps if using a significant amount of weight.","Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position.","Keeping the knees stationary, lower the barbell to over the top of your feet by bending at the hips while keeping your back straight. Keep moving forward as if you were going to pick something from the floor until you feel a stretch on the hamstrings. Inhale as you perform this movement.","Start bringing your torso up straight again by extending your hips until you are back at the starting position. Exhale as you perform this movement.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Stiff-Legged_Barbell_Deadlift/0.jpg","Stiff-Legged_Barbell_Deadlift/1.jpg"],"id":"Stiff-Legged_Barbell_Deadlift"}'),
('free-exercise-db', 'Stiff-Legged_Dumbbell_Deadlift', 'dumbbell-stiff-legged-deadlift', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Stiff-Legged_Dumbbell_Deadlift.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Stiff-Legged Dumbbell Deadlift","force":"pull","level":"beginner","mechanic":"compound","equipment":"dumbbell","primaryMuscles":["hamstrings"],"secondaryMuscles":["glutes","lower back"],"instructions":["Grasp a couple of dumbbells holding them by your side at arm''s length.","Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position.","Keeping the knees stationary, lower the dumbbells to over the top of your feet by bending at the waist while keeping your back straight. Keep moving forward as if you were going to pick something from the floor until you feel a stretch on the hamstrings. Exhale as you perform this movement","Start bringing your torso up straight again by extending your hips and waist until you are back at the starting position. Inhale as you perform this movement.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Stiff-Legged_Dumbbell_Deadlift/0.jpg","Stiff-Legged_Dumbbell_Deadlift/1.jpg"],"id":"Stiff-Legged_Dumbbell_Deadlift"}'),
('free-exercise-db', 'Stiff_Leg_Barbell_Good_Morning', 'barbell-stiff-leg-good-morning', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Stiff_Leg_Barbell_Good_Morning.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Stiff Leg Barbell Good Morning","force":"push","level":"beginner","mechanic":"compound","equipment":"barbell","primaryMuscles":["lower back"],"secondaryMuscles":["glutes","hamstrings"],"instructions":["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.","Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.","Step away from the rack and position your legs using a shoulder width medium stance. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position.","Keeping your legs stationary, move your torso forward by bending at the hips while inhaling. Lower your torso until it is parallel with the floor.","Begin to raise the bar as you exhale by elevating your torso back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Stiff_Leg_Barbell_Good_Morning/0.jpg","Stiff_Leg_Barbell_Good_Morning/1.jpg"],"id":"Stiff_Leg_Barbell_Good_Morning"}'),
('free-exercise-db', 'Stomach_Vacuum', 'stomach-vacuum', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Stomach_Vacuum.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Stomach Vacuum","force":"static","level":"beginner","mechanic":"isolation","equipment":"body only","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["To begin, stand straight with your feet shoulder width apart from each other. Place your hands on your hips. This is the starting position.","Now slowly inhale as much air as possible and then start to exhale as much as possible while bringing your stomach in as much as possible and hold this position. Try to visualize your navel touching your backbone.","One isometric contraction is around 20 seconds. During the 20 second hold, try to breathe normally. Then inhale and bring your stomach back to the starting position.","Once you have practiced this exercise, try to perform this exercise for longer than 20 seconds. Tip: You can work your way up to 40-60 seconds.","Repeat for the recommended amount of sets."],"category":"stretching","images":["Stomach_Vacuum/0.jpg","Stomach_Vacuum/1.jpg"],"id":"Stomach_Vacuum"}'),
('free-exercise-db', 'Straight-Arm_Dumbbell_Pullover', 'dumbbell-straight-arm-pullover', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Straight-Arm_Dumbbell_Pullover.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Straight-Arm Dumbbell Pullover","force":"pull","level":"intermediate","mechanic":"compound","equipment":"dumbbell","primaryMuscles":["chest"],"secondaryMuscles":["lats","shoulders","triceps"],"instructions":["Place a dumbbell standing up on a flat bench.","Ensuring that the dumbbell stays securely placed at the top of the bench, lie perpendicular to the bench (torso across it as in forming a cross) with only your shoulders lying on the surface. Hips should be below the bench and legs bent with feet firmly on the floor. The head will be off the bench as well.","Grasp the dumbbell with both hands and hold it straight over your chest at arms length. Both palms should be pressing against the underside one of the sides of the dumbbell. This will be your starting position.\nCaution: Always ensure that the dumbbell used for this exercise is secure. Using a dumbbell with loose plates can result in the dumbbell falling apart and falling on your face.","While keeping your arms straight, lower the weight slowly in an arc behind your head while breathing in until you feel a stretch on the chest.","At that point, bring the dumbbell back to the starting position using the arc through which the weight was lowered and exhale as you perform this movement.","Hold the weight on the initial position for a second and repeat the motion for the prescribed number of repetitions."],"category":"strength","images":["Straight-Arm_Dumbbell_Pullover/0.jpg","Straight-Arm_Dumbbell_Pullover/1.jpg"],"id":"Straight-Arm_Dumbbell_Pullover"}'),
('free-exercise-db', 'Straight-Arm_Pulldown', 'cable-straight-arm-pulldown', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Straight-Arm_Pulldown.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Straight-Arm Pulldown","force":"pull","level":"beginner","mechanic":"isolation","equipment":"cable","primaryMuscles":["lats"],"secondaryMuscles":[],"instructions":["You will start by grabbing the wide bar from the top pulley of a pulldown machine and using a wider than shoulder-width pronated (palms down) grip. Step backwards two feet or so.","Bend your torso forward at the waist by around 30-degrees with your arms fully extended in front of you and a slight bend at the elbows. If your arms are not fully extended then you need to step a bit more backwards until they are. Once your arms are fully extended and your torso is slightly bent at the waist, tighten the lats and then you are ready to begin.","While keeping the arms straight, pull the bar down by contracting the lats until your hands are next to the side of the thighs. Breathe out as you perform this step.","While keeping the arms straight, go back to the starting position while breathing in.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Straight-Arm_Pulldown/0.jpg","Straight-Arm_Pulldown/1.jpg"],"id":"Straight-Arm_Pulldown"}'),
('free-exercise-db', 'Straight_Bar_Bench_Mid_Rows', 'barbell-straight-bar-bench-mid-row', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Straight_Bar_Bench_Mid_Rows.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Straight Bar Bench Mid Rows","force":"pull","level":"beginner","mechanic":"compound","equipment":"barbell","primaryMuscles":["middle back"],"secondaryMuscles":["biceps","lats"],"instructions":["Place a loaded barbell on the end of a bench. Standing on the bench behind the bar, take a medium, pronated grip. Stand with your hips back and chest up, maintaining a neutral spine. This will be your starting position.","Row the bar to your torso by retracting the shoulder blades and flexing the elbows. Use a controlled movement with no jerking.","After a brief pause, slowly return the bar to the starting position, ensuring to go all the way down."],"category":"strength","images":["Straight_Bar_Bench_Mid_Rows/0.jpg","Straight_Bar_Bench_Mid_Rows/1.jpg"],"id":"Straight_Bar_Bench_Mid_Rows"}'),
('free-exercise-db', 'Straight_Raises_on_Incline_Bench', 'barbell-straight-raise-incline-bench', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Straight_Raises_on_Incline_Bench.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Straight Raises on Incline Bench","force":"push","level":"beginner","mechanic":"isolation","equipment":"barbell","primaryMuscles":["shoulders"],"secondaryMuscles":["traps"],"instructions":["Place a bar on the ground behind the head of an incline bench.","Lay on the bench face down. With a pronated grip, pick the barbell up from the floor, keeping your arms straight. Allow the bar to hang straight down. This will be your starting position.","To begin, raise the barbell out in front of your head while keeping your arms extended.","Return to the starting position."],"category":"strength","images":["Straight_Raises_on_Incline_Bench/0.jpg","Straight_Raises_on_Incline_Bench/1.jpg"],"id":"Straight_Raises_on_Incline_Bench"}');
INSERT INTO source_records (source_id, source_record_id, exercise_id, source_url, license, author, match_method, match_score, raw_json) VALUES
('free-exercise-db', 'Stride_Jump_Crossover', 'stride-jump-crossover', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Stride_Jump_Crossover.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Stride Jump Crossover","force":"push","level":"beginner","mechanic":"compound","equipment":"other","primaryMuscles":["quadriceps"],"secondaryMuscles":["abductors","adductors","calves","hamstrings"],"instructions":["Stand to the side of a box with your inside foot on top of it, close to the edge.","Begin by swinging the arms upward as you push through the top leg, jumping upward as high as possible. Attempt to drive the opposite knee upward.","Land in the opposite position that you started, on the opposite side of the box. The foot that was initially on the box will now be on the ground, with the opposite foot now on the box.","Repeat the movement, crossing back over to the other side."],"category":"plyometrics","images":["Stride_Jump_Crossover/0.jpg","Stride_Jump_Crossover/1.jpg"],"id":"Stride_Jump_Crossover"}'),
('free-exercise-db', 'Sumo_Deadlift', 'barbell-sumo-deadlift', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Sumo_Deadlift.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Sumo Deadlift","force":"pull","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["hamstrings"],"secondaryMuscles":["adductors","forearms","glutes","lower back","middle back","quadriceps","traps"],"instructions":["Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the shoulders, which in effect lengthens your arms.","Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees.","As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.","Return the weight to the ground by bending at the hips and controlling the weight on the way down."],"category":"powerlifting","images":["Sumo_Deadlift/0.jpg","Sumo_Deadlift/1.jpg"],"id":"Sumo_Deadlift"}'),
('free-exercise-db', 'Sumo_Deadlift_with_Bands', 'band-sumo-deadlift', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Sumo_Deadlift_with_Bands.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Sumo Deadlift with Bands","force":"pull","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["hamstrings"],"secondaryMuscles":["adductors","forearms","glutes","lower back","middle back","quadriceps","traps"],"instructions":["To deadlift with short bands, simply loop them over the bar before you start, and step into them to set up. Ensure that they under the back half of your foot, directly where you are driving into the floor.","Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip.","Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees.","As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.","Return the weight to the ground by bending at the hips and controlling the weight on the way down."],"category":"powerlifting","images":["Sumo_Deadlift_with_Bands/0.jpg","Sumo_Deadlift_with_Bands/1.jpg"],"id":"Sumo_Deadlift_with_Bands"}'),
('free-exercise-db', 'Sumo_Deadlift_with_Chains', 'barbell-sumo-deadlift-chains', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Sumo_Deadlift_with_Chains.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Sumo Deadlift with Chains","force":"pull","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["hamstrings"],"secondaryMuscles":["abductors","adductors","forearms","glutes","lower back","middle back","quadriceps","traps"],"instructions":["You can attach the chains to the sleeves of the bar, or just drape the middle over the bar so there is a greater weight increase as you lift. Attempt to keep the ends of the chains away from the plates so you don''t hit them when you lower the weight.","Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the shoulders, which in effect lengthens your arms.","Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees.","As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.","Return the weight to the ground by bending at the hips and controlling the weight on the way down."],"category":"powerlifting","images":["Sumo_Deadlift_with_Chains/0.jpg","Sumo_Deadlift_with_Chains/1.jpg"],"id":"Sumo_Deadlift_with_Chains"}'),
('free-exercise-db', 'Superman', 'superman', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Superman.json', 'Unlicense', NULL, 'exact', 100.0, '{"name":"Superman","force":"static","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["lower back"],"secondaryMuscles":["glutes","hamstrings"],"instructions":["To begin, lie straight and face down on the floor or exercise mat. Your arms should be fully extended in front of you. This is the starting position.","Simultaneously raise your arms, legs, and chest off of the floor and hold this contraction for 2 seconds. Tip: Squeeze your lower back to get the best results from this exercise. Remember to exhale during this movement. Note: When holding the contracted position, you should look like superman when he is flying.","Slowly begin to lower your arms, legs and chest back down to the starting position while inhaling.","Repeat for the recommended amount of repetitions prescribed in your program."],"category":"stretching","images":["Superman/0.jpg","Superman/1.jpg"],"id":"Superman"}'),
('free-exercise-db', 'Supine_Chest_Throw', 'medicine-ball-supine-chest-throw', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Supine_Chest_Throw.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Supine Chest Throw","force":"push","level":"beginner","mechanic":"compound","equipment":"medicine ball","primaryMuscles":["triceps"],"secondaryMuscles":["chest","shoulders"],"instructions":["This drill is great for chest passes when you lack a partner or a wall of sufficient strength. Lay on the ground on your back with your knees bent.","Begin with the ball on your chest, held with both hands on the bottom.","Explode up, extending through the elbow to throw the ball directly above you as high as possible.","Catch the ball with both hands as it comes down."],"category":"plyometrics","images":["Supine_Chest_Throw/0.jpg","Supine_Chest_Throw/1.jpg"],"id":"Supine_Chest_Throw"}'),
('free-exercise-db', 'Supine_One-Arm_Overhead_Throw', 'medicine-ball-supine-one-arm-overhead-throw', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Supine_One-Arm_Overhead_Throw.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Supine One-Arm Overhead Throw","force":"pull","level":"beginner","mechanic":"compound","equipment":"medicine ball","primaryMuscles":["abdominals"],"secondaryMuscles":["chest","lats","shoulders"],"instructions":["Lay on the ground on your back with your knees bent. Hold the ball with one hand, extending the arm fully behind your head. This will be your starting position.","Initiate the movement at the shoulder, throwing the ball directly forward of you as you sit up, attempting to go for maximum distance.","The ball can be thrown to a partner or bounced off of a wall."],"category":"plyometrics","images":["Supine_One-Arm_Overhead_Throw/0.jpg","Supine_One-Arm_Overhead_Throw/1.jpg"],"id":"Supine_One-Arm_Overhead_Throw"}'),
('free-exercise-db', 'Supine_Two-Arm_Overhead_Throw', 'medicine-ball-supine-two-arm-overhead-throw', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Supine_Two-Arm_Overhead_Throw.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Supine Two-Arm Overhead Throw","force":"pull","level":"beginner","mechanic":"compound","equipment":"medicine ball","primaryMuscles":["abdominals"],"secondaryMuscles":["chest","lats","shoulders"],"instructions":["Lay on the ground on your back with your knees bent.","Hold the ball with both hands, extending the arms fully behind your head. This will be your starting position.","Initiate the movement at the shoulder, throwing the ball directly forward of you as you sit up, attempting to go for maximum distance.","The ball can be thrown to a partner or bounced off of a wall."],"category":"plyometrics","images":["Supine_Two-Arm_Overhead_Throw/0.jpg","Supine_Two-Arm_Overhead_Throw/1.jpg"],"id":"Supine_Two-Arm_Overhead_Throw"}'),
('free-exercise-db', 'Suspended_Fallout', 'suspended-fallout', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Suspended_Fallout.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Suspended Fallout","force":"pull","level":"intermediate","mechanic":"isolation","equipment":"other","primaryMuscles":["abdominals"],"secondaryMuscles":["chest","lower back","shoulders"],"instructions":["Adjust the straps so the handles are at an appropriate height, below waist level.","Begin standing and grasping the handles. Lean into the straps, moving to an incline push-up position. This will be your starting position.","Keeping your arms straight, lean further into the suspension straps, bringing your body closer to the ground, allowing your shoulders to extend, raising your arms up and over your head.","Maintain a neutral spine and keep the rest of your body straight, your shoulders being the only joints allowed to move.","Pause during the peak contraction, and then return to the starting position."],"category":"strength","images":["Suspended_Fallout/0.jpg","Suspended_Fallout/1.jpg"],"id":"Suspended_Fallout"}'),
('free-exercise-db', 'Suspended_Push-Up', 'suspended-push-up', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Suspended_Push-Up.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Suspended Push-Up","force":"push","level":"beginner","mechanic":"compound","equipment":"other","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["Anchor your suspension straps securely to the top of a rack or other object.","Leaning into the straps, take a handle in each hand and move into a push-up plank position. You should be as close to parallel to the ground as you can manage with your arms fully extended, maintaining good posture.","Maintaining a straight, rigid torso, descend slowly by allowing the elbows to flex.","Continue until your elbows break 90 degrees, pausing before you extend to return to the starting position."],"category":"strength","images":["Suspended_Push-Up/0.jpg","Suspended_Push-Up/1.jpg"],"id":"Suspended_Push-Up"}'),
('free-exercise-db', 'Suspended_Reverse_Crunch', 'suspended-reverse-crunch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Suspended_Reverse_Crunch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Suspended Reverse Crunch","force":"pull","level":"beginner","mechanic":"isolation","equipment":"other","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Secure a set of suspension straps with the handles hanging about a foot off of the ground. Move yourself into a pushup plank position facing away from the rack.","Place your feet into the handles. You should maintain a straight posture, not allowing the hips to sag. This will be your starting position.","Begin the movement by flexing the knees and hips, drawing the knees to your torso. As you do so, anteriorly tilt your pelvis, allowing your spine to flex.","At the top of the controlled motion, return to the starting position."],"category":"strength","images":["Suspended_Reverse_Crunch/0.jpg","Suspended_Reverse_Crunch/1.jpg"],"id":"Suspended_Reverse_Crunch"}'),
('free-exercise-db', 'Suspended_Row', 'suspended-row', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Suspended_Row.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Suspended Row","force":"pull","level":"beginner","mechanic":"compound","equipment":"other","primaryMuscles":["middle back"],"secondaryMuscles":["biceps","lats"],"instructions":["Suspend your straps at around chest height. Take a handle in each hand and lean back. Keep your body erect and your head and chest up. Your arms should be fully extended. This will be your starting position.","Begin by flexing the elbow to initiate the movement. Protract your shoulder blades as you do so.","At the completion of the motion pause, and then return to the starting position."],"category":"strength","images":["Suspended_Row/0.jpg","Suspended_Row/1.jpg"],"id":"Suspended_Row"}'),
('free-exercise-db', 'Suspended_Split_Squat', 'suspended-split-squat', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Suspended_Split_Squat.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Suspended Split Squat","force":"push","level":"intermediate","mechanic":"compound","equipment":"other","primaryMuscles":["quadriceps"],"secondaryMuscles":["abductors","adductors","calves","glutes","hamstrings"],"instructions":["Suspend your straps so the handles are 18-30 inches from the floor.","Facing away from the setup, place your rear foot into the handle behind you. Keep your head looking forward and your chest up, with your knee slightly bent. This will be your starting position.","Descend by flexing the knee and hips, lowering yourself to the ground. Keep your weight on the heel of your foot and maintain your posture throughout the exercise.","At the bottom of the movement, reverse the motion, extending through the hip and knee to return to the starting position."],"category":"strength","images":["Suspended_Split_Squat/0.jpg","Suspended_Split_Squat/1.jpg"],"id":"Suspended_Split_Squat"}'),
('free-exercise-db', 'Svend_Press', 'svend-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Svend_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Svend Press","force":"push","level":"beginner","mechanic":"compound","equipment":"other","primaryMuscles":["chest"],"secondaryMuscles":["forearms","shoulders","triceps"],"instructions":["Begin in a standing position.","Press two lightweight plates together with your hands. Hold the plates together close to your chest to create an isometric contraction in your chest muscles. Your fingers should be pointed forward. This is your starting position.","Squeeze the plates between your palms and extend your arms directly out in front of you in a controlled motion.","Pause at the top of the motion, and then slowly return to the starting position."],"category":"strength","images":["Svend_Press/0.jpg","Svend_Press/1.jpg"],"id":"Svend_Press"}'),
('free-exercise-db', 'T-Bar_Row_with_Handle', 'barbell-t-bar-row-handle', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/T-Bar_Row_with_Handle.json', 'Unlicense', NULL, 'new', NULL, '{"name":"T-Bar Row with Handle","force":"pull","level":"beginner","mechanic":"compound","equipment":"barbell","primaryMuscles":["middle back"],"secondaryMuscles":["biceps","lats"],"instructions":["Position a bar into a landmine or in a corner to keep it from moving. Load an appropriate weight onto your end.","Stand over the bar, and position a Double D row handle around the bar next to the collar. Using your hips and legs, rise to a standing position.","Assume a wide stance with your hips back and your chest up. Your arms should be extended. This will be your starting position.","Pull the weight to your upper abdomen by retracting the shoulder blades and flexing the elbows. Do not jerk the weight or cheat during the movement.","After a brief pause, return to the starting position."],"category":"strength","images":["T-Bar_Row_with_Handle/0.jpg","T-Bar_Row_with_Handle/1.jpg"],"id":"T-Bar_Row_with_Handle"}'),
('free-exercise-db', 'Tate_Press', 'dumbbell-tate-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Tate_Press.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Tate Press","force":"push","level":"intermediate","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["triceps"],"secondaryMuscles":["chest","shoulders"],"instructions":["Lie down on a flat bench with a dumbbell in each hand on top of your thighs. The palms of your hand will be facing each other.","By using your thighs to help you get the dumbbells up, clean the dumbbells one arm at a time so that you can hold them in front of you at shoulder width. Note: when holding the dumbbells in front of you, make sure your arms are wider than shoulder width apart from each other using a pronated (palms forward) grip. Allow your elbows to point out. This is your starting position.","Keeping the upper arms stationary, slowly move the dumbbells in and down in a semi circular motion until they touch the upper chest while inhaling. Keep full control of the dumbbells at all times and do not move the upper arms nor rest the dumbbells on the chest.","As you breathe out, move the dumbbells up using your triceps and the same semi-circular motion but in reverse. Attempt to keep the dumbbells together as they move up. Lock your arms in the contracted position, hold for a second and then start coming down again slowly again. Tip: It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions of your training program."],"category":"strength","images":["Tate_Press/0.jpg","Tate_Press/1.jpg"],"id":"Tate_Press"}'),
('free-exercise-db', 'The_Straddle', 'straddle', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/The_Straddle.json', 'Unlicense', NULL, 'new', NULL, '{"name":"The Straddle","force":"static","level":"beginner","mechanic":null,"equipment":null,"primaryMuscles":["hamstrings"],"secondaryMuscles":["adductors","calves"],"instructions":["Begin in a seated, upright position. Start by extending your legs in front of you in a V.","With your hands on the floor, lean forward as far as possible. Hold for 10 to 20 seconds."],"category":"stretching","images":["The_Straddle/0.jpg","The_Straddle/1.jpg"],"id":"The_Straddle"}'),
('free-exercise-db', 'Thigh_Abductor', 'machine-thigh-abductor', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Thigh_Abductor.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Thigh Abductor","force":"push","level":"beginner","mechanic":"isolation","equipment":"machine","primaryMuscles":["abductors"],"secondaryMuscles":["glutes"],"instructions":["To begin, sit down on the abductor machine and select a weight you are comfortable with. When your legs are positioned properly, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position.","Slowly press against the machine with your legs to move them away from each other while exhaling.","Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note: Remember to keep your upper body stationary to prevent any injuries from occurring.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Thigh_Abductor/0.jpg","Thigh_Abductor/1.jpg"],"id":"Thigh_Abductor"}'),
('free-exercise-db', 'Thigh_Adductor', 'machine-thigh-adductor', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Thigh_Adductor.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Thigh Adductor","force":"pull","level":"beginner","mechanic":"isolation","equipment":"machine","primaryMuscles":["adductors"],"secondaryMuscles":["glutes","hamstrings"],"instructions":["To begin, sit down on the adductor machine and select a weight you are comfortable with. When your legs are positioned properly on the leg pads of the machine, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position.","Slowly press against the machine with your legs to move them towards each other while exhaling.","Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note: Remember to keep your upper body stationary and avoid fast jerking motions in order to prevent any injuries from occurring.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Thigh_Adductor/0.jpg","Thigh_Adductor/1.jpg"],"id":"Thigh_Adductor"}'),
('free-exercise-db', 'Tire_Flip', 'tire-flip-2', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Tire_Flip.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Tire Flip","force":"pull","level":"intermediate","mechanic":"compound","equipment":"other","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","chest","forearms","glutes","hamstrings","lower back","shoulders","traps","triceps"],"instructions":["Begin by gripping the bottom of the tire on the tread, and position your feet back a bit. Your chest should be driving into the tire.","To lift the tire, extend through the hips, knees, and ankles, driving into the tire and up.","As the tire reaches a 45 degree angle, step forward and drive a knee into the tire. As you do so adjust your grip to the upper portion of the tire and push it forward as hard as possible to complete the turn. Repeat as necessary."],"category":"strongman","images":["Tire_Flip/0.jpg","Tire_Flip/1.jpg"],"id":"Tire_Flip"}'),
('free-exercise-db', 'Toe_Touchers', 'toe-touchers', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Toe_Touchers.json', 'Unlicense', NULL, 'new', 85.7, '{"name":"Toe Touchers","force":"pull","level":"beginner","mechanic":"isolation","equipment":"body only","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["To begin, lie down on the floor or an exercise mat with your back pressed against the floor. Your arms should be lying across your sides with the palms facing down.","Your legs should be touching each other. Slowly elevate your legs up in the air until they are almost perpendicular to the floor with a slight bend at the knees. Your feet should be parallel to the floor.","Move your arms so that they are fully extended at a 45 degree angle from the floor. This is the starting position.","While keeping your lower back pressed against the floor, slowly lift your torso and use your hands to try and touch your toes. Remember to exhale while perform this part of the exercise.","Slowly begin to lower your torso and arms back down to the starting position while inhaling. Remember to keep your arms straight out pointing towards your toes.","Repeat for the recommended amount of repetitions."],"category":"stretching","images":["Toe_Touchers/0.jpg","Toe_Touchers/1.jpg"],"id":"Toe_Touchers"}'),
('free-exercise-db', 'Torso_Rotation', 'exercise-ball-torso-rotation', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Torso_Rotation.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Torso Rotation","force":"pull","level":"beginner","mechanic":null,"equipment":"exercise ball","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Stand upright holding an exercise ball with both hands. Extend your arms so the ball is straight out in front of you. This will be your starting position.","Rotate your torso to one side, keeping your eyes on the ball as you move. Now, rotate back to the opposite direction. Repeat for 10-20 repetitions."],"category":"stretching","images":["Torso_Rotation/0.jpg","Torso_Rotation/1.jpg"],"id":"Torso_Rotation"}'),
('free-exercise-db', 'Trail_Running_Walking', 'trail-running-walking', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Trail_Running_Walking.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Trail Running/Walking","force":null,"level":"beginner","mechanic":null,"equipment":null,"primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings"],"instructions":["Running or hiking on trails will get the blood pumping and heart beating almost immediately. Make sure you have good shoes. While you use the muscles in your calves and buttocks to pull yourself up a hill, the knees, joints and ankles absorb the bulk of the pounding coming back down. Take smaller steps as you walk downhill, keep your knees bent to reduce the impact and slow down to avoid falling.","A 150 lb person can burn over 200 calories for 30 minutes walking uphill, compared to 175 on a flat surface. If running the trail, a 150 lb person can burn well over 500 calories in 30 minutes."],"category":"cardio","images":["Trail_Running_Walking/0.jpg","Trail_Running_Walking/1.jpg"],"id":"Trail_Running_Walking"}'),
('free-exercise-db', 'Trap_Bar_Deadlift', 'trap-bar-deadlift-high-handles', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Trap_Bar_Deadlift.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Trap Bar Deadlift","force":"pull","level":"beginner","mechanic":"compound","equipment":"other","primaryMuscles":["quadriceps"],"secondaryMuscles":["glutes","hamstrings"],"instructions":["For this exercise load a trap bar, also known as a hex bar, to an appropriate weight resting on the ground. Stand in the center of the apparatus and grasp both handles.","Lower your hips, look forward with your head and keep your chest up.","Begin the movement by driving through the heels and extend your hips and knees. Avoid rounding your back at all times.","At the completion of the movement, lower the weight back to the ground under control."],"category":"strength","images":["Trap_Bar_Deadlift/0.jpg","Trap_Bar_Deadlift/1.jpg"],"id":"Trap_Bar_Deadlift"}'),
('free-exercise-db', 'Tricep_Dumbbell_Kickback', 'dumbbell-tricep-kickback', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Tricep_Dumbbell_Kickback.json', 'Unlicense', NULL, 'exact', 100.0, '{"name":"Tricep Dumbbell Kickback","force":"push","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["triceps"],"secondaryMuscles":[],"instructions":["Start with a dumbbell in each hand and your palms facing your torso. Keep your back straight with a slight bend in the knees and bend forward at the waist. Your torso should be almost parallel to the floor. Make sure to keep your head up. Your upper arms should be close to your torso and parallel to the floor. Your forearms should be pointed towards the floor as you hold the weights. There should be a 90-degree angle formed between your forearm and upper arm. This is your starting position.","Now, while keeping your upper arms stationary, exhale and use your triceps to lift the weights until the arm is fully extended. Focus on moving the forearm.","After a brief pause at the top contraction, inhale and slowly lower the dumbbells back down to the starting position.","Repeat the movement for the prescribed amount of repetitions."],"category":"strength","images":["Tricep_Dumbbell_Kickback/0.jpg","Tricep_Dumbbell_Kickback/1.jpg"],"id":"Tricep_Dumbbell_Kickback"}'),
('free-exercise-db', 'Tricep_Side_Stretch', 'tricep-side-stretch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Tricep_Side_Stretch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Tricep Side Stretch","force":"static","level":"beginner","mechanic":null,"equipment":null,"primaryMuscles":["triceps"],"secondaryMuscles":["shoulders"],"instructions":["Bring right arm across your body and over your left shoulder, holding your elbow with your left hand, until you feel a stretch in your tricep. Then repeat for your other arm."],"category":"stretching","images":["Tricep_Side_Stretch/0.jpg","Tricep_Side_Stretch/1.jpg"],"id":"Tricep_Side_Stretch"}'),
('free-exercise-db', 'Triceps_Overhead_Extension_with_Rope', 'cable-rope-overhead-triceps-extension', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Triceps_Overhead_Extension_with_Rope.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Triceps Overhead Extension with Rope","force":"push","level":"beginner","mechanic":"isolation","equipment":"cable","primaryMuscles":["triceps"],"secondaryMuscles":[],"instructions":["Attach a rope to a low pulley. After selecting an appropriate weight, grasp the rope with both hands and face away from the cable.","Position your hands behind your head with your elbows point straight up. Your elbows should start out flexed, and you can stagger your stance and lean gently away from the machine to create greater stability. This will be your starting position.","To perform the movement, extend through the elbow while keeping the upper arm in position, raising your hands above your head.","Squeeze your triceps at the top of the movement, and slowly lower the weight back to the start position."],"category":"strength","images":["Triceps_Overhead_Extension_with_Rope/0.jpg","Triceps_Overhead_Extension_with_Rope/1.jpg"],"id":"Triceps_Overhead_Extension_with_Rope"}'),
('free-exercise-db', 'Triceps_Pushdown', 'cable-tricep-pushdown', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Triceps_Pushdown.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Triceps Pushdown","force":"push","level":"beginner","mechanic":"isolation","equipment":"cable","primaryMuscles":["triceps"],"secondaryMuscles":[],"instructions":["Attach a straight or angled bar to a high pulley and grab with an overhand grip (palms facing down) at shoulder width.","Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the bar. This is your starting position.","Using the triceps, bring the bar down until it touches the front of your thighs and the arms are fully extended perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.","After a second hold at the contracted position, bring the bar slowly up to the starting point. Breathe in as you perform this step.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Triceps_Pushdown/0.jpg","Triceps_Pushdown/1.jpg"],"id":"Triceps_Pushdown"}'),
('free-exercise-db', 'Triceps_Pushdown_-_Rope_Attachment', 'cable-triceps-pushdown-rope-attachment', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Triceps_Pushdown_-_Rope_Attachment.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Triceps Pushdown - Rope Attachment","force":"push","level":"beginner","mechanic":"isolation","equipment":"cable","primaryMuscles":["triceps"],"secondaryMuscles":[],"instructions":["Attach a rope attachment to a high pulley and grab with a neutral grip (palms facing each other).","Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the rope with the palms facing each other. This is your starting position.","Using the triceps, bring the rope down as you bring each side of the rope to the side of your thighs. At the end of the movement the arms are fully extended and perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.","After holding for a second, at the contracted position, bring the rope slowly up to the starting point. Breathe in as you perform this step.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Triceps_Pushdown_-_Rope_Attachment/0.jpg","Triceps_Pushdown_-_Rope_Attachment/1.jpg"],"id":"Triceps_Pushdown_-_Rope_Attachment"}'),
('free-exercise-db', 'Triceps_Pushdown_-_V-Bar_Attachment', 'cable-triceps-pushdown-v-bar-attachment', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Triceps_Pushdown_-_V-Bar_Attachment.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Triceps Pushdown - V-Bar Attachment","force":"push","level":"beginner","mechanic":"isolation","equipment":"cable","primaryMuscles":["triceps"],"secondaryMuscles":[],"instructions":["Attach a V-Bar to a high pulley and grab with an overhand grip (palms facing down) at shoulder width.","Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the bar. The thumbs should be higher than the small finger. This is your starting position.","Using the triceps, bring the bar down until it touches the front of your thighs and the arms are fully extended perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.","After a second hold at the contracted position, bring the V-Bar slowly up to the starting point. Breathe in as you perform this step.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Triceps_Pushdown_-_V-Bar_Attachment/0.jpg","Triceps_Pushdown_-_V-Bar_Attachment/1.jpg"],"id":"Triceps_Pushdown_-_V-Bar_Attachment"}'),
('free-exercise-db', 'Triceps_Stretch', 'triceps-stretch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Triceps_Stretch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Triceps Stretch","force":"static","level":"beginner","mechanic":"isolation","equipment":null,"primaryMuscles":["triceps"],"secondaryMuscles":["lats"],"instructions":["Reach your hand behind your head, grasp your elbow and gently pull. Hold for 10 to 20 seconds, then switch sides."],"category":"stretching","images":["Triceps_Stretch/0.jpg","Triceps_Stretch/1.jpg"],"id":"Triceps_Stretch"}'),
('free-exercise-db', 'Tuck_Crunch', 'tuck-crunch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Tuck_Crunch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Tuck Crunch","force":"pull","level":"beginner","mechanic":"isolation","equipment":"body only","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["To begin, lie down on the floor or an exercise mat with your back pressed against the floor. Your arms should be lying across your sides with the palms facing down.","Your legs should be crossed by wrapping one ankle around the other. Slowly elevate your legs up in the air until your thighs are perpendicular to the floor with a slight bend at the knees. Note: Your knees and toes should be parallel to the floor as opposed to the thighs.","Move your arms from the floor and cross them so they are resting on your chest. This is the starting position.","While keeping your lower back pressed against the floor, slowly lift your torso. Remember to exhale while perform this part of the exercise.","Slowly begin to lower your torso back down to the starting position while inhaling.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Tuck_Crunch/0.jpg","Tuck_Crunch/1.jpg"],"id":"Tuck_Crunch"}'),
('free-exercise-db', 'Two-Arm_Dumbbell_Preacher_Curl', 'dumbbell-two-arm-preacher-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Two-Arm_Dumbbell_Preacher_Curl.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Two-Arm Dumbbell Preacher Curl","force":"pull","level":"beginner","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["biceps"],"secondaryMuscles":[],"instructions":["Grab a dumbbell with each arm and place the upper arms on top of the preacher bench or the incline bench. The dumbbell should be held at shoulder length. This will be your starting position.","As you breathe in, slowly lower the dumbbells until your upper arm is extended and the biceps is fully stretched.","As you exhale, use the biceps to curl the weights up until your biceps is fully contracted and the dumbbells are at shoulder height.","Squeeze the biceps hard for a second at the contracted position and repeat for the recommended amount of repetitions."],"category":"strength","images":["Two-Arm_Dumbbell_Preacher_Curl/0.jpg","Two-Arm_Dumbbell_Preacher_Curl/1.jpg"],"id":"Two-Arm_Dumbbell_Preacher_Curl"}'),
('free-exercise-db', 'Two-Arm_Kettlebell_Clean', 'kettlebell-two-arm-clean', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Two-Arm_Kettlebell_Clean.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Two-Arm Kettlebell Clean","force":"pull","level":"intermediate","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["shoulders"],"secondaryMuscles":["calves","glutes","hamstrings","lower back","traps"],"instructions":["Place two kettlebells between your feet. To get in the starting position, push your butt back and look straight ahead.","Clean the kettlebells to your shoulders by extending through the legs and hips as you raise the kettlebells towards your shoulders. Rotate your wrists as you do so.","Lower the kettlebells back to the starting position and repeat."],"category":"strength","images":["Two-Arm_Kettlebell_Clean/0.jpg","Two-Arm_Kettlebell_Clean/1.jpg"],"id":"Two-Arm_Kettlebell_Clean"}'),
('free-exercise-db', 'Two-Arm_Kettlebell_Jerk', 'kettlebell-two-arm-jerk', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Two-Arm_Kettlebell_Jerk.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Two-Arm Kettlebell Jerk","force":"push","level":"intermediate","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["shoulders"],"secondaryMuscles":["calves","quadriceps","triceps"],"instructions":["Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you swing the kettlebells towards your shoulders. Rotate your wrists as you do so, so that the palms face forward. Squat down a few inches and reverse the motion rapidly driving both kettlebells overhead. Immediately after the initial push, squat down again and get under the kettlebells. Once the kettlebells are locked out, stand upright to complete the exercise."],"category":"strength","images":["Two-Arm_Kettlebell_Jerk/0.jpg","Two-Arm_Kettlebell_Jerk/1.jpg"],"id":"Two-Arm_Kettlebell_Jerk"}'),
('free-exercise-db', 'Two-Arm_Kettlebell_Military_Press', 'kettlebell-two-arm-military-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Two-Arm_Kettlebell_Military_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Two-Arm Kettlebell Military Press","force":"push","level":"intermediate","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["shoulders"],"secondaryMuscles":["triceps"],"instructions":["Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you swing the kettlebells towards your shoulders. Rotate your wrists as you do so, so that the palms face forward.","Press the kettlebells up and out. As the kettlebells pass your head, lean into the weights so that the kettlebells are racked behind your head. Make sure to contract your lats, butt, and stomach for added stability."],"category":"strength","images":["Two-Arm_Kettlebell_Military_Press/0.jpg","Two-Arm_Kettlebell_Military_Press/1.jpg"],"id":"Two-Arm_Kettlebell_Military_Press"}'),
('free-exercise-db', 'Two-Arm_Kettlebell_Row', 'kettlebell-two-arm-row', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Two-Arm_Kettlebell_Row.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Two-Arm Kettlebell Row","force":"pull","level":"intermediate","mechanic":"compound","equipment":"kettlebells","primaryMuscles":["middle back"],"secondaryMuscles":["biceps","lats"],"instructions":["Place two kettlebells in front of your feet. Bend your knees slightly and then push your butt out as much as possible as you bend over to get in the starting position.","Grab both kettlebells and pull them to your stomach, retracting your shoulder blades and flexing the elbows. Keep your back straight. Lower and repeat."],"category":"strength","images":["Two-Arm_Kettlebell_Row/0.jpg","Two-Arm_Kettlebell_Row/1.jpg"],"id":"Two-Arm_Kettlebell_Row"}'),
('free-exercise-db', 'Underhand_Cable_Pulldowns', 'cable-underhand-pulldowns', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Underhand_Cable_Pulldowns.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Underhand Cable Pulldowns","force":"pull","level":"beginner","mechanic":"compound","equipment":"cable","primaryMuscles":["lats"],"secondaryMuscles":["biceps","middle back","shoulders"],"instructions":["Sit down on a pull-down machine with a wide bar attached to the top pulley. Adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.","Grab the pull-down bar with the palms facing your torso (a supinated grip). Make sure that the hands are placed closer than the shoulder width.","As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.","As you breathe out, pull the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the fully contracted position and keep the elbows close to your body. The upper torso should remain stationary as your bring the bar to you and only the arms should move. The forearms should do no other work other than hold the bar.","After a second on the contracted position, while breathing in, slowly bring the bar back to the starting position when your arms are fully extended and the lats are fully stretched.","Repeat this motion for the prescribed amount of repetitions."],"category":"strength","images":["Underhand_Cable_Pulldowns/0.jpg","Underhand_Cable_Pulldowns/1.jpg"],"id":"Underhand_Cable_Pulldowns"}'),
('free-exercise-db', 'Upper_Back-Leg_Grab', 'upper-back-leg-grab', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Upper_Back-Leg_Grab.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Upper Back-Leg Grab","force":"static","level":"beginner","mechanic":null,"equipment":null,"primaryMuscles":["hamstrings"],"secondaryMuscles":["lower back","middle back"],"instructions":["While seated, bend forward to hug your thighs from underneath with both arms.","Keep your knees together and your legs extended out as you bring your chest down to your knees. You can also stretch your middle back by pulling your back away from your knees as your hugging them."],"category":"stretching","images":["Upper_Back-Leg_Grab/0.jpg","Upper_Back-Leg_Grab/1.jpg"],"id":"Upper_Back-Leg_Grab"}'),
('free-exercise-db', 'Upper_Back_Stretch', 'upper-back-stretch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Upper_Back_Stretch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Upper Back Stretch","force":"static","level":"beginner","mechanic":null,"equipment":null,"primaryMuscles":["middle back"],"secondaryMuscles":["middle back"],"instructions":["Clasp fingers together with your thumbs pointing down, round your shoulders as you reach your hands forward."],"category":"stretching","images":["Upper_Back_Stretch/0.jpg","Upper_Back_Stretch/1.jpg"],"id":"Upper_Back_Stretch"}'),
('free-exercise-db', 'Upright_Barbell_Row', 'barbell-upright-row', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Upright_Barbell_Row.json', 'Unlicense', NULL, 'normalized', 100.0, '{"name":"Upright Barbell Row","force":"pull","level":"beginner","mechanic":"compound","equipment":"barbell","primaryMuscles":["shoulders"],"secondaryMuscles":["traps"],"instructions":["Grasp a barbell with an overhand grip that is slightly less than shoulder width. The bar should be resting on the top of your thighs with your arms extended and a slight bend in your elbows. Your back should also be straight. This will be your starting position.","Now exhale and use the sides of your shoulders to lift the bar, raising your elbows up and to the side. Keep the bar close to your body as you raise it. Continue to lift the bar until it nearly touches your chin. Tip: Your elbows should drive the motion, and should always be higher than your forearms. Remember to keep your torso stationary and pause for a second at the top of the movement.","Lower the bar back down slowly to the starting position. Inhale as you perform this portion of the movement.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Upright_Barbell_Row/0.jpg","Upright_Barbell_Row/1.jpg"],"id":"Upright_Barbell_Row"}'),
('free-exercise-db', 'Upright_Cable_Row', 'cable-upright-row', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Upright_Cable_Row.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Upright Cable Row","force":"pull","level":"intermediate","mechanic":"compound","equipment":"cable","primaryMuscles":["traps"],"secondaryMuscles":["shoulders"],"instructions":["Grasp a straight bar cable attachment that is attached to a low pulley with a pronated (palms facing your thighs) grip that is slightly less than shoulder width. The bar should be resting on top of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position.","Use your side shoulders to lift the cable bar as you exhale. The bar should be close to the body as you move it up. Continue to lift it until it nearly touches your chin. Tip: Your elbows should drive the motion. As you lift the bar, your elbows should always be higher than your forearms. Also, keep your torso stationary and pause for a second at the top of the movement.","Lower the bar back down slowly to the starting position. Inhale as you perform this portion of the movement.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Upright_Cable_Row/0.jpg","Upright_Cable_Row/1.jpg"],"id":"Upright_Cable_Row"}'),
('free-exercise-db', 'Upright_Row_-_With_Bands', 'band-upright-row', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Upright_Row_-_With_Bands.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Upright Row - With Bands","force":"pull","level":"beginner","mechanic":"compound","equipment":"bands","primaryMuscles":["traps"],"secondaryMuscles":["shoulders"],"instructions":["To begin, stand on an exercise band so that tension begins at arm''s length. Grasp the handles using a pronated (palms facing your thighs) grip that is slightly less than shoulder width. The handles should be resting on top of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position.","Use your side shoulders to lift the handles as you exhale. The handles should be close to the body as you move them up. Continue to lift the handles until they nearly touches your chin. Tip: Your elbows should drive the motion. As you lift the handles, your elbows should always be higher than your forearms. Also, keep your torso stationary and pause for a second at the top of the movement.","Lower the handles back down slowly to the starting position. Inhale as you perform this portion of the movement.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Upright_Row_-_With_Bands/0.jpg","Upright_Row_-_With_Bands/1.jpg"],"id":"Upright_Row_-_With_Bands"}'),
('free-exercise-db', 'Upward_Stretch', 'upward-stretch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Upward_Stretch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Upward Stretch","force":"static","level":"beginner","mechanic":null,"equipment":null,"primaryMuscles":["shoulders"],"secondaryMuscles":["chest","lats"],"instructions":["Extend both hands straight above your head, palms touching.","Slowly push your hands up and back, keeping your back straight."],"category":"stretching","images":["Upward_Stretch/0.jpg","Upward_Stretch/1.jpg"],"id":"Upward_Stretch"}'),
('free-exercise-db', 'V-Bar_Pulldown', 'cable-v-bar-pulldown', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/V-Bar_Pulldown.json', 'Unlicense', NULL, 'new', NULL, '{"name":"V-Bar Pulldown","force":"pull","level":"intermediate","mechanic":"compound","equipment":"cable","primaryMuscles":["lats"],"secondaryMuscles":["biceps","middle back","shoulders"],"instructions":["Sit down on a pull-down machine with a V-Bar attached to the top pulley.","Adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.","Grab the V-bar with the palms facing each other (a neutral grip). Stick your chest out and lean yourself back slightly (around 30-degrees) in order to better engage the lats. This will be your starting position.","Using your lats, pull the bar down as you squeeze your shoulder blades. Continue until your chest nearly touches the V-bar. Exhale as you execute this motion. Tip: Keep the torso stationary throughout the movement.","After a second hold on the contracted position, slowly bring the bar back to the starting position as you breathe in.","Repeat for the prescribed number of repetitions."],"category":"strength","images":["V-Bar_Pulldown/0.jpg","V-Bar_Pulldown/1.jpg"],"id":"V-Bar_Pulldown"}'),
('free-exercise-db', 'V-Bar_Pullup', 'v-bar-pullup', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/V-Bar_Pullup.json', 'Unlicense', NULL, 'new', NULL, '{"name":"V-Bar Pullup","force":"pull","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["lats"],"secondaryMuscles":["biceps","middle back","shoulders"],"instructions":["Start by placing the middle of the V-bar in the middle of the pull-up bar (assuming that the pull-up station you are using does not have neutral grip handles). The V-Bar handles will be facing down so that you can hang from the pull-up bar through the use of the handles.","Once you securely place the V-bar, take a hold of the bar from each side and hang from it. Stick your chest out and lean yourself back slightly in order to better engage the lats. This will be your starting position.","Using your lats, pull your torso up while leaning your head back slightly so that you do not hit yourself with the chin-up bar. Continue until your chest nearly touches the V-bar. Exhale as you execute this motion.","After a second hold on the contracted position, slowly lower your body back to the starting position as you breathe in.","Repeat for the prescribed number of repetitions."],"category":"strength","images":["V-Bar_Pullup/0.jpg","V-Bar_Pullup/1.jpg"],"id":"V-Bar_Pullup"}'),
('free-exercise-db', 'Vertical_Swing', 'dumbbell-vertical-swing', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Vertical_Swing.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Vertical Swing","force":"pull","level":"beginner","mechanic":"compound","equipment":"dumbbell","primaryMuscles":["hamstrings"],"secondaryMuscles":["glutes","quadriceps","shoulders"],"instructions":["Allow the dumbbell to hang at arms length between your legs, holding it with both hands. Keep your back straight and your head up.","Swing the dumbbell between your legs, flexing at the hips and bending the knees slightly.","Powerfully reverse the motion by extending at the hips, knees, and ankles to propel yourself upward, swinging the dumbell over your head.","As you land, absorb the impact through your legs and draw the dumbbell to your torso before the next repetition."],"category":"plyometrics","images":["Vertical_Swing/0.jpg","Vertical_Swing/1.jpg"],"id":"Vertical_Swing"}'),
('free-exercise-db', 'Walking_Treadmill', 'machine-walking-treadmill', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Walking_Treadmill.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Walking, Treadmill","force":null,"level":"beginner","mechanic":null,"equipment":"machine","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings"],"instructions":["To begin, step onto the treadmill and select the desired option from the menu. Most treadmills have a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout.","Treadmills offer convenience, cardiovascular benefits, and usually have less impact than walking outside. When walking, you should move at a moderate to fast pace, not a leisurely one. Being an activity of lower intensity, walking doesn''t burn as many calories as some other activities, but still provides great benefit. A 150 lb person will burn about 175 calories walking 4 miles per hour for 30 minutes, compared to 450 calories running twice as fast. Maintain proper posture as you walk, and only hold onto the handles when necessary, such as when dismounting or checking your heart rate."],"category":"cardio","images":["Walking_Treadmill/0.jpg","Walking_Treadmill/1.jpg"],"id":"Walking_Treadmill"}'),
('free-exercise-db', 'Weighted_Ball_Hyperextension', 'exercise-ball-weighted-ball-hyperextension', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Weighted_Ball_Hyperextension.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Weighted Ball Hyperextension","force":"pull","level":"intermediate","mechanic":"compound","equipment":"exercise ball","primaryMuscles":["lower back"],"secondaryMuscles":["glutes","hamstrings","middle back"],"instructions":["To begin, lie down on an exercise ball with your torso pressing against the ball and parallel to the floor. The ball of your feet should be pressed against the floor to help keep you balanced. Place a weighted plate under your chin or behind your neck. This is the starting position.","Slowly raise your torso up by bending at the waist and lower back. Remember to exhale during this movement.","Hold the contraction on your lower back for a second and lower your torso back down to the starting position while inhaling.","Repeat for the recommended amount of repetitions prescribed in your program."],"category":"strength","images":["Weighted_Ball_Hyperextension/0.jpg","Weighted_Ball_Hyperextension/1.jpg"],"id":"Weighted_Ball_Hyperextension"}'),
('free-exercise-db', 'Weighted_Ball_Side_Bend', 'exercise-ball-weighted-ball-side-bend', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Weighted_Ball_Side_Bend.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Weighted Ball Side Bend","force":"pull","level":"intermediate","mechanic":"isolation","equipment":"exercise ball","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["To begin, lie down on an exercise ball with your left side of the torso (waist, hips and shoulder) pressed against the ball.","Your feet should be on the floor while your legs are crossed and hanging from the ball. Hold a weighted plate with your right hand directly to the right side of your head. Tip: Make sure the smooth side of the plate is resting against your head.","Place your left arm across your torso so that your palm is on your obliques. There should be a right angle between your left forearm and upper arm. This is the starting position.","Raise the side of your torso up by laterally flexing at the waist while exhaling.","Hold the contraction for a second and slowly lower yourself back down to the starting position while inhaling.","Repeat for the recommended amount of repetitions.","Switch sides and repeat the exercise."],"category":"strength","images":["Weighted_Ball_Side_Bend/0.jpg","Weighted_Ball_Side_Bend/1.jpg"],"id":"Weighted_Ball_Side_Bend"}'),
('free-exercise-db', 'Weighted_Bench_Dip', 'weighted-bench-dip', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Weighted_Bench_Dip.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Weighted Bench Dip","force":"push","level":"intermediate","mechanic":"compound","equipment":"other","primaryMuscles":["triceps"],"secondaryMuscles":["chest","shoulders"],"instructions":["For this exercise you will need to place a bench behind your back and another one in front of you. With the benches perpendicular to your body, hold on to one bench on its edge with the hands close to your body, separated at shoulder width. Your arms should be fully extended.","The legs will be extended forward on top of the other bench. Your legs should be parallel to the floor while your torso is to be perpendicular to the floor. Have your partner place the dumbbell on your lap. Note: This exercise is best performed with a partner as placing the weight on your lap can be challenging and cause injury without assistance. This will be your starting position.","Slowly lower your body as you inhale by bending at the elbows until you lower yourself far enough to where there is an angle slightly smaller than 90 degrees between the upper arm and the forearm. Tip: Keep the elbows as close as possible throughout the movement. Forearms should always be pointing down.","Using your triceps to bring your torso up again, lift yourself back to the starting position while exhaling.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Weighted_Bench_Dip/0.jpg","Weighted_Bench_Dip/1.jpg"],"id":"Weighted_Bench_Dip"}'),
('free-exercise-db', 'Weighted_Crunches', 'medicine-ball-weighted-crunch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Weighted_Crunches.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Weighted Crunches","force":"pull","level":"beginner","mechanic":"isolation","equipment":"medicine ball","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Lie flat on your back with your feet flat on the ground or resting on a bench with your knees bent at a 90 degree angle.","Hold a weight to your chest, or you may hold it extended above your torso. This will be your starting position.","Now, exhale and slowly begin to roll your shoulders off the floor. Your shoulders should come up off the floor about 4 inches while your lower back remains on the floor.","At the top of the movement, flex your abdominals and hold for a brief pause.","Then inhale and slowly lower yourself back down to the starting position."],"category":"strength","images":["Weighted_Crunches/0.jpg","Weighted_Crunches/1.jpg"],"id":"Weighted_Crunches"}'),
('free-exercise-db', 'Weighted_Jump_Squat', 'barbell-weighted-jump-squat', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Weighted_Jump_Squat.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Weighted Jump Squat","force":"push","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings","lower back"],"instructions":["Position a lightly loaded barbell across the back of your shoulders. You could also use a weighted vest, sandbag, or other type of resistance for this exercise.","The weight should be light enough that it doesn''t slow you down significantly. Your feet should be just outside of shoulder width with your head and chest up. This will be your starting position.","Using a countermovement, squat partially down and immediately reverse your direction to explode off of the ground, extending through your hips, knees, and ankles. Maintain good posture throughout the jump.","As you return to the ground, absorb the impact through your legs."],"category":"strength","images":["Weighted_Jump_Squat/0.jpg","Weighted_Jump_Squat/1.jpg"],"id":"Weighted_Jump_Squat"}'),
('free-exercise-db', 'Weighted_Pull_Ups', 'weighted-pull-up', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Weighted_Pull_Ups.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Weighted Pull Ups","force":"pull","level":"intermediate","mechanic":"compound","equipment":"other","primaryMuscles":["lats"],"secondaryMuscles":["biceps","middle back"],"instructions":["Attach a weight to a dip belt and secure it around your waist. Grab the pull-up bar with the palms of your hands facing forward. For a medium grip, your hands should be spaced at shoulder width. Both arms should be extended in front of you holding the bar at the chosen grip.","You''ll want to bring your torso back about 30 degrees while creating a curvature in your lower back and sticking your chest out. This will be your starting position.","Now, exhale and pull your torso up until your head is above your hands. Concentrate on squeezing yourshoulder blades back and down as you reach the top contracted position.","After a brief moment at the top contracted position, inhale and slowly lower your torso back to the starting position with your arms extended and your lats fully stretched."],"category":"strength","images":["Weighted_Pull_Ups/0.jpg","Weighted_Pull_Ups/1.jpg"],"id":"Weighted_Pull_Ups"}'),
('free-exercise-db', 'Weighted_Sissy_Squat', 'barbell-weighted-sissy-squat', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Weighted_Sissy_Squat.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Weighted Sissy Squat","force":"push","level":"expert","mechanic":"compound","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings"],"instructions":["Standing upright, with feet at shoulder width and toes raised, use one hand to hold onto the beams of a squat rack and the opposite arm to hold a plate on top of your chest. This is your starting position.","As you use one arm to hold yourself, bend at the knees and slowly lower your torso toward the ground by bringing your pelvis and knees forward. Inhale as you go down and stop when your upper and lower legs almost create a 90-degree angle. Hold the stretch position for a second.","After your one second hold, use your thigh muscles to bring your torso back up to the starting position. Exhale as you move up.","Repeat for the recommended amount of times."],"category":"strength","images":["Weighted_Sissy_Squat/0.jpg","Weighted_Sissy_Squat/1.jpg"],"id":"Weighted_Sissy_Squat"}'),
('free-exercise-db', 'Weighted_Sit-Ups_-_With_Bands', 'band-weighted-sit-up', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Weighted_Sit-Ups_-_With_Bands.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Weighted Sit-Ups - With Bands","force":"pull","level":"intermediate","mechanic":"isolation","equipment":"other","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Start out by strapping the bands around the base of the decline bench. Place the handles towards the inside of the decline bench so that when lying down, you can reach for both of them.","Position your legs through the decline machine until they are secured. Now reach for the exercise bands with both hands. Use a pronated (palms forward) grip to grasp the handles. Position them near your collar bone and rotate your wrist to a neutral grip (palms facing the torso). Note: Your arms should remain stationary throughout the exercise. This is the starting position.","Move your torso upward until your upper body is perpendicular to the floor while exhaling. Hold the contraction for a second and lower your upper body back down to the starting position while inhaling.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Weighted_Sit-Ups_-_With_Bands/0.jpg","Weighted_Sit-Ups_-_With_Bands/1.jpg"],"id":"Weighted_Sit-Ups_-_With_Bands"}'),
('free-exercise-db', 'Weighted_Squat', 'weighted-squat', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Weighted_Squat.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Weighted Squat","force":"push","level":"intermediate","mechanic":"compound","equipment":"other","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings"],"instructions":["Start by positioning two flat benches shoulder width apart from each other. Stand on top of them and wrap the weighted belt around your waist with the amount of weight you feel comfortable with. Make sure your toes are facing out.","Once you are standing straight up with the weight hanging in between your legs, position your arms so that they are fully extended to the side of your body. This is the starting position.","Begin by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that are perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to move the body back up by pushing the floor of the flat bench with the ball of your foot mainly as you straighten the legs again and go back to the starting position. Exhale as you perform this portion of the exercise.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Weighted_Squat/0.jpg","Weighted_Squat/1.jpg"],"id":"Weighted_Squat"}'),
('free-exercise-db', 'Wide-Grip_Barbell_Bench_Press', 'barbell-wide-grip-bench-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Wide-Grip_Barbell_Bench_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Wide-Grip Barbell Bench Press","force":"push","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["Lie back on a flat bench with feet firm on the floor. Using a wide, pronated (palms forward) grip that is around 3 inches away from shoulder width (for each hand), lift the bar from the rack and hold it straight over you with your arms locked. The bar will be perpendicular to the torso and the floor. This will be your starting position.","As you breathe in, come down slowly until you feel the bar on your middle chest.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions."],"category":"strength","images":["Wide-Grip_Barbell_Bench_Press/0.jpg","Wide-Grip_Barbell_Bench_Press/1.jpg"],"id":"Wide-Grip_Barbell_Bench_Press"}'),
('free-exercise-db', 'Wide-Grip_Decline_Barbell_Bench_Press', 'barbell-wide-grip-decline-bench-press', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Wide-Grip_Decline_Barbell_Bench_Press.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Wide-Grip Decline Barbell Bench Press","force":"push","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["Lie back on a decline bench with the feet securely locked at the front of the bench. Using a wide, pronated (palms forward) grip that is around 3 inches away from shoulder width (for each hand), lift the bar from the rack and hold it straight over you with your arms locked. The bar will be perpendicular to the torso and the floor. This will be your starting position.","As you breathe in, come down slowly until you feel the bar on your lower chest.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions."],"category":"strength","images":["Wide-Grip_Decline_Barbell_Bench_Press/0.jpg","Wide-Grip_Decline_Barbell_Bench_Press/1.jpg"],"id":"Wide-Grip_Decline_Barbell_Bench_Press"}'),
('free-exercise-db', 'Wide-Grip_Decline_Barbell_Pullover', 'barbell-wide-grip-decline-pullover', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Wide-Grip_Decline_Barbell_Pullover.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Wide-Grip Decline Barbell Pullover","force":"pull","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["Lie down on a decline bench with both legs securely locked in position. Reach for the barbell behind the head using a pronated grip (palms facing out). Make sure to grab the barbell wider than shoulder width apart for this exercise. Slowly lift the barbell up from the floor by using your arms.","When positioned properly, your arms should be fully extended and perpendicular to the floor. This is the starting position.","Begin by moving the barbell back down in a semicircular motion as if you were going to place it on the floor, but instead, stop when the arms are parallel to the floor. Tip: Keep the arms fully extended at all times. The movement should only happen at the shoulder joint. Inhale as you perform this portion of the movement.","Now bring the barbell up while exhaling until you are back at the starting position. Remember to keep full control of the barbell at all times.","Repeat the movement for the prescribed amount of repetitions of your training program.","When finished with your set, slowly lower the barbell back down until it is level with your head and release it."],"category":"strength","images":["Wide-Grip_Decline_Barbell_Pullover/0.jpg","Wide-Grip_Decline_Barbell_Pullover/1.jpg"],"id":"Wide-Grip_Decline_Barbell_Pullover"}'),
('free-exercise-db', 'Wide-Grip_Lat_Pulldown', 'cable-wide-grip-lat-pulldown', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Wide-Grip_Lat_Pulldown.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Wide-Grip Lat Pulldown","force":"pull","level":"beginner","mechanic":"compound","equipment":"cable","primaryMuscles":["lats"],"secondaryMuscles":["biceps","middle back","shoulders"],"instructions":["Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.","Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.","As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.","As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the bar; therefore do not try to pull down the bar using the forearms.","After a second at the contracted position squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.","Repeat this motion for the prescribed amount of repetitions."],"category":"strength","images":["Wide-Grip_Lat_Pulldown/0.jpg","Wide-Grip_Lat_Pulldown/1.jpg"],"id":"Wide-Grip_Lat_Pulldown"}'),
('free-exercise-db', 'Wide-Grip_Pulldown_Behind_The_Neck', 'cable-wide-grip-pulldown-behind-neck', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Wide-Grip_Pulldown_Behind_The_Neck.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Wide-Grip Pulldown Behind The Neck","force":"pull","level":"intermediate","mechanic":"compound","equipment":"cable","primaryMuscles":["lats"],"secondaryMuscles":["biceps","middle back","shoulders"],"instructions":["Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.","Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.","As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso and head forward. Think of an imaginary line from the center of the bar down to the back of your neck. This is your starting position.","As you breathe out, bring the bar down until it touches the back of your neck by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the bar; therefore do not try to pull down the bar using the forearms.","After a second on the contracted position squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.","Repeat this motion for the prescribed amount of repetitions."],"category":"strength","images":["Wide-Grip_Pulldown_Behind_The_Neck/0.jpg","Wide-Grip_Pulldown_Behind_The_Neck/1.jpg"],"id":"Wide-Grip_Pulldown_Behind_The_Neck"}'),
('free-exercise-db', 'Wide-Grip_Rear_Pull-Up', 'wide-grip-rear-pull-up', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Wide-Grip_Rear_Pull-Up.json', 'Unlicense', NULL, 'new', 85.7, '{"name":"Wide-Grip Rear Pull-Up","force":"pull","level":"intermediate","mechanic":"compound","equipment":"body only","primaryMuscles":["lats"],"secondaryMuscles":["biceps","middle back","shoulders"],"instructions":["Grab the pull-up bar with the palms facing forward using a wide grip.","As you have both arms extended in front of you holding the bar, bring your torso forward and head so that there is an imaginary line from the pull-up bar to the back of your neck. This is your starting position.","Pull your torso up until the bar is near the back of your neck. To do this, draw the shoulders and upper arms down and back while slightly leaning your head forward. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.","After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.","Repeat this motion for the prescribed amount of repetitions."],"category":"strength","images":["Wide-Grip_Rear_Pull-Up/0.jpg","Wide-Grip_Rear_Pull-Up/1.jpg"],"id":"Wide-Grip_Rear_Pull-Up"}'),
('free-exercise-db', 'Wide-Grip_Standing_Barbell_Curl', 'barbell-wide-grip-standing-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Wide-Grip_Standing_Barbell_Curl.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Wide-Grip Standing Barbell Curl","force":"pull","level":"beginner","mechanic":"isolation","equipment":"barbell","primaryMuscles":["biceps"],"secondaryMuscles":[],"instructions":["Stand up with your torso upright while holding a barbell at the wide outer handle. The palm of your hands should be facing forward. The elbows should be close to the torso. This will be your starting position.","While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move.","Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.","Slowly begin to bring the bar back to starting position as your breathe in.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Wide-Grip_Standing_Barbell_Curl/0.jpg","Wide-Grip_Standing_Barbell_Curl/1.jpg"],"id":"Wide-Grip_Standing_Barbell_Curl"}'),
('free-exercise-db', 'Wide_Stance_Barbell_Squat', 'barbell-wide-stance-squat', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Wide_Stance_Barbell_Squat.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Wide Stance Barbell Squat","force":"push","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings","lower back"],"instructions":["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.","Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.","Step away from the rack and position your legs using a wider-than-shoulder-width stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance, and also maintain a straight back. This will be your starting position.","Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Wide_Stance_Barbell_Squat/0.jpg","Wide_Stance_Barbell_Squat/1.jpg"],"id":"Wide_Stance_Barbell_Squat"}'),
('free-exercise-db', 'Wide_Stance_Stiff_Legs', 'barbell-wide-stance-stiff-legs', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Wide_Stance_Stiff_Legs.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Wide Stance Stiff Legs","force":"pull","level":"intermediate","mechanic":"compound","equipment":"barbell","primaryMuscles":["hamstrings"],"secondaryMuscles":["adductors","glutes","lower back"],"instructions":["Begin with a barbell loaded on the floor. Adopt a wide stance, and then bend at the hips to grab the bar. Your hips should be as far back as possible, and your legs nearly straight. Keep your back straight, and your head and chest up. This will be your starting position.","Begin the movement be engaging the hips, driving them forward as you allow the arms to hang straight. Continue until you are standing straight up, and then slowly return the weight to the starting position. For successive reps, the weight need not touch the floor."],"category":"olympic weightlifting","images":["Wide_Stance_Stiff_Legs/0.jpg","Wide_Stance_Stiff_Legs/1.jpg"],"id":"Wide_Stance_Stiff_Legs"}'),
('free-exercise-db', 'Wind_Sprints', 'wind-sprint', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Wind_Sprints.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Wind Sprints","force":"pull","level":"beginner","mechanic":"compound","equipment":"body only","primaryMuscles":["abdominals"],"secondaryMuscles":[],"instructions":["Hang from a pull-up bar using a pronated grip. Your arms and legs should be extended. This will be your starting position.","Begin by quickly raising one knee as high as you can. Do not swing your body or your legs. 3","Immediately reverse the motion, returning that leg to the starting position. Simultaneously raise the opposite knee as high as possible.","Continue alternating between legs until the set is complete."],"category":"strength","images":["Wind_Sprints/0.jpg","Wind_Sprints/1.jpg"],"id":"Wind_Sprints"}'),
('free-exercise-db', 'Windmills', 'windmill', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Windmills.json', 'Unlicense', NULL, 'new', 100.0, '{"name":"Windmills","force":"pull","level":"intermediate","mechanic":null,"equipment":null,"primaryMuscles":["abductors"],"secondaryMuscles":["glutes","hamstrings","lower back"],"instructions":["Lie on your back with your arms extended out to the sides and your legs straight. This will be your starting position.","Lift one leg and quickly cross it over your body, attempting to touch the ground near the opposite hand.","Return to the starting position, and repeat with the opposite leg. Continue to alternate for 10-20 repetitions."],"category":"stretching","images":["Windmills/0.jpg","Windmills/1.jpg"],"id":"Windmills"}'),
('free-exercise-db', 'Worlds_Greatest_Stretch', 'worlds-greatest-stretch', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Worlds_Greatest_Stretch.json', 'Unlicense', NULL, 'new', NULL, '{"name":"World''s Greatest Stretch","force":"static","level":"intermediate","mechanic":null,"equipment":null,"primaryMuscles":["hamstrings"],"secondaryMuscles":["calves","glutes","quadriceps"],"instructions":["This is a three-part stretch. Begin by lunging forward, with your front foot flat on the ground and on the toes of your back foot. With your knees bent, squat down until your knee is almost touching the ground. Keep your torso erect, and hold this position for 10-20 seconds.","Now, place the arm on the same side as your front leg on the ground, with the elbow next to the foot. Your other hand should be placed on the ground, parallel to your lead leg, to help support you during this portion of the stretch.","After 10-20 seconds, place your hands on either side of your front foot. Raise the toes of the front foot off of the ground, and straighten your leg. You may need to reposition your rear leg to do so. Hold for 10-20 seconds, and then repeat the entire sequence for the other side."],"category":"stretching","images":["Worlds_Greatest_Stretch/0.jpg","Worlds_Greatest_Stretch/1.jpg"],"id":"Worlds_Greatest_Stretch"}'),
('free-exercise-db', 'Wrist_Circles', 'wrist-circle', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Wrist_Circles.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Wrist Circles","force":"pull","level":"beginner","mechanic":"isolation","equipment":"body only","primaryMuscles":["forearms"],"secondaryMuscles":[],"instructions":["Start by standing straight with your feet being shoulder width apart from each other. Elevate your arms to the side of you until they are fully extended and parallel to the floor at a height that is evenly aligned with your shoulders. Tip: Your torso and arms should form the letter \"T: Your palms should be facing down. This is the starting position.","Keeping your entire body stationary except for the wrists, begin to rotate both wrists forward in a circular motion. Tip: Pretend that you are trying to draw circles by using your hands as the brush. Breathe normally as you perform this exercise.","Repeat for the recommended amount of repetitions."],"category":"stretching","images":["Wrist_Circles/0.jpg","Wrist_Circles/1.jpg"],"id":"Wrist_Circles"}'),
('free-exercise-db', 'Wrist_Roller', 'wrist-roller', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Wrist_Roller.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Wrist Roller","force":"pull","level":"beginner","mechanic":"isolation","equipment":"other","primaryMuscles":["forearms"],"secondaryMuscles":["shoulders"],"instructions":["To begin, stand straight up grabbing a wrist roller using a pronated grip (palms facing down). Your feet should be shoulder width apart.","Slowly lift both arms until they are fully extended and parallel to the floor in front of you. Note: Make sure the rope is not wrapped around the roller. Your entire body should be stationary except for the forearms. This is the starting position.","Rotate one wrist at a time in an upward motion to bring the weight up to the bar by rolling the rope around the roller.","Once the weight has reached the bar, slowly begin to lower the weight back down by rotating the wrist in a downward motion until the weight reaches the starting position.","Repeat for the prescribed amount of repetitions in your program."],"category":"strength","images":["Wrist_Roller/0.jpg","Wrist_Roller/1.jpg"],"id":"Wrist_Roller"}'),
('free-exercise-db', 'Wrist_Rotations_with_Straight_Bar', 'barbell-wrist-rotation-straight-bar', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Wrist_Rotations_with_Straight_Bar.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Wrist Rotations with Straight Bar","force":"pull","level":"beginner","mechanic":"isolation","equipment":"barbell","primaryMuscles":["forearms"],"secondaryMuscles":[],"instructions":["Hold a barbell with both hands and your palms facing down; hands spaced about shoulder width. This will be your starting position.","Alternating between each of your hands, perform the movement by extending the wrist as though you were rolling up a newspaper. Continue alternating back and forth until failure.","Reverse the motion by flexing the wrist, rolling the opposite direction. Continue the alternating motion until failure."],"category":"strength","images":["Wrist_Rotations_with_Straight_Bar/0.jpg","Wrist_Rotations_with_Straight_Bar/1.jpg"],"id":"Wrist_Rotations_with_Straight_Bar"}'),
('free-exercise-db', 'Yoke_Walk', 'yoke-walk', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Yoke_Walk.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Yoke Walk","force":null,"level":"intermediate","mechanic":"compound","equipment":"other","primaryMuscles":["quadriceps"],"secondaryMuscles":["abdominals","abductors","adductors","calves","glutes","hamstrings","lower back"],"instructions":["The yoke is usually done with a yoke apparatus, but is sometimes seen with refrigerators or other heavy objects.","Begin by racking the apparatus across the back of the shoulders. With your head looking forward and back arched, lift the yoke by driving through the heels.","Begin walking as quickly as possible using short, quick steps. You may hold the side posts of the yoke to help steady it and hold it in position. Continue for the given distance as fast as possible, usually 75-100 feet."],"category":"strongman","images":["Yoke_Walk/0.jpg","Yoke_Walk/1.jpg"],"id":"Yoke_Walk"}'),
('free-exercise-db', 'Zercher_Squats', 'barbell-zercher-squat', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Zercher_Squats.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Zercher Squats","force":"push","level":"expert","mechanic":"compound","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["calves","glutes","hamstrings"],"instructions":["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. The correct height should be anywhere above the waist but below the chest. Once the correct height is chosen and the bar is loaded, lock your hands together and place the bar on top of your arms in between the forearm and upper arm.","Lift the bar up so that it is resting on top of your forearms. If you are holding the bar properly, it should look as if you have your arms crossed but with a bar running across them.","Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section).","Begin to lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise the bar as you exhale by pushing the floor with the ball of your foot mainly as you straighten the legs again and go back to the starting position.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Zercher_Squats/0.jpg","Zercher_Squats/1.jpg"],"id":"Zercher_Squats"}'),
('free-exercise-db', 'Zottman_Curl', 'dumbbell-zottman-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Zottman_Curl.json', 'Unlicense', NULL, 'exact', 100.0, '{"name":"Zottman Curl","force":"pull","level":"intermediate","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["biceps"],"secondaryMuscles":["forearms"],"instructions":["Stand up with your torso upright and a dumbbell in each hand being held at arms length. The elbows should be close to the torso.","Make sure the palms of the hands are facing each other. This will be your starting position.","While holding the upper arm stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Your wrist should rotate so that you have a supinated (palms up) grip. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a second as you squeeze the biceps.","Now during the contracted position, rotate your wrist until you now have a pronated (palms facing down) grip with the thumb at a higher position than the pinky.","Slowly begin to bring the dumbbells back down using the pronated grip.","As the dumbbells close your thighs, start rotating the wrist so that you go back to a neutral (palms facing your body) grip.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Zottman_Curl/0.jpg","Zottman_Curl/1.jpg"],"id":"Zottman_Curl"}'),
('free-exercise-db', 'Zottman_Preacher_Curl', 'dumbbell-zottman-preacher-curl', 'https://github.com/yuhonas/free-exercise-db/blob/f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5/exercises/Zottman_Preacher_Curl.json', 'Unlicense', NULL, 'new', NULL, '{"name":"Zottman Preacher Curl","force":"pull","level":"intermediate","mechanic":"isolation","equipment":"dumbbell","primaryMuscles":["biceps"],"secondaryMuscles":["forearms"],"instructions":["Grab a dumbbell in each hand and place your upper arms on top of the preacher bench or the incline bench. The dumbbells should be held at shoulder height and the elbows should be flexed. Hold the dumbbells with the palms of your hands facing down. This will be your starting position.","As you breathe in, slowly lower the dumbbells keeping the palms down until your upper arm is extended and your biceps are fully stretched.","Now rotate your wrists once you are at the bottom of the movement so that the palms of the hands are facing up.","As you exhale, use your biceps to curl the weights up until they are fully contracted and the dumbbells are at shoulder height. Again, remember that to ensure full contraction you need to bring that small finger higher than the thumb.","Squeeze the biceps hard for a second at the contracted position and rotate your wrists so that the palms are facing down again.","Repeat for the recommended amount of repetitions."],"category":"strength","images":["Zottman_Preacher_Curl/0.jpg","Zottman_Preacher_Curl/1.jpg"],"id":"Zottman_Preacher_Curl"}'),
('longhaul-fitness', '1', NULL, 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/cardio.json', 'MIT', 'Longhaul Fitness', NULL, NULL, '{"pk":1,"name":"Run","slug":"run","instructions":["Running is a versatile form of cardiovascular exercise that involves rhythmic, continuous movement of the legs and arms. It can be performed at various speeds and intensities, making it suitable for enhancing endurance, burning calories, and improving overall fitness. Runners can enjoy the activity outdoors on various terrains or indoors on a treadmill, fostering flexibility in workout routines and locations."]}'),
('longhaul-fitness', '2', NULL, 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/cardio.json', 'MIT', 'Longhaul Fitness', NULL, NULL, '{"pk":2,"name":"Bike","slug":"bike","instructions":["Biking, or cycling, is a low-impact, cardiovascular exercise that involves using a bicycle to move across varying terrains or on stationary equipment. It''s effective for building leg strength, improving joint mobility, and boosting cardiovascular endurance. Suitable for all fitness levels, biking can be enjoyed outdoors on roads and trails, or indoors on a stationary bike, providing a versatile workout option."]}'),
('longhaul-fitness', '3', NULL, 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/cardio.json', 'MIT', 'Longhaul Fitness', NULL, NULL, '{"pk":3,"name":"Row","slug":"row","instructions":["Rowing is a full-body, low-impact cardiovascular exercise that engages multiple muscle groups including legs, arms, back, and core. It involves a synchronized motion on a rowing machine or in a boat, combining resistance and cardiovascular training to improve fitness and endurance. Suitable for indoor and outdoor settings, rowing offers a highly effective workout that enhances strength, cardiovascular health, and coordination, making it a comprehensive exercise choice for individuals of various fitness levels."]}'),
('longhaul-fitness', '4', NULL, 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/cardio.json', 'MIT', 'Longhaul Fitness', NULL, NULL, '{"pk":4,"name":"Elliptical","slug":"elliptical","instructions":["Elliptical training is a low-impact, cardio exercise performed on an elliptical machine, which mimics the natural motion of running without the harsh impact on joints. It simultaneously engages both the upper and lower body, promoting overall muscular endurance and cardiovascular fitness. Suitable for all fitness levels, using an elliptical provides a versatile workout option that can be adjusted for intensity and is particularly beneficial for those seeking a joint-friendly exercise alternative."]}'),
('longhaul-fitness', '5', NULL, 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/cardio.json', 'MIT', 'Longhaul Fitness', NULL, NULL, '{"pk":5,"name":"Stair Climb","slug":"stair-climb","instructions":["Elliptical training is a low-impact, cardio exercise performed on an elliptical machine, which mimics the natural motion of running without the harsh impact on joints. It simultaneously engages both the upper and lower body, promoting overall muscular endurance and cardiovascular fitness. Suitable for all fitness levels, using an elliptical provides a versatile workout option that can be adjusted for intensity and is particularly beneficial for those seeking a joint-friendly exercise alternative."]}'),
('longhaul-fitness', '6', NULL, 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/cardio.json', 'MIT', 'Longhaul Fitness', NULL, NULL, '{"pk":6,"name":"Swim","slug":"swim","instructions":["Swimming is a full-body, low-impact exercise performed in water, encompassing various strokes like freestyle, breaststroke, backstroke, and butterfly. It engages multiple muscle groups, improves cardiovascular stamina, and enhances flexibility, all while providing buoyant support that minimizes stress on joints. Ideal for all ages and fitness levels, swimming offers both therapeutic and fitness benefits, making it a highly effective workout for overall health and conditioning."]}'),
('longhaul-fitness', '7', NULL, 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/cardio.json', 'MIT', 'Longhaul Fitness', NULL, NULL, '{"pk":7,"name":"Jump Rope","slug":"jump-rope","instructions":["Jump rope is a dynamic cardiovascular exercise that involves swinging a rope beneath your feet and over your head in a continuous rhythm. This activity not only elevates your heart rate, promoting cardiovascular health, but also enhances coordination, agility, and lower body strength. Perfect for varying intensity levels and incorporating into high-intensity interval training, jump rope is portable, can be done almost anywhere, and is effective for burning calories in short periods. It offers a full-body workout, engaging both lower and upper body muscles, making it a comprehensive and versatile exercise choice."]}'),
('longhaul-fitness', '8', NULL, 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/cardio.json', 'MIT', 'Longhaul Fitness', NULL, NULL, '{"pk":8,"name":"Aerobics Class","slug":"aerobics-class","instructions":["Aerobics classes involve a series of rhythmic exercises often set to music, primarily aiming to improve cardiovascular fitness and endurance. These classes combine elements of dance, stretching, and strength training to target various muscle groups and boost overall health. Suitable for varying fitness levels, aerobics offers a fun, social environment that can help maintain motivation and improve mood, making it a popular choice for those looking to enhance their fitness in a group setting. These classes are also adaptable, with options ranging from low-impact for beginners or those with joint issues, to high-intensity for more advanced fitness enthusiasts."]}'),
('longhaul-fitness', '9', NULL, 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/cardio.json', 'MIT', 'Longhaul Fitness', NULL, NULL, '{"pk":9,"name":"High-Intensity Interval Training (HIIT)","slug":"high-intensity-interval-training","instructions":["High-Intensity Interval Training (HIIT) is a training technique that involves short bursts of intense exercise alternated with low-intensity recovery periods. HIIT is highly efficient in boosting cardiovascular fitness, increasing metabolism, and burning calories. Suitable for a variety of fitness enthusiasts from moderate to high fitness levels, HIIT can be adapted to many types of activities, including sprinting, biking, jump rope, or bodyweight exercises, making it a flexible and effective choice for those looking to maximize their workout efficiency."]}'),
('longhaul-fitness', '00535621-681b-4765-9b4f-ca82dc4df55a', 'dumbbell-standing-external-shoulder-rotation', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', 100.0, '{"pk":"00535621-681b-4765-9b4f-ca82dc4df55a","name":"Standing External Shoulder Rotation – Dumbbell","slug":"standing-external-shoulder-rotation-dumbbell","primaryMuscles":["rotator cuff - back"],"secondaryMuscles":["rotator cuff - front","shoulder - back","shoulder - front","shoulder - side"],"steps":["Stand with feet shoulder-width apart, holding a dumbbell in one hand.","Bend the arm at the shoulder to raise your upper arm, making it parallel to the floor and perpendicular to your body.","Bend your forearm at the elbow to a 90-degree angle so that your forearm is parallel to the floor, creating an ''L'' shape with your arm. This is the starting position.","Keeping your upper arm stationary, rotate your shoulder, lifting the dumbbell towards the ceiling as far as possible without discomfort.","Pause briefly at the top of the rotation, then slowly return the dumbbell to the starting position.","Complete the desired number of repetitions, then switch arms and repeat the exercise."],"notes":""}'),
('longhaul-fitness', '01212465-6e78-4c7a-826a-c7ca2dcdae2c', 'medicine-ball-seated-rotational-slam', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"01212465-6e78-4c7a-826a-c7ca2dcdae2c","name":"Seated Rotational Slam – Medicine Ball","slug":"seated-rotational-slam-medicine-ball","primaryMuscles":["abdominal","oblique"],"secondaryMuscles":["lat","lower back","shoulder - front"],"steps":["Sit with your feet extended in front of you, knees bent, and your feet or heels on the ground for stability. Hold the medicine ball with both hands near one hip. This is your starting position.","Begin the exercise by lifting the medicine ball in a circular motion on the same side, raising it up and over your head.","Continue the circular motion bringing the ball down with force on the opposite side.","Release the medicine ball towards the ground as you near the opposite hip from where you started, channeling maximum force through the slam.","Retrieve the medicine ball, return to the starting position on the opposite hip, and perform the exercise on the other side.","Repeat the exercise for the desired number of repetitions."],"notes":"Keep your arms extended, elbows slightly bent, throughout the exercise. Focus on creating big circles with your arms, avoiding the tendency to create smaller, easier circles, close to your chest."}'),
('longhaul-fitness', '03ded3cd-bba0-4f04-9afd-f7e321aec282', 'supinated-grip-lat-pulldown', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"03ded3cd-bba0-4f04-9afd-f7e321aec282","name":"Supinated Grip Lat Pulldown","slug":"supinated-grip-lat-pulldown","primaryMuscles":["lat"],"secondaryMuscles":["bicep","forearm - inner","rotator cuff - back","rotator cuff - front","shoulder - back"],"steps":["Adjust the weight on the lat pulldown machine to a comfortable level.","Stand facing the machine and grasp the bar with an underhand grip, with your hands shoulder-width apart.","Sit down on the bench and adjust the knee pad so that it fits snugly against your thighs.","Lean back slightly and keep your chest up and your shoulders down.","Exhale and pull the bar down towards your chest, keeping your elbows close to your body.","Pause for a moment and squeeze your shoulder blades together.","Inhale and slowly release the bar back to the starting position, keeping your arms straight but not locked.","Repeat."],"notes":""}'),
('longhaul-fitness', '04067604-fb64-4303-9d44-d26e7fed7e96', 'band-external-shoulder-rotation', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"04067604-fb64-4303-9d44-d26e7fed7e96","name":"External Shoulder Rotation – Band","slug":"external-shoulder-rotation-band","primaryMuscles":["rotator cuff - back"],"secondaryMuscles":[],"steps":["Attach a resistance band to a stable object at waist height.","Stand perpendicular to the anchor point with your right arm farthest away from it, and your feet shoulder-width apart.","Reach across your body with your right hand and grab the band.","Create resistance in the band by bringing your right elbow close to your right side where it hangs naturally.","This starting position has you with your right forearm across the front of your body, at a 90-degree angle to your right upper-arm.","Keep your core engaged and your shoulders relaxed.","Slowly rotate your arms outward, away from your body, until your right hand is in line with your right shoulder.","Pause for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions and then switch sides."],"notes":""}'),
('longhaul-fitness', '04f4ff32-ec03-4905-99a7-d669ff221de4', 'front-squat', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', 100.0, '{"pk":"04f4ff32-ec03-4905-99a7-d669ff221de4","name":"Front Squat","slug":"front-squat","primaryMuscles":["glute","lower back","quad","thigh - inner"],"secondaryMuscles":["calf"],"steps":["Load a barbell with weights on a rack at chest height.","Start by standing with your feet shoulder-width apart and your toes slightly turned out.","Hold a barbell across the front of your shoulders, resting it on your collarbone and shoulders. Keep your hands just outside your shoulders, holding the barbell with your palms facing up. Raise your elbows up and forward to create a shelf with your shoulders for the bar to rest on.","Engage your core and keep your chest up as you lower your body down into a squat position.","Bend your knees and push your hips back, keeping your weight in your heels.","Lower your body until your thighs are parallel to the ground, or as low as you can comfortably go.","Push through your heels to stand back up, keeping your core engaged and chest up throughout the movement.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '05ec369f-76e2-44c2-b748-648a5fe96323', 'cable-upright-upward-external-rotation', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"05ec369f-76e2-44c2-b748-648a5fe96323","name":"Upright Upward External Rotation – Cable","slug":"upright-upward-external-rotation-cable","primaryMuscles":["rotator cuff - back"],"secondaryMuscles":[],"steps":["Adjust the pulley on a cable machine to sternum-level and attach a handle to it.","Stand facing the machine, feet shoulder-width apart.","Grab the handle with one hand, palm facing down, keeping your upper arm parallel to the ground and your forearm pointing towards the pulley, also parallel to the ground. This is your starting position.","Begin to rotate your arm at the shoulder, moving your hand upward and backwards, keeping the upper arm stable and parallel to the ground throughout the movement.","Continue the rotation until your forearm is pointing straight up, perpendicular to the ground, maintaining a 90-degree angle at your elbow.","Lower the handle back down to the starting position in a controlled manner.","Complete the desired number of repetitions before switching arms to perform the exercise on the opposite side."],"notes":""}'),
('longhaul-fitness', '0641b6f6-8ef5-4120-907c-c3352d801432', 'inverted-row-2', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', 100.0, '{"pk":"0641b6f6-8ef5-4120-907c-c3352d801432","name":"Inverted Row","slug":"inverted-row","primaryMuscles":["lat","shoulder - back","trap"],"secondaryMuscles":["bicep","forearm - inner","forearm - outer","rotator cuff - back","rotator cuff - front"],"steps":["Set up a bar in a rack or Smith machine to about waist height. Ensure it is secure.","Lie on the ground underneath the bar which should be set just above where you can reach from the ground.","Grab the bar with a wide overhand grip.","Extend your legs out in front of you, resting your heels on the ground with legs straight.","Straighten your body and tighten your core so your body is in a straight line from head to heels. This is your starting position.","Keep your elbows at a neutral angle, roughly 45 degrees away from your body, and pull your chest towards the bar while squeezing your shoulder blades together.","Pause briefly with your chest close to the bar.","Lower yourself slowly and controlled back to the starting position."],"notes":"Raise the bar higher to increase the angle of your body to the ground and make the exercise easier."}'),
('longhaul-fitness', '06909d78-5f81-41f3-918b-d90abaf07c3f', 'barbell-stiff-legged-deadlift', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"06909d78-5f81-41f3-918b-d90abaf07c3f","name":"Stiff-Legged Deadlift – Barbell","slug":"stiff-legged-deadlift-barbell","primaryMuscles":["glute","hamstring","lower back"],"secondaryMuscles":["calf","forearm - inner","forearm - outer","trap","quad"],"steps":["Stand with your feet hip-width apart, holding a barbell in front of your thighs with straight arms using an overhand grip.","Position the bar so it is touching or nearly touching your legs.","Keep your legs straight or maintain a slight bend in the knees (do not lock them).","Brace your core, keep your upper back straight while slightly arching your lower back.","Inhale, then push your hips back and lower the bar towards the ground, hinging at the hips, not the waist.","Keep the bar close to your body to avoid putting undue stress on your lower back.","Lower the barbell as far down as your hamstring flexibility allows. You should feel a stretch in your hamstrings. Do not round your spine.","Exhale as you lift the bar back to the starting position by extending your hips and pushing them forward. Avoid using your back to pull; the motion should come from your hamstrings and glutes.","Squeeze your glutes at the top of the movement for a second before performing the next repetition.","Perform the desired number of repetitions while maintaining proper form, keeping the movement controlled and avoiding any jerky motions."],"notes":""}'),
('longhaul-fitness', '079c8688-a04e-4eee-8761-c7caff04751d', 'tire-flip', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"079c8688-a04e-4eee-8761-c7caff04751d","name":"Tire Flip","slug":"tire-flip","primaryMuscles":["glute","lower back","quad","thigh - inner"],"secondaryMuscles":["bicep","calf","chest","shoulder - front","trap"],"steps":["Stand facing the tire with your feet wider than shoulder-width apart, toes pointing slightly outwards to ensure a stable wide-leg squat stance.","Bend at the hips and knees to squat down and grab the bottom of the tire with your fingers underneath and palms facing towards you.","Keep your chest up, back straight, and engage your core to prepare to lift.","Drive through your heels and legs, lifting the tire off the ground using your entire body, especially your glutes, hamstrings, and quads.","Once the tire is lifted, quickly reposition your hands from underneath to a pushing position as the tire reaches knee to waist level.","Extend your hips forward powerfully, and use the momentum to flip the tire over by pushing it away from you.","Follow through with your arms to ensure the tire completes the flip and lands flat.","Reposition your feet as necessary and reset your stance to repeat the process for the desired number of reps."],"notes":""}'),
('longhaul-fitness', '07d48bff-e7e9-41a1-8ade-934b8bc6a4f7', 'dumbbell-one-handed-overhead-tricep-extension', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"07d48bff-e7e9-41a1-8ade-934b8bc6a4f7","name":"One-Handed Overhead Tricep Extension – Dumbbell","slug":"one-handed-overhead-tricep-extension-dumbbell","primaryMuscles":["tricep"],"secondaryMuscles":[],"steps":["Stand with your feet shoulder-width apart and hold a dumbbell in one hand.","Extend your arm straight up, holding the dumbbell above your head.","Bend your elbow and lower the dumbbell behind your head, keeping your upper arm stationary.","Pause for a moment, then extend your arm back up to the starting position.","Repeat for the desired number of reps, then switch to the other arm."],"notes":""}'),
('longhaul-fitness', '080ed4be-cc9a-4890-97cc-d6676aad6031', 'cable-high-to-low-wood-chop', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"080ed4be-cc9a-4890-97cc-d6676aad6031","name":"High to Low Wood Chop – Cable","slug":"high-to-low-wood-chop-cable","primaryMuscles":["oblique"],"secondaryMuscles":["abdominal"],"steps":["Attach a cable to a high pulley and select the desired weight.","Stand perpendicular to the cable with feet shoulder-width apart and knees slightly bent.","Grasp the handle with both hands and extend arms overhead, keeping them straight.","Engage core muscles and rotate torso diagonally downwards, pulling the cable down towards the opposite hip.","Bend knees and pivot back foot as needed to maintain balance and stability.","Pause briefly at the bottom of the movement, then reverse the motion and return to starting position.","Repeat for desired number of repetitions, then switch sides and repeat."],"notes":""}'),
('longhaul-fitness', '08125ff9-6197-44d2-810f-fcf0a65e3a54', 'barbell-forearm-roll-up', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"08125ff9-6197-44d2-810f-fcf0a65e3a54","name":"Forearm Roll-Up – Barbell","slug":"forearm-roll-up-barbell","primaryMuscles":["forearm - inner","forearm - outer"],"secondaryMuscles":[],"steps":["Set up a power rack placing a barbell at about chest height.","Select a kettlebell and an appropriately sized resistance band that can be looped around it.","Loop one end of the resistance band around the kettlebell securely.","Loop the other end of the resistance band around one end of the barbell securely, wrapping it twice to ensure the kettlebell is suspended and the band is taut.","Stand facing the barbell with your feet shoulder-width apart, positioning yourself slightly back to allow full range of motion for the barbell to roll.","Extend your arms forward and grasp the barbell with both hands using an overhand grip, placing your hands slightly wider than shoulder-width for stability. Place one hand on either side of the band connected to the barbell.","Begin with your right hand, rolling the barbell away from you as much as possible to contract your forearm muscles.","After rolling with your right hand, switch to your left hand and perform the same rolling motion, alternating between hands with each roll.","Continue this alternating pattern, rolling the barbell and lifting the kettlebell until you cannot roll any further or the kettlebell reaches its peak height.","Carefully reverse the rolling motion using alternate hands again to lower the kettlebell back to the starting position in a controlled manner."],"notes":""}'),
('longhaul-fitness', '0939d4bb-12f4-4c7a-a03b-d3c7893c5f53', 'machine-seated-row', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"0939d4bb-12f4-4c7a-a03b-d3c7893c5f53","name":"Seated Row – Machine","slug":"seated-row-machine","primaryMuscles":["lat","shoulder - back","trap"],"secondaryMuscles":["bicep","forearm - inner","rotator cuff - back","rotator cuff - front"],"steps":["Adjust the seat height so that the handles are at chest level.","Sit on the machine with your feet flat on the footrests and your knees slightly bent.","Grasp the handles with an overhand grip and keep your back straight.","Pull the handles towards your chest while keeping your elbows close to your body.","Pause for a moment and then slowly release the handles back to the starting position.","Repeat."],"notes":""}'),
('longhaul-fitness', '09a46dba-4999-4c4b-9ef2-4d0d64b9db2d', 'push-up-against-wall', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"09a46dba-4999-4c4b-9ef2-4d0d64b9db2d","name":"Push-Up Against Wall","slug":"push-up-against-wall","primaryMuscles":["chest","shoulder - front","tricep"],"secondaryMuscles":["abdominal"],"steps":["Stand facing a wall with your feet shoulder-width apart.","Place your hands on the wall at shoulder height, slightly wider than shoulder-width apart.","Step back a few feet, keeping your body straight and your core engaged.","Bend your elbows and lower your chest towards the wall, keeping your body in a straight line.","Push through your palms and straighten your arms to return to the starting position.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '0ac565aa-c74d-4bde-8ff4-c269ec63e2ae', 'barbell-pullover', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"0ac565aa-c74d-4bde-8ff4-c269ec63e2ae","name":"Pullover – Barbell","slug":"pullover-barbell","primaryMuscles":["chest","lat","tricep"],"secondaryMuscles":["rotator cuff - back","rotator cuff - front"],"steps":["Lie on a bench with your head and shoulders supported, and your feet flat on the floor.","Hold a barbell with a pronated grip (palms facing forward) slightly wider than shoulder-width, and press it up to arm''s length over your chest. This is your starting position.","Keep a slight bend in your elbows and lock your arms in this slightly bent position throughout the entire movement.","Inhale and slowly lower the barbell in an arc behind your head while keeping your arms straight, moving primarily at the shoulder joints.","Lower the barbell until your arms are parallel to the floor or until you feel a stretch in your chest or lats, whichever comes first.","Exhale as you reverse the motion, bringing the barbell back over your chest in the same arc motion.","Repeat for the desired number of reps."],"notes":""}'),
('longhaul-fitness', '0b1665ab-19bc-4c97-8b83-bcebf1af3362', 'jump-squat-bodyweight', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', 100.0, '{"pk":"0b1665ab-19bc-4c97-8b83-bcebf1af3362","name":"Jump Squat – Bodyweight","slug":"jump-squat-bodyweight","primaryMuscles":["calf","glute","hamstring","quad"],"secondaryMuscles":["abdominal","lower back"],"steps":["Stand with feet shoulder-width apart, toes slightly pointing outward, knees slightly bent.","Engage your core and keep your chest up. This is your starting position.","Lower your body into a squat, bending at the hips and knees until your thighs are parallel to the ground.","Ensure your knees do not extend past your toes.","Keep weight distributed evenly across your feet.","Once at the bottom of the squat, explosively push through your feet to jump upward.","Swing your arms downward to gain momentum.","Land softly, with knees slightly bent, returning to the starting position.","Repeat the jump squat for desired repetitions."],"notes":""}'),
('longhaul-fitness', '0be71de4-1995-4f8e-ac35-0b156604bb63', 'dumbbell-bench-press', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"0be71de4-1995-4f8e-ac35-0b156604bb63","name":"Bench Press – Dumbbell","slug":"bench-press-dumbbell","primaryMuscles":["chest","shoulder - front"],"secondaryMuscles":["tricep"],"steps":["Lie flat on a bench with your feet firmly planted on the ground.","Hold a dumbbell in each hand, palms facing forward, and extend your arms straight up over your chest.","Lower the dumbbells slowly towards your chest, keeping your elbows wide.","Pause for a moment when the dumbbells are just above your chest.","Push the dumbbells back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '0c08a586-856b-405d-82dc-518c3948250e', 'cable-one-handed-bayesian-curl', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"0c08a586-856b-405d-82dc-518c3948250e","name":"One-Handed Bayesian Curl – Cable","slug":"one-handed-bayesian-curl-cable","primaryMuscles":["bicep"],"secondaryMuscles":["forearm - inner","forearm - outer"],"steps":["Stand facing away from a cable machine with the pulley set to the lowest height.","Select an appropriate weight on the machine for your fitness level.","Grip the handle attached to the cable with one hand, your palm facing forward.","Keep your feet shoulder-width apart, back straight, and shoulders back.","Curl the handle towards your chest, focusing on contracting the biceps while keeping your elbow stationary and close to your body.","Pause at the top of the curl to squeeze the bicep muscle intensely.","Slowly lower the handle back to the starting position, controlling the movement throughout the descent.","Repeat the movement for the desired number of repetitions before switching arms."],"notes":""}'),
('longhaul-fitness', '0c5940e6-419e-476b-a1eb-39302e0aebe5', 'dumbbell-fly', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"0c5940e6-419e-476b-a1eb-39302e0aebe5","name":"Chest Fly – Dumbbell","slug":"chest-fly-dumbbell","primaryMuscles":["chest"],"secondaryMuscles":["bicep","forearm - inner","shoulder - front"],"steps":["Start by lying flat on a bench with your feet firmly on the ground and your head, shoulders, and buttocks touching the bench.","Hold a dumbbell in each hand with your palms facing each other and your arms extended above your chest.","Slowly lower the dumbbells out to the sides of your body, keeping your elbows slightly bent and your palms facing up.","Lower the dumbbells until your arms are parallel to the ground or until you feel a stretch in your chest muscles.","Pause for a moment, then slowly bring the dumbbells back up to the starting position, keeping your elbows slightly bent and your palms facing each other.","Repeat."],"notes":""}'),
('longhaul-fitness', '0c6fa94e-c285-474f-9d27-637568050770', 'cable-one-handed-tricep-pushdown', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"0c6fa94e-c285-474f-9d27-637568050770","name":"One-Handed Tricep Pushdown – Cable","slug":"one-handed-tricep-pushdown-cable","primaryMuscles":["tricep"],"secondaryMuscles":[],"steps":["Stand facing a cable machine with your feet shoulder-width apart.","Grasp the cable attachment with one hand, palm facing down.","Position your elbow at a 90-degree angle and keep it close to your side.","Engage your core and maintain a neutral spine.","Exhale and extend your arm down, fully straightening your elbow.","Pause for a moment, squeezing your tricep muscle.","Inhale and slowly return your arm to the starting position, maintaining control.","Repeat for the desired number of repetitions and then switch arms."],"notes":""}'),
('longhaul-fitness', '0d1eddbd-2ae9-4cfa-b385-5f2d0d44560c', 'band-seated-half-good-morning', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"0d1eddbd-2ae9-4cfa-b385-5f2d0d44560c","name":"Seated Half Good Morning – Band","slug":"seated-half-good-morning-band","primaryMuscles":["glute","lower back"],"secondaryMuscles":["abdominal","hamstring","oblique"],"steps":["Sit on an incline bench set at a 45-degree angle, facing the bench.","Loop a light monster band around both of your feet and run it across your upper back.","Maintain a neutral spine and hinge forward at the hips until your torso touches the pad of the bench.","Hinge backward to return to the neutral position.","Repeat the movement for your desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '0d48ee63-e09c-4bbc-8343-3bc632977a23', 'one-arm-bicep-wall-stretch', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/flexibility.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"0d48ee63-e09c-4bbc-8343-3bc632977a23","name":"One-Arm Bicep Wall Stretch","slug":"one-arm-bicep-wall-stretch","primaryMuscles":["bicep"],"secondaryMuscles":["chest","shoulder - front"],"steps":["Raise one arm to shoulder height next to your body.","Rotate your wrist so your palm faces down.","Place your palm firmly against a doorframe, squat rack, or wall.","Twist your body away from your anchored arm to stretch your biceps.","Hold the stretch for the desired time and switch to the other side."],"notes":""}'),
('longhaul-fitness', '0e16de0b-235a-4f68-8949-9a3fd3f560b1', 'dumbbell-thumbs-up-lateral-raise', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"0e16de0b-235a-4f68-8949-9a3fd3f560b1","name":"Thumbs-Up Lateral Raise – Dumbbell","slug":"thumbs-up-lateral-raise-dumbbell","primaryMuscles":["rotator cuff - back","shoulder - side"],"secondaryMuscles":["trap"],"steps":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with a thumbs up grip (mid pronation).","Position your arms to your side and about 30 degrees in front of your body.","Engage your core and keep your elbows slightly bent. This is your starting position.","Raise the dumbbells to approximately shoulder height, focusing on using your shoulder muscles.","Pause briefly at the top of the movement.","Slowly lower the dumbbells back to the starting position with control.","Repeat the movement for your desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '102850fa-8459-4cd0-81b5-88cc982d5de4', 'dip', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"102850fa-8459-4cd0-81b5-88cc982d5de4","name":"Dip – Bar","slug":"dip-bar","primaryMuscles":["chest","tricep"],"secondaryMuscles":["rotator cuff - front","shoulder - front"],"steps":["Start by approaching a set of parallel bars or dip bars approximately shoulder-width apart. Grab each bar with an overhand grip and hoist yourself up so your arms are fully extended, and your feet are off the ground.","Slightly lean forward and keep your elbows slightly bent to engage your chest, shoulders, and triceps muscles.","Lower your body by bending your elbows and leaning forward while keeping your back straight and your legs behind you. Keep your elbows close to your body throughout the entire exercise.","Continue lowering yourself until your arms are parallel to the ground, or slightly below parallel, while inhaling.","Push back up by straightening your arms while exhaling. Be sure to push with your triceps, chest, and shoulder muscles to return to your starting position.","Repeat."],"notes":"You can also add variations to the dip, such as weighted dips or assisted dips, to increase or decrease the intensity of the exercise."}'),
('longhaul-fitness', '1232d6bd-1b97-4c14-b8e6-de4a40cae8db', 'pull-up-2', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', 100.0, '{"pk":"1232d6bd-1b97-4c14-b8e6-de4a40cae8db","name":"Pull-Up","slug":"pull-up","primaryMuscles":["lat"],"secondaryMuscles":["bicep","forearm - inner","rotator cuff - back","shoulder - back"],"steps":["Begin by finding a sturdy horizontal bar high enough off the ground that you can hang from it with your feet off the floor.","Stand underneath the bar and jump up, grabbing onto the bar with an overhand grip (palms facing away from you) and your hands slightly wider than shoulder-width apart. Your arms should be fully extended.","Engage your core and retract your shoulder blades as you pull your body up towards the bar. Keep your elbows pointed downwards and your head in a neutral position.","Continue pulling your body up until your chin is above the bar. Keep your core tight and your shoulders engaged throughout the movement.","Pause briefly at the top of the movement, then slowly lower yourself back down to the starting position with control. Make sure to maintain a controlled descent and avoid letting your body swing or drop.","Repeat the movement for your desired number of repetitions."],"notes":"Try assisted variations using resistance bands or an assisted pull-up machine until you build the necessary strength."}'),
('longhaul-fitness', '12b39c55-c510-4cd7-b957-e989750bb03a', 'machine-torso-rotation', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"12b39c55-c510-4cd7-b957-e989750bb03a","name":"Torso Rotation Machine","slug":"torso-rotation-machine","primaryMuscles":["oblique"],"secondaryMuscles":[],"steps":["Adjust the seat and chest pad of the machine.","Kneel on the knee pad with your chest against the chest pad.","Grasp the handles with both hands and keep your elbows bent.","Rotate your torso to the left as far as you comfortably can, while keeping your hips and legs stationary.","Pause briefly at the end of the range of motion, then rotate your torso back to the starting position.","Repeat the rotation to the right side, and continue alternating sides for the desired number of repetitions or time."],"notes":""}'),
('longhaul-fitness', '13c792a7-e6b2-4520-a468-34fe741751d3', 'machine-incline-bench-press', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"13c792a7-e6b2-4520-a468-34fe741751d3","name":"Incline Bench Press – Machine","slug":"incline-bench-press-machine","primaryMuscles":["chest","shoulder - front","tricep"],"secondaryMuscles":["rotator cuff - front"],"steps":["Adjust the bench and seat height so that your chest aligns with the incline bench press machine''s handles and your feet are flat on the floor.","Select the appropriate weight on the weight stack.","Sit on the machine with your back flat against the back pad.","Grasp the handles with a firm grip, keeping your wrists straight. This is the starting position.","Press the handles away from your chest, keeping your elbows at about a 45-degree angle from your body, extending your arms fully without locking your elbows.","Pause briefly at the top of the press.","Slowly lower the handles back to the starting position, maintaining control throughout the movement.","Repeat the press for the desired number of repetitions."],"notes":"Ensure your back is flat against the bench, and your feet are firmly planted on the ground.  Keep your core tight. Exhale as you push the bar away from your chest, and inhale as you lower it down."}'),
('longhaul-fitness', '13ce59d9-4fd0-4aea-857a-3afc186c3074', 'sit-up', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"13ce59d9-4fd0-4aea-857a-3afc186c3074","name":"Sit-Up","slug":"sit-up","primaryMuscles":["abdominal"],"secondaryMuscles":["oblique"],"steps":["Start by lying on your back with your legs close together, knees bent, and feet flat on the ground.","Place your hands lightly on the back of your head without interlocking your fingers. Elbows should be out to the sides.","Engage your core muscles, exhale, and lift your upper body off the ground towards your knees. Lift until you''re essentially sitting upright.","Inhale as you reverse the movement and lower back down to the ground.","Repeat."],"notes":"Do not rest at the top or bottom of the movement. Avoid using momentum or pulling on your neck to lift your upper body. This goes for most exercises, but it''s better to do fewer, controlled reps with proper form than to do more reps with poor form."}'),
('longhaul-fitness', '13d9db44-d9e9-4d6e-ac38-f26784fa6f9d', 'hanging-side-to-knee-drive', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"13d9db44-d9e9-4d6e-ac38-f26784fa6f9d","name":"Hanging Side-To-Side Knee Drive","slug":"hanging-side-to-side-knee-drive","primaryMuscles":["abdominal","bicep","lat","oblique"],"secondaryMuscles":["forearm - inner","forearm - outer"],"steps":["Grip the pull-up bar with a supinated grip (palms facing you) and arms fully extended.","Pull yourself up to a halfway pull-up until your upper arms are parallel to the floor. This is the starting position.","Start by cycle your knees towards your chest in a bicycle motion straight in front of you.","Continue the cycling motion as you rotate your hips to the right, then the left, going as far as you can while maintaining the half pull-up. This is one repetition.","Repeat the bicycle and rotating motions for the desired number of repetitions or seconds before lowering yourself to the ground."],"notes":""}'),
('longhaul-fitness', '1425a757-46dd-41a0-8fcc-67bdb24e3ee0', 'neck-twist-lacrosse-ball', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/flexibility.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"1425a757-46dd-41a0-8fcc-67bdb24e3ee0","name":"Neck Twist – Lacrosse Ball","slug":"neck-twist-lacrosse-ball","primaryMuscles":["trap"],"secondaryMuscles":[],"steps":["Place a massage or lacrosse ball against the front and outer side of your neck.","Use your hand to gently compress the ball into the muscles.","Slowly rotate your head to the opposite side to increase the stretch on the neck.","Use small movements to massage the muscle group while maintaining gentle pressure.","Hold the massage and stretch for the desired time and switch to the other side."],"notes":""}'),
('longhaul-fitness', '145092cb-b4a3-4aed-8e94-cd6ff65d9147', 'power-jerk', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"145092cb-b4a3-4aed-8e94-cd6ff65d9147","name":"Power Jerk","slug":"power-jerk","primaryMuscles":["shoulder - front"],"secondaryMuscles":["glute","lower back","quad","shoulder - side","thigh - inner","trap","tricep"],"steps":["Start with the barbell resting on your front shoulders, with your feet shoulder-width apart.","Bend your knees slightly and dip your hips down.","Quickly extend your legs and hips, driving the barbell upwards.","As the barbell reaches its highest point, quickly drop underneath it, in a small squat.","As you catch the barbell overhead, straighten your legs and stand up.","Lower the barbell back down to your front shoulders to complete the rep.","Repeat."],"notes":""}'),
('longhaul-fitness', '14a89726-44da-46b6-8771-c193a1db083b', 'barbell-skull-crusher', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"14a89726-44da-46b6-8771-c193a1db083b","name":"Skull Crusher – Barbell","slug":"skull-crusher-barbell","primaryMuscles":["tricep"],"secondaryMuscles":[],"steps":["Lie down on a flat bench with a barbell in your hands. Your feet should be flat on the floor for stability.","Grip the barbell with an overhand grip (palms facing towards your feet) slightly narrower than shoulder-width apart.","Extend your arms fully so that the barbell is directly above your shoulders. This is your starting position.","Keeping your upper arms stationary, inhale and slowly lower the barbell by bending your elbows until the barbell is just above your forehead.","Pause when the barbell is closest to your forehead, ensuring your elbows are in position and only your forearms are moving.","Exhale and raise the barbell back to the starting position by extending your elbows and contracting the triceps.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '15531742-c61c-4baa-876d-a01acfc6827b', 'trap-bar-deadlift-high-handles', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"15531742-c61c-4baa-876d-a01acfc6827b","name":"Deadlift – Trap Bar High Handles","slug":"deadlift-trap-bar-high-handles","primaryMuscles":["glute","hamstring","lower back"],"secondaryMuscles":["calf","forearm - inner","forearm - outer","trap","quad"],"steps":["Stand in the center of a loaded trap bar with your feet about hip-width apart.","Bend at your hips and knees to lower your body, maintaining a flat back, to grasp the high handles of the trap bar.","Look forward, keeping your chest up, and straighten your back to prepare for the lift.","Drive through your heels to stand up straight, extending your hips and knees simultaneously while keeping the core engaged.","At the top of the movement, stand fully upright with your shoulders back.","Pause briefly at the top of the lift before initiating the return.","Lower the bar by bending at the hips first, then the knees, maintaining a flat back and controlled movement until the weights are back on the ground.","Reset your posture and prepare for the next repetition."],"notes":""}'),
('longhaul-fitness', '15a35cff-bb70-4c80-9f01-280ffd42e9b8', 'trap-bar-deadlift-high-handles', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"15a35cff-bb70-4c80-9f01-280ffd42e9b8","name":"Deadlift – Trap Bar Low Handles","slug":"deadlift-trap-bar-low-handles","primaryMuscles":["glute","hamstring","lower back"],"secondaryMuscles":["calf","forearm - inner","forearm - outer","trap","quad"],"steps":["Stand in the center of a loaded trap bar with your feet about hip-width apart.","Bend at your hips and knees to lower your body, maintaining a flat back, to grasp the low handles of the trap bar.","Look forward, keeping your chest up, and straighten your back to prepare for the lift.","Drive through your heels to stand up straight, extending your hips and knees simultaneously while keeping the core engaged.","At the top of the movement, stand fully upright with your shoulders back and the bar close to your body.","Pause briefly at the top of the lift before initiating the return.","Lower the bar by bending at the hips first, then the knees, maintaining a flat back and controlled movement until the weights are back on the ground.","Reset your posture and prepare for the next repetition."],"notes":""}'),
('longhaul-fitness', '15bf0bb1-406f-49b2-b29a-1d1cd41ffe38', 'band-monster-walk', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"15bf0bb1-406f-49b2-b29a-1d1cd41ffe38","name":"Monster Walk – Band","slug":"monster-walk-band","primaryMuscles":["glute","thigh - outer"],"secondaryMuscles":["quad"],"steps":["Place a band around your ankles.","Stand with your feet shoulder-width apart and your knees slightly bent.","Engage your core and keep your hands at your sides or on your hips. This is your starting position.","Take a diagonal step forward and to the side with one foot, keeping tension in the band and your body low.","Follow with the other foot, stepping diagonally forward to meet the first foot, maintaining the band’s tension.","Continue moving forward by alternating diagonal steps with each foot.","Keep your steps controlled and the band tense, moving steadily forward across the room.","Repeat for the desired number of repetitions."],"notes":"Stay in the semi-squat position throughout the exercise to maintain focus on the hip and thigh muscles."}'),
('longhaul-fitness', '15f7dd4a-04a8-437a-813a-9c8029040edc', 'machine-chest-fly', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"15f7dd4a-04a8-437a-813a-9c8029040edc","name":"Chest Fly – Machine","slug":"chest-fly-machine","primaryMuscles":["chest"],"secondaryMuscles":["bicep","forearm - inner","shoulder - front"],"steps":["Adjust the seat height and position on the machine to ensure proper alignment with the handles.","Extend your arms out to the sides, keeping a slight bend in your elbows. Grasp the handles and sit with your back flat against the pad.","Inhale and slowly bring your arms together in front of your chest, keeping them slightly bent.","Exhale and slowly return your arms to the starting position, maintaining a slight bend in your elbows.","Repeat."],"notes":""}'),
('longhaul-fitness', '175f5483-4d9d-4e2f-8d71-9e669a42348f', 'barbell-pause-deadlift', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"175f5483-4d9d-4e2f-8d71-9e669a42348f","name":"Pause Deadlift – Barbell","slug":"pause-deadlift-barbell","primaryMuscles":["glute","hamstring","lower back"],"secondaryMuscles":["calf","forearm - inner","forearm - outer","trap","quad"],"steps":["Stand with your feet hip-width apart and your toes pointing forward.","Bend at the hips and knees to lower your body down, keeping your back straight and your chest lifted.","Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Engage your core and lift the barbell off the ground, driving through your heels and keeping your back straight.","Almost immediately during your lift, pause for a brief moment when the barbell is in front of your lower shins, maintaining tension in your muscles.","Continue the lift until you''re standing straight.","Lower the barbell back down to the ground, maintaining control and keeping your back straight.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '17d42c9b-b211-4a85-aa9e-8060387c7380', 'dumbbell-shrug', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"17d42c9b-b211-4a85-aa9e-8060387c7380","name":"Shrug – Dumbbell","slug":"shrug-dumbbell","primaryMuscles":["trap"],"secondaryMuscles":["forearm - inner"],"steps":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.","Keep your arms straight and allow the dumbbells to hang at your sides.","Engage your core and lift your shoulders towards your ears, squeezing your shoulder blades together.","Hold the contraction for a second, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '180aa683-0df8-4e12-ae0d-2e247e8c1889', 'foam-roller-one-leg-seated-knee-to-chest', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/flexibility.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"180aa683-0df8-4e12-ae0d-2e247e8c1889","name":"One-Leg Seated Knee-to-Chest – Foam Roller","slug":"one-leg-seated-knee-to-chest-foam-roller","primaryMuscles":["glute","lower back"],"secondaryMuscles":["hamstring","quad"],"steps":["Sit on the floor and place a foam roller behind your lower back.","Lean back slowly onto the foam roller, positioning it under your lumbar spine.","Hug one knee to your chest, keeping the other leg straight on the floor to avoid arching your lower back.","Find a tender spot and hold gentle pressure on it for the desired time. Hold each position instead of rolling.","Switch sides and hold the stretch for the same amount of time on the other leg."],"notes":""}'),
('longhaul-fitness', '1ac7c960-3381-40dc-a146-a1e08e0332c8', 'seated-leg-curl', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"1ac7c960-3381-40dc-a146-a1e08e0332c8","name":"Seated Leg Curl","slug":"seated-leg-curl","primaryMuscles":["hamstring"],"secondaryMuscles":[],"steps":["Adjust the machine to fit your body size and leg length.","Sit on the machine with your back against the backrest and your legs straight out in front of you.","Place your ankles over the padded bar and grasp the handles on the sides of the seat for support.","Bend your knees and curl your legs towards your buttocks, keeping your back straight and your feet flexed.","Pause briefly at the bottom of the movement, then slowly straighten your legs back to the starting position.","Repeat."],"notes":""}'),
('longhaul-fitness', '1b1e585e-53c4-4d4e-8649-b41ef17baf55', 'floor-back-extension', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"1b1e585e-53c4-4d4e-8649-b41ef17baf55","name":"Floor Back Extension","slug":"floor-back-extension","primaryMuscles":["lower back"],"secondaryMuscles":[],"steps":["Lie face down on the floor with your legs extended and your arms by your sides.","Place your hands on the back of your head, or keep them out in a \"cactus pose\".","Engage your core muscles by drawing your navel towards your spine.","Slowly lift your upper body off the floor, using your lower back muscles.","Keep your neck in a neutral position and avoid straining or arching it.","Hold the lifted position long enough to squeeze your lower back muscles.","Lower your upper body back down to the starting position in a controlled manner.","Repeat the exercise for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '1cc7bad9-63fb-4797-8c20-aabcdda115b9', 'underhand-grip-inverted-row', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"1cc7bad9-63fb-4797-8c20-aabcdda115b9","name":"Underhand Grip Inverted Row","slug":"underhand-grip-inverted-row","primaryMuscles":["lat","shoulder - back","trap"],"secondaryMuscles":["bicep","forearm - inner","rotator cuff - back","rotator cuff - front"],"steps":["Set up a barbell or suspension trainer at waist height.","Stand facing the barbell or suspension trainer and grab it with an underhand grip, hands shoulder-width apart.","Walk your feet forward until your body is at a slight angle, with your arms extended and your body in a straight line.","Engage your core and squeeze your shoulder blades together as you pull your chest towards the barbell or suspension trainer.","Pause for a moment at the top of the movement, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '1e5593eb-8b88-46c3-81db-28feffa30f86', 'towel-pull-up', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"1e5593eb-8b88-46c3-81db-28feffa30f86","name":"Towel Pull-Up","slug":"towel-pull-up","primaryMuscles":["forearm - inner","lat"],"secondaryMuscles":["bicep","rotator cuff - back","rotator cuff - front","shoulder - back"],"steps":["Find a sturdy horizontal bar that can support your body weight.","Fold a single large towel or two hand towels in half and drape them over the bar.","Grab the ends of the towel with both hands, palms facing each other.","Hang from the bar with your arms fully extended and your feet off the ground.","Pull yourself up towards the bar by bending your elbows and squeezing your shoulder blades together.","Pause at the top of the movement, with your chin above the bar.","Lower yourself back down to the starting position with control.","Repeat for desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '1f825dcf-0ff2-4b1b-ab9d-f34ebf47f96e', 'barbell-kneeling-cuban-rotation', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"1f825dcf-0ff2-4b1b-ab9d-f34ebf47f96e","name":"Kneeling Cuban Rotation – Barbell","slug":"kneeling-cuban-rotation-barbell","primaryMuscles":["rotator cuff - back","rotator cuff - front"],"secondaryMuscles":["forearm - outer","shoulder - side"],"steps":["Start in a tall kneeling position with your knees hip-width apart and your torso upright.","Hold a barbell with a wide, pronated grip (palms facing forward) in both hands over your head.","Lower the barbell towards your head by bending your elbows until your upper arms are parallel to the ground and your forearms are perpendicular to the ground. This is your starting position.","Slowly lower the barbell by rotating your shoulders forward, keeping your elbows as stationary as possible.","Pause briefly when your forearms have rotated parallel to the ground.","Rotate your shoulders backwards, slowly raising the barbell back to the starting position.","Repeat for the desired number of repetitions."],"notes":"Imagine that your upper arms are resting on a shelf as you perform the movement to focus the effort on your rotator cuffs."}'),
('longhaul-fitness', '1fe97035-c45a-4a2c-9485-92ad42a03105', 'barbell-hack-squat-landmine', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"1fe97035-c45a-4a2c-9485-92ad42a03105","name":"Hack Squat – Landmine","slug":"hack-squat-landmine","primaryMuscles":["glute","quad","thigh - inner"],"secondaryMuscles":[],"steps":["Place the end of a barbell into a landmine attachment or securely anchor it in a corner.","Stand with your feet shoulder-width apart, toes slightly turned out.","Hold the unattached end of the barbell with both hands, palms facing inwards. Lift the end up and over one shoulder while you turn away from the weight. Rest the barbell on your shoulder with the weight at your back.","Keep your core engaged, chest lifted, and back straight.","Lower your body by bending at the knees and hips, as if sitting back into a chair.","Continue lowering until your thighs are parallel to the ground or slightly below.","Push through your heels and extend your knees and hips to return to the starting position.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '20406343-147f-4290-b985-e57fabc11069', 'rope-wave', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"20406343-147f-4290-b985-e57fabc11069","name":"Rope Wave","slug":"rope-wave","primaryMuscles":["bicep","forearm - inner","forearm - outer","shoulder - back","shoulder - front","shoulder - side","trap"],"secondaryMuscles":["abdominal","chest","tricep"],"steps":["Stand with your feet shoulder-width apart, knees slightly bent, in front of a heavy rope.","Grip the ends of the rope with both hands. Your palms should be facing inward.","Tighten your core to stabilize your spine.","Begin to raise and lower both arms rapidly in unison. The motion should create waves in the rope.","Keep the waves going consistently for the desired number of repetitions."],"notes":"Keep your back straight and your head up throughout the exercise."}'),
('longhaul-fitness', '20d6c2a0-6791-4393-aab6-9996d8857854', 'smith-machine-seated-shoulder-press', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"20d6c2a0-6791-4393-aab6-9996d8857854","name":"Seated Shoulder Press – Smith Machine","slug":"seated-shoulder-press-smith-machine","primaryMuscles":["shoulder - front"],"secondaryMuscles":["shoulder - side","tricep"],"steps":["Sit on a back-supporting seat under a Smith Machine with your back straight and feet flat on the floor.","Adjust the height of the barbell on the Smith Machine so that it is at shoulder level.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Engage your core and press the barbell upward until your arms are fully extended, but not locked.","Pause for a moment at the top of the movement, then slowly lower the barbell back down to shoulder level.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '224efa9a-0e81-47e5-af0b-8ba0100f0a8e', 'machine-squat-belt', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', 100.0, '{"pk":"224efa9a-0e81-47e5-af0b-8ba0100f0a8e","name":"Squat – Belt","slug":"squat-belt","primaryMuscles":["glute","quad","thigh - inner"],"secondaryMuscles":["calf"],"steps":["Add your desired weight to the machine.","Attach a belt or harness around your waist.","Attach a cable or chain to the belt or harness.","Stand on a platform or box with feet shoulder-width apart.","Hold onto a stable object for balance.","Squat by bending the knees and hips while keeping the back straight.","Pause at the bottom of the squat and then push up through the legs to return to the starting position.","Repeat."],"notes":""}'),
('longhaul-fitness', '23062382-d9f2-4f38-b999-4085a9dcb302', 'barbell-calf-raise', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"23062382-d9f2-4f38-b999-4085a9dcb302","name":"Calf Raise – Barbell","slug":"calf-raise-barbell","primaryMuscles":["calf"],"secondaryMuscles":[],"steps":["Load a barbell. Also, find a raised platform or step to stand on.","Place yourself with the step in front of you and the barbell behind you. Stand with your feet shoulder-width apart, toes pointing forward.","Perform a Hack Squat to lift and hold the barbell behind your glutes.","Step onto the platform or step with the balls of your feet, leaving your heels hanging off the edge. Your feet should be parallel to each other. This is your starting position.","Slowly rise up on the balls of your feet, lifting your heels off the ground.","Hold the raised position for a moment, feeling the contraction in your calf muscles.","Lower your heels back down to the starting position in a controlled manner.","Repeat the movement for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '23a7be0e-9a15-4c72-a635-697d0bc3d261', 'bodyweight-biceps-curl', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"23a7be0e-9a15-4c72-a635-697d0bc3d261","name":"Curl – Bodyweight","slug":"curl-bodyweight","primaryMuscles":["bicep","lat"],"secondaryMuscles":["forearm - inner"],"steps":["Adjust the height of the rings or TRX to waist height and stand facing them.","Hold the rings or TRX handles with an underhand grip and lean back, extending your arms straight in front of you.","Keep your feet shoulder-width apart and your body in a straight line from head to heels.","Engage your biceps and bend your elbows, pulling your body up towards the rings or TRX handles.","As you pull your body up, keep your elbows close to your body and your wrists straight.","When your hands reach your chest, pause for a moment and then slowly lower your body back down to the starting position.","Repeat the exercise for the desired number of reps."],"notes":""}'),
('longhaul-fitness', '23cf1e36-69e0-424b-8403-fc4e30de15da', 'barbell-bench-press', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"23cf1e36-69e0-424b-8403-fc4e30de15da","name":"Bench Press – Barbell","slug":"bench-press-barbell","primaryMuscles":["chest","shoulder - front"],"secondaryMuscles":["tricep"],"steps":["Lie on a flat bench with your feet firmly planted on the ground.","Grip the barbell with your hands slightly wider than shoulder-width apart, with your palms facing away from your body.","Lift the bar off the rack and hold it directly above your chest with extended arms.","Slowly lower the bar down to your chest, keeping your elbows close to your body.","Pause briefly when the bar touches your chest.","Push the bar back up to the starting position by extending your arms.","Repeat."],"notes":"Ensure your back is flat against the bench, and your feet are firmly planted on the ground.  Keep your core tight, and your elbows close to your body throughout the movement. Exhale as you push the bar away from your chest, and inhale as you lower it down."}'),
('longhaul-fitness', '24523e30-2b0c-435c-91a5-c0f913b18221', 'cable-horizontal-wood-chop', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"24523e30-2b0c-435c-91a5-c0f913b18221","name":"Horizontal Wood Chop – Cable","slug":"horizontal-wood-chop-cable","primaryMuscles":["oblique"],"secondaryMuscles":["abdominal"],"steps":["Set up the cable machine by adjusting the cable to just under chest height and attach a handle.","Stand perpendicular to the cable machine with your feet shoulder-width apart, keeping your toes and head angled away from the machine.","Grip the handle with both hands, extending your arms fully. Begin with your upper body twisted so that your arms and the handle are positioned on the side closest to the machine, while your head and toes continue to face away.","Step away from the machine to create enough tension in the cable, ensuring it is taut before you start the exercise.","Rotate your torso while keeping your arms straight, moving the handle in a horizontal motion across your body until your hands are aligned forward, matching the direction of your toes and head.","Keep your core engaged throughout the movement to maintain stability and prevent any rotation in your hips or bending of the arms.","Complete the twisting motion until your arms are fully extended in front of you, parallel to the direction your toes and head are facing.","Slowly and with control, reverse the motion, returning to the twisted starting position while maintaining the alignment of your head and toes facing forward."],"notes":""}'),
('longhaul-fitness', '24dcec30-58a5-4ebb-8bec-49b39fe9a3ac', 'machine-calf-raise-leg-press', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"24dcec30-58a5-4ebb-8bec-49b39fe9a3ac","name":"Calf Raise – Leg Press Machine","slug":"calf-raise-leg-press-machine","primaryMuscles":["calf"],"secondaryMuscles":[],"steps":["Sit on the leg press machine and position your feet about hip-width apart on the lower part of the platform.","Ensure that only the balls of your feet and your toes are making contact with the platform, with your heels hanging off.","Straighten your legs to release the safety bars of the machine, keeping your knees slightly bent to avoid locking them.","Press through the balls of your feet to push the platform away, raising your heels as high as possible and contracting your calf muscles.","Pause at the top of the movement for a moment to maximize the contraction in the calves.","Slowly lower your heels back below the level of the platform to return to the starting position and stretch your calf muscles.","Repeat for the desired number of reps."],"notes":""}'),
('longhaul-fitness', '26815958-5883-49fd-8445-5522409fc9df', 'one-leg-lying-heel-slide', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"26815958-5883-49fd-8445-5522409fc9df","name":"One-Leg Lying Heel Slide","slug":"one-leg-lying-heel-slide","primaryMuscles":["hamstring"],"secondaryMuscles":["calf","glute","lower back"],"steps":["Lie down on your back on a padded surface with the target leg straight.","Wear a pair of socks or place a slider disc under the heel of the target leg. The goal is to be able to slide your heel on the floor.","Engage your core and keep your non-working leg bent with the foot flat on the floor. This is your starting position.","Slide your heel across the floor towards your buttocks, bending your knee as you go. Focus on contracting your hamstring on the sliding leg.","Slowly slide your heel back down to return to the straight leg position.","Repeat the movement for your desired number of repetitions then switch sides."],"notes":""}'),
('longhaul-fitness', '27b42ba6-addb-4b0b-a9c9-19fe7558ef56', 'bosu-squat', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"27b42ba6-addb-4b0b-a9c9-19fe7558ef56","name":"Squat – BOSU","slug":"squat-bosu","primaryMuscles":["glute","quad"],"secondaryMuscles":["abdominal","calf","hamstring","thigh - inner"],"steps":["Place the BOSU ball on the ground with the flat side down.","Stand on the BOSU ball with your feet shoulder-width apart for stability.","Find your balance and engage your core muscles.","Perform a squat by bending your knees and lowering your hips as if sitting back into a chair, keeping your back straight.","Lower down as far as comfortable. Aim for your thighs to be parallel with the Bosu ball, but you may go lower for increased difficulty.","Press through your heels to lift yourself back up to the starting position.","Repeat the squat for the desired number of repetitions."],"notes":"To increase the difficulty, perform the exercise with the BOSU''s flat side up."}'),
('longhaul-fitness', '284e9630-4315-43b0-bbf3-e2ee25ac9d75', 'cable-crunch', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"284e9630-4315-43b0-bbf3-e2ee25ac9d75","name":"Crunch – Cable","slug":"crunch-cable","primaryMuscles":["abdominal"],"secondaryMuscles":["oblique"],"steps":["Attach a rope handle to a high pulley cable machine.","Adjust the weight to a comfortable level.","Kneel on a mat facing the machine and grab the rope handle with both hands.","Position yourself so that your hands hold the rope by each ear and the cable is behind your neck, above you.","Engage your core and pull the rope towards your knees.","Hold the contraction for a few seconds and slowly release back to the starting position.","Repeat."],"notes":""}'),
('longhaul-fitness', '286bb89e-4b1c-4e9e-ba26-0e6d81baeaed', 'smith-machine-incline-press', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"286bb89e-4b1c-4e9e-ba26-0e6d81baeaed","name":"Incline Bench Press – Smith Machine","slug":"incline-bench-press-smith-machine","primaryMuscles":["chest","shoulder - front"],"secondaryMuscles":["tricep"],"steps":["Adjust the height of the Smith machine bar to a comfortable level for the incline bench press.","Select the desired weight and load it onto the bar.","Lie down on the incline bench and position yourself under the bar.","Grip the bar with a slightly wider than shoulder-width grip and lift it off the rack.","Lower the bar down to your chest while keeping your elbows tucked in.","Push the bar back up to the starting position, keeping your core engaged and your back flat on the bench.","Repeat.","When finished, carefully rack the bar back onto the Smith machine."],"notes":""}'),
('longhaul-fitness', '288eae8d-af58-42db-9f10-16b599e11876', 'barbell-hack-squat', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', 100.0, '{"pk":"288eae8d-af58-42db-9f10-16b599e11876","name":"Hack Squat – Barbell","slug":"hack-squat-barbell","primaryMuscles":["quad"],"secondaryMuscles":["calf","forearm - inner","glute","lower back","thigh - inner","trap"],"steps":["Stand in front of the barbell with your feet shoulder-width apart. The barbell will be by the back of your calves.","Bend down and grip the barbell with an overhand grip, with your palms facing behind you.","Stand up straight, lifting the barbell off the ground and holding it behind your legs.","Keeping your back straight, lower your body by bending your knees and hips, as if you were sitting down on a chair, until your thighs are parallel to the ground.","Push through your heels to stand back up to the starting position.","Repeat."],"notes":""}'),
('longhaul-fitness', '2a4b4f9e-4ed5-4e60-acce-1514d5cc6f43', 'dumbbell-lateral-raise', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"2a4b4f9e-4ed5-4e60-acce-1514d5cc6f43","name":"Lateral Raise – Dumbbell","slug":"lateral-raise-dumbbell","primaryMuscles":["shoulder - side"],"secondaryMuscles":["shoulder - front"],"steps":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand with your palms facing inward.","Keep your arms straight and lift them out to the sides until they are parallel to the floor.","Pause for a moment, then slowly lower the dumbbells back down to your sides.","Repeat."],"notes":""}'),
('longhaul-fitness', '2b395aa2-c563-4001-b639-116928e05231', 'dumbbell-one-leg-front-foot-elevated-split-squat', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"2b395aa2-c563-4001-b639-116928e05231","name":"One-Leg Front Foot Elevated Split Squat – Dumbbell","slug":"one-leg-front-foot-elevated-split-squat-dumbbell","primaryMuscles":["glute","quad"],"secondaryMuscles":["calf","hamstring","lower back"],"steps":["Place a 12-16 inch plyobox in front of you and hold dumbbells of the desired weight.","Step onto the plyobox with your front foot, creating a split stance.","Engage your core and keep your chest lifted.","Lunge forward by bending the front foot''s knee, allowing your back knee to lower towards the ground.","Lean forward slightly to allow your front knee to move past your toes, ensuring full knee flexion.","Push through your front heel to return to the standing position.","Repeat the movement for your desired number of repetitions then switch legs."],"notes":""}'),
('longhaul-fitness', '2b7afcd7-9389-4d87-a634-3383576991e4', 'kettlebell-single-arm-bottoms-up-overhead-press', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"2b7afcd7-9389-4d87-a634-3383576991e4","name":"Single-Arm Bottoms-Up Overhead Press – Kettlebell","slug":"single-arm-bottoms-up-overhead-press-kettlebell","primaryMuscles":["shoulder - front"],"secondaryMuscles":["forearm - inner","forearm - outer","shoulder - side","tricep"],"steps":["Stand with feet shoulder-width apart holding a kettlebell bottoms-up in one hand at shoulder height.","Engage your core and make sure your wrist is straight and aligned directly under the kettlebell.","Press the kettlebell overhead by extending your arm fully while keeping the bottom of the kettlebell facing up.","Maintain a stable and upright position without leaning backward or sideways.","Slowly lower the kettlebell back to shoulder height, keeping control of the movement.","Repeat for desired number of reps, then switch to the other arm."],"notes":""}'),
('longhaul-fitness', '2b7f437c-8b4c-4fa5-9f8e-6307cef2797d', 'plate-one-handed-pinch', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"2b7f437c-8b4c-4fa5-9f8e-6307cef2797d","name":"One-Handed Plate Pinch","slug":"one-handed-plate-pinch","primaryMuscles":["forearm - inner"],"secondaryMuscles":[],"steps":["Choose two weight plates of the same size and weight.","Stand facing the plates and place them on the ground.","Bend down and grip the top of each plate with your fingers and thumbs.","Lift the plates off the ground and hold them beside your body with your arms hanging, elbows straight, but not locked.","Squeeze your fingers and thumbs together to maintain a strong grip on the plates.","Hold the plates for a set amount of time. Consider each second one \"repetition\".","Lower the plates back to the ground and release your grip."],"notes":""}'),
('longhaul-fitness', '2b9085c4-ad46-466b-acc9-f863a93dbaa9', 'one-handed-cross-body-curl', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"2b9085c4-ad46-466b-acc9-f863a93dbaa9","name":"One-Handed Cross-Body Curl","slug":"one-handed-cross-body-curl","primaryMuscles":["bicep"],"secondaryMuscles":["forearm - inner"],"steps":["Stand up, leaning slightly forward from a straight position, feet shoulder-width apart, and your knees slightly bent.","Hold a dumbbell in each hand, with your palms facing your body and arms fully extended at your sides. This is your starting position.","Keeping your elbows close to your body, slowly curl one dumbbell up toward your opposite shoulder, across your body.","Continue curling until the weight comes close to the activating bicep''s shoulder. Squeeze your bicep before slowly lowering the weight to the starting position.","Repeat the curl on the opposite side.","Continue alternating curls on each side for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '2bafa5cc-a98f-4113-8ec7-0adf62d190fd', 'leg-curl-laying', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'fuzzy', 96.3, '{"pk":"2bafa5cc-a98f-4113-8ec7-0adf62d190fd","name":"Lying Leg Curl","slug":"lying-leg-curl","primaryMuscles":["hamstring"],"secondaryMuscles":[],"steps":["Lie face down on a leg curl machine with your legs fully extended and your ankles against the padded lever.","Grasp the handles on the machine for stability.","Engage your core and squeeze your glutes.","Bend your knees to curl the lever towards your glutes, keeping your upper legs stationary.","Pause for a moment at the top of the movement, feeling the contraction in your hamstrings.","Slowly lower the lever back to the starting position, fully extending your legs.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '2cc23389-d818-4527-a180-eb7a8d3db5fd', 'lunge-bodyweight', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"2cc23389-d818-4527-a180-eb7a8d3db5fd","name":"Lunge – Bodyweight","slug":"lunge-bodyweight","primaryMuscles":["glute","quad","thigh - inner"],"secondaryMuscles":[],"steps":["Stand with your feet shoulder-width apart and your hands on your hips.","Step forward with one leg, bending your knee until your thigh is parallel to the ground.","Keep your back straight and your core engaged.","Push through your front heel to return to the starting position.","Repeat with the other leg."],"notes":""}'),
('longhaul-fitness', '2cce67fc-2bb1-4181-97dd-1c9342110801', 'medicine-ball-slam', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"2cce67fc-2bb1-4181-97dd-1c9342110801","name":"Slam – Medicine Ball","slug":"slam-medicine-ball","primaryMuscles":["abdominal","lat","oblique","shoulder - front"],"secondaryMuscles":["calf","chest","forearm - inner","forearm - outer","glute","hamstring","lower back","quad","tricep"],"steps":["Stand with your feet shoulder-width apart, holding a medicine ball in front of you with both hands.","Begin by raising the medicine ball above your head. As you lift the ball, come onto the balls of your feet, elevating your heels to maximize reach.","From this fully extended position, drive your heels down to the ground as you explosively throw the ball onto the ground in front of you with as much force as possible, engaging your abs, shoulders, and arms.","Squat down to pick up the ball after it bounces, keeping your back straight and chest up.","Return to a standing position and lift the ball above your head again, coming onto your toes to prepare for the next slam.","Repeat the sequence for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '2d152c59-7a71-42da-a19d-e573962a6343', 'dumbbell-lateral-lunge', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"2d152c59-7a71-42da-a19d-e573962a6343","name":"Lateral Lunge – Dumbbell","slug":"lateral-lunge-dumbbell","primaryMuscles":["glute","quad","thigh - inner","thigh - outer"],"secondaryMuscles":["calf","hamstring"],"steps":["Stand with your feet hip-width apart, holding a dumbbell in each hand at your sides. This is the starting position.","Take a big step out to the right, ensuring your toes on both feet are pointing forward.","Shift your weight over your right leg, hinging at the hip and pushing your buttocks back while bending the right knee. Keep the left leg straight.","Keep your back straight and chest up as you lunge, lowering until your right thigh is parallel to the floor. The dumbbells will lower with your arms on either side of your right calf.","Push off your right foot to return to the starting position.","Repeat for the desired number of repetitions before switching to the left side."],"notes":""}'),
('longhaul-fitness', '2f8924fe-39e6-4a6c-a14b-e9095acc24b5', 'hang-clean', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"2f8924fe-39e6-4a6c-a14b-e9095acc24b5","name":"Hang Clean","slug":"hang-clean","primaryMuscles":["glute","lower back","quad","thigh - inner"],"secondaryMuscles":["calf","forearm - outer","hamstring","trap"],"steps":["Stand holding a barbell across your pelvis with straight arms and a shoulder-width grip, palms facing you. This is your starting position.","Bend your knees slightly, hinge at the hips to lower the bar to just above knee level.","Tighten your core and keep your back straight.","Explosively extend your hips and knees, simultaneously pulling the barbell up to your shoulders, keeping it close to your body.","Drop into a deep squat, moving your body, arms, and wrists under the weight.","Catch the bar on your front shoulders, driving your elbows forward and up under the bar.","Stand up straight by extending your hips and knees fully to complete the lift.","Lower the bar back to the starting position.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '30960fcd-ff15-4722-b065-31a48f9b6dcf', 'forearm-plank-knee-to-elbow', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"30960fcd-ff15-4722-b065-31a48f9b6dcf","name":"Forearm Plank Knee to Elbow","slug":"forearm-plank-knee-to-elbow","primaryMuscles":["abdominal","oblique"],"secondaryMuscles":["chest","glute","quad","shoulder - front"],"steps":["Begin in a forearm plank position with elbows directly beneath shoulders and body in a straight line from head to heels.","Engage core muscles and maintain a neutral spine position throughout the exercise. This is your starting position.","Lift one foot off the ground and bring the knee towards the same side elbow, maintaining plank position.","Return the foot back to the starting plank position.","Repeat the movement on the opposite side, bringing the other knee towards its respective elbow. This is one repetition.","Continue alternating knees to elbows while maintaining stability in the plank position."],"notes":""}'),
('longhaul-fitness', '310d636b-c865-4d1a-b50d-50a6d9c0855f', 'dumbbell-incline-hex-press', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', 88.9, '{"pk":"310d636b-c865-4d1a-b50d-50a6d9c0855f","name":"Incline Hex Press – Dumbbell","slug":"incline-hex-press-dumbbell","primaryMuscles":["chest","shoulder - front"],"secondaryMuscles":["tricep"],"steps":["Select two dumbbells of suitable weight and an incline bench set to a 30-degree angle.","Sit on the bench with a dumbbell in each hand, resting them on your thighs.","Kick the weights to shoulder height as you lean back, positioning the dumbbells at chest level with your palms facing each other.","Press the dumbbells up over your chest by extending your arms while actively pushing the dumbbells against one another the entire time.","Pause briefly at the top of the movement, squeezing your chest muscles.","Lower the weights slowly back to the starting position, maintaining control and keeping the dumbbells close together."],"notes":"Lower the incline to reduce the load on your shoulders and make the exercise easier."}'),
('longhaul-fitness', '326de9b0-967a-4f87-bce9-49026fdad139', 'dumbbell-sumo-squat', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"326de9b0-967a-4f87-bce9-49026fdad139","name":"Sumo Squat – Dumbbell","slug":"sumo-squat-dumbbell","primaryMuscles":["glute","hamstring","quad","thigh - inner"],"secondaryMuscles":["calf","lower back"],"steps":["Hold a dumbbell in front of your chest with both hands.","Stand with your feet wider than shoulder-width apart and toes pointed out at about a 45-degree angle.","Keep your chest up, back straight, and weight primarily on your heels. This is your starting position.","Bend your knees, keeping them in line with your toes, while lowerering your hips down until your thighs are at least parallel to the floor.","Push through your heels to extend your legs and return to the starting position."],"notes":""}'),
('longhaul-fitness', '328b8330-4a04-4f43-a255-f17cba659635', 'hyperextensions', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"328b8330-4a04-4f43-a255-f17cba659635","name":"Back Extension","slug":"back-extension","primaryMuscles":["glute","hamstring","lower back"],"secondaryMuscles":["abdominal"],"steps":["Adjust the back extension bench so that the pads at the thigh are snug against your thighs and your feet are securely held in place by the footpads.","Cross your arms over your chest or hold them behind your head.","Keep your back straight and your neck in a neutral position. Hang your body forward over the thigh pads. This is the starting position.","Engage your lower back muscles and slowly lift your upper body off the bench until it aligns with your legs.","Hold this position for up to a few seconds, squeezing your glutes and lower back muscles at the top of the movement.","Slowly lower your upper body back down to the starting position.","Repeat."],"notes":"Hold weights such as plates to your chest to increase the exercise difficulty."}'),
('longhaul-fitness', '32df2e84-04fd-4338-8c6d-86b54f0fef36', 'cable-rear-delt-row', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"32df2e84-04fd-4338-8c6d-86b54f0fef36","name":"Rear Delt Row – Cable","slug":"rear-delt-row-cable","primaryMuscles":["shoulder - back","trap"],"secondaryMuscles":["forearm - inner","rotator cuff - back","shoulder - side","lat"],"steps":["Attach a straight bar to a cable machine, preferably with a bench and foot rests.","Sit facing the cable machine with your feet shoulder-width apart and your knees slightly bent.","Grasp the bar with an overhand grip, with your hands slightly more than shoulder-width apart.","Lean forward slightly, keeping your back straight and your core engaged.","Pull the bar towards your upper chest, keeping your elbows wide and out to the sides.","Squeeze your shoulder blades together at the top of the movement.","Slowly release the bar back to the starting position.","Repeat."],"notes":""}'),
('longhaul-fitness', '335f9629-c7c2-4cc2-a7e2-d3e2866790f0', 'barbell-romanian-deadlift', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"335f9629-c7c2-4cc2-a7e2-d3e2866790f0","name":"Romanian Deadlift – Barbell","slug":"romanian-deadlift-barbell","primaryMuscles":["glute","hamstring","lower back"],"secondaryMuscles":["calf","trap","quad"],"steps":["Preferably, start with a loaded barbell at hip height on a squat rack. Alternatively, you can lift the barbell from the floor to the starting position.","Stand with your feet hip-width apart, and grip the barbell with hands just outside your thighs using an overhand grip.","Begin the movement with a slight bend in your knees, and keep your back straight and chest up throughout the exercise.","Push your hips back, hinging at the hips to lower the barbell, while keeping it close to your body as the bar descends.","Lower the weight to just below your knees or to mid-shin level — the exact point depends on your hamstring flexibility, without rounding your back.","Pause briefly at the bottom of the movement, maintaining a braced core and tension in your hamstrings and glutes.","Reverse the motion by driving your hips forward to return to a fully upright position, squeezing your glutes at the top of the movement.","Repeat for the desired number of repetitions, ensuring that the tension is maintained in the target muscles without resting the bar on the floor between reps."],"notes":"Differences between a RDL and a standard deadlift:<ul><li>Keep your legs relatively straight with only a slight bend in your knees.</li><li>Focus on the eccentric phase while hinging at the hips and lowering the weight.</li><li>Lower the bar just below the knees or to mid-shin level without touching the ground to maintain tension on the hamstrings and glutes throughout the exercise.</li></ul>"}'),
('longhaul-fitness', '336eaa90-b12b-47a1-9dbf-8f4011093d99', 'dumbbell-alternating-arnold-press', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"336eaa90-b12b-47a1-9dbf-8f4011093d99","name":"Alternating Arnold Press – Dumbbell","slug":"alternating-arnold-press-dumbbell","primaryMuscles":["shoulder - front","shoulder - side"],"secondaryMuscles":["bicep","rotator cuff - front","tricep"],"steps":["Begin standing with your feet shoulder-width apart, holding a dumbbell in each hand in front of each shoulder, palms facing your body. This is your starting position.","Rotate your wrists as you press one dumbbell overhead, turning the palm away from your body during the movement.","Simultaneously maintain the starting position with the other arm, keeping the dumbbell at shoulder height and palm facing your body.","Fully extend the pressing arm until it is straight overhead.","Lower the dumbbell back to the starting position, rotating the wrist back to the starting position.","Immediately rotate the alternate hand’s wrist, pressing the other dumbbell overhead with the same motion.","Continue alternating the press between each arm for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '3386d943-19a7-4d80-b10d-402e4aababe1', 'dip-bench', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"3386d943-19a7-4d80-b10d-402e4aababe1","name":"Dip – Bench","slug":"dip-bench","primaryMuscles":["tricep"],"secondaryMuscles":["chest","rotator cuff - front","shoulder - front"],"steps":["Find a stable bench or chair and sit on the edge with your hands next to your hips, fingers pointing forward.","Slide your feet forward and lower your hips off the bench. Straighten or bend your knees to make the exercise more or less difficult.","Lower your body by bending your elbows until your upper arms are parallel to the ground.","Push yourself back up to the starting position by straightening your arms.","Repeat."],"notes":""}'),
('longhaul-fitness', '33b7c338-9835-40ac-b795-96c630563884', 'cable-low-chest-fly', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"33b7c338-9835-40ac-b795-96c630563884","name":"Low Chest Fly – Cable","slug":"low-chest-fly-cable","primaryMuscles":["chest"],"secondaryMuscles":["rotator cuff - front","shoulder - front"],"steps":["Attach single handle grips to the low pulleys on both sides of a cable machine.","Set the weight on the stack to an appropriate level.","Grab the handles with your palms facing forwards, and slightly bend your elbows.","Stand in the middle of the cable machine and take one step forward so you''re in a staggered stance.","Lean slightly forward at your hips, keeping your back straight and core engaged.","Start with your arms down towards the ground as low as the gripped cables allow. This is the starting position.","Pull the handles together in a wide, upward arc until your hands meet in front of your chest.","Squeeze your chest muscles and hold the contraction briefly.","Slowly return your arms back to the starting position maintaining the slight bend in the elbows.","Repeat the exercise for the desired number of repetitions."],"notes":"Focus on moving the cables with your chest muscles. Avoid creating momentum with other parts of your body."}'),
('longhaul-fitness', '33ce3ab8-7ae9-4e34-9d0f-8c45168f25cc', 'barbell-deadlift-fat-bar', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"33ce3ab8-7ae9-4e34-9d0f-8c45168f25cc","name":"Deadlift – Fat Bar","slug":"deadlift-fat-bar","primaryMuscles":["forearm - inner","forearm - outer","glute","hamstring","lower back"],"secondaryMuscles":["calf","trap","quad"],"steps":["Stand with your feet shoulder-width apart, holding a loaded fat bar in front of your quads.","Bend your knees, hinge and lean forward at the hips, keeping your back straight and your chest up.","Lower the fat bar towards the ground, keeping it close to your legs.","Pause when the fat bar is just below your knees.","Push through your heels and stand up, keeping your back straight and your chest up.","Repeat."],"notes":""}'),
('longhaul-fitness', '33dc0a63-c6cc-4488-97af-0172483630a4', 'dumbbell-close-grip-incline-bench-press', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"33dc0a63-c6cc-4488-97af-0172483630a4","name":"Close-Grip Incline Bench Press – Dumbbell","slug":"close-grip-incline-bench-press-dumbbell","primaryMuscles":["chest","tricep"],"secondaryMuscles":["shoulder - front"],"steps":["Set the incline bench to a 30-45 degree angle.","Grab a pair of dumbbells with a neutral grip and sit on the bench.","Lie back on the bench, positioning the dumbbells at shoulder width with palms facing each other.","Engage your core and firmly plant your feet on the ground.","Press the dumbbells above your chest until your arms are fully extended, making sure they are close to each other without touching.","Slowly lower the dumbbells back to the starting position just above your chest.","Repeat for the desired number of repetitions."],"notes":"Lower the incline to reduce the load on your shoulders and move it to your chest."}'),
('longhaul-fitness', '343dc5c0-3ad2-49cd-a576-1a9ad8866caa', 'isometric-pull-up-hold', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', 100.0, '{"pk":"343dc5c0-3ad2-49cd-a576-1a9ad8866caa","name":"Isometric Pull-Up Hold","slug":"isometric-pull-up-hold","primaryMuscles":["forearm - inner","forearm - outer","lat","shoulder - back","trap"],"secondaryMuscles":["abdominal","bicep","lower back","oblique"],"steps":["Grasp the pull-up bar with an overhand grip slightly wider than shoulder-width apart.","Jump up or use a step to get into the top position of a pull-up with your chin above the bar.","Hold your body up with your chin above the bar, ensuring your core is tight and legs straight.","Keep your elbows bent and close to your body to engage the back muscles effectively.","Maintain the position as long as possible while breathing steadily."],"notes":""}'),
('longhaul-fitness', '345ec620-4a66-429b-9804-354b4bbbc37c', 'close-grip-push-up', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', 100.0, '{"pk":"345ec620-4a66-429b-9804-354b4bbbc37c","name":"Close-Grip Push-Up","slug":"close-grip-push-up","primaryMuscles":["chest","shoulder - front","tricep"],"secondaryMuscles":["abdominal"],"steps":["Start in a plank position with your hands under your shoulders, or just slightly narrower, and your fingers pointing forward.","Lower your body towards the ground, keeping your elbows close to your sides.","Push back up to the starting position, keeping your core engaged and your body in a straight line.","Repeat."],"notes":""}'),
('longhaul-fitness', '34ce41d3-2e8e-4b9f-82eb-9461b32e95b1', 'cable-biceps-curl', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"34ce41d3-2e8e-4b9f-82eb-9461b32e95b1","name":"Cable Curl – Bar","slug":"cable-curl-bar","primaryMuscles":["bicep"],"secondaryMuscles":["forearm - inner"],"steps":["Stand facing a cable machine with your feet shoulder-width apart.","Attach a straight bar to the low pulley of the cable machine.","Grasp the bar with an underhand grip, hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Exhale and curl the bar up towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the bar back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '3547bc2f-898c-4f53-9dbe-2459c477ede2', 'barbell-seated-shoulder-press', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"3547bc2f-898c-4f53-9dbe-2459c477ede2","name":"Seated Shoulder Press – Barbell","slug":"seated-overhead-press-barbell","primaryMuscles":["shoulder - front"],"secondaryMuscles":["shoulder - side","tricep"],"steps":["Start by sitting on a back-supporting bench with your feet firmly planted on the ground.","Hold the barbell with an overhand grip, slightly wider than shoulder-width apart.","Bring the barbell to shoulder level, resting it on your upper chest and front shoulders.","Engage your core and keep your back straight throughout the exercise.","Press the barbell overhead by extending your arms fully, but without locking your elbows.","Pause briefly at the top of the movement, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '37115036-6477-4046-96dc-5c48d077a201', 'lying-windshield-wiper', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"37115036-6477-4046-96dc-5c48d077a201","name":"Lying Windshield Wiper","slug":"lying-windshield-wiper","primaryMuscles":["oblique"],"secondaryMuscles":["abdominal"],"steps":["Lie flat on your back with your arms extended out to the sides, palms down, and your legs extended straight up towards the ceiling.","Keep your feet together and engage your core muscles by drawing your navel towards your spine.","Lower your legs to one side, keeping them straight and close to the floor without touching it.","Pause briefly and then lift your legs back up to the starting position.","Repeat the movement, this time lowering your legs to the opposite side.","Continue alternating sides for the desired number of reps or time."],"notes":"Avoid swinging or using momentum to perform the movement; instead, control the action with your core muscles."}'),
('longhaul-fitness', '372c2021-cdab-467e-a65d-be2c0ab2fe5b', 'snatch-grip-deadlift', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"372c2021-cdab-467e-a65d-be2c0ab2fe5b","name":"Snatch Grip Deadlift","slug":"snatch-grip-deadlift","primaryMuscles":["glute","hamstring","lower back"],"secondaryMuscles":["calf","forearm - inner","forearm - outer","trap","quad"],"steps":["Begin by standing with your feet shoulder-width apart and the barbell on the ground in front of you.","Take a wide grip on the barbell, with your hands outside of your shoulders.","Lower your hips and bend your knees, keeping your back straight and your chest up.","Engage your core and lift the barbell off the ground, keeping it close to your body.","As you lift the barbell, extend your hips and knees to stand up straight.","Once you are standing, pause briefly and then lower the barbell back down to the ground, keeping it close to your body.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '3785eb2c-64cc-41ff-8ce5-cd95d72f4a31', 'alternating-lying-chin-tuck-neck-twist', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/flexibility.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"3785eb2c-64cc-41ff-8ce5-cd95d72f4a31","name":"Alternating Lying Chin Tuck Neck Twist","slug":"alternating-lying-chin-tuck-neck-twist","primaryMuscles":["trap"],"secondaryMuscles":[],"steps":["Lie on your back with your forehead and chin parallel to the floor.","Tuck your chin in gently without lifting your head.","Rotate your neck slowly all the way to one side.","Return your head to center and rest briefly.","Rotate your neck all the way to the opposite side.","Return your head to center to complete one repetition.","Alternate the starting side with each new set.","Repeat the exercise for the desired amount of time or repetitions."],"notes":""}'),
('longhaul-fitness', '37b095b9-8e2e-4210-acb8-8c77415ab94d', 'one-leg-lying-outer-thigh-hip-twist', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/flexibility.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"37b095b9-8e2e-4210-acb8-8c77415ab94d","name":"One-Leg Lying Outer Thigh Hip Twist","slug":"one-leg-lying-outer-thigh-hip-twist","primaryMuscles":["thigh - outer"],"secondaryMuscles":[],"steps":["Lie on your back with knees bent and feet flat on the floor.","Cross one ankle over the opposite thigh just above the knee.","Keep your upper back and shoulders pressed into the floor.","Slowly rotate your hips away from the crossed leg, letting the bottom thigh fall toward the floor.","Use the weight of the crossed leg to deepen the stretch in your outer hip.","Hold the stretch for the desired time and switch to the other side."],"notes":""}'),
('longhaul-fitness', '38484d69-3853-4a57-9220-430b0e228e42', 'one-leg-seated-rock-paper-scissor-toes', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/flexibility.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"38484d69-3853-4a57-9220-430b0e228e42","name":"One-Leg Seated Rock-Paper-Scissor Toes","slug":"one-leg-seated-rock-paper-scissor-toes","primaryMuscles":["calf"],"secondaryMuscles":[],"steps":["Sit on a chair or on the floor. Raise one foot off the floor, holding the leg up by the raised knee.","Curl all toes to create the ''rock'' position.","Return to neutral with toes relaxed.","Spread all toes apart into the ''paper'' position.","Extend the big toe while keeping other toes curled for the ''scissors'' position part one.","Curl the big toe and extend the other four toes for the ''scissors'' position part two.","Continue alternating between the ''rock'', ''paper'', and both ''scissors'' positions for the desired number of repetitions before switching to the other side."],"notes":""}'),
('longhaul-fitness', '3bc232a6-36f1-4322-948c-61c0df58cb15', 'arnold-press', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"3bc232a6-36f1-4322-948c-61c0df58cb15","name":"Arnold Press","slug":"arnold-press","primaryMuscles":["shoulder - back","shoulder - side"],"secondaryMuscles":[],"steps":["Hold a dumbbell in each hand and sit or stand with your feet shoulder-width apart.","Start with your arms bent so that your palms face your body and the dumbbells are at shoulder height.","As you press the dumbbells overhead, rotate your palms to face forward.","Continue to press the dumbbells overhead until your arms are fully extended.","Lower the dumbbells back down to the starting position, rotating your palms back to face your body as you do so.","Repeat."],"notes":""}'),
('longhaul-fitness', '3cf8f2e0-5170-49e9-ae19-b22d14738473', 'kettlebell-kickstand-squat', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"3cf8f2e0-5170-49e9-ae19-b22d14738473","name":"Kickstand Squat – Kettlebell","slug":"kickstand-squat-kettlebell","primaryMuscles":["glute","hamstring","lower back","quad"],"secondaryMuscles":["abdominal","calf","oblique"],"steps":["Stand with your feet hip-width apart, holding a kettlebell with both hands in front of your chest.","Shift your weight onto your left foot and place your right foot behind you, resting on the ball of your foot – this is your kickstand position.","Hinge your hips back slightly, ensuring a straight back and engaged core.","Bend at your left knee to lower down into a squat, keeping the weight in your left heel and the kettlebell steady in front of your chest.","Lower down until your left thigh is nearly parallel to the ground, or as low as you can go comfortably.","Drive through your left heel to stand back up to the starting position.","Complete the desired number of repetitions on the left side before switching sides and repeating."],"notes":""}'),
('longhaul-fitness', '3edd4f6d-8f3b-43be-bec6-155baaee1382', 'dumbbell-one-handed-leaning-lateral-raise', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"3edd4f6d-8f3b-43be-bec6-155baaee1382","name":"One-Handed Leaning Lateral Raise – Dumbbell","slug":"one-handed-leaning-lateral-raise-dumbbell","primaryMuscles":["shoulder - side"],"secondaryMuscles":["shoulder - front","oblique"],"steps":["Stand with your feet shoulder-width apart and a dumbbell in your left hand.","Slightly lean your right shoulder against a wall or stable structure. Aim for a 60-degree angle between you and the ground.","Keep your back straight and core engaged. This is your starting position.","Slowly lift the dumbbell to the side, keeping your arm slightly bent. Raise it until your left arm is perpendicular with your body.","Pause at the top of the movement, then slowly lower the dumbbell back to the starting position.","Repeat the desired number of repetitions before switching to the other side."],"notes":"Ensure not to bend your elbow excessively. Also, avoid leaning with your feet too far from the wall, as this can shift the emphasis from your shoulders to your core muscles, altering the primary focus of the exercise."}'),
('longhaul-fitness', '3f982fe0-0602-470f-9ecf-7d5e1616e5a2', 'lying-leg-raise', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', 100.0, '{"pk":"3f982fe0-0602-470f-9ecf-7d5e1616e5a2","name":"Lying Leg Raise","slug":"lying-leg-raise","primaryMuscles":["abdominal"],"secondaryMuscles":["oblique"],"steps":["Lie flat on your back on a mat or bench.","Place your hands by your sides or under your glutes for support.","Keep your legs straight and together, with your toes pointed towards the ceiling.","Engage your core muscles by drawing your belly button towards your spine.","Slowly lift your legs off the ground, keeping them straight, until they are perpendicular to the floor.","Pause for a moment at the top, squeezing your lower abs.","Lower your legs back down to the starting position in a controlled manner.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '41ebcee3-f853-4078-a1c2-39e16937d713', 'dumbbell-reverse-fly', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"41ebcee3-f853-4078-a1c2-39e16937d713","name":"Reverse Fly – Dumbbell","slug":"reverse-fly-dumbbell","primaryMuscles":["rotator cuff - back","shoulder - back"],"secondaryMuscles":["trap"],"steps":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand with your palms facing each other.","Bend forward at your hips, keeping your back straight and your core engaged.","Extend your arms straight down towards the floor, with your elbows slightly bent.","Keeping your arms straight, lift the dumbbells out to the sides until they reach shoulder height.","Pause for a moment, then slowly lower the dumbbells back down to the starting position.","Repeat."],"notes":""}'),
('longhaul-fitness', '430ec1c7-0abe-41e6-b5e8-c127aeb0b43a', 'goblet-squat', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', 100.0, '{"pk":"430ec1c7-0abe-41e6-b5e8-c127aeb0b43a","name":"Goblet Squat","slug":"goblet-squat","primaryMuscles":["glute","quad","thigh - inner"],"secondaryMuscles":["calf","lower back"],"steps":["Stand with your feet shoulder-width apart and hold a dumbbell or kettlebell vertically against your chest with both hands, elbows pointing down.","Brace your core and lower your body as far as you can by pushing your hips back and bending your knees.","Pause, then push yourself back up to the starting position.","Repeat."],"notes":""}'),
('longhaul-fitness', '43311985-7fa7-4e1a-89ee-b8dc0cf5e73f', 'roll-up', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"43311985-7fa7-4e1a-89ee-b8dc0cf5e73f","name":"Roll-Up","slug":"roll-up","primaryMuscles":["abdominal"],"secondaryMuscles":[],"steps":["Lie on your back with your arms extended overhead and your legs straight.","Engage your core and slowly lift your head, neck, and shoulders off the ground.","Continue to roll up, reaching your arms towards your toes and keeping your legs straight.","Pause at the top of the movement, then slowly roll back down to the starting position.","Repeat."],"notes":""}'),
('longhaul-fitness', '456cefbe-0d73-4b6e-a8e3-b4530ca8df37', 'push-up-feet-in-rings', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"456cefbe-0d73-4b6e-a8e3-b4530ca8df37","name":"Push-Up – Feet in Rings","slug":"push-up-feet-in-rings","primaryMuscles":["chest","shoulder - front","tricep"],"secondaryMuscles":["abdominal"],"steps":["Start in a plank position with your feet in the rings and your hands shoulder-width apart on the ground.","Lower your body towards the ground by bending your elbows and keeping your body straight.","Push yourself back up to the starting position by straightening your arms.","Repeat."],"notes":""}'),
('longhaul-fitness', '464283e2-2725-40c6-9b28-d7b57d54863e', 'sled-pull', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"464283e2-2725-40c6-9b28-d7b57d54863e","name":"Sled Pull","slug":"sled-pull","primaryMuscles":["calf","glute","hamstring","quad"],"secondaryMuscles":["abdominal","lower back"],"steps":["Adjust the weight on the sled according to your fitness level and training goals.","If using a pulling harness, strap it on securely, making sure it''s comfortably snug. If using straps with handles, grip the handles firmly with both hands.","Stand facing the sled with your feet hip-width apart. Make sure you have a smooth, level, unobstructed path behind you.","Lower into a quarter-squat position, keeping your back straight, and brace your core.","Begin walking backwards slowly, taking small steps while keeping the tension on the harness or handles.","Push through the balls of your feet with each step, focusing on engaging your quadriceps, calves, and glutes.","Keep your chest up and shoulders back throughout the movement to maintain proper posture.","Continue pulling the sled for a number of steps or seconds.","Carefully disengage from the harness or place down the handles."],"notes":"Leaning back slightly allows your weight to help move the sled. Avoid leaning too far back, as you can injure yourself or lose benefits of the exercise."}'),
('longhaul-fitness', '4670f1ec-73f7-4f18-bcb5-d68b3e2fa6d7', 'one-arm-seated-lower-back-rotation-stretch', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/flexibility.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"4670f1ec-73f7-4f18-bcb5-d68b3e2fa6d7","name":"One-Arm Seated Lower Back Rotation Stretch","slug":"one-arm-seated-lower-back-rotation-stretch","primaryMuscles":["lower back","oblique"],"secondaryMuscles":["hamstring","shoulder - back"],"steps":["Sit on a stable surface with your legs extended in front of you.","Place your opposite forearm between both thighs.","Lean forward slightly and rotate your torso away from the side you want to stretch.","Reach your back arm towards the ceiling.","Use the arm between your thighs to provide additional leverage to assist in your rotation.","Hold the stretch for the desired time and switch to the other side."],"notes":""}'),
('longhaul-fitness', '46dea0e2-e740-4901-9f5b-c7370d5e0da1', 'overhead-tricep-extension-bodyweight', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"46dea0e2-e740-4901-9f5b-c7370d5e0da1","name":"Overhead Tricep Extension – Bodyweight","slug":"overhead-tricep-extension-bodyweight","primaryMuscles":["tricep"],"secondaryMuscles":[],"steps":["Set a stationary bar (ex. Smith Machine) at hip height","Stand with your feet shoulder-width, lean forward, and grab the bar with your arms in front of you.","Bend your elbows and lower your head forward and below the bar. Keep your elbows close to your ears.","Squeeze your triceps to extend your arms to the starting position.","Repeat."],"notes":""}'),
('longhaul-fitness', '47d61f40-0743-47af-95a5-545a6a9a4824', 'leg-extension', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'exact', 100.0, '{"pk":"47d61f40-0743-47af-95a5-545a6a9a4824","name":"Leg Extension","slug":"leg-extension","primaryMuscles":["quad"],"secondaryMuscles":[],"steps":["Adjust the machine to fit your body and select the appropriate weight.","Sit on the machine with your back against the backrest and your feet or ankle flat against the supporting pad.","Grasp the handles on the side of the machine for stability.","Extend your legs out in front of you until they are parallel to the floor, keeping your feet flexed and your knees slightly bent.","Hold for a moment, then slowly lower the weight back down to the starting position.","Repeat."],"notes":""}'),
('longhaul-fitness', '48adc847-d455-4a36-b9c2-43a91196a194', 'hamstring-floor-sweep', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/flexibility.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"48adc847-d455-4a36-b9c2-43a91196a194","name":"Hamstring Floor Sweep","slug":"hamstring-floor-sweep","primaryMuscles":["glute","hamstring","lower back"],"secondaryMuscles":["shoulder - back"],"steps":["Stand with one leg straight and extended in front of you, bending the other knee.","Hinge at the hips, keeping your back straight, and sweep the floor with your arms. Your arms should go in a sweeping motion from behind your back leg to the front of your straight, extended leg.","Step the front leg back, both feet side-by-side, and alternate sides by stepping forward with the opposite leg and bending the other knee.","Continue alternating sides and repeating the movement for the desired amount of time."],"notes":""}'),
('longhaul-fitness', '497e1bbc-3010-4738-88b6-8eef91520ee9', 'barbell-incline-bench-press', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"497e1bbc-3010-4738-88b6-8eef91520ee9","name":"Incline Bench Press – Barbell","slug":"incline-bench-press-barbell","primaryMuscles":["chest","shoulder - front"],"secondaryMuscles":["tricep"],"steps":["Set up the incline bench at a 45-degree angle.","Lie down on the bench with your feet flat on the ground.","Grip the barbell with your hands slightly wider than shoulder-width apart.","Unrack the barbell and lower it towards your chest, keeping your elbows tucked in.","Pause briefly at the bottom of the movement, then press the barbell back up to the starting position.","Repeat for desired number of reps.","Rack the barbell once you have completed your set."],"notes":""}'),
('longhaul-fitness', '49f9a136-368c-4b5d-9038-1811a479b1c3', 'hand-release-push-up', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"49f9a136-368c-4b5d-9038-1811a479b1c3","name":"Hand-Release Push-Up","slug":"hand-release-push-up","primaryMuscles":["chest","tricep"],"secondaryMuscles":["abdominal","shoulder - front"],"steps":["Assume the prone position with your body lying face-down on the ground. Place your hands flat on the ground, pointer fingers inside the outer edges of the shoulders. This is your starting position.","Push your whole body up from the ground as a single unit to the up position by fully extending the elbows.","Maintain a straight body alignment from the top of the head to the ankles throughout the movement.","Bend your elbows to lower your body all the way to the ground, ensuring chest, hips, and thighs touch down at the same time.","Lift your hands off the ground. Without moving the head, body, or legs, fully extend both arms into the T position until the arms are straight out to the side.","Immediately move your hands back on the ground to return to the starting position.","Repeat the movement for your desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '4a9f61c9-eab8-4321-80d0-369abf0ca206', 'front-line-opener', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/flexibility.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"4a9f61c9-eab8-4321-80d0-369abf0ca206","name":"Front Line Opener","slug":"front-line-opener","primaryMuscles":["chest","lower back"],"secondaryMuscles":["abdominal","shoulder - front"],"steps":["Stand with your feet hip-width apart.","Bend forward, rounding your back and neck, tucking your chin. Tuck your chin and round your back far enough so that the crown of your head points directly in front of you.","Reach towards the floor with your arms internally rotated, touching the back of your wrists to each other in front of you.","Once you''ve reached your end range, extend your spine to straighten it and lift your chin to look directly in front.","As you''re extending your spine, rotate your arms out and to your sides, palm facing forward, to open your chest muscles.","Continue repetitions for the desired amount of time."],"notes":""}'),
('longhaul-fitness', '4af58df1-7f89-490d-85c8-2f92146f7bed', 'dumbbell-preacher-curl', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"4af58df1-7f89-490d-85c8-2f92146f7bed","name":"Preacher Curl – Dumbbell","slug":"preacher-curl-dumbbell","primaryMuscles":["bicep"],"secondaryMuscles":["forearm - inner"],"steps":["Sit on a preacher bench, placing your upper arms on the padding, holding a dumbbell in each hand with an underhand grip.","Adjust the seat height so your armpits touch the top of the padding and your arm fully extends. This is your starting position.","Curl the dumbbells upwards towards your shoulders, contracting your biceps while keeping your upper arms stationary.","Pause briefly at the top of the movement, squeezing your biceps.","Lower the dumbbells slowly back to the starting position in a controlled manner, fully extending your arms.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '4afe32fd-8821-45bf-82a6-4b23acf3885f', 'machine-crunch', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"4afe32fd-8821-45bf-82a6-4b23acf3885f","name":"Crunch – Machine","slug":"crunch-machine","primaryMuscles":["abdominal"],"secondaryMuscles":["oblique"],"steps":["Adjust the seat height and foot pad position on the crunch machine to ensure proper alignment.","Sit on the machine with your back against the backrest and your feet secured under the foot pads.","Place your hands lightly on the sides of your head, avoiding pulling on your neck.","Engage your core muscles by drawing your belly button in towards your spine.","Exhale and slowly curl your upper body forward, contracting your abdominal muscles.","Pause for a moment at the top of the movement, feeling the contraction in your abs.","Inhale and slowly lower your upper body back to the starting position, maintaining control throughout the movement.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '4bd3658e-1c1b-4c19-92e1-4097c206203f', 'dumbbell-incline-bench-press', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"4bd3658e-1c1b-4c19-92e1-4097c206203f","name":"Incline Bench Press – Dumbbell","slug":"incline-bench-press-dumbbell","primaryMuscles":["chest","shoulder - front"],"secondaryMuscles":["tricep"],"steps":["Set up an incline bench at a 45-degree angle.","Choose two dumbbells of equal weight and sit on the bench with them resting on your thighs.","Lie back on the bench and bring the dumbbells up to your chest, palms facing forward.","Push the dumbbells up and away from your chest, extending your arms fully but not locking your elbows.","Slowly lower the dumbbells back down to your chest, keeping your elbows at a 45-degree angle to your body.","Repeat."],"notes":""}'),
('longhaul-fitness', '4c9aaf26-6f09-4cc6-9203-176db1271621', 'band-internal-shoulder-rotation', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"4c9aaf26-6f09-4cc6-9203-176db1271621","name":"Internal Shoulder Rotation – Band","slug":"internal-shoulder-rotation-band","primaryMuscles":["rotator cuff - front"],"secondaryMuscles":[],"steps":["Attach a resistance band to a stable object at waist height.","Stand perpendicular to the anchor point with your right arm closest to it, and your feet shoulder-width apart.","Reach your right hand and grab the band.","Create resistance in the band by side-stepping away from the anchor point.","This starting position has your right forearm at a 90-degree angle to your right upper-arm. Your right forearm points to your right.","Keep your core engaged and your shoulders relaxed.","Slowly rotate your arms inward, toward your body, until your right hand is in line with your right shoulder.","Pause for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions and then switch sides."],"notes":""}'),
('longhaul-fitness', '4d646f27-a246-4b40-955e-5851ccba177e', 'oblique-sit-up', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"4d646f27-a246-4b40-955e-5851ccba177e","name":"Oblique Sit-Up","slug":"oblique-sit-up","primaryMuscles":["oblique"],"secondaryMuscles":["abdominal"],"steps":["Lie on your back with your knees bent and feet flat on the ground.","Place your hands behind your head, with your elbows pointing out to the sides.","Engage your core muscles by pulling your belly button in towards your spine.","Slowly lift your upper body off the ground, twisting to one side, touching one elbow to the opposite knee.","Exhale as you reach the top of the movement and hold for a second.","Lower your upper body back down to the starting position, inhaling as you do so.","Repeat the movement on the other side, twisting to the opposite side.","Continue alternating sides for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '4d904f9e-c70b-4e48-96cc-37079cf73fd8', 'eccentric-chest-press', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"4d904f9e-c70b-4e48-96cc-37079cf73fd8","name":"Eccentric Chest Press","slug":"eccentric-chest-press","primaryMuscles":["chest"],"secondaryMuscles":[],"steps":["Adjust a chest press machine''s seat height so that the handles are at chest level.","Select the appropriate weight on the weight stack.","Sit on the machine with your back flat against the backrest and your feet flat on the floor.","Grasp the handles with an overhand grip and push them away from your chest with two hands until your arms are fully extended.","Release the handle with your right hand; your right hand bears no weight.","Slowly lower the handles back towards your chest with your left hand, keeping your elbow at a 90-degree angle. Note that this will only work on machines where the two handles are linked to each other and to the weight.","Grasp the handles with both hands. Push to fully extend your arms.","Release the handle with your left hand; your left hand bears no weight.","Slowly lower the handles back towards your chest with your right hand. This marks one repetition.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '4e7fce7c-1b19-4585-92bc-ff97e74da2f0', 'cable-wide-grip-seated-row', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"4e7fce7c-1b19-4585-92bc-ff97e74da2f0","name":"Wide Grip Seated Row – Cable","slug":"wide-grip-seated-row-cable","primaryMuscles":["lat","shoulder - back","trap"],"secondaryMuscles":["rotator cuff - back","rotator cuff - front"],"steps":["Adjust the cable machine to a low setting and attach a wide grip handle to the cable.","Sit on the seat with your feet flat on the floor and your knees slightly bent.","Grab the handle with an overhand grip, hands wider than shoulder-width apart.","Keep your back straight and lean slightly forward from the hips.","Pull the handle towards your lower chest, squeezing your shoulder blades together.","Pause for a moment, then slowly extend your arms back to the starting position.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '4e837ea7-d71c-439c-97bf-6e5bf0d86edf', 'dumbbell-single-arm-front-rack-walking-lunge', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"4e837ea7-d71c-439c-97bf-6e5bf0d86edf","name":"Single-Arm Front Rack Walking Lunge – Dumbbell","slug":"single-arm-front-rack-walking-lunge-dumbbell","primaryMuscles":["glute","quad"],"secondaryMuscles":["abdominal","calf","oblique","shoulder - front","trap"],"steps":["Stand with feet hip-width apart holding a dumbbell in one hand at shoulder height, with your elbow close to your body, palm facing inward.","Engage your core to maintain balance and ensure your shoulders are level.","Step forward with the opposite leg to the dumbbell and lower your body into a lunge until both knees are at around 90-degree angles.","Ensure your front knee does not extend past your toes and your back knee hovers just above the ground.","Push off the front foot to bring your rear leg forward, coming back to the standing position.","Continue the movement by alternating legs as you walk forward, maintaining balance and control throughout.","Perform an even number of repetitions with the dumbbell in one hand before switching the dumbbell to the other hand and doing the same number of repetitions again."],"notes":""}'),
('longhaul-fitness', '4eaa8bc3-1982-4de2-a0e3-c244205632c4', 'pendlay-row', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"4eaa8bc3-1982-4de2-a0e3-c244205632c4","name":"Pendlay Row","slug":"pendlay-row","primaryMuscles":["lat","shoulder - back","trap"],"secondaryMuscles":["bicep","forearm - inner","lower back","rotator cuff - back","rotator cuff - front"],"steps":["Load a barbell with weights on the floor.","Stand with your feet shoulder-width apart and your knees slightly bent.","Bend forward at the hips, keeping your back straight and parallel to the ground.","Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Keeping your upper body still and your elbows close to your body, pull the barbell up towards your chest, squeezing your shoulder blades together.","Lower the barbell all the way back down to the floor. Completely release the tension of the weight for a brief moment while maintaining control and keeping your back straight.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '50944578-2377-4973-ba99-77c62de0fd8e', 'one-leg-kneeling-couch-quad-stretch', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/flexibility.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"50944578-2377-4973-ba99-77c62de0fd8e","name":"One-Leg Kneeling Couch Quad Stretch","slug":"one-leg-kneeling-couch-quad-stretch","primaryMuscles":["quad"],"secondaryMuscles":[],"steps":["Stand in front of a couch, chair, or step stool.","Bend your right knee to place the top of your right foot on the surface behind you.","Bend your left knee to kneel to lower your body into a single-leg kneeling position.","Lower your body until you feel a comfortable stretch or your right knee rests on the floor.","Sit back towards your heel to increase the stretch in your quad.","Hold the stretch for the desired time and switch to the other side to complete a set."],"notes":""}'),
('longhaul-fitness', '50ed6871-7fa2-4e60-ba1c-ce07a503b2ba', 'machine-overhead-tricep-extension', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"50ed6871-7fa2-4e60-ba1c-ce07a503b2ba","name":"Overhead Tricep Extension – Machine","slug":"overhead-tricep-extension-machine","primaryMuscles":["tricep"],"secondaryMuscles":[],"steps":["Adjust the seat height so your arms comfortably reach the handles with your elbows at a 90-degree angle.","Sit down on the machine bench and grasp the handles with your palms facing each other.","Keep your elbows close to your head and your back flat against the pad throughout the exercise.","Exhale and extend your arms, pushing the handles overhead until your arms are fully extended but not locked.","Pause momentarily at the top of the movement, focusing on contracting your triceps.","Inhale as you slowly lower the handles back to the starting position, maintaining control and tension on the triceps.","Repeat for the desired number of repetitions."],"notes":""}');
INSERT INTO source_records (source_id, source_record_id, exercise_id, source_url, license, author, match_method, match_score, raw_json) VALUES
('longhaul-fitness', '51679e6f-6119-4c0e-b5ef-8dc25b6e0b4a', 'glute-bridge', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'exact', 100.0, '{"pk":"51679e6f-6119-4c0e-b5ef-8dc25b6e0b4a","name":"Glute Bridge","slug":"glute-bridge","primaryMuscles":["glute","hamstring"],"secondaryMuscles":[],"steps":["Start by lying on your back with your knees bent and feet flat on the ground.","Place your arms by your sides with your palms facing down.","Engage your core and glutes to lift your hips off the ground until your body forms a straight line from your shoulders to your knees.","Hold the position for a few seconds, squeezing your glutes at the top of the movement.","Lower your hips back down to the ground.","Repeat."],"notes":""}'),
('longhaul-fitness', '518578bb-130c-42f3-9fb8-1df14c5d7585', 'dumbbell-decline-bench-press', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"518578bb-130c-42f3-9fb8-1df14c5d7585","name":"Decline Bench Press – Dumbbell","slug":"decline-bench-press-dumbbell","primaryMuscles":["chest","shoulder - front"],"secondaryMuscles":["tricep"],"steps":["Set up a decline bench at a 45-degree angle.","Grab a pair of dumbbells and lie down on the bench with your feet secured at the end.","Hold the dumbbells at chest level with your palms facing forward.","Lower the dumbbells slowly towards your chest, keeping your elbows at a 45-degree angle.","Pause for a moment, then push the dumbbells back up to the starting position.","Repeat."],"notes":""}'),
('longhaul-fitness', '5315e4c2-9fb0-4240-b863-7b450bfbc57a', 'smith-machine-squat', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"5315e4c2-9fb0-4240-b863-7b450bfbc57a","name":"Squat – Smith Machine","slug":"squat-smith-machine","primaryMuscles":["glute","lower back","quad","thigh - inner"],"secondaryMuscles":["calf"],"steps":["Adjust the bar height to your desired position.","Load the bar with an appropriate weight.","Stand facing the bar with your feet shoulder-width apart.","Step forward and position the bar on your shoulders, resting on the back of your neck.","Grasp the bar with both hands, keeping your elbows pointed down and your chest up.","Lower your body by bending at the knees and hips, keeping your back straight and your head up.","Lower until your thighs are parallel to the ground, then push back up to the starting position.","Repeat."],"notes":""}'),
('longhaul-fitness', '549cc378-561e-4ab6-ac8e-f381c6167a65', 'flutter-kick', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"549cc378-561e-4ab6-ac8e-f381c6167a65","name":"Flutter Kick","slug":"flutter-kick","primaryMuscles":["abdominal"],"secondaryMuscles":["lower back","quad"],"steps":["Lie on your back with your legs straight and your arms by your sides or underneath your lower back.","Lift both legs off the ground.","Begin rapidly fluttering your legs up and down.","Keep your core engaged and your gaze towards the ceiling.","Continue fluttering for the desired amount of time or repetitions."],"notes":""}'),
('longhaul-fitness', '55639d34-075c-4183-9976-b08f8bfc3f0c', 'barbell-pause-squat', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"55639d34-075c-4183-9976-b08f8bfc3f0c","name":"Pause Squat – Barbell","slug":"pause-squat-barbell","primaryMuscles":["glute","lower back","quad","thigh - inner"],"secondaryMuscles":["calf"],"steps":["Start with your feet shoulder-width apart, your toes pointing slightly outward, and the barbell on your shoulders.","Lower your body into a squat position, keeping your back straight and your knees tracking with your toes.","Pause at the bottom of the squat for 2-3 seconds.","Slowly rise back up to the starting position.","Repeat."],"notes":""}'),
('longhaul-fitness', '558402d1-588a-449a-9f71-c04f2ded6695', 'runners-5', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"558402d1-588a-449a-9f71-c04f2ded6695","name":"Runner''s 5","slug":"runners-5","primaryMuscles":["calf","glute","hamstring","quad"],"secondaryMuscles":["thigh - inner","thigh - outer"],"steps":["Stand with your feet hip-width apart. We''re going to complete five, one-legged exercises on one side, then the other.","First, One-legged Squats: Stand on one leg with the other leg extended slightly behind you. Slowly lower your body by bending the knee of the standing leg, keeping your back straight and chest up. Lower yourself as far as comfortable while maintaining balance, then return to the starting position. Repeat for the desired number of repetitions.","Second, One-legged Romanian Deadlifts: Stand on one leg with a slight bend in your knee. Keeping your back straight, hinge at your hips to lower your upper body forward while extending the opposite leg straight behind you. Go as low as your flexibility allows, feeling a stretch in your hamstring. Return to the upright position. Repeat for the desired number of repetitions.","Third, One-legged Lunges: Stand on one leg and take a step forward with the other leg. Lower your body by bending both knees until your front thigh is parallel to the ground (or as low as you can comfortably go). Keep your upper body upright, and push through your front heel to return to the starting position. Repeat for the desired number of repetitions.","Fourth, One-legged Sidekicks: Stand on one leg with the other leg slightly lifted to the side. Perform a side kick by extending your lifted leg straight out to the side, then bring it back to the starting position. Maintain balance throughout. Repeat for the desired number of repetitions.","Fifth, One-legged Front-Back Kicks: Stand on one leg with the other leg lifted slightly in front of you. Perform a front kick by extending your lifted leg forward, then immediately perform a back kick by extending it backward. Keep control and balance throughout the movement. Repeat for the desired number of repetitions.","Repeat the five exercises on the other side."],"notes":""}'),
('longhaul-fitness', '5656bd84-ba8f-4d06-b06e-bc4f53be27a6', 'kneeling-push-up', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"5656bd84-ba8f-4d06-b06e-bc4f53be27a6","name":"Kneeling Push-Up","slug":"kneeling-push-up","primaryMuscles":["chest","shoulder - front","tricep"],"secondaryMuscles":["abdominal"],"steps":["Start on your hands and knees, with your hands shoulder-width apart and your knees hip-width apart.","Extend your legs behind you, so that your body forms a straight line from your head to your heels.","Engage your core and glutes to keep your body in a straight line.","Lower your body towards the ground by bending your elbows, keeping them close to your body.","Pause when your chest is just above the ground.","Push yourself back up to the starting position by straightening your arms.","Repeat."],"notes":""}'),
('longhaul-fitness', '580ce603-efcc-450d-921f-4f36b14496e3', 'lying-windshield-wiper-bent-knees', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"580ce603-efcc-450d-921f-4f36b14496e3","name":"Lying Windshield Wiper with Bent Knees","slug":"lying-windshield-wiper-with-bent-knees","primaryMuscles":["oblique"],"secondaryMuscles":["abdominal"],"steps":["Start by lying flat on your back with your arms extended out to the sides and your palms facing down.","Bend your knees and lift your feet off the ground, keeping your shins parallel to the floor.","Slowly lower your legs to one side, keeping your knees bent and your feet together.","Pause for a moment, then use your core muscles to lift your legs back to the starting position.","Repeat the movement to the other side, alternating sides for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '586887a1-88c8-462e-945a-230a87667e6f', 'eccentric-leg-extension', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"586887a1-88c8-462e-945a-230a87667e6f","name":"Eccentric Leg Extension","slug":"eccentric-leg-extension","primaryMuscles":["quad"],"secondaryMuscles":[],"steps":["Start by sitting on a leg extension machine with your back against the backrest and your feet flat on the footpad.","Adjust the machine so that the knee joint is aligned with the axis of rotation.","Place your hands on the side handles for stability.","Slowly extend your legs by straightening your knees, pushing against the resistance of the weight stack.","Once your legs are fully extended, pause briefly at the top of the movement.","Withdraw one leg so that the other leg supports all the weight. Slowly lower the weight back down with one leg by bending a knee, resisting the weight as it pulls your legs back towards the starting position.","Continue lowering the weight until your knees are at a 90-degree angle or slightly beyond.","Repeat the movement for the desired number of repetitions then switch sides."],"notes":""}'),
('longhaul-fitness', '59933119-adc2-48a5-a798-f5a4f81472aa', 'cable-upright-downward-internal-rotation', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"59933119-adc2-48a5-a798-f5a4f81472aa","name":"Upright Downward Internal Rotation – Cable","slug":"upright-downward-internal-rotation-cable","primaryMuscles":["rotator cuff - front"],"secondaryMuscles":[],"steps":["Adjust the pulley on a cable machine to eye-level and attach a handle to it.","Stand facing away from the machine, feet shoulder-width apart.","Grab the handle with one hand, raising your arm so your upper arm is parallel to the ground and your forearm is pointing straight up, creating a 90-degree angle at your elbow.","Brace your core and begin to rotate your hand forward at your shoulder, keeping your upper arm stable and parallel to the ground throughout the movement.","Continue the rotation until your forearm is parallel to the ground, completing the internal rotation.","Complete the desired number of repetitions before switching arms to perform the exercise on the opposite side."],"notes":""}'),
('longhaul-fitness', '599f3b85-fa7d-4296-8e03-d3d2d8d57234', 'kettlebell-alternating-z-press-double', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"599f3b85-fa7d-4296-8e03-d3d2d8d57234","name":"Alternating Z Press – Double Kettlebell","slug":"alternating-z-press-double-kettlebell","primaryMuscles":["shoulder - front","shoulder - side"],"secondaryMuscles":["abdominal","lower back","shoulder - back","tricep"],"steps":["Select two kettlebells of appropriate weight.","Sit on the floor with legs extended in front of you.","Clean the kettlebells to the front rack position.","Engage your core and ensure your spine is neutral.","Press one kettlebell overhead while keeping the other in the front rack position.","Lower the overhead kettlebell back to the front rack position.","Simultaneously press the other kettlebell overhead.","Continue to alternate pressing each kettlebell, creating a ''seesaw'' motion.","Repeat for the desired number of repetitions."],"notes":"Maintain core tension throughout the exercise to prevent arching your back or leaning back too far."}'),
('longhaul-fitness', '5b4eb704-166c-457b-a95e-808c328f6fc4', 'kneeling-incline-push-up', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"5b4eb704-166c-457b-a95e-808c328f6fc4","name":"Kneeling Incline Push-Up","slug":"kneeling-incline-push-up","primaryMuscles":["chest","shoulder - front","tricep"],"secondaryMuscles":["abdominal"],"steps":["Start by kneeling on the ground with your hands placed slightly wider than shoulder-width apart on an elevated surface, such as a bench or step.","Engage your core and lower your chest towards the elevated surface, bending your elbows and keeping them close to your body. Keep your body in a straight line from head to knee.","Pause briefly when your chest is just above the surface, then push through your hands to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '5c967fe6-d99f-4e10-9ac8-cd8e24d76367', 'pronated-grip-lat-pulldown', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"5c967fe6-d99f-4e10-9ac8-cd8e24d76367","name":"Pronated Grip Lat Pulldown","slug":"pronated-grip-lat-pulldown","primaryMuscles":["lat"],"secondaryMuscles":["bicep","forearm - inner","rotator cuff - back","rotator cuff - front","shoulder - back"],"steps":["Adjust the seat height and position yourself on the lat pulldown machine.","Grab the bar with an overhand grip, palms facing away from you, slightly wider than shoulder-width apart.","Sit down and position your thighs under the thigh pads, keeping your feet flat on the floor.","Keep your back straight and lean back slightly, engaging your core muscles.","Exhale and pull the bar down towards your upper chest, leading with your elbows.","Squeeze your shoulder blades together at the bottom of the movement.","Inhale and slowly release the bar back to the starting position, extending your arms fully.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '5d9b404c-4b12-4a7a-8222-08ab0c7cb473', 'barbell-reverse-curl', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"5d9b404c-4b12-4a7a-8222-08ab0c7cb473","name":"Reverse Curl – Barbell","slug":"reverse-curl-barbell","primaryMuscles":["forearm - outer"],"secondaryMuscles":["bicep"],"steps":["Stand up straight with a shoulder-width grip on the barbell, palms facing down (pronated grip). Keep your elbows close to your torso.","While keeping the upper arms stationary, contract your forearms by raising the bar towards your shoulders, hinging at your elbows. Your forearms should be the only part moving. Keep your wrists straight, focusing on a straight line from your elbow to your knuckles.","Continue to raise the weight until bar is at shoulder level. Hold the forearm-contracting position for a brief pause.","Inhale and slowly begin to lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"notes":"Keep your elbows close to your body and avoid swinging the weight. This is a targetted exercise for a small, specific muscle. If you find yourself flaring your elbows, or using momentum to lift the weight, consider lowering the weight to maintain proper form."}'),
('longhaul-fitness', '5e5f39a1-c950-49a9-abde-2e7aadd90f1b', 'barbell-shrug', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"5e5f39a1-c950-49a9-abde-2e7aadd90f1b","name":"Shrug – Barbell","slug":"shrug-barbell","primaryMuscles":["trap"],"secondaryMuscles":["forearm - inner"],"steps":["Stand with your feet shoulder-width apart and hold a barbell in front of your thighs with an overhand grip.","Keep your arms fully extended and your shoulders relaxed.","Slowly raise your shoulders as high as possible, as if you are trying to touch your ears with them.","Hold the contracted position for a brief pause, squeezing your shoulder muscles.","Lower your shoulders back down to the starting position in a controlled manner.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '5ea4b519-41ae-45a3-b8ad-c3fd9a15121c', 'hands-and-knees-segmental-cat-cow', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/flexibility.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"5ea4b519-41ae-45a3-b8ad-c3fd9a15121c","name":"Hands-And-Knees Segmental Cat Cow","slug":"hands-and-knees-segmental-cat-cow","primaryMuscles":["lower back"],"secondaryMuscles":["abdominal"],"steps":["Get on your hands and knees on a padded surface, such as a gym mat or yoga mat.","Start from the tailbone and shift each vertebra up, towards the ceiling, one at a time. Continue to flex each segment through the lower, middle, and upper spine.","Once your full spine is in flexion, reverse the motion and push each vertebra, from the top of your spine to the bottom, towards the floor.","Continue alternating between flexion and extension for the desired amount of time."],"notes":"This exercise differs from a traditional Cat Cow by focusing on each vertebra''s slow and deliberate motion through the stretch, hence the \"Segmental\" descriptor."}'),
('longhaul-fitness', '5f281096-ed92-4b29-b189-7e91c50024be', 'one-arm-kneeling-spine-twist', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/flexibility.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"5f281096-ed92-4b29-b189-7e91c50024be","name":"One-Arm Kneeling Spine Twist","slug":"one-arm-kneeling-spine-twist","primaryMuscles":["oblique","lower back"],"secondaryMuscles":[],"steps":["Sit on your heels to isolate the movement from your low back.","Place one palm flat on the floor and the other just behind your head or neck. This is your starting position.","Rotate your upper body as far as you can or until your elbow points straight up to the ceiling.","Hold the rotation for the desired amount of time.","Slowly return to the start position.","Repeat the exercise on the other side for the same time."],"notes":""}'),
('longhaul-fitness', '5f509f4e-6008-49d8-aa02-3aad760c7296', 'cable-skull-crusher-rope', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"5f509f4e-6008-49d8-aa02-3aad760c7296","name":"Skull Crusher – Cable with Rope","slug":"skull-crusher-cable-with-rope","primaryMuscles":["tricep"],"secondaryMuscles":["forearm - inner","forearm - outer"],"steps":["Begin by setting a flat bench in front of a cable machine with a low pulley.","Lie down on the bench with your head closest to the cable machine.","Grab the rope with an overhand grip, arms fully extended above your forehead. This is your starting position.","Ensure your elbows are shoulder-width apart and remain in a fixed position throughout the exercise.","Engage your core as you slowly lower the rope towards your forehead by bending your elbows.","Pause briefly once the rope is close to your forehead.","Press back to the starting position by extending your elbows and contracting your triceps.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '60576989-d045-492b-82b0-743bb4a3ce62', 'plank-2', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', 100.0, '{"pk":"60576989-d045-492b-82b0-743bb4a3ce62","name":"Plank","slug":"plank","primaryMuscles":["abdominal","lower back"],"secondaryMuscles":["oblique","shoulder - front"],"steps":[],"notes":""}'),
('longhaul-fitness', '60a68833-4f4c-4f42-9bf6-7113cdcc12b7', 'barbell-hip-thrust', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"60a68833-4f4c-4f42-9bf6-7113cdcc12b7","name":"Hip Thrust – Barbell","slug":"hip-thrust-barbell","primaryMuscles":["glute"],"secondaryMuscles":["hamstring","thigh - inner"],"steps":["Sit on the ground with your back against a bench, your feet flat on the ground, and position a barbell across your hips.","Engage your core and glute muscles, and slowly lift your hips up off the ground until your body forms a straight line from your knees to your shoulders.","Hold for a second or two at the top of the movement, then lower your hips back down to the ground.","Repeat."],"notes":""}'),
('longhaul-fitness', '61fa9545-1e8c-4308-8824-2eaa44825b22', 'one-arm-front-bend-wall-push', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/flexibility.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"61fa9545-1e8c-4308-8824-2eaa44825b22","name":"One-Arm Front Bend Wall Push","slug":"one-arm-front-bend-wall-push","primaryMuscles":["chest","lat","shoulder - front"],"secondaryMuscles":[],"steps":["Stand facing a wall and place one hand flat against it at shoulder height.","Step back slightly and bend forward at the hips, keeping your arm straight and pressed into the wall.","Lift your arm upward along the wall to increase the stretch in the front of your shoulder.","Keep your back flat and your core engaged to avoid arching.","Hold the stretch for the desired time and switch to the other side."],"notes":""}'),
('longhaul-fitness', '627f9ef6-8d10-4b15-a647-397166cd5f3a', 'cable-pull-through', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'exact', 100.0, '{"pk":"627f9ef6-8d10-4b15-a647-397166cd5f3a","name":"Cable Pull Through","slug":"cable-pull-through","primaryMuscles":["glute","hamstring","lower back"],"secondaryMuscles":["thigh - inner"],"steps":["Attach a rope to a cable machine at floor-level position and stand facing away from the machine with your feet shoulder-width apart.","Grab the rope with both hands and position it between your legs, just above your knees.","Hinge forward at the hips and push your glutes back, keeping your back straight and chest up.","Lower your torso until it is parallel to the floor, feeling a stretch in your hamstrings.","Engage your glutes and hamstrings to drive your hips forward, standing up straight.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '634b5e9d-d092-4e2e-89d4-342369e91920', 'cable-hammer-curl-rope', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"634b5e9d-d092-4e2e-89d4-342369e91920","name":"Hammer Curl – Cable With Rope","slug":"hammer-curl-cable-with-rope","primaryMuscles":["bicep"],"secondaryMuscles":["forearm - outer"],"steps":["Attach a rope to the low pulley of a cable machine.","Stand facing the cable machine with your feet shoulder-width apart and a slight bend in your knees.","Grab each end of the rope with a neutral grip (palms facing each other) and stand up straight. This is your starting position.","Keeping your upper arms stationary, exhale as you curl the weights up towards your shoulders by flexing your biceps. Keep your elbows close to your body.","Pause briefly at the top of the movement, squeezing your biceps.","Inhale as you slowly lower the rope back to the starting position.","Repeat for the desired number of reps."],"notes":""}'),
('longhaul-fitness', '64c13d9c-16e6-489b-a999-e2b44edb3cb4', 'one-arm-tabletop-spine-twist', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/flexibility.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"64c13d9c-16e6-489b-a999-e2b44edb3cb4","name":"One-Arm Tabletop Spine Twist","slug":"one-arm-tabletop-spine-twist","primaryMuscles":["lower back","oblique"],"secondaryMuscles":["shoulder - back","trap"],"steps":["Kneel down and sit back onto your heels.","Place both elbows on the ground in front of you.","Raise one arm and place your hand behind your head.","Rotate your upper body towards the side with the raised arm, looking up.","Hold the stretch for the desired time.","Slowly return to the starting position.","Repeat the stretch for the same time on the other side."],"notes":""}'),
('longhaul-fitness', '64c75731-36c2-45ae-b8c1-c8b481f34144', 'dumbbell-shoulder-press', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"64c75731-36c2-45ae-b8c1-c8b481f34144","name":"Shoulder Press – Dumbbell","slug":"standing-shoulder-press-dumbbell","primaryMuscles":["shoulder - front"],"secondaryMuscles":["shoulder - side","tricep"],"steps":["Start by standing with your feet shoulder-width apart, holding a dumbbell in each hand by your thighs.","Raise the dumbbells to shoulder height, palms facing forward, and elbows bent.","Press the dumbbells upward until your arms are fully extended above your head.","Pause for a moment at the top of the movement, then slowly lower the dumbbells back down to shoulder height.","Repeat."],"notes":""}'),
('longhaul-fitness', '6556cc6a-40c4-4474-8424-f48794f57438', 'dumbbell-romanian-deadlift', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"6556cc6a-40c4-4474-8424-f48794f57438","name":"Romanian Deadlift – Dumbbell","slug":"romanian-deadlift-dumbbell","primaryMuscles":["glute","hamstring","lower back"],"secondaryMuscles":["calf","trap","quad"],"steps":["Stand with your feet hip-width apart, holding a dumbbell in each hand with palms facing your body.","Begin with a slight bend in your knees, keep your back straight, chest up, and shoulders back throughout the exercise.","Push your hips back and hinge at the hips to lower the dumbbells along the front of your legs, maintaining a neutral spine.","Lower the dumbbells to just below your knees or to mid-shin level, depending on your flexibility, while keeping the weights close to your legs.","Pause briefly at the bottom of the movement, ensuring your core is braced and your hamstrings and glutes are engaged.","Thrust your hips forward to lift your torso back to the starting position, simultaneously contracting your glutes at the top of the movement.","Repeat the movement for the desired number of repetitions without letting the dumbbells touch the floor between reps to keep tension on the muscles."],"notes":"Differences between a RDL and a standard deadlift:<ul><li>Keep your legs relatively straight with only a slight bend in your knees.</li><li>Focus on the eccentric phase while hinging at the hips and lowering the weight.</li><li>Lower the bar just below the knees or to mid-shin level without touching the ground to maintain tension on the hamstrings and glutes throughout the exercise.</li></ul>"}'),
('longhaul-fitness', '65e38827-9d2d-4854-b745-c66ad6901e14', 'standing-bicycle-crunch', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"65e38827-9d2d-4854-b745-c66ad6901e14","name":"Standing Bicycle Crunch","slug":"standing-bicycle-crunch","primaryMuscles":["abdominal","oblique"],"secondaryMuscles":["glute","thigh - inner","thigh - outer","lower back"],"steps":["Stand upright with your feet hip-width apart.","Place your hands behind your head, elbows out to the sides.","Engage your core muscles to stabilize your torso.","Lift your right knee towards your chest while simultaneously crunching your left elbow towards your right knee.","Return to the starting position.","Now, lift your left knee towards your chest while crunching your right elbow towards your left knee.","Continue alternating between sides for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '65fb73cb-f41d-4326-8095-32a0cd9f1b89', 'dumbbell-one-handed-hammer-isometric-hold', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"65fb73cb-f41d-4326-8095-32a0cd9f1b89","name":"One-Handed Hammer Isometric Hold – Dumbbell","slug":"one-handed-hammer-isometric-hold-dumbbell","primaryMuscles":["bicep"],"secondaryMuscles":["forearm - inner","forearm - outer"],"steps":["Select a dumbbell of appropriate weight and position yourself at a preacher curl bench.","Stand with one foot forward and the other back in a staggered stance.","Lean slightly forward from the hips and place the back of your upper arm (of the arm that will be curling) on the sloped part of the preacher bench, ensuring your shoulders are open to the side.","Curl your arm up to achieve a 90-degree angle at the elbow. Your forearm should be roughly perpendicular to the floor.","Hold the dumbbell at this angle, maintain the position firmly and ensure the muscle is under constant tension without movement for the desired time period.","Once the hold is complete, slowly lower the dumbbell back to the starting position in a controlled manner.","Repeat the process using the other arm."],"notes":"Ensure that your wrist remains straight and stable throughout the duration of the exercise."}'),
('longhaul-fitness', '660b4a26-21f5-44fc-8186-c82c1e5ce99e', 'dumbbell-front-rack-knee-over-toe-split-squat', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"660b4a26-21f5-44fc-8186-c82c1e5ce99e","name":"Front Rack Knee Over Toe Split Squat – Dumbbell","slug":"front-rack-knee-over-toe-split-squat-dumbbell","primaryMuscles":["glute","hamstring","quad"],"secondaryMuscles":["calf","shoulder - front"],"steps":["Select an appropriate pair of dumbbells and hold one in each hand.","Clean the dumbbells to the front rack position, resting one end of each dumbbell on your shoulders with your elbows pointed forward and your palms facing each other.","Position your feet in a split stance with one leg forward and the other leg behind you.","Align your front knee with your second to fourth toes, ensuring your knee travels over your toes throughout the movement.","Engage your core to maintain an upright torso and stabilize your position. This is your starting position.","Lower your body by bending both knees, ensuring the front knee tracks over the toes and the back knee approaches the ground.","Descend until the back knee is just above the ground and the front thigh is parallel to the floor.","Press through the heel of your front foot to return to the starting position.","Repeat the movement for the desired number of repetitions and then switch legs."],"notes":""}'),
('longhaul-fitness', '6713b6cf-8f67-4ee1-b546-436e5f4fba21', 'overhead-shrug-neck-rotation', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/flexibility.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"6713b6cf-8f67-4ee1-b546-436e5f4fba21","name":"Overhead Shrug Neck Rotation","slug":"overhead-shrug-neck-rotation","primaryMuscles":["trap"],"secondaryMuscles":["shoulder - back","shoulder - front"],"steps":["Raise both arms with your elbows straight overhead.","Shrug your shoulders upwards.","Slowly rotate your head and neck completely to one side without dropping the shoulders.","Rotate your head and neck completely to the opposite side.","Return to neutral cervical spine rotation.","Continue these rotations for the desired amount of time."],"notes":""}'),
('longhaul-fitness', '67cc9514-9294-4772-b7c3-e2ba8e00e92a', 'dumbbell-lunge', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', 100.0, '{"pk":"67cc9514-9294-4772-b7c3-e2ba8e00e92a","name":"Lunge – Dumbbell","slug":"lunge-dumbbell","primaryMuscles":["glute","quad","thigh - inner"],"secondaryMuscles":["forearm - inner"],"steps":["Stand with your feet hip-width apart and hold a dumbbell in each hand, palms facing your body.","Take a big step forward with your right foot, keeping your torso upright.","Bend both knees to lower your body towards the floor, making sure your right knee is directly above your ankle.","Push through your right heel to return to the starting position.","Repeat on the other side, stepping forward with your left foot.","Continue alternating legs for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '6849d9f8-8f62-4873-aed0-e85a4b0fa8ca', 'dumbbell-squat', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"6849d9f8-8f62-4873-aed0-e85a4b0fa8ca","name":"Squat – Dumbbell","slug":"squat-dumbbell","primaryMuscles":["glute","lower back","quad","thigh - inner"],"secondaryMuscles":["calf"],"steps":["Stand with your feet shoulder-width apart, with your toes pointing slightly outward.","Hold a dumbbell in each hand by your sides, with your palms facing inward.","Engage your core and keep your chest lifted throughout the movement.","Lower your body by bending at the hips and knees as if sitting on a chair.","Keep your weight in your heels, and make sure your knees are tracking over your toes.","Lower your body until your thighs are parallel to the ground or until you reach your desired depth.","Push through your heels to stand back up to the starting position.","Repeat."],"notes":"Keep your knees in line with your toes throughout the movement."}'),
('longhaul-fitness', '69fa145a-d0a0-4261-a2cd-111c273d7b6b', 'fire-hydrants', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"69fa145a-d0a0-4261-a2cd-111c273d7b6b","name":"Fire Hydrants","slug":"fire-hydrants","primaryMuscles":["glute","thigh - outer"],"secondaryMuscles":[],"steps":["Start on all fours with your hands directly under your shoulders and your knees directly under your hips.","Engage your core and keep your back straight throughout the exercise.","Keeping your knee bent, lift one leg out to the side, keeping your foot flexed and parallel to the ground.","Pause for a moment at the top of the movement, squeezing your glutes.","Slowly lower your leg back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"notes":""}'),
('longhaul-fitness', '6a68e84c-8965-4dfe-b3c3-56ccb396a89e', 'one-leg-prone-hip-extension', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"6a68e84c-8965-4dfe-b3c3-56ccb396a89e","name":"One-Leg Prone Hip Extension","slug":"one-leg-prone-hip-extension","primaryMuscles":["glute","hamstring"],"secondaryMuscles":["lower back"],"steps":["Lie down on your stomach with your arms extended out in front of you for support.","Engage your core to stabilize your lower back and minimize anterior pelvic tilt.","Lift one heel up towards the ceiling while keeping the knee straight and the foot flexed.","Hold the lifted position for 5-10 seconds, focusing on the contraction in the glutes and hamstrings.","Slowly lower your leg back down to the ground.","Repeat the movement on the same side for your desired number of repetitions, then switch to the other leg."],"notes":""}'),
('longhaul-fitness', '6aea031b-4635-4135-b249-f8e0c1fca3c8', 'in-out-rope-wave', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"6aea031b-4635-4135-b249-f8e0c1fca3c8","name":"In-Out Rope Wave","slug":"in-out-rope-wave","primaryMuscles":["bicep","forearm - inner","forearm - outer","shoulder - back","shoulder - front","shoulder - side","trap"],"secondaryMuscles":["abdominal","chest","tricep"],"steps":["Stand with your feet shoulder-width apart, facing the anchor point of the battle rope.","Hold one end of the rope in each hand, arms extended in front of you at about waist height.","Begin with a slight bend in your knees, a straight back, and a tight core.","Simultaneously move your arms outward to your sides, creating outward waves with each side of the rope.","Quickly reverse the movement by bringing your arms back toward each other, creating inward waves.","Keep your arms moving in and out quickly, maintaining the rhythm to continuously send waves down the rope.","Ensure your movements are controlled and focused, utilizing your arm, shoulder, and core muscles.","Continue the in-out motion for the desired duration or number of repetitions."],"notes":""}'),
('longhaul-fitness', '6b346b4a-c672-466b-a4d5-e5b84aa3a526', 'machine-hip-thrust', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"6b346b4a-c672-466b-a4d5-e5b84aa3a526","name":"Hip Thrust – Machine","slug":"hip-thrust-machine","primaryMuscles":["glute"],"secondaryMuscles":["hamstring","thigh - inner"],"steps":["Adjust the machine to the appropriate height and resistance level.","Sit on the machine with your back against the backrest and your feet flat on the foot platform.","Engage your core and glutes, then press through your heels to extend your hips forward.","Continue to drive your hips forward until your body is in a straight line from your knees to your shoulders.","Hold the position for a brief moment, focusing on squeezing your glutes.","Slowly lower your hips back down to the starting position, maintaining control throughout the movement.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '6b36f879-6076-463a-b8f3-06f61cd3bcbe', 'clean-and-jerk', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"6b36f879-6076-463a-b8f3-06f61cd3bcbe","name":"Clean and Jerk","slug":"clean-and-jerk","primaryMuscles":["glute","lower back","quad","shoulder - front","thigh - inner"],"secondaryMuscles":["calf","forearm - inner","hamstring","shoulder - side","trap","tricep"],"steps":["Start with the barbell on the ground, feet shoulder-width apart and toes pointing forward.","Bend down and grip the bar with hands slightly wider than shoulder-width apart.","Stand up, keeping your back straight and the bar close to your body.","Once the bar reaches your hips, explosively extend your hips, knees, and ankles to propel the bar upward.","As the bar reaches your chest, drop your body underneath it and catch it on your shoulders in a front squat position.","Stand up from the front squat position and prepare for the jerk.","Dip your body slightly and then explosively drive the bar overhead by extending your arms and legs.","Lock out your arms and hold the bar overhead for a moment before lowering it back down to the starting position.","Repeat."],"notes":""}'),
('longhaul-fitness', '6bc882f1-29e7-44c0-99b4-a36a4c91fc08', 'facepull', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"6bc882f1-29e7-44c0-99b4-a36a4c91fc08","name":"Face Pull","slug":"face-pull","primaryMuscles":["rotator cuff - back","trap","shoulder - back"],"secondaryMuscles":["shoulder - side","forearm - outer"],"steps":["Start by attaching a single long rope or two shorter ropes to a eye-level pulley on a cable machine.","Grasp the rope or cable with both hands using an overhand grip, with your palms facing each other. You want your thumbs to be able to point backwards, guiding the movement.","Step back a few feet from the cable machine, so there is tension in the rope or cable.","Stand with your feet shoulder-width apart, and engage your core muscles to maintain good posture throughout the exercise. This is your starting position.","Pull the handles towards your face, separating your hands and arms as they go back.","Keep your elbows high and out to the sides as you pull the rope backwards. End the pull with each arm at a 90-degree angle at the elbow.","Hold the position for a second, then slowly lower the rope back to the starting position.","Repeat for the desired number of repetitions."],"notes":"Focus on using your back muscles to perform the movement rather than relying on your arms or shoulders."}'),
('longhaul-fitness', '6c9d30d3-a001-4529-a3c6-65c6db15ca42', 'barbell-preacher-curl', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"6c9d30d3-a001-4529-a3c6-65c6db15ca42","name":"Preacher Curl – Barbell","slug":"preacher-curl-barbell","primaryMuscles":["bicep"],"secondaryMuscles":["forearm - inner"],"steps":["Set up a preacher curl bench with the appropriate weight on the barbell.","Adjust the seat height so that your armpits are resting comfortably on the top of the bench.","Grab the barbell with an underhand grip, hands shoulder-width apart.","Place your upper arms on the bench pad, keeping your elbows close to your body.","Exhale and curl the barbell up towards your shoulders, keeping your upper arms stationary.","Pause briefly at the top of the movement, squeezing your biceps.","Inhale and slowly lower the barbell back down to the starting position.","Repeat."],"notes":""}'),
('longhaul-fitness', '6ce7b2fa-f145-4864-8b6e-12883465557d', 'seated-calf-raise', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', 100.0, '{"pk":"6ce7b2fa-f145-4864-8b6e-12883465557d","name":"Seated Calf Raise","slug":"seated-calf-raise","primaryMuscles":["calf"],"secondaryMuscles":[],"steps":["Adjust the seat height and position yourself on the calf raise machine with your feet flat on the foot platform.","Place your thighs under the leg pad and ensure that your knees are slightly bent.","Grasp the handles or sides of the machine for stability.","Slowly raise your heels by extending your ankles as far as possible while keeping your toes on the foot platform.","Hold the contracted position for a brief moment, feeling the stretch in your calves.","Lower your heels back down to the starting position, allowing your calves to stretch.","Repeat the movement for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '6d2ea3ce-084a-478b-95ce-a5b65ccbe580', 'cable-standing-chest-fly', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', 100.0, '{"pk":"6d2ea3ce-084a-478b-95ce-a5b65ccbe580","name":"Standing Chest Fly – Cable","slug":"standing-chest-fly-cable","primaryMuscles":["chest"],"secondaryMuscles":["bicep","forearm - inner","shoulder - front"],"steps":["Stand in front of a cable machine, facing away from the machine, with your feet shoulder-width apart and knees slightly bent.","Grasp the handles of the cables with your palms facing forward and your arms extended out to the sides at shoulder height.","Engage your core and maintain a slight bend in your elbows throughout the exercise. Try not to change the degree of elbow bend during the repetitions.","Exhale and slowly bring your arms forward, until your hands touch, while maintaining the same level of shoulder height.","Inhale and slowly return your arms back to the starting position, keeping them extended and at shoulder height.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '6d9c3bff-a56e-424c-924f-db93da20f44f', 'kettlebell-single-arm-front-rack-contralateral-walking-lunge', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"6d9c3bff-a56e-424c-924f-db93da20f44f","name":"Single-Arm Front Rack Contralateral Walking Lunge – Kettlebell","slug":"single-arm-front-rack-contralateral-walking-lunge-kettlebell","primaryMuscles":["glute","quad"],"secondaryMuscles":["abdominal","calf","oblique","shoulder - front","trap"],"steps":["Start standing with feet hip-width apart and a kettlebell in your right hand in a front rack position, resting the kettlebell on the back of your forearm with your elbow close to the body. This is your starting position.","Engage your core and brace your body, maintaining a neutral spine throughout the movement.","Step your left foot forward into a lunge position, ensuring your knee is aligned with your toe and creating a 90-degree angle at the knee joint.","Lower your right knee toward the ground without letting it touch, keeping your front knee stacked over your ankle.","Press through your left heel to return to the starting position, keeping the kettlebell stable in the front rack position.","Repeat for the desired number of repetitions walking forward with your left foot.","Switch sides to complete the same number of repetitions, holding the kettlebell with your left hand and walking forward with your right foot."],"notes":""}'),
('longhaul-fitness', '6ddf0c74-d1ee-4f51-8e7e-bef2d3ff653e', 'dumbbell-one-handed-overhead-contralateral-step-up', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"6ddf0c74-d1ee-4f51-8e7e-bef2d3ff653e","name":"One-Handed Overhead Contralateral Step-Up – Dumbbell","slug":"one-handed-overhead-contralateral-step-up-dumbbell","primaryMuscles":["glute","quad"],"secondaryMuscles":["abdominal","calf","hamstring","oblique","shoulder - front"],"steps":["Stand in front of a step or bench with feet hip-width apart and a dumbbell in one hand.","Press the dumbbell overhead with the arm fully extended, keeping the core engaged.","Place the opposite foot on the step, ensuring the entire foot is on the platform.","Push through the heel of the foot on the step to lift your body up, while keeping the dumbbell arm extended overhead.","Bring the trailing leg up to join the lead on the step, achieving a balanced position.","Carefully step back down with the trailing leg first, followed by the lead leg.","Maintain control and balance throughout the movement, keeping the dumbbell overhead.","Repeat for desired reps, then switch arms and legs."],"notes":""}'),
('longhaul-fitness', '6e94e3fd-7403-4597-98f5-3861d83b8f72', 'bulgarian-split-squat', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"6e94e3fd-7403-4597-98f5-3861d83b8f72","name":"Bulgarian Split Squat","slug":"bulgarian-split-squat","primaryMuscles":["glute","quad","thigh - inner"],"secondaryMuscles":[],"steps":["Stand with your back facing a bench or step.","Place the top of one foot on the bench or step behind you.","Bend your front knee and lower your body down towards the ground, keeping your back straight.","Pause when your front thigh is parallel to the ground.","Push through your front heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."],"notes":""}'),
('longhaul-fitness', '6f538926-fbaf-45ac-874f-cd3acb052e6f', 'one-leg-incline-pigeon-stretch-bench', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/flexibility.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"6f538926-fbaf-45ac-874f-cd3acb052e6f","name":"One-Leg Incline Pigeon Stretch – Bench","slug":"one-leg-incline-pigeon-stretch-bench","primaryMuscles":["glute","hamstring"],"secondaryMuscles":["thigh - inner","thigh - outer"],"steps":["Set up an exercise bench at a 30 to 45 degree incline.","Place the outside calf of the leg you want to stretch on the inclined bench with the knee elevated above the foot. This calf should cross the center line of your body.","Have the other leg supporting your bodyweight behind you.","Drop the hip towards the ground and use your hands to support your body.","Keep the spine neutral to isolate the stretch to the hips.","Optionally, hinge forwards at the hips while maintaining a neutral spine to deepen the stretch.","Hold the stretch for the desired time and switch to the other side."],"notes":""}'),
('longhaul-fitness', '6f6f3ba2-98ee-4c0d-9f2a-75e5dfc91206', 'dumbbell-hammer-curl', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"6f6f3ba2-98ee-4c0d-9f2a-75e5dfc91206","name":"Hammer Curl – Dumbbell","slug":"hammer-curl-dumbbell","primaryMuscles":["bicep"],"secondaryMuscles":["forearm - outer"],"steps":["Stand up straight with your feet shoulder-width apart and hold a dumbbell in each hand with your palms facing your body.","Keep your elbows close to your torso and exhale as you lift both dumbbells towards the shoulder of their holding hand, until your bicep is fully contracted and the dumbbell is at shoulder level.","Pause for a second at the top of the movement and squeeze your biceps.","Lower the dumbbells back down to the starting position in a controlled manner.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '6f7b19e2-af13-4a5e-b0a1-329b6b642c1e', 'bar-hang', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"6f7b19e2-af13-4a5e-b0a1-329b6b642c1e","name":"Bar Hang","slug":"bar-hang","primaryMuscles":["forearm - inner","forearm - outer"],"secondaryMuscles":[],"steps":["Find a sturdy horizontal bar that can support your body weight.","Stand facing the bar and reach up to grab it with both hands, palms facing away from your body.","Jump or step up to lift your feet off the ground and hang from the bar with your arms fully extended.","Engage your shoulder blades and core muscles to maintain a stable position.","Hold the position for a desired amount of time.","To release, slowly lower your body down and step or jump off the bar."],"notes":""}'),
('longhaul-fitness', '70398b40-1c71-41f7-9568-1a73b79cefe3', 'dumbbell-prone-incline-front-raise', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"70398b40-1c71-41f7-9568-1a73b79cefe3","name":"Prone Incline Front Raise – Dumbbell","slug":"prone-incline-front-raise-dumbbell","primaryMuscles":["shoulder - front"],"secondaryMuscles":["chest","shoulder - side","trap"],"steps":["Set an incline bench to a 45-degree angle and lie face down with your chest against the bench.","Hold a dumbbell in each hand, palms facing your knees, arms extended towards the ground.","Keep the balls of your feet on the ground and your neck in a neutral position. Brace your core and maintain a straight back throughout the exercise.","With your arms straight except for a slight elbow bend, slowly raise the dumbbells until they are above your head, parallel with your upper body.","Pause briefly at the top of the movement.","Slowly lower the dumbbells back to the starting position.","Repeat the movement for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '703d017a-492a-417d-9ff5-5f78f7d29d7a', 'dumbbell-single-leg-romanian-deadlift', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"703d017a-492a-417d-9ff5-5f78f7d29d7a","name":"Single-Leg Romanian Deadlift – Dumbbell","slug":"single-leg-romanian-deadlift-dumbbell","primaryMuscles":["calf","glute","hamstring","lower back"],"secondaryMuscles":["trap","quad"],"steps":["Begin by standing on one leg, with a slight bend in the knee. Keep your other leg off the ground and behind you.","Hold a dumbbell or kettlebell in the opposite hand of the leg you are standing on.","Brace your core, keep your chest up, and slowly hinge forward at the hips, keeping your back straight and your shoulders down. As you hinge, lift your non-standing leg behind you, keeping it in line with your torso.","Continue lowering the weight until you feel a stretch in your hamstring. Your standing knee should be slightly bent but not locked.","Pause briefly at the bottom of the movement, then slowly reverse the motion by driving your hips forward and standing up tall while bringing your lifted leg back down to the ground.","Repeat for the desired number of repetitions on one leg before switching to the other."],"notes":""}'),
('longhaul-fitness', '70485eac-6986-49e0-83ea-a714dd634c4f', 'band-horizontal-wood-chop', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"70485eac-6986-49e0-83ea-a714dd634c4f","name":"Horizontal Wood Chop – Band","slug":"horizontal-wood-chop-band","primaryMuscles":["oblique"],"secondaryMuscles":["abdominal"],"steps":["Attach a resistance band to a sturdy anchor point at waist height.","Stand perpendicular to the anchor point with feet shoulder-width apart and knees slightly bent.","Hold the resistance band with both hands and extend arms out in front of the body.","Rotate the torso and pull the band across the body towards the opposite hip.","Keep the arms straight and engage the core muscles throughout the movement.","Slowly return to the starting position","Repeat."],"notes":""}'),
('longhaul-fitness', '7069565b-3ef8-4bd7-97c7-543dbd5f542d', 'step-up', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"7069565b-3ef8-4bd7-97c7-543dbd5f542d","name":"Step-Up","slug":"step-up","primaryMuscles":["glute","quad"],"secondaryMuscles":["calf","hamstring","thigh - inner","thigh - outer"],"steps":["Stand upright with a bench or bench-height platform in front of you, feet hip-width apart.","Place your right foot on the bench, ensuring your entire foot is on the surface.","Press through your right foot to lift your body up onto the bench, bringing your left foot to meet your right foot.","Stand tall on the bench with both feet flat and your core engaged.","Step back down with your left foot, returning to the floor.","Follow by stepping down with your right foot, coming back to the starting position.","Repeat the exercise for the desired number of repetitions before switching to lead with the left foot."],"notes":"Hold weight in your hands to increase the exercise''s resistance."}'),
('longhaul-fitness', '70e0b9fd-a6e8-4e68-b804-2ef6b81dda4f', 'crunch-2', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', 100.0, '{"pk":"70e0b9fd-a6e8-4e68-b804-2ef6b81dda4f","name":"Crunch","slug":"crunch","primaryMuscles":["abdominal"],"secondaryMuscles":["oblique"],"steps":["Start by lying flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head, with your elbows pointing outwards.","Engage your core muscles by pulling your belly button towards your spine.","Lift your head, neck, and shoulders off the ground, while keeping your lower back pressed into the floor.","Hold the contraction for a moment, then slowly lower yourself back down to the starting position.","Repeat."],"notes":"For additional intensity, hold a weight during the crunch. You have two options. One, you can place the weight on your upper chest. Two, you can hold the weight directly above your chest with straight arms except for a slight bend in your elbows."}'),
('longhaul-fitness', '70ee43ca-112b-482c-9403-57d00d03bf5c', 'one-leg-wide-lunge', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/flexibility.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"70ee43ca-112b-482c-9403-57d00d03bf5c","name":"One-Leg Wide Lunge","slug":"one-leg-wide-lunge","primaryMuscles":["glute","hamstring"],"secondaryMuscles":["quad"],"steps":["Start in a plank or push-up position with both hands on the floor.","Step one foot forward, placing it just outside your hand on the same side.","Keep the back leg extended straight behind you with toes tucked under.","Lower your hips towards the floor to stretch the front leg''s hamstrings and glutes. Your back knee may touch the floor.","Push your hips forward to stretch the hip flexors of the back leg.","Hold the stretch for the desired time and switch to the other side."],"notes":""}'),
('longhaul-fitness', '719c9b11-bb34-4f4a-95fd-332ee68c1ff7', 'close-grip-bench-press', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', 100.0, '{"pk":"719c9b11-bb34-4f4a-95fd-332ee68c1ff7","name":"Close-Grip Bench Press","slug":"close-grip-bench-press","primaryMuscles":["tricep"],"secondaryMuscles":["chest","shoulder - front"],"steps":["Set up the bench press station with the appropriate weight on the barbell.","Lie down on the bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with your hands shoulder-width apart or just slightly narrower.","Unrack the barbell and hold it directly above your chest, arms fully extended.","Lower the barbell towards your chest by bending your elbows, keeping them close to your body.","Pause briefly with the barbell barely above your chest.","Push the barbell back up to the starting position by extending your arms, keeping your elbows close to your body.","Repeat the movement for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '75662402-905e-4f0d-92c3-ea37d528e0f7', 'single-arm-hang-bar', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"75662402-905e-4f0d-92c3-ea37d528e0f7","name":"Single-Arm Hang – Bar","slug":"single-arm-hang-bar","primaryMuscles":["forearm - inner","forearm - outer"],"secondaryMuscles":[],"steps":["Find a sturdy bar that can support your weight.","Jump up and grab the bar with one hand.","Hold the position for as long as you can.","Slowly lower yourself down and release your grip on the bar."],"notes":""}'),
('longhaul-fitness', '765372ba-e08c-4103-9e7a-b7dc532fe86e', 'seated-calf-massage-lacrosse-ball', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/flexibility.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"765372ba-e08c-4103-9e7a-b7dc532fe86e","name":"Seated Calf Massage – Lacrosse Ball","slug":"seated-calf-massage-lacrosse-ball","primaryMuscles":["calf"],"secondaryMuscles":[],"steps":["Sit on the floor and place a massage ball under your calf muscle.","Apply gentle pressure by pressing your leg down onto the ball.","Slowly flex your foot upward (dorsiflex) to stretch the calf while keeping pressure on the ball.","Then point your foot downward (plantarflex) to massage the calf.","Repeat the flexing and pointing movement slowly to massage the muscle.","Hold the massage for the desired time and switch to the other calf if needed."],"notes":"Increase the pressure of your calf on the ball by adding your other leg''s ankle onto the pressured leg''s shin to press down."}'),
('longhaul-fitness', '76b1b81d-88fd-4f66-b6cb-ea104d66c464', 'archer-push-up-rings', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"76b1b81d-88fd-4f66-b6cb-ea104d66c464","name":"Archer Push Up – Rings","slug":"archer-push-up-rings","primaryMuscles":["chest","tricep"],"secondaryMuscles":["abdominal","shoulder - side","trap"],"steps":["Adjust the rings to be about shin height.","Grip each ring with your palms facing towards each other and arms extended.","Position yourself in a plank position with feet together, body in a straight line from head to heels.","Engage your core and keep your glutes and legs tight. This is your starting position.","Shift your body weight to one side. Bend your elbow to lower your chest on that side as if doing a push-up. While lowering, extend the other arm out to the side as if you''re holding a drawn bow and arrow.","Lower yourself until your chest is in line with the lowered hand, keeping the extended arm slightly bent.","Push back up to the starting position by pressing with the bent arm and performing a chest fly with the extended arm.","Alternate sides and repeat for desired repetitions, ensuring equal reps for both arms."],"notes":"Raise the ring height to take weight off the push-up and make it easier to perform. Lower the ring height to make the exercise more difficult."}'),
('longhaul-fitness', '78a8e45c-0b2a-407c-8cc3-6fd1cb7f0135', 'kettlebell-front-rack-low-switch-cossack-squat', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"78a8e45c-0b2a-407c-8cc3-6fd1cb7f0135","name":"Front Rack Low Switch Cossack Squat – Kettlebell","slug":"front-rack-low-switch-cossack-squat-kettlebell","primaryMuscles":["glute","quad","thigh - inner"],"secondaryMuscles":["calf","forearm - inner","forearm - outer","shoulder - front","thigh - outer"],"steps":["Begin with two kettlebells positioned on the floor in front of you.","Clean the kettlebells into a front rack position, with elbows tucked in and weights resting comfortably between your forearms and biceps.","Stand with feet wider than shoulder-width apart, toes slightly pointed out.","Shift your weight to your right leg, bending the right knee while keeping the left leg straight.","Lower your hips into a deep squat over your right leg, maintaining an upright torso. Your left toes may lift towards the ceiling, but keep both heels on the ground. This is your starting position.","Without standing up, shift your weight across to your left leg, bending your left knee while straightening your right leg similarly.","Transition the weight distribution smoothly towards the left leg.","Continue to alternate the weight shift from one leg to the other for the desired number of repetitions, maintaining a low squat position throughout the entire movement."],"notes":"Ensure your front rack position is stable, keeping the chest lifted and core engaged throughout the exercise."}'),
('longhaul-fitness', '7997b04d-b3f0-4b6c-a795-8b32c13bc650', 'machine-calf-raise', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"7997b04d-b3f0-4b6c-a795-8b32c13bc650","name":"Calf Raise – Machine","slug":"calf-raise-machine","primaryMuscles":["calf"],"secondaryMuscles":[],"steps":["Stand on calf raise machine with the balls of your feet on the edge and your heels hanging off.","Slowly raise your heels as high as possible, keeping your knees straight.","Hold the position, then lower your heels back down below the level of the raised surface.","Repeat."],"notes":""}'),
('longhaul-fitness', '79df21bd-9e07-4fac-b581-6b34f4f05651', 'landmine-rotation', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"79df21bd-9e07-4fac-b581-6b34f4f05651","name":"Landmine Rotation","slug":"landmine-rotation","primaryMuscles":["abdominal","oblique"],"secondaryMuscles":["glute","lower back","rotator cuff - back","rotator cuff - front","shoulder - front","shoulder - side"],"steps":["Place one end of a barbell securely into a landmine attachment or a corner to stabilize it.","Stand with your feet shoulder-width apart, facing the end of the barbell, and grab the end of the bar with both hands.","Press the barbell up and hold it in front of your head with your arms extended, while keeping your elbows slightly bent.","Begin to rotate your torso to one side; as you do, allow your hands holding the barbell to drop towards the hip on the same side as the rotation. During the rotation, keep your arms in the same position, extended with elbows bent, as much as possible.","Simultaneously, allow the foot you are rotating away from to rise up to the ball of the foot at the bottom of the rotation, facilitating a full rotation of the hips.","Reverse the direction and rotate your torso to the opposite side, repeating the arm movement and foot pivot to complete one full repetition.","Continue alternating the rotational movements for the desired number of repetitions, maintaining the appropriate arm and foot mechanics throughout."],"notes":""}'),
('longhaul-fitness', '79df8346-799a-4040-b8f2-bcd7f6dabbbc', 'kettlebell-alternating-single-arm-dead-clean-to-push-press', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"79df8346-799a-4040-b8f2-bcd7f6dabbbc","name":"Alternating Single-Arm Dead Clean to Push Press – Kettlebell","slug":"alternating-single-arm-dead-clean-to-push-press-kettlebell","primaryMuscles":["glute","quad","shoulder - front"],"secondaryMuscles":["calf","hamstring","lower back","tricep"],"steps":["Stand with feet shoulder-width apart, a kettlebell in front of you.","Hinge at the hips and slightly bend your knees to grip the kettlebell with one hand, palm facing you.","Engage your core and drive through your heels to lift the kettlebell off the ground.","As you reach the top of the movement, quickly pull the kettlebell upwards, allowing it to rotate around your hand to the rack position at shoulder level.","From the rack position, bend your knees slightly in a quarter squat.","Explosively extend your legs and press the kettlebell overhead, rotating your wrist so your palm faces forward.","Reverse the press motion to return the kettlebell to the rack position.","Rotate the kettlebell back down to the starting position with control.","Switch hands and repeat the sequence on the opposite side."],"notes":""}'),
('longhaul-fitness', '7a971512-0265-490a-8ac0-871c0e1013de', 'push-up-2', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', 100.0, '{"pk":"7a971512-0265-490a-8ac0-871c0e1013de","name":"Push-Up","slug":"push-up","primaryMuscles":["chest","shoulder - front","tricep"],"secondaryMuscles":["abdominal"],"steps":["Start in a plank position, with your hands shoulder-width apart and your fingers pointing forward.","Keep your core engaged, your back straight, and your hips in line with your shoulders.","Lower your body towards the ground by bending your elbows, keeping your upper arms close to your sides.","Keep your elbows at a 45-degree angle to your body, and continue lowering until your chest touches the ground.","Push back up to the starting position by straightening your arms, keeping your core engaged and your body in a straight line throughout the movement.","Repeat"],"notes":""}'),
('longhaul-fitness', '7b34c325-1800-4bb0-a99e-d1a868bb07c1', 'cable-overhead-tricep-extension', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"7b34c325-1800-4bb0-a99e-d1a868bb07c1","name":"Overhead Tricep Extension – Cable With Rope","slug":"overhead-tricep-extension-cable-with-rope","primaryMuscles":["tricep"],"secondaryMuscles":[],"steps":["Attach a rope to a cable machine at a low setting.","Face the machine and grab the rope with an overhand grip.","Step back to create tension in the cable and keep your feet shoulder-width apart.","Keep your elbows close to your head and your upper arms stationary.","Extend your forearms down until your arms are fully extended.","Pause for a moment and then slowly return to the starting position.","Repeat for desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '7b853e82-8131-408b-984e-451b74251b81', 'barbell-push-press', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', 100.0, '{"pk":"7b853e82-8131-408b-984e-451b74251b81","name":"Push Press – Barbell","slug":"push-press-barbell","primaryMuscles":["shoulder - front"],"secondaryMuscles":["glute","lower back","quad","shoulder - side","trap","tricep"],"steps":["Start with the barbell resting on your front shoulders, with your feet shoulder-width apart.","Bend your knees slightly and dip your hips down, then explosively extend your legs and push the barbell up overhead.","As the barbell reaches the top of the movement, press it up and lock out your arms.","Lower the barbell back down to your shoulders and repeat for the desired number of reps."],"notes":""}'),
('longhaul-fitness', '7b9ae742-67f9-48cc-b560-ec9c9518dbf6', 'kettlebell-front-rack-march', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"7b9ae742-67f9-48cc-b560-ec9c9518dbf6","name":"Front Rack March – Kettlebell","slug":"front-rack-march-kettlebell","primaryMuscles":["abdominal","shoulder - front"],"secondaryMuscles":["calf","glute","quad"],"steps":["Choose two kettlebells of the same weight.","Clean the kettlebells to your chest, tucking your elbows close to your body and holding the bells in front of your shoulders with your hands facing each other. This is your starting position.","Lift one knee to hip level and hold briefly, then lower it back to the ground.","Alternate lifting the other knee to the same level, maintaining balance and control.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '7d7182bd-b2a4-4d98-9065-df84013b14b3', 'medicine-ball-rolling-push-up', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"7d7182bd-b2a4-4d98-9065-df84013b14b3","name":"Rolling Push-Up – Medicine Ball","slug":"rolling-push-up-medicine-ball","primaryMuscles":["chest","shoulder - front","tricep"],"secondaryMuscles":["abdominal","forearm - inner","forearm - outer","shoulder - side"],"steps":["Begin by placing a medicine ball on the floor in front of you.","Assume a push-up position by getting into a plank, with your hands shoulder-width apart and feet extended back.","Position one hand on the center of the medicine ball, while the other remains on the floor, keeping your body straight and core engaged.","Perform a push-up, lowering your chest to the floor while maintaining balance and stability on the ball.","Push back up to the starting position, keeping your body in a straight line.","Carefully roll the medicine ball across to the other hand while remaining in the plank position.","Place your opposite hand on the medicine ball and stabilize your body.","Repeat the push-up with the medicine ball under the other hand.","Continue alternating hands after each push-up for the desired number of repetitions or sets."],"notes":""}'),
('longhaul-fitness', '7e48d467-c289-4dd8-b6e8-479a0bcc7cc6', 'band-side-kick', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"7e48d467-c289-4dd8-b6e8-479a0bcc7cc6","name":"Side Kicks – Band","slug":"side-kicks-band","primaryMuscles":["thigh - outer"],"secondaryMuscles":["glute"],"steps":["Stand with your feet hip-width apart and a resistance band around your ankles.","Engage your core and lift one leg out to the side, keeping it straight and the foot flexed.","Pause at the top of the movement, then slowly lower the leg back down to the starting position.","Repeat for the desired number of reps, then switch sides."],"notes":""}'),
('longhaul-fitness', '7e703b05-364f-4847-af0f-a1a22aab19f6', 'bosu-burpee', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"7e703b05-364f-4847-af0f-a1a22aab19f6","name":"Burpee – BOSU","slug":"burpee-bosu","primaryMuscles":["chest","glute","quad","shoulder - front","shoulder - side"],"secondaryMuscles":["abdominal","trap"],"steps":["Start in a standing position with the BOSU ball on the ground (inflated-side down) in front of you.","Grip the edges of the BOSU ball and jump your feet back into a plank position.","Perform a push-up while gripping the BOSU ball.","Jump your feet back towards the BOSU ball into a low squat position.","Complete the squat by standing up. As you rise, lift the BOSU ball overhead, extending your arms towards the ceiling.","Repeat the exercise for desired number of reps."],"notes":""}'),
('longhaul-fitness', '7e95b8b5-a6eb-41b6-a3c9-ae06a9ba7ac4', 'machine-hip-abduction', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"7e95b8b5-a6eb-41b6-a3c9-ae06a9ba7ac4","name":"Hip Abduction – Machine","slug":"hip-abduction-machine","primaryMuscles":["thigh - outer"],"secondaryMuscles":["glute"],"steps":["Adjust the machine to fit your height and leg length.","Sit on the machine with your back against the backrest and your feet on the footrests.","Press your legs outward against the resistance of the machine.","With your knees at their farthest point, hold the weight for a moment before slowly releasing the resistance and returning to the starting position.","Repeat."],"notes":""}'),
('longhaul-fitness', '7eb6aca3-4a9b-483d-bbf4-56f9c7b28c4e', 'cable-shoulder-external-rotation', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"7eb6aca3-4a9b-483d-bbf4-56f9c7b28c4e","name":"External Shoulder Rotation – Cable","slug":"external-shoulder-rotation-cable","primaryMuscles":["rotator cuff - back"],"secondaryMuscles":["forearm - outer","shoulder - back"],"steps":["Stand side-on to a cable machine, with the machine arm set at the middle height. Attach a single handle.","Grab the handle with the hand that''s furthest from the machine, ensuring that your elbow is bent at a 90-degree angle.","Step away from the machine so that the weight is lifted slightly from its stack and there is tension on the cable.","Position your elbow so that it is close to your side and holding weight across your abdomen.","Slowly rotate your arm outward, pulling the handle away from the machine while keeping your elbow fixed at your side.","Rotate the arm until the hand as far as possible without releasing tension on your back rotator cuff and without compromising form.","Pause for a moment at the maximum rotation point.","Slowly return the handle to the starting position in a controlled manner without allowing the weight to pull your arm back too fast.","Repeat the exercise for the desired number of reps before switching sides to ensure both back rotator cuffs are worked evenly."],"notes":"Keep your feet shoulder-width apart for stable footing and engage your core. Keep your body straight and avoid rotating your hips or shoulders during the movement. Your forearm should be perpendicular to your torso throughout the exercise."}'),
('longhaul-fitness', '7ee4abdd-e815-49d1-9d47-ec92a26a6b75', 'one-arm-lying-spine-twist-yoga-block', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/flexibility.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"7ee4abdd-e815-49d1-9d47-ec92a26a6b75","name":"One-Arm Lying Spine Twist – Yoga Block","slug":"one-arm-lying-spine-twist-yoga-block","primaryMuscles":["lower back","oblique"],"secondaryMuscles":["chest","trap"],"steps":["Lie on your side with your top leg supported by a yoga block or foam roller.","Extend both arms straight in front of you, palms together.","Lift your top arm up towards the ceiling while keeping your legs stable. Your gaze should follow the top arm while it travels.","Rotate your upper body, moving your top arm behind your back, face twisted towards the top arm, without lifting your leg off the support.","Hold the pose for the desired amount of time before repeating the exercise on the other side."],"notes":""}'),
('longhaul-fitness', '7f13d2c2-73bc-4ff1-a02b-fde9a6f0f5f3', 'power-clean-and-press', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"7f13d2c2-73bc-4ff1-a02b-fde9a6f0f5f3","name":"Power Clean and Press","slug":"power-clean-and-press","primaryMuscles":["glute","lower back","shoulder - front","thigh - inner"],"secondaryMuscles":["calf","forearm - inner","hamstring","shoulder - side","trap","tricep"],"steps":["Start with feet shoulder-width apart and the barbell on the floor in front of you.","Bend down and grip the barbell with hands slightly wider than shoulder-width apart.","Stand up, keeping your back straight, the barbell close to your shins, and lifting with your legs.","As the barbell reaches your chest, quickly drop into a high squat position. The crease of your hips should be above the top of your thighs. Catch the barbell at shoulder height.","Stand up from the squat position, lifting the barbell overhead with arms fully extended.","Lower the barbell back down to shoulder height.","Reverse the movement and lower the barbell back down to the floor and release your grip.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '803604bd-04f2-44fa-b4e4-57b6b61a4e72', 'lying-overhead-shoulder-rotation-dowel', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/flexibility.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"803604bd-04f2-44fa-b4e4-57b6b61a4e72","name":"Lying Overhead Shoulder Rotation – Dowel","slug":"lying-overhead-shoulder-rotation-dowel","primaryMuscles":["shoulder - front"],"secondaryMuscles":["rotator cuff - front"],"steps":["Lie on your back holding a dowel with both hands above your chest, hands shoulder-width apart, with straight arms.","Lower the dowel over over your head by flexing your shoulders, keeping arms straight.","Hold the end range stretch for the desired amount of time."],"notes":""}'),
('longhaul-fitness', '80582f01-1e34-4f03-ba2f-1964d8e33de3', 'cable-biceps-curl', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"80582f01-1e34-4f03-ba2f-1964d8e33de3","name":"Cable Curl – Rope","slug":"cable-curl-rope","primaryMuscles":["bicep"],"secondaryMuscles":["forearm - inner"],"steps":["Attach a rope to a low pulley cable machine.","Stand facing the machine with feet shoulder-width apart and knees slightly bent.","Grasp the rope with an underhand grip, palms facing each other.","Keep elbows close to your sides and curl the rope towards your shoulders.","Pause briefly at the top of the movement, then slowly lower the rope back to the starting position.","Repeat."],"notes":""}'),
('longhaul-fitness', '81b24d3f-91b4-4b51-96c2-5b1440d8cbae', 'kneeling-pallof-press', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"81b24d3f-91b4-4b51-96c2-5b1440d8cbae","name":"Kneeling Pallof Press","slug":"kneeling-pallof-press","primaryMuscles":["abdominal","oblique"],"secondaryMuscles":["lower back","rotator cuff - back","rotator cuff - front","shoulder - front","shoulder - side"],"steps":["Kneel side-on to a cable machine or secure a resistance band at chest height.","Grasp the handle (or end of the band) with both hands and take a kneeling step away to create tension.","Position your knees shoulder-width apart for stability.","Hold the handle or band close to your chest, keeping your hands centered in front of you.","Engage your core muscles to stabilize your torso. This is your starting position.","Slowly press the handle or band straight out in front of your chest, keeping your arms straight.","Ensure your hips and shoulders stay squared and facing forward throughout the movement.","Hold the fully-pressed position for 1-2 seconds.","Slowly return the handle or band back to the starting position with control.","Repeat for the desired number of repetitions.","Switch sides and perform the exercise to work the core muscles evenly."],"notes":""}'),
('longhaul-fitness', '82432a9d-fe95-4805-af08-2b8b96126645', 'standing-clamshell', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"82432a9d-fe95-4805-af08-2b8b96126645","name":"Standing Clamshell","slug":"standing-clamshell","primaryMuscles":["glute","thigh - outer"],"secondaryMuscles":["thigh - inner"],"steps":["Stand with your feet shoulder-width apart and place your hands together, in front of your face, for balance.","Lower your body by bending your knees until you''re in a half-squat position.","Bring your knees close together, until they''re almost touching. This is your starting position.","Rotate your knees outwards, away from your body, engaging your outer hips and glutes.","Hold the position for a moment, then slowly bring your knees back to the starting position.","Continue the movement for your desired number of repetitions."],"notes":"Use a resistance band around your knees to increase the difficulty of the exercise."}'),
('longhaul-fitness', '82c48a55-f4f8-483f-9767-11cb6053dcb3', 'prone-assisted-neck-bridge', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/flexibility.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"82c48a55-f4f8-483f-9767-11cb6053dcb3","name":"Prone Assisted Neck Bridge","slug":"prone-assisted-neck-bridge","primaryMuscles":["lower back"],"secondaryMuscles":["glute","hamstring","trap"],"steps":["Place a yoga or exercise mat on the floor for head padding.","Position the top of your head on the floor with your arms bent at the elbows, hands on the ground by both sides of your head, supporting your upper body.","Support your lower body by balancing on the balls of your toes.","Hinge at the hips to maintain a neutral spine throughout the movement.","Hold the bridge position for up to 8 seconds or as long as comfortable.","Lower your heels back down to the floor and extend your arms at the elbows to finish one repetition.","Repeat the exercise for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '83961423-3b39-4147-94d6-0b8147f2aecb', 'copenhagen-plank-leg-lift', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"83961423-3b39-4147-94d6-0b8147f2aecb","name":"Copenhagen Plank with Leg Lift","slug":"copenhagen-plank-with-leg-lift","primaryMuscles":["oblique","thigh - inner"],"secondaryMuscles":["abdominal","glute","hamstring","quad"],"steps":["Begin by positioning yourself on your side, propped up on your forearm and elbow directly beneath your shoulder.","Extend your legs straight out with your top foot resting on a bench or elevated surface.","Align your body in a straight line from head to heels, engaging your core and glutes.","Lift your lower leg up and down without rotating your hips or losing alignment.","Maintain a strong core throughout the movement to keep your hips elevated and stable.","Repeat for desired number of reps, then switch to the other side."],"notes":""}'),
('longhaul-fitness', '84106cf9-fa3f-4ce8-9a87-f20bb90a3203', 'one-arm-lunging-lower-back-wall-twist', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/flexibility.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"84106cf9-fa3f-4ce8-9a87-f20bb90a3203","name":"One-Arm Lunging Lower Back Wall Twist","slug":"one-arm-lunging-spinal-wall-twist","primaryMuscles":["lower back","oblique","trap"],"secondaryMuscles":[],"steps":["Start in a split squat position with your front leg against the wall, foot flat on the ground. Place your back leg''s knee and toes on the ground.","Raise the arm on the same side as your front leg parallel to the ground in front of you. Keep the back of your hand and forearm in contact with the wall.","Rotate your torso slowly away from the front leg side, reaching your other arm back, parallel to the ground, to touch the back of that hand to the wall behind you.","Keep your hips facing forward and chest open as you rotate.","Hold the stretch for the desired time and switch to the other side."],"notes":""}'),
('longhaul-fitness', '84134ecd-e418-48f4-a52b-1a3aeb72c33c', 'foam-roller-one-arm-kneeling-lower-back-wall-sweep', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/flexibility.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"84134ecd-e418-48f4-a52b-1a3aeb72c33c","name":"One-Arm Kneeling Lower Back Wall Sweep – Foam Roller","slug":"one-arm-kneeling-lower-back-wall-sweep-foam-roller","primaryMuscles":["lower back"],"secondaryMuscles":["abdominal","oblique"],"steps":["Start in a half kneel position by resting on one knee that''s against a wall and the other leg in front of you with the foot place on the ground.","Place a foam roller or yoga block between your front knee and the wall and hold it in place.","Raise both hands behind your head and mesh your fingers.","Rotate your torso so that your chest faces away from the wall and your back is against the wall as much as possible.","Bend forwards through the torso, maintaining contact with the wall using your elbow that''s closest to the wall, until you reach your end range, chest approaching the front knee.","Slide against the wall, reversing the movement, until you are once again upright.","Rotate through your torso until your chest faces the wall. Try to make the same elbow maintain contact with the wall throughout the movement.","Extend your spine towards your back leg as far as is comfortable for you.","Slide against the wall until you return to an upright position to complete a repetition.","Continue repetitions for the desired amount of time then switch to the other side."],"notes":""}'),
('longhaul-fitness', '842cfbf1-1a71-48c6-832d-3713d3f6811b', 'dumbbell-row', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', 100.0, '{"pk":"842cfbf1-1a71-48c6-832d-3713d3f6811b","name":"Row – Dumbbell","slug":"row-dumbbell","primaryMuscles":["lat","shoulder - back","trap"],"secondaryMuscles":["bicep","forearm - inner","rotator cuff - back","rotator cuff - front"],"steps":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand with a neutral grip (palms facing each other).","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Bring the dumbbells up towards your chest, keeping your elbows close to your body.","Pause at the top of the movement and squeeze your shoulder blades together.","Lower the dumbbells back down to the starting position.","Repeat."],"notes":""}'),
('longhaul-fitness', '8431323c-ca05-4424-9e2f-995e85f4f9e3', 'hang-power-clean', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"8431323c-ca05-4424-9e2f-995e85f4f9e3","name":"Hang Power Clean","slug":"hang-power-clean","primaryMuscles":["glute","lower back"],"secondaryMuscles":["forearm - outer","hamstring","thigh - inner","trap"],"steps":["Stand with feet shoulder-width apart, gripping a barbell at thigh level with palms facing you. This is your starting position.","Bend your knees slightly and hinge at the waist to bring the barbell just above knee level.","Keep your back straight and core tight.","Explosively extend your hips and knees. At the same time, shrug your shoulders and pull the barbell up along your body.","As the barbell reaches chest height, rotate your wrists under the bar and push your body slightly under it.","Catch the bar on the front part of your shoulders with a slight bend in your knees (higher than a full squat).","Stand up fully with the barbell in the front rack position.","Lower the bar back to the starting position.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '859b2211-9bb0-462b-987c-620a3e37d688', 'machine-leg-press', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', 100.0, '{"pk":"859b2211-9bb0-462b-987c-620a3e37d688","name":"Leg Press – Machine","slug":"leg-press-machine","primaryMuscles":["glute","quad","thigh - inner"],"secondaryMuscles":["hamstring"],"steps":["Adjust the seat of the leg press machine so that your knees are at a ~90-degree angle when your feet are on the footplate.","Sit on the machine and place your feet shoulder-width apart on the footplate.","Push the footplate away from your body by extending your legs.","Lower the footplate back towards your body by bending your legs and keeping your feet flat on the plate.","Repeat."],"notes":"Keep your back flat against the seat throughout the movement. Keep your feet flat on the footplate, and make sure your knees are tracking in line with your toes. Exhale as you push the footplate away from your body, and inhale as you lower it back down. Avoid locking out your knees at the top of the movement, as this can put unnecessary stress on the joint."}'),
('longhaul-fitness', '87118ae6-212c-499f-81e3-328e9596c08a', 'plate-front-hold', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"87118ae6-212c-499f-81e3-328e9596c08a","name":"Front Hold – Plate","slug":"front-hold-plate","primaryMuscles":["shoulder - front"],"secondaryMuscles":["shoulder - side"],"steps":["Stand with your feet shoulder-width apart and hold a weight plate with both hands in front of your chest.","Engage your core and keep your back straight.","Extend your arms fully, keeping your arms parallel to the ground.","Hold this position for the desired amount of time."],"notes":""}'),
('longhaul-fitness', '871eaca9-5404-4e13-98ce-114d2b840c6a', 'bosu-mountain-climber', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"871eaca9-5404-4e13-98ce-114d2b840c6a","name":"Mountain Climbers – BOSU","slug":"mountain-climbers-bosu","primaryMuscles":["abdominal"],"secondaryMuscles":["oblique"],"steps":["Place a BOSU ball on the floor with the dome side facing down.","Assume a push-up position with your hands gripped on the sides of the BOSU ball.","Engage your core and keep your body in a straight line from head to toe.","Start by bringing one knee towards your chest, then quickly switch and bring the other knee towards your chest.","Continue alternating your knees in a running motion, keeping your hips low and your abs tight.","Perform the exercise for the desired number of repetitions or time."],"notes":""}'),
('longhaul-fitness', '8770385f-5661-4027-98c1-adc13f4a9140', 'foam-roller-prone-quad-rolling', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/flexibility.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"8770385f-5661-4027-98c1-adc13f4a9140","name":"Prone Quad Rolling – Foam Roller","slug":"prone-quad-rolling-foam-roller","primaryMuscles":["quad"],"secondaryMuscles":[],"steps":["Lay down, facing the floor, on a foam roller placed on a tender spot on your quadriceps muscle.","Use your arms and other leg to control the amount of bodyweight you distribute on the foam roller.","Slowly flex and extend your knee to get an active massage.","Continue rolling and massaging the quadriceps for the desired amount of time."],"notes":""}'),
('longhaul-fitness', '87856d89-8e9a-464c-bf9f-61b4454f9f4d', 'lying-hamstring-bridge', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"87856d89-8e9a-464c-bf9f-61b4454f9f4d","name":"Lying Hamstring Bridge","slug":"lying-hamstring-bridge","primaryMuscles":["glute","hamstring"],"secondaryMuscles":["lower back"],"steps":["Lie down on your back with your knees bent at about 110 degrees.","Keep your heels planted on the floor and raise your toes up.","Engage your core to maintain a neutral spine.","Lift your pelvis off the ground, squeezing your hamstrings and glutes.","Hold the lifted position for a moment, ensuring your spine remains neutral.","Slowly lower your pelvis back down to the starting position.","Repeat the movement for your desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '894860a3-3fd5-439a-ae31-a60f4f90e6c2', 'seated-knee-to-heel-taps', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/flexibility.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"894860a3-3fd5-439a-ae31-a60f4f90e6c2","name":"Seated Knee To Heel Taps","slug":"seated-knee-to-heel-taps","primaryMuscles":["glute","thigh - inner","thigh - outer"],"secondaryMuscles":["lower back","oblique","quad"],"steps":["Sit on the ground leaning backwards with your arms straight and your hands behind you.","Place your feet just wider than shoulder distance in front of you with your knees bent at 90° angles. This is your starting position.","Rotate one hip outwards until the knee of that leg reaches the ground.","Rotate the other hip inwards so that the knee of that leg touches the heel of the leg on the ground.","Return to the starting position and alternate sides.","Continue alternating the movement on each side for the desired amount of time."],"notes":"Keep the 90° bend in your knees throughout the exercise."}'),
('longhaul-fitness', '8a96a73c-0c69-4102-a2c9-f103c8497e7e', 'frog-pumps', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"8a96a73c-0c69-4102-a2c9-f103c8497e7e","name":"Frog Pumps","slug":"frog-pumps","primaryMuscles":["glute"],"secondaryMuscles":["hamstring","thigh - inner"],"steps":["Lie on your back with your knees bent and your feet flat on the ground. Keep your feet close together and your heels touching.","Bring your feet up towards your hips along the ground until they''re about 6 inches apart, and then let your knees fall out to the sides so that your feet are touching each other. This is the starting position.","Engage your glutes and lift your hips up towards the ceiling as high as you can, making sure to keep your feet and knees in the same position.","Hold the top position for 1-2 seconds, then slowly lower your hips to the starting position.","Repeat."],"notes":"Place a dumbbell or plate on your lower abdomen for extra difficulty."}'),
('longhaul-fitness', '8aa20360-bcb2-4044-a963-f45718362782', 'dumbbell-lu-raise', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"8aa20360-bcb2-4044-a963-f45718362782","name":"Lu Raise – Dumbbell","slug":"lu-raise-dumbbell","primaryMuscles":["shoulder - front","shoulder - side"],"secondaryMuscles":["rotator cuff - back","rotator cuff - front","trap"],"steps":["Stand with your feet shoulder-width apart, holding a pair of dumbbells at your sides with your palms facing your body.","Lift the dumbbells laterally with a slight bend in the elbows, rotating your thumbs upwards as the weights ascend.","Continue lifting the weights above your head until your arms are fully extended and your thumbs are pointing towards each other.","Pause briefly at the top of the movement.","Lower the dumbbells back to the starting position in a controlled manner, reversing the thumb rotation."],"notes":""}'),
('longhaul-fitness', '8b8db841-8aa2-4248-91d4-6ad192d06f4a', 'cable-shoulder-internal-rotation', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"8b8db841-8aa2-4248-91d4-6ad192d06f4a","name":"Internal Shoulder Rotation – Cable","slug":"internal-shoulder-rotation-cable","primaryMuscles":["rotator cuff - front"],"secondaryMuscles":["forearm - inner","shoulder - front"],"steps":["Stand side-on to a cable machine, with the machine arm set at the middle height. Attach a single handle.","Grab the handle with the hand that''s closest to the machine, ensuring that your elbow is bent at a 90-degree angle.","Step away from the machine so that the weight is lifted slightly from its stack and there is tension on the cable.","Position your elbow so that it is close to your side and your forearm points towards the machine as far as naturally possible.","Slowly rotate your arm inward, pulling the handle away from the machine while keeping your elbow fixed at your side.","Rotate the arm until the hand crosses your abdomen without releasing tension on your front rotator cuff and without compromising form.","Pause for a moment at the maximum rotation point.","Slowly return the handle to the starting position in a controlled manner without allowing the weight to pull your arm back too fast.","Repeat the exercise for the desired number of reps before switching sides to ensure both front rotator cuffs are worked evenly."],"notes":"Keep your feet shoulder-width apart for stable footing and engage your core. Keep your body straight and avoid rotating your hips or shoulders during the movement. Your forearm should be perpendicular to your torso throughout the exercise."}'),
('longhaul-fitness', '8b94a531-c6e9-4eb4-94d2-46352ce849f8', 'dumbbell-one-handed-row', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', 100.0, '{"pk":"8b94a531-c6e9-4eb4-94d2-46352ce849f8","name":"One-Handed Row – Dumbbell","slug":"one-handed-row-dumbbell","primaryMuscles":["lat","shoulder - back","trap"],"secondaryMuscles":["bicep","forearm - inner","rotator cuff - back","rotator cuff - front"],"steps":["Stand with your feet shoulder-width apart and your knees slightly bent.","Hold a dumbbell in one hand with your palm facing your body.","Bend forward at the waist, keeping your back straight and your abs engaged.","Let the dumbbell hang straight down towards the floor.","Exhale and pull the dumbbell up towards your chest, keeping your elbow close to your body.","Squeeze your shoulder blades together at the top of the movement.","Inhale and slowly lower the dumbbell back down towards the floor.","Repeat for the desired number of reps, then switch sides and repeat."],"notes":"Brace yourself against a bench with your free hand to take some of the effort off your lower back."}'),
('longhaul-fitness', '8daa6758-aa1a-46a9-ab25-7c1274eeecb5', 'machine-bench-press', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"8daa6758-aa1a-46a9-ab25-7c1274eeecb5","name":"Bench Press – Machine","slug":"bench-press-machine","primaryMuscles":["chest","shoulder - front","tricep"],"secondaryMuscles":["rotator cuff - front"],"steps":["Adjust the bench and seat height so that your chest aligns with the bench press machine''s handles and your feet are flat on the floor.","Select the appropriate weight on the weight stack.","Sit on the machine with your back flat against the back pad.","Grasp the handles with a firm grip, keeping your wrists straight. This is the starting position.","Press the handles away from your chest, keeping your elbows at about a 45-degree angle from your body, extending your arms fully without locking your elbows.","Pause briefly at the top of the press.","Slowly lower the handles back to the starting position, maintaining control throughout the movement.","Repeat the press for the desired number of repetitions."],"notes":"Ensure your back is flat against the bench, and your feet are firmly planted on the ground.  Keep your core tight. Exhale as you push the bar away from your chest, and inhale as you lower it down."}'),
('longhaul-fitness', '8e166eae-5d0f-4661-9f9e-996f6859df36', 'wrist-extensor-rotation-stretch', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/flexibility.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"8e166eae-5d0f-4661-9f9e-996f6859df36","name":"Wrist Extensor Rotation Stretch","slug":"wrist-extensor-rotation-stretch","primaryMuscles":["forearm - outer"],"secondaryMuscles":[],"steps":["Bend your hands at the wrists towards you. Place the back of your hands against a stable object like a bench or the floor with your body in a comfortable position that allows you to push down on your wrists.","Lean your body forwards to push the wrist into extension, staying within tolerable limits.","Rotate the elbows in and hold the stretch for up to 10 seconds.","Rotate the elbows out and hold the stretch for up to 10 seconds.","Continue alternating the movement on each side for the desired amount of time."],"notes":""}'),
('longhaul-fitness', '8e620f2a-f028-47c4-b86e-37d0dc0021cb', 'barbell-squat-landmine', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"8e620f2a-f028-47c4-b86e-37d0dc0021cb","name":"Squat – Landmine","slug":"squat-landmine","primaryMuscles":["glute","quad","thigh - inner"],"secondaryMuscles":["calf"],"steps":["Start by placing a barbell into a landmine attachment or securely anchor it into a corner.","Stand facing the barbell with your feet shoulder-width apart and your toes pointing slightly outward.","Grab the end of the barbell with both hands and lift it up to your chest.","Lower your hips down and back, keeping your chest up and your back straight.","Bend your knees and lower your body until your thighs are parallel to the ground.","Push through your heels and stand back up to the starting position.","Repeat."],"notes":""}'),
('longhaul-fitness', '8ed275bd-45a2-4d23-9f2a-ad19bd6f4328', 'dumbbell-front-raise', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"8ed275bd-45a2-4d23-9f2a-ad19bd6f4328","name":"Front Raise – Dumbbell","slug":"front-raise-dumbbell","primaryMuscles":["shoulder - front"],"secondaryMuscles":["shoulder - side"],"steps":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand with your palms facing your thighs.","Keeping your arms straight, lift the dumbbells in front of you until they reach shoulder height.","Hold the position for a second, then slowly lower the dumbbells back down to your thighs.","Repeat."],"notes":""}'),
('longhaul-fitness', '8f9fe1df-e342-4884-927e-070598eaed0b', 'dumbbell-lying-internal-shoulder-rotation', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"8f9fe1df-e342-4884-927e-070598eaed0b","name":"Lying Internal Shoulder Rotation – Dumbbell","slug":"lying-internal-shoulder-rotation-dumbbell","primaryMuscles":["rotator cuff - front"],"secondaryMuscles":[],"steps":["Lie on your side on a flat bench with your legs stacked, and your body straight as possible from head to toes.","Bend your lower arm (the one closest to the bench) at a 90-degree angle at your elbow, and grasp a dumbbell with a your palm facing the ceiling.","Rotate your shoulder while keeping your elbow at a 90-degree angle, moving your forearm towards the ceiling and inwards towards your body.","Rotate your arm upward as far as comfortably possible without lifting your elbow off the bench or your body moving off its position.","Pause at the top of the movement for a brief moment.","Slowly return the dumbbell to the starting position by rotating the forearm back to the bench while keeping the elbow angle constant.","Complete all the desired repetitions on one arm before switching to the other arm and repeating the steps."],"notes":"Keep your elbow tucked into your side and pinned to the bench throughout the exercise."}'),
('longhaul-fitness', '90d7e253-d5c6-4683-bb18-6c12a4fccef9', 'dumbbell-incline-curl', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"90d7e253-d5c6-4683-bb18-6c12a4fccef9","name":"Incline Curl – Dumbbell","slug":"incline-curl-dumbbell","primaryMuscles":["bicep"],"secondaryMuscles":["forearm - inner"],"steps":["Adjust the bench to a 45-degree angle.","Grab a pair of dumbbells and sit on the bench with your back straight.","Let your arms hang down by your sides with your palms facing forward.","Slowly curl the dumbbells up towards your shoulders while keeping your elbows close to your body.","Pause for a moment at the top of the movement, then slowly lower the dumbbells back down to the starting position.","Repeat."],"notes":""}'),
('longhaul-fitness', '90fb272a-1f4e-4a49-b7bf-e613e5570930', 'barbell-single-leg-romanian-deadlift-landmine', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"90fb272a-1f4e-4a49-b7bf-e613e5570930","name":"Single-Leg Romanian Deadlift – Landmine","slug":"single-leg-romanian-deadlift-landmine","primaryMuscles":["glute","hamstring"],"secondaryMuscles":["abdominal","calf","lower back","oblique","quad"],"steps":["Stand with your right side facing the end of a barbell secured in a landmine attachment, holding the bar with your right hand using a pronated (overhand) grip. The end of the barbell should be at arms-length in front of your quad. This is your starting position.","Shift your weight onto your left leg, keeping a slight bend in the knee of your standing leg.","Hinge at your hips and lean forward, extending your right leg straight back for balance.","Lower the barbell toward the floor while keeping your back straight and core engaged, ensuring your hips remain square.","Continue lowering until you feel a stretch in the hamstring of the standing leg or your upper body is nearly parallel to the floor.","Drive through the heel of the standing leg to return to the starting position, engaging your glutes as you stand.","Keep your gaze forward and chest lifted throughout the movement to maintain a flat back.","Repeat for the desired number of reps before switching to the opposite leg."],"notes":""}'),
('longhaul-fitness', '91ee79b7-397d-4b90-8988-9a41bff9d639', 'barbell-upright-row', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"91ee79b7-397d-4b90-8988-9a41bff9d639","name":"Upright Row – Barbell","slug":"upright-row-barbell","primaryMuscles":["shoulder - side"],"secondaryMuscles":["bicep","shoulder - front","trap"],"steps":["Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp the barbell with an overhand grip, hands narrower than shoulder-width apart.","Hold the barbell in front of your thighs with your arms extended.","Exhale and lift the barbell straight up towards your chin, keeping it close to your body.","Pause for a moment at the top of the movement, then inhale and slowly lower the barbell back down to the starting position.","Repeat."],"notes":""}'),
('longhaul-fitness', '9201b8ec-d8dc-461a-9069-3d3dfe1b4bfd', 'one-leg-seated-calf-release-lacrosse-ball', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/flexibility.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"9201b8ec-d8dc-461a-9069-3d3dfe1b4bfd","name":"One-Leg Seated Calf Release – Lacrosse Ball","slug":"one-leg-seated-calf-release-lacrosse-ball","primaryMuscles":["calf"],"secondaryMuscles":[],"steps":["Sit on a chair with both feet on the floor.","Lift your target leg and cross it over the other leg so that the target leg''s ankle is resting on your other knee.","Place a massage ball on the inner part of your shin bone.","Apply pressure with the ball within tolerable limits.","Start with the ball at the midpoint of your shin and move down towards the foot 1 inch at a time.","Slowly and repeatedly rotate the ankle to point your foot towards the floor, then the ceiling, then back again to get an active release of the muscle.","Complete 3-5 slow repetitions per tender spot.","Continue the massage for the desired amount of time."],"notes":""}'),
('longhaul-fitness', '9281ff5a-ec41-4366-ac71-bf6c126adb7c', 'kettlebell-one-leg-kneeling-bottoms-up-hold', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"9281ff5a-ec41-4366-ac71-bf6c126adb7c","name":"One-Leg Kneeling Bottoms-Up Hold – Kettlebell","slug":"one-leg-kneeling-bottoms-up-hold-kettlebell","primaryMuscles":["shoulder - front"],"secondaryMuscles":["rotator cuff - front"],"steps":["Hold a kettlebell in your left hand.","Kneel with your left knee and right foot on the ground.","Raise the kettlebell by the handle so that you''re balancing it upside-down.","Keep your elbow stacked directly below your wrist.","Flex your shoulder to 90 degrees and bend your elbow to 90 degrees.","Hold the kettlebell with your arm in this position for the desired amount of time.","Repeat the exercise on the other side from the same amount of time to complete a set."],"notes":""}'),
('longhaul-fitness', '92a2e3fc-e8f7-433e-b398-2eb37cbc06d8', 'barbell-biceps-curl', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"92a2e3fc-e8f7-433e-b398-2eb37cbc06d8","name":"Curl – Barbell","slug":"curl-barbell","primaryMuscles":["bicep"],"secondaryMuscles":["forearm - inner"],"steps":["Stand with your feet shoulder-width apart and your knees slightly bent.","Hold the barbell with an underhand grip, palms facing up, and your hands shoulder-width apart.","Keep your elbows close to your sides and curl the barbell up towards your chest, exhaling as you lift.","Pause at the top of the movement and squeeze your biceps.","Lower the barbell back down to the starting position, inhaling as you lower.","Repeat."],"notes":""}'),
('longhaul-fitness', '92e7386f-e062-4ac5-b318-0d1f2b9fdff4', 'dumbbell-z-press', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"92e7386f-e062-4ac5-b318-0d1f2b9fdff4","name":"Z Press – Dumbbell","slug":"z-press-dumbbell","primaryMuscles":["shoulder - front","shoulder - side"],"secondaryMuscles":["abdominal","lower back","shoulder - back","tricep"],"steps":["Sit down on the ground, legs extended in front of you and spaced apart for stability.","Hold a dumbbell in each hand at shoulder height, palms facing forward.","Plant your heels firmly on the ground and brace your core.","Press the dumbbells vertically overhead, fully extending your arms without locking your elbows.","Pause briefly at the top of the movement.","Lower the dumbbells back to the starting position at shoulder height in a controlled manner.","Repeat for the desired number of repetitions."],"notes":"Maintain core tension throughout the exercise to prevent arching your back or leaning back too far."}'),
('longhaul-fitness', '930d9fc3-52c0-4a87-aaee-923552ffbb94', 'dumbbell-push-press', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', 100.0, '{"pk":"930d9fc3-52c0-4a87-aaee-923552ffbb94","name":"Push Press – Dumbbell","slug":"push-press-dumbbell","primaryMuscles":["shoulder - front"],"secondaryMuscles":["abdominal","glute","lat","lower back","quad","trap","tricep"],"steps":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand at shoulder level with your palms facing your head.","Bend your knees slightly and dip your body down.","Quickly straighten your legs and use the momentum to push the dumbbells overhead.","Lock out your arms at the top of the movement.","Lower the dumbbells back down to shoulder level and repeat for desired number of reps."],"notes":""}'),
('longhaul-fitness', '934a015c-8515-4652-bb12-1e9e0ce3c1f1', 'dumbbell-alternating-tall-kneeling-arnold-press-hand-weights', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"934a015c-8515-4652-bb12-1e9e0ce3c1f1","name":"Alternating Tall Kneeling Arnold Press – Hand Weights","slug":"alternating-tall-kneeling-arnold-press-hand-weights","primaryMuscles":["shoulder - front","shoulder - side"],"secondaryMuscles":["abdominal","bicep","tricep"],"steps":["Choose a pair of appropriate weights: dumbbells, kettlebells, etc.","Kneel on the ground with both knees, keeping your back straight and core engaged.","Hold the dumbbells in front of you at shoulder height, elbows bent, and palms facing your face. This is your starting position.","Rotate one arm outward, so your palm faces forward, and press the dumbbell overhead.","Bring the dumbbell back to the starting position while simultaneously rotating the other arm and pressing the dumbbell overhead.","Continue alternating arms, pressing one dumbbell overhead at a time.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '93524891-f216-4dc0-8d87-2f32d655bd3d', 'barbell-front-rack-curtsy-lunge', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"93524891-f216-4dc0-8d87-2f32d655bd3d","name":"Front Rack Curtsy Lunge – Barbell","slug":"front-rack-curtsy-lunge-barbell","primaryMuscles":["glute","quad","thigh - inner","thigh - outer"],"secondaryMuscles":["calf","hamstring"],"steps":["Position a barbell on a squat rack at shoulder height.","Stand facing the barbell, step under it, and rest it across the front of your shoulders.","Step back from the rack with the barbell in the front rack position.","Stand with feet hip-width apart, head up, and chest high. This is your starting position.","Take a step back and to the side with your right foot, crossing it behind your left leg.","Lower your body into a lunge, keeping your front knee aligned over your front foot and your core engaged.","Push through your front heel to rise, bringing your right foot back to the starting position.","Repeat for the desired number of repetitions and switch to the other side."],"notes":""}'),
('longhaul-fitness', '95cb9f28-ab4d-40ec-8c17-fddf859538b9', 'one-leg-foot-plank-yoga-block', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/flexibility.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"95cb9f28-ab4d-40ec-8c17-fddf859538b9","name":"One-Leg Foot Plank – Yoga Block","slug":"one-leg-foot-plank-yoga-block","primaryMuscles":["calf"],"secondaryMuscles":[],"steps":["Place two yoga blocks on the floor and stand so one foot is supported on the blocks at the heel and toes.","Shift your weight onto the supported foot.","Allow the ball of your big toe to drop below the level of the yoga block.","Activate the muscles in your foot to lift the ball of your big toe back to a neutral position.","Hold the lifted position for 5 to 7 seconds.","Rest for the same amount of time.","Continue repetitions for the desired amount of time."],"notes":""}'),
('longhaul-fitness', '9788d2f4-c8be-4c08-868c-a3ae758d09de', 'barbell-one-handed-shoulder-press-landmine', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"9788d2f4-c8be-4c08-868c-a3ae758d09de","name":"One-Handed Shoulder Press – Landmine","slug":"one-handed-shoulder-press-landmine","primaryMuscles":["chest","shoulder - front","shoulder - side","tricep"],"secondaryMuscles":["abdominal","oblique","rotator cuff - back","rotator cuff - front","trap"],"steps":["Position a barbell securely in a landmine attachment or securely in a corner to prevent it from sliding.","Load the desired weight onto the free end of the barbell.","Stand facing the barbell with your feet shoulder-width apart for stability.","Bend slightly to grab the barbell with one hand directly where the barbell is loaded.","Raise the barbell to your shoulder level, switching your grip so that your hand is under the barbell and your palm faces your chin over a bent and tucked elbow. This is your starting position.","Brace your core, and exhale as you press the barbell upward and slightly forward by extending your arm.","Keep your body straight and avoid rotating your hips or shoulders during the press.","Inhale as you slowly return the barbell to the starting position at your shoulder.","Complete all reps on one side before switching hands to work the opposite side."],"notes":""}'),
('longhaul-fitness', '9807a1e2-f8fa-4167-b5af-5ed13d3ae61b', 'side-lying-clamshell', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"9807a1e2-f8fa-4167-b5af-5ed13d3ae61b","name":"Side-Lying Clamshell","slug":"side-lying-clamshell","primaryMuscles":["thigh - outer"],"secondaryMuscles":["glute"],"steps":["Lie on your side with your knees bent and your feet together.","Keep your feet touching and lift your top knee as high as you can without moving your pelvis.","Pause for a moment at the top of the movement, then slowly lower your knee back down.","Repeat the movement for the desired number of repetitions, then switch to the other side."],"notes":"Use a resistance band around your knees to increase the difficulty of the exercise."}'),
('longhaul-fitness', '98251de8-8e5c-408f-9a47-e959493aedd1', 'barbell-feet-up-bench-press', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"98251de8-8e5c-408f-9a47-e959493aedd1","name":"Feet-Up Bench Press – Barbell","slug":"feet-up-bench-press-barbell","primaryMuscles":["chest","shoulder - front"],"secondaryMuscles":["tricep"],"steps":["Lie flat on a bench with your feet up in the air, knees bent at a 90-degree angle.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Engage your core and press your lower back into the bench.","Unrack the barbell and hold it directly above your chest, arms fully extended.","Inhale and slowly lower the barbell towards your chest, keeping your elbows tucked in.","Pause for a brief moment when the barbell touches your chest.","Exhale and push the barbell back up to the starting position, fully extending your arms.","Repeat the movement for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '98a43391-4d1f-4de1-8036-c0787307c84e', 'one-leg-incline-reverse-pigeon-bench', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/flexibility.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"98a43391-4d1f-4de1-8036-c0787307c84e","name":"One-Leg Incline Reverse Pigeon – Bench","slug":"one-leg-incline-reverse-pigeon-bench","primaryMuscles":["glute","hamstring","thigh - inner"],"secondaryMuscles":["thigh - outer"],"steps":["Set up an exercise bench at a 30 to 45 degree incline.","Place the shin of the leg you want to stretch on the inclined bench with the knee elevated above the foot.","Position the other leg behind you to support your bodyweight.","Drop the hip of the leg on the bench towards the ground and use your hands to support your body.","Keep your spine neutral to focus the stretch on your hips.","Hinge forward at the hips while maintaining a neutral spine to deepen the stretch.","Hold the stretch for the desired time and switch to the other side."],"notes":""}'),
('longhaul-fitness', '992fea61-616b-4576-a341-024b3b5609f6', 'feet-elevated-bulgarian-row-ring', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"992fea61-616b-4576-a341-024b3b5609f6","name":"Feet-Elevated Bulgarian Row – Ring","slug":"feet-elevated-bulgarian-row-ring","primaryMuscles":["bicep","lat"],"secondaryMuscles":["forearm - inner","forearm - outer","shoulder - back","trap"],"steps":["Set the gymnastic rings to a suitable height, typically about waist height.","Place a bench or elevated surface in front of you. The top of the surface should be about an arms-length lower than the rings.","Hold onto the rings with an overhand grip and walk your feet forward to place them on the surface.","Hang from the rings with your arms straight, creating a straight line from your feet to your shoulders that is parallel with the floor. This is your starting position.","With your arms extended, pull yourself upwards by bending your elbows and drawing your chest towards the rings.","Squeeze your shoulder blades together at the top of the movement, keeping your body stable.","Slowly extend your arms to lower yourself back to the starting position.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '99bf5a59-6b83-410e-a4e1-0992c0aa6b8e', 'band-rebound-external-rotation', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"99bf5a59-6b83-410e-a4e1-0992c0aa6b8e","name":"Rebound External Rotation – Band","slug":"rebound-external-rotation-band","primaryMuscles":["rotator cuff - back"],"secondaryMuscles":["shoulder - back","shoulder - side"],"steps":["Anchor a resistance band in front of you at roughly head height.","Keep your elbow bent at a 90-degree angle and abducted to shoulder height.","Start with your forearm parallel to the floor.","Grip the free end of the band and take a step backwards to add tension to the band.","Pull the band by externally rotating your shoulder until your forearm is perpendicular to the floor (90 degrees external rotation). This is your starting position.","Let the band pull your hand internally by 5-10 degrees.","Externally rotate your shoulder once again to return to the starting position.","Repeat the movement for your desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '99f90af9-c3da-4afe-8988-57865cbb9b92', 'cable-tricep-pushdown', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"99f90af9-c3da-4afe-8988-57865cbb9b92","name":"Tricep Pushdown – Cable With Rope","slug":"tricep-pushdown-cable-with-rope","primaryMuscles":["tricep"],"secondaryMuscles":[],"steps":["Stand facing a cable machine with your feet shoulder-width apart and your knees slightly bent.","Attach a rope handle to the high pulley of the cable machine.","Grasp the rope with an overhand grip, palms facing each other.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Pull the rope towards the ground until your forearms are about parallel to the ground. This is your starting position.","Exhale and push the rope down until your arms are fully extended, while keeping your upper arms stationary.","Hold the contracted position for a brief pause, squeezing your triceps.","Inhale and slowly allow the rope to return to the starting position, while maintaining tension in your triceps.","Repeat for the desired number of repetitions."],"notes":"You can kneel in front of the cable machine, rather than stand, if the length of the cable and rope is too long for a full range of motion."}'),
('longhaul-fitness', '9a3d7102-c171-4532-8173-a34a3834493d', 'exercise-ball-dumbbell-pullover', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"9a3d7102-c171-4532-8173-a34a3834493d","name":"Stability Ball Pullover – Dumbbell","slug":"stability-ball-pullover-dumbbell","primaryMuscles":["chest","lat","tricep"],"secondaryMuscles":["abdominal","rotator cuff - back","rotator cuff - front"],"steps":["Select an appropriate weight dumbbell and a stability ball.","Sit on the stability ball and place the dumbbell on your lap.","Roll down the ball until your upper back and shoulders are supported by it, keeping your hips lifted, your body in a straight line, and your feet flat on the ground.","Hold the dumbbell over your chest with both hands, gripping one end of the dumbbell while the other end points towards your chest. This is your starting position.","Slowly lower the dumbbell in an arc behind your head, keeping your arms mostly straight, but slightly bent, throughout.","Stretch your arms back as far as comfortably possible while maintaining control of the weight.","Bring the dumbbell back up over your chest along the same arc.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '9a4c2b68-eb2b-456a-bb3a-dec25f870b23', 'cable-one-handed-standing-chest-fly', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"9a4c2b68-eb2b-456a-bb3a-dec25f870b23","name":"One-Handed Standing Chest Fly – Cable","slug":"one-handed-standing-chest-fly-cable","primaryMuscles":["chest","shoulder - front"],"secondaryMuscles":["abdominal","oblique","rotator cuff - front"],"steps":["Adjust the cable machine pulley to shoulder height and attach a single handle.","Stand with your side facing the cable machine and grab the handle with your nearest hand.","Step away from the machine to create tension on the cable, feet shoulder-width apart and knees slightly bent for stability.","Straighten your arm with a slight bend in the elbow, positioning it parallel to the floor.","Brace your core and keep your hips and shoulders squared forward. This is your starting position.","Pull the handle just across your sternum, allowing your chest muscles to fully contract while keeping your arm slightly bent.","Slowly return the handle to the starting position while controlling the resistance.","Complete the desired number of repetitions and then switch sides."],"notes":""}'),
('longhaul-fitness', '9a5dd7ca-59c0-4bc3-b865-0bdc51fb7a48', 'barbell-single-arm-thruster-landmine', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"9a5dd7ca-59c0-4bc3-b865-0bdc51fb7a48","name":"Single-Arm Thruster – Landmine","slug":"single-arm-thruster-landmine","primaryMuscles":["glute","quad","shoulder - front"],"secondaryMuscles":["abdominal","lat","oblique","tricep"],"steps":["Start by placing a barbell into a landmine attachment or securely anchor it into a corner.","Stand with feet shoulder-width apart, holding the unattached end of the barbell with one hand at shoulder height. This is your starting position.","Perform a squat by pushing your hips back, keeping your chest up, and bending your knees until your thighs are parallel to the floor.","Explode upward from the squat position, using leg drive to assist in pressing the barbell overhead.","Extend your arm fully overhead while keeping the opposite arm by your side for balance.","Slowly lower the barbell back to shoulder height, controlling the descent, returning to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."],"notes":""}'),
('longhaul-fitness', '9b3a5a87-3555-47d9-8eca-64f9ee819c4b', 'machine-reverse-fly', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"9b3a5a87-3555-47d9-8eca-64f9ee819c4b","name":"Reverse Fly – Machine","slug":"reverse-fly-machine","primaryMuscles":["rotator cuff - back","shoulder - back"],"secondaryMuscles":["trap"],"steps":["Adjust the seat height and chest pad of the machine to your comfort level.","Sit on the machine with your chest against the pad and grasp the handles with an overhand grip.","Keep your back straight and engage your core muscles.","Exhale and slowly pull the handles back and away from your body, squeezing your shoulder blades together.","Pause for a moment at the fully contracted position.","Inhale and slowly return the handles to the starting position, maintaining control throughout the movement.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '9b629ff7-e212-413d-b44c-bc2a5e4979c1', 'machine-biceps-curl', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"9b629ff7-e212-413d-b44c-bc2a5e4979c1","name":"Curl – Machine","slug":"curl-machine","primaryMuscles":["bicep"],"secondaryMuscles":["forearm - inner"],"steps":["Adjust the seat height and position yourself comfortably on the machine.","Grasp the handles with an underhand grip, palms facing up.","Keep your back straight and your elbows close to your sides.","Exhale and slowly curl the handles towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the handles back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '9b8d159f-a4a0-4c33-b5bd-b62390b092cc', 'kneeling-side-plank', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"9b8d159f-a4a0-4c33-b5bd-b62390b092cc","name":"Kneeling Side Plank","slug":"kneeling-side-plank","primaryMuscles":["oblique"],"secondaryMuscles":["abdominal"],"steps":["From a kneeling position on the ground, lean to the right until your right hand or elbow make contact with the ground directly under your right shoulder.","Your body should form a straight line from your left shoulder (pointing towards the ceiling) to your left knee that stacked on top of the right knee.","Hold this position, engaging your core, for the desired time.","Raise back up to a kneeling position and repeat on the other side."],"notes":""}'),
('longhaul-fitness', '9d2940c4-6fcc-49ee-b5f6-9d10d90c30aa', 'nordic-hamstring-curl', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', 88.0, '{"pk":"9d2940c4-6fcc-49ee-b5f6-9d10d90c30aa","name":"Nordic Hamstring Curl","slug":"nordic-hamstring-curl","primaryMuscles":["hamstring"],"secondaryMuscles":["calf","glute","lower back"],"steps":["Kneel on a padded surface, with your body upright and legs bent at a 90-degree angle at the knees.","Secure your lower legs or ankles under a sturdy object, or have a partner hold them down.","Cross your arms over your chest or place your hands on your thighs.","Engage your core and glutes to keep your body straight from your knees to your head.","Slowly lower your upper body towards the ground by extending your knees, keeping your torso straight.","Descend as far as you can control, ideally until your body is nearly parallel to the floor.","Use your hamstrings to pull your body back up to the starting position."],"notes":""}'),
('longhaul-fitness', '9d9ac1be-4ef9-43e8-a5a5-d6a4d1e6b5de', 'bicycle-crunch-2', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', 100.0, '{"pk":"9d9ac1be-4ef9-43e8-a5a5-d6a4d1e6b5de","name":"Bicycle Crunch","slug":"bicycle-crunch","primaryMuscles":["abdominal","oblique"],"secondaryMuscles":[],"steps":["Lie flat on your back with your hands behind your head and your knees bent.","Bring your right elbow towards your left knee while simultaneously straightening your right leg.","Return to the starting position and repeat the movement on the opposite side, bringing your left elbow towards your right knee while straightening your left leg.","Continue alternating sides in a pedaling motion, keeping your core engaged and your lower back pressed into the floor.","Complete the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '9dad56f9-08a4-4631-845a-d0b7c58fbece', 'meadows-row', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', 100.0, '{"pk":"9dad56f9-08a4-4631-845a-d0b7c58fbece","name":"Meadows Row","slug":"meadows-row","primaryMuscles":["lat","trap","shoulder - back"],"secondaryMuscles":["lower back","rotator cuff - back"],"steps":["Place one end of a barbell in a corner to secure it, or use a landmine attachment if available.","Stand next to the barbell so it is to your side, with your feet shoulder-width apart.","Bend your knees slightly and hinge at the hips to lean forward, keeping your back straight.","Grasp the barbell with one hand using an overhand grip, just above the weight plates.","Place your other hand on your thigh or knee for support.","Brace your core and row the barbell towards your armpit, keeping your elbow tucked in.","Squeeze your back muscles at the top of the movement.","Slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions before switching sides."],"notes":""}'),
('longhaul-fitness', '9dcaa104-06fe-4d18-88ea-ecadcda7b4c1', 'snatch', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"9dcaa104-06fe-4d18-88ea-ecadcda7b4c1","name":"Snatch","slug":"snatch","primaryMuscles":["glute","lower back","quad","thigh - inner"],"secondaryMuscles":["calf","forearm - inner","hamstring","trap"],"steps":["Start with feet shoulder-width apart and toes pointing slightly outward.","Place hands on the barbell with a wide grip, palms facing down.","Lower your hips and bend your knees, keeping your back straight.","Drive through your legs and hips, pulling the barbell up to your chest.","As the barbell reaches chest height, quickly extend your arms and legs, pulling the barbell up and overhead.","Lock out your arms and stand up straight, holding the barbell overhead.","Lower the barbell back down to the starting position by reversing the movement.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '9e2af81e-141f-44c9-8115-3370c66d14d1', 'halo-neck-rotation', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/flexibility.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"9e2af81e-141f-44c9-8115-3370c66d14d1","name":"Halo Neck Rotation","slug":"halo-neck-rotation","primaryMuscles":["trap"],"secondaryMuscles":[],"steps":["Stand or sit with your back straight and shoulders relaxed.","Keep your head looking straight forward.","Slowly move your neck to draw a halo with the tip of your head, moving it in a circular motion.","You can start by moving your head in a counter-clockwise direction, then switch to clockwise.","Continue the movement for the desired amount of time, ensuring you maintain the forward gaze throughout."],"notes":""}'),
('longhaul-fitness', '9e5d1c13-5383-4dce-a250-909d6c7c3633', 'farmers-walk', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"9e5d1c13-5383-4dce-a250-909d6c7c3633","name":"Farmers Walk","slug":"farmers-walk","primaryMuscles":["forearm - inner","glute","oblique","trap"],"secondaryMuscles":["abdominal","calf","lower back","quad","shoulder - side"],"steps":["Stand with your feet shoulder-width apart and your core engaged.","Pick up a heavy weight in each hand, such as dumbbells or kettlebells.","Keep your shoulders down and your chest up as you walk forward, taking small, quick steps.","Make sure to keep your back straight and avoid leaning forward or backward.","Continue walking for a set distance or time, then carefully set the weights down."],"notes":""}'),
('longhaul-fitness', '9ec287f0-bb82-4cd6-bae6-fec86b3094e7', 'pec-deck', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'exact', 100.0, '{"pk":"9ec287f0-bb82-4cd6-bae6-fec86b3094e7","name":"Pec Deck","slug":"pec-deck","primaryMuscles":["chest"],"secondaryMuscles":["shoulder - front"],"steps":["Sit on the Pec Deck machine with your back flat against the backrest and your feet firmly on the floor.","Adjust the seat height so that the handles are at chest level.","Grasp the handles with an overhand grip, keeping your elbows slightly bent.","Exhale and push the handles together in front of your chest, squeezing your chest muscles.","Hold the contraction for a second, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', '9f3951d0-23e5-45c6-8ccb-2951d0f9ddce', 'monkey-row', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"9f3951d0-23e5-45c6-8ccb-2951d0f9ddce","name":"Monkey Row","slug":"monkey-row","primaryMuscles":["shoulder - side"],"secondaryMuscles":["bicep","shoulder - front","trap"],"steps":["Start in a standing position with your feet shoulder-width apart and your knees slightly bent.","Hold a dumbbell in each hand with your palms facing each other and your arms extended by your sides.","Bend your elbows and pull the dumbbells up towards your armpits, keeping your elbows close to your body.","Pause at the top of the movement and squeeze your shoulder blades together.","Lower the dumbbells back down to the starting position.","Repeat."],"notes":""}'),
('longhaul-fitness', '9fb879e4-df56-4601-b65a-b7d99c87c994', 'kneeling-ab-wheel-roll-out', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"9fb879e4-df56-4601-b65a-b7d99c87c994","name":"Kneeling Ab Wheel Roll-Out","slug":"kneeling-ab-wheel-roll-out","primaryMuscles":["abdominal"],"secondaryMuscles":["oblique"],"steps":["Kneel on the floor with an ab wheel in front of you.","Place your hands on the ab wheel handles, shoulder-width apart.","Engage your core and slowly roll the ab wheel forward, keeping your arms straight and your back flat.","Continue rolling out until your body is fully extended and your arms are overhead.","Pause for a moment, then slowly roll the ab wheel back towards your knees.","Repeat."],"notes":""}'),
('longhaul-fitness', 'a00f925a-5af9-4d79-a054-9cc42256a83f', 'split-jerk', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"a00f925a-5af9-4d79-a054-9cc42256a83f","name":"Split Jerk","slug":"split-jerk","primaryMuscles":["shoulder - front"],"secondaryMuscles":["glute","lower back","quad","shoulder - side","thigh - inner","trap","tricep"],"steps":["Start with the barbell resting on your shoulders, hands slightly wider than shoulder-width apart.","Bend your knees and lower your body into a partial squat, keeping your back straight and core engaged.","Drive through your legs and explosively push the barbell overhead, extending your arms fully.","As the barbell reaches its peak, quickly split your legs, with one foot moving forward and the other moving backward into a high lunge position.","Stabilize your body and hold the split position for a moment.","Stand back up by bringing your front and back feet back to the position where they started.","Lower the barbell back to your shoulders and repeat the movement for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', 'a02747d9-7ee8-41d5-aade-d3c7c8556c3a', 'barbell-rear-delt-row', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"a02747d9-7ee8-41d5-aade-d3c7c8556c3a","name":"Rear Delt Row – Barbell","slug":"rear-delt-row-barbell","primaryMuscles":["shoulder - back","trap"],"secondaryMuscles":["forearm - inner","rotator cuff - back","shoulder - side","lat"],"steps":["Stand with your feet shoulder-width apart and your knees slightly bent.","Hold a barbell with an overhand grip, hands shoulder-width apart.","Lean forward at the hips, keeping your back straight and your abs engaged.","Bring the barbell up towards your upper chest, keeping your elbows wide and out to the sides.","Squeeze your shoulder blades together at the top of the movement.","Lower the barbell back down to the starting position.","Repeat."],"notes":""}'),
('longhaul-fitness', 'a06410b6-c871-45c0-aee5-db6df750f494', 'bosu-plank', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', 100.0, '{"pk":"a06410b6-c871-45c0-aee5-db6df750f494","name":"Plank - BOSU","slug":"plank-bosu","primaryMuscles":["abdominal","lower back"],"secondaryMuscles":["oblique","shoulder - front"],"steps":["Place a BOSU ball on the ground with the flat side facing up.","Assume a plank position with your forearms on the BOSU ball and your toes on the ground.","Engage your core and keep your body in a straight line from head to heels.","Hold the position for the desired amount of time.","Release the position by lowering your knees to the ground."],"notes":"Instead of placing your forearms on the flat side of the BOSU, you can grab the edges with both hands and plank from a straight-armed position."}'),
('longhaul-fitness', 'a12409b6-5e95-47ae-a83a-3f3ed439aaff', 'band-hip-thrust', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"a12409b6-5e95-47ae-a83a-3f3ed439aaff","name":"Hip Thrust – Band","slug":"hip-thrust-band","primaryMuscles":["glute"],"secondaryMuscles":["hamstring","thigh - inner"],"steps":["Place a resistance band below your knees.","Sit on the ground with your back against a bench, your feet flat on the ground, and position a barbell across your hips.","Engage your core and glute muscles, and slowly lift your hips up off the ground until your body forms a straight line from your knees to your shoulders.","Hold for a second or two at the top of the movement, then lower your hips back down to the ground.","Repeat."],"notes":""}'),
('longhaul-fitness', 'a189b026-3641-426f-b9a2-d32678ccb99f', 'straight-arm-lat-pulldown', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', 89.8, '{"pk":"a189b026-3641-426f-b9a2-d32678ccb99f","name":"Straight Arm Lat Pulldown","slug":"straight-arm-lat-pulldown","primaryMuscles":["lat"],"secondaryMuscles":["rotator cuff - back","rotator cuff - front","shoulder - back"],"steps":["Adjust the cable machine to a high position and attach a straight bar to the cable.","Stand facing the machine with your feet shoulder-width apart and your knees slightly bent.","Grasp the bar with both hands using an overhand grip, with your hands slightly wider than shoulder-width apart.","Engage your core and keep your arms straight as you pull the bar down towards your thighs, using your lats to initiate the movement.","Pause for a moment at the bottom of the movement, then slowly release the bar back up to the starting position.","Repeat."],"notes":""}'),
('longhaul-fitness', 'a26e9750-8c80-48e1-be34-e552123bf18f', 'dumbbell-lying-external-shoulder-rotation', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"a26e9750-8c80-48e1-be34-e552123bf18f","name":"Lying External Shoulder Rotation – Dumbbell","slug":"lying-external-shoulder-rotation-dumbbell","primaryMuscles":["rotator cuff - back"],"secondaryMuscles":[],"steps":["Lie on your side on a flat bench with your legs stacked, and your body straight as possible from head to toes.","Bend your upper arm (the one farthest from the bench) at a 90-degree angle at your elbow with your forearm parallel to the floor, and grasp a dumbbell with a your palm facing the floor.","Rotate your shoulder while keeping your elbow at a 90-degree angle, moving your forearm towards the ceiling and above your body.","Rotate your arm upward as far as comfortably possible without lifting your elbow off your torso or your body moving off its position.","Pause at the top of the movement for a brief moment.","Slowly return the dumbbell to the starting position by rotating the forearm back to the horizontal starting position while keeping the elbow angle constant.","Complete all the desired repetitions on one arm before switching to the other arm and repeating the steps."],"notes":"Keep your elbow pinned to your torso throughout the exercise."}'),
('longhaul-fitness', 'a2ee6995-f130-4005-9335-80a210060677', 'dumbbell-skullcrusher', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"a2ee6995-f130-4005-9335-80a210060677","name":"Skull Crusher – Dumbbell","slug":"skull-crusher-dumbbell","primaryMuscles":["tricep"],"secondaryMuscles":[],"steps":["Lie on a bench with your knees bent and feet flat on the ground. Hold a dumbbell in each hand directly above your shoulders with your arms fully extended.","With your palms facing each other, engage your core and keep your wrists straight.","Slowly bend your elbows to lower the dumbbells towards the sides of your forehead. Keep your upper arms stationary and elbows pointing straight up throughout the movement.","Lower the weights until your forearms and biceps are at least at a 90-degree angle.","Pause briefly at the bottom of the movement.","Press the dumbbells back up to the starting position by extending your elbows while exhaling. Focus on using your triceps to move the weight.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', 'a3b737e2-d859-4e69-b52c-efc572c58a9a', 'quadruped-hip-extension', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"a3b737e2-d859-4e69-b52c-efc572c58a9a","name":"Quadruped Hip Extension","slug":"quadruped-hip-extension","primaryMuscles":["glute","hamstring"],"secondaryMuscles":["lower back","abdominal"],"steps":["Begin on your hands and knees in the quadruped position with hands under shoulders and knees under hips.","Engage your core and maintain a neutral spine throughout the exercise. This is your starting position.","Maintaining a bent knee, squeeze your glute and extend one foot towards the ceiling. Imagine placing your foot flat on the ceiling.","Squeeze your glutes at the top of the movement.","Lower the leg back to the starting position without touching the ground.","Perform the desired repetitions on one side before switching to the other leg."],"notes":"Placing a band around both knees is a good way to add resistance to this exercise."}'),
('longhaul-fitness', 'a3d128e0-85d3-4f1e-b543-e3fcd9c2e1b8', 'hanging-knee-raise', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"a3d128e0-85d3-4f1e-b543-e3fcd9c2e1b8","name":"Hanging Knee Raise","slug":"hanging-knee-raise","primaryMuscles":["abdominal","forearm - inner","forearm - outer"],"secondaryMuscles":["oblique"],"steps":["Hang from a pull-up bar with both hands using an overhand grip.","Keep your arms and legs straight with feet off the ground.","Stabilize your torso by engaging your core and slightly retracting your shoulders.","While exhaling, slowly raise your knees toward your chest. Imagine bringing your knees to your nipples.","Pause momentarily when your thighs reach your chest.","Inhale as you lower your legs back down, slowly and controlled, to the starting position."],"notes":"There are hanging knee raise machines that allow you to balance on your forearms rather than hang from a bar. Also, you could perform this exercise by holding yourself up on dip bars. Consider using either machine if you want to remove most of the forearm activation and focus on the abdominal work."}'),
('longhaul-fitness', 'a40205d6-396c-4c0b-a4b9-8ffbef49ed32', 'barbell-t-bar-row', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"a40205d6-396c-4c0b-a4b9-8ffbef49ed32","name":"Row – T-Bar","slug":"row-t-bar","primaryMuscles":["lat","shoulder - back","trap"],"secondaryMuscles":["bicep","forearm - inner","lower back","rotator cuff - back","rotator cuff - front"],"steps":["Load the desired weight onto the T-Bar machine.","Lie down on the T-Bar machine with your feet securely planted.","Grasp the handles of the T-Bar with an overhand grip.","Pull the T-Bar towards your chest, keeping your elbows close to your body.","Pause briefly at the top of the movement, squeezing your shoulder blades together.","Slowly lower the T-Bar back to the starting position.","Repeat."],"notes":""}'),
('longhaul-fitness', 'a45c44a3-693e-4c60-b2db-b5a13f1f677c', 'one-leg-lying-ankle-nerve-floss', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/flexibility.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"a45c44a3-693e-4c60-b2db-b5a13f1f677c","name":"One-Leg Lying Ankle Nerve Floss","slug":"one-leg-lying-ankle-nerve-floss","primaryMuscles":["calf","hamstring"],"secondaryMuscles":["glute"],"steps":["Lie on your back on a padded surface with one thigh lifted to 90 degrees and supported by both both hands interlaced on the hamstring.","Keep the raised knee as straight as possible without causing nerve tension.","Keep the other leg straight and flat on the floor.","Simultaneously lift your head off the ground and at your chest while pointing your toes away from you (plantarflex).","Then, lower your head and look towards the ceiling while pulling your raised foot toward you (dorsiflex).","Repeat the movement for the desired number of repetitions then switch sides."],"notes":""}'),
('longhaul-fitness', 'a46155b5-3912-47c7-82ff-fe7fabd7b76c', 'dumbbell-forearm-twist', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"a46155b5-3912-47c7-82ff-fe7fabd7b76c","name":"Forearm Twist – Dumbbell","slug":"forearm-twist-dumbbell","primaryMuscles":["forearm - inner","forearm - outer"],"secondaryMuscles":["bicep"],"steps":["Stand up straight with your feet shoulder-width apart.","Hold a dumbbell in each hand and let your arms hang down in front of your quads, palms facing forward, with a slight bend in the elbows.","Curl the dumbbells upwards by bending your elbows, stopping when your forearms are parallel to the ground. This is the starting position.","While keeping your upper arms stationary, rotate your wrists to flip the dumbbells towards each other until your palms face down.","Pause for a moment, then rotate your wrists in the opposite direction, turning the dumbbells back to the starting position.","Repeat the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', 'a48140ad-b181-4f83-9883-5456bd26ee9a', 'band-pull-apart', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"a48140ad-b181-4f83-9883-5456bd26ee9a","name":"Pull-Apart – Band","slug":"pull-apart-band","primaryMuscles":["rotator cuff - back","shoulder - back"],"secondaryMuscles":["rotator cuff - front"],"steps":["Stand with feet shoulder-width apart and hold a resistance band with both hands.","Extend your arms straight out in front of you, keeping your palms facing down.","Begin pulling the band apart by squeezing your shoulder blades together.","Continue pulling until your hands are at shoulder height and the band is stretched tight.","Hold for a moment, then slowly release the tension and return to the starting position.","Repeat."],"notes":""}'),
('longhaul-fitness', 'a4ae2bd4-ba14-4187-81eb-7b8a5bf8b764', 'cable-lateral-raise-single-arm', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"a4ae2bd4-ba14-4187-81eb-7b8a5bf8b764","name":"One-Handed Lateral Raise – Cable","slug":"one-handed-lateral-raise-cable","primaryMuscles":["shoulder - side"],"secondaryMuscles":["shoulder - front"],"steps":["Stand upright with your feet shoulder-width apart and your knees slightly bent.","Hold the cable handle in one hand with an overhand grip.","Keep your arm straight and your palm facing down.","Engage your core and maintain a neutral spine.","Exhale and slowly lift your arm out to the side until it reaches shoulder level.","Pause for a moment and squeeze your shoulder muscles.","Inhale and slowly lower your arm back down to the starting position.","Repeat for the desired number of repetitions.","Switch sides and perform the exercise with the other arm."],"notes":""}'),
('longhaul-fitness', 'a63f2b45-f72d-4c47-967e-4388a89b276a', 'seated-snatch-grip-behind-neck-press', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"a63f2b45-f72d-4c47-967e-4388a89b276a","name":"Seated Snatch Grip Behind the Neck Press","slug":"seated-snatch-grip-behind-the-neck-press","primaryMuscles":["shoulder - front","shoulder - side"],"secondaryMuscles":["trap","tricep"],"steps":["Start by sitting on a bench with a backrest, next to a racked, weighted barbell.","Grip the barbell with a wide snatch grip.","Position the barbell behind your neck, resting it on your upper traps.","Engage your core and keep your back straight.","Press the barbell overhead by extending your arms and pushing the weight up.","Lock out your elbows at the top of the movement.","Lower the barbell back down to the starting position behind your neck.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', 'a6dae002-fc42-44eb-bf62-43c2d91e5f2c', 'sled-push', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'exact', 100.0, '{"pk":"a6dae002-fc42-44eb-bf62-43c2d91e5f2c","name":"Sled Push","slug":"sled-push","primaryMuscles":["calf","glute","hamstring","quad"],"secondaryMuscles":["chest","shoulder - front","tricep"],"steps":["Position yourself behind the sled with your feet shoulder-width apart.","Place your hands on the handles of the sled, gripping them firmly.","Engage your core and drive through your legs to push the sled forward.","Maintain a straight back and keep your head up as you push the sled.","Continue pushing the sled for the desired steps, distance, or time.","Once finished, release the handles and step away from the sled."],"notes":""}'),
('longhaul-fitness', 'a7fc1047-4296-4122-93fa-9f1d5ddfb2a0', 'shallow-lunge-bodyweight', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"a7fc1047-4296-4122-93fa-9f1d5ddfb2a0","name":"Shallow Lunge – Bodyweight","slug":"shallow-lunge-bodyweight","primaryMuscles":["glute","quad","thigh - inner"],"secondaryMuscles":["hamstring"],"steps":["Stand with your feet shoulder-width apart and your hands on your hips.","Step forward with one leg, bending your knee until your thigh is parallel to the ground.","Keep your back straight and your core engaged.","Push through your front heel to return to the starting position.","Repeat with the other leg."],"notes":"Remember to keep the lunge shallow. Your back knee should stay several inches above the ground. This exercise is an easier version of the Body Weight Lunge."}'),
('longhaul-fitness', 'a837f634-8aca-48b6-800e-2cc82f1335dd', 'incline-push-up', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"a837f634-8aca-48b6-800e-2cc82f1335dd","name":"Incline Push-Up","slug":"incline-push-up","primaryMuscles":["chest","shoulder - front","tricep"],"secondaryMuscles":["abdominal"],"steps":["Start in a plank position with your hands on an elevated surface, such as a bench or step.","Place your hands slightly wider than shoulder-width apart and keep your fingers pointing forward.","Engage your core and glutes to maintain a straight line from your head to your heels.","Lower your chest towards the bench, keeping your elbows close to your body.","Pause when your chest is just above the bench.","Push back up to the starting position, fully extending your arms.","Repeat."],"notes":""}'),
('longhaul-fitness', 'a9adb61b-6dd1-4beb-b90c-be1ee60adc1f', 'pallof-press', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'exact', 100.0, '{"pk":"a9adb61b-6dd1-4beb-b90c-be1ee60adc1f","name":"Pallof Press","slug":"pallof-press","primaryMuscles":["abdominal","oblique"],"secondaryMuscles":["lower back","rotator cuff - back","rotator cuff - front","shoulder - front","shoulder - side"],"steps":["Stand side-on to a cable machine or secure a resistance band at chest height.","Select an appropriate weight if using a cable machine.","Grasp the handle (or end of the band) with both hands and take a step away to create tension.","Position your feet shoulder-width apart for stability.","Hold the handle or band close to your chest, keeping your hands centered in front of you.","Engage your core muscles to stabilize your torso.","Slowly press the handle or band straight out in front of your chest, keeping your arms straight.","Ensure your hips and shoulders stay squared and facing forward throughout the movement.","Hold the fully-pressed position for 1-2 seconds.","Slowly return the handle or band back to your chest with control.","Repeat for the desired number of repetitions.","Switch sides and perform the exercise to work the core muscles evenly."],"notes":""}'),
('longhaul-fitness', 'aab77e3c-32ac-4676-92f3-bc5a0589891b', 'foam-roller-one-leg-seated-hamstring-roll', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/flexibility.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"aab77e3c-32ac-4676-92f3-bc5a0589891b","name":"One-Leg Seated Hamstring Roll – Foam Roller","slug":"one-leg-seated-hamstring-roll-foam-roller","primaryMuscles":["hamstring"],"secondaryMuscles":[],"steps":["Sit on the floor and place a foam roller under one hamstring while placing the other leg''s foot flat on the ground for stability.","Lean forward slightly to engage and stretch your hamstring.","Roll your leg back and forth on the foam roller to find tender spots.","When you find a tender spot, hold the position.","Hold the stretch for the desired time, then move to another spot or switch legs."],"notes":""}'),
('longhaul-fitness', 'aacfe3df-63af-4a27-9ade-80907bd89e31', 'gripper', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"aacfe3df-63af-4a27-9ade-80907bd89e31","name":"Gripper","slug":"gripper","primaryMuscles":["forearm - inner"],"secondaryMuscles":[],"steps":["Adjust the gripper machine to the desired resistance level.","Hold the gripper in one hand with a firm grip, making sure your fingers are comfortably positioned on the handles.","Keep your wrist and forearm in a neutral position to avoid unnecessary strain.","Start by squeezing the handles together using your hand strength.","Continue to squeeze the handles as forcefully as you can, engaging your grip muscles.","Hold the maximum contraction for a few seconds to fully activate your muscles.","Slowly release the tension and allow the handles to return to the starting position.","Repeat the squeezing and releasing motion for the desired number of repetitions.","Switch to the other hand and repeat the exercise to work both hands equally."],"notes":""}'),
('longhaul-fitness', 'ab0da03b-dd54-4a7f-bb06-40c866dfa88c', 'one-legged-glute-bridge', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', 100.0, '{"pk":"ab0da03b-dd54-4a7f-bb06-40c866dfa88c","name":"One-Legged Glute Bridge","slug":"one-legged-glute-bridge","primaryMuscles":["glute","hamstring"],"secondaryMuscles":["thigh - inner"],"steps":["Start by lying on your back with your knees bent and feet flat on the ground.","Lift your right leg off the ground and extend it straight up towards the ceiling.","Press your left foot into the ground and lift your hips up towards the ceiling.","Pause at the top of the movement and squeeze your glutes.","Lower your hips back down to the ground and repeat for the desired number of reps.","Switch legs and repeat the exercise on the other side."],"notes":"For increased difficult, hold your leg parallel with your torso instead of extending your leg to the ceiling."}'),
('longhaul-fitness', 'abf570d0-c26e-4865-a2d6-4b40c332b82c', 'side-plank-2', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', 100.0, '{"pk":"abf570d0-c26e-4865-a2d6-4b40c332b82c","name":"Side Plank","slug":"side-plank","primaryMuscles":["oblique"],"secondaryMuscles":["abdominal"],"steps":["Start by lying on your side with your legs extended and stacked on top of each other.","Place your forearm on the ground directly below your shoulder, with your elbow bent at a 90-degree angle.","Engage your core muscles and lift your hips off the ground, creating a straight line from your head to your feet.","Keep your body in a straight line and avoid sagging or letting your hips drop.","Hold the position for the desired amount of time.","Repeat on the other side."],"notes":""}'),
('longhaul-fitness', 'ae722011-8bc7-4714-8465-0f3969482e52', 'dumbbell-horizontal-external-shoulder-rotation', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"ae722011-8bc7-4714-8465-0f3969482e52","name":"Horizontal External Shoulder Rotation – Dumbbell","slug":"horizontal-external-shoulder-rotation-dumbbell","primaryMuscles":["rotator cuff - back"],"secondaryMuscles":[],"steps":["Stand perpendicular to a bar set at a height just below shoulder level when standing.","Grip a dumbbell with your working hand, maintaining the 90-degree angle at the elbow.","Place the upper arm of your working side on the bar so that it is parallel to the ground and your elbow is bent at a 90-degree angle. Your forearm with dumbbell should be hanging vertically towards the floor.","Brace your core and keep your shoulder blades down and back to prevent them from rolling forward during the exercise.","Rotate your arm at the shoulder, lifting the dumbbell upwards while keeping your upper arm and elbow firmly in place on the bar.","Continue the rotation until your forearm is horizontal to the floor or as far as your shoulder flexibility allows without discomfort or compromising form.","Pause at the top of the movement, focusing on contracting the muscles around the shoulder.","Slowly reverse the motion, lowering the dumbbell back to the starting position with control to complete one repetition.","Perform the desired number of reps, then switch sides and repeat the exercise with the other arm."],"notes":""}'),
('longhaul-fitness', 'af12bb86-3b46-4e79-bd31-71f74b81ded1', 'machine-standing-glute-kickback', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', 100.0, '{"pk":"af12bb86-3b46-4e79-bd31-71f74b81ded1","name":"Standing Glute Kickback – Machine","slug":"standing-glute-kickback-machine","primaryMuscles":["glute"],"secondaryMuscles":["hamstring","thigh - inner"],"steps":["Adjust the machine to the appropriate height for your body.","Stand facing the machine with your feet shoulder-width apart and your hands holding onto the handles.","Engage your glutes and lift one leg straight back behind you, keeping it in line with your body.","Pause at the top of the movement and squeeze your glutes.","Lower your leg back down to the starting position and repeat on the other side.","Complete the desired number of repetitions on each leg."],"notes":""}'),
('longhaul-fitness', 'af240c84-074c-4992-9448-2fd9f1b09400', 'dumbbell-pullover', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"af240c84-074c-4992-9448-2fd9f1b09400","name":"Pullover – Dumbbell","slug":"pullover-dumbbell","primaryMuscles":["chest","lat","tricep"],"secondaryMuscles":["rotator cuff - back","rotator cuff - front"],"steps":["Lie on a bench with your head and shoulders supported, and your feet flat on the floor.","Hold a dumbbell with both hands, palms pressing against the underside of one of the sides of the dumbbell. Push the dumbbell towards the sky above your chest. This is your starting position.","Keep a slight bend in your elbows and lock your arms in this slightly bent position throughout the entire movement.","Inhale and slowly lower the dumbbell in an arc behind your head while keeping your arms straight, moving primarily at the shoulder joints.","Lower the dumbbell until your arms are parallel to the floor or until you feel a stretch in your chest or lats, whichever comes first.","Exhale as you reverse the motion, bringing the dumbbell back over your chest in the same arc motion.","Repeat for the desired number of reps."],"notes":""}'),
('longhaul-fitness', 'af7ac4f1-0a7f-43cb-a4c9-33277fbff4ab', 'dumbbell-one-handed-chest-press', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"af7ac4f1-0a7f-43cb-a4c9-33277fbff4ab","name":"One-Handed Chest Press – Dumbbell","slug":"one-handed-chest-press-dumbbell","primaryMuscles":["chest"],"secondaryMuscles":[],"steps":["Start by lying flat on a bench with your feet firmly planted on the ground.","Hold a dumbbell in one hand, with your palm facing towards your feet.","Extend your arm straight up towards the ceiling, keeping your elbow slightly bent.","Inhale and slowly lower the dumbbell towards your chest, keeping your elbow at a 90-degree angle.","Exhale and push the dumbbell back up to the starting position, fully extending your arm.","Repeat for the desired number of repetitions, then switch to the other hand."],"notes":""}'),
('longhaul-fitness', 'b0be817d-8ef3-48f0-9485-b81d765fa31b', 'single-leg-tuck-up', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"b0be817d-8ef3-48f0-9485-b81d765fa31b","name":"Single-Leg Tuck-Up","slug":"single-leg-tuck-up","primaryMuscles":["abdominal","oblique"],"secondaryMuscles":[],"steps":["Start by lying flat on the floor with your arms extended overhead and your legs straight. This is your starting position.","Simultaneously lift one knee towards your chest while crunching upwards, bringing your arms forward to reach past the raised knee towards the foot.","Hold the crunch position briefly, ensuring your core is engaged and your hands are reaching towards the lifting foot.","Slowly lower your arms, upper body, and leg back to the starting position.","Repeat the movement with the opposite leg and alternate sides for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', 'b0f5eb25-3d65-42fe-b7e4-ba104698bcd9', 'chin-up-2', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', 100.0, '{"pk":"b0f5eb25-3d65-42fe-b7e4-ba104698bcd9","name":"Chin-Up","slug":"chin-up","primaryMuscles":["lat"],"secondaryMuscles":["bicep","forearm - inner","rotator cuff - back","rotator cuff - front","shoulder - back"],"steps":["Stand underneath a chin-up bar with your feet shoulder-width apart.","Reach up and grasp the bar with an underhand grip, with your palms facing towards you and your hands shoulder-width apart.","Hang from the bar with your arms fully extended and your shoulders relaxed.","Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.","Continue pulling until your chin is above the bar.","Pause briefly at the top of the movement, then slowly lower yourself back down to the starting position.","Repeat."],"notes":""}'),
('longhaul-fitness', 'b1909b37-f9f5-476e-be62-04bb790e534c', 'push-up-hands-in-rings', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"b1909b37-f9f5-476e-be62-04bb790e534c","name":"Push-Up – Hands in Rings","slug":"push-up-hands-in-rings","primaryMuscles":["chest","shoulder - front","tricep"],"secondaryMuscles":["abdominal"],"steps":["Start in a plank position with your hands placed inside suspended rings.","Engage your core and glutes to keep your body in a straight line.","Lower your body towards the ground by bending your elbows.","Keep your elbows close to your body and your shoulders down and back.","Push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', 'b2a6e0e6-70ae-4326-84ae-92f053eec3b8', 'dead-bug', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"b2a6e0e6-70ae-4326-84ae-92f053eec3b8","name":"Dead Bug","slug":"dead-bug","primaryMuscles":["abdominal"],"secondaryMuscles":["oblique"],"steps":["Start by lying on your back with your arms extended towards the ceiling.","Bend your knees and lift your legs up so that your knees are directly above your hips and your shins are parallel to the floor.","Engage your core muscles by lowering your right arm and left leg towards the floor, keeping them hovering just above the ground. Both your right arm and left leg straighten as they approach the floor.","Return your arm and leg to the starting position and repeat on the opposite side.","Continue alternating sides for the desired number of repetitions or time."],"notes":""}'),
('longhaul-fitness', 'b3ecbc78-8c4d-4adf-b575-454438a45208', 'kettlebell-swing-and-high-pull-double', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"b3ecbc78-8c4d-4adf-b575-454438a45208","name":"Swing and High Pull – Double Kettlebell","slug":"swing-and-high-pull-double-kettlebell","primaryMuscles":["glute","lower back","shoulder - back","shoulder - front","trap"],"secondaryMuscles":["forearm - outer","hamstring","lat","shoulder - side","thigh - inner"],"steps":["Stand with your feet slightly wider than shoulder-width apart, toes slightly turned out.","Hinging forward, hold a kettlebell in each hand between your thighs, maintaining overhand grips, arms hanging naturally extended towards the floor.","Initiate the swing by snapping your hips forward, driving the kettlebell upward with your glutes and hamstrings. Maintain a flat back through the swing.","Push through your heels, pulling the kettlebells to chin height with elbows leading and flaring outward.","Pull your hands back towards your face at the top of the swing. Take care not to pull back so far that the kettlebells come too close to your face.","Return to the forward bend position by extending your arms at the elbows, hinging forward, and dropping the weights back down to the starting position between your legs and under your glutes in a controlled manner.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', 'b4c6d7ac-dc8c-45cb-9b23-988321a15bab', 'plate-alternating-side-lunge-pull', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"b4c6d7ac-dc8c-45cb-9b23-988321a15bab","name":"Alternating Side Lunge Pull – Plate","slug":"alternating-side-lunge-pull-plate","primaryMuscles":["glute","quad","thigh - inner"],"secondaryMuscles":["abdominal","calf","lower back","thigh - outer"],"steps":["Stand with a plate between your feet. This is your starting position.","Take a step to the side with one leg, bending that knee to lower your body into a side lunge.","Keep the other leg straight and your torso upright.","As you push through the heel of your bent leg to return to the standing position, use your non-planted leg to pull the weight plate inwards.","Continue pulling the plate inwards until you are fully standing with the plate close to your feet in the starting position.","Repeat the movement on the other side to complete a single repetition.","Continue for your desired number of repetitions, alternating legs with each lunge."],"notes":""}'),
('longhaul-fitness', 'b571988a-f667-4131-88ed-1467a5a19fb7', 'dumbbell-seated-shoulder-press', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"b571988a-f667-4131-88ed-1467a5a19fb7","name":"Seated Shoulder Press – Dumbbell","slug":"seated-shoulder-press-dumbbell","primaryMuscles":["shoulder - front"],"secondaryMuscles":["shoulder - side","tricep"],"steps":["Start by sitting on a bench with a backrest, holding a dumbbell in each hand at shoulder level.","Ensure that your feet are firmly planted on the ground and your back is straight.","Press the dumbbells up above your head, extending your arms fully.","Pause briefly at the top of the movement, then slowly lower the dumbbells back down to shoulder level.","Repeat."],"notes":""}'),
('longhaul-fitness', 'b757312a-49ac-4617-934a-7d02935944b2', 'kneeling-reclining-hero-pose-pillow', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/flexibility.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"b757312a-49ac-4617-934a-7d02935944b2","name":"Kneeling Reclining Hero Pose – Pillow","slug":"kneeling-reclining-hero-pose-pillow","primaryMuscles":["quad"],"secondaryMuscles":["thigh - inner"],"steps":["Kneel on a padded and stable surface.","Place a thick cushion or pillow directly behind you.","Sit on the floor with your bum between your feet.","Recline back with your upper body until your upper back is fully supported by the pillow.","Keep your arms straight overhead.","Hold the stretch for the desired time."],"notes":""}'),
('longhaul-fitness', 'b7575f4e-3a17-4e4d-8f85-bf9f80352f1c', 'deficit-deadlift', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"b7575f4e-3a17-4e4d-8f85-bf9f80352f1c","name":"Deficit Deadlift","slug":"deficit-deadlift","primaryMuscles":["glute","hamstring","lower back"],"secondaryMuscles":["calf","forearm - inner","forearm - outer","trap","quad"],"steps":["Stand with your feet roughly hip-width apart on a step or plate that raises your body 2-4 inches (5-10 cm) off the ground.","Position a loaded barbell over the middle of your feet.","Bend at your hips and knees to reach down and grasp the barbell with both hands, slightly wider than shoulder-width apart, palms facing towards your body.","With a flat back, engage your core, flatten your shoulder blades and look ahead to keep your neck in a neutral position.","Stand up with the weight by pushing through your heels, keeping the bar close to your body, and driving your hips forward.","Straighten your legs and hips to come to a full standing position, with the barbell hanging in front of your thighs. Do not lean back at the top.","Pause briefly at the top of the lift while maintaining a tight core, and take a breath if needed.","Lower the barbell back to the ground by hinging at the hips and bending the knees, keeping the bar close to your body and your back straight.","Place the barbell back on the ground and return to the starting position, ready to perform the next repetition."],"notes":"The barbell travels extra distance since you''ve raised your body off the ground. With that extra stretch reaching for the barbell, this exercise is more difficult than a standard Deadlift."}'),
('longhaul-fitness', 'b82e8a9a-d794-4a1e-8f5a-5659cafb607d', 'plank-pull-through', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"b82e8a9a-d794-4a1e-8f5a-5659cafb607d","name":"Plank Pull Through","slug":"plank-pull-through","primaryMuscles":["abdominal","shoulder - front"],"secondaryMuscles":["chest","lower back","oblique"],"steps":["Start in a high plank position with your hands positioned directly under your shoulders, feet slightly wider than hip-width apart, and a dumbbell or kettlebell placed on the floor on one side of your body at sternum-level.","Reach under your torso with your opposite hand to grab the dumbbell.","Pull the weight across the floor to the other side of your body while keeping your hips as stable as possible.","Place the weight on the floor and return your hand to the starting plank position.","Repeat the movement by reaching with the other hand to pull the dumbbell back to the starting side.","Continue alternating sides for the desired number of reps or time duration."],"notes":""}'),
('longhaul-fitness', 'b8b5d80e-fc68-4e95-84a8-d20cc3a9b95b', 'concentration-curl', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', 100.0, '{"pk":"b8b5d80e-fc68-4e95-84a8-d20cc3a9b95b","name":"Concentration Curl","slug":"concentration-curl","primaryMuscles":["bicep"],"secondaryMuscles":["forearm - inner"],"steps":["Start by sitting on a bench with your feet flat on the floor and your knees slightly bent.","Hold a dumbbell in one hand and place your elbow on the inside of your thigh, just above the knee.","Extend your arm fully, allowing the dumbbell to hang down towards the floor.","Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder while contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the dumbbell back to the starting position, fully extending your arm.","Repeat for the desired number of repetitions and then switch arms."],"notes":""}'),
('longhaul-fitness', 'b9781769-e3b3-4b44-949a-399139c35825', 'dumbbell-biceps-curl', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"b9781769-e3b3-4b44-949a-399139c35825","name":"Curl – Dumbbell","slug":"curl-dumbbell","primaryMuscles":["bicep"],"secondaryMuscles":["forearm - inner"],"steps":["Stand up straight with your feet shoulder-width apart and your arms at your sides, holding a dumbbell in each hand.","Keeping your elbows close to your sides, slowly lift the dumbbells up towards your shoulders, rotating your palms to face your shoulders as you lift.","Pause for a moment at the top of the movement, squeezing your biceps.","Slowly lower the dumbbells back down to the starting position, rotating your palms back to face your thighs as you lower.","Repeat."],"notes":""}'),
('longhaul-fitness', 'b99edace-a641-4113-b730-f8c8de670dc7', 'one-leg-seated-pretzel-stretch', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/flexibility.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"b99edace-a641-4113-b730-f8c8de670dc7","name":"One-Leg Seated Pretzel Stretch","slug":"one-leg-seated-pretzel-stretch","primaryMuscles":["glute","hamstring"],"secondaryMuscles":["lower back"],"steps":["Sit on a chair with your feet flat on the floor.","Place one ankle on the opposite knee by rotating the leg.","Push the folded knee towards the floor while leaning forward by hinging at the hips.","Keep the spine neutral to uncouple motion between the hip and back.","Hold the stretch for the desired time and switch to the other side."],"notes":""}'),
('longhaul-fitness', 'b9bf1ba7-459f-436e-a14c-d82aa7ce0251', 'dumbbell-single-arm-bulgarian-split-squat', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"b9bf1ba7-459f-436e-a14c-d82aa7ce0251","name":"Single-Arm Bulgarian Split Squat – Dumbbell","slug":"single-arm-bulgarian-split-squat-dumbbell","primaryMuscles":["glute","hamstring","quad"],"secondaryMuscles":["abdominal","calf","oblique"],"steps":["Stand a few feet in front of a bench with your back towards it.","Hold a dumbbell in one hand on the same side as the working leg.","Extend your opposite leg back and place the top of your foot on the bench.","Keep your chest upright and core engaged throughout the movement.","Slowly lower your hips by bending the knee of the working leg.","Continue lowering until your front thigh is parallel to the ground.","Push through the heel of your front foot to return to the starting position.","Repeat for the desired number of repetitions before switching sides."],"notes":""}'),
('longhaul-fitness', 'ba2387cd-2192-42d5-8895-4c8ad78b3607', 'barbell-deadlift', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"ba2387cd-2192-42d5-8895-4c8ad78b3607","name":"Deadlift – Barbell","slug":"deadlift-barbell","primaryMuscles":["glute","hamstring","lower back"],"secondaryMuscles":["calf","forearm - inner","forearm - outer","trap","quad"],"steps":["Stand with your feet roughly hip-width apart, with the barbell positioned over the middle of your feet.","Bend at your hips and knees to reach down and grasp the barbell with both hands, slightly wider than shoulder-width apart, palms facing towards your body.","With a flat back, engage your core, flatten your shoulder blades and look ahead to keep your neck in a neutral position.","Stand up with the weight by pushing through your heels, keeping the bar close to your body, and driving your hips forward.","Straighten your legs and hips to come to a full standing position, with the barbell hanging in front of your thighs. Do not lean back at the top.","Pause briefly at the top of the lift while maintaining a tight core, and take a breath if needed.","Lower the barbell back to the ground by hinging at the hips and bending the knees, keeping the bar close to your body and your back straight.","Place the barbell back on the ground and return to the starting position, ready to perform the next repetition."],"notes":""}'),
('longhaul-fitness', 'baaa4aee-68fa-48cf-aa36-aeb60a2646fe', 'one-handed-plank', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"baaa4aee-68fa-48cf-aa36-aeb60a2646fe","name":"One-Handed Plank","slug":"one-handed-plank","primaryMuscles":["abdominal","shoulder - front"],"secondaryMuscles":["chest","lower back","oblique"],"steps":["Begin in a standard push-up position with your hands on the ground and elbows aligned below your shoulders, and your body forming a straight line from your head to your heels.","Spread your legs slightly wider than hip-width apart to provide additional stability.","Shift your weight onto your left hand as you slowly lift your right hand off the ground, wrapping it behind your back or under your sternum.","Engage your core, glutes, and thigh muscles to prevent your hips from dropping or rotating.","Hold the one-handed plank for the desired duration, breathing steadily throughout the exercise.","Lower your right hand back to the starting plank position with control.","Repeat the exercise by shifting your weight onto your right hand and wrapping your left hand behind your back or under your sternum."],"notes":""}'),
('longhaul-fitness', 'c029b94a-907a-481d-83b2-079b978deb9a', 'cable-single-arm-half-kneeling-high-row', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"c029b94a-907a-481d-83b2-079b978deb9a","name":"Single Arm Half Kneeling High Row – Cable","slug":"single-arm-half-kneeling-high-row-cable","primaryMuscles":["lat"],"secondaryMuscles":["oblique","rotator cuff - back","shoulder - back","trap"],"steps":["Position a cable machine at the top setting and attach a single handle.","Assume a half-kneeling position with your right knee on the ground and left foot forward.","Grasp the handle with your right hand while keeping the arm extended.","Engage your core and keep your torso upright.","Pull the handle down and backwards by engaging your lat, keeping the elbow close to your body.","Pull until your hand reaches chest level, then pause briefly.","Slowly extend your arm back to the start position, controlling the movement.","Complete the desired number of repetitions and switch to the other side."],"notes":""}'),
('longhaul-fitness', 'c0ea6557-b06d-4263-b6d8-fbebedc4316c', 'alternating-rope-wave', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"c0ea6557-b06d-4263-b6d8-fbebedc4316c","name":"Alternating Rope Wave","slug":"alternating-rope-wave","primaryMuscles":["bicep","forearm - inner","forearm - outer","shoulder - back","shoulder - front","shoulder - side","trap"],"secondaryMuscles":["abdominal","chest","tricep"],"steps":["Stand with your feet shoulder-width apart, knees slightly bent, in front of a heavy rope.","Grip the ends of the rope with both hands. Your palms should be facing inward.","Tighten your core to stabilize your spine.","Begin to alternately raise and lower each arm rapidly. The motion should create alternating waves in each of the two ropes.","Keep the waves going consistently for the desired number of repetitions."],"notes":"Keep your back straight and your head up throughout the exercise."}'),
('longhaul-fitness', 'c1800e75-33e8-4c3c-a1a0-a466c71830d7', 'machine-eccentric-bicep-curl', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"c1800e75-33e8-4c3c-a1a0-a466c71830d7","name":"Eccentric Bicep Curl – Machine","slug":"eccentric-bicep-curl-machine","primaryMuscles":["bicep"],"secondaryMuscles":["forearm - inner","forearm - outer"],"steps":["Select the appropriate weight on the machine and adjust the seat and arm pad to align with your elbow joint.","Grip the handles with your palms facing upward in a supinated position.","Sit or stand (depending on machine design) with your upper arm pressed against the arm pad, back straight, and feet flat on the floor for stability.","Use both arms to lift the weight with a controlled motion, flexing the elbows without swinging the arms or leaning back.","Release the handle with one hand. Your other arm completely controls the weight.","Gradually release the weight back to the starting position, emphasizing the downward movement—this is the eccentric phase—taking 3 to 4 seconds to lower the load.","Make sure to fully extend the arms at the bottom, but avoid locking the elbows.","Grip the handles with both hands and use both arms to lift the weight again.","Release the handle with the other hand.","Gradually release the weight back to the starting position again, focusing on the eccentric phase of a single bicep. This completes one full repetition.","Repeat the movement for the desired number of reps, maintaining good form and controlled speed."],"notes":"Keep the tension on the biceps throughout the movement without resting at the bottom."}'),
('longhaul-fitness', 'c1f18283-30bf-4a26-9682-7dca971b901a', 'dumbbell-deadlift', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"c1f18283-30bf-4a26-9682-7dca971b901a","name":"Deadlift – Dumbbell","slug":"deadlift-dumbbell","primaryMuscles":["glute","hamstring","lower back"],"secondaryMuscles":["calf","forearm - inner","forearm - outer","trap","quad"],"steps":["Stand with your feet shoulder-width apart, with a dumbbell in each hand.","Hold the dumbbells about halfway between the front and side of your quads, with your palms facing your body.","Bend your knees, hinge and lean forward at the hips, keeping your back straight and your chest up.","Lower the dumbbells towards the ground, keeping them close to your body.","Pause when your dumbbells are just below your knees.","Push through your heels and stand up, keeping your back straight and your chest up.","Repeat."],"notes":""}'),
('longhaul-fitness', 'c2869e90-30b1-492b-8c8c-32927dc429fc', 'barbell-z-press', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"c2869e90-30b1-492b-8c8c-32927dc429fc","name":"Z Press – Barbell","slug":"z-press-barbell","primaryMuscles":["shoulder - front","shoulder - side"],"secondaryMuscles":["abdominal","lower back","shoulder - back","tricep"],"steps":["Position a loaded barbell in a rack a little above knee height.","Sit down on the floor so that the barbell touches your upper chest.","Extend your legs straight in front of you. Ensure your back is straight.","Grip the barbell just outside shoulder width with palms facing forward.","Unrack the barbell so it is positioned in front of your chin with tension on your front shoulders. This is your starting position.","Brace your core. Push your heels into the ground.","Press the barbell upwards until your arms are fully extended, making sure the bar moves in a straight vertical line.","Pause briefly at the top of the movement.","Lower the bar back to the starting position in a controlled manner.","Repeat for the desired number of reps."],"notes":"Maintain core tension throughout the exercise to prevent arching your back or leaning back too far."}'),
('longhaul-fitness', 'c36cfa8f-b7ea-4571-9e53-778459f7db86', 'one-arm-front-shoulder-active-massage-lacrosse-ball', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/flexibility.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"c36cfa8f-b7ea-4571-9e53-778459f7db86","name":"One-Arm Front Shoulder Active Massage – Lacrosse Ball","slug":"one-arm-front-shoulder-active-massage-lacrosse-ball","primaryMuscles":["shoulder - front"],"secondaryMuscles":["bicep","rotator cuff - front"],"steps":["Stand with a massage ball in one hand and your other arm, the target arm, in a natural position hanging by your side.","Reach across your body to place a massage ball along a tender spot on the front of your target shoulder.","Pin the massage ball in place and compress it within tolerable limits.","Bend your target arm at the elbow so that there''s a right angle between your upper and lower arm. This is your starting position.","Slowly extend your elbow behind you, keeping it close to your torso, to stretch your shoulder.","Lift your elbow away from your body about 45°.","Extend your arm in front of you, straightening the elbow, until you''re comfortably reaching forward.","Return to the starting position, lowering your elbow close to your body, to complete the circlular motion and one repetition.","Continue repetitions for the desired amount of time."],"notes":""}'),
('longhaul-fitness', 'c46c643f-d109-4720-8ce9-3b5d24b9cdec', 'band-lateral-walk', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', 100.0, '{"pk":"c46c643f-d109-4720-8ce9-3b5d24b9cdec","name":"Lateral Walk – Band","slug":"lateral-walk-band","primaryMuscles":["glute","thigh - outer"],"secondaryMuscles":["calf","hamstring","quad","thigh - inner"],"steps":["Place a resistance band around your ankles and stand with your feet hip-width apart.","Take a step to the right with your right foot, keeping tension on the band.","Bring your left foot to meet your right foot, maintaining tension on the band.","Take another step to the right with your right foot, again keeping tension on the band.","Repeat this lateral movement for a desired number of steps to the right.","Then, reverse the movement and take the same number of steps to the left."],"notes":""}'),
('longhaul-fitness', 'c5116ba3-8a9d-4318-80e5-678a927cf916', 'dumbbell-floor-press', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"c5116ba3-8a9d-4318-80e5-678a927cf916","name":"Floor Press – Dumbbell","slug":"floor-press-dumbbell","primaryMuscles":["chest","shoulder - front"],"secondaryMuscles":["tricep"],"steps":["Lie flat on your back on the floor with your knees bent and feet flat on the ground.","Hold a dumbbell in each hand with your palms facing towards your feet.","Extend your arms straight up towards the ceiling, with your elbows slightly bent.","Slowly lower the dumbbells down towards your chest, keeping your elbows close to your body.","Pause when your upper arms touch the ground.","Repeat."],"notes":""}'),
('longhaul-fitness', 'c518bd9d-aa9d-425d-abc3-94036ec0dbc0', 'machine-hip-adduction', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"c518bd9d-aa9d-425d-abc3-94036ec0dbc0","name":"Hip Adduction – Machine","slug":"hip-adduction-machine","primaryMuscles":["thigh - inner"],"secondaryMuscles":[],"steps":["Adjust the seat height of the hip adduction machine so that your knees are at a 90-degree angle when seated.","Sit on the machine with your back against the backrest and your feet flat on the footrests.","Place your thighs against the thigh pads, just above your knees.","Grasp the handles on the sides of the machine for stability.","Engage your core and squeeze your inner thighs together as you exhale.","Hold the contraction for a second and then slowly release as you inhale.","Repeat the movement for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', 'c6d629ff-4e81-455c-a365-aed900ca9a57', 'trap-bar-shrug', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"c6d629ff-4e81-455c-a365-aed900ca9a57","name":"Shrug –  Trap Bar","slug":"shrug-trap-bar","primaryMuscles":["trap"],"secondaryMuscles":["forearm - inner"],"steps":["Stand inside a trap bar with your feet shoulder-width apart.","Grasp the handles of the trap bar with an overhand grip.","Keep your back straight and your core engaged.","Exhale and lift your shoulders up towards your ears, squeezing your trapezius muscles.","Hold the shrug position for a second.","Inhale and slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', 'c714ca8d-3df3-439b-bae0-da66423b7daa', 'squat-box', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', 100.0, '{"pk":"c714ca8d-3df3-439b-bae0-da66423b7daa","name":"Squat – Box","slug":"squat-box","primaryMuscles":["glute","lower back","quad","thigh - inner"],"secondaryMuscles":["calf"],"steps":["Stand with your feet shoulder-width apart, toes slightly turned out.","Place a box or bench behind you at a height that allows you to squat to parallel or slightly below parallel.","Engage your core and keep your chest lifted throughout the exercise.","Lower your body by pushing your hips back and bending your knees, as if sitting back onto the box.","Keep your weight on your heels and your knees in line with your toes.","Pause briefly on the box, then push through your heels to stand back up, fully extending your hips and knees.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', 'c714f4a0-d27f-4909-9c0e-e9a34471d2dc', 'band-one-handed-standing-chest-fly', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"c714f4a0-d27f-4909-9c0e-e9a34471d2dc","name":"One-Handed Standing Chest Fly – Band","slug":"one-handed-standing-chest-fly-band","primaryMuscles":["chest"],"secondaryMuscles":["bicep","forearm - inner","shoulder - front"],"steps":["Find a sturdy stationary object, such as a pole or a door anchor, and attach one end of the resistance band to it at chest height.","Stand with your feet shoulder-width apart, facing away from the stationary object.","Hold the free end of the resistance band in one hand, with your palm facing forward.","Position yourself at a distance from the stationary object so that there is tension in the band when your arm is extended forward at chest height.","Keep your elbow slightly bent and your arm extended out to the side at shoulder height.","Engage your core muscles to stabilize your torso.","With a slight bend in your elbow, bring your arm across your chest in a sweeping motion while keeping your chest open.","Feel the stretch in your chest muscles as you bring your arm across your body.","Return your arm to the starting position in a controlled manner.","Complete the desired number of repetitions on one side before switching to the other."],"notes":""}'),
('longhaul-fitness', 'c7fc3f17-22f5-41bd-8b2e-8b433ca4350f', 'band-drinking-bird-row', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"c7fc3f17-22f5-41bd-8b2e-8b433ca4350f","name":"Drinking Bird Row – Band","slug":"drinking-bird-row-band","primaryMuscles":["lat","lower back","trap"],"secondaryMuscles":["bicep","glute","hamstring"],"steps":["Tie a resistance band down in front of you at sternum height and hold it with both hands using an overhand grip.","Stand with your feet shoulder-width apart and hinge at the hips forward while keeping your spine neutral and a slight bend in the knees.","Reach your hands out overhead as you hinge forward, maintaining tension in the band. This is your starting position.","Reverse the hinge and stand straight up while pulling the band towards your sternum, leading with your elbows.","Squeeze your back muscles as your hands reach your sternum and you''re standing up straight.","Slowly return to the starting position by hinging forward at the hips again.","Repeat the movement for your desired number of repetitions."],"notes":""}'),
('longhaul-fitness', 'c8482f26-d46b-42be-a7ef-132b2aba5658', 'good-mornings', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"c8482f26-d46b-42be-a7ef-132b2aba5658","name":"Good Morning","slug":"good-morning","primaryMuscles":["glute","hamstring","lower back"],"secondaryMuscles":["thigh - inner"],"steps":["Start by standing with your feet shoulder-width apart and your toes pointing forward.","Place your hands behind your head, or on a weighted barbell on your shoulders, with your elbows pointing out to the sides.","Keeping your back straight and your core engaged, hinge forward at your hips, pushing your butt back as far as possible.","Lower your torso until it is nearly parallel to the ground, or until you feel a stretch in your hamstrings.","Pause for a moment, then slowly return to the starting position by squeezing your glutes and pushing your hips forward.","Repeat."],"notes":""}'),
('longhaul-fitness', 'c85b6e20-7a2c-45fe-99b2-854f4c2c6fd8', 'barbell-sumo-deadlift', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', 100.0, '{"pk":"c85b6e20-7a2c-45fe-99b2-854f4c2c6fd8","name":"Sumo Deadlift – Barbell","slug":"sumo-deadlift-barbell","primaryMuscles":["glute","hamstring","lower back"],"secondaryMuscles":["calf","forearm - inner","forearm - outer","trap","quad"],"steps":["Stand with feet wider than shoulder-width apart and toes pointed outwards.","Place hands on the barbell with a grip wider than shoulder-width apart and palms facing down.","Engage core and lift the barbell off the ground, keeping back straight and knees bent.","As you lift, push hips forward and straighten legs.","Lower the barbell back down to the ground, keeping back straight and knees bent."],"notes":""}'),
('longhaul-fitness', 'c85eac17-4d0a-4a7b-b5ee-3ecaf08ab5f7', 'dumbbell-crush-grip-curl', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"c85eac17-4d0a-4a7b-b5ee-3ecaf08ab5f7","name":"Crush Grip Curl – Dumbbell","slug":"crush-grip-curl-dumbbell","primaryMuscles":["bicep"],"secondaryMuscles":["forearm - inner","forearm - outer"],"steps":["Select a single dumbbell and grip it with both hands, one on each end, pressing your palms against the sides of the dumbbell.","Position yourself straight-armed on a preacher curl bench, ensuring that your elbows and upper arms are comfortably resting against the bench pad. This is your starting position.","Keep pressing your hands together firmly to maintain a ''crush grip'' on the dumbbell throughout the exercise.","While maintaining the grip, exhale and curl the dumbbell upwards towards your shoulders, focusing on contracting the biceps.","Hold the contraction briefly at the top of the movement, then inhale and slowly lower the dumbbell back to the starting position.","Repeat the curl for the desired number of repetitions, ensuring the crush grip is maintained throughout each curl."],"notes":""}'),
('longhaul-fitness', 'c8794b07-358b-458a-8e09-80f7277797d3', 'dumbbell-horizontal-internal-shoulder-rotation', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"c8794b07-358b-458a-8e09-80f7277797d3","name":"Horizontal Internal Shoulder Rotation – Dumbbell","slug":"horizontal-internal-shoulder-rotation-dumbbell","primaryMuscles":["rotator cuff - front"],"secondaryMuscles":[],"steps":["Lie on your back on a flat surface with a dumbbell nearby.","Raise one arm at the shoulder joint to your side so that your upper arm is perpendicular to your body. Bend your elbow at a 90-degree angle bringing your forearm perpendicular to the upper arm so that your hand is above your head on your supporting surface. This position is commonly known as as a single-arm \"cactus pose\".","Hold a dumbbell in your hand with your palm facing up towards the ceiling.","Slowly rotate your arm up towards the ceiling until it''s perpendicular to the ground, keeping your elbow bent and your upper arm stationary.","Pause for a moment at the top of the movement, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch sides and repeat the exercise with your other arm."],"notes":""}'),
('longhaul-fitness', 'c8ad50b1-38c4-4074-9465-67b7c0e2a20a', 'dumbbell-one-handed-wrist-curl', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"c8ad50b1-38c4-4074-9465-67b7c0e2a20a","name":"One-Handed Wrist Curl – Dumbbell","slug":"one-handed-wrist-curl-dumbbell","primaryMuscles":["forearm - inner"],"secondaryMuscles":[],"steps":["Sit on a bench, resting your forearm on your knee, gripping a dumbbell in one hand with your palm facing up.","Bending at the wrist, extend your knuckles towards the floor.","Curl your wrist upward, bringing the dumbbell towards your forearm.","Pause for a moment at the top of the movement, squeezing your forearm muscles.","Slowly lower the dumbbell back to the starting position, fully extending your wrist.","Repeat for the desired number of repetitions.","Switch hands and repeat the exercise with the other hand."],"notes":""}'),
('longhaul-fitness', 'c98e0b0a-87d1-4202-9f19-36b174e65ab2', 'dumbbell-one-handed-suitcase-walking-lunge', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"c98e0b0a-87d1-4202-9f19-36b174e65ab2","name":"One-Handed Suitcase Walking Lunge – Dumbbell","slug":"one-handed-suitcase-walking-lunge-dumbbell","primaryMuscles":["glute","hamstring","quad"],"secondaryMuscles":["abdominal","calf","forearm - inner","forearm - outer","lower back","oblique","trap"],"steps":["Stand upright with feet shoulder-width apart while holding a dumbbell in one hand by your side, similar to carrying a suitcase.","Keep your chest up, shoulders back, and core engaged.","Step forward with one leg into a lunge position, ensuring your front knee is directly above your ankle and your back knee is hovering just above the ground.","Push through the heel of your front foot to bring your back leg forward into the starting position, keeping the dumbbell steady by your side.","Continue the lunge by stepping forward with the opposite leg, maintaining balance and proper form.","Repeat the walking lunge series for the desired number of repetitions or distance while keeping the dumbbell in the same hand.","Switch the dumbbell to the other hand and repeat for balance after completing the set with one side."],"notes":""}'),
('longhaul-fitness', 'ca9b99c8-66d3-4fe5-a871-88c2bc2c97ab', 'band-hip-hinge', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"ca9b99c8-66d3-4fe5-a871-88c2bc2c97ab","name":"Hip Hinge – Band","slug":"hip-hinge-band","primaryMuscles":["glute","hamstring"],"secondaryMuscles":["lower back"],"steps":["Place a resistance band around your hips and anchor it behind you at mid-hamstring level.","Stand with your feet hip-width apart and maintain a light bend in your knees. This is your starting position.","Engage your core and hinge forward at the hips, keeping your back straight and chest lifted.","Continue hinging until you feel a stretch in your hamstrings.","Pause briefly at the bottom, ensuring you maintain a neutral spine.","Stand straight back up to the starting position.","Repeat the movement for your desired number of repetitions."],"notes":""}'),
('longhaul-fitness', 'cbbdaae8-7600-456f-b025-12d2050b3765', 'hanging-leg-raise-2', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', 100.0, '{"pk":"cbbdaae8-7600-456f-b025-12d2050b3765","name":"Hanging Leg Raise","slug":"hanging-leg-raise","primaryMuscles":["abdominal","forearm - inner","forearm - outer"],"secondaryMuscles":["oblique"],"steps":["Start by securing your grip on a pull-up bar, ensuring your hands are spaced shoulder-width apart.","Allow your body to hang straight down from the bar with your feet together. This is your starting position.","Engage your core and slowly raise your legs in front of you while keeping them straight.","Raise your legs until they are parallel to the ground, or higher if your flexibility and strength allows.","Pause briefly at the top of the movement, keeping your core tight to stabilize your body.","Slowly lower your legs back to the starting position in a controlled manner.","Repeat the movement for the desired number of repetitions."],"notes":"There are hanging leg raise machines that allow you to balance on your forearms rather than hang from a bar. Also, you could perform this exercise by holding yourself up on dip bars. Consider using either machine if you want to remove most of the forearm activation and focus on the abdominal work."}'),
('longhaul-fitness', 'cbc3639e-776d-43ec-bd98-dd0df647aed6', 'cable-standing-leg-curl', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', 100.0, '{"pk":"cbc3639e-776d-43ec-bd98-dd0df647aed6","name":"Standing Cable Leg Curl","slug":"standing-cable-leg-curl","primaryMuscles":["hamstring"],"secondaryMuscles":[],"steps":["Stand facing a cable machine with your feet hip-width apart.","Attach an ankle cuff to your right ankle.","Hold onto the machine for support and balance.","Bend your right knee and bring your heel towards your glutes, keeping your upper leg stationary.","Squeeze your hamstring at the top of the movement.","Slowly lower your leg back to the starting position.","Repeat for the desired number of repetitions.","Switch sides and perform the exercise with your left leg."],"notes":""}'),
('longhaul-fitness', 'cc331b1d-d223-4281-bb95-83eb06d43d7b', 'barbell-front-raise', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"cc331b1d-d223-4281-bb95-83eb06d43d7b","name":"Front Raise – Barbell","slug":"front-raise-barbell","primaryMuscles":["shoulder - front"],"secondaryMuscles":["shoulder - side"],"steps":["Stand with your feet shoulder-width apart and your knees slightly bent.","Hold a barbell with an overhand grip, hands shoulder-width apart, and the bar resting on your thighs.","Keeping your arms straight, lift the barbell up in front of you until it reaches shoulder height.","Pause for a moment, then slowly lower the barbell back down to your thighs.","Repeat."],"notes":""}'),
('longhaul-fitness', 'cc340eb0-206a-4baa-ad49-575696e4613e', 'plate-one-handed-wrist-curl', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"cc340eb0-206a-4baa-ad49-575696e4613e","name":"One-Handed Plate Wrist Curl","slug":"one-handed-plate-wrist-curl","primaryMuscles":["forearm - inner"],"secondaryMuscles":[],"steps":["Start by sitting on a bench or chair with your feet flat on the ground.","Hold a weight plate with an underhand grip, placing your hand on the inside rim of the plate.","Rest your forearm on your thigh, with your wrist hanging off the edge and pointing to the ceiling.","Lower the weight plate towards the ground by flexing your wrist, keeping your forearm stationary.","Pause for a moment at the bottom of the movement, feeling the stretch in your wrist.","Slowly curl the weight plate back up towards your body.","Repeat for the desired number of reps and then switch sides."],"notes":""}'),
('longhaul-fitness', 'd010a335-71e9-4660-ae1d-fd6f384b5458', 'band-one-leg-prone-quad-stretch', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/flexibility.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"d010a335-71e9-4660-ae1d-fd6f384b5458","name":"One-Leg Prone Quad Stretch – Band","slug":"one-leg-prone-quad-stretch-band","primaryMuscles":["quad"],"secondaryMuscles":["hamstring"],"steps":["Loop a strength band or pull-up assist band around one ankle.","Lie down on your stomach.","Hold the band with both hands, over your back, over the same shoulder as the looped ankle, all the way until it''s in front of your forehead as your lying down.","Pull the band away from your forehead to flex your quad.","Hold the stretch for the desired time and switch to the other side."],"notes":""}'),
('longhaul-fitness', 'd0344102-ed3a-43bd-a786-27d4fbcba2f3', 'medicine-ball-push-up', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', 100.0, '{"pk":"d0344102-ed3a-43bd-a786-27d4fbcba2f3","name":"Push-Up – Medicine Ball","slug":"push-up-medicine-ball","primaryMuscles":["chest","shoulder - front","tricep"],"secondaryMuscles":["abdominal","forearm - inner","forearm - outer"],"steps":["Place a medicine ball on the ground and assume a plank position with your hands placed on the ball directly beneath your chest. Keep your feet together or slightly apart for better stability.","Engage your core and maintain a straight line from your head to your heels, avoiding any sagging or arching in your lower back.","Lower your body towards the ball by bending your elbows, keeping them close to your body. Go as low as you can without compromising your form.","Push through your hands and chest to extend your arms and raise your body back up to the starting position.","Repeat the movement for the desired number of reps, making sure to maintain proper form throughout the set."],"notes":""}'),
('longhaul-fitness', 'd0c37823-891a-415a-bc8d-05f7b465977e', 'kettlebell-around-world', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"d0c37823-891a-415a-bc8d-05f7b465977e","name":"Around the World – Kettlebell","slug":"around-the-world-kettlebell","primaryMuscles":["oblique"],"secondaryMuscles":["abdominal","shoulder - front","shoulder - side"],"steps":["Hold the kettlebell in front of your body with arms extended and both hands on the handle.","Move the kettlebell around your body; start by passing it to your right hand and move it behind your back.","Receive the kettlebell with your left hand behind your back, and continue moving it around to the left side and back to the front.","Continue this motion for the desired number of repetitions before switching direction."],"notes":"Stay stable and centered as possible. Resisting the sway is a big part of the exercise."}');
INSERT INTO source_records (source_id, source_record_id, exercise_id, source_url, license, author, match_method, match_score, raw_json) VALUES
('longhaul-fitness', 'd130d9cb-bc1b-4f41-a833-c493de07abc6', 'machine-decline-bench-press', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"d130d9cb-bc1b-4f41-a833-c493de07abc6","name":"Decline Bench Press – Machine","slug":"decline-bench-press-machine","primaryMuscles":["chest","shoulder - front","tricep"],"secondaryMuscles":["rotator cuff - front"],"steps":["Adjust the bench and seat height so that your chest aligns with the decline bench press machine''s handles and your feet are flat on the floor.","Select the appropriate weight on the weight stack.","Sit on the machine with your back flat against the back pad.","Grasp the handles with a firm grip, keeping your wrists straight. This is the starting position.","Press the handles away from your chest, keeping your elbows at about a 45-degree angle from your body, extending your arms fully without locking your elbows.","Pause briefly at the top of the press.","Slowly lower the handles back to the starting position, maintaining control throughout the movement.","Repeat the press for the desired number of repetitions."],"notes":"Ensure your back is flat against the bench, and your feet are firmly planted on the ground.  Keep your core tight. Exhale as you push the bar away from your chest, and inhale as you lower it down."}'),
('longhaul-fitness', 'd16cec81-500f-4a0b-8f51-ee2efe91ecee', 'prisoner-squat-bodyweight', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"d16cec81-500f-4a0b-8f51-ee2efe91ecee","name":"Prisoner Squat – Bodyweight","slug":"prisoner-squat-bodyweight","primaryMuscles":["glute","quad","thigh - inner"],"secondaryMuscles":["abdominal","calf","lower back"],"steps":["Stand with your feet shoulder-width apart and toes pointing forward or slightly away from your body up to 15°.","Place your hands behind your head with your elbows pointing out to the sides. This is your starting position.","Bend your knees and lower your hips back and down as if sitting in a chair, keeping your weight on your heels.","Lower your body until your thighs are parallel to the ground.","Push through your heels to stand back up to the starting position.","Repeat the movement for your desired number of repetitions."],"notes":"Engage your core and keep your chest lifted throughout the exercise."}'),
('longhaul-fitness', 'd2b2ae91-3363-4894-995a-82a07ae5294f', 'barbell-wrist-extension', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"d2b2ae91-3363-4894-995a-82a07ae5294f","name":"Wrist Extension – Barbell","slug":"wrist-extension-barbell","primaryMuscles":["forearm - outer"],"secondaryMuscles":[],"steps":["Hold a barbell with an overhand grip, with your hands shoulder-width apart.","Sit on a bench with your feet shoulder-width apart.","Rest the barbell on the top of your thighs, with your palms facing down.","Slowly lift the barbell by extending your wrists, keeping your elbows stationary. Focus on bringing your knuckles back towards the top of your forearms.","Hold the barbell at the top of the movement for a moment.","Lower the barbell back down to the starting position by flexing your wrists.","Repeat."],"notes":""}'),
('longhaul-fitness', 'd3040d3b-c208-45a4-aa70-b31416d060a3', 'one-leg-lying-pretzel-stretch', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/flexibility.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"d3040d3b-c208-45a4-aa70-b31416d060a3","name":"One-Leg Lying Pretzel Stretch","slug":"one-leg-lying-pretzel-stretch","primaryMuscles":["glute","hamstring"],"secondaryMuscles":["lower back"],"steps":["Lie on your back with your feet flat on the floor, knees bent.","Place one ankle on the opposite knee by rotating the leg.","Reach around the leg with the foot on the floor to grab that leg''s shin.","Keep your back on the floor and pull your knee towards your chest.","Hold the stretch for the desired time and switch to the other side."],"notes":""}'),
('longhaul-fitness', 'd30a00c4-438c-4860-b201-7203ac451c3b', 'dumbbell-seated-incline-front-raise', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"d30a00c4-438c-4860-b201-7203ac451c3b","name":"Seated Incline Front Raise – Dumbbell","slug":"seated-incline-front-raise-dumbbell","primaryMuscles":["shoulder - front"],"secondaryMuscles":["chest","shoulder - side"],"steps":["Sit on an incline bench set at a 45-degree angle, holding a dumbbell in each hand with palms facing each other.","Keep your feet flat on the floor, back against the bench, and chest up.","Start with the dumbbells hanging straight down towards the ground, arms extended.","Raise the dumbbells in front of you, keeping your arms straight, palms facing down, until they are above shoulder height but not so high to take tension off the front shoulder muscle.","Pause briefly at the top of the movement.","Slowly lower the dumbbells back to the starting position.","Repeat the movement for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', 'd3e4fbd5-7177-4243-b4ba-519b6a0f5ab8', 'oblique-crunch', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"d3e4fbd5-7177-4243-b4ba-519b6a0f5ab8","name":"Oblique Crunch","slug":"oblique-crunch","primaryMuscles":["oblique"],"secondaryMuscles":["abdominal"],"steps":["Lie on your back with your legs together, knees bent and feet flat on the ground. Drop both legs to the ground on your right side.","Place your left hand behind your head and your right arm on the ground on your right side.","Engage your core muscles and lift your shoulders off the ground, extending your left elbow towards your left quadricep. Flex your waist several inches to feel the contraction in your left oblique.","Lower your shoulders back down to the ground and repeat for the desired number of repetitions.","Continue alternating sides for the desired number of repetitions.","Switch sides and repeat the exercise for the same number of repetitions."],"notes":"Make this exercise more difficult by putting both hands behind your head, or even more difficult by stretching your hands beyond your head."}'),
('longhaul-fitness', 'd3fe33ec-cb3b-4a38-bef8-7391da0f9e68', 'burpee', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', 100.0, '{"pk":"d3fe33ec-cb3b-4a38-bef8-7391da0f9e68","name":"Burpee","slug":"burpee","primaryMuscles":["chest","glute","quad","shoulder - front"],"secondaryMuscles":["abdominal","lower back"],"steps":["Start in a standing position with your feet shoulder-width apart.","Lower your body into a squat position, placing your hands on the floor in front of you.","Kick your feet back, landing in a plank position with your arms fully extended.","Lower your chest and thighs to the floor, keeping your elbows close to your body.","Push up to return to the plank position.","Jump your feet back towards your hands, landing in a squat position.","Jump up explosively, reaching your arms overhead.","Land softly and immediately lower back into the squat position to begin the next repetition."],"notes":""}'),
('longhaul-fitness', 'd52ab563-adac-47d9-a85a-3593b285e041', 'power-clean', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', 100.0, '{"pk":"d52ab563-adac-47d9-a85a-3593b285e041","name":"Power Clean","slug":"power-clean","primaryMuscles":["glute","hamstring","quad","trap"],"secondaryMuscles":["calf","forearm - outer","lower back","shoulder - front"],"steps":["Place a barbell on the ground and stand with your feet hip-width apart, toes under the bar.","Bend at the hips and knees to grip the bar with an overhand grip slightly wider than shoulder width.","Bend your knees until your shins touch the bar, keeping your back flat and chest up. This is your starting position.","Lift the bar by extending your hips and knees, keeping the bar close to your body and your elbows straight.","As the bar passes your knees, aggressively extend your hips, shrug your shoulders, and then pull yourself under the bar.","Catch the bar in a partial squat position, with elbows forward and the bar resting on your shoulders.","Stand up straight to complete the movement.","Lower the bar to the ground carefully and set up for the next repetition.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', 'd5349874-565e-4e21-b808-aa3ee10ec357', 'clean', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', 100.0, '{"pk":"d5349874-565e-4e21-b808-aa3ee10ec357","name":"Clean","slug":"clean","primaryMuscles":["glute","lower back","quad","thigh - inner"],"secondaryMuscles":["calf","forearm - inner","hamstring","trap"],"steps":["Start with feet hip-width apart and hands gripping the barbell just outside the legs.","Lower into a squat position, keeping the back straight and the chest up.","Explosively extend the hips, knees, and ankles, driving the barbell upwards.","As the barbell reaches chest level, quickly drop underneath it in a squat position, rotating the elbows forward.","Catch the barbell on the front of the shoulders, with the elbows pointing forward and the chest up.","Stand up by extending the hips and knees, keeping the barbell close to the body.","Lower the barbell back to the starting position by reversing the movement."],"notes":""}'),
('longhaul-fitness', 'd6bb8d08-e991-4b4a-8531-eedf42e915e6', 'rack-pull', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"d6bb8d08-e991-4b4a-8531-eedf42e915e6","name":"Rack Pull","slug":"rack-pull","primaryMuscles":["glute","hamstring","lower back"],"secondaryMuscles":["calf","forearm - inner","forearm - outer","trap","quad"],"steps":["Set up a barbell in a power rack at shin height or just below your knees.","Stand with your feet shoulder-width apart and your shins touching the bar.","Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Engage your core and lift the bar by extending your hips and knees.","Keep your back straight and your shoulders pulled back throughout the movement.","Lower the bar back down to the starting position by bending your hips and knees.","Repeat."],"notes":"With its elevated starting point, the Rack Pull is an easier version of the Deadlift."}'),
('longhaul-fitness', 'd6d575f0-d09b-49ed-a5aa-07215fa12158', 'one-arm-posterior-shoulder-pull-dowel', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/flexibility.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"d6d575f0-d09b-49ed-a5aa-07215fa12158","name":"One-Arm Posterior Shoulder Pull – Dowel","slug":"one-arm-posterior-shoulder-pull-dowel","primaryMuscles":["shoulder - back","rotator cuff - back"],"secondaryMuscles":["tricep"],"steps":["Stand tall with a dowel held behind your back using both hands.","Place one hand on the dowel at the small of your low back and the other hand behind your head on the dowel.","Use your top arm to gently pull the target hand up between your shoulder blades.","Hold the stretch for the desired amount of time and switch sides."],"notes":""}'),
('longhaul-fitness', 'd74842c0-577f-4dca-ac4d-6bb52aa6976b', 'squat-bodyweight', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"d74842c0-577f-4dca-ac4d-6bb52aa6976b","name":"Squat – Bodyweight","slug":"squat-bodyweight","primaryMuscles":["glute","quad","thigh - inner"],"secondaryMuscles":["calf"],"steps":["Stand with your feet shoulder-width apart and point your toes slightly outward.","Keep your chest up, shoulders back, and core engaged.","Lower your body by bending your knees and pushing your hips back as if you were sitting in a chair.","Keep your weight on your heels and your knees behind your toes.","Lower yourself until your thighs are parallel to the ground or as low as you can comfortably go while maintaining good form.","Pause briefly at the bottom of the squat.","Push through your heels to stand back up, driving your hips forward as you do.","Stand up straight and repeat."],"notes":""}'),
('longhaul-fitness', 'd81d955d-3f93-4961-9519-608ee5f901b3', 'box-step-up', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"d81d955d-3f93-4961-9519-608ee5f901b3","name":"Box Step-Up","slug":"box-step-up","primaryMuscles":["glute","quad"],"secondaryMuscles":["calf","hamstring","thigh - inner","thigh - outer"],"steps":["Stand upright with a platform in front of you, feet hip-width apart. The height of the platform marks the difficult of the exercise.","Place your right foot on the platform, ensuring your entire foot is on the surface.","Press through your right foot to lift your body up onto the platform, bringing your left foot to meet your right foot.","Stand tall on the platform with both feet flat and your core engaged.","Step back down with your left foot, returning to the floor.","Follow by stepping down with your right foot, coming back to the starting position.","Repeat the exercise for the desired number of repetitions before switching to lead with the left foot."],"notes":"Increase the platform''s height to increase the exercise''s resistance."}'),
('longhaul-fitness', 'dab16014-5801-4fd0-bcfd-3db50f9ca801', 'one-leg-seated-ankle-crosses', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/flexibility.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"dab16014-5801-4fd0-bcfd-3db50f9ca801","name":"One-Leg Seated Ankle Crosses","slug":"one-leg-seated-ankle-crosses","primaryMuscles":["calf"],"secondaryMuscles":[],"steps":["Sit on a chair or a stable surface with your legs on the ground.","Pull the target leg''s knee towards your chest. Leave the other foot on the ground for stability.","You''re going to draw a bowtie shape, ''⋈'', with your with the toes of your target leg.","Rotate your foot inwards and then outwards, exploring the full range of motion at the ankle.","After completing the bowtie shape in one direction, reverse the direction you''re drawing with your foot.","Repeat the shape, forward and backward, for the desired amount of time and switch to target the other leg."],"notes":""}'),
('longhaul-fitness', 'dba9a235-84f3-400c-a389-c4bdaca0e2a8', 'cable-twist', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"dba9a235-84f3-400c-a389-c4bdaca0e2a8","name":"Twist – Cable","slug":"twist-cable","primaryMuscles":["oblique"],"secondaryMuscles":["abdominal"],"steps":["Stand with your left foot in front of your right, knees slightly bent, facing away from the cable machine.","Rotate and reach to your right, behind you, and grab the cable handle with both hands. Your left arm should be straight across your body and behind you.","Rotate your torso left until you''re facing forward, pulling the cable across your body.","Pause briefly at the end of the movement, then slowly rotate back to the starting position.","Repeat for the desired number of reps and then switch sides."],"notes":""}'),
('longhaul-fitness', 'dc033c10-988c-4558-bf74-3ab5be6c59fc', 'barbell-squat', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"dc033c10-988c-4558-bf74-3ab5be6c59fc","name":"Squat – Barbell","slug":"squat-barbell","primaryMuscles":["glute","lower back","quad","thigh - inner"],"secondaryMuscles":["calf"],"steps":["Begin by standing with your feet shoulder-width apart and your toes pointing forward. Hold a barbell behind your neck, resting it on your shoulders with your elbows pointing down and your palms facing forward.","Engage your core and keep your chest lifted as you bend your knees and lower your hips back and down as if sitting in a chair. Make sure to keep your weight on your heels and your knees tracking in line with your toes.","As you descend into the squat, inhale and maintain proper form. Lean forward so that your chest is over your thighs. Keep your back straight and your core engaged. Lower your body until your thighs parallel the ground, and your hips should align with your knees.","Pause briefly at the bottom of the movement, then exhale and push through your heels to stand back up to the starting position. Keep your core engaged and your chest lifted until you''re fully standing.","Repeat the movement for your desired number of repetitions.","Place the barbell on the rack after you''ve finished your set."],"notes":""}'),
('longhaul-fitness', 'dce6d67f-877e-4595-9277-3a3f0f19dc46', 'barbell-walking-lunge', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"dce6d67f-877e-4595-9277-3a3f0f19dc46","name":"Walking Lunge – Barbell","slug":"walking-lunge-barbell","primaryMuscles":["glute","quad","thigh - inner"],"secondaryMuscles":[],"steps":["Start with your feet hip-width apart and the barbell on your shoulders.","Take a large step forward with your right foot, lowering your body until your right thigh is parallel to the ground and your left knee is hovering just above the floor.","Push through your right heel to stand back up, bringing your left foot forward to meet your right foot.","Repeat the lunge on the other side by stepping forward with your left foot.","Continue alternating lunges for the desired number of reps or distance."],"notes":""}'),
('longhaul-fitness', 'dd06d4bf-6aa8-4de4-9ad7-f1a4d960cd13', 'assisted-wrist-rotation', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/flexibility.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"dd06d4bf-6aa8-4de4-9ad7-f1a4d960cd13","name":"Assisted Wrist Rotation","slug":"assisted-wrist-rotation","primaryMuscles":["forearm - inner","forearm - outer"],"secondaryMuscles":[],"steps":["Raise your arms straight in front of you and clasp your hands together with your thumbs up and fingers interlaced.","Rotate your wrists together. Imagine tracing an infinity symbol (∞) with your knuckles. Aim for the largest rotation possible within tolerable limits.","Complete 5-8 repetitions in one direction (clockwise).","Switch direction (counter-clockwise) and repeat.","Continue alternating the movement in each direction for the desired amount of time."],"notes":""}'),
('longhaul-fitness', 'dd85ffa7-ed9f-4911-a0f2-dc3ebb5676d6', 'band-hip-abduction', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"dd85ffa7-ed9f-4911-a0f2-dc3ebb5676d6","name":"Hip Abduction – Band","slug":"hip-abduction-band","primaryMuscles":["thigh - outer"],"secondaryMuscles":["glute"],"steps":["Start by placing an exercise band around both of your knees. Make sure the band is secure and does not slip during the exercise.","Sit on a bench with your feet hip-width apart and your toes pointing forward.","Exhale as you slowly press your knees outward, against the resistance of the exercise band.","Continue pressing until you feel a comfortable stretch in your outer hip and thigh muscles.","Pause for a brief moment at the outwardmost position, feeling the tension in the exercise band.","Inhale as you release the pressure and bring your knees back together, returning to the starting position.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', 'ddc8990f-9190-4d23-ba77-64cfb39a7e1b', 'machine-chest-press-exercise', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"ddc8990f-9190-4d23-ba77-64cfb39a7e1b","name":"Chest Press – Machine","slug":"chest-press-machine","primaryMuscles":["chest","shoulder - front"],"secondaryMuscles":["tricep"],"steps":["Adjust the seat height so that the handles are at chest level.","Select the appropriate weight on the weight stack.","Sit on the machine with your back flat against the backrest and your feet flat on the floor.","Grasp the handles with an overhand grip and push them away from your chest until your arms are fully extended.","Slowly lower the handles back towards your chest, keeping your elbows at a 90-degree angle.","Repeat."],"notes":""}'),
('longhaul-fitness', 'de2489dd-12c5-4e6c-b8a7-1c3ed9027135', 'one-handed-lat-pulldown', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"de2489dd-12c5-4e6c-b8a7-1c3ed9027135","name":"One-Handed Lat Pulldown","slug":"one-handed-lat-pulldown","primaryMuscles":["lat"],"secondaryMuscles":["bicep","forearm - inner","rotator cuff - back","rotator cuff - front","shoulder - back"],"steps":["Adjust the seat height and position yourself in the lat pulldown machine.","Grasp the lat pulldown bar with one hand, using an overhand grip.","Engage your core and keep your back straight throughout the exercise.","Start with your arm fully extended, allowing the weight to be lifted off the stack.","Exhale and pull the bar down towards your side, focusing on squeezing your lat muscles.","Pause for a moment at the bottom of the movement, feeling the contraction in your lat.","Inhale and slowly return the bar to the starting position, fully extending your arm.","Repeat for the desired number of repetitions and then switch to the other hand."],"notes":""}'),
('longhaul-fitness', 'de4cd379-702b-411c-a127-41a7ac78c658', 'cable-chest-press', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', 100.0, '{"pk":"de4cd379-702b-411c-a127-41a7ac78c658","name":"Chest Press – Cable","slug":"chest-press-cable","primaryMuscles":["chest"],"secondaryMuscles":["shoulder - front","tricep"],"steps":["Adjust the cable machine to chest height and attach the handles to the cables.","Stand facing away from the machine and grasp the handles with an overhand grip.","Step forward to create tension in the cables and position your feet shoulder-width apart.","Engage your core and keep your chest up as you push the handles forward until your arms are fully extended.","Hold the position for a moment and then slowly release the handles back to the starting position.","Repeat."],"notes":""}'),
('longhaul-fitness', 'dee8ca71-a01b-4ffd-b85e-426080e92f1e', 'machine-glute-kickback', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"dee8ca71-a01b-4ffd-b85e-426080e92f1e","name":"Glute Kickback – Machine","slug":"glute-kickback-machine","primaryMuscles":["glute"],"secondaryMuscles":["hamstring","thigh - inner"],"steps":["Adjust the machine to fit your body height","Position yourself in the machine with your hands on the handles and one ankle on the padding.","Keeping your core engaged, exhale and extend your leg back as far as possible while squeezing your glutes.","Inhale and slowly return your leg to the starting position.","Repeat."],"notes":""}'),
('longhaul-fitness', 'defa7c1b-b8d8-4979-ac65-ae3faaf285d1', 'kettlebell-bottoms-up-seesaw-overhead-press', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"defa7c1b-b8d8-4979-ac65-ae3faaf285d1","name":"Bottoms Up Seesaw Overhead Press – Kettlebell","slug":"bottoms-up-seesaw-overhead-press-kettlebell","primaryMuscles":["shoulder - front","shoulder - side"],"secondaryMuscles":["rotator cuff - back","rotator cuff - front","tricep"],"steps":["Stand with feet shoulder-width apart, holding a kettlebell in each hand by the horns on the floor between your legs.","Swing both kettlebells up, bending your elbows, so that the kettlebells end up in front of your shoulders in the bottoms-up position. This is your starting position.","Begin the press by pushing one kettlebell upward, over your head, until your arm is staight with a slight bend in the elbow.","Lower the raised kettlebell to your shoulder while simultaneously raising the lowered kettlebell over your head.","Alternate the press between the kettlebells in a seesaw motion, ensuring one is always moving up as the other moves down.","Complete the desired number of repetitions, ensuring that each hand pushes the kettlebell the same number of times, then safely lower both kettlebells to the ground."],"notes":""}'),
('longhaul-fitness', 'df1179cd-ad11-4374-b414-fe67eba0cd3b', 'segmental-lower-back-flexion', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/flexibility.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"df1179cd-ad11-4374-b414-fe67eba0cd3b","name":"Segmental Lower Back Flexion","slug":"segmental-lower-back-flexion","primaryMuscles":["trap","lower back"],"secondaryMuscles":[],"steps":["Sit or stand with a neutral spine.","Flex your neck by bringing your chin towards your chest.","Slump your shoulders forward and flex your upper back.","Bend forward incrementally at each segment of the thoracic spine.","Continue the movement for the desired amount of time."],"notes":""}'),
('longhaul-fitness', 'dfb13090-2373-438e-988d-dcb6f851802a', 'barbell-seated-good-morning', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"dfb13090-2373-438e-988d-dcb6f851802a","name":"Seated Good Morning – Barbell","slug":"seated-good-morning-barbell","primaryMuscles":["glute","hamstring","lower back"],"secondaryMuscles":["abdominal","thigh - inner"],"steps":["Select an appropriate weight barbell and set up a bench for sitting.","Sit on the bench with feet firmly planted on the ground, slightly wider than shoulder-width apart.","Position the barbell on your upper back, using a grip slightly wider than shoulder-width.","Ensure your back is straight, chest up, and core engaged. This is your starting position.","Bend at the hips, lowering your torso forward while keeping your back flat and core tight.","Lower your torso until it is nearly parallel with the ground, maintaining control.","Engage your glutes and core as you raise your torso back to the starting position.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', 'e13cf8a4-6b48-4d9e-9a24-a30d5f98d713', 'mountain-climber', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', 100.0, '{"pk":"e13cf8a4-6b48-4d9e-9a24-a30d5f98d713","name":"Mountain Climbers","slug":"mountain-climbers","primaryMuscles":["abdominal"],"secondaryMuscles":["oblique"],"steps":["Start in a high plank position with your hands shoulder-width apart and your wrists directly under your shoulders.","Engage your core and bring your right knee towards your chest, keeping your foot off the ground.","Quickly switch legs, bringing your left knee towards your chest while extending your right leg back.","Continue alternating legs at a quick pace, as if you are running in place while in a plank position.","Keep your hips low and your shoulders over your wrists throughout the exercise.","Repeat."],"notes":""}'),
('longhaul-fitness', 'e32f671a-5bb1-4d39-8b51-d21aa62c29bc', 'zottman-curl', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', 100.0, '{"pk":"e32f671a-5bb1-4d39-8b51-d21aa62c29bc","name":"Zottman Curl","slug":"zottman-curl","primaryMuscles":["bicep","forearm - inner","forearm - outer"],"secondaryMuscles":[],"steps":["Stand up straight with a dumbbell in each hand at arm''s length. Keep your elbows close to your torso and palms facing upward.","Without moving your upper arms, curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position briefly.","While holding the dumbbells at shoulder height, rotate your wrists until your palms are facing downward.","Keep your upper arms still, exhale, and start to lower the dumbbells back to the starting position with your palms facing downward in a reverse curl motion.","Once you have reached the starting position, rotate your wrists back to the initial palms-up grip.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', 'e44bab0f-44f9-4921-a39e-453a14ea249e', 'cable-seated-one-handed-row', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"e44bab0f-44f9-4921-a39e-453a14ea249e","name":"Seated One-Handed Row – Cable","slug":"seated-one-handed-row-cable","primaryMuscles":["lat","shoulder - back","trap"],"secondaryMuscles":["bicep","forearm - inner","rotator cuff - back","rotator cuff - front"],"steps":["Sit facing a cable machine with your feet flat on the ground or footrests.","Grasp the handle with one hand, palm facing inward.","Use your feet to push your body back, creating tension on the cable, keeping your arm fully extended.","Engage your core while leaning slightly forward.","Pull the handle towards your torso, keeping your elbow close to your body.","Squeeze your shoulder blades together while leaning slightly back.","Pause for a moment at the top of the movement, feeling the contraction in your back muscles.","Slowly extend your arm back to the starting position, maintaining control throughout the movement.","Repeat for the desired number of repetitions, then switch to the other hand."],"notes":""}'),
('longhaul-fitness', 'e4ada608-1354-43e6-99cb-c7af0c76edde', 'v-up', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"e4ada608-1354-43e6-99cb-c7af0c76edde","name":"V-Up","slug":"v-up","primaryMuscles":["abdominal"],"secondaryMuscles":[],"steps":["Start by lying on your back with your arms extended above your head and your legs straight out in front of you.","Engage your core muscles and lift your legs up to a 45-degree angle while simultaneously lifting your upper body off the ground.","Reach your arms forward and try to touch your toes with your fingertips.","Hold the position long enough to flex your abdominal muscles, then slowly lower your body back down to the starting position.","Repeat."],"notes":""}'),
('longhaul-fitness', 'e64417c3-e4b6-4dcc-b902-c095067282a6', 'one-legged-balance', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"e64417c3-e4b6-4dcc-b902-c095067282a6","name":"One-Legged Balance","slug":"one-legged-balance","primaryMuscles":["calf"],"secondaryMuscles":[],"steps":["Stand tall with your feet hip-width apart.","Shift your weight onto one leg and lift the other leg off the ground.","Engage your core muscles to maintain balance.","Keep your standing leg slightly bent and your knee aligned with your toes.","Find a focal point to help you maintain balance and focus.","Hold the position for a desired amount of time.","Switch legs and repeat the exercise."],"notes":"Try this exercise with closed eyes for increased difficulty."}'),
('longhaul-fitness', 'e6e1ebd0-65dc-45cf-86e9-a79a28721fe3', 'barbell-close-grip-feet-up-bench-press', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"e6e1ebd0-65dc-45cf-86e9-a79a28721fe3","name":"Close-Grip Feet-Up Bench Press – Barbell","slug":"close-grip-feet-up-bench-press-barbell","primaryMuscles":["tricep"],"secondaryMuscles":["chest","shoulder - front"],"steps":["Lie flat on a bench with your feet up and your back pressed against the bench.","Grasp the barbell with your hands shoulder-width apart or just slightly narrower.","Unrack the barbell and hold it above your chest with your arms extended.","Lower the barbell to your chest, keeping your elbows close to your body.","Pause briefly at the bottom of the movement, then press the barbell back up to the starting position.","Repeat."],"notes":""}'),
('longhaul-fitness', 'e6f11c05-ae73-4a61-b791-4e86dd599227', 'dumbbell-one-handed-wrist-extension', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"e6f11c05-ae73-4a61-b791-4e86dd599227","name":"One-Handed Wrist Extension – Dumbbell","slug":"one-handed-wrist-extension-dumbbell","primaryMuscles":["forearm - outer"],"secondaryMuscles":[],"steps":["Hold a dumbbell with an overhand grip.","Sit on a bench with your feet shoulder-width apart.","Rest your forearm on the top of your thigh, with your palm facing down.","Slowly lift the dumbbell by extending your wrist, keeping your elbows stationary. Focus on bringing your knuckles back towards the top of your forearm.","Hold the dumbbell at the top of the movement for a moment.","Lower the dumbbell back down to the starting position by flexing your wrist towards the floor.","Repeat for the desired number of reps and then switch sides."],"notes":""}'),
('longhaul-fitness', 'e739a096-130b-4d30-a752-423d43866ec5', 'barbell-row', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', 100.0, '{"pk":"e739a096-130b-4d30-a752-423d43866ec5","name":"Row – Barbell","slug":"row-barbell","primaryMuscles":["lat","shoulder - back","trap"],"secondaryMuscles":["bicep","forearm - inner","lower back","rotator cuff - back","rotator cuff - front"],"steps":["Stand in front of a barbell with your feet shoulder-width apart.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Engage your core and pull the barbell towards your upper abs or lower chest, keeping your elbows close to your body.","Pause and squeeze your shoulder blades together for a moment at the top of the movement.","Slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', 'e8c1430a-c1c6-4813-9f5d-ceef0bc39ca7', 'dumbbell-one-handed-hammer-curl', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"e8c1430a-c1c6-4813-9f5d-ceef0bc39ca7","name":"One-Handed Hammer Curl – Dumbbell","slug":"one-handed-hammer-curl-dumbbell","primaryMuscles":["bicep"],"secondaryMuscles":["forearm - inner","forearm - outer"],"steps":["Select a dumbbell of appropriate weight and position yourself at a preacher curl bench.","Stand with one foot forward and the other back in a staggered stance.","Lean slightly forward from the hips and place the back of your upper arm (of the arm that will be curling) on the sloped part of the preacher bench, ensuring your shoulders are open to the side.","Grasp the dumbbell with a neutral grip (palm facing the wall) and fully extend your arm downwards. This is your starting position.","Brace your core and curl the dumbbell upwards toward your shoulder, keeping the wrist stable and in a neutral position throughout the movement.","Pause briefly at the top of the curl to contract the bicep, then slowly lower the dumbbell back to the starting position, controlling the weight as it descends.","Complete the desired number of repetitions before switching arms."],"notes":""}'),
('longhaul-fitness', 'e8dc87a4-79e1-4114-90a4-418a4b67359f', 'dumbbell-rear-delt-row', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"e8dc87a4-79e1-4114-90a4-418a4b67359f","name":"Rear Delt Row – Dumbbell","slug":"rear-delt-row-dumbbell","primaryMuscles":["shoulder - back","trap"],"secondaryMuscles":["forearm - inner","rotator cuff - back","shoulder - side","lat"],"steps":["Stand up straight holding a dumbbell in each hand with an overhand grip, palms facing your thighs.","Hinge forward at the hips with a slight bend in the knees, keeping your back straight and nearly parallel to the floor.","Let the dumbbells hang directly in front of you with your arms fully extended. This is the starting position.","Keep your eyes looking slightly ahead to maintain neck alignment with your spine.","Exhale as you pull the dumbbells towards your upper chest, keeping your elbows flared out. Imagine you are squeezing your shoulder blades together.","Hold the contraction for a second when the dumbbells reach the peak position when your upper arm is just beyond horizontal.","Inhale as you slowly lower the dumbbells back to the starting position in a controlled manner.","Repeat the movement for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', 'e9281159-6200-4fa6-bc8d-46314494dd7f', 'barbell-behind-neck-press', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"e9281159-6200-4fa6-bc8d-46314494dd7f","name":"Behind the Neck Press – Barbell","slug":"behind-the-neck-press-barbell","primaryMuscles":["shoulder - front","shoulder - side"],"secondaryMuscles":["trap","tricep"],"steps":["Start by standing at a barbell rack with your feet shoulder-width apart and your knees slightly bent.","Grasp the barbell with a wide grip, with your palms facing forward and your hands slightly wider than your shoulders.","Lift the barbell up and bring it behind your head, resting it on your upper traps.","Press the barbell up towards the ceiling, keeping your elbows pointed out to the sides.","Lower the barbell back down to the starting position behind your head.","Repeat."],"notes":""}'),
('longhaul-fitness', 'ea48a790-a04d-49a0-b149-a327908d2420', 'eccentric-heel-drop', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"ea48a790-a04d-49a0-b149-a327908d2420","name":"Eccentric Heel Drop","slug":"eccentric-heel-drop","primaryMuscles":["calf"],"secondaryMuscles":[],"steps":["Stand on a raised platform or step with the balls of your feet on the edge and your heels hanging off.","Raise your heels up as high as possible with both feet.","Shift your weight onto one leg and slowly lower your heel down below the platform, only using the single leg.","Use both feet to push yourself back up to the raised position.","Switch your weight to the other foot and lower yourself down single-legged.","Continue alternating sides for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', 'ea4fe379-e8e5-469d-a9ef-45f1be7c98ac', 'one-legged-hip-thrust', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', 100.0, '{"pk":"ea4fe379-e8e5-469d-a9ef-45f1be7c98ac","name":"One-Legged Hip Thrust","slug":"one-legged-hip-thrust","primaryMuscles":["glute"],"secondaryMuscles":["hamstring","thigh - inner"],"steps":["Begin by lying on your back with your knees bent and feet flat on the ground.","Extend one leg straight out, keeping it in line with your hip.","Place your hands on the ground by your sides for support.","Engage your glutes and lift your hips up towards the ceiling, keeping your extended leg straight.","Pause at the top of the movement, then slowly lower your hips back down to the ground.","Repeat for the desired number of reps, then switch legs."],"notes":"Consider variations of this exercises where your back is on a bench and your feet are still on the floor, or adding weight to your hips."}'),
('longhaul-fitness', 'ea5ae8d5-89e3-478d-9513-795e2dfd4e4a', 'exercise-ball-feet-elevated-oblique-crunch', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"ea5ae8d5-89e3-478d-9513-795e2dfd4e4a","name":"Feet-Elevated Oblique Crunch – Stability Ball","slug":"feet-elevated-oblique-crunch-stability-ball","primaryMuscles":["oblique"],"secondaryMuscles":["abdominal"],"steps":["Begin by lying on your back on the ground with your feet and calves resting on a stability ball placed by your glutes. This is the starting position.","Place your arms crossed over your chest or hands behind your ears, ensuring not to pull on your head or neck.","Engage your core muscles and rotate your right shoulder towards your left knee. Lift your shoulder as high as you can while keeping your lower back connected to the ground. Focus on contracting your right oblique muscles.","Hold the position briefly at the top of the movement while squeezing your obliques.","Lower your torso back down to the starting position in a controlled manner.","Continue alternating crunches on each side for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', 'eac4cfc0-3da3-4609-85c7-335d3d221cc9', 'barbell-sumo-squat', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"eac4cfc0-3da3-4609-85c7-335d3d221cc9","name":"Sumo Squat – Barbell","slug":"sumo-squat-barbell","primaryMuscles":["glute","hamstring","quad","thigh - inner"],"secondaryMuscles":["calf","lower back"],"steps":["Hold a barbell behind your neck, resting it on your shoulders with your elbows pointing down and your palms facing forward.","Stand with your feet wider than shoulder-width apart and toes pointed out at about a 45-degree angle.","Keep your chest up, back straight, and weight primarily on your heels. This is your starting position.","Bend your knees, keeping them in line with your toes, while lowerering your hips down until your thighs are at least parallel to the floor.","Push through your heels to extend your legs and return to the starting position."],"notes":""}'),
('longhaul-fitness', 'eb6a6487-383c-4648-b6e4-0d12bfcfa26f', 'barbell-wrist-curl', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"eb6a6487-383c-4648-b6e4-0d12bfcfa26f","name":"Wrist Curl – Barbell","slug":"wrist-curl-barbell","primaryMuscles":["forearm - inner"],"secondaryMuscles":[],"steps":["Start by sitting on a bench with your forearms resting on your knees and your palms facing up.","Hold a barbell with an underhand grip, with your hands shoulder-width apart.","Slowly lift the barbell towards your forearms by curling your wrists.","Pause for a moment at the top of the movement, then slowly lower the barbell back down to the starting position.","Repeat."],"notes":""}'),
('longhaul-fitness', 'eba49f91-3389-432f-b148-b51646b3724d', 'single-arm-hang-bar', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"eba49f91-3389-432f-b148-b51646b3724d","name":"Single-Arm Hang – Rings","slug":"single-arm-hang-rings","primaryMuscles":["forearm - inner","forearm - outer","lat"],"secondaryMuscles":["bicep","oblique","rotator cuff - back","shoulder - side","trap"],"steps":["Locate a ring that is securely anchored and can support your weight. Adjust the ring to a height where you can comfortably reach it while keeping your feet off the ground.","Stand beneath the ring and reach up with one hand to grip it tightly. Lift your feet off the ground and let your body hang freely, maintaining a straight posture.","Focus on holding the position while keeping your shoulder activated and core engaged, avoiding any twisting or rotating.","Hold for the desired amount of time or for as long as you can maintain proper form before safely lowering yourself."],"notes":""}'),
('longhaul-fitness', 'ebe6214a-44c8-47a6-b4d5-c05d4088fc76', 'barbell-decline-bench-press', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"ebe6214a-44c8-47a6-b4d5-c05d4088fc76","name":"Decline Bench Press – Barbell","slug":"decline-bench-press-barbell","primaryMuscles":["chest"],"secondaryMuscles":["shoulder - front","tricep"],"steps":["Set up the decline bench at a decline angle of your choice.","Lie down on the bench with your feet secured under the foot pads.","Grip the barbell with an overhand grip slightly wider than shoulder-width apart.","Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Inhale and slowly lower the barbell towards your lower chest.","Pause for a moment when the barbell is just above your chest.","Exhale and push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', 'ecd9d14f-93e9-4160-b0a9-8d4652732f50', 'single-leg-romanian-deadlift-jump', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"ecd9d14f-93e9-4160-b0a9-8d4652732f50","name":"Single-Leg Romanian Deadlift Jump","slug":"single-leg-romanian-deadlift-jump","primaryMuscles":["calf","glute","hamstring","quad"],"secondaryMuscles":["abdominal","lower back"],"steps":["Stand on your right leg, keeping a slight bend in the right knee. Bend your right arm in front of your chest and keep your left arm straight down by your side. This is your starting position.","Lean forward at your hips, extending your left leg behind you for balance. Keep your back straight, bend your left arm bent in front of your chest, and straighten your right arm behind you in rough alignment with your left leg.","Lower your torso and lift your left leg until your body forms a ''T'' shape, or go as low as your flexibility allows.","Push through the heel of your right foot and prepare to explode upwards. Thrust your left arm down towards the ground while bringing your right arm up towards your chest to gain momentum for the jump.","Jump upwards, driving force through your right leg and using the motion of your arms to enhance the lift.","Land softly on your right leg, absorbing the impact with a slight bend in your knee, and reset your arms to their starting positions.","Repeat for the desired number of repetitions on one leg before switching to the other."],"notes":"To increase difficulty, try to remain balanced on the working leg throughout the set."}'),
('longhaul-fitness', 'ed36669e-3f5c-411d-8eab-8fb757a21e93', 'medicine-ball-rotational-throw', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"ed36669e-3f5c-411d-8eab-8fb757a21e93","name":"Rotational Throw – Medicine Ball","slug":"rotational-throw-medicine-ball","primaryMuscles":["oblique"],"secondaryMuscles":["abdominal","shoulder - front"],"steps":["Start by standing about arms-length away from the wall with your feet shoulder-width apart.","Hold a medicine ball with both hands at chest height.","Rotating your core and upper body towards the wall, explosively throw the ball against the wall.","Catch the ball as it rebounds off the wall and rotate your body away from the wall.","Repeat for the desired number of reps and then switch sides."],"notes":""}'),
('longhaul-fitness', 'edb21df1-0a7a-49f8-94e3-fa47138af935', 'cable-tricep-pushdown', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"edb21df1-0a7a-49f8-94e3-fa47138af935","name":"Tricep Pushdown – Cable With Bar","slug":"tricep-pushdown-cable-with-bar","primaryMuscles":["tricep"],"secondaryMuscles":[],"steps":["Attach a straight bar to the high pulley of a cable machine.","Stand facing the machine with your feet shoulder-width apart and your knees slightly bent.","Grasp the bar with an overhand grip, with your hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary.","Exhale and push the bar down until your arms are fully extended.","Pause for a moment, then inhale and slowly return the bar to the starting position.","Repeat."],"notes":""}'),
('longhaul-fitness', 'edbc1829-75f7-4ea7-96db-0a6b3b7f994f', 'band-one-arm-row-lunge', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"edbc1829-75f7-4ea7-96db-0a6b3b7f994f","name":"One-Arm Row Lunge – Band","slug":"one-arm-row-lunge-band","primaryMuscles":["glute","lat","trap","quad"],"secondaryMuscles":["calf"],"steps":["Anchor a resistance band at the level of your belly button in front of you.","Grip the band with your target arm and start in a lunge position with the front leg opposite the target arm.","Simultaneously pull the band through a row motion while transitioning into a single leg stand on the front leg.","Raise the knee of the same side leg as the target arm to hip height as you pull the band, squeezing your back muscles.","Reverse the motion by lowering the knee and returning to the starting lunge position.","Repeat the movement for your desired number of repetitions."],"notes":""}'),
('longhaul-fitness', 'edd0f4bb-7f54-4f56-a1ee-5e5547cae18c', 'shoulder-teepee-dowel', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/flexibility.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"edd0f4bb-7f54-4f56-a1ee-5e5547cae18c","name":"Shoulder Teepee – Dowel","slug":"shoulder-teepee-dowel","primaryMuscles":["shoulder - back","shoulder - front"],"secondaryMuscles":["tricep","bicep","forearm - inner","forearm - outer"],"steps":["Grab a dowel or broomstick with hands wider than shoulder-width apart, holding it parallel to the ground in front of your waist.","Raise one end of the dowel above your head and then behind your back, keeping the other hand at hip level.","Lower the dowel so that it''s parallel to the ground behind your back.","Raise the other hand to pull the dowel up and over your body bringing it parallel to the ground in front of you again.","Alternate directions, performing the same steps going the other direction.","Continue alternating the movement on each side for the desired amount of time."],"notes":""}'),
('longhaul-fitness', 'ee2f03bd-b805-49fb-b216-c118e226b95c', 'rowing-seated-narrow-grip', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"ee2f03bd-b805-49fb-b216-c118e226b95c","name":"Close Grip Seated Row","slug":"close-grip-seated-row","primaryMuscles":["lat","shoulder - back","trap"],"secondaryMuscles":["bicep","forearm - inner","rotator cuff - back","rotator cuff - front"],"steps":["Adjust the cable machine to the appropriate weight and attach a V-bar handle to the cable.","Sit on the machine with your feet flat on the footrests and your knees slightly bent.","Grasp the V-bar handle with an overhand grip, with your hands close together.","Keep your back straight and your shoulders down and back.","Pull the V-bar handle towards your abdomen, keeping your elbows close to your body.","Squeeze your shoulder blades together at the end of the movement.","Slowly release the handle back to the starting position.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', 'ef429bfb-4fe4-414c-a1d5-65e9668c5da9', 'smith-machine-bench-press', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"ef429bfb-4fe4-414c-a1d5-65e9668c5da9","name":"Bench Press – Smith Machine","slug":"bench-press-smith-machine","primaryMuscles":["chest","shoulder - front"],"secondaryMuscles":["tricep"],"steps":["Set up a bench under a Smith machine so that the bar is over your chest while lying on the bench.","Lie down on the bench with your feet flat on the floor and your back pressed against the bench.","Extend your arms and grip the bar with your hands slightly wider than shoulder-width apart, palms facing forward.","Unrack the bar by straightening your arms and lifting it off the rack.","Lower the bar slowly towards your chest, keeping your elbows wide.","Pause for a moment when the bar touches your chest.","Push the bar back up to the starting position by extending your arms fully.","Repeat the movement for the desired number of repetitions.","Once finished, carefully rack the bar back onto the Smith machine."],"notes":""}'),
('longhaul-fitness', 'ef5fd2d5-95b0-429e-96aa-bdf8fc3df367', 'barbell-shoulder-press', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"ef5fd2d5-95b0-429e-96aa-bdf8fc3df367","name":"Shoulder Press – Barbell","slug":"standing-shoulder-press-barbell","primaryMuscles":["shoulder - front"],"secondaryMuscles":["shoulder - side","tricep"],"steps":["Start by standing with your feet shoulder-width apart, looking at a racked, weighted barbell.","Raise the barbell to shoulder height, palms facing forward, and elbows bent.","Press the barbell upward until your arms are fully extended above your head.","Pause for a moment at the top of the movement, then slowly lower the barbell back down to shoulder height.","Repeat."],"notes":""}'),
('longhaul-fitness', 'eff261cc-68a0-4867-92d2-dc099abf7d99', 'barbell-lunge', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', 100.0, '{"pk":"eff261cc-68a0-4867-92d2-dc099abf7d99","name":"Lunge – Barbell","slug":"lunge-barbell","primaryMuscles":["glute","quad","thigh - inner"],"secondaryMuscles":[],"steps":["Start by standing with your feet hip-width apart and your back straight.","Hold a barbell across your upper back, resting it on your shoulders.","Take a step forward with your right foot, keeping your core engaged and your chest lifted.","Bend both knees to lower your body towards the ground, making sure your front knee does not go past your toes.","Lower your body until your front thigh is parallel to the ground, and your back knee is hovering just above the floor.","Push through your front heel to return to the starting position.","Repeat the movement on the other side by stepping forward with your left foot.","Continue alternating legs for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', 'f08b4ec4-b3ee-4c67-adcf-d292f43f1e3e', 'machine-hack-squat', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', 100.0, '{"pk":"f08b4ec4-b3ee-4c67-adcf-d292f43f1e3e","name":"Hack Squat – Machine","slug":"hack-squat-machine","primaryMuscles":["glute","quad","thigh - inner"],"secondaryMuscles":[],"steps":["Adjust the seat height and foot platform of the machine to your desired position.","Sit on the machine with your back against the pad and grasp the handles with an overhand grip.","Engage your core throughout the exercise.","Bend your knees and lower your body down, keeping your back straight and your heels on the foot platform.","Continue descending until your thighs are parallel to the foot platform or as low as your flexibility allows.","Push through your heels and extend your legs to return to the starting position.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', 'f15d4766-7fa4-4802-8146-c53f45a64970', 'seated-crossed-leg-forward-stretch', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/flexibility.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"f15d4766-7fa4-4802-8146-c53f45a64970","name":"Seated Crossed Leg Forward Stretch","slug":"seated-crossed-leg-forward-stretch","primaryMuscles":["glute","lower back"],"secondaryMuscles":["hamstring","thigh - inner","thigh - outer"],"steps":["Sit on the floor with your legs crossed.","Place your hands on the floor beside your hips.","Begin to lean forward, leading with your hands.","Crawl your hands forward to deepen the stretch.","Hold the stretch for the desired time while focusing on relaxed breaths."],"notes":""}'),
('longhaul-fitness', 'f1c844bd-28c8-4191-9b2a-d0233e6941e1', 'barbell-wrist-curl-behind-back', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"f1c844bd-28c8-4191-9b2a-d0233e6941e1","name":"Wrist Curl Behind the Back – Barbell","slug":"wrist-curl-behind-the-back-barbell","primaryMuscles":["forearm - inner"],"secondaryMuscles":[],"steps":["Stand with your feet shoulder-width apart and your knees slightly bent.","Hold a barbell with an overhand grip behind your back, with your palms facing away from your body.","Keep your elbows close to your body and your upper arms stationary.","Curl the barbell up towards your forearms, keeping your wrists straight.","Pause at the top of the movement and squeeze your forearms.","Slowly lower the barbell back down to the starting position.","Repeat."],"notes":""}'),
('longhaul-fitness', 'f2420af5-d84f-4152-81a0-8c44aeaba8a6', 'half-air-squat', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"f2420af5-d84f-4152-81a0-8c44aeaba8a6","name":"Half Air Squat","slug":"half-air-squat","primaryMuscles":["glute","quad","thigh - inner"],"secondaryMuscles":["calf"],"steps":["Stand with your feet shoulder-width apart, toes pointing slightly outward.","Engage your core and keep your chest lifted throughout the exercise.","Lower your body by bending your knees and pushing your hips back.","Continue lowering until your thighs approach parallel to the ground but do not go any deeper.","Pause for a moment at the bottom of the squat.","Push through your heels and extend your knees and hips to return to the starting position.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', 'f25454d4-851d-41aa-b015-afc6dc734031', 'power-snatch', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"f25454d4-851d-41aa-b015-afc6dc734031","name":"Power Snatch","slug":"power-snatch","primaryMuscles":["glute","lower back","quad","thigh - inner"],"secondaryMuscles":["calf","forearm - inner","hamstring","trap"],"steps":["Start with feet hip-width apart, toes slightly turned out, with a loaded barbell on the ground in front of you.","Hold the barbell with a wide grip, hands outside the legs.","Bend at the knees and hips, keeping the back straight and chest up.","Explosively extend the hips, knees, and ankles, pulling the barbell upwards.","As the barbell reaches hip level, quickly drop under it by pulling yourself down into a squat position.","Catch the barbell overhead with arms fully extended, in a deep squat position.","Stand up by extending the hips and knees, keeping the barbell overhead.","Lower the barbell back to the starting position by reversing the movement."],"notes":""}'),
('longhaul-fitness', 'f292c579-0f86-4080-8f84-bc42ab3e3661', 'machine-side-lateral-raise', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"f292c579-0f86-4080-8f84-bc42ab3e3661","name":"Lateral Raise – Machine","slug":"lateral-raise-machine","primaryMuscles":["shoulder - side"],"secondaryMuscles":["shoulder - front"],"steps":["Adjust the seat height so that the handles are at shoulder level.","Sit on the machine with your back against the pad and your feet flat on the floor.","Grasp the handles with an overhand grip and keep your elbows slightly bent.","Exhale and raise your arms out to the sides until they are parallel to the floor.","Pause for a moment and then inhale as you slowly lower the handles back to the starting position.","Repeat."],"notes":""}'),
('longhaul-fitness', 'f2fad514-fb0f-4467-8b3d-b65655794591', 'one-arm-prone-rotator-cuff-external-rotation', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/flexibility.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"f2fad514-fb0f-4467-8b3d-b65655794591","name":"One-Arm Prone Rotator Cuff External Rotation","slug":"one-arm-prone-rotator-cuff-external-rotation","primaryMuscles":["rotator cuff - back"],"secondaryMuscles":["shoulder - back"],"steps":["Lie on your belly on a padded surface, such as a yoga mat.","Extend one arm out to the side, in line with your shoulder. Bend your elbow to a 90-degree angle to form a ''cactus'' or ''goalpost'' shape, with your forearm and palm resting on the floor.","Keep your elbow pinned to the floor, ensuring it stays in contact with the floor throughout the movement.","Rotate your hand towards the ceiling as high as possible, keeping the elbow pinned.","Hold the position for the desired time.","Repeat exercise on the other side."],"notes":""}'),
('longhaul-fitness', 'f3b288b8-bdc2-4b6f-9dae-dfee16fbd3f1', 'single-leg-v-up', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"f3b288b8-bdc2-4b6f-9dae-dfee16fbd3f1","name":"Single-Leg V-Up","slug":"single-leg-v-up","primaryMuscles":["abdominal","oblique"],"secondaryMuscles":[],"steps":["Lie flat on your back on a mat with your arms extended overhead and your legs fully extended.","Lift one leg towards a 60-degree angle with the floor while simultaneously raising your upper body, reaching your hands towards the raised foot.","Keep both legs straight, with the non-moving leg remaining on the floor.","Contract your abdominals as you lift your body, aiming to touch your toes with your hands.","Hold the V position momentarily, maintaining balance and stability.","Slowly lower your upper body and leg back to the starting position.","Repeat the movement with the other leg, alternating legs with each repetition."],"notes":""}'),
('longhaul-fitness', 'f3f3df04-9b8a-43a3-84fe-2a7bd4330a0b', 'perfect-hang', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"f3f3df04-9b8a-43a3-84fe-2a7bd4330a0b","name":"Perfect Hang","slug":"perfect-hang","primaryMuscles":["forearm - inner","forearm - outer","lat"],"secondaryMuscles":["abdominal","bicep","chest","oblique","trap"],"steps":["Grasp a pull-up bar with both hands at shoulder-width apart using an overhand grip.","Hang from the bar with your feet off the ground and your arms fully extended.","Engage your shoulder blades by pulling them back and down to stabilize your shoulders and upper back.","Lean back slightly to bring your chest parallel to the ground and your torso at a 45° angle to the ground.","Curl your legs backwards. Imagine your body as the curve on the letter \"D\" if you were to see yourself from the side.","Breathe deeply and hold the hang for as long as you can manage comfortably, ensuring your shoulder blades remain engaged."],"notes":""}'),
('longhaul-fitness', 'f41cdfa8-b3f5-4735-9ec9-2e45d27771c0', 'hang-snatch', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"f41cdfa8-b3f5-4735-9ec9-2e45d27771c0","name":"Hang Snatch","slug":"hang-snatch","primaryMuscles":["glute","lower back","quad","thigh - inner"],"secondaryMuscles":["calf","forearm - inner","hamstring","trap"],"steps":["Start standing up with the barbell in an overhand grip, hands slightly wider than shoulder-width apart, resting against your thighs.","Quickly drop down into a quarter squat, then explosively extend your hips, knees, and ankles to jump upwards.","As you jump, pull the bar upwards with your arms, keeping it close to your body and using your momentum to bring it up to shoulder height.","Rotate your elbows around and under the bar, catching it in an overhead squat position with your arms fully extended and your feet shoulder-width apart.","Stand up to complete the lift","Lower the bar back down to the ground with control.","Repeat."],"notes":""}'),
('longhaul-fitness', 'f42b8e31-a3e6-44e4-85fb-14508bf84130', 'cable-one-handed-high-row', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"f42b8e31-a3e6-44e4-85fb-14508bf84130","name":"One-Handed High-Cable Row","slug":"one-handed-high-cable-row","primaryMuscles":["lat"],"secondaryMuscles":["bicep","forearm - inner","rotator cuff - back","shoulder - back"],"steps":["Adjust the cable machine pulley to a position above your head and attach a single handle.","Stand facing the cable machine with your feet shoulder-width apart.","Grab the handle with one hand, palm facing down.","Step back slightly from the cable machine to create tension on the cable. Stretch your arm out in front of you. This is your starting position.","Pull the handle towards your side, keeping your elbow close to your body. Rotate your palm to face your torso as you pull.","Squeeze your back muscles when your hand is near your torso.","Slowly extend your arm to return the handle to the starting position while controlling the weight.","Repeat for the desired number of repetitions before switching arms."],"notes":""}'),
('longhaul-fitness', 'f45f9e24-fc85-4974-b870-93b6479c0481', 'medicine-ball-rotational-slam', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"f45f9e24-fc85-4974-b870-93b6479c0481","name":"Rotational Slam – Medicine Ball","slug":"rotational-slam-medicine-ball","primaryMuscles":["abdominal","lat","oblique","shoulder - front"],"secondaryMuscles":["calf","chest","forearm - inner","forearm - outer","glute","hamstring","lower back","quad","rotator cuff - back","rotator cuff - front","shoulder - side","tricep"],"steps":["Stand with your feet shoulder-width apart and knees slightly bent, holding the medicine ball with both hands near one hip.","Begin the exercise by lifting the medicine ball in a circular motion on the same side, raising it up and over your head.","Continue the circular motion bringing the ball down with force on the opposite side.","As you bring the ball down, rotate your hips towards the opposite side, pivoting on the toes of one foot, while the other leg bends into a small squat.","Release the medicine ball towards the ground as you near the opposite hip from where you started, channeling maximum force through the slam.","Retrieve the medicine ball, return to the starting position on the opposite hip, and perform the exercise on the other side.","Repeat the exercise for the desired number of repetitions."],"notes":"Keep your arms extended, elbows slightly bent, throughout the exercise. Focus on creating big circles with your arms, avoiding the tendency to create smaller, easier circles, close to your chest."}'),
('longhaul-fitness', 'f4d35499-bbfe-4d37-b89d-8229873bdb45', 'barbell-split-squat', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"f4d35499-bbfe-4d37-b89d-8229873bdb45","name":"Split Squat – Barbell","slug":"split-squat-barbell","primaryMuscles":["glute","hamstring","quad"],"secondaryMuscles":["calf","lower back"],"steps":["Set up a barbell on a squat rack at shoulder height and load it with the desired weight.","Position yourself under the barbell, placing it comfortably across your upper back. Hold the barbell with both hands just outside shoulder-width.","Engage your core, step back and away from the rack, and position one foot forward and the other foot back, bending your knees.","Adjust your position so your back toe is on the ground and your forward knee is slightly bent. This is your starting position.","Lower your hips by bending both knees until your back knee is just above the ground. Keep your chest lifted and your front knee over your ankle.","Push through your front heel and extend your legs to return to the starting position.","Complete the desired number of repetitions and switch to the other side."],"notes":""}'),
('longhaul-fitness', 'f5c582d5-955e-4859-9635-1317c63e3015', 'block-snatch', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"f5c582d5-955e-4859-9635-1317c63e3015","name":"Block Snatch","slug":"block-snatch","primaryMuscles":["glute","lower back","quad","thigh - inner"],"secondaryMuscles":["calf","forearm - inner","hamstring","trap"],"steps":["Set up the blocks so the barbell rests somewhere between mid-shin to mid-thigh height.","Stand with your feet hip-width apart, in front of the bar.","Bend at the hips and knees, and grip the bar with a wide overhand grip.","Position your shoulders slightly over the bar, back straight, eyes focused ahead. This is your starting position.","Explosively extend your hips and knees, simultaneously shrugging your shoulders upward.","Pull your body under the bar rapidly, rotating your wrists around the bar as you drop into a squat position.","Catch the bar overhead with arms fully extended, while in a deep squat.","Stand up by straightening your legs, keeping the bar steady overhead.","Lower the bar back to the blocks carefully.","Repeat for the desired number of repetitions."],"notes":"Lower the barbell''s starting height to increase the difficulty of the exercise. Raise the barbell''s starting height for a easier lift."}'),
('longhaul-fitness', 'f5f0a39a-5bdc-480f-a17c-cb64b6cbafc6', 'kettlebell-swing', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'exact', 100.0, '{"pk":"f5f0a39a-5bdc-480f-a17c-cb64b6cbafc6","name":"Kettlebell Swing","slug":"kettlebell-swing","primaryMuscles":["glute","lower back"],"secondaryMuscles":["forearm - inner","hamstring","thigh - inner","trap"],"steps":["Stand with your feet shoulder-width apart, toes slightly turned out.","Hold the kettlebell with both hands between your thighs, maintaining an overhand grip, arms hanging naturally extended towards the floor.","Slightly bend your knees and hinge at the hips to push your buttocks back while keeping a flat back.","Initiate the swing by snapping your hips forward, driving the kettlebell upward with your glutes and hamstrings.","Swing the kettlebell to chest height with arms extended; keep your core engaged.","Allow the kettlebell to descend by hinging at the hips again, controlling the downward movement.","Use the momentum of the descending kettlebell to immediately begin the next swing.","Perform the desired number of repetitions, maintaining a rhythmic and controlled pace.","To finish, allow the kettlebell to swing back down one last time, slowing the swing to a stop safely."],"notes":""}'),
('longhaul-fitness', 'f7b65315-115a-4161-8b6b-3c9557c78098', 'hang-power-snatch', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"f7b65315-115a-4161-8b6b-3c9557c78098","name":"Hang Power Snatch","slug":"hang-power-snatch","primaryMuscles":["glute","lower back","quad","thigh - inner"],"secondaryMuscles":["calf","forearm - inner","hamstring","trap"],"steps":["Stand with feet hip-width apart, holding a barbell with an overhand grip just outside of your thighs.","Lower into a quarter squat position, keeping your back straight and chest up.","Explosively extend your hips, knees, and ankles, jumping upward.","As you jump, pull the barbell upward, keeping it close to your body.","As the barbell reaches chest height, quickly drop into a quarter squat position and rotate your elbows under the barbell, keeping your arms straight.","Catch the barbell overhead with arms fully extended, in a quarter squat position.","Stand up, fully extending your hips and knees, while keeping the barbell overhead.","Lower the barbell back down to the starting position, and repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', 'f83df073-8d24-4bd5-84b9-96b62aefd860', 'one-leg-bent-knee-calf-stretch-yoga-block', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/flexibility.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"f83df073-8d24-4bd5-84b9-96b62aefd860","name":"One-Leg Bent Knee Calf Stretch – Yoga Block","slug":"one-leg-bent-knee-calf-stretch-yoga-block","primaryMuscles":["calf"],"secondaryMuscles":[],"steps":["Stand with one foot slightly ahead of the other as if you''d just taken one step forward.","Place your forward foot on a yoga block, in the loop of a kettlebell, or anything stable you can step on with the ball of your foot at ankle height. Ensure your heel remains on the ground.","Lean forward with both legs to create a stretch in the calf of the front leg.","Bend the knee of the front leg to target the soleus muscle in your calf.","Hold the stretch for the desired time and switch to the other side."],"notes":""}'),
('longhaul-fitness', 'f93ff5e0-0d43-4771-8c63-63f27c66e659', 'plate-front-raise', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"f93ff5e0-0d43-4771-8c63-63f27c66e659","name":"Plate Front Raise","slug":"plate-front-raise","primaryMuscles":["shoulder - front"],"secondaryMuscles":["shoulder - side"],"steps":["Stand with your feet shoulder-width apart and hold a weight plate with both hands in front of your thighs.","Keep your arms straight and slowly raise the weight plate up to shoulder level, making sure to keep your core engaged and your back straight.","Pause for a moment at the top of the movement, then slowly lower the weight plate back down to the starting position.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', 'f954e30f-cb89-488b-99da-4358244fd815', 'machine-shoulder-press', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'normalized', 100.0, '{"pk":"f954e30f-cb89-488b-99da-4358244fd815","name":"Shoulder Press – Machine","slug":"shoulder-press-machine","primaryMuscles":["shoulder - front"],"secondaryMuscles":["shoulder - side","tricep"],"steps":["Adjust the seat height so that the handles are at shoulder level.","Sit on the machine with your back against the pad and your feet flat on the floor.","Grasp the handles with an overhand grip and push them upward until your arms are fully extended.","Slowly lower the handles back down to shoulder level, keeping your elbows slightly bent.","Repeat for desired number of repetitions."],"notes":""}'),
('longhaul-fitness', 'fa1e4680-bb98-42cd-b638-8d0ef4478b3b', 'kettlebell-horn-grip-bicep-curl', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"fa1e4680-bb98-42cd-b638-8d0ef4478b3b","name":"Horn Grip Bicep Curl – Kettlebell","slug":"horn-grip-bicep-curl-kettlebell","primaryMuscles":["bicep"],"secondaryMuscles":["forearm - inner","forearm - outer"],"steps":["Choose an appropriate kettlebell weight. Hold it by the horns (sides of the handle) with both hands, palms facing each other. Stand with your feet shoulder-width apart. This is your starting position.","Keep your elbows close to your torso and slowly curl the kettlebell up towards your chest by bending your elbows.","Keep your upper arms stationary and only move your forearms.","Squeeze your biceps at the top of the movement.","Lower the kettlebell back to the starting position in a controlled manner.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', 'fae8985f-1235-4791-8b40-d0982797325f', 'hang-power-clean-and-jerk', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"fae8985f-1235-4791-8b40-d0982797325f","name":"Hang Power Clean and Jerk","slug":"hang-power-clean-and-jerk","primaryMuscles":["glute","lower back","shoulder - front"],"secondaryMuscles":["calf","hamstring","shoulder - side","quad","trap","tricep"],"steps":["Approach the barbell on the floor and stand with your feet shoulder-width apart.","Bend at the hips and knees to grip the barbell with hands slightly wider than shoulder-width apart with an overhand grip.","Lift the barbell in front of your thighs by extending your hips and knees to stand tall, keeping your arms straight. This is your starting position.","Bend your knees and slightly hinge forward to lower the bar just above your knees, keeping your back straight.","Explosively extend your hips, knees, and ankles to lift the bar, shrug your shoulders, and begin to pull yourself under the bar.","Catch the bar at your shoulders in a partial squat position, standing up tall to complete the power clean.","With the barbell resting on your shoulders, dip slightly at the knees, then drive up through your legs to push the bar overhead.","Lock out your arms overhead and stand straight.","With control, lower the weight to your shoulders, then back to the starting position.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', 'fb2f3298-0414-4426-a4a7-8a0b7d62f90b', 'decline-sit-up', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"fb2f3298-0414-4426-a4a7-8a0b7d62f90b","name":"Decline Sit-Up","slug":"decline-sit-up","primaryMuscles":["abdominal"],"secondaryMuscles":["oblique"],"steps":["Position yourself on a decline bench with your feet securely locked in place.","Place your hands behind your head or across your chest.","Engage your core and slowly lift your upper body towards your knees.","Pause briefly at the top of the movement, then slowly lower your upper body back down to the starting position.","Repeat."],"notes":""}'),
('longhaul-fitness', 'fc2c3807-61c2-4b79-a5db-d20820a1892e', 'one-leg-elevated-pigeon-stretch', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/flexibility.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"fc2c3807-61c2-4b79-a5db-d20820a1892e","name":"One-Leg Elevated Pigeon Stretch","slug":"one-leg-elevated-pigeon-stretch","primaryMuscles":["glute"],"secondaryMuscles":["hamstring"],"steps":["Place your front leg on an elevated surface, such as a bench, with the shin flat on the surface and the knee rotated outward from your hip.","Extend your back leg straight behind you on the ground.","Drop your front hip down toward the ground.","Support your upper body with your hands on the ground to maintain balance.","Keep your spine neutral and avoid leaning forward or back.","Take deep breaths, holding the stretch for the desired time, and switch sides."],"notes":""}'),
('longhaul-fitness', 'fdaa0f69-50af-4f17-8a40-88d7006860a4', 'squat-jerk', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"fdaa0f69-50af-4f17-8a40-88d7006860a4","name":"Squat Jerk","slug":"squat-jerk","primaryMuscles":["glute","lower back","quad","shoulder - front","thigh - inner"],"secondaryMuscles":["calf","shoulder - side","trap","tricep"],"steps":["Start with your feet shoulder-width apart and toes slightly turned out.","Get into position by cleaning the barbell or lifting it from a rack at shoulder height with an overhand grip.","Drop your body into a deep squat position, keeping your chest up and back straight, while pushing the barbell above your head, extending your arms fully.","As you reach the bottom of the squat, explosively drive through your legs and hips to stand up.","Lock out your elbows and stabilize the weight overhead.","Lower the weight back down to shoulder height and repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', 'fdb2513d-bed3-49e0-86fc-af9e86d2cd78', 'standing-snatch-grip-behind-neck-press', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"fdb2513d-bed3-49e0-86fc-af9e86d2cd78","name":"Standing Snatch Grip Behind the Neck Press","slug":"standing-snatch-grip-behind-the-neck-press","primaryMuscles":["shoulder - front","shoulder - side"],"secondaryMuscles":["trap","tricep"],"steps":["Stand with your feet shoulder-width apart and grip the barbell with a wide snatch grip.","Position the barbell behind your neck, resting it on your upper traps.","Engage your core and keep your back straight.","Press the barbell overhead by extending your arms and pushing the weight up.","Lock out your elbows at the top of the movement.","Lower the barbell back down to the starting position behind your neck.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', 'fdd30b0a-af69-4cd6-af02-25968b615b36', 'barbell-overhead-tricep-extension', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"fdd30b0a-af69-4cd6-af02-25968b615b36","name":"Overhead Tricep Extension – Barbell","slug":"overhead-tricep-extension-barbell","primaryMuscles":["tricep"],"secondaryMuscles":[],"steps":["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip.","Bring the barbell behind your head, keeping your elbows close to your ears.","Extend your arms upward, straightening your elbows and lifting the barbell above your head.","Pause briefly at the top of the movement, then slowly lower the barbell back behind your head.","Repeat for the desired number of repetitions."],"notes":""}'),
('longhaul-fitness', 'ff2c5e56-139c-4e79-913c-8479a0b20972', 'seated-oblique-twist', 'https://github.com/longhaul-fitness/exercises/blob/2c77d52a8c412eb2e8614e2d2f4f2f6edcea2b42/strength.json', 'MIT', 'Longhaul Fitness', 'new', NULL, '{"pk":"ff2c5e56-139c-4e79-913c-8479a0b20972","name":"Seated Oblique Twist","slug":"seated-oblique-twist","primaryMuscles":["oblique"],"secondaryMuscles":["abdominal"],"steps":["Sit on a workout mat or bench with your knees bent and feet flat on the floor.","Engage your core muscles by drawing your navel towards your spine.","Hold a dumbbell or medicine ball with both hands close to your chest.","Keeping your back straight, lean slightly back to engage your abdominal muscles.","Exhale and rotate your torso to the right, bringing the weight towards your right hip.","Inhale as you return to the starting position.","Exhale and rotate your torso to the left, bringing the weight towards your left hip.","Inhale as you return to the starting position.","Repeat the twisting motion for the desired number of repetitions on each side."],"notes":""}'),
