('wger', '1348', NULL, 'https://wger.de/en/exercise/1348/view', 'CC-BY-SA-4.0', 'Anastasious', NULL, NULL, '{"exercise":{"model":"exercises.exercise","pk":1348,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Anastasious","license_author_url":"","license_derivative_source_url":"","uuid":"50a8f1f6-6772-4319-be9d-3bad1374dadf","category":12,"variation_group":null,"created":"2024-07-23T11:15:05.033Z","last_update":"2024-07-23T11:15:05.033Z","muscles":[],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2318,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Anastasious","license_author_url":"","license_derivative_source_url":"","description":"<ul>\n<li>Muskulatur anspannen</li>\n<li>Hintern ein wenig anheben</li>\n<li>Kontrollierte Bewegung</li>\n<li>Langsame Bewegung</li>\n<li>Kein Schwung holen</li>\n<li>Oberkörper gerade halten</li>\n</ul>\n","description_source":"* Muskulatur anspannen\n* Hintern ein wenig anheben\n* Kontrollierte Bewegung\n* Langsame Bewegung\n* Kein Schwung holen\n* Oberkörper gerade halten","name":"Lower Back Extensions","created":"2024-07-23T11:15:05.216Z","last_update":"2026-04-13T18:58:26.817Z","language":2,"uuid":"991b4fa5-8814-4374-b275-b6abdfca7c99","exercise":1348}}],"aliases":[],"comments":[]}'),
('wger', '1353', NULL, 'https://wger.de/en/exercise/1353/view', 'CC-BY-SA-4.0', 'Anastasious', NULL, NULL, '{"exercise":{"model":"exercises.exercise","pk":1353,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Anastasious","license_author_url":"","license_derivative_source_url":"","uuid":"587af8f1-516b-44c3-8660-70f262e1bef8","category":11,"variation_group":null,"created":"2024-07-23T11:38:58.433Z","last_update":"2024-07-23T11:38:58.433Z","muscles":[],"muscles_secondary":[],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2323,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Anastasious","license_author_url":"","license_derivative_source_url":"","description":"<ul>\n<li>Muskulatur anspannen</li>\n<li>Füße Breitpositionieren</li>\n<li>Kontrollierte Bewegung</li>\n<li>Langsame Bewegung</li>\n<li>Gewichte zur unteren Brust/ Bauch führen</li>\n</ul>\n","description_source":"* Muskulatur anspannen\n* Füße Breitpositionieren\n* Kontrollierte Bewegung\n* Langsame Bewegung\n* Gewichte zur unteren Brust/ Bauch führen","name":"Dumbbell Hex Press","created":"2024-07-23T11:38:58.564Z","last_update":"2026-04-13T18:58:26.422Z","language":2,"uuid":"2d730c08-fbf1-4e88-a446-f36f4b755ee1","exercise":1353}}],"aliases":[],"comments":[]}'),
