('wger', '1366', 'dumbbell-split-squat', 'https://wger.de/en/exercise/1366/view', 'CC-BY-SA-4.0', 'Anastasious; admin', 'normalized', 100.0, '{"exercise":{"model":"exercises.exercise","pk":1366,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Anastasious","license_author_url":"","license_derivative_source_url":"","uuid":"8a3e08ab-4e97-4aee-897a-60d8693b9b43","category":9,"variation_group":null,"created":"2024-08-17T17:24:17.852Z","last_update":"2024-08-17T17:24:17.852Z","muscles":[],"muscles_secondary":[],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2333,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Anastasious","license_author_url":"","license_derivative_source_url":"","description":"<ul>\n<li>Controlled execution</li>\n<li>No momentum</li>\n<li>Execute slowly</li>\n</ul>\n","description_source":"* Controlled execution\n* No momentum\n* Execute slowly","name":"Dumbbell Split Squat","created":"2024-08-17T17:24:17.962Z","last_update":"2026-04-13T18:58:26.440Z","language":2,"uuid":"73d152bd-fde4-4e1d-8b2c-778a11cf27e4","exercise":1366}},{"model":"exercises.translation","pk":2655,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"admin","license_author_url":"","license_derivative_source_url":"","description":"<ul>\n<li>Kontrollierte Ausführung</li>\n<li>Kein Schwung holen</li>\n<li>Langsam Ausführen</li>\n</ul>\n","description_source":"* Kontrollierte Ausführung\n* Kein Schwung holen\n* Langsam Ausführen","name":"Dumbbell Split Squat","created":"2025-09-09T22:45:02.311Z","last_update":"2026-04-13T18:58:26.441Z","language":1,"uuid":"c47643b8-78a2-4fb2-b750-d9223c5b663a","exercise":1366}}],"aliases":[],"comments":[]}'),
