('wger', '1373', 'box-jump', 'https://wger.de/en/exercise/1373/view', 'CC-BY-SA-4.0', 'tekknokrat@gmx.de; admin', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1373,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"tekknokrat@gmx.de","license_author_url":"","license_derivative_source_url":"","uuid":"002c6a4f-28ac-4b07-8e94-053e5b05d52b","category":15,"variation_group":null,"created":"2024-09-08T07:32:22.298Z","last_update":"2024-09-08T07:32:22.298Z","muscles":[8],"muscles_secondary":[7],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2339,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"tekknokrat@gmx.de","license_author_url":"","license_derivative_source_url":"","description":"<p>Jump from a standing position onto the box, stretch your body, then step down again (do not jump)</p>\n","description_source":"Jump from a standing position onto the box, stretch your body, then step down again (do not jump)","name":"box jumps","created":"2024-09-08T07:32:22.465Z","last_update":"2026-04-13T18:58:27.942Z","language":2,"uuid":"26ec2908-9272-4222-9f4a-0dd91eb83b86","exercise":1373}},{"model":"exercises.translation","pk":2656,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"admin","license_author_url":"","license_derivative_source_url":"","description":"<p>Sprung aus dem Stand auf die Box, Körperstreckung durchführen, dann wieder heruntersteigen (nicht springen)</p>\n","description_source":"Sprung aus dem Stand auf die Box, Körperstreckung durchführen, dann wieder heruntersteigen (nicht springen)","name":"Boxsprünge","created":"2025-09-09T22:54:55.868Z","last_update":"2026-04-13T18:58:26.134Z","language":1,"uuid":"90fefa8d-b2cb-43f7-a0fd-3470f7db08eb","exercise":1373}}],"aliases":[{"model":"exercises.alias","pk":603,"fields":{"uuid":"44796270-7989-4dcd-81cc-96410901ef5b","translation":2656,"alias":"Kastensprünge"}},{"model":"exercises.alia