('wger', '1374', 'machine-rotary-torso', 'https://wger.de/en/exercise/1374/view', 'CC-BY-SA-4.0', '6LXBO', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1374,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"6LXBO","license_author_url":"","license_derivative_source_url":"","uuid":"849f2fa6-42f9-4c59-90f6-275c8ada6725","category":10,"variation_group":null,"created":"2024-09-11T13:26:45.612Z","last_update":"2024-09-11T13:26:45.612Z","muscles":[6],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2340,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"6LXBO","license_author_url":"","license_derivative_source_url":"","description":"<ul>\n<li>Slow and Steady</li>\n<li>Not too much weight</li>\n</ul>\n","description_source":"- Slow and Steady\n- Not too much weight","name":"Rotary Torso Machine","created":"2024-09-11T13:26:45.765Z","last_update":"2026-04-13T18:58:27.184Z","language":2,"uuid":"7aef0848-0ffb-431c-b09c-f650a6a9e08d","exercise":1374}},{"model":"exercises.translation","pk":2341,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"6LXBO","license_author_url":"","license_derivative_source_url":"","description":"<ul>\n<li>Langsam und stätig</li>\n<li>Nicht zu viel Gewicht nutzen</li>\n</ul>\n","description_source":"- Langsam und stätig\n- Nicht zu viel Gewicht nutzen","name":"Bauch-Twist Gerät","created":"2024-09-11T13:26:45.909Z","last_update":"2026-04-13T18:58:26.084Z","language":1,"uuid":"eaffa176-5021-497d-99ef-3b8bdc3cab4d","exercise":1374}}],"aliases":[],"comments":[]}'),
('wger', '1376', 'recumbent-bike', 'https://wger.de/en/exercise/1376/view', 'CC-BY-SA-4.0', 'pera_perkan', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1376,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"pera_perkan","license_author_url":"","license_derivative_source_url":"","uuid":"12f88134-0f7a-4fb7-8bd9-436aa80d8b7c","category":15,"variation_group":null,"created":"2024-09-16T11:42:26.798Z","last_update":"2024-09-16T11:42:26.798Z","muscles":[11,7,8,10],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2342,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"pera_perkan","license_author_url":"","license_derivative_source_url":"","description":"<p>For this exercise Recumbent Bike is needed. You just sit on it, set level and time and start the workout</p>\n","description_source":"For this exercise Recumbent Bike is needed. You just sit on it, set level and time and start the workout","name":"Recumbent Bike","created":"2024-09-16T11:42:27.009Z","last_update":"2026-04-13T18:58:27.129Z","language":2,"uuid":"ac7808e1-c2ff-446a-9ac5-10fe54ee5cfb","exercise":1376}}],"aliases":[],"comments":[]}'),
('wger', '1377', 'torso-twist', 'https://wger.de/en/exercise/1377/view', 'CC-BY-SA-4.0', 'brucem', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1377,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"brucem","license_author_url":"","license_derivative_source_url":"","uuid":"56a03260-2901-4b28-bd41-a030185f985a","category":10,"variation_group":null,"created":"2024-09-24T06:01:15.420Z","last_update":"2024-09-24T06:01:15.420Z","muscles":[6],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2344,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"brucem","license_author_url":"","license_derivative_source_url":"","description":"<p>Standing Torso Twist WorkoutTarget your core and improve flexibility with this dynamic standing exercise! The Standing Torso Twist Workout involves twisting your torso while keeping your feet and hips stable, engaging your obliques, and stretching your entire upper body. This movement helps to:Strengthen core musclesIncrease flexibility in the spine and torsoImprove posture and balanceEnhance overall athletic performancePerform 3 sets of 10-15 reps, twisting to each side, to feel the benefits of this effective and efficient workout!</p>\n","description_source":"Standing Torso Twist WorkoutTarget your core and improve flexibility with this dynamic standing exercise! The Standing Torso Twist Workout involves twisting your torso while keeping your feet and hips stable, engaging your obliques, and stretching your entire upper body. This movement helps to:Strengthen core musclesIncrease flexibility in the spine and torsoImprove posture and balanceEnhance overall athletic performancePerform 3 sets of 10-15 reps, twisting to each side, to feel the benefits of this effective and efficient workout!","name":"TORSO TWIST","created":"2024-09-24T06:01:15.752Z","last_update":"2026-04-13T18:58:27.606Z","language":2,"uuid":"552789c4-e68a-42ad-bf35-96e33a70934b","exercise":1377}}],"aliases":[],"comments":[]}'),
('wger', '1378', 'cable-lateral-raise-single-arm', 'https://wger.de/en/exercise/1378/view', 'CC-BY-SA-4.0', 'carlos3c', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1378,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"carlos3c","license_author_url":"","license_derivative_source_url":"","uuid":"81942f3d-d92c-431c-b9d0-0da12918d1e4","category":13,"variation_group":"1501b536-71f2-4137-aa42-fefaa14f1934","created":"2024-10-03T11:29:25.628Z","last_update":"2026-01-20T14:10:36.422Z","muscles":[2],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2345,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"carlos3c","license_author_url":"","license_derivative_source_url":"","description":"<p>The single arm cable lateral raise is a variation of the lateral raise and an exercise used to build the muscles of the shoulders.</p>\n<ol>\n<li>Position a cable at the lowest position possible and attach a single handle.</li>\n<li>Reach across your body and grab the handle with a neutral grip.</li>\n<li>Keep the elbow slightly bent and pull the handle across your body and raise laterally.</li>\n<li>Slowly lower the handle back to the starting position under control.</li>\n</ol>\n","description_source":"The single arm cable lateral raise is a variation of the lateral raise and an exercise used to build the muscles of the shoulders.\n\n1. Position a cable at the lowest position possible and attach a single handle.\n2. Reach across your body and grab the handle with a neutral grip.\n3. Keep the elbow slightly bent and pull the handle across your body and raise laterally.\n4. Slowly lower the handle back to the starting position under control.","name":"Cable Lateral Raises (Single Arm)","created":"2024-10-03T11:29:25.821Z","last_update":"2026-04-13T18:58:26.179Z","language":2,"uuid":"76c7d412-7144-4b65-ba1f-52747af2de98","exercise":1378}}],"aliases":[],"comments":[{"model":"exercises.exercisecomment","pk":520,"fields":{"uuid":"3ee6c227-b050-4686-af26-d534bdadf244","translation":2345,"comment":"Keep the abs braced and don’t arch the back at the top of the movement"}},{"model":"exercises.exercisecomment","pk":521,"fields":{"uuid":"27549df2-b3f1-4f5e-a0ba-4d01a0bd882b","translation":2345,"comment":"Focus during the movement and don’t rely on momentum"}},{"model":"exercises.exercisecomment","pk":522,"fields":{"uuid":"badb7897-5c97-4e92-9ecb-91b5d670f906","translation":2345,"comment":"Allow the arms to move freely but don’t lock out the elbows."}},{"model":"exercises.exercisecomment","pk":523,"fields":{"uuid":"e8404058-c93b-4248-99a1-f08947e1623f","translation":2345,"comment":"Tilt your pinkies slightly higher than your thumbs. Imagine you’re pouring out a cup of water."}}]}'),
('wger', '1380', 'band-pull-apart', 'https://wger.de/en/exercise/1380/view', 'CC-BY-SA-4.0', 'schwolfar', 'fuzzy', 95.2, '{"exercise":{"model":"exercises.exercise","pk":1380,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"schwolfar","license_author_url":"","license_derivative_source_url":"","uuid":"f18eb684-9a9b-4566-9771-e22a87d536b1","category":12,"variation_group":null,"created":"2024-10-07T08:45:20.418Z","last_update":"2024-10-07T08:45:20.418Z","muscles":[],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2346,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"schwolfar","license_author_url":"","license_derivative_source_url":"","description":"<ul>\n<li>Hold the band with your arms extended in front of you at shoulder height.</li>\n<li>Keep your elbows slightly bent but fixed throughout the movement.</li>\n<li>Pull the band apart by spreading your arms until the band touches or comes close to your chest.</li>\n<li>Slowly bring your arms back to the starting position, controlling the tension on the band.</li>\n</ul>\n","description_source":"* Hold the band with your arms extended in front of you at shoulder height.\n* Keep your elbows slightly bent but fixed throughout the movement.\n* Pull the band apart by spreading your arms until the band touches or comes close to your chest.\n* Slowly bring your arms back to the starting position, controlling the tension on the band.","name":"Band pull-aparts","created":"2024-10-07T08:45:20.604Z","last_update":"2026-04-13T18:58:26.062Z","language":2,"uuid":"0db48e08-5f52-479b-b7fc-8566b0e57fec","exercise":1380}},{"model":"exercises.translation","pk":2347,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"schwolfar","license_author_url":"","license_derivative_source_url":"","description":"<ul>\n<li>Tiens l''élastique avec les bras tendus devant toi, à hauteur des épaules.</li>\n<li>Garde les coudes légèrement fléchis, mais fixes.</li>\n<li>Tire l''élastique vers l''extérieur en écartant les bras jusqu''à ce qu''il touche ou approche ta poitrine.</li>\n<li>Ramène lentement les bras à la position initiale en contrôlant la tension.</li>\n</ul>\n","description_source":"* Tiens l''élastique avec les bras tendus devant toi, à hauteur des épaules.\n* Garde les coudes légèrement fléchis, mais fixes.\n* Tire l''élastique vers l''extérieur en écartant les bras jusqu''à ce qu''il touche ou approche ta poitrine.\n* Ramène lentement les bras à la position initiale en contrôlant la tension.","name":"Pull-apart avec élastique","created":"2024-10-07T08:45:20.760Z","last_update":"2026-04-13T18:58:27.092Z","language":12,"uuid":"afa9d15c-d1b2-44e0-b7f3-6866bdd9f748","exercise":1380}}],"aliases":[],"comments":[]}'),
('wger', '1381', 'upper-back', 'https://wger.de/en/exercise/1381/view', 'CC-BY-SA-4.0', 'phpi', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1381,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"phpi","license_author_url":"","license_derivative_source_url":"","uuid":"df18b577-0610-4804-a993-161024da67db","category":12,"variation_group":null,"created":"2024-10-16T10:24:31.626Z","last_update":"2024-10-16T10:24:31.626Z","muscles":[2,9],"muscles_secondary":[1,12],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2348,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"phpi","license_author_url":"","license_derivative_source_url":"","description":"<p>Upper Back is suitable for building up the core muscles with a special focus on the deltoid and rhomboid muscles and the upper back muscles</p>\n","description_source":"Upper Back is suitable for building up the core muscles with a special focus on the deltoid and rhomboid muscles and the upper back muscles","name":"Upper Back","created":"2024-10-16T10:24:31.792Z","last_update":"2026-04-13T18:58:27.756Z","language":2,"uuid":"4b11d8dd-d609-411a-8893-86b2f2f53e7f","exercise":1381}},{"model":"exercises.translation","pk":2349,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"phpi","license_author_url":"","license_derivative_source_url":"","description":"<p>Upper Back eignet sich für den Aufbau der Rumpfmuskultur mit besonderem Schwerpunkt auf den Delta- und Rautenmuskel und der oberen Rückenmuskulatur</p>\n","description_source":"Upper Back eignet sich für den Aufbau der Rumpfmuskultur mit besonderem Schwerpunkt auf den Delta- und Rautenmuskel und der oberen Rückenmuskulatur","name":"Upper Back","created":"2024-10-16T10:24:31.897Z","last_update":"2026-04-13T18:58:27.757Z","language":1,"uuid":"e978404b-5b0a-41cd-b7e2-292d973aef18","exercise":1381}}],"aliases":[],"comments":[]}'),
('wger', '1384', 'machine-pullover', 'https://wger.de/en/exercise/1384/view', 'CC-BY-SA-4.0', 'Paul@Chemistry', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1384,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Paul@Chemistry","license_author_url":"","license_derivative_source_url":"","uuid":"ad20ef5e-e360-4859-9110-668ee0c24721","category":12,"variation_group":null,"created":"2024-11-13T20:34:24.902Z","last_update":"2024-11-13T20:34:24.902Z","muscles":[12],"muscles_secondary":[4,5],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2352,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Paul@Chemistry","license_author_url":"","license_derivative_source_url":"","description":"<p>Pullover machine, sitting, elbows on pads</p>\n","description_source":"Pullover machine, sitting, elbows on pads","name":"Pullover Machine","created":"2024-11-13T20:34:25.091Z","last_update":"2026-04-13T18:58:27.097Z","language":2,"uuid":"6af6593b-c55d-4d86-ae6f-0d8f60a3bda3","exercise":1384}}],"aliases":[],"comments":[]}'),
('wger', '1387', 'hamstring-kick', 'https://wger.de/en/exercise/1387/view', 'CC-BY-SA-4.0', 'captive0592', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1387,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"captive0592","license_author_url":"","license_derivative_source_url":"","uuid":"66aef559-02e8-4f35-91f6-600f103e9cbf","category":9,"variation_group":null,"created":"2024-11-23T14:39:08.322Z","last_update":"2024-11-23T14:39:08.322Z","muscles":[11],"muscles_secondary":[8],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2353,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"captive0592","license_author_url":"","license_derivative_source_url":"","description":"<p>Stand with your feet hip-width apart and extend one arm in front of you. Swing that leg up in front of you and back down while keeping your leg as straight as possible and your toes pointed up.Repeat with the other leg.</p>\n","description_source":"Stand with your feet hip-width apart and extend one arm in front of you. Swing that leg up in front of you and back down while keeping your leg as straight as possible and your toes pointed up.Repeat with the other leg.","name":"Hamstring Kicks","created":"2024-11-23T14:39:08.506Z","last_update":"2026-04-13T18:58:26.609Z","language":2,"uuid":"a47896e8-1c62-4cc7-bf41-930d8e1170ee","exercise":1387}},{"model":"exercises.translation","pk":2354,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"captive0592","license_author_url":"","license_derivative_source_url":"","description":"<p>Stehen Sie mit hüftbreit geöffneten Füßen. Schwingen Sie ein Bein vor und zurück, wobei Sie es so gerade wie möglich halten und die Zehen nach oben zeigen. Wiederholen Sie dies mit dem anderen Bein.</p>\n","description_source":"Stehen Sie mit hüftbreit geöffneten Füßen. Schwingen Sie ein Bein vor und zurück, wobei Sie es so gerade wie möglich halten und die Zehen nach oben zeigen. Wiederholen Sie dies mit dem anderen Bein.","name":"Hamstring-Kicks","created":"2024-11-23T14:39:09.751Z","last_update":"2026-04-13T18:58:26.609Z","language":1,"uuid":"866428d0-6190-4f5c-93a3-ec241603aca3","exercise":1387}}],"aliases":[],"comments":[{"model":"exercises.exercisecomment","pk":524,"fields":{"uuid":"907494d3-ef1a-4b7f-ae9d-81009b2726bc","translation":2353,"comment":"Keep your upper body upright and stable"}},{"model":"exercises.exercisecomment","pk":525,"fields":{"uuid":"f147842c-748c-44fb-afcd-133a209a45bd","translation":2353,"comment":"Focus on controlling the movement"}},{"model":"exercises.exercisecomment","pk":526,"fields":{"uuid":"f800ac6a-c649-4983-b6ac-683bbab0db32","translation":2354,"comment":"Halten Sie Ihren Oberkörper stabil und benutzen Sie bei Bedarf Ihre Arme zur Balance"}}]}'),
('wger', '1388', 'single-leg-romanian-deadlift', 'https://wger.de/en/exercise/1388/view', 'CC-BY-SA-4.0', 'captive0592', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1388,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"captive0592","license_author_url":"","license_derivative_source_url":"","uuid":"957ca37c-b6d7-4c30-8ba9-9512b0fa2659","category":9,"variation_group":null,"created":"2024-11-23T15:17:08.468Z","last_update":"2024-11-23T15:17:08.468Z","muscles":[11],"muscles_secondary":[8],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2355,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"captive0592","license_author_url":"","license_derivative_source_url":"","description":"<ol>\n<li>Stand upright and hold weights in both hands if using loads.</li>\n<li>Brace your core and lift one leg off the ground.</li>\n<li>Keep your back straight, hinge at the hips while lowering your torso forward, ensuring you don’t rotate your hips.</li>\n<li>Lower until you feel a stretch in your standing leg''s hamstring, then return to standing position. Repeat on both sides.</li>\n</ol>\n","description_source":"1. Stand upright and hold weights in both hands if using loads.\n2. Brace your core and lift one leg off the ground.\n3. Keep your back straight, hinge at the hips while lowering your torso forward, ensuring you don’t rotate your hips.\n4. Lower until you feel a stretch in your standing leg''s hamstring, then return to standing position. Repeat on both sides.","name":"Single Leg RDL","created":"2024-11-23T15:17:08.670Z","last_update":"2026-04-13T18:58:27.400Z","language":2,"uuid":"bb949338-0d62-42bc-8077-0bd7e660e841","exercise":1388}}],"aliases":[],"comments":[{"model":"exercises.exercisecomment","pk":527,"fields":{"uuid":"1e9f44fc-2e33-4859-a594-a0b20ba0df76","translation":2355,"comment":"Maintain balance and focus on proper form to prevent injury."}}]}'),
('wger', '1389', 'single-leg-romanian-deadlift', 'https://wger.de/en/exercise/1389/view', 'CC-BY-SA-4.0', 'captive0592', 'exact', 100.0, '{"exercise":{"model":"exercises.exercise","pk":1389,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"captive0592","license_author_url":"","license_derivative_source_url":"","uuid":"965d7607-e9c1-4c16-b5cb-2c3d278e2a03","category":9,"variation_group":"335b2b18-e072-4636-aa13-4045d7a133ae","created":"2024-11-23T15:29:10.057Z","last_update":"2025-11-01T17:37:49.997Z","muscles":[11,8],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2356,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"captive0592","license_author_url":"","license_derivative_source_url":"","description":"<p>Stand with your feet hip-width apart, shift your weight onto one leg and slightly bend the other. Keep your back straight while hinging at your hips. Use your hamstring to pull yourself back up.</p>\n","description_source":"Stand with your feet hip-width apart, shift your weight onto one leg and slightly bend the other. Keep your back straight while hinging at your hips. Use your hamstring to pull yourself back up.","name":"Single Leg RDL","created":"2024-11-23T15:29:11.679Z","last_update":"2026-04-13T18:58:27.398Z","language":2,"uuid":"2d657127-6322-40b6-84ab-ccac64426697","exercise":1389}}],"aliases":[{"model":"exercises.alias","pk":582,"fields":{"uuid":"9d123d4a-78f0-4eaf-9758-ef249bd1923b","translation":2356,"alias":"Single Leg Romanian Deadlift"}}],"comments":[{"model":"exercises.exercisecomment","pk":528,"fields":{"uuid":"b0f803e2-ea2f-4509-a0de-eecf3d47468b","translation":2356,"comment":"Maintain a straight back and hinge from the hips"}}]}'),
('wger', '1390', 'toe-touch', 'https://wger.de/en/exercise/1390/view', 'CC-BY-SA-4.0', 'captive0592', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1390,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"captive0592","license_author_url":"","license_derivative_source_url":"","uuid":"a51de8df-4101-45cb-8da5-de230d9bac1d","category":9,"variation_group":null,"created":"2024-11-23T15:30:46.550Z","last_update":"2024-11-23T15:30:46.550Z","muscles":[11,8],"muscles_secondary":[7],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2357,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"captive0592","license_author_url":"","license_derivative_source_url":"","description":"<p>Stand with your feet closer together. Hinge at your hips and lower your upper body towards your toes. Reach your hands towards your feet, try to touch your toes, the ground, or as far down your legs as you can comfortably go.</p>\n","description_source":"Stand with your feet closer together. Hinge at your hips and lower your upper body towards your toes. Reach your hands towards your feet, try to touch your toes, the ground, or as far down your legs as you can comfortably go.","name":"Toe Touch","created":"2024-11-23T15:30:46.699Z","last_update":"2026-04-13T18:58:27.658Z","language":2,"uuid":"98b86ab4-da54-4de9-b239-39493947a90a","exercise":1390}}],"aliases":[{"model":"exercises.alias","pk":583,"fields":{"uuid":"6d543a00-d6aa-4b39-89dd-d996692730b3","translation":2357,"alias":"Standing Forward Bend"}}],"comments":[{"model":"exercises.exercisecomment","pk":529,"fields":{"uuid":"c60b1e66-8050-4971-8583-a3bbb92a41ac","translation":2357,"comment":"Keep your legs straight but don''t lock your knees"}}]}'),
('wger', '1391', 'elephant-walk', 'https://wger.de/en/exercise/1391/view', 'CC-BY-SA-4.0', 'captive0592', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1391,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"captive0592","license_author_url":"","license_derivative_source_url":"","uuid":"34cce09a-edb3-4140-892a-1cf70da8d98b","category":9,"variation_group":null,"created":"2024-11-23T15:32:52.804Z","last_update":"2024-11-23T15:32:52.804Z","muscles":[11],"muscles_secondary":[7],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2358,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"captive0592","license_author_url":"","license_derivative_source_url":"","description":"<p>Hinge at your hips until you feel a stretch behind your knees. Bend one leg while the other is straight then fluidly bend the other knee while straightening the first knee.</p>\n","description_source":"Hinge at your hips until you feel a stretch behind your knees. Bend one leg while the other is straight then fluidly bend the other knee while straightening the first knee.","name":"Elephant Walks","created":"2024-11-23T15:32:52.924Z","last_update":"2026-04-13T18:58:26.465Z","language":2,"uuid":"376f7a82-9ff8-4112-9a39-edaecfe85648","exercise":1391}}],"aliases":[{"model":"exercises.alias","pk":584,"fields":{"uuid":"c8d27986-b015-4ca3-86be-9d7c3cd1b876","translation":2358,"alias":"Walking Hamstring Stretch"}}],"comments":[{"model":"exercises.exercisecomment","pk":530,"fields":{"uuid":"a4a1ac86-1e75-4534-8349-14d3d6302096","translation":2358,"comment":"Maintain a fluid motion between leg bends"}}]}'),
('wger', '1392', 'good-morning', 'https://wger.de/en/exercise/1392/view', 'CC-BY-SA-4.0', 'captive0592', 'new', 100.0, '{"exercise":{"model":"exercises.exercise","pk":1392,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"captive0592","license_author_url":"","license_derivative_source_url":"","uuid":"77a56810-d050-4083-9501-d648f773376a","category":9,"variation_group":null,"created":"2024-11-23T15:40:21.912Z","last_update":"2024-11-23T15:40:21.912Z","muscles":[11],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2359,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"captive0592","license_author_url":"","license_derivative_source_url":"","description":"<p>Stand with your feet more than shoulder-width apart (wider stance) and place your hands on your hips. Hinge at your hips and lower your upper body towards the ground while keeping your back straight then come back up.</p>\n","description_source":"Stand with your feet more than shoulder-width apart (wider stance) and place your hands on your hips. Hinge at your hips and lower your upper body towards the ground while keeping your back straight then come back up.","name":"Good Morning","created":"2024-11-23T15:40:22.162Z","last_update":"2026-04-13T18:58:26.596Z","language":2,"uuid":"dd110052-7ece-4eab-9945-2948113da9b3","exercise":1392}}],"aliases":[{"model":"exercises.alias","pk":585,"fields":{"uuid":"28429833-c091-45ca-96ca-a416893b9f06","translation":2359,"alias":"Hip Hinge"}}],"comments":[{"model":"exercises.exercisecomment","pk":531,"fields":{"uuid":"0211077a-d3a7-414a-a780-cbca792e554e","translation":2359,"comment":"Keep your back straight throughout the movement"}}]}'),
('wger', '1393', 'single-leg-hamstring-stretch', 'https://wger.de/en/exercise/1393/view', 'CC-BY-SA-4.0', 'captive0592', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1393,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"captive0592","license_author_url":"","license_derivative_source_url":"","uuid":"45cd73d7-98ac-4451-849a-a645fcfe9bee","category":9,"variation_group":null,"created":"2024-11-23T15:41:14.684Z","last_update":"2024-11-23T15:41:14.684Z","muscles":[11],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2360,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"captive0592","license_author_url":"","license_derivative_source_url":"","description":"<p>Sit on the ground with one leg straight out in front of you and the other leg bent in toward you. Reach forward with both hands, trying to touch the toes of your straight leg.</p>\n","description_source":"Sit on the ground with one leg straight out in front of you and the other leg bent in toward you. Reach forward with both hands, trying to touch the toes of your straight leg.","name":"Single Leg Hamstring Stretch","created":"2024-11-23T15:41:14.813Z","last_update":"2026-04-13T18:58:27.396Z","language":2,"uuid":"acd59a99-ba9f-4175-b49e-370828a4d402","exercise":1393}}],"aliases":[{"model":"exercises.alias","pk":586,"fields":{"uuid":"1251ad16-5b98-4754-aeac-857664e7d184","translation":2360,"alias":"Seated Single Leg Stretch"}}],"comments":[{"model":"exercises.exercisecomment","pk":532,"fields":{"uuid":"bbdb6603-adb2-4fe8-9d62-2539adf1a501","translation":2360,"comment":"Keep the extended leg straight but don''t lock the knee"}}]}'),
('wger', '1394', 'sit-and-reach', 'https://wger.de/en/exercise/1394/view', 'CC-BY-SA-4.0', 'captive0592', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1394,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"captive0592","license_author_url":"","license_derivative_source_url":"","uuid":"5a5e8883-b185-40ff-b292-9e433d13b5e7","category":12,"variation_group":null,"created":"2024-11-23T15:43:33.213Z","last_update":"2024-11-23T15:43:33.213Z","muscles":[11],"muscles_secondary":[],"equipment":[4]}},"translations":[{"model":"exercises.translation","pk":2361,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"captive0592","license_author_url":"","license_derivative_source_url":"","description":"<p>Sit on the ground with your legs extended straight in front of you. Reach both hands forward, trying to reach past your toes or as far as you can go. Return to the starting position and repeat.</p>\n","description_source":"Sit on the ground with your legs extended straight in front of you. Reach both hands forward, trying to reach past your toes or as far as you can go. Return to the starting position and repeat.","name":"Sit & Reach","created":"2024-11-23T15:43:33.333Z","last_update":"2026-04-13T18:58:27.410Z","language":2,"uuid":"458ddfcb-b5a9-4d12-89f1-54975acedc07","exercise":1394}}],"aliases":[{"model":"exercises.alias","pk":587,"fields":{"uuid":"cc6e298b-0442-4862-bf3e-60679a7b477e","translation":2361,"alias":"Seated Forward Bend"}}],"comments":[{"model":"exercises.exercisecomment","pk":533,"fields":{"uuid":"1ba64973-e039-40b7-ad4c-42e533ea36e4","translation":2361,"comment":"Keep your legs straight but don''t lock your knees"}}]}'),
('wger', '1395', 'crossbody-leg-swing', 'https://wger.de/en/exercise/1395/view', 'CC-BY-SA-4.0', 'captive0592', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1395,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"captive0592","license_author_url":"","license_derivative_source_url":"","uuid":"bb948d34-8948-4995-9e59-003d7b6fc1b2","category":9,"variation_group":null,"created":"2024-11-23T15:46:02.116Z","last_update":"2024-11-23T15:46:02.116Z","muscles":[11],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2362,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"captive0592","license_author_url":"","license_derivative_source_url":"","description":"<p>Hold onto a wall or something near you for support. Swing one leg across the front of your body, then back and out to the side. Repeat while slowly increasing your range of motion.</p>\n","description_source":"Hold onto a wall or something near you for support. Swing one leg across the front of your body, then back and out to the side. Repeat while slowly increasing your range of motion.","name":"Crossbody Leg Swings","created":"2024-11-23T15:46:02.286Z","last_update":"2026-04-13T18:58:26.241Z","language":2,"uuid":"1078f75c-976e-4e56-91e3-26e7e28ed813","exercise":1395}}],"aliases":[{"model":"exercises.alias","pk":588,"fields":{"uuid":"7a0408fa-ff0a-489e-882d-58a8a59cd0d8","translation":2362,"alias":"Lateral Leg Swings"}}],"comments":[{"model":"exercises.exercisecomment","pk":534,"fields":{"uuid":"3d29766d-a14c-4686-902a-295f9de40bee","translation":2362,"comment":"Keep your supporting leg slightly bent for stability"}}]}'),
('wger', '1396', 'standing-pancake', 'https://wger.de/en/exercise/1396/view', 'CC-BY-SA-4.0', 'captive0592', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1396,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"captive0592","license_author_url":"","license_derivative_source_url":"","uuid":"af59f161-147a-49ba-85c8-6c9f4e5ffe63","category":9,"variation_group":null,"created":"2024-11-23T15:46:56.725Z","last_update":"2024-11-23T15:46:56.725Z","muscles":[11],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2363,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"captive0592","license_author_url":"","license_derivative_source_url":"","description":"<p>Stand and open your legs as wide as possible into a straddle position. Then bend at the hips, pushing them back while keeping your back straight.</p>\n","description_source":"Stand and open your legs as wide as possible into a straddle position. Then bend at the hips, pushing them back while keeping your back straight.","name":"Standing Pancake","created":"2024-11-23T15:46:56.920Z","last_update":"2026-04-13T18:58:27.525Z","language":2,"uuid":"a0033af1-c63d-41f0-b7da-1756b5850724","exercise":1396}}],"aliases":[],"comments":[{"model":"exercises.exercisecomment","pk":535,"fields":{"uuid":"d757671a-1e35-4bb4-9f3b-7ea8a94ab243","translation":2363,"comment":"Keep your back straight as you bend forward"}}]}'),
('wger', '1397', 'standing-pancake-good-morning', 'https://wger.de/en/exercise/1397/view', 'CC-BY-SA-4.0', 'captive0592', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1397,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"captive0592","license_author_url":"","license_derivative_source_url":"","uuid":"aa3c2791-74f7-4fed-a812-297ff454e2f9","category":9,"variation_group":"32d2d0f2-51a3-4c26-89b0-0dca0132aa25","created":"2024-11-23T15:47:48.575Z","last_update":"2026-02-12T13:00:14.978Z","muscles":[11],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2364,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"captive0592","license_author_url":"","license_derivative_source_url":"","description":"<p>Stand with your feet wider than shoulder-width apart and toes pointed slightly outward. Place your hands on the back of your head. Hinge at your hips and lower your upper body towards the ground, keeping your back straight and chest open.</p>\n","description_source":"Stand with your feet wider than shoulder-width apart and toes pointed slightly outward. Place your hands on the back of your head. Hinge at your hips and lower your upper body towards the ground, keeping your back straight and chest open.","name":"Standing Pancake Good Morning","created":"2024-11-23T15:47:48.697Z","last_update":"2026-04-13T18:58:27.527Z","language":2,"uuid":"d0fbe774-56bf-44fe-b6bb-196678cee924","exercise":1397}}],"aliases":[{"model":"exercises.alias","pk":589,"fields":{"uuid":"4c73d198-65fd-4a39-90e9-62e7fb48607e","translation":2364,"alias":"Wide-Stance Good Morning"}}],"comments":[{"model":"exercises.exercisecomment","pk":536,"fields":{"uuid":"37f51a1b-a702-4109-a9ba-ff101e115b3d","translation":2364,"comment":"Keep your back straight and chest open throughout the movement"}}]}'),
('wger', '1398', 'hamstring-chokes', 'https://wger.de/en/exercise/1398/view', 'CC-BY-SA-4.0', 'captive0592', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1398,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"captive0592","license_author_url":"","license_derivative_source_url":"","uuid":"638756b5-a957-48f4-93ca-8994cead818f","category":9,"variation_group":null,"created":"2024-11-23T15:48:39.502Z","last_update":"2024-11-23T15:48:39.502Z","muscles":[11],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2365,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"captive0592","license_author_url":"","license_derivative_source_url":"","description":"<p>Sit on the ground and bend one leg, bringing your knee toward you. Place your hand behind your hamstring and gently pull your leg toward your chest, feeling a stretch in the back of your thigh. Straighten your leg, extending up toward the ceiling.</p>\n","description_source":"Sit on the ground and bend one leg, bringing your knee toward you. Place your hand behind your hamstring and gently pull your leg toward your chest, feeling a stretch in the back of your thigh. Straighten your leg, extending up toward the ceiling.","name":"Hamstring Chokes","created":"2024-11-23T15:48:39.628Z","last_update":"2026-04-13T18:58:26.607Z","language":2,"uuid":"49369b7d-023c-4d7f-a252-70d684fe3aab","exercise":1398}}],"aliases":[{"model":"exercises.alias","pk":590,"fields":{"uuid":"816818c9-4056-4087-8b4b-e5831b410df7","translation":2365,"alias":"Dynamic Hamstring Stretch"}}],"comments":[{"model":"exercises.exercisecomment","pk":537,"fields":{"uuid":"786a9e64-b021-46f9-b871-a4fa9ad74bca","translation":2365,"comment":"Maintain control throughout the movement, especially when extending the leg"}}]}'),
('wger', '1399', NULL, 'https://wger.de/en/exercise/1399/view', 'CC-BY-SA-4.0', 'captive0592', NULL, NULL, '{"exercise":{"model":"exercises.exercise","pk":1399,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"captive0592","license_author_url":"","license_derivative_source_url":"","uuid":"d5ee3b1f-2879-406f-97a9-51a8b0817cd4","category":12,"variation_group":null,"created":"2024-11-23T15:50:40.739Z","last_update":"2024-11-23T15:50:40.739Z","muscles":[],"muscles_secondary":[11],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2366,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"captive0592","license_author_url":"","license_derivative_source_url":"","description":"<p>Stand with your feet hip-width apart and slowly roll your upper body forward, one vertebra at a time, until your hands touch the ground or as far as you can comfortably go. Roll back up to the starting position in the same controlled manner.</p>\n","description_source":"Stand with your feet hip-width apart and slowly roll your upper body forward, one vertebra at a time, until your hands touch the ground or as far as you can comfortably go. Roll back up to the starting position in the same controlled manner.","name":"Roll Down","created":"2024-11-23T15:50:40.864Z","last_update":"2026-04-13T18:58:27.169Z","language":2,"uuid":"3019fe23-8e2d-48cd-948e-c39334f548e4","exercise":1399}}],"aliases":[],"comments":[{"model":"exercises.exercisecomment","pk":538,"fields":{"uuid":"4de7f452-b564-4ba5-929a-cf119cf6d7c3","translation":2366,"comment":"Move slowly and deliberately, focusing on each vertebra as you roll down and up"}}]}'),
('wger', '1400', 'crossbody-hamstring-stretch', 'https://wger.de/en/exercise/1400/view', 'CC-BY-SA-4.0', 'captive0592', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1400,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"captive0592","license_author_url":"","license_derivative_source_url":"","uuid":"4f38cc2e-5904-4ef5-b811-e729105cfd3b","category":9,"variation_group":null,"created":"2024-11-23T15:51:37.951Z","last_update":"2024-11-23T15:51:37.951Z","muscles":[11],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2367,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"captive0592","license_author_url":"","license_derivative_source_url":"","description":"<p>While standing, cross one leg behind the other (keep this leg straight). Reach downward and try to touch the toes of that leg. Slightly bend the other leg so that you can bend down.</p>\n","description_source":"While standing, cross one leg behind the other (keep this leg straight). Reach downward and try to touch the toes of that leg. Slightly bend the other leg so that you can bend down.","name":"Crossbody Hamstring Stretch","created":"2024-11-23T15:51:38.068Z","last_update":"2026-04-13T18:58:26.240Z","language":2,"uuid":"3212f90d-c706-4a33-a228-3ae54ff0eac7","exercise":1400}}],"aliases":[{"model":"exercises.alias","pk":591,"fields":{"uuid":"f1b3285a-4d93-41a9-8a26-2ead565ea904","translation":2367,"alias":"Standing Cross-Leg Hamstring Stretch"}}],"comments":[{"model":"exercises.exercisecomment","pk":539,"fields":{"uuid":"20c397a3-a828-4662-b6d4-120e35465178","translation":2367,"comment":"Keep the crossed leg straight to maximize the hamstring stretch"}}]}'),
('wger', '1406', 'plank-to-elbow-extension', 'https://wger.de/en/exercise/1406/view', 'CC-BY-SA-4.0', 'clafal', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1406,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"clafal","license_author_url":"","license_derivative_source_url":"","uuid":"e75629ed-4991-4a48-984c-b297f3f9fb58","category":10,"variation_group":null,"created":"2024-12-28T16:07:38.662Z","last_update":"2024-12-28T16:07:38.662Z","muscles":[2,6,5],"muscles_secondary":[14,4],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2369,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"clafal","license_author_url":"","license_derivative_source_url":"","description":"<p>The Plank-to-Elbow Extension is a dynamic exercise that combines the plank with an elbow extension movement</p>\n","description_source":"The Plank-to-Elbow Extension is a dynamic exercise that combines the plank with an elbow extension movement","name":"Plank-to-Elbow Extension","created":"2024-12-28T16:07:38.797Z","last_update":"2026-04-13T18:58:26.974Z","language":2,"uuid":"b295b660-dcb7-4970-ba96-4b57f7422c21","exercise":1406}},{"model":"exercises.translation","pk":2370,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"clafal","license_author_url":"","license_derivative_source_url":"","description":"<p><strong>Esecuzione</strong></p>\n<ol>\n<li>\n<p><strong>Posizione di partenza</strong> :</p>\n<ul>\n<li>Parti in posizione di plancia alta (mani appoggiate a terra, braccia completamente estese, corpo in linea retta dalla testa ai talloni).</li>\n<li>Piedi leggermente divaricati per maggiore stabilità.</li>\n</ul>\n</li>\n<li>\n<p><strong>Movimento</strong> :</p>\n<ul>\n<li>Piega un gomito e appoggia l''avambraccio a terra, seguito dall''altro gomito, passando così alla posizione di plank sugli avambracci.</li>\n<li>Torna alla posizione iniziale spingendoti verso l''alto con un braccio alla volta, estendendo completamente i gomiti.</li>\n</ul>\n</li>\n<li>\n<p><strong>Respirazione</strong> :</p>\n<ul>\n<li>Espira mentre spingi verso l''alto ed estendi le braccia.</li>\n<li>Inspira mentre scendi sugli avambracci.</li>\n</ul>\n</li>\n</ol>\n","description_source":"**Esecuzione**\n\n1. **Posizione di partenza** :\n\n   * Parti in posizione di plancia alta (mani appoggiate a terra, braccia completamente estese, corpo in linea retta dalla testa ai talloni).\n   * Piedi leggermente divaricati per maggiore stabilità.\n2. **Movimento** :\n\n   * Piega un gomito e appoggia l''avambraccio a terra, seguito dall''altro gomito, passando così alla posizione di plank sugli avambracci.\n   * Torna alla posizione iniziale spingendoti verso l''alto con un braccio alla volta, estendendo completamente i gomiti.\n3. **Respirazione** :\n\n   * Espira mentre spingi verso l''alto ed estendi le braccia.\n   * Inspira mentre scendi sugli avambracci.","name":"Estensione Plank-Gomito","created":"2024-12-28T16:17:10.275Z","last_update":"2026-04-13T18:58:26.496Z","language":13,"uuid":"2ad237a1-a0bd-4497-91b8-14964b6bb16d","exercise":1406}}],"aliases":[],"comments":[]}'),
('wger', '1407', 'cossack-squat', 'https://wger.de/en/exercise/1407/view', 'CC-BY-SA-4.0', 'clafal', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1407,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"clafal","license_author_url":"","license_derivative_source_url":"","uuid":"96a899ee-16a4-457d-8f66-efdd39fd38a0","category":9,"variation_group":null,"created":"2024-12-28T18:16:08.985Z","last_update":"2024-12-28T18:16:08.985Z","muscles":[8,10],"muscles_secondary":[7,6],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2371,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"clafal","license_author_url":"","license_derivative_source_url":"","description":"<p>The Cossack Squat is a multi-joint exercise that works mainly on the legs and buttocks, but also involves stabilizing muscles. It is an excellent exercise for improving strength, mobility and stability in a functional way.</p>\n","description_source":"The Cossack Squat is a multi-joint exercise that works mainly on the legs and buttocks, but also involves stabilizing muscles. It is an excellent exercise for improving strength, mobility and stability in a functional way.","name":"Cossack squat","created":"2024-12-28T18:16:09.139Z","last_update":"2026-04-13T18:58:26.231Z","language":2,"uuid":"4591481c-5a39-4c15-ba64-747c56c6993e","exercise":1407}}],"aliases":[],"comments":[]}'),
('wger', '1408', 'wall-sit', 'https://wger.de/en/exercise/1408/view', 'CC-BY-SA-4.0', 'clafal', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1408,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"clafal","license_author_url":"","license_derivative_source_url":"","uuid":"3f8ad988-1aee-48ca-ad37-44e39ae1715d","category":9,"variation_group":null,"created":"2024-12-28T18:26:30.658Z","last_update":"2024-12-28T18:26:30.658Z","muscles":[8,10],"muscles_secondary":[7,6],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2372,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"clafal","license_author_url":"","license_derivative_source_url":"","description":"<p>The Wall Sit (or wall chair) is an isometric exercise that mainly involves the leg muscles, improving muscular endurance and stability. Here are the main and secondary muscles activated during the exercise.</p>\n","description_source":"The Wall Sit (or wall chair) is an isometric exercise that mainly involves the leg muscles, improving muscular endurance and stability. Here are the main and secondary muscles activated during the exercise.","name":"Wall-sit","created":"2024-12-28T18:26:31.003Z","last_update":"2026-04-13T18:58:27.856Z","language":2,"uuid":"5b2e67c7-015c-4c3f-939b-86b5b8ef2fc3","exercise":1408}}],"aliases":[],"comments":[]}'),
('wger', '1409', 'dragon-flag', 'https://wger.de/en/exercise/1409/view', 'CC-BY-SA-4.0', 'clafal; hurr99', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1409,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"clafal","license_author_url":"","license_derivative_source_url":"","uuid":"f5ad82a8-adf8-4795-9874-1f6d183c56ed","category":10,"variation_group":null,"created":"2024-12-28T18:35:23.063Z","last_update":"2024-12-28T18:35:23.063Z","muscles":[14,6],"muscles_secondary":[2,8,12,5],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2373,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"clafal","license_author_url":"","license_derivative_source_url":"","description":"<p>Keep your body completely rigid throughout the movement, avoiding sagging in your lower back.\nUse a firm grip to stabilize your upper body.\nStart with simpler versions (such as with bent knees) to build strength and control.</p>\n","description_source":"Keep your body completely rigid throughout the movement, avoiding sagging in your lower back.\nUse a firm grip to stabilize your upper body.\nStart with simpler versions (such as with bent knees) to build strength and control.","name":"Dragon-flag","created":"2024-12-28T18:35:23.196Z","last_update":"2026-04-13T18:58:26.407Z","language":2,"uuid":"8882ac66-d185-463c-928d-c6ed48faf743","exercise":1409}},{"model":"exercises.translation","pk":3022,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"hurr99","license_author_url":"","license_derivative_source_url":"","description":"<p>In Rückenlage, mit den Händen über dem Kopf an etwas festhalten (Kopfpolster der Hantelbank, unterste Sprosse der Sprossenwand...), sodass der Oberkörper möglichst unbeweglich wird. Dann die Beine in Richtung Decke heben, dabei auch das Becken abheben (ähnlich wie die \"Kerze\" aus Gymnastik/Yoga). Die Beine langsam wieder ablassen, möglichst viel Widerstand aus dem Bauch heraus. Beine seitlich drehen ist auch möglich.</p>\n","description_source":"In Rückenlage, mit den Händen über dem Kopf an etwas festhalten (Kopfpolster der Hantelbank, unterste Sprosse der Sprossenwand...), sodass der Oberkörper möglichst unbeweglich wird. Dann die Beine in Richtung Decke heben, dabei auch das Becken abheben (ähnlich wie die \"Kerze\" aus Gymnastik/Yoga). Die Beine langsam wieder ablassen, möglichst viel Widerstand aus dem Bauch heraus. Beine seitlich drehen ist auch möglich.","name":"Dragon Flag","created":"2026-02-19T21:21:01.737Z","last_update":"2026-04-13T18:58:26.405Z","language":1,"uuid":"564962fc-22a8-4c48-9d72-b00d855b9832","exercise":1409}}],"aliases":[],"comments":[]}'),
('wger', '1410', 'plank-alternating-leg-lift', 'https://wger.de/en/exercise/1410/view', 'CC-BY-SA-4.0', 'hpmbala@gmail.com', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1410,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"hpmbala@gmail.com","license_author_url":"","license_derivative_source_url":"","uuid":"94f2dea6-b336-41b2-a438-3ab7b13adbf7","category":9,"variation_group":null,"created":"2025-01-03T01:24:29.443Z","last_update":"2025-01-03T01:24:29.443Z","muscles":[8],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2374,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"hpmbala@gmail.com","license_author_url":"","license_derivative_source_url":"","description":"<p>In a plank position, lift one leg alternately.</p>\n","description_source":"In a plank position, lift one leg alternately.","name":"Plank with Alternating Leg Lift","created":"2025-01-03T01:24:29.711Z","last_update":"2026-04-13T18:58:26.974Z","language":2,"uuid":"3c3462c9-16e3-4eac-94bf-12b32cb74caa","exercise":1410}},{"model":"exercises.translation","pk":2375,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"hpmbala@gmail.com","license_author_url":"","license_derivative_source_url":"","description":"<p>En posición de plancha, levanta una pierna alternadamente.</p>\n","description_source":"En posición de plancha, levanta una pierna alternadamente.","name":"Plancha con elevación de pierna","created":"2025-01-03T01:24:29.930Z","last_update":"2026-04-13T18:58:26.955Z","language":4,"uuid":"771cdbc7-3468-4505-b9b5-c9e8ae4e674f","exercise":1410}}],"aliases":[],"comments":[]}'),
('wger', '1411', 'heel-touches', 'https://wger.de/en/exercise/1411/view', 'CC-BY-SA-4.0', 'hpmbala@gmail.com', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1411,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"hpmbala@gmail.com","license_author_url":"","license_derivative_source_url":"","uuid":"cfe3f20e-d078-4e6c-91fc-37da62f5ac0a","category":10,"variation_group":null,"created":"2025-01-03T17:06:14.854Z","last_update":"2025-01-03T17:06:14.854Z","muscles":[14],"muscles_secondary":[6],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2376,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"hpmbala@gmail.com","license_author_url":"","license_derivative_source_url":"","description":"<ul>\n<li>\n<p><strong>Starting Position:</strong></p>\n<ul>\n<li>Lie on your back on an exercise mat.</li>\n<li>Bend your knees, keeping your feet flat on the floor and hip-width apart.</li>\n<li>Place your arms along your sides, palms facing inward, just off the floor.</li>\n</ul>\n</li>\n<li>\n<p><strong>Engage Core:</strong></p>\n<ul>\n<li>Lift your head, shoulders, and upper back slightly off the ground.</li>\n<li>Keep your neck neutral and chin slightly tucked.</li>\n</ul>\n</li>\n<li>\n<p><strong>Perform the Movement:</strong></p>\n<ul>\n<li>Side-bend to the right, reaching your right hand toward your right heel.</li>\n<li>Return to the center, then side-bend to the left, reaching your left hand toward your left heel.</li>\n<li>Continue alternating sides in a controlled manner.</li>\n</ul>\n</li>\n<li>\n<p><strong>Breathing:</strong></p>\n<ul>\n<li>Exhale as you reach toward your heel and inhale as you return to the center.</li>\n</ul>\n</li>\n</ul>\n","description_source":"- **Starting Position:**\n\n  * Lie on your back on an exercise mat.\n  * Bend your knees, keeping your feet flat on the floor and hip-width apart.\n  * Place your arms along your sides, palms facing inward, just off the floor.\n- **Engage Core:**\n\n  * Lift your head, shoulders, and upper back slightly off the ground.\n  * Keep your neck neutral and chin slightly tucked.\n- **Perform the Movement:**\n\n  * Side-bend to the right, reaching your right hand toward your right heel.\n  * Return to the center, then side-bend to the left, reaching your left hand toward your left heel.\n  * Continue alternating sides in a controlled manner.\n- **Breathing:**\n\n  * Exhale as you reach toward your heel and inhale as you return to the center.","name":"Heel Touches","created":"2025-01-03T17:06:15.103Z","last_update":"2026-04-13T18:58:26.618Z","language":2,"uuid":"d00a896e-0426-42bb-ab5b-43aa16acc4ac","exercise":1411}},{"model":"exercises.translation","pk":2377,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"hpmbala@gmail.com","license_author_url":"","license_derivative_source_url":"","description":"<ul>\n<li>\n<p><strong>Posición inicial:</strong></p>\n<ul>\n<li>Acuéstate de espaldas sobre una esterilla de ejercicio.</li>\n<li>Flexiona las rodillas, manteniendo los pies planos en el suelo y separados al ancho de las caderas.</li>\n<li>Coloca los brazos a lo largo de los costados, con las palmas hacia adentro, apenas despegados del suelo.</li>\n</ul>\n</li>\n<li>\n<p><strong>Activa el core:</strong></p>\n<ul>\n<li>Eleva ligeramente la cabeza, los hombros y la parte superior de la espalda del suelo.</li>\n<li>Mantén el cuello en una posición neutral y la barbilla ligeramente hacia adentro.</li>\n</ul>\n</li>\n<li>\n<p><strong>Realiza el movimiento:</strong></p>\n<ul>\n<li>Inclínate hacia la derecha, llevando tu mano derecha hacia tu talón derecho.</li>\n<li>Vuelve al centro y luego inclínate hacia la izquierda, llevando tu mano izquierda hacia tu talón izquierdo.</li>\n<li>Continúa alternando lados de manera controlada.</li>\n</ul>\n</li>\n<li>\n<p><strong>Respiración:</strong></p>\n<ul>\n<li>Exhala al alcanzar el talón e inhala al regresar al centro.</li>\n</ul>\n</li>\n</ul>\n","description_source":"- **Posición inicial:**\n\n  * Acuéstate de espaldas sobre una esterilla de ejercicio.\n  * Flexiona las rodillas, manteniendo los pies planos en el suelo y separados al ancho de las caderas.\n  * Coloca los brazos a lo largo de los costados, con las palmas hacia adentro, apenas despegados del suelo.\n- **Activa el core:**\n\n  * Eleva ligeramente la cabeza, los hombros y la parte superior de la espalda del suelo.\n  * Mantén el cuello en una posición neutral y la barbilla ligeramente hacia adentro.\n- **Realiza el movimiento:**\n\n  * Inclínate hacia la derecha, llevando tu mano derecha hacia tu talón derecho.\n  * Vuelve al centro y luego inclínate hacia la izquierda, llevando tu mano izquierda hacia tu talón izquierdo.\n  * Continúa alternando lados de manera controlada.\n- **Respiración:**\n\n  * Exhala al alcanzar el talón e inhala al regresar al centro.","name":"Toques de Talón","created":"2025-01-03T17:06:15.337Z","last_update":"2026-04-13T18:58:27.663Z","language":4,"uuid":"866f93f3-9bd3-41bd-8986-0ecc0e9df160","exercise":1411}}],"aliases":[],"comments":[]}'),
('wger', '1412', 'bicycle-crunch', 'https://wger.de/en/exercise/1412/view', 'CC-BY-SA-4.0', 'hpmbala@gmail.com', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1412,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"hpmbala@gmail.com","license_author_url":"","license_derivative_source_url":"","uuid":"fcf5039b-7784-4f82-830a-b213b597a646","category":10,"variation_group":null,"created":"2025-01-07T01:40:32.635Z","last_update":"2025-01-07T01:40:32.635Z","muscles":[6],"muscles_secondary":[14],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2378,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"hpmbala@gmail.com","license_author_url":"","license_derivative_source_url":"","description":"<p>Bicycle crunches are a core exercise performed on the floor. Lie on your back with your hands behind your head and legs extended. Lift your shoulders off the ground, bring one knee toward your chest, and twist your torso so your opposite elbow meets the knee. Alternate sides in a pedaling motion, ensuring controlled movements and engaging your core throughout the exercise.</p>\n","description_source":"Bicycle crunches are a core exercise performed on the floor. Lie on your back with your hands behind your head and legs extended. Lift your shoulders off the ground, bring one knee toward your chest, and twist your torso so your opposite elbow meets the knee. Alternate sides in a pedaling motion, ensuring controlled movements and engaging your core throughout the exercise.","name":"bicycle crunches","created":"2025-01-07T01:40:32.909Z","last_update":"2026-04-13T18:58:27.941Z","language":2,"uuid":"2a7af9f8-f44e-460c-b332-fcf60cda42a5","exercise":1412}},{"model":"exercises.translation","pk":2379,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"hpmbala@gmail.com","license_author_url":"","license_derivative_source_url":"","description":"<p>Los abdominales en bicicleta son un ejercicio para el core que se realiza en el suelo. Acuéstate de espaldas con las manos detrás de la cabeza y las piernas extendidas. Eleva los hombros del suelo, lleva una rodilla hacia el pecho y gira el torso para que el codo opuesto toque la rodilla. Alterna los lados en un movimiento de pedaleo, asegurándote de mantener el core comprometido durante todo el ejercicio.</p>\n","description_source":"Los abdominales en bicicleta son un ejercicio para el core que se realiza en el suelo. Acuéstate de espaldas con las manos detrás de la cabeza y las piernas extendidas. Eleva los hombros del suelo, lleva una rodilla hacia el pecho y gira el torso para que el codo opuesto toque la rodilla. Alterna los lados en un movimiento de pedaleo, asegurándote de mantener el core comprometido durante todo el ejercicio.","name":"Abdominales en bicicleta","created":"2025-01-07T01:40:33.123Z","last_update":"2026-04-13T18:58:25.992Z","language":4,"uuid":"17630b32-87bf-491c-852f-8f5b7bd6a8b4","exercise":1412}}],"aliases":[],"comments":[]}'),
('wger', '1414', 'hack-squat', 'https://wger.de/en/exercise/1414/view', 'CC-BY-SA-4.0', 'hpmbala@gmail.com', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1414,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"hpmbala@gmail.com","license_author_url":"","license_derivative_source_url":"","uuid":"f462df26-3264-48c2-b5aa-2374d0670c24","category":9,"variation_group":null,"created":"2025-01-10T02:05:21.881Z","last_update":"2025-01-10T02:05:21.881Z","muscles":[10],"muscles_secondary":[11,7,8],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2383,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"hpmbala@gmail.com","license_author_url":"","license_derivative_source_url":"","description":"<p>Hack squats target the lower body and are performed on a hack squat machine or with a barbell. For the machine variation, position yourself on the platform with your shoulders under the pads and feet slightly forward. Push through your heels to lift the weight, then bend your knees to lower the platform in a controlled motion until your thighs are parallel to the ground. Push back up to the starting position. For the barbell variation, hold the bar behind your legs with your arms extended and perform a squat-like motion.</p>\n","description_source":"Hack squats target the lower body and are performed on a hack squat machine or with a barbell. For the machine variation, position yourself on the platform with your shoulders under the pads and feet slightly forward. Push through your heels to lift the weight, then bend your knees to lower the platform in a controlled motion until your thighs are parallel to the ground. Push back up to the starting position. For the barbell variation, hold the bar behind your legs with your arms extended and perform a squat-like motion.","name":"Hack Squats","created":"2025-01-10T02:05:22.140Z","last_update":"2026-04-13T18:58:26.599Z","language":2,"uuid":"9f97983c-2eea-40f1-b4c8-3592716fa681","exercise":1414}},{"model":"exercises.translation","pk":2384,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"hpmbala@gmail.com","license_author_url":"","license_derivative_source_url":"","description":"<p>Las sentadillas hack son un ejercicio para la parte inferior del cuerpo que se realiza en una máquina hack squat o con barra. En la variación con máquina, coloca los hombros bajo las almohadillas y los pies ligeramente hacia adelante en la plataforma. Empuja con los talones para levantar el peso, luego flexiona las rodillas para bajar la plataforma de manera controlada hasta que los muslos estén paralelos al suelo. Empuja de vuelta a la posición inicial. En la variación con barra, sostiene la barra detrás de las piernas con los brazos extendidos y realiza un movimiento similar a una sentadilla.</p>\n","description_source":"Las sentadillas hack son un ejercicio para la parte inferior del cuerpo que se realiza en una máquina hack squat o con barra. En la variación con máquina, coloca los hombros bajo las almohadillas y los pies ligeramente hacia adelante en la plataforma. Empuja con los talones para levantar el peso, luego flexiona las rodillas para bajar la plataforma de manera controlada hasta que los muslos estén paralelos al suelo. Empuja de vuelta a la posición inicial. En la variación con barra, sostiene la barra detrás de las piernas con los brazos extendidos y realiza un movimiento similar a una sentadilla.","name":"Sentadillas Hack","created":"2025-01-10T02:05:22.362Z","last_update":"2026-04-13T18:58:27.323Z","language":4,"uuid":"08f0e180-a187-4b44-999b-2522e7b32ba9","exercise":1414}}],"aliases":[],"comments":[]}'),
('wger', '1415', 'dumbbell-crunch', 'https://wger.de/en/exercise/1415/view', 'CC-BY-SA-4.0', 'hpmbala@gmail.com', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1415,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"hpmbala@gmail.com","license_author_url":"","license_derivative_source_url":"","uuid":"b48e4d9d-f7fc-4619-85fb-6dabe5d7c999","category":10,"variation_group":null,"created":"2025-01-10T02:20:17.394Z","last_update":"2025-01-10T02:20:17.394Z","muscles":[6],"muscles_secondary":[14],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2385,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"hpmbala@gmail.com","license_author_url":"","license_derivative_source_url":"","description":"<p>Dumbbell crunches are a weighted variation of traditional crunches designed to target the abdominal muscles more intensely. Lie flat on your back with your knees bent and feet flat on the floor. Hold a dumbbell with both hands close to your chest or above your head. Lift your shoulders and upper back off the ground in a crunching motion, engaging your core. Slowly lower yourself back to the starting position. Ensure controlled movements throughout the exercise to prevent strain.</p>\n","description_source":"Dumbbell crunches are a weighted variation of traditional crunches designed to target the abdominal muscles more intensely. Lie flat on your back with your knees bent and feet flat on the floor. Hold a dumbbell with both hands close to your chest or above your head. Lift your shoulders and upper back off the ground in a crunching motion, engaging your core. Slowly lower yourself back to the starting position. Ensure controlled movements throughout the exercise to prevent strain.","name":"Dumbbell Crunches","created":"2025-01-10T02:20:17.641Z","last_update":"2026-04-13T18:58:26.415Z","language":2,"uuid":"c7c888e9-00c5-416c-8a81-f3034393909d","exercise":1415}},{"model":"exercises.translation","pk":2386,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"hpmbala@gmail.com","license_author_url":"","license_derivative_source_url":"","description":"<p>Los abdominales con mancuerna son una variación con peso de los abdominales tradicionales, diseñados para trabajar los músculos abdominales con mayor intensidad. Acuéstate de espaldas con las rodillas dobladas y los pies apoyados en el suelo. Sostén una mancuerna con ambas manos cerca del pecho o sobre la cabeza. Levanta los hombros y la parte superior de la espalda del suelo en un movimiento de contracción, activando el core. Baja lentamente a la posición inicial. Asegúrate de mantener movimientos controlados durante el ejercicio para evitar lesiones.</p>\n","description_source":"Los abdominales con mancuerna son una variación con peso de los abdominales tradicionales, diseñados para trabajar los músculos abdominales con mayor intensidad. Acuéstate de espaldas con las rodillas dobladas y los pies apoyados en el suelo. Sostén una mancuerna con ambas manos cerca del pecho o sobre la cabeza. Levanta los hombros y la parte superior de la espalda del suelo en un movimiento de contracción, activando el core. Baja lentamente a la posición inicial. Asegúrate de mantener movimientos controlados durante el ejercicio para evitar lesiones.","name":"Abdominales con mancuerna","created":"2025-01-10T02:20:17.848Z","last_update":"2026-04-13T18:58:25.987Z","language":4,"uuid":"36e6b473-ec87-43d8-9733-5486a86c8547","exercise":1415}}],"aliases":[],"comments":[]}'),
('wger', '1424', 'machine-biceps-curl', 'https://wger.de/en/exercise/1424/view', 'CC-BY-SA-4.0', 'hpmbala@gmail.com', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1424,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"hpmbala@gmail.com","license_author_url":"","license_derivative_source_url":"","uuid":"e68f6d51-fe02-4175-b277-dec0c1521f36","category":8,"variation_group":null,"created":"2025-01-15T02:35:17.015Z","last_update":"2025-01-15T02:35:17.016Z","muscles":[1],"muscles_secondary":[13],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2387,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"hpmbala@gmail.com","license_author_url":"","license_derivative_source_url":"","description":"<p>The biceps curl machine is designed to isolate the biceps muscles and provide a controlled range of motion. Sit on the machine with your back against the pad and adjust the seat so your arms are aligned with the machine''s handles or pads. Grip the handles firmly, keeping your elbows fixed in place, and curl the handles upward by contracting your biceps. Slowly lower the handles to the starting position, maintaining control throughout the movement.</p>\n","description_source":"The biceps curl machine is designed to isolate the biceps muscles and provide a controlled range of motion. Sit on the machine with your back against the pad and adjust the seat so your arms are aligned with the machine''s handles or pads. Grip the handles firmly, keeping your elbows fixed in place, and curl the handles upward by contracting your biceps. Slowly lower the handles to the starting position, maintaining control throughout the movement.","name":"Biceps Curl Machine","created":"2025-01-15T02:35:17.317Z","last_update":"2026-04-13T18:58:26.110Z","language":2,"uuid":"f07d4a46-2ece-4d2f-9319-cc23f4086320","exercise":1424}},{"model":"exercises.translation","pk":2388,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"hpmbala@gmail.com","license_author_url":"","license_derivative_source_url":"","description":"<p>La máquina de curl de bíceps está diseñada para aislar los músculos del bíceps y proporcionar un rango de movimiento controlado. Siéntate en la máquina con la espalda apoyada en el respaldo y ajusta el asiento para que tus brazos estén alineados con las manijas o almohadillas de la máquina. Agarra las manijas con firmeza, manteniendo los codos fijos en su lugar, y levanta las manijas contrayendo los bíceps. Baja las manijas lentamente a la posición inicial, manteniendo el control durante todo el movimiento.</p>\n","description_source":"La máquina de curl de bíceps está diseñada para aislar los músculos del bíceps y proporcionar un rango de movimiento controlado. Siéntate en la máquina con la espalda apoyada en el respaldo y ajusta el asiento para que tus brazos estén alineados con las manijas o almohadillas de la máquina. Agarra las manijas con firmeza, manteniendo los codos fijos en su lugar, y levanta las manijas contrayendo los bíceps. Baja las manijas lentamente a la posición inicial, manteniendo el control durante todo el movimiento.","name":"Curl de bíceps sentado","created":"2025-01-15T02:35:17.634Z","last_update":"2026-04-13T18:58:26.336Z","language":4,"uuid":"90f63639-4366-4dca-8d0e-77961757fc3f","exercise":1424}}],"aliases":[],"comments":[]}'),
('wger', '1425', 'toe-taps', 'https://wger.de/en/exercise/1425/view', 'CC-BY-SA-4.0', 'hpmbala@gmail.com', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1425,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"hpmbala@gmail.com","license_author_url":"","license_derivative_source_url":"","uuid":"33728393-2b84-4d39-8b68-462222e004e3","category":10,"variation_group":null,"created":"2025-01-15T02:47:11.890Z","last_update":"2025-01-15T02:47:11.890Z","muscles":[6],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2389,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"hpmbala@gmail.com","license_author_url":"","license_derivative_source_url":"","description":"<p>Toe taps are a core-focused exercise performed lying on your back. Lie flat with your arms by your sides and your legs raised to a tabletop position (knees bent at 90 degrees). Slowly lower one foot to gently tap the floor, keeping your core engaged and your lower back pressed into the ground. Return to the starting position and alternate legs. This exercise strengthens the core while minimizing strain on the lower back.</p>\n","description_source":"Toe taps are a core-focused exercise performed lying on your back. Lie flat with your arms by your sides and your legs raised to a tabletop position (knees bent at 90 degrees). Slowly lower one foot to gently tap the floor, keeping your core engaged and your lower back pressed into the ground. Return to the starting position and alternate legs. This exercise strengthens the core while minimizing strain on the lower back.","name":"Toe Taps","created":"2025-01-15T02:47:12.212Z","last_update":"2026-04-13T18:58:27.657Z","language":2,"uuid":"7da93f8a-bc5d-4793-87ff-1ed22252a92a","exercise":1425}},{"model":"exercises.translation","pk":2390,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"hpmbala@gmail.com","license_author_url":"","license_derivative_source_url":"","description":"<p>Los toques de pie son un ejercicio enfocado en el core que se realiza acostado de espaldas. Acuéstate con los brazos a los lados y las piernas elevadas en posición de mesa (rodillas dobladas a 90 grados). Baja lentamente un pie para tocar el suelo suavemente, manteniendo el core activado y la espalda baja presionada contra el suelo. Regresa a la posición inicial y alterna las piernas. Este ejercicio fortalece el core mientras reduce la tensión en la parte baja de la espalda.</p>\n","description_source":"Los toques de pie son un ejercicio enfocado en el core que se realiza acostado de espaldas. Acuéstate con los brazos a los lados y las piernas elevadas en posición de mesa (rodillas dobladas a 90 grados). Baja lentamente un pie para tocar el suelo suavemente, manteniendo el core activado y la espalda baja presionada contra el suelo. Regresa a la posición inicial y alterna las piernas. Este ejercicio fortalece el core mientras reduce la tensión en la parte baja de la espalda.","name":"Toques de pie alternados","created":"2025-01-15T02:47:12.433Z","last_update":"2026-04-13T18:58:27.664Z","language":4,"uuid":"0c340bf8-521f-4d36-8c12-55e4fd3c1e98","exercise":1425}}],"aliases":[],"comments":[]}'),
('wger', '1426', 'standing-side-crunch', 'https://wger.de/en/exercise/1426/view', 'CC-BY-SA-4.0', 'hpmbala@gmail.com', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1426,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"hpmbala@gmail.com","license_author_url":"","license_derivative_source_url":"","uuid":"864b0a80-5d29-4d87-9144-f6ee6f5087b9","category":10,"variation_group":null,"created":"2025-01-15T02:58:36.558Z","last_update":"2025-01-15T02:58:36.558Z","muscles":[14],"muscles_secondary":[6],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2391,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"hpmbala@gmail.com","license_author_url":"","license_derivative_source_url":"","description":"<p>Standing side crunches are a dynamic exercise that targets the obliques while improving balance and stability. Stand upright with your feet shoulder-width apart and hands behind your head or holding a dumbbell in one hand. Lean your torso to one side, contracting your obliques, while bringing your elbow toward your hip (or crunching toward the weight if using a dumbbell). Return to the starting position and alternate sides or perform all repetitions on one side before switching.</p>\n","description_source":"Standing side crunches are a dynamic exercise that targets the obliques while improving balance and stability. Stand upright with your feet shoulder-width apart and hands behind your head or holding a dumbbell in one hand. Lean your torso to one side, contracting your obliques, while bringing your elbow toward your hip (or crunching toward the weight if using a dumbbell). Return to the starting position and alternate sides or perform all repetitions on one side before switching.","name":"Standing Side Crunches","created":"2025-01-15T02:58:36.802Z","last_update":"2026-04-13T18:58:27.530Z","language":2,"uuid":"06ead0a5-34f2-4a7e-8749-035a82d7ef42","exercise":1426}},{"model":"exercises.translation","pk":2392,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"hpmbala@gmail.com","license_author_url":"","license_derivative_source_url":"","description":"<p>Los crunches laterales de pie son un ejercicio dinámico que trabaja los oblicuos mientras mejora el equilibrio y la estabilidad. Párate derecho con los pies a la altura de los hombros y las manos detrás de la cabeza o sosteniendo una mancuerna en una mano. Inclina el torso hacia un lado, contrayendo los oblicuos, mientras llevas el codo hacia la cadera (o realizas el crunch hacia el peso si usas mancuerna). Regresa a la posición inicial y alterna lados o realiza todas las repeticiones en un lado antes de cambiar.</p>\n","description_source":"Los crunches laterales de pie son un ejercicio dinámico que trabaja los oblicuos mientras mejora el equilibrio y la estabilidad. Párate derecho con los pies a la altura de los hombros y las manos detrás de la cabeza o sosteniendo una mancuerna en una mano. Inclina el torso hacia un lado, contrayendo los oblicuos, mientras llevas el codo hacia la cadera (o realizas el crunch hacia el peso si usas mancuerna). Regresa a la posición inicial y alterna lados o realiza todas las repeticiones en un lado antes de cambiar.","name":"Crunch lateral de pie","created":"2025-01-15T02:58:37.028Z","last_update":"2026-04-13T18:58:26.249Z","language":4,"uuid":"1c4c784b-4f2a-42e6-954b-57cbbfc243f3","exercise":1426}}],"aliases":[],"comments":[]}'),
('wger', '1429', 'dumbbell-shoulder-rotation', 'https://wger.de/en/exercise/1429/view', 'CC-BY-SA-4.0', 'hpmbala@gmail.com', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1429,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"hpmbala@gmail.com","license_author_url":"","license_derivative_source_url":"","uuid":"5a9f4fa4-6b71-4bc7-a284-e76e43e3106a","category":13,"variation_group":null,"created":"2025-01-23T02:56:45.378Z","last_update":"2025-01-23T02:56:45.378Z","muscles":[2],"muscles_secondary":[],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2393,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"hpmbala@gmail.com","license_author_url":"","license_derivative_source_url":"","description":"<p>Dumbbell shoulder rotations are designed to strengthen the rotator cuff muscles and improve shoulder stability and mobility.</p>\n<ol>\n<li><strong>External Rotation</strong>: Hold a dumbbell in one hand, keeping your elbow bent at 90 degrees and close to your body. Rotate your forearm outward, away from your body, keeping your elbow stationary. Slowly return to the starting position.</li>\n<li><strong>Internal Rotation</strong>: Hold a dumbbell in one hand, keeping your elbow bent at 90 degrees and close to your body. Rotate your forearm inward, toward your body, and slowly return to the starting position. Perform the exercise with controlled movements to avoid strain.</li>\n</ol>\n","description_source":"Dumbbell shoulder rotations are designed to strengthen the rotator cuff muscles and improve shoulder stability and mobility.\n\n1. **External Rotation**: Hold a dumbbell in one hand, keeping your elbow bent at 90 degrees and close to your body. Rotate your forearm outward, away from your body, keeping your elbow stationary. Slowly return to the starting position.\n2. **Internal Rotation**: Hold a dumbbell in one hand, keeping your elbow bent at 90 degrees and close to your body. Rotate your forearm inward, toward your body, and slowly return to the starting position. Perform the exercise with controlled movements to avoid strain.","name":"Dumbbell Shoulder Rotations","created":"2025-01-23T02:56:53.578Z","last_update":"2026-04-13T18:58:26.435Z","language":2,"uuid":"300d8723-8330-46af-a95e-75c172af76f1","exercise":1429}},{"model":"exercises.translation","pk":2394,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"hpmbala@gmail.com","license_author_url":"","license_derivative_source_url":"","description":"<p>Las rotaciones de hombro con mancuerna están diseñadas para fortalecer los músculos del manguito rotador y mejorar la estabilidad y movilidad del hombro.</p>\n<ol>\n<li><strong>Rotación Externa</strong>: Sostén una mancuerna en una mano, con el codo doblado a 90 grados y pegado al cuerpo. Rota el antebrazo hacia afuera, alejándolo del cuerpo, manteniendo el codo fijo. Vuelve lentamente a la posición inicial.</li>\n<li><strong>Rotación Interna</strong>: Sostén una mancuerna en una mano, con el codo doblado a 90 grados y pegado al cuerpo. Rota el antebrazo hacia adentro, acercándolo al cuerpo, y vuelve lentamente a la posición inicial. Realiza el ejercicio con movimientos controlados para evitar lesiones.</li>\n</ol>\n","description_source":"Las rotaciones de hombro con mancuerna están diseñadas para fortalecer los músculos del manguito rotador y mejorar la estabilidad y movilidad del hombro.\n\n1. **Rotación Externa**: Sostén una mancuerna en una mano, con el codo doblado a 90 grados y pegado al cuerpo. Rota el antebrazo hacia afuera, alejándolo del cuerpo, manteniendo el codo fijo. Vuelve lentamente a la posición inicial.\n2. **Rotación Interna**: Sostén una mancuerna en una mano, con el codo doblado a 90 grados y pegado al cuerpo. Rota el antebrazo hacia adentro, acercándolo al cuerpo, y vuelve lentamente a la posición inicial. Realiza el ejercicio con movimientos controlados para evitar lesiones.","name":"Rotaciones de hombro con mancuerna","created":"2025-01-23T02:56:56.391Z","last_update":"2026-04-13T18:58:27.178Z","language":4,"uuid":"a4ade560-0201-4d93-b0df-7f462c3812ee","exercise":1429}}],"aliases":[],"comments":[]}'),
('wger', '1430', 'plate-pinch-hold', 'https://wger.de/en/exercise/1430/view', 'CC-BY-SA-4.0', 'hpmbala@gmail.com', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1430,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"hpmbala@gmail.com","license_author_url":"","license_derivative_source_url":"","uuid":"493fb1ac-c45a-4b18-bcbb-58b809881e6f","category":8,"variation_group":null,"created":"2025-01-23T03:09:23.197Z","last_update":"2025-01-23T03:09:23.197Z","muscles":[2],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2395,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"hpmbala@gmail.com","license_author_url":"","license_derivative_source_url":"","description":"<p>The plate pinch hold is a grip strength exercise designed to target the forearms and improve grip endurance. Select one or two weight plates (smooth-edged plates work best) and pinch them together between your thumb and fingers. Hold the plates with your arm straight down by your side or extended slightly in front of you. Maintain the hold for as long as you can, keeping your shoulders relaxed and your grip firm. This exercise can be done for time or repetitions.</p>\n","description_source":"The plate pinch hold is a grip strength exercise designed to target the forearms and improve grip endurance. Select one or two weight plates (smooth-edged plates work best) and pinch them together between your thumb and fingers. Hold the plates with your arm straight down by your side or extended slightly in front of you. Maintain the hold for as long as you can, keeping your shoulders relaxed and your grip firm. This exercise can be done for time or repetitions.","name":"Plate Pinch Hold","created":"2025-01-23T03:09:23.519Z","last_update":"2026-04-13T18:58:26.976Z","language":2,"uuid":"29254b00-946b-4a9b-a76c-29354a35845f","exercise":1430}},{"model":"exercises.translation","pk":2396,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"hpmbala@gmail.com","license_author_url":"","license_derivative_source_url":"","description":"<p>El sostén con pellizco de disco es un ejercicio para mejorar la fuerza de agarre y la resistencia en los antebrazos. Selecciona uno o dos discos de pesas (los discos de bordes lisos son ideales) y pínzalos entre el pulgar y los dedos. Mantén los discos con el brazo recto hacia abajo a tu lado o ligeramente extendido frente a ti. Sostén la posición el mayor tiempo posible, manteniendo los hombros relajados y el agarre firme. Este ejercicio puede realizarse por tiempo o repeticiones.</p>\n","description_source":"El sostén con pellizco de disco es un ejercicio para mejorar la fuerza de agarre y la resistencia en los antebrazos. Selecciona uno o dos discos de pesas (los discos de bordes lisos son ideales) y pínzalos entre el pulgar y los dedos. Mantén los discos con el brazo recto hacia abajo a tu lado o ligeramente extendido frente a ti. Sostén la posición el mayor tiempo posible, manteniendo los hombros relajados y el agarre firme. Este ejercicio puede realizarse por tiempo o repeticiones.","name":"Sostén con pellizco de disco","created":"2025-01-23T03:09:23.755Z","last_update":"2026-04-13T18:58:27.450Z","language":4,"uuid":"4ec0d8e1-4148-4977-a05a-b1debbf386af","exercise":1430}}],"aliases":[],"comments":[]}'),
('wger', '1433', 'reverse-wood-chops', 'https://wger.de/en/exercise/1433/view', 'CC-BY-SA-4.0', 'M9', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1433,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"M9","license_author_url":"","license_derivative_source_url":"","uuid":"6f5d4373-66d1-4acd-a16f-ba0e636fe979","category":12,"variation_group":null,"created":"2025-01-24T15:58:46.446Z","last_update":"2025-01-24T15:58:46.446Z","muscles":[8,12],"muscles_secondary":[2,1,14,10,6],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2397,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"M9","license_author_url":"","license_derivative_source_url":"","description":"<ul>\n<li>Attach a looping resistance band to a rack below knee height</li>\n<li>Grip the other end of the band like holding a baseball bat with both hands</li>\n<li>Stretch the band facing it</li>\n<li>Start with your hands at the side of your hips, knees bent</li>\n<li>Rotate your hips while moving your hands towards over the top of your opposite shoulder</li>\n<li>Imagine the motion as striking a baseball with a bat</li>\n</ul>\n","description_source":"* Attach a looping resistance band to a rack below knee height\n* Grip the other end of the band like holding a baseball bat with both hands\n* Stretch the band facing it\n* Start with your hands at the side of your hips, knees bent\n* Rotate your hips while moving your hands towards over the top of your opposite shoulder\n* Imagine the motion as striking a baseball with a bat","name":"Reverse Wood Chops","created":"2025-01-24T15:58:46.586Z","last_update":"2026-04-13T18:58:27.157Z","language":2,"uuid":"43afa4fe-6188-4808-9d54-842b6ba47254","exercise":1433}}],"aliases":[],"comments":[{"model":"exercises.exercisecomment","pk":540,"fields":{"uuid":"451fe238-f5a7-416e-a05f-61b84c03f32e","translation":2397,"comment":"Keep arms almost fully extended throughout"}},{"model":"exercises.exercisecomment","pk":541,"fields":{"uuid":"5b8ea843-1dfc-40cc-96ce-7ba768c7ddb5","translation":2397,"comment":"Use as much force as possible"}}]}'),
('wger', '1434', 'dumbbell-lat-pull', 'https://wger.de/en/exercise/1434/view', 'CC-BY-SA-4.0', 'M9', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1434,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"M9","license_author_url":"","license_derivative_source_url":"","uuid":"90dea8b9-4cf8-430e-8633-e08df1dd900b","category":12,"variation_group":null,"created":"2025-01-24T17:16:34.167Z","last_update":"2025-01-24T17:16:34.168Z","muscles":[12],"muscles_secondary":[8],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2398,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"M9","license_author_url":"","license_derivative_source_url":"","description":"<ul>\n<li>Bend upper body forward</li>\n<li>Move dumbbells near your body with slightly bent arms towards your back</li>\n</ul>\n","description_source":"* Bend upper body forward\n* Move dumbbells near your body with slightly bent arms towards your back","name":"Lat Pull DB","created":"2025-01-24T17:16:34.324Z","last_update":"2026-04-13T18:58:26.757Z","language":2,"uuid":"b507ee86-6cec-46f3-9708-ee82839985c5","exercise":1434}}],"aliases":[],"comments":[]}'),
('wger', '1435', 'scapula-pull', 'https://wger.de/en/exercise/1435/view', 'CC-BY-SA-4.0', 'M9', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1435,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"M9","license_author_url":"","license_derivative_source_url":"","uuid":"2a983b8f-b77e-4f8f-8335-0e5caecd715f","category":12,"variation_group":null,"created":"2025-01-24T17:21:21.963Z","last_update":"2025-01-24T17:21:21.963Z","muscles":[12,9],"muscles_secondary":[],"equipment":[6]}},"translations":[{"model":"exercises.translation","pk":2399,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"M9","license_author_url":"","license_derivative_source_url":"","description":"<ul>\n<li>Hang straight on a pull-up bar</li>\n<li>Pull shoulder blades together, moving the body slightly up</li>\n</ul>\n","description_source":"* Hang straight on a pull-up bar\n* Pull shoulder blades together, moving the body slightly up","name":"Scapula Pulls","created":"2025-01-24T17:21:22.149Z","last_update":"2026-04-13T18:58:27.231Z","language":2,"uuid":"3fad07d8-618c-479d-83ad-9ae5b44cbbab","exercise":1435}}],"aliases":[],"comments":[]}'),
('wger', '1436', 'barbell-pin-bench-press', 'https://wger.de/en/exercise/1436/view', 'CC-BY-SA-4.0', 'M9', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1436,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"M9","license_author_url":"","license_derivative_source_url":"","uuid":"abd2854b-114a-4584-8746-30bd40127863","category":11,"variation_group":null,"created":"2025-01-24T17:41:31.595Z","last_update":"2025-01-24T17:41:31.595Z","muscles":[4,5],"muscles_secondary":[],"equipment":[1]}},"translations":[{"model":"exercises.translation","pk":2400,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"M9","license_author_url":"","license_derivative_source_url":"","description":"<ul>\n<li>Set security pins to about the height of your sticking point</li>\n<li>Lower the bar, rest on the pins for 1s while holding tension</li>\n<li>Move bar up with maximum force</li>\n</ul>\n","description_source":"* Set security pins to about the height of your sticking point\n* Lower the bar, rest on the pins for 1s while holding tension\n* Move bar up with maximum force","name":"Pin Bench Press BB","created":"2025-01-24T17:41:31.828Z","last_update":"2026-04-13T18:58:26.937Z","language":2,"uuid":"da069fa5-1e79-49fa-808f-0a95ad1701c5","exercise":1436}}],"aliases":[],"comments":[]}'),
('wger', '1437', 'barbell-pin-squat', 'https://wger.de/en/exercise/1437/view', 'CC-BY-SA-4.0', 'M9', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1437,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"M9","license_author_url":"","license_derivative_source_url":"","uuid":"96f9d74a-7bf4-4ec1-9cd6-c62c13cf7b67","category":9,"variation_group":null,"created":"2025-01-24T17:47:29.990Z","last_update":"2025-01-24T17:47:29.990Z","muscles":[11,8,10],"muscles_secondary":[6],"equipment":[1]}},"translations":[{"model":"exercises.translation","pk":2401,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"M9","license_author_url":"","license_derivative_source_url":"","description":"<ul>\n<li>Set security pins to about the height of your sticking point</li>\n<li>Lower the bar, rest on the pins for 2s keeping tension</li>\n<li>Stand up with maximum force</li>\n</ul>\n","description_source":"* Set security pins to about the height of your sticking point\n* Lower the bar, rest on the pins for 2s keeping tension\n* Stand up with maximum force","name":"Pin Squat","created":"2025-01-24T17:47:30.172Z","last_update":"2026-04-13T18:58:26.939Z","language":2,"uuid":"fc554b85-6b79-4de8-9212-f3e4464c749d","exercise":1437}}],"aliases":[],"comments":[]}'),
('wger', '1438', 'barbell-clean', 'https://wger.de/en/exercise/1438/view', 'CC-BY-SA-4.0', 'M9', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1438,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"M9","license_author_url":"","license_derivative_source_url":"","uuid":"a8f76beb-b6d8-430b-8e45-cc03d4959043","category":9,"variation_group":null,"created":"2025-01-24T18:03:52.258Z","last_update":"2025-01-24T18:03:52.258Z","muscles":[8,10],"muscles_secondary":[11,12,6],"equipment":[1]}},"translations":[{"model":"exercises.translation","pk":2402,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"M9","license_author_url":"","license_derivative_source_url":"","description":"<p>Regular olympic lift clean.\nPull bar from ground, catch on shoulders performing a front squat.</p>\n","description_source":"Regular olympic lift clean.\nPull bar from ground, catch on shoulders performing a front squat.","name":"Clean","created":"2025-01-24T18:03:52.528Z","last_update":"2026-04-13T18:58:26.212Z","language":2,"uuid":"6908b8b5-a56b-4962-973d-7c9d4408b5c5","exercise":1438}}],"aliases":[],"comments":[{"model":"exercises.exercisecomment","pk":542,"fields":{"uuid":"2ee09f26-8ecb-4edb-9881-5d54b346cfba","translation":2402,"comment":"Keep ellbows up"}}]}'),
('wger', '1439', 'barbell-pin-ohp', 'https://wger.de/en/exercise/1439/view', 'CC-BY-SA-4.0', 'M9', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1439,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"M9","license_author_url":"","license_derivative_source_url":"","uuid":"a33ba0c7-1680-4e42-a84e-aecc18c5d75b","category":13,"variation_group":null,"created":"2025-01-24T18:13:41.500Z","last_update":"2025-01-24T18:13:41.500Z","muscles":[2,5],"muscles_secondary":[],"equipment":[1]}},"translations":[{"model":"exercises.translation","pk":2403,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"M9","license_author_url":"","license_derivative_source_url":"","description":"<ul>\n<li>Set security pins to the height of your lower chin</li>\n<li>Rest bar on pins keeping tension</li>\n<li>Raise bar over head</li>\n</ul>\n","description_source":"* Set security pins to the height of your lower chin\n* Rest bar on pins keeping tension\n* Raise bar over head","name":"Pin OHP","created":"2025-01-24T18:13:41.598Z","last_update":"2026-04-13T18:58:26.938Z","language":2,"uuid":"48377dd7-c51a-4f02-988d-5246df367780","exercise":1439}}],"aliases":[],"comments":[]}');
