('wger', '1440', 'barbell-push-ohp', 'https://wger.de/en/exercise/1440/view', 'CC-BY-SA-4.0', 'M9', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1440,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"M9","license_author_url":"","license_derivative_source_url":"","uuid":"a535b8f1-2024-4c5c-b323-f711cbf9773c","category":13,"variation_group":null,"created":"2025-01-24T18:23:13.870Z","last_update":"2025-01-24T18:23:13.870Z","muscles":[2,8,10],"muscles_secondary":[5],"equipment":[1]}},"translations":[{"model":"exercises.translation","pk":2404,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"M9","license_author_url":"","license_derivative_source_url":"","description":"<ul>\n<li>Rest bar in front on your shoulders</li>\n<li>Bend knees while keeping upper body straight</li>\n<li>Extend legs pushing the bar overhead with force</li>\n</ul>\n","description_source":"* Rest bar in front on your shoulders\n* Bend knees while keeping upper body straight\n* Extend legs pushing the bar overhead with force","name":"Push OHP","created":"2025-01-24T18:23:14.126Z","last_update":"2026-04-13T18:58:27.101Z","language":2,"uuid":"a58b2681-2c2b-4f1b-af64-c40e30c94ae0","exercise":1440}}],"aliases":[],"comments":[]}'),
('wger', '1441', 'dumbbell-incline-ohp', 'https://wger.de/en/exercise/1441/view', 'CC-BY-SA-4.0', 'M9', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1441,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"M9","license_author_url":"","license_derivative_source_url":"","uuid":"f89b3662-f911-4aab-9402-cfa6d47cea2b","category":13,"variation_group":null,"created":"2025-01-24T18:46:31.371Z","last_update":"2025-01-24T18:46:31.371Z","muscles":[2],"muscles_secondary":[5],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2405,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"M9","license_author_url":"","license_derivative_source_url":"","description":"<ul>\n<li>Sit on a bench with 45° incline</li>\n<li>Ellbows 45° out</li>\n<li>Move dumbbells down until upper arms are parallel to shoulders</li>\n<li>Move dumbbells up, meeting overhead</li>\n</ul>\n","description_source":"* Sit on a bench with 45° incline\n* Ellbows 45° out\n* Move dumbbells down until upper arms are parallel to shoulders\n* Move dumbbells up, meeting overhead","name":"Incline OHP DB","created":"2025-01-24T18:46:31.491Z","last_update":"2026-04-13T18:58:26.659Z","language":2,"uuid":"513476ef-cd2e-4b18-9025-4d1e834f31e6","exercise":1441}}],"aliases":[],"comments":[]}'),
('wger', '1442', 'dumbbell-kreis-press', 'https://wger.de/en/exercise/1442/view', 'CC-BY-SA-4.0', 'M9', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1442,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"M9","license_author_url":"","license_derivative_source_url":"","uuid":"b4e78b5a-6141-4fc9-a6f7-cba13ce6559b","category":13,"variation_group":null,"created":"2025-01-24T18:55:07.517Z","last_update":"2025-01-24T18:55:07.517Z","muscles":[2],"muscles_secondary":[1,4,6,5],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2406,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"M9","license_author_url":"","license_derivative_source_url":"","description":"<ul>\n<li>Sit on a bench with 45° incline</li>\n<li>Hold dumbbells overhead</li>\n<li>Move dumbbells down as if doing overhead press</li>\n<li>Rotate dumbbells palms facing up and extend your arms in front of your body</li>\n<li>Move hands together until dumbbells meet, keep arms extended</li>\n<li>Reverse the motion until dumbbells are overhead again</li>\n<li>This is one repetition</li>\n</ul>\n","description_source":"* Sit on a bench with 45° incline\n* Hold dumbbells overhead\n* Move dumbbells down as if doing overhead press\n* Rotate dumbbells palms facing up and extend your arms in front of your body\n* Move hands together until dumbbells meet, keep arms extended\n* Reverse the motion until dumbbells are overhead again\n* This is one repetition","name":"Kreis Press DB","created":"2025-01-24T18:55:07.766Z","last_update":"2026-04-13T18:58:26.739Z","language":2,"uuid":"341a4fe2-61ea-4c95-81ca-57cb992545e4","exercise":1442}}],"aliases":[],"comments":[]}'),
('wger', '1443', 'dumbbell-shoulder-raise-side-and-front', 'https://wger.de/en/exercise/1443/view', 'CC-BY-SA-4.0', 'M9', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1443,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"M9","license_author_url":"","license_derivative_source_url":"","uuid":"c146fa3c-35a4-4e6e-9000-e12a9ee19cbd","category":13,"variation_group":null,"created":"2025-01-24T19:03:16.902Z","last_update":"2025-01-24T19:03:16.902Z","muscles":[2],"muscles_secondary":[],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2407,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"M9","license_author_url":"","license_derivative_source_url":"","description":"<ul>\n<li>Stand while holding dumbbells beside body</li>\n<li>Keep arms almost fully extended</li>\n<li>Without momentum raise dumbbells to the side of your body until shoulder height, palms facing down</li>\n<li>Lower dumbbells beside body, palms facing inwards</li>\n<li>Immediately raise dumbbells in front of your body until shoulder height, palms facing down</li>\n<li>Down again</li>\n<li>This is one repetition</li>\n</ul>\n","description_source":"* Stand while holding dumbbells beside body\n* Keep arms almost fully extended\n* Without momentum raise dumbbells to the side of your body until shoulder height, palms facing down\n* Lower dumbbells beside body, palms facing inwards\n* Immediately raise dumbbells in front of your body until shoulder height, palms facing down\n* Down again\n* This is one repetition","name":"Shoulder Raise Side and Front DB","created":"2025-01-24T19:03:17.006Z","last_update":"2026-04-13T18:58:27.351Z","language":2,"uuid":"bb737264-6df5-4b1a-97d0-82e807350965","exercise":1443}}],"aliases":[],"comments":[]}'),
('wger', '1444', 'dumbbell-incline-chest-press', 'https://wger.de/en/exercise/1444/view', 'CC-BY-SA-4.0', 'M9', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1444,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"M9","license_author_url":"","license_derivative_source_url":"","uuid":"e5e17c42-3c34-410b-84ab-81fde378778f","category":11,"variation_group":null,"created":"2025-01-24T19:08:21.242Z","last_update":"2025-01-24T19:08:21.242Z","muscles":[4],"muscles_secondary":[5],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2408,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"M9","license_author_url":"","license_derivative_source_url":"","description":"<ul>\n<li>Bench 45° incline</li>\n<li>Hold dumbbells parallel on your chest</li>\n<li>Press up until arms extended</li>\n</ul>\n","description_source":"* Bench 45° incline\n* Hold dumbbells parallel on your chest\n* Press up until arms extended","name":"Incline Chest Press DB","created":"2025-01-24T19:08:21.398Z","last_update":"2026-04-13T18:58:26.652Z","language":2,"uuid":"83c07e0d-4003-454f-bbe8-f6bedd420918","exercise":1444}}],"aliases":[],"comments":[]}'),
('wger', '1445', 'barbell-jerk-ol', 'https://wger.de/en/exercise/1445/view', 'CC-BY-SA-4.0', 'M9', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1445,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"M9","license_author_url":"","license_derivative_source_url":"","uuid":"85c28424-ab47-40d4-9a27-e1b9bfb01e7c","category":13,"variation_group":null,"created":"2025-01-24T19:19:14.749Z","last_update":"2025-01-24T19:19:14.749Z","muscles":[2],"muscles_secondary":[8,10,5],"equipment":[1]}},"translations":[{"model":"exercises.translation","pk":2409,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"M9","license_author_url":"","license_derivative_source_url":"","description":"<p>Olympic lift jerk</p>\n<ul>\n<li>Hold bar in front on shoulders like push press</li>\n<li>Bend and extend knees pushing bar up while diving under the bar</li>\n<li>Catch bar overhead with straight arms using lunge</li>\n<li>Move feet parallel while holding bar in lockout</li>\n</ul>\n","description_source":"Olympic lift jerk\n\n* Hold bar in front on shoulders like push press\n* Bend and extend knees pushing bar up while diving under the bar\n* Catch bar overhead with straight arms using lunge\n* Move feet parallel while holding bar in lockout","name":"Jerk OL","created":"2025-01-24T19:19:14.889Z","last_update":"2026-04-13T18:58:26.689Z","language":2,"uuid":"eba91172-05e6-456d-a2b5-ffa52cab1d04","exercise":1445}}],"aliases":[],"comments":[]}'),
('wger', '1446', 'barbell-clean-and-jerk-ol', 'https://wger.de/en/exercise/1446/view', 'CC-BY-SA-4.0', 'M9', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1446,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"M9","license_author_url":"","license_derivative_source_url":"","uuid":"8c509754-c86f-4c1b-bfa9-29c906ffc409","category":13,"variation_group":null,"created":"2025-01-24T19:22:19.718Z","last_update":"2025-01-24T19:22:19.718Z","muscles":[2,11,8,10],"muscles_secondary":[12,6,9,5],"equipment":[1]}},"translations":[{"model":"exercises.translation","pk":2410,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"M9","license_author_url":"","license_derivative_source_url":"","description":"<p>Olympic lift clean and jerk.\nCombination of clean and jerk in one motion.</p>\n","description_source":"Olympic lift clean and jerk.\nCombination of clean and jerk in one motion.","name":"Clean and Jerk OL","created":"2025-01-24T19:22:20.587Z","last_update":"2026-04-13T18:58:26.213Z","language":2,"uuid":"afd1194b-dee0-4add-8225-2690bc28879e","exercise":1446}}],"aliases":[],"comments":[]}'),
('wger', '1447', 'barbell-snatch-ol', 'https://wger.de/en/exercise/1447/view', 'CC-BY-SA-4.0', 'M9', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1447,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"M9","license_author_url":"","license_derivative_source_url":"","uuid":"127033e0-46c5-44a6-825b-fbecfe60ed9a","category":12,"variation_group":null,"created":"2025-01-24T19:30:57.988Z","last_update":"2025-01-24T19:30:57.988Z","muscles":[2,11,8,10],"muscles_secondary":[12],"equipment":[1]}},"translations":[{"model":"exercises.translation","pk":2411,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"M9","license_author_url":"","license_derivative_source_url":"","description":"<p>Olympic lift snatch</p>\n<ul>\n<li>Pull barbell from ground to overhead lockout using a wide grip and overhead squat.</li>\n<li>Move bar slowly until cleared knees then explosively extend hips, pull bar up and dive under the bar</li>\n<li>Catch bar overhead with straight arms</li>\n<li>Push head forward during lockout</li>\n</ul>\n","description_source":"Olympic lift snatch\n\n* Pull barbell from ground to overhead lockout using a wide grip and overhead squat.\n* Move bar slowly until cleared knees then explosively extend hips, pull bar up and dive under the bar\n* Catch bar overhead with straight arms\n* Push head forward during lockout","name":"Snatch OL","created":"2025-01-24T19:30:58.747Z","last_update":"2026-04-13T18:58:27.439Z","language":2,"uuid":"3934cdf7-154c-4676-9951-f719f7dd03f1","exercise":1447}}],"aliases":[],"comments":[]}'),
('wger', '1448', 'dumbbell-seated-w-curl', 'https://wger.de/en/exercise/1448/view', 'CC-BY-SA-4.0', 'M9', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1448,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"M9","license_author_url":"","license_derivative_source_url":"","uuid":"ecc46519-94b8-4ecc-b5b8-973e753e98a6","category":8,"variation_group":null,"created":"2025-01-24T19:57:02.236Z","last_update":"2025-01-24T19:57:02.236Z","muscles":[1,13],"muscles_secondary":[],"equipment":[8,3]}},"translations":[{"model":"exercises.translation","pk":2412,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"M9","license_author_url":"","license_derivative_source_url":"","description":"<ul>\n<li>Sit on bench with 60° incline</li>\n<li>Hold dumbbells beside body near the ground, palms facing outwards, arms fully extended</li>\n<li>Move dumbbells up using only biceps and without momentum</li>\n</ul>\n","description_source":"* Sit on bench with 60° incline\n* Hold dumbbells beside body near the ground, palms facing outwards, arms fully extended\n* Move dumbbells up using only biceps and without momentum","name":"Seated W Curl","created":"2025-01-24T19:57:02.407Z","last_update":"2026-04-13T18:58:27.291Z","language":2,"uuid":"2734cc5a-87e6-45fc-adcd-4004b5987d4f","exercise":1448}},{"model":"exercises.translation","pk":2624,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"admin","license_author_url":"","license_derivative_source_url":"","description":"<p>Sentado en un banco con el respaldo inclinado en un ángulo de 40 a 60 grados. Deja que tus brazos cuelguen hacia el suelo. Sujeta una mancuerna en cada mano en supinación.</p>\n","description_source":"Sentado en un banco con el respaldo inclinado en un ángulo de 40 a 60 grados. Deja que tus brazos cuelguen hacia el suelo. Sujeta una mancuerna en cada mano en supinación.","name":"Curl inclinado con mancuernas","created":"2025-09-09T15:55:48.621Z","last_update":"2026-04-13T18:58:26.348Z","language":4,"uuid":"916f9246-4f9b-4550-a5cb-4a6a2acf2fcd","exercise":1448}},{"model":"exercises.translation","pk":2762,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"AlucardEvil40","license_author_url":"","license_derivative_source_url":"","description":"<p><strong>Asseyez-vous sur un banc incliné à 60∘.</strong>\n<strong>Tenez les haltères le long du corps près du sol, paumes vers l''extérieur, bras complètement étendus.</strong>\n<strong>Soulevez les haltères en utilisant uniquement les biceps et sans élan (sans donner d''à-coups).</strong></p>\n","description_source":"**Asseyez-vous sur un banc incliné à 60∘.**\n**Tenez les haltères le long du corps près du sol, paumes vers l''extérieur, bras complètement étendus.**\n**Soulevez les haltères en utilisant uniquement les biceps et sans élan (sans donner d''à-coups).**","name":"Curl incliné avec haltères","created":"2025-09-27T08:55:10.701Z","last_update":"2026-04-13T18:58:26.352Z","language":12,"uuid":"667bd651-03e3-4f38-b7bb-cb5fe7993c57","exercise":1448}}],"aliases":[],"comments":[]}'),
('wger', '1449', 'climbmill', 'https://wger.de/en/exercise/1449/view', 'CC-BY-SA-4.0', 'hpmbala@gmail.com', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1449,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"hpmbala@gmail.com","license_author_url":"","license_derivative_source_url":"","uuid":"2536b8cd-a287-48ee-b8da-58d8bd595f43","category":15,"variation_group":null,"created":"2025-01-31T16:32:43.821Z","last_update":"2025-01-31T16:32:43.821Z","muscles":[10],"muscles_secondary":[11,8],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2413,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"hpmbala@gmail.com","license_author_url":"","license_derivative_source_url":"","description":"<p>The ClimbMill, also known as a stair climber, is a cardio-focused machine that simulates climbing stairs. It provides an effective way to improve endurance while strengthening the lower body. To use the machine, step onto the moving stairs, maintain an upright posture, and use the handrails for balance if needed. Adjust the speed and intensity to match your fitness level. This exercise helps improve cardiovascular health, burns calories, and enhances lower body muscle endurance.</p>\n","description_source":"The ClimbMill, also known as a stair climber, is a cardio-focused machine that simulates climbing stairs. It provides an effective way to improve endurance while strengthening the lower body. To use the machine, step onto the moving stairs, maintain an upright posture, and use the handrails for balance if needed. Adjust the speed and intensity to match your fitness level. This exercise helps improve cardiovascular health, burns calories, and enhances lower body muscle endurance.","name":"ClimbMill","created":"2025-01-31T16:32:44.139Z","last_update":"2026-04-13T18:58:26.214Z","language":2,"uuid":"ec599eb8-bb69-4f1d-bc4e-d14ad7527159","exercise":1449}},{"model":"exercises.translation","pk":2414,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"hpmbala@gmail.com","license_author_url":"","license_derivative_source_url":"","description":"<p>La ClimbMill, también conocida como escaladora o máquina de subir escaleras, es una máquina de cardio que simula la acción de subir escaleras. Es una excelente forma de mejorar la resistencia y fortalecer la parte inferior del cuerpo. Para usarla, sube a los escalones en movimiento, mantén una postura erguida y usa las barras de apoyo solo si es necesario. Ajusta la velocidad e intensidad según tu nivel de condición física. Este ejercicio mejora la salud cardiovascular, quema calorías y aumenta la resistencia muscular.</p>\n","description_source":"La ClimbMill, también conocida como escaladora o máquina de subir escaleras, es una máquina de cardio que simula la acción de subir escaleras. Es una excelente forma de mejorar la resistencia y fortalecer la parte inferior del cuerpo. Para usarla, sube a los escalones en movimiento, mantén una postura erguida y usa las barras de apoyo solo si es necesario. Ajusta la velocidad e intensidad según tu nivel de condición física. Este ejercicio mejora la salud cardiovascular, quema calorías y aumenta la resistencia muscular.","name":"Escaladora","created":"2025-01-31T16:32:44.364Z","last_update":"2026-04-13T18:58:26.491Z","language":4,"uuid":"e2be7601-7174-48f8-b6bb-3eeaa0cd69e8","exercise":1449}}],"aliases":[],"comments":[]}'),
('wger', '1450', 'cobra-stretch', 'https://wger.de/en/exercise/1450/view', 'CC-BY-SA-4.0', 'hpmbala@gmail.com', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1450,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"hpmbala@gmail.com","license_author_url":"","license_derivative_source_url":"","uuid":"d8d1b919-94e1-4e91-b37e-29bb8a479740","category":12,"variation_group":null,"created":"2025-01-31T16:39:48.657Z","last_update":"2025-01-31T16:39:48.657Z","muscles":[6],"muscles_secondary":[4],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2415,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"hpmbala@gmail.com","license_author_url":"","license_derivative_source_url":"","description":"<p>The Cobra Stretch is a back extension exercise that helps improve spinal flexibility and relieve lower back tension. To perform, lie face down on the floor with your hands placed under your shoulders. Press your palms into the floor and lift your chest while keeping your hips on the ground. Keep your elbows slightly bent and your shoulders relaxed. Hold the stretch for a few seconds, then slowly lower yourself back down. This exercise is beneficial for improving posture and reducing lower back stiffness.</p>\n","description_source":"The Cobra Stretch is a back extension exercise that helps improve spinal flexibility and relieve lower back tension. To perform, lie face down on the floor with your hands placed under your shoulders. Press your palms into the floor and lift your chest while keeping your hips on the ground. Keep your elbows slightly bent and your shoulders relaxed. Hold the stretch for a few seconds, then slowly lower yourself back down. This exercise is beneficial for improving posture and reducing lower back stiffness.","name":"Cobra Stretch","created":"2025-01-31T16:39:48.892Z","last_update":"2026-04-13T18:58:26.219Z","language":2,"uuid":"6a08c76d-0b46-4bb5-9d12-1996727c2a68","exercise":1450}},{"model":"exercises.translation","pk":2416,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"hpmbala@gmail.com","license_author_url":"","license_derivative_source_url":"","description":"<p>El estiramiento de Cobra es un ejercicio de extensión de espalda que ayuda a mejorar la flexibilidad de la columna y aliviar la tensión en la zona lumbar. Para realizarlo, acuéstate boca abajo con las manos apoyadas debajo de los hombros. Presiona las palmas contra el suelo y levanta el pecho mientras mantienes las caderas en el suelo. Mantén los codos ligeramente flexionados y los hombros relajados. Sostén la posición por unos segundos y luego baja lentamente. Este ejercicio es ideal para mejorar la postura y reducir la rigidez en la parte baja de la espalda.</p>\n","description_source":"El estiramiento de Cobra es un ejercicio de extensión de espalda que ayuda a mejorar la flexibilidad de la columna y aliviar la tensión en la zona lumbar. Para realizarlo, acuéstate boca abajo con las manos apoyadas debajo de los hombros. Presiona las palmas contra el suelo y levanta el pecho mientras mantienes las caderas en el suelo. Mantén los codos ligeramente flexionados y los hombros relajados. Sostén la posición por unos segundos y luego baja lentamente. Este ejercicio es ideal para mejorar la postura y reducir la rigidez en la parte baja de la espalda.","name":"Postura de la Cobra (en Yoga)","created":"2025-01-31T16:39:49.097Z","last_update":"2026-04-13T18:58:26.988Z","language":4,"uuid":"526c3aab-5b98-4b4c-9be5-795be473f066","exercise":1450}}],"aliases":[],"comments":[]}'),
('wger', '1451', 'torso-rotation-stretch', 'https://wger.de/en/exercise/1451/view', 'CC-BY-SA-4.0', 'hpmbala@gmail.com', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1451,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"hpmbala@gmail.com","license_author_url":"","license_derivative_source_url":"","uuid":"1e9b886f-0dbe-4434-829e-7159bcc40692","category":11,"variation_group":null,"created":"2025-01-31T16:45:06.380Z","last_update":"2025-01-31T16:45:06.380Z","muscles":[14],"muscles_secondary":[4],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2417,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"hpmbala@gmail.com","license_author_url":"","license_derivative_source_url":"","description":"<p>The torso rotation stretch helps improve spinal mobility and relieves tension in the lower back and obliques. It can be performed standing or seated.</p>\n<ol>\n<li><strong>Standing Variation</strong>: Stand upright with your feet shoulder-width apart. Place your hands on your hips or extend your arms in front of you. Slowly rotate your torso to one side, keeping your hips stable. Hold for a few seconds, then rotate to the opposite side.</li>\n<li><strong>Seated Variation</strong>: Sit on a chair with your feet flat on the floor. Place one hand on the outside of your opposite thigh and gently twist your torso toward that side. Hold the stretch before switching sides.</li>\n</ol>\n","description_source":"The torso rotation stretch helps improve spinal mobility and relieves tension in the lower back and obliques. It can be performed standing or seated.\n\n1. **Standing Variation**: Stand upright with your feet shoulder-width apart. Place your hands on your hips or extend your arms in front of you. Slowly rotate your torso to one side, keeping your hips stable. Hold for a few seconds, then rotate to the opposite side.\n2. **Seated Variation**: Sit on a chair with your feet flat on the floor. Place one hand on the outside of your opposite thigh and gently twist your torso toward that side. Hold the stretch before switching sides.","name":"Torso rotation stretch","created":"2025-01-31T16:45:06.615Z","last_update":"2026-04-13T18:58:27.666Z","language":2,"uuid":"931685ae-155c-41ba-84dd-9d1ad99ba1ea","exercise":1451}},{"model":"exercises.translation","pk":2418,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"hpmbala@gmail.com","license_author_url":"","license_derivative_source_url":"","description":"<p>El estiramiento de rotación del torso mejora la movilidad de la columna y alivia la tensión en la espalda baja y los oblicuos. Puede realizarse de pie o sentado.</p>\n<ol>\n<li><strong>Variante de pie</strong>: Párate derecho con los pies a la altura de los hombros. Coloca las manos en las caderas o extiende los brazos al frente. Gira lentamente el torso hacia un lado, manteniendo las caderas estables. Mantén la posición unos segundos y luego gira hacia el otro lado.</li>\n<li><strong>Variante sentada</strong>: Siéntate en una silla con los pies planos en el suelo. Coloca una mano en el exterior del muslo contrario y gira suavemente el torso hacia ese lado. Mantén el estiramiento antes de cambiar de lado.</li>\n</ol>\n","description_source":"El estiramiento de rotación del torso mejora la movilidad de la columna y alivia la tensión en la espalda baja y los oblicuos. Puede realizarse de pie o sentado.\n\n1. **Variante de pie**: Párate derecho con los pies a la altura de los hombros. Coloca las manos en las caderas o extiende los brazos al frente. Gira lentamente el torso hacia un lado, manteniendo las caderas estables. Mantén la posición unos segundos y luego gira hacia el otro lado.\n2. **Variante sentada**: Siéntate en una silla con los pies planos en el suelo. Coloca una mano en el exterior del muslo contrario y gira suavemente el torso hacia ese lado. Mantén el estiramiento antes de cambiar de lado.","name":"Estiramiento de rotación del torso","created":"2025-01-31T16:45:06.820Z","last_update":"2026-04-13T18:58:26.502Z","language":4,"uuid":"b8722192-bfca-4bc6-ab07-23e52af4484a","exercise":1451}}],"aliases":[],"comments":[]}'),
('wger', '1452', 'knee-to-chest-stretch', 'https://wger.de/en/exercise/1452/view', 'CC-BY-SA-4.0', 'hpmbala@gmail.com', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1452,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"hpmbala@gmail.com","license_author_url":"","license_derivative_source_url":"","uuid":"492e90a5-1ecb-4a06-8e9d-26a00042560e","category":9,"variation_group":null,"created":"2025-01-31T16:48:24.992Z","last_update":"2025-01-31T16:48:24.992Z","muscles":[8],"muscles_secondary":[11],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2419,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"hpmbala@gmail.com","license_author_url":"","license_derivative_source_url":"","description":"<p>The knee to chest stretch is a simple yet effective exercise for relieving lower back tension and improving hip mobility. To perform, lie flat on your back with your legs extended. Bring one knee toward your chest, wrapping your hands around your shin or behind your thigh. Gently pull the knee closer to your chest while keeping the other leg straight on the floor. Hold the stretch for 15–30 seconds, then switch sides. For a deeper stretch, both knees can be pulled toward the chest simultaneously.</p>\n","description_source":"The knee to chest stretch is a simple yet effective exercise for relieving lower back tension and improving hip mobility. To perform, lie flat on your back with your legs extended. Bring one knee toward your chest, wrapping your hands around your shin or behind your thigh. Gently pull the knee closer to your chest while keeping the other leg straight on the floor. Hold the stretch for 15–30 seconds, then switch sides. For a deeper stretch, both knees can be pulled toward the chest simultaneously.","name":"Knee to Chest Stretch","created":"2025-01-31T16:48:25.230Z","last_update":"2026-04-13T18:58:26.724Z","language":2,"uuid":"a9d69acc-84e5-4954-92a2-999d3822e325","exercise":1452}},{"model":"exercises.translation","pk":2420,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"hpmbala@gmail.com","license_author_url":"","license_derivative_source_url":"","description":"<p>El estiramiento de rodilla al pecho es un ejercicio simple pero efectivo para aliviar la tensión en la zona lumbar y mejorar la movilidad de la cadera. Para realizarlo, acuéstate de espaldas con las piernas extendidas. Lleva una rodilla hacia el pecho y abraza la pierna con ambas manos, sujetando la espinilla o la parte posterior del muslo. Tira suavemente de la rodilla hacia el pecho mientras mantienes la otra pierna estirada en el suelo. Mantén el estiramiento durante 15–30 segundos y luego cambia de lado. Para un estiramiento más profundo, puedes llevar ambas rodillas al pecho al mismo tiempo.</p>\n","description_source":"El estiramiento de rodilla al pecho es un ejercicio simple pero efectivo para aliviar la tensión en la zona lumbar y mejorar la movilidad de la cadera. Para realizarlo, acuéstate de espaldas con las piernas extendidas. Lleva una rodilla hacia el pecho y abraza la pierna con ambas manos, sujetando la espinilla o la parte posterior del muslo. Tira suavemente de la rodilla hacia el pecho mientras mantienes la otra pierna estirada en el suelo. Mantén el estiramiento durante 15–30 segundos y luego cambia de lado. Para un estiramiento más profundo, puedes llevar ambas rodillas al pecho al mismo tiempo.","name":"Estiramiento de rodilla al pecho","created":"2025-01-31T16:48:25.441Z","last_update":"2026-04-13T18:58:26.501Z","language":4,"uuid":"1b8eb388-65ef-434c-a631-02851a8ada44","exercise":1452}}],"aliases":[],"comments":[]}'),
('wger', '1455', 'towel-superman', 'https://wger.de/en/exercise/1455/view', 'CC-BY-SA-4.0', 'Yderkone', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1455,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Yderkone","license_author_url":"","license_derivative_source_url":"","uuid":"f44cf553-067e-4f3a-b35b-e16549c1d055","category":12,"variation_group":null,"created":"2025-02-09T20:41:27.305Z","last_update":"2025-02-09T20:41:27.305Z","muscles":[12],"muscles_secondary":[2],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2421,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Yderkone","license_author_url":"","license_derivative_source_url":"","description":"<p>In this exercise, you lie flat on your stomach, hold a\ntowel with your arms extended in front of you, and pull it apart to\ncreate tension. Then, you move it forward and back under your stomach.\nThis exercise targets the back and shoulder muscles as well as core\nstability.</p>\n","description_source":"In this exercise, you lie flat on your stomach, hold a\ntowel with your arms extended in front of you, and pull it apart to\ncreate tension. Then, you move it forward and back under your stomach.\nThis exercise targets the back and shoulder muscles as well as core\nstability.","name":"Towel Superman","created":"2025-02-09T20:41:27.442Z","last_update":"2026-04-13T18:58:27.671Z","language":2,"uuid":"379b27db-5ded-48dd-827d-02d117e81fb9","exercise":1455}}],"aliases":[],"comments":[]}'),
('wger', '1457', 'cable-press-around', 'https://wger.de/en/exercise/1457/view', 'CC-BY-SA-4.0', 'Expenses7000', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1457,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Expenses7000","license_author_url":"","license_derivative_source_url":"","uuid":"70479b75-0df4-4ac2-a324-4a44b148304c","category":11,"variation_group":null,"created":"2025-02-14T00:07:16.340Z","last_update":"2025-02-14T00:07:16.340Z","muscles":[2,4,5],"muscles_secondary":[1,3],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2422,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Expenses7000","license_author_url":"","license_derivative_source_url":"","description":"<p>Set the cable pulley at chest height and attach a D-handle bar. Grab\nthe handle with a neutral grip and hold it next to your chest with your\nelbow fully flexed and tight to your side. Turn away from the pulley so\nyour torso is at 45 degrees.</p>\n<p>Hold the other side of the functional trainer with your corresponding hand. Assume a staggered stance for better balance.</p>\n<p>While keeping your chest proud, extend your elbow at 45 degrees\nacross your midline while keeping your arm parallel to the floor. Stop\nshy of lockout and contract your chest at the top of the range of motion\n(ROM).</p>\n","description_source":"Set the cable pulley at chest height and attach a D-handle bar. Grab\nthe handle with a neutral grip and hold it next to your chest with your\nelbow fully flexed and tight to your side. Turn away from the pulley so\nyour torso is at 45 degrees.\n\nHold the other side of the functional trainer with your corresponding hand. Assume a staggered stance for better balance.\n\nWhile keeping your chest proud, extend your elbow at 45 degrees\nacross your midline while keeping your arm parallel to the floor. Stop\nshy of lockout and contract your chest at the top of the range of motion\n(ROM).","name":"Cable Press Around","created":"2025-02-14T00:07:16.548Z","last_update":"2026-04-13T18:58:26.180Z","language":2,"uuid":"e4bfc654-98ad-4961-98bd-f41466a7111b","exercise":1457}}],"aliases":[],"comments":[]}'),
('wger', '1458', 'cable-cross-body-y-raise', 'https://wger.de/en/exercise/1458/view', 'CC-BY-SA-4.0', 'Expenses7000', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1458,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Expenses7000","license_author_url":"","license_derivative_source_url":"","uuid":"37314b67-1aad-4405-aa88-70846d5f035d","category":12,"variation_group":null,"created":"2025-02-14T12:38:16.241Z","last_update":"2025-02-14T12:38:16.241Z","muscles":[2,12,9],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2423,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Expenses7000","license_author_url":"","license_derivative_source_url":"","description":"<p>Attach a D-Bar to the cable machine. Perform a motion akin to drawing a sword from across your body.</p>\n","description_source":"Attach a D-Bar to the cable machine. Perform a motion akin to drawing a sword from across your body.","name":"Cross-Body Cable Y-Raise","created":"2025-02-14T12:38:16.372Z","last_update":"2026-04-13T18:58:26.239Z","language":2,"uuid":"49d9db94-389c-4b90-8b03-03c980e25975","exercise":1458}}],"aliases":[],"comments":[]}'),
('wger', '1461', 'dumbbell-no-leg-drive-chest-press', 'https://wger.de/en/exercise/1461/view', 'CC-BY-SA-4.0', 'Expenses7000', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1461,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Expenses7000","license_author_url":"","license_derivative_source_url":"","uuid":"10b0684c-1c48-4be6-913e-19bf1419107b","category":11,"variation_group":null,"created":"2025-02-22T20:52:29.021Z","last_update":"2025-02-22T20:52:29.021Z","muscles":[4],"muscles_secondary":[2,5],"equipment":[8,3]}},"translations":[{"model":"exercises.translation","pk":2424,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Expenses7000","license_author_url":"","license_derivative_source_url":"","description":"<p>Set up for a normal Dumbbell chest press but lift your leg ups straight or put them on another bench to remove the leg drive.</p>\n","description_source":"Set up for a normal Dumbbell chest press but lift your leg ups straight or put them on another bench to remove the leg drive.","name":"No Leg Drive Dumbbell Chest Press","created":"2025-02-22T20:52:30.309Z","last_update":"2026-04-13T18:58:26.873Z","language":2,"uuid":"5dd4e82a-df0c-430a-b3ee-5fa1c8478289","exercise":1461}}],"aliases":[],"comments":[]}'),
('wger', '1462', 'punches', 'https://wger.de/en/exercise/1462/view', 'CC-BY-SA-4.0', 'lh1701', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1462,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"lh1701","license_author_url":"","license_derivative_source_url":"","uuid":"adf81065-407c-4dd7-8ec5-920cc5944d58","category":8,"variation_group":null,"created":"2025-02-23T18:47:15.703Z","last_update":"2025-02-23T18:47:15.703Z","muscles":[2,5],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2425,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"lh1701","license_author_url":"","license_derivative_source_url":"","description":"<p>stand stable and throw normal straight punches</p>\n","description_source":"stand stable and throw normal straight punches","name":"punches","created":"2025-02-23T18:47:15.953Z","last_update":"2026-04-13T18:58:27.961Z","language":2,"uuid":"d5170a32-e8d3-409e-be99-a253b81a7301","exercise":1462}}],"aliases":[],"comments":[]}'),
('wger', '1463', 'dumbbell-underhand-dead-row', 'https://wger.de/en/exercise/1463/view', 'CC-BY-SA-4.0', 'Moffi', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1463,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Moffi","license_author_url":"","license_derivative_source_url":"","uuid":"1dca10f9-a976-4a09-ab85-b95fafaa1a28","category":8,"variation_group":null,"created":"2025-02-24T14:42:11.310Z","last_update":"2025-02-24T14:42:11.310Z","muscles":[1],"muscles_secondary":[12],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2426,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Moffi","license_author_url":"","license_derivative_source_url":"","description":"<p>The Dumbbell Underhand Dead Row will involve the back, which means you can try a bit heavier weight. The catch is that you need to be able to control the weight for all the reps.</p>\n<ol>\n<li>Start by holding a pair of dumbbells with your feet shoulder-wide apart and your knees slightly bent.</li>\n<li>Hinge at your hips to lower your torse forward until it''s almost parallel to the floor, keeping your back flat and maintaining a slight bend in your knees.</li>\n<li>Exhale as you row the dumbbells to your sides up to chest height, leading with your elbows until your upper arms are just past parallel to the floor and the dumbbells are at ribcage level.</li>\n<li>Slowly lower to the starting position and repeat. Keep your back flat all the time.</li>\n</ol>\n","description_source":"The Dumbbell Underhand Dead Row will involve the back, which means you can try a bit heavier weight. The catch is that you need to be able to control the weight for all the reps.\n\n1. Start by holding a pair of dumbbells with your feet shoulder-wide apart and your knees slightly bent.\n2. Hinge at your hips to lower your torse forward until it''s almost parallel to the floor, keeping your back flat and maintaining a slight bend in your knees.\n3. Exhale as you row the dumbbells to your sides up to chest height, leading with your elbows until your upper arms are just past parallel to the floor and the dumbbells are at ribcage level.\n4. Slowly lower to the starting position and repeat. Keep your back flat all the time.","name":"Dumbbell Underhand Dead Row","created":"2025-02-24T14:42:11.449Z","last_update":"2026-04-13T18:58:26.444Z","language":2,"uuid":"1f968340-2619-4cd9-b639-4b9d1a0cd3a1","exercise":1463}}],"aliases":[],"comments":[]}'),
('wger', '1464', 'pause-hack-squat', 'https://wger.de/en/exercise/1464/view', 'CC-BY-SA-4.0', 'Expenses7000', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1464,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Expenses7000","license_author_url":"","license_derivative_source_url":"","uuid":"1b329beb-fcda-4471-ba70-eea62da410dd","category":9,"variation_group":null,"created":"2025-02-24T14:53:10.523Z","last_update":"2025-02-24T14:53:10.523Z","muscles":[10],"muscles_secondary":[11,7,8],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2427,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Expenses7000","license_author_url":"","license_derivative_source_url":"","description":"<p>Hack Squats but with a 1-2s pause at the bottom of the movement. This makes sure that there is no more elastic energy stored in the muscles.</p>\n","description_source":"Hack Squats but with a 1-2s pause at the bottom of the movement. This makes sure that there is no more elastic energy stored in the muscles.","name":"Pause Hack Squats","created":"2025-02-24T14:53:10.643Z","last_update":"2026-04-13T18:58:26.911Z","language":2,"uuid":"baca9bc1-85a7-4e0d-95aa-fd9c32afcad7","exercise":1464}}],"aliases":[],"comments":[]}'),
('wger', '1465', 'spider-curl', 'https://wger.de/en/exercise/1465/view', 'CC-BY-SA-4.0', 'Moffi', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1465,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Moffi","license_author_url":"","license_derivative_source_url":"","uuid":"b3049397-a1d1-4442-9113-3532bcd1f278","category":8,"variation_group":null,"created":"2025-02-24T15:00:41.070Z","last_update":"2025-02-24T15:00:41.070Z","muscles":[1],"muscles_secondary":[],"equipment":[9]}},"translations":[{"model":"exercises.translation","pk":2428,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Moffi","license_author_url":"","license_derivative_source_url":"","description":"<p>To get the most out of DB Spider Curls, you need an\nadjustable weight bench set at a 45-degree incline. This inclined position\nallows your arms to hang freely, putting them in an extended start position\nwith elbows slightly in front of your torso, which is the key to maintaining\nlow-level isometric tension throughout the movement pattern.</p>\n<ol>\n<li>Lie face-down on an adjustable\nweight bench with your chest fully supported, holding a pair of dumbbells.</li>\n<li>Keep a neutral head position\nand don’t crane your neck.</li>\n<li>Let your arms hang straight\ndown with your palms facing forward (for a standard Spider Curl) or palms\nfacing inward for a Hammer Curl exercise variation.</li>\n<li>Keep a stable foot position on\nthe floor to maintain balance and control.</li>\n<li>Start the curl motion by\nflexing your biceps muscles and lifting the pair of dumbbells or curl bar\ntoward your shoulders.</li>\n<li>Keep your elbow flexion\ncontrolled. Your arms should stay locked in position with no unnecessary\nmovement.</li>\n<li>Squeeze hard at the top for 1-2 seconds. This\nis where maximum tension hits the biceps muscle fibers.</li>\n<li>Lower the weight under control\nfor 3-4 seconds to keep muscles under tension for the entire range of\nmotion.</li>\n</ol>\n","description_source":"To get the most out of DB Spider Curls, you need an\nadjustable weight bench set at a 45-degree incline. This inclined position\nallows your arms to hang freely, putting them in an extended start position\nwith elbows slightly in front of your torso, which is the key to maintaining\nlow-level isometric tension throughout the movement pattern.\n\n1. Lie face-down on an adjustable\n   weight bench with your chest fully supported, holding a pair of dumbbells.\n2. Keep a neutral head position\n   and don’t crane your neck.\n3. Let your arms hang straight\n   down with your palms facing forward (for a standard Spider Curl) or palms\n   facing inward for a Hammer Curl exercise variation.\n4. Keep a stable foot position on\n   the floor to maintain balance and control.\n5. Start the curl motion by\n   flexing your biceps muscles and lifting the pair of dumbbells or curl bar\n   toward your shoulders.\n6. Keep your elbow flexion\n   controlled. Your arms should stay locked in position with no unnecessary\n   movement.\n7. Squeeze hard at the top for 1-2 seconds. This\n   is where maximum tension hits the biceps muscle fibers.\n8. Lower the weight under control\n   for 3-4 seconds to keep muscles under tension for the entire range of\n   motion.","name":"Spider Curl","created":"2025-02-24T15:00:41.306Z","last_update":"2026-04-13T18:58:27.458Z","language":2,"uuid":"20827414-7b00-480a-ba2a-d6b4a5d7810f","exercise":1465}},{"model":"exercises.translation","pk":2635,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"admin","license_author_url":"","license_derivative_source_url":"","description":"<ol>\n<li>Comience colocando la barra en la parte del banco en la que normalmente se sentaría. Debe asegurarse de alinear la barra correctamente para que no se caiga y esté equilibrada.</li>\n<li>Muévase a la parte delantera del banco, la parte donde generalmente se encuentran los brazos, y colóquese para recostarse en un ángulo de 45 grados con el estómago y el torso presionados contra la parte delantera del banco.</li>\n<li>Los pies, y especialmente los dedos de los pies, deben estar bien colocados en el piso. Luego coloque los brazos superiores sobre la almohadilla que se encuentra en la parte interior del banco. La almohadilla superior debe estar ajustada en las axilas.</li>\n<li>Use sus brazos para agarrar la barra con las palmas hacia arriba, con un poco de ancho de hombro o un poco más cerca. Su agarre para este ejercicio será importante. Sosteniendo las manos juntas, apuntará a la cabeza externa del bíceps, mientras que cuanto más separadas estén las manos, apuntará a la cabeza interna. Puede experimentar haciendo un conjunto de rizos con un agarre más cercano y otro conjunto con un agarre más ancho para asegurarse de golpear ambas cabezas del bíceps.</li>\n<li>Poco a poco comience a levantar la barra hacia arriba y exhale. Asegúrese de mantener la posición contratada por un segundo y luego apriete los bíceps. Al hacer esto, desea mantener la parte superior de los brazos estacionaria y rizar el peso lo más alto posible.</li>\n<li>Vuelva a colocar la barra lentamente en la posición inicial y asegúrese de respirar.</li>\n<li>Haga una breve pausa antes de repetir la cantidad recomendada de repeticiones para su set.</li>\n</ol>\n","description_source":"1. Comience colocando la barra en la parte del banco en la que normalmente se sentaría. Debe asegurarse de alinear la barra correctamente para que no se caiga y esté equilibrada.\n2. Muévase a la parte delantera del banco, la parte donde generalmente se encuentran los brazos, y colóquese para recostarse en un ángulo de 45 grados con el estómago y el torso presionados contra la parte delantera del banco.\n3. Los pies, y especialmente los dedos de los pies, deben estar bien colocados en el piso. Luego coloque los brazos superiores sobre la almohadilla que se encuentra en la parte interior del banco. La almohadilla superior debe estar ajustada en las axilas.\n4. Use sus brazos para agarrar la barra con las palmas hacia arriba, con un poco de ancho de hombro o un poco más cerca. Su agarre para este ejercicio será importante. Sosteniendo las manos juntas, apuntará a la cabeza externa del bíceps, mientras que cuanto más separadas estén las manos, apuntará a la cabeza interna. Puede experimentar haciendo un conjunto de rizos con un agarre más cercano y otro conjunto con un agarre más ancho para asegurarse de golpear ambas cabezas del bíceps.\n5. Poco a poco comience a levantar la barra hacia arriba y exhale. Asegúrese de mantener la posición contratada por un segundo y luego apriete los bíceps. Al hacer esto, desea mantener la parte superior de los brazos estacionaria y rizar el peso lo más alto posible.\n6. Vuelva a colocar la barra lentamente en la posición inicial y asegúrese de respirar.\n7. Haga una breve pausa antes de repetir la cantidad recomendada de repeticiones para su set.","name":"Curl Araña","created":"2025-09-09T17:50:58.015Z","last_update":"2026-04-13T18:58:26.259Z","language":4,"uuid":"518cb415-a2a5-423b-a9d9-7e53c0aa47cf","exercise":1465}}],"aliases":[],"comments":[{"model":"exercises.exercisecomment","pk":543,"fields":{"uuid":"bb233bcb-facd-46bf-b887-8d3221338aa8","translation":2428,"comment":"Perform 3-4 sets with 10-12 reps, maintaining strict form and avoiding any swinging or momentum."}}]}'),
('wger', '1466', 'machine-calf-raise-hack-squat', 'https://wger.de/en/exercise/1466/view', 'CC-BY-SA-4.0', 'Expenses7000', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1466,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Expenses7000","license_author_url":"","license_derivative_source_url":"","uuid":"efeccb1b-73c0-4303-8542-bb4f45ef831a","category":9,"variation_group":null,"created":"2025-02-24T21:21:59.739Z","last_update":"2025-02-24T21:21:59.739Z","muscles":[7,15],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2429,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Expenses7000","license_author_url":"","license_derivative_source_url":"","description":"<p>Ideally using a trapeze addon, Lift the weight up using your calves by getting on your toes.</p>\n","description_source":"Ideally using a trapeze addon, Lift the weight up using your calves by getting on your toes.","name":"Calf Raise using Hack Squat Machine","created":"2025-02-24T21:21:59.935Z","last_update":"2026-04-13T18:58:26.189Z","language":2,"uuid":"53f13dfe-3043-4f41-9414-3feb3a7c2e4b","exercise":1466}}],"aliases":[],"comments":[]}'),
('wger', '1467', 'barbell-incline-close-grip-bench-press', 'https://wger.de/en/exercise/1467/view', 'CC-BY-SA-4.0', 'Expenses7000', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1467,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Expenses7000","license_author_url":"","license_derivative_source_url":"","uuid":"fca05168-7212-42ec-8927-efb1e8dd0971","category":8,"variation_group":null,"created":"2025-02-24T21:28:24.243Z","last_update":"2025-02-24T21:28:24.243Z","muscles":[5],"muscles_secondary":[2,4],"equipment":[1]}},"translations":[{"model":"exercises.translation","pk":2430,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Expenses7000","license_author_url":"","license_derivative_source_url":"","description":"<p>Narrower grip than regular bench press, just outside shoulder width.</p>\n","description_source":"Narrower grip than regular bench press, just outside shoulder width.","name":"Incline Close Grip Barbell Bench Press","created":"2025-02-24T21:28:24.366Z","last_update":"2026-04-13T18:58:26.654Z","language":2,"uuid":"e556e2c8-24ef-441e-a56f-23f2195252f6","exercise":1467}}],"aliases":[],"comments":[]}'),
('wger', '1468', 'ez-bar-floor-skull-crusher', 'https://wger.de/en/exercise/1468/view', 'CC-BY-SA-4.0', 'Expenses7000', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1468,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Expenses7000","license_author_url":"","license_derivative_source_url":"","uuid":"6b68043c-a900-41f4-89fb-ea5c8193f216","category":8,"variation_group":null,"created":"2025-02-24T21:37:58.686Z","last_update":"2025-02-24T21:37:58.686Z","muscles":[5],"muscles_secondary":[],"equipment":[2]}},"translations":[{"model":"exercises.translation","pk":2431,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Expenses7000","license_author_url":"","license_derivative_source_url":"","description":"<p>Allowing you to safely load more weight than a regular skull crusher, lie on the floor and rest the weight on the floor in between each repetition.</p>\n","description_source":"Allowing you to safely load more weight than a regular skull crusher, lie on the floor and rest the weight on the floor in between each repetition.","name":"Floor Skull Crusher","created":"2025-02-24T21:37:58.808Z","last_update":"2026-04-13T18:58:26.546Z","language":2,"uuid":"2b8d530c-954f-4332-aee6-ade6a56f60ad","exercise":1468}}],"aliases":[],"comments":[]}'),
('wger', '1469', 'cable-bent-over-flye', 'https://wger.de/en/exercise/1469/view', 'CC-BY-SA-4.0', 'Expenses7000', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1469,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Expenses7000","license_author_url":"","license_derivative_source_url":"","uuid":"7ef2e00e-067c-48e0-9b42-3d622e0df8a4","category":11,"variation_group":null,"created":"2025-02-24T21:43:36.165Z","last_update":"2025-02-24T21:43:36.165Z","muscles":[4],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2432,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Expenses7000","license_author_url":"","license_derivative_source_url":"","description":"<p>Holding your upper body at an approximate 105° angle.</p>\n","description_source":"Holding your upper body at an approximate 105° angle. ","name":"Bent over Cable Flye","created":"2025-02-24T21:43:36.320Z","last_update":"2026-04-13T18:58:26.104Z","language":2,"uuid":"9bc8ce74-1e4f-4f7c-a55e-ea38bb26f84f","exercise":1469}}],"aliases":[],"comments":[]}'),
('wger', '1470', '1-arm-half-kneeling-lat-pulldown', 'https://wger.de/en/exercise/1470/view', 'CC-BY-SA-4.0', 'Expenses7000', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1470,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Expenses7000","license_author_url":"","license_derivative_source_url":"","uuid":"a8a4ea81-9531-48e1-b6dc-f7621c7b9283","category":12,"variation_group":null,"created":"2025-02-25T20:00:07.513Z","last_update":"2025-02-25T20:00:07.513Z","muscles":[12],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2433,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Expenses7000","license_author_url":"","license_derivative_source_url":"","description":"<p>Attach a D-Handle to a high pully. And use your lat muscles to pull the weight single handedly.</p>\n","description_source":"Attach a D-Handle to a high pully. And use your lat muscles to pull the weight single handedly.","name":"1-Arm Half-Kneeling Lat Pulldown","created":"2025-02-25T20:00:07.681Z","last_update":"2026-04-13T18:58:25.965Z","language":2,"uuid":"57e34f52-88eb-46ae-9bd8-4ffb7774dbb0","exercise":1470}}],"aliases":[],"comments":[]}'),
('wger', '1471', 'kroc-row', 'https://wger.de/en/exercise/1471/view', 'CC-BY-SA-4.0', 'Expenses7000', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1471,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Expenses7000","license_author_url":"","license_derivative_source_url":"","uuid":"84b38ac6-9628-4f80-8940-204047fa2544","category":12,"variation_group":null,"created":"2025-02-25T20:23:50.141Z","last_update":"2025-02-25T20:23:50.141Z","muscles":[12,9],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2434,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Expenses7000","license_author_url":"","license_derivative_source_url":"","description":"<p>Dumbbell rows with looser technique but heavier weight.</p>\n","description_source":"Dumbbell rows with looser technique but heavier weight.","name":"Kroc Row","created":"2025-02-25T20:23:51.807Z","last_update":"2026-04-13T18:58:26.741Z","language":2,"uuid":"f67b90fd-3149-40c0-8a8c-19b1fa475f35","exercise":1471}}],"aliases":[],"comments":[]}'),
('wger', '1472', 'cable-shrug-in', 'https://wger.de/en/exercise/1472/view', 'CC-BY-SA-4.0', 'Expenses7000', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1472,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Expenses7000","license_author_url":"","license_derivative_source_url":"","uuid":"05853a58-4426-450c-9b06-bfa461a767bf","category":13,"variation_group":null,"created":"2025-02-25T20:29:07.544Z","last_update":"2025-02-25T20:29:07.544Z","muscles":[9],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2435,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Expenses7000","license_author_url":"","license_derivative_source_url":"","description":"<p>Attach two D-Handles to two low cables and shrug in using your upper traps.</p>\n","description_source":"Attach two D-Handles to two low cables and shrug in using your upper traps.","name":"Cable Shrug-In","created":"2025-02-25T20:29:07.878Z","last_update":"2026-04-13T18:58:26.182Z","language":2,"uuid":"d82be0dc-f927-4f08-9117-a4c3338495ca","exercise":1472}}],"aliases":[],"comments":[]}'),
('wger', '1473', 'cable-rear-delt-fly', 'https://wger.de/en/exercise/1473/view', 'CC-BY-SA-4.0', 'Expenses7000', 'normalized', 100.0, '{"exercise":{"model":"exercises.exercise","pk":1473,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Expenses7000","license_author_url":"","license_derivative_source_url":"","uuid":"39c13706-6a8c-4ab5-b605-b9b716665a20","category":12,"variation_group":null,"created":"2025-02-25T20:40:01.409Z","last_update":"2025-02-25T20:40:01.409Z","muscles":[2],"muscles_secondary":[9],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2436,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Expenses7000","license_author_url":"","license_derivative_source_url":"","description":"<p>Attach D-Handles to two cable pulleys in the upper position. Grab the left on with your right hand and vice-versa.</p>\n","description_source":"Attach D-Handles to two cable pulleys in the upper position. Grab the left on with your right hand and vice-versa. ","name":"Reverse Cable Flye","created":"2025-02-25T20:40:03.526Z","last_update":"2026-04-13T18:58:27.147Z","language":2,"uuid":"c82967f5-7fac-43e4-b516-9db63d7fb542","exercise":1473}}],"aliases":[],"comments":[]}'),
('wger', '1474', 'w-raise', 'https://wger.de/en/exercise/1474/view', 'CC-BY-SA-4.0', 'Moffi', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1474,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Moffi","license_author_url":"","license_derivative_source_url":"","uuid":"8b494562-012e-4944-be65-9b168f0c8c41","category":10,"variation_group":null,"created":"2025-03-03T07:57:04.313Z","last_update":"2025-03-03T07:57:04.313Z","muscles":[14,6],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2437,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Moffi","license_author_url":"","license_derivative_source_url":"","description":"<p>This challenging exercise is a variation of reverse crunches that is made up of three parts in which we’re basically drawing an upside down ‘W’ with our legs.\nStart position is lying face up flat on the floor with legs extended at the low point of the outer leg of the ‘W’. Keeping a strong core and legs straight, go up, rise your hips and then slowly lower your legs down halfway. Then, lifting your legs back up to the top, rise your hips again, maintaining that straight line, use your core strength to finally come back all the way down to the other outer leg of the W. Then you reverse the ‘W’ to return to the start.</p>\n","description_source":"This challenging exercise is a variation of reverse crunches that is made up of three parts in which we’re basically drawing an upside down ‘W’ with our legs.\nStart position is lying face up flat on the floor with legs extended at the low point of the outer leg of the ‘W’. Keeping a strong core and legs straight, go up, rise your hips and then slowly lower your legs down halfway. Then, lifting your legs back up to the top, rise your hips again, maintaining that straight line, use your core strength to finally come back all the way down to the other outer leg of the W. Then you reverse the ‘W’ to return to the start.","name":"W-Raise","created":"2025-03-03T07:57:05.127Z","last_update":"2026-04-13T18:58:27.815Z","language":2,"uuid":"3da2176c-3e5d-427e-84d8-a01b623583a7","exercise":1474}}],"aliases":[],"comments":[]}'),
('wger', '1475', 'black-widow-knee-slide', 'https://wger.de/en/exercise/1475/view', 'CC-BY-SA-4.0', 'Moffi', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1475,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Moffi","license_author_url":"","license_derivative_source_url":"","uuid":"64ebb7a5-15ec-48dd-8f82-47cdb022f215","category":10,"variation_group":null,"created":"2025-03-03T08:03:22.312Z","last_update":"2025-03-03T08:03:22.312Z","muscles":[14,6],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2438,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Moffi","license_author_url":"","license_derivative_source_url":"","description":"<p>In\nthis bottom-up rotation exercise movement, you’ll cross your knee over and\ndrive it into that opposite elbow. Start in high plank position (or tabletop\nposition) with hands directly beneath your shoulders. Lift the left knee toward\nthe right arm and slide it up the forearm to get more of that posterior pelvic\ntilt and engagement of the abdominal muscles. Then do the opposite side,\nbringing your right knee toward your left hand.</p>\n","description_source":"In\nthis bottom-up rotation exercise movement, you’ll cross your knee over and\ndrive it into that opposite elbow. Start in high plank position (or tabletop\nposition) with hands directly beneath your shoulders. Lift the left knee toward\nthe right arm and slide it up the forearm to get more of that posterior pelvic\ntilt and engagement of the abdominal muscles. Then do the opposite side,\nbringing your right knee toward your left hand.","name":"Black Widow Knee Slides","created":"2025-03-03T08:03:22.565Z","last_update":"2026-04-13T18:58:26.125Z","language":2,"uuid":"633a01fd-d392-4245-821c-c69a2632b8e5","exercise":1475}}],"aliases":[],"comments":[]}'),
('wger', '1476', 'butterfly-sit-up', 'https://wger.de/en/exercise/1476/view', 'CC-BY-SA-4.0', 'Moffi', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1476,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Moffi","license_author_url":"","license_derivative_source_url":"","uuid":"1bb3bbaf-2dc2-4651-95db-71faf5304075","category":10,"variation_group":null,"created":"2025-03-03T08:08:08.014Z","last_update":"2025-03-03T08:08:08.014Z","muscles":[14,6],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2439,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Moffi","license_author_url":"","license_derivative_source_url":"","description":"<p>In\nthis midrange exercise your arm muscles provide you with a little bit of\nmomentum to help to get you off the ground. You also open them up in overhead\nposition which engages the upper back. Start\nlying with feet flat on the ground, knees at an angle, arms crossed in towards your chest. Using\nyour ab muscles, bring your upper body off the ground as you open your arms\ninto goal post position, then slowly lower yourself back down to return to\nstarting position.</p>\n","description_source":"In\nthis midrange exercise your arm muscles provide you with a little bit of\nmomentum to help to get you off the ground. You also open them up in overhead\nposition which engages the upper back. Start\nlying with feet flat on the ground, knees at an angle, arms crossed in towards your chest. Using\nyour ab muscles, bring your upper body off the ground as you open your arms\ninto goal post position, then slowly lower yourself back down to return to\nstarting position. ","name":"Butterfly Sit Up","created":"2025-03-03T08:08:08.577Z","last_update":"2026-04-13T18:58:26.165Z","language":2,"uuid":"664d9c3a-ddea-401a-8054-5ccee19a71ea","exercise":1476}}],"aliases":[],"comments":[{"model":"exercises.exercisecomment","pk":544,"fields":{"uuid":"32927c50-3ab0-4a2c-9097-e7501b62478e","translation":2439,"comment":"Be sure to pull your belly button in toward your spine throughout this crunch variation."}}]}'),
('wger', '1477', 'seated-corkscrew', 'https://wger.de/en/exercise/1477/view', 'CC-BY-SA-4.0', 'Moffi', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1477,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Moffi","license_author_url":"","license_derivative_source_url":"","uuid":"e9891a94-b1d4-47f4-a82b-c1aa82121abb","category":10,"variation_group":null,"created":"2025-03-03T08:14:49.333Z","last_update":"2025-03-03T08:14:49.333Z","muscles":[14,6],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2440,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Moffi","license_author_url":"","license_derivative_source_url":"","description":"<p>To\ndo this abs and obliques exercise, start with your hands back behind your body\nand bring your knees in and across, really trying to contract the obliques.\nThen extend your legs back out to starting position and repeat toward the\nopposite side of the abs.\nBeginners\nmight find that they can’t even get through the first 45 seconds of this\nchallenging reverse crunches variation.&nbsp; That’s ok because it gives you a\nplace to start and something to improve upon.</p>\n","description_source":"To\ndo this abs and obliques exercise, start with your hands back behind your body\nand bring your knees in and across, really trying to contract the obliques.\nThen extend your legs back out to starting position and repeat toward the\nopposite side of the abs.\nBeginners\nmight find that they can’t even get through the first 45 seconds of this\nchallenging reverse crunches variation.  That’s ok because it gives you a\nplace to start and something to improve upon.","name":"Seated Corkscrew","created":"2025-03-03T08:14:49.683Z","last_update":"2026-04-13T18:58:27.269Z","language":2,"uuid":"370e312f-ed39-4df1-a71d-71e85e2d7571","exercise":1477}}],"aliases":[],"comments":[{"model":"exercises.exercisecomment","pk":545,"fields":{"uuid":"4b54888a-03f9-415c-b300-bff0ff4d65b5","translation":2440,"comment":"Engage your core as you move upper and lower body at the same time."}},{"model":"exercises.exercisecomment","pk":546,"fields":{"uuid":"660c8945-0268-4349-a13d-3f5fb55db53d","translation":2440,"comment":"Make sure your belly button is pulled in toward the spine throughout the entire motion."}}]}'),
('wger', '1478', 'levitation-crunch', 'https://wger.de/en/exercise/1478/view', 'CC-BY-SA-4.0', 'Moffi', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1478,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Moffi","license_author_url":"","license_derivative_source_url":"","uuid":"9816dc3a-9739-4c70-bce0-4131f889e4f2","category":10,"variation_group":null,"created":"2025-03-03T08:22:31.885Z","last_update":"2025-03-03T08:22:31.885Z","muscles":[6],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2441,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Moffi","license_author_url":"","license_derivative_source_url":"","description":"<p>For\nthis top down movement, we’re trying to move the upper torso without moving the\nlower torso. Start lying on the ground with feet flat on the floor and crossed\narms above your head with hands behind head. Lift upper body up and clear your\nshoulder blades off the ground and then hold and pause at the top for a one or\ntwo count. Try to make the upper abs work and hold that contraction for 10 good\nquality reps.</p>\n","description_source":"For\nthis top down movement, we’re trying to move the upper torso without moving the\nlower torso. Start lying on the ground with feet flat on the floor and crossed\narms above your head with hands behind head. Lift upper body up and clear your\nshoulder blades off the ground and then hold and pause at the top for a one or\ntwo count. Try to make the upper abs work and hold that contraction for 10 good\nquality reps.","name":"Levitation Crunch","created":"2025-03-03T08:22:32.028Z","last_update":"2026-04-13T18:58:26.798Z","language":2,"uuid":"57174ad2-84f3-4f0a-a73e-b73b54b457dc","exercise":1478}}],"aliases":[],"comments":[{"model":"exercises.exercisecomment","pk":547,"fields":{"uuid":"e6fb7170-68c8-4568-af73-598e50921513","translation":2441,"comment":"Make sure your belly button is pulled in toward the spine throughout the entire motion."}}]}'),
('wger', '1479', 'sit-up-elbow-thrust', 'https://wger.de/en/exercise/1479/view', 'CC-BY-SA-4.0', 'Moffi; admin', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1479,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Moffi","license_author_url":"","license_derivative_source_url":"","uuid":"5af00591-2d77-4ea6-a347-825ad18beff1","category":10,"variation_group":null,"created":"2025-03-03T08:29:00.927Z","last_update":"2025-03-03T08:29:00.927Z","muscles":[14,6],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2442,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Moffi","license_author_url":"","license_derivative_source_url":"","description":"<p>This\nis a top down rotation movement, and it’s a bit more\nexplosive, too.\nLying with knees bent and feet on the floor, sit up and then drive your left elbow across your entire body toward the right, then come back\nto center and then finally lower yourself down. Then hit the other side.</p>\n","description_source":"This\nis a top down rotation movement, and it’s a bit more\nexplosive, too.\nLying with knees bent and feet on the floor, sit up and then drive your left elbow across your entire body toward the right, then come back\nto center and then finally lower yourself down. Then hit the other side.","name":"Sit Up Elbow Thrust","created":"2025-03-03T08:29:02.581Z","last_update":"2026-04-13T18:58:27.412Z","language":2,"uuid":"d9e25534-e000-497e-9240-058ec4885ea7","exercise":1479}},{"model":"exercises.translation","pk":2649,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"admin","license_author_url":"","license_derivative_source_url":"","description":"<ul>\n<li>Füße fixieren</li>\n<li>Muskulatur anspannen</li>\n<li>Kein Schwung holen</li>\n<li>Kontrollierte Bewegung</li>\n<li>Langsame Durchführung</li>\n<li>Gleichmäßig atmen</li>\n</ul>\n","description_source":"* Füße fixieren\n* Muskulatur anspannen\n* Kein Schwung holen\n* Kontrollierte Bewegung\n* Langsame Durchführung\n* Gleichmäßig atmen","name":"Sit-Ups (Ellenbogen zum Knie)","created":"2025-09-09T18:44:17.329Z","last_update":"2026-04-13T18:58:27.416Z","language":1,"uuid":"74e97ac0-e2cd-43f9-9069-915eaf9851a0","exercise":1479}}],"aliases":[],"comments":[{"model":"exercises.exercisecomment","pk":548,"fields":{"uuid":"f918c4fa-0797-48e6-ba62-9e5cd92fb613","translation":2442,"comment":"Make sure your belly button is pulled in toward the spine throughout the entire motion."}}]}'),
('wger', '1480', 'lying-triceps-extension', 'https://wger.de/en/exercise/1480/view', 'CC-BY-SA-4.0', 'Moffi', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1480,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Moffi","license_author_url":"","license_derivative_source_url":"","uuid":"8a356e9a-0058-4f60-b8d7-89147c3c371f","category":8,"variation_group":null,"created":"2025-03-03T09:42:38.173Z","last_update":"2025-03-03T09:42:38.173Z","muscles":[5],"muscles_secondary":[],"equipment":[1,3]}},"translations":[{"model":"exercises.translation","pk":2443,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Moffi","license_author_url":"","license_derivative_source_url":"","description":"<ol>\n<li>Starting position for this\npractical triceps exercise is lying on a standard bench holding a barbell or two dumbbells in both hands with an overhand grip, hands at shoulder width apart.</li>\n<li>Begin with arms over your upper\nchest and elbows bent back at about a 45-degree angle.</li>\n<li>First bend at the elbows and\nthen allow the upper arm to drop back, bringing the barbell/dumbbells behind your\nhead and down toward the floor. In terms of upper arm position, the barbell/dumbbells should never be fully above your head, but instead behind it, to\nensure that you’re targeting the triceps.</li>\n<li>Keep the shoulder blades tucked\nunder, the elbows tight in toward your head and your core active during\nthis entire movement.</li>\n</ol>\n","description_source":"1. Starting position for this\n   practical triceps exercise is lying on a standard bench holding a barbell or two dumbbells in both hands with an overhand grip, hands at shoulder width apart.\n2. Begin with arms over your upper\n   chest and elbows bent back at about a 45-degree angle.\n3. First bend at the elbows and\n   then allow the upper arm to drop back, bringing the barbell/dumbbells behind your\n   head and down toward the floor. In terms of upper arm position, the barbell/dumbbells should never be fully above your head, but instead behind it, to\n   ensure that you’re targeting the triceps.\n4. Keep the shoulder blades tucked\n   under, the elbows tight in toward your head and your core active during\n   this entire movement.","name":"Lying Triceps Extensions","created":"2025-03-03T09:42:38.314Z","last_update":"2026-04-13T18:58:26.829Z","language":2,"uuid":"f135f2dc-b50f-4470-b077-bb61a67549bf","exercise":1480}}],"aliases":[],"comments":[]}'),
('wger', '1481', 'ez-bar-drag-pushdown', 'https://wger.de/en/exercise/1481/view', 'CC-BY-SA-4.0', 'Moffi', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1481,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Moffi","license_author_url":"","license_derivative_source_url":"","uuid":"02b96dc1-d1d9-4fc7-b54c-82dda1691485","category":8,"variation_group":null,"created":"2025-03-03T09:50:08.002Z","last_update":"2025-03-03T09:50:08.002Z","muscles":[5],"muscles_secondary":[],"equipment":[2]}},"translations":[{"model":"exercises.translation","pk":2444,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Moffi","license_author_url":"","license_derivative_source_url":"","description":"<ol>\n<li>Starting\nposition for this rope pushdown is standing facing a cable machine with\nthe handles of a rope attachment in both hands and feet shoulder width\napart.</li>\n<li>Hinge\nforward slightly at the hips maintaining an upright chest and bring the\nshoulders and elbows behind the body so that when you push down on the\ncable attachments, you can get a fully contracted triceps long head.</li>\n<li>Drag\nthe cable machine rope attachment as close to the body as possible and\nstraighten your elbows until lockout.</li>\n</ol>\n","description_source":"1. Starting\n   position for this rope pushdown is standing facing a cable machine with\n   the handles of a rope attachment in both hands and feet shoulder width\n   apart.\n2. Hinge\n   forward slightly at the hips maintaining an upright chest and bring the\n   shoulders and elbows behind the body so that when you push down on the\n   cable attachments, you can get a fully contracted triceps long head.\n3. Drag\n   the cable machine rope attachment as close to the body as possible and\n   straighten your elbows until lockout.","name":"Drag Pushdown","created":"2025-03-03T09:50:08.134Z","last_update":"2026-04-13T18:58:26.404Z","language":2,"uuid":"3b453e5a-8c58-4f33-a9b8-3d7d00322464","exercise":1481}}],"aliases":[],"comments":[]}'),
('wger', '1482', 'dumbbell-cheat-curl', 'https://wger.de/en/exercise/1482/view', 'CC-BY-SA-4.0', 'Moffi', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1482,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Moffi","license_author_url":"","license_derivative_source_url":"","uuid":"31a58615-d3ae-4233-9c50-9143c899ce8c","category":8,"variation_group":null,"created":"2025-03-03T10:26:57.334Z","last_update":"2025-03-03T10:26:57.334Z","muscles":[1],"muscles_secondary":[],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2445,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Moffi","license_author_url":"","license_derivative_source_url":"","description":"<ol>\n<li>Starting position is standing\nwith feet shoulder width apart.</li>\n<li>Hands should take an underhand\nor supinated grip on the dumbbells holding them with hands shoulder\nwidth apart.</li>\n<li>Keeping elbows tucked into your\nsides throughout the entire movement, use momentum to curl the dumbbells,\nsqueezing your biceps at the top of the movement.</li>\n<li>Slowly lower to return to the\nstarting position. Keep the core tight throughout the exercise.</li>\n</ol>\n<p>Cheating\nthrough the concentric curling portion of this challenging exercise gives us a\ngreat opportunity to increase time under tension and create eccentric overload\nwith heavier weight when we lower.</p>\n","description_source":"1. Starting position is standing\n   with feet shoulder width apart.\n2. Hands should take an underhand\n   or supinated grip on the dumbbells holding them with hands shoulder\n   width apart.\n3. Keeping elbows tucked into your\n   sides throughout the entire movement, use momentum to curl the dumbbells,\n   squeezing your biceps at the top of the movement.\n4. Slowly lower to return to the\n   starting position. Keep the core tight throughout the exercise.\n\nCheating\nthrough the concentric curling portion of this challenging exercise gives us a\ngreat opportunity to increase time under tension and create eccentric overload\nwith heavier weight when we lower.","name":"Dumbbell Cheat Curl","created":"2025-03-03T10:26:57.472Z","last_update":"2026-04-13T18:58:26.413Z","language":2,"uuid":"2e726a38-9c5c-49a2-bc74-63e6e747e23e","exercise":1482}}],"aliases":[],"comments":[]}'),
('wger', '1483', 'dumbbell-bizeps-curl-trifecta', 'https://wger.de/en/exercise/1483/view', 'CC-BY-SA-4.0', 'Moffi', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1483,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Moffi","license_author_url":"","license_derivative_source_url":"","uuid":"da6ab4d8-edd2-428d-b194-fb15948d3fd5","category":8,"variation_group":null,"created":"2025-03-03T10:35:54.857Z","last_update":"2025-03-03T10:35:54.857Z","muscles":[1],"muscles_secondary":[],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2446,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Moffi","license_author_url":"","license_derivative_source_url":"","description":"<p>This exercise is a mixture of three different curls: the Supinated Cross Body Curl, the Pronated Cross Body Curl and the No Money Curl. You\nalternate between three curl variations that each accomplish different goals,\nand you’ll keep the set going beyond the usual 8-12 rep range&nbsp;which gives\nus that intensity.</p>\n<ol>\n<li>For the Supinated Cross Body\nCurl, supinate the forearm with palms facing toward the ceiling and\nforearms coming across the body. Lift the inner-facing weight of the dumbbell towards your shoulder.</li>\n<li>For the Pronated Cross Body\nCurl, pronate the forearm with palms facing toward the floor (pronated\ngrip or overhand grip) and forearms coming across the body.&nbsp;Lift the inner-facing weight of the dumbbell towards your shoulder.</li>\n<li>For the No Money Curl, you’ll\ncurl the dumbbell as you outwardly rotate the shoulder.&nbsp;Lift the inner-facing weight of the dumbbell towards your outer side of the shoulder.</li>\n</ol>\n","description_source":"This exercise is a mixture of three different curls: the Supinated Cross Body Curl, the Pronated Cross Body Curl and the No Money Curl. You\nalternate between three curl variations that each accomplish different goals,\nand you’ll keep the set going beyond the usual 8-12 rep range which gives\nus that intensity.\n\n1. For the Supinated Cross Body\n   Curl, supinate the forearm with palms facing toward the ceiling and\n   forearms coming across the body. Lift the inner-facing weight of the dumbbell towards your shoulder.\n2. For the Pronated Cross Body\n   Curl, pronate the forearm with palms facing toward the floor (pronated\n   grip or overhand grip) and forearms coming across the body. Lift the inner-facing weight of the dumbbell towards your shoulder.\n3. For the No Money Curl, you’ll\n   curl the dumbbell as you outwardly rotate the shoulder. Lift the inner-facing weight of the dumbbell towards your outer side of the shoulder.","name":"Bizeps Curls Trifecta","created":"2025-03-03T10:35:55.034Z","last_update":"2026-04-13T18:58:26.121Z","language":2,"uuid":"7c171c60-f58f-4f74-a3f4-866e82d9b01a","exercise":1483}}],"aliases":[],"comments":[]}'),
('wger', '1484', 'cable-omni-cross-over', 'https://wger.de/en/exercise/1484/view', 'CC-BY-SA-4.0', 'Moffi', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1484,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Moffi","license_author_url":"","license_derivative_source_url":"","uuid":"ac00021c-12f9-4827-8003-ea07de980b76","category":11,"variation_group":null,"created":"2025-03-03T12:35:22.700Z","last_update":"2025-03-03T12:35:22.700Z","muscles":[4],"muscles_secondary":[],"equipment":[2]}},"translations":[{"model":"exercises.translation","pk":2447,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Moffi","license_author_url":"","license_derivative_source_url":"","description":"<p>Adjust the weights based on the\nmotion. When pulling from top to bottom, increase the weight by 20% to 40%\nmore than the bottom-to-top motion. This accounts for the fact that when\noperating from top down, the upper chest muscles are naturally weaker than\nthe lower chest muscles. So, adjust your weight stack to\ncompensate.</p>\n<ol>\n<li>Position one cable at a high\nsetting and the other at the lowest level setting. Get into a staggered\nstance in between the cable towers.</li>\n<li>For the cable set low, pull it\nupward and across your body. This effectively targets the upper chest.</li>\n<li>For the cable set high, draw it\ndownward and across your body. This will primarily engage the lower chest.</li>\n</ol>\n<p>Once you’re done, swap the\npositions of the cables. Change the previously high cable to the lowest\nposition and vice versa. Repeat the exercise sequence, ensuring you’re\ntargeting both chest regions effectively.</p>\n","description_source":"Adjust the weights based on the\nmotion. When pulling from top to bottom, increase the weight by 20% to 40%\nmore than the bottom-to-top motion. This accounts for the fact that when\noperating from top down, the upper chest muscles are naturally weaker than\nthe lower chest muscles. So, adjust your weight stack to\ncompensate.\n\n1. Position one cable at a high\n   setting and the other at the lowest level setting. Get into a staggered\n   stance in between the cable towers.\n2. For the cable set low, pull it\n   upward and across your body. This effectively targets the upper chest.\n3. For the cable set high, draw it\n   downward and across your body. This will primarily engage the lower chest.\n\nOnce you’re done, swap the\npositions of the cables. Change the previously high cable to the lowest\nposition and vice versa. Repeat the exercise sequence, ensuring you’re\ntargeting both chest regions effectively.","name":"Omni Cable Cross-over","created":"2025-03-03T12:35:22.837Z","last_update":"2026-04-13T18:58:26.879Z","language":2,"uuid":"0e4911d2-548a-4d51-9432-283f7420e471","exercise":1484}}],"aliases":[],"comments":[]}'),
('wger', '1485', 'ez-bar-rocking-triceps-pushdown', 'https://wger.de/en/exercise/1485/view', 'CC-BY-SA-4.0', 'Moffi', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1485,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Moffi","license_author_url":"","license_derivative_source_url":"","uuid":"0dfe655e-ee2e-4c49-a279-c672d5591613","category":8,"variation_group":null,"created":"2025-03-03T14:03:50.858Z","last_update":"2025-03-03T14:03:50.858Z","muscles":[5],"muscles_secondary":[],"equipment":[2]}},"translations":[{"model":"exercises.translation","pk":2448,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Moffi","license_author_url":"","license_derivative_source_url":"","description":"<p>Set your feet below the rope and lean your upper body towards the rope. Set one foot back. Push down the rope and lean your entire body back onto the rear foot as you push down to get your hands behind your body. Don''t forget to bring your chest to the front during the pushdown. As you release the rope slowly, lean your body back onto the front foot.</p>\n","description_source":"Set your feet below the rope and lean your upper body towards the rope. Set one foot back. Push down the rope and lean your entire body back onto the rear foot as you push down to get your hands behind your body. Don''t forget to bring your chest to the front during the pushdown. As you release the rope slowly, lean your body back onto the front foot.","name":"Rocking Triceps Pushdown","created":"2025-03-03T14:03:51.021Z","last_update":"2026-04-13T18:58:27.166Z","language":2,"uuid":"abc6dd77-c39c-4dca-a731-0e3e540251e6","exercise":1485}}],"aliases":[],"comments":[{"model":"exercises.exercisecomment","pk":549,"fields":{"uuid":"8c03f767-cf8c-4bd2-a984-f952975ef773","translation":2448,"comment":"Don''t use your body weight to pull the rope down. Let the triceps do all the work."}},{"model":"exercises.exercisecomment","pk":550,"fields":{"uuid":"18a65984-cebc-4063-ac2d-0b0463d635d2","translation":2448,"comment":"The back&forth movement of your body is purely to keep a more perpendicular position between arm and rope."}}]}'),
('wger', '1486', 'cable-alternating-high-row', 'https://wger.de/en/exercise/1486/view', 'CC-BY-SA-4.0', 'Moffi', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1486,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Moffi","license_author_url":"","license_derivative_source_url":"","uuid":"45251627-5f89-4858-bf0c-8884a21cbb1f","category":12,"variation_group":null,"created":"2025-03-06T09:20:18.687Z","last_update":"2025-03-06T09:20:18.687Z","muscles":[12],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2449,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Moffi","license_author_url":"","license_derivative_source_url":"","description":"<ol>\n<li>Start\nby putting the attachment in a high position on the cable station and step back about 1m from the attachment. Grab\nthe cable pulley handle in your left hand at about head height with your elbow&nbsp;slightly bent. Step back with your left foot.</li>\n<li>Pull\nyour elbow joint in toward the torso twisting slightly and perform a\nsingle-arm row. Engage the lats as you twist.</li>\n<li>Return\nto the starting position with cable pulley and left foot and grab the cable pulley handle in the right\nhand. Repeat this motion on the opposite side with your right foot stepped back.</li>\n</ol>\n","description_source":"1. Start\n   by putting the attachment in a high position on the cable station and step back about 1m from the attachment. Grab\n   the cable pulley handle in your left hand at about head height with your elbow slightly bent. Step back with your left foot.\n2. Pull\n   your elbow joint in toward the torso twisting slightly and perform a\n   single-arm row. Engage the lats as you twist.\n3. Return\n   to the starting position with cable pulley and left foot and grab the cable pulley handle in the right\n   hand. Repeat this motion on the opposite side with your right foot stepped back.","name":"Alternating High Cable Row","created":"2025-03-06T09:20:18.848Z","last_update":"2026-04-13T18:58:26.024Z","language":2,"uuid":"281afbc1-381f-43e9-ba64-177375d3bbc2","exercise":1486}}],"aliases":[],"comments":[{"model":"exercises.exercisecomment","pk":551,"fields":{"uuid":"1c18ef49-14b7-4aeb-ae99-daa71ff4202d","translation":2449,"comment":"Use your core strength for stability and keep spine stable for all repetitions."}},{"model":"exercises.exercisecomment","pk":552,"fields":{"uuid":"ade27d2d-881e-4b86-ae19-fde0c6e98f84","translation":2449,"comment":"Focus on taking the lats through their entire range of motion in this cable pulley movement."}}]}'),
('wger', '1487', 'hyper-y-w-combo', 'https://wger.de/en/exercise/1487/view', 'CC-BY-SA-4.0', 'Moffi', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1487,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Moffi","license_author_url":"","license_derivative_source_url":"","uuid":"ebe7d74b-78a8-4757-9310-6fb22b23aa58","category":12,"variation_group":null,"created":"2025-03-06T09:30:01.802Z","last_update":"2025-03-06T09:30:01.802Z","muscles":[12],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2450,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Moffi","license_author_url":"","license_derivative_source_url":"","description":"<ol>\n<li>Use a glute-ham raise or a\nstability ball for this exercise and a light weight plate in each hand.</li>\n<li>Raise your torso to form a straight line with your legs and raise the\narms outward slightly beyond a 90-degree angle into a W position to hit\nthe rotator cuff muscles, and then lower back to the starting position.</li>\n<li>Then raise up again with arms\nin a Y position to activate the lower traps.</li>\n</ol>\n","description_source":"1. Use a glute-ham raise or a\n   stability ball for this exercise and a light weight plate in each hand.\n2. Raise your torso to form a straight line with your legs and raise the\n   arms outward slightly beyond a 90-degree angle into a W position to hit\n   the rotator cuff muscles, and then lower back to the starting position.\n3. Then raise up again with arms\n   in a Y position to activate the lower traps.","name":"Hyper Y W Combo","created":"2025-03-06T09:30:01.907Z","last_update":"2026-04-13T18:58:26.646Z","language":2,"uuid":"40f9ae59-1870-4e05-ae42-9a91506bee81","exercise":1487}}],"aliases":[],"comments":[]}'),
('wger', '1488', 'dumbbell-pullover', 'https://wger.de/en/exercise/1488/view', 'CC-BY-SA-4.0', 'Moffi', 'normalized', 100.0, '{"exercise":{"model":"exercises.exercise","pk":1488,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Moffi","license_author_url":"","license_derivative_source_url":"","uuid":"c395ad8d-164c-4031-9136-b4116d354451","category":12,"variation_group":null,"created":"2025-03-06T09:54:49.804Z","last_update":"2025-03-06T09:54:49.804Z","muscles":[12],"muscles_secondary":[],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2451,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Moffi","license_author_url":"","license_derivative_source_url":"","description":"<ol>\n<li>Starting\nposition is lying across a flat bench perpendicularly with your feet flat\non the ground, holding a dumbbell overhead with both hands.</li>\n<li>With\na slight bend in the elbow, begin lowering the dumbbell over and behind\nthe head with the arm muscles in extended position.</li>\n<li>Then\nreverse the movement bringing the dumbbell back up and over the head.</li>\n<li>Keep\nyour abdominal muscles tight and spine stable throughout allow repetitions\nand don’t allow your back to arch up away from the flat bench.</li>\n</ol>\n","description_source":"1. Starting\n   position is lying across a flat bench perpendicularly with your feet flat\n   on the ground, holding a dumbbell overhead with both hands.\n2. With\n   a slight bend in the elbow, begin lowering the dumbbell over and behind\n   the head with the arm muscles in extended position.\n3. Then\n   reverse the movement bringing the dumbbell back up and over the head.\n4. Keep\n   your abdominal muscles tight and spine stable throughout allow repetitions\n   and don’t allow your back to arch up away from the flat bench.","name":"Dumbbell Pullover","created":"2025-03-06T09:54:50.074Z","last_update":"2026-04-13T18:58:26.429Z","language":2,"uuid":"52a3b378-9bcf-4b8d-8bcc-a61b264ac8bf","exercise":1488}}],"aliases":[],"comments":[{"model":"exercises.exercisecomment","pk":553,"fields":{"uuid":"32b4a105-49fc-42fc-be61-b31b7ae5584f","translation":2451,"comment":"This is an excellent dumbbell exercise for laser targeting the lats."}}]}'),
('wger', '1489', 'plank-jacks', 'https://wger.de/en/exercise/1489/view', 'CC-BY-SA-4.0', 'jayninja', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1489,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"jayninja","license_author_url":"","license_derivative_source_url":"","uuid":"4f5de647-eb73-4394-84a7-469d02a96de8","category":10,"variation_group":null,"created":"2025-03-10T01:27:32.008Z","last_update":"2025-03-10T01:27:32.008Z","muscles":[8,14,6],"muscles_secondary":[7,10],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2452,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"jayninja","license_author_url":"","license_derivative_source_url":"","description":"<p>Jumping jacks from the plank position.</p>\n","description_source":"Jumping jacks from the plank position. ","name":"Plank Jacks","created":"2025-03-10T01:27:32.330Z","last_update":"2026-04-13T18:58:26.967Z","language":2,"uuid":"f253340c-8f1c-4431-b651-89a87b060c4d","exercise":1489}}],"aliases":[],"comments":[]}'),
('wger', '1490', 'dumbbell-lying-triceps-kickback', 'https://wger.de/en/exercise/1490/view', 'CC-BY-SA-4.0', 'Moffi', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1490,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Moffi","license_author_url":"","license_derivative_source_url":"","uuid":"9c979645-78d1-44be-92a0-7940430a6a98","category":8,"variation_group":null,"created":"2025-03-10T12:44:54.900Z","last_update":"2025-03-10T12:44:54.900Z","muscles":[5],"muscles_secondary":[],"equipment":[3,9]}},"translations":[{"model":"exercises.translation","pk":2453,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Moffi","license_author_url":"","license_derivative_source_url":"","description":"<p>Set the bench to an 60deg angle. Stand still and rest your upper body on the inclined bench, ensuring a nearly straight line of your entire body. Squeeze your shoulder blades together, so that your elbows are located behind your torso with your upper arms nearly parallel to the floor. Lift the dumbbells until your arms form a straight line. Slowly lower the dumbbells back to the initial position. Initial position corresponds to an rectangular position of upper and lower arms.</p>\n","description_source":"Set the bench to an 60deg angle. Stand still and rest your upper body on the inclined bench, ensuring a nearly straight line of your entire body. Squeeze your shoulder blades together, so that your elbows are located behind your torso with your upper arms nearly parallel to the floor. Lift the dumbbells until your arms form a straight line. Slowly lower the dumbbells back to the initial position. Initial position corresponds to an rectangular position of upper and lower arms.","name":"Lying Triceps Kickback","created":"2025-03-10T12:44:55.766Z","last_update":"2026-04-13T18:58:26.829Z","language":2,"uuid":"4ee28a5b-ed37-44cf-90dd-48e352ad60c1","exercise":1490}}],"aliases":[],"comments":[{"model":"exercises.exercisecomment","pk":554,"fields":{"uuid":"2c1444fb-c4b7-4322-9d0e-278b2ae9b9c4","translation":2453,"comment":"Keep your upper arms more or less parallel to the floor during the entire exercise to maximize muscle activation."}},{"model":"exercises.exercisecomment","pk":555,"fields":{"uuid":"2f04e490-52ca-43c5-b4b1-f68b734e09ca","translation":2453,"comment":"Start with some light weights to focus on a proper form and a good mind-muscle connection."}}]}'),
('wger', '1491', 'remada-unilateral-no-cabo', 'https://wger.de/en/exercise/1491/view', 'CC-BY-SA-4.0', 'technofer', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1491,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"technofer","license_author_url":"","license_derivative_source_url":"","uuid":"dd0d5504-6204-4775-86f2-84b7c69fff5f","category":12,"variation_group":null,"created":"2025-03-13T12:45:14.040Z","last_update":"2025-03-13T12:45:14.040Z","muscles":[12],"muscles_secondary":[],"equipment":[6]}},"translations":[{"model":"exercises.translation","pk":2454,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"technofer","license_author_url":"","license_derivative_source_url":"","description":"<p>pegada neutra&nbsp;A remada unilateral, também conhecida como remada serrote, é um exercício que&nbsp;fortalece as costas e os bíceps, além de melhorar a postura.</p>\n","description_source":"pegada neutra A remada unilateral, também conhecida como remada serrote, é um exercício que fortalece as costas e os bíceps, além de melhorar a postura. ","name":"Remada unilateral no cabo","created":"2025-03-13T12:45:14.427Z","last_update":"2026-04-13T18:58:27.131Z","language":2,"uuid":"183db424-d168-47c1-acfa-0ef5299959c6","exercise":1491}}],"aliases":[],"comments":[]}'),
