('wger', '1496', 'dumbbell-upper-chest-variation', 'https://wger.de/en/exercise/1496/view', 'CC-BY-SA-4.0', 'JohnPreston', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1496,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"JohnPreston","license_author_url":"","license_derivative_source_url":"","uuid":"4b23738a-67a8-41af-996d-abc53a7c3f97","category":11,"variation_group":null,"created":"2025-04-06T19:31:31.402Z","last_update":"2025-04-06T19:31:31.402Z","muscles":[4],"muscles_secondary":[2],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2458,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"JohnPreston","license_author_url":"","license_derivative_source_url":"","description":"<p>Dumbbell in hand in a curl fashion, lean body into the arm to help the dumbbell up above the chest, next to the head, to activate chest and delt combo</p>\n","description_source":"Dumbbell in hand in a curl fashion, lean body into the arm to help the dumbbell up above the chest, next to the head, to activate chest and delt combo","name":"DB Upper Chest Variation","created":"2025-04-06T19:31:31.597Z","last_update":"2026-04-13T18:58:26.369Z","language":2,"uuid":"0169ded6-95dc-47e6-8725-8ea5769a0945","exercise":1496}}],"aliases":[],"comments":[]}'),
