('wger', '1499', 'dumbbell-skullcrusher', 'https://wger.de/en/exercise/1499/view', 'CC-BY-SA-4.0', 'JohnPreston', 'normalized', 100.0, '{"exercise":{"model":"exercises.exercise","pk":1499,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"JohnPreston","license_author_url":"","license_derivative_source_url":"","uuid":"0cbe304f-0b5f-4153-aed1-024e654dee90","category":8,"variation_group":null,"created":"2025-04-06T19:43:58.558Z","last_update":"2025-04-06T19:43:58.558Z","muscles":[5],"muscles_secondary":[],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2461,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"JohnPreston","license_author_url":"","license_derivative_source_url":"","description":"<p>Alike tricpes extensions, DBs fall down near the head and pushed back up. Unlike for the triceps extension tring to extend the arms as far back</p>\n","description_source":"Alike tricpes extensions, DBs fall down near the head and pushed back up. Unlike for the triceps extension tring to extend the arms as far back","name":"DB Skull Crushers","created":"2025-04-06T19:43:58.675Z","last_update":"2026-04-13T18:58:26.367Z","language":2,"uuid":"cd847d3a-1faa-4490-8812-b459dd9a2c1c","exercise":1499}}],"aliases":[],"comments":[]}'),
('wger', '1500', 'dumbbell-ucv', 'https://wger.de/en/exercise/1500/view', 'CC-BY-SA-4.0', 'JohnPreston', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1500,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"JohnPreston","license_author_url":"","license_derivative_source_url":"","uuid":"5efffab3-53dd-4c2a-9558-31e3b5cebbcc","category":11,"variation_group":null,"created":"2025-04-06T19:51:14.674Z","last_update":"2025-04-06T19:51:14.674Z","muscles":[4],"muscles_secondary":[2],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2462,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"JohnPreston","license_author_url":"","license_derivative_source_url":"","description":"<p>Dumbbell upper chest variance. Curl like movement up above at head level, activating chest and front delts</p>\n","description_source":"Dumbbell upper chest variance. Curl like movement up above at head level, activating chest and front delts","name":"DB UCV","created":"2025-04-06T19:51:14.805Z","last_update":"2026-04-13T18:58:26.367Z","language":2,"uuid":"fe581474-0a72-410f-86bb-95d477d2c6e0","exercise":1500}}],"aliases":[],"comments":[]}'),
