('wger', '1502', 'dumbbell-cross-body-hammer-curl', 'https://wger.de/en/exercise/1502/view', 'CC-BY-SA-4.0', 'JohnPreston', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1502,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"JohnPreston","license_author_url":"","license_derivative_source_url":"","uuid":"038f7cb1-6aa3-4c48-a19d-a31993f7b0d8","category":8,"variation_group":null,"created":"2025-04-06T20:06:28.793Z","last_update":"2025-04-06T20:06:28.793Z","muscles":[1],"muscles_secondary":[],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2464,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"JohnPreston","license_author_url":"","license_derivative_source_url":"","description":"<p>Dumbbell cross body biceps curls, works on the braccialis</p>\n","description_source":"Dumbbell cross body biceps curls, works on the braccialis","name":"DB Cross Body Hammer Curls","created":"2025-04-06T20:06:28.905Z","last_update":"2026-04-13T18:58:26.366Z","language":2,"uuid":"ba778fd8-e5d8-4987-8e2d-9078e2110082","exercise":1502}}],"aliases":[],"comments":[]}'),
('wger', '1503', 'dumbbell-frog-press', 'https://wger.de/en/exercise/1503/view', 'CC-BY-SA-4.0', 'JohnPreston', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1503,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"JohnPreston","license_author_url":"","license_derivative_source_url":"","uuid":"b407768d-d519-47b8-818a-44c9761a8be6","category":9,"variation_group":null,"created":"2025-04-06T20:13:47.713Z","last_update":"2025-04-06T20:13:47.713Z","muscles":[8],"muscles_secondary":[],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2465,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"JohnPreston","license_author_url":"","license_derivative_source_url":"","description":"<p>Similar to hip thrust, but with feet put up together, lifting the butt off the ground in a frog like position.</p>\n","description_source":"Similar to hip thrust, but with feet put up together, lifting the butt off the ground in a frog like position.","name":"Dumbbell Frog Press","created":"2025-04-06T20:13:47.848Z","last_update":"2026-04-13T18:58:26.419Z","language":2,"uuid":"a2f4f3f8-582c-4aaa-9a17-df96d8e734a7","exercise":1503}}],"aliases":[],"comments":[]}'),
('wger', '1504', 'dumbbell-bradford-press', 'https://wger.de/en/exercise/1504/view', 'CC-BY-SA-4.0', 'JohnPreston', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1504,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"JohnPreston","license_author_url":"","license_derivative_source_url":"","uuid":"82f19d1c-f12b-49f0-bfdd-24239f93eabc","category":13,"variation_group":null,"created":"2025-04-06T20:16:50.863Z","last_update":"2025-04-06T20:16:50.863Z","muscles":[2],"muscles_secondary":[],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2466,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"JohnPreston","license_author_url":"","license_derivative_source_url":"","description":"<p>From a front hold of the DBs in a OHP, press above the head, bring back towards the rear of the shoulders, down, and press back forward.</p>\n","description_source":"From a front hold of the DBs in a OHP, press above the head, bring back towards the rear of the shoulders, down, and press back forward.","name":"Dumbbell Bradford press","created":"2025-04-06T20:16:50.981Z","last_update":"2026-04-13T18:58:26.412Z","language":2,"uuid":"ceaddaef-06a4-42ee-a335-d677304810cc","exercise":1504}}],"aliases":[],"comments":[]}'),
('wger', '1508', 'smith-machine-high-incline-press', 'https://wger.de/en/exercise/1508/view', 'CC-BY-SA-4.0', 'Expenses7000', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1508,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Expenses7000","license_author_url":"","license_derivative_source_url":"","uuid":"ecba2395-f364-4e5f-a34c-04f178c8b822","category":11,"variation_group":null,"created":"2025-04-12T19:51:01.277Z","last_update":"2025-04-12T19:51:01.277Z","muscles":[2,4,5],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2467,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Expenses7000","license_author_url":"","license_derivative_source_url":"","description":"<p>Set the bench to a 45-60° incline. Touch the upper chest with the bar.</p>\n","description_source":"Set the bench to a 45-60° incline. Touch the upper chest with the bar.","name":"High-Incline Smith Machine Press","created":"2025-04-12T19:51:01.445Z","last_update":"2026-04-13T18:58:26.627Z","language":2,"uuid":"211279c2-5f1b-49aa-818d-a16d9ae0d594","exercise":1508}}],"aliases":[],"comments":[]}'),
('wger', '1509', 'cable-tricep-kickback', 'https://wger.de/en/exercise/1509/view', 'CC-BY-SA-4.0', 'Expenses7000', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1509,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Expenses7000","license_author_url":"","license_derivative_source_url":"","uuid":"1ea73578-08a5-4f3e-9255-3c58b29b170d","category":8,"variation_group":null,"created":"2025-04-12T20:35:00.547Z","last_update":"2025-04-12T20:35:00.547Z","muscles":[5],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2468,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Expenses7000","license_author_url":"","license_derivative_source_url":"","description":"<p>Grab onto the handle, and pull your elbow up and back slightly above\nyour torso. Keep your upper arm to be parallel to the ground for the\nduration of the set</p>\n","description_source":"Grab onto the handle, and pull your elbow up and back slightly above\nyour torso. Keep your upper arm to be parallel to the ground for the\nduration of the set","name":"Cable Tricep Kickback","created":"2025-04-12T20:35:00.696Z","last_update":"2026-04-13T18:58:26.184Z","language":2,"uuid":"a90096c1-fa50-4ab3-9918-0395b938b003","exercise":1509}}],"aliases":[],"comments":[]}'),
('wger', '1510', 'neutral-grip-lat-pulldown', 'https://wger.de/en/exercise/1510/view', 'CC-BY-SA-4.0', 'Expenses7000', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1510,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Expenses7000","license_author_url":"","license_derivative_source_url":"","uuid":"3cad7b92-a16b-45dc-a53e-d6a01a158f8e","category":12,"variation_group":null,"created":"2025-04-12T20:51:09.259Z","last_update":"2025-04-12T20:51:09.259Z","muscles":[12],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2469,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Expenses7000","license_author_url":"","license_derivative_source_url":"","description":"<p>Lat pull downs with a neutral grip on the bar.</p>\n","description_source":"Lat pull downs with a neutral grip on the bar.","name":"Neutral Grip Lat Pulldown","created":"2025-04-12T20:51:09.385Z","last_update":"2026-04-13T18:58:26.871Z","language":2,"uuid":"5f92d7e1-4e21-484b-9645-2f66bea4f950","exercise":1510}}],"aliases":[],"comments":[]}'),
('wger', '1511', 'dumbbell-kong-curl', 'https://wger.de/en/exercise/1511/view', 'CC-BY-SA-4.0', 'Moffi', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1511,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Moffi","license_author_url":"","license_derivative_source_url":"","uuid":"329d2adc-4b2c-4bb2-95d7-f5f6fedb9b96","category":8,"variation_group":null,"created":"2025-04-14T11:33:29.540Z","last_update":"2025-04-14T11:33:29.540Z","muscles":[1],"muscles_secondary":[],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2470,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Moffi","license_author_url":"","license_derivative_source_url":"","description":"<p>This exercise is somewhat similar to a cable curl and a cable crossover. But instead of a chest/biceps exercise, this exercise targets the brachialis muscle, responsible for that broad arm when viewed from a front view.\nDuring the exercise, maintain a pronated forearm position with starting position of approx. 45 degree pronated. Start with slightly bend elbows and alternately curl until your hands (your thumb first) meet your upper middle chest (similar to how Kong hits his chest, thus the name of this exercise).</p>\n","description_source":"This exercise is somewhat similar to a cable curl and a cable crossover. But instead of a chest/biceps exercise, this exercise targets the brachialis muscle, responsible for that broad arm when viewed from a front view.\nDuring the exercise, maintain a pronated forearm position with starting position of approx. 45 degree pronated. Start with slightly bend elbows and alternately curl until your hands (your thumb first) meet your upper middle chest (similar to how Kong hits his chest, thus the name of this exercise).","name":"Kong Curl","created":"2025-04-14T11:33:29.723Z","last_update":"2026-04-13T18:58:26.735Z","language":2,"uuid":"9ed44155-f7ab-4d30-948f-7cf9edf325da","exercise":1511}}],"aliases":[],"comments":[]}'),
('wger', '1512', 'dumbbell-drop-curl', 'https://wger.de/en/exercise/1512/view', 'CC-BY-SA-4.0', 'Moffi', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1512,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Moffi","license_author_url":"","license_derivative_source_url":"","uuid":"15ee508d-fbd7-4acf-ab44-e35525582693","category":8,"variation_group":null,"created":"2025-04-14T11:45:55.921Z","last_update":"2025-04-14T11:45:55.921Z","muscles":[1],"muscles_secondary":[],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2471,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Moffi","license_author_url":"","license_derivative_source_url":"","description":"<p>Drop curls in a modified position at a slow pace effectively engage the brachialis for arm width.\nStarting position is with both arms in a slight angle towards each other at chest height with a dumbbell in each hand. Lower one dumbbell close to full extended arm position slowly and in a controlled manner during the first half of the curl, then curl it back up to starting position, while the other dumbbell stays at its starting position. Now lower the other dumbbell down. This keeps tension on the brachialis. As we pass the 90deg mark on our way down, the biceps will take over the work.</p>\n","description_source":"Drop curls in a modified position at a slow pace effectively engage the brachialis for arm width.\nStarting position is with both arms in a slight angle towards each other at chest height with a dumbbell in each hand. Lower one dumbbell close to full extended arm position slowly and in a controlled manner during the first half of the curl, then curl it back up to starting position, while the other dumbbell stays at its starting position. Now lower the other dumbbell down. This keeps tension on the brachialis. As we pass the 90deg mark on our way down, the biceps will take over the work.","name":"Drop Curl","created":"2025-04-14T11:45:56.093Z","last_update":"2026-04-13T18:58:26.409Z","language":2,"uuid":"4de70c8c-d995-4795-a50c-629dc833f4f5","exercise":1512}}],"aliases":[],"comments":[]}'),
('wger', '1513', 'cable-overhead-tricep-extension', 'https://wger.de/en/exercise/1513/view', 'CC-BY-SA-4.0', 'Expenses7000', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1513,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Expenses7000","license_author_url":"","license_derivative_source_url":"","uuid":"f2e17c8d-7285-4fd5-bfe8-26f407802850","category":8,"variation_group":null,"created":"2025-04-22T16:13:44.605Z","last_update":"2025-04-22T16:13:44.605Z","muscles":[5],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2472,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Expenses7000","license_author_url":"","license_derivative_source_url":"","description":"<p>Use rope handle with your back against the cable machine. Straighten your arms until they are filly extended and reverse the motion resisting on the negative.</p>\n","description_source":"Use rope handle with your back against the cable machine. Straighten your arms until they are filly extended and reverse the motion resisting on the negative.","name":"Overhead Cable Tricep Extension","created":"2025-04-22T16:13:44.835Z","last_update":"2026-04-13T18:58:26.893Z","language":2,"uuid":"1fddce36-4a94-4d01-b72b-ed170a5930c9","exercise":1513}}],"aliases":[],"comments":[]}'),
('wger', '1514', 'lateral-walk', 'https://wger.de/en/exercise/1514/view', 'CC-BY-SA-4.0', 'cozyGalvinism', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1514,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"cozyGalvinism","license_author_url":"","license_derivative_source_url":"","uuid":"c5015ed9-042b-42d3-9dac-13759ea9571e","category":12,"variation_group":null,"created":"2025-04-26T12:37:03.397Z","last_update":"2025-04-26T12:37:03.397Z","muscles":[8],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2473,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"cozyGalvinism","license_author_url":"","license_derivative_source_url":"","description":"<p>Lateral walks, also known as side steps or squat walks, are a type of exercise where you move sideways in a squatting position. They can be performed with or without resistance bands. These exercises strengthen the hip abductors, glutes, and other stabilizing muscles.</p>\n","description_source":"Lateral walks, also known as side steps or squat walks, are a type of exercise where you move sideways in a squatting position. They can be performed with or without resistance bands. These exercises strengthen the hip abductors, glutes, and other stabilizing muscles.","name":"Lateral Walk","created":"2025-04-26T12:37:03.563Z","last_update":"2026-04-13T18:58:26.767Z","language":2,"uuid":"af549f3b-ef65-4b3b-ae42-a3233889d5b0","exercise":1514}}],"aliases":[],"comments":[]}'),
('wger', '1515', 'leg-press-toe', 'https://wger.de/en/exercise/1515/view', 'CC-BY-SA-4.0', 'Expenses7000', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1515,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Expenses7000","license_author_url":"","license_derivative_source_url":"","uuid":"0cc9c8ed-57f1-42c3-a4c4-6e57e6a1b878","category":9,"variation_group":null,"created":"2025-05-04T11:04:01.041Z","last_update":"2025-05-04T11:04:01.041Z","muscles":[7],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2474,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Expenses7000","license_author_url":"","license_derivative_source_url":"","description":"<p>Move the leg press&nbsp;using your calves by placing your feet at the bottom of the platform.</p>\n","description_source":"Move the leg press using your calves by placing your feet at the bottom of the platform.","name":"Leg Press Toe Press","created":"2025-05-04T11:04:01.237Z","last_update":"2026-04-13T18:58:26.778Z","language":2,"uuid":"38b82e3c-43cc-4c98-827c-55adf1adeded","exercise":1515}}],"aliases":[],"comments":[]}'),
('wger', '1516', 'handstand', 'https://wger.de/en/exercise/1516/view', 'CC-BY-SA-4.0', 'Fittness69', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1516,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Fittness69","license_author_url":"","license_derivative_source_url":"","uuid":"35008ce6-74ca-40db-b965-44a1eccfa061","category":13,"variation_group":null,"created":"2025-05-06T12:17:22.932Z","last_update":"2025-05-06T12:17:22.932Z","muscles":[2],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2475,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Fittness69","license_author_url":"","license_derivative_source_url":"","description":"<p>Handstand free standing by pressing arms into the ground and contracting core and glutes</p>\n","description_source":"Handstand free standing by pressing arms into the ground and contracting core and glutes","name":"Handstand","created":"2025-05-06T12:17:23.558Z","last_update":"2026-04-13T18:58:26.611Z","language":2,"uuid":"e6f978cc-2277-4cc8-b71b-b6f8f615bc95","exercise":1516}}],"aliases":[],"comments":[]}'),
('wger', '1519', 'ez-bar-overhead-triceps-extension', 'https://wger.de/en/exercise/1519/view', 'CC-BY-SA-4.0', 'benjamin.yildiz@proton.me', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1519,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"benjamin.yildiz@proton.me","license_author_url":"","license_derivative_source_url":"","uuid":"c5797bdf-1aa1-4d51-9775-c929ec5a2aaf","category":8,"variation_group":null,"created":"2025-05-09T18:55:52.053Z","last_update":"2025-05-09T18:55:52.053Z","muscles":[9],"muscles_secondary":[],"equipment":[2]}},"translations":[{"model":"exercises.translation","pk":2476,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"benjamin.yildiz@proton.me","license_author_url":"","license_derivative_source_url":"","description":"<p><strong>Overhead Triceps Extension with EZ Bar – Quick Guide</strong></p>\n<p>The <strong>overhead position</strong> <em>emphasizes the long head</em> of the triceps (because it''s stretched under load), the exercise <strong>does engage all three triceps heads</strong> (long, lateral, and medial) to some degree during extension.</p>\n<ol>\n<li><strong>Setup</strong>:\nSit on a bench (or stand) and hold an EZ bar with a narrow, overhand\ngrip. Lift the bar overhead, arms fully extended. Keep your core tight\nand elbows close to your head.</li>\n<li><strong>Execution</strong>:\nSlowly lower the bar behind your head by bending your elbows until they\nreach ~90°. Keep elbows pointed forward (not flaring out).</li>\n<li><strong>Finish</strong>: Extend your arms back up to the starting position, squeezing your triceps at the top.</li>\n</ol>\n<p><strong>Tips</strong>:</p>\n<ul>\n<li>Control the movement to avoid straining your shoulders.</li>\n<li>Use a moderate weight for full range of motion.</li>\n<li>Keep your back straight and avoid arching.</li>\n</ul>\n","description_source":"**Overhead Triceps Extension with EZ Bar – Quick Guide**\n\nThe **overhead position** *emphasizes the long head* of the triceps (because it''s stretched under load), the exercise **does engage all three triceps heads** (long, lateral, and medial) to some degree during extension.\n\n1. **Setup**:\n   Sit on a bench (or stand) and hold an EZ bar with a narrow, overhand\n   grip. Lift the bar overhead, arms fully extended. Keep your core tight\n   and elbows close to your head.\n2. **Execution**:\n   Slowly lower the bar behind your head by bending your elbows until they\n   reach ~90°. Keep elbows pointed forward (not flaring out).\n3. **Finish**: Extend your arms back up to the starting position, squeezing your triceps at the top.\n\n**Tips**:\n\n* Control the movement to avoid straining your shoulders.\n* Use a moderate weight for full range of motion.\n* Keep your back straight and avoid arching.","name":"Overhead Triceps Extension","created":"2025-05-09T18:55:52.240Z","last_update":"2026-04-13T18:58:26.895Z","language":2,"uuid":"2f84145b-681e-4f9e-848f-7df92922f253","exercise":1519}}],"aliases":[],"comments":[]}'),
('wger', '1521', NULL, 'https://wger.de/en/exercise/1521/view', 'CC-BY-SA-4.0', 'polloperro', NULL, NULL, '{"exercise":{"model":"exercises.exercise","pk":1521,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"polloperro","license_author_url":"","license_derivative_source_url":"","uuid":"daaf1459-e748-4c95-8990-ed3101b2e20d","category":9,"variation_group":null,"created":"2025-05-13T21:03:24.811Z","last_update":"2025-05-13T21:03:24.811Z","muscles":[],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2477,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"polloperro","license_author_url":"","license_derivative_source_url":"","description":"<p>Pendulum hack, made on a pendulum machine</p>\n","description_source":"Pendulum hack, made on a pendulum machine","name":"Pendular hack","created":"2025-05-13T21:03:25.025Z","last_update":"2026-04-13T18:58:26.920Z","language":2,"uuid":"9530aeb3-bb3e-48c2-aeef-b5fc6064c5ea","exercise":1521}},{"model":"exercises.translation","pk":2610,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"admin","license_author_url":"","license_derivative_source_url":"","description":"<p>Pendular hack, realizado en máquina pendular</p>\n","description_source":"Pendular hack, realizado en máquina pendular","name":"Pendular hack","created":"2025-09-09T15:17:46.980Z","last_update":"2026-04-13T18:58:26.919Z","language":4,"uuid":"500b9186-e4d9-4ef4-8179-2ae85c644b50","exercise":1521}}],"aliases":[],"comments":[]}'),
('wger', '1523', 'sled-push', 'https://wger.de/en/exercise/1523/view', 'CC-BY-SA-4.0', 'flanny', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1523,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"flanny","license_author_url":"","license_derivative_source_url":"","uuid":"32cc7175-3fda-4c7e-900f-8766c22e3b2b","category":15,"variation_group":null,"created":"2025-05-14T02:20:28.011Z","last_update":"2025-05-14T02:20:28.011Z","muscles":[7,8,10],"muscles_secondary":[2,11,5],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2479,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"flanny","license_author_url":"","license_derivative_source_url":"","description":"<ol>\n<li>Load the sled with 25% of your maximum load. If you don’t know this, choose a weight you can push for 10 minutes with short breaks. Beginners may choose to push the sled with no weight.</li>\n<li>Stand behind the sled and grab the poles with a high-grip hand position.</li>\n<li>Engage your core muscles and start pushing the sled forward as fast as you can, powering through your entire leg. Extend your hips and knees as you move the sled forward. Your foot stance should resemble your natural running position.</li>\n</ol>\n","description_source":"1. Load the sled with 25% of your maximum load. If you don’t know this, choose a weight you can push for 10 minutes with short breaks. Beginners may choose to push the sled with no weight.\n2. Stand behind the sled and grab the poles with a high-grip hand position.\n3. Engage your core muscles and start pushing the sled forward as fast as you can, powering through your entire leg. Extend your hips and knees as you move the sled forward. Your foot stance should resemble your natural running position.","name":"Sled Push","created":"2025-05-14T02:20:28.412Z","last_update":"2026-04-13T18:58:27.429Z","language":2,"uuid":"8d050e84-6357-46f0-9953-322f728703b1","exercise":1523}}],"aliases":[],"comments":[]}'),
('wger', '1524', 'battle-ropes', 'https://wger.de/en/exercise/1524/view', 'CC-BY-SA-4.0', 'flanny', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1524,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"flanny","license_author_url":"","license_derivative_source_url":"","uuid":"a5d1f45b-ff07-45d7-a699-a654f9328934","category":15,"variation_group":null,"created":"2025-05-14T02:33:20.746Z","last_update":"2025-05-14T02:33:20.746Z","muscles":[11,8,12,14,10,6],"muscles_secondary":[2,1,4,9,5],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2480,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"flanny","license_author_url":"","license_derivative_source_url":"","description":"<ol>\n<li>Hold the ends of the rope at arm''s length in front of your hips with your hands shoulder-width apart.</li>\n<li>Brace your core and begin alternately raising and lowering each arm explosively.</li>\n<li>Keep alternating arms for three to four sets of 1 to 2 minutes.</li>\n</ol>\n","description_source":"1. Hold the ends of the rope at arm''s length in front of your hips with your hands shoulder-width apart.\n2. Brace your core and begin alternately raising and lowering each arm explosively.\n3. Keep alternating arms for three to four sets of 1 to 2 minutes.","name":"Battle Ropes","created":"2025-05-14T02:33:21.178Z","last_update":"2026-04-13T18:58:26.082Z","language":2,"uuid":"ca63f248-3fc8-43de-9f7b-9bbc2e3f03d4","exercise":1524}}],"aliases":[],"comments":[]}'),
('wger', '1525', 'ball-slam', 'https://wger.de/en/exercise/1525/view', 'CC-BY-SA-4.0', 'flanny', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1525,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"flanny","license_author_url":"","license_derivative_source_url":"","uuid":"a1e8759d-72b9-422f-87a8-9d316fa18498","category":15,"variation_group":null,"created":"2025-05-14T02:40:27.789Z","last_update":"2025-05-14T02:40:27.789Z","muscles":[12,14,6],"muscles_secondary":[2,8],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2481,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"flanny","license_author_url":"","license_derivative_source_url":"","description":"<ol>\n<li>Stand with your feet about shoulder-width apart, your knees and hips slightly bent, holding the ball in both hands at chest height. Engage your core, and keep a good posture.</li>\n<li>Extend your knees and drive your hips forward while simultaneously lifting the ball. Aim for being as tall as possible, the ball overhead, arms up, hips slightly forward, and on your toes from the force of your drive.</li>\n<li>Use your core and arms to slam the medicine ball straight down between your feet with as much force as possible. Press your hips back and bend your knees to further power the slam. Exhale as you slam the ball down.</li>\n<li>Squat down to pick up the ball from the floor, then immediately move into the next slam by repeating the movement. Repeat for reps or time.</li>\n</ol>\n","description_source":"1. Stand with your feet about shoulder-width apart, your knees and hips slightly bent, holding the ball in both hands at chest height. Engage your core, and keep a good posture.\n2. Extend your knees and drive your hips forward while simultaneously lifting the ball. Aim for being as tall as possible, the ball overhead, arms up, hips slightly forward, and on your toes from the force of your drive.\n3. Use your core and arms to slam the medicine ball straight down between your feet with as much force as possible. Press your hips back and bend your knees to further power the slam. Exhale as you slam the ball down.\n4. Squat down to pick up the ball from the floor, then immediately move into the next slam by repeating the movement. Repeat for reps or time.","name":"Ball Slams","created":"2025-05-14T02:40:28.293Z","last_update":"2026-04-13T18:58:26.060Z","language":2,"uuid":"29d863f2-e611-4182-aaf0-4699b9c2ba2b","exercise":1525}}],"aliases":[],"comments":[]}'),
('wger', '1526', 'machine-ski', 'https://wger.de/en/exercise/1526/view', 'CC-BY-SA-4.0', 'flanny', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1526,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"flanny","license_author_url":"","license_derivative_source_url":"","uuid":"e29d9914-6b02-490b-8f3a-f9fe8f21993c","category":15,"variation_group":null,"created":"2025-05-14T05:08:31.266Z","last_update":"2025-05-14T05:08:31.266Z","muscles":[7,12,9,5],"muscles_secondary":[11,8,10,6],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2482,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"flanny","license_author_url":"","license_derivative_source_url":"","description":"<ol>\n<li>Start standing on the platform with your feet hip-width apart.</li>\n<li>Reach overhead to grip the handles with your palms facing in.</li>\n<li>Soften your knees, then simultaneously drive your butt back as if you''re closing a door behind you while pulling your arms straight down past your hips until your hands pass by the side of your knees.</li>\n<li>Next, bring your arms back overhead while thrusting your hips forward until you''re standing with your arms fully extended.</li>\n<li>Repeat for reps, time or distance.</li>\n</ol>\n","description_source":"1. Start standing on the platform with your feet hip-width apart.\n2. Reach overhead to grip the handles with your palms facing in.\n3. Soften your knees, then simultaneously drive your butt back as if you''re closing a door behind you while pulling your arms straight down past your hips until your hands pass by the side of your knees.\n4. Next, bring your arms back overhead while thrusting your hips forward until you''re standing with your arms fully extended.\n5. Repeat for reps, time or distance.","name":"Ski Machine","created":"2025-05-14T05:08:31.697Z","last_update":"2026-04-13T18:58:27.422Z","language":2,"uuid":"acbbd5c9-a5ec-4f20-8f99-e44611473f94","exercise":1526}}],"aliases":[],"comments":[]}'),
('wger', '1527', 'pendulum-squat', 'https://wger.de/en/exercise/1527/view', 'CC-BY-SA-4.0', 'schweezer', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1527,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"schweezer","license_author_url":"","license_derivative_source_url":"","uuid":"ffdb4806-d64e-474b-8ce5-8df9a57fb9c7","category":9,"variation_group":null,"created":"2025-05-15T08:00:42.721Z","last_update":"2025-05-15T08:00:42.721Z","muscles":[10],"muscles_secondary":[11,8],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2484,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"schweezer","license_author_url":"","license_derivative_source_url":"","description":"<p>Place your feet in the middle of the plate at about shoulder width. Tense your torso. Keep your neck relaxed.</p>\n","description_source":"Place your feet in the middle of the plate at about shoulder width. Tense your torso. Keep your neck relaxed.","name":"Pendulum Squat","created":"2025-05-15T08:00:42.905Z","last_update":"2026-04-13T18:58:26.921Z","language":2,"uuid":"da76f66a-f083-48c9-99d3-e331ae3f0b56","exercise":1527}},{"model":"exercises.translation","pk":2486,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"schweezer","license_author_url":"","license_derivative_source_url":"","description":"<p>Platziere die Füße in der Mitte der Platte und ca. schulterbreit. Spanne den Bauch an. Entspanne den Nacken während der gesamten Übung.</p>\n","description_source":"Platziere die Füße in der Mitte der Platte und ca. schulterbreit. Spanne den Bauch an. Entspanne den Nacken während der gesamten Übung.","name":"Pendelkniebeube","created":"2025-05-16T07:08:20.177Z","last_update":"2026-04-13T18:58:26.919Z","language":1,"uuid":"3e718c83-0ae2-42ee-80c0-49ead002fd2a","exercise":1527}}],"aliases":[],"comments":[]}'),
('wger', '1528', 'glute-drive', 'https://wger.de/en/exercise/1528/view', 'CC-BY-SA-4.0', 'schweezer', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1528,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"schweezer","license_author_url":"","license_derivative_source_url":"","uuid":"ce21d3a2-cdc5-410c-9970-c25029ca3769","category":9,"variation_group":null,"created":"2025-05-16T06:59:30.982Z","last_update":"2025-05-16T06:59:30.982Z","muscles":[8],"muscles_secondary":[11,10],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2485,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"schweezer","license_author_url":"","license_derivative_source_url":"","description":"<p>Lie down on the back pad and strap yourself in with the waistband. Position yout feet&nbsp;shoulder-length apart. They should be slightly splayed.</p>\n","description_source":"Lie down on the back pad and strap yourself in with the waistband. Position yout feet shoulder-length apart. They should be slightly splayed.","name":"Glute Drive","created":"2025-05-16T06:59:31.169Z","last_update":"2026-04-13T18:58:26.594Z","language":2,"uuid":"fa0a47c0-ef5e-4cfa-9361-3e80bd5d49dd","exercise":1528}}],"aliases":[],"comments":[]}'),
('wger', '1529', NULL, 'https://wger.de/en/exercise/1529/view', 'CC-BY-SA-4.0', 'florian.bussmann; admin', NULL, NULL, '{"exercise":{"model":"exercises.exercise","pk":1529,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"florian.bussmann","license_author_url":"","license_derivative_source_url":"","uuid":"42d09639-a5a6-4aa6-b115-e4c96b1d3735","category":10,"variation_group":null,"created":"2025-05-17T20:07:31.685Z","last_update":"2025-05-17T20:07:31.685Z","muscles":[],"muscles_secondary":[],"equipment":[6]}},"translations":[{"model":"exercises.translation","pk":2487,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"florian.bussmann","license_author_url":"","license_derivative_source_url":"","description":"<p>The name \"Toes to Bar\" says it all: This exercise, in which you hang from a pull-up bar, involves bringing your toes toward the bar, pointing toward your face. This really works your abdominal muscles. \"Toes to Bar\" is popular in functional fitness programs like Freeletics and CrossFit, and is an effective exercise for six-pack training.</p>\n","description_source":"The name \"Toes to Bar\" says it all: This exercise, in which you hang from a pull-up bar, involves bringing your toes toward the bar, pointing toward your face. This really works your abdominal muscles. \"Toes to Bar\" is popular in functional fitness programs like Freeletics and CrossFit, and is an effective exercise for six-pack training.","name":"Toes to bar","created":"2025-05-17T20:07:31.897Z","last_update":"2026-04-13T18:58:27.660Z","language":2,"uuid":"46a6db00-8524-48cb-807a-12f3d75f4e12","exercise":1529}},{"model":"exercises.translation","pk":2612,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"admin","license_author_url":"","license_derivative_source_url":"","description":"<p>Der Name „Toes to Bar“ sagt es bereits: Bei dieser Übung, bei der Sie an einer Klimmzugstange hängen, geht es darum, die Zehenspitzen zur Stange Richtung Gesicht zu bringen. Dabei werden die Bauchmuskeln ordentlich gefordert. „Toes to Bar“ sind beliebt im Functional Fitness wie Freeletics oder CrossFit sowie eine wirksame Übung im Sixpack-Training.</p>\n","description_source":"Der Name „Toes to Bar“ sagt es bereits: Bei dieser Übung, bei der Sie an einer Klimmzugstange hängen, geht es darum, die Zehenspitzen zur Stange Richtung Gesicht zu bringen. Dabei werden die Bauchmuskeln ordentlich gefordert. „Toes to Bar“ sind beliebt im Functional Fitness wie Freeletics oder CrossFit sowie eine wirksame Übung im Sixpack-Training.","name":"Toes to bar","created":"2025-09-09T15:24:54.517Z","last_update":"2026-04-13T18:58:27.659Z","language":1,"uuid":"234f0ee4-2b24-445f-b1eb-b96d6ef72297","exercise":1529}}],"aliases":[],"comments":[]}'),
('wger', '1530', 'dumbbell-lying-curl', 'https://wger.de/en/exercise/1530/view', 'CC-BY-SA-4.0', 'Moffi', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1530,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Moffi","license_author_url":"","license_derivative_source_url":"","uuid":"861f7396-f34e-486c-a903-3c326086f920","category":8,"variation_group":null,"created":"2025-05-22T12:02:22.610Z","last_update":"2025-05-22T12:02:22.610Z","muscles":[1],"muscles_secondary":[],"equipment":[8,3]}},"translations":[{"model":"exercises.translation","pk":2488,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Moffi","license_author_url":"","license_derivative_source_url":"","description":"<p>Take a\ndumbbell in each hand and lie backwards on a bench, similar to a classic chest press.\nLet your arms hang down at your sides, with the dumbbells possibly touching the\nfloor. Now start to lift the dumbbells upwards until your forearms are\nperpendicular to the ceiling. Slowly lower the dumbbells until they almost\ntouch the floor again. Keep your ellbows in place to minimize cheating.</p>\n","description_source":"Take a\ndumbbell in each hand and lie backwards on a bench, similar to a classic chest press.\nLet your arms hang down at your sides, with the dumbbells possibly touching the\nfloor. Now start to lift the dumbbells upwards until your forearms are\nperpendicular to the ceiling. Slowly lower the dumbbells until they almost\ntouch the floor again. Keep your ellbows in place to minimize cheating.","name":"Lying Dumbbell Curls","created":"2025-05-22T12:02:22.879Z","last_update":"2026-04-13T18:58:26.824Z","language":2,"uuid":"eb71d001-100c-4d7e-9533-c37ab318992f","exercise":1530}}],"aliases":[],"comments":[]}'),
('wger', '1531', 'cable-biceps-curl', 'https://wger.de/en/exercise/1531/view', 'CC-BY-SA-4.0', 'Brigade7938', 'normalized', 100.0, '{"exercise":{"model":"exercises.exercise","pk":1531,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Brigade7938","license_author_url":"","license_derivative_source_url":"","uuid":"479ef6f0-5274-4da7-b5ad-67528ff3c8fd","category":8,"variation_group":null,"created":"2025-05-23T04:06:17.591Z","last_update":"2025-05-23T04:06:17.591Z","muscles":[1],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2489,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Brigade7938","license_author_url":"","license_derivative_source_url":"","description":"<p>Bicep Curls using cables. Can be seated or standing</p>\n","description_source":"Bicep Curls using cables. Can be seated or standing","name":"Cable Curls","created":"2025-05-23T04:06:17.894Z","last_update":"2026-04-13T18:58:26.171Z","language":2,"uuid":"6f9a3652-6e40-4af8-846b-5dbfe2be9b44","exercise":1531}}],"aliases":[],"comments":[]}'),
('wger', '1535', 'dumbbell-lying-curl', 'https://wger.de/en/exercise/1535/view', 'CC-BY-SA-4.0', 'wget@pytt.io', 'normalized', 100.0, '{"exercise":{"model":"exercises.exercise","pk":1535,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"wget@pytt.io","license_author_url":"","license_derivative_source_url":"","uuid":"9b68c3c4-fbe5-4c69-af0d-319e8fb5390d","category":8,"variation_group":null,"created":"2025-06-01T10:39:45.003Z","last_update":"2025-06-01T10:39:45.003Z","muscles":[1],"muscles_secondary":[],"equipment":[8,3]}},"translations":[{"model":"exercises.translation","pk":2490,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"wget@pytt.io","license_author_url":"","license_derivative_source_url":"","description":"<p>RP fitness bicept curle variant to get a good streach on bicept</p>\n","description_source":"RP fitness bicept curle variant to get a good streach on bicept","name":"lying bicep curl","created":"2025-06-01T10:39:45.210Z","last_update":"2026-04-13T18:58:27.955Z","language":2,"uuid":"c3ad64aa-2fb3-45d3-96fb-21906c71d6fc","exercise":1535}}],"aliases":[],"comments":[]}'),
('wger', '1536', 'delt-stretch', 'https://wger.de/en/exercise/1536/view', 'CC-BY-SA-4.0', 'Expenses7000', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1536,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Expenses7000","license_author_url":"","license_derivative_source_url":"","uuid":"6a448382-0ea9-4f41-8a83-0b7cd7d8a2bf","category":13,"variation_group":null,"created":"2025-06-02T18:26:47.722Z","last_update":"2025-06-02T18:26:47.722Z","muscles":[2],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2491,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Expenses7000","license_author_url":"","license_derivative_source_url":"","description":"<p>Stretch your deltoids for a certain period of time.</p>\n","description_source":"Stretch your deltoids for a certain period of time.","name":"Delt Stretch","created":"2025-06-02T18:26:48.025Z","last_update":"2026-04-13T18:58:26.383Z","language":2,"uuid":"5119be20-933c-4102-9148-3f6ac9d031de","exercise":1536}}],"aliases":[],"comments":[]}'),
('wger', '1537', 'pull-up-isometric-hold', 'https://wger.de/en/exercise/1537/view', 'CC-BY-SA-4.0', 'DiscoCop', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1537,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"DiscoCop","license_author_url":"","license_derivative_source_url":"","uuid":"5e3a322b-98dd-4197-b16f-4ac72c42c223","category":12,"variation_group":null,"created":"2025-06-06T21:32:14.886Z","last_update":"2025-06-06T21:32:14.886Z","muscles":[1,12,9],"muscles_secondary":[],"equipment":[6]}},"translations":[{"model":"exercises.translation","pk":2492,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"DiscoCop","license_author_url":"","license_derivative_source_url":"","description":"<p>Hold the pull-up movement in any position</p>\n","description_source":"Hold the pull-up movement in any position","name":"Pull-up Isometric Hold","created":"2025-06-06T21:32:15.265Z","last_update":"2026-04-13T18:58:27.093Z","language":2,"uuid":"bd50cc10-1fa3-4738-9cb1-32cdd48e97ad","exercise":1537}}],"aliases":[],"comments":[]}'),
('wger', '1542', 'wide-pull-up', 'https://wger.de/en/exercise/1542/view', 'CC-BY-SA-4.0', 'Antsy6277', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1542,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Antsy6277","license_author_url":"","license_derivative_source_url":"","uuid":"b2340417-dcd5-485a-9707-04dd9168b801","category":12,"variation_group":null,"created":"2025-06-22T20:22:37.313Z","last_update":"2025-06-22T20:22:37.313Z","muscles":[12],"muscles_secondary":[],"equipment":[6]}},"translations":[{"model":"exercises.translation","pk":2493,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Antsy6277","license_author_url":"","license_derivative_source_url":"","description":"<p>The grip width for a wide grip pull-up is typically wider than\nshoulder-width apart, which means your hands will be positioned farther\napart than they would be for a standard pull-up. This wider grip targets\nthe latissimus dorsi muscles more effectively, making it an excellent\nexercise for building upper body strength, particularly in the back\nmuscles.</p>\n","description_source":"The grip width for a wide grip pull-up is typically wider than\nshoulder-width apart, which means your hands will be positioned farther\napart than they would be for a standard pull-up. This wider grip targets\nthe latissimus dorsi muscles more effectively, making it an excellent\nexercise for building upper body strength, particularly in the back\nmuscles.","name":"Wide Pull Up","created":"2025-06-22T20:22:37.501Z","last_update":"2026-04-13T18:58:27.869Z","language":2,"uuid":"4302adb4-7956-4fa0-b273-4575b1109ff0","exercise":1542}}],"aliases":[],"comments":[]}'),
('wger', '1545', 'archer-pull-up', 'https://wger.de/en/exercise/1545/view', 'CC-BY-SA-4.0', 'Antsy6277', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1545,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Antsy6277","license_author_url":"","license_derivative_source_url":"","uuid":"56808c52-050e-4c24-9f27-2657f0462499","category":12,"variation_group":null,"created":"2025-06-22T20:28:55.929Z","last_update":"2025-06-22T20:28:55.929Z","muscles":[12],"muscles_secondary":[1,9],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2494,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Antsy6277","license_author_url":"","license_derivative_source_url":"","description":"<p>An archer pull-up is an advanced bodyweight exercise that strengthens your back and biceps, serving as a progression towards a one-arm pull-up. It gets its name from the \"bow-drawing\" position your body takes at the top.Here''s how to do it:1. Grip: Grasp a pull-up bar with a wider-than-shoulder-width overhand grip.2. Starting Position: Hang with arms fully extended, engaging your core and keeping your shoulder blades pulled down.3. The Pull: Pull your body up towards one hand, similar to a regular pull-up. At the same time, extend the other arm out to the side, keeping it as straight as possible. Your chin should come towards the hand that is pulling.4. Hold &amp; Lower: Briefly hold the top position where one arm is bent and pulling, and the other is extended. Slowly lower yourself back to the starting position with control.5. Alternate: Repeat the movement, pulling up towards the opposite hand.The key to this exercise is to keep the assisting arm as straight as possible to maximise the load on the working arm. This makes it a challenging but effective exercise for unilateral pulling strength.</p>\n","description_source":"An archer pull-up is an advanced bodyweight exercise that strengthens your back and biceps, serving as a progression towards a one-arm pull-up. It gets its name from the \"bow-drawing\" position your body takes at the top.Here''s how to do it:1. Grip: Grasp a pull-up bar with a wider-than-shoulder-width overhand grip.2. Starting Position: Hang with arms fully extended, engaging your core and keeping your shoulder blades pulled down.3. The Pull: Pull your body up towards one hand, similar to a regular pull-up. At the same time, extend the other arm out to the side, keeping it as straight as possible. Your chin should come towards the hand that is pulling.4. Hold & Lower: Briefly hold the top position where one arm is bent and pulling, and the other is extended. Slowly lower yourself back to the starting position with control.5. Alternate: Repeat the movement, pulling up towards the opposite hand.The key to this exercise is to keep the assisting arm as straight as possible to maximise the load on the working arm. This makes it a challenging but effective exercise for unilateral pulling strength.","name":"Archer Pull Up","created":"2025-06-22T20:28:56.109Z","last_update":"2026-04-13T18:58:26.039Z","language":2,"uuid":"bb0c40c0-1728-4d7f-82a2-7fe5e732ef29","exercise":1545}}],"aliases":[],"comments":[]}'),
('wger', '1546', 'barbell-larsen-press', 'https://wger.de/en/exercise/1546/view', 'CC-BY-SA-4.0', 'Expenses7000', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1546,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Expenses7000","license_author_url":"","license_derivative_source_url":"","uuid":"87f30f6d-dc8a-4b26-8c4f-640b66ecacf0","category":11,"variation_group":null,"created":"2025-06-23T20:20:50.129Z","last_update":"2025-06-23T20:20:50.129Z","muscles":[4],"muscles_secondary":[5],"equipment":[1]}},"translations":[{"model":"exercises.translation","pk":2495,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Expenses7000","license_author_url":"","license_derivative_source_url":"","description":"<p>Put your legs up on a separate Bench and press with no leg drive</p>\n","description_source":"Put your legs up on a separate Bench and press with no leg drive","name":"Larsen Press","created":"2025-06-23T20:20:50.298Z","last_update":"2026-04-13T18:58:26.755Z","language":2,"uuid":"f9663985-8d98-4d73-a4a8-1b84208bfb0f","exercise":1546}}],"aliases":[],"comments":[]}'),
('wger', '1548', 'stair-master', 'https://wger.de/en/exercise/1548/view', 'CC-BY-SA-4.0', 'MisterPinnacle', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1548,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"MisterPinnacle","license_author_url":"","license_derivative_source_url":"","uuid":"b3e433ed-0247-46b3-be77-9f2738a09a48","category":15,"variation_group":null,"created":"2025-07-06T17:38:47.041Z","last_update":"2025-07-06T17:38:47.041Z","muscles":[11,7,8,10],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2496,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"MisterPinnacle","license_author_url":"","license_derivative_source_url":"","description":"<p>cardio and lower-body strength machine&nbsp;designed to simulate climbing stairs. It provides a&nbsp;low-impact, high-intensity workout&nbsp;that targets the legs, glutes, and core while improving cardiovascular endurance.</p>\n","description_source":"cardio and lower-body strength machine designed to simulate climbing stairs. It provides a low-impact, high-intensity workout that targets the legs, glutes, and core while improving cardiovascular endurance.","name":"Stair Master","created":"2025-07-06T17:38:47.404Z","last_update":"2026-04-13T18:58:27.514Z","language":2,"uuid":"d2c534a5-88bc-429b-9a21-3e9c239baea1","exercise":1548}}],"aliases":[],"comments":[]}'),
('wger', '1549', 'stair-master', 'https://wger.de/en/exercise/1549/view', 'CC-BY-SA-4.0', 'MisterPinnacle', 'exact', 100.0, '{"exercise":{"model":"exercises.exercise","pk":1549,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"MisterPinnacle","license_author_url":"","license_derivative_source_url":"","uuid":"3edc1a89-f669-41ba-a8fc-d663fbbdc8ba","category":15,"variation_group":null,"created":"2025-07-06T17:41:07.920Z","last_update":"2025-07-06T17:41:07.920Z","muscles":[11,7,8,10],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2497,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"MisterPinnacle","license_author_url":"","license_derivative_source_url":"","description":"<p><strong>cardio and lower-body strength machine designed to simulate climbing stairs. It provides a low-impact, high-intensity workout that targets the legs, glutes, and core while improving cardiovascular endurance.</strong></p>\n","description_source":"**cardio and lower-body strength machine designed to simulate climbing stairs. It provides a low-impact, high-intensity workout that targets the legs, glutes, and core while improving cardiovascular endurance.**","name":"Stair Master","created":"2025-07-06T17:41:08.215Z","last_update":"2026-04-13T18:58:27.516Z","language":2,"uuid":"0cb1908e-6c7d-4f61-a65a-9bb746accec0","exercise":1549}}],"aliases":[],"comments":[]}'),
('wger', '1551', 'push-up', 'https://wger.de/en/exercise/1551/view', 'CC-BY-SA-4.0', 'Settebello', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1551,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Settebello","license_author_url":"","license_derivative_source_url":"","uuid":"f5b84269-18af-4464-a61f-b767cbcd81dc","category":11,"variation_group":"9cbed464-c3ca-40bc-ad83-ec5fe8faffab","created":"2025-07-07T11:48:38.312Z","last_update":"2025-10-12T21:57:01.562Z","muscles":[4],"muscles_secondary":[2,6,5],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2498,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Settebello","license_author_url":"","license_derivative_source_url":"","description":"<p>The push-up is a fundamental bodyweight exercise that targets the chest, arms, and shoulders while engaging the core for stability. It requires no equipment and is excellent for building upper body strength.</p>\n<p>Instructions:</p>\n<ol>\n<li>Start in a plank position with hands placed slightly wider than shoulder-width, feet together, and body in a straight line from head to heels.</li>\n<li>Engage your core and lower your body by bending your elbows, keeping them close to your body or flared slightly outward.</li>\n<li>Lower until your chest nearly touches the ground while maintaining a neutral spine.</li>\n<li>Push through your palms to return to the starting position, fully extending your arms.</li>\n</ol>\n","description_source":"The push-up is a fundamental bodyweight exercise that targets the chest, arms, and shoulders while engaging the core for stability. It requires no equipment and is excellent for building upper body strength.\n\nInstructions:\n\n1. Start in a plank position with hands placed slightly wider than shoulder-width, feet together, and body in a straight line from head to heels.\n2. Engage your core and lower your body by bending your elbows, keeping them close to your body or flared slightly outward.\n3. Lower until your chest nearly touches the ground while maintaining a neutral spine.\n4. Push through your palms to return to the starting position, fully extending your arms.","name":"Push-Up","created":"2025-07-07T11:48:38.623Z","last_update":"2026-04-13T18:58:27.106Z","language":2,"uuid":"2f99b628-1389-40c0-8fa6-dcc72eea7b3b","exercise":1551}},{"model":"exercises.translation","pk":2504,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Settebello","license_author_url":"","license_derivative_source_url":"","description":"<p>La flexión es un ejercicio fundamental con peso corporal que trabaja el pecho, los brazos y los hombros, a la vez que trabaja el core para lograr estabilidad. No requiere equipo y es excelente para fortalecer la parte superior del cuerpo.&nbsp;\n&nbsp;Instrucciones:</p>\n<ol>\n<li>Comience en posición de plancha con las manos colocadas ligeramente más anchas que el ancho de los hombros, los pies juntos y el cuerpo en línea recta desde la cabeza hasta los talones.</li>\n<li>Contraiga el torso y baje el cuerpo flexionando los codos, manteniéndolos cerca del cuerpo o ligeramente separados.</li>\n<li>Baje hasta que el pecho casi toque el suelo, manteniendo la columna neutra.</li>\n<li>Empuje con las palmas de las manos para volver a la posición inicial, extendiendo completamente los brazos.</li>\n</ol>\n","description_source":"La flexión es un ejercicio fundamental con peso corporal que trabaja el pecho, los brazos y los hombros, a la vez que trabaja el core para lograr estabilidad. No requiere equipo y es excelente para fortalecer la parte superior del cuerpo. \n Instrucciones:\n\n1. Comience en posición de plancha con las manos colocadas ligeramente más anchas que el ancho de los hombros, los pies juntos y el cuerpo en línea recta desde la cabeza hasta los talones.\n2. Contraiga el torso y baje el cuerpo flexionando los codos, manteniéndolos cerca del cuerpo o ligeramente separados.\n3. Baje hasta que el pecho casi toque el suelo, manteniendo la columna neutra.\n4. Empuje con las palmas de las manos para volver a la posición inicial, extendiendo completamente los brazos.","name":"Push-Up","created":"2025-07-07T13:25:14.685Z","last_update":"2026-04-13T18:58:27.104Z","language":4,"uuid":"d0ab9a62-399c-40d3-be8d-dc197f1dc266","exercise":1551}}],"aliases":[{"model":"exercises.alias","pk":592,"fields":{"uuid":"b8192eaf-35b1-4a10-b143-8852a694ab81","translation":2504,"alias":"Lagartijas"}},{"model":"exercises.alias","pk":593,"fields":{"uuid":"fecc5592-6bde-4df8-97a7-b161c0a2bc2b","translation":2504,"alias":"Flexiones"}}],"comments":[]}'),
('wger', '1554', 'clap-push-up', 'https://wger.de/en/exercise/1554/view', 'CC-BY-SA-4.0', 'Settebello', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1554,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Settebello","license_author_url":"","license_derivative_source_url":"","uuid":"fdeb0973-121f-494d-8b94-54f1d7ba003f","category":11,"variation_group":null,"created":"2025-07-07T12:50:16.366Z","last_update":"2025-07-07T12:50:16.366Z","muscles":[4],"muscles_secondary":[2,6,5],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2501,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Settebello","license_author_url":"","license_derivative_source_url":"","description":"<p>The clap push-up is an explosive upper body movement that builds power and fast-twitch muscle strength. It adds a plyometric challenge to the traditional push-up by requiring the hands to leave the ground mid-rep.</p>\n<ol>\n<li>Start in a strong push-up position with your hands slightly wider than shoulder-width and core engaged</li>\n<li>Lower your body explosively and push off the ground with enough force to lift your hands.</li>\n<li>Quickly clap your hands together at chest level before returning them to the floor.</li>\n<li>Land with soft elbows to absorb the impact and immediately move into the next rep</li>\n</ol>\n","description_source":"The clap push-up is an explosive upper body movement that builds power and fast-twitch muscle strength. It adds a plyometric challenge to the traditional push-up by requiring the hands to leave the ground mid-rep.\n\n1. Start in a strong push-up position with your hands slightly wider than shoulder-width and core engaged\n2. Lower your body explosively and push off the ground with enough force to lift your hands.\n3. Quickly clap your hands together at chest level before returning them to the floor.\n4. Land with soft elbows to absorb the impact and immediately move into the next rep","name":"Clap Push-UP","created":"2025-07-07T12:50:16.629Z","last_update":"2026-04-13T18:58:26.211Z","language":2,"uuid":"906e2287-dae0-4479-8951-3ab556aca03a","exercise":1554}}],"aliases":[],"comments":[]}'),
('wger', '1556', 'dumbbell-devils-press', 'https://wger.de/en/exercise/1556/view', 'CC-BY-SA-4.0', 'Settebello', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1556,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Settebello","license_author_url":"","license_derivative_source_url":"","uuid":"bb9b994e-426f-4693-9d16-3f8d5a9c72b8","category":13,"variation_group":null,"created":"2025-07-07T13:16:45.420Z","last_update":"2025-07-07T13:16:45.420Z","muscles":[2,8,4],"muscles_secondary":[11,12,14,5],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2503,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Settebello","license_author_url":"","license_derivative_source_url":"","description":"<p>The Devil’s Press is a hybrid movement combining a dumbbell burpee and a double dumbbell snatch. It’s a full-body, high-intensity exercise that develops strength, power, and metabolic conditioning.</p>\n<ol>\n<li>Start with a dumbbell in each hand and perform a burpee, letting your chest touch the ground while holding the dumbbells.</li>\n<li>Explosively jump your feet forward and swing the dumbbells between your legs.</li>\n<li>Drive the dumbbells overhead in one continuous motion, locking out your arms.</li>\n<li>Lower the dumbbells with control to return to the starting position and repeat</li>\n</ol>\n","description_source":"The Devil’s Press is a hybrid movement combining a dumbbell burpee and a double dumbbell snatch. It’s a full-body, high-intensity exercise that develops strength, power, and metabolic conditioning.\n\n1. Start with a dumbbell in each hand and perform a burpee, letting your chest touch the ground while holding the dumbbells.\n2. Explosively jump your feet forward and swing the dumbbells between your legs.\n3. Drive the dumbbells overhead in one continuous motion, locking out your arms.\n4. Lower the dumbbells with control to return to the starting position and repeat","name":"Devil’s Press","created":"2025-07-07T13:16:45.767Z","last_update":"2026-04-13T18:58:26.384Z","language":2,"uuid":"37aefa13-9591-4159-bd9e-a4845901d912","exercise":1556}}],"aliases":[],"comments":[]}'),
('wger', '1567', 'dumbbell-alternating-hammer-curl', 'https://wger.de/en/exercise/1567/view', 'CC-BY-SA-4.0', 'Mariano_O; admin', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1567,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Mariano_O","license_author_url":"","license_derivative_source_url":"","uuid":"eb9476ac-2c00-4f49-a40f-f81682161a75","category":8,"variation_group":"3081bbd4-bd49-47c5-9ab4-735962cd9fc3","created":"2025-07-08T00:50:42.572Z","last_update":"2025-10-28T05:19:38.981Z","muscles":[1],"muscles_secondary":[],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2515,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Mariano_O","license_author_url":"","license_derivative_source_url":"","description":"<p>Stand with your knees slightly bent and your back straight. Hold a dumbbell in each hand, using a neutral grip at your sides.</p>\n","description_source":"Stand with your knees slightly bent and your back straight. Hold a dumbbell in each hand, using a neutral grip at your sides.","name":"Alternating dumbbell hammer curl","created":"2025-07-08T00:50:42.938Z","last_update":"2026-04-13T18:58:26.026Z","language":2,"uuid":"abe05849-3dc4-427a-8e6f-3ab458e492d6","exercise":1567}},{"model":"exercises.translation","pk":2622,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"admin","license_author_url":"","license_derivative_source_url":"","description":"<p>Stehen Sie mit leicht gebeugten Knien und geradem Rücken. Halten Sie in jeder Hand eine Hantel und verwenden Sie einen neutralen Griff an Ihren Seiten.</p>\n","description_source":"Stehen Sie mit leicht gebeugten Knien und geradem Rücken. Halten Sie in jeder Hand eine Hantel und verwenden Sie einen neutralen Griff an Ihren Seiten.","name":"Hammercurl mit Kurzhanteln, abwechselnd","created":"2025-09-09T15:54:15.612Z","last_update":"2026-04-13T18:58:26.603Z","language":1,"uuid":"ea2c5caa-8dac-40c4-be7a-a4e8c69f7e5c","exercise":1567}},{"model":"exercises.translation","pk":2623,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"admin","license_author_url":"","license_derivative_source_url":"","description":"<p>De pie, con las rodillas ligeramente dobladas y la espalda recta. Sujeta una mancuerna en cada mano, en un agarre neutral a lo largo del cuerpo.</p>\n","description_source":"De pie, con las rodillas ligeramente dobladas y la espalda recta. Sujeta una mancuerna en cada mano, en un agarre neutral a lo largo del cuerpo.","name":"Curl alterno de martillo con mancuernas","created":"2025-09-09T15:54:33.361Z","last_update":"2026-04-13T18:58:26.267Z","language":4,"uuid":"ff222ac4-661e-496f-b4fc-d88c1edbdb7a","exercise":1567}}],"aliases":[],"comments":[]}'),
('wger', '1572', 'bird-dog', 'https://wger.de/en/exercise/1572/view', 'CC-BY-SA-4.0', 'Settebello', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1572,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Settebello","license_author_url":"","license_derivative_source_url":"","uuid":"6349365e-e901-4280-a1b7-65734986f47d","category":10,"variation_group":null,"created":"2025-07-09T19:04:29.327Z","last_update":"2025-07-09T19:04:29.327Z","muscles":[6],"muscles_secondary":[2,8],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2520,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Settebello","license_author_url":"","license_derivative_source_url":"","description":"<p>The Bird Dog is a core stability exercise that enhances balance, coordination, and spinal alignment. It’s a low-impact movement ideal for strengthening the posterior chain and improving overall functional control.</p>\n<ol>\n<li>Begin on all fours with hands under shoulders and knees under hips, keeping your spine neutral.</li>\n<li>Extend your right arm forward and left leg backward simultaneously, keeping hips square.</li>\n<li>Pause briefly at full extension while engaging your core and glutes.</li>\n<li>Return to the starting position and repeat on the opposite side</li>\n</ol>\n","description_source":"The Bird Dog is a core stability exercise that enhances balance, coordination, and spinal alignment. It’s a low-impact movement ideal for strengthening the posterior chain and improving overall functional control.\n\n1. Begin on all fours with hands under shoulders and knees under hips, keeping your spine neutral.\n2. Extend your right arm forward and left leg backward simultaneously, keeping hips square.\n3. Pause briefly at full extension while engaging your core and glutes.\n4. Return to the starting position and repeat on the opposite side","name":"Bird Dog","created":"2025-07-09T19:04:29.636Z","last_update":"2026-04-13T18:58:26.119Z","language":2,"uuid":"90e05e5e-c839-47d3-9a23-ed01ca86d2cd","exercise":1572}}],"aliases":[],"comments":[]}'),
('wger', '1573', 'ab-wheel', 'https://wger.de/en/exercise/1573/view', 'CC-BY-SA-4.0', 'lhegedus', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1573,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"lhegedus","license_author_url":"","license_derivative_source_url":"","uuid":"203a6fee-7436-4313-858f-c1e364136793","category":10,"variation_group":null,"created":"2025-07-11T09:47:04.659Z","last_update":"2025-07-11T09:47:04.659Z","muscles":[6],"muscles_secondary":[14,3],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2521,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"lhegedus","license_author_url":"","license_derivative_source_url":"","description":"<ol>\n<li><strong>Starting Position</strong>: Kneel on the floor with the ab wheel in front of you.</li>\n<li><strong>Grip the Wheel</strong>: Hold the handles firmly.</li>\n<li><strong>Roll Out</strong>: Slowly roll the wheel forward, extending your body while keeping your core tight.</li>\n<li><strong>Return</strong>: Pull the wheel back towards your knees, maintaining tension in your core.</li>\n</ol>\n","description_source":"1. **Starting Position**: Kneel on the floor with the ab wheel in front of you.\n2. **Grip the Wheel**: Hold the handles firmly.\n3. **Roll Out**: Slowly roll the wheel forward, extending your body while keeping your core tight.\n4. **Return**: Pull the wheel back towards your knees, maintaining tension in your core.","name":"Ab wheel","created":"2025-07-11T09:47:04.830Z","last_update":"2026-04-13T18:58:25.981Z","language":2,"uuid":"09871172-f43f-424a-b452-e52beca49b3b","exercise":1573}}],"aliases":[],"comments":[]}'),
('wger', '1574', NULL, 'https://wger.de/en/exercise/1574/view', 'CC-BY-SA-4.0', 'delta@romeo', NULL, NULL, '{"exercise":{"model":"exercises.exercise","pk":1574,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"delta@romeo","license_author_url":"","license_derivative_source_url":"","uuid":"f5252c85-04b7-48f0-97cf-711f326a5821","category":15,"variation_group":null,"created":"2025-07-13T10:17:25.874Z","last_update":"2025-07-13T10:17:25.874Z","muscles":[],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2522,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"delta@romeo","license_author_url":"","license_derivative_source_url":"","description":"<ul>\n<li>800m Schwimmen in 20 Minuten</li>\n</ul>\n","description_source":"* 800m Schwimmen in 20 Minuten","name":"Schwimmen","created":"2025-07-13T10:17:26.082Z","last_update":"2026-04-13T18:58:27.250Z","language":2,"uuid":"72f940d1-d98d-4709-9d1c-d1ea386be413","exercise":1574}}],"aliases":[],"comments":[]}'),
('wger', '1575', NULL, 'https://wger.de/en/exercise/1575/view', 'CC-BY-SA-4.0', 'mountain.potato', NULL, NULL, '{"exercise":{"model":"exercises.exercise","pk":1575,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"mountain.potato","license_author_url":"","license_derivative_source_url":"","uuid":"083bc8a6-0eb4-4049-b2ef-88415aa15459","category":13,"variation_group":null,"created":"2025-07-23T16:49:03.263Z","last_update":"2025-07-23T16:49:03.263Z","muscles":[],"muscles_secondary":[],"equipment":[1]}},"translations":[{"model":"exercises.translation","pk":2523,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"mountain.potato","license_author_url":"","license_derivative_source_url":"","description":"<p>Mobility - prone dowel press or standing dowel shoulder press alternating between front andback</p>\n","description_source":"Mobility - prone dowel press or standing dowel shoulder press alternating between front andback","name":"Standing Dowel Shoulder press","created":"2025-07-23T16:49:03.636Z","last_update":"2026-04-13T18:58:27.523Z","language":2,"uuid":"b51a3873-cb87-4679-8286-b2820a5cd2bb","exercise":1575}}],"aliases":[],"comments":[]}'),
('wger', '1576', 'snap-down', 'https://wger.de/en/exercise/1576/view', 'CC-BY-SA-4.0', 'mountain.potato', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1576,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"mountain.potato","license_author_url":"","license_derivative_source_url":"","uuid":"c8f951dd-94e0-4548-bbed-3b7bc883f7ba","category":9,"variation_group":null,"created":"2025-07-23T17:01:23.623Z","last_update":"2025-07-23T17:01:23.623Z","muscles":[11,8,10],"muscles_secondary":[7,6],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2524,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"mountain.potato","license_author_url":"","license_derivative_source_url":"","description":"<p>Begin in a standing position with your\narms up over your head and your toes pushing into the ground raising\nyour heels up becoming as tall as you can. From this position, perform a\nsmall hop with both feet slightly coming off of the ground. As you\nland, bend your knees and begin to hinge forward at your hips absorbing\nthe landing. Return to the starting position and repeat.&nbsp;\nYou should feel the muscles in your lower body working.&nbsp;\nStart with your arms and knees fully\nstraightened out. Keep a stable balance as you land and briefly hold\nthat end position, don’t go too fast and become off balanced. Keep your\nchest up.&nbsp;\nFor a detailed video on landing mechanics, click here: https://youtu.be/RThUCYRDyZw</p>\n","description_source":"Begin in a standing position with your\narms up over your head and your toes pushing into the ground raising\nyour heels up becoming as tall as you can. From this position, perform a\nsmall hop with both feet slightly coming off of the ground. As you\nland, bend your knees and begin to hinge forward at your hips absorbing\nthe landing. Return to the starting position and repeat. \nYou should feel the muscles in your lower body working. \nStart with your arms and knees fully\nstraightened out. Keep a stable balance as you land and briefly hold\nthat end position, don’t go too fast and become off balanced. Keep your\nchest up. \nFor a detailed video on landing mechanics, click here: https://youtu.be/RThUCYRDyZw","name":"Snap Down","created":"2025-07-23T17:01:24.054Z","last_update":"2026-04-13T18:58:27.438Z","language":2,"uuid":"89cf88d1-e578-427e-96ac-e068b397196c","exercise":1576}}],"aliases":[],"comments":[]}'),
('wger', '1577', 'bretzel-stretch', 'https://wger.de/en/exercise/1577/view', 'CC-BY-SA-4.0', 'mountain.potato', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1577,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"mountain.potato","license_author_url":"","license_derivative_source_url":"","uuid":"a94c635d-096c-45a8-a68c-64941d0b6ba4","category":12,"variation_group":null,"created":"2025-07-23T17:11:20.176Z","last_update":"2025-07-23T17:11:20.176Z","muscles":[8],"muscles_secondary":[11,12,4],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2525,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"mountain.potato","license_author_url":"","license_derivative_source_url":"","description":"<p>How to Perform the Bretzel Stretch&nbsp; &nbsp; Starting Position:&nbsp; &nbsp; &nbsp; &nbsp; Lie on your back on a flat surface, such as a mat.&nbsp; &nbsp; &nbsp; &nbsp; Bend your knees and place your feet flat on the ground.&nbsp; &nbsp; Leg Positioning:&nbsp; &nbsp; &nbsp; &nbsp; Lift your right leg and cross it over your left leg, placing your right foot on the outside of your left knee.&nbsp; &nbsp; &nbsp; &nbsp; Your left leg should remain flat on the ground.&nbsp; &nbsp; Arm Positioning:&nbsp; &nbsp; &nbsp; &nbsp; Extend your left arm out to the side at shoulder height, keeping it straight.&nbsp; &nbsp; &nbsp; &nbsp; Use your right hand to gently pull your right knee towards the floor on the left side of your body.&nbsp; &nbsp; Stretching:&nbsp; &nbsp; &nbsp; &nbsp; As you pull your knee down, try to keep your left shoulder flat on the ground.&nbsp; &nbsp; &nbsp; &nbsp; You should feel a stretch in your hip, lower back, and possibly your chest.&nbsp; &nbsp; Hold the Position:&nbsp; &nbsp; &nbsp; &nbsp; Maintain this position for 20-30 seconds, breathing deeply and relaxing into the stretch.&nbsp; &nbsp; &nbsp; &nbsp; Switch sides and repeat the process.</p>\n","description_source":"How to Perform the Bretzel Stretch    Starting Position:        Lie on your back on a flat surface, such as a mat.        Bend your knees and place your feet flat on the ground.    Leg Positioning:        Lift your right leg and cross it over your left leg, placing your right foot on the outside of your left knee.        Your left leg should remain flat on the ground.    Arm Positioning:        Extend your left arm out to the side at shoulder height, keeping it straight.        Use your right hand to gently pull your right knee towards the floor on the left side of your body.    Stretching:        As you pull your knee down, try to keep your left shoulder flat on the ground.        You should feel a stretch in your hip, lower back, and possibly your chest.    Hold the Position:        Maintain this position for 20-30 seconds, breathing deeply and relaxing into the stretch.        Switch sides and repeat the process.","name":"Bretzel stretch","created":"2025-07-23T17:11:20.528Z","last_update":"2026-04-13T18:58:26.137Z","language":2,"uuid":"1f0ae821-1987-47fb-b640-a78a78226ae9","exercise":1577}}],"aliases":[],"comments":[]}'),
('wger', '1578', 'barbell-hip-hinge', 'https://wger.de/en/exercise/1578/view', 'CC-BY-SA-4.0', 'mountain.potato', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1578,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"mountain.potato","license_author_url":"","license_derivative_source_url":"","uuid":"e4c9bfde-cf06-4c24-9c56-c0bbc13c49b5","category":9,"variation_group":null,"created":"2025-07-23T17:21:22.641Z","last_update":"2025-07-23T17:21:22.641Z","muscles":[11,8],"muscles_secondary":[7,10,6],"equipment":[1]}},"translations":[{"model":"exercises.translation","pk":2526,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"mountain.potato","license_author_url":"","license_derivative_source_url":"","description":"<p>Hip Hinge Exercise DescriptionThe hip hinge is a fundamental movement pattern that involves bending at the hips while keeping the spine neutral. It is commonly used in exercises like deadlifts, kettlebell swings, and good mornings. To perform a hip hinge:&nbsp; &nbsp; Starting Position: Stand with your feet hip-width apart and a slight bend in your knees.&nbsp; &nbsp; Hinge at the Hips: Push your hips back while maintaining a straight back. Your torso should lean forward, and your chest should stay up.&nbsp; &nbsp; Lowering Phase: Continue to hinge until your torso is nearly parallel to the ground, or until you feel a stretch in your hamstrings.&nbsp; &nbsp; Return to Standing: Drive through your heels and thrust your hips forward to return to the starting position.</p>\n","description_source":"Hip Hinge Exercise DescriptionThe hip hinge is a fundamental movement pattern that involves bending at the hips while keeping the spine neutral. It is commonly used in exercises like deadlifts, kettlebell swings, and good mornings. To perform a hip hinge:    Starting Position: Stand with your feet hip-width apart and a slight bend in your knees.    Hinge at the Hips: Push your hips back while maintaining a straight back. Your torso should lean forward, and your chest should stay up.    Lowering Phase: Continue to hinge until your torso is nearly parallel to the ground, or until you feel a stretch in your hamstrings.    Return to Standing: Drive through your heels and thrust your hips forward to return to the starting position.","name":"Hip hinge","created":"2025-07-23T17:21:23.033Z","last_update":"2026-04-13T18:58:26.636Z","language":2,"uuid":"c6cfe6a7-4a1c-4a7f-96a5-8a32b6b5e771","exercise":1578}}],"aliases":[],"comments":[]}'),
('wger', '1579', NULL, 'https://wger.de/en/exercise/1579/view', 'CC-BY-SA-4.0', 'MU5H', NULL, NULL, '{"exercise":{"model":"exercises.exercise","pk":1579,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"MU5H","license_author_url":"","license_derivative_source_url":"","uuid":"a6d880e5-bdbe-408f-b762-3b41c7fff834","category":15,"variation_group":null,"created":"2025-07-26T05:20:18.477Z","last_update":"2025-07-26T05:20:18.477Z","muscles":[],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2527,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"MU5H","license_author_url":"","license_derivative_source_url":"","description":"<p>Finess test for rugby.5 x shuttle runs of 20m, 40m, and 60m (20yd, 45yd, 65yd/far 45yd mark)\nComplete as fast as possible</p>\n","description_source":"Finess test for rugby.5 x shuttle runs of 20m, 40m, and 60m (20yd, 45yd, 65yd/far 45yd mark)\nComplete as fast as possible","name":"Bronco","created":"2025-07-26T05:20:18.787Z","last_update":"2026-04-13T18:58:26.138Z","language":2,"uuid":"38d88b1a-1704-4483-836c-5dd501459443","exercise":1579}}],"aliases":[],"comments":[]}'),
('wger', '1580', 'barbell-perpendicular-unilateral-landmine-row', 'https://wger.de/en/exercise/1580/view', 'CC-BY-SA-4.0', 'CptnFatbeard', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1580,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"CptnFatbeard","license_author_url":"","license_derivative_source_url":"","uuid":"7ae1aca7-cdd4-4a81-b22c-f31778462b6b","category":13,"variation_group":null,"created":"2025-07-29T13:55:06.572Z","last_update":"2025-07-29T13:55:06.572Z","muscles":[2,9],"muscles_secondary":[],"equipment":[1]}},"translations":[{"model":"exercises.translation","pk":2528,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"CptnFatbeard","license_author_url":"","license_derivative_source_url":"","description":"<p>Using a landmine attachment with the barbell running at 90 degrees to either side, hinge slightly at the hips and grip the barbell by the plate sleeve. Raise the barbell to chest height, with your upper arm parallel to the floor at the top of the movement.</p>\n","description_source":"Using a landmine attachment with the barbell running at 90 degrees to either side, hinge slightly at the hips and grip the barbell by the plate sleeve. Raise the barbell to chest height, with your upper arm parallel to the floor at the top of the movement. ","name":"Perpendicular Unilateral Landmine Row","created":"2025-07-29T13:55:06.767Z","last_update":"2026-04-13T18:58:26.925Z","language":2,"uuid":"672352dd-77c6-4d5a-86bd-1beb27e24ac2","exercise":1580}}],"aliases":[],"comments":[]}'),
('wger', '1581', 'trap-press', 'https://wger.de/en/exercise/1581/view', 'CC-BY-SA-4.0', 'CptnFatbeard', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1581,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"CptnFatbeard","license_author_url":"","license_derivative_source_url":"","uuid":"41b9f5a5-73de-414d-b08a-54025eccedc6","category":13,"variation_group":null,"created":"2025-07-29T14:58:13.128Z","last_update":"2025-07-29T14:58:13.128Z","muscles":[9],"muscles_secondary":[],"equipment":[1,8,3]}},"translations":[{"model":"exercises.translation","pk":2529,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"CptnFatbeard","license_author_url":"","license_derivative_source_url":"","description":"<p>Laying flat with arm pointing straight upwards, elbow fully extended, use only your shoulder to raise the weight as high as comfortable and back to rest.</p>\n","description_source":"Laying flat with arm pointing straight upwards, elbow fully extended, use only your shoulder to raise the weight as high as comfortable and back to rest.","name":"Trap press","created":"2025-07-29T14:58:13.337Z","last_update":"2026-04-13T18:58:27.676Z","language":2,"uuid":"edcd46ab-28d4-4507-959c-be884786e1c9","exercise":1581}}],"aliases":[],"comments":[]}'),
('wger', '1582', 'side-laying-interior-rotation', 'https://wger.de/en/exercise/1582/view', 'CC-BY-SA-4.0', 'CptnFatbeard', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1582,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"CptnFatbeard","license_author_url":"","license_derivative_source_url":"","uuid":"d9c1f78c-7bf6-4e6a-92e4-7bf4ed4a0a67","category":13,"variation_group":null,"created":"2025-07-29T15:11:49.023Z","last_update":"2025-07-29T15:11:49.023Z","muscles":[9],"muscles_secondary":[],"equipment":[1,8,3]}},"translations":[{"model":"exercises.translation","pk":2530,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"CptnFatbeard","license_author_url":"","license_derivative_source_url":"","description":"<p>Laying on your side and using the arm closest to the bench, maintain a 90 degree bend at the elbow and allow the weight to fall towards the ground past the bench as low as comfortable. Bring the weight up using only rotation of the shoulder to the opposing shoulder.</p>\n","description_source":"Laying on your side and using the arm closest to the bench, maintain a 90 degree bend at the elbow and allow the weight to fall towards the ground past the bench as low as comfortable. Bring the weight up using only rotation of the shoulder to the opposing shoulder. ","name":"Side-laying interior rotation","created":"2025-07-29T15:11:49.199Z","last_update":"2026-04-13T18:58:27.390Z","language":2,"uuid":"6008786a-ac24-4337-9de9-6d5bf0f0f98b","exercise":1582}}],"aliases":[],"comments":[]}'),
('wger', '1583', 'barbell-supine-press', 'https://wger.de/en/exercise/1583/view', 'CC-BY-SA-4.0', 'CptnFatbeard', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1583,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"CptnFatbeard","license_author_url":"","license_derivative_source_url":"","uuid":"2c31daac-17b1-4cc9-b1c1-f34266ee2038","category":12,"variation_group":null,"created":"2025-07-29T15:23:03.652Z","last_update":"2025-07-29T15:23:03.652Z","muscles":[9],"muscles_secondary":[],"equipment":[1,8]}},"translations":[{"model":"exercises.translation","pk":2531,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"CptnFatbeard","license_author_url":"","license_derivative_source_url":"","description":"<p>Take a close grip and push perpendicular to the bench. Keep back flat.</p>\n","description_source":"Take a close grip and push perpendicular to the bench. Keep back flat.","name":"Supine press","created":"2025-07-29T15:23:03.785Z","last_update":"2026-04-13T18:58:27.582Z","language":2,"uuid":"3ab6b105-10df-4f66-9325-417409d3bf85","exercise":1583}}],"aliases":[],"comments":[]}'),
('wger', '1584', 'march-or-jog-in-place', 'https://wger.de/en/exercise/1584/view', 'CC-BY-SA-4.0', 'MrAlfaRobot', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1584,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"MrAlfaRobot","license_author_url":"","license_derivative_source_url":"","uuid":"564dc73e-e8d4-4fd1-85ab-64dce4dd3ea0","category":15,"variation_group":null,"created":"2025-07-30T22:38:50.267Z","last_update":"2025-07-30T22:38:50.267Z","muscles":[11,7,8,10],"muscles_secondary":[2,1,14,6,5],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2532,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"MrAlfaRobot","license_author_url":"","license_derivative_source_url":"","description":"<p>Low-impact cardiovascular exercise that simulates running without moving, ideal for warming up, improving endurance, or training in small spaces.</p>\n","description_source":"Low-impact cardiovascular exercise that simulates running without moving, ideal for warming up, improving endurance, or training in small spaces.","name":"March or jog in place","created":"2025-07-30T22:38:50.625Z","last_update":"2026-04-13T18:58:26.837Z","language":2,"uuid":"d7a6a419-0c7e-4580-9d8d-f285d748a372","exercise":1584}},{"model":"exercises.translation","pk":2627,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"admin","license_author_url":"","license_derivative_source_url":"","description":"<p>Ejercicio cardiovascular de bajo impacto que simula correr sin desplazamiento, ideal para calentar, mejorar la resistencia o entrenar en espacios reducidos.</p>\n","description_source":"Ejercicio cardiovascular de bajo impacto que simula correr sin desplazamiento, ideal para calentar, mejorar la resistencia o entrenar en espacios reducidos.","name":"Marcha o trote en el lugar","created":"2025-09-09T16:02:45.539Z","last_update":"2026-04-13T18:58:26.838Z","language":4,"uuid":"60be035b-4b59-42fe-8afa-ca70250d23c9","exercise":1584}}],"aliases":[],"comments":[]}'),
('wger', '1589', 'estiramiento-de-piernas-y-cadera', 'https://wger.de/en/exercise/1589/view', 'CC-BY-SA-4.0', 'MrAlfaRobot', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1589,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"MrAlfaRobot","license_author_url":"","license_derivative_source_url":"","uuid":"505d6a28-1e24-4349-ab2b-49af3300e08e","category":9,"variation_group":null,"created":"2025-08-01T21:27:46.824Z","last_update":"2025-08-01T21:27:46.824Z","muscles":[11,8,10],"muscles_secondary":[12],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2538,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"MrAlfaRobot","license_author_url":"","license_derivative_source_url":"","description":"<p>Movimientos suaves para mejorar la flexibilidad de la parte inferior del cuerpo y liberar tensión en la cadera.</p>\n","description_source":"Movimientos suaves para mejorar la flexibilidad de la parte inferior del cuerpo y liberar tensión en la cadera.","name":"Estiramiento de piernas y cadera","created":"2025-08-01T21:27:47.131Z","last_update":"2026-04-13T18:58:26.500Z","language":2,"uuid":"d2c197f4-fe14-4737-b597-4f6d6714f140","exercise":1589}}],"aliases":[],"comments":[]}'),
('wger', '1590', 'estiramiento-de-brazos-y-cuello', 'https://wger.de/en/exercise/1590/view', 'CC-BY-SA-4.0', 'MrAlfaRobot', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1590,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"MrAlfaRobot","license_author_url":"","license_derivative_source_url":"","uuid":"b48cd640-dd9f-4557-a4db-8cd33d5655a6","category":10,"variation_group":null,"created":"2025-08-01T21:31:14.032Z","last_update":"2025-08-01T21:31:14.032Z","muscles":[2,9,5],"muscles_secondary":[12,3],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2539,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"MrAlfaRobot","license_author_url":"","license_derivative_source_url":"","description":"<p>Alivia tensiones en la parte superior del cuerpo, especialmente útil para personas con trabajo de oficina o posturas prolongadas.</p>\n","description_source":"Alivia tensiones en la parte superior del cuerpo, especialmente útil para personas con trabajo de oficina o posturas prolongadas.","name":"Estiramiento de brazos y cuello","created":"2025-08-01T21:31:14.401Z","last_update":"2026-04-13T18:58:26.500Z","language":2,"uuid":"4ef3243d-2918-48fd-9434-966472b590f1","exercise":1590}}],"aliases":[],"comments":[]}'),
('wger', '1591', 'respiracion-profunda-de-pie-o-sentado', 'https://wger.de/en/exercise/1591/view', 'CC-BY-SA-4.0', 'MrAlfaRobot', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1591,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"MrAlfaRobot","license_author_url":"","license_derivative_source_url":"","uuid":"fae44c34-2e85-4d22-8fb8-7b14faf14719","category":11,"variation_group":null,"created":"2025-08-01T21:34:09.071Z","last_update":"2025-08-01T21:34:09.071Z","muscles":[14,6],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2540,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"MrAlfaRobot","license_author_url":"","license_derivative_source_url":"","description":"<p>Técnica de respiración consciente para mejorar oxigenación, reducir el estrés y conectar con el momento presente.</p>\n","description_source":"Técnica de respiración consciente para mejorar oxigenación, reducir el estrés y conectar con el momento presente.","name":"Respiración profunda (de pie o sentado)","created":"2025-08-01T21:34:09.403Z","last_update":"2026-04-13T18:58:27.145Z","language":2,"uuid":"80527846-cfc0-4e4d-9338-b7ff3de165ea","exercise":1591}}],"aliases":[],"comments":[]}'),
('wger', '1592', NULL, 'https://wger.de/en/exercise/1592/view', 'CC-BY-SA-4.0', 'MrAlfaRobot', NULL, NULL, '{"exercise":{"model":"exercises.exercise","pk":1592,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"MrAlfaRobot","license_author_url":"","license_derivative_source_url":"","uuid":"7f942691-2a01-4675-9e3a-409105d5f2bf","category":15,"variation_group":null,"created":"2025-08-01T21:36:19.425Z","last_update":"2025-08-01T21:36:19.425Z","muscles":[],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2541,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"MrAlfaRobot","license_author_url":"","license_derivative_source_url":"","description":"<p>Ejercicio mental de atención plena (mindfulness) que ayuda a reducir ansiedad, mejorar el enfoque y el bienestar general.</p>\n","description_source":"Ejercicio mental de atención plena (mindfulness) que ayuda a reducir ansiedad, mejorar el enfoque y el bienestar general.","name":"Meditación guiada o libre","created":"2025-08-01T21:36:19.748Z","last_update":"2026-04-13T18:58:26.845Z","language":2,"uuid":"c101f72c-85f1-41de-bd0e-306a8931fd6f","exercise":1592}}],"aliases":[],"comments":[]}'),
('wger', '1593', 'smith-machine-split-squat', 'https://wger.de/en/exercise/1593/view', 'CC-BY-SA-4.0', 'workout@rooven.anonaddy.me', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1593,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"workout@rooven.anonaddy.me","license_author_url":"","license_derivative_source_url":"","uuid":"b382dcb2-60a8-412d-b0ee-6afe9c9f36d7","category":9,"variation_group":null,"created":"2025-08-05T06:21:43.757Z","last_update":"2025-08-05T06:21:43.757Z","muscles":[11,10],"muscles_secondary":[],"equipment":[1]}},"translations":[{"model":"exercises.translation","pk":2542,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"workout@rooven.anonaddy.me","license_author_url":"","license_derivative_source_url":"","description":"<p>The <strong>\"Smith Machine Split Squat\"</strong> is a strength exercise\nperformed on the Smith machine, ideal for targeting the legs and glutes.\nIt involves placing one foot forward and the other back, lowering the\nbody until the front thigh is parallel to the ground while the bar\nslides vertically along the machine. This exercise helps improve\nstability, correct muscle imbalances, and reduces stress on the back,\nproviding a safe environment for strength training.</p>\n","description_source":"The **\"Smith Machine Split Squat\"** is a strength exercise\nperformed on the Smith machine, ideal for targeting the legs and glutes.\nIt involves placing one foot forward and the other back, lowering the\nbody until the front thigh is parallel to the ground while the bar\nslides vertically along the machine. This exercise helps improve\nstability, correct muscle imbalances, and reduces stress on the back,\nproviding a safe environment for strength training.","name":"Smith Machine Split Squat","created":"2025-08-05T06:21:44.174Z","last_update":"2026-04-13T18:58:27.434Z","language":2,"uuid":"2f4ebd76-e4ac-44ae-9544-1044562d4164","exercise":1593}}],"aliases":[],"comments":[]}'),
('wger', '1594', 'smith-machine-split-squat', 'https://wger.de/en/exercise/1594/view', 'CC-BY-SA-4.0', 'workout@rooven.anonaddy.me', 'exact', 100.0, '{"exercise":{"model":"exercises.exercise","pk":1594,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"workout@rooven.anonaddy.me","license_author_url":"","license_derivative_source_url":"","uuid":"e8f937c9-da7f-47ff-bd14-75cc27956b4a","category":9,"variation_group":null,"created":"2025-08-05T06:22:23.216Z","last_update":"2025-08-05T06:22:23.216Z","muscles":[11,10],"muscles_secondary":[],"equipment":[1]}},"translations":[{"model":"exercises.translation","pk":2543,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"workout@rooven.anonaddy.me","license_author_url":"","license_derivative_source_url":"","description":"<p>The <strong>\"Smith Machine Split Squat\"</strong> is a strength exercise\nperformed on the Smith machine, ideal for targeting the legs and glutes.\nIt involves placing one foot forward and the other back, lowering the\nbody until the front thigh is parallel to the ground while the bar\nslides vertically along the machine. This exercise helps improve\nstability, correct muscle imbalances, and reduces stress on the back,\nproviding a safe environment for strength training.</p>\n","description_source":"The **\"Smith Machine Split Squat\"** is a strength exercise\nperformed on the Smith machine, ideal for targeting the legs and glutes.\nIt involves placing one foot forward and the other back, lowering the\nbody until the front thigh is parallel to the ground while the bar\nslides vertically along the machine. This exercise helps improve\nstability, correct muscle imbalances, and reduces stress on the back,\nproviding a safe environment for strength training.","name":"Smith Machine Split Squat","created":"2025-08-05T06:22:23.574Z","last_update":"2026-04-13T18:58:27.434Z","language":2,"uuid":"22d4bb1e-736f-436c-a33b-b9abfe2e0798","exercise":1594}}],"aliases":[],"comments":[]}'),
('wger', '1602', 'dumbbell-scaption', 'https://wger.de/en/exercise/1602/view', 'CC-BY-SA-4.0', 'zdelko', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1602,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"zdelko","license_author_url":"","license_derivative_source_url":"","uuid":"d420baf8-977b-499e-8f91-416374227b91","category":13,"variation_group":null,"created":"2025-08-18T09:50:30.160Z","last_update":"2025-08-18T09:50:30.160Z","muscles":[9],"muscles_secondary":[2],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2571,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"zdelko","license_author_url":"","license_derivative_source_url":"","description":"<p>Starting position:</p>\n<p>Stand upright with your feet shoulder-width apart.</p>\n<p>Hold a dumbbell in each hand with a neutral grip (palms facing each other).</p>\n<p>Keep a slight bend in your elbows, shoulders relaxed and shoulder blades pulled back.</p>\n<p>Execution:</p>\n<p>Slowly raise the dumbbells forward and slightly to the side, at about a 30–45° angle from your body (between a front raise and a lateral raise).</p>\n<p>Lift until your arms are about shoulder height (do not go overhead).</p>\n<p>Pause for a second at the top and feel the activation in your shoulders and scapular stabilizers.</p>\n<p>Lower the dumbbells back down under control to the starting position.</p>\n<p>Breathing:</p>\n<p>Inhale as you lower the dumbbells.</p>\n<p>Exhale as you lift them.</p>\n<p>Common mistakes:</p>\n<p>Using dumbbells that are too heavy (causing jerky movements).</p>\n<p>Lifting above shoulder height (puts unnecessary stress on the shoulder joint).</p>\n<p>Arching the lower back instead of keeping the movement controlled at the shoulders.</p>\n<p>Purpose of the exercise:</p>\n<p>Activates the lower trapezius, serratus anterior, and scapular stabilizers.</p>\n<p>Helps correct posture and improve shoulder balance.</p>\n","description_source":"Starting position:\n\nStand upright with your feet shoulder-width apart.\n\nHold a dumbbell in each hand with a neutral grip (palms facing each other).\n\nKeep a slight bend in your elbows, shoulders relaxed and shoulder blades pulled back.\n\nExecution:\n\nSlowly raise the dumbbells forward and slightly to the side, at about a 30–45° angle from your body (between a front raise and a lateral raise).\n\nLift until your arms are about shoulder height (do not go overhead).\n\nPause for a second at the top and feel the activation in your shoulders and scapular stabilizers.\n\nLower the dumbbells back down under control to the starting position.\n\nBreathing:\n\nInhale as you lower the dumbbells.\n\nExhale as you lift them.\n\nCommon mistakes:\n\nUsing dumbbells that are too heavy (causing jerky movements).\n\nLifting above shoulder height (puts unnecessary stress on the shoulder joint).\n\nArching the lower back instead of keeping the movement controlled at the shoulders.\n\nPurpose of the exercise:\n\nActivates the lower trapezius, serratus anterior, and scapular stabilizers.\n\nHelps correct posture and improve shoulder balance.","name":"Dumbbell Scaption","created":"2025-08-18T09:50:30.329Z","last_update":"2026-04-13T18:58:26.432Z","language":2,"uuid":"8e028835-53e7-4037-9831-218bff514058","exercise":1602}},{"model":"exercises.translation","pk":2572,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"zdelko","license_author_url":"","license_derivative_source_url":"","description":"<p>Početni položaj:</p>\n<p>Stani uspravno, stopala u širini kukova.</p>\n<p>U svakoj ruci drži po bučicu neutralnim hvatom (dlanovi okrenuti jedan prema drugome).</p>\n<p>Ruke lagano savijene u laktovima, ramena spuštena i zategnuta lopatice.</p>\n<p>Izvođenje pokreta:</p>\n<p>Polako podiži bučice prema naprijed i u stranu, pod kutom od oko 30–45° od tijela (između prednjeg i bočnog podizanja).</p>\n<p>Podiži sve dok ruke ne dođu u visinu ramena (ne iznad glave).</p>\n<p>Zadrži sekundu na vrhu i osjeti aktivaciju mišića ramena i lopatica.</p>\n<p>Kontrolirano spuštaj bučice nazad u početni položaj.</p>\n<p>Disanje:</p>\n<p>Udah dok spuštaš bučice.</p>\n<p>Izdisaj dok podižeš.</p>\n<p>Najčešće greške:</p>\n<p>Dizanje preteških bučica (loša kontrola, trzanje).</p>\n<p>Podizanje iznad visine ramena (povećava rizik od prenaprezanja).</p>\n<p>„Slomljena“ forma – podizanje iz donjeg dijela leđa umjesto iz ramena.</p>\n<p>Cilj vježbe:</p>\n<p>Aktivira donji trapez, serratus anterior i stabilizatore lopatice.</p>\n<p>Pomaže u ispravljanju držanja i balansiranju ramena.</p>\n","description_source":"Početni položaj:\n\nStani uspravno, stopala u širini kukova.\n\nU svakoj ruci drži po bučicu neutralnim hvatom (dlanovi okrenuti jedan prema drugome).\n\nRuke lagano savijene u laktovima, ramena spuštena i zategnuta lopatice.\n\nIzvođenje pokreta:\n\nPolako podiži bučice prema naprijed i u stranu, pod kutom od oko 30–45° od tijela (između prednjeg i bočnog podizanja).\n\nPodiži sve dok ruke ne dođu u visinu ramena (ne iznad glave).\n\nZadrži sekundu na vrhu i osjeti aktivaciju mišića ramena i lopatica.\n\nKontrolirano spuštaj bučice nazad u početni položaj.\n\nDisanje:\n\nUdah dok spuštaš bučice.\n\nIzdisaj dok podižeš.\n\nNajčešće greške:\n\nDizanje preteških bučica (loša kontrola, trzanje).\n\nPodizanje iznad visine ramena (povećava rizik od prenaprezanja).\n\n„Slomljena“ forma – podizanje iz donjeg dijela leđa umjesto iz ramena.\n\nCilj vježbe:\n\nAktivira donji trapez, serratus anterior i stabilizatore lopatice.\n\nPomaže u ispravljanju držanja i balansiranju ramena.","name":"Dumbbell Scaption","created":"2025-08-18T09:50:30.439Z","last_update":"2026-04-13T18:58:26.434Z","language":22,"uuid":"4e3ad8c0-26ce-452a-8d4f-5059dd55192e","exercise":1602}}],"aliases":[],"comments":[]}'),
('wger', '1603', 'band-leg-curl-elastic', 'https://wger.de/en/exercise/1603/view', 'CC-BY-SA-4.0', 'clafal', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1603,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"clafal","license_author_url":"","license_derivative_source_url":"","uuid":"ca514fad-c6ce-47b0-93a0-dc73a3507099","category":14,"variation_group":null,"created":"2025-08-18T20:57:37.407Z","last_update":"2025-08-18T20:57:37.407Z","muscles":[7],"muscles_secondary":[11],"equipment":[11]}},"translations":[{"model":"exercises.translation","pk":2574,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"clafal","license_author_url":"","license_derivative_source_url":"","description":"<p>Standing position: Place the band under your feet in the middle of your foot and grasp it with a hammer grip.</p>\n","description_source":"Standing position: Place the band under your feet in the middle of your foot and grasp it with a hammer grip.","name":"Leg curl with elastic","created":"2025-08-18T20:57:37.686Z","last_update":"2026-04-13T18:58:26.785Z","language":2,"uuid":"f7f80c25-eed2-4ed1-93f8-b5705d84117d","exercise":1603}},{"model":"exercises.translation","pk":2575,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"clafal","license_author_url":"","license_derivative_source_url":"","description":"<p>In posizione eretta: posiziona l''elastico sotto i piedi a centro piede e afferralo con presa a martello.</p>\n","description_source":"In posizione eretta: posiziona l''elastico sotto i piedi a centro piede e afferralo con presa a martello.","name":"Leg curl con elastico","created":"2025-08-18T20:57:37.826Z","last_update":"2026-04-13T18:58:26.784Z","language":13,"uuid":"de93288c-7f18-4229-997b-7ce0591122b6","exercise":1603}}],"aliases":[],"comments":[]}'),
('wger', '1604', 'barbell-sliding-lateral-lunge', 'https://wger.de/en/exercise/1604/view', 'CC-BY-SA-4.0', 'RiccaBaro', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1604,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"RiccaBaro","license_author_url":"","license_derivative_source_url":"","uuid":"55bb8725-a7c9-48a0-b192-ec6c9db6f9bc","category":9,"variation_group":null,"created":"2025-08-19T08:10:13.345Z","last_update":"2025-08-19T08:10:13.345Z","muscles":[11,8,10],"muscles_secondary":[7,14],"equipment":[1]}},"translations":[{"model":"exercises.translation","pk":2576,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"RiccaBaro","license_author_url":"","license_derivative_source_url":"","description":"<p>Stand upright with your feet hip-width apart, holding a kettlebell close to your chest in goblet position. Place one foot on a slider, gliding disc, or towel. Keep your chest tall and core engaged. Slowly slide the foot outward to the side while bending the opposite knee, lowering your hips into a lateral lunge. Keep the working leg’s knee aligned with the toes and avoid letting it collapse inward. The non-working leg remains straight and slides smoothly along the floor. Push through the heel of the bent leg to return to the starting position while maintaining control of the kettlebell.</p>\n","description_source":"Stand upright with your feet hip-width apart, holding a kettlebell close to your chest in goblet position. Place one foot on a slider, gliding disc, or towel. Keep your chest tall and core engaged. Slowly slide the foot outward to the side while bending the opposite knee, lowering your hips into a lateral lunge. Keep the working leg’s knee aligned with the toes and avoid letting it collapse inward. The non-working leg remains straight and slides smoothly along the floor. Push through the heel of the bent leg to return to the starting position while maintaining control of the kettlebell.","name":"Sliding Lateral Lunge","created":"2025-08-19T08:10:13.562Z","last_update":"2026-04-13T18:58:27.431Z","language":2,"uuid":"658c8974-0bcb-41d1-b939-9dabf4140f01","exercise":1604}},{"model":"exercises.translation","pk":2577,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"RiccaBaro","license_author_url":"","license_derivative_source_url":"","description":"<p>n piedi, piedi alla larghezza delle anche, tieni un kettlebell vicino al petto in posizione goblet. Posiziona un piede su una pattina/disco scorrevole. Mantieni il busto eretto e il core attivo. Fai scivolare lentamente il piede verso l’esterno piegando il ginocchio della gamba opposta, abbassando i fianchi in un affondo laterale. Mantieni il ginocchio della gamba di lavoro allineato con le dita del piede, evitando che collassi verso l’interno. La gamba non in appoggio resta distesa e scivola fluidamente sul pavimento. Spingi con il tallone della gamba piegata per tornare alla posizione iniziale, mantenendo il controllo del kettlebell.</p>\n","description_source":"n piedi, piedi alla larghezza delle anche, tieni un kettlebell vicino al petto in posizione goblet. Posiziona un piede su una pattina/disco scorrevole. Mantieni il busto eretto e il core attivo. Fai scivolare lentamente il piede verso l’esterno piegando il ginocchio della gamba opposta, abbassando i fianchi in un affondo laterale. Mantieni il ginocchio della gamba di lavoro allineato con le dita del piede, evitando che collassi verso l’interno. La gamba non in appoggio resta distesa e scivola fluidamente sul pavimento. Spingi con il tallone della gamba piegata per tornare alla posizione iniziale, mantenendo il controllo del kettlebell.","name":"Affondo laterale con pattina","created":"2025-08-19T08:10:14.566Z","last_update":"2026-04-13T18:58:26.013Z","language":13,"uuid":"183fe2b6-b535-4d3d-bfcc-69d233e15899","exercise":1604}}],"aliases":[],"comments":[]}'),
('wger', '1605', 'copenhagen-adduction-exercise', 'https://wger.de/en/exercise/1605/view', 'CC-BY-SA-4.0', 'RiccaBaro', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1605,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"RiccaBaro","license_author_url":"","license_derivative_source_url":"","uuid":"dbed4613-e1d5-483f-90ae-6db5d593911e","category":9,"variation_group":null,"created":"2025-08-19T08:26:33.071Z","last_update":"2025-08-19T08:26:33.071Z","muscles":[8,10],"muscles_secondary":[14,3,9],"equipment":[8]}},"translations":[{"model":"exercises.translation","pk":2578,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"RiccaBaro","license_author_url":"","license_derivative_source_url":"","description":"<p>Lie on your side with the elbow placed directly under the shoulder, similar to a side plank position. Place the upper leg on a bench with the inside of the foot or ankle resting on it. Lift your hips and hold your body in a straight line while keeping the lower leg off the floor. The exercise strongly activates the adductors of the upper leg while also challenging the core and hip stabilizers.</p>\n","description_source":"Lie on your side with the elbow placed directly under the shoulder, similar to a side plank position. Place the upper leg on a bench with the inside of the foot or ankle resting on it. Lift your hips and hold your body in a straight line while keeping the lower leg off the floor. The exercise strongly activates the adductors of the upper leg while also challenging the core and hip stabilizers.","name":"Copenhagen Adduction Exercise","created":"2025-08-19T08:26:33.277Z","last_update":"2026-04-13T18:58:26.224Z","language":2,"uuid":"cea92455-41cc-4d3e-a79c-6da22367ccc6","exercise":1605}},{"model":"exercises.translation","pk":2579,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"RiccaBaro","license_author_url":"","license_derivative_source_url":"","description":"<p>Sdraiati su un fianco con il gomito appoggiato sotto la spalla, in posizione simile a una plank laterale. Appoggia la gamba superiore su una panca con il lato interno del piede o della caviglia. Solleva i fianchi e mantieni il corpo in linea retta tenendo la gamba inferiore sollevata da terra. L’esercizio attiva intensamente gli adduttori della gamba in appoggio e coinvolge anche il core e i muscoli stabilizzatori dell’anca.</p>\n","description_source":"Sdraiati su un fianco con il gomito appoggiato sotto la spalla, in posizione simile a una plank laterale. Appoggia la gamba superiore su una panca con il lato interno del piede o della caviglia. Solleva i fianchi e mantieni il corpo in linea retta tenendo la gamba inferiore sollevata da terra. L’esercizio attiva intensamente gli adduttori della gamba in appoggio e coinvolge anche il core e i muscoli stabilizzatori dell’anca.","name":"Copenhagen Plank","created":"2025-08-19T08:26:33.409Z","last_update":"2026-04-13T18:58:26.225Z","language":13,"uuid":"8fdae9b3-89a5-49fc-bdc5-c807da031d0a","exercise":1605}}],"aliases":[],"comments":[]}'),
('wger', '1606', 'arm-raise-t-y-i', 'https://wger.de/en/exercise/1606/view', 'CC-BY-SA-4.0', 'WiNNiE', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1606,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"WiNNiE","license_author_url":"","license_derivative_source_url":"","uuid":"e62d52fa-32f9-4747-9005-f88f05dc8334","category":8,"variation_group":null,"created":"2025-08-20T08:26:20.098Z","last_update":"2025-08-20T08:26:20.098Z","muscles":[2,12,3,9],"muscles_secondary":[14],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2580,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"WiNNiE","license_author_url":"","license_derivative_source_url":"","description":"<p>Stand upright with feet hip-width apart, core engaged, and arms relaxed at your sides. From this position, perform three different arm raises to target the shoulders and upper back:</p>\n<ul>\n<li><strong>T Raise:</strong> Lift your arms straight out to the sides until they are parallel to the floor, forming a “T” shape.</li>\n<li><strong>Y Raise:</strong> Lift your arms upward at about a 45° angle from your body to form a “Y” shape.</li>\n<li><strong>I Raise:</strong> Raise your arms straight overhead, close together, forming an “I” shape.</li>\n</ul>\n<p>Maintain a neutral spine, avoid arching your lower back, and move slowly with control. Focus on squeezing your shoulder blades together and keeping your shoulders down away from your ears.</p>\n","description_source":"Stand upright with feet hip-width apart, core engaged, and arms relaxed at your sides. From this position, perform three different arm raises to target the shoulders and upper back:\n\n* **T Raise:** Lift your arms straight out to the sides until they are parallel to the floor, forming a “T” shape.\n* **Y Raise:** Lift your arms upward at about a 45° angle from your body to form a “Y” shape.\n* **I Raise:** Raise your arms straight overhead, close together, forming an “I” shape.\n\nMaintain a neutral spine, avoid arching your lower back, and move slowly with control. Focus on squeezing your shoulder blades together and keeping your shoulders down away from your ears.","name":"Arm Raises (T/Y/I)","created":"2025-08-20T08:26:20.606Z","last_update":"2026-04-13T18:58:26.040Z","language":2,"uuid":"887e4234-0145-41d9-876f-bb7b57fd6442","exercise":1606}}],"aliases":[],"comments":[]}'),
('wger', '1607', 'typewriter-pull-up', 'https://wger.de/en/exercise/1607/view', 'CC-BY-SA-4.0', 'tenebrizz', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1607,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"tenebrizz","license_author_url":"","license_derivative_source_url":"","uuid":"075bff87-f676-4d9d-92b4-39d557453fc7","category":12,"variation_group":null,"created":"2025-08-20T11:39:46.043Z","last_update":"2025-08-20T11:39:46.043Z","muscles":[1,12],"muscles_secondary":[9],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2581,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"tenebrizz","license_author_url":"","license_derivative_source_url":"","description":"<p>Hang from a pull-up bar with an overhand grip, slightly wider than shoulder-width. Pull yourself up until your chin is above the bar. At the top position, instead of going straight down, shift your body to one side by extending one arm while keeping the other arm bent. Move smoothly from one side to the other, like a typewriter motion, before lowering yourself back down. This exercise increases time under tension and strengthens the lats, biceps, and shoulders while building unilateral pulling strength.</p>\n","description_source":"Hang from a pull-up bar with an overhand grip, slightly wider than shoulder-width. Pull yourself up until your chin is above the bar. At the top position, instead of going straight down, shift your body to one side by extending one arm while keeping the other arm bent. Move smoothly from one side to the other, like a typewriter motion, before lowering yourself back down. This exercise increases time under tension and strengthens the lats, biceps, and shoulders while building unilateral pulling strength.","name":"Typewriter Pull-ups","created":"2025-08-20T11:39:46.324Z","last_update":"2026-04-13T18:58:27.738Z","language":2,"uuid":"b38ca01d-7325-4f5a-8f12-8b89aba37ad6","exercise":1607}},{"model":"exercises.translation","pk":2582,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"tenebrizz","license_author_url":"","license_derivative_source_url":"","description":"<p>Підтягуєшся вгору, утримуєш верхню точку → переводиш тіло вліво → вправо → опускаєшся.</p>\n","description_source":"Підтягуєшся вгору, утримуєш верхню точку → переводиш тіло вліво → вправо → опускаєшся.","name":"Підтягування-друкарська машинка","created":"2025-08-20T11:39:46.461Z","last_update":"2026-04-13T18:58:28.083Z","language":15,"uuid":"7f9b03a4-87d7-4d24-9502-7af8a66080e4","exercise":1607}}],"aliases":[],"comments":[]}'),
('wger', '1608', 'bodyweight-biceps-curl', 'https://wger.de/en/exercise/1608/view', 'CC-BY-SA-4.0', 'tenebrizz', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1608,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"tenebrizz","license_author_url":"","license_derivative_source_url":"","uuid":"a94623fc-518f-4a74-947b-febd086264bf","category":8,"variation_group":null,"created":"2025-08-20T11:47:43.036Z","last_update":"2025-08-20T11:47:43.036Z","muscles":[1],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2583,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"tenebrizz","license_author_url":"","license_derivative_source_url":"","description":"<p>Set up under a straight bar (around waist or chest height). Grip the bar with your palms facing you (supinated grip), hands about shoulder-width apart. Lean back with straight arms so that your body is at an angle to the ground. Keeping your elbows high and close to the bar, pull your upper body toward the bar by flexing your elbows, similar to a biceps curl. Lower yourself back down in a controlled manner. Keep your core tight and movement slow to maximize tension on the biceps.</p>\n","description_source":"Set up under a straight bar (around waist or chest height). Grip the bar with your palms facing you (supinated grip), hands about shoulder-width apart. Lean back with straight arms so that your body is at an angle to the ground. Keeping your elbows high and close to the bar, pull your upper body toward the bar by flexing your elbows, similar to a biceps curl. Lower yourself back down in a controlled manner. Keep your core tight and movement slow to maximize tension on the biceps.","name":"Bodyweight Biceps Curl","created":"2025-08-20T11:47:43.634Z","last_update":"2026-04-13T18:58:26.129Z","language":2,"uuid":"65b3c8b3-761c-49e4-8291-1d197ee04b7e","exercise":1608}}],"aliases":[],"comments":[]}'),
('wger', '1612', 'kettlebell-sumo-deadlift', 'https://wger.de/en/exercise/1612/view', 'CC-BY-SA-4.0', 'Tierrasverdes', 'new', 100.0, '{"exercise":{"model":"exercises.exercise","pk":1612,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Tierrasverdes","license_author_url":"","license_derivative_source_url":"","uuid":"5cbaa028-114d-4a15-9a95-70d9b3146f30","category":9,"variation_group":null,"created":"2025-08-25T10:46:20.007Z","last_update":"2025-08-25T10:46:20.007Z","muscles":[11,8,10],"muscles_secondary":[],"equipment":[10]}},"translations":[{"model":"exercises.translation","pk":2586,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Tierrasverdes","license_author_url":"","license_derivative_source_url":"","description":"<p>Place your feet wider than shoulder-width apart, pointing your toes outward.\nKeep your back straight, shoulders back, and chest up.\nThe knees must follow the same direction as the toes and not move forward.\nWhen going up, it is advisable to contract your glutes to maximize the effectiveness of the exercise.</p>\n","description_source":"Place your feet wider than shoulder-width apart, pointing your toes outward.\nKeep your back straight, shoulders back, and chest up.\nThe knees must follow the same direction as the toes and not move forward.\nWhen going up, it is advisable to contract your glutes to maximize the effectiveness of the exercise.","name":"kettlebell sumo deadlift","created":"2025-08-25T10:46:20.222Z","last_update":"2026-04-13T18:58:27.952Z","language":2,"uuid":"de1340a6-06b4-4db2-b28e-3b22c2de2b48","exercise":1612}},{"model":"exercises.translation","pk":2587,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Tierrasverdes","license_author_url":"","license_derivative_source_url":"","description":"<p>Separar los pies a una distancia mayor que la anchura de los hombros, con los dedos de los pies apuntando hacia afuera.Manténer la espalda recta, los hombros hacia atrás y el pecho erguido.&nbsp;\nLas rodillas deben seguir la misma dirección que los dedos de los pies y no moverse hacia adelante.&nbsp;\nAl subir, es recomendable contraer los glúteos para maximizar la efectividad del ejercicio.</p>\n","description_source":"Separar los pies a una distancia mayor que la anchura de los hombros, con los dedos de los pies apuntando hacia afuera.Manténer la espalda recta, los hombros hacia atrás y el pecho erguido. \nLas rodillas deben seguir la misma dirección que los dedos de los pies y no moverse hacia adelante. \nAl subir, es recomendable contraer los glúteos para maximizar la efectividad del ejercicio.","name":"Sentadilla con pesa rusa","created":"2025-08-25T10:54:50.669Z","last_update":"2026-04-13T18:58:27.311Z","language":4,"uuid":"8472471b-a0ad-4409-948a-b06acf9d9689","exercise":1612}}],"aliases":[],"comments":[]}'),
('wger', '1613', 'band-rubber-glute-kickback', 'https://wger.de/en/exercise/1613/view', 'CC-BY-SA-4.0', 'Tierrasverdes', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1613,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Tierrasverdes","license_author_url":"","license_derivative_source_url":"","uuid":"4221c8af-b3ca-4a53-9176-bd66e46d10f2","category":9,"variation_group":null,"created":"2025-08-25T11:53:41.566Z","last_update":"2025-08-25T11:53:41.566Z","muscles":[8],"muscles_secondary":[],"equipment":[11]}},"translations":[{"model":"exercises.translation","pk":2588,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Tierrasverdes","license_author_url":"","license_derivative_source_url":"","description":"<p>A rubber band glute kickback is an exercise performed on hands and knees, where you anchor a resistance band to your foot and kick your heel back and up, squeezing your glute at the top of the movement, while maintaining a stable core and flat back to target and strengthen the gluteal muscles.</p>\n","description_source":"A rubber band glute kickback is an exercise performed on hands and knees, where you anchor a resistance band to your foot and kick your heel back and up, squeezing your glute at the top of the movement, while maintaining a stable core and flat back to target and strengthen the gluteal muscles. ","name":"rubber band glute kickback","created":"2025-08-25T11:53:41.774Z","last_update":"2026-04-13T18:58:27.962Z","language":2,"uuid":"b1266d49-8a68-4523-b9da-ceae57b49a47","exercise":1613}},{"model":"exercises.translation","pk":2589,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Tierrasverdes","license_author_url":"","license_derivative_source_url":"","description":"<p>Una patada de glúteos con banda elástica es un ejercicio que se realiza a gatas. Se ancla una banda de resistencia a la parte posterior de la rodilla y se patea el talón hacia atrás y arriba, apretando el glúteo en la parte superior del movimiento, manteniendo el torso estable y la espalda recta para trabajar y fortalecer los músculos de los glúteos.</p>\n","description_source":"Una patada de glúteos con banda elástica es un ejercicio que se realiza a gatas. Se ancla una banda de resistencia a la parte posterior de la rodilla y se patea el talón hacia atrás y arriba, apretando el glúteo en la parte superior del movimiento, manteniendo el torso estable y la espalda recta para trabajar y fortalecer los músculos de los glúteos.","name":"Patada de glúteo con banda elástica","created":"2025-08-25T12:00:36.758Z","last_update":"2026-04-13T18:58:26.905Z","language":4,"uuid":"eded31e8-870e-4b28-b22a-c0fabcfb62b1","exercise":1613}}],"aliases":[],"comments":[]}'),
('wger', '1614', 'dumbbell-hip-thrust', 'https://wger.de/en/exercise/1614/view', 'CC-BY-SA-4.0', 'Tierrasverdes', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1614,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Tierrasverdes","license_author_url":"","license_derivative_source_url":"","uuid":"e5ccfcaf-d93c-4924-9042-24037f3f0499","category":9,"variation_group":null,"created":"2025-08-25T12:27:43.460Z","last_update":"2025-08-25T12:27:43.460Z","muscles":[8],"muscles_secondary":[],"equipment":[8]}},"translations":[{"model":"exercises.translation","pk":2590,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Tierrasverdes","license_author_url":"","license_derivative_source_url":"","description":"<p>Dumbbell hip thrust\nBegin seated on the ground with a bench placed horizontally behind you and your knees bent. Lay a dumbbell across your hips, holding either end with both hands. You may wish to place a pad or towel on your hips to increase comfort. With knees bent and feet firmly planted on the floor, lean back onto the bench so that it is gently pressing into your upper back. This is your starting position.\nInhale. Exhale. Holding onto the dumbbell, press your heels into the mat and raise your hips off the floor until your body forms one straight line from chin to knee, resting your shoulders on the bench and ensuring that your head is an extension of your spine.\nInhale. Lower your hips to return to the starting position but without resting your glutes on the mat. Repeat for the specified number of repetitions.</p>\n","description_source":"Dumbbell hip thrust\nBegin seated on the ground with a bench placed horizontally behind you and your knees bent. Lay a dumbbell across your hips, holding either end with both hands. You may wish to place a pad or towel on your hips to increase comfort. With knees bent and feet firmly planted on the floor, lean back onto the bench so that it is gently pressing into your upper back. This is your starting position.\nInhale. Exhale. Holding onto the dumbbell, press your heels into the mat and raise your hips off the floor until your body forms one straight line from chin to knee, resting your shoulders on the bench and ensuring that your head is an extension of your spine.\nInhale. Lower your hips to return to the starting position but without resting your glutes on the mat. Repeat for the specified number of repetitions.","name":"Dumbbell Hip Thrust","created":"2025-08-25T12:27:43.691Z","last_update":"2026-04-13T18:58:26.424Z","language":2,"uuid":"e229025e-1d3a-4073-955e-ea46c4e3584f","exercise":1614}},{"model":"exercises.translation","pk":2591,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Tierrasverdes","license_author_url":"","license_derivative_source_url":"","description":"<p>Elevación de cadera con mancuernas\nComienza sentado en el suelo con un banco horizontal detrás de ti y las rodillas flexionadas. Coloca una mancuerna sobre tus caderas, sujetando cada extremo con ambas manos. Puedes colocar una almohadilla o toalla sobre las caderas para mayor comodidad. Con las rodillas flexionadas y los pies firmemente apoyados en el suelo, inclínate hacia atrás sobre el banco de modo que presione suavemente la parte superior de la espalda. Esta es la posición inicial.\nInhala. Exhala. Sujetando la mancuerna, presiona los talones contra la colchoneta y levanta las caderas del suelo hasta que tu cuerpo forme una línea recta desde la barbilla hasta la rodilla, apoyando los hombros en el banco y asegurándote de que la cabeza sea una extensión de la columna vertebral.\nInhala. Baja las caderas para volver a la posición inicial, pero sin apoyar los glúteos en la colchoneta. Repite el número de repeticiones indicado.</p>\n","description_source":"Elevación de cadera con mancuernas\nComienza sentado en el suelo con un banco horizontal detrás de ti y las rodillas flexionadas. Coloca una mancuerna sobre tus caderas, sujetando cada extremo con ambas manos. Puedes colocar una almohadilla o toalla sobre las caderas para mayor comodidad. Con las rodillas flexionadas y los pies firmemente apoyados en el suelo, inclínate hacia atrás sobre el banco de modo que presione suavemente la parte superior de la espalda. Esta es la posición inicial.\nInhala. Exhala. Sujetando la mancuerna, presiona los talones contra la colchoneta y levanta las caderas del suelo hasta que tu cuerpo forme una línea recta desde la barbilla hasta la rodilla, apoyando los hombros en el banco y asegurándote de que la cabeza sea una extensión de la columna vertebral.\nInhala. Baja las caderas para volver a la posición inicial, pero sin apoyar los glúteos en la colchoneta. Repite el número de repeticiones indicado.","name":"Elevacion de cadera con mancuernas","created":"2025-08-25T12:31:08.489Z","last_update":"2026-04-13T18:58:26.465Z","language":4,"uuid":"e374b6c3-9f5d-4fd4-bfa7-4d2b7497a45d","exercise":1614}}],"aliases":[],"comments":[]}'),
('wger', '1615', NULL, 'https://wger.de/en/exercise/1615/view', 'CC-BY-SA-4.0', 'Tierrasverdes', NULL, NULL, '{"exercise":{"model":"exercises.exercise","pk":1615,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Tierrasverdes","license_author_url":"","license_derivative_source_url":"","uuid":"3f8e5871-4895-48c9-928d-dc1bc134f57b","category":15,"variation_group":null,"created":"2025-08-26T10:37:25.089Z","last_update":"2025-08-26T10:37:25.089Z","muscles":[],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2592,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Tierrasverdes","license_author_url":"","license_derivative_source_url":"","description":"<p>It''s a cardiovascular workout performed on a treadmill to improve endurance, burn calories, and promote heart health. It offers multiple benefits, such as the ability to easily adjust speed and incline, allowing for a variety of workouts, from hill walking to high-intensity interval training (HIIT) and tempo runs. To optimize results, it''s important to vary your workouts.\nBenefits of Treadmill Cardio:</p>\n<ul>\n<li>Improved Cardiovascular Health:\nRegular aerobic exercise on a treadmill strengthens the heart and lungs, which can help prevent heart disease.</li>\n<li>Weight Loss:\nBy burning calories, treadmill training can be an effective tool for weight loss and maintaining a healthy weight.</li>\n<li>Muscle Strengthening:\nIt strengthens the muscles in the legs and glutes, helping to prevent muscle loss, which is especially important with age.</li>\n<li>Training Flexibility:\nAllows you to vary speed, incline, and intervals, making your workout more dynamic and adaptable to different fitness levels.\nTypes of Treadmill Training:</li>\n<li>Hill Walking:\nIncreasing the incline of the treadmill and walking at a brisk pace can improve endurance and work your leg muscles.</li>\n<li>Endurance Jog:\nA run at a comfortable, steady pace that keeps your heart rate in a target zone (such as Zone 2) to build endurance.</li>\n<li>Interval Training:\nAlternating periods of high intensity (fast running) with periods of low intensity (easy walking or jogging) to maximize calorie burn and cardiovascular improvement.</li>\n<li>Tempo Run:\nA run at a steady, sustained pace that is slightly faster than a normal jog, which challenges your ability to sustain a more intense effort for an extended period.</li>\n</ul>\n","description_source":"It''s a cardiovascular workout performed on a treadmill to improve endurance, burn calories, and promote heart health. It offers multiple benefits, such as the ability to easily adjust speed and incline, allowing for a variety of workouts, from hill walking to high-intensity interval training (HIIT) and tempo runs. To optimize results, it''s important to vary your workouts.\nBenefits of Treadmill Cardio:\n- Improved Cardiovascular Health:\nRegular aerobic exercise on a treadmill strengthens the heart and lungs, which can help prevent heart disease.\n- Weight Loss:\nBy burning calories, treadmill training can be an effective tool for weight loss and maintaining a healthy weight.\n- Muscle Strengthening:\nIt strengthens the muscles in the legs and glutes, helping to prevent muscle loss, which is especially important with age.\n- Training Flexibility:\nAllows you to vary speed, incline, and intervals, making your workout more dynamic and adaptable to different fitness levels.\nTypes of Treadmill Training:\n- Hill Walking:\nIncreasing the incline of the treadmill and walking at a brisk pace can improve endurance and work your leg muscles.\n- Endurance Jog:\nA run at a comfortable, steady pace that keeps your heart rate in a target zone (such as Zone 2) to build endurance.\n- Interval Training:\nAlternating periods of high intensity (fast running) with periods of low intensity (easy walking or jogging) to maximize calorie burn and cardiovascular improvement.\n- Tempo Run:\nA run at a steady, sustained pace that is slightly faster than a normal jog, which challenges your ability to sustain a more intense effort for an extended period.","name":"Treadmill Cardio","created":"2025-08-26T10:37:25.312Z","last_update":"2026-04-13T18:58:27.695Z","language":2,"uuid":"f7935740-7d31-420d-a701-7835632343e0","exercise":1615}},{"model":"exercises.translation","pk":2593,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Tierrasverdes","license_author_url":"","license_derivative_source_url":"","description":"<p>Es un entrenamiento cardiovascular que se realiza en una cinta de correr para mejorar la resistencia, quemar calorías y promover la salud del corazón. Ofrece múltiples beneficios, como la capacidad de ajustar fácilmente la velocidad e inclinación, lo que permite realizar diversos entrenamientos, desde caminatas en pendiente hasta carreras a intervalos de alta intensidad (HIIT) y carreras de tempo. Para optimizar los resultados, es importante variar los entrenamientos.\nBeneficios del cardio en cinta:</p>\n<ul>\n<li>Mejora de la salud cardiovascular:\nEl ejercicio aeróbico regular en la cinta fortalece el corazón y los pulmones, lo que puede ayudar a prevenir enfermedades cardíacas.</li>\n<li>Pérdida de peso:\nAl quemar calorías, el entrenamiento en cinta puede ser una herramienta eficaz para la pérdida de peso y el mantenimiento de un peso saludable.</li>\n<li>Fortalecimiento muscular:\nFortalece los músculos de las piernas y glúteos, ayudando a prevenir la pérdida de masa muscular, especialmente importante con la edad.</li>\n<li>Flexibilidad en el entrenamiento:\nPermite variar la velocidad, la inclinación y los intervalos, lo que hace que el entrenamiento sea más dinámico y adaptable a diferentes niveles de condición física.</li>\n</ul>\n","description_source":"Es un entrenamiento cardiovascular que se realiza en una cinta de correr para mejorar la resistencia, quemar calorías y promover la salud del corazón. Ofrece múltiples beneficios, como la capacidad de ajustar fácilmente la velocidad e inclinación, lo que permite realizar diversos entrenamientos, desde caminatas en pendiente hasta carreras a intervalos de alta intensidad (HIIT) y carreras de tempo. Para optimizar los resultados, es importante variar los entrenamientos.\nBeneficios del cardio en cinta:\n- Mejora de la salud cardiovascular:\nEl ejercicio aeróbico regular en la cinta fortalece el corazón y los pulmones, lo que puede ayudar a prevenir enfermedades cardíacas. \n- Pérdida de peso:\nAl quemar calorías, el entrenamiento en cinta puede ser una herramienta eficaz para la pérdida de peso y el mantenimiento de un peso saludable. \n- Fortalecimiento muscular:\nFortalece los músculos de las piernas y glúteos, ayudando a prevenir la pérdida de masa muscular, especialmente importante con la edad. \n- Flexibilidad en el entrenamiento:\nPermite variar la velocidad, la inclinación y los intervalos, lo que hace que el entrenamiento sea más dinámico y adaptable a diferentes niveles de condición física. ","name":"Cardio en cinta","created":"2025-08-26T10:47:00.079Z","last_update":"2026-04-13T18:58:26.196Z","language":4,"uuid":"c7a9e2fd-7b65-4af4-beaf-3650592d270a","exercise":1615}}],"aliases":[],"comments":[]}'),
('wger', '1616', 'dumbbell-patada-de-burro-con-mancuerna', 'https://wger.de/en/exercise/1616/view', 'CC-BY-SA-4.0', 'Tierrasverdes', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1616,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Tierrasverdes","license_author_url":"","license_derivative_source_url":"","uuid":"2539f907-0c10-4af5-807c-48cd15fd0878","category":9,"variation_group":null,"created":"2025-08-27T10:39:59.009Z","last_update":"2025-08-27T10:39:59.009Z","muscles":[11,8],"muscles_secondary":[],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2598,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Tierrasverdes","license_author_url":"","license_derivative_source_url":"","description":"<p>La patada de burro con mancuerna es un ejercicio efectivo para trabajar los músculos de los glúteos y los isquiotibiales. Este ejercicio se realiza generalmente en una posición de cuatro patas, utilizando una mancuerna para aumentar la resistencia. A continuación, se describen los pasos para realizarlo correctamente.\nPosición Inicial: Colócate en una posición de cuatro patas sobre una colchoneta, con las manos alineadas con los hombros y las rodillas alineadas con las caderas.\nColocación de la Mancuerna: Toma una mancuerna y colócala detrás de la rodilla de la pierna que vas a levantar. Asegúrate de que esté bien sujeta para evitar que se caiga durante el ejercicio.\nEjercicio:\nInhala y, al exhalar, levanta la pierna con la mancuerna hacia arriba, manteniendo la rodilla flexionada en un ángulo de 90 grados.\nEleva la pierna hasta que esté paralela al suelo, sintiendo la contracción en los glúteos.\nMantén la posición durante un segundo en la parte superior y luego baja lentamente la pierna a la posición inicial.\nRepeticiones: Realiza de 10 a 15 repeticiones por cada pierna, asegurándote de mantener una buena forma durante todo el ejercicio.\nSeries: Completa de 2 a 3 series, dependiendo de tu nivel de condición física.</p>\n","description_source":"La patada de burro con mancuerna es un ejercicio efectivo para trabajar los músculos de los glúteos y los isquiotibiales. Este ejercicio se realiza generalmente en una posición de cuatro patas, utilizando una mancuerna para aumentar la resistencia. A continuación, se describen los pasos para realizarlo correctamente.\nPosición Inicial: Colócate en una posición de cuatro patas sobre una colchoneta, con las manos alineadas con los hombros y las rodillas alineadas con las caderas.\nColocación de la Mancuerna: Toma una mancuerna y colócala detrás de la rodilla de la pierna que vas a levantar. Asegúrate de que esté bien sujeta para evitar que se caiga durante el ejercicio.\nEjercicio:\nInhala y, al exhalar, levanta la pierna con la mancuerna hacia arriba, manteniendo la rodilla flexionada en un ángulo de 90 grados.\nEleva la pierna hasta que esté paralela al suelo, sintiendo la contracción en los glúteos.\nMantén la posición durante un segundo en la parte superior y luego baja lentamente la pierna a la posición inicial.\nRepeticiones: Realiza de 10 a 15 repeticiones por cada pierna, asegurándote de mantener una buena forma durante todo el ejercicio.\nSeries: Completa de 2 a 3 series, dependiendo de tu nivel de condición física.","name":"Patada de burro con mancuerna","created":"2025-08-27T10:39:59.217Z","last_update":"2026-04-13T18:58:26.904Z","language":2,"uuid":"b859303e-dd3c-44c8-8f0c-188521e4f851","exercise":1616}}],"aliases":[],"comments":[]}'),
('wger', '1618', NULL, 'https://wger.de/en/exercise/1618/view', 'CC-BY-SA-4.0', 'Tierrasverdes', NULL, NULL, '{"exercise":{"model":"exercises.exercise","pk":1618,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Tierrasverdes","license_author_url":"","license_derivative_source_url":"","uuid":"5da3d393-0c4e-4ac8-96b4-aab51f6ab3d1","category":15,"variation_group":null,"created":"2025-08-27T11:27:05.809Z","last_update":"2025-08-27T11:27:05.809Z","muscles":[],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2601,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Tierrasverdes","license_author_url":"","license_derivative_source_url":"","description":"<p>Beneficios del Cardio en Bicicleta Estática\nEl cardio en bicicleta estática es una excelente forma de ejercicio que ofrece múltiples beneficios para la salud y el bienestar. Aquí te detallo algunos de los más destacados:\nMejora de la Salud Cardiovascular\nFortalece el corazón: El ejercicio regular ayuda a mejorar la eficiencia del corazón y a reducir el riesgo de enfermedades cardiovasculares.\nAumenta la circulación: Mejora el flujo sanguíneo, lo que puede ayudar a reducir la presión arterial.\nQuema de Calorías y Pérdida de Peso\nEficiente para quemar calorías: Dependiendo de la intensidad, puedes quemar entre 400 y 600 calorías por hora.\nAyuda en la pérdida de peso: Combinado con una dieta equilibrada, el cardio en bicicleta estática puede ser efectivo para perder peso.\nFortalecimiento Muscular\nTonifica las piernas: Trabaja principalmente los músculos de las piernas, incluyendo cuádriceps, isquiotibiales y pantorrillas.\nMejora la resistencia muscular: Con el tiempo, puedes aumentar la resistencia y la fuerza en las piernas.\nBeneficios para la Salud Mental\nReduce el estrés: El ejercicio libera endorfinas, que pueden mejorar tu estado de ánimo y reducir el estrés.\nAumenta la energía: La actividad física regular puede aumentar tus niveles de energía y mejorar la calidad del sueño.</p>\n","description_source":"Beneficios del Cardio en Bicicleta Estática\nEl cardio en bicicleta estática es una excelente forma de ejercicio que ofrece múltiples beneficios para la salud y el bienestar. Aquí te detallo algunos de los más destacados:\nMejora de la Salud Cardiovascular\nFortalece el corazón: El ejercicio regular ayuda a mejorar la eficiencia del corazón y a reducir el riesgo de enfermedades cardiovasculares.\nAumenta la circulación: Mejora el flujo sanguíneo, lo que puede ayudar a reducir la presión arterial.\nQuema de Calorías y Pérdida de Peso\nEficiente para quemar calorías: Dependiendo de la intensidad, puedes quemar entre 400 y 600 calorías por hora.\nAyuda en la pérdida de peso: Combinado con una dieta equilibrada, el cardio en bicicleta estática puede ser efectivo para perder peso.\nFortalecimiento Muscular\nTonifica las piernas: Trabaja principalmente los músculos de las piernas, incluyendo cuádriceps, isquiotibiales y pantorrillas.\nMejora la resistencia muscular: Con el tiempo, puedes aumentar la resistencia y la fuerza en las piernas.\nBeneficios para la Salud Mental\nReduce el estrés: El ejercicio libera endorfinas, que pueden mejorar tu estado de ánimo y reducir el estrés.\nAumenta la energía: La actividad física regular puede aumentar tus niveles de energía y mejorar la calidad del sueño.","name":"Cardio en bicicleta estática","created":"2025-08-27T11:27:06.052Z","last_update":"2026-04-13T18:58:26.195Z","language":2,"uuid":"28e6955a-1fe2-40d0-9593-749eb93f9e4f","exercise":1618}}],"aliases":[],"comments":[]}'),
('wger', '1620', 'dumbbell-seated-calf-raise', 'https://wger.de/en/exercise/1620/view', 'CC-BY-SA-4.0', 'AlucardEvil40', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1620,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"AlucardEvil40","license_author_url":"","license_derivative_source_url":"","uuid":"6995c30a-037f-4de3-ac4a-45384a1f38f9","category":14,"variation_group":null,"created":"2025-09-02T10:08:09.181Z","last_update":"2025-09-02T10:08:09.181Z","muscles":[7],"muscles_secondary":[],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2602,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"AlucardEvil40","license_author_url":"","license_derivative_source_url":"","description":"<p>The seated dumbbell calf raise is a targeted exercise for strengthening the lower leg muscles. It follows the same movement pattern as the machine version: you place the weight on your knees, and by extending and flexing your ankles, you move the weight.</p>\n","description_source":"The seated dumbbell calf raise is a targeted exercise for strengthening the lower leg muscles. It follows the same movement pattern as the machine version: you place the weight on your knees, and by extending and flexing your ankles, you move the weight.","name":"Seated Dumbbell Calf Raise","created":"2025-09-02T10:08:09.389Z","last_update":"2026-04-13T18:58:27.270Z","language":2,"uuid":"2439f916-fed8-40af-b86c-7dc7fe1dcc3f","exercise":1620}},{"model":"exercises.translation","pk":2603,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"AlucardEvil40","license_author_url":"","license_derivative_source_url":"","description":"<p>L''élévation des mollets avec haltères en position assise est un exercice ciblé pour renforcer les muscles du bas de la jambe. Il suit le même schéma de mouvement que la version avec machine : vous placez le poids sur vos genoux, et en étendant et en fléchissant vos chevilles, vous déplacez le poids.</p>\n","description_source":"L''élévation des mollets avec haltères en position assise est un exercice ciblé pour renforcer les muscles du bas de la jambe. Il suit le même schéma de mouvement que la version avec machine : vous placez le poids sur vos genoux, et en étendant et en fléchissant vos chevilles, vous déplacez le poids.","name":"Élévation des mollets haltères assis","created":"2025-09-02T10:08:09.718Z","last_update":"2026-04-13T18:58:27.973Z","language":12,"uuid":"b479cef8-9c13-4922-9d24-46cd9e4a3490","exercise":1620}}],"aliases":[],"comments":[]}'),
('wger', '1621', 'cable-unilateral-row', 'https://wger.de/en/exercise/1621/view', 'CC-BY-SA-4.0', 'Rottekongen', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1621,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Rottekongen","license_author_url":"","license_derivative_source_url":"","uuid":"c1a9297d-6786-45dc-9047-5539fb61db9c","category":12,"variation_group":null,"created":"2025-09-04T07:44:17.513Z","last_update":"2025-09-04T07:44:17.513Z","muscles":[12,3],"muscles_secondary":[],"equipment":[8]}},"translations":[{"model":"exercises.translation","pk":2604,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Rottekongen","license_author_url":"","license_derivative_source_url":"","description":"<p>Put a vertical seated bench in front of the cable row machine.position it so that you can focus on one side, and then do slow pulls focusing on the lateral muscles and ensuring tention in those muscles when in a stretched position.</p>\n","description_source":"Put a vertical seated bench in front of the cable row machine.position it so that you can focus on one side, and then do slow pulls focusing on the lateral muscles and ensuring tention in those muscles when in a stretched position.","name":"Unilateral Cable row","created":"2025-09-04T07:44:17.691Z","last_update":"2026-04-13T18:58:27.748Z","language":2,"uuid":"b86c6bcd-6346-4492-8ddb-4d5c933253b8","exercise":1621}}],"aliases":[],"comments":[]}'),
('wger', '1627', 'barbell-squat', 'https://wger.de/en/exercise/1627/view', 'CC-BY-SA-4.0', 'clafal; admin', 'normalized', 100.0, '{"exercise":{"model":"exercises.exercise","pk":1627,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"clafal","license_author_url":"","license_derivative_source_url":"","uuid":"40d071cd-d142-426b-8fe3-ca184985d86b","category":9,"variation_group":"bf39ef58-188b-4b23-a6a4-ddbf8863d9e9","created":"2025-09-09T13:15:11.905Z","last_update":"2026-01-14T13:18:36.984Z","muscles":[11,8],"muscles_secondary":[14,6],"equipment":[1]}},"translations":[{"model":"exercises.translation","pk":2605,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"clafal","license_author_url":"","license_derivative_source_url":"","description":"<p>Stand with your feet shoulder-width apart and the barbell resting securely on your upper back (not your neck), gripping it slightly wider than shoulder-width. Keep your chest up, back straight, and core engaged.</p>\n<p>Begin the movement by bending at your hips and knees, lowering your body as if sitting back into a chair. Continue descending until your thighs are at least parallel to the ground (or slightly below if mobility allows). Keep your knees aligned with your toes and your weight evenly distributed through your heels.</p>\n<p>Push through your heels to return to the starting position, extending your hips and knees until you are standing tall again.</p>\n","description_source":"Stand with your feet shoulder-width apart and the barbell resting securely on your upper back (not your neck), gripping it slightly wider than shoulder-width. Keep your chest up, back straight, and core engaged.\n\nBegin the movement by bending at your hips and knees, lowering your body as if sitting back into a chair. Continue descending until your thighs are at least parallel to the ground (or slightly below if mobility allows). Keep your knees aligned with your toes and your weight evenly distributed through your heels.\n\nPush through your heels to return to the starting position, extending your hips and knees until you are standing tall again.","name":"Barbell squat","created":"2025-09-09T13:15:12.163Z","last_update":"2026-04-13T18:58:26.081Z","language":2,"uuid":"fd5e0ab4-63ab-44b3-859e-0c494d9b4428","exercise":1627}},{"model":"exercises.translation","pk":2606,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"clafal","license_author_url":"","license_derivative_source_url":"","description":"<p>Stai in piedi con i piedi alla larghezza delle spalle e il bilanciere appoggiato saldamente sulla parte alta della schiena (non sul collo), afferrandolo con le mani leggermente più larghe delle spalle. Mantieni il petto alto, la schiena dritta e il core contratto.</p>\n<p>Inizia il movimento piegando fianchi e ginocchia, abbassando il corpo come se stessi per sederti su una sedia. Continua a scendere finché le cosce non sono almeno parallele al pavimento (o leggermente più in basso se la mobilità lo consente). Mantieni le ginocchia allineate con le punte dei piedi e il peso distribuito sui talloni.</p>\n<p>Spingi con forza attraverso i talloni per tornare alla posizione iniziale, estendendo anche fianchi e ginocchia fino a tornare in posizione eretta.</p>\n","description_source":"Stai in piedi con i piedi alla larghezza delle spalle e il bilanciere appoggiato saldamente sulla parte alta della schiena (non sul collo), afferrandolo con le mani leggermente più larghe delle spalle. Mantieni il petto alto, la schiena dritta e il core contratto.\n\nInizia il movimento piegando fianchi e ginocchia, abbassando il corpo come se stessi per sederti su una sedia. Continua a scendere finché le cosce non sono almeno parallele al pavimento (o leggermente più in basso se la mobilità lo consente). Mantieni le ginocchia allineate con le punte dei piedi e il peso distribuito sui talloni.\n\nSpingi con forza attraverso i talloni per tornare alla posizione iniziale, estendendo anche fianchi e ginocchia fino a tornare in posizione eretta.","name":"Squat con bilanciere","created":"2025-09-09T13:15:12.310Z","last_update":"2026-04-13T18:58:27.489Z","language":13,"uuid":"0ede3977-0602-4598-afa9-bef43a416a61","exercise":1627}},{"model":"exercises.translation","pk":2651,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"admin","license_author_url":"","license_derivative_source_url":"","description":"<ul>\n<li>Muskulatur anspannen</li>\n<li>Kein Schwung holen</li>\n<li>Kontrollierte Bewegung</li>\n<li>Langsame Bewegung</li>\n<li>Beine nicht überstrecken</li>\n<li>Rücken gerade halten</li>\n</ul>\n","description_source":"* Muskulatur anspannen\n* Kein Schwung holen\n* Kontrollierte Bewegung\n* Langsame Bewegung\n* Beine nicht überstrecken\n* Rücken gerade halten","name":"Kniebeuge mit Kurzhanteln","created":"2025-09-09T19:02:30.414Z","last_update":"2026-04-13T18:58:26.731Z","language":1,"uuid":"221bc231-88f7-41ef-8c8a-87b5ca2b8b01","exercise":1627}}],"aliases":[{"model":"exercises.alias","pk":600,"fields":{"uuid":"7f989f27-2e96-4005-9558-55989d7a00e4","translation":2651,"alias":"Squats (Dumbbells)"}}],"comments":[]}'),
('wger', '1630', 'blaze', 'https://wger.de/en/exercise/1630/view', 'CC-BY-SA-4.0', 'ricwheatley', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1630,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"ricwheatley","license_author_url":"","license_derivative_source_url":"","uuid":"24f988e7-51eb-44f5-92f2-d4e0199c2269","category":15,"variation_group":null,"created":"2025-09-20T04:26:51.063Z","last_update":"2025-09-20T04:26:51.063Z","muscles":[2,8,4,10],"muscles_secondary":[1,11,12,6],"equipment":[8,3,10,7]}},"translations":[{"model":"exercises.translation","pk":2739,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"ricwheatley","license_author_url":"","license_derivative_source_url":"","description":"<p>BLAZE is a full-body HIIT workout. Designed to supercharge your cardio fitness and strength.&nbsp;Delivered in its own purpose-built studio, BLAZE is a unique mix of martial arts, intense cardio and strength training.</p>\n","description_source":"BLAZE is a full-body HIIT workout. Designed to supercharge your cardio fitness and strength. Delivered in its own purpose-built studio, BLAZE is a unique mix of martial arts, intense cardio and strength training.","name":"Blaze","created":"2025-09-20T04:26:51.248Z","last_update":"2026-04-13T18:58:26.126Z","language":2,"uuid":"60f500a5-9656-4b2e-8b8d-897f0da80d48","exercise":1630}}],"aliases":[],"comments":[]}'),
('wger', '1634', 'rope-pullover-row', 'https://wger.de/en/exercise/1634/view', 'CC-BY-SA-4.0', 'Rottekongen', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1634,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Rottekongen","license_author_url":"","license_derivative_source_url":"","uuid":"148f2ffc-05e2-486b-874f-2a401337a1c6","category":12,"variation_group":null,"created":"2025-09-23T12:58:42.849Z","last_update":"2025-09-23T12:58:42.849Z","muscles":[12],"muscles_secondary":[],"equipment":[9]}},"translations":[{"model":"exercises.translation","pk":2740,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Rottekongen","license_author_url":"","license_derivative_source_url":"","description":"<p>Set up bench in front of cable row machine. Lean over bench to do a row/pullover with rope that targets lats. See picture.</p>\n","description_source":"Set up bench in front of cable row machine. Lean over bench to do a row/pullover with rope that targets lats. See picture.","name":"Rope Pullover/row","created":"2025-09-23T12:58:43.011Z","last_update":"2026-04-13T18:58:27.175Z","language":2,"uuid":"9ff6ac66-e687-4a21-ba49-2e9cbf7882a9","exercise":1634}}],"aliases":[],"comments":[]}'),
('wger', '1635', 'modified-pulldown', 'https://wger.de/en/exercise/1635/view', 'CC-BY-SA-4.0', 'Rottekongen', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1635,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Rottekongen","license_author_url":"","license_derivative_source_url":"","uuid":"5851e2b1-3a80-42ff-91da-530e6b143a34","category":12,"variation_group":null,"created":"2025-09-23T13:02:42.257Z","last_update":"2025-09-23T13:02:42.257Z","muscles":[12],"muscles_secondary":[],"equipment":[9]}},"translations":[{"model":"exercises.translation","pk":2741,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Rottekongen","license_author_url":"","license_derivative_source_url":"","description":"<p>With an inclined bench in front of the pulldown machine, use a close-grip to do latfocused pulldowns.</p>\n","description_source":"With an inclined bench in front of the pulldown machine, use a close-grip to do latfocused pulldowns.","name":"Modified pulldown","created":"2025-09-23T13:02:42.399Z","last_update":"2026-04-13T18:58:26.851Z","language":2,"uuid":"b01040e3-5d6e-4d7b-8361-a6b51cc69df9","exercise":1635}}],"aliases":[],"comments":[]}'),
('wger', '1636', 'cable-unilateral-row', 'https://wger.de/en/exercise/1636/view', 'CC-BY-SA-4.0', 'Rottekongen', 'exact', 100.0, '{"exercise":{"model":"exercises.exercise","pk":1636,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Rottekongen","license_author_url":"","license_derivative_source_url":"","uuid":"505b2027-2f65-4cef-851b-f5e634921f1a","category":12,"variation_group":null,"created":"2025-09-23T13:06:23.310Z","last_update":"2025-09-23T13:06:23.310Z","muscles":[12],"muscles_secondary":[],"equipment":[9]}},"translations":[{"model":"exercises.translation","pk":2742,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Rottekongen","license_author_url":"","license_derivative_source_url":"","description":"<p>With an inclined bench in front of the cable row machine, do onehanded rows with focus on a big stretch in the lats.</p>\n","description_source":"With an inclined bench in front of the cable row machine, do onehanded rows with focus on a big stretch in the lats. ","name":"Unilateral Cable row","created":"2025-09-23T13:06:23.430Z","last_update":"2026-04-13T18:58:27.749Z","language":2,"uuid":"f927e5f8-ea50-49b3-996b-842d9b106736","exercise":1636}}],"aliases":[],"comments":[]}'),
('wger', '1637', 'single-arm-row', 'https://wger.de/en/exercise/1637/view', 'CC-BY-SA-4.0', 'Rottekongen', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1637,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Rottekongen","license_author_url":"","license_derivative_source_url":"","uuid":"81dd44b3-67b3-4198-9e57-c2a80b3c4102","category":12,"variation_group":null,"created":"2025-09-23T13:10:33.585Z","last_update":"2025-09-23T13:10:33.585Z","muscles":[12],"muscles_secondary":[],"equipment":[9]}},"translations":[{"model":"exercises.translation","pk":2743,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Rottekongen","license_author_url":"","license_derivative_source_url":"","description":"<p>Sitting on the ground, use a high cable in a single grip, to do lat pulldowns with a focus on a long stretch in the lats.</p>\n","description_source":"Sitting on the ground, use a high cable in a single grip, to do lat pulldowns with a focus on a long stretch in the lats.","name":"Single arm row","created":"2025-09-23T13:10:33.688Z","last_update":"2026-04-13T18:58:27.401Z","language":2,"uuid":"75f7115b-a70a-455d-ac52-ba40ae6cdba0","exercise":1637}}],"aliases":[],"comments":[]}'),
('wger', '1638', 'barbell-clean-and-press', 'https://wger.de/en/exercise/1638/view', 'CC-BY-SA-4.0', 'Rottekongen', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1638,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Rottekongen","license_author_url":"","license_derivative_source_url":"","uuid":"e9e7372c-b5c1-45d9-ae5c-b1aa0fc2e2ce","category":13,"variation_group":null,"created":"2025-09-23T13:23:59.561Z","last_update":"2025-09-23T13:23:59.561Z","muscles":[2,4],"muscles_secondary":[],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2744,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Rottekongen","license_author_url":"","license_derivative_source_url":"","description":"<p>This exercise involves lifting a barbell from the ground to the shoulders, then pressing it overhead. It is a compound movement that targets multiple muscle groups, including the legs, back, shoulders, and arms. It is often used in strength and conditioning programs to improve overall power and athleticism.</p>\n","description_source":"This exercise involves lifting a barbell from the ground to the shoulders, then pressing it overhead. It is a compound movement that targets multiple muscle groups, including the legs, back, shoulders, and arms. It is often used in strength and conditioning programs to improve overall power and athleticism.","name":"Barbell Clean and press","created":"2025-09-23T13:23:59.741Z","last_update":"2026-04-13T18:58:26.069Z","language":2,"uuid":"6b8f45d0-85fb-48de-b958-b9247b2436f3","exercise":1638}}],"aliases":[],"comments":[]}'),
('wger', '1639', 'dumbbell-bent-over-face-pull', 'https://wger.de/en/exercise/1639/view', 'CC-BY-SA-4.0', 'AlucardEvil40', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1639,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"AlucardEvil40","license_author_url":"","license_derivative_source_url":"","uuid":"51ab6376-eb3e-42dc-ad48-46166c94adac","category":12,"variation_group":null,"created":"2025-09-27T06:57:28.900Z","last_update":"2025-09-27T06:57:28.900Z","muscles":[2,12],"muscles_secondary":[9],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2745,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"AlucardEvil40","license_author_url":"","license_derivative_source_url":"","description":"<p>This exercise involves using dumbbells to perform a bent over face pull, which targets the upper back and shoulders. The movement involves pulling the weights towards the face while keeping the elbows high and squeezing the shoulder blades together.</p>\n","description_source":"This exercise involves using dumbbells to perform a bent over face pull, which targets the upper back and shoulders. The movement involves pulling the weights towards the face while keeping the elbows high and squeezing the shoulder blades together.","name":"Dumbbell Bent Over Face Pull","created":"2025-09-27T06:57:29.168Z","last_update":"2026-04-13T18:58:26.411Z","language":2,"uuid":"8982311d-55fd-4744-a35c-d53ac00c28f0","exercise":1639}},{"model":"exercises.translation","pk":2746,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"AlucardEvil40","license_author_url":"","license_derivative_source_url":"","description":"<p><strong>Cet exercice consiste à utiliser des haltères pour effectuer un \"face pull penché en avant\" (bent over face pull), qui cible le haut du dos et les épaules. Le mouvement implique de tirer les poids vers le visage tout en gardant les coudes hauts et en serrant les omoplates l''une contre l''autre.</strong></p>\n","description_source":"**Cet exercice consiste à utiliser des haltères pour effectuer un \"face pull penché en avant\" (bent over face pull), qui cible le haut du dos et les épaules. Le mouvement implique de tirer les poids vers le visage tout en gardant les coudes hauts et en serrant les omoplates l''une contre l''autre.**","name":"Tirage facial avec haltères buste penché","created":"2025-09-27T06:57:29.526Z","last_update":"2026-04-13T18:58:27.652Z","language":12,"uuid":"60c4a893-2b01-4a43-8d47-f7078c57dc56","exercise":1639}}],"aliases":[],"comments":[]}'),
('wger', '1640', 'dumbbell-front-squat', 'https://wger.de/en/exercise/1640/view', 'CC-BY-SA-4.0', 'AlucardEvil40', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1640,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"AlucardEvil40","license_author_url":"","license_derivative_source_url":"","uuid":"4621b41f-0d32-4033-acff-dc079c792606","category":9,"variation_group":null,"created":"2025-09-27T07:40:14.127Z","last_update":"2025-09-27T07:40:14.127Z","muscles":[8,10],"muscles_secondary":[2,6],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2747,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"AlucardEvil40","license_author_url":"","license_derivative_source_url":"","description":"<p>This exercise involves holding a dumbbell in each hand at shoulder height and performing a squat. It targets the lower body muscles, including the quads, hamstrings, and glutes, while also engaging the core and upper body.</p>\n","description_source":"This exercise involves holding a dumbbell in each hand at shoulder height and performing a squat. It targets the lower body muscles, including the quads, hamstrings, and glutes, while also engaging the core and upper body.","name":"Dumbbell Front Squat","created":"2025-09-27T07:40:14.338Z","last_update":"2026-04-13T18:58:26.420Z","language":2,"uuid":"828f1fa9-868d-46a3-979c-463cde2b071f","exercise":1640}},{"model":"exercises.translation","pk":2748,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"AlucardEvil40","license_author_url":"","license_derivative_source_url":"","description":"<p><strong>Cet exercice consiste à tenir un haltère dans chaque main à hauteur d''épaule et à effectuer un squat. Il cible les muscles du bas du corps, notamment les quadriceps, les ischio-jambiers et les fessiers, tout en engageant également le tronc (le <em>core</em>) et le haut du corps.</strong></p>\n","description_source":"**Cet exercice consiste à tenir un haltère dans chaque main à hauteur d''épaule et à effectuer un squat. Il cible les muscles du bas du corps, notamment les quadriceps, les ischio-jambiers et les fessiers, tout en engageant également le tronc (le *core*) et le haut du corps.**","name":"Squat avant avec haltères","created":"2025-09-27T07:40:14.618Z","last_update":"2026-04-13T18:58:27.485Z","language":12,"uuid":"f13f448e-8594-4e3a-a819-eb74193d2c30","exercise":1640}}],"aliases":[],"comments":[]}'),
('wger', '1641', 'kettlebell-one-legged-deadlift', 'https://wger.de/en/exercise/1641/view', 'CC-BY-SA-4.0', 'AlucardEvil40', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1641,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"AlucardEvil40","license_author_url":"","license_derivative_source_url":"","uuid":"20b17b71-6d91-4b56-978a-04b7f94c04cc","category":9,"variation_group":null,"created":"2025-09-27T08:05:01.224Z","last_update":"2025-09-27T08:05:01.224Z","muscles":[8],"muscles_secondary":[],"equipment":[3,10]}},"translations":[{"model":"exercises.translation","pk":2749,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"AlucardEvil40","license_author_url":"","license_derivative_source_url":"","description":"<p>This exercise involves holding a kettlebell in one hand and standing on one leg while bending forward to touch the kettlebell to the ground. It targets the hamstrings, glutes, and lower back while also improving balance and stability.</p>\n","description_source":"This exercise involves holding a kettlebell in one hand and standing on one leg while bending forward to touch the kettlebell to the ground. It targets the hamstrings, glutes, and lower back while also improving balance and stability.","name":"Kettlebell One Legged Deadlift","created":"2025-09-27T08:05:01.391Z","last_update":"2026-04-13T18:58:26.706Z","language":2,"uuid":"bc0bfa07-eac1-423b-819c-9c6753efcd21","exercise":1641}},{"model":"exercises.translation","pk":2750,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"AlucardEvil40","license_author_url":"","license_derivative_source_url":"","description":"<p><strong>Cet exercice consiste à tenir un <em>kettlebell</em> (ou une <em>cloche</em>) dans une main et à se tenir sur une jambe tout en se penchant vers l''avant pour toucher le sol avec le <em>kettlebell</em>. Il cible les ischio-jambiers, les fessiers et le bas du dos, tout en améliorant également l''équilibre et la stabilité.</strong></p>\n","description_source":"**Cet exercice consiste à tenir un *kettlebell* (ou une *cloche*) dans une main et à se tenir sur une jambe tout en se penchant vers l''avant pour toucher le sol avec le *kettlebell*. Il cible les ischio-jambiers, les fessiers et le bas du dos, tout en améliorant également l''équilibre et la stabilité.**","name":"Soulevé de terre unilatéral","created":"2025-09-27T08:05:01.638Z","last_update":"2026-04-13T18:58:27.453Z","language":12,"uuid":"56334442-1627-41b8-8071-b2213bea1bd6","exercise":1641}}],"aliases":[],"comments":[]}'),
('wger', '1642', 'dumbbell-hip-thrust', 'https://wger.de/en/exercise/1642/view', 'CC-BY-SA-4.0', 'AlucardEvil40', 'exact', 100.0, '{"exercise":{"model":"exercises.exercise","pk":1642,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"AlucardEvil40","license_author_url":"","license_derivative_source_url":"","uuid":"af77220c-098c-47c2-9f8c-92a651998903","category":9,"variation_group":null,"created":"2025-09-27T08:10:37.930Z","last_update":"2025-09-27T08:10:37.930Z","muscles":[8,10],"muscles_secondary":[],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2751,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"AlucardEvil40","license_author_url":"","license_derivative_source_url":"","description":"<p>This exercise involves sitting on the ground with a dumbbell resting on the hips, then thrusting the hips upward while squeezing the glutes. It is a great exercise for strengthening the glutes and improving hip mobility.</p>\n","description_source":"This exercise involves sitting on the ground with a dumbbell resting on the hips, then thrusting the hips upward while squeezing the glutes. It is a great exercise for strengthening the glutes and improving hip mobility.","name":"Dumbbell Hip Thrust","created":"2025-09-27T08:10:38.129Z","last_update":"2026-04-13T18:58:26.423Z","language":2,"uuid":"2f38fa5e-c20b-46a6-9c73-0e903a5d5736","exercise":1642}},{"model":"exercises.translation","pk":2752,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"AlucardEvil40","license_author_url":"","license_derivative_source_url":"","description":"<p><strong>Cet exercice consiste à s''asseoir sur le sol avec un haltère posé sur les hanches, puis à pousser les hanches vers le haut tout en contractant les fessiers. C''est un excellent exercice pour renforcer les fessiers et améliorer la mobilité des hanches.</strong></p>\n","description_source":"**Cet exercice consiste à s''asseoir sur le sol avec un haltère posé sur les hanches, puis à pousser les hanches vers le haut tout en contractant les fessiers. C''est un excellent exercice pour renforcer les fessiers et améliorer la mobilité des hanches.**","name":"Hip Thrust avec haltère","created":"2025-09-27T08:10:38.467Z","last_update":"2026-04-13T18:58:26.634Z","language":12,"uuid":"96c955a1-86e3-4356-a41f-05139855196e","exercise":1642}}],"aliases":[],"comments":[]}'),
('wger', '1643', 'dumbbell-incline-fly', 'https://wger.de/en/exercise/1643/view', 'CC-BY-SA-4.0', 'AlucardEvil40', 'normalized', 100.0, '{"exercise":{"model":"exercises.exercise","pk":1643,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"AlucardEvil40","license_author_url":"","license_derivative_source_url":"","uuid":"965eb23f-761c-45cd-bb7b-07d4d77040f1","category":11,"variation_group":null,"created":"2025-09-27T08:23:42.059Z","last_update":"2025-09-27T08:23:42.059Z","muscles":[4],"muscles_secondary":[],"equipment":[3,9]}},"translations":[{"model":"exercises.translation","pk":2753,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"AlucardEvil40","license_author_url":"","license_derivative_source_url":"","description":"<p>This exercise involves lying on an incline bench and holding dumbbells in each hand. The arms are then extended out to the sides, parallel to the ground, and then brought back together in a hugging motion. This exercise primarily targets the chest muscles.</p>\n","description_source":"This exercise involves lying on an incline bench and holding dumbbells in each hand. The arms are then extended out to the sides, parallel to the ground, and then brought back together in a hugging motion. This exercise primarily targets the chest muscles.","name":"Dumbbell Incline Fly","created":"2025-09-27T08:23:42.243Z","last_update":"2026-04-13T18:58:26.426Z","language":2,"uuid":"78b59647-1b44-4264-9e8e-b2df3af6a8fc","exercise":1643}},{"model":"exercises.translation","pk":2754,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"AlucardEvil40","license_author_url":"","license_derivative_source_url":"","description":"<p><strong>Cet exercice consiste à s''allonger sur un banc incliné et à tenir un haltère dans chaque main. Les bras sont ensuite étendus sur les côtés, parallèlement au sol, puis ramenés l''un vers l''autre dans un mouvement d''étreinte (ou d''enveloppement). Cet exercice cible principalement les muscles de la poitrine.</strong></p>\n","description_source":"**Cet exercice consiste à s''allonger sur un banc incliné et à tenir un haltère dans chaque main. Les bras sont ensuite étendus sur les côtés, parallèlement au sol, puis ramenés l''un vers l''autre dans un mouvement d''étreinte (ou d''enveloppement). Cet exercice cible principalement les muscles de la poitrine.**","name":"Écarté incliné avec haltères","created":"2025-09-27T08:23:42.517Z","last_update":"2026-04-13T18:58:27.972Z","language":12,"uuid":"df4f16dd-ca85-4315-9947-506e8d3d51b3","exercise":1643}}],"aliases":[],"comments":[]}'),
('wger', '1645', 'dumbbell-shrug', 'https://wger.de/en/exercise/1645/view', 'CC-BY-SA-4.0', 'AlucardEvil40', 'exact', 100.0, '{"exercise":{"model":"exercises.exercise","pk":1645,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"AlucardEvil40","license_author_url":"","license_derivative_source_url":"","uuid":"41213cc0-f8d7-4b20-998a-f22deacfc83a","category":13,"variation_group":null,"created":"2025-09-27T08:37:34.274Z","last_update":"2025-09-27T08:37:34.274Z","muscles":[],"muscles_secondary":[],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2757,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"AlucardEvil40","license_author_url":"","license_derivative_source_url":"","description":"<p>This exercise involves holding a dumbbell in each hand and shrugging your shoulders up towards your ears, then lowering them back down. It primarily targets the trapezius muscles in the upper back and can help improve posture and shoulder stability.</p>\n","description_source":"This exercise involves holding a dumbbell in each hand and shrugging your shoulders up towards your ears, then lowering them back down. It primarily targets the trapezius muscles in the upper back and can help improve posture and shoulder stability.","name":"Dumbbell Shrug","created":"2025-09-27T08:37:34.451Z","last_update":"2026-04-13T18:58:26.437Z","language":2,"uuid":"46fbe9ca-988c-437e-acab-e5ec269153d9","exercise":1645}},{"model":"exercises.translation","pk":2758,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"AlucardEvil40","license_author_url":"","license_derivative_source_url":"","description":"<p><strong>Cet exercice consiste à tenir un haltère dans chaque main et à hausser les épaules vers les oreilles, puis à les redescendre. Il cible principalement les muscles trapèzes dans le haut du dos et peut aider à améliorer la posture ainsi que la stabilité de l''épaule.</strong></p>\n","description_source":"**Cet exercice consiste à tenir un haltère dans chaque main et à hausser les épaules vers les oreilles, puis à les redescendre. Il cible principalement les muscles trapèzes dans le haut du dos et peut aider à améliorer la posture ainsi que la stabilité de l''épaule.**","name":"Shrug avec haltères","created":"2025-09-27T08:37:34.746Z","last_update":"2026-04-13T18:58:27.361Z","language":12,"uuid":"96030fb1-52af-47c4-b215-19610b6a2f96","exercise":1645}}],"aliases":[],"comments":[]}'),
('wger', '1648', 'dumbbell-weighted-crunch', 'https://wger.de/en/exercise/1648/view', 'CC-BY-SA-4.0', 'AlucardEvil40', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1648,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"AlucardEvil40","license_author_url":"","license_derivative_source_url":"","uuid":"8d333b94-148c-48f8-9154-8b13279500d1","category":10,"variation_group":null,"created":"2025-09-27T08:47:40.056Z","last_update":"2025-09-27T08:47:40.056Z","muscles":[14],"muscles_secondary":[],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2759,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"AlucardEvil40","license_author_url":"","license_derivative_source_url":"","description":"<p>The Weighted Crunch is a variation of the classic crunch exercise that involves adding resistance (a weight) to increase the intensity of the abdominal work.</p>\n<ol>\n<li>Lay down</li>\n<li>(Optional) Bend your knees to add difficulty</li>\n<li>(Optional) Bend your knees and let your feet rest on a bench or a box or something (90 degree angle on knees)</li>\n<li>Lift your head and torso <strong>while bending your back forward</strong> (if you don''t it''s a sit-up and also involves some back muscles). The higher you go, the more you should feel your abs contracting.</li>\n<li>Go back to starting position an repeat</li>\n</ol>\n","description_source":"The Weighted Crunch is a variation of the classic crunch exercise that involves adding resistance (a weight) to increase the intensity of the abdominal work.\n\n1. Lay down\n2. (Optional) Bend your knees to add difficulty\n3. (Optional) Bend your knees and let your feet rest on a bench or a box or something (90 degree angle on knees)\n4. Lift your head and torso **while bending your back forward** (if you don''t it''s a sit-up and also involves some back muscles). The higher you go, the more you should feel your abs contracting.\n5. Go back to starting position an repeat","name":"Weighted Crunch","created":"2025-09-27T08:47:40.234Z","last_update":"2026-04-13T18:58:27.859Z","language":2,"uuid":"67e34e0e-9b1b-4736-b3a2-6e42b56847b6","exercise":1648}},{"model":"exercises.translation","pk":2760,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"AlucardEvil40","license_author_url":"","license_derivative_source_url":"","description":"<p>Le Crunch lesté cible principalement les <strong>grands droits de l''abdomen</strong> (les fameuses \"tablettes de chocolat\").</p>\n","description_source":"Le Crunch lesté cible principalement les **grands droits de l''abdomen** (les fameuses \"tablettes de chocolat\").","name":"Crunch lesté","created":"2025-09-27T08:47:40.534Z","last_update":"2026-04-13T18:58:26.249Z","language":12,"uuid":"1ff2bef0-569d-4e45-846a-80949cad275e","exercise":1648}}],"aliases":[],"comments":[]}'),
('wger', '1649', 'dumbbell-concentration-curl', 'https://wger.de/en/exercise/1649/view', 'CC-BY-SA-4.0', 'AlucardEvil40', 'normalized', 100.0, '{"exercise":{"model":"exercises.exercise","pk":1649,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"AlucardEvil40","license_author_url":"","license_derivative_source_url":"","uuid":"7adca809-0fbb-4785-bcd3-d512e2c49888","category":8,"variation_group":null,"created":"2025-09-27T09:07:04.506Z","last_update":"2025-09-27T09:07:04.506Z","muscles":[1],"muscles_secondary":[],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2764,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"AlucardEvil40","license_author_url":"","license_derivative_source_url":"","description":"<p>This exercise involves holding a dumbbell in one hand and curling it towards the shoulder while keeping the upper arm stationary. It primarily targets the biceps muscle.</p>\n","description_source":"This exercise involves holding a dumbbell in one hand and curling it towards the shoulder while keeping the upper arm stationary. It primarily targets the biceps muscle.","name":"Concentration Curl","created":"2025-09-27T09:07:04.695Z","last_update":"2026-04-13T18:58:26.222Z","language":2,"uuid":"783dc486-2e5d-4259-ab20-7175bdc296b4","exercise":1649}},{"model":"exercises.translation","pk":2765,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"AlucardEvil40","license_author_url":"","license_derivative_source_url":"","description":"<p><strong>Cet exercice consiste à tenir un haltère dans une main et à le lever (ou le \"curler\") vers l''épaule tout en gardant le haut du bras immobile. Il cible principalement le muscle biceps.</strong></p>\n","description_source":"**Cet exercice consiste à tenir un haltère dans une main et à le lever (ou le \"curler\") vers l''épaule tout en gardant le haut du bras immobile. Il cible principalement le muscle biceps.**","name":"Curl biceps avec haltère","created":"2025-09-27T09:07:04.978Z","last_update":"2026-04-13T18:58:26.267Z","language":12,"uuid":"9bfee84e-cf05-4231-9a1c-bb6f2f070884","exercise":1649}}],"aliases":[],"comments":[]}'),
('wger', '1650', 'dumbbell-side-bend', 'https://wger.de/en/exercise/1650/view', 'CC-BY-SA-4.0', 'AlucardEvil40', 'new', 100.0, '{"exercise":{"model":"exercises.exercise","pk":1650,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"AlucardEvil40","license_author_url":"","license_derivative_source_url":"","uuid":"3e9b3bb0-7958-4836-89a5-ed0c5f7eeb03","category":10,"variation_group":null,"created":"2025-09-27T09:26:25.055Z","last_update":"2025-09-27T09:26:25.055Z","muscles":[14],"muscles_secondary":[],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2766,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"AlucardEvil40","license_author_url":"","license_derivative_source_url":"","description":"<p>This exercise involves holding a dumbbell in one hand and bending sideways to work the oblique muscles on the side of the body. It can be done standing or seated and is often used as a core strengthening exercise.</p>\n","description_source":"This exercise involves holding a dumbbell in one hand and bending sideways to work the oblique muscles on the side of the body. It can be done standing or seated and is often used as a core strengthening exercise.","name":"Dumbbell Side Bend","created":"2025-09-27T09:26:25.237Z","last_update":"2026-04-13T18:58:26.438Z","language":2,"uuid":"e83a8972-e7ca-4870-adc4-91d1e11a15ac","exercise":1650}},{"model":"exercises.translation","pk":2767,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"AlucardEvil40","license_author_url":"","license_derivative_source_url":"","description":"<p>Cet exercice consiste à tenir un <strong>haltère</strong> dans une main et à se pencher sur le côté pour travailler les <strong>muscles obliques</strong> sur le flanc du corps. Il peut être effectué <strong>debout</strong> ou <strong>assis</strong> et est souvent utilisé comme exercice de <strong>renforcement du tronc</strong> (<em>core strengthening</em>).</p>\n","description_source":"Cet exercice consiste à tenir un **haltère** dans une main et à se pencher sur le côté pour travailler les **muscles obliques** sur le flanc du corps. Il peut être effectué **debout** ou **assis** et est souvent utilisé comme exercice de **renforcement du tronc** (*core strengthening*).","name":"Flexion Latérale avec haltère","created":"2025-09-27T09:26:25.489Z","last_update":"2026-04-13T18:58:26.532Z","language":12,"uuid":"b879e19d-dcca-4f95-8cdc-5afff4154219","exercise":1650}}],"aliases":[],"comments":[]}'),
('wger', '1651', 'dumbbell-rear-lunge', 'https://wger.de/en/exercise/1651/view', 'CC-BY-SA-4.0', 'AlucardEvil40', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1651,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"AlucardEvil40","license_author_url":"","license_derivative_source_url":"","uuid":"75e34967-b0ec-40d5-811e-b474b234a7a9","category":9,"variation_group":null,"created":"2025-09-27T09:31:29.393Z","last_update":"2025-09-27T09:31:29.393Z","muscles":[8,10],"muscles_secondary":[15],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2768,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"AlucardEvil40","license_author_url":"","license_derivative_source_url":"","description":"<p>This exercise involves holding a dumbbell in each hand and stepping back into a lunge position, then returning to standing. It primarily targets the glutes, hamstrings, and quadriceps.</p>\n","description_source":"This exercise involves holding a dumbbell in each hand and stepping back into a lunge position, then returning to standing. It primarily targets the glutes, hamstrings, and quadriceps.","name":"Dumbbell Rear Lunge","created":"2025-09-27T09:31:29.574Z","last_update":"2026-04-13T18:58:26.430Z","language":2,"uuid":"97d49605-0075-4342-9f30-95d68e090d63","exercise":1651}},{"model":"exercises.translation","pk":2769,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"AlucardEvil40","license_author_url":"","license_derivative_source_url":"","description":"<p>Cet exercice consiste à tenir un <strong>haltère</strong> dans chaque main et à reculer pour se mettre en position de <strong>fente</strong> (<em>lunge</em>), puis à revenir à la position debout. Il cible principalement les <strong>fessiers</strong>, les <strong>ischio-jambiers</strong> et les <strong>quadriceps</strong>.</p>\n","description_source":"Cet exercice consiste à tenir un **haltère** dans chaque main et à reculer pour se mettre en position de **fente** (*lunge*), puis à revenir à la position debout. Il cible principalement les **fessiers**, les **ischio-jambiers** et les **quadriceps**.","name":"Fente arrière avec haltères","created":"2025-09-27T09:31:29.836Z","last_update":"2026-04-13T18:58:26.521Z","language":12,"uuid":"7125c8a4-7997-4c5b-af20-127c7802c8d2","exercise":1651}}],"aliases":[],"comments":[]}'),
('wger', '1652', 'dumbbell-romanian-deadlift', 'https://wger.de/en/exercise/1652/view', 'CC-BY-SA-4.0', 'AlucardEvil40', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1652,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"AlucardEvil40","license_author_url":"","license_derivative_source_url":"","uuid":"65d12ecf-54b8-466d-a412-e55c396cad69","category":9,"variation_group":"ad96df0d-30be-46ea-887f-606642c2f13b","created":"2025-09-27T09:38:44.466Z","last_update":"2025-12-07T10:53:51.154Z","muscles":[11,8],"muscles_secondary":[],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2770,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"AlucardEvil40","license_author_url":"","license_derivative_source_url":"","description":"<p>This exercise involves holding a dumbbell in each hand and bending forward at the hips while keeping the back straight, then returning to a standing position. It primarily targets the hamstrings and glutes.</p>\n","description_source":"This exercise involves holding a dumbbell in each hand and bending forward at the hips while keeping the back straight, then returning to a standing position. It primarily targets the hamstrings and glutes.","name":"Dumbbell Romanian Deadlift","created":"2025-09-27T09:38:44.638Z","last_update":"2026-04-13T18:58:26.431Z","language":2,"uuid":"002e5114-597e-43ac-a1aa-b0f7926382da","exercise":1652}},{"model":"exercises.translation","pk":2771,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"AlucardEvil40","license_author_url":"","license_derivative_source_url":"","description":"<p>Cet exercice consiste à tenir un <strong>haltère</strong> dans chaque main et à se pencher vers l''avant au niveau des <strong>hanches</strong> tout en gardant le <strong>dos droit</strong>, puis à revenir à la position debout. Il cible principalement les <strong>ischio-jambiers</strong> et les <strong>fessiers</strong>.</p>\n","description_source":"Cet exercice consiste à tenir un **haltère** dans chaque main et à se pencher vers l''avant au niveau des **hanches** tout en gardant le **dos droit**, puis à revenir à la position debout. Il cible principalement les **ischio-jambiers** et les **fessiers**.","name":"Soulevé de terre roumain avec haltères","created":"2025-09-27T09:38:44.930Z","last_update":"2026-04-13T18:58:27.452Z","language":12,"uuid":"71f4c08f-4086-4d7d-ad1a-f713fef0302e","exercise":1652}}],"aliases":[],"comments":[]}'),
('wger', '1653', 'dumbbell-side-squat', 'https://wger.de/en/exercise/1653/view', 'CC-BY-SA-4.0', 'AlucardEvil40', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1653,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"AlucardEvil40","license_author_url":"","license_derivative_source_url":"","uuid":"412ba9ab-ae29-4411-9bbc-74af1263494c","category":9,"variation_group":null,"created":"2025-09-27T09:49:03.528Z","last_update":"2025-09-27T09:49:03.528Z","muscles":[8,10],"muscles_secondary":[11],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2772,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"AlucardEvil40","license_author_url":"","license_derivative_source_url":"","description":"<p>This exercise involves holding a dumbbell in one hand and performing a squat while stepping to the side. It targets the legs, glutes, and core muscles.</p>\n","description_source":"This exercise involves holding a dumbbell in one hand and performing a squat while stepping to the side. It targets the legs, glutes, and core muscles.","name":"Dumbbell Side Squat","created":"2025-09-27T09:49:03.714Z","last_update":"2026-04-13T18:58:26.438Z","language":2,"uuid":"5327bf9a-c362-43b1-afe3-1a6b4b22d15b","exercise":1653}},{"model":"exercises.translation","pk":2773,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"AlucardEvil40","license_author_url":"","license_derivative_source_url":"","description":"<p>Cet exercice consiste à tenir un <strong>haltère</strong> dans une main et à effectuer un <strong>squat</strong> tout en faisant un <strong>pas latéral</strong> (<em>step to the side</em>). Il cible les <strong>jambes</strong>, les <strong>fessiers</strong> et les <strong>muscles du tronc</strong> (<em>core muscles</em>).</p>\n","description_source":"Cet exercice consiste à tenir un **haltère** dans une main et à effectuer un **squat** tout en faisant un **pas latéral** (*step to the side*). Il cible les **jambes**, les **fessiers** et les **muscles du tronc** (*core muscles*).","name":"Squat latéral avec haltère","created":"2025-09-27T09:49:04.002Z","last_update":"2026-04-13T18:58:27.497Z","language":12,"uuid":"d1e1a069-ad6f-478e-8ccb-20918eaab386","exercise":1653}}],"aliases":[],"comments":[]}'),
('wger', '1654', 'machine-lateral-wise', 'https://wger.de/en/exercise/1654/view', 'CC-BY-SA-4.0', 'roneydya', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1654,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"roneydya","license_author_url":"","license_derivative_source_url":"","uuid":"3d2adf99-8fe9-45cb-b669-c5b18242e282","category":13,"variation_group":null,"created":"2025-09-27T13:45:33.269Z","last_update":"2025-09-27T13:45:33.269Z","muscles":[2],"muscles_secondary":[],"equipment":[4]}},"translations":[{"model":"exercises.translation","pk":2774,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"roneydya","license_author_url":"","license_derivative_source_url":"","description":"<p>The machine lateral raise is an isolation exercise that targets the medial (side) deltoid muscle to build wider, more defined shoulders. The machine''s fixed path of motion provides greater stability than dumbbells, making it ideal for beginners or those who want to focus solely on muscle activation.</p>\n","description_source":"The machine lateral raise is an isolation exercise that targets the medial (side) deltoid muscle to build wider, more defined shoulders. The machine''s fixed path of motion provides greater stability than dumbbells, making it ideal for beginners or those who want to focus solely on muscle activation.","name":"Machine lateral wise","created":"2025-09-27T13:45:33.617Z","last_update":"2026-04-13T18:58:26.836Z","language":2,"uuid":"dcc51a0a-d9ec-47b8-96a8-cbef4ae2d388","exercise":1654}},{"model":"exercises.translation","pk":2775,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"roneydya","license_author_url":"","license_derivative_source_url":"","description":"<p>A elevação lateral na máquina é um exercício isolado que trabalha o músculo deltoide medial (lateral) para construir ombros mais largos e definidos. O caminho de movimento fixo da máquina proporciona maior estabilidade do que com halteres, tornando-a ideal para iniciantes ou para aqueles que desejam se concentrar apenas na ativação muscular.</p>\n","description_source":"A elevação lateral na máquina é um exercício isolado que trabalha o músculo deltoide medial (lateral) para construir ombros mais largos e definidos. O caminho de movimento fixo da máquina proporciona maior estabilidade do que com halteres, tornando-a ideal para iniciantes ou para aqueles que desejam se concentrar apenas na ativação muscular.","name":"Elevação lateral na mãquina","created":"2025-09-27T13:45:34.454Z","last_update":"2026-04-13T18:58:26.485Z","language":7,"uuid":"bcb248f9-60ae-46f9-8508-03d9ab24883c","exercise":1654}}],"aliases":[],"comments":[]}'),
('wger', '1655', 'machine-chest-press-exercise', 'https://wger.de/en/exercise/1655/view', 'CC-BY-SA-4.0', 'roneydya', 'new', 100.0, '{"exercise":{"model":"exercises.exercise","pk":1655,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"roneydya","license_author_url":"","license_derivative_source_url":"","uuid":"c4aca20e-9591-425f-85a8-0ab04cd1515d","category":11,"variation_group":null,"created":"2025-09-27T17:07:24.198Z","last_update":"2025-09-27T17:07:24.198Z","muscles":[4],"muscles_secondary":[5],"equipment":[4]}},"translations":[{"model":"exercises.translation","pk":2776,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"roneydya","license_author_url":"","license_derivative_source_url":"","description":"<p>. It provides an effective but straightforward way to work your upper body. With no weights to balance and no tricky techniques to master, the chest press leaves you free to focus on your training.</p>\n","description_source":". It provides an effective but straightforward way to work your upper body. With no weights to balance and no tricky techniques to master, the chest press leaves you free to focus on your training.","name":"Machine Chest Press Exercise","created":"2025-09-27T17:07:24.550Z","last_update":"2026-04-13T18:58:26.831Z","language":2,"uuid":"d25750cc-eaf3-47ad-81f3-85367f1fac07","exercise":1655}}],"aliases":[],"comments":[]}'),
('wger', '1656', 'cable-chest-press-decline', 'https://wger.de/en/exercise/1656/view', 'CC-BY-SA-4.0', 'Shiladree', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1656,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Shiladree","license_author_url":"","license_derivative_source_url":"","uuid":"b2865908-b93e-4507-ada4-a5bb9317566c","category":11,"variation_group":null,"created":"2025-09-27T22:30:48.212Z","last_update":"2025-09-27T22:30:48.212Z","muscles":[4],"muscles_secondary":[5],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2777,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Shiladree","license_author_url":"","license_derivative_source_url":"","description":"<p>Single arm chest press done with the cable machine. Use the other arm to brace bodyweight to focus on strength of the press, rather than balancing of the body. Start with the hand as close to the chest as possible, and then press against the cable at a slight decline and aiming towards the center of your chest.</p>\n","description_source":"Single arm chest press done with the cable machine. Use the other arm to brace bodyweight to focus on strength of the press, rather than balancing of the body. Start with the hand as close to the chest as possible, and then press against the cable at a slight decline and aiming towards the center of your chest.  ","name":"Cable Chest Press - Decline","created":"2025-09-27T22:30:48.554Z","last_update":"2026-04-13T18:58:26.168Z","language":2,"uuid":"ceaf8d4c-479a-418a-b110-d4a52a1ace59","exercise":1656}}],"aliases":[],"comments":[]}'),
('wger', '1657', 'dumbbell-preacher-curl-internally-rotated', 'https://wger.de/en/exercise/1657/view', 'CC-BY-SA-4.0', 'Shiladree', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1657,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Shiladree","license_author_url":"","license_derivative_source_url":"","uuid":"4baa4962-64bd-434f-b2ed-0c3c88099841","category":8,"variation_group":null,"created":"2025-09-27T22:47:16.349Z","last_update":"2025-09-27T22:47:16.349Z","muscles":[1],"muscles_secondary":[],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2778,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Shiladree","license_author_url":"","license_derivative_source_url":"","description":"<p>Single arm curl that can be done using a dumbbell and a preacher bench, or a preacher curl machine. Turn body towards the weight</p>\n","description_source":"Single arm curl that can be done using a dumbbell and a preacher bench, or a preacher curl machine. Turn body towards the weight ","name":"Preacher Curl - Internally Rotated","created":"2025-09-27T22:47:16.630Z","last_update":"2026-04-13T18:58:26.997Z","language":2,"uuid":"03176122-84d1-4a49-a783-aa0d9ff4dda2","exercise":1657}}],"aliases":[],"comments":[]}'),
('wger', '1658', 'dumbbell-preacher-curl-externally-rotated', 'https://wger.de/en/exercise/1658/view', 'CC-BY-SA-4.0', 'Shiladree', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1658,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Shiladree","license_author_url":"","license_derivative_source_url":"","uuid":"7cd76565-8a8f-4658-98f1-253af9d8bb39","category":8,"variation_group":null,"created":"2025-09-27T22:49:04.150Z","last_update":"2025-09-27T22:49:04.150Z","muscles":[1],"muscles_secondary":[],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2779,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Shiladree","license_author_url":"","license_derivative_source_url":"","description":"<p>Single arm curl that can be done using a dumbbell and a preacher bench, or a preacher curl machine. Turn body away from the weight</p>\n","description_source":"Single arm curl that can be done using a dumbbell and a preacher bench, or a preacher curl machine. Turn body away from the weight ","name":"Preacher Curl - Externally Rotated","created":"2025-09-27T22:49:04.430Z","last_update":"2026-04-13T18:58:26.995Z","language":2,"uuid":"36452749-48f8-4edc-9541-9afdc2b5d50a","exercise":1658}}],"aliases":[],"comments":[]}'),
('wger', '1659', 'lat-pulldown-cross-body-single-arm', 'https://wger.de/en/exercise/1659/view', 'CC-BY-SA-4.0', 'Shiladree', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1659,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Shiladree","license_author_url":"","license_derivative_source_url":"","uuid":"5a096571-4eae-472e-8849-fe5647035e2c","category":12,"variation_group":null,"created":"2025-09-27T23:22:25.434Z","last_update":"2025-09-27T23:22:25.434Z","muscles":[12],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2780,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Shiladree","license_author_url":"","license_derivative_source_url":"","description":"<p>Sit at lat pulldown machine with body at a diagonal angle so that only one leg is under the pad. Pull the cable down with the opposite arm. this will force the cable to across your body while pulling down. Emphasises the stretch of the lat.</p>\n","description_source":"Sit at lat pulldown machine with body at a diagonal angle so that only one leg is under the pad. Pull the cable down with the opposite arm. this will force the cable to across your body while pulling down. Emphasises the stretch of the lat. ","name":"Lat Pulldown - Cross Body Single Arm","created":"2025-09-27T23:22:25.712Z","last_update":"2026-04-13T18:58:26.761Z","language":2,"uuid":"36cf38c3-9130-4350-bb13-021127c41699","exercise":1659}}],"aliases":[],"comments":[]}'),
('wger', '1660', 'cable-chest-press-incline', 'https://wger.de/en/exercise/1660/view', 'CC-BY-SA-4.0', 'Shiladree', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1660,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Shiladree","license_author_url":"","license_derivative_source_url":"","uuid":"e22c4320-7753-49c6-b7f7-4be21b025fb6","category":11,"variation_group":null,"created":"2025-09-27T23:24:25.871Z","last_update":"2025-09-27T23:24:25.871Z","muscles":[4],"muscles_secondary":[5],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2781,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Shiladree","license_author_url":"","license_derivative_source_url":"","description":"<p>Single arm chest press done with the cable machine. Use the other arm to brace bodyweight to focus on strength of the press, rather than balancing of the body. Start with the hand as close to the chest as possible, and then press against the cable at a slight incline and aiming towards the center of your chest.</p>\n","description_source":"Single arm chest press done with the cable machine. Use the other arm to brace bodyweight to focus on strength of the press, rather than balancing of the body. Start with the hand as close to the chest as possible, and then press against the cable at a slight incline and aiming towards the center of your chest.  ","name":"Cable Chest Press - Incline","created":"2025-09-27T23:24:26.196Z","last_update":"2026-04-13T18:58:26.169Z","language":2,"uuid":"724a86c5-d569-4f21-a6b2-cc0bbb265ae3","exercise":1660}}],"aliases":[],"comments":[]}'),
('wger', '1661', 'cable-triceps-press', 'https://wger.de/en/exercise/1661/view', 'CC-BY-SA-4.0', 'Shiladree', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1661,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Shiladree","license_author_url":"","license_derivative_source_url":"","uuid":"5aee8ae1-2752-4868-af62-e3c79954d811","category":8,"variation_group":null,"created":"2025-09-27T23:53:28.150Z","last_update":"2025-09-27T23:53:28.150Z","muscles":[5],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2782,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Shiladree","license_author_url":"","license_derivative_source_url":"","description":"<p>A single arm exercise that starts with the hand close to the chest with with the elbows bent, and the elbow flared out. Press forward and down against the cable straightening the elbow.</p>\n","description_source":"A single arm exercise that starts with the hand close to the chest with with the elbows bent, and the elbow flared out. Press forward and down against the cable straightening the elbow.","name":"Cable Triceps Press","created":"2025-09-27T23:53:28.434Z","last_update":"2026-04-13T18:58:26.185Z","language":2,"uuid":"a3656e5c-426f-4fdc-a667-c590e5e9a6d3","exercise":1661}}],"aliases":[],"comments":[]}'),
('wger', '1662', 'cable-tri-extension-internal-rotation', 'https://wger.de/en/exercise/1662/view', 'CC-BY-SA-4.0', 'Shiladree', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1662,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Shiladree","license_author_url":"","license_derivative_source_url":"","uuid":"07ded945-de5d-4e77-b13c-17d51a2f0007","category":8,"variation_group":null,"created":"2025-09-28T00:02:50.238Z","last_update":"2025-09-28T00:02:50.238Z","muscles":[5],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2783,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Shiladree","license_author_url":"","license_derivative_source_url":"","description":"<p>single arm exercise with cable held at opposite shoulder with elbow bent. Turn towards the cable, and the straighten the elbow across the body.</p>\n","description_source":"single arm exercise with cable held at opposite shoulder with elbow bent. Turn towards the cable, and the straighten the elbow across the body. ","name":"Cable Tri Extension - Internal Rotation","created":"2025-09-28T00:02:50.583Z","last_update":"2026-04-13T18:58:26.184Z","language":2,"uuid":"309d24f0-99af-4734-b882-272e2a1414b4","exercise":1662}}],"aliases":[],"comments":[]}'),
('wger', '1665', 'cable-tri-extension-external-rotation', 'https://wger.de/en/exercise/1665/view', 'CC-BY-SA-4.0', 'Shiladree', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1665,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Shiladree","license_author_url":"","license_derivative_source_url":"","uuid":"4c8cf398-b400-46dc-89b4-94bb478f4ea9","category":8,"variation_group":null,"created":"2025-09-28T13:44:27.700Z","last_update":"2025-09-28T13:44:27.700Z","muscles":[5],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2784,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Shiladree","license_author_url":"","license_derivative_source_url":"","description":"<p>single arm exercise with cable held at opposite shoulder with elbow bent. Turn away from the cable, and the straighten the elbow across the body.</p>\n","description_source":"single arm exercise with cable held at opposite shoulder with elbow bent. Turn away from the cable, and the straighten the elbow across the body. ","name":"Cable Tri Extension - External Rotation","created":"2025-09-28T13:44:27.966Z","last_update":"2026-04-13T18:58:26.183Z","language":2,"uuid":"d0c4a1ef-1d04-4ffc-9746-65aa935997ed","exercise":1665}}],"aliases":[],"comments":[]}'),
('wger', '1666', 'dumbbell-curl-shoulder-elevated', 'https://wger.de/en/exercise/1666/view', 'CC-BY-SA-4.0', 'Shiladree', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1666,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Shiladree","license_author_url":"","license_derivative_source_url":"","uuid":"9828f705-350b-4afd-86c4-fcc0e8a0fb4b","category":8,"variation_group":null,"created":"2025-09-28T13:59:00.809Z","last_update":"2025-09-28T13:59:00.809Z","muscles":[1],"muscles_secondary":[],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2785,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Shiladree","license_author_url":"","license_derivative_source_url":"","description":"<p>Place elbow so that it is about level with the shoulder. Curl the wieght to your shoulder. Focus on the stretch in the&nbsp;eccentric part of the curl</p>\n","description_source":"Place elbow so that it is about level with the shoulder. Curl the wieght to your shoulder. Focus on the stretch in the eccentric part of the curl","name":"Curl  - With Shoulder Elevated","created":"2025-09-28T13:59:01.073Z","last_update":"2026-04-13T18:58:26.258Z","language":2,"uuid":"9b24e22c-e04f-4bf3-9e0f-df71031609a4","exercise":1666}}],"aliases":[],"comments":[]}'),
('wger', '1668', 'cable-one-arm-overhead-tricep-extension', 'https://wger.de/en/exercise/1668/view', 'CC-BY-SA-4.0', 'AlucardEvil40', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1668,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"AlucardEvil40","license_author_url":"","license_derivative_source_url":"","uuid":"5ed12527-c8be-4e86-8f2a-cf9dd4781f5b","category":8,"variation_group":null,"created":"2025-10-02T10:27:12.081Z","last_update":"2025-10-02T10:27:12.081Z","muscles":[5],"muscles_secondary":[],"equipment":[11]}},"translations":[{"model":"exercises.translation","pk":2787,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"AlucardEvil40","license_author_url":"","license_derivative_source_url":"","description":"<p>Set the pulley at the bottom of the cable machine and grab onto it without using any attachments. Extend the cable directly overhead.</p>\n<p>While keeping your back straight and upper arm stationary, lower the cable behind your head until you feel a good stretch in your triceps, and then extend it back upward until your elbow is locked out.</p>\n","description_source":"Set the pulley at the bottom of the cable machine and grab onto it without using any attachments. Extend the cable directly overhead.\n\nWhile keeping your back straight and upper arm stationary, lower the cable behind your head until you feel a good stretch in your triceps, and then extend it back upward until your elbow is locked out.","name":"One Arm Overhead Cable Tricep Extension","created":"2025-10-02T10:27:12.128Z","last_update":"2026-04-13T18:58:26.882Z","language":2,"uuid":"936c19c6-ca46-4006-9ddc-b4f343eddc23","exercise":1668}},{"model":"exercises.translation","pk":2788,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"AlucardEvil40","license_author_url":"","license_derivative_source_url":"","description":"<p>Réglez la poulie au bas de la machine à câble et saisissez-la **sans utiliser d''accessoire**. **Étendez le câble directement au-dessus de votre tête.</p>\n<p>Tout en gardant votre dos droit et votre bras supérieur immobile, abaissez le câble derrière votre tête jusqu''à ce que vous sentiez un bon étirement dans vos triceps, puis étendez-le à nouveau vers le haut jusqu''à ce que votre **coude soit verrouillé (ou complètement tendu).</p>\n","description_source":"Réglez la poulie au bas de la machine à câble et saisissez-la \\*\\*sans utiliser d''accessoire\\*\\*. \\*\\*Étendez le câble directement au-dessus de votre tête.\n\nTout en gardant votre dos droit et votre bras supérieur immobile, abaissez le câble derrière votre tête jusqu''à ce que vous sentiez un bon étirement dans vos triceps, puis étendez-le à nouveau vers le haut jusqu''à ce que votre \\*\\*coude soit verrouillé (ou complètement tendu).","name":"Extension Triceps Poulie Basse à Un Bras","created":"2025-10-02T10:27:12.162Z","last_update":"2026-04-13T18:58:26.506Z","language":12,"uuid":"42e6841d-3051-45e7-ac95-d9ed0f512f46","exercise":1668}}],"aliases":[],"comments":[]}'),
('wger', '1669', 'jumping-jacks-2', 'https://wger.de/en/exercise/1669/view', 'CC-BY-SA-4.0', 'Jhonatan', 'new', 100.0, '{"exercise":{"model":"exercises.exercise","pk":1669,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Jhonatan","license_author_url":"","license_derivative_source_url":"","uuid":"bb080cd6-bf24-42ce-8258-f38cf8e9e71c","category":15,"variation_group":null,"created":"2025-10-08T14:32:59.450Z","last_update":"2025-10-08T14:32:59.450Z","muscles":[7,10],"muscles_secondary":[2,6,9],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2791,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Jhonatan","license_author_url":"","license_derivative_source_url":"","description":"<p>A full-body exercise where you jump while spreading your legs and raising your arms overhead.</p>\n","description_source":"A full-body exercise where you jump while spreading your legs and raising your arms overhead.","name":"Jumping Jacks","created":"2025-10-08T14:32:59.510Z","last_update":"2026-04-13T18:58:26.697Z","language":2,"uuid":"3081be0e-3507-46fc-b09a-69c0d2da9c8a","exercise":1669}},{"model":"exercises.translation","pk":2792,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Jhonatan","license_author_url":"","license_derivative_source_url":"","description":"<p>Exercício de corpo inteiro onde você salta abrindo as pernas e levantando os braços acima da cabeça.</p>\n","description_source":"Exercício de corpo inteiro onde você salta abrindo as pernas e levantando os braços acima da cabeça.","name":"Polichinelos","created":"2025-10-08T14:32:59.543Z","last_update":"2026-04-13T18:58:26.979Z","language":7,"uuid":"6e37c590-d9ee-40e1-a8fa-9b5b960f1c28","exercise":1669}}],"aliases":[],"comments":[]}'),
('wger', '1670', 'leg-swing-frontback', 'https://wger.de/en/exercise/1670/view', 'CC-BY-SA-4.0', 'Jhonatan', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1670,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Jhonatan","license_author_url":"","license_derivative_source_url":"","uuid":"1fae7d45-0731-4640-8809-94c76b836571","category":9,"variation_group":null,"created":"2025-10-08T19:18:11.569Z","last_update":"2025-10-08T19:18:11.569Z","muscles":[11],"muscles_secondary":[8,10],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2793,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Jhonatan","license_author_url":"","license_derivative_source_url":"","description":"<p>Stand tall next to a wall or stable support. Swing one leg forward and backward in a controlled motion, keeping the torso upright and the core engaged. Alternate legs after completing the repetitions.</p>\n","description_source":"Stand tall next to a wall or stable support. Swing one leg forward and backward in a controlled motion, keeping the torso upright and the core engaged. Alternate legs after completing the repetitions.","name":"Leg Swings (Front–Back)","created":"2025-10-08T19:18:11.628Z","last_update":"2026-04-13T18:58:26.783Z","language":2,"uuid":"8a100276-d298-4210-a7a7-c2c9866c6c9d","exercise":1670}},{"model":"exercises.translation","pk":2794,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Jhonatan","license_author_url":"","license_derivative_source_url":"","description":"<p>Fique em pé ao lado de uma parede ou apoio estável. Balance uma perna para frente e para trás em movimento controlado, mantendo o tronco ereto e o abdômen contraído. Troque de perna após completar as repetições.</p>\n","description_source":"Fique em pé ao lado de uma parede ou apoio estável. Balance uma perna para frente e para trás em movimento controlado, mantendo o tronco ereto e o abdômen contraído. Troque de perna após completar as repetições.","name":"Círculos de perna (frente-trás)","created":"2025-10-08T19:18:11.655Z","last_update":"2026-04-13T18:58:26.365Z","language":7,"uuid":"6db60d23-0eb8-4419-aad4-f6de88dd75be","exercise":1670}}],"aliases":[],"comments":[]}'),
('wger', '1672', 'seated-hip-abduction', 'https://wger.de/en/exercise/1672/view', 'CC-BY-SA-4.0', 'Iko', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1672,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Iko","license_author_url":"","license_derivative_source_url":"","uuid":"b144ac00-ec0c-4c43-898f-b2ac65048d98","category":9,"variation_group":null,"created":"2025-10-12T14:20:05.219Z","last_update":"2025-10-12T14:20:05.219Z","muscles":[8],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2795,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Iko","license_author_url":"","license_derivative_source_url":"","description":"<p>Starting Position:</p>\n<ul>\n<li>Adjust the seat height so that your knees are aligned with the pivot point of the machine.</li>\n<li>Sit with your back flat against the backrest, maintaining good posture.</li>\n<li>Place the outside of your thighs against the machine''s padded levers.</li>\n<li>Position your feet flat on the footrests or platform of the machine.</li>\n<li>Grasp the handles or sides of the seat for stability.</li>\n<li>Ensure your spine is neutral and your core is slightly engaged.</li>\n</ul>\n<p>Movement:</p>\n<ul>\n<li>Exhale as you slowly push your legs outward against the resistance pads.</li>\n<li>Focus on initiating the movement from your hips, not your knees.</li>\n<li>Continue opening your legs until you feel a strong contraction in your outer hips and thighs.</li>\n<li>Hold the fully abducted position briefly (1-2 seconds) to maximize muscle engagement.</li>\n<li>Inhale as you slowly control the return of your legs to the starting position, resisting the weight throughout the movement.</li>\n<li>Avoid allowing the weight stack to touch down between repetitions to maintain constant tension on the muscles.</li>\n<li>Repeat for the desired number of repetitions, maintaining control throughout the set.</li>\n</ul>\n","description_source":"Starting Position:\n\n* Adjust the seat height so that your knees are aligned with the pivot point of the machine.\n* Sit with your back flat against the backrest, maintaining good posture.\n* Place the outside of your thighs against the machine''s padded levers.\n* Position your feet flat on the footrests or platform of the machine.\n* Grasp the handles or sides of the seat for stability.\n* Ensure your spine is neutral and your core is slightly engaged.\n\nMovement:\n\n* Exhale as you slowly push your legs outward against the resistance pads.\n* Focus on initiating the movement from your hips, not your knees.\n* Continue opening your legs until you feel a strong contraction in your outer hips and thighs.\n* Hold the fully abducted position briefly (1-2 seconds) to maximize muscle engagement.\n* Inhale as you slowly control the return of your legs to the starting position, resisting the weight throughout the movement.\n* Avoid allowing the weight stack to touch down between repetitions to maintain constant tension on the muscles.\n* Repeat for the desired number of repetitions, maintaining control throughout the set.","name":"Seated Hip Abduction","created":"2025-10-12T14:20:05.263Z","last_update":"2026-04-13T18:58:27.280Z","language":2,"uuid":"b128393c-b85c-4ee1-a9f9-3ca303373395","exercise":1672}}],"aliases":[],"comments":[]}'),
('wger', '1674', 'dumbbell-floor-press', 'https://wger.de/en/exercise/1674/view', 'CC-BY-SA-4.0', 'FoyrhzMarin789', 'exact', 100.0, '{"exercise":{"model":"exercises.exercise","pk":1674,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"FoyrhzMarin789","license_author_url":"","license_derivative_source_url":"","uuid":"674b9b84-32bd-4aca-bf74-6909249444d5","category":11,"variation_group":null,"created":"2025-10-12T21:48:52.937Z","last_update":"2025-10-12T21:48:52.937Z","muscles":[4],"muscles_secondary":[2,5],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2797,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"FoyrhzMarin789","license_author_url":"","license_derivative_source_url":"","description":"<ol>\n<li>Sit on the floor holding a dumbbell in each hand, knees bent and feet flat.</li>\n<li>Roll back and plant your upper back and head on the floor; keep hips on the ground.</li>\n<li>Hold dumbbells at chest level with palms facing each other (neutral)\nor facing forward; elbows tucked at about 45–75° to the torso.</li>\n<li>Brace your core and press both dumbbells upward until arms are nearly extended but not locked.</li>\n<li>Pause briefly at the top, then lower the dumbbells under control\nuntil your upper arms contact the floor (or just above it) — this\nshortens the range of motion.</li>\n<li>Repeat for desired reps.\nCoaching notes: keep shoulders packed, avoid arching hips, use a spotter\nor lighter weight if needed. The floor press reduces shoulder stress\nand emphasizes lockout strength.</li>\n</ol>\n","description_source":"1. Sit on the floor holding a dumbbell in each hand, knees bent and feet flat.\n2. Roll back and plant your upper back and head on the floor; keep hips on the ground.\n3. Hold dumbbells at chest level with palms facing each other (neutral)\n   or facing forward; elbows tucked at about 45–75° to the torso.\n4. Brace your core and press both dumbbells upward until arms are nearly extended but not locked.\n5. Pause briefly at the top, then lower the dumbbells under control\n   until your upper arms contact the floor (or just above it) — this\n   shortens the range of motion.\n6. Repeat for desired reps.  \n   Coaching notes: keep shoulders packed, avoid arching hips, use a spotter\n   or lighter weight if needed. The floor press reduces shoulder stress\n   and emphasizes lockout strength.","name":"Dumbbell Floor Press","created":"2025-10-12T21:48:53.088Z","last_update":"2026-04-13T18:58:26.418Z","language":2,"uuid":"79a3cb01-2375-460f-a04d-e9e47ae73297","exercise":1674}}],"aliases":[],"comments":[]}'),
('wger', '1675', 'push-up', 'https://wger.de/en/exercise/1675/view', 'CC-BY-SA-4.0', 'FoyrhzMarin789', 'normalized', 100.0, '{"exercise":{"model":"exercises.exercise","pk":1675,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"FoyrhzMarin789","license_author_url":"","license_derivative_source_url":"","uuid":"c50695b2-44f0-4a16-927d-238fe2e16049","category":11,"variation_group":"9cbed464-c3ca-40bc-ad83-ec5fe8faffab","created":"2025-10-12T21:57:01.355Z","last_update":"2025-10-12T21:57:01.581Z","muscles":[4],"muscles_secondary":[2,6,3,5],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2798,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"FoyrhzMarin789","license_author_url":"","license_derivative_source_url":"","description":"<ul>\n<li><strong>1.</strong>&nbsp;Hands shoulder-width on the floor, fingers\nforward; feet together or hip-width; body in a straight line from head\nto heels; engage core and glutes.</li>\n<li><strong>2.</strong>&nbsp;Inhale and bend elbows, keeping them at ~45°\nfrom the torso (or closer for triceps focus); lower chest toward the\nfloor until elbows reach ~90° or chest nearly touches.</li>\n<li>\n<ol>\n<li>Briefly hold at the bottom with tension in chest and core.</li>\n</ol>\n</li>\n<li><strong>4.</strong> Exhale and push through palms to extend elbows, returning to the starting plank position without locking elbows.</li>\n</ul>\n","description_source":"- **1.** Hands shoulder-width on the floor, fingers\n  forward; feet together or hip-width; body in a straight line from head\n  to heels; engage core and glutes.\n- **2.** Inhale and bend elbows, keeping them at ~45°\n  from the torso (or closer for triceps focus); lower chest toward the\n  floor until elbows reach ~90° or chest nearly touches.\n- 3. Briefly hold at the bottom with tension in chest and core.\n- **4.** Exhale and push through palms to extend elbows, returning to the starting plank position without locking elbows.","name":"Push-Ups","created":"2025-10-12T21:57:01.491Z","last_update":"2026-04-13T18:58:27.107Z","language":2,"uuid":"7e288787-50ca-4cd4-9b15-40cf4fe16faa","exercise":1675}}],"aliases":[],"comments":[]}'),
('wger', '1676', 'dumbbell-bench-press', 'https://wger.de/en/exercise/1676/view', 'CC-BY-SA-4.0', 'Jhonatan', 'normalized', 100.0, '{"exercise":{"model":"exercises.exercise","pk":1676,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Jhonatan","license_author_url":"","license_derivative_source_url":"","uuid":"0fed3cd1-f6ef-4306-8c63-28246a931bf0","category":11,"variation_group":null,"created":"2025-10-13T14:07:52.534Z","last_update":"2025-10-13T14:07:52.534Z","muscles":[4],"muscles_secondary":[2,5],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2799,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Jhonatan","license_author_url":"","license_derivative_source_url":"","description":"<p>Lie on a flat bench and press dumbbells upward until arms are fully extended, then lower them slowly.</p>\n","description_source":"Lie on a flat bench and press dumbbells upward until arms are fully extended, then lower them slowly.","name":"Dumbbell Bench Press","created":"2025-10-13T14:07:52.581Z","last_update":"2026-04-13T18:58:26.410Z","language":2,"uuid":"1ac2d7b0-91b1-4242-909e-e7b79b0be14e","exercise":1676}},{"model":"exercises.translation","pk":2800,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Jhonatan","license_author_url":"","license_derivative_source_url":"","description":"<p>Deite-se em um banco plano e empurre os halteres para cima até que os braços estejam totalmente estendidos, depois abaixe-os lentamente.</p>\n","description_source":"Deite-se em um banco plano e empurre os halteres para cima até que os braços estejam totalmente estendidos, depois abaixe-os lentamente.","name":"Supino com Halteres","created":"2025-10-13T14:07:52.606Z","last_update":"2026-04-13T18:58:27.588Z","language":7,"uuid":"9493d96c-23fa-4124-ab66-d00f04a3d20e","exercise":1676}}],"aliases":[],"comments":[]}'),
('wger', '1679', 'wall-angels', 'https://wger.de/en/exercise/1679/view', 'CC-BY-SA-4.0', 'bbayuwega', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1679,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"bbayuwega","license_author_url":"","license_derivative_source_url":"","uuid":"2eb61587-85d1-494f-b2fb-a92dd108b3d3","category":13,"variation_group":null,"created":"2025-10-26T13:34:48.100Z","last_update":"2025-10-26T13:34:48.100Z","muscles":[9],"muscles_secondary":[2],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2801,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"bbayuwega","license_author_url":"","license_derivative_source_url":"","description":"<p>The <strong>Wall Angels</strong> exercise primarily targets the <strong>upper back and shoulder muscles</strong>, helping improve <strong>posture</strong>, <strong>shoulder mobility</strong>, and <strong>scapular control</strong>.</p>\n","description_source":"The **Wall Angels** exercise primarily targets the **upper back and shoulder muscles**, helping improve **posture**, **shoulder mobility**, and **scapular control**.","name":"Wall Angels","created":"2025-10-26T13:34:48.149Z","last_update":"2026-04-13T18:58:27.837Z","language":2,"uuid":"98a28d62-29f3-460a-a102-4c2e8df986d5","exercise":1679}}],"aliases":[],"comments":[]}'),
('wger', '1680', 'seated-figure-four', 'https://wger.de/en/exercise/1680/view', 'CC-BY-SA-4.0', 'ricardodavidrd', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1680,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"ricardodavidrd","license_author_url":"","license_derivative_source_url":"","uuid":"73144238-414e-438f-8b0c-832a6591aa2f","category":9,"variation_group":null,"created":"2025-10-28T03:58:00.250Z","last_update":"2025-10-28T03:58:00.250Z","muscles":[8],"muscles_secondary":[],"equipment":[8]}},"translations":[{"model":"exercises.translation","pk":2802,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"ricardodavidrd","license_author_url":"","license_derivative_source_url":"","description":"<p>Seat on&nbsp; a bench. Feet flat on the ground. Place your left ankle over your right knee. Your right knee stays flat. Keep your back straight. Gently push your left knee down.</p>\n","description_source":"Seat on  a bench. Feet flat on the ground. Place your left ankle over your right knee. Your right knee stays flat. Keep your back straight. Gently push your left knee down.  ","name":"seated figure four","created":"2025-10-28T03:58:00.449Z","last_update":"2026-04-13T18:58:27.963Z","language":2,"uuid":"c7e59147-9941-480d-9d07-4c1e87e70740","exercise":1680}}],"aliases":[],"comments":[]}'),
('wger', '1683', 'dumbbell-zottman-curl', 'https://wger.de/en/exercise/1683/view', 'CC-BY-SA-4.0', 'meldun', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1683,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"meldun","license_author_url":"","license_derivative_source_url":"","uuid":"9564ab2d-2534-4b47-bdf7-f2f653aae3de","category":8,"variation_group":"3081bbd4-bd49-47c5-9ab4-735962cd9fc3","created":"2025-10-28T05:19:38.849Z","last_update":"2025-10-28T05:19:38.987Z","muscles":[1,13],"muscles_secondary":[],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2803,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"meldun","license_author_url":"","license_derivative_source_url":"","description":"<p>With your palms facing forward, curl the weights up to your shoulders. Turn your hands so that that your palms downwards and slowly return the weights back down. Finally face your palms back forward.</p>\n","description_source":"With your palms facing forward, curl the weights up to your shoulders. Turn your hands so that that your palms downwards and slowly return the weights back down. Finally face your palms back forward.","name":"Zottman curl","created":"2025-10-28T05:19:38.930Z","last_update":"2026-04-13T18:58:27.934Z","language":2,"uuid":"64f54ece-a9c9-43f5-938c-de809d22a5e3","exercise":1683}}],"aliases":[],"comments":[]}'),
('wger', '1684', 'dumbbell-thruster', 'https://wger.de/en/exercise/1684/view', 'CC-BY-SA-4.0', 'meldun', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1684,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"meldun","license_author_url":"","license_derivative_source_url":"","uuid":"ae6a522e-db10-45ba-9642-987468d8a4de","category":9,"variation_group":"7fd1f6bd-a8d7-4ea7-b87b-049f10e6798d","created":"2025-10-29T19:00:05.210Z","last_update":"2025-10-29T19:00:05.350Z","muscles":[11,8,10],"muscles_secondary":[2],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2804,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"meldun","license_author_url":"","license_derivative_source_url":"","description":"<p>Start with the dumbbells resting on your shoulders and squat down. Push\ninto standing and raise the dumbbells into an overhead position. Bring\nthe dumbbells back to your shoulders and repeat.</p>\n","description_source":"Start with the dumbbells resting on your shoulders and squat down. Push\ninto standing and raise the dumbbells into an overhead position. Bring\nthe dumbbells back to your shoulders and repeat.","name":"Dumbbell Thruster","created":"2025-10-29T19:00:05.293Z","last_update":"2026-04-13T18:58:26.442Z","language":2,"uuid":"c34a2c74-2339-4b07-bc52-e20ddf007db7","exercise":1684}}],"aliases":[],"comments":[]}'),
('wger', '1686', 'dumbbell-glute-bridge-single-arm-press', 'https://wger.de/en/exercise/1686/view', 'CC-BY-SA-4.0', 'meldun', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1686,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"meldun","license_author_url":"","license_derivative_source_url":"","uuid":"8c4a9c16-294b-40e5-ba6d-50ae523704ba","category":8,"variation_group":"9e728c35-6e9d-4b3d-8416-1f5b10983de1","created":"2025-10-29T19:47:20.205Z","last_update":"2025-10-29T19:47:20.322Z","muscles":[4],"muscles_secondary":[2,1,11,8,5],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2805,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"meldun","license_author_url":"","license_derivative_source_url":"","description":"<p>With one dumbbell in hand, perform a glute bridge. Now hold the dumbbell above your chest, this is the rep starting position.&nbsp;Lower the dumbbell so that your elbow touches the floor or is roughly 45 degrees below your shoulder if using a bench. Push the dumbbell back into the starting position.</p>\n","description_source":"With one dumbbell in hand, perform a glute bridge. Now hold the dumbbell above your chest, this is the rep starting position. Lower the dumbbell so that your elbow touches the floor or is roughly 45 degrees below your shoulder if using a bench. Push the dumbbell back into the starting position.","name":"Glute Bridge Single-Arm Press","created":"2025-10-29T19:47:20.270Z","last_update":"2026-04-13T18:58:26.593Z","language":2,"uuid":"9819a45f-b1cd-4464-8d7f-2e3cd5dafb80","exercise":1686}}],"aliases":[],"comments":[]}'),
('wger', '1687', 'dumbbell-bear-crawl-pull-through', 'https://wger.de/en/exercise/1687/view', 'CC-BY-SA-4.0', 'meldun', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1687,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"meldun","license_author_url":"","license_derivative_source_url":"","uuid":"b4dc15da-4d4d-4a93-a30a-74aaf99192ff","category":10,"variation_group":"361cdbb4-66a0-45da-9653-9306ff25828e","created":"2025-11-01T13:10:05.495Z","last_update":"2025-11-01T13:10:05.676Z","muscles":[2,8,10,6],"muscles_secondary":[11,7,9],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2806,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"meldun","license_author_url":"","license_derivative_source_url":"","description":"<p>Place a dumbbell at around hip level and assume a bear crawl position. Push the knees off the floor and hold.</p>\n<p>With the opposite hand reach for the dumbbell and pull it to the other side. Place your hand back on the floor and repeat with your other hand.</p>\n","description_source":"Place a dumbbell at around hip level and assume a bear crawl position. Push the knees off the floor and hold.\n\nWith the opposite hand reach for the dumbbell and pull it to the other side. Place your hand back on the floor and repeat with your other hand.","name":"Bear crawl pull through","created":"2025-11-01T13:10:05.596Z","last_update":"2026-04-13T18:58:26.087Z","language":2,"uuid":"ef97a407-8394-4f28-8c30-0092d7657e11","exercise":1687}}],"aliases":[],"comments":[]}'),
('wger', '1688', 'barbell-kickstand-romanian-deadlift', 'https://wger.de/en/exercise/1688/view', 'CC-BY-SA-4.0', 'eriktrinkle', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1688,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"eriktrinkle","license_author_url":"","license_derivative_source_url":"","uuid":"107ea68a-d976-49ed-be75-3b0cf253c36a","category":9,"variation_group":"335b2b18-e072-4636-aa13-4045d7a133ae","created":"2025-11-01T17:37:49.640Z","last_update":"2025-11-01T17:37:50.047Z","muscles":[11],"muscles_secondary":[],"equipment":[1]}},"translations":[{"model":"exercises.translation","pk":2807,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"eriktrinkle","license_author_url":"","license_derivative_source_url":"","description":"<p>use non-working leg''s toes to help with balance and perform an RDL.</p>\n","description_source":"use non-working leg''s toes to help with balance and perform an RDL.","name":"Kickstand RDL","created":"2025-11-01T17:37:49.868Z","last_update":"2026-04-13T18:58:26.715Z","language":2,"uuid":"def2d31e-5bd9-4f7d-be40-b8aaada2b9ca","exercise":1688}}],"aliases":[],"comments":[]}'),
('wger', '1689', 'cable-fly-middle-chest', 'https://wger.de/en/exercise/1689/view', 'CC-BY-SA-4.0', 'daiben', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1689,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"daiben","license_author_url":"","license_derivative_source_url":"","uuid":"5b4fb3ec-53a1-4525-a58a-c070798ea86e","category":11,"variation_group":null,"created":"2025-11-01T21:38:27.729Z","last_update":"2025-11-01T21:38:27.729Z","muscles":[4],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2808,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"daiben","license_author_url":"","license_derivative_source_url":"","description":"<strong>Execution</strong>\n<ol>\n<li>\n<p><strong>Start position:</strong>&nbsp;Arms extended out to your sides (a big “T” shape), feeling a stretch in your chest.</p>\n</li>\n<li>\n<p><strong>Movement:</strong>&nbsp;Bring your hands together in front of your chest in a&nbsp;<strong>wide hugging motion</strong>.</p>\n<ul>\n<li>Focus on squeezing your chest at the center.</li>\n<li>Do&nbsp;<strong>not lock your elbows</strong>&nbsp;or turn it into a press.</li>\n</ul>\n</li>\n<li>\n<p><strong>Return:</strong>&nbsp;Slowly open your arms back to the start, maintaining tension on the chest.</p>\n</li>\n</ol>\n","description_source":"### **Execution**\n\n1. **Start position:** Arms extended out to your sides (a big “T” shape), feeling a stretch in your chest.\n2. **Movement:** Bring your hands together in front of your chest in a **wide hugging motion**.\n\n   * Focus on squeezing your chest at the center.\n   * Do **not lock your elbows** or turn it into a press.\n3. **Return:** Slowly open your arms back to the start, maintaining tension on the chest.","name":"Cable Fly Middle Chest","created":"2025-11-01T21:38:27.790Z","last_update":"2026-04-13T18:58:26.175Z","language":2,"uuid":"e8e210c5-7808-4280-816e-bdb09d8ed27b","exercise":1689}}],"aliases":[],"comments":[]}'),
('wger', '1690', 'cable-fly-upper-chest', 'https://wger.de/en/exercise/1690/view', 'CC-BY-SA-4.0', 'daiben', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1690,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"daiben","license_author_url":"","license_derivative_source_url":"","uuid":"b16a28c4-40bf-42d4-94b3-bf3f56fab743","category":11,"variation_group":null,"created":"2025-11-01T21:42:15.807Z","last_update":"2025-11-01T21:42:15.807Z","muscles":[4],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2809,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"daiben","license_author_url":"","license_derivative_source_url":"","description":"<strong>Execution</strong>\n<ol>\n<li>\n<p><strong>Start position:</strong></p>\n<ul>\n<li>Arms down and slightly behind your body, elbows slightly bent.</li>\n<li>Feel a light stretch across your chest.</li>\n</ul>\n</li>\n<li>\n<p><strong>Movement:</strong></p>\n<ul>\n<li>Bring your hands&nbsp;<strong>upward and together</strong>&nbsp;in front of your upper chest — roughly at&nbsp;<strong>chin to collarbone level</strong>.</li>\n<li>Use a smooth, controlled motion (avoid jerking).</li>\n<li><strong>Squeeze</strong>&nbsp;your chest at the top for 1–2 seconds.</li>\n</ul>\n</li>\n<li>\n<p><strong>Return:</strong></p>\n<ul>\n<li>Slowly let your arms move back down and out to the sides, keeping control and tension.</li>\n</ul>\n</li>\n</ol>\n","description_source":"### **Execution**\n\n1. **Start position:**\n\n   * Arms down and slightly behind your body, elbows slightly bent.\n   * Feel a light stretch across your chest.\n2. **Movement:**\n\n   * Bring your hands **upward and together** in front of your upper chest — roughly at **chin to collarbone level**.\n   * Use a smooth, controlled motion (avoid jerking).\n   * **Squeeze** your chest at the top for 1–2 seconds.\n3. **Return:**\n\n   * Slowly let your arms move back down and out to the sides, keeping control and tension.","name":"Cable Fly Upper Chest","created":"2025-11-01T21:42:15.874Z","last_update":"2026-04-13T18:58:26.177Z","language":2,"uuid":"68e510b2-ca56-412d-914f-716ba122f6fc","exercise":1690}}],"aliases":[],"comments":[]}'),
('wger', '1691', 'cable-fly-lower-chest', 'https://wger.de/en/exercise/1691/view', 'CC-BY-SA-4.0', 'daiben', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1691,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"daiben","license_author_url":"","license_derivative_source_url":"","uuid":"ae695660-7cee-4601-8241-edd3e2a6d896","category":11,"variation_group":null,"created":"2025-11-01T21:44:17.900Z","last_update":"2025-11-01T21:44:17.900Z","muscles":[4],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2810,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"daiben","license_author_url":"","license_derivative_source_url":"","description":"<strong>Execution</strong>\n<ol>\n<li>\n<p><strong>Start position:</strong></p>\n<ul>\n<li>Arms extended out to your sides in a “Y” shape.</li>\n<li>Feel a stretch in your chest (slight bend in elbows — don’t lock them).</li>\n</ul>\n</li>\n<li>\n<p><strong>Movement:</strong></p>\n<ul>\n<li>Bring your hands&nbsp;<strong>downward and together</strong>&nbsp;in front of your&nbsp;<strong>lower chest or upper abs</strong>, in a smooth arc motion.</li>\n<li><strong>Squeeze your chest</strong>&nbsp;hard at the bottom for 1–2 seconds.</li>\n</ul>\n</li>\n<li>\n<p><strong>Return:</strong></p>\n<ul>\n<li>Slowly raise your arms back up along the same path until you feel a good stretch in your chest.</li>\n<li>Maintain control — don’t let the weights pull you back too quickly.</li>\n</ul>\n</li>\n</ol>\n","description_source":"### **Execution**\n\n1. **Start position:**\n\n   * Arms extended out to your sides in a “Y” shape.\n   * Feel a stretch in your chest (slight bend in elbows — don’t lock them).\n2. **Movement:**\n\n   * Bring your hands **downward and together** in front of your **lower chest or upper abs**, in a smooth arc motion.\n   * **Squeeze your chest** hard at the bottom for 1–2 seconds.\n3. **Return:**\n\n   * Slowly raise your arms back up along the same path until you feel a good stretch in your chest.\n   * Maintain control — don’t let the weights pull you back too quickly.","name":"Cable Fly Lower Chest","created":"2025-11-01T21:44:17.959Z","last_update":"2026-04-13T18:58:26.174Z","language":2,"uuid":"3dcae508-5e1e-4bf9-b60a-718294cac1d5","exercise":1691}}],"aliases":[],"comments":[]}'),
('wger', '1692', 'smith-machine-incline-press', 'https://wger.de/en/exercise/1692/view', 'CC-BY-SA-4.0', 'daiben', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1692,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"daiben","license_author_url":"","license_derivative_source_url":"","uuid":"e2724724-b3d4-44d6-b832-95b80e314537","category":11,"variation_group":null,"created":"2025-11-01T21:47:21.811Z","last_update":"2025-11-01T21:47:21.811Z","muscles":[4],"muscles_secondary":[],"equipment":[9]}},"translations":[{"model":"exercises.translation","pk":2811,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"daiben","license_author_url":"","license_derivative_source_url":"","description":"* <strong>Execution</strong> * <strong>Start position:</strong>\n<ul>\n<li>Unrack the bar and hold it above your upper chest with arms fully extended.</li>\n<li>Keep your shoulder blades&nbsp;<strong>retracted and pressed into the bench</strong>.</li>\n<li><strong>Lowering phase (eccentric):</strong></li>\n<li>Slowly bring the bar down to just below your collarbone or upper chest.</li>\n<li>Maintain control — don’t bounce the bar.</li>\n<li><strong>Pressing phase (concentric):</strong></li>\n<li>Push the bar upward in a straight line until your arms are fully extended.</li>\n<li>Focus on&nbsp;<strong>squeezing your upper chest</strong>&nbsp;at the top.</li>\n<li><strong>Lock and repeat:</strong></li>\n<li>Complete your reps, then safely rack the bar back into the hooks.</li>\n</ul>\n","description_source":"### * **Execution** * **Start position:**\n\n* Unrack the bar and hold it above your upper chest with arms fully extended.\n* Keep your shoulder blades **retracted and pressed into the bench**.\n* **Lowering phase (eccentric):**\n* Slowly bring the bar down to just below your collarbone or upper chest.\n* Maintain control — don’t bounce the bar.\n* **Pressing phase (concentric):**\n* Push the bar upward in a straight line until your arms are fully extended.\n* Focus on **squeezing your upper chest** at the top.\n* **Lock and repeat:**\n* Complete your reps, then safely rack the bar back into the hooks.","name":"Incline Smith Press","created":"2025-11-01T21:47:21.861Z","last_update":"2026-04-13T18:58:26.664Z","language":2,"uuid":"3ad3ea1d-4a7b-4099-92e6-e30b488c3bf0","exercise":1692}}],"aliases":[],"comments":[]}'),
('wger', '1693', 'dumbbell-incline-static-hold', 'https://wger.de/en/exercise/1693/view', 'CC-BY-SA-4.0', 'daiben', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1693,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"daiben","license_author_url":"","license_derivative_source_url":"","uuid":"88afb956-8d4a-45b3-8c7c-c23719316bfe","category":11,"variation_group":null,"created":"2025-11-01T22:51:36.598Z","last_update":"2025-11-01T22:51:36.598Z","muscles":[4],"muscles_secondary":[],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2812,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"daiben","license_author_url":"","license_derivative_source_url":"","description":"<strong>Execution</strong>\n<ol>\n<li>\n<p><strong>Hold Position:</strong></p>\n<ul>\n<li>Lower the dumbbells&nbsp;<strong>a few inches above your chest</strong>&nbsp;— about the&nbsp;<strong>midpoint</strong>&nbsp;of a normal incline press.</li>\n<li>This is where your upper chest is under maximum tension.</li>\n</ul>\n</li>\n<li>\n<p><strong>Static Hold:</strong></p>\n<ul>\n<li>Hold the position for&nbsp;<strong>20–45 seconds</strong>&nbsp;while keeping the chest tight.</li>\n<li>Breathe slowly but stay tense —&nbsp;<strong>do not relax your chest or shoulders</strong>.</li>\n</ul>\n</li>\n<li>\n<p><strong>End the set:</strong></p>\n<ul>\n<li>After the hold, carefully bring the dumbbells down and rest.</li>\n</ul>\n</li>\n</ol>\n","description_source":"### **Execution**\n\n1. **Hold Position:**\n\n   * Lower the dumbbells **a few inches above your chest** — about the **midpoint** of a normal incline press.\n   * This is where your upper chest is under maximum tension.\n2. **Static Hold:**\n\n   * Hold the position for **20–45 seconds** while keeping the chest tight.\n   * Breathe slowly but stay tense — **do not relax your chest or shoulders**.\n3. **End the set:**\n\n   * After the hold, carefully bring the dumbbells down and rest.","name":"Incline Static Hold","created":"2025-11-01T22:51:36.665Z","last_update":"2026-04-13T18:58:26.666Z","language":2,"uuid":"cd2aeff9-4066-4ecc-9b47-6ed7e8af8aa8","exercise":1693}}],"aliases":[],"comments":[]}'),
('wger', '1694', 'machine-flat-press', 'https://wger.de/en/exercise/1694/view', 'CC-BY-SA-4.0', 'daiben', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1694,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"daiben","license_author_url":"","license_derivative_source_url":"","uuid":"03f7fc27-e64f-4417-ab0c-a52adac60fda","category":11,"variation_group":null,"created":"2025-11-01T22:56:46.611Z","last_update":"2025-11-01T22:56:46.611Z","muscles":[4],"muscles_secondary":[],"equipment":[8]}},"translations":[{"model":"exercises.translation","pk":2813,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"daiben","license_author_url":"","license_derivative_source_url":"","description":"<strong>Execution</strong>\n<ol>\n<li>\n<p><strong>Start position:</strong></p>\n<ul>\n<li>Elbows bent at roughly 90°, hands just outside your chest.</li>\n<li>Keep wrists straight and aligned with your forearms.</li>\n</ul>\n</li>\n<li>\n<p><strong>Pressing phase (concentric):</strong></p>\n<ul>\n<li>Push the handles forward until your arms are&nbsp;<strong>almost fully extended</strong>&nbsp;— don’t lock out.</li>\n<li>Focus on&nbsp;<strong>squeezing your chest</strong>&nbsp;at the end of the movement.</li>\n</ul>\n</li>\n<li>\n<p><strong>Returning phase (eccentric):</strong></p>\n<ul>\n<li>Slowly bring the handles back toward your chest, feeling the&nbsp;<strong>stretch in your pecs</strong>.</li>\n<li>Maintain tension — don’t let the weight stack touch down between reps.</li>\n</ul>\n</li>\n</ol>\n","description_source":"### **Execution**\n\n1. **Start position:**\n\n   * Elbows bent at roughly 90°, hands just outside your chest.\n   * Keep wrists straight and aligned with your forearms.\n2. **Pressing phase (concentric):**\n\n   * Push the handles forward until your arms are **almost fully extended** — don’t lock out.\n   * Focus on **squeezing your chest** at the end of the movement.\n3. **Returning phase (eccentric):**\n\n   * Slowly bring the handles back toward your chest, feeling the **stretch in your pecs**.\n   * Maintain tension — don’t let the weight stack touch down between reps.","name":"Flat Machine Press","created":"2025-11-01T22:56:46.673Z","last_update":"2026-04-13T18:58:26.528Z","language":2,"uuid":"4605e188-fc43-4235-b97f-d49423a7d88a","exercise":1694}}],"aliases":[],"comments":[]}'),
('wger', '1695', 'pull-up-wide-grip', 'https://wger.de/en/exercise/1695/view', 'CC-BY-SA-4.0', 'daiben', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1695,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"daiben","license_author_url":"","license_derivative_source_url":"","uuid":"be4eb0b6-2c39-4ff5-b57d-419f1687c90f","category":12,"variation_group":null,"created":"2025-11-01T23:11:20.655Z","last_update":"2025-11-01T23:11:20.655Z","muscles":[12],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2814,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"daiben","license_author_url":"","license_derivative_source_url":"","description":"<p><strong>Execution</strong></p>\n<ol>\n<li>\n<p><strong>Pulling phase (concentric):</strong></p>\n<ul>\n<li>Drive your&nbsp;<strong>elbows down and slightly back</strong>, pulling your chest&nbsp;<strong>toward the bar</strong>.</li>\n<li>Focus on leading with your&nbsp;<strong>chest</strong>, not your chin.</li>\n<li>Keep your&nbsp;<strong>shoulders depressed</strong>&nbsp;(avoid shrugging).</li>\n</ul>\n</li>\n<li>\n<p><strong>Top position:</strong></p>\n<ul>\n<li>Chin should clear the bar (or at least reach bar level).</li>\n<li>Pause for a brief&nbsp;<strong>squeeze in your lats</strong>.</li>\n</ul>\n</li>\n</ol>\n","description_source":"**Execution**\n\n1. **Pulling phase (concentric):**\n\n   * Drive your **elbows down and slightly back**, pulling your chest **toward the bar**.\n   * Focus on leading with your **chest**, not your chin.\n   * Keep your **shoulders depressed** (avoid shrugging).\n2. **Top position:**\n\n   * Chin should clear the bar (or at least reach bar level).\n   * Pause for a brief **squeeze in your lats**.","name":"Pull-Ups (Wide Grip)","created":"2025-11-01T23:11:20.705Z","last_update":"2026-04-13T18:58:27.090Z","language":2,"uuid":"7dbb0812-908e-4ae0-9a3f-7a016031044f","exercise":1695}}],"aliases":[],"comments":[]}'),
('wger', '1696', 'pull-up-neutral-grip', 'https://wger.de/en/exercise/1696/view', 'CC-BY-SA-4.0', 'daiben', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1696,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"daiben","license_author_url":"","license_derivative_source_url":"","uuid":"1f490456-b426-4b89-b70c-e155c3571422","category":12,"variation_group":null,"created":"2025-11-01T23:14:27.862Z","last_update":"2025-11-01T23:14:27.862Z","muscles":[12],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2815,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"daiben","license_author_url":"","license_derivative_source_url":"","description":"<strong>Execution</strong>\n<ol>\n<li>\n<p><strong>Pulling phase (concentric):</strong></p>\n<ul>\n<li>Drive your&nbsp;<strong>elbows down and back</strong>, pulling your&nbsp;<strong>chest toward your hands</strong>.</li>\n<li>Keep your shoulders&nbsp;<strong>depressed and retracted</strong>&nbsp;(avoid shrugging).</li>\n<li>Focus on squeezing your&nbsp;<strong>lats and upper back</strong>&nbsp;at the top.</li>\n</ul>\n</li>\n<li>\n<p><strong>Top position:</strong></p>\n<ul>\n<li>Chin should clear or reach the level of your hands.</li>\n<li>Pause briefly and&nbsp;<strong>contract your lats</strong>&nbsp;hard.</li>\n</ul>\n</li>\n</ol>\n","description_source":"### **Execution**\n\n1. **Pulling phase (concentric):**\n\n   * Drive your **elbows down and back**, pulling your **chest toward your hands**.\n   * Keep your shoulders **depressed and retracted** (avoid shrugging).\n   * Focus on squeezing your **lats and upper back** at the top.\n2. **Top position:**\n\n   * Chin should clear or reach the level of your hands.\n   * Pause briefly and **contract your lats** hard.","name":"Pull-Ups (Neutral Grip)","created":"2025-11-01T23:14:27.893Z","last_update":"2026-04-13T18:58:27.086Z","language":2,"uuid":"c57be1c3-5dfc-42e1-9804-497045c22c00","exercise":1696}}],"aliases":[],"comments":[]}'),
('wger', '1697', 'lat-pulldown-wide-grip', 'https://wger.de/en/exercise/1697/view', 'CC-BY-SA-4.0', 'daiben', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1697,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"daiben","license_author_url":"","license_derivative_source_url":"","uuid":"c6daf781-02ba-4b73-8e88-530165afd32d","category":12,"variation_group":null,"created":"2025-11-01T23:16:51.267Z","last_update":"2025-11-01T23:16:51.267Z","muscles":[12],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2816,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"daiben","license_author_url":"","license_derivative_source_url":"","description":"<strong>Execution</strong>\n<ol>\n<li>\n<p><strong>Starting position:</strong></p>\n<ul>\n<li>Arms extended overhead, feeling a stretch in your lats.</li>\n<li>Keep your shoulders depressed (don’t shrug upward).</li>\n</ul>\n</li>\n<li>\n<p><strong>Pulling phase (concentric):</strong></p>\n<ul>\n<li>Pull the bar&nbsp;<strong>down to your upper chest or collarbone area</strong>&nbsp;by driving your&nbsp;<strong>elbows down and back</strong>.</li>\n<li>Keep your&nbsp;<strong>chest lifted</strong>&nbsp;and squeeze your&nbsp;<strong>shoulder blades together</strong>&nbsp;at the bottom.</li>\n</ul>\n</li>\n</ol>\n","description_source":"### **Execution**\n\n1. **Starting position:**\n\n   * Arms extended overhead, feeling a stretch in your lats.\n   * Keep your shoulders depressed (don’t shrug upward).\n2. **Pulling phase (concentric):**\n\n   * Pull the bar **down to your upper chest or collarbone area** by driving your **elbows down and back**.\n   * Keep your **chest lifted** and squeeze your **shoulder blades together** at the bottom.","name":"Lat Pulldown (Wide Grip)","created":"2025-11-01T23:16:51.294Z","last_update":"2026-04-13T18:58:26.761Z","language":2,"uuid":"a05335d7-91b2-44e1-ae0c-beebff76e75e","exercise":1697}}],"aliases":[],"comments":[]}'),
('wger', '1698', 'barbell-row-overhand', 'https://wger.de/en/exercise/1698/view', 'CC-BY-SA-4.0', 'daiben', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1698,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"daiben","license_author_url":"","license_derivative_source_url":"","uuid":"6ce25688-ae91-4dc7-9b17-0b66a47151fa","category":12,"variation_group":null,"created":"2025-11-01T23:31:47.940Z","last_update":"2025-11-01T23:31:47.940Z","muscles":[12],"muscles_secondary":[],"equipment":[1]}},"translations":[{"model":"exercises.translation","pk":2817,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"daiben","license_author_url":"","license_derivative_source_url":"","description":"<strong>Execution</strong>\n<ol>\n<li>\n<p><strong>Starting position:</strong></p>\n<ul>\n<li>Hold the barbell with arms fully extended toward the floor.</li>\n<li>Maintain tension in your lats and back muscles.</li>\n</ul>\n</li>\n</ol>\n","description_source":"### **Execution**\n\n1. **Starting position:**\n\n   * Hold the barbell with arms fully extended toward the floor.\n   * Maintain tension in your lats and back muscles.","name":"Barbell Row (Overhand)","created":"2025-11-01T23:31:47.987Z","last_update":"2026-04-13T18:58:26.076Z","language":2,"uuid":"7bf3506d-37d8-457c-8f35-cfbd1afdca53","exercise":1698}}],"aliases":[],"comments":[]}'),
('wger', '1699', 'barbell-row-underhand', 'https://wger.de/en/exercise/1699/view', 'CC-BY-SA-4.0', 'daiben', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1699,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"daiben","license_author_url":"","license_derivative_source_url":"","uuid":"3c2b5e2d-bd9d-43e8-8b5f-e6363331faa1","category":12,"variation_group":null,"created":"2025-11-01T23:33:49.723Z","last_update":"2025-11-01T23:33:49.723Z","muscles":[12],"muscles_secondary":[],"equipment":[1]}},"translations":[{"model":"exercises.translation","pk":2818,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"daiben","license_author_url":"","license_derivative_source_url":"","description":"<strong>Execution</strong>\n<ol>\n<li>\n<p><strong>Starting position:</strong></p>\n<ul>\n<li>Hold the barbell with arms fully extended toward the floor.</li>\n<li>Maintain tension in your lats and back muscles.</li>\n</ul>\n</li>\n</ol>\n","description_source":"### **Execution**\n\n1. **Starting position:**\n\n   * Hold the barbell with arms fully extended toward the floor.\n   * Maintain tension in your lats and back muscles.","name":"Barbell Row (Underhand)","created":"2025-11-01T23:33:49.820Z","last_update":"2026-04-13T18:58:26.077Z","language":2,"uuid":"9af74153-749a-42dc-a998-6e241a096b0b","exercise":1699}}],"aliases":[],"comments":[]}'),
('wger', '1700', 'barbell-romanian-deadlift', 'https://wger.de/en/exercise/1700/view', 'CC-BY-SA-4.0', 'daiben', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1700,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"daiben","license_author_url":"","license_derivative_source_url":"","uuid":"72129e4f-df97-4869-9561-33a1ba3c9186","category":12,"variation_group":null,"created":"2025-11-01T23:35:21.264Z","last_update":"2025-11-01T23:35:21.264Z","muscles":[12],"muscles_secondary":[],"equipment":[1]}},"translations":[{"model":"exercises.translation","pk":2819,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"daiben","license_author_url":"","license_derivative_source_url":"","description":"<strong>Execution</strong>\n<ol>\n<li>\n<p><strong>Hinge at the hips:</strong></p>\n<ul>\n<li>Push your&nbsp;<strong>hips backward</strong>, keeping a slight bend in the knees (soft knees).</li>\n<li>Lower the barbell&nbsp;<strong>along the front of your thighs/shins</strong>&nbsp;while maintaining a&nbsp;<strong>neutral spine</strong>.</li>\n<li>Keep the bar&nbsp;<strong>close to your body</strong>.</li>\n</ul>\n</li>\n</ol>\n","description_source":"### **Execution**\n\n1. **Hinge at the hips:**\n\n   * Push your **hips backward**, keeping a slight bend in the knees (soft knees).\n   * Lower the barbell **along the front of your thighs/shins** while maintaining a **neutral spine**.\n   * Keep the bar **close to your body**.","name":"Barbell Romanian Deadlift (RDL)","created":"2025-11-01T23:35:21.342Z","last_update":"2026-04-13T18:58:26.075Z","language":2,"uuid":"ad9c64c1-731d-45e8-acff-369b81cd32a0","exercise":1700}}],"aliases":[],"comments":[]}'),
('wger', '1701', 'dumbbell-one-arm-heavy-row', 'https://wger.de/en/exercise/1701/view', 'CC-BY-SA-4.0', 'daiben', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1701,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"daiben","license_author_url":"","license_derivative_source_url":"","uuid":"d8ec22e5-8575-483f-bd66-5203fd4bfe84","category":12,"variation_group":null,"created":"2025-11-01T23:37:56.313Z","last_update":"2025-11-01T23:37:56.313Z","muscles":[12],"muscles_secondary":[],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2820,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"daiben","license_author_url":"","license_derivative_source_url":"","description":"<strong>Execution</strong>\n<ol>\n<li>\n<p><strong>Rowing phase (concentric):</strong></p>\n<ul>\n<li>Pull the dumbbell&nbsp;<strong>toward your lower chest or waist</strong>, leading with your&nbsp;<strong>elbow</strong>.</li>\n<li>Keep your torso&nbsp;<strong>stable</strong>&nbsp;— avoid twisting or rotating your shoulders.</li>\n<li>Pause at the top and&nbsp;<strong>squeeze your lats</strong>.</li>\n</ul>\n</li>\n</ol>\n","description_source":"### **Execution**\n\n1. **Rowing phase (concentric):**\n\n   * Pull the dumbbell **toward your lower chest or waist**, leading with your **elbow**.\n   * Keep your torso **stable** — avoid twisting or rotating your shoulders.\n   * Pause at the top and **squeeze your lats**.","name":"One-Arm Heavy Row","created":"2025-11-01T23:37:56.453Z","last_update":"2026-04-13T18:58:26.884Z","language":2,"uuid":"30be19a6-0bc8-4b09-a70d-44c73efb4143","exercise":1701}}],"aliases":[],"comments":[]}'),
('wger', '1702', 'jalon-al-pecho-con-agarre-ancho', 'https://wger.de/en/exercise/1702/view', 'CC-BY-SA-4.0', 'Mariano_O', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1702,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Mariano_O","license_author_url":"","license_derivative_source_url":"","uuid":"c9de4551-f1bc-4490-98f4-c9f87c2a2cac","category":12,"variation_group":null,"created":"2025-11-06T03:10:34.800Z","last_update":"2025-11-06T03:10:34.800Z","muscles":[12,9],"muscles_secondary":[1,13],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2821,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Mariano_O","license_author_url":"","license_derivative_source_url":"","description":"<p>The lat pulldown is a pulling exercise that primarily targets the latissimus dorsi muscles (commonly known as “lats”) in your back. It involves pulling a cable bar or handle down towards your chest while seated on a machine specifically designed for this exercise. The lat pulldown is typically performed with a wide grip, but can also be done with a narrow grip or underhand grip to target different muscle groups in the back and arms. It is a popular exercise for building upper body strength and improving posture.</p>\n","description_source":"The lat pulldown is a pulling exercise that primarily targets the latissimus dorsi muscles (commonly known as “lats”) in your back. It involves pulling a cable bar or handle down towards your chest while seated on a machine specifically designed for this exercise. The lat pulldown is typically performed with a wide grip, but can also be done with a narrow grip or underhand grip to target different muscle groups in the back and arms. It is a popular exercise for building upper body strength and improving posture.","name":"Jalón al pecho con agarre ancho","created":"2025-11-06T03:10:34.854Z","last_update":"2026-04-13T18:58:26.686Z","language":2,"uuid":"606c9263-bd4f-4739-8b42-01da22a57838","exercise":1702}},{"model":"exercises.translation","pk":2822,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Mariano_O","license_author_url":"","license_derivative_source_url":"","description":"<p>Posición inicial\nSentado, los muslos bajo las partes acolchadas, la barra agarrada en pronación, las manos más separadas que el ancho de los hombros. Mantén los codos apuntados hacia afuera y la espalda recta.\nEjecución\nTira de la barra hasta llegar a la barbilla. Mantén la contracción por un momento antes de volver lentamente a la posición inicial. Durante el movimiento, no dejes que tus codos se adelanten.</p>\n","description_source":"Posición inicial\nSentado, los muslos bajo las partes acolchadas, la barra agarrada en pronación, las manos más separadas que el ancho de los hombros. Mantén los codos apuntados hacia afuera y la espalda recta.\nEjecución\nTira de la barra hasta llegar a la barbilla. Mantén la contracción por un momento antes de volver lentamente a la posición inicial. Durante el movimiento, no dejes que tus codos se adelanten.","name":"Jalón al pecho con agarre ancho","created":"2025-11-06T03:10:34.889Z","last_update":"2026-04-13T18:58:26.685Z","language":4,"uuid":"437728fc-2909-4e43-b2a4-07f6de81b5f1","exercise":1702}}],"aliases":[],"comments":[]}'),
('wger', '1703', 'dumbbell-patadas-traseras', 'https://wger.de/en/exercise/1703/view', 'CC-BY-SA-4.0', 'Mariano_O', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1703,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Mariano_O","license_author_url":"","license_derivative_source_url":"","uuid":"17dd0986-5248-410d-89a4-9268282d103b","category":8,"variation_group":null,"created":"2025-11-06T03:37:05.568Z","last_update":"2025-11-06T03:37:05.568Z","muscles":[5],"muscles_secondary":[],"equipment":[8,3]}},"translations":[{"model":"exercises.translation","pk":2823,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Mariano_O","license_author_url":"","license_derivative_source_url":"","description":"<p>The dumbbell kickback is a popular strength training exercise that targets the triceps muscles in the back of your upper arms. It helps strengthen and tone the triceps, contributing to overall arm strength and aesthetics.</p>\n<p>Among the exercises that work the arm muscles, kickback and its variations are very effective. You can easily apply these exercises with dumbbells, cables or resistance bands.</p>\n","description_source":"The dumbbell kickback is a popular strength training exercise that targets the triceps muscles in the back of your upper arms. It helps strengthen and tone the triceps, contributing to overall arm strength and aesthetics.\n\nAmong the exercises that work the arm muscles, kickback and its variations are very effective. You can easily apply these exercises with dumbbells, cables or resistance bands.","name":"Patadas traseras","created":"2025-11-06T03:37:05.662Z","last_update":"2026-04-13T18:58:26.908Z","language":2,"uuid":"e92c0b60-f8a9-49c9-ad76-2fdcdfc6181f","exercise":1703}},{"model":"exercises.translation","pk":2824,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Mariano_O","license_author_url":"","license_derivative_source_url":"","description":"<p>Posición inicial</p>\n<p>Coloca tu rodilla izquierda y tu mano izquierda en un banco, con el pecho paralelo al suelo. Mantén el pie derecho en el suelo y agarra la mancuerna con la mano derecha. Manteniéndola cerca de tu cuerpo, levanta la parte superior de tu brazo derecho hasta que esté paralelo al suelo.</p>\n<p>Ejecución</p>\n<p>Realiza una extensión del brazo derecho. Cuando esté completamente extendido, contrae tu tríceps por un momento antes de volver a la posición inicial. Una vez que hayas completado tu serie, haz lo mismo con el otro brazo.</p>\n","description_source":"Posición inicial\n\nColoca tu rodilla izquierda y tu mano izquierda en un banco, con el pecho paralelo al suelo. Mantén el pie derecho en el suelo y agarra la mancuerna con la mano derecha. Manteniéndola cerca de tu cuerpo, levanta la parte superior de tu brazo derecho hasta que esté paralelo al suelo.\n\nEjecución\n\nRealiza una extensión del brazo derecho. Cuando esté completamente extendido, contrae tu tríceps por un momento antes de volver a la posición inicial. Una vez que hayas completado tu serie, haz lo mismo con el otro brazo.","name":"Patadas traseras","created":"2025-11-06T03:37:05.710Z","last_update":"2026-04-13T18:58:26.909Z","language":4,"uuid":"2729444f-94d2-432a-adcc-1c3169797d92","exercise":1703}}],"aliases":[],"comments":[]}'),
('wger', '1704', 'tuck-l-sit', 'https://wger.de/en/exercise/1704/view', 'CC-BY-SA-4.0', 'clafal', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1704,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"clafal","license_author_url":"","license_derivative_source_url":"","uuid":"9396a728-3da4-4390-ae4d-882395805008","category":10,"variation_group":null,"created":"2025-11-07T20:19:18.372Z","last_update":"2025-11-07T20:19:18.372Z","muscles":[6],"muscles_secondary":[13,4,10,9,5],"equipment":[8]}},"translations":[{"model":"exercises.translation","pk":2825,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"clafal","license_author_url":"","license_derivative_source_url":"","description":"<p>The tuck L-sit is a bodyweight hold where you support yourself on parallel bars, parallettes, or the floor with straight arms while pulling your knees toward your chest. Your hips stay lifted, your spine stays tall, and your feet hover off the ground. The goal is to keep your core tight, shoulders depressed, and arms locked out while maintaining the tucked position. It’s a core-intensive, shoulder-stabilizing static hold often used as a progression toward the full L-sit.</p>\n","description_source":"The tuck L-sit is a bodyweight hold where you support yourself on parallel bars, parallettes, or the floor with straight arms while pulling your knees toward your chest. Your hips stay lifted, your spine stays tall, and your feet hover off the ground. The goal is to keep your core tight, shoulders depressed, and arms locked out while maintaining the tucked position. It’s a core-intensive, shoulder-stabilizing static hold often used as a progression toward the full L-sit.","name":"Tuck L-sit","created":"2025-11-07T20:19:18.442Z","last_update":"2026-04-13T18:58:27.731Z","language":2,"uuid":"9edaf458-b333-4ab0-b063-0246af63a817","exercise":1704}}],"aliases":[],"comments":[]}'),
('wger', '1706', 'dumbbell-bulgarian-squat', 'https://wger.de/en/exercise/1706/view', 'CC-BY-SA-4.0', 'AlucardEvil40', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1706,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"AlucardEvil40","license_author_url":"","license_derivative_source_url":"","uuid":"60d2c34b-43a1-48a3-b43b-160e4c0157f2","category":9,"variation_group":null,"created":"2025-11-10T15:22:08.397Z","last_update":"2025-11-10T15:22:08.397Z","muscles":[8,10],"muscles_secondary":[11],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2827,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"AlucardEvil40","license_author_url":"","license_derivative_source_url":"","description":"<p>The Bulgarian split squat consists of performing a squat on one leg with the rear foot resting on a raised platform. Elevating your back leg on a bench creates instability and increases the range of motion of the exercise.</p>\n","description_source":"The Bulgarian split squat consists of performing a squat on one leg with the rear foot resting on a raised platform. Elevating your back leg on a bench creates instability and increases the range of motion of the exercise.","name":"Bulgarian Squat with Dumbbells","created":"2025-11-10T15:22:08.454Z","last_update":"2026-04-13T18:58:26.143Z","language":2,"uuid":"08eef404-f074-4e54-bea1-da588bda17f3","exercise":1706}},{"model":"exercises.translation","pk":2828,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"AlucardEvil40","license_author_url":"","license_derivative_source_url":"","description":"<p>Le squat bulgare consiste à faire un squat sur une jambe avec le pied arrière en appui sur une plateforme surélevée. Le fait de surélever votre jambe sur un banc crée une instabilité et augmente l''amplitude de mouvement de l''exercice.</p>\n","description_source":"Le squat bulgare consiste à faire un squat sur une jambe avec le pied arrière en appui sur une plateforme surélevée. Le fait de surélever votre jambe sur un banc crée une instabilité et augmente l''amplitude de mouvement de l''exercice.","name":"Squats bulgares haltères","created":"2025-11-10T15:22:08.484Z","last_update":"2026-04-13T18:58:27.511Z","language":12,"uuid":"5201f09b-bd07-41fa-875e-b032255fe223","exercise":1706}}],"aliases":[],"comments":[]}'),
('wger', '1707', 'elevacion-lateral-polea', 'https://wger.de/en/exercise/1707/view', 'CC-BY-SA-4.0', 'polloperro', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1707,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"polloperro","license_author_url":"","license_derivative_source_url":"","uuid":"a2fa24ba-597f-4746-b9b0-fbabae6396e6","category":12,"variation_group":null,"created":"2025-11-10T15:34:22.632Z","last_update":"2025-11-10T15:34:22.632Z","muscles":[2],"muscles_secondary":[],"equipment":[9]}},"translations":[{"model":"exercises.translation","pk":2829,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"polloperro","license_author_url":"","license_derivative_source_url":"","description":"<p>Lateral elevation unilateral using a polea</p>\n","description_source":"Lateral elevation unilateral using a polea ","name":"Elevación lateral polea","created":"2025-11-10T15:34:22.675Z","last_update":"2026-04-13T18:58:26.481Z","language":2,"uuid":"2b8efcfc-861b-4a5f-b0f9-34b7f84a7d0e","exercise":1707}},{"model":"exercises.translation","pk":2830,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"polloperro","license_author_url":"","license_derivative_source_url":"","description":"<p>elevaciones laterales realizadas unilateralmente en polea</p>\n","description_source":"elevaciones laterales realizadas unilateralmente en polea","name":"Elevacion lateral polea","created":"2025-11-10T15:34:22.702Z","last_update":"2026-04-13T18:58:26.466Z","language":4,"uuid":"c365b2c0-ea6c-4867-b5c8-7ad29c56a050","exercise":1707}}],"aliases":[],"comments":[]}'),
('wger', '1709', 'band-reverse-fly-standing', 'https://wger.de/en/exercise/1709/view', 'CC-BY-SA-4.0', 'Croak6728', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1709,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Croak6728","license_author_url":"","license_derivative_source_url":"","uuid":"440cf10c-effb-4b63-a6e0-182fe47376f6","category":13,"variation_group":null,"created":"2025-11-11T13:49:52.336Z","last_update":"2025-11-11T13:49:52.336Z","muscles":[2,9],"muscles_secondary":[],"equipment":[11]}},"translations":[{"model":"exercises.translation","pk":2832,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Croak6728","license_author_url":"","license_derivative_source_url":"","description":"<ol>\n<li>Stand with a good posture holding a cable in each hand opposite the machine</li>\n<li>Starting with the hands in front of your chest pull the arms out to\nyour side into the shape of a T with the elbows nearly straight</li>\n<li>Slowly release the arms forward to the start</li>\n<li>Repeat with the arms moving into the shape of a Y</li>\n<li>Repeat with the arms in the shape of a W</li>\n<li>Repeat with the arms in the shape of an L by your side</li>\n</ol>\n","description_source":"1. Stand with a good posture holding a cable in each hand opposite the machine\n2. Starting with the hands in front of your chest pull the arms out to\n   your side into the shape of a T with the elbows nearly straight\n3. Slowly release the arms forward to the start\n4. Repeat with the arms moving into the shape of a Y\n5. Repeat with the arms in the shape of a W\n6. Repeat with the arms in the shape of an L by your side","name":"Reverse Fly Standing","created":"2025-11-11T13:49:52.364Z","last_update":"2026-04-13T18:58:27.150Z","language":2,"uuid":"22e11532-11be-4057-847a-baf8388ef45a","exercise":1709}}],"aliases":[],"comments":[{"model":"exercises.exercisecomment","pk":556,"fields":{"uuid":"4837f5b7-4147-4f08-b8da-7dae7e356162","translation":2832,"comment":"The full described cycle is one rep."}}]}'),
('wger', '1710', 'butchers-block-stretch', 'https://wger.de/en/exercise/1710/view', 'CC-BY-SA-4.0', 'Croak6728', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1710,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Croak6728","license_author_url":"","license_derivative_source_url":"","uuid":"4885c051-154b-4a9b-a0fe-ccb70a652fa4","category":13,"variation_group":null,"created":"2025-11-11T13:53:58.462Z","last_update":"2025-11-11T13:53:58.462Z","muscles":[12],"muscles_secondary":[9],"equipment":[8]}},"translations":[{"model":"exercises.translation","pk":2833,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Croak6728","license_author_url":"","license_derivative_source_url":"","description":"<ol>\n<li>Kneel down with the hands together</li>\n<li>Rest the elbows on a bench in front of you and lower the chest down</li>\n<li>Keep the elbows bent with good posture and hold</li>\n</ol>\n","description_source":"1. Kneel down with the hands together\n2. Rest the elbows on a bench in front of you and lower the chest down\n3. Keep the elbows bent with good posture and hold","name":"Butchers Block Stretch","created":"2025-11-11T13:53:58.560Z","last_update":"2026-04-13T18:58:26.162Z","language":2,"uuid":"0058685c-65ab-4347-b6e1-32f251de654e","exercise":1710}}],"aliases":[],"comments":[]}'),
('wger', '1711', 'sleeper-stretch', 'https://wger.de/en/exercise/1711/view', 'CC-BY-SA-4.0', 'Croak6728', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1711,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Croak6728","license_author_url":"","license_derivative_source_url":"","uuid":"90f12b1b-b33e-4d83-9f9e-e26d3a4b8e0b","category":13,"variation_group":null,"created":"2025-11-11T13:58:04.522Z","last_update":"2025-11-11T13:58:04.522Z","muscles":[2],"muscles_secondary":[9],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2834,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Croak6728","license_author_url":"","license_derivative_source_url":"","description":"<ol>\n<li>Lie on your side so that you are resting a little weight on your shoulder blade to keep it still</li>\n<li>Extend your arm to 90 degrees in front of you, resting on the floor/mat</li>\n<li>Lift your hand with your elbow so that your fingers point to the ceiling and your palm points towards your feet</li>\n<li>Keeping your elbow still, gently lower your palm toward the floor</li>\n</ol>\n","description_source":"1. Lie on your side so that you are resting a little weight on your shoulder blade to keep it still\n2. Extend your arm to 90 degrees in front of you, resting on the floor/mat\n3. Lift your hand with your elbow so that your fingers point to the ceiling and your palm points towards your feet\n4. Keeping your elbow still, gently lower your palm toward the floor","name":"Sleeper Stretch","created":"2025-11-11T13:58:04.590Z","last_update":"2026-04-13T18:58:27.430Z","language":2,"uuid":"c1724d71-9012-4f4a-aae8-55fbc6933700","exercise":1711}}],"aliases":[],"comments":[]}'),
('wger', '1712', 'horizontal-shoulder-flexion-stretch', 'https://wger.de/en/exercise/1712/view', 'CC-BY-SA-4.0', 'Croak6728', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1712,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Croak6728","license_author_url":"","license_derivative_source_url":"","uuid":"ca4c8872-e53c-47ca-bc33-448b9ba9360f","category":13,"variation_group":null,"created":"2025-11-11T14:01:59.451Z","last_update":"2025-11-11T14:01:59.451Z","muscles":[4],"muscles_secondary":[2],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2835,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Croak6728","license_author_url":"","license_derivative_source_url":"","description":"<ol>\n<li>Raise your arm out to the side, placing your hand on a wall or doorway beside you at shoulder height</li>\n<li>Turn your body away from your arm to stretch the chest, as far as is comfortable</li>\n</ol>\n","description_source":"1. Raise your arm out to the side, placing your hand on a wall or doorway beside you at shoulder height\n2. Turn your body away from your arm to stretch the chest, as far as is comfortable","name":"Horizontal Shoulder Flexion Stretch","created":"2025-11-11T14:01:59.536Z","last_update":"2026-04-13T18:58:26.640Z","language":2,"uuid":"f20eaa3c-0b35-4e14-a4ba-e7fad017ddcd","exercise":1712}}],"aliases":[],"comments":[{"model":"exercises.exercisecomment","pk":557,"fields":{"uuid":"730b9285-3e57-442e-ba0a-b1512a6cfa74","translation":2835,"comment":"Gently push your hand forward against the wall/doorway, keeping your elbow straight"}}]}'),
('wger', '1713', 'doorway-pectoral-stretch', 'https://wger.de/en/exercise/1713/view', 'CC-BY-SA-4.0', 'Croak6728', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1713,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Croak6728","license_author_url":"","license_derivative_source_url":"","uuid":"adbb1d4c-962b-4a26-a353-9c47a2b37a93","category":11,"variation_group":null,"created":"2025-11-11T14:05:31.602Z","last_update":"2025-11-11T14:05:31.602Z","muscles":[4],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2836,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Croak6728","license_author_url":"","license_derivative_source_url":"","description":"<ol>\n<li>Place the forearm vertically on a door frame or stationary object at head height</li>\n<li>Step forward past the arm, keeping it still against the object to stretch the chest</li>\n</ol>\n","description_source":"1. Place the forearm vertically on a door frame or stationary object at head height\n2. Step forward past the arm, keeping it still against the object to stretch the chest","name":"Doorway Pectoral Stretch","created":"2025-11-11T14:05:31.722Z","last_update":"2026-04-13T18:58:26.399Z","language":2,"uuid":"3a3ebcbc-5edd-4135-88b9-1783a753f85b","exercise":1713}}],"aliases":[],"comments":[]}'),
('wger', '1714', 'dumbbell-shoulder-pendular-exercise', 'https://wger.de/en/exercise/1714/view', 'CC-BY-SA-4.0', 'Croak6728', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1714,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Croak6728","license_author_url":"","license_derivative_source_url":"","uuid":"e237611c-2730-4d0c-891b-bb29d3d15297","category":13,"variation_group":null,"created":"2025-11-11T14:10:11.133Z","last_update":"2025-11-11T14:10:11.133Z","muscles":[2,12,4,9],"muscles_secondary":[],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2837,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Croak6728","license_author_url":"","license_derivative_source_url":"","description":"<ol>\n<li>Lean forward to rest your hand on a chair or other object, holding a dumbbell in the other hand</li>\n<li>Gently swing the dumbbell in a circular motion</li>\n</ol>\n","description_source":"1. Lean forward to rest your hand on a chair or other object, holding a dumbbell in the other hand\n2. Gently swing the dumbbell in a circular motion","name":"Shoulder Dumbbell Pendular Exercise","created":"2025-11-11T14:10:11.207Z","last_update":"2026-04-13T18:58:27.339Z","language":2,"uuid":"08d1487e-6505-47e7-939a-8723e69e263a","exercise":1714}}],"aliases":[],"comments":[{"model":"exercises.exercisecomment","pk":558,"fields":{"uuid":"53a50161-4a47-4603-b0f8-15090afe211c","translation":2837,"comment":"One clockwise circle and one counter-clockwise circle are together one rep."}}]}'),
('wger', '1715', 'dumbbell-shoulder-external-rotation', 'https://wger.de/en/exercise/1715/view', 'CC-BY-SA-4.0', 'Croak6728', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1715,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Croak6728","license_author_url":"","license_derivative_source_url":"","uuid":"2eead109-098e-4c59-bdef-f580a6a82748","category":13,"variation_group":null,"created":"2025-11-11T14:13:10.358Z","last_update":"2025-11-11T14:13:10.358Z","muscles":[2,13],"muscles_secondary":[9],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2838,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Croak6728","license_author_url":"","license_derivative_source_url":"","description":"<ol>\n<li>Lie on your side holding a dumbbell in your upper hand</li>\n<li>Tuck your elbow into your side and rest the hand in front of you</li>\n<li>Rotate the shoulder so the hand raises up</li>\n<li>Lower the hand down</li>\n</ol>\n","description_source":"1. Lie on your side holding a dumbbell in your upper hand\n2. Tuck your elbow into your side and rest the hand in front of you\n3. Rotate the shoulder so the hand raises up\n4. Lower the hand down","name":"Shoulder External Rotation with Dumbbell","created":"2025-11-11T14:13:10.420Z","last_update":"2026-04-13T18:58:27.342Z","language":2,"uuid":"4fcef00d-0646-4b97-8754-be10690eef30","exercise":1715}}],"aliases":[],"comments":[]}'),
('wger', '1716', 'incline-shoulder-press-up', 'https://wger.de/en/exercise/1716/view', 'CC-BY-SA-4.0', 'Croak6728', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1716,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Croak6728","license_author_url":"","license_derivative_source_url":"","uuid":"743690d3-dbfb-417a-a049-8b77fd5df31b","category":11,"variation_group":null,"created":"2025-11-11T14:17:05.926Z","last_update":"2025-11-11T14:17:05.926Z","muscles":[2,4],"muscles_secondary":[],"equipment":[8]}},"translations":[{"model":"exercises.translation","pk":2839,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Croak6728","license_author_url":"","license_derivative_source_url":"","description":"<ol>\n<li>Place your hands on the bench in a press up position</li>\n<li>Push your chest away from the bench to separate your shoulder blades</li>\n<li><strong>Keeping your elbows straight</strong>, lower your chest towards the bench so your shoulder blades move closer together</li>\n<li>Push your chest away from the bench again</li>\n</ol>\n","description_source":"1. Place your hands on the bench in a press up position\n2. Push your chest away from the bench to separate your shoulder blades\n3. **Keeping your elbows straight**, lower your chest towards the bench so your shoulder blades move closer together\n4. Push your chest away from the bench again","name":"Incline Shoulder Press Up","created":"2025-11-11T14:17:05.971Z","last_update":"2026-04-13T18:58:26.662Z","language":2,"uuid":"8f9962e8-e512-4ba9-989b-c6172716c82b","exercise":1716}}],"aliases":[],"comments":[]}'),
('wger', '1717', 'ez-bar-neck-extension', 'https://wger.de/en/exercise/1717/view', 'CC-BY-SA-4.0', 'polloperro', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1717,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"polloperro","license_author_url":"","license_derivative_source_url":"","uuid":"d27a93fa-7066-477c-a475-c6b6170831db","category":8,"variation_group":null,"created":"2025-11-11T20:05:29.566Z","last_update":"2025-11-11T20:05:29.566Z","muscles":[1],"muscles_secondary":[],"equipment":[2]}},"translations":[{"model":"exercises.translation","pk":2840,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"polloperro","license_author_url":"","license_derivative_source_url":"","description":"<p>Unilateral triceps exercise with your back to the pulley, with the pulley at the top</p>\n","description_source":"Unilateral triceps exercise with your back to the pulley, with the pulley at the top","name":"Neck extension","created":"2025-11-11T20:05:29.618Z","last_update":"2026-04-13T18:58:26.863Z","language":2,"uuid":"69f230b2-1b05-46ed-9d7a-1a1dc48237fc","exercise":1717}},{"model":"exercises.translation","pk":2841,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"polloperro","license_author_url":"","license_derivative_source_url":"","description":"<p>Ejerecicio realizado en polea alta, de espaldas a la polea. Unilateral</p>\n","description_source":"Ejerecicio realizado en polea alta, de espaldas a la polea. Unilateral","name":"Codo unilateral polea alta","created":"2025-11-11T20:05:29.648Z","last_update":"2026-04-13T18:58:26.219Z","language":4,"uuid":"20f74559-14a9-497a-a758-842546af7827","exercise":1717}}],"aliases":[],"comments":[]}'),
