('wger', '1719', 'dumbbell-jalon-caballero-unialteral', 'https://wger.de/en/exercise/1719/view', 'CC-BY-SA-4.0', 'polloperro', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1719,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"polloperro","license_author_url":"","license_derivative_source_url":"","uuid":"dcd81ab4-1e6f-4123-b4a5-3364195faf7b","category":12,"variation_group":null,"created":"2025-11-11T20:32:21.821Z","last_update":"2025-11-11T20:32:21.821Z","muscles":[13,14],"muscles_secondary":[],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2844,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"polloperro","license_author_url":"","license_derivative_source_url":"","description":"Pull performed in knight''s stance\n\n","description_source":"```\nPull performed in knight''s stance\n```","name":"Jalon caballero unialteral","created":"2025-11-11T20:32:21.866Z","last_update":"2026-04-13T18:58:26.679Z","language":2,"uuid":"3d1a1689-7ceb-4fdb-801b-7ebc816ce4c0","exercise":1719}},{"model":"exercises.translation","pk":2845,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"polloperro","license_author_url":"","license_derivative_source_url":"","description":"<p>Jalón unilateral realizado en postura de caballero. La rodilla que se apoya en el suelo es la misma de la mano que hace la fuerza</p>\n","description_source":"Jalón unilateral realizado en postura de caballero. La rodilla que se apoya en el suelo es la misma de la mano que hace la fuerza","name":"Jalón caballero unialteral","created":"2025-11-11T20:32:21.890Z","last_update":"2026-04-13T18:58:26.687Z","language":4,"uuid":"7b86e2bf-d3b4-48d0-b8d4-564f713441c3","exercise":1719}}],"aliases":[],"comments":[]}'),
('wger', '1723', 'machine-glute-kickback', 'https://wger.de/en/exercise/1723/view', 'CC-BY-SA-4.0', 'barry', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1723,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"barry","license_author_url":"","license_derivative_source_url":"","uuid":"66ed6788-a1d8-49a2-af4d-397107fbf5fb","category":9,"variation_group":null,"created":"2025-11-24T17:35:58.621Z","last_update":"2025-11-24T17:35:58.621Z","muscles":[8],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2849,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"barry","license_author_url":"","license_derivative_source_url":"","description":"<p>Drive through your heel, not your toes, to hit the glute.</p>\n<p>Don’t hyperextend your lower back at the top.</p>\n","description_source":"Drive through your heel, not your toes, to hit the glute.\n\nDon’t hyperextend your lower back at the top.","name":"Glute Kickback (Machine)","created":"2025-11-24T17:35:58.696Z","last_update":"2026-04-13T18:58:26.594Z","language":2,"uuid":"42f27d57-7b19-464f-b2cf-1177a6d1b352","exercise":1723}}],"aliases":[],"comments":[]}'),
('wger', '1724', NULL, 'https://wger.de/en/exercise/1724/view', 'CC-BY-SA-4.0', 'barry', NULL, NULL, '{"exercise":{"model":"exercises.exercise","pk":1724,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"barry","license_author_url":"","license_derivative_source_url":"","uuid":"93b9b84c-7b72-4712-a7c2-0e14a5fab32a","category":9,"variation_group":null,"created":"2025-11-24T17:45:38.556Z","last_update":"2025-11-24T17:45:38.556Z","muscles":[],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2850,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"barry","license_author_url":"","license_derivative_source_url":"","description":"<p>Keep your hips square and still, pulling the cable across your opposing leg using only your inner thigh.</p>\n<p>Don’t let your torso lean or twist — no side bending to help the rep.</p>\n","description_source":"Keep your hips square and still, pulling the cable across your opposing leg using only your inner thigh.\n\nDon’t let your torso lean or twist — no side bending to help the rep.","name":"Standing Adduction (Cable)","created":"2025-11-24T17:45:38.626Z","last_update":"2026-04-13T18:58:27.517Z","language":2,"uuid":"e9a8de1a-6af3-4c35-858d-b839f77046e3","exercise":1724}}],"aliases":[],"comments":[]}');
