('wger', '1725', 'machine-seated-row', 'https://wger.de/en/exercise/1725/view', 'CC-BY-SA-4.0', 'barry', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1725,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"barry","license_author_url":"","license_derivative_source_url":"","uuid":"9bcc7b4f-4172-4db7-be95-d7b659c486f5","category":12,"variation_group":null,"created":"2025-11-24T19:06:34.952Z","last_update":"2025-11-24T19:06:34.952Z","muscles":[12],"muscles_secondary":[2,9],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2851,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"barry","license_author_url":"","license_derivative_source_url":"","description":"<p>Keep your chest up and squeeze your shoulder blades at the end.</p>\n<p>Don’t hunch forward or round your back during the pull.</p>\n","description_source":"Keep your chest up and squeeze your shoulder blades at the end.\n\nDon’t hunch forward or round your back during the pull.","name":"Seated Row (Machine)","created":"2025-11-24T19:06:35.026Z","last_update":"2026-04-13T18:58:27.284Z","language":2,"uuid":"5e5e04ad-a750-4faf-b3ea-397feed76afb","exercise":1725}}],"aliases":[],"comments":[]}'),
('wger', '1726', 'cable-straight-arm-pulldown', 'https://wger.de/en/exercise/1726/view', 'CC-BY-SA-4.0', 'barry', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1726,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"barry","license_author_url":"","license_derivative_source_url":"","uuid":"a45123c6-34c2-43cf-b6bf-914a8f40995a","category":12,"variation_group":null,"created":"2025-11-24T19:12:30.021Z","last_update":"2025-11-24T19:12:30.021Z","muscles":[12],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2852,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"barry","license_author_url":"","license_derivative_source_url":"","description":"<p>Keep arms straight but not locked, pulling with your lats, not your shoulders.</p>\n<p>Don’t let your shoulders shrug up during the movement.</p>\n","description_source":"Keep arms straight but not locked, pulling with your lats, not your shoulders.\n\nDon’t let your shoulders shrug up during the movement.","name":"Straight-Arm Pulldown (Cable)","created":"2025-11-24T19:12:30.110Z","last_update":"2026-04-13T18:58:27.561Z","language":2,"uuid":"96f8a9a4-e81c-46ec-80b4-72db9e42e240","exercise":1726}}],"aliases":[],"comments":[]}'),
('wger', '1727', 'cable-side-straight-arm-pulldown', 'https://wger.de/en/exercise/1727/view', 'CC-BY-SA-4.0', 'barry', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1727,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"barry","license_author_url":"","license_derivative_source_url":"","uuid":"0dd4dde7-9712-4c06-8ebe-16bc7a0b1917","category":12,"variation_group":null,"created":"2025-11-24T19:20:26.257Z","last_update":"2025-11-24T19:20:26.257Z","muscles":[12],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2853,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"barry","license_author_url":"","license_derivative_source_url":"","description":"<p>Keep your torso still, pulling the handle down along your side using the outer lat.</p>\n<p>Don’t twist your body or rotate your torso to cheat the rep.</p>\n","description_source":"Keep your torso still, pulling the handle down along your side using the outer lat.\n\nDon’t twist your body or rotate your torso to cheat the rep.","name":"Side Straight-Arm Pulldown (Cable)","created":"2025-11-24T19:20:26.316Z","last_update":"2026-04-13T18:58:27.379Z","language":2,"uuid":"fcd6bc74-d670-41f3-9385-269f4fa98679","exercise":1727}}],"aliases":[],"comments":[]}'),
('wger', '1728', 'cable-shoulder-internal-rotation', 'https://wger.de/en/exercise/1728/view', 'CC-BY-SA-4.0', 'barry', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1728,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"barry","license_author_url":"","license_derivative_source_url":"","uuid":"dadecc94-6322-4c66-93b5-9cb44ec79e46","category":13,"variation_group":null,"created":"2025-11-24T19:40:15.142Z","last_update":"2025-11-24T19:40:15.142Z","muscles":[2],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2854,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"barry","license_author_url":"","license_derivative_source_url":"","description":"<p>Keep your elbow tucked to your side like it''s superglued there.</p>\n<p>Don’t rotate your torso — only your forearm should move.</p>\n","description_source":"Keep your elbow tucked to your side like it''s superglued there.\n\nDon’t rotate your torso — only your forearm should move.","name":"Shoulder Internal Rotation (Cable)","created":"2025-11-24T19:40:15.201Z","last_update":"2026-04-13T18:58:27.343Z","language":2,"uuid":"5812567f-6c35-4205-8a66-b0f57b1e3c4d","exercise":1728}}],"aliases":[],"comments":[]}'),
('wger', '1729', 'cable-shoulder-external-rotation', 'https://wger.de/en/exercise/1729/view', 'CC-BY-SA-4.0', 'barry', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1729,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"barry","license_author_url":"","license_derivative_source_url":"","uuid":"b283cd47-9a1c-4004-9bf5-220560ef0a16","category":13,"variation_group":null,"created":"2025-11-24T19:41:17.283Z","last_update":"2025-11-24T19:41:17.283Z","muscles":[2],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2855,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"barry","license_author_url":"","license_derivative_source_url":"","description":"<p>Keep elbow fixed at your side and rotate forearm outward smoothly.</p>\n<p>Don’t let your wrist or elbow drift upward — stay in one plane.</p>\n","description_source":"Keep elbow fixed at your side and rotate forearm outward smoothly.\n\nDon’t let your wrist or elbow drift upward — stay in one plane.","name":"Shoulder External Rotation (Cable)","created":"2025-11-24T19:41:17.325Z","last_update":"2026-04-13T18:58:27.340Z","language":2,"uuid":"67cf4888-28ed-4fa6-bee0-1c24434fe954","exercise":1729}}],"aliases":[],"comments":[]}'),
('wger', '1730', 'cable-side-lateral-raise', 'https://wger.de/en/exercise/1730/view', 'CC-BY-SA-4.0', 'barry', 'new', 100.0, '{"exercise":{"model":"exercises.exercise","pk":1730,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"barry","license_author_url":"","license_derivative_source_url":"","uuid":"dba57084-d148-4b22-bb90-2fdd3a845ca4","category":12,"variation_group":null,"created":"2025-11-24T19:42:42.191Z","last_update":"2025-11-24T19:42:42.191Z","muscles":[12],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2856,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"barry","license_author_url":"","license_derivative_source_url":"","description":"<p>Lift with your elbows leading, not your hands.</p>\n<p>Don’t shrug your shoulders; keep traps quiet.</p>\n","description_source":"Lift with your elbows leading, not your hands.\n\nDon’t shrug your shoulders; keep traps quiet.","name":"Side Lateral Raise (Cable)","created":"2025-11-24T19:42:42.219Z","last_update":"2026-04-13T18:58:27.372Z","language":2,"uuid":"d85618ff-5e22-441f-943b-01b39c109634","exercise":1730}}],"aliases":[],"comments":[]}'),
('wger', '1731', 'cable-front-raise', 'https://wger.de/en/exercise/1731/view', 'CC-BY-SA-4.0', 'barry', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1731,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"barry","license_author_url":"","license_derivative_source_url":"","uuid":"be9dfe16-9fc3-463d-a9cd-7aade27ef571","category":13,"variation_group":null,"created":"2025-11-24T19:43:27.418Z","last_update":"2025-11-24T19:43:27.418Z","muscles":[2],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2857,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"barry","license_author_url":"","license_derivative_source_url":"","description":"<p>Raise the handle in a slight arc with controlled movement.</p>\n<p>Don’t swing your torso to start the rep.</p>\n","description_source":"Raise the handle in a slight arc with controlled movement.\n\nDon’t swing your torso to start the rep.","name":"Front Raise (Cable)","created":"2025-11-24T19:43:27.474Z","last_update":"2026-04-13T18:58:26.574Z","language":2,"uuid":"a53b46d4-0242-4b8e-8125-1fd8b0aea7d0","exercise":1731}}],"aliases":[],"comments":[]}'),
('wger', '1732', 'band-face-pull-yellow-green', 'https://wger.de/en/exercise/1732/view', 'CC-BY-SA-4.0', '54str', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1732,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"54str","license_author_url":"","license_derivative_source_url":"","uuid":"7bf4e131-d4a3-44c0-8fca-9e10002492e7","category":12,"variation_group":null,"created":"2025-12-05T05:59:28.726Z","last_update":"2025-12-05T05:59:28.726Z","muscles":[12],"muscles_secondary":[9],"equipment":[11]}},"translations":[{"model":"exercises.translation","pk":2858,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"54str","license_author_url":"","license_derivative_source_url":"","description":"<p>Face pulls with band – standing horizontal pull. Grab the band at face height, pull elbows high and wide towards your face while squeezing shoulder blades together. Trains upper back, rear shoulders and improves posture.</p>\n","description_source":"Face pulls with band – standing horizontal pull. Grab the band at face height, pull elbows high and wide towards your face while squeezing shoulder blades together. Trains upper back, rear shoulders and improves posture.","name":"Face pulls with yellow/green band","created":"2025-12-05T05:59:28.798Z","last_update":"2026-04-13T18:58:26.519Z","language":2,"uuid":"89c7649f-214d-42cd-ac00-c496cdad0206","exercise":1732}}],"aliases":[],"comments":[]}'),
('wger', '1733', 'isometric-squat-to-failure', 'https://wger.de/en/exercise/1733/view', 'CC-BY-SA-4.0', 'Tierrasverdes', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1733,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Tierrasverdes","license_author_url":"","license_derivative_source_url":"","uuid":"06cb77ba-e56d-4422-bc14-77cc367c9fd8","category":9,"variation_group":null,"created":"2025-12-06T10:24:58.745Z","last_update":"2025-12-06T10:24:58.746Z","muscles":[8,10],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2859,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Tierrasverdes","license_author_url":"","license_derivative_source_url":"","description":"<p>sometric Squat to Failure: A Strength Training Technique</p>\n<p>Definition</p>\n<p>The isometric squat to failure is a variation of the squat exercise where you hold a static squat position at a specific angle, maintaining the position until your muscles can no longer sustain the contraction.</p>\n","description_source":"sometric Squat to Failure: A Strength Training Technique\n\nDefinition\n\nThe isometric squat to failure is a variation of the squat exercise where you hold a static squat position at a specific angle, maintaining the position until your muscles can no longer sustain the contraction.","name":"Isometric Squat to Failure","created":"2025-12-06T10:24:58.811Z","last_update":"2026-04-13T18:58:26.674Z","language":2,"uuid":"2df1ce8a-ab24-4ce2-98dd-e988608d5d02","exercise":1733}},{"model":"exercises.translation","pk":2860,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Tierrasverdes","license_author_url":"","license_derivative_source_url":"","description":"<p>Sentadilla Isométrica al Fallo</p>\n<p>Definición</p>\n<p>La sentadilla isométrica al fallo es una variante de ejercicio de sentadilla donde mantienes una posición estática de sentadilla en un ángulo específico, sosteniendo la posición hasta que los músculos no pueden mantener más la contracción.</p>\n<p>Tipo de Contracción Isométrica (estática, sin movimiento)</p>\n<p>Grupos Musculares Principales Cuádriceps, glúteos, músculos posteriores del muslo</p>\n<p>Intensidad Muy alta, trabaja hasta el agotamiento muscular</p>\n<p>Beneficios Mejora fuerza, resistencia muscular, estabilidad</p>\n<p>Técnica de Ejecución</p>\n<p>Colócate en posición de sentadilla con los pies separados al ancho de las caderas</p>\n<p>Desciende hasta formar un ángulo de 90 grados en las rodillas</p>\n<p>Mantén esa posición completamente inmóvil</p>\n<p>Resiste hasta que los músculos fallen y no puedas sostener más la posición</p>\n<p>Beneficios</p>\n<p>Desarrollo de fuerza máxima</p>\n<p>Mejora de la resistencia muscular</p>\n<p>Fortalecimiento de la estabilidad articular</p>\n<p>Incremento de la tolerancia al dolor muscular</p>\n<p>Precauciones</p>\n<p>No recomendado para principiantes</p>\n<p>Riesgo de fatiga muscular intensa</p>\n<p>Consultar con un profesional antes de implementarlo</p>\n<p>Usar con moderación en la rutina de entrenamiento</p>\n","description_source":"Sentadilla Isométrica al Fallo\n\nDefinición\n\nLa sentadilla isométrica al fallo es una variante de ejercicio de sentadilla donde mantienes una posición estática de sentadilla en un ángulo específico, sosteniendo la posición hasta que los músculos no pueden mantener más la contracción.\n\nTipo de Contracción Isométrica (estática, sin movimiento)\n\nGrupos Musculares Principales Cuádriceps, glúteos, músculos posteriores del muslo\n\nIntensidad Muy alta, trabaja hasta el agotamiento muscular\n\nBeneficios Mejora fuerza, resistencia muscular, estabilidad\n\nTécnica de Ejecución\n\nColócate en posición de sentadilla con los pies separados al ancho de las caderas\n\nDesciende hasta formar un ángulo de 90 grados en las rodillas\n\nMantén esa posición completamente inmóvil\n\nResiste hasta que los músculos fallen y no puedas sostener más la posición\n\nBeneficios\n\nDesarrollo de fuerza máxima\n\nMejora de la resistencia muscular\n\nFortalecimiento de la estabilidad articular\n\nIncremento de la tolerancia al dolor muscular\n\nPrecauciones\n\nNo recomendado para principiantes\n\nRiesgo de fatiga muscular intensa\n\nConsultar con un profesional antes de implementarlo\n\nUsar con moderación en la rutina de entrenamiento","name":"Sentadilla isometrica al fallo","created":"2025-12-06T10:24:58.846Z","last_update":"2026-04-13T18:58:27.316Z","language":4,"uuid":"48112c38-f3f6-4d87-bae2-408b4287f468","exercise":1733}}],"aliases":[],"comments":[]}'),
('wger', '1734', 'kettlebell-single-leg-lunge', 'https://wger.de/en/exercise/1734/view', 'CC-BY-SA-4.0', 'Tierrasverdes', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1734,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Tierrasverdes","license_author_url":"","license_derivative_source_url":"","uuid":"ff6c2fb1-5105-49ba-babe-c0d403940269","category":9,"variation_group":null,"created":"2025-12-06T11:24:30.759Z","last_update":"2025-12-06T11:24:30.759Z","muscles":[7,8,10],"muscles_secondary":[],"equipment":[10]}},"translations":[{"model":"exercises.translation","pk":2861,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Tierrasverdes","license_author_url":"","license_derivative_source_url":"","description":"<p>How to do a single-leg kettlebell lunge</p>\n<p>Preparation: Stand with your feet together. Hold the kettlebell with both hands by the handle, keeping it close to your chest, or hold it with one hand (on the same side as the working leg).</p>\n<p>Step and Lower: Take a large step forward (or backward, which is safer for your knees) with one leg, lowering your hips until both knees form a 90-degree angle.</p>\n<p>Focus: Shift your weight onto your front (or bent) leg, keeping your back straight and your torso upright.</p>\n<p>Return: Push off with your front leg to return to the starting position.</p>\n","description_source":"How to do a single-leg kettlebell lunge\n\nPreparation: Stand with your feet together. Hold the kettlebell with both hands by the handle, keeping it close to your chest, or hold it with one hand (on the same side as the working leg).\n\nStep and Lower: Take a large step forward (or backward, which is safer for your knees) with one leg, lowering your hips until both knees form a 90-degree angle.\n\nFocus: Shift your weight onto your front (or bent) leg, keeping your back straight and your torso upright.\n\nReturn: Push off with your front leg to return to the starting position.","name":"Single-Leg Lunge with Kettlebell:","created":"2025-12-06T11:24:30.825Z","last_update":"2026-04-13T18:58:27.405Z","language":2,"uuid":"25f14529-47c4-4d9c-b1df-306812c35575","exercise":1734}},{"model":"exercises.translation","pk":2862,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Tierrasverdes","license_author_url":"","license_derivative_source_url":"","description":"<p>La \"zancada con pesa rusa a una pierna\" (o unilateral)\nes un ejercicio que mejora el equilibrio y la fuerza, implicando sujetar la pesa rusa cerca del pecho o con un brazo (mismo lado de la pierna de apoyo) y bajar en una zancada profunda, alternando piernas, o hacer variantes como sentadillas búlgaras con kettlebell, enfocándose en la estabilidad y el trabajo unilateral del tren inferior para fortalecer cuádriceps, glúteos y femorales, con versiones hacia adelante, atrás o laterales.&nbsp;\nCómo hacer la zancada unilateral con pesa rusa\nPreparación: Ponte de pie con los pies juntos. Sujeta la pesa rusa con ambas manos por el asa, manteniéndola pegada al pecho, o sosténla con una sola mano (del mismo lado que la pierna que trabajará).\nPaso y descenso: Da un gran paso hacia adelante (o hacia atrás, que es más seguro para las rodillas) con una pierna, bajando la cadera hasta que ambas rodillas formen un ángulo de 90 grados.\nEnfoque: Desplaza el peso hacia la pierna delantera (o la que se flexiona), manteniendo la espalda recta y el torso erguido.\nRegreso: Empuja con la pierna delantera para volver a la posición inicial.</p>\n","description_source":"La \"zancada con pesa rusa a una pierna\" (o unilateral)\nes un ejercicio que mejora el equilibrio y la fuerza, implicando sujetar la pesa rusa cerca del pecho o con un brazo (mismo lado de la pierna de apoyo) y bajar en una zancada profunda, alternando piernas, o hacer variantes como sentadillas búlgaras con kettlebell, enfocándose en la estabilidad y el trabajo unilateral del tren inferior para fortalecer cuádriceps, glúteos y femorales, con versiones hacia adelante, atrás o laterales. \nCómo hacer la zancada unilateral con pesa rusa\nPreparación: Ponte de pie con los pies juntos. Sujeta la pesa rusa con ambas manos por el asa, manteniéndola pegada al pecho, o sosténla con una sola mano (del mismo lado que la pierna que trabajará).\nPaso y descenso: Da un gran paso hacia adelante (o hacia atrás, que es más seguro para las rodillas) con una pierna, bajando la cadera hasta que ambas rodillas formen un ángulo de 90 grados.\nEnfoque: Desplaza el peso hacia la pierna delantera (o la que se flexiona), manteniendo la espalda recta y el torso erguido.\nRegreso: Empuja con la pierna delantera para volver a la posición inicial.","name":"Zancada con pesa rusa a una pierna","created":"2025-12-06T11:24:30.866Z","last_update":"2026-04-13T18:58:27.913Z","language":4,"uuid":"96bc2709-db3e-4313-af32-abff1367b459","exercise":1734}}],"aliases":[],"comments":[]}'),
('wger', '1735', 'single-leg-side-glute-press', 'https://wger.de/en/exercise/1735/view', 'CC-BY-SA-4.0', 'Tierrasverdes', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1735,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Tierrasverdes","license_author_url":"","license_derivative_source_url":"","uuid":"d28cf04f-4077-484b-82ed-abaea8d4053d","category":9,"variation_group":null,"created":"2025-12-06T12:47:42.575Z","last_update":"2025-12-06T12:47:42.575Z","muscles":[7,8,10],"muscles_secondary":[],"equipment":[9]}},"translations":[{"model":"exercises.translation","pk":2863,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Tierrasverdes","license_author_url":"","license_derivative_source_url":"","description":"<p>The Single-Leg Side Glute Press is a leg press machine variation where you angle your body sideways on the pad, placing one foot high and slightly angled to press the weight, powerfully targeting the outer glute (gluteus medius/minimus) and hamstrings for balanced leg development and stability, requiring focus on pushing through the heel and maintaining control without locking out.</p>\n<p>How to Perform:</p>\n<p>Setup: Sit in the leg press machine, rotate your body to one hip, placing one foot high on the platform at about a 45-degree angle with toes pointed slightly out/forward.</p>\n<p>Positioning: Keep your hip, knee, and ankle aligned, and ensure your lower back stays on the pad.</p>\n<p>Descent: Slowly lower the weight, allowing your knee to bend deeply (near 90 degrees), feeling a stretch in your glute and hamstring.</p>\n<p>Press: Drive through your heel (not your toes) to press the weight back up, squeezing your glutes and hamstrings, stopping just before your leg fully extends.</p>\n<p>Control: Avoid bouncing and don''t let your lower back lift off the pad; maintain tension throughout the movement.</p>\n","description_source":"The Single-Leg Side Glute Press is a leg press machine variation where you angle your body sideways on the pad, placing one foot high and slightly angled to press the weight, powerfully targeting the outer glute (gluteus medius/minimus) and hamstrings for balanced leg development and stability, requiring focus on pushing through the heel and maintaining control without locking out.\n\nHow to Perform:\n\nSetup: Sit in the leg press machine, rotate your body to one hip, placing one foot high on the platform at about a 45-degree angle with toes pointed slightly out/forward.\n\nPositioning: Keep your hip, knee, and ankle aligned, and ensure your lower back stays on the pad.\n\nDescent: Slowly lower the weight, allowing your knee to bend deeply (near 90 degrees), feeling a stretch in your glute and hamstring.\n\nPress: Drive through your heel (not your toes) to press the weight back up, squeezing your glutes and hamstrings, stopping just before your leg fully extends.\n\nControl: Avoid bouncing and don''t let your lower back lift off the pad; maintain tension throughout the movement.","name":"Single-leg side glute press","created":"2025-12-06T12:47:42.732Z","last_update":"2026-04-13T18:58:27.409Z","language":2,"uuid":"6dac8fe0-60bb-4be7-a7e7-560b42015937","exercise":1735}},{"model":"exercises.translation","pk":2864,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Tierrasverdes","license_author_url":"","license_derivative_source_url":"","description":"<p>Colócate en la máquina de prensa de piernas, pero en lugar de sentarte de frente, siéntate de lado para que la pierna que vas a trabajar quede alineada con la plataforma móvil. Asegura tu espalda contra el respaldo y agárrate bien de las asas para mantener la estabilidad</p>\n<p>Coloca el pie de la pierna de trabajo en la plataforma, asegurándote de que el talón quede bien apoyado y que la pierna esté casi completamente extendida, pero sin bloquear la rodilla. Desbloquea la seguridad de la máquina. Baja la plataforma lentamente y con control, doblando la rodilla y la cadera. El objetivo es llevar el talón lo más cerca posible de tu glúteo sin que la zona lumbar se despegue del respaldo. Es crucial mantener la espalda recta y no encorvarse.</p>\n<p>Empuja la plataforma hacia arriba usando principalmente la fuerza del glúteo y el cuádriceps, volviendo a la posición inicial (pierna casi extendida). Concéntrate en la contracción muscular en la parte superior del movimiento</p>\n<p>Evita rebotar o usar el impulso</p>\n<p>Comienza con un peso ligero para dominar la técnica y evitar lesiones, especialmente en la espalda baja o las rodillas.</p>\n","description_source":"Colócate en la máquina de prensa de piernas, pero en lugar de sentarte de frente, siéntate de lado para que la pierna que vas a trabajar quede alineada con la plataforma móvil. Asegura tu espalda contra el respaldo y agárrate bien de las asas para mantener la estabilidad\n\nColoca el pie de la pierna de trabajo en la plataforma, asegurándote de que el talón quede bien apoyado y que la pierna esté casi completamente extendida, pero sin bloquear la rodilla. Desbloquea la seguridad de la máquina. Baja la plataforma lentamente y con control, doblando la rodilla y la cadera. El objetivo es llevar el talón lo más cerca posible de tu glúteo sin que la zona lumbar se despegue del respaldo. Es crucial mantener la espalda recta y no encorvarse.\n\nEmpuja la plataforma hacia arriba usando principalmente la fuerza del glúteo y el cuádriceps, volviendo a la posición inicial (pierna casi extendida). Concéntrate en la contracción muscular en la parte superior del movimiento\n\nEvita rebotar o usar el impulso\n\nComienza con un peso ligero para dominar la técnica y evitar lesiones, especialmente en la espalda baja o las rodillas.","name":"Gluteo en prensa de lado con una pierna","created":"2025-12-06T12:47:42.791Z","last_update":"2026-04-13T18:58:26.595Z","language":4,"uuid":"54ae1173-a3f3-45f5-a024-00c346fd6a05","exercise":1735}}],"aliases":[],"comments":[]}'),
('wger', '1736', 'dumbbell-single-leg-deadlift', 'https://wger.de/en/exercise/1736/view', 'CC-BY-SA-4.0', 'Tierrasverdes', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1736,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Tierrasverdes","license_author_url":"","license_derivative_source_url":"","uuid":"a630de17-9170-434c-b486-96a6b8705506","category":9,"variation_group":"ad96df0d-30be-46ea-887f-606642c2f13b","created":"2025-12-07T10:53:51.065Z","last_update":"2025-12-07T10:53:51.166Z","muscles":[11,8],"muscles_secondary":[],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2865,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Tierrasverdes","license_author_url":"","license_derivative_source_url":"","description":"<p>Starting Position: Stand upright with a slight bend in your knees, holding a dumbbell in one or both hands. Shift your weight onto your supporting leg (e.g., your right leg) and lift your non-supporting foot slightly off the floor.</p>\n<p>The Hinge: Keeping your back flat and core engaged, hinge at your hips, pushing your glutes backward. As your torso lowers, extend your non-supporting leg straight back behind you for balance, keeping your hips square to the floor. The dumbbell(s) should lower toward the ground along the line of your supporting leg.</p>\n<p>Range of Motion: Continue lowering your torso until it is nearly parallel to the floor, or you feel an intense stretch in your supporting hamstring, ensuring your back remains neutral throughout the movement.</p>\n<p>Return to Start: Pause at the bottom, then contract your glutes and hamstrings to slowly raise your torso back to the starting position. Your non-supporting leg should return in line with the supporting one.</p>\n<p>Switch Sides: After completing your desired number of repetitions on one side, switch your weight and repeat the movement on the other leg.</p>\n","description_source":"Starting Position: Stand upright with a slight bend in your knees, holding a dumbbell in one or both hands. Shift your weight onto your supporting leg (e.g., your right leg) and lift your non-supporting foot slightly off the floor.\n\nThe Hinge: Keeping your back flat and core engaged, hinge at your hips, pushing your glutes backward. As your torso lowers, extend your non-supporting leg straight back behind you for balance, keeping your hips square to the floor. The dumbbell(s) should lower toward the ground along the line of your supporting leg.\n\nRange of Motion: Continue lowering your torso until it is nearly parallel to the floor, or you feel an intense stretch in your supporting hamstring, ensuring your back remains neutral throughout the movement.\n\nReturn to Start: Pause at the bottom, then contract your glutes and hamstrings to slowly raise your torso back to the starting position. Your non-supporting leg should return in line with the supporting one.\n\nSwitch Sides: After completing your desired number of repetitions on one side, switch your weight and repeat the movement on the other leg.","name":"Single-Leg Deadlift with Dumbbell","created":"2025-12-07T10:53:51.116Z","last_update":"2026-04-13T18:58:27.403Z","language":2,"uuid":"833be9e4-eb83-45fe-98c0-74ba95cf458a","exercise":1736}},{"model":"exercises.translation","pk":2866,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Tierrasverdes","license_author_url":"","license_derivative_source_url":"","description":"<p>Postura inicial:</p>\n<p>Sostén una mancuerna en la mano opuesta a la pierna que vas a utilizar como soporte. (Si te paras sobre la pierna derecha, sostén la mancuerna con la mano izquierda). Esto ayuda a contrarrestar el peso y activa los músculos estabilizadores.</p>\n<p>Mantén la espalda recta y el core activado.</p>\n<p>Mueve ligeramente el peso de tu cuerpo a la pierna de apoyo, con una mínima flexión en la rodilla.</p>\n<p>El movimiento (la bisagra de cadera):</p>\n<p>Inicia el movimiento doblando la cadera hacia atrás, no doblando las rodillas. Imagina que empujas un interruptor con los glúteos.</p>\n<p>Simultáneamente, extiende la pierna libre hacia atrás para mantener el equilibrio. Tu cuerpo debería formar una línea recta desde la cabeza hasta el talón de la pierna extendida.</p>\n<p>Baja la mancuerna hacia el suelo, manteniendo el brazo extendido. El objetivo es que tu torso quede casi paralelo al suelo, o hasta donde tu flexibilidad te lo permita sin curvar la espalda baja.</p>\n<p>El regreso:</p>\n<p>Haz una pausa breve en la parte inferior del movimiento.</p>\n<p>Empuja el suelo con el talón de la pierna de apoyo y contrae los glúteos para volver a la posición inicial, llevando la pierna trasera de vuelta al lado de la de apoyo.</p>\n<p>Mantén el control en todo momento.</p>\n","description_source":"Postura inicial:\n\nSostén una mancuerna en la mano opuesta a la pierna que vas a utilizar como soporte. (Si te paras sobre la pierna derecha, sostén la mancuerna con la mano izquierda). Esto ayuda a contrarrestar el peso y activa los músculos estabilizadores.\n\nMantén la espalda recta y el core activado.\n\nMueve ligeramente el peso de tu cuerpo a la pierna de apoyo, con una mínima flexión en la rodilla.\n\nEl movimiento (la bisagra de cadera):\n\nInicia el movimiento doblando la cadera hacia atrás, no doblando las rodillas. Imagina que empujas un interruptor con los glúteos.\n\nSimultáneamente, extiende la pierna libre hacia atrás para mantener el equilibrio. Tu cuerpo debería formar una línea recta desde la cabeza hasta el talón de la pierna extendida.\n\nBaja la mancuerna hacia el suelo, manteniendo el brazo extendido. El objetivo es que tu torso quede casi paralelo al suelo, o hasta donde tu flexibilidad te lo permita sin curvar la espalda baja.\n\nEl regreso:\n\nHaz una pausa breve en la parte inferior del movimiento.\n\nEmpuja el suelo con el talón de la pierna de apoyo y contrae los glúteos para volver a la posición inicial, llevando la pierna trasera de vuelta al lado de la de apoyo.\n\nMantén el control en todo momento.","name":"Peso muerto a una pierna con mancuerna","created":"2025-12-07T10:53:51.144Z","last_update":"2026-04-13T18:58:26.930Z","language":4,"uuid":"e79431cd-90f9-4471-af5c-a40309866663","exercise":1736}}],"aliases":[],"comments":[]}'),
('wger', '1737', NULL, 'https://wger.de/en/exercise/1737/view', 'CC-BY-SA-4.0', NULL, NULL, NULL, '{"exercise":{"model":"exercises.exercise","pk":1737,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","uuid":"e4bbd8d8-20e1-4174-b785-2590d2a1a7ad","category":12,"variation_group":null,"created":"2025-12-07T21:48:03.518Z","last_update":"2025-12-07T21:48:03.518Z","muscles":[],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2867,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","description":"<p>Chin-ups with machine assistance (counterweights)</p>\n","description_source":"Chin-ups with machine assistance (counterweights)","name":"Assisted chin-ups","created":"2025-12-07T21:48:03.552Z","last_update":"2026-04-13T18:58:26.048Z","language":2,"uuid":"ac2035b3-bb5a-40bc-a05f-02d67a45282a","exercise":1737}}],"aliases":[],"comments":[]}'),
('wger', '1738', 'neutral-grip-pull-up-or-trx-row', 'https://wger.de/en/exercise/1738/view', 'CC-BY-SA-4.0', '54str', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1738,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"54str","license_author_url":"","license_derivative_source_url":"","uuid":"15fda45b-108b-4b28-bfe5-d0e55a0914bf","category":8,"variation_group":null,"created":"2025-12-10T08:47:36.038Z","last_update":"2025-12-10T08:47:36.038Z","muscles":[12],"muscles_secondary":[1],"equipment":[6]}},"translations":[{"model":"exercises.translation","pk":2868,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"54str","license_author_url":"","license_derivative_source_url":"","description":"<ul>\n<li>\n<p><strong>Pull-Up: Vertical Pull — Focuses more on the Lats (back width).</strong></p>\n<p><strong>TRX Row: Horizontal Pull — Focuses more on the Rhomboids/Traps (mid-back thickness and posture).</strong></p>\n</li>\n</ul>\n","description_source":"- **Pull-Up: Vertical Pull — Focuses more on the Lats (back width).**\n\n  **TRX Row: Horizontal Pull — Focuses more on the Rhomboids/Traps (mid-back thickness and posture).**","name":"Neutral-grip pull-ups or TRX rows","created":"2025-12-10T08:47:36.233Z","last_update":"2026-04-13T18:58:26.872Z","language":2,"uuid":"44aeba10-9ef9-4827-aa75-2647e7381502","exercise":1738}}],"aliases":[],"comments":[]}'),
('wger', '1739', NULL, 'https://wger.de/en/exercise/1739/view', 'CC-BY-SA-4.0', 'Happy', NULL, NULL, '{"exercise":{"model":"exercises.exercise","pk":1739,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Happy","license_author_url":"","license_derivative_source_url":"","uuid":"43eeec70-df51-4cad-9bef-a35261b0caaf","category":9,"variation_group":null,"created":"2025-12-10T12:58:53.613Z","last_update":"2025-12-10T12:58:53.613Z","muscles":[],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2869,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Happy","license_author_url":"","license_derivative_source_url":"","description":"<p>Single leg squad where one leg is behind you.</p>\n","description_source":"Single leg squad where one leg is behind you.","name":"Shrimp Squad","created":"2025-12-10T12:58:53.658Z","last_update":"2026-04-13T18:58:27.359Z","language":2,"uuid":"ea097c66-dbe8-419f-9b0c-13da54cca2bd","exercise":1739}}],"aliases":[],"comments":[]}'),
('wger', '1740', 'single-leg-glute-bridge', 'https://wger.de/en/exercise/1740/view', 'CC-BY-SA-4.0', 'Happy', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1740,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Happy","license_author_url":"","license_derivative_source_url":"","uuid":"68f1efb8-e7d2-4a79-99bb-65f128e10a11","category":9,"variation_group":"9e728c35-6e9d-4b3d-8416-1f5b10983de1","created":"2025-12-10T13:01:09.088Z","last_update":"2025-12-10T13:01:09.088Z","muscles":[8],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2870,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Happy","license_author_url":"","license_derivative_source_url":"","description":"<p>A glute bridge, where you use just one leg at a time.</p>\n","description_source":"A glute bridge, where you use just one leg at a time.","name":"Single Leg Glute Bridge","created":"2025-12-10T13:01:09.129Z","last_update":"2026-04-13T18:58:27.395Z","language":2,"uuid":"70c76fe3-4879-4100-ba37-ff31c18c6a3c","exercise":1740}}],"aliases":[],"comments":[]}'),
('wger', '1741', NULL, 'https://wger.de/en/exercise/1741/view', 'CC-BY-SA-4.0', 'Happy', NULL, NULL, '{"exercise":{"model":"exercises.exercise","pk":1741,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Happy","license_author_url":"","license_derivative_source_url":"","uuid":"547217ec-cb9e-4713-8bab-2d8bfb160667","category":8,"variation_group":null,"created":"2025-12-10T13:11:12.128Z","last_update":"2025-12-10T13:11:12.128Z","muscles":[],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2871,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Happy","license_author_url":"","license_derivative_source_url":"","description":"<p>L-Sit Pull-ups train both upper body and core muscles.</p>\n","description_source":"L-Sit Pull-ups train both upper body and core muscles.","name":"L-Sit Pull-ups","created":"2025-12-10T13:11:12.169Z","last_update":"2026-04-13T18:58:26.747Z","language":2,"uuid":"0f8a6fe7-eaa5-457a-ae84-fe97b633da0b","exercise":1741}}],"aliases":[],"comments":[]}'),
('wger', '1742', NULL, 'https://wger.de/en/exercise/1742/view', 'CC-BY-SA-4.0', 'Happy', NULL, NULL, '{"exercise":{"model":"exercises.exercise","pk":1742,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Happy","license_author_url":"","license_derivative_source_url":"","uuid":"8e1cda15-542b-4714-8cc5-c1fe5089ee27","category":12,"variation_group":null,"created":"2025-12-10T13:13:33.020Z","last_update":"2025-12-10T13:13:33.020Z","muscles":[],"muscles_secondary":[],"equipment":[6,7]}},"translations":[{"model":"exercises.translation","pk":2872,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Happy","license_author_url":"","license_derivative_source_url":"","description":"<p>Hanging from a pull-up bar facing downwards with your arms extended</p>\n","description_source":"Hanging from a pull-up bar facing downwards with your arms extended","name":"Back Lever","created":"2025-12-10T13:13:33.052Z","last_update":"2026-04-13T18:58:26.054Z","language":2,"uuid":"96a7e6e9-1604-45a1-813e-1e3374a53dbe","exercise":1742}}],"aliases":[],"comments":[]}'),
('wger', '1743', 'windshield-wiper', 'https://wger.de/en/exercise/1743/view', 'CC-BY-SA-4.0', 'Happy', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1743,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Happy","license_author_url":"","license_derivative_source_url":"","uuid":"026d2939-9156-408b-bf11-21cfa8278851","category":10,"variation_group":null,"created":"2025-12-10T13:15:53.101Z","last_update":"2025-12-10T13:15:53.101Z","muscles":[14,6],"muscles_secondary":[],"equipment":[6,7]}},"translations":[{"model":"exercises.translation","pk":2873,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Happy","license_author_url":"","license_derivative_source_url":"","description":"<p>Hang from a pull-up bar, raise your legs to the ceiling. Move lower body from left to right with straight legs like a windshield wiper</p>\n","description_source":"Hang from a pull-up bar, raise your legs to the ceiling. Move lower body from left to right with straight legs like a windshield wiper","name":"Windshield Wipers","created":"2025-12-10T13:15:53.143Z","last_update":"2026-04-13T18:58:27.872Z","language":2,"uuid":"b09d7088-2fe1-4219-9b2f-c8cd9d0d0593","exercise":1743}}],"aliases":[],"comments":[]}'),
('wger', '1744', 'machine-side-lateral-raise', 'https://wger.de/en/exercise/1744/view', 'CC-BY-SA-4.0', 'Tierrasverdes', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1744,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Tierrasverdes","license_author_url":"","license_derivative_source_url":"","uuid":"dc87b735-016c-410b-915c-e3521fea4be7","category":13,"variation_group":null,"created":"2025-12-10T16:43:52.505Z","last_update":"2025-12-10T16:43:52.505Z","muscles":[2],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2874,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Tierrasverdes","license_author_url":"","license_derivative_source_url":"","description":"<p>Machine side lateral raises are an isolation exercise for the side (lateral) deltoids, performed on a machine for stability, targeting the outer shoulder by lifting pads or handles out to the sides to shoulder height, then lowering slowly, keeping elbows slightly bent and traps down to focus on the delts. This exercise helps build shoulder width by preventing swinging and providing constant tension, making it great for beginners or as a finisher.</p>\n<p>How to Perform Machine Lateral Raises</p>\n<p>Setup: Adjust the seat so your shoulders align with the machine''s pivot point, your chest is against the pad (or back if facing out), and your arms are at a 90-degree angle with the pads/handles.</p>\n<p>Starting Position: Grip the handles with a relaxed grip, elbows slightly bent, and shoulders down (depressed) away from your ears.</p>\n<p>Lifting Phase: Exhale and lift your arms out to the sides, moving your upper arms laterally, until they are parallel to the floor.</p>\n<p>Peak Contraction: Pause briefly at the top, squeezing the side delts, but don''t shrug your shoulders up.</p>\n<p>Lowering Phase: Inhale and slowly lower the weight back down with control, resisting the weight on the way down.</p>\n","description_source":"Machine side lateral raises are an isolation exercise for the side (lateral) deltoids, performed on a machine for stability, targeting the outer shoulder by lifting pads or handles out to the sides to shoulder height, then lowering slowly, keeping elbows slightly bent and traps down to focus on the delts. This exercise helps build shoulder width by preventing swinging and providing constant tension, making it great for beginners or as a finisher.\n\nHow to Perform Machine Lateral Raises\n\nSetup: Adjust the seat so your shoulders align with the machine''s pivot point, your chest is against the pad (or back if facing out), and your arms are at a 90-degree angle with the pads/handles.\n\nStarting Position: Grip the handles with a relaxed grip, elbows slightly bent, and shoulders down (depressed) away from your ears.\n\nLifting Phase: Exhale and lift your arms out to the sides, moving your upper arms laterally, until they are parallel to the floor.\n\nPeak Contraction: Pause briefly at the top, squeezing the side delts, but don''t shrug your shoulders up.\n\nLowering Phase: Inhale and slowly lower the weight back down with control, resisting the weight on the way down.","name":"Machine Side Lateral Raises","created":"2025-12-10T16:43:52.560Z","last_update":"2026-04-13T18:58:26.834Z","language":2,"uuid":"d521872c-6e1f-44f6-b1ae-a83352a21852","exercise":1744}},{"model":"exercises.translation","pk":2875,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Tierrasverdes","license_author_url":"","license_derivative_source_url":"","description":"<p>Técnica de Ejecución</p>\n<p>La elevación lateral en máquina es un ejercicio diseñado para trabajar específicamente el músculo deltoides lateral (hombro medio) con un alto grado de control y seguridad.</p>\n<p>Pasos de Ejecución:</p>\n<p>Ajuste la máquina a su altura y posición correcta</p>\n<p>Siéntese con la espalda apoyada firmemente contra el respaldo</p>\n<p>Agarre los mangos laterales con un agarre cómodo</p>\n<p>Mantenga los codos ligeramente flexionados</p>\n<p>Eleve los brazos lateralmente hasta la altura de los hombros</p>\n<p>Pause brevemente en la posición superior</p>\n<p>Baje los brazos de manera controlada a la posición inicial</p>\n<p>Beneficios</p>\n<p>Aislamiento preciso del deltoides lateral</p>\n<p>Menor riesgo de lesiones en comparación con elevaciones libres</p>\n<p>Control del rango de movimiento</p>\n<p>Ideal para principiantes y rehabilitación</p>\n<p>Consejos Importantes</p>\n<p>Evite balancear o hacer movimientos de impulso</p>\n<p>Mantenga un movimiento controlado y constante</p>\n<p>No sobrecargue el peso</p>\n<p>Respire de manera apropiada: exhale al levantar, inhale al bajar</p>\n","description_source":"Técnica de Ejecución\n\nLa elevación lateral en máquina es un ejercicio diseñado para trabajar específicamente el músculo deltoides lateral (hombro medio) con un alto grado de control y seguridad.\n\nPasos de Ejecución:\n\nAjuste la máquina a su altura y posición correcta\n\nSiéntese con la espalda apoyada firmemente contra el respaldo\n\nAgarre los mangos laterales con un agarre cómodo\n\nMantenga los codos ligeramente flexionados\n\nEleve los brazos lateralmente hasta la altura de los hombros\n\nPause brevemente en la posición superior\n\nBaje los brazos de manera controlada a la posición inicial\n\nBeneficios\n\nAislamiento preciso del deltoides lateral\n\nMenor riesgo de lesiones en comparación con elevaciones libres\n\nControl del rango de movimiento\n\nIdeal para principiantes y rehabilitación\n\nConsejos Importantes\n\nEvite balancear o hacer movimientos de impulso\n\nMantenga un movimiento controlado y constante\n\nNo sobrecargue el peso\n\nRespire de manera apropiada: exhale al levantar, inhale al bajar","name":"Elevación lateral en maquina","created":"2025-12-10T16:43:52.600Z","last_update":"2026-04-13T18:58:26.480Z","language":4,"uuid":"b457d0e1-ed7a-45f7-9700-e21c0fca8ba4","exercise":1744}}],"aliases":[],"comments":[]}'),
('wger', '1745', 'cable-front-raise-small-bar', 'https://wger.de/en/exercise/1745/view', 'CC-BY-SA-4.0', 'Tierrasverdes', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1745,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Tierrasverdes","license_author_url":"","license_derivative_source_url":"","uuid":"6e03ecb3-6bfe-4b34-be9d-e5c33e820cc6","category":13,"variation_group":null,"created":"2025-12-10T17:09:07.350Z","last_update":"2025-12-10T17:09:07.350Z","muscles":[2],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2876,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Tierrasverdes","license_author_url":"","license_derivative_source_url":"","description":"<p>The Cable Front Raise with a small bar isolates your anterior deltoids (front shoulders) by providing constant tension, requiring you to stand facing away from a low pulley, grab the bar with an overhand grip, and lift it in front of you to shoulder height with slightly bent arms, avoiding swinging and keeping your core tight for controlled movement up and down. Use a light-to-moderate weight, focusing on slow, controlled reps to feel the muscle work, not momentum.</p>\n<p>How to Perform the Cable Front Raise (Bar)</p>\n<p>Setup: Attach a small straight bar to a low cable pulley. Set the weight to a light or moderate setting.</p>\n<p>Starting Position: Stand with your back to the machine, holding the bar with an overhand grip (palms facing down) at hip level, arms extended but not locked. Feet shoulder-width apart, core braced, shoulders back and down.</p>\n<p>The Lift: Exhale and slowly raise the bar straight up in front of you, keeping a slight bend in your elbows, until your hands reach shoulder height (or slightly below).</p>\n<p>The Hold: Pause briefly at the top, squeezing your front delts.</p>\n<p>The Lower: Inhale as you slowly and controllably lower the bar back to the starting position, maintaining tension.</p>\n","description_source":"The Cable Front Raise with a small bar isolates your anterior deltoids (front shoulders) by providing constant tension, requiring you to stand facing away from a low pulley, grab the bar with an overhand grip, and lift it in front of you to shoulder height with slightly bent arms, avoiding swinging and keeping your core tight for controlled movement up and down. Use a light-to-moderate weight, focusing on slow, controlled reps to feel the muscle work, not momentum.\n\nHow to Perform the Cable Front Raise (Bar)\n\nSetup: Attach a small straight bar to a low cable pulley. Set the weight to a light or moderate setting.\n\nStarting Position: Stand with your back to the machine, holding the bar with an overhand grip (palms facing down) at hip level, arms extended but not locked. Feet shoulder-width apart, core braced, shoulders back and down.\n\nThe Lift: Exhale and slowly raise the bar straight up in front of you, keeping a slight bend in your elbows, until your hands reach shoulder height (or slightly below).\n\nThe Hold: Pause briefly at the top, squeezing your front delts.\n\nThe Lower: Inhale as you slowly and controllably lower the bar back to the starting position, maintaining tension.","name":"Cable Front Raise with a small bar","created":"2025-12-10T17:09:07.412Z","last_update":"2026-04-13T18:58:26.178Z","language":2,"uuid":"4123458a-bd28-4542-9aec-1b2d11270839","exercise":1745}},{"model":"exercises.translation","pk":2877,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Tierrasverdes","license_author_url":"","license_derivative_source_url":"","description":"<p>Posición inicial: Colócate de espaldas a la polea baja. Agarra la barra recta (o barra Z) con un agarre prono (palmas hacia abajo), a la anchura de los hombros. Da un paso atrás para que la barra quede a la altura de tus muslos, con las rodillas ligeramente flexionadas y el core activado para proteger la zona lumbar.</p>\n<p>Fase de elevación: Levanta la barra hacia adelante en un arco, manteniendo los codos semiflexionados. Sube hasta que la barra esté a la altura de los hombros o un poco por debajo.</p>\n<p>Contracción: En la parte superior, aprieta el deltoides anterior (parte frontal del hombro) durante un instante.</p>\n<p>Fase de descenso: Baja el peso de forma lenta y controlada hasta la posición inicial. La fase excéntrica (bajada) es crucial para el desarrollo muscular.</p>\n<p>Consejos clave</p>\n<p>Evita el balanceo: Mantén el torso firme y no uses el impulso del cuerpo. Si te balanceas, el peso es demasiado alto.</p>\n<p>Codos: Mantenlos ligeramente flexionados y fijos; no los extiendas por completo ni los subas excesivamente.</p>\n<p>Enfoque: Concéntrate en sentir el trabajo en el deltoides anterior. Es un movimiento de flexión de hombro, no de bíceps.</p>\n","description_source":"Posición inicial: Colócate de espaldas a la polea baja. Agarra la barra recta (o barra Z) con un agarre prono (palmas hacia abajo), a la anchura de los hombros. Da un paso atrás para que la barra quede a la altura de tus muslos, con las rodillas ligeramente flexionadas y el core activado para proteger la zona lumbar.\n\nFase de elevación: Levanta la barra hacia adelante en un arco, manteniendo los codos semiflexionados. Sube hasta que la barra esté a la altura de los hombros o un poco por debajo.\n\nContracción: En la parte superior, aprieta el deltoides anterior (parte frontal del hombro) durante un instante.\n\nFase de descenso: Baja el peso de forma lenta y controlada hasta la posición inicial. La fase excéntrica (bajada) es crucial para el desarrollo muscular.\n\nConsejos clave\n\nEvita el balanceo: Mantén el torso firme y no uses el impulso del cuerpo. Si te balanceas, el peso es demasiado alto.\n\nCodos: Mantenlos ligeramente flexionados y fijos; no los extiendas por completo ni los subas excesivamente.\n\nEnfoque: Concéntrate en sentir el trabajo en el deltoides anterior. Es un movimiento de flexión de hombro, no de bíceps.","name":"Elevación frontal en polea con barra","created":"2025-12-10T17:09:07.471Z","last_update":"2026-04-13T18:58:26.478Z","language":4,"uuid":"8422c9f0-739b-4e09-bdb6-4317cad1b447","exercise":1745}}],"aliases":[],"comments":[]}'),
('wger', '1746', 'dumbbell-floor-bench-press', 'https://wger.de/en/exercise/1746/view', 'CC-BY-SA-4.0', '54str', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1746,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"54str","license_author_url":"","license_derivative_source_url":"","uuid":"47ee9fc4-d226-44c8-926b-f52c675b79e2","category":11,"variation_group":null,"created":"2025-12-11T05:35:28.732Z","last_update":"2025-12-11T05:35:28.732Z","muscles":[4],"muscles_secondary":[5],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2879,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"54str","license_author_url":"","license_derivative_source_url":"","description":"<p>This exercise involves lying on your back with a dumbbell in each hand, and pressing them up towards the ceiling, targeting the chest muscles. The dumbbells are then lowered back down to the starting position on the floor.</p>\n","description_source":"This exercise involves lying on your back with a dumbbell in each hand, and pressing them up towards the ceiling, targeting the chest muscles. The dumbbells are then lowered back down to the starting position on the floor.","name":"Floor dumbbell bench press","created":"2025-12-11T05:35:28.783Z","last_update":"2026-04-13T18:58:26.547Z","language":2,"uuid":"143f23a8-dbb7-4fa1-94cd-f8330aff3474","exercise":1746}}],"aliases":[],"comments":[]}'),
('wger', '1747', 'smith-machine-squat', 'https://wger.de/en/exercise/1747/view', 'CC-BY-SA-4.0', 'Tierrasverdes', 'normalized', 100.0, '{"exercise":{"model":"exercises.exercise","pk":1747,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Tierrasverdes","license_author_url":"","license_derivative_source_url":"","uuid":"f3ef220b-a070-449c-a463-876d30cd9b14","category":9,"variation_group":null,"created":"2025-12-11T17:49:08.415Z","last_update":"2025-12-11T17:49:08.415Z","muscles":[8,10],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2880,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Tierrasverdes","license_author_url":"","license_derivative_source_url":"","description":"<p>Technique and Execution</p>\n<p>The Smith machine squat is a variation of the traditional barbell squat that uses a guided, fixed-path barbell. Here''s a detailed breakdown of the proper technique:</p>\n<p>Starting Position</p>\n<p>Foot Placement: Position feet slightly forward of the bar, about shoulder-width apart</p>\n<p>Bar Position: Rest the bar on your upper trapezius/shoulders, similar to a traditional back squat</p>\n<p>Stance: Feet can be slightly angled outward for natural hip rotation</p>\n<p>Squat Movement</p>\n<p>Unrack the bar by rotating it to release from the safety hooks</p>\n<p>Slowly lower your body by bending knees and hips</p>\n<p>Descend until thighs are parallel to the ground (or slightly below)</p>\n<p>Pause briefly at the bottom of the movement</p>\n<p>Drive through your heels to return to the starting position</p>\n<p>Benefits and Considerations</p>\n<p>Advantages</p>\n<p>Reduced Balance Requirements: Fixed bar path makes it easier for beginners</p>\n<p>Controlled Movement: Less risk of improper form compared to free weight squats</p>\n<p>Isolation: Allows focused leg muscle development</p>\n","description_source":"Technique and Execution\n\nThe Smith machine squat is a variation of the traditional barbell squat that uses a guided, fixed-path barbell. Here''s a detailed breakdown of the proper technique:\n\nStarting Position\n\nFoot Placement: Position feet slightly forward of the bar, about shoulder-width apart\n\nBar Position: Rest the bar on your upper trapezius/shoulders, similar to a traditional back squat\n\nStance: Feet can be slightly angled outward for natural hip rotation\n\nSquat Movement\n\nUnrack the bar by rotating it to release from the safety hooks\n\nSlowly lower your body by bending knees and hips\n\nDescend until thighs are parallel to the ground (or slightly below)\n\nPause briefly at the bottom of the movement\n\nDrive through your heels to return to the starting position\n\nBenefits and Considerations\n\nAdvantages\n\nReduced Balance Requirements: Fixed bar path makes it easier for beginners\n\nControlled Movement: Less risk of improper form compared to free weight squats\n\nIsolation: Allows focused leg muscle development","name":"Smith machine squat","created":"2025-12-11T17:49:08.461Z","last_update":"2026-04-13T18:58:27.436Z","language":2,"uuid":"c939e05c-6657-43e2-8027-67611ba68a08","exercise":1747}},{"model":"exercises.translation","pk":2881,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Tierrasverdes","license_author_url":"","license_derivative_source_url":"","description":"<p>Técnica y ejecución</p>\n<p>La sentadilla en máquina Smith es una variante de la sentadilla con barra tradicional que utiliza una barra guiada con una trayectoria fija. Aquí tienes un desglose detallado de la técnica correcta:</p>\n<p>Posición inicial</p>\n<p>Colocación de los pies: Coloca los pies ligeramente por delante de la barra, separados aproximadamente a la anchura de los hombros.</p>\n<p>Posición de la barra: Apoya la barra sobre la parte superior del trapecio/hombros, similar a una sentadilla tradicional.</p>\n<p>Postura: Los pies pueden estar ligeramente inclinados hacia afuera para una rotación natural de la cadera.</p>\n<p>Movimiento de la sentadilla</p>\n<p>Descarga la barra girándola para soltarla de los ganchos de seguridad.</p>\n<p>Baja lentamente el cuerpo flexionando las rodillas y las caderas.</p>\n<p>Desciende hasta que los muslos estén paralelos al suelo (o ligeramente por debajo).</p>\n<p>Haz una breve pausa al final del movimiento.</p>\n<p>Impulsa los talones para volver a la posición inicial.</p>\n<p>Beneficios y consideraciones</p>\n<p>Ventajas</p>\n<p>Requiere menos equilibrio: La trayectoria fija de la barra facilita el movimiento para principiantes.</p>\n<p>Movimiento controlado: Menor riesgo de mala postura en comparación con las sentadillas con peso libre.</p>\n<p>Aislamiento: Permite el desarrollo muscular de las piernas.</p>\n","description_source":"Técnica y ejecución\n\nLa sentadilla en máquina Smith es una variante de la sentadilla con barra tradicional que utiliza una barra guiada con una trayectoria fija. Aquí tienes un desglose detallado de la técnica correcta:\n\nPosición inicial\n\nColocación de los pies: Coloca los pies ligeramente por delante de la barra, separados aproximadamente a la anchura de los hombros.\n\nPosición de la barra: Apoya la barra sobre la parte superior del trapecio/hombros, similar a una sentadilla tradicional.\n\nPostura: Los pies pueden estar ligeramente inclinados hacia afuera para una rotación natural de la cadera.\n\nMovimiento de la sentadilla\n\nDescarga la barra girándola para soltarla de los ganchos de seguridad.\n\nBaja lentamente el cuerpo flexionando las rodillas y las caderas.\n\nDesciende hasta que los muslos estén paralelos al suelo (o ligeramente por debajo).\n\nHaz una breve pausa al final del movimiento.\n\nImpulsa los talones para volver a la posición inicial.\n\nBeneficios y consideraciones\n\nVentajas\n\nRequiere menos equilibrio: La trayectoria fija de la barra facilita el movimiento para principiantes.\n\nMovimiento controlado: Menor riesgo de mala postura en comparación con las sentadillas con peso libre.\n\nAislamiento: Permite el desarrollo muscular de las piernas.","name":"Sentadilla multipower","created":"2025-12-11T17:49:08.493Z","last_update":"2026-04-13T18:58:27.319Z","language":4,"uuid":"a82f0c0d-eea9-4886-9028-88580da3aa75","exercise":1747}}],"aliases":[],"comments":[]}'),
('wger', '1748', 'machine-hip-abduction', 'https://wger.de/en/exercise/1748/view', 'CC-BY-SA-4.0', 'Tierrasverdes', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1748,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Tierrasverdes","license_author_url":"","license_derivative_source_url":"","uuid":"b5726562-82ed-451a-89d8-8c8b13c5019a","category":9,"variation_group":"446c33b6-273b-4b61-8583-8774547cd754","created":"2025-12-11T18:47:02.871Z","last_update":"2025-12-11T18:47:02.969Z","muscles":[8],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2882,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Tierrasverdes","license_author_url":"","license_derivative_source_url":"","description":"<p>Technique and Execution</p>\n<p>Starting Position</p>\n<p>Seated Positioning: Sit in the machine with back against the pad</p>\n<p>Leg Placement: Inner thighs against the machine''s padded resistance points</p>\n<p>Adjust Machine: Set seat position to align your hip joint with the machine''s pivot point</p>\n<p>Movement Technique</p>\n<p>Start with legs together or slightly pressed against the inner pads</p>\n<p>Slowly push legs outward, spreading them apart</p>\n<p>Move until maximum comfortable lateral range is reached</p>\n<p>Pause briefly at the outer point of the movement</p>\n<p>Slowly return to the starting position with controlled movement</p>\n<p>Biomechanical Breakdown</p>\n<p>Muscle Engagement</p>\n<p>Primary Activation: Gluteus Medius (side hip muscle)</p>\n<p>Stabilization: Engages core and lower back muscles</p>\n<p>Functional Movement: Mimics lateral leg movement used in walking, sports, and daily activities</p>\n<p>Benefits</p>\n<p>Strength and Stability</p>\n<p>Improves Hip Stability</p>\n<p>Reduces Risk of Knee Injuries</p>\n<p>Enhances Lateral Movement Capabilities</p>\n<p>Targets Often-Neglected Muscle Groups</p>\n","description_source":"Technique and Execution\n\nStarting Position\n\nSeated Positioning: Sit in the machine with back against the pad\n\nLeg Placement: Inner thighs against the machine''s padded resistance points\n\nAdjust Machine: Set seat position to align your hip joint with the machine''s pivot point\n\nMovement Technique\n\nStart with legs together or slightly pressed against the inner pads\n\nSlowly push legs outward, spreading them apart\n\nMove until maximum comfortable lateral range is reached\n\nPause briefly at the outer point of the movement\n\nSlowly return to the starting position with controlled movement\n\nBiomechanical Breakdown\n\nMuscle Engagement\n\nPrimary Activation: Gluteus Medius (side hip muscle)\n\nStabilization: Engages core and lower back muscles\n\nFunctional Movement: Mimics lateral leg movement used in walking, sports, and daily activities\n\nBenefits\n\nStrength and Stability\n\nImproves Hip Stability\n\nReduces Risk of Knee Injuries\n\nEnhances Lateral Movement Capabilities\n\nTargets Often-Neglected Muscle Groups","name":"Machine Hip Abduction","created":"2025-12-11T18:47:02.917Z","last_update":"2026-04-13T18:58:26.833Z","language":2,"uuid":"da4f64c5-2157-4b82-9567-f4746da0ffef","exercise":1748}},{"model":"exercises.translation","pk":2883,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Tierrasverdes","license_author_url":"","license_derivative_source_url":"","description":"<p>Técnica y ejecución</p>\n<p>Posición inicial</p>\n<p>Posición sentada: Siéntese en la máquina con la espalda apoyada en la almohadilla. Colocación de las piernas: La parte interna de los muslos contra los puntos de resistencia acolchados de la máquina. Ajuste de la máquina: Ajuste la posición del asiento para alinear la articulación de la cadera con el punto de pivote de la máquina.</p>\n<p>Técnica de movimiento</p>\n<p>Comience con las piernas juntas o ligeramente presionadas contra las almohadillas internas. Empuje lentamente las piernas hacia afuera, separándolas. Muévase hasta alcanzar el máximo rango lateral cómodo. Haga una breve pausa en el punto final del movimiento. Regrese lentamente a la posición inicial con un movimiento controlado.</p>\n<p>Desglose biomecánico</p>\n<p>Activación muscular</p>\n<p>Activación principal: Glúteo medio (músculo lateral de la cadera)</p>\n<p>Estabilización: Activa los músculos del core y la zona lumbar.</p>\n<p>Movimiento funcional: Imita el movimiento lateral de las piernas utilizado al caminar, practicar deportes y realizar actividades diarias.</p>\n<p>Beneficios</p>\n<p>Fuerza y ​​estabilidad</p>\n<p>Mejora la estabilidad de la cadera</p>\n<p>Reduce el riesgo de lesiones de rodilla</p>\n<p>Mejora la capacidad de movimiento lateral</p>\n<p>Trabaja grupos musculares a menudo descuidados</p>\n<p>Rehabilitación y prevención</p>\n<p>Beneficioso para:</p>\n<p>Corredores</p>\n<p>Atletas de deportes de movimiento lateral</p>\n<p>Personas que se recuperan de lesiones en la parte inferior del cuerpo</p>\n<p>Prevención de la desalineación de cadera y rodilla</p>\n","description_source":"Técnica y ejecución\n\nPosición inicial\n\nPosición sentada: Siéntese en la máquina con la espalda apoyada en la almohadilla. Colocación de las piernas: La parte interna de los muslos contra los puntos de resistencia acolchados de la máquina. Ajuste de la máquina: Ajuste la posición del asiento para alinear la articulación de la cadera con el punto de pivote de la máquina.\n\nTécnica de movimiento\n\nComience con las piernas juntas o ligeramente presionadas contra las almohadillas internas. Empuje lentamente las piernas hacia afuera, separándolas. Muévase hasta alcanzar el máximo rango lateral cómodo. Haga una breve pausa en el punto final del movimiento. Regrese lentamente a la posición inicial con un movimiento controlado.\n\nDesglose biomecánico\n\nActivación muscular\n\nActivación principal: Glúteo medio (músculo lateral de la cadera)\n\nEstabilización: Activa los músculos del core y la zona lumbar.\n\nMovimiento funcional: Imita el movimiento lateral de las piernas utilizado al caminar, practicar deportes y realizar actividades diarias.\n\nBeneficios\n\nFuerza y ​​estabilidad\n\nMejora la estabilidad de la cadera\n\nReduce el riesgo de lesiones de rodilla\n\nMejora la capacidad de movimiento lateral\n\nTrabaja grupos musculares a menudo descuidados\n\nRehabilitación y prevención\n\nBeneficioso para:\n\nCorredores\n\nAtletas de deportes de movimiento lateral\n\nPersonas que se recuperan de lesiones en la parte inferior del cuerpo\n\nPrevención de la desalineación de cadera y rodilla","name":"Abducción en máquina","created":"2025-12-11T18:47:02.946Z","last_update":"2026-04-13T18:58:25.996Z","language":4,"uuid":"46a0856e-8ab3-47fb-89cf-ad7304ef9003","exercise":1748}}],"aliases":[],"comments":[]}'),
('wger', '1749', 'seated-triceps-press', 'https://wger.de/en/exercise/1749/view', 'CC-BY-SA-4.0', 'Tierrasverdes', 'new', 100.0, '{"exercise":{"model":"exercises.exercise","pk":1749,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Tierrasverdes","license_author_url":"","license_derivative_source_url":"","uuid":"f6f4359d-eeb4-469c-a32f-b4de5732d8a1","category":8,"variation_group":null,"created":"2025-12-11T19:43:42.629Z","last_update":"2025-12-11T19:43:42.629Z","muscles":[5],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2884,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Tierrasverdes","license_author_url":"","license_derivative_source_url":"","description":"<p>Machine Setup</p>\n<p>Adjust the seat height so that the machine''s handles align with your elbow joint</p>\n<p>Ensure your back is firmly supported against the backrest</p>\n<p>Feet should be flat on the floor</p>\n<p>Maintain a neutral spine position</p>\n<p>Movement Mechanics</p>\n<p>Starting Position</p>\n<p>Grip the handles with a neutral grip</p>\n<p>Keep upper arms close to your body</p>\n<p>Elbows bent at approximately 90 degrees</p>\n<p>Press Movement</p>\n<p>Extend arms forward by pushing the handles away</p>\n<p>Focus on using triceps to drive the movement</p>\n<p>Avoid using shoulder or chest muscles</p>\n<p>Fully extend arms without locking elbows</p>\n<p>Return Phase</p>\n<p>Slowly return to the starting position</p>\n<p>Maintain controlled, smooth motion</p>\n<p>Keep tension on the triceps throughout</p>\n","description_source":"Machine Setup\n\nAdjust the seat height so that the machine''s handles align with your elbow joint\n\nEnsure your back is firmly supported against the backrest\n\nFeet should be flat on the floor\n\nMaintain a neutral spine position\n\nMovement Mechanics\n\nStarting Position\n\nGrip the handles with a neutral grip\n\nKeep upper arms close to your body\n\nElbows bent at approximately 90 degrees\n\nPress Movement\n\nExtend arms forward by pushing the handles away\n\nFocus on using triceps to drive the movement\n\nAvoid using shoulder or chest muscles\n\nFully extend arms without locking elbows\n\nReturn Phase\n\nSlowly return to the starting position\n\nMaintain controlled, smooth motion\n\nKeep tension on the triceps throughout","name":"Seated Triceps Press","created":"2025-12-11T19:43:42.673Z","last_update":"2026-04-13T18:58:27.289Z","language":2,"uuid":"bd49b667-9965-485c-ade9-cef89a0e9954","exercise":1749}},{"model":"exercises.translation","pk":2885,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Tierrasverdes","license_author_url":"","license_derivative_source_url":"","description":"<p>El press de tríceps sentado es un ejercicio de entrenamiento de resistencia específico, diseñado específicamente para desarrollar y fortalecer los tríceps.</p>\n<p>Ajuste la altura del asiento para que las manijas de la máquina se alineen con la articulación del codo</p>\n<p>Asegúrese de que la espalda esté firmemente apoyada contra el respaldo</p>\n<p>Los pies deben estar apoyados en el suelo</p>\n<p>Mantenga una posición neutra de la columna</p>\n<p>Posición inicial</p>\n<p>Sujete las manijas con un agarre neutro</p>\n<p>Mantenga los brazos pegados al cuerpo</p>\n<p>Codos doblados aproximadamente a 90 grados</p>\n<p>Movimiento de prensa</p>\n<p>Extienda los brazos hacia adelante empujando las manijas hacia afuera</p>\n<p>Concéntrese en usar los tríceps para impulsar el movimiento</p>\n<p>Evite usar los músculos del hombro o el pecho</p>\n<p>Extienda completamente los brazos sin bloquear los codos</p>\n<p>Regrese lentamente a la posición inicial</p>\n<p>Mantenga un movimiento controlado y suave</p>\n<p>Mantenga la tensión en los tríceps durante todo el ejercicio</p>\n","description_source":"El press de tríceps sentado es un ejercicio de entrenamiento de resistencia específico, diseñado específicamente para desarrollar y fortalecer los tríceps.\n\nAjuste la altura del asiento para que las manijas de la máquina se alineen con la articulación del codo\n\nAsegúrese de que la espalda esté firmemente apoyada contra el respaldo\n\nLos pies deben estar apoyados en el suelo\n\nMantenga una posición neutra de la columna\n\nPosición inicial\n\nSujete las manijas con un agarre neutro\n\nMantenga los brazos pegados al cuerpo\n\nCodos doblados aproximadamente a 90 grados\n\nMovimiento de prensa\n\nExtienda los brazos hacia adelante empujando las manijas hacia afuera\n\nConcéntrese en usar los tríceps para impulsar el movimiento\n\nEvite usar los músculos del hombro o el pecho\n\nExtienda completamente los brazos sin bloquear los codos\n\nRegrese lentamente a la posición inicial\n\nMantenga un movimiento controlado y suave\n\nMantenga la tensión en los tríceps durante todo el ejercicio","name":"Fondos en maquina","created":"2025-12-11T19:43:42.709Z","last_update":"2026-04-13T18:58:26.561Z","language":4,"uuid":"2648d573-f1d2-47df-ba15-1ae43187ceda","exercise":1749}}],"aliases":[],"comments":[]}'),
('wger', '1750', 'dumbbell-romanian-deadlift', 'https://wger.de/en/exercise/1750/view', 'CC-BY-SA-4.0', '54str', 'normalized', 100.0, '{"exercise":{"model":"exercises.exercise","pk":1750,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"54str","license_author_url":"","license_derivative_source_url":"","uuid":"a11f8ace-4718-4e5e-abbc-cb2a183fe7fc","category":9,"variation_group":null,"created":"2025-12-13T12:30:09.060Z","last_update":"2025-12-13T12:30:09.060Z","muscles":[8],"muscles_secondary":[11],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2886,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"54str","license_author_url":"","license_derivative_source_url":"","description":"<p>This exercise involves holding a dumbbell in each hand and bending forward at the hips while keeping the back straight, then returning to a standing position. It primarily targets the hamstrings and glutes.</p>\n","description_source":"This exercise involves holding a dumbbell in each hand and bending forward at the hips while keeping the back straight, then returning to a standing position. It primarily targets the hamstrings and glutes.","name":"Romanian Deadlift","created":"2025-12-13T12:30:09.144Z","last_update":"2026-04-13T18:58:27.173Z","language":2,"uuid":"ba157cf1-19b7-4341-a7e8-9a7fbf15cf60","exercise":1750}}],"aliases":[],"comments":[]}'),
('wger', '1751', 'cable-pull-through', 'https://wger.de/en/exercise/1751/view', 'CC-BY-SA-4.0', 'manuher89', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1751,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"manuher89","license_author_url":"","license_derivative_source_url":"","uuid":"821e289e-bd39-4410-b436-6f2a43bc3649","category":9,"variation_group":null,"created":"2025-12-14T23:35:55.338Z","last_update":"2025-12-14T23:35:55.338Z","muscles":[8],"muscles_secondary":[11,7,10,15],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2887,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"manuher89","license_author_url":"","license_derivative_source_url":"","description":"<p>The <strong>Cable Pull Through</strong> is a lower-body exercise that targets the glutes and hamstrings using a \"hip hinge\" motion. To perform it, attach a rope to the lowest pulley setting, face away from the machine with the rope between your legs, and step forward to create tension. Keeping your back flat and knees slightly soft, push your hips backward as if trying to close a door behind you until you feel a deep stretch in your hamstrings.</p>\n<p>To finish the rep, explosively drive your hips forward to return to a standing position, squeezing your glutes hard at the top. It is vital to remember that this is <strong>not a squat</strong>; your knees should not bend deeply, and your arms should remain straight and relaxed, acting only as hooks for the rope. This movement provides constant tension on the glutes while placing less stress on the lower back than a traditional deadlift.</p>\n","description_source":"The **Cable Pull Through** is a lower-body exercise that targets the glutes and hamstrings using a \"hip hinge\" motion. To perform it, attach a rope to the lowest pulley setting, face away from the machine with the rope between your legs, and step forward to create tension. Keeping your back flat and knees slightly soft, push your hips backward as if trying to close a door behind you until you feel a deep stretch in your hamstrings.\n\nTo finish the rep, explosively drive your hips forward to return to a standing position, squeezing your glutes hard at the top. It is vital to remember that this is **not a squat**; your knees should not bend deeply, and your arms should remain straight and relaxed, acting only as hooks for the rope. This movement provides constant tension on the glutes while placing less stress on the lower back than a traditional deadlift.","name":"Cable pull through","created":"2025-12-14T23:35:55.426Z","last_update":"2026-04-13T18:58:26.186Z","language":2,"uuid":"8d178dff-e8e9-43c1-8c4d-126686073671","exercise":1751}}],"aliases":[],"comments":[]}'),
('wger', '1752', 'cable-side-lateral-raise-front', 'https://wger.de/en/exercise/1752/view', 'CC-BY-SA-4.0', NULL, 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1752,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","uuid":"7f9c13ab-1718-4f8a-8636-232f05f5f640","category":13,"variation_group":null,"created":"2025-12-19T07:41:40.762Z","last_update":"2025-12-19T07:41:40.762Z","muscles":[2],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2889,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","description":"<p>in a cablerack do a side lateral raise with cable in front of you, with focus in tension on the back of your shoulder.</p>\n","description_source":"in a cablerack do a side lateral raise with cable in front of you, with focus in tension on the back of your shoulder.","name":"Side lateral raise - Front (Cable)","created":"2025-12-19T07:41:40.826Z","last_update":"2026-04-13T18:58:27.380Z","language":2,"uuid":"2ac1b840-3d82-4b32-ac95-09c08138e357","exercise":1752}}],"aliases":[],"comments":[]}'),
('wger', '1753', 'cable-side-lateral-raise-back', 'https://wger.de/en/exercise/1753/view', 'CC-BY-SA-4.0', NULL, 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1753,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","uuid":"065ff3ca-a9e8-4339-997e-d65556d9ebf3","category":13,"variation_group":null,"created":"2025-12-19T07:43:03.889Z","last_update":"2025-12-19T07:43:03.889Z","muscles":[2],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2890,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","description":"<p>on a cable rack do a side lateral raise with the cable behind you. focus on tension in the front of the shoulder.</p>\n","description_source":"on a cable rack do a side lateral raise with the cable behind you. focus on tension in the front of the shoulder.","name":"Side lateral raise - Back (Cable)","created":"2025-12-19T07:43:03.918Z","last_update":"2026-04-13T18:58:27.380Z","language":2,"uuid":"3561162e-75d1-4d48-ab56-a575e10fed83","exercise":1753}}],"aliases":[],"comments":[]}'),
('wger', '1754', NULL, 'https://wger.de/en/exercise/1754/view', 'CC-BY-SA-4.0', NULL, NULL, NULL, '{"exercise":{"model":"exercises.exercise","pk":1754,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","uuid":"1f2ba913-3b2e-4621-a70b-b7f0ce649032","category":13,"variation_group":null,"created":"2025-12-19T07:49:51.648Z","last_update":"2025-12-19T07:49:51.648Z","muscles":[],"muscles_secondary":[],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":2891,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","description":"<p>dumbbell raise in the space between front and side raises</p>\n","description_source":"dumbbell raise in the space between front and side raises","name":"45° lateral raises","created":"2025-12-19T07:49:51.740Z","last_update":"2026-04-13T18:58:25.980Z","language":2,"uuid":"44fbff41-9a73-4f67-867f-f8fcc551730e","exercise":1754}}],"aliases":[],"comments":[]}'),
('wger', '1755', NULL, 'https://wger.de/en/exercise/1755/view', 'CC-BY-SA-4.0', NULL, NULL, NULL, '{"exercise":{"model":"exercises.exercise","pk":1755,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","uuid":"7e039ac7-37ab-49f9-9ae8-c7efeef070cd","category":13,"variation_group":null,"created":"2025-12-19T07:54:45.179Z","last_update":"2025-12-19T07:54:45.179Z","muscles":[],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2892,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","description":"<p>on a cable rack cross the cables and pull elbows to ceiling close to the body.</p>\n","description_source":"on a cable rack cross the cables and pull elbows to ceiling close to the body.","name":"Shoulder Y-pull cable","created":"2025-12-19T07:54:45.248Z","last_update":"2026-04-13T18:58:27.354Z","language":2,"uuid":"cadf9006-547e-4d36-8815-cccb5d7b0c2e","exercise":1755}}],"aliases":[],"comments":[]}'),
('wger', '1757', NULL, 'https://wger.de/en/exercise/1757/view', 'CC-BY-SA-4.0', NULL, NULL, NULL, '{"exercise":{"model":"exercises.exercise","pk":1757,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","uuid":"2491eceb-d19e-4da4-a8c5-4d80fea56562","category":11,"variation_group":null,"created":"2025-12-19T09:14:22.324Z","last_update":"2025-12-19T09:14:22.324Z","muscles":[],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2893,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","description":"<p>Colocar a barra em linha reta ao peito e descer ate atingir 90 graus</p>\n","description_source":"Colocar a barra em linha reta ao peito e descer ate atingir 90 graus","name":"supino","created":"2025-12-19T09:14:22.999Z","last_update":"2026-04-13T18:58:27.966Z","language":2,"uuid":"b573ee17-0fda-4ac4-85ce-8f31fae54172","exercise":1757}}],"aliases":[],"comments":[]}'),
('wger', '1763', NULL, 'https://wger.de/en/exercise/1763/view', 'CC-BY-SA-4.0', NULL, NULL, NULL, '{"exercise":{"model":"exercises.exercise","pk":1763,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","uuid":"96ae70d6-7d77-4729-84b4-40f2a423f3d1","category":11,"variation_group":null,"created":"2025-12-19T09:56:47.765Z","last_update":"2025-12-19T09:56:47.765Z","muscles":[],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2895,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","description":"<p>Exercise description....................</p>\n","description_source":"Exercise description....................","name":"supino","created":"2025-12-19T09:56:48.227Z","last_update":"2026-04-13T18:58:27.968Z","language":2,"uuid":"4411f49d-ab2f-4ad4-8843-732cc647842b","exercise":1763}}],"aliases":[],"comments":[]}'),
('wger', '1765', 'pull-up-wide-grip', 'https://wger.de/en/exercise/1765/view', 'CC-BY-SA-4.0', '54str', 'exact', 100.0, '{"exercise":{"model":"exercises.exercise","pk":1765,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"54str","license_author_url":"","license_derivative_source_url":"","uuid":"0bd78ef3-e31c-4c38-be0a-2f3af6fd5cd2","category":12,"variation_group":null,"created":"2025-12-19T13:39:21.836Z","last_update":"2025-12-19T13:39:21.836Z","muscles":[12],"muscles_secondary":[1],"equipment":[6]}},"translations":[{"model":"exercises.translation","pk":2897,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"54str","license_author_url":"","license_derivative_source_url":"","description":"<p>The Pull-Up is a bodyweight exercise that builds strength in your back, shoulders, and biceps. It can be difficult at first, but you can make it easier by using bands or an assisted machine.</p>\n<strong>Instructions</strong>\n<ol>\n<li><strong>Grab the bar:</strong> Place your hands on the bar with your palms facing away from you.</li>\n<li><strong>Get ready:</strong> Take a breath and tighten your stomach muscles.</li>\n<li><strong>Pull up:</strong> Pull your body up until your chest reaches the bar. Think about driving your elbows down.</li>\n<li><strong>Lower down:</strong> Slowly lower yourself back to the starting position.</li>\n</ol>\n","description_source":"The Pull-Up is a bodyweight exercise that builds strength in your back, shoulders, and biceps. It can be difficult at first, but you can make it easier by using bands or an assisted machine.\n\n### **Instructions**\n\n1. **Grab the bar:** Place your hands on the bar with your palms facing away from you.\n2. **Get ready:** Take a breath and tighten your stomach muscles.\n3. **Pull up:** Pull your body up until your chest reaches the bar. Think about driving your elbows down.\n4. **Lower down:** Slowly lower yourself back to the starting position.","name":"Pull-Ups (Wide Grip)","created":"2025-12-19T13:39:21.920Z","last_update":"2026-04-13T18:58:27.088Z","language":2,"uuid":"5351664c-b218-4641-8955-0e85235b6539","exercise":1765}}],"aliases":[],"comments":[]}'),
('wger', '1766', NULL, 'https://wger.de/en/exercise/1766/view', 'CC-BY-SA-4.0', NULL, NULL, NULL, '{"exercise":{"model":"exercises.exercise","pk":1766,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","uuid":"12418067-6cb5-44db-8973-b5be25c0146b","category":10,"variation_group":null,"created":"2025-12-21T06:59:57.801Z","last_update":"2025-12-21T06:59:57.801Z","muscles":[],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2898,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","description":"<p>Position your body in plank position, keeping your eyes on the ground. Raise one arm in front of you and return it. Repeat with the other arm. Raise and return slowly while keeping your body as still as possible.</p>\n","description_source":"Position your body in plank position, keeping your eyes on the ground. Raise one arm in front of you and return it. Repeat with the other arm. Raise and return slowly while keeping your body as still as possible.","name":"Plank Reach","created":"2025-12-21T06:59:57.866Z","last_update":"2026-04-13T18:58:26.967Z","language":2,"uuid":"87a73555-2e74-4969-96a8-ad8601ab4e82","exercise":1766}},{"model":"exercises.translation","pk":2899,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","description":"<p>Bringe deinen Körper in die Planken-Position. Halte den Blick auf den Boden gerichtet und hebe abwechselnd deine Arme langsam nach vorne und zurück. Versuche dabei deinen Körper so ruhig wie möglich zu halten.</p>\n","description_source":"Bringe deinen Körper in die Planken-Position. Halte den Blick auf den Boden gerichtet und hebe abwechselnd deine Arme langsam nach vorne und zurück. Versuche dabei deinen Körper so ruhig wie möglich zu halten.","name":"Unterarmstütz mit Armheben","created":"2025-12-21T06:59:58.014Z","last_update":"2026-04-13T18:58:27.754Z","language":1,"uuid":"d48ad757-28f9-4978-9e45-861da36639a1","exercise":1766}}],"aliases":[],"comments":[]}'),
('wger', '1768', NULL, 'https://wger.de/en/exercise/1768/view', 'CC-BY-SA-4.0', NULL, NULL, NULL, '{"exercise":{"model":"exercises.exercise","pk":1768,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","uuid":"f263ddc9-2418-4bb3-a22c-f79abea18d00","category":8,"variation_group":null,"created":"2025-12-22T12:40:58.356Z","last_update":"2025-12-22T12:40:58.356Z","muscles":[],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2902,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","description":"<p>Não se encontra uma descrição disponível</p>\n","description_source":"Não se encontra uma descrição disponível","name":"bicep","created":"2025-12-22T12:40:58.858Z","last_update":"2026-04-13T18:58:27.939Z","language":2,"uuid":"ecec7438-0ff0-455e-9be7-c4000af60e6f","exercise":1768}}],"aliases":[],"comments":[]}'),
('wger', '1769', NULL, 'https://wger.de/en/exercise/1769/view', 'CC-BY-SA-4.0', NULL, NULL, NULL, '{"exercise":{"model":"exercises.exercise","pk":1769,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","uuid":"d1a37666-9b59-4834-a4ec-80706b34cd49","category":9,"variation_group":null,"created":"2025-12-22T12:44:46.658Z","last_update":"2025-12-22T12:44:46.658Z","muscles":[],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2903,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","description":"<p>Não se encontra uma descrição disponível</p>\n","description_source":"Não se encontra uma descrição disponível","name":"cabel","created":"2025-12-22T12:44:47.254Z","last_update":"2026-04-13T18:58:27.944Z","language":2,"uuid":"ac6cf8f4-a08c-4223-9005-264eaba2b585","exercise":1769}}],"aliases":[],"comments":[]}'),
('wger', '1770', 'machine-seated-row', 'https://wger.de/en/exercise/1770/view', 'CC-BY-SA-4.0', 'mhe', 'normalized', 100.0, '{"exercise":{"model":"exercises.exercise","pk":1770,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"mhe","license_author_url":"","license_derivative_source_url":"","uuid":"af11a7c1-876c-455b-b59a-d8456a99d6e5","category":12,"variation_group":null,"created":"2025-12-22T23:15:06.767Z","last_update":"2025-12-22T23:15:06.767Z","muscles":[12],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2904,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"mhe","license_author_url":"","license_derivative_source_url":"","description":"<p>A seated row machine is a\ngym apparatus for strength training the back (lats, rhomboids, traps)\nby pulling handles toward the torso from a seated position,\nfeaturing adjustable seats and chest pads for proper form, emphasizing\nupright posture and squeezing shoulder blades, crucial for posture and\nback thickness, and distinct from a cardio rowing machine.</p>\n","description_source":"A seated row machine is a\ngym apparatus for strength training the back (lats, rhomboids, traps)\nby pulling handles toward the torso from a seated position,\nfeaturing adjustable seats and chest pads for proper form, emphasizing\nupright posture and squeezing shoulder blades, crucial for posture and\nback thickness, and distinct from a cardio rowing machine.","name":"Seated machine row","created":"2025-12-22T23:15:06.938Z","last_update":"2026-04-13T18:58:27.292Z","language":2,"uuid":"57ba75cd-aa06-457b-ba40-c9674ae4beb8","exercise":1770}}],"aliases":[],"comments":[]}'),
('wger', '1771', 'cable-wrist-curl', 'https://wger.de/en/exercise/1771/view', 'CC-BY-SA-4.0', 'eufvksruh', 'normalized', 100.0, '{"exercise":{"model":"exercises.exercise","pk":1771,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"eufvksruh","license_author_url":"","license_derivative_source_url":"","uuid":"f6471f4a-0290-4a71-9580-bf3d046fdb9d","category":8,"variation_group":"50ebb841-e32e-441c-9dcc-5d3e5f731ed7","created":"2025-12-23T02:12:59.277Z","last_update":"2025-12-23T02:12:59.277Z","muscles":[],"muscles_secondary":[1],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2905,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"eufvksruh","license_author_url":"","license_derivative_source_url":"","description":"<ol>\n<li>Extend your arm down, then slightly lift your forearm</li>\n<li>Extend your wrist in a supinated form (palm up)</li>\n<li>Adjust cable height so that the cable handle is in your supinated hand</li>\n<li>Perform the movement by\ncurling your palms and wrists upwards</li>\n<li>(optional/variable) Pause at the top</li>\n<li>Slowly return to the starting position</li>\n</ol>\n","description_source":"1. Extend your arm down, then slightly lift your forearm\n2. Extend your wrist in a supinated form (palm up)\n3. Adjust cable height so that the cable handle is in your supinated hand\n4. Perform the movement by\n   curling your palms and wrists upwards\n5. (optional/variable) Pause at the top\n6. Slowly return to the starting position","name":"Wrist curl, cable","created":"2025-12-23T02:12:59.332Z","last_update":"2026-04-13T18:58:27.876Z","language":2,"uuid":"bbe20748-d00b-4fc4-9bfa-d418b4a6a713","exercise":1771}}],"aliases":[],"comments":[]}'),
('wger', '1772', 'reverse-crunch', 'https://wger.de/en/exercise/1772/view', 'CC-BY-SA-4.0', 'eufvksruh', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1772,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"eufvksruh","license_author_url":"","license_derivative_source_url":"","uuid":"5d8d3581-bce5-4a28-868f-8b299eaedbdd","category":10,"variation_group":null,"created":"2025-12-23T02:18:37.928Z","last_update":"2025-12-23T02:18:37.928Z","muscles":[6],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2906,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"eufvksruh","license_author_url":"","license_derivative_source_url":"","description":"<ol>\n<li>Lay down</li>\n<li>Place your hands near your butt (often slightly in front or under or both)</li>\n<li>Raise your legs, but about 70% of the way you should be able to also raise your pelvis</li>\n<li>(optional/variable) Hold 1/2 seconds at the top</li>\n<li>Go back to starting position</li>\n</ol>\n","description_source":"1. Lay down\n2. Place your hands near your butt (often slightly in front or under or both)\n3. Raise your legs, but about 70% of the way you should be able to also raise your pelvis\n4. (optional/variable) Hold 1/2 seconds at the top\n5. Go back to starting position","name":"Reverse crunch","created":"2025-12-23T02:18:37.991Z","last_update":"2026-04-13T18:58:27.158Z","language":2,"uuid":"d9bf5b38-7fea-4a76-9f9c-b66ecfec792a","exercise":1772}}],"aliases":[],"comments":[{"model":"exercises.exercisecomment","pk":559,"fields":{"uuid":"f66f91f5-1ef4-4eaa-bfb5-0c2788bb43cc","translation":2906,"comment":"Inclining (legs lower than head), or holding weight between/on your feet increases the difficulty"}}]}'),
('wger', '1773', 'legend-incline-bench-press', 'https://wger.de/en/exercise/1773/view', 'CC-BY-SA-4.0', NULL, 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1773,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","uuid":"e4804b7c-50af-4947-821f-3750718ffe65","category":11,"variation_group":null,"created":"2025-12-25T19:54:44.659Z","last_update":"2025-12-25T19:54:44.659Z","muscles":[4],"muscles_secondary":[2,5],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2907,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","description":"<p>incline bench press on LeverEdge machine.</p>\n","description_source":"incline bench press on LeverEdge machine.","name":"Legend Incline Bench Press","created":"2025-12-25T19:54:44.741Z","last_update":"2026-04-13T18:58:26.787Z","language":2,"uuid":"78d2ce8d-81ff-4ba5-986e-50357b05eea6","exercise":1773}}],"aliases":[{"model":"exercises.alias","pk":605,"fields":{"uuid":"0e15aa7d-be11-4519-ab73-4161375073b9","translation":2907,"alias":"LeverEdge Machine Incline Press"}}],"comments":[]}'),
('wger', '1774', NULL, 'https://wger.de/en/exercise/1774/view', 'CC-BY-SA-4.0', 'tinman', NULL, NULL, '{"exercise":{"model":"exercises.exercise","pk":1774,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"tinman","license_author_url":"","license_derivative_source_url":"","uuid":"aa22b0b7-795d-47a6-8c0b-fdd0f6b9c8fc","category":13,"variation_group":"3bffb851-6462-4f72-845d-f702c955a70a","created":"2025-12-26T11:26:16.585Z","last_update":"2025-12-26T11:26:16.689Z","muscles":[],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2908,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"tinman","license_author_url":"","license_derivative_source_url":"","description":"<p><strong>Starting position:</strong></p>\n<p>Sit down on the front edge of a chair, back straight, hands holding the front edge. Still holding the edge of the chair, arms extended, lift your butt and walk forward slightly so that it is a few inches from the chair.</p>\n<p><strong>Steps:</strong></p>\n<ol>\n<li>\n<p>Slowly lower your body, keeping the back straight, until your arms are at a right angle.</p>\n</li>\n<li>\n<p>Raise your body again to the initial position, arms extended.</p>\n</li>\n<li>\n<p>Repeat.</p>\n</li>\n</ol>\n","description_source":"**Starting position:**\n\nSit down on the front edge of a chair, back straight, hands holding the front edge. Still holding the edge of the chair, arms extended, lift your butt and walk forward slightly so that it is a few inches from the chair.\n\n**Steps:**\n\n1. Slowly lower your body, keeping the back straight, until your arms are at a right angle.\n\n2. Raise your body again to the initial position, arms extended.\n\n3. Repeat.","name":"Chair dips","created":"2025-12-26T11:26:16.631Z","last_update":"2026-04-13T18:58:26.202Z","language":2,"uuid":"84ce2d3f-0085-4f3e-9c75-bde8f3dd55d9","exercise":1774}}],"aliases":[],"comments":[]}'),
('wger', '1775', NULL, 'https://wger.de/en/exercise/1775/view', 'CC-BY-SA-4.0', 'eufvksruh', NULL, NULL, '{"exercise":{"model":"exercises.exercise","pk":1775,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"eufvksruh","license_author_url":"","license_derivative_source_url":"","uuid":"e797ca42-f9fc-480a-8f48-7f6905978c72","category":13,"variation_group":"068dd634-ba84-444d-ab5e-a5da7a6e3896","created":"2026-01-05T18:40:25.954Z","last_update":"2026-01-05T18:40:26.076Z","muscles":[],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2909,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"eufvksruh","license_author_url":"","license_derivative_source_url":"","description":"<p>Seated rear delt fly on pec deck machine (facing the machine and extending arms backwards, the hands should be at the height of the shoulders)</p>\n","description_source":"Seated rear delt fly on pec deck machine (facing the machine and extending arms backwards, the hands should be at the height of the shoulders)","name":"Pec deck rear delt fly","created":"2026-01-05T18:40:26.005Z","last_update":"2026-04-13T18:58:26.913Z","language":2,"uuid":"f188cd25-d057-4d83-b1d0-13ef31120025","exercise":1775}}],"aliases":[],"comments":[]}'),
