('wger', '1777', 'deficit-push-up', 'https://wger.de/en/exercise/1777/view', 'CC-BY-SA-4.0', 'Rottekongen', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1777,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Rottekongen","license_author_url":"","license_derivative_source_url":"","uuid":"b7dd3766-f660-45dc-bbe1-10e15e2f7cee","category":11,"variation_group":null,"created":"2026-01-06T08:54:26.849Z","last_update":"2026-01-06T08:54:26.849Z","muscles":[4],"muscles_secondary":[5],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2911,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Rottekongen","license_author_url":"","license_derivative_source_url":"","description":"<p>Pushup on blocks or grips, so you can dip lower than the hands in the decent.</p>\n","description_source":"Pushup on blocks or grips, so you can dip lower than the hands in the decent.","name":"Deficit Push ups","created":"2026-01-06T08:54:26.899Z","last_update":"2026-04-13T18:58:26.379Z","language":2,"uuid":"2dd9d1cd-7570-43f9-bffb-99ae5e48d2d8","exercise":1777}}],"aliases":[],"comments":[]}'),
