('wger', '1779', NULL, 'https://wger.de/en/exercise/1779/view', 'CC-BY-SA-4.0', 'aboksz', NULL, NULL, '{"exercise":{"model":"exercises.exercise","pk":1779,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"aboksz","license_author_url":"","license_derivative_source_url":"","uuid":"73c1e130-fba9-473b-a093-a5712e2ae34d","category":10,"variation_group":null,"created":"2026-01-07T15:29:36.460Z","last_update":"2026-01-07T15:29:36.460Z","muscles":[],"muscles_secondary":[],"equipment":[1]}},"translations":[{"model":"exercises.translation","pk":2913,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"aboksz","license_author_url":"","license_derivative_source_url":"","description":"<p>Start with landmine barbell straight up by using your shoulders to push it up above you. Then, from that position, bring it your side to target your abdominals and return to starting position.</p>\n","description_source":"Start with landmine barbell straight up by using your shoulders to push it up above you. Then, from that position, bring it your side to target your abdominals and return to starting position.","name":"Landmine Rotation","created":"2026-01-07T15:29:36.511Z","last_update":"2026-04-13T18:58:26.751Z","language":2,"uuid":"8d226a54-cec9-4761-a1b1-cc9455fd6987","exercise":1779}}],"aliases":[],"comments":[]}'),
('wger', '1793', NULL, 'https://wger.de/en/exercise/1793/view', 'CC-BY-SA-4.0', NULL, NULL, NULL, '{"exercise":{"model":"exercises.exercise","pk":1793,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","uuid":"d01d1a2b-2cc8-438c-b604-4db00e1b5860","category":11,"variation_group":null,"created":"2026-01-07T17:30:45.591Z","last_update":"2026-01-07T17:30:45.591Z","muscles":[],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2916,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","description":"<p>Ângulo 90 graus.........................</p>\n","description_source":"Ângulo 90 graus.........................","name":"Supino Inclinado","created":"2026-01-07T17:30:45.875Z","last_update":"2026-04-13T18:58:27.586Z","language":2,"uuid":"079182c8-5814-4102-9828-625af397971d","exercise":1793}}],"aliases":[],"comments":[]}'),
('wger', '1795', 'cable-unilateral-cross-body-pull-down', 'https://wger.de/en/exercise/1795/view', 'CC-BY-SA-4.0', NULL, 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1795,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","uuid":"d788811b-be46-485a-b8a0-0d9ba7f4cf85","category":13,"variation_group":null,"created":"2026-01-08T09:01:32.236Z","last_update":"2026-01-08T09:01:32.236Z","muscles":[2],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2918,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","description":"<p>on a cable rack place cable high, and with a straight arm pull that cable across you from high to low. focus on tension in back shoulder.</p>\n","description_source":"on a cable rack place cable high, and with a straight arm pull that cable across you from high to low. focus on tension in back shoulder.","name":"unilateral cross body cable pull down","created":"2026-01-08T09:01:32.322Z","last_update":"2026-04-13T18:58:27.969Z","language":2,"uuid":"8f5eb4a4-779c-489a-9a98-70abd35282b0","exercise":1795}}],"aliases":[],"comments":[]}'),
('wger', '1798', NULL, 'https://wger.de/en/exercise/1798/view', 'CC-BY-SA-4.0', NULL, NULL, NULL, '{"exercise":{"model":"exercises.exercise","pk":1798,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","uuid":"ec8587cd-5048-4b0c-b244-6d3fe830f9bf","category":8,"variation_group":null,"created":"2026-01-11T01:54:43.362Z","last_update":"2026-01-11T01:54:43.362Z","muscles":[],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2921,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","description":"<p>T red...................................</p>\n","description_source":"T red...................................","name":"Supino","created":"2026-01-11T01:54:43.678Z","last_update":"2026-04-13T18:58:27.584Z","language":2,"uuid":"859b2ced-82b4-4b80-bc02-81db9160c271","exercise":1798}}],"aliases":[],"comments":[]}'),
('wger', '1800', NULL, 'https://wger.de/en/exercise/1800/view', 'CC-BY-SA-4.0', NULL, NULL, NULL, '{"exercise":{"model":"exercises.exercise","pk":1800,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","uuid":"b5f7066a-fcda-47cb-b4bd-4b956b59b52a","category":8,"variation_group":null,"created":"2026-01-14T02:03:58.551Z","last_update":"2026-01-14T02:04:10.155Z","muscles":[],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2923,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","description":"<p>Ângulo de 90 graus devagar..............</p>\n","description_source":"Ângulo de 90 graus devagar..............","name":"Supino Inclinado","created":"2026-01-14T02:03:58.762Z","last_update":"2026-04-13T18:58:27.585Z","language":2,"uuid":"feb95862-ed38-416b-820a-7822c0b9d00d","exercise":1800}}],"aliases":[],"comments":[]}'),
('wger', '1801', 'barbell-full-squat', 'https://wger.de/en/exercise/1801/view', 'CC-BY-SA-4.0', 'fabrice', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1801,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"fabrice","license_author_url":"","license_derivative_source_url":"","uuid":"5d0e0a8b-1940-4034-b4ae-b965859f1ff0","category":9,"variation_group":"bf39ef58-188b-4b23-a6a4-ddbf8863d9e9","created":"2026-01-14T13:18:36.794Z","last_update":"2026-01-14T13:18:36.999Z","muscles":[11,8,10],"muscles_secondary":[7,6],"equipment":[1]}},"translations":[{"model":"exercises.translation","pk":2925,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"fabrice","license_author_url":"","license_derivative_source_url":"","description":"<ul>\n<li>The barbell full squat is a&nbsp;<strong>compound exercise</strong>&nbsp;that&nbsp;<strong>targets multiple muscle groups</strong>&nbsp;in the lower body, including the quadriceps, hamstrings, and glutes.</li>\n<li>Proper form is crucial for maximizing results and preventing injuries during the barbell full squat. This includes maintaining a shoulder-width stance, creating whole body tension, controlling your descent, and maintaining proper depth and knee positioning.</li>\n<li>Assistance moves such as the front squat, goblet squat, split squat, and Bulgarian split squat can help improve your performance in the barbell full squat by targeting specific muscle groups and improving overall technique.</li>\n<li>To&nbsp;<strong>achieve new personal records</strong>&nbsp;in your back squat, gradually increase weight over time, vary rep ranges and sets to stimulate muscle growth, and&nbsp;<strong>prioritize rest and recovery</strong>&nbsp;between training sessions.</li>\n</ul>\n","description_source":"* The barbell full squat is a **compound exercise** that **targets multiple muscle groups** in the lower body, including the quadriceps, hamstrings, and glutes.\n* Proper form is crucial for maximizing results and preventing injuries during the barbell full squat. This includes maintaining a shoulder-width stance, creating whole body tension, controlling your descent, and maintaining proper depth and knee positioning.\n* Assistance moves such as the front squat, goblet squat, split squat, and Bulgarian split squat can help improve your performance in the barbell full squat by targeting specific muscle groups and improving overall technique.\n* To **achieve new personal records** in your back squat, gradually increase weight over time, vary rep ranges and sets to stimulate muscle growth, and **prioritize rest and recovery** between training sessions.","name":"Barbell Full Squat","created":"2026-01-14T13:18:36.867Z","last_update":"2026-04-13T18:58:26.070Z","language":2,"uuid":"55647038-1d20-4d85-bb62-a4ec0d8df590","exercise":1801}}],"aliases":[],"comments":[{"model":"exercises.exercisecomment","pk":560,"fields":{"uuid":"3715dc3b-70b0-4bae-8d0f-2ad677cd3091","translation":2925,"comment":"Start by positioning your feet shoulder-width apart, with toes slightly turned outwards."}}]}'),
('wger', '1803', 'trap-bar-squat', 'https://wger.de/en/exercise/1803/view', 'CC-BY-SA-4.0', 'kmcalderwood', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1803,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"kmcalderwood","license_author_url":"","license_derivative_source_url":"","uuid":"d18407c2-75d0-43d8-8bbc-dfbb256b6b2f","category":9,"variation_group":null,"created":"2026-01-14T16:26:30.211Z","last_update":"2026-01-14T16:26:30.211Z","muscles":[10],"muscles_secondary":[11],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2927,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"kmcalderwood","license_author_url":"","license_derivative_source_url":"","description":"<p>A combination of squat and deadlift principles with the use of a hex/trap bar, easing stress on the lower back by better centering the weight.</p>\n","description_source":"A combination of squat and deadlift principles with the use of a hex/trap bar, easing stress on the lower back by better centering the weight.","name":"Trap Bar Squat","created":"2026-01-14T16:26:30.390Z","last_update":"2026-04-13T18:58:27.675Z","language":2,"uuid":"6308d548-085c-4a22-9260-c41f93f89041","exercise":1803}}],"aliases":[],"comments":[]}'),
('wger', '1804', 'ankle-dorsiflexion-rocks', 'https://wger.de/en/exercise/1804/view', 'CC-BY-SA-4.0', 'Davidgj32', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1804,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Davidgj32","license_author_url":"","license_derivative_source_url":"","uuid":"fa5252d3-973c-4b35-9324-a02460545283","category":9,"variation_group":null,"created":"2026-01-16T07:38:06.283Z","last_update":"2026-01-16T07:38:06.284Z","muscles":[7,15],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2928,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Davidgj32","license_author_url":"","license_derivative_source_url":"","description":"<p>Move your knee forward, keeping your heel on the ground. Hold the position for a couple of seconds and return to the starting position.</p>\n","description_source":"Move your knee forward, keeping your heel on the ground. Hold the position for a couple of seconds and return to the starting position.","name":"ankle dorsiflexion rocks","created":"2026-01-16T07:38:06.340Z","last_update":"2026-04-13T18:58:27.938Z","language":2,"uuid":"929dc8aa-70c7-4a16-83a5-33225a082553","exercise":1804}},{"model":"exercises.translation","pk":2929,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Davidgj32","license_author_url":"","license_derivative_source_url":"","description":"<p>Mueve tu rodilla adelante evitando separar el talón del suelo. Manten la posición un par de segundos y vuelve a&nbsp; la posición inicial</p>\n","description_source":"Mueve tu rodilla adelante evitando separar el talón del suelo. Manten la posición un par de segundos y vuelve a  la posición inicial","name":"Dorsiflexión de tobillo","created":"2026-01-16T07:38:06.368Z","last_update":"2026-04-13T18:58:26.399Z","language":4,"uuid":"ba6ce84f-eb55-48e9-9c21-5b675cdeb0c0","exercise":1804}}],"aliases":[],"comments":[]}'),
('wger', '1805', 'barbell-squat', 'https://wger.de/en/exercise/1805/view', 'CC-BY-SA-4.0', 'Yiannis', 'exact', 100.0, '{"exercise":{"model":"exercises.exercise","pk":1805,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Yiannis","license_author_url":"","license_derivative_source_url":"","uuid":"057e6fe8-a78b-4d8e-8438-d394be5f134a","category":9,"variation_group":null,"created":"2026-01-17T23:43:56.081Z","last_update":"2026-01-17T23:43:56.081Z","muscles":[],"muscles_secondary":[],"equipment":[1]}},"translations":[{"model":"exercises.translation","pk":2931,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Yiannis","license_author_url":"","license_derivative_source_url":"","description":"<p>A barbell squat is a fundamental strength exercise where you lower your body as if sitting in a chair while holding a weighted barbell, primarily targeting leg and core muscles, requiring proper form (chest up, back straight, knees over toes) for safety and effectiveness, engaging quads, hamstrings, glutes, and core for strength, muscle, and fat reduction.</p>\n","description_source":"A barbell squat is a fundamental strength exercise where you lower your body as if sitting in a chair while holding a weighted barbell, primarily targeting leg and core muscles, requiring proper form (chest up, back straight, knees over toes) for safety and effectiveness, engaging quads, hamstrings, glutes, and core for strength, muscle, and fat reduction.","name":"Barbell Squat","created":"2026-01-17T23:43:56.124Z","last_update":"2026-04-13T18:58:26.078Z","language":2,"uuid":"8099bafb-46dd-41af-b81a-78a7e7050a52","exercise":1805}}],"aliases":[],"comments":[{"model":"exercises.exercisecomment","pk":561,"fields":{"uuid":"a0170766-ac8d-4458-ba0e-f0b725a01d0c","translation":2931,"comment":"To perform it, unrack the bar, step back, squat down by sitting back and keeping your chest high, then drive up through your feet, ensuring your knees track with your toes."}}]}'),
('wger', '1806', 'lat-pull-down', 'https://wger.de/en/exercise/1806/view', 'CC-BY-SA-4.0', NULL, 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1806,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","uuid":"3021ccf2-36b2-48ec-90aa-9ad8ce2ab57a","category":12,"variation_group":null,"created":"2026-01-20T13:53:21.691Z","last_update":"2026-01-20T13:53:21.691Z","muscles":[12],"muscles_secondary":[2,13,3,9],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2933,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","description":"<p>The lat pull down is an exercise used to build the muscles of the back. While the exercise will primarily target the lats, you will also notice a fair amount of bicep and middle back activation.</p>\n","description_source":"The lat pull down is an exercise used to build the muscles of the back. While the exercise will primarily target the lats, you will also notice a fair amount of bicep and middle back activation.","name":"Lat Pull Down","created":"2026-01-20T13:53:21.749Z","last_update":"2026-04-13T18:58:26.758Z","language":2,"uuid":"d67138e4-e3c9-4682-bd75-9786a68f8852","exercise":1806}}],"aliases":[{"model":"exercises.alias","pk":606,"fields":{"uuid":"bde0cc68-9944-475a-905e-9cf8024724a7","translation":2933,"alias":"lat Pulldown"}},{"model":"exercises.alias","pk":607,"fields":{"uuid":"2da1d2e2-c443-4a43-84ac-c1310d569853","translation":2933,"alias":"Pulldown"}}],"comments":[]}'),
('wger', '1807', 'cable-behind-back-lateral-raise', 'https://wger.de/en/exercise/1807/view', 'CC-BY-SA-4.0', 'LEBRERO', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1807,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"LEBRERO","license_author_url":"","license_derivative_source_url":"","uuid":"57018827-f344-4627-88e5-03e4f2f49859","category":13,"variation_group":"1501b536-71f2-4137-aa42-fefaa14f1934","created":"2026-01-20T14:10:36.343Z","last_update":"2026-01-20T14:10:36.431Z","muscles":[2],"muscles_secondary":[9],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2934,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"LEBRERO","license_author_url":"","license_derivative_source_url":"","description":"<p>Lateral raises have long been a staple for building capped delts, and lifters use everything from dumbbells and bands to machines and single-arm variations to make them grow.</p>\n","description_source":"Lateral raises have long been a staple for building capped delts, and lifters use everything from dumbbells and bands to machines and single-arm variations to make them grow.","name":"Behind the Back Cable Lateral Raise","created":"2026-01-20T14:10:36.392Z","last_update":"2026-04-13T18:58:26.089Z","language":2,"uuid":"56fe3ac2-88b8-4298-934c-a388740f5444","exercise":1807}}],"aliases":[],"comments":[]}'),
('wger', '1808', 'parallel-bar-hold', 'https://wger.de/en/exercise/1808/view', 'CC-BY-SA-4.0', 'Croak6728', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1808,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Croak6728","license_author_url":"","license_derivative_source_url":"","uuid":"934856f3-6eb3-4b37-9536-0ff67a6aa036","category":8,"variation_group":null,"created":"2026-01-20T16:44:55.374Z","last_update":"2026-01-20T16:44:55.374Z","muscles":[2,4,5],"muscles_secondary":[12,14,6],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2937,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Croak6728","license_author_url":"","license_derivative_source_url":"","description":"<ol>\n<li>Stand between a set of parallel bars.</li>\n<li>Place your hands, knuckles outwards, on the bars.</li>\n<li>Push down on your hands to lift yourself off the floor.</li>\n<li>Hold yourself in this position with your arms straight for the required time.</li>\n</ol>\n","description_source":"1. Stand between a set of parallel bars.\n2. Place your hands, knuckles outwards, on the bars.\n3. Push down on your hands to lift yourself off the floor.\n4. Hold yourself in this position with your arms straight for the required time.","name":"Parallel Bar Hold","created":"2026-01-20T16:44:55.429Z","last_update":"2026-04-13T18:58:26.902Z","language":2,"uuid":"5013c6f0-fe40-46ab-9f2f-fb9aff1013cf","exercise":1808}}],"aliases":[],"comments":[{"model":"exercises.exercisecomment","pk":562,"fields":{"uuid":"6ed2a936-5fef-4a72-8814-6dcac199b8a7","translation":2937,"comment":"Keep your body in a slightly hollow position"}}]}'),
('wger', '1809', 'reverse-hyperextension', 'https://wger.de/en/exercise/1809/view', 'CC-BY-SA-4.0', 'Croak6728', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1809,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Croak6728","license_author_url":"","license_derivative_source_url":"","uuid":"682ea312-af02-450a-9880-fea7bf8e854a","category":9,"variation_group":null,"created":"2026-01-20T16:55:58.504Z","last_update":"2026-01-20T16:55:58.504Z","muscles":[11,8],"muscles_secondary":[],"equipment":[8]}},"translations":[{"model":"exercises.translation","pk":2938,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Croak6728","license_author_url":"","license_derivative_source_url":"","description":"<p>Lie face-down on a bench with your legs hanging off the edge.</p>\n<ol>\n<li>Bend your hips so your thighs are vertical, bending your knees at the same time so your shins stay horizontal.</li>\n<li>Straighten out your legs so they are not bent and your toes are pointing backwards horizontally.</li>\n<li>Return to the original position, and repeat.</li>\n</ol>\n","description_source":"Lie face-down on a bench with your legs hanging off the edge.\n\n1. Bend your hips so your thighs are vertical, bending your knees at the same time so your shins stay horizontal.\n2. Straighten out your legs so they are not bent and your toes are pointing backwards horizontally.\n3. Return to the original position, and repeat.","name":"Reverse Hyperextension","created":"2026-01-20T16:55:58.649Z","last_update":"2026-04-13T18:58:27.153Z","language":2,"uuid":"b03eb41f-bf06-4d6b-b2b2-b0538c1a0dfa","exercise":1809}}],"aliases":[],"comments":[]}'),
('wger', '1810', 'sphinx', 'https://wger.de/en/exercise/1810/view', 'CC-BY-SA-4.0', 'Joculari', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1810,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Joculari","license_author_url":"","license_derivative_source_url":"","uuid":"23d2b2ce-4ae7-441a-a122-9f6784f15aa6","category":10,"variation_group":null,"created":"2026-01-22T20:16:32.735Z","last_update":"2026-01-22T20:16:32.735Z","muscles":[6],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2939,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Joculari","license_author_url":"","license_derivative_source_url":"","description":"<p>Lie on your stomach flat, legs extended and the backs of your feet on\nthe ground. Bring your forearms under your shoulders, elbows directly\nunderneath. Then press your hands into the floor to lift your chest.\nDraw your shoulder blades together, open your collarbones, and direct\nyour gaze forward, while keeping the lower back relaxed.</p>\n","description_source":"Lie on your stomach flat, legs extended and the backs of your feet on\nthe ground. Bring your forearms under your shoulders, elbows directly\nunderneath. Then press your hands into the floor to lift your chest.\nDraw your shoulder blades together, open your collarbones, and direct\nyour gaze forward, while keeping the lower back relaxed.","name":"Sphinx","created":"2026-01-22T20:16:32.807Z","last_update":"2026-04-13T18:58:27.456Z","language":2,"uuid":"6ae9319d-6fe3-4528-b0ad-6f938d783b59","exercise":1810}},{"model":"exercises.translation","pk":2940,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Joculari","license_author_url":"","license_derivative_source_url":"","description":"<p>Flach auf den Bauch legen, Beine gestreckt und Fußrücken am Boden. Bringe die Unterarme unter die Schultern, Ellenbogen direkt darunter. Dann drücke die Hände auf den Fußboden um den Brustkorb anzuheben. Ziehe die Schulterblätter zusammen, öffne die Schlüsselbeine und richte den Blick nach vorn, während der untere Rücken entspannt bleibt.</p>\n","description_source":"Flach auf den Bauch legen, Beine gestreckt und Fußrücken am Boden. Bringe die Unterarme unter die Schultern, Ellenbogen direkt darunter. Dann drücke die Hände auf den Fußboden um den Brustkorb anzuheben. Ziehe die Schulterblätter zusammen, öffne die Schlüsselbeine und richte den Blick nach vorn, während der untere Rücken entspannt bleibt.","name":"Sphinx","created":"2026-01-22T20:16:32.838Z","last_update":"2026-04-13T18:58:27.455Z","language":1,"uuid":"656fe33e-a3bd-410a-8109-fb26fc43fd4e","exercise":1810}}],"aliases":[],"comments":[]}'),
('wger', '1822', NULL, 'https://wger.de/en/exercise/1822/view', 'CC-BY-SA-4.0', 'teus_ergaster', NULL, NULL, '{"exercise":{"model":"exercises.exercise","pk":1822,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"teus_ergaster","license_author_url":"","license_derivative_source_url":"","uuid":"164b83aa-195e-4eed-b820-b81df950d9bb","category":12,"variation_group":null,"created":"2026-01-24T16:14:26.823Z","last_update":"2026-01-24T16:14:26.823Z","muscles":[],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2956,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"teus_ergaster","license_author_url":"","license_derivative_source_url":"","description":"<p><strong>Basic exercise</strong></p>\n<ul>\n<li><strong>Focus:</strong> enhances thoracic mobility and\nspinal segmentation while opening the shoulders and chest.</li>\n<li>**Position:**kneeling on the floor with your right side facing a wall. Hips are square and stable, with the right knee down and the left foot forward. Lengthen your spine and align your head comfortably.\nBegin with your arms relaxed and open in front of your chest, palms\nfacing each other and hands apart.</li>\n<li><strong>Inhale</strong>\nto initiate the movement, allowing your left arm —the one farther from\nthe wall— to open outward and backward. Lead the twist from your thoracic\nspine, rotating your upper back progressively while keeping your pelvis\nstill.</li>\n<li><strong>Exhale</strong> as you complete the rotation, guiding your left hand\ntoward the wall as your gaze follows your hand.</li>\n<li><strong>Return by inhaling</strong> and\nslowly bringing your arm forward, reversing the spinal rotation segment\nby segment.</li>\n<li><strong>Repeat on the opposite side.</strong></li>\n</ul>\n<p><strong>Progression</strong></p>\n<ul>\n<li>**Position:**kneeling on the floor with your right side facing a wall. Left knee down and right foot forward.</li>\n<li><strong>Before the basic exercise: inhale</strong>,&nbsp;<strong>exhale</strong>while moving the right arm along the wall with a circle upwards and backwards,&nbsp;<strong>inhale</strong>while bringing back the arm.</li>\n<li><strong>Basic exercise.</strong></li>\n<li><strong>Repeat on the opposite side.</strong></li>\n</ul>\n","description_source":"**Basic exercise**\n\n* **Focus:** enhances thoracic mobility and\n  spinal segmentation while opening the shoulders and chest.\n* **Position:**kneeling on the floor with your right side facing a wall. Hips are square and stable, with the right knee down and the left foot forward. Lengthen your spine and align your head comfortably.\n  Begin with your arms relaxed and open in front of your chest, palms\n  facing each other and hands apart.\n* **Inhale**\n  to initiate the movement, allowing your left arm —the one farther from\n  the wall— to open outward and backward. Lead the twist from your thoracic\n  spine, rotating your upper back progressively while keeping your pelvis\n  still.\n* **Exhale** as you complete the rotation, guiding your left hand\n  toward the wall as your gaze follows your hand.\n* **Return by inhaling** and\n  slowly bringing your arm forward, reversing the spinal rotation segment\n  by segment.\n* **Repeat on the opposite side.**\n\n**Progression**\n\n\n* **Position:**kneeling on the floor with your right side facing a wall. Left knee down and right foot forward.\n* **Before the basic exercise: inhale**, **exhale**while moving the right arm along the wall with a circle upwards and backwards, **inhale**while bringing back the arm.\n* **Basic exercise.**\n* **Repeat on the opposite side.**","name":"Open Book","created":"2026-01-24T16:14:26.884Z","last_update":"2026-04-13T18:58:26.887Z","language":2,"uuid":"e154d163-0986-4a6a-b3eb-c7f480630b7c","exercise":1822}}],"aliases":[],"comments":[]}'),
('wger', '1823', 'clamshell', 'https://wger.de/en/exercise/1823/view', 'CC-BY-SA-4.0', 'teus_ergaster', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1823,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"teus_ergaster","license_author_url":"","license_derivative_source_url":"","uuid":"ca3ca5d0-5231-4420-ad06-fa3d32693a1b","category":10,"variation_group":"f6a9a4e8-aa3c-4d55-b114-1b46cc72da1f","created":"2026-01-24T16:23:45.877Z","last_update":"2026-01-24T16:23:46.006Z","muscles":[8,6],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2957,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"teus_ergaster","license_author_url":"","license_derivative_source_url":"","description":"<p><strong>Position</strong>\nSide plank with the elbow and the forearm on the ground and the legs slightly bent.</p>\n<p><strong>Execution</strong>\nLift your upper knee while keeping your feet close together, like a “shell opening,” then slowly return to the starting position. Keep your core stable and your hips aligned.</p>\n","description_source":"**Position**  \nSide plank with the elbow and the forearm on the ground and the legs slightly bent.   \n  \n**Execution**  \nLift your upper knee while keeping your feet close together, like a “shell opening,” then slowly return to the starting position. Keep your core stable and your hips aligned.","name":"Clamshell","created":"2026-01-24T16:23:45.953Z","last_update":"2026-04-13T18:58:26.210Z","language":2,"uuid":"2b86aa60-c732-420a-9b85-74bd1e7475ad","exercise":1823}},{"model":"exercises.translation","pk":2958,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"teus_ergaster","license_author_url":"","license_derivative_source_url":"","description":"<p><strong>Posizione</strong></p>\n<p>Plank laterale, avambraccio a terra, corpo in linea retta.</p>\n<p><strong>Esecuzione</strong>\nSolleva il ginocchio superiore mantenendo i piedi vicini,\ncome un “guscio che si apre”, poi ritorna lentamente. Mantieni il core\nstabile e i fianchi allineati.</p>\n","description_source":"**Posizione**\n\nPlank laterale, avambraccio a terra, corpo in linea retta.\n\n**Esecuzione**  \nSolleva il ginocchio superiore mantenendo i piedi vicini,\ncome un “guscio che si apre”, poi ritorna lentamente. Mantieni il core\nstabile e i fianchi allineati.","name":"Clamshell","created":"2026-01-24T16:23:45.985Z","last_update":"2026-04-13T18:58:26.209Z","language":13,"uuid":"57c0a5f7-d658-4f98-bb44-43d74e447800","exercise":1823}}],"aliases":[],"comments":[]}'),
('wger', '1824', 'dumbbell-tate-press', 'https://wger.de/en/exercise/1824/view', 'CC-BY-SA-4.0', 'beagle', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1824,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"beagle","license_author_url":"","license_derivative_source_url":"","uuid":"2affa71f-7308-4448-af57-dc44b424090e","category":8,"variation_group":null,"created":"2026-01-25T17:23:44.427Z","last_update":"2026-01-25T17:23:44.427Z","muscles":[5],"muscles_secondary":[2,4],"equipment":[8,3]}},"translations":[{"model":"exercises.translation","pk":2959,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"beagle","license_author_url":"","license_derivative_source_url":"","description":"<ol>\n<li><strong>Set Up</strong>: Lie flat with a dumbbell in each hand. Extend your arms straight up over your chest as if you were at the top of a dumbbell bench press</li>\n<li><strong>Starting Position</strong>: Position the dumbbells so they are touching or very close together with a pronated grip (palms facing your feet and thumbs facing each other)</li>\n<li><strong>Lowering</strong>: Without moving your upper arms or shoulders, bend your elbows and flare them outward to the sides. Lower the inner ends of the dumbbells toward the center of your chest</li>\n<li><strong>Touch and Pause</strong>: Gently touch the dumbbells to your chest. Do not rest the weight on your body; maintain constant tension in your triceps</li>\n<li><strong>Press</strong>: Forcefully extend your elbows to return the dumbbells to the starting position. Focus on \"pushing your pinkies toward the sky\" to maximize triceps engagement</li>\n</ol>\n<p>https://www.youtube.com/watch?v=IgSjoXbpy1M&amp;t=2</p>\n","description_source":"1. **Set Up**: Lie flat with a dumbbell in each hand. Extend your arms straight up over your chest as if you were at the top of a dumbbell bench press\n2. **Starting Position**: Position the dumbbells so they are touching or very close together with a pronated grip (palms facing your feet and thumbs facing each other)\n3. **Lowering**: Without moving your upper arms or shoulders, bend your elbows and flare them outward to the sides. Lower the inner ends of the dumbbells toward the center of your chest\n4. **Touch and Pause**: Gently touch the dumbbells to your chest. Do not rest the weight on your body; maintain constant tension in your triceps\n5. **Press**: Forcefully extend your elbows to return the dumbbells to the starting position. Focus on \"pushing your pinkies toward the sky\" to maximize triceps engagement\n\nhttps://www.youtube.com/watch?v=IgSjoXbpy1M&t=2","name":"Dumbell Tate Press","created":"2026-01-25T17:23:44.543Z","last_update":"2026-04-13T18:58:26.452Z","language":2,"uuid":"a4467032-8c94-411e-a73b-cb844b532171","exercise":1824}}],"aliases":[],"comments":[{"model":"exercises.exercisecomment","pk":603,"fields":{"uuid":"88a0d57a-ba2d-40e3-a6b6-307ca2668c32","translation":2959,"comment":"Upper Arm Stability: Your upper arms should remain mostly vertical. Avoid letting your shoulders round forward or move as you bend your elbows"}},{"model":"exercises.exercisecomment","pk":604,"fields":{"uuid":"f2de7636-36fb-4147-9e94-0c25c1c1cab4","translation":2959,"comment":"Keep Elbows Out: Unlike a standard press or skull crusher, the elbows must point strictly outward to the sides throughout the movement"}},{"model":"exercises.exercisecomment","pk":605,"fields":{"uuid":"23cafbe2-fa05-4800-afde-835efdd20b96","translation":2959,"comment":"Wrist Alignment: Keep your wrists straight and firm to prevent strain"}}]}'),
('wger', '1825', 'dumbbell-chest-supported-rear-delt-raise', 'https://wger.de/en/exercise/1825/view', 'CC-BY-SA-4.0', 'beagle', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1825,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"beagle","license_author_url":"","license_derivative_source_url":"","uuid":"25cbc266-aa84-44f5-989b-53c9cc8fdc77","category":13,"variation_group":null,"created":"2026-01-25T17:59:23.176Z","last_update":"2026-01-25T17:59:23.176Z","muscles":[2],"muscles_secondary":[9],"equipment":[8,3]}},"translations":[{"model":"exercises.translation","pk":2960,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"beagle","license_author_url":"","license_derivative_source_url":"","description":"<p>\"The Y\"Position: Set an incline bench to 30-45 degrees. Lie face-down with your chest supported, keeping your head neutral or looking slightly down to avoid neck strain.Grip: Hold light dumbbells with a neutral or thumbs-up grip (thumb pointing to the ceiling).Movement: With straight or slightly bent elbows, raise the dumbbells up and out in a \"Y\" shape. Focus on moving the shoulders and shoulder blades rather than just lifting the arms.Top Position: Squeeze the shoulder blades together and reach high, ensuring the arms are angled to form a \"Y\".Control: Lower the dumbbells slowly to the starting position.</p>\n","description_source":"\"The Y\"Position: Set an incline bench to 30-45 degrees. Lie face-down with your chest supported, keeping your head neutral or looking slightly down to avoid neck strain.Grip: Hold light dumbbells with a neutral or thumbs-up grip (thumb pointing to the ceiling).Movement: With straight or slightly bent elbows, raise the dumbbells up and out in a \"Y\" shape. Focus on moving the shoulders and shoulder blades rather than just lifting the arms.Top Position: Squeeze the shoulder blades together and reach high, ensuring the arms are angled to form a \"Y\".Control: Lower the dumbbells slowly to the starting position.","name":"Chest-Supported Rear Delt Raise","created":"2026-01-25T17:59:23.255Z","last_update":"2026-04-13T18:58:26.203Z","language":2,"uuid":"6c2cea8d-cdc6-436c-81b0-75dc834cdd84","exercise":1825}}],"aliases":[],"comments":[]}'),
('wger', '1826', 'band-pull-apart-external-rotation', 'https://wger.de/en/exercise/1826/view', 'CC-BY-SA-4.0', 'beagle', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1826,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"beagle","license_author_url":"","license_derivative_source_url":"","uuid":"83650b79-add8-4846-b114-b4f28d96495a","category":13,"variation_group":null,"created":"2026-01-25T18:02:51.800Z","last_update":"2026-01-25T18:02:51.800Z","muscles":[2],"muscles_secondary":[],"equipment":[11]}},"translations":[{"model":"exercises.translation","pk":2961,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"beagle","license_author_url":"","license_derivative_source_url":"","description":"<p>Stand tall with your feet shoulder-width apart, chest out, and shoulders back.</p>\n<p>Hold the resistance band with both hands, palms facing up or facing each other, depending on the band type.</p>\n<p>Bend your elbows at a 90-degree angle and glue your upper arms to your sides.</p>\n<p>The band should have some tension in the starting position, with your hands closer together in front of your stomach.</p>\n<p>Rotate Outward: While keeping your elbows tucked into your sides, slowly move your hands away from each other, stretching the band.</p>\n<p>Squeeze: Squeeze your shoulder blades together and down as you rotate your hands outward.</p>\n<p>Range of Motion: Rotate your hands as far outward as you comfortably can without allowing your elbows to leave your sides.</p>\n<p>Hold: Hold the end position for 1–2 seconds to maximize muscle engagement.</p>\n<p>Return: Slowly and with control, bring your hands back to the starting position.</p>\n","description_source":"Stand tall with your feet shoulder-width apart, chest out, and shoulders back.\n\nHold the resistance band with both hands, palms facing up or facing each other, depending on the band type.  \n\nBend your elbows at a 90-degree angle and glue your upper arms to your sides.\n\nThe band should have some tension in the starting position, with your hands closer together in front of your stomach.\n\n  \nRotate Outward: While keeping your elbows tucked into your sides, slowly move your hands away from each other, stretching the band.  \n\nSqueeze: Squeeze your shoulder blades together and down as you rotate your hands outward.\n\nRange of Motion: Rotate your hands as far outward as you comfortably can without allowing your elbows to leave your sides.\n\nHold: Hold the end position for 1–2 seconds to maximize muscle engagement.\n\nReturn: Slowly and with control, bring your hands back to the starting position.","name":"Band pull-apart with external rotation","created":"2026-01-25T18:02:51.853Z","last_update":"2026-04-13T18:58:26.061Z","language":2,"uuid":"28062f15-1bd3-46c4-8c79-9dbbecc253d1","exercise":1826}}],"aliases":[],"comments":[{"model":"exercises.exercisecomment","pk":606,"fields":{"uuid":"3176d4ff-928c-4027-ac27-24aeb46008f0","translation":2961,"comment":"Consider placing a small, rolled-up towel between your elbow and your ribs on each side to ensure your elbows stay locked at your sides."}}]}'),
('wger', '1827', 'double-leg-abdominal-press', 'https://wger.de/en/exercise/1827/view', 'CC-BY-SA-4.0', 'beagle', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1827,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"beagle","license_author_url":"","license_derivative_source_url":"","uuid":"f0823bb5-3f18-48d4-98de-cbe38f9fd8ff","category":10,"variation_group":null,"created":"2026-01-25T18:05:42.977Z","last_update":"2026-01-25T18:05:42.977Z","muscles":[6],"muscles_secondary":[],"equipment":[4,7]}},"translations":[{"model":"exercises.translation","pk":2962,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"beagle","license_author_url":"","license_derivative_source_url":"","description":"<p>Lie on your back with knees and hips bent at 90 degrees (tabletop).</p>\n<p>Place your hands on your thighs just above your knees. Push your hands against your knees as hard as possible while using your abs to pull your knees toward your hands.</p>\n<p>Hold for 10 seconds of maximum effort. Your abs should be shaking.</p>\n","description_source":"Lie on your back with knees and hips bent at 90 degrees (tabletop).  \n\nPlace your hands on your thighs just above your knees. Push your hands against your knees as hard as possible while using your abs to pull your knees toward your hands.\n\nHold for 10 seconds of maximum effort. Your abs should be shaking.","name":"Double-Leg Abdominal Press","created":"2026-01-25T18:05:43.130Z","last_update":"2026-04-13T18:58:26.402Z","language":2,"uuid":"409a0320-3426-4f3a-a466-b51cee75ca0e","exercise":1827}}],"aliases":[],"comments":[]}'),
('wger', '1828', 'abdominal-draw-in', 'https://wger.de/en/exercise/1828/view', 'CC-BY-SA-4.0', 'beagle', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1828,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"beagle","license_author_url":"","license_derivative_source_url":"","uuid":"793b0e5f-8dea-48a6-84c8-9123b59c2721","category":10,"variation_group":null,"created":"2026-01-25T18:08:15.530Z","last_update":"2026-01-25T18:08:15.530Z","muscles":[6],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2963,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"beagle","license_author_url":"","license_derivative_source_url":"","description":"<p>Lie\non your back with knees bent. Gently pull your belly button toward your\nspine without moving your hips or holding your breath.</p>\n","description_source":"Lie\non your back with knees bent. Gently pull your belly button toward your\nspine without moving your hips or holding your breath.","name":"Abdominal Draw-In","created":"2026-01-25T18:08:15.571Z","last_update":"2026-04-13T18:58:25.984Z","language":2,"uuid":"b2db3e5a-6381-4fd5-a79d-ccbd2e86aa35","exercise":1828}}],"aliases":[],"comments":[]}'),
('wger', '1829', 'barbell-landmine-squat-to-press', 'https://wger.de/en/exercise/1829/view', 'CC-BY-SA-4.0', 'beagle', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1829,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"beagle","license_author_url":"","license_derivative_source_url":"","uuid":"67bca611-d9f1-4855-9e02-ecc8d7d688e9","category":9,"variation_group":null,"created":"2026-01-25T18:13:54.125Z","last_update":"2026-01-25T18:13:54.125Z","muscles":[2,8,10],"muscles_secondary":[11,6],"equipment":[1]}},"translations":[{"model":"exercises.translation","pk":2964,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"beagle","license_author_url":"","license_derivative_source_url":"","description":"<p>Bar Position: Anchor one end of a barbell in a landmine attachment or a secure corner.\nStance: Stand facing the barbell with feet slightly wider than shoulder-width. Turn your toes out 10–35 degrees to allow for better pelvic movement and depth.\nGrip: Cup the free end of the barbell with both hands (fingers interlaced or overlapping) and hold it at mid-chest level, just below the collarbone.</p>\n<p>Descent: Brace your core and sit back into a squat, keeping your chest up and weight on your heels.\nDepth: Lower until your thighs are at least parallel to the floor. A good reference is when your elbows touch the tops of your thighs or just inside your knees.\nPosture: Ensure your back remains flat and your spine neutral throughout the movement.</p>\n<p>Drive: Powerfully drive through your heels to stand up. Use the momentum from your legs to \"thrust\" the weight upward.\nExtension: In one fluid motion, press the bar overhead until your arms are fully extended. At the top, your biceps should be near your ears.\nThe \"Lean\": As you reach the top of the press, lean slightly forward into the bar to encourage proper upward rotation of the shoulder blades and avoid lower back arching.</p>\n<p>Slowly lower the barbell back to chest height in a controlled manner before immediately beginning the next repetition.</p>\n","description_source":"Bar Position: Anchor one end of a barbell in a landmine attachment or a secure corner.  \nStance: Stand facing the barbell with feet slightly wider than shoulder-width. Turn your toes out 10–35 degrees to allow for better pelvic movement and depth.  \nGrip: Cup the free end of the barbell with both hands (fingers interlaced or overlapping) and hold it at mid-chest level, just below the collarbone.   \n  \nDescent: Brace your core and sit back into a squat, keeping your chest up and weight on your heels.  \nDepth: Lower until your thighs are at least parallel to the floor. A good reference is when your elbows touch the tops of your thighs or just inside your knees.  \nPosture: Ensure your back remains flat and your spine neutral throughout the movement.   \n  \nDrive: Powerfully drive through your heels to stand up. Use the momentum from your legs to \"thrust\" the weight upward.  \nExtension: In one fluid motion, press the bar overhead until your arms are fully extended. At the top, your biceps should be near your ears.  \nThe \"Lean\": As you reach the top of the press, lean slightly forward into the bar to encourage proper upward rotation of the shoulder blades and avoid lower back arching.   \n  \nSlowly lower the barbell back to chest height in a controlled manner before immediately beginning the next repetition.","name":"Landmine Squat to Press","created":"2026-01-25T18:13:54.193Z","last_update":"2026-04-13T18:58:26.752Z","language":2,"uuid":"eec63336-b0c6-4b39-ae9d-3e8e0966f126","exercise":1829}}],"aliases":[],"comments":[]}'),
('wger', '1830', 'barbell-step-back-lunge', 'https://wger.de/en/exercise/1830/view', 'CC-BY-SA-4.0', NULL, 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1830,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","uuid":"928eeae3-d849-4605-a470-048ca259a8c5","category":9,"variation_group":null,"created":"2026-01-31T23:28:06.081Z","last_update":"2026-01-31T23:28:06.081Z","muscles":[10],"muscles_secondary":[],"equipment":[1]}},"translations":[{"model":"exercises.translation","pk":2965,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","description":"<p>Step 1: Stand with your feet hip-width apart, holding a barbell on your upper back.\nStep 2: Keep your back straight, chest up, and core engaged.\nStep 3: Take a step back with one leg and lower your body by bending both knees. Ensure that your back knee nearly touches the ground.\nStep 4: Push off your back foot to return to the starting position.\nStep 5: Repeat the movement with the other leg.\nContinue alternating between legs for the desired repetitions.</p>\n","description_source":"Step 1: Stand with your feet hip-width apart, holding a barbell on your upper back.\nStep 2: Keep your back straight, chest up, and core engaged.\nStep 3: Take a step back with one leg and lower your body by bending both knees. Ensure that your back knee nearly touches the ground.\nStep 4: Push off your back foot to return to the starting position.\nStep 5: Repeat the movement with the other leg.\nContinue alternating between legs for the desired repetitions.","name":"Barbell Step Back Lunge","created":"2026-01-31T23:28:06.133Z","last_update":"2026-04-13T18:58:26.079Z","language":2,"uuid":"f2ffb8fd-2855-4762-9005-71ad7de9abae","exercise":1830}}],"aliases":[{"model":"exercises.alias","pk":608,"fields":{"uuid":"7ebdcd74-888f-4eb5-9655-3da4e6846c48","translation":2965,"alias":"Barbell Reverse Lunge"}}],"comments":[]}'),
('wger', '1831', 'hammerstrength-decline-chest-press', 'https://wger.de/en/exercise/1831/view', 'CC-BY-SA-4.0', NULL, 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1831,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","uuid":"920692b2-0842-428a-b925-ba0daf6b41db","category":11,"variation_group":null,"created":"2026-02-01T08:44:56.428Z","last_update":"2026-02-01T08:44:56.428Z","muscles":[4],"muscles_secondary":[2,5],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2966,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","description":"<ol>\n<li>Sit upright in a hammerstrength decline chest press machine while squeezing your shoulder blades together and placing your heels firmly on the ground underneath your knees.</li>\n<li>The back pad should be contact with your head, shoulders, and butt at all times.</li>\n<li>Grab ahold of the handles with an overhand grip just outside shoulder-width apart just below your chest.</li>\n<li>Keeping your core braced by breathing into your stomach and flexing the abdominal muscles, push through your palms to extend your elbows while keeping them at a 45 degree angle from your torso.</li>\n<li>Once your arms are fully extended, return to the starting position.</li>\n</ol>\n","description_source":"1. Sit upright in a hammerstrength decline chest press machine while squeezing your shoulder blades together and placing your heels firmly on the ground underneath your knees.\n2. The back pad should be contact with your head, shoulders, and butt at all times.\n3. Grab ahold of the handles with an overhand grip just outside shoulder-width apart just below your chest.\n4. Keeping your core braced by breathing into your stomach and flexing the abdominal muscles, push through your palms to extend your elbows while keeping them at a 45 degree angle from your torso.\n5. Once your arms are fully extended, return to the starting position.","name":"Hammerstrength Decline Chest Press","created":"2026-02-01T08:44:56.691Z","last_update":"2026-04-13T18:58:26.606Z","language":2,"uuid":"27b93d2f-b899-4c4a-87b8-402bd07e9a10","exercise":1831}}],"aliases":[{"model":"exercises.alias","pk":609,"fields":{"uuid":"44a95129-501d-4606-9491-10961ea9b368","translation":2966,"alias":"Hammerstrength Decline Press"}}],"comments":[]}'),
('wger', '1832', NULL, 'https://wger.de/en/exercise/1832/view', 'CC-BY-SA-4.0', NULL, NULL, NULL, '{"exercise":{"model":"exercises.exercise","pk":1832,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","uuid":"6c9c9d14-e6bf-43ed-9859-a689e2131fe0","category":11,"variation_group":null,"created":"2026-02-04T03:35:12.602Z","last_update":"2026-02-04T03:35:12.602Z","muscles":[],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2967,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","description":"<p>Hold yourself in a support position on gymnastic rings with arms straight at sides. Focus on keeping rings turned out slightly and maintaining hollow body position. This is an isometric hold for chest, shoulders, and triceps.</p>\n","description_source":"Hold yourself in a support position on gymnastic rings with arms straight at sides. Focus on keeping rings turned out slightly and maintaining hollow body position. This is an isometric hold for chest, shoulders, and triceps.","name":"Ring Support Hold","created":"2026-02-04T03:39:12.133Z","last_update":"2026-04-13T18:58:27.165Z","language":2,"uuid":"356387f6-bc15-4b84-bc6b-107df16fd3e8","exercise":1832}}],"aliases":[],"comments":[]}'),
('wger', '1833', NULL, 'https://wger.de/en/exercise/1833/view', 'CC-BY-SA-4.0', NULL, NULL, NULL, '{"exercise":{"model":"exercises.exercise","pk":1833,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","uuid":"d6b2ac1d-4363-45e9-8fdb-9fba0a47b27d","category":13,"variation_group":null,"created":"2026-02-04T03:35:45.283Z","last_update":"2026-02-04T03:35:45.283Z","muscles":[],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":2968,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","description":"<p>Lie on back with heels on floor gliders or towels. Lift hips into a bridge, then slide heels toward glutes while keeping hips elevated. Slowly return to the starting position while maintaining the hip bridge.</p>\n","description_source":"Lie on back with heels on floor gliders or towels. Lift hips into a bridge, then slide heels toward glutes while keeping hips elevated. Slowly return to the starting position while maintaining the hip bridge.","name":"Floor Glider Hamstring Curls","created":"2026-02-04T03:39:13.178Z","last_update":"2026-04-13T18:58:26.545Z","language":2,"uuid":"3f42954d-d16c-4aed-b4c5-cd1c0e1268a9","exercise":1833}}],"aliases":[],"comments":[]}'),
('wger', '1834', 'trap-3-raise', 'https://wger.de/en/exercise/1834/view', 'CC-BY-SA-4.0', 'Croak6728', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1834,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Croak6728","license_author_url":"","license_derivative_source_url":"","uuid":"62f90b5c-7451-4fd0-91ae-4dd93c51aa41","category":12,"variation_group":null,"created":"2026-02-12T11:32:22.157Z","last_update":"2026-02-12T11:32:22.157Z","muscles":[9],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2969,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Croak6728","license_author_url":"","license_derivative_source_url":"","description":"<ol>\n<li>Hinge forwards and bend your knees slightly. Depress and retract the shoulder you will use. Rest the other hand on your knee.</li>\n<li>Raise your hand about 15 degrees overhead, maintaining the position of your shoulder.</li>\n</ol>\n","description_source":"1. Hinge forwards and bend your knees slightly. Depress and retract the shoulder you will use. Rest the other hand on your knee.\n2. Raise your hand about 15 degrees overhead, maintaining the position of your shoulder.","name":"Trap-3 Raise","created":"2026-02-12T11:32:22.225Z","last_update":"2026-04-13T18:58:27.677Z","language":2,"uuid":"28c2327b-d504-4ffa-be15-c85c7ef6882b","exercise":1834}}],"aliases":[],"comments":[]}'),
('wger', '1835', 'barbell-external-rotation-stretch', 'https://wger.de/en/exercise/1835/view', 'CC-BY-SA-4.0', 'Croak6728', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1835,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Croak6728","license_author_url":"","license_derivative_source_url":"","uuid":"a4413bcc-dcd1-4332-a09a-fee94a265e22","category":13,"variation_group":null,"created":"2026-02-12T11:39:32.371Z","last_update":"2026-02-12T11:39:32.372Z","muscles":[2,9],"muscles_secondary":[],"equipment":[1]}},"translations":[{"model":"exercises.translation","pk":2970,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Croak6728","license_author_url":"","license_derivative_source_url":"","description":"<ol>\n<li>Sit with your feet pressed against each other, and one knee raised all the way out to the side of your body.</li>\n<li>Place your elbow on your raised knee, bend it at 90 degrees, and point your hand directly forward, holding your barbell/dumbbell.</li>\n<li>Keep your shoulder depressed and retracted, raise your hand until your forearm is vertical, as if you were about to wave at someone like a robot.</li>\n<li>Lower your hand to the original position and repeat.</li>\n</ol>\n","description_source":"1. Sit with your feet pressed against each other, and one knee raised all the way out to the side of your body.\n2. Place your elbow on your raised knee, bend it at 90 degrees, and point your hand directly forward, holding your barbell/dumbbell.\n3. Keep your shoulder depressed and retracted, raise your hand until your forearm is vertical, as if you were about to wave at someone like a robot.\n4. Lower your hand to the original position and repeat.","name":"External Rotation Stretch","created":"2026-02-12T11:39:32.431Z","last_update":"2026-04-13T18:58:26.515Z","language":2,"uuid":"52608131-ee8d-4f62-9e27-0576f9f8a215","exercise":1835}}],"aliases":[],"comments":[{"model":"exercises.exercisecomment","pk":607,"fields":{"uuid":"cb02d007-3359-473f-8735-77e8b01fba38","translation":2970,"comment":"Shoulders Depressed and Retracted."}},{"model":"exercises.exercisecomment","pk":608,"fields":{"uuid":"c51ecb12-afe3-4688-a2c5-d4ac26afc28f","translation":2970,"comment":"If you can’t feel it, don’t up the weight because it must be ‘too easy’."}}]}'),
('wger', '1838', 'band-banded-shoulder-drills', 'https://wger.de/en/exercise/1838/view', 'CC-BY-SA-4.0', 'Croak6728', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1838,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Croak6728","license_author_url":"","license_derivative_source_url":"","uuid":"4c317795-c301-4081-9f96-6036682f80c1","category":13,"variation_group":null,"created":"2026-02-12T11:52:43.429Z","last_update":"2026-02-12T11:52:43.430Z","muscles":[2,4,9],"muscles_secondary":[],"equipment":[11]}},"translations":[{"model":"exercises.translation","pk":2973,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Croak6728","license_author_url":"","license_derivative_source_url":"","description":"<ol>\n<li>Attach a resistance band to something solid behind you. Stand away from it, holding it in your hand so it is taut.</li>\n<li>See the attached youtube video: https://www.youtube.com/watch?v=zdwEWchSjrI .</li>\n</ol>\n","description_source":"1. Attach a resistance band to something solid behind you. Stand away from it, holding it in your hand so it is taut.\n2. See the attached youtube video: https://www.youtube.com/watch?v=zdwEWchSjrI .","name":"Banded Shoulder Drills","created":"2026-02-12T11:52:43.454Z","last_update":"2026-04-13T18:58:26.065Z","language":2,"uuid":"36cb753a-f58c-41e3-8f89-2d563d7d9701","exercise":1838}}],"aliases":[],"comments":[]}'),
('wger', '1839', NULL, 'https://wger.de/en/exercise/1839/view', 'CC-BY-SA-4.0', 'Croak6728', NULL, NULL, '{"exercise":{"model":"exercises.exercise","pk":1839,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Croak6728","license_author_url":"","license_derivative_source_url":"","uuid":"33a55e1a-ff83-4c34-b056-887a121b0978","category":9,"variation_group":null,"created":"2026-02-12T11:56:19.129Z","last_update":"2026-02-12T11:56:19.129Z","muscles":[],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2974,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Croak6728","license_author_url":"","license_derivative_source_url":"","description":"<p>See this instructive video: https://www.youtube.com/watch?v=qHwyBHS6MQs .</p>\n","description_source":"See this instructive video: https://www.youtube.com/watch?v=qHwyBHS6MQs .","name":"Solo Hip Flexor Stretch","created":"2026-02-12T11:56:19.175Z","last_update":"2026-04-13T18:58:27.447Z","language":2,"uuid":"ce79a43e-c03f-469f-9fec-05740ad2b4e5","exercise":1839}}],"aliases":[],"comments":[]}'),
('wger', '1840', NULL, 'https://wger.de/en/exercise/1840/view', 'CC-BY-SA-4.0', 'Croak6728', NULL, NULL, '{"exercise":{"model":"exercises.exercise","pk":1840,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Croak6728","license_author_url":"","license_derivative_source_url":"","uuid":"abdd2b41-0c30-4ec1-8d14-f6dc5deb3561","category":9,"variation_group":null,"created":"2026-02-12T11:59:00.978Z","last_update":"2026-02-12T11:59:00.978Z","muscles":[],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2975,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Croak6728","license_author_url":"","license_derivative_source_url":"","description":"<p>See this instructional video from Stretch Therapy: https://www.youtube.com/watch?v=CrF2iMnn09w .</p>\n","description_source":"See this instructional video from Stretch Therapy: https://www.youtube.com/watch?v=CrF2iMnn09w .","name":"Bent-Leg Hamstring Stretch","created":"2026-02-12T11:59:01.041Z","last_update":"2026-04-13T18:58:26.106Z","language":2,"uuid":"555ba5a2-2323-42d7-8b9d-4cfdfaa5f5b8","exercise":1840}}],"aliases":[],"comments":[]}'),
('wger', '1841', 'seated-shoulder-extension-stretch', 'https://wger.de/en/exercise/1841/view', 'CC-BY-SA-4.0', 'Croak6728', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1841,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Croak6728","license_author_url":"","license_derivative_source_url":"","uuid":"a00b852c-0d2b-4b4a-bbc2-ef538f211b6c","category":13,"variation_group":null,"created":"2026-02-12T12:02:26.400Z","last_update":"2026-02-12T12:02:26.400Z","muscles":[12,4],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2976,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Croak6728","license_author_url":"","license_derivative_source_url":"","description":"<ol>\n<li>Sit with your hands behind you, shoulder width apart.</li>\n<li>Lock your elbows.</li>\n<li>Scoot your feet and hips out forwards, lowering your shoulders down towards ground.</li>\n<li>Go as far as possible to obtain a good stretch.</li>\n</ol>\n<p>See the video: https://www.youtube.com/watch?v=ihUAbG0e8zw</p>\n","description_source":"1. Sit with your hands behind you, shoulder width apart.\n2. Lock your elbows.\n3. Scoot your feet and hips out forwards, lowering your shoulders down towards ground.\n4. Go as far as possible to obtain a good stretch.\n\nSee the video: https://www.youtube.com/watch?v=ihUAbG0e8zw","name":"Seated Shoulder Extension Stretch","created":"2026-02-12T12:02:26.474Z","last_update":"2026-04-13T18:58:27.286Z","language":2,"uuid":"a606c9c1-502a-434a-8e71-eafe5d484b0f","exercise":1841}}],"aliases":[],"comments":[{"model":"exercises.exercisecomment","pk":609,"fields":{"uuid":"7b3cfb59-c020-4fd7-a851-0eb0fd80f34a","translation":2976,"comment":"Be mindful of the elbows"}},{"model":"exercises.exercisecomment","pk":610,"fields":{"uuid":"a93be799-011b-42eb-963b-29fd48fbb0fe","translation":2976,"comment":"Slow and controlled"}},{"model":"exercises.exercisecomment","pk":611,"fields":{"uuid":"ba4d4a30-11cb-42f1-8e53-5461be421e81","translation":2976,"comment":"Should not be painful"}}]}'),
('wger', '1842', 'band-banded-clamshell', 'https://wger.de/en/exercise/1842/view', 'CC-BY-SA-4.0', 'Croak6728', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1842,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Croak6728","license_author_url":"","license_derivative_source_url":"","uuid":"8cc84753-e638-4c43-91c6-51c097813ca4","category":9,"variation_group":"f6a9a4e8-aa3c-4d55-b114-1b46cc72da1f","created":"2026-02-12T12:18:24.938Z","last_update":"2026-02-12T12:18:24.938Z","muscles":[8,6],"muscles_secondary":[10],"equipment":[11]}},"translations":[{"model":"exercises.translation","pk":2977,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Croak6728","license_author_url":"","license_derivative_source_url":"","description":"<p><strong>Position</strong>\nSide plank with the elbow and the forearm on the ground and the legs slightly bent. Stretch a doubled-up resistance band between your thighs, just above the knee.</p>\n<p><strong>Execution</strong>\nLift\nyour upper knee while keeping your feet close together, like a “shell\nopening,” then slowly return to the starting position. Keep your core\nstable and your hips aligned.</p>\n","description_source":"**Position**  \nSide plank with the elbow and the forearm on the ground and the legs slightly bent. Stretch a doubled-up resistance band between your thighs, just above the knee.  \n  \n**Execution**  \nLift\nyour upper knee while keeping your feet close together, like a “shell\nopening,” then slowly return to the starting position. Keep your core\nstable and your hips aligned.","name":"Banded Clamshell","created":"2026-02-12T12:18:25.154Z","last_update":"2026-04-13T18:58:26.064Z","language":2,"uuid":"a3985f4b-436a-44f6-8a8a-f5103d92069d","exercise":1842}}],"aliases":[],"comments":[]}'),
('wger', '1843', NULL, 'https://wger.de/en/exercise/1843/view', 'CC-BY-SA-4.0', 'Croak6728', NULL, NULL, '{"exercise":{"model":"exercises.exercise","pk":1843,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Croak6728","license_author_url":"","license_derivative_source_url":"","uuid":"df3a6900-55c1-435b-bcde-7510dc229b20","category":9,"variation_group":null,"created":"2026-02-12T12:48:51.268Z","last_update":"2026-02-12T12:48:51.268Z","muscles":[],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2978,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Croak6728","license_author_url":"","license_derivative_source_url":"","description":"<ol>\n<li>Sit in a prayer position with the soles of your feet gently pressed together.</li>\n<li>Use your hands to slowly pull your feet inwards towards your groin. Hold for as long as required.</li>\n</ol>\n","description_source":"1. Sit in a prayer position with the soles of your feet gently pressed together.\n2. Use your hands to slowly pull your feet inwards towards your groin. Hold for as long as required.","name":"Butterfly Stretch","created":"2026-02-12T12:48:51.389Z","last_update":"2026-04-13T18:58:26.166Z","language":2,"uuid":"933ba231-3667-4294-8eb5-5e852d37d64b","exercise":1843}}],"aliases":[],"comments":[{"model":"exercises.exercisecomment","pk":612,"fields":{"uuid":"31f1a63d-1aac-4e81-aafe-1a4dda1ada4a","translation":2978,"comment":"Keep your back straight, don''t enter a hollow position."}},{"model":"exercises.exercisecomment","pk":613,"fields":{"uuid":"52e95743-46ca-4759-9a11-a7ce365db894","translation":2978,"comment":"Push your thighs and knees downwards with your elbows if you need a better stretch."}}]}'),
('wger', '1844', 'frog-stretch', 'https://wger.de/en/exercise/1844/view', 'CC-BY-SA-4.0', 'Croak6728', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1844,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Croak6728","license_author_url":"","license_derivative_source_url":"","uuid":"a37001e9-b4b3-45db-8ee3-046f40350efa","category":9,"variation_group":null,"created":"2026-02-12T12:56:27.329Z","last_update":"2026-02-12T12:56:27.329Z","muscles":[8],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2979,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Croak6728","license_author_url":"","license_derivative_source_url":"","description":"<ol>\n<li>Get on your hands and knees.</li>\n<li>Widen your knees outwards, and drop to your elbows.</li>\n<li>Without moving your elbows or knees, start to rock forwards and backwards, trying to get your bum closer to your feet.</li>\n</ol>\n","description_source":"1. Get on your hands and knees.\n2. Widen your knees outwards, and drop to your elbows.\n3. Without moving your elbows or knees, start to rock forwards and backwards, trying to get your bum closer to your feet.","name":"Frog Stretch","created":"2026-02-12T12:56:27.382Z","last_update":"2026-04-13T18:58:26.569Z","language":2,"uuid":"95961794-b5aa-4d06-8dfa-56918300986f","exercise":1844}}],"aliases":[],"comments":[{"model":"exercises.exercisecomment","pk":614,"fields":{"uuid":"aaf1f4d5-9314-4ba6-95ee-fe1072432d9b","translation":2979,"comment":"Maintain a gentle arch in your lower back, don''t let it round/hollow."}},{"model":"exercises.exercisecomment","pk":615,"fields":{"uuid":"d2f08755-9b74-4b4d-a129-afdc192f4341","translation":2979,"comment":"For extra challenge, hold your shins parallel and point your feet outwards at a 90 degree angle from your body,"}}]}'),
('wger', '1845', 'seated-pancake-good-morning', 'https://wger.de/en/exercise/1845/view', 'CC-BY-SA-4.0', 'Croak6728', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1845,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Croak6728","license_author_url":"","license_derivative_source_url":"","uuid":"96583e33-e643-486d-95e9-67d0d5935b05","category":9,"variation_group":"32d2d0f2-51a3-4c26-89b0-0dca0132aa25","created":"2026-02-12T13:00:14.647Z","last_update":"2026-02-12T13:00:14.990Z","muscles":[8],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2980,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Croak6728","license_author_url":"","license_derivative_source_url":"","description":"<ol>\n<li>Sit with your legs completely straight (knees locked), spread wide in a straddle position.</li>\n<li>Place your hands on the back of your neck.</li>\n<li>Hinge your torso and head towards the floor.</li>\n</ol>\n","description_source":"1. Sit with your legs completely straight (knees locked), spread wide in a straddle position.\n2. Place your hands on the back of your neck.\n3. Hinge your torso and head towards the floor.","name":"Seated Pancake Good Morning","created":"2026-02-12T13:00:14.764Z","last_update":"2026-04-13T18:58:27.284Z","language":2,"uuid":"451c28fd-596e-4029-8b35-6cabc32355d1","exercise":1845}}],"aliases":[],"comments":[{"model":"exercises.exercisecomment","pk":616,"fields":{"uuid":"424d3239-5f95-4b9b-af2a-1740b27bd51e","translation":2980,"comment":"Keep your back as flat as possible."}},{"model":"exercises.exercisecomment","pk":617,"fields":{"uuid":"e11ad958-4c7f-49c6-96e3-0b00e4c17195","translation":2980,"comment":"Initiate the ascent/return with your lower back, keeping your chest up."}}]}'),
('wger', '1846', 'horse-stance-side-splits', 'https://wger.de/en/exercise/1846/view', 'CC-BY-SA-4.0', 'Croak6728', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1846,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Croak6728","license_author_url":"","license_derivative_source_url":"","uuid":"36411665-4a87-4ab5-b5d3-e4eaa2802a62","category":9,"variation_group":null,"created":"2026-02-12T13:10:31.907Z","last_update":"2026-02-12T13:10:31.907Z","muscles":[8],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2981,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Croak6728","license_author_url":"","license_derivative_source_url":"","description":"<ol>\n<li>Stand as for a squat, with your feet wide and your toes pointed slightly outwards.</li>\n<li>Gently squat into a deep, wide squat - your hips should be below your knees.</li>\n<li>Hold for 3 to 5 seconds.</li>\n<li>Come up under control, and repeat as needed.</li>\n</ol>\n","description_source":"1. Stand as for a squat, with your feet wide and your toes pointed slightly outwards.\n2. Gently squat into a deep, wide squat - your hips should be below your knees.\n3. Hold for 3 to 5 seconds.\n4. Come up under control, and repeat as needed.","name":"Horse Stance (Side Splits)","created":"2026-02-12T13:10:31.966Z","last_update":"2026-04-13T18:58:26.643Z","language":2,"uuid":"affed7a9-b1a7-41d7-ba66-ab37c25f2f02","exercise":1846}}],"aliases":[],"comments":[{"model":"exercises.exercisecomment","pk":618,"fields":{"uuid":"efaeb94e-4f4d-4377-8b9f-7b8151754a00","translation":2981,"comment":"Keep your back straight, as with squats."}},{"model":"exercises.exercisecomment","pk":619,"fields":{"uuid":"47f06aab-2450-4087-9554-6aaae35679c2","translation":2981,"comment":"For a better stretch, widen your stance."}}]}'),
('wger', '1847', 'straddle-l-sit', 'https://wger.de/en/exercise/1847/view', 'CC-BY-SA-4.0', 'Croak6728', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1847,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Croak6728","license_author_url":"","license_derivative_source_url":"","uuid":"d2cf769a-9271-41ae-90fc-aef813e41740","category":10,"variation_group":"c6422a88-6760-4103-8efa-d097a43769e3","created":"2026-02-12T13:17:18.539Z","last_update":"2026-02-12T13:25:16.414Z","muscles":[6],"muscles_secondary":[12,4,10,3],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2982,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Croak6728","license_author_url":"","license_derivative_source_url":"","description":"<p>With your legs in a sitting saddle position, push your body upwards off the ground. Your legs should be horizontal and point straight outwards. Your arms should be between your legs.</p>\n<p>Hold isometrically as long as required.</p>\n","description_source":"With your legs in a sitting saddle position, push your body upwards off the ground. Your legs should be horizontal and point straight outwards. Your arms should be between your legs.\n\nHold isometrically as long as required.","name":"Straddle L-Sit","created":"2026-02-12T13:17:18.593Z","last_update":"2026-04-13T18:58:27.558Z","language":2,"uuid":"d4f4c41c-4fe8-452b-9216-12c872523073","exercise":1847}}],"aliases":[],"comments":[{"model":"exercises.exercisecomment","pk":620,"fields":{"uuid":"f6b8378b-4a03-4917-b129-78776a76e0ee","translation":2982,"comment":"Maintain a hollow body shape."}},{"model":"exercises.exercisecomment","pk":621,"fields":{"uuid":"98ddcb0c-0b07-4c21-8911-f1298e8bf822","translation":2982,"comment":"Protract and depress your shoulders, and lock your elbows."}},{"model":"exercises.exercisecomment","pk":622,"fields":{"uuid":"170db98c-34e0-4e07-8343-08b316cc05c9","translation":2982,"comment":"Point your toes."}}]}'),
('wger', '1852', 'l-sit', 'https://wger.de/en/exercise/1852/view', 'CC-BY-SA-4.0', 'Croak6728', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1852,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Croak6728","license_author_url":"","license_derivative_source_url":"","uuid":"16202754-f567-4d23-a866-2c9cc8eba71d","category":10,"variation_group":"c6422a88-6760-4103-8efa-d097a43769e3","created":"2026-02-12T13:25:16.326Z","last_update":"2026-02-12T13:25:16.421Z","muscles":[12,4,6],"muscles_secondary":[10,5],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":2987,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Croak6728","license_author_url":"","license_derivative_source_url":"","description":"<p>Sit on the ground with your legs together and your arms by your sides. Push your body off the ground using your hands, maintaining the same sitting position so that your legs are straight and your feet do not touch the floor.</p>\n<p>Hold for as long as required.</p>\n","description_source":"Sit on the ground with your legs together and your arms by your sides. Push your body off the ground using your hands, maintaining the same sitting position so that your legs are straight and your feet do not touch the floor.\n\nHold for as long as required.","name":"L-sit","created":"2026-02-12T13:25:16.369Z","last_update":"2026-04-13T18:58:26.748Z","language":2,"uuid":"cecb9f25-2519-42a7-8830-6a00fe8e1df0","exercise":1852}}],"aliases":[],"comments":[{"model":"exercises.exercisecomment","pk":631,"fields":{"uuid":"78873fef-06a0-4660-9e6c-08e4949dda16","translation":2987,"comment":"Keep your shoulders depressed - do not allow yourself to shrug."}},{"model":"exercises.exercisecomment","pk":632,"fields":{"uuid":"90e95552-f074-4acc-8825-78f5d8ef8ab8","translation":2987,"comment":"Keep your arms straight."}}]}'),
