('wger', '1876', NULL, 'https://wger.de/en/exercise/1876/view', 'CC-BY-SA-4.0', 'Davidgj32', NULL, NULL, '{"exercise":{"model":"exercises.exercise","pk":1876,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Davidgj32","license_author_url":"","license_derivative_source_url":"","uuid":"b81f4e3c-64e2-4fbd-9198-d422f6f2151f","category":14,"variation_group":null,"created":"2026-02-16T17:12:05.103Z","last_update":"2026-02-16T17:12:05.103Z","muscles":[],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":3018,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Davidgj32","license_author_url":"","license_derivative_source_url":"","description":"<p>View the video to undestand the exercise</p>\n","description_source":"View the video to undestand the exercise","name":"Supported Calf Stretch","created":"2026-02-16T17:12:05.139Z","last_update":"2026-04-13T18:58:27.591Z","language":2,"uuid":"b0b16883-caac-490a-bbdf-981dc1398c4f","exercise":1876}}],"aliases":[],"comments":[]}'),
('wger', '1877', 'band-banded-scapular-retraction', 'https://wger.de/en/exercise/1877/view', 'CC-BY-SA-4.0', 'hurr99', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1877,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"hurr99","license_author_url":"","license_derivative_source_url":"","uuid":"add364ed-4444-4752-9a22-d85d58199fe5","category":12,"variation_group":null,"created":"2026-02-17T20:25:46.261Z","last_update":"2026-02-17T20:25:46.261Z","muscles":[2,9],"muscles_secondary":[],"equipment":[11]}},"translations":[{"model":"exercises.translation","pk":3019,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"hurr99","license_author_url":"","license_derivative_source_url":"","description":"<p>Attach one end of resistance band to wall/upright/... at shoulder height. Insert arm into the loop, at the tricep. Step back until band is pulled straight. Pull back elbow and shoulder against the resistance of the band.</p>\n","description_source":"Attach one end of resistance band to wall/upright/... at shoulder height. Insert arm into the loop, at the tricep. Step back until band is pulled straight. Pull back elbow and shoulder against the resistance of the band.","name":"Banded Scapular Retraction","created":"2026-02-17T20:25:46.345Z","last_update":"2026-04-13T18:58:26.064Z","language":2,"uuid":"284c7658-c89c-49e1-9f2d-5a08a2de77ca","exercise":1877}},{"model":"exercises.translation","pk":3020,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"hurr99","license_author_url":"","license_derivative_source_url":"","description":"<p>Band in Schullterhöhe an Wand/Pfosten/... anbringen. Arm durch die Schlaufe und am Trizeps anlegen. Band straff ziehen. Ellenbogen und Schulter dann nach hinten ziehen.</p>\n","description_source":"Band in Schullterhöhe an Wand/Pfosten/... anbringen. Arm durch die Schlaufe und am Trizeps anlegen. Band straff ziehen. Ellenbogen und Schulter dann nach hinten ziehen.","name":"Schulter-Rückzieher","created":"2026-02-17T20:25:46.396Z","last_update":"2026-04-13T18:58:27.242Z","language":1,"uuid":"4f705e1f-ba32-4a4b-932d-b43e6ba9e3b2","exercise":1877}}],"aliases":[],"comments":[]}'),
('wger', '1879', 'dumbbell-incline-y-raise', 'https://wger.de/en/exercise/1879/view', 'CC-BY-SA-4.0', 'Deflation', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1879,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Deflation","license_author_url":"","license_derivative_source_url":"","uuid":"16bd91ca-a9fe-47fc-b3a8-a9d70549e929","category":13,"variation_group":null,"created":"2026-02-23T02:52:36.574Z","last_update":"2026-02-23T02:52:36.574Z","muscles":[2],"muscles_secondary":[9],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":3023,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Deflation","license_author_url":"","license_derivative_source_url":"","description":"<ol>\n<li>Set\nan incline bench to a 45-degree angle and sit facing the bench, chest\nagainst the pad, with a dumbbell in each hand, palms facing each other.</li>\n<li>Position your feet firmly on the ground for stability and let your arms hang down naturally with a slight bend in your elbows.</li>\n<li>Engage your core and keep your back straight throughout the movement.</li>\n<li>Raise your arms forward and out to form a Y shape, keeping the movement controlled and your elbows slightly bent.</li>\n<li>Lift until your arms are roughly parallel to the floor and in line with your ears.</li>\n<li>Pause\nbriefly at the top of the movement to engage your shoulder muscles\nfully, then slowly lower your arms back down to the starting position.</li>\n<li>Ensure\nthe movement is slow and controlled during both the ascent and descent\nto maximize engagement of the deltoids and supporting muscles.</li>\n<li>Repeat for the desired number of repetitions, maintaining proper form throughout.</li>\n</ol>\n","description_source":"1. Set\n   an incline bench to a 45-degree angle and sit facing the bench, chest\n   against the pad, with a dumbbell in each hand, palms facing each other.\n2. Position your feet firmly on the ground for stability and let your arms hang down naturally with a slight bend in your elbows.\n3. Engage your core and keep your back straight throughout the movement.\n4. Raise your arms forward and out to form a Y shape, keeping the movement controlled and your elbows slightly bent.\n5. Lift until your arms are roughly parallel to the floor and in line with your ears.\n6. Pause\n   briefly at the top of the movement to engage your shoulder muscles\n   fully, then slowly lower your arms back down to the starting position.\n7. Ensure\n   the movement is slow and controlled during both the ascent and descent\n   to maximize engagement of the deltoids and supporting muscles.\n8. Repeat for the desired number of repetitions, maintaining proper form throughout.","name":"Incline DB Y-Raise","created":"2026-02-23T02:52:36.632Z","last_update":"2026-04-13T18:58:26.656Z","language":2,"uuid":"b1ce071c-3667-4652-a350-282931321272","exercise":1879}}],"aliases":[],"comments":[]}'),
('wger', '1880', 'pull-up-wide-grip', 'https://wger.de/en/exercise/1880/view', 'CC-BY-SA-4.0', 'Deflation', 'normalized', 100.0, '{"exercise":{"model":"exercises.exercise","pk":1880,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Deflation","license_author_url":"","license_derivative_source_url":"","uuid":"0e707ae0-1985-4b74-b0bc-24fc5021eab8","category":12,"variation_group":null,"created":"2026-02-23T02:55:40.954Z","last_update":"2026-02-23T02:55:40.954Z","muscles":[12],"muscles_secondary":[2,1,9],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":3024,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Deflation","license_author_url":"","license_derivative_source_url":"","description":"<ol>\n<li>Using a pronated grip, grasp the pull bar with a wider than shoulder width grip.</li>\n<li>Take a deep breath, squeeze your glutes and brace your abs. Depress\nthe shoulder blades and then drive the elbows straight down to the floor\nwhile activating the lats.</li>\n<li>Pull your chin towards the bar until the lats are fully contracted,\nthen slowly lower yourself back to the start position and repeat for the\nassigned number of repetitions.</li>\n</ol>\n","description_source":"1. Using a pronated grip, grasp the pull bar with a wider than shoulder width grip.\n2. Take a deep breath, squeeze your glutes and brace your abs. Depress\n   the shoulder blades and then drive the elbows straight down to the floor\n   while activating the lats.\n3. Pull your chin towards the bar until the lats are fully contracted,\n   then slowly lower yourself back to the start position and repeat for the\n   assigned number of repetitions.","name":"Wide Grip Pull Up","created":"2026-02-23T02:55:41.018Z","last_update":"2026-04-13T18:58:27.867Z","language":2,"uuid":"b91bdc5a-27e6-40cd-9ef2-27c7a5ec7363","exercise":1880}}],"aliases":[],"comments":[]}'),
('wger', '1881', NULL, 'https://wger.de/en/exercise/1881/view', 'CC-BY-SA-4.0', 'Deflation', NULL, NULL, '{"exercise":{"model":"exercises.exercise","pk":1881,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Deflation","license_author_url":"","license_derivative_source_url":"","uuid":"73646b21-62e3-493b-8d75-4179326cd404","category":8,"variation_group":null,"created":"2026-02-23T04:20:45.218Z","last_update":"2026-02-23T04:20:45.218Z","muscles":[],"muscles_secondary":[],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":3025,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Deflation","license_author_url":"","license_derivative_source_url":"","description":"<p>:   Grab two dumbbells with an overhand grip and lay your forearms across your knees.</p>\n<p>:   Let your wrists flex fully, then extend your wrists.</p>\n","description_source":":   Grab two dumbbells with an overhand grip and lay your forearms across your knees.\n\n:   Let your wrists flex fully, then extend your wrists.","name":"DB Wrist Extension","created":"2026-02-23T04:20:45.293Z","last_update":"2026-04-13T18:58:26.370Z","language":2,"uuid":"5af3d5c8-f5b9-4ad1-9cb8-482a01264755","exercise":1881}}],"aliases":[],"comments":[]}'),
('wger', '1882', 'cable-high-lateral-raise', 'https://wger.de/en/exercise/1882/view', 'CC-BY-SA-4.0', 'Deflation', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1882,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Deflation","license_author_url":"","license_derivative_source_url":"","uuid":"47b244f0-ebc6-4498-9d9f-7e7bff47322e","category":13,"variation_group":null,"created":"2026-02-23T04:25:01.295Z","last_update":"2026-02-23T04:25:01.295Z","muscles":[2],"muscles_secondary":[12,3],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":3026,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Deflation","license_author_url":"","license_derivative_source_url":"","description":"<p>Stand next to a cable machine with the pulley set to waist height.</p>\n<p>Grab the opposite-side handle with the hand farthest from the\npulley, keeping your palm facing in.</p>\n<p>Keep your core engaged, chest lifted, and shoulders relaxed. Maintain a slight bend in the elbow throughout the lift.</p>\n<p>Lift your arm out to the side until your elbow reaches shoulder height, keeping your wrist aligned with your elbow.</p>\n<p>Briefly pause at the top, then slowly lower the handle back to your side with control. Repeat for the desired reps.</p>\n","description_source":"Stand next to a cable machine with the pulley set to waist height.\n\nGrab the opposite-side handle with the hand farthest from the\npulley, keeping your palm facing in.\n\nKeep your core engaged, chest lifted, and shoulders relaxed. Maintain a slight bend in the elbow throughout the lift.\n\nLift your arm out to the side until your elbow reaches shoulder height, keeping your wrist aligned with your elbow.\n\nBriefly pause at the top, then slowly lower the handle back to your side with control. Repeat for the desired reps.","name":"High-Cable Lateral Raise","created":"2026-02-23T04:25:01.361Z","last_update":"2026-04-13T18:58:26.626Z","language":2,"uuid":"715eec2c-e2b7-4115-ac5e-01863b6ca2da","exercise":1882}}],"aliases":[],"comments":[]}'),
('wger', '1883', 'machine-chest-press-exercise', 'https://wger.de/en/exercise/1883/view', 'CC-BY-SA-4.0', 'Deflation', 'normalized', 100.0, '{"exercise":{"model":"exercises.exercise","pk":1883,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Deflation","license_author_url":"","license_derivative_source_url":"","uuid":"9e7b6a15-1893-4e85-a500-66251dfc6326","category":11,"variation_group":null,"created":"2026-02-23T04:32:13.699Z","last_update":"2026-02-23T04:32:13.699Z","muscles":[4],"muscles_secondary":[2,1,13,5],"equipment":[8]}},"translations":[{"model":"exercises.translation","pk":3027,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Deflation","license_author_url":"","license_derivative_source_url":"","description":"<ol>\n<li>Adjust the seat height so that the grips are parallel to your chest.</li>\n<li>Use your legs to push the foot forward pedal.</li>\n<li>Bring the handles to the start position.</li>\n<li>Keep your back and the cushion in contact with the handles, press outwards.</li>\n<li>Press the handles away from your chest and exhale.</li>\n<li>Allow the handles to come in gently until they reach your chest.</li>\n<li>Allow the handles to return to your chest as you exhale.</li>\n</ol>\n","description_source":"1. Adjust the seat height so that the grips are parallel to your chest.\n2. Use your legs to push the foot forward pedal.\n3. Bring the handles to the start position.\n4. Keep your back and the cushion in contact with the handles, press outwards.\n5. Press the handles away from your chest and exhale.\n6. Allow the handles to come in gently until they reach your chest.\n7. Allow the handles to return to your chest as you exhale.","name":"Machine Chest Press","created":"2026-02-23T04:32:13.769Z","last_update":"2026-04-13T18:58:26.831Z","language":2,"uuid":"eeda8966-7fa6-4394-8dd9-3e2e7c37800a","exercise":1883}}],"aliases":[],"comments":[]}'),
('wger', '1884', 'shinbox-ir-stretch', 'https://wger.de/en/exercise/1884/view', 'CC-BY-SA-4.0', 'teus_ergaster', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1884,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"teus_ergaster","license_author_url":"","license_derivative_source_url":"","uuid":"ceb58be5-2927-48c5-bb2d-4cc42b0a60e2","category":9,"variation_group":null,"created":"2026-02-23T21:24:27.636Z","last_update":"2026-02-23T21:24:27.636Z","muscles":[8,14],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":3028,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"teus_ergaster","license_author_url":"","license_derivative_source_url":"","description":"<ul>\n<li><strong>Starting Position:</strong> Sit on the floor with both hips and knees bent at 90-degree angles.</li>\n<li><strong>Leg Placement:</strong>\nPlace one leg in front of you (external rotation) and the other leg out\nto the side/behind you (internal rotation). The shins and knees should\nremain flat on the ground.</li>\n<li><strong>The Movement:</strong>\nKeeping your hips square, hinge your torso forward or tilt it laterally\n(side-to-side) toward the front leg to deepen the stretch.</li>\n<li><strong>Target Areas:</strong>\nStretches the glutes and piriformis (front leg) and the hip flexors and\nquads (back leg). Engages the core and obliques during lateral flexion.</li>\n<li><strong>Goal:</strong> Improves hip mobility, specifically internal and external rotation, and relieves lower back tension.</li>\n</ul>\n","description_source":"* **Starting Position:** Sit on the floor with both hips and knees bent at 90-degree angles.\n* **Leg Placement:**\n  Place one leg in front of you (external rotation) and the other leg out\n  to the side/behind you (internal rotation). The shins and knees should\n  remain flat on the ground.\n* **The Movement:**\n  Keeping your hips square, hinge your torso forward or tilt it laterally\n  (side-to-side) toward the front leg to deepen the stretch.\n* **Target Areas:**\n  Stretches the glutes and piriformis (front leg) and the hip flexors and\n  quads (back leg). Engages the core and obliques during lateral flexion.\n* **Goal:** Improves hip mobility, specifically internal and external rotation, and relieves lower back tension.","name":"Shinbox IR Stretch","created":"2026-02-23T21:24:27.699Z","last_update":"2026-04-13T18:58:27.332Z","language":2,"uuid":"948790fa-7679-4a33-8dfd-6958f4d879b8","exercise":1884}},{"model":"exercises.translation","pk":3029,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"teus_ergaster","license_author_url":"","license_derivative_source_url":"","description":"<ul>\n<li><strong>Posizione di partenza:</strong> Seduti a terra con entrambe le anche e le ginocchia piegate a 90 gradi.</li>\n<li><strong>Posizione delle gambe:</strong>\nUna gamba è posizionata davanti (rotazione esterna), l''altra è\nposizionata di lato/dietro (rotazione interna). Tibie e ginocchia devono\nrimanere appoggiate a terra.</li>\n<li><strong>Il movimento:</strong>\nMantenendo il bacino dritto, inclinare il busto in avanti o\nlateralmente (da un lato all''altro) verso la gamba anteriore per\nintensificare l''allungamento.</li>\n<li><strong>Aree coinvolte:</strong>\nAllunga i glutei e il piriforme (gamba anteriore) e i flessori\ndell''anca e i quadricipiti (gamba posteriore). Attiva il core e gli\nobliqui durante la flessione laterale.</li>\n<li><strong>Obiettivo:</strong> Migliora la mobilità dell''anca (rotazione interna ed esterna) e allevia la tensione nella zona lombare.</li>\n</ul>\n","description_source":"* **Posizione di partenza:** Seduti a terra con entrambe le anche e le ginocchia piegate a 90 gradi.\n* **Posizione delle gambe:**\n  Una gamba è posizionata davanti (rotazione esterna), l''altra è\n  posizionata di lato/dietro (rotazione interna). Tibie e ginocchia devono\n  rimanere appoggiate a terra.\n* **Il movimento:**\n  Mantenendo il bacino dritto, inclinare il busto in avanti o\n  lateralmente (da un lato all''altro) verso la gamba anteriore per\n  intensificare l''allungamento.\n* **Aree coinvolte:**\n  Allunga i glutei e il piriforme (gamba anteriore) e i flessori\n  dell''anca e i quadricipiti (gamba posteriore). Attiva il core e gli\n  obliqui durante la flessione laterale.\n* **Obiettivo:** Migliora la mobilità dell''anca (rotazione interna ed esterna) e allevia la tensione nella zona lombare.","name":"Shinbox IR stretch","created":"2026-02-23T21:24:27.734Z","last_update":"2026-04-13T18:58:27.335Z","language":13,"uuid":"b0ea0cbe-9c32-47ce-8e66-c802b796f7eb","exercise":1884}}],"aliases":[],"comments":[]}'),
('wger', '1885', 'dumbbell-ytwl-exercise', 'https://wger.de/en/exercise/1885/view', 'CC-BY-SA-4.0', 'teus_ergaster', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1885,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"teus_ergaster","license_author_url":"","license_derivative_source_url":"","uuid":"5986cd29-11ff-43f4-af65-fc48dec62156","category":13,"variation_group":null,"created":"2026-02-23T22:19:08.834Z","last_update":"2026-02-23T22:19:08.834Z","muscles":[2,9],"muscles_secondary":[],"equipment":[3,9]}},"translations":[{"model":"exercises.translation","pk":3030,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"teus_ergaster","license_author_url":"","license_derivative_source_url":"","description":"<ul>\n<li><strong>Purpose:</strong> Improves shoulder stability, posture, and scapular (shoulder blade) control. Often used in physical therapy and warm-ups.</li>\n<li><strong>Starting Position:</strong>\nStand with feet shoulder-width apart. Hinge forward at the hips (like a\ndeadlift) keeping your back flat, or lie face down on an incline bench.\nKeep your thumbs pointing up throughout.</li>\n<li><strong>Y (Arms up):</strong>\nExtend both arms straight forward and upward at a 135-degree angle from\nyour body, forming a \"Y\". Squeeze your shoulder blades together at the\ntop.</li>\n<li><strong>T (Arms out):</strong> Open your arms straight out to the sides, perpendicular to your body, forming a \"T\". Focus on pinching your shoulder blades.</li>\n<li><strong>W (Arms bent):</strong> Pull your elbows back, bending them to 90 degrees, and squeeze your shoulder blades to form a \"W\". Keep your wrists firm.</li>\n<li><strong>L (Arms rotated):</strong>\nStart with elbows bent at 90 degrees and close to your body. Rotate\nyour forearms outward (external rotation) like a goalpost, forming an\n\"L\" or a gate.</li>\n<li><strong>Key Focus:</strong>\nMovements should be slow and controlled. Always lead with the thumbs\nand think about moving the shoulder blades, not just the arms.</li>\n</ul>\n","description_source":"* **Purpose:** Improves shoulder stability, posture, and scapular (shoulder blade) control. Often used in physical therapy and warm-ups.\n* **Starting Position:**\n  Stand with feet shoulder-width apart. Hinge forward at the hips (like a\n  deadlift) keeping your back flat, or lie face down on an incline bench.\n  Keep your thumbs pointing up throughout.\n* **Y (Arms up):**\n  Extend both arms straight forward and upward at a 135-degree angle from\n  your body, forming a \"Y\". Squeeze your shoulder blades together at the\n  top.\n* **T (Arms out):** Open your arms straight out to the sides, perpendicular to your body, forming a \"T\". Focus on pinching your shoulder blades.\n* **W (Arms bent):** Pull your elbows back, bending them to 90 degrees, and squeeze your shoulder blades to form a \"W\". Keep your wrists firm.\n* **L (Arms rotated):**\n  Start with elbows bent at 90 degrees and close to your body. Rotate\n  your forearms outward (external rotation) like a goalpost, forming an\n  \"L\" or a gate.\n* **Key Focus:**\n  Movements should be slow and controlled. Always lead with the thumbs\n  and think about moving the shoulder blades, not just the arms.","name":"YTWL Exercise","created":"2026-02-23T22:19:08.937Z","last_update":"2026-04-13T18:58:27.889Z","language":2,"uuid":"c2918282-6da0-4d21-9950-851378a1922e","exercise":1885}},{"model":"exercises.translation","pk":3031,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"teus_ergaster","license_author_url":"","license_derivative_source_url":"","description":"<ul>\n<li><strong>Obiettivo:</strong>\nMigliorare la stabilità della spalla, la postura e il controllo delle\nscapole. Ampiamente usato in fisioterapia e nel riscaldamento.</li>\n<li><strong>Posizione iniziale:</strong>\nIn piedi con i piedi alla larghezza delle spalle. Piega il busto in\navanti mantenendo la schiena dritta (come uno stacco), oppure sdraiati a\npancia in giù su una panca inclinata. Tieni i pollici sempre rivolti\nverso l''alto.</li>\n<li><strong>Y (Braccia in alto):</strong>\nDistendi entrambe le braccia dritte in avanti e verso l''alto con un\nangolo di 135° rispetto al corpo, formando una \"Y\". Unisci le scapole\nnel punto più alto.</li>\n<li><strong>T (Braccia aperte):</strong> Apri le braccia lateralmente, perpendicolari al corpo, formando una \"T\". Concentrati sullo stringere le scapole.</li>\n<li><strong>W (Braccia piegate):</strong> Tira i gomiti indietro piegandoli a 90°, stringendo le scapole per formare una \"W\". Tieni i polsi fermi.</li>\n<li><strong>L (Rotazione esterna):</strong>\nGomiti piegati a 90° e vicini al corpo. Ruota gli avambracci verso\nl''esterno (rotazione esterna) come dei pali della porta, formando una\n\"L\".</li>\n<li><strong>Attenzione:</strong>\nI movimenti devono essere lenti e controllati. Guida sempre il\nmovimento con i pollici e concentrati sul movimento delle scapole, non\nsolo delle braccia.</li>\n</ul>\n","description_source":"* **Obiettivo:**\n  Migliorare la stabilità della spalla, la postura e il controllo delle\n  scapole. Ampiamente usato in fisioterapia e nel riscaldamento.\n* **Posizione iniziale:**\n  In piedi con i piedi alla larghezza delle spalle. Piega il busto in\n  avanti mantenendo la schiena dritta (come uno stacco), oppure sdraiati a\n  pancia in giù su una panca inclinata. Tieni i pollici sempre rivolti\n  verso l''alto.\n* **Y (Braccia in alto):**\n  Distendi entrambe le braccia dritte in avanti e verso l''alto con un\n  angolo di 135° rispetto al corpo, formando una \"Y\". Unisci le scapole\n  nel punto più alto.\n* **T (Braccia aperte):** Apri le braccia lateralmente, perpendicolari al corpo, formando una \"T\". Concentrati sullo stringere le scapole.\n* **W (Braccia piegate):** Tira i gomiti indietro piegandoli a 90°, stringendo le scapole per formare una \"W\". Tieni i polsi fermi.\n* **L (Rotazione esterna):**\n  Gomiti piegati a 90° e vicini al corpo. Ruota gli avambracci verso\n  l''esterno (rotazione esterna) come dei pali della porta, formando una\n  \"L\".\n* **Attenzione:**\n  I movimenti devono essere lenti e controllati. Guida sempre il\n  movimento con i pollici e concentrati sul movimento delle scapole, non\n  solo delle braccia.","name":"Esercizio YTWL","created":"2026-02-23T22:19:08.982Z","last_update":"2026-04-13T18:58:26.493Z","language":13,"uuid":"7a8c04b8-1d2a-495b-b2cd-16a303f62907","exercise":1885}}],"aliases":[],"comments":[]}'),
('wger', '1886', 'dumbbell-supine-hip-abduction', 'https://wger.de/en/exercise/1886/view', 'CC-BY-SA-4.0', 'teus_ergaster', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1886,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"teus_ergaster","license_author_url":"","license_derivative_source_url":"","uuid":"2fe15ae4-085b-4116-8d73-2a120cc2a231","category":9,"variation_group":null,"created":"2026-02-23T22:32:45.500Z","last_update":"2026-02-23T22:32:45.500Z","muscles":[8,10],"muscles_secondary":[],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":3032,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"teus_ergaster","license_author_url":"","license_derivative_source_url":"","description":"<ul>\n<li><strong>Starting Position:</strong>\nLie on your back (supine) on a mat, with your legs extended and\nrelaxed. Arms can be placed alongside your body or out to the sides for\nstability.</li>\n<li><strong>The Movement:</strong>\nSlightly lift one leg off the floor (keeping it straight or with a\nslight bend). Move it laterally outward, away from the other leg, as if\nstepping over a small obstacle.</li>\n<li><strong>Range of Motion:</strong>\nMove the leg as far as comfortable without lifting your pelvis or\nrotating your torso, feeling a stretch in the inner thigh and hip.</li>\n<li><strong>Return:</strong> Slowly bring the leg back to the starting position with controlled movement.</li>\n<li><strong>Goal:</strong> Improves lateral hip mobility (abduction) and strengthens the pelvic stabilizer muscles.</li>\n</ul>\n","description_source":"* **Starting Position:**\n  Lie on your back (supine) on a mat, with your legs extended and\n  relaxed. Arms can be placed alongside your body or out to the sides for\n  stability.\n* **The Movement:**\n  Slightly lift one leg off the floor (keeping it straight or with a\n  slight bend). Move it laterally outward, away from the other leg, as if\n  stepping over a small obstacle.\n* **Range of Motion:**\n  Move the leg as far as comfortable without lifting your pelvis or\n  rotating your torso, feeling a stretch in the inner thigh and hip.\n* **Return:** Slowly bring the leg back to the starting position with controlled movement.\n* **Goal:** Improves lateral hip mobility (abduction) and strengthens the pelvic stabilizer muscles.","name":"Supine Hip Abduction","created":"2026-02-23T22:32:45.559Z","last_update":"2026-04-13T18:58:27.581Z","language":2,"uuid":"642fe147-7543-415f-89da-80277782cda8","exercise":1886}},{"model":"exercises.translation","pk":3033,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"teus_ergaster","license_author_url":"","license_derivative_source_url":"","description":"<ul>\n<li><strong>Posizione iniziale:</strong>\nSdraiati sulla schiena (supini) su un tappetino, con le gambe distese e\nrilassate. Le braccia possono essere lungo i fianchi o aperte per\nmaggiore stabilità.</li>\n<li><strong>Il movimento:</strong>\nSolleva leggermente una gamba da terra (mantenendola tesa o con una\nleggera flessione). Spostala lateralmente verso l''esterno,\nallontanandola dall''altra gamba, come se dovessi scavalcare un piccolo\nostacolo.</li>\n<li><strong>Ampiezza:</strong>\nPorta la gamba più in là possibile senza sollevare il bacino o ruotare\nil busto, sentendo un allungamento nella parte interna della coscia e\ndell''anca.</li>\n<li><strong>Ritorno:</strong> Riporta lentamente la gamba alla posizione iniziale, controllando il movimento.</li>\n<li><strong>Obiettivo:</strong> Migliora la mobilità laterale dell''anca (abduzione) e allena i muscoli stabilizzatori del bacino.</li>\n</ul>\n","description_source":"* **Posizione iniziale:**\n  Sdraiati sulla schiena (supini) su un tappetino, con le gambe distese e\n  rilassate. Le braccia possono essere lungo i fianchi o aperte per\n  maggiore stabilità.\n* **Il movimento:**\n  Solleva leggermente una gamba da terra (mantenendola tesa o con una\n  leggera flessione). Spostala lateralmente verso l''esterno,\n  allontanandola dall''altra gamba, come se dovessi scavalcare un piccolo\n  ostacolo.\n* **Ampiezza:**\n  Porta la gamba più in là possibile senza sollevare il bacino o ruotare\n  il busto, sentendo un allungamento nella parte interna della coscia e\n  dell''anca.\n* **Ritorno:** Riporta lentamente la gamba alla posizione iniziale, controllando il movimento.\n* **Obiettivo:** Migliora la mobilità laterale dell''anca (abduzione) e allena i muscoli stabilizzatori del bacino.","name":"Abduzione dell''anca in posizione supina","created":"2026-02-23T22:32:45.589Z","last_update":"2026-04-13T18:58:25.999Z","language":13,"uuid":"0c0bfbac-a764-449b-b2b2-7f2bb6a40121","exercise":1886}}],"aliases":[],"comments":[]}'),
('wger', '1889', 'decline-bench-leg-raise', 'https://wger.de/en/exercise/1889/view', 'CC-BY-SA-4.0', 'nishant0712', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1889,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"nishant0712","license_author_url":"","license_derivative_source_url":"","uuid":"9ac4813e-79a6-4a4d-ab93-9cfa5bf7b8fa","category":10,"variation_group":"f1bfdc62-0ec0-4bf4-9862-96cacb08ed62","created":"2026-02-26T17:49:17.224Z","last_update":"2026-02-26T17:49:17.224Z","muscles":[6],"muscles_secondary":[],"equipment":[9]}},"translations":[{"model":"exercises.translation","pk":3036,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"nishant0712","license_author_url":"","license_derivative_source_url":"","description":"<ul>\n<li><strong>Setup</strong>: Lie on a decline bench with your head at the top and grip the handles.</li>\n<li><strong>The Start</strong>: Extend legs fully, keeping them slightly elevated to engage your core.</li>\n<li><strong>The Lift</strong>: Raise your legs toward the ceiling using your abs, not momentum.</li>\n<li><strong>The Squeeze</strong>: Pause and contract your lower abdominals at the top.</li>\n<li><strong>The Return</strong>: Lower your legs slowly to the starting position with control.</li>\n</ul>\n","description_source":"- **Setup**: Lie on a decline bench with your head at the top and grip the handles.\n- **The Start**: Extend legs fully, keeping them slightly elevated to engage your core.\n- **The Lift**: Raise your legs toward the ceiling using your abs, not momentum.\n- **The Squeeze**: Pause and contract your lower abdominals at the top.\n- **The Return**: Lower your legs slowly to the starting position with control.","name":"Decline Bench Leg Raise","created":"2026-02-26T17:49:17.258Z","last_update":"2026-04-13T18:58:26.375Z","language":2,"uuid":"d392db6b-f343-4024-a086-5e4e9f2a59b8","exercise":1889}}],"aliases":[],"comments":[]}'),
('wger', '1893', 'barbell-shoulder-press', 'https://wger.de/en/exercise/1893/view', 'CC-BY-SA-4.0', 'nishant0712', 'normalized', 100.0, '{"exercise":{"model":"exercises.exercise","pk":1893,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"nishant0712","license_author_url":"","license_derivative_source_url":"","uuid":"2500c212-6f14-4a8d-a997-04e9e7c04116","category":13,"variation_group":null,"created":"2026-02-26T18:32:51.939Z","last_update":"2026-02-26T18:32:51.939Z","muscles":[2],"muscles_secondary":[],"equipment":[1]}},"translations":[{"model":"exercises.translation","pk":3040,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"nishant0712","license_author_url":"","license_derivative_source_url":"","description":"<ul>\n<li><strong>Setup:</strong> Stand with feet together and grip the bar slightly wider than shoulders.</li>\n<li><strong>Position:</strong> Rest the bar on your upper chest.</li>\n<li><strong>Press:</strong> Brace your core and push the bar straight up until your arms lock out.</li>\n<li><strong>Finish:</strong> Control the bar back down to your chest.</li>\n<li>https://youtu.be/ZXpdJOLNoWw?si=u27cGyODoblXHBu1</li>\n</ul>\n","description_source":"- **Setup:** Stand with feet together and grip the bar slightly wider than shoulders.\n- **Position:** Rest the bar on your upper chest.\n- **Press:** Brace your core and push the bar straight up until your arms lock out.\n- **Finish:** Control the bar back down to your chest.\n- https://youtu.be/ZXpdJOLNoWw?si=u27cGyODoblXHBu1","name":"Overhead Barbell Press","created":"2026-02-26T18:32:51.988Z","last_update":"2026-04-13T18:58:26.892Z","language":2,"uuid":"4c6b30ff-c89e-4735-8255-296f3b9b1e0d","exercise":1893}}],"aliases":[{"model":"exercises.alias","pk":616,"fields":{"uuid":"445fdadb-bea7-4969-ba13-50dbdf781763","translation":3040,"alias":"Military Press"}}],"comments":[]}'),
('wger', '1897', 'barbell-bench-press-narrow-grip', 'https://wger.de/en/exercise/1897/view', 'CC-BY-SA-4.0', 'nishant0712', 'normalized', 100.0, '{"exercise":{"model":"exercises.exercise","pk":1897,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"nishant0712","license_author_url":"","license_derivative_source_url":"","uuid":"145a9e7d-d25f-4687-9eb6-5b35878e87b4","category":11,"variation_group":null,"created":"2026-02-26T19:58:47.920Z","last_update":"2026-02-26T19:58:47.920Z","muscles":[5],"muscles_secondary":[4],"equipment":[1]}},"translations":[{"model":"exercises.translation","pk":3044,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"nishant0712","license_author_url":"","license_derivative_source_url":"","description":"<ul>\n<li><strong>Setup:</strong> Lie flat on the bench and grip the bar at shoulder-width (closer than a standard bench press).</li>\n<li><strong>Descent:</strong> Lower the bar with control to your lower chest.</li>\n<li><strong>Form:</strong> Keep your elbows tucked in tight against your torso—do not let them flare out.</li>\n<li><strong>Ascent:</strong> Press the bar straight back up, squeezing your triceps at the top.</li>\n</ul>\n","description_source":"- **Setup:** Lie flat on the bench and grip the bar at shoulder-width (closer than a standard bench press).\n- **Descent:** Lower the bar with control to your lower chest.\n- **Form:** Keep your elbows tucked in tight against your torso—do not let them flare out.\n- **Ascent:** Press the bar straight back up, squeezing your triceps at the top.","name":"Close-Grip Bench Press","created":"2026-02-26T19:58:47.967Z","last_update":"2026-04-13T18:58:26.216Z","language":2,"uuid":"3b261e10-0ba3-4297-b0c2-81a1c3dd570e","exercise":1897}}],"aliases":[],"comments":[]}'),
('wger', '1900', 'tricep-rope-pushdowns', 'https://wger.de/en/exercise/1900/view', 'CC-BY-SA-4.0', 'nishant0712', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1900,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"nishant0712","license_author_url":"","license_derivative_source_url":"","uuid":"fc608f0e-d754-4911-ae59-8856952e7064","category":8,"variation_group":null,"created":"2026-02-26T20:17:49.166Z","last_update":"2026-02-26T20:17:49.166Z","muscles":[5],"muscles_secondary":[12],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":3047,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"nishant0712","license_author_url":"","license_derivative_source_url":"","description":"<ul>\n<li><strong>Setup:</strong> Stand facing the cable, feet shoulder-width apart, with a slight forward lean.</li>\n<li><strong>Grip:</strong> Hold the rope with palms facing each other and elbows tucked tight to your ribs.</li>\n<li><strong>Execution:</strong> Push the rope down until arms are fully straight, pulling the ends apart at the bottom.</li>\n<li><strong>Control:</strong> Keep upper arms still and return to the start with a slow, controlled motion.</li>\n</ul>\n","description_source":"- **Setup:** Stand facing the cable, feet shoulder-width apart, with a slight forward lean.\n- **Grip:** Hold the rope with palms facing each other and elbows tucked tight to your ribs.\n- **Execution:** Push the rope down until arms are fully straight, pulling the ends apart at the bottom.\n- **Control:** Keep upper arms still and return to the start with a slow, controlled motion.","name":"Tricep Rope Pushdowns","created":"2026-02-26T20:17:49.212Z","last_update":"2026-04-13T18:58:27.704Z","language":2,"uuid":"06ccfe15-0e92-4c14-9536-6dee8045615b","exercise":1900}}],"aliases":[],"comments":[]}'),
('wger', '1901', 'barbell-clean-and-press-2', 'https://wger.de/en/exercise/1901/view', 'CC-BY-SA-4.0', 'nishant0712', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1901,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"nishant0712","license_author_url":"","license_derivative_source_url":"","uuid":"2a125f64-1d10-4926-95ad-33a48e61b3d6","category":13,"variation_group":null,"created":"2026-02-26T20:55:41.009Z","last_update":"2026-02-26T20:55:41.009Z","muscles":[2],"muscles_secondary":[10],"equipment":[1]}},"translations":[{"model":"exercises.translation","pk":3048,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"nishant0712","license_author_url":"","license_derivative_source_url":"","description":"<ul>\n<li><strong>The First Pull:</strong> Lift the bar from the floor to knee-height by driving with the legs, keeping the angle of your back constant.</li>\n<li><strong>The \"Power\" Position:</strong> As the bar reaches mid-thigh, explosively shrug and extend your hips to create vertical momentum.</li>\n<li><strong>The Quick Elbow Turnover:</strong> In the catch phase, rotate your elbows rapidly under the bar to create a \"shelf\" on your front deltoids.</li>\n<li><strong>The Vertical Press:</strong> Press the bar in a straight line; your head should shift slightly forward once the bar clears your forehead to reach full lockout.</li>\n</ul>\n","description_source":"* **The First Pull:** Lift the bar from the floor to knee-height by driving with the legs, keeping the angle of your back constant.\n* **The \"Power\" Position:** As the bar reaches mid-thigh, explosively shrug and extend your hips to create vertical momentum.\n* **The Quick Elbow Turnover:** In the catch phase, rotate your elbows rapidly under the bar to create a \"shelf\" on your front deltoids.\n* **The Vertical Press:** Press the bar in a straight line; your head should shift slightly forward once the bar clears your forehead to reach full lockout.","name":"Clean and Press","created":"2026-02-26T20:55:41.077Z","last_update":"2026-04-13T18:58:26.214Z","language":2,"uuid":"cb56285b-e4fe-4c3d-a159-1e0fd203a2e7","exercise":1901}}],"aliases":[{"model":"exercises.alias","pk":620,"fields":{"uuid":"5d86113b-96bf-47a2-80d0-43736b65942e","translation":3048,"alias":"Barbell Clean and Press"}},{"model":"exercises.alias","pk":621,"fields":{"uuid":"8d19147c-0c10-4e12-8176-e173a83377d4","translation":3048,"alias":"Clean & Press"}},{"model":"exercises.alias","pk":622,"fields":{"uuid":"6e8b224f-f0bf-49dc-8bc0-c49a4dd8ca01","translation":3048,"alias":"Olympic Clean and Press"}}],"comments":[]}'),
('wger', '1902', 'weighted-push-up', 'https://wger.de/en/exercise/1902/view', 'CC-BY-SA-4.0', 'nishant0712', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1902,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"nishant0712","license_author_url":"","license_derivative_source_url":"","uuid":"37abbe32-2fab-4818-8355-fffcff2dc3e3","category":11,"variation_group":null,"created":"2026-02-26T21:06:51.476Z","last_update":"2026-02-26T21:06:51.476Z","muscles":[4],"muscles_secondary":[5],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":3049,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"nishant0712","license_author_url":"","license_derivative_source_url":"","description":"<ul>\n<li><strong>Setup:</strong> Begin in a standard plank position with a weight plate balanced securely on your upper back.</li>\n<li><strong>Alignment:</strong> Maintain a straight line from your head to your heels, engaging your core to prevent your back from sagging.</li>\n<li><strong>Execution:</strong> Lower your body until your chest nearly touches the floor, keeping your elbows at a&nbsp;<strong>forty-five degrees</strong>.</li>\n<li><strong>Ascent:</strong> Press through your palms to return to the starting position, fully extending your arms.</li>\n</ul>\n","description_source":"- **Setup:** Begin in a standard plank position with a weight plate balanced securely on your upper back.\n- **Alignment:** Maintain a straight line from your head to your heels, engaging your core to prevent your back from sagging.\n- **Execution:** Lower your body until your chest nearly touches the floor, keeping your elbows at a **forty-five degrees**.\n- **Ascent:** Press through your palms to return to the starting position, fully extending your arms.","name":"Weighted push-ups","created":"2026-02-26T21:06:51.572Z","last_update":"2026-04-13T18:58:27.864Z","language":2,"uuid":"1d10ee1f-cd3e-4335-9589-ba8bc35091f9","exercise":1902}}],"aliases":[],"comments":[]}'),
('wger', '1903', 'band-walking-lunge', 'https://wger.de/en/exercise/1903/view', 'CC-BY-SA-4.0', 'nishant0712', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1903,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"nishant0712","license_author_url":"","license_derivative_source_url":"","uuid":"cb7b9c95-bef9-4a84-9b26-13dab0f29da1","category":9,"variation_group":null,"created":"2026-02-26T21:17:50.757Z","last_update":"2026-02-26T21:17:50.757Z","muscles":[10],"muscles_secondary":[8],"equipment":[11]}},"translations":[{"model":"exercises.translation","pk":3050,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"nishant0712","license_author_url":"","license_derivative_source_url":"","description":"<ul>\n<li><strong>Starting Position:</strong> Stand with feet hip-width apart and hands either on your hips or holding dumbbells at your sides.</li>\n<li><strong>The Stride:</strong> Take a wide step forward with your right leg.</li>\n<li><strong>The Descent:</strong> Lower your hips until both knees are bent at approximately <strong>90-degree angles</strong>.</li>\n<li><strong>The Transition:</strong> Drive through your front heel to stand up, bringing your back foot forward to step directly into the next lunge.</li>\n</ul>\n","description_source":"- **Starting Position:** Stand with feet hip-width apart and hands either on your hips or holding dumbbells at your sides.\n- **The Stride:** Take a wide step forward with your right leg.\n- **The Descent:** Lower your hips until both knees are bent at approximately **90-degree angles**.\n- **The Transition:** Drive through your front heel to stand up, bringing your back foot forward to step directly into the next lunge.","name":"Walking Lunges","created":"2026-02-26T21:17:50.826Z","last_update":"2026-04-13T18:58:27.834Z","language":2,"uuid":"5202d01f-2dac-4178-82ba-89f4a69911e7","exercise":1903}}],"aliases":[{"model":"exercises.alias","pk":623,"fields":{"uuid":"f3f765b4-9c3e-4bfb-bfbc-4a8684440c7a","translation":3050,"alias":"Walking Dumbbell Lunges"}},{"model":"exercises.alias","pk":624,"fields":{"uuid":"db203ef7-ecd9-4a61-934f-7ad2bacdb7a0","translation":3050,"alias":"Forward Walking Lunges"}},{"model":"exercises.alias","pk":625,"fields":{"uuid":"2c4a982a-4622-4d3c-9189-8d86d30a51ab","translation":3050,"alias":"Alternating Lunges (Walking)"}},{"model":"exercises.alias","pk":626,"fields":{"uuid":"3b90b3c7-72d5-478b-b9d3-adfb5696e792","translation":3050,"alias":"Stepping Lunges"}},{"model":"exercises.alias","pk":627,"fields":{"uuid":"ee7f2ca8-edd4-413f-b462-10416da50ab8","translation":3050,"alias":"Dynamic Lunges"}},{"model":"exercises.alias","pk":628,"fields":{"uuid":"31be85f5-ef64-451d-b838-456844dc7436","translation":3050,"alias":"Dynamic Lunges"}},{"model":"exercises.alias","pk":629,"fields":{"uuid":"187d97cd-b878-4309-9324-38c0f1d51f7c","translation":3050,"alias":"Forward Walking Lunges"}}],"comments":[]}'),
('wger', '1904', 'pec-deck', 'https://wger.de/en/exercise/1904/view', 'CC-BY-SA-4.0', NULL, 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1904,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","uuid":"71b9da1a-ac07-49c8-8b2d-7179032181fd","category":11,"variation_group":null,"created":"2026-02-27T16:42:46.225Z","last_update":"2026-02-27T16:42:46.225Z","muscles":[4],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":3051,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","description":"<p>Pectoral issolation exercise - full range of motion is best with full contraction and slow negative</p>\n","description_source":"Pectoral issolation exercise - full range of motion is best with full contraction and slow negative","name":"Pec Deck","created":"2026-02-27T16:42:46.347Z","last_update":"2026-04-13T18:58:26.912Z","language":2,"uuid":"7235f311-2d7e-4cfa-a4fe-db0898e6202f","exercise":1904}}],"aliases":[],"comments":[]}'),
('wger', '1905', 'pullback', 'https://wger.de/en/exercise/1905/view', 'CC-BY-SA-4.0', 'cybro', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1905,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"cybro","license_author_url":"","license_derivative_source_url":"","uuid":"289bd40b-e3dd-4217-8670-e475771a0ea7","category":12,"variation_group":null,"created":"2026-02-28T14:13:31.246Z","last_update":"2026-02-28T14:13:31.246Z","muscles":[1,12],"muscles_secondary":[13],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":3052,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"cybro","license_author_url":"","license_derivative_source_url":"","description":"<p>Set weight and grip for the cables in the cage. Take a few steps away, bend over, pull and extend the back at the same time.</p>\n","description_source":"Set weight and grip for the cables in the cage. Take a few steps away, bend over, pull and extend the back at the same time.","name":"Pullback","created":"2026-02-28T14:13:31.362Z","last_update":"2026-04-13T18:58:27.095Z","language":2,"uuid":"d1ed6252-7ea6-402d-8134-f4cf19b51294","exercise":1905}}],"aliases":[],"comments":[]}'),
('wger', '1906', 'hip-bridge', 'https://wger.de/en/exercise/1906/view', 'CC-BY-SA-4.0', 'cybro', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1906,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"cybro","license_author_url":"","license_derivative_source_url":"","uuid":"6b127132-cc0b-4b40-ac8c-177a28ccb6e2","category":9,"variation_group":null,"created":"2026-03-02T12:49:18.160Z","last_update":"2026-03-02T12:49:18.160Z","muscles":[8,6],"muscles_secondary":[14],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":3053,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"cybro","license_author_url":"","license_derivative_source_url":"","description":"<p>Get into bridge position, balance yourself on heels and start extending legs unilaterally.</p>\n<p>Keep hip extended as much as possible.</p>\n","description_source":"Get into bridge position, balance yourself on heels and start extending legs unilaterally.\n\nKeep hip extended as much as possible.","name":"Hip Bridge","created":"2026-03-02T12:49:18.220Z","last_update":"2026-04-13T18:58:26.630Z","language":2,"uuid":"7b21d758-2e74-4e7f-9d8a-3e8209845d4a","exercise":1906}}],"aliases":[],"comments":[]}'),
('wger', '1907', 'unilateral-lunge', 'https://wger.de/en/exercise/1907/view', 'CC-BY-SA-4.0', 'cybro', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1907,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"cybro","license_author_url":"","license_derivative_source_url":"","uuid":"2dd1cf54-b8e3-4769-9455-48120d7cc427","category":9,"variation_group":null,"created":"2026-03-02T12:50:59.560Z","last_update":"2026-03-02T12:50:59.560Z","muscles":[8,10],"muscles_secondary":[11],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":3054,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"cybro","license_author_url":"","license_derivative_source_url":"","description":"<p>No stops during movement, hands on the hips.</p>\n","description_source":"No stops during movement, hands on the hips.","name":"Unilateral Lunges","created":"2026-03-02T12:50:59.601Z","last_update":"2026-04-13T18:58:27.752Z","language":2,"uuid":"a5e1edb2-261d-4ca6-9701-e7eae7411269","exercise":1907}}],"aliases":[],"comments":[]}'),
('wger', '1908', 'butterfly-superman', 'https://wger.de/en/exercise/1908/view', 'CC-BY-SA-4.0', 'cybro', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1908,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"cybro","license_author_url":"","license_derivative_source_url":"","uuid":"de06856d-109d-4bef-acab-0918028cea36","category":12,"variation_group":null,"created":"2026-03-02T12:54:12.157Z","last_update":"2026-03-02T12:54:12.157Z","muscles":[9],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":3055,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"cybro","license_author_url":"","license_derivative_source_url":"","description":"<p>Lie on stomach, intertwine fingers behind the head and start raising your head and raise elbows as far as they go.</p>\n","description_source":"Lie on stomach, intertwine fingers behind the head and start raising your head and raise elbows as far as they go.","name":"Butterfly Superman","created":"2026-03-02T12:54:12.193Z","last_update":"2026-04-13T18:58:26.167Z","language":2,"uuid":"40f33f28-b2fe-46f1-93e7-23808b47e080","exercise":1908}}],"aliases":[],"comments":[]}'),
('wger', '1909', 'leg-wheel', 'https://wger.de/en/exercise/1909/view', 'CC-BY-SA-4.0', 'cybro', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1909,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"cybro","license_author_url":"","license_derivative_source_url":"","uuid":"19d10f51-3e53-4d8f-b283-1d8d9a7d3543","category":10,"variation_group":null,"created":"2026-03-02T12:57:35.904Z","last_update":"2026-03-02T12:57:35.904Z","muscles":[6],"muscles_secondary":[],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":3056,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"cybro","license_author_url":"","license_derivative_source_url":"","description":"<p>Lay on the back and lift legs in perpendicular fashion, keeping the knees together.</p>\n<p>Start making small circles in one direction with both of your knees with very small range of motion, focusing on abs and keeping your back in contact with the floor.</p>\n","description_source":"Lay on the back and lift legs in perpendicular fashion, keeping the knees together.\n\nStart making small circles in one direction with both of your knees with very small range of motion, focusing on abs and keeping your back in contact with the floor.","name":"Leg Wheel","created":"2026-03-02T12:57:35.933Z","last_update":"2026-04-13T18:58:26.783Z","language":2,"uuid":"89c7ff2f-663c-4cc8-9bae-376ffe8b0313","exercise":1909}}],"aliases":[],"comments":[]}'),
('wger', '1910', 'kneeling-superman', 'https://wger.de/en/exercise/1910/view', 'CC-BY-SA-4.0', 'cybro', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1910,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"cybro","license_author_url":"","license_derivative_source_url":"","uuid":"00f4a2b1-b1ac-49e6-a657-1d27e46522fd","category":12,"variation_group":null,"created":"2026-03-02T13:03:08.058Z","last_update":"2026-03-02T13:03:08.058Z","muscles":[11,9],"muscles_secondary":[6],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":3057,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"cybro","license_author_url":"","license_derivative_source_url":"","description":"<ul>\n<li>\n<p>Push one foot back until leg fully extended, concentrating on the having the foot high and pushed back as if pulled.</p>\n</li>\n<li>\n<p>Extend arm forward with focus having the shoulder high up.</p>\n</li>\n</ul>\n<p>Unilateral and static hold.</p>\n","description_source":"- Push one foot back until leg fully extended, concentrating on the having the foot high and pushed back as if pulled.\n\n- Extend arm forward with focus having the shoulder high up.\n\nUnilateral and static hold.","name":"Kneeling Superman","created":"2026-03-02T13:03:08.143Z","last_update":"2026-04-13T18:58:26.726Z","language":2,"uuid":"69462354-d751-44a4-8af8-00f15b332cfa","exercise":1910}}],"aliases":[],"comments":[]}'),
('wger', '1911', 'cat-plank', 'https://wger.de/en/exercise/1911/view', 'CC-BY-SA-4.0', 'cybro', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1911,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"cybro","license_author_url":"","license_derivative_source_url":"","uuid":"b02825ca-bbe4-4a07-a162-2b7a6c0a662b","category":9,"variation_group":null,"created":"2026-03-02T13:09:31.421Z","last_update":"2026-03-02T13:09:31.421Z","muscles":[10,6],"muscles_secondary":[2],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":3058,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"cybro","license_author_url":"","license_derivative_source_url":"","description":"<p>On your fours and raise the knees of the floor ever so slightly.&nbsp;\nCurl your back out and push back from your shoulders as to resemble a cat making itself look large.</p>\n","description_source":"On your fours and raise the knees of the floor ever so slightly. \nCurl your back out and push back from your shoulders as to resemble a cat making itself look large.","name":"Cat Plank","created":"2026-03-02T13:09:31.505Z","last_update":"2026-04-13T18:58:26.198Z","language":2,"uuid":"cce1a183-6642-4a86-a30c-189a1defd318","exercise":1911}}],"aliases":[],"comments":[]}'),
('wger', '1912', 'core-rotation', 'https://wger.de/en/exercise/1912/view', 'CC-BY-SA-4.0', 'cybro', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1912,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"cybro","license_author_url":"","license_derivative_source_url":"","uuid":"1b140999-e1fa-49b5-9f2b-690bac959db3","category":10,"variation_group":null,"created":"2026-03-02T13:19:07.171Z","last_update":"2026-03-02T13:19:07.171Z","muscles":[10,6],"muscles_secondary":[14,3],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":3059,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"cybro","license_author_url":"","license_derivative_source_url":"","description":"<p>Sit back, raise feet above the ground with knees bent and start rotating left and right with hands touching the ground every move.</p>\n","description_source":"Sit back, raise feet above the ground with knees bent and start rotating left and right with hands touching the ground every move.","name":"Core Rotation","created":"2026-03-02T13:19:07.288Z","last_update":"2026-04-13T18:58:26.228Z","language":2,"uuid":"f17db69f-c3cb-4de7-9da2-258319a4812e","exercise":1912}}],"aliases":[],"comments":[]}'),
('wger', '1913', 'unilateral-hip-thrust', 'https://wger.de/en/exercise/1913/view', 'CC-BY-SA-4.0', 'cybro', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1913,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"cybro","license_author_url":"","license_derivative_source_url":"","uuid":"139e3d1a-ccd5-46cd-b953-8db6cea7b005","category":9,"variation_group":null,"created":"2026-03-02T13:24:02.280Z","last_update":"2026-03-02T13:24:02.280Z","muscles":[8],"muscles_secondary":[6],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":3060,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"cybro","license_author_url":"","license_derivative_source_url":"","description":"<p>Extend one leg while laying down and start raising your body with one leg touching the ground through the heel.</p>\n","description_source":"Extend one leg while laying down and start raising your body with one leg touching the ground through the heel.","name":"Unilateral Hip Thrust","created":"2026-03-02T13:24:02.414Z","last_update":"2026-04-13T18:58:27.751Z","language":2,"uuid":"082627fb-6f53-4ac7-81c7-d4224dade5b1","exercise":1913}}],"aliases":[],"comments":[]}'),
('wger', '1914', 'isometria-alle-parallele', 'https://wger.de/en/exercise/1914/view', 'CC-BY-SA-4.0', NULL, 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1914,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","uuid":"7a1e0cd7-0076-4d4d-b05f-1d114235f199","category":13,"variation_group":null,"created":"2026-03-03T07:15:14.125Z","last_update":"2026-03-03T07:15:14.125Z","muscles":[4,9],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":3061,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","description":"<p>The parallel bars isometric hold is a static upper-body exercise performed on dip bars (parallel bars). Instead of moving up and down like in a traditional dip, you hold a fixed position under tension.</p>\n","description_source":"The parallel bars isometric hold is a static upper-body exercise performed on dip bars (parallel bars). Instead of moving up and down like in a traditional dip, you hold a fixed position under tension.","name":"Isometria alle parallele","created":"2026-03-03T07:15:14.221Z","last_update":"2026-04-13T18:58:26.672Z","language":2,"uuid":"c212fe8e-a1e9-44d0-8c10-1737a869f3c5","exercise":1914}}],"aliases":[],"comments":[]}'),
('wger', '1915', NULL, 'https://wger.de/en/exercise/1915/view', 'CC-BY-SA-4.0', 'treder', NULL, NULL, '{"exercise":{"model":"exercises.exercise","pk":1915,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"treder","license_author_url":"","license_derivative_source_url":"","uuid":"2a1f7c0c-c63d-43f1-9934-a209ed405ff8","category":14,"variation_group":null,"created":"2026-03-04T10:13:46.289Z","last_update":"2026-03-04T10:13:46.289Z","muscles":[],"muscles_secondary":[],"equipment":[11,7]}},"translations":[{"model":"exercises.translation","pk":3062,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"treder","license_author_url":"","license_derivative_source_url":"","description":"<p>Distribute your body weight evenly on all knees and arms.\nKeep the torso stable, with the abdomen engaged and the lumbar spine\nstraight without twisting the back (imagine: a glass on your lower back\nwon''t fall off). Raise one leg outwards without twisting it.</p>\n<p>Pay attention to the right angle at the hips and knees.&nbsp;Always train both sides of the body.</p>\n<p>To increase resistance, a resistance band can be used.</p>\n","description_source":"Distribute your body weight evenly on all knees and arms.  \nKeep the torso stable, with the abdomen engaged and the lumbar spine\nstraight without twisting the back (imagine: a glass on your lower back\nwon''t fall off). Raise one leg outwards without twisting it.\n\nPay attention to the right angle at the hips and knees. Always train both sides of the body.\n\nTo increase resistance, a resistance band can be used.","name":"Quadruped Hip Abduction","created":"2026-03-04T10:13:46.341Z","last_update":"2026-04-13T18:58:27.119Z","language":2,"uuid":"15bd7b27-4fd6-4fda-8602-38ce357dbb93","exercise":1915}}],"aliases":[],"comments":[]}'),
('wger', '1916', 'tuck-planche', 'https://wger.de/en/exercise/1916/view', 'CC-BY-SA-4.0', 'ISSACS', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1916,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"ISSACS","license_author_url":"","license_derivative_source_url":"","uuid":"3e9973f6-c218-4dd4-850b-da6f4f1622bb","category":13,"variation_group":null,"created":"2026-03-10T23:42:45.156Z","last_update":"2026-03-10T23:42:45.156Z","muscles":[2,6,3],"muscles_secondary":[14,4,5],"equipment":[7]}},"translations":[{"model":"exercises.translation","pk":3063,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"ISSACS","license_author_url":"","license_derivative_source_url":"","description":"<p>Basic calisthenics progression for the full planche</p>\n","description_source":"Basic calisthenics progression for the full planche","name":"Tuck planche","created":"2026-03-10T23:42:45.221Z","last_update":"2026-04-13T18:58:27.732Z","language":2,"uuid":"fd7ffeeb-590b-4b74-95f6-53c02623c8a1","exercise":1916}}],"aliases":[],"comments":[]}'),
('wger', '1918', NULL, 'https://wger.de/en/exercise/1918/view', 'CC-BY-SA-4.0', NULL, NULL, NULL, '{"exercise":{"model":"exercises.exercise","pk":1918,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","uuid":"2e96e572-ddb4-4251-a812-ccf03ea677a6","category":11,"variation_group":null,"created":"2026-03-12T13:15:17.728Z","last_update":"2026-03-12T13:15:17.728Z","muscles":[],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":3065,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","description":"<p>Plate-loaded chest press machine from Legend Fitness LeverEdge line.</p>\n","description_source":"Plate-loaded chest press machine from Legend Fitness LeverEdge line.","name":"Legend Chest Press","created":"2026-03-12T13:15:18.438Z","last_update":"2026-04-13T18:58:26.786Z","language":2,"uuid":"c619e31d-2463-4aa5-b210-181b3b75676e","exercise":1918}}],"aliases":[],"comments":[]}'),
('wger', '1919', NULL, 'https://wger.de/en/exercise/1919/view', 'CC-BY-SA-4.0', NULL, NULL, NULL, '{"exercise":{"model":"exercises.exercise","pk":1919,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","uuid":"3c33c9fd-20cc-4dff-ac88-c992bb9b2e33","category":11,"variation_group":null,"created":"2026-03-12T13:15:19.039Z","last_update":"2026-03-12T13:15:19.039Z","muscles":[],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":3066,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","description":"<p>Deep loaded stretch for pectorals, typically performed at end of chest work.</p>\n","description_source":"Deep loaded stretch for pectorals, typically performed at end of chest work.","name":"Extreme Pec Stretch","created":"2026-03-12T13:15:19.657Z","last_update":"2026-04-13T18:58:26.516Z","language":2,"uuid":"85d6b83e-749a-40af-8875-de7e5e6ab54a","exercise":1919}}],"aliases":[],"comments":[]}'),
('wger', '1920', NULL, 'https://wger.de/en/exercise/1920/view', 'CC-BY-SA-4.0', NULL, NULL, NULL, '{"exercise":{"model":"exercises.exercise","pk":1920,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","uuid":"4925b6c0-bbe6-4864-a649-23ec18d49985","category":13,"variation_group":null,"created":"2026-03-12T13:15:20.220Z","last_update":"2026-03-12T13:15:20.220Z","muscles":[],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":3067,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","description":"<p>Deep loaded stretch for deltoids, performed after pressing movements.</p>\n","description_source":"Deep loaded stretch for deltoids, performed after pressing movements.","name":"Extreme Shoulder Stretch","created":"2026-03-12T13:15:20.775Z","last_update":"2026-04-13T18:58:26.517Z","language":2,"uuid":"9cbf4065-364f-4c2c-9a4b-b6cbf569aaa8","exercise":1920}}],"aliases":[],"comments":[]}'),
('wger', '1921', NULL, 'https://wger.de/en/exercise/1921/view', 'CC-BY-SA-4.0', NULL, NULL, NULL, '{"exercise":{"model":"exercises.exercise","pk":1921,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","uuid":"ab808c2c-2e84-42bb-a65d-287a06ca7aa2","category":12,"variation_group":null,"created":"2026-03-12T13:15:21.431Z","last_update":"2026-03-12T13:15:21.431Z","muscles":[],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":3068,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","description":"<p>Deep loaded stretch for latissimus dorsi, performed after pulling movements.</p>\n","description_source":"Deep loaded stretch for latissimus dorsi, performed after pulling movements.","name":"Extreme Lat Stretch","created":"2026-03-12T13:15:22.096Z","last_update":"2026-04-13T18:58:26.516Z","language":2,"uuid":"24401430-3082-4527-a8ed-af8fff01bbae","exercise":1921}}],"aliases":[],"comments":[]}'),
('wger', '1922', 'cable-seated-chest-fly', 'https://wger.de/en/exercise/1922/view', 'CC-BY-SA-4.0', 'shushu', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1922,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"shushu","license_author_url":"","license_derivative_source_url":"","uuid":"139772c6-e401-4281-8aa6-c7ff7fb49f6a","category":11,"variation_group":null,"created":"2026-03-13T14:16:15.027Z","last_update":"2026-03-13T14:16:15.027Z","muscles":[4],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":3069,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"shushu","license_author_url":"","license_derivative_source_url":"","description":"<ol>\n<li>Place a bench between two cable pulleys and adjust the pulleys so they are at chest/shoulder height when you are seated.</li>\n<li>Grab the handles with a neutral grip and lean against the upright backrest.</li>\n<li>Bring your arms together in front of your chest in a controlled motion, focusing on squeezing your chest muscles. Keep your elbows slightly bent throughout the movement.</li>\n<li>Pause briefly at the top position.</li>\n<li>Slowly lower your arms back to the starting position while maintaining control of the movement.</li>\n<li>Repeat for reps.</li>\n</ol>\n","description_source":"1. Place a bench between two cable pulleys and adjust the pulleys so they are at chest/shoulder height when you are seated.\n2. Grab the handles with a neutral grip and lean against the upright backrest.\n3. Bring your arms together in front of your chest in a controlled motion, focusing on squeezing your chest muscles. Keep your elbows slightly bent throughout the movement.\n4. Pause briefly at the top position.\n5. Slowly lower your arms back to the starting position while maintaining control of the movement.\n6. Repeat for reps.","name":"Seated Cable chest fly","created":"2026-03-13T14:16:15.113Z","last_update":"2026-04-13T18:58:27.267Z","language":2,"uuid":"0407c6fa-9ebb-4ad3-95fd-1e94bd7e8f11","exercise":1922}},{"model":"exercises.translation","pk":3070,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"shushu","license_author_url":"","license_derivative_source_url":"","description":"<p>Die Übung wird auch als \"Cable Fly\", \"Cable Crossover\" oder \"Butterfly am Kabelzug\" bezeichnet</p>\n","description_source":"Die Übung wird auch als \"Cable Fly\", \"Cable Crossover\" oder \"Butterfly am Kabelzug\" bezeichnet","name":"Butterfly am Kabelzug","created":"2026-03-13T14:16:15.166Z","last_update":"2026-04-13T18:58:26.168Z","language":1,"uuid":"44f688e0-75ea-43ae-aaab-fc62f204d9da","exercise":1922}}],"aliases":[],"comments":[]}'),
('wger', '1924', '3008-abdominal-crunch', 'https://wger.de/en/exercise/1924/view', 'CC-BY-SA-4.0', NULL, 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1924,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","uuid":"7870ad8d-a0c1-4e3a-a4fe-a237908eba9b","category":10,"variation_group":null,"created":"2026-03-22T20:00:05.927Z","last_update":"2026-03-22T20:00:05.927Z","muscles":[6],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":3073,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","description":"<p>This is especially for the gym80 device 3008 Abdominal Crunch.</p>\n","description_source":"This is especially for the gym80 device 3008 Abdominal Crunch.","name":"3008 Abdominal Crunch","created":"2026-03-22T20:00:05.989Z","last_update":"2026-04-13T18:58:25.973Z","language":2,"uuid":"58dd7dc3-0029-49c4-8e5f-fecbba5ba16e","exercise":1924}}],"aliases":[{"model":"exercises.alias","pk":630,"fields":{"uuid":"f18e3c4d-6b6b-4078-83d1-59245d1e4f36","translation":3073,"alias":"3008 Klappsitz"}}],"comments":[]}'),
('wger', '1925', 'barbell-silverback-shrug', 'https://wger.de/en/exercise/1925/view', 'CC-BY-SA-4.0', NULL, 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1925,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","uuid":"64b50772-c73d-4833-8518-947a648fa623","category":13,"variation_group":null,"created":"2026-03-23T09:45:09.998Z","last_update":"2026-03-23T09:45:09.998Z","muscles":[9],"muscles_secondary":[],"equipment":[1]}},"translations":[{"model":"exercises.translation","pk":3074,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","description":"<ol>\n<li>Stand with your feet shoulder width apart holding the barbell with both hands in front just past shoulder width.</li>\n<li>Bend forward at the hips with a slight bend in your knees, keeping your back straight.</li>\n<li>Engage your shoulder blades, as if you are trying to touch them together.</li>\n<li>Release the shrug.\nDescription taken from MuscleWiki</li>\n</ol>\n","description_source":"1. Stand with your feet shoulder width apart holding the barbell with both hands in front just past shoulder width.\n2. Bend forward at the hips with a slight bend in your knees, keeping your back straight.\n3. Engage your shoulder blades, as if you are trying to touch them together.\n4. Release the shrug.\nDescription taken from MuscleWiki","name":"Barbell Silverback Shrug","created":"2026-03-23T09:45:10.043Z","last_update":"2026-04-13T18:58:26.077Z","language":2,"uuid":"5788eec1-35b8-40ae-a010-e03b64695466","exercise":1925}}],"aliases":[],"comments":[]}'),
('wger', '1927', 'inverted-lat-pull-down', 'https://wger.de/en/exercise/1927/view', 'CC-BY-SA-4.0', 'amaesc', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1927,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"amaesc","license_author_url":"","license_derivative_source_url":"","uuid":"1639425c-7dc6-4776-b039-47ef14a328ee","category":12,"variation_group":null,"created":"2026-03-23T15:46:34.813Z","last_update":"2026-03-23T15:46:34.813Z","muscles":[12,9],"muscles_secondary":[1,13,14,6,3],"equipment":[6]}},"translations":[{"model":"exercises.translation","pk":3076,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"amaesc","license_author_url":"","license_derivative_source_url":"","description":"<p>The <strong>Inverted Lat Pull Down</strong> (most commonly known as the <strong>Reverse Grip Lat Pull Down</strong>) is a variation of the standard exercise that uses an underhand (supinated) grip with hands at shoulder-width. This position shifts more emphasis to the <strong>lower lats</strong> and increases <strong>biceps</strong> involvement, often allowing for a greater range of motion and a deeper squeeze at the bottom of the movement.</p>\n","description_source":"The **Inverted Lat Pull Down** (most commonly known as the **Reverse Grip Lat Pull Down**) is a variation of the standard exercise that uses an underhand (supinated) grip with hands at shoulder-width. This position shifts more emphasis to the **lower lats** and increases **biceps** involvement, often allowing for a greater range of motion and a deeper squeeze at the bottom of the movement.","name":"Inverted Lat Pull Down","created":"2026-03-23T15:46:34.877Z","last_update":"2026-04-13T18:58:26.668Z","language":2,"uuid":"c20705a1-1b6b-4724-b83d-47d2fc83f2fe","exercise":1927}}],"aliases":[],"comments":[]}'),
('wger', '1928', 'band-seated-v-grip-row', 'https://wger.de/en/exercise/1928/view', 'CC-BY-SA-4.0', 'amaesc', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1928,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"amaesc","license_author_url":"","license_derivative_source_url":"","uuid":"b2ca4a13-6fe2-4c4f-85b2-dcb5af28d2be","category":12,"variation_group":null,"created":"2026-03-23T15:51:52.143Z","last_update":"2026-03-23T15:51:52.143Z","muscles":[12,9],"muscles_secondary":[2,1,6,3],"equipment":[11]}},"translations":[{"model":"exercises.translation","pk":3077,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"amaesc","license_author_url":"","license_derivative_source_url":"","description":"<p>The <strong>Seated V-Grip Row</strong> is a compound pulling exercise performed on a cable machine using a close-grip \"V\" handle. While seated with your feet braced, you pull the handle toward your midsection, focusing on <strong>back thickness</strong> and mid-back development.</p>\n","description_source":"The **Seated V-Grip Row** is a compound pulling exercise performed on a cable machine using a close-grip \"V\" handle. While seated with your feet braced, you pull the handle toward your midsection, focusing on **back thickness** and mid-back development.","name":"Seated V-Grip Row","created":"2026-03-23T15:51:52.281Z","last_update":"2026-04-13T18:58:27.290Z","language":2,"uuid":"d26348bc-006d-47ac-a3fc-ddd3592920f0","exercise":1928}}],"aliases":[],"comments":[]}'),
('wger', '1929', 'band-assisted-pull-up', 'https://wger.de/en/exercise/1929/view', 'CC-BY-SA-4.0', 'amaesc', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1929,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"amaesc","license_author_url":"","license_derivative_source_url":"","uuid":"8bc4c616-e76b-4291-9074-186ecbbb3cfd","category":12,"variation_group":null,"created":"2026-03-23T15:55:41.657Z","last_update":"2026-03-23T15:55:41.657Z","muscles":[12,9],"muscles_secondary":[2,1,6,3],"equipment":[11]}},"translations":[{"model":"exercises.translation","pk":3078,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"amaesc","license_author_url":"","license_derivative_source_url":"","description":"<p>The <strong>Assisted Pull-Up</strong> is a compound vertical pulling exercise performed on a machine with a counterweight platform or by using resistance bands. It mimics the mechanics of a standard pull-up but reduces the total weight you have to lift, making it an excellent tool for building functional strength and perfecting your technique.</p>\n","description_source":"The **Assisted Pull-Up** is a compound vertical pulling exercise performed on a machine with a counterweight platform or by using resistance bands. It mimics the mechanics of a standard pull-up but reduces the total weight you have to lift, making it an excellent tool for building functional strength and perfecting your technique.","name":"Assisted Pull-Up","created":"2026-03-23T15:55:41.762Z","last_update":"2026-04-13T18:58:26.047Z","language":2,"uuid":"dc59f760-8c2f-446c-9f90-877fa236a8d4","exercise":1929}}],"aliases":[],"comments":[]}'),
('wger', '1931', 'dumbbell-biceps-curl', 'https://wger.de/en/exercise/1931/view', 'CC-BY-SA-4.0', 'amaesc', 'normalized', 100.0, '{"exercise":{"model":"exercises.exercise","pk":1931,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"amaesc","license_author_url":"","license_derivative_source_url":"","uuid":"99846da5-5dc8-4de1-ba55-ae2b4c03c30d","category":8,"variation_group":null,"created":"2026-03-23T16:04:33.548Z","last_update":"2026-03-23T16:04:33.548Z","muscles":[1,13],"muscles_secondary":[2,6],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":3080,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"amaesc","license_author_url":"","license_derivative_source_url":"","description":"<p>The <strong>Dumbbell Curl</strong> is a classic isolation exercise for the arms. Unlike the Hammer Curl, it involves rotating your wrists (supination) as you lift the weights, which allows for a full contraction of the biceps.</p>\n","description_source":"The **Dumbbell Curl** is a classic isolation exercise for the arms. Unlike the Hammer Curl, it involves rotating your wrists (supination) as you lift the weights, which allows for a full contraction of the biceps.","name":"Dumbbell Curl","created":"2026-03-23T16:04:33.599Z","last_update":"2026-04-13T18:58:26.416Z","language":2,"uuid":"d311ef25-e808-432d-a74f-09b75f849724","exercise":1931}}],"aliases":[],"comments":[]}'),
('wger', '1932', 'dumbbell-hammer-curl', 'https://wger.de/en/exercise/1932/view', 'CC-BY-SA-4.0', 'amaesc', 'normalized', 100.0, '{"exercise":{"model":"exercises.exercise","pk":1932,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"amaesc","license_author_url":"","license_derivative_source_url":"","uuid":"422a48aa-a41e-46e7-b84f-0bd99ccb0737","category":8,"variation_group":null,"created":"2026-03-23T16:08:06.792Z","last_update":"2026-03-23T16:08:06.792Z","muscles":[1,13],"muscles_secondary":[2,6],"equipment":[3]}},"translations":[{"model":"exercises.translation","pk":3081,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"amaesc","license_author_url":"","license_derivative_source_url":"","description":"<p>The <strong>Hammer Curl</strong> is a\npopular isolation exercise for the arms, typically performed with\ndumbbells. Instead of rotating your wrists like a standard bicep curl,\nyou keep a neutral grip (palms facing each other) throughout the entire\nmovement, as if you were holding a hammer.</p>\n","description_source":"The **Hammer Curl** is a\npopular isolation exercise for the arms, typically performed with\ndumbbells. Instead of rotating your wrists like a standard bicep curl,\nyou keep a neutral grip (palms facing each other) throughout the entire\nmovement, as if you were holding a hammer.","name":"Hammer Curl","created":"2026-03-23T16:08:07.006Z","last_update":"2026-04-13T18:58:26.601Z","language":2,"uuid":"b49054ca-ef7d-487d-bb26-681cd06e48de","exercise":1932}}],"aliases":[],"comments":[]}'),
('wger', '1933', 'abdominal-crunch', 'https://wger.de/en/exercise/1933/view', 'CC-BY-SA-4.0', 'amaesc', 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1933,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"amaesc","license_author_url":"","license_derivative_source_url":"","uuid":"2ac901e6-f0c2-416f-998f-e01e00fe0aa1","category":10,"variation_group":null,"created":"2026-03-23T16:11:41.201Z","last_update":"2026-03-23T16:11:41.201Z","muscles":[6],"muscles_secondary":[14,3],"equipment":[4]}},"translations":[{"model":"exercises.translation","pk":3082,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"amaesc","license_author_url":"","license_derivative_source_url":"","description":"<p>The <strong>Abdominal Crunch</strong> is a classic core isolation exercise performed on the floor or a mat. Unlike a full sit-up, it involves a smaller range of motion where you only lift your shoulders and upper back off the ground, keeping your lower back pressed firmly against the floor.</p>\n","description_source":"The **Abdominal Crunch** is a classic core isolation exercise performed on the floor or a mat. Unlike a full sit-up, it involves a smaller range of motion where you only lift your shoulders and upper back off the ground, keeping your lower back pressed firmly against the floor.","name":"Abdominal Crunch","created":"2026-03-23T16:11:41.327Z","last_update":"2026-04-13T18:58:25.983Z","language":2,"uuid":"c2105905-eb31-4237-838c-7dd100ec884f","exercise":1933}}],"aliases":[],"comments":[]}'),
('wger', '1935', 'belt-squat', 'https://wger.de/en/exercise/1935/view', 'CC-BY-SA-4.0', NULL, 'new', NULL, '{"exercise":{"model":"exercises.exercise","pk":1935,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","uuid":"e9f3446f-ca98-4bf2-817c-0dacd123cecd","category":9,"variation_group":null,"created":"2026-04-07T12:01:39.670Z","last_update":"2026-04-07T12:01:39.670Z","muscles":[8,10],"muscles_secondary":[11],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":3084,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"","license_author_url":"","license_derivative_source_url":"","description":"<p>Belt Squat: a squat variation done with a belt attached to a loading machine or platform so the weight is supported at the hips instead of on the spine. It mainly trains the quads and glutes, with much less lower-back fatigue than a barbell squat. Use a full range of motion, keep the torso upright, and drive through the mid-foot.</p>\n","description_source":"Belt Squat: a squat variation done with a belt attached to a loading machine or platform so the weight is supported at the hips instead of on the spine. It mainly trains the quads and glutes, with much less lower-back fatigue than a barbell squat. Use a full range of motion, keep the torso upright, and drive through the mid-foot.","name":"Belt Squat","created":"2026-04-07T12:01:39.923Z","last_update":"2026-04-13T18:58:26.097Z","language":2,"uuid":"6f283530-db56-4aaf-9858-6573434f1218","exercise":1935}}],"aliases":[],"comments":[]}'),
('wger', '1936', NULL, 'https://wger.de/en/exercise/1936/view', 'CC-BY-SA-4.0', 'Dulive', NULL, NULL, '{"exercise":{"model":"exercises.exercise","pk":1936,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Dulive","license_author_url":"","license_derivative_source_url":"","uuid":"0285f198-36d5-4a77-bb76-5f72e1a4d6c9","category":13,"variation_group":"068dd634-ba84-444d-ab5e-a5da7a6e3896","created":"2026-04-08T12:07:36.122Z","last_update":"2026-04-08T12:07:36.122Z","muscles":[],"muscles_secondary":[],"equipment":[]}},"translations":[{"model":"exercises.translation","pk":3085,"fields":{"license":2,"license_title":"","license_object_url":"","license_author":"Dulive","license_author_url":"","license_derivative_source_url":"","description":"<p><strong>Cable rear delt fly (single arm):</strong>\nStand sideways to a cable machine with the handle set around shoulder height. With a slight bend in the elbow, pull the handle out and back in a wide arc so the upper arm moves away from the body. Keep your torso still and focus on the rear delt doing the work. Use <strong>light to moderate weight</strong> and controlled reps.</p>\n","description_source":"**Cable rear delt fly (single arm):**  \nStand sideways to a cable machine with the handle set around shoulder height. With a slight bend in the elbow, pull the handle out and back in a wide arc so the upper arm moves away from the body. Keep your torso still and focus on the rear delt doing the work. Use **light to moderate weight** and controlled reps.","name":"Cable Rear-Delt Fly (single arm)","created":"2026-04-08T12:07:36.176Z","last_update":"2026-04-13T18:58:26.182Z","language":2,"uuid":"85493329-1253-4e8a-9f5c-46ce807136b7","exercise":1936}}],"aliases":[],"comments":[]}');
